-- main_gag2_ui.lua - Grow A Garden 2 boot
-- 1) STATE: GAG2_STATE_A lalu GAG2_STATE_B (IIFE terpisah). LINK opsional, tidak wajib.
-- 2) WeatherPredict + WeatherKick load+sync SEBELUM ReduceFPS (kick paling awal; apply Kick di task.spawn).
-- 3) ReduceFPS load+Start SEBELUM MainUI / WS Helper (kejar soft shell). ReduceLag oneshot SETELAH modules ready.
-- 4) WS Helper (WSHELPERGAG2) di-inject SETELAH ReduceFPS Start — jangan di atas file (file besar menahan boot).
-- 5) AntiAFK early Start setelah UI
-- 6) Module optional gagal tidak stop boot

----------------------------------------------------------------
-- SERVICES / BOOT GUARD
----------------------------------------------------------------
if not game:IsLoaded() then
    game.Loaded:Wait()
end

local Players = game:GetService("Players")
-- PropertyChangedSignal:Wait() TIDAK return LocalPlayer → jangan pakai `or Wait()`
local LP = Players.LocalPlayer
if not LP then
    Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
    LP = Players.LocalPlayer
end
if not LP then
    LP = Players.PlayerAdded:Wait()
end
pcall(function() LP:WaitForChild("PlayerGui", 1.5) end)

local G = (getgenv and getgenv()) or _G

local BOOT_NAME = "GROW A GARDEN 2 V1.2"
local BOOT_RETRY = 3
local RETRY_DELAY = 2
local STATE_RETRY = 2
local STATE_RETRY_DELAY = 0.25

local function warnlog(...)
    warn("[" .. BOOT_NAME .. "]", ...)
end

local function failBoot(msg)
    G.__GROWAGARDEN2_RUNNING = false
    G.__GAG2_READY = false
    _G.__GAG2_READY = false
    error("[" .. BOOT_NAME .. "] " .. tostring(msg), 0)
end

-- UI "hidup" = overlay di PlayerGui ScreenGui (bukan cuma host SurfaceGui)
local function hubUiVisible()
    local pg = LP and LP:FindFirstChild("PlayerGui")
    local sg = pg and pg:FindFirstChild("NodeHubNeonUI")
    if not (sg and sg:IsA("ScreenGui")) then return false end
    local overlay = sg:FindFirstChild("NodeHubOverlay")
    return overlay ~= nil and overlay.Parent == sg
end

-- READY + UI terlihat → skip. READY tapi UI hilang / nyangkut host → reboot.
if G.__GROWAGARDEN2_RUNNING and G.__GAG2_READY then
    if hubUiVisible() then
        return true
    end
    warnlog("UI tidak di PlayerGui — reboot (early module mungkin masih jalan)")
    G.__GROWAGARDEN2_RUNNING = false
    G.__GAG2_READY = false
    _G.__GAG2_READY = false
end

G.__GROWAGARDEN2_RUNNING = true
G.__GAG2_READY = false
_G.__GAG2_READY = false
G.__GROWAGARDEN2_MODULES_READY = false
_G.__GROWAGARDEN2_MODULES_READY = false

