    { key = "MainUI",                  name = "NodeHubNeonUI",           factory = function() -- NodeHubNeonUI.lua
-- UI Style B: Kuning - Hitam, Neon Glow, Sidebar kiri, Floating
-- Dibungkus jadi module "MainUI" supaya tab main & sub tab bisa di-file terpisah.

local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")
local LP = Players.LocalPlayer
local PlayerGui = LP:WaitForChild("PlayerGui")
local TextService  = game:GetService("TextService")

local LOADING_HOST_NAME = "NodeHubLoadingHost"

-- WAJIB PlayerGui saja (setelah loading).
-- gethui/CoreGui/protect_gui → Plugin capability error.
local function destroyNamedGui(name)
    local pg = PlayerGui:FindFirstChild(name)
    if pg then
        pcall(function()
            pg:Destroy()
        end)
    end
    pcall(function()
        if typeof(gethui) == "function" then
            local hui = gethui()
            local old = hui and hui:FindFirstChild(name)
            if old then
                old:Destroy()
            end
        end
    end)
    pcall(function()
        local cg = game:GetService("CoreGui")
        local old = cg:FindFirstChild(name)
        if old then
            old:Destroy()
        end
    end)
    -- host SurfaceGui milik kita (bukan LoadingScreenMenu game)
    pcall(function()
        local host = workspace:FindFirstChild(LOADING_HOST_NAME)
        if host then
            host:Destroy()
        end
    end)
end

local function isWorldReady()
    return workspace:FindFirstChild("Gardens") ~= nil
        and LP:GetAttribute("PlotId") ~= nil
        and LP.Character ~= nil
end

local function hideLoadingEnabled()
    local G = (getgenv and getgenv()) or _G
    return G.HIDE_LOADING_ENABLED == true or rawget(_G, "HIDE_LOADING_ENABLED") == true
end

local function isLoadingFinished()
    return LP:GetAttribute("LoadingScreenDone") == true
end

local function loadingMenuExists()
    return workspace:FindFirstChild("LoadingScreenMenu") ~= nil
end

-- Latch: sekali lihat loading, tetap mode host sampai selesai.
-- Jangan clear cuma karena Gardens/Character/HideLoading flicker (bikin UI hilang di belakang loading).
local _loadingHostLatch = false
local _menuGoneSince = nil

local function isLoadingActive()
    if isLoadingFinished() then
        _loadingHostLatch = false
        _menuGoneSince = nil
        return false
    end

    -- Menu masih ada → WAJIB host (di depan SurfaceGui loading).
    -- Hide Loading tidak boleh cabut host selama menu masih ada (UI ketutup).
    if loadingMenuExists() then
        _loadingHostLatch = true
        _menuGoneSince = nil
        return true
    end

    if LP:GetAttribute("LoadingScreenActive") == true and not isWorldReady() then
        _loadingHostLatch = true
        _menuGoneSince = nil
        return true
    end

    -- Menu hilang: tahan latch sebentar (anti flicker recreate), lalu lepas.
    if _loadingHostLatch then
        if hideLoadingEnabled() and isWorldReady() then
            _loadingHostLatch = false
            _menuGoneSince = nil
            return false
        end
        _menuGoneSince = _menuGoneSince or os.clock()
        if (os.clock() - _menuGoneSince) >= 0.6 then
            _loadingHostLatch = false
            _menuGoneSince = nil
            return false
        end
        return true
    end

    return false
end

-- Host SurfaceGui SENDIRI di depan kamera (lebih dekat dari loading -16).
-- Jangan parent ke LoadingScreenMenu game — saat loading destroy, hub ikut hilang.
local function keepHubAboveLoading(sg, overlay, miniBtn)
    task.spawn(function()
        local hostPart, hostGui, renderConn
        local usingHost = false
        local restoring = false
        local hostDestroyConn

        local function alive(inst)
            return typeof(inst) == "Instance" and inst.Parent ~= nil
        end

        local function safeReparent(inst, parent)
            if not alive(inst) or not alive(parent) then
                return false
            end
            if inst.Parent == parent then
                return true
            end
            local ok = pcall(function()
                inst.Parent = parent
            end)
            return ok == true and inst.Parent == parent
        end

        local function destroyHost(force)
            if renderConn then
                pcall(function()
                    renderConn:Disconnect()
                end)
                renderConn = nil
            end
            local part = hostPart
            hostPart, hostGui = nil, nil
            if not part then
                return
            end
            local stillHolding = false
            if not force then
                pcall(function()
                    if overlay and overlay:IsDescendantOf(part) then
                        stillHolding = true
                    end
                    if miniBtn and miniBtn:IsDescendantOf(part) then
                        stillHolding = true
                    end
                end)
            end
            if not stillHolding then
                pcall(function()
                    part:Destroy()
                end)
            end
        end

        local function restoreToScreenGui()
            if restoring then
                return alive(overlay) and overlay.Parent == sg
            end
            restoring = true
            local ok = false
            pcall(function()
                if not alive(sg) then
                    return
                end
                -- cabut dari host DULU, baru enable ScreenGui
                if alive(overlay) then
                    safeReparent(overlay, sg)
                    overlay.Active = false
                end
                if alive(miniBtn) then
                    safeReparent(miniBtn, sg)
                end
                sg.Enabled = true
                sg.DisplayOrder = 99999
                ok = alive(overlay) and overlay.Parent == sg and sg.Enabled == true
            end)
            usingHost = false
            -- destroy host hanya setelah overlay aman di ScreenGui
            if ok or not (alive(overlay) and hostPart and overlay:IsDescendantOf(hostPart)) then
                destroyHost(false)
            end
            restoring = false
            return ok
        end

        local function rescueFromHostNow()
            -- HARUS sync di Destroying — task.defer sering terlambat (UI ikut kena Destroy)
            if alive(sg) then
                if alive(overlay) then
                    pcall(function()
                        overlay.Parent = sg
                        overlay.Active = false
                    end)
                end
                if alive(miniBtn) then
                    pcall(function()
                        miniBtn.Parent = sg
                    end)
                end
                pcall(function()
                    sg.Enabled = true
                    sg.DisplayOrder = 99999
                end)
            end
            usingHost = false
            hostPart, hostGui = nil, nil
            if renderConn then
                pcall(function()
                    renderConn:Disconnect()
                end)
                renderConn = nil
            end
        end

        local function watchHostDestroy(part)
            if hostDestroyConn then
                pcall(function()
                    hostDestroyConn:Disconnect()
                end)
                hostDestroyConn = nil
            end
            if not part then
                return
            end
            hostDestroyConn = part.Destroying:Connect(function()
                rescueFromHostNow()
            end)
        end

        local function ensureHost()
            if hostPart and hostPart.Parent and hostGui and hostGui.Parent then
                return hostGui
            end
            -- reparent dulu sebelum buang host rusak
            if alive(overlay) and alive(sg) then
                safeReparent(overlay, sg)
            end
            if alive(miniBtn) and alive(sg) then
                safeReparent(miniBtn, sg)
            end
            destroyHost(false)

            local part = Instance.new("Part")
            part.Name = LOADING_HOST_NAME
            part.Anchored = true
            part.CanCollide = false
            -- WAJIB true: SurfaceGui terima klik lewat raycast part.
            part.CanQuery = true
            part.CanTouch = false
            part.CastShadow = false
            part.Transparency = 1
            part.Size = Vector3.new(1, 1, 0.1)
            part:SetAttribute("GAG2HubHost", true)
            part.Parent = workspace

            local gui = Instance.new("SurfaceGui")
            gui.Name = "NodeHubHostGui"
            gui.AlwaysOnTop = true
            gui.Active = true
            gui.LightInfluence = 0
            gui.ResetOnSpawn = false
            gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            gui.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
            gui.PixelsPerStud = 50
            gui.Face = Enum.NormalId.Front
            gui.MaxDistance = 1000
            gui.Parent = part

            hostPart, hostGui = part, gui
            watchHostDestroy(part)

            renderConn = RunService.RenderStepped:Connect(function()
                if not (hostPart and hostPart.Parent and hostGui and hostGui.Parent) then
                    return
                end
                local cam = workspace.CurrentCamera
                if not cam then
                    return
                end
                -- Loading game di Z=-16; kita di -10 → di depan loading
                local halfFov = math.rad(cam.FieldOfView / 2)
                local dist = 10
                local h = math.tan(halfFov) * dist * 2
                local w = h * (cam.ViewportSize.X / math.max(cam.ViewportSize.Y, 1))
                hostPart.Size = Vector3.new(w, h, 0.1)
                hostPart.CFrame = cam.CFrame * CFrame.new(0, 0, -dist) * CFrame.Angles(0, math.pi, 0)
                hostGui.CanvasSize = cam.ViewportSize
            end)

            return hostGui
        end

        local function sinkLoadingGuiInput()
            local menu = workspace:FindFirstChild("LoadingScreenMenu")
            if not menu then return end
            pcall(function()
                for _, d in ipairs(menu:GetDescendants()) do
                    if d:IsA("BasePart") then
                        d.CanQuery = false
                    elseif d:IsA("SurfaceGui") then
                        d.Active = false
                    end
                end
            end)
        end

        local function attachToHost()
            if not alive(overlay) then
                return false
            end
            local gui = ensureHost()
            if not gui then
                return false
            end
            local ok = false
            pcall(function()
                if overlay.Parent ~= gui then
                    overlay.Parent = gui
                end
                overlay.ZIndex = 10
                overlay.Active = true
                if alive(miniBtn) then
                    if miniBtn.Parent ~= gui then
                        miniBtn.Parent = gui
                    end
                    miniBtn.ZIndex = 11
                    miniBtn.Active = true
                end
                if alive(sg) then
                    sg.Enabled = false
                end
                ok = overlay.Parent == gui
            end)
            sinkLoadingGuiInput()
            usingHost = ok == true
            return ok
        end

        local function ensureUiVisible()
            if not alive(sg) then
                return false
            end
            if isLoadingActive() then
                return attachToHost()
            end
            local ok = restoreToScreenGui()
            if alive(sg) and sg.Enabled ~= true then
                pcall(function()
                    sg.Enabled = true
                    sg.DisplayOrder = 99999
                end)
            end
            return ok
        end

        -- Escape stuck: latch nyangkut SETELAH menu hilang + dunia siap
        -- (jangan paksa restore selama LoadingScreenMenu masih ada)
        local menuGoneReadySince = nil
        local STUCK_HOST_SEC = 8
        -- UI sering spawn sebelum menu muncul → tunggu sebentar
        local bootWaitUntil = os.clock() + 10

        -- Saat loading aktif: tempel ke host. Setelah selesai: restore + jaga tetap hidup.
        while alive(sg) do
            if not alive(overlay) then
                break
            end

            local menuOn = loadingMenuExists()
            if (not menuOn) and isWorldReady() then
                menuGoneReadySince = menuGoneReadySince or os.clock()
            else
                menuGoneReadySince = nil
            end

            local stuckHost = (not menuOn)
                and menuGoneReadySince ~= nil
                and (os.clock() - menuGoneReadySince) >= STUCK_HOST_SEC
                and usingHost == true

            local wantHost = isLoadingActive() and not stuckHost
            if wantHost then
                local onHost = hostPart and alive(hostPart) and overlay:IsDescendantOf(hostPart)
                if not onHost then
                    attachToHost()
                end
                task.wait(0.25)
            elseif os.clock() < bootWaitUntil and not isLoadingFinished() and not stuckHost then
                -- belum ada sinyal loading, tunggu menu (jangan restore+break terlalu cepat)
                task.wait(0.15)
            else
                ensureUiVisible()
                break
            end
        end

        if alive(sg) then
            if usingHost or (alive(overlay) and hostPart and overlay:IsDescendantOf(hostPart)) then
                if not isLoadingActive() then
                    _loadingHostLatch = false
                    restoreToScreenGui()
                end
            else
                if not isLoadingActive() then
                    ensureUiVisible()
                elseif not (hostPart and alive(hostPart) and overlay:IsDescendantOf(hostPart)) then
                    attachToHost()
                end
            end
        end

        -- Watchdog: re-attach kalau menu loading masih ada; restore kalau sudah selesai.
        while alive(sg) do
            if not alive(overlay) then
                break
            end
            local onHost = hostPart and alive(hostPart) and overlay:IsDescendantOf(hostPart)
            if isLoadingActive() then
                if not onHost then
                    attachToHost()
                end
            else
                if onHost then
                    _loadingHostLatch = false
                    restoreToScreenGui()
                elseif overlay.Parent ~= sg or sg.Enabled ~= true then
                    ensureUiVisible()
                end
                if alive(sg) and sg.Enabled ~= true then
                    pcall(function()
                        sg.Enabled = true
                        sg.DisplayOrder = 99999
                    end)
                end
            end
            task.wait(0.4)
        end

        if hostDestroyConn then
            pcall(function()
                hostDestroyConn:Disconnect()
            end)
        end
    end)
end 

