local function _clamp01(n, fallback)
    n = tonumber(n)
    if n == nil then return fallback end
    if n < 0 then return 0 end
    if n > 1 then return 1 end
    return n
end

local function _readHubUiTransparency()
    local G = (getgenv and getgenv()) or _G
    local main = G.MAIN or rawget(_G, "MAIN")
    local hub = (type(main) == "table" and type(main.misc) == "table" and type(main.misc.hub_ui) == "table")
        and main.misc.hub_ui
        or nil
    local panel = _clamp01(hub and hub.panel_transparency, DEFAULT_PANEL_BG_TRANSPARENCY)
    return {
        panel = panel,
        overlay = DEFAULT_OVERLAY_BG_TRANSPARENCY, -- fixed 100% clear
        section = panel, -- section selalu ikut panel
    }
end

