local uiScale = Instance.new("UIScale")
uiScale.Parent = mainFrame

local function updateScale()
    local cam = workspace.CurrentCamera
    if not cam then return end

    local v = cam.ViewportSize
    if not v or v.X <= 0 or v.Y <= 0 then return end

    -- sisakan margin biar tidak mepet edge (terasa lebih tajam & rapi)
    local fit = math.min((v.X * 0.96) / MAIN_W, (v.Y * 0.94) / MAIN_H, 1)
    local MIN_SCALE = 0.5

    -- pilih scale terbesar dari daftar favorit yang masih muat → teks lebih tajam
    local s = MIN_SCALE
    for _, step in ipairs(UI_SCALE_STEPS) do
        if step <= fit + 0.001 then
            s = step
            break
        end
    end
    if s < MIN_SCALE then s = MIN_SCALE end

    uiScale.Scale = s
end

local viewportConn
local function bindCamera(cam)
    if viewportConn then viewportConn:Disconnect() end
    if not cam then return end
    viewportConn = cam:GetPropertyChangedSignal("ViewportSize"):Connect(updateScale)
end

bindCamera(workspace.CurrentCamera)
updateScale()

