local onceSendTotalRow = nil
local onceSendTotalLabel = nil
local onceSendTotalSetFn = nil
local onceSendTotalActiveMode = "total"
local onceCatRow = nil
local onceHarvestConfigLabel = nil
local onceHarvestPriceRows = {}

local function setOnceSendTotalInputValue(sendMode, categories, store)
    if type(onceSendTotalSetFn) ~= "function" then return end
    store = store or ensureAutoGiftStore()
    categories = type(categories) == "table" and categories or store.once.categories
    sendMode = normalizeOnceSendMode(sendMode or store.once.send_mode)
    if giftOnceUsesPriceMode(categories, sendMode) then
        pcall(onceSendTotalSetFn, formatGiftSendTotalDisplay(parseOnceQtyAllowZero(store.once.send_total, 1000)))
    else
        pcall(onceSendTotalSetFn, giftOnceSendCountDisplay(categories, store))
    end
end

local function refreshOnceSendTotalRows(categories, sendMode)
    local store = ensureAutoGiftStore()
    categories = type(categories) == "table" and categories or store.once.categories
    sendMode = normalizeOnceSendMode(sendMode or readOnceSendModeFromUi())
    local priceMode = giftOnceUsesPriceMode(categories, sendMode)
    -- Track effective UI mode (price only when Harvest+Price), not just preference.
    onceSendTotalActiveMode = priceMode and "price" or "total"
    if onceSendTotalLabel then
        onceSendTotalLabel.Text = priceMode and "Send total price (0 = all)" or "Send total (0 = all)"
    end
    setOnceSendTotalInputValue(sendMode, categories, store)
end

local function refreshOnceSendModeUi(sendMode)
    local store = ensureAutoGiftStore()
    sendMode = normalizeOnceSendMode(sendMode or readOnceSendModeFromUi())
    local priceMode = onceSendModeIsPrice(sendMode)

    if onceHarvestConfigLabel then
        onceHarvestConfigLabel.Visible = true
    end
    for _, row in ipairs(onceHarvestPriceRows) do
        if row then row.Visible = priceMode end
    end

    refreshOnceSendTotalRows(store.once.categories, sendMode)

    if G.__GAG2_GIFT_SKIP_DROPDOWN_REFRESH ~= true then
        local refreshFn = G.__GAG2_REFRESH_ONCE_CATEGORY_LISTS or rawget(_G, "__GAG2_REFRESH_ONCE_CATEGORY_LISTS")
        if type(refreshFn) == "function" then
            pcall(refreshFn, sendMode)
        end
    end

    local multiRefresh = G.__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW or rawget(_G, "__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW")
    if type(multiRefresh) == "function" then
        pcall(multiRefresh)
    end
    local multiListRefresh = G.__GAG2_REFRESH_MULTI_CATEGORY_LISTS or rawget(_G, "__GAG2_REFRESH_MULTI_CATEGORY_LISTS")
    if type(multiListRefresh) == "function" then
        pcall(multiListRefresh)
    end
end

local function applyOnceSendTotalInputsFromProfile(prof, store)
    store = store or ensureAutoGiftStore()
    prof = normalizeGiftProfileFields(prof, true)
    refreshOnceSendTotalRows(prof.categories, prof.send_mode)
end

local function syncGiftProfileFromUi(profileKey)
    if G.__GAG2_AUTO_GIFT_UI_READY ~= true then return end
    local opts = flushGiftProfileFromUi(profileKey)
    mergeGiftProfileOpts(profileKey, opts)
end

local function readOnceSendTotalTarget(store)
    store = store or ensureAutoGiftStore()
    local mode = normalizeOnceSendMode(store.once.send_mode)
    if giftOnceUsesPriceMode(store.once.categories, mode) then
        return parseOnceQtyAllowZero(store.once.send_total, 1000)
    end
    local catKey = firstEnabledCategoryKey(store.once.categories)
    if catKey and type(store.send_totals) == "table" then
        return parseOnceQtyAllowZero(store.send_totals[catKey], 20)
    end
    return 20
end

local function checkGiftSendTotalAvailability(profileKey, targetN, priceMode)
    profileKey = (profileKey == "loop") and "loop" or "once"
    targetN = math.floor(tonumber(targetN) or 0)
    if targetN < 1 then return end
    syncGiftProfileFromUi(profileKey)
    if profileKey == "loop" then
        applyGiftLoopRuntime()
    else
        applyGiftOnceRuntime()
    end
    local ag = getAutoGiftModule()
    if type(ag) ~= "table" then return end
    if type(ag.CheckSendTotalAvailability) == "function" then
        local ok, pass, err = pcall(function()
            return ag.CheckSendTotalAvailability(ag, targetN, priceMode == true)
        end)
        if ok then
            if pass == false then
                setGiftAvailabilityStatus(tostring(err or "Item kurang"))
                return
            end
            local cur = tostring(G.AUTO_GIFT_ONCE_STATUS or rawget(_G, "AUTO_GIFT_ONCE_STATUS") or "")
            if cur:find("kurang", 1, true) or cur:find("Tidak ada item giftable", 1, true) then
                setGiftAvailabilityStatus("Ready")
            end
            return
        end
    end
    local available = getGiftSendableMax(profileKey)
    if available < 1 then
        setGiftAvailabilityStatus("Tidak ada item giftable di inventory untuk category terpilih")
        return
    end
    if targetN > available then
        local msg = (priceMode == true)
            and ("Value kurang: punya " .. formatGiftSendTotalDisplay(available)
                .. ", butuh " .. formatGiftSendTotalDisplay(targetN))
            or ("Item kurang: punya " .. tostring(available) .. ", butuh " .. tostring(targetN))
        setGiftAvailabilityStatus(msg)
    else
        local cur = tostring(G.AUTO_GIFT_ONCE_STATUS or rawget(_G, "AUTO_GIFT_ONCE_STATUS") or "")
        if cur:find("kurang", 1, true) then
            setGiftAvailabilityStatus("Ready")
        end
    end
end

G.__GAG2_CHECK_GIFT_SEND_TOTAL = function()
    local store = ensureAutoGiftStore()
    local mode = normalizeOnceSendMode(store.once.send_mode)
    local priceMode = giftOnceUsesPriceMode(store.once.categories, mode)
    checkGiftSendTotalAvailability("once", readOnceSendTotalTarget(store), priceMode)
end
_G.__GAG2_CHECK_GIFT_SEND_TOTAL = G.__GAG2_CHECK_GIFT_SEND_TOTAL

local function getGiftSendableMax(profile)
    syncGiftProfileFromUi(profile)
    local ag = getAutoGiftModule()
    if type(ag) ~= "table" then return 0 end
    local store = ensureAutoGiftStore()
    local prof = (profile == "loop") and store.loop or store.once
    local priceMode = false
    if profile ~= "loop" then
        local ok, v = pcall(
            giftOnceUsesPriceMode,
            prof.categories,
            prof.send_mode or store.once.send_mode
        )
        priceMode = ok and v == true
    end
    if type(ag.ApplyConfig) == "function" then
        pcall(ag.ApplyConfig, ag, giftConfigFromProfile(store, profile or "once"))
    end
    if type(ag.InvalidateHarvestFruitCache) == "function" then
        pcall(ag.InvalidateHarvestFruitCache, ag)
    end
    if priceMode and type(ag.CountSendablePrice) == "function" then
        local ok, n = pcall(ag.CountSendablePrice, ag)
        if ok and type(n) == "number" then
            return math.max(0, math.floor(n))
        end
    end
    if type(ag.CountSendableUnits) == "function" then
        local ok, n = pcall(ag.CountSendableUnits, ag)
        if ok and type(n) == "number" then
            return math.max(0, math.floor(n))
        end
    end
    return 0
end

local function buildGiftMailProfileUi(body, profileKey)
    local prefix = string.upper(profileKey)
    local allowMultiMode = (profileKey == "loop")
    local store = ensureAutoGiftStore()
    local profile = (profileKey == "loop") and store.loop or store.once
    local itemDropdowns = {}
    local syncingCategoryUi = false
    local catMultiDd = nil
    local catModeDd = nil

    -- Lazy: only build item-list dropdown when category is active (Gift tab open was heavy).
    local function ensureItemDropdown(catKey)
        catKey = tostring(catKey or "")
        if catKey == "" then return nil end
        local existing = itemDropdowns[catKey]
        if existing and (existing.noList == true or existing.dd ~= nil) then
            return existing
        end
        local def
        for _, d in ipairs(buildGiftCatUiDefs()) do
            if d.key == catKey then
                def = d
                break
            end
        end
        if not def or isGiftCategoryNoList(catKey) then
            itemDropdowns[catKey] = { row = nil, dd = nil, noList = true }
            return itemDropdowns[catKey]
        end
        local storeNow = ensureAutoGiftStore()
        local profNow = (profileKey == "loop") and storeNow.loop or storeNow.once
        local row, itemDd = ui:CreateRowDropdown(body, {
            label = def.itemLabel,
            placeholder = def.placeholder,
            mode = "multi",
            deferItemLoad = true,
            labelForKey = function(key)
                return tostring(key or "")
            end,
            getItems = function()
                local ag = getAutoGiftModule()
                if type(ag) == "table" and type(ag.BuildInventoryItems) == "function" then
                    local ok, items = pcall(ag.BuildInventoryItems, ag, catKey)
                    if ok and type(items) == "table" then return items end
                end
                return {}
            end,
            initial = cleanSelectedMap(profNow.selected[catKey]),
            onChanged = function(_, value)
                patchGiftProfile(profileKey, {
                    selected = { [catKey] = cleanSelectedMap(value) },
                }, function()
                    if profileKey == "loop" then
                        applyGiftLoopRuntime()
                    else
                        applyGiftOnceRuntime()
                    end
                end)
                if profileKey == "once" then
                    local checkFn = G.__GAG2_CHECK_GIFT_SEND_TOTAL or rawget(_G, "__GAG2_CHECK_GIFT_SEND_TOTAL")
                    if type(checkFn) == "function" then
                        pcall(checkFn)
                    end
                end
            end,
        })
        row.Visible = false
        itemDropdowns[catKey] = { row = row, dd = itemDd, noList = false }
        G["__GAG2_AUTO_GIFT_" .. prefix .. "_DD_" .. catKey] = itemDd
        _G["__GAG2_AUTO_GIFT_" .. prefix .. "_DD_" .. catKey] = itemDd
        return itemDropdowns[catKey]
    end

    local function applyCategorySelection(selectedMap, persist)
        selectedMap = type(selectedMap) == "table" and selectedMap or {}
        local cats = {}
        for _, def in ipairs(buildGiftCatUiDefs()) do
            cats[def.key] = selectedMap[def.key] == true
        end
        local onceSendMode = (profileKey == "once") and readOnceSendModeFromUi() or "total"
        for _, def in ipairs(buildGiftCatUiDefs()) do
            local showList = onceCategoryShowsItemList(profileKey, def.key, onceSendMode)
            local show = cats[def.key] == true and showList
            if show then
                local entry = ensureItemDropdown(def.key)
                if entry and entry.row then
                    local wasVisible = entry.row.Visible
                    entry.row.Visible = true
                    if show and not wasVisible and G.__GAG2_GIFT_UI_BOOTSTRAP ~= true
                        and type(entry.dd) == "table" and type(entry.dd.refreshItems) == "function" then
                        pcall(entry.dd.refreshItems, entry.dd)
                    end
                end
            else
                local entry = itemDropdowns[def.key]
                if entry and entry.row then
                    entry.row.Visible = false
                end
            end
        end
        if profileKey == "once" then
            refreshOnceSendTotalRows(cats, onceSendMode)
        end
        if persist and not syncingCategoryUi then
            local patch = { categories = cats }
            patchGiftProfile(profileKey, patch, function()
                if profileKey == "loop" then
                    applyGiftLoopRuntime()
                else
                    applyGiftOnceRuntime()
                end
            end)
        end
    end

    local function applyGiftCategoryMode(mode, persist)
        if not allowMultiMode then return end
        mode = (mode == "multi") and "multi" or "single"
        if type(catMultiDd) == "table" and type(catMultiDd.setMode) == "function" then
            catMultiDd.setMode(mode)
            if mode == "multi" and type(catMultiDd.getSelected) == "function" then
                local sel = safeDdGetSelected(catMultiDd)
                if type(sel) == "string" and sel ~= "" then
                    catMultiDd.setSelected({ [sel] = true })
                end
            elseif mode == "single" and type(catMultiDd.getSelected) == "function" then
                local sel = safeDdGetSelected(catMultiDd)
                if type(sel) == "table" then
                    catMultiDd.setSelected(firstEnabledCategoryKey(sel))
                end
            end
        end
        if persist then
            patchGiftProfile(profileKey, { category_mode = mode }, function() applyGiftLoopRuntime() end)
        end
        if type(catMultiDd) == "table" and type(catMultiDd.getSelected) == "function" then
            local sel = safeDdGetSelected(catMultiDd)
            if mode == "single" then
                local key = sel
                if type(key) == "table" then key = firstEnabledCategoryKey(key) end
                local map = {}
                for _, def in ipairs(buildGiftCatUiDefs()) do
                    map[def.key] = (key ~= nil and def.key == tostring(key))
                end
                applyCategorySelection(map, false)
            elseif type(sel) == "table" then
                applyCategorySelection(sel, false)
            end
        end
    end

    if allowMultiMode then
        local _, catModeDdApi = ui:CreateRowDropdown(body, {
            label = "Category mode",
            placeholder = "Single",
            mode = "single",
            getItems = function()
                return {
                    { key = "single", name = "Single" },
                    { key = "multi", name = "Multi" },
                }
            end,
            initial = giftCategoryModeFromProfile(profile, false),
            onChanged = function(_, key)
                applyGiftCategoryMode(tostring(key or "single"), true)
            end,
        })
        catModeDd = catModeDdApi
        G["__GAG2_AUTO_GIFT_" .. prefix .. "_CATEGORY_MODE"] = catModeDdApi
        _G["__GAG2_AUTO_GIFT_" .. prefix .. "_CATEGORY_MODE"] = catModeDdApi
    end

    local catInitMode = allowMultiMode and giftCategoryModeFromProfile(profile, false) or "single"
    local catInitial
    if catInitMode == "single" then
        catInitial = firstEnabledCategoryKey(profile.categories)
    else
        catInitial = categoriesToMultiMap(profile.categories)
    end
    onceCatRow, catMultiDd = ui:CreateRowDropdown(body, {
        label = "Categories",
        placeholder = allowMultiMode and "Select categories..." or "Select category...",
        mode = catInitMode,
        getItems = function()
            local items = {}
            for _, def in ipairs(buildGiftCatUiDefs()) do
                items[#items + 1] = { key = def.key, name = def.label }
            end
            return items
        end,
        initial = catInitial,
        onChanged = function(ddMode, value)
            ddMode = tostring(ddMode or "single")
            if ddMode == "single" then
                local key = value
                local map = {}
                for _, def in ipairs(buildGiftCatUiDefs()) do
                    map[def.key] = (key ~= nil and def.key == tostring(key))
                end
                applyCategorySelection(map, true)
            elseif type(value) == "table" then
                applyCategorySelection(value, true)
            end
        end,
    })
    if profileKey ~= "once" then
        onceCatRow = nil
    end
    G["__GAG2_AUTO_GIFT_" .. prefix .. "_CAT"] = catMultiDd
    _G["__GAG2_AUTO_GIFT_" .. prefix .. "_CAT"] = catMultiDd

    -- Pre-create semua item list di sini (sebelum Send total / After send / Send now),
    -- supaya ganti category tidak menaruh list di paling bawah section.
    for _, def in ipairs(buildGiftCatUiDefs()) do
        ensureItemDropdown(def.key)
    end

    applyCategorySelection(profile.categories, false)

    if profileKey == "once" then
        G.__GAG2_REFRESH_ONCE_CATEGORY_LISTS = function(mode)
            local sm = normalizeOnceSendMode(mode or readOnceSendModeFromUi())
            local cats = {}
            local store = ensureAutoGiftStore()
            for _, def in ipairs(buildGiftCatUiDefs()) do
                cats[def.key] = store.once.categories[def.key] == true
            end
            applyCategorySelection(cats, false)
            if G.__GAG2_GIFT_UI_BOOTSTRAP ~= true and G.__GAG2_GIFT_SKIP_DROPDOWN_REFRESH ~= true then
                refreshItems(true)
            end
        end
        _G.__GAG2_REFRESH_ONCE_CATEGORY_LISTS = G.__GAG2_REFRESH_ONCE_CATEGORY_LISTS
    end

    local function refreshItems(visibleOnly)
        local ag = getAutoGiftModule()
        if type(ag) == "table" and type(ag.InvalidateHarvestFruitCache) == "function" then
            pcall(ag.InvalidateHarvestFruitCache, ag)
        end
        for _, def in ipairs(buildGiftCatUiDefs()) do
            local entry = itemDropdowns[def.key]
            if entry and not entry.noList and type(entry.dd) == "table" and type(entry.dd.refreshItems) == "function" then
                local show = not visibleOnly or (entry.row and entry.row.Visible)
                if show then
                    pcall(entry.dd.refreshItems, entry.dd)
                end
            end
        end
    end

    local function restoreUi()
        store = ensureAutoGiftStore()
        profile = (profileKey == "loop") and store.loop or store.once
        if type(catMultiDd) == "table" and type(catMultiDd.setSelected) == "function" then
            syncingCategoryUi = true
            local cm = allowMultiMode and giftCategoryModeFromProfile(profile, false) or "single"
            if cm == "single" then
                catMultiDd.setSelected(firstEnabledCategoryKey(profile.categories))
            else
                catMultiDd.setSelected(categoriesToMultiMap(profile.categories))
            end
            syncingCategoryUi = false
        end
        applyCategorySelection(profile.categories, false)
        for _, def in ipairs(buildGiftCatUiDefs()) do
            local entry = itemDropdowns[def.key]
            if entry and not entry.noList and type(entry.dd) == "table" and type(entry.dd.setSelected) == "function" then
                entry.dd.setSelected(cleanSelectedMap(profile.selected[def.key]))
            end
        end
    end

    return {
        itemDropdowns = itemDropdowns,
        catMultiDd = catMultiDd,
        catModeDd = catModeDd,
        applyCategorySelection = applyCategorySelection,
        applyGiftCategoryMode = applyGiftCategoryMode,
        refreshItems = refreshItems,
        restoreUi = restoreUi,
        syncingCategoryUi = function() return syncingCategoryUi end,
        setSyncing = function(v) syncingCategoryUi = v == true end,
    }
end

local onceUi = buildGiftMailProfileUi(bodyGiftOnce, "once")

local initStore = ensureAutoGiftStore()
local initSendMode = normalizeOnceSendMode(initStore.once.send_mode)
local initPriceMode = giftOnceUsesPriceMode(initStore.once.categories, initSendMode)
onceSendTotalActiveMode = initSendMode

onceSendTotalRow, onceSendTotalSetFn = ui:CreateRowInput(
    bodyGiftOnce,
    initPriceMode and "Send total price (0 = all)" or "Send total (0 = all)",
    initPriceMode and formatGiftSendTotalDisplay(parseOnceQtyAllowZero(initStore.once.send_total, 1000))
        or giftOnceSendCountDisplay(initStore.once.categories, initStore),
    function(txt)
        local store = ensureAutoGiftStore()
        local mode = normalizeOnceSendMode(onceSendTotalActiveMode or readOnceSendModeFromUi())
        if giftOnceUsesPriceMode(store.once.categories, mode) then
            local n = parseGiftSendTotalPrice(txt)
            if tostring(txt or ""):gsub("%s+", "") == "" then return end
            if n < 0 then return end
            patchGiftProfile("once", { send_total = math.floor(n) }, function()
                applyGiftOnceRuntime()
            end)
            checkGiftSendTotalAvailability("once", n, true)
            return
        end
        local store = ensureAutoGiftStore()
        local n = tonumber(txt)
        if n == nil or n < 0 then return end
        local catKey = firstEnabledCategoryKey(store.once.categories)
        if not catKey then return end
        patchGift({ send_totals = { [catKey] = math.floor(n) } }, function()
            applyGiftOnceRuntime()
        end)
        checkGiftSendTotalAvailability("once", n, false)
    end,
    false -- jangan clearOnFocus: pindah tab commit "" → wipe send_total
)
onceSendTotalLabel = onceSendTotalRow and onceSendTotalRow:FindFirstChild("Label")
G.__GAG2_AUTO_GIFT_ONCE_SEND_TOTAL_PRICE = onceSendTotalSetFn
_G.__GAG2_AUTO_GIFT_ONCE_SEND_TOTAL_PRICE = onceSendTotalSetFn
G.__GAG2_AUTO_GIFT_ONCE_SEND_TOTAL = onceSendTotalSetFn
_G.__GAG2_AUTO_GIFT_ONCE_SEND_TOTAL = onceSendTotalSetFn
onceUi.sendTotalRow = onceSendTotalRow
G.__GAG2_REFRESH_ONCE_SEND_TOTAL_ROW = refreshOnceSendTotalRows
_G.__GAG2_REFRESH_ONCE_SEND_TOTAL_ROW = refreshOnceSendTotalRows

local _, onceAfterSendDd = ui:CreateRowDropdown(bodyGiftOnce, {
    label = "After send",
    placeholder = "Keep",
    mode = "single",
    getItems = function()
        return {
            { key = "keep", name = "Keep" },
            { key = "reset", name = "Reset" },
        }
    end,
    initial = (ensureAutoGiftStore().once.after_send_mode == "reset") and "reset" or "keep",
    onChanged = function(_, key)
        patchGiftProfile("once", { after_send_mode = tostring(key or "keep") }, function() applyGiftOnceRuntime() end)
    end,
})
G.__GAG2_AUTO_GIFT_ONCE_AFTER_SEND_MODE = onceAfterSendDd
_G.__GAG2_AUTO_GIFT_ONCE_AFTER_SEND_MODE = onceAfterSendDd

do
    local _, _, sendApi = ui:CreateRowToggle(bodyGiftOnce, "Send now", false, function(isOn)
        if isOn == true then
            local autoApi = G.__GAG2_AUTO_GIFT_AUTO_SEND_API or rawget(_G, "__GAG2_AUTO_GIFT_AUTO_SEND_API")
            if type(autoApi) == "table" and type(autoApi.set) == "function" then
                pcall(autoApi.set, false, true)
            end
            local multiApi = G.__GAG2_AUTO_GIFT_MULTI_SEND_API or rawget(_G, "__GAG2_AUTO_GIFT_MULTI_SEND_API")
            if type(multiApi) == "table" and type(multiApi.set) == "function" then
                pcall(multiApi.set, false, true)
            end
            local multiMod = G.AutoGiftMultiModule or G.AutoGiftMulti
                or rawget(_G, "AutoGiftMultiModule") or rawget(_G, "AutoGiftMulti")
            if type(multiMod) == "table" and type(multiMod.Stop) == "function" then
                pcall(multiMod.Stop, multiMod)
            end
        end
        sendGiftNow(isOn == true)
    end, nil, nil, false)
    G.__GAG2_AUTO_GIFT_SEND_API = sendApi
    _G.__GAG2_AUTO_GIFT_SEND_API = sendApi
end

-- Mail - Setting dibuat belakangan (setelah Mail Multi) lewat RegisterMailSettings.
M._buildMailSettingsSection = function(settingsUi)
    if type(settingsUi) ~= "table" then return end
    local bodyGiftOnceConfig = settingsUi:CreateSection("Mail - Setting", false)

    local onceCfgInit = normalizeGiftProfileFields(ensureAutoGiftStore().once, true)

    local harvestConfigLabel = select(1, settingsUi:CreateRowLabel(
        bodyGiftOnceConfig,
        "Config category Harvest",
        "Threshold = rentang total kombinasi buah (contoh target 1M + 10% → kirim total 1M–1.1M)",
        nil,
        "section"
    ))
    onceHarvestConfigLabel = harvestConfigLabel

    local _, onceSendModeDd = settingsUi:CreateRowDropdown(bodyGiftOnceConfig, {
        label = "Send mode",
        placeholder = "Total",
        mode = "single",
        getItems = function()
            return GIFT_ONCE_SEND_MODE_ITEMS
        end,
        initial = normalizeOnceSendMode(onceCfgInit.send_mode),
        onChanged = function(_, key)
            local mode = normalizeOnceSendMode(key)
            -- Mail - Setting shared: persist ke Once + Loop supaya tidak "masih total"
            patchGift({
                once = { send_mode = mode },
                loop = { send_mode = mode },
            }, function()
                applyGiftOnceRuntime()
                applyGiftLoopRuntime()
            end)
            refreshOnceSendModeUi(mode)
        end,
    })
    G.__GAG2_AUTO_GIFT_ONCE_SEND_MODE = onceSendModeDd
    _G.__GAG2_AUTO_GIFT_ONCE_SEND_MODE = onceSendModeDd

    local onceHarvestCfg = onceCfgInit
    local harvestThresholdRow, harvestThresholdFn = settingsUi:CreateRowInput(
        bodyGiftOnceConfig,
        "Harvest price threshold max %",
        tostring(onceHarvestCfg.harvest_price_threshold_pct or 10),
        function(txt)
            local n = tonumber(txt)
            if n == nil then return end
            if n < 0 then n = 0 end
            if n > 100 then n = 100 end
            local pct = math.floor(n)
            patchGift({
                once = { harvest_price_threshold_pct = pct },
                loop = { harvest_price_threshold_pct = pct },
            }, function()
                applyGiftOnceRuntime()
                applyGiftLoopRuntime()
            end)
        end,
        false -- jangan clearOnFocus saat pindah tab
    )
    onceHarvestPriceRows[#onceHarvestPriceRows + 1] = harvestThresholdRow
    G.__GAG2_AUTO_GIFT_ONCE_HARVEST_THRESHOLD = harvestThresholdFn
    _G.__GAG2_AUTO_GIFT_ONCE_HARVEST_THRESHOLD = G.__GAG2_AUTO_GIFT_ONCE_HARVEST_THRESHOLD

    local _, _, onceAutoUnfavApi = settingsUi:CreateRowToggle(
        bodyGiftOnceConfig,
        "Auto unfav fruit",
        onceHarvestCfg.auto_unfav == true,
        function(isOn)
            local on = (isOn == true)
            patchGift({
                once = { auto_unfav = on },
                loop = { auto_unfav = on },
            }, function()
                applyGiftOnceRuntime()
                applyGiftLoopRuntime()
            end)
        end
    )
    G.__GAG2_AUTO_GIFT_ONCE_AUTO_UNFAV = onceAutoUnfavApi
    _G.__GAG2_AUTO_GIFT_ONCE_AUTO_UNFAV = onceAutoUnfavApi

    local onceHarvestCalcRow, onceHarvestCalcDd = settingsUi:CreateRowDropdown(bodyGiftOnceConfig, {
        label = "Mode calculation",
        placeholder = "Base",
        mode = "single",
        getItems = function()
            return GIFT_ONCE_HARVEST_CALC_ITEMS
        end,
        initial = normalizeGiftOnceHarvestCalcMode(onceHarvestCfg.harvest_price_calc_mode),
        onChanged = function(_, key)
            local calc = normalizeGiftOnceHarvestCalcMode(key)
            patchGift({
                once = { harvest_price_calc_mode = calc },
                loop = { harvest_price_calc_mode = calc },
            }, function()
                applyGiftOnceRuntime()
                applyGiftLoopRuntime()
            end)
        end,
    })
    onceHarvestPriceRows[#onceHarvestPriceRows + 1] = onceHarvestCalcRow
    G.__GAG2_AUTO_GIFT_ONCE_HARVEST_CALC_MODE = onceHarvestCalcDd
    _G.__GAG2_AUTO_GIFT_ONCE_HARVEST_CALC_MODE = onceHarvestCalcDd

    refreshOnceSendModeUi(onceCfgInit.send_mode)

    local historyCfg = ensureAutoGiftStore()
    do
        local _, _, historyToggleApi = settingsUi:CreateRowToggle(
            bodyGiftOnceConfig,
            "Show gift mail history",
            historyCfg.show_gift_history == true,
            function(isOn)
                local on = isOn == true
                patchGift({ show_gift_history = on }, function()
                    forceGiftHistoryPanelVisible(on)
                end)
                forceGiftHistoryPanelVisible(on)
            end
        )
        G.__GAG2_AUTO_GIFT_HISTORY_TOGGLE_API = historyToggleApi
        _G.__GAG2_AUTO_GIFT_HISTORY_TOGGLE_API = historyToggleApi

        G.__GAG2_SYNC_GIFT_HISTORY_TOGGLE = function(on)
            local api = G.__GAG2_AUTO_GIFT_HISTORY_TOGGLE_API or rawget(_G, "__GAG2_AUTO_GIFT_HISTORY_TOGGLE_API")
            if type(api) == "table" and type(api.set) == "function" then
                pcall(api.set, on == true, true)
            end
            patchGift({ show_gift_history = on == true }, function()
                forceGiftHistoryPanelVisible(on == true)
            end)
            forceGiftHistoryPanelVisible(on == true)
        end
        _G.__GAG2_SYNC_GIFT_HISTORY_TOGGLE = G.__GAG2_SYNC_GIFT_HISTORY_TOGGLE

        _, G.__GAG2_AUTO_GIFT_HISTORY_RETAIN_DAYS = settingsUi:CreateRowInput(
            bodyGiftOnceConfig,
            "History retain (days)",
            tostring(historyCfg.gift_history_retain_days or 7),
            function(txt)
                local n = math.floor(tonumber(txt) or 7)
                if n < 1 then n = 1 end
                if n > 90 then n = 90 end
                patchGift({ gift_history_retain_days = n }, function()
                    applyGiftHistoryUiFromStore()
                end)
            end
        )
        _G.__GAG2_AUTO_GIFT_HISTORY_RETAIN_DAYS = G.__GAG2_AUTO_GIFT_HISTORY_RETAIN_DAYS
    end
end

