 end,    required = false },
    { key = "AutoGiftMulti",           name = "Auto Gift Multi",         factory = function() -- AutoGiftMulti.lua — Gift Mail multi-username queue (A → B → C → selesai)
-- Orchestrates AutoGift Once-style jobs; does not replace Mail Once / Mail Loop.

local G = (getgenv and getgenv()) or _G
local M = {}

local MAX_TARGETS = 200

local cfg = {
    targets = {},
    categories = {},
    selected = {},
    category_mode = "single",
    after_send_mode = "keep",
    send_total = 1000,
    send_totals = {},
    note = "",
    delay_sec = 10,
    skip_equipped = true,
    max_per_batch = 999999,
}

-- Mode/harvest/auto_unfav dari Mail - Setting (Once); total/price dari Multi cfg sendiri
local function _readMailOnceSendSettings()
    local gift = G.__GAG2_AUTO_GIFT or rawget(_G, "__GAG2_AUTO_GIFT")
    if type(gift) ~= "table" then
        local main = G.MAIN or rawget(_G, "MAIN")
        if type(main) == "table" and type(main.auto) == "table" then
            gift = main.auto.gift
        end
    end
    gift = type(gift) == "table" and gift or {}
    local once = type(gift.once) == "table" and gift.once or gift
    once = type(once) == "table" and once or {}

    local pct = math.floor(tonumber(once.harvest_price_threshold_pct) or 10)
    if pct < 0 then pct = 0 end
    if pct > 100 then pct = 100 end

    return {
        send_mode = (tostring(once.send_mode or "total"):lower() == "price") and "price" or "total",
        harvest_price_threshold_pct = pct,
        harvest_price_calc_mode = (tostring(once.harvest_price_calc_mode or "base"):lower() == "stock") and "stock" or "base",
        auto_unfav = once.auto_unfav == true,
        note = tostring(gift.note or cfg.note or ""),
        delay_sec = tonumber(gift.delay_sec) or tonumber(cfg.delay_sec) or 10,
        skip_equipped = (gift.skip_equipped ~= false) and (cfg.skip_equipped ~= false),
        max_per_batch = gift.max_per_batch or cfg.max_per_batch,
    }
end

local St = {
    running = false,
    jobId = 0,
    currentIndex = 0,
    users = {}, -- { username, user_id, display, status, reason, sent_ok }
    lastStatus = "Ready",
    summary = "",
}

local function _getAutoGift()
    return G.AutoGiftModule or G.AutoGift or rawget(_G, "AutoGiftModule") or rawget(_G, "AutoGift")
end

local function _getHistory()
    return G.GiftMailHistoryModule or G.GiftMailHistory
        or rawget(_G, "GiftMailHistoryModule") or rawget(_G, "GiftMailHistory")
end

local function _cleanUser(s)
    return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
end

local function _setStatus(msg)
    msg = tostring(msg or "")
    St.lastStatus = msg
    G.AUTO_GIFT_MULTI_STATUS = msg
    _G.AUTO_GIFT_MULTI_STATUS = msg
    local fn = G.__GAG2_REFRESH_GIFT_MULTI_STATUS or rawget(_G, "__GAG2_REFRESH_GIFT_MULTI_STATUS")
    if type(fn) == "function" then
        pcall(fn)
    end
end

local function _normalizeTargets(list)
    local out, seen = {}, {}
    if type(list) ~= "table" then return out end
    local src = (#list > 0) and list or nil
    if src then
        for _, row in ipairs(list) do
            if #out >= MAX_TARGETS then break end
            if type(row) == "table" then
                local uid = math.floor(tonumber(row.user_id or row.userId or row.key) or 0)
                local user = _cleanUser(row.username or row.name or row.user or "")
                local disp = tostring(row.display or row.recipient_display or "")
                if uid <= 0 and user == "" and row.key ~= nil then
                    local k = tostring(row.key)
                    uid = math.floor(tonumber(k) or 0)
                    if uid <= 0 then user = _cleanUser(k) end
                end
                local idKey = (uid > 0) and ("id:" .. tostring(uid)) or ("u:" .. user:lower())
                if (uid > 0 or user ~= "") and not seen[idKey] then
                    seen[idKey] = true
                    out[#out + 1] = {
                        username = user,
                        user_id = uid,
                        display = (disp ~= "" and disp) or user,
                    }
                end
            elseif type(row) == "string" or type(row) == "number" then
                local s = tostring(row)
                local uid = math.floor(tonumber(s) or 0)
                local user = (uid > 0) and "" or _cleanUser(s)
                local idKey = (uid > 0) and ("id:" .. tostring(uid)) or ("u:" .. user:lower())
                if (uid > 0 or user ~= "") and not seen[idKey] then
                    seen[idKey] = true
                    out[#out + 1] = { username = user, user_id = uid, display = user }
                end
            end
        end
        return out
    end
    for k, v in pairs(list) do
        if #out >= MAX_TARGETS then break end
        if v == true or v == 1 or v == "true" or type(v) == "table" then
            local uid = math.floor(tonumber(k) or 0)
            local user = ""
            local disp = ""
            if type(v) == "table" then
                uid = math.floor(tonumber(v.user_id or v.userId or k) or uid)
                user = _cleanUser(v.username or v.name or "")
                disp = tostring(v.display or "")
            end
            if uid <= 0 then user = _cleanUser(k) end
            local idKey = (uid > 0) and ("id:" .. tostring(uid)) or ("u:" .. user:lower())
            if (uid > 0 or user ~= "") and not seen[idKey] then
                seen[idKey] = true
                out[#out + 1] = {
                    username = user,
                    user_id = uid,
                    display = (disp ~= "" and disp) or user,
                }
            end
        end
    end
    return out
end

local function _normalizeSelectedMap(src)
    local out = {}
    if type(src) ~= "table" then return out end
    if #src > 0 then
        for _, v in ipairs(src) do
            if v ~= nil and tostring(v) ~= "" then out[tostring(v)] = true end
        end
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then out[tostring(k)] = true end
    end
    return out
end

local function _normalizeCategories(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, v in pairs(src) do
        out[tostring(k)] = (v == true)
    end
    return out
end

local function _shortName(u, maxLen)
    maxLen = math.floor(tonumber(maxLen) or 16)
    local name = ""
    if type(u) == "table" then
        name = tostring(u.display ~= "" and u.display or u.username or u.user_id or "")
    else
        name = tostring(u or "")
    end
    name = name:gsub("^@", "")
    if #name > maxLen then
        name = name:sub(1, math.max(1, maxLen - 1)) .. "…"
    end
    return name
end

local function _countUserStatuses()
    local c = { done = 0, failed = 0, skipped = 0, partial = 0, pending = 0, sending = 0, total = #St.users }
    for _, u in ipairs(St.users) do
        local s = tostring(u.status or "pending")
        if c[s] ~= nil then
            c[s] += 1
        else
            c.pending += 1
        end
    end
    return c
end

local function _summaryText()
    local c = _countUserStatuses()
    local parts = { tostring(c.done) .. "/" .. tostring(c.total) .. " done" }
    if c.partial > 0 then parts[#parts + 1] = tostring(c.partial) .. " partial" end
    if c.failed > 0 then parts[#parts + 1] = tostring(c.failed) .. " failed" end
    if c.skipped > 0 then parts[#parts + 1] = tostring(c.skipped) .. " skipped" end
    if c.sending > 0 then parts[#parts + 1] = tostring(c.sending) .. " sending" end
    if c.pending > 0 and St.running then parts[#parts + 1] = tostring(c.pending) .. " pending" end
    return table.concat(parts, " · ")
end

local function _progressSnapshot()
    local c = _countUserStatuses()
    local last = tostring(St.lastStatus or "")
    local status = "Ready"
    if St.running then
        status = "Running"
    elseif last:find("stop", 1, true) or last:find("Stop", 1, true) then
        status = "Stopped"
    elseif c.total > 0 and (c.done + c.failed + c.partial + c.skipped) >= c.total then
        status = (c.failed > 0 or c.partial > 0) and "Finished*" or "Done"
    elseif last:find("pilih", 1, true) or last:find("missing", 1, true) then
        status = "Idle"
    end

    local process = "-"
    if St.running and St.currentIndex > 0 and St.users[St.currentIndex] then
        local u = St.users[St.currentIndex]
        local st = tostring(u.status or "sending")
        local verb = (st == "sending") and "Sending" or st
        process = string.format("%s %d/%d · %s", verb, St.currentIndex, c.total, _shortName(u, 18))
    elseif status == "Done" or status == "Finished*" or status == "Stopped" then
        process = status == "Stopped" and "Stopped" or "Batch complete"
    elseif status == "Idle" then
        process = last:gsub("^Mail Multi:%s*", "")
        if #process > 40 then process = process:sub(1, 39) .. "…" end
    end

    local queueParts = {}
    if c.total > 0 then
        queueParts[#queueParts + 1] = tostring(c.done) .. " done"
        if c.sending > 0 then queueParts[#queueParts + 1] = tostring(c.sending) .. " send" end
        if c.pending > 0 then queueParts[#queueParts + 1] = tostring(c.pending) .. " wait" end
        if c.failed > 0 then queueParts[#queueParts + 1] = tostring(c.failed) .. " fail" end
        if c.partial > 0 then queueParts[#queueParts + 1] = tostring(c.partial) .. " part" end
        if c.skipped > 0 then queueParts[#queueParts + 1] = tostring(c.skipped) .. " skip" end
    else
        queueParts[1] = "No targets"
    end

    local note = ""
    if St.currentIndex > 0 and St.users[St.currentIndex] then
        local r = tostring(St.users[St.currentIndex].reason or "")
        if r ~= "" then note = r end
    end
    if note == "" then
        for i = #St.users, 1, -1 do
            local u = St.users[i]
            local st = tostring(u.status or "")
            local r = tostring(u.reason or "")
            if r ~= "" and (st == "failed" or st == "partial" or st == "skipped") then
                note = _shortName(u, 12) .. ": " .. r
                break
            end
        end
    end
    if #note > 42 then note = note:sub(1, 41) .. "…" end

    return {
        status = status,
        process = process,
        queue = table.concat(queueParts, " · "),
        note = note,
        summary = _summaryText(),
    }
end

local function _refreshSummary()
    St.summary = _summaryText()
    local p = _progressSnapshot()
    if St.running then
        _setStatus(p.process)
    elseif St.lastStatus == "Ready" or tostring(St.lastStatus or ""):find("Mail Multi", 1, true)
        or tostring(St.lastStatus or ""):find("Sending", 1, true)
        or tostring(St.lastStatus or ""):find("Batch", 1, true) then
        _setStatus(p.status == "Ready" and "Ready" or (p.process ~= "-" and p.process or p.status))
    end
end

-- Success history dicatat AutoGift (RecordSendBatch, profile=multi).
-- Stub ini hanya untuk gagal/skip (belum ada batch item).
local function _recordUserHistory(user, ok, reason, index, total)
    if ok == true then return end
    local hist = _getHistory()
    if type(hist) ~= "table" or type(hist.Record) ~= "function" then return end
    local label = tostring(user.display ~= "" and user.display or user.username or user.user_id)
    local st = tostring(user.status or "failed")
    local why = tostring(reason or "")
    local msg = string.format("%d/%d · %s", index, total, st)
    if why ~= "" then msg = msg .. " · " .. why end
    pcall(hist.Record, {
        ts = os.time(),
        profile = "multi",
        success = false,
        recipient_user_id = math.floor(tonumber(user.user_id) or 0),
        recipient_username = tostring(user.username or ""),
        recipient_display = label,
        item_count = 0,
        send_batch = 0, -- bukan nomor urut target; batch kirim hanya di RecordSendBatch sukses
        batch_rows = 0,
        note = tostring(cfg.note or ""),
        message = msg,
        summary = {},
    })
end

local function _stopOnceAndLoop()
    local onceApi = G.__GAG2_AUTO_GIFT_SEND_API or rawget(_G, "__GAG2_AUTO_GIFT_SEND_API")
    if type(onceApi) == "table" and type(onceApi.set) == "function" then
        pcall(onceApi.set, false, true)
    end
    local loopApi = G.__GAG2_AUTO_GIFT_AUTO_SEND_API or rawget(_G, "__GAG2_AUTO_GIFT_AUTO_SEND_API")
    if type(loopApi) == "table" and type(loopApi.set) == "function" then
        pcall(loopApi.set, false, true)
    end
    local ag = _getAutoGift()
    if type(ag) == "table" then
        if type(ag.StopSendJob) == "function" then pcall(ag.StopSendJob, ag) end
        if type(ag.StopAutoSend) == "function" then pcall(ag.StopAutoSend, ag) end
        if type(ag.ApplyAutoSendRuntime) == "function" then pcall(ag.ApplyAutoSendRuntime, ag, false) end
    end
end

local function _isHarvestCatKey(key)
    local n = tostring(key or ""):lower():gsub("[%s_]+", "")
    return n == "harvestedfruits" or n == "harvestedfruit"
end

local function _multiHasHarvestCategory(categories)
    categories = type(categories) == "table" and categories or {}
    if categories.HarvestedFruits == true then return true end
    for key, on in pairs(categories) do
        if on == true and _isHarvestCatKey(key) then
            return true
        end
    end
    return false
end

local function _buildOnceConfigForUser(user)
    local selected = {}
    for cat, map in pairs(cfg.selected) do
        selected[cat] = _normalizeSelectedMap(map)
    end
    local onceSend = _readMailOnceSendSettings()
    local categories = _normalizeCategories(cfg.categories)
    -- Preserve enabled cats that normalize may drop when catalog keys incomplete
    if type(cfg.categories) == "table" then
        for key, on in pairs(cfg.categories) do
            if type(key) == "string" and on == true then
                categories[key] = true
            end
        end
    end
    local send_totals = {}
    if type(cfg.send_totals) == "table" then
        for k, v in pairs(cfg.send_totals) do
            send_totals[tostring(k)] = math.max(1, math.floor(tonumber(v) or 20))
        end
    end
    local multiSendTotal = math.max(1, math.floor(tonumber(cfg.send_total) or 1000))
    -- Alur sama Once: Mail Setting Price + Harvest di Multi → price path
    local wantPrice = (tostring(onceSend.send_mode) == "price") and _multiHasHarvestCategory(categories)
    -- Never seed count totals from the price goal (e.g. 1M) — that made failed price
    -- detection look like a huge "total" send, or wipe price behavior entirely.
    if not next(send_totals) then
        for cat, on in pairs(categories) do
            if on == true then
                send_totals[cat] = 20
                break
            end
        end
    end
    -- Keep Harvest explicitly enabled so AutoGift price mode cannot drop it.
    if wantPrice then
        categories.HarvestedFruits = true
    end
    return {
        enabled = true,
        auto_send = false,
        recipient_username = tostring(user.username or ""),
        recipient_user_id = math.floor(tonumber(user.user_id) or 0),
        recipient_display = tostring(user.display or user.username or ""),
        categories = categories,
        selected = selected,
        skip_equipped = onceSend.skip_equipped ~= false,
        max_per_batch = onceSend.max_per_batch,
        note = tostring(onceSend.note or ""),
        delay_sec = tonumber(onceSend.delay_sec) or 10,
        send_totals = send_totals,
        category_mode = (tostring(cfg.category_mode) == "multi") and "multi" or "single",
        send_list_mode = "send_total",
        send_total = multiSendTotal,
        after_send_mode = "keep",
        harvest_price_threshold_pct = math.floor(tonumber(onceSend.harvest_price_threshold_pct) or 10),
        harvest_price_calc_mode = (tostring(onceSend.harvest_price_calc_mode) == "stock") and "stock" or "base",
        once_send_mode = wantPrice and "price" or "total",
        auto_unfav = onceSend.auto_unfav == true,
    }
end

local function _waitSendJob(ag, myMultiId)
    local finished, okFlag = false, false
    local prev = G.__GAG2_GIFT_SEND_JOB_DONE or rawget(_G, "__GAG2_GIFT_SEND_JOB_DONE")
    local wrapper = function(ok, keepToggle)
        okFlag = ok == true
        finished = true
        if type(prev) == "function" then
            -- keepToggle true: jangan ganggu toggle Once saat multi jalan
            pcall(prev, ok, true)
        end
    end
    G.__GAG2_GIFT_SEND_JOB_DONE = wrapper
    _G.__GAG2_GIFT_SEND_JOB_DONE = wrapper

    local started, startErr = false, nil
    if type(ag.StartSendJob) == "function" then
        local okCall, a, b = pcall(ag.StartSendJob, ag)
        if okCall then
            started = a == true or a == nil
            startErr = b
            if a == false then
                started = false
                startErr = b or "start_failed"
            end
        else
            started = false
            startErr = a
        end
    else
        startErr = "StartSendJob missing"
    end

    if not started then
        if G.__GAG2_GIFT_SEND_JOB_DONE == wrapper then
            G.__GAG2_GIFT_SEND_JOB_DONE = prev
            _G.__GAG2_GIFT_SEND_JOB_DONE = prev
        end
        return false, tostring(startErr or "start_failed")
    end

    local t0 = os.clock()
    local stoppedAt = 0
    while St.running and St.jobId == myMultiId do
        if finished then break end
        if type(ag.IsSendJobRunning) == "function" then
            local okR, running = pcall(ag.IsSendJobRunning, ag)
            if okR and running ~= true then
                -- Jangan anggap sukses: callback bisa delay karena restore fav.
                -- History di-flush sebelum callback; tunggu callback, bukan StartSendJob berikutnya.
                if stoppedAt <= 0 then
                    stoppedAt = os.clock()
                elseif (os.clock() - stoppedAt) > 20 then
                    okFlag = false
                    finished = true
                    break
                end
            else
                stoppedAt = 0
            end
        end
        if os.clock() - t0 > 600 then
            if type(ag.StopSendJob) == "function" then pcall(ag.StopSendJob, ag) end
            if G.__GAG2_GIFT_SEND_JOB_DONE == wrapper then
                G.__GAG2_GIFT_SEND_JOB_DONE = prev
                _G.__GAG2_GIFT_SEND_JOB_DONE = prev
            end
            return false, "timeout"
        end
        task.wait(0.15)
    end

    if G.__GAG2_GIFT_SEND_JOB_DONE == wrapper then
        G.__GAG2_GIFT_SEND_JOB_DONE = prev
        _G.__GAG2_GIFT_SEND_JOB_DONE = prev
    end

    if not St.running or St.jobId ~= myMultiId then
        return false, "stopped"
    end
    return okFlag == true, okFlag and "" or "send_failed"
end

local function _classifyFailReason(ag, reason)
    reason = tostring(reason or "")
    local st = ""
    if type(ag) == "table" and type(ag.GetProfileStatus) == "function" then
        local ok, s = pcall(ag.GetProfileStatus, ag, "once")
        if ok then st = tostring(s or "") end
    end
    local blob = (reason .. " " .. st):lower()
    -- hardStop=true → hentikan queue + matikan toggle Send multi
    -- Gift limit = per username (server max ~5). Soft fail: skip user, lanjut antrean.
    if reason == "daily_limit"
        or blob:find("daily_limit", 1, true)
        or blob:find("daily gift limit", 1, true)
        or blob:find("gift limit", 1, true)
        or (blob:find("daily", 1, true) and blob:find("gift", 1, true) and blob:find("limit", 1, true))
        or blob:find("try again tomorrow", 1, true)
        or (blob:find("reached", 1, true) and blob:find("gift", 1, true) and blob:find("limit", 1, true)) then
        return "daily_limit", false
    end
    if blob:find("cooldown", 1, true) then return "cooldown", true end
    if blob:find("kurang", 1, true)
        or blob:find("no item", 1, true)
        or blob:find("no_items", 1, true)
        or blob:find("tidak ada", 1, true)
        or blob:find("empty", 1, true) then
        return "no_items", true
    end
    -- lookup/username salah: skip user ini saja, lanjut antrean (bukan hard-stop)
    if blob:find("lookup", 1, true) or blob:find("recipient", 1, true) or blob:find("target", 1, true) then
        return "lookup_fail", false
    end
    if blob:find("mailbox", 1, true) then return "mailbox_disabled", true end
    if blob:find("error", 1, true) or blob:find("fail", 1, true) or blob:find("gagal", 1, true) then
        return (reason ~= "" and reason) or (st ~= "" and st) or "send_failed", true
    end
    if reason ~= "" then return reason, true end
    if st ~= "" then return st, true end
    return "send_failed", true
end

local function _finishMultiJob(statusMsg)
    St.currentIndex = 0
    St.running = false
    G.__GAG2_GIFT_MULTI_ACTIVE = false
    _G.__GAG2_GIFT_MULTI_ACTIVE = false
    _refreshSummary()
    if statusMsg ~= nil and tostring(statusMsg) ~= "" then
        local msg = tostring(statusMsg)
        if #msg > 40 then msg = msg:sub(1, 39) .. "…" end
        _setStatus(msg)
    else
        local p = _progressSnapshot()
        _setStatus(p.status == "Finished*" and "Finished with issues" or "Done")
    end
    local doneFn = G.__GAG2_GIFT_MULTI_JOB_DONE or rawget(_G, "__GAG2_GIFT_MULTI_JOB_DONE")
    if type(doneFn) == "function" then
        pcall(doneFn, false)
    end
end

local function _notifyLookupFail(user)
    local fn = G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL or rawget(_G, "__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL")
    if type(fn) ~= "function" then return end
    local key = _cleanUser(user and user.username or "")
    if key == "" then
        key = tostring(user and user.user_id or "")
    end
    if key ~= "" and key ~= "0" then
        pcall(fn, key)
    end
end

local function _notifyLookupOk(user)
    local fn = G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK or rawget(_G, "__GAG2_ON_GIFT_MULTI_LOOKUP_OK")
    if type(fn) ~= "function" or type(user) ~= "table" then return end
    local uid = math.floor(tonumber(user.user_id) or 0)
    if uid <= 0 then return end
    local key = _cleanUser(user.username)
    if key == "" then key = tostring(uid) end
    pcall(fn, key, uid, user.display or user.username)
end

local function _resolveUser(ag, user)
    local uid = math.floor(tonumber(user.user_id) or 0)
    if uid > 0 then
        user.user_id = uid
        return true
    end
    local name = _cleanUser(user.username)
    if name == "" then return false, "lookup_fail" end
    if type(ag.LookupRecipient) == "function" then
        local ok, res = pcall(ag.LookupRecipient, ag, name)
        if ok and res == true then
            if type(ag.GetConfig) == "function" then
                local okC, c = pcall(ag.GetConfig, ag)
                if okC and type(c) == "table" then
                    user.user_id = math.floor(tonumber(c.recipient_user_id) or 0)
                    if tostring(c.recipient_username or "") ~= "" then
                        user.username = tostring(c.recipient_username)
                    end
                    if tostring(c.recipient_display or "") ~= "" then
                        user.display = tostring(c.recipient_display)
                    end
                end
            end
            if user.user_id > 0 then
                _notifyLookupOk(user)
                return true
            end
        end
    end
    return false, "lookup_fail"
end

local function _skipRemainingUsers(fromIndex, total, reason)
    for j = fromIndex, total do
        local u2 = St.users[j]
        if u2 and (u2.status == "pending" or u2.status == "sending") then
            u2.status = "skipped"
            u2.reason = reason
            _recordUserHistory(u2, false, reason, j, total)
        end
    end
end

local function _runQueue(myId)
    local ag = _getAutoGift()
    if type(ag) ~= "table" then
        _finishMultiJob("AutoGift missing")
        return
    end

    local total = #St.users
    local stoppedEarly = false
    local stopReason = ""
    for i, user in ipairs(St.users) do
        if not St.running or St.jobId ~= myId then
            stoppedEarly = true
            stopReason = "stopped"
            break
        end
        St.currentIndex = i
        user.status = "sending"
        user.reason = ""
        _refreshSummary()

        local okResolve, resolveErr = _resolveUser(ag, user)
        if not okResolve then
            user.status = "failed"
            user.reason = tostring(resolveErr or "lookup_fail")
            _notifyLookupFail(user)
            _recordUserHistory(user, false, user.reason, i, total)
            _refreshSummary()
            -- username salah / lookup fail → skip user, lanjut antrean
            task.wait(0.2)
            continue
        end

        local onceCfg = _buildOnceConfigForUser(user)
        if type(ag.ApplyConfig) == "function" then
            pcall(ag.ApplyConfig, ag, onceCfg)
        end

        -- Re-apply recipient after ApplyConfig (Lookup may have filled ids)
        if type(ag.ApplyConfig) == "function" then
            pcall(ag.ApplyConfig, ag, {
                recipient_username = user.username,
                recipient_user_id = user.user_id,
                recipient_display = user.display,
                send_list_mode = "send_total",
                auto_send = false,
            })
        end

        _setStatus(string.format("Sending %d/%d · %s", i, total, _shortName(user, 18)))

        local okSend, sendReason = _waitSendJob(ag, myId)
        if not St.running or St.jobId ~= myId then
            user.status = "skipped"
            user.reason = "stopped"
            stoppedEarly = true
            stopReason = "stopped"
            break
        end

        if okSend then
            user.status = "done"
            user.reason = ""
            user.sent_ok = true
            _recordUserHistory(user, true, "", i, total)
        else
            local reason, hardStop = _classifyFailReason(ag, sendReason)
            if reason == "no_items" or reason == "empty_batch" then
                user.status = "partial"
            elseif reason == "stopped" then
                user.status = "skipped"
            else
                user.status = "failed"
            end
            user.reason = reason
            if reason == "lookup_fail" then
                _notifyLookupFail(user)
            end
            -- Partial: item yang sempat terkirim sudah di-flush AutoGift (jangan kartu kosong).
            if user.status ~= "partial" then
                _recordUserHistory(user, false, reason, i, total)
            end
            if hardStop ~= false then
                -- gagal keras (limit/cooldown/no_items/dll) → stop queue + matikan toggle
                _skipRemainingUsers(i + 1, total, reason)
                stoppedEarly = true
                stopReason = reason
                break
            end
            -- soft fail (lookup): lanjut user berikutnya
        end
        _refreshSummary()
        task.wait(0.2)
    end

    if stoppedEarly and stopReason ~= "" and stopReason ~= "stopped" then
        _finishMultiJob("Stopped · " .. tostring(stopReason))
    else
        _finishMultiJob(nil)
    end

    -- After send Reset: hapus user yang sudah completed, meski antrean stop di tengah (limit/dll).
    -- Stop manual (tombol) tidak reset list.
    if cfg.after_send_mode == "reset" and stopReason ~= "stopped" then
        local resetFn = G.__GAG2_RESET_GIFT_MULTI or rawget(_G, "__GAG2_RESET_GIFT_MULTI")
        if type(resetFn) == "function" then
            pcall(resetFn)
        end
    end
end

function M.ApplyConfig(_self, nextCfg)
    if type(_self) == "table" and nextCfg == nil then
        nextCfg = _self
    end
    if type(nextCfg) ~= "table" then return cfg end
    if nextCfg.targets ~= nil then cfg.targets = _normalizeTargets(nextCfg.targets) end
    if nextCfg.categories ~= nil then cfg.categories = _normalizeCategories(nextCfg.categories) end
    if type(nextCfg.selected) == "table" then
        cfg.selected = {}
        for cat, map in pairs(nextCfg.selected) do
            cfg.selected[tostring(cat)] = _normalizeSelectedMap(map)
        end
    end
    if nextCfg.category_mode ~= nil then
        cfg.category_mode = (tostring(nextCfg.category_mode) == "multi") and "multi" or "single"
    end
    if nextCfg.after_send_mode ~= nil then
        cfg.after_send_mode = (tostring(nextCfg.after_send_mode) == "reset") and "reset" or "keep"
    end
    if nextCfg.send_total ~= nil then
        cfg.send_total = math.max(1, math.floor(tonumber(nextCfg.send_total) or 1000))
    end
    if type(nextCfg.send_totals) == "table" then
        cfg.send_totals = {}
        for k, v in pairs(nextCfg.send_totals) do
            cfg.send_totals[tostring(k)] = math.max(1, math.floor(tonumber(v) or 20))
        end
    end
    if nextCfg.note ~= nil then cfg.note = tostring(nextCfg.note or "") end
    if nextCfg.delay_sec ~= nil then cfg.delay_sec = tonumber(nextCfg.delay_sec) or 10 end
    if nextCfg.skip_equipped ~= nil then cfg.skip_equipped = nextCfg.skip_equipped ~= false end
    if nextCfg.max_per_batch ~= nil then
        cfg.max_per_batch = math.floor(tonumber(nextCfg.max_per_batch) or 999999)
    end
    return cfg
end

function M.GetConfig(_self)
    local onceSend = _readMailOnceSendSettings()
    return {
        targets = cfg.targets,
        categories = cfg.categories,
        selected = cfg.selected,
        category_mode = cfg.category_mode,
        send_mode = onceSend.send_mode,
        send_total = cfg.send_total,
        send_totals = cfg.send_totals,
        harvest_price_threshold_pct = onceSend.harvest_price_threshold_pct,
        harvest_price_calc_mode = onceSend.harvest_price_calc_mode,
        after_send_mode = cfg.after_send_mode,
        auto_unfav = onceSend.auto_unfav,
        note = onceSend.note,
        delay_sec = onceSend.delay_sec,
        skip_equipped = onceSend.skip_equipped,
        max_per_batch = onceSend.max_per_batch,
    }
end

function M.GetStatus(_self)
    local p = _progressSnapshot()
    return p.status or St.lastStatus or "Ready"
end

function M.GetSummary(_self)
    return St.summary ~= "" and St.summary or _summaryText()
end

function M.GetProgress(_self)
    return _progressSnapshot()
end

function M.GetUserStatuses(_self)
    local out = {}
    for _, u in ipairs(St.users) do
        out[#out + 1] = {
            username = u.username,
            user_id = u.user_id,
            display = u.display,
            status = u.status,
            reason = u.reason,
            sent_ok = u.sent_ok == true,
        }
    end
    return out
end

function M.PruneCompletedUsers(_self)
    local kept = {}
    for _, u in ipairs(St.users) do
        if tostring(u.status or "") ~= "done" and u.sent_ok ~= true then
            kept[#kept + 1] = u
        end
    end
    St.users = kept
    St.currentIndex = 0
    _refreshSummary()
    return #kept
end

function M.IsRunning(_self)
    return St.running == true
end

function M.MaxTargets()
    return MAX_TARGETS
end

function M.Stop(_self)
    St.running = false
    G.__GAG2_GIFT_MULTI_ACTIVE = false
    _G.__GAG2_GIFT_MULTI_ACTIVE = false
    local ag = _getAutoGift()
    if type(ag) == "table" and type(ag.StopSendJob) == "function" then
        pcall(ag.StopSendJob, ag)
    end
    _setStatus("Stopped")
end

-- [NODEHUBWS APPLY UI] Auto Gift Multi
-- id_code_list: 271 / Gag2_autogiftmulti
-- Taruh setelah: function M.Stop(_self) selesai
-- Sebelum: function M.Start(_self, targetsOverride)
if type(NodeHubWS) == "table" and type(NodeHubWS.OnApplyUI) == "function" then
    NodeHubWS.OnApplyUI("gag2", "auto_gift_multi_runtime", function(config, message, bridge, api)
        local giftMulti = api.get(config, "main.auto.giftMulti") or api.get(config, "main.auto.autoGiftMulti")
        if type(giftMulti) ~= "table" then return true end
        if type(M.ApplyConfig) == "function" then pcall(M.ApplyConfig, M, giftMulti) end
        return true
    end)
end

function M.Start(_self, targetsOverride)
    if St.running then return false, "already_running" end
    local targets = _normalizeTargets(targetsOverride or cfg.targets)
    if #targets == 0 then
        _setStatus("Select targets first")
        return false, "no_targets"
    end
    if not next(cfg.categories) then
        _setStatus("Select category first")
        return false, "no_category"
    end
    local hasCat = false
    for _, on in pairs(cfg.categories) do
        if on == true then hasCat = true break end
    end
    if not hasCat then
        _setStatus("Select category first")
        return false, "no_category"
    end

    local ag = _getAutoGift()
    if type(ag) ~= "table" then
        _setStatus("AutoGift missing")
        return false, "no_autogift"
    end

    _stopOnceAndLoop()
    cfg.targets = targets
    St.users = {}
    for _, t in ipairs(targets) do
        St.users[#St.users + 1] = {
            username = t.username,
            user_id = t.user_id,
            display = t.display,
            status = "pending",
            reason = "",
            sent_ok = false,
        }
    end
    St.running = true
    St.jobId += 1
    local myId = St.jobId
    St.currentIndex = 0
    G.__GAG2_GIFT_MULTI_ACTIVE = true
    _G.__GAG2_GIFT_MULTI_ACTIVE = true
    _refreshSummary()
    _setStatus(string.format("Starting · %d targets", #St.users))

    task.spawn(function()
        task.wait(0.1)
        _runQueue(myId)
    end)
    return true
end

G.AutoGiftMulti = M
G.AutoGiftMultiModule = M
_G.AutoGiftMulti = M
_G.AutoGiftMultiModule = M

return M
 end,                 required = false },
    { key = "SectionAutoGiftMulti",    name = "Section Auto Gift Multi", factory = function() -- section_auto_gift_multi.lua — Mail Multi UI (multi username gift mail)
-- Dipanggil dari tabs_auto.lua (tab Auto → Gift & Drop)

local G = (getgenv and getgenv()) or _G
local M = {}

local MAX_TARGETS = 200
local GIFT_HARVESTED_FRUITS_CAT = "HarvestedFruits"
local VERIFY_MAX_ATTEMPTS = 20
local VERIFY_RESOLVE_GAP = 1.0
local VERIFY_IDLE_SLEEP = 4.0

local saveNow
local patchAutoOnly
local cleanSelectedMap
local mapToArray
local arrayToMap
local registerFlush

function M.initBridge(bridge)
    if type(bridge) ~= "table" then return end
    saveNow = bridge.saveNow
    patchAutoOnly = bridge.patchAutoOnly
    cleanSelectedMap = bridge.cleanSelectedMap
    mapToArray = bridge.mapToArray
    arrayToMap = bridge.arrayToMap
    registerFlush = bridge.registerFlush
end

local function _ensureBridge()
    if type(saveNow) ~= "function" then
        error("SectionAutoGiftMulti.initBridge belum dipanggil dari tabs_auto.lua")
    end
end

local function getMultiModule()
    return G.AutoGiftMultiModule or G.AutoGiftMulti
        or rawget(_G, "AutoGiftMultiModule") or rawget(_G, "AutoGiftMulti")
end

local function getAutoGiftModule()
    return G.AutoGiftModule or G.AutoGift or rawget(_G, "AutoGiftModule") or rawget(_G, "AutoGift")
end

local function getFriendStealList()
    return G.FriendStealList or rawget(_G, "FriendStealList")
end

local function _cleanSelected(m)
    if type(cleanSelectedMap) == "function" then return cleanSelectedMap(m) end
    local out = {}
    if type(m) ~= "table" then return out end
    if #m > 0 then
        for _, v in ipairs(m) do
            if v ~= nil and tostring(v) ~= "" then out[tostring(v)] = true end
        end
        return out
    end
    for k, v in pairs(m) do
        if v == true or v == 1 or v == "true" then out[tostring(k)] = true end
    end
    return out
end

local function _mapToArray(m)
    if type(mapToArray) == "function" then return mapToArray(m) end
    local out = {}
    for k, v in pairs(type(m) == "table" and m or {}) do
        if v == true then out[#out + 1] = tostring(k) end
    end
    table.sort(out)
    return out
end

local function defaultCategories()
    return { Seeds = true }
end

local function defaultSelected()
    return { Seeds = {} }
end

local function defaultSendTotals()
    return { Seeds = 20 }
end

local function defaultStore()
    return {
        targets = {},
        categories = defaultCategories(),
        selected = defaultSelected(),
        category_mode = "single",
        after_send_mode = "keep",
        -- total/price milik Multi sendiri; send_mode/harvest/auto_unfav tetap dari Mail - Setting
        send_total = 1000,
        send_totals = defaultSendTotals(),
    }
end

local function ensureStore()
    if type(G.__GAG2_AUTO_GIFT_MULTI) ~= "table" then
        G.__GAG2_AUTO_GIFT_MULTI = defaultStore()
    end
    local s = G.__GAG2_AUTO_GIFT_MULTI
    s.targets = type(s.targets) == "table" and s.targets or {}
    s.categories = type(s.categories) == "table" and s.categories or defaultCategories()
    s.selected = type(s.selected) == "table" and s.selected or defaultSelected()
    s.category_mode = (tostring(s.category_mode) == "multi") and "multi" or "single"
    s.after_send_mode = (tostring(s.after_send_mode) == "reset") and "reset" or "keep"
    s.send_total = math.max(1, math.floor(tonumber(s.send_total) or 1000))
    s.send_totals = type(s.send_totals) == "table" and s.send_totals or defaultSendTotals()
    -- mode/harvest/auto_unfav tetap dari Mail - Setting (Once)
    s.send_mode = nil
    s.harvest_price_threshold_pct = nil
    s.harvest_price_calc_mode = nil
    s.auto_unfav = nil
    _G.__GAG2_AUTO_GIFT_MULTI = s
    return s
end

local function readMailOnceSendMode()
    -- 1) UI Mail - Setting (paling up-to-date saat user baru ganti)
    local dd = G.__GAG2_AUTO_GIFT_ONCE_SEND_MODE or rawget(_G, "__GAG2_AUTO_GIFT_ONCE_SEND_MODE")
    if type(dd) == "table" and type(dd.getSelected) == "function" then
        local ok, sel = pcall(dd.getSelected, dd)
        if not ok then ok, sel = pcall(dd.getSelected) end
        if ok and sel ~= nil and tostring(sel) ~= "" then
            local mode = tostring(sel):lower()
            if type(sel) == "table" then
                for k, v in pairs(sel) do
                    if v == true then mode = tostring(k):lower() break end
                end
            end
            if mode == "price" or mode == "total" then
                return mode
            end
        end
    end
    -- 2) Store / MAIN
    local gift = G.__GAG2_AUTO_GIFT or rawget(_G, "__GAG2_AUTO_GIFT")
    if type(gift) ~= "table" then
        local main = G.MAIN or rawget(_G, "MAIN")
        if type(main) == "table" and type(main.auto) == "table" then
            gift = main.auto.gift
        end
    end
    local once = (type(gift) == "table" and type(gift.once) == "table") and gift.once or gift
    if type(once) ~= "table" then return "total" end
    return (tostring(once.send_mode or "total"):lower() == "price") and "price" or "total"
end

local function _parseScaledPriceLocal(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then return nil end
    local sign = 1
    if txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "juta", 1000000 }, { "jt", 1000000 },
        { "ribu", 1000 }, { "rb", 1000 },
        { "b", 1000000000 }, { "m", 1000000 }, { "k", 1000 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then return math.floor(n * mult * sign) end
        end
    end
    local n = tonumber(txt)
    if n then return math.floor(n * sign) end
    return nil
end

local function parseSendTotalPrice(txt)
    local ag = getAutoGiftModule()
    if type(ag) == "table" and type(ag.ParseSendTotalPrice) == "function" then
        local ok, n = pcall(ag.ParseSendTotalPrice, ag, txt)
        if ok and type(n) == "number" then return n end
    end
    local parsed = _parseScaledPriceLocal(txt)
    if parsed ~= nil then return math.max(0, parsed) end
    return math.max(0, math.floor(tonumber(txt) or 0))
end

local function formatSendTotalPrice(n)
    local ag = getAutoGiftModule()
    if type(ag) == "table" and type(ag.FormatSendTotalPrice) == "function" then
        local ok, s = pcall(ag.FormatSendTotalPrice, ag, n)
        if ok and type(s) == "string" then return s end
    end
    n = math.floor(tonumber(n) or 0)
    if n >= 1000000000 then return string.format("%.2fB", n / 1000000000) end
    if n >= 1000000 then return string.format("%.2fM", n / 1000000) end
    if n >= 1000 then return string.format("%.1fK", n / 1000) end
    return tostring(n)
end

local function targetKey(t)
    if type(t) ~= "table" then return "" end
    local uid = math.floor(tonumber(t.user_id) or 0)
    if uid > 0 then return tostring(uid) end
    return tostring(t.username or ""):gsub("^@", "")
end

local function _clampVerifyAttempts(n)
    n = math.floor(tonumber(n) or 0)
    if n < 0 then n = 0 end
    if n > VERIFY_MAX_ATTEMPTS then n = VERIFY_MAX_ATTEMPTS end
    return n
end

local function _normalizeVerifyStatus(uid, status)
    status = tostring(status or ""):lower()
    if uid > 0 then return "ok" end
    if status == "wrong" or status == "ok" or status == "pending" then
        return status
    end
    return "pending"
end

local function normalizeTargetRow(t)
    if type(t) ~= "table" then return nil end
    local uid = math.floor(tonumber(t.user_id) or 0)
    local user = tostring(t.username or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")
    local disp = tostring(t.display or "")
    if uid <= 0 and user == "" then return nil end
    local verifyStatus = _normalizeVerifyStatus(uid, t.verify_status)
    local verifyAttempts = _clampVerifyAttempts(t.verify_attempts)
    -- enabled=false = tetap di list, tapi tidak ikut di-send
    local enabled = (t.enabled ~= false)
    if verifyStatus == "wrong" then
        enabled = false
    elseif uid > 0 then
        verifyStatus = "ok"
    end
    return {
        username = user,
        user_id = uid,
        display = disp,
        enabled = enabled,
        verify_status = verifyStatus,
        verify_attempts = verifyAttempts,
    }
end

local function targetLabelForRow(row, index)
    row = normalizeTargetRow(row) or row
    if type(row) ~= "table" then return tostring(index or "") end
    local key = targetKey(row)
    local name = tostring(row.display ~= "" and row.display or row.username or key)
    -- strip leftover verify markers from display for clean verified labels
    name = name:gsub("%s*⚠.*$", ""):gsub("%s+$", "")
    if name == "" then name = tostring(row.username or key) end
    local label = name
    if row.user_id > 0 and row.username ~= "" then
        label = name .. " (" .. row.username .. ")"
    elseif row.user_id > 0 then
        label = name .. " (" .. tostring(row.user_id) .. ")"
    elseif row.verify_status == "wrong" then
        local attempts = _clampVerifyAttempts(row.verify_attempts)
        label = row.username .. " ⚠ wrong username (" .. tostring(attempts) .. "/" .. tostring(VERIFY_MAX_ATTEMPTS) .. ")"
    elseif row.username ~= "" then
        label = row.username .. " ⚠ belum terverifikasi"
    end
    local n = math.floor(tonumber(index) or 0)
    if n > 0 then
        label = tostring(n) .. ". " .. label
    end
    return label
end

local function activeTargetsFromStore(s)
    s = s or ensureStore()
    local out = {}
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row and row.enabled then
            out[#out + 1] = {
                username = row.username,
                user_id = row.user_id,
                display = row.display,
            }
        end
    end
    return out
end

local function payloadFromStore(s)
    s = ensureStore()
    local selected = {}
    for cat, map in pairs(s.selected) do
        selected[cat] = _mapToArray(_cleanSelected(map))
    end
    local targets = {}
    for _, t in ipairs(s.targets) do
        local row = normalizeTargetRow(t)
        if row then
            targets[#targets + 1] = row
        end
    end
    local send_totals = {}
    for k, v in pairs(type(s.send_totals) == "table" and s.send_totals or {}) do
        send_totals[tostring(k)] = math.max(1, math.floor(tonumber(v) or 20))
    end
    return {
        targets = targets,
        categories = s.categories,
        selected = selected,
        category_mode = s.category_mode,
        after_send_mode = s.after_send_mode,
        send_total = math.max(1, math.floor(tonumber(s.send_total) or 1000)),
        send_totals = send_totals,
    }
end

local function writeToMain()
    local s = ensureStore()
    local payload = payloadFromStore(s)
    if type(patchAutoOnly) == "function" then
        pcall(patchAutoOnly, "giftMulti", payload)
    else
        local main = G.MAIN or rawget(_G, "MAIN")
        if type(main) == "table" then
            main.auto = main.auto or {}
            main.auto.giftMulti = payload
        end
    end
end

local function applyRuntime()
    local mod = getMultiModule()
    local s = ensureStore()
    if type(mod) == "table" and type(mod.ApplyConfig) == "function" then
        pcall(mod.ApplyConfig, mod, {
            -- runtime only gets checked (enabled) recipients
            -- send_mode / harvest / auto_unfav dari Mail - Setting; total/price dari Multi store
            targets = activeTargetsFromStore(s),
            categories = s.categories,
            selected = s.selected,
            category_mode = s.category_mode,
            after_send_mode = s.after_send_mode,
            send_total = s.send_total,
            send_totals = s.send_totals,
        })
    end
end

local function patchStore(opts, after)
    local s = ensureStore()
    if type(opts) ~= "table" then return end
    for k, v in pairs(opts) do
        s[k] = v
    end
    writeToMain()
    applyRuntime()
    if type(after) == "function" then pcall(after) end
    if type(saveNow) == "function" then pcall(saveNow) end
end

local function buildCatDefs()
    local ag = getAutoGiftModule()
    if type(ag) == "table" and type(ag.GetCategoryDefs) == "function" then
        local ok, defs = pcall(ag.GetCategoryDefs, ag)
        if ok and type(defs) == "table" and #defs > 0 then
            local out = {}
            for _, def in ipairs(defs) do
                out[#out + 1] = {
                    key = def.key,
                    label = def.label or def.key,
                    itemLabel = (def.label or def.key) .. " list",
                    placeholder = "Select " .. string.lower(tostring(def.label or def.key)) .. "...",
                }
            end
            return out
        end
    end
    return {
        { key = "Seeds", label = "Seeds", itemLabel = "Seeds list", placeholder = "Select seeds..." },
        { key = "Pets", label = "Pets", itemLabel = "Pets list", placeholder = "Select pets..." },
        { key = GIFT_HARVESTED_FRUITS_CAT, label = "Harvested Fruits", itemLabel = "Fruits list", placeholder = "Select fruits..." },
    }
end

local function firstEnabledCat(cats)
    cats = type(cats) == "table" and cats or {}
    for _, def in ipairs(buildCatDefs()) do
        if cats[def.key] == true then return def.key end
    end
    return nil
end

local function multiUsesPriceMode(cats)
    cats = type(cats) == "table" and cats or ensureStore().categories
    if readMailOnceSendMode() ~= "price" then return false end
    -- Align with AutoGift._onceUsesPriceMode: price if Harvest is enabled (any),
    -- not only when it is the first enabled key (Eggs/EmptyPots sort before Harvest).
    if type(cats) ~= "table" then return false end
    if cats[GIFT_HARVESTED_FRUITS_CAT] == true then return true end
    for key, on in pairs(cats) do
        if on == true then
            local n = tostring(key or ""):lower():gsub("[%s_]+", "")
            if n == "harvestedfruits" or n == "harvestedfruit" then
                return true
            end
        end
    end
    return false
end

local function readMultiSendDisplay(cats)
    local s = ensureStore()
    cats = type(cats) == "table" and cats or s.categories
    if multiUsesPriceMode(cats) then
        return formatSendTotalPrice(s.send_total or 1000), "Send total price (each account)", true
    end
    local catKey = firstEnabledCat(cats)
    local n = 20
    if catKey then
        n = math.max(1, math.floor(tonumber(s.send_totals[catKey]) or 20))
    end
    return tostring(n), "Send total (each account)", false
end

local function writeMultiSendTotal(txt, cats)
    local s = ensureStore()
    cats = type(cats) == "table" and cats or s.categories
    if multiUsesPriceMode(cats) then
        local n = parseSendTotalPrice(txt)
        if n < 1 then return false end
        patchStore({ send_total = math.floor(n) })
    else
        local n = tonumber(txt)
        if n == nil or n < 1 then return false end
        local catKey = firstEnabledCat(cats)
        if not catKey then return false end
        local totals = type(s.send_totals) == "table" and s.send_totals or {}
        totals[catKey] = math.floor(n)
        patchStore({ send_totals = totals })
    end
    return true
end

local function safeDdGetSelected(api)
    if type(api) ~= "table" or type(api.getSelected) ~= "function" then return nil end
    local ok, sel = pcall(api.getSelected, api)
    if ok then return sel end
    ok, sel = pcall(api.getSelected)
    if ok then return sel end
    return nil
end

local function targetInfoFromKey(key, FriendStealList)
    key = tostring(key or "")
    if key == "" then return nil end
    local uid, pendingName = 0, nil
    if type(FriendStealList) == "table" and type(FriendStealList.parseTargetKey) == "function" then
        uid, pendingName = FriendStealList.parseTargetKey(key)
        uid = math.floor(tonumber(uid) or 0)
    else
        uid = math.floor(tonumber(key) or 0)
    end
    local user, disp = "", ""
    if type(FriendStealList) == "table" and type(FriendStealList.displayLabel) == "function" and uid > 0 then
        local label = tostring(FriendStealList.displayLabel(key, {}) or "")
        local parsed = label:match("^(.-)%s+%(")
        disp = parsed or label
        local uname = label:match("@([%w_]+)")
        user = uname or ""
    end
    if uid > 0 then
        return {
            user_id = uid,
            username = user,
            display = disp ~= "" and disp or user,
            enabled = true,
            verify_status = "ok",
            verify_attempts = 0,
        }
    end
    local name = tostring(pendingName or key)
        :gsub("^[Nn]ame:", "")
        :gsub("^@", "")
        :gsub("^%s+", "")
        :gsub("%s+$", "")
    if name == "" then return nil end
    return {
        user_id = 0,
        username = name,
        display = name,
        enabled = true,
        verify_status = "pending",
        verify_attempts = 0,
    }
end

local function selectionKeys(sel)
    local keys = {}
    if type(sel) == "table" then
        if #sel > 0 then
            for _, k in ipairs(sel) do
                k = tostring(k or "")
                if k ~= "" then keys[k] = true end
            end
        else
            for k, v in pairs(sel) do
                if v == true then
                    k = tostring(k or "")
                    if k ~= "" then keys[k] = true end
                end
            end
        end
    elseif sel ~= nil then
        local k = tostring(sel)
        if k ~= "" then keys[k] = true end
    end
    return keys
end

-- Merge dropdown selection into saved pool:
-- checked = enabled, unchecked = stay in list (enabled=false). Never drop on unselect.
local function mergeTargetsFromSelection(sel, FriendStealList)
    local s = ensureStore()
    local checked = selectionKeys(sel)
    local byKey = {}
    local order = {}
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row then
            local key = targetKey(row)
            if key ~= "" and not byKey[key] then
                byKey[key] = row
                order[#order + 1] = key
            end
        end
    end
    for key in pairs(checked) do
        if not byKey[key] then
            local row = targetInfoFromKey(key, FriendStealList)
            if row then
                byKey[key] = row
                order[#order + 1] = key
            end
        end
    end
    local out = {}
    for _, key in ipairs(order) do
        if #out >= MAX_TARGETS then break end
        local row = byKey[key]
        if row then
            row = normalizeTargetRow(row) or row
            if row.verify_status == "wrong" then
                row.enabled = false
            else
                row.enabled = checked[key] == true
            end
            out[#out + 1] = row
        end
    end
    return out
end

local function targetsToSelectedMap(targets)
    local m = {}
    for _, t in ipairs(type(targets) == "table" and targets or {}) do
        local row = normalizeTargetRow(t)
        if row and row.enabled then
            local key = targetKey(row)
            if key ~= "" then m[key] = true end
        end
    end
    return m
end

local function refreshTargetDropdown()
    local api = G.__GAG2_AUTO_GIFT_MULTI_TARGET_DD or rawget(_G, "__GAG2_AUTO_GIFT_MULTI_TARGET_DD")
    if type(api) ~= "table" then return end
    local s = ensureStore()
    if type(api.setSelected) == "function" then
        pcall(api.setSelected, targetsToSelectedMap(s.targets))
    end
    if type(api.refreshItems) == "function" then
        pcall(api.refreshItems, api)
    end
end

local function _isUsernameFormatValid(name)
    name = tostring(name or "")
    if name == "" then return false, "empty" end
    if tonumber(name) and tonumber(name) > 0 and not name:find("%a") then
        return true
    end
    if name:find("%s") or not name:match("^[%w_]+$") then
        return false, "invalid"
    end
    if #name < 3 or #name > 20 then
        return false, "invalid"
    end
    return true
end

local function _isVerifyEligible(row)
    row = normalizeTargetRow(row)
    if not row then return false end
    if row.user_id > 0 then return false end
    if row.verify_status == "wrong" and row.verify_attempts >= VERIFY_MAX_ATTEMPTS then
        return false
    end
    return true
end

local function _commitTargets(nextTargets)
    local normalized = {}
    for _, t in ipairs(type(nextTargets) == "table" and nextTargets or {}) do
        local row = normalizeTargetRow(t)
        if row then
            normalized[#normalized + 1] = row
        end
    end
    patchStore({ targets = normalized }, function()
        refreshTargetDropdown()
    end)
end

local function _updateTargetByKey(key, mutator)
    key = tostring(key or "")
    if key == "" or type(mutator) ~= "function" then return false end
    local s = ensureStore()
    local nextTargets = {}
    local changed = false
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row then
            if targetKey(row) == key then
                mutator(row)
                row = normalizeTargetRow(row) or row
                changed = true
            end
            nextTargets[#nextTargets + 1] = row
        end
    end
    if changed then
        _commitTargets(nextTargets)
    end
    return changed
end

-- Send-time / UI: mark username wrong + disable; counts toward 5 background retries.
function M.markTargetLookupFail(usernameOrKey)
    local key = tostring(usernameOrKey or ""):gsub("^@", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if key == "" then return false end
    local s = ensureStore()
    local matchedKey = nil
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row then
            local tk = targetKey(row)
            if tk == key or string.lower(row.username) == string.lower(key) then
                matchedKey = tk
                break
            end
        end
    end
    if not matchedKey then return false end
    return _updateTargetByKey(matchedKey, function(row)
        if row.user_id > 0 then return end
        local attempts = _clampVerifyAttempts(row.verify_attempts) + 1
        row.verify_attempts = attempts
        row.verify_status = "wrong"
        row.enabled = false
        row.display = row.username
    end)
end

function M.markTargetVerified(usernameOrKey, userId, displayName)
    local key = tostring(usernameOrKey or ""):gsub("^@", ""):gsub("^%s+", ""):gsub("%s+$", "")
    local uid = math.floor(tonumber(userId) or 0)
    if key == "" or uid <= 0 then return false end
    local s = ensureStore()
    local matchedKey = nil
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row then
            local tk = targetKey(row)
            if tk == key or string.lower(row.username) == string.lower(key) then
                matchedKey = tk
                break
            end
        end
    end
    if not matchedKey then return false end
    return _updateTargetByKey(matchedKey, function(row)
        row.user_id = uid
        local uname = tostring(displayName or row.username or "")
            :gsub("%s*⚠.*$", "")
            :gsub("^%s+", "")
            :gsub("%s+$", "")
        if uname ~= "" and not tonumber(uname) then
            row.username = uname
        end
        row.display = (uname ~= "" and uname) or row.username
        row.verify_status = "ok"
        row.verify_attempts = 0
        row.enabled = true
    end)
end

local function _startBackgroundVerifyLoop()
    if G.__GAG2_GIFT_MULTI_VERIFY_LOOP == true then return end
    G.__GAG2_GIFT_MULTI_VERIFY_LOOP = true
    _G.__GAG2_GIFT_MULTI_VERIFY_LOOP = true

    task.spawn(function()
        local lastResolveAt = 0
        while G.__GAG2_GIFT_MULTI_VERIFY_LOOP == true do
            local FriendStealList = getFriendStealList()
            if type(FriendStealList) ~= "table"
                or type(FriendStealList.resolveUsernameDetailed) ~= "function" then
                task.wait(VERIFY_IDLE_SLEEP)
                continue
            end

            local s = ensureStore()
            local pick = nil
            local pickKey = nil
            for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
                local row = normalizeTargetRow(t)
                if row and _isVerifyEligible(row) then
                    pick = row
                    pickKey = targetKey(row)
                    break
                end
            end

            if not pick or not pickKey then
                task.wait(VERIFY_IDLE_SLEEP)
                continue
            end

            local gap = VERIFY_RESOLVE_GAP - (os.clock() - lastResolveAt)
            if gap > 0 then
                task.wait(gap)
            end

            -- Re-read: target may have changed while waiting
            local current = nil
            s = ensureStore()
            for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
                local row = normalizeTargetRow(t)
                if row and targetKey(row) == pickKey then
                    current = row
                    break
                end
            end
            if not current or not _isVerifyEligible(current) then
                task.wait(0.2)
                continue
            end

            local okFmt = _isUsernameFormatValid(current.username)
            if not okFmt then
                _updateTargetByKey(pickKey, function(row)
                    row.verify_status = "wrong"
                    row.verify_attempts = VERIFY_MAX_ATTEMPTS
                    row.enabled = false
                    row.display = row.username
                end)
                lastResolveAt = os.clock()
                continue
            end

            local force = current.verify_attempts > 0 or current.verify_status == "wrong"
            lastResolveAt = os.clock()
            local okCall, userIdOrNil, nameOrErr = pcall(
                FriendStealList.resolveUsernameDetailed,
                current.username,
                force
            )
            if not okCall then
                task.wait(VERIFY_RESOLVE_GAP)
                continue
            end

            local uid = math.floor(tonumber(userIdOrNil) or 0)
            local err = tostring(nameOrErr or "")
            if uid > 0 then
                local disp = err
                if type(nameOrErr) ~= "string" or nameOrErr == "" or err:find("not_found", 1, true) then
                    disp = current.username
                end
                M.markTargetVerified(pickKey, uid, disp)
            else
                -- Soft = infra / Redfinger flaky (jangan naikkan wrong-username counter)
                local soft = (err == "rate_limited")
                    or (err == "pending")
                    or (err == "no_http")
                    or (err == "async_not_found_unconfirmed")
                    or err:find("rate", 1, true)
                    or err:find("http", 1, true)
                    or err:find("HTTP", 1, true)
                    or err:find("throttle", 1, true)
                    or err:find("timeout", 1, true)
                    or err:find("busy", 1, true)
                    or err:find("bad_json", 1, true)
                    or err:find("bad_response", 1, true)
                    or err:find("async_error", 1, true)
                    or err:find("unconfirmed", 1, true)
                if soft then
                    task.wait(VERIFY_RESOLVE_GAP)
                else
                    -- hard fail: not_found / invalid / empty (HTTP confirmed empty_data)
                    _updateTargetByKey(pickKey, function(row)
                        if row.user_id > 0 then return end
                        row.verify_attempts = _clampVerifyAttempts(row.verify_attempts) + 1
                        row.verify_status = "wrong"
                        row.enabled = false
                        row.display = row.username
                    end)
                end
            end
        end
    end)
end

local function removeTargetFromPool(key)
    key = tostring(key or "")
    local s = ensureStore()
    local out = {}
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row and targetKey(row) ~= key then
            out[#out + 1] = row
        end
    end
    return out
end

-- Paste: "a,b,c" / "a;b;c" / "a:b:c" / "a/b/c" / "a-b-c" / newline / spasi
local function parseBulkUsernames(txt)
    txt = tostring(txt or "")
        :gsub("[\r\n\t]+", ",")
        :gsub("[%s]*[,/;:|%-]+[%s]*", ",")
        :gsub("%s+", ",")
    local out, seen = {}, {}
    for part in string.gmatch(txt, "[^,]+") do
        local name = tostring(part)
            :gsub("^%s+", "")
            :gsub("%s+$", "")
            :gsub("^@", "")
        if name ~= "" then
            local low = string.lower(name)
            if not seen[low] then
                seen[low] = true
                out[#out + 1] = name
            end
        end
    end
    return out
end

local function mergeBulkUsernamesIntoTargets(names)
    local s = ensureStore()
    local byKey, order, seenUser = {}, {}, {}
    for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
        local row = normalizeTargetRow(t)
        if row then
            local key = targetKey(row)
            if key ~= "" and not byKey[key] then
                byKey[key] = row
                order[#order + 1] = key
                if row.username ~= "" then
                    seenUser[string.lower(row.username)] = key
                end
            end
        end
    end
    local added, skipped = 0, 0
    for _, name in ipairs(type(names) == "table" and names or {}) do
        local low = string.lower(tostring(name or ""))
        if low == "" then
            -- skip
        elseif seenUser[low] then
            local key = seenUser[low]
            if byKey[key] then byKey[key].enabled = true end
            skipped += 1
        elseif #order >= MAX_TARGETS then
            skipped += 1
        else
            local row = {
                user_id = 0,
                username = tostring(name),
                display = tostring(name),
                enabled = true,
                verify_status = "pending",
                verify_attempts = 0,
            }
            local key = targetKey(row)
            byKey[key] = row
            order[#order + 1] = key
            seenUser[low] = key
            added += 1
        end
    end
    local out = {}
    for _, key in ipairs(order) do
        if #out >= MAX_TARGETS then break end
        if byKey[key] then out[#out + 1] = byKey[key] end
    end
    return out, added, skipped
end

function M.initStore()
    ensureStore()
    local main = G.MAIN or rawget(_G, "MAIN")
    if type(main) == "table" and type(main.auto) == "table" and type(main.auto.giftMulti) == "table" then
        local src = main.auto.giftMulti
        local s = ensureStore()
        if type(src.targets) == "table" then
            local normalized = {}
            for _, t in ipairs(src.targets) do
                local row = normalizeTargetRow(t)
                if row then normalized[#normalized + 1] = row end
            end
            s.targets = normalized
        end
        if type(src.categories) == "table" then s.categories = src.categories end
        if type(src.selected) == "table" then
            s.selected = {}
            for cat, map in pairs(src.selected) do
                s.selected[cat] = _cleanSelected(map)
            end
        end
        if src.category_mode ~= nil then s.category_mode = src.category_mode end
        if src.after_send_mode ~= nil then s.after_send_mode = src.after_send_mode end
        if src.send_total ~= nil then s.send_total = src.send_total end
        if type(src.send_totals) == "table" then s.send_totals = src.send_totals end
    end
    ensureStore()
    applyRuntime()
    G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL = function(usernameOrKey)
        return M.markTargetLookupFail(usernameOrKey)
    end
    _G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL = G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL
    G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK = function(usernameOrKey, userId, displayName)
        return M.markTargetVerified(usernameOrKey, userId, displayName)
    end
    _G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK = G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK
    _startBackgroundVerifyLoop()
end

function M.RegisterSubTab(ui)
    if type(ui) ~= "table" then return end
    _ensureBridge()
    ensureStore()

    if type(registerFlush) == "function" then
        pcall(registerFlush, "giftMulti", function()
            writeToMain()
        end)
    end

    local FriendStealList = getFriendStealList()
    local store = ensureStore()
    do
        local normalized = {}
        for _, t in ipairs(type(store.targets) == "table" and store.targets or {}) do
            local row = normalizeTargetRow(t)
            if row then normalized[#normalized + 1] = row end
        end
        store.targets = normalized
    end
    local body = ui:CreateSection("Mail Multi", false)

    ----------------------------------------------------------------
    -- Targets
    ----------------------------------------------------------------
    local targetDdApi
    if type(FriendStealList) == "table" then
        ui:CreateRowLabel(
            body,
            "Contoh: a,b,c  ·  Pemisah: , ; : / - | spasi enter",
            nil,
            nil,
            "muted"
        )

        local bulkPasteRow, bulkPasteApi, bulkPasteCommit = ui:CreateRowInput(
            body,
            "Paste banyak username",
            "",
            function(_) end,
            false -- jangan clear saat fokus (biar paste panjang aman)
        )

        local function readBulkPasteText()
            if type(bulkPasteCommit) == "function" then
                pcall(bulkPasteCommit)
            end
            if bulkPasteRow then
                local box = bulkPasteRow:FindFirstChild("Input")
                if box and box:IsA("TextBox") then
                    local live = tostring(box.Text or "")
                    if live ~= "" then return live end
                end
            end
            if type(bulkPasteApi) == "function" then
                return tostring(bulkPasteApi() or "")
            end
            return ""
        end

        local function applyBulkPaste()
            local names = parseBulkUsernames(readBulkPasteText())
            if #names == 0 then return end
            local nextTargets, added = mergeBulkUsernamesIntoTargets(names)
            patchStore({ targets = nextTargets }, function()
                local api = G.__GAG2_AUTO_GIFT_MULTI_TARGET_DD or rawget(_G, "__GAG2_AUTO_GIFT_MULTI_TARGET_DD")
                if type(api) == "table" then
                    if type(api.setSelected) == "function" then
                        pcall(api.setSelected, targetsToSelectedMap(nextTargets))
                    end
                    if type(api.refreshItems) == "function" then
                        pcall(api.refreshItems, api)
                    end
                end
                if added > 0 and type(bulkPasteApi) == "function" then
                    pcall(bulkPasteApi, "")
                end
            end)
        end

        -- momentary: toggle auto mati setelah pulse (sama pola APPLY di collect rules)
        local _, _, bulkPasteToggleApi = ui:CreateRowToggle(
            body,
            "Add pasted targets",
            false,
            function(isOn)
                if isOn ~= true then return end
                applyBulkPaste()
                if type(bulkPasteToggleApi) == "table" and type(bulkPasteToggleApi.set) == "function" then
                    task.defer(function()
                        pcall(bulkPasteToggleApi.set, false, true)
                    end)
                end
            end,
            nil,
            nil,
            0.25
        )

        local function savedTargetItems()
            local s = ensureStore()
            local items = {}
            local idx = 0
            for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
                local row = normalizeTargetRow(t)
                if row then
                    local key = targetKey(row)
                    if key ~= "" then
                        idx += 1
                        items[#items + 1] = {
                            key = key,
                            name = targetLabelForRow(row, idx),
                            order = idx,
                        }
                    end
                end
            end
            return items
        end

        local function labelForSavedKey(key)
            key = tostring(key or "")
            local s = ensureStore()
            local idx = 0
            for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
                local row = normalizeTargetRow(t)
                if row then
                    local k = targetKey(row)
                    if k ~= "" then
                        idx += 1
                        if k == key then
                            return targetLabelForRow(row, idx)
                        end
                    end
                end
            end
            return nil
        end

        local function applyTargetsFromSelection(sel)
            patchStore({ targets = mergeTargetsFromSelection(sel, FriendStealList) })
        end

        local _, ddApi = ui:CreateRowDropdown(body, {
            label = "Targets (max " .. tostring(MAX_TARGETS) .. ")",
            panelTitle = "Select recipients",
            placeholder = "Search / pick usernames...",
            mode = "multi",
            emptyUntilSearch = true,
            preserveItemOrder = true,
            maxResults = 20,
            searchPlaceholder = "Search Roblox username...",
            initial = targetsToSelectedMap(store.targets),
            -- Pool tersimpan selalu tampil; unselect = nonaktif (abu), bukan hilang.
            getItems = function()
                return savedTargetItems()
            end,
            searchGetItems = function(query)
                local q = tostring(query or ""):gsub("^%s+", ""):gsub("%s+$", "")
                local out = {}
                local seen = {}
                for _, it in ipairs(savedTargetItems()) do
                    local key = tostring(it.key or "")
                    if key ~= "" then
                        seen[key] = true
                        out[#out + 1] = it
                    end
                end
                if q ~= "" and type(FriendStealList.searchUsers) == "function" then
                    local ok, res = pcall(FriendStealList.searchUsers, q, 10)
                    if ok and type(res) == "table" then
                        for _, it in ipairs(res) do
                            local key = tostring(it.key or it.userId or "")
                            if key == "" or seen[key] then
                                -- skip
                            else
                                local dup = false
                                if type(FriendStealList.parseTargetKey) == "function" then
                                    local uid, pname = FriendStealList.parseTargetKey(key)
                                    if pname and seen[pname] then dup = true end
                                    if uid and uid > 0 and seen[tostring(uid)] then dup = true end
                                end
                                if not dup then
                                    seen[key] = true
                                    out[#out + 1] = it
                                end
                            end
                        end
                        out._searchMessage = res._searchMessage or res.searchMessage
                    end
                    if (out._searchMessage == nil or out._searchMessage == "")
                        and type(FriendStealList.getLastSearchMessage) == "function" then
                        local msg = FriendStealList.getLastSearchMessage()
                        if type(msg) == "string" and msg ~= "" then
                            out._searchMessage = msg
                        end
                    end
                end
                return out
            end,
            labelForKey = function(key)
                local saved = labelForSavedKey(key)
                if saved then return saved end
                if type(FriendStealList.displayLabel) == "function" then
                    return FriendStealList.displayLabel(key, {})
                end
                return tostring(key)
            end,
            -- Tombol X = hapus permanen dari saved list
            onDeleteItem = function(key)
                local api = G.__GAG2_AUTO_GIFT_MULTI_TARGET_DD or rawget(_G, "__GAG2_AUTO_GIFT_MULTI_TARGET_DD")
                local nextTargets = removeTargetFromPool(key)
                patchStore({ targets = nextTargets })
                if type(api) == "table" and type(api.setSelected) == "function" then
                    pcall(api.setSelected, targetsToSelectedMap(nextTargets))
                end
                if type(api) == "table" and type(api.refreshItems) == "function" then
                    pcall(api.refreshItems, api)
                end
            end,
            onChanged = function(_, sel)
                applyTargetsFromSelection(sel)
            end,
        })
        targetDdApi = ddApi
        G.__GAG2_AUTO_GIFT_MULTI_TARGET_DD = ddApi
        _G.__GAG2_AUTO_GIFT_MULTI_TARGET_DD = ddApi

        if type(ui.CreateRowButton) == "function" then
            ui:CreateRowButton(body, "Clear all targets", function()
                if type(targetDdApi) == "table" and type(targetDdApi.setSelected) == "function" then
                    pcall(targetDdApi.setSelected, {})
                end
                patchStore({ targets = {} })
                if type(targetDdApi) == "table" and type(targetDdApi.refreshItems) == "function" then
                    pcall(targetDdApi.refreshItems, targetDdApi)
                end
            end)
        end
    else
        ui:CreateRowLabel(body, "FriendStealList missing — upload FriendStealList.lua", nil, nil, "muted")
    end

    ----------------------------------------------------------------
    -- Status (2 baris)
    ----------------------------------------------------------------
    local _, statusLabel = ui:CreateRowLabel(body, "Status: Ready", nil, nil, "info")
    local _, detailLabel = ui:CreateRowLabel(body, "Detail: -", nil, nil, "muted")

    local function refreshStatus()
        local mod = getMultiModule()
        local line1, line2 = "Ready", "-"
        if type(mod) == "table" and type(mod.GetProgress) == "function" then
            local ok, p = pcall(mod.GetProgress, mod)
            if ok and type(p) == "table" then
                local status = tostring(p.status or "Ready")
                local process = tostring(p.process or "-")
                local queue = tostring(p.queue or "-")
                local note = tostring(p.note or "")
                if status == "Running" or process ~= "-" then
                    line1 = status .. " · " .. process
                else
                    line1 = status
                end
                if note ~= "" then
                    line2 = queue .. " · " .. note
                else
                    line2 = queue
                end
            end
        else
            line1 = tostring(G.AUTO_GIFT_MULTI_STATUS or _G.AUTO_GIFT_MULTI_STATUS or "Ready")
            local s = ensureStore()
            line2 = tostring(#activeTargetsFromStore(s)) .. " active · " .. tostring(#(s.targets or {})) .. " saved"
        end
        if line2 == "-" or line2 == "No targets" then
            local s = ensureStore()
            local activeN = #activeTargetsFromStore(s)
            local savedN = #(s.targets or {})
            if savedN > 0 then
                line2 = tostring(activeN) .. " active · " .. tostring(savedN) .. " saved"
            end
        end
        if #line1 > 52 then line1 = line1:sub(1, 51) .. "…" end
        if #line2 > 52 then line2 = line2:sub(1, 51) .. "…" end
        if statusLabel then statusLabel.Text = "Status: " .. line1 end
        if detailLabel then detailLabel.Text = "Detail: " .. line2 end
    end
    G.__GAG2_REFRESH_GIFT_MULTI_STATUS = refreshStatus
    _G.__GAG2_REFRESH_GIFT_MULTI_STATUS = refreshStatus
    task.spawn(function()
        while statusLabel and statusLabel.Parent do
            refreshStatus()
            task.wait(0.75)
        end
    end)

    ----------------------------------------------------------------
    -- Category mode + categories + item lists
    ----------------------------------------------------------------
    local itemDropdowns = {}
    local syncing = false
    local catDd

    local function ensureItemDropdown(catKey)
        catKey = tostring(catKey or "")
        if catKey == "" then return nil end
        local existing = itemDropdowns[catKey]
        if existing and existing.dd then return existing end
        local def
        for _, d in ipairs(buildCatDefs()) do
            if d.key == catKey then def = d break end
        end
        if not def then return nil end
        local row, dd = ui:CreateRowDropdown(body, {
            label = def.itemLabel,
            placeholder = def.placeholder,
            mode = "multi",
            deferItemLoad = true,
            getItems = function()
                local ag = getAutoGiftModule()
                if type(ag) ~= "table" or type(ag.BuildInventoryItems) ~= "function" then
                    return {}
                end
                local ok, items = pcall(ag.BuildInventoryItems, ag, catKey)
                if ok and type(items) == "table" then return items end
                return {}
            end,
            initial = _cleanSelected(ensureStore().selected[catKey]),
            onChanged = function(_, sel)
                if syncing then return end
                local s = ensureStore()
                s.selected = type(s.selected) == "table" and s.selected or {}
                s.selected[catKey] = _cleanSelected(sel)
                patchStore({ selected = s.selected })
            end,
        })
        row.Visible = false
        itemDropdowns[catKey] = { row = row, dd = dd }
        G["__GAG2_AUTO_GIFT_MULTI_DD_" .. catKey] = dd
        _G["__GAG2_AUTO_GIFT_MULTI_DD_" .. catKey] = dd
        return itemDropdowns[catKey]
    end

    local function applyCategoryVisibility(cats)
        cats = type(cats) == "table" and cats or {}
        for _, def in ipairs(buildCatDefs()) do
            local showList = cats[def.key] == true
            if showList then
                local entry = ensureItemDropdown(def.key)
                if entry and entry.row then
                    entry.row.Visible = true
                end
            else
                local entry = itemDropdowns[def.key]
                if entry and entry.row then
                    entry.row.Visible = false
                end
            end
        end
        local refreshSend = G.__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW or rawget(_G, "__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW")
        if type(refreshSend) == "function" then
            pcall(refreshSend, cats)
        end
    end

    local _, catModeDd = ui:CreateRowDropdown(body, {
        label = "Category mode",
        placeholder = "Single",
        mode = "single",
        getItems = function()
            return {
                { key = "single", name = "Single" },
                { key = "multi", name = "Multi" },
            }
        end,
        initial = store.category_mode == "multi" and "multi" or "single",
        onChanged = function(_, key)
            if syncing then return end
            local mode = (key == "multi") and "multi" or "single"
            patchStore({ category_mode = mode }, function()
                if type(catDd) == "table" and type(catDd.setMode) == "function" then
                    pcall(catDd.setMode, mode)
                end
            end)
        end,
    })
    G.__GAG2_AUTO_GIFT_MULTI_CATEGORY_MODE = catModeDd
    _G.__GAG2_AUTO_GIFT_MULTI_CATEGORY_MODE = catModeDd

    do
        local catItems = {}
        for _, def in ipairs(buildCatDefs()) do
            catItems[#catItems + 1] = { key = def.key, name = def.label }
        end
        local initCats = ensureStore().categories
        local initMode = ensureStore().category_mode
        local initial
        if initMode == "multi" then
            initial = {}
            for k, v in pairs(initCats) do if v == true then initial[k] = true end end
        else
            initial = firstEnabledCat(initCats) or "Seeds"
        end
        local row, dd = ui:CreateRowDropdown(body, {
            label = "Category",
            placeholder = "Select category...",
            mode = initMode == "multi" and "multi" or "single",
            getItems = function() return catItems end,
            initial = initial,
            onChanged = function(ddMode, sel)
                if syncing then return end
                local cats = {}
                for _, def in ipairs(buildCatDefs()) do cats[def.key] = false end
                ddMode = tostring(ddMode or ensureStore().category_mode or "single")
                if ddMode == "single" then
                    local key = sel
                    if type(key) == "table" then
                        for k, v in pairs(key) do
                            if v == true then key = k break end
                        end
                    end
                    if key ~= nil and tostring(key) ~= "" then
                        cats[tostring(key)] = true
                    end
                elseif type(sel) == "table" then
                    for k, v in pairs(sel) do
                        if v == true then
                            cats[tostring(k)] = true
                        elseif type(v) == "string" and tostring(k):match("^%d+$") then
                            -- array-style { "HarvestedFruits", ... }
                            cats[tostring(v)] = true
                        end
                    end
                elseif sel ~= nil and tostring(sel) ~= "" then
                    cats[tostring(sel)] = true
                end
                patchStore({ categories = cats }, function()
                    applyCategoryVisibility(cats)
                    local refreshSend = G.__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW
                        or rawget(_G, "__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW")
                    if type(refreshSend) == "function" then
                        pcall(refreshSend, cats)
                    end
                end)
            end,
        })
        catDd = dd
        G.__GAG2_AUTO_GIFT_MULTI_CAT = dd
        _G.__GAG2_AUTO_GIFT_MULTI_CAT = dd
    end

    -- Pre-create item lists sebelum Send total / After send / Send multi
    for _, def in ipairs(buildCatDefs()) do
        ensureItemDropdown(def.key)
    end
    applyCategoryVisibility(ensureStore().categories)

    ----------------------------------------------------------------
    -- Send total / Send total price (shared Mail Once config; label ikut Mail - Setting)
    ----------------------------------------------------------------
    local multiSendRefreshing = false
    local multiSendTotalRow, multiSendTotalSetFn
    local initDisplay, initLabel = readMultiSendDisplay(ensureStore().categories)
    multiSendTotalRow, multiSendTotalSetFn = ui:CreateRowInput(
        body,
        initLabel,
        initDisplay,
        function(txt)
            if syncing or multiSendRefreshing then return end
            writeMultiSendTotal(txt, ensureStore().categories)
        end
    )
    local multiSendTotalLabel = multiSendTotalRow and multiSendTotalRow:FindFirstChild("Label")

    local function refreshMultiSendTotalRow(cats)
        if multiSendRefreshing then return end
        multiSendRefreshing = true
        cats = type(cats) == "table" and cats or ensureStore().categories
        local display, label = readMultiSendDisplay(cats)
        if multiSendTotalLabel then
            multiSendTotalLabel.Text = label
        end
        if type(multiSendTotalSetFn) == "function" then
            pcall(multiSendTotalSetFn, display)
        end
        multiSendRefreshing = false
    end
    G.__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW = refreshMultiSendTotalRow
    _G.__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW = refreshMultiSendTotalRow
    G.__GAG2_REFRESH_MULTI_CATEGORY_LISTS = function()
        applyCategoryVisibility(ensureStore().categories)
    end
    _G.__GAG2_REFRESH_MULTI_CATEGORY_LISTS = G.__GAG2_REFRESH_MULTI_CATEGORY_LISTS

    local _, afterDd = ui:CreateRowDropdown(body, {
        label = "After send",
        placeholder = "Keep",
        mode = "single",
        getItems = function()
            return {
                { key = "keep", name = "Keep" },
                { key = "reset", name = "Reset" },
            }
        end,
        initial = store.after_send_mode == "reset" and "reset" or "keep",
        onChanged = function(_, key)
            if syncing then return end
            patchStore({ after_send_mode = (key == "reset") and "reset" or "keep" })
        end,
    })
    G.__GAG2_AUTO_GIFT_MULTI_AFTER_SEND_MODE = afterDd
    _G.__GAG2_AUTO_GIFT_MULTI_AFTER_SEND_MODE = afterDd

    ----------------------------------------------------------------
    -- Send toggle
    ----------------------------------------------------------------
    local sendApi
    local function turnOffSendToggle()
        if type(sendApi) == "table" and type(sendApi.set) == "function" then
            pcall(sendApi.set, false, true)
        end
        refreshStatus()
    end

    _, _, sendApi = ui:CreateRowToggle(body, "Send multi", false, function(isOn)
        local mod = getMultiModule()
        if isOn == true then
            if type(mod) ~= "table" or type(mod.Start) ~= "function" then
                turnOffSendToggle()
                return
            end
            applyRuntime()
            local okCall, ok = pcall(mod.Start, mod)
            if okCall ~= true or ok ~= true then
                turnOffSendToggle()
                return
            end
            refreshStatus()
        else
            if type(mod) == "table" and type(mod.Stop) == "function" then
                pcall(mod.Stop, mod)
            end
            refreshStatus()
        end
    end)
    G.__GAG2_AUTO_GIFT_MULTI_SEND_API = sendApi
    _G.__GAG2_AUTO_GIFT_MULTI_SEND_API = sendApi

    -- Dipanggil module saat selesai / gagal / kurang / error → langsung matikan toggle
    G.__GAG2_GIFT_MULTI_JOB_DONE = function()
        turnOffSendToggle()
    end
    _G.__GAG2_GIFT_MULTI_JOB_DONE = G.__GAG2_GIFT_MULTI_JOB_DONE

    local function resetMultiUi()
        local s = ensureStore()
        local keepAfter = s.after_send_mode
        local keepCats = s.categories
        local keepMode = s.category_mode
        local keepSendTotal = s.send_total
        local keepSendTotals = s.send_totals
        -- Hapus user yang sudah completed (done). Unselect saja tidak cukup:
        -- pool dropdown "Never drop on unselect" + tanpa refreshItems.
        local doneKeys = {}
        local mod = getMultiModule()
        if type(mod) == "table" and type(mod.GetUserStatuses) == "function" then
            local okRows, rows = pcall(mod.GetUserStatuses, mod)
            if okRows and type(rows) == "table" then
                for _, u in ipairs(rows) do
                    if tostring(u.status or "") == "done" or u.sent_ok == true then
                        local uid = math.floor(tonumber(u.user_id) or 0)
                        if uid > 0 then doneKeys[tostring(uid)] = true end
                        local name = tostring(u.username or ""):gsub("^@", "")
                        if name ~= "" then
                            doneKeys[name] = true
                            doneKeys[string.lower(name)] = true
                        end
                    end
                end
            end
        end
        local kept = {}
        if next(doneKeys) then
            for _, t in ipairs(type(s.targets) == "table" and s.targets or {}) do
                local row = normalizeTargetRow(t)
                if not row then continue end
                local key = targetKey(row)
                local uname = tostring(row.username or "")
                if doneKeys[key] or doneKeys[uname] or doneKeys[string.lower(uname)] then
                    continue
                end
                kept[#kept + 1] = row
            end
        else
            kept = {}
        end
        s.targets = kept
        s.after_send_mode = keepAfter
        s.categories = keepCats
        s.category_mode = keepMode
        s.send_total = keepSendTotal
        s.send_totals = keepSendTotals
        writeToMain()
        applyRuntime()
        if type(mod) == "table" and type(mod.PruneCompletedUsers) == "function" then
            pcall(mod.PruneCompletedUsers, mod)
        end
        refreshTargetDropdown()
        refreshStatus()
        if type(saveNow) == "function" then pcall(saveNow) end
    end
    G.__GAG2_RESET_GIFT_MULTI = resetMultiUi
    _G.__GAG2_RESET_GIFT_MULTI = resetMultiUi

    applyRuntime()
    refreshStatus()
    -- Pastikan label Send total/price sinkron setelah semua row + refresh hook siap
    if type(refreshMultiSendTotalRow) == "function" then
        pcall(refreshMultiSendTotalRow, ensureStore().categories)
    end
    _startBackgroundVerifyLoop()
    G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL = function(usernameOrKey)
        return M.markTargetLookupFail(usernameOrKey)
    end
    _G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL = G.__GAG2_ON_GIFT_MULTI_LOOKUP_FAIL
    G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK = function(usernameOrKey, userId, displayName)
        return M.markTargetVerified(usernameOrKey, userId, displayName)
    end
    _G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK = G.__GAG2_ON_GIFT_MULTI_LOOKUP_OK
end

function M.applyUiDefaults(giftMulti, setToggleApi, setInputApi)
    if type(giftMulti) ~= "table" then return end
    local s = ensureStore()
    if type(giftMulti.targets) == "table" then
        local normalized = {}
        for _, t in ipairs(giftMulti.targets) do
            local row = normalizeTargetRow(t)
            if row then normalized[#normalized + 1] = row end
        end
        s.targets = normalized
    end
    if type(giftMulti.categories) == "table" then s.categories = giftMulti.categories end
    if type(giftMulti.selected) == "table" then
        s.selected = {}
        for cat, map in pairs(giftMulti.selected) do
            s.selected[cat] = _cleanSelected(map)
        end
    end
    if giftMulti.category_mode ~= nil then s.category_mode = giftMulti.category_mode end
    if giftMulti.after_send_mode ~= nil then s.after_send_mode = giftMulti.after_send_mode end
    if giftMulti.send_total ~= nil then s.send_total = giftMulti.send_total end
    if type(giftMulti.send_totals) == "table" then s.send_totals = giftMulti.send_totals end
    setToggleApi("__GAG2_AUTO_GIFT_MULTI_SEND_API", false)
    local multiRefresh = G.__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW or rawget(_G, "__GAG2_REFRESH_MULTI_SEND_TOTAL_ROW")
    if type(multiRefresh) == "function" then pcall(multiRefresh) end
    local dd = G.__GAG2_AUTO_GIFT_MULTI_TARGET_DD or rawget(_G, "__GAG2_AUTO_GIFT_MULTI_TARGET_DD")
    if type(dd) == "table" and type(dd.setSelected) == "function" then
        pcall(dd.setSelected, targetsToSelectedMap(s.targets))
    end
    applyRuntime()
end

G.SectionAutoGiftMulti = M
_G.SectionAutoGiftMulti = M

return M
 end,       required = false },
    { key = "AutoDrop",                name = "Auto Drop",               factory = function() -- AutoDrop — drop items via Networking.DroppedItem.RequestDrop

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G

local M, H = {}, {}

local RequestDrop, DropBackpackGetLayout, DropBackpackPromoteFruit
local FruitProxyUtil, bagCache, bagCacheAt = nil, nil, 0
local dropBusy, dropCancel = false, false
local teleWasOn, dropTelePaused, dropNearTargetActive = false, false, false

local stats = { lastStatus = "Ready", dropped = 0, goal = 0 }
local cfg = {
    category = "Seeds", selected = {}, drop_total = 1, drop_delay_sec = 0.08,
    target_user_id = 0, target_name = "", teleport_to_target = true,
}

local DROP_NEAR_DIST = 15
local TP_STAND_DIST = 6
local TP_Y_OFFSET = 0.5
local AFTER_TP_SEC = 0.04
local TP_MAX_ATTEMPTS = 8
local TP_STICK_ATTEMPTS = 3
local TP_RETRY_WAIT = 0.06

-- Dump DroppedItemController: RequestDrop:Fire(cat, id) dari tool equipped.
-- Harvest fruit: DroppedBy sering replicate 1–2 frame setelah ChildAdded, jadi confirm harus longgar.
local CONFIRM_MIN = 0.02
local CONFIRM_MAX = 0.22
local HARVEST_CONFIRM = 0.7
local GENERIC_CONFIRM = 0.45
local PROMOTE_WAIT = 1.2
local HARVEST_EQUIP_WAIT = 0.5
local EQUIP_SETTLE = 0
local BAG_CACHE_SEC = 0.2
local FAIL_MAX = 20
local RETRY_MAX = 3
local SKIP_MAX = 12

-- Game soft-cap: max own drops on ground before more RequestDrop are rejected.
local MAX_PENDING_DROPS = 10
local PENDING_POLL_SEC = 0.12
-- Server toast "still dropping your last item" jika Fire lagi sebelum drop sebelumnya selesai spawn.
-- Delay UI 0 tidak boleh menembak lebih cepat dari ini.
local MIN_REQUEST_GAP = 0.5
local DROP_LAND_EXTRA = 0.28
local lastDropFireAt = 0
local lastDropPendingBefore = 0

local ownGroundModels, groundWatchFolder, groundAddConn, groundRemConn = {}, nil, nil, nil

local GIFT_ATTR = {
    SeedTool = "Seeds", Sprinkler = "Sprinklers", Rake = "Rakes", WateringCan = "WateringCans",
    Shovel = "Shovels", Trowel = "Trowels", Crowbar = "Crowbars", Build = "Builds",
    Mushroom = "Mushrooms", Gnome = "Gnomes", Raccoon = "Raccoons", Crate = "Crates",
    Teleporter = "Teleporters", PlayerMagnet = "Magnets", FruitMagnet = "FruitMagnets",
    PetTeleporter = "PetTeleporters", PetLure = "PetLures", SeedPack = "SeedPacks", Egg = "Eggs",
    Wheelbarrow = "Wheelbarrows", Ladder = "Ladders", FreezeRay = "FreezeRays", PowerHose = "PowerHoses",
    Sign = "Signs", EmptyPot = "EmptyPots", Flashbang = "Flashbangs", Bird = "Birds", Pet = "Pets",
}

local function ag() return G.AutoGiftModule or G.AutoGift end
local function ng() return G.NormalGiftModule or G.NormalGift end

function H._setStatus(msg)
    stats.lastStatus = tostring(msg or "Ready")
    G.AUTO_DROP_STATUS = stats.lastStatus
    rawset(_G, "AUTO_DROP_STATUS", stats.lastStatus)
end

function H._cat(c)
    local n = tostring(c or ""):lower():gsub("[%s_]+", "")
    if n == "harvestedfruits" or n == "harvestedfruit" then return "HarvestedFruits" end
    return tostring(c or "Seeds")
end

function H._isHarvest(c) return H._cat(c) == "HarvestedFruits" end

function H._isPetCat(c)
    local n = tostring(c or ""):lower():gsub("[%s_]+", "")
    return n == "pets" or n == "birds" or n == "tools"
end

function H._petDropCategory(catKey)
    catKey = H._cat(catKey)
    if tostring(catKey):lower() == "tools" then return "Pets" end
    return catKey
end

function H._normSet(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for k, v in pairs(src) do if v == true or v == 1 or v == "true" then out[tostring(k)] = true end end
    for _, v in ipairs(src) do if v ~= nil and tostring(v) ~= "" then out[tostring(v)] = true end end
    return out
end

function H._hasSel(m)
    for _, v in pairs(H._normSet(m)) do if v then return true end end
    return false
end

function H._fruitBaseName(s)
    s = tostring(s or "")
    s = s:gsub("%s+x%s+.+$", "")
    s = s:gsub("%s*%b[]", "")
    s = s:gsub("%s+$", "")
    return s
end

function H._fruitTypeFrom(entry, tool)
    if type(entry) == "table" then
        for _, k in ipairs({ "FruitName", "Fruit", "Name", "ItemName" }) do
            local v = entry[k]
            if v and tostring(v) ~= "" then
                if k == "Name" and H._isFruitId(v) then continue end
                return H._fruitBaseName(v)
            end
        end
    end
    if tool and type(tool.GetAttribute) == "function" then
        local v = tool:GetAttribute("FruitName") or tool:GetAttribute("Fruit")
        if v and tostring(v) ~= "" then return H._fruitBaseName(v) end
    end
    if tool then return H._fruitBaseName(tool.Name) end
    return ""
end

function H._strip(s)
    return H._fruitBaseName(s)
end

function H._normKey(v)
    v = H._strip(v):lower():gsub("[%s_%-%.'']+", "")
    if v:sub(-4) == "seed" then v = v:sub(1, -5) end
    return v
end

function H._callable(r)
    if r == nil then return false end
    if type(r) == "table" then return type(r.Fire) == "function" or type(r.Invoke) == "function" end
    if typeof(r) == "Instance" then
        return r:IsA("RemoteEvent") or r:IsA("UnreliableRemoteEvent") or r:IsA("BindableEvent") or r:IsA("RemoteFunction")
    end
    return type(r) == "function"
end

function H._fireNet(r, ...)
    if not H._callable(r) then return false end
    local a = table.pack(...)
    local ok = pcall(function()
        if type(r) == "function" then return r(table.unpack(a, 1, a.n)) end
        if typeof(r) == "Instance" then
            if r:IsA("RemoteFunction") then return r:InvokeServer(table.unpack(a, 1, a.n)) end
            return r:FireServer(table.unpack(a, 1, a.n))
        end
        if type(r.Fire) == "function" then return r:Fire(table.unpack(a, 1, a.n)) end
        if type(r.Invoke) == "function" then return r:Invoke(table.unpack(a, 1, a.n)) end
    end)
    return ok
end

function H._ensureDropRemote()
    if H._callable(RequestDrop) then return true end
    local ok, net = pcall(function() return require(ReplicatedStorage.SharedModules.Networking) end)
    if ok and type(net.DroppedItem) == "table" then RequestDrop = net.DroppedItem.RequestDrop end
    return H._callable(RequestDrop)
end

function H._ensureBackpackNet()
    if H._callable(DropBackpackGetLayout) and H._callable(DropBackpackPromoteFruit) then return true end
    local ok, net = pcall(function() return require(ReplicatedStorage.SharedModules.Networking) end)
    if ok and type(net.Backpack) == "table" then
        DropBackpackGetLayout = DropBackpackGetLayout or net.Backpack.GetLayout
        DropBackpackPromoteFruit = DropBackpackPromoteFruit or net.Backpack.PromoteFruit
    end
    return H._callable(DropBackpackGetLayout)
end

function H._invalidateBag()
    bagCache, bagCacheAt = nil, 0
    local a = ag()
    if type(a) == "table" and type(a.InvalidateHarvestFruitCache) == "function" then pcall(a.InvalidateHarvestFruitCache, a) end
end

function H._backpack() return LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack") end

function H._fruitId(inst)
    if not inst or type(inst.GetAttribute) ~= "function" then return "" end
    return tostring(inst:GetAttribute("Id") or inst:GetAttribute("UUID") or "")
end

function H._isFruitId(id)
    id = tostring(id or "")
    return id ~= "" and not id:find("%s") and #id >= 8
        and not (id:match("^[%a'%-]+$") and not id:match("[%d_]"))
end

function H._isHarvestInst(inst)
    if not inst or type(inst.GetAttribute) ~= "function" then return false end
    if inst:GetAttribute("SeedTool") or inst:GetAttribute("Pet") or inst:GetAttribute("PetId") then return false end
    if inst:GetAttribute("PottedPlant") == true or inst:GetAttribute("MainCategory") == "Seed" then return false end
    local f = inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit")
    if f and tostring(f) ~= "" then return true end
    if inst:GetAttribute("FruitProxy") == true then return true end
    local hf = inst:GetAttribute("HarvestedFruit")
    if hf == true or (type(hf) == "string" and hf ~= "") then return true end
    return inst:GetAttribute("Id") and (inst:GetAttribute("Weight") or inst:GetAttribute("SizeMultiplier"))
end

function H._matchId(inst, id)
    id = tostring(id or "")
    if id == "" then return false end
    if H._fruitId(inst) == id then return true end
    if not inst or type(inst.GetAttribute) ~= "function" then return false end
    local petId = inst:GetAttribute("PetId")
    if type(petId) == "string" and petId == id then return true end
    local uid = inst:GetAttribute("Id") or inst:GetAttribute("UUID") or inst:GetAttribute("InstanceId")
    return uid ~= nil and tostring(uid) == id
end

function H._findPetTool(id)
    id = tostring(id or "")
    if id == "" then return nil end
    local found = nil
    local function scan(container)
        if not container or found then return end
        for _, inst in ipairs(container:GetDescendants()) do
            if inst:IsA("Tool") and H._matchId(inst, id) then
                found = inst
                return
            end
        end
    end
    scan(LP.Character)
    scan(H._backpack())
    return found
end

function H._findTool(id)
    return H._findPetTool(id)
end

function H._eachTool(fn)
    for _, c in ipairs({ LP.Character, H._backpack() }) do
        if c then for _, t in ipairs(c:GetChildren()) do if t:IsA("Tool") then fn(t) end end end
    end
end

function H._fpu()
    if FruitProxyUtil == nil then
        pcall(function() FruitProxyUtil = require(ReplicatedStorage.SharedModules.FruitProxyUtil) end)
        if type(FruitProxyUtil) ~= "table" then FruitProxyUtil = false end
    end
    return FruitProxyUtil ~= false and FruitProxyUtil or nil
end

function H._nukeTool(t)
    if not t then return end
    -- Unequip/reparent only. Destroy races HarvestedFruitHandleController.SpawnHandle
    -- and HeldHandleSelfHeal (max 3 respawns / 10s) — leftover visual sticks on the character.
    local bp = H._backpack()
    local char = LP.Character
    if bp and t.Parent == char then
        pcall(function() t.Parent = bp end)
    elseif t.Parent and t.Parent ~= bp then
        pcall(function() t.Parent = bp or nil end)
    end
end

function H._fruitHandleCtrl()
    if H._hfCtrlCached ~= nil then
        return H._hfCtrlCached ~= false and H._hfCtrlCached or nil
    end
    local ctrl = nil
    pcall(function()
        local ps = LP:FindFirstChild("PlayerScripts")
        local folder = ps and ps:FindFirstChild("Controllers")
        local mod = folder and folder:FindFirstChild("HarvestedFruitHandleController")
        if not mod and ps then
            mod = ps:FindFirstChild("HarvestedFruitHandleController", true)
        end
        if mod then
            ctrl = require(mod)
        end
    end)
    H._hfCtrlCached = type(ctrl) == "table" and ctrl or false
    return H._hfCtrlCached ~= false and H._hfCtrlCached or nil
end

-- Dump: fruit visuals live in workspace.Handles, welded to the arm — not on the Tool.
function H._sweepFruitHandles()
    local char = LP.Character
    local handles = workspace:FindFirstChild("Handles")
    if not char or not handles then return end
    for _, child in ipairs(handles:GetChildren()) do
        local hasAnchor = child:FindFirstChild("FruitAnchor", true) ~= nil
        if not hasAnchor and child.Name ~= "Build" then continue end
        local ours = false
        for _, d in ipairs(child:GetDescendants()) do
            if d:IsA("WeldConstraint") or d:IsA("Weld") then
                local a, b = d.Part0, d.Part1
                if (a and a:IsDescendantOf(char)) or (b and b:IsDescendantOf(char)) then
                    ours = true
                    break
                end
            end
        end
        if ours then
            pcall(function() child:Destroy() end)
        end
    end
end

function H._releaseHarvestHold(tool)
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function() hum:UnequipTools() end) end
    local ctrl = H._fruitHandleCtrl()
    if type(ctrl) == "table" then
        if tool and type(ctrl.CleanupTool) == "function" then
            pcall(ctrl.CleanupTool, ctrl, tool)
        end
        if char and type(ctrl.CleanupAllToolsForCharacter) == "function" then
            pcall(ctrl.CleanupAllToolsForCharacter, ctrl, char)
        end
    end
    local bp = H._backpack()
    if char and bp then
        for _, t in ipairs(char:GetChildren()) do
            if t:IsA("Tool") and (t == tool or H._isHarvestInst(t) or t:GetAttribute("HarvestedFruit") == true) then
                pcall(function() t.Parent = bp end)
            end
        end
    end
    H._sweepFruitHandles()
end

function H._waitHarvestUnequipped(uuid, timeout)
    uuid = tostring(uuid or "")
    local dl = os.clock() + (tonumber(timeout) or 0.35)
    while os.clock() < dl do
        local char = LP.Character
        local holding = false
        if char then
            for _, t in ipairs(char:GetChildren()) do
                if t:IsA("Tool") and (H._isHarvestInst(t) or (uuid ~= "" and H._matchId(t, uuid))) then
                    holding = true
                    break
                end
            end
        end
        if not holding then return true end
        RunService.Heartbeat:Wait()
    end
    return false
end

function H._clearChar()
    local char, bp = LP.Character, H._backpack()
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function() hum:UnequipTools() end) end
    if not bp then return end
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") then
            pcall(function() t.Parent = bp end)
        end
    end
    H._sweepFruitHandles()
end

-- Ghost leftover after a confirmed drop: unequip + dump ClearHandle, jangan Destroy.
function H._stripGhost(tool, uuid)
    H._releaseHarvestHold(tool)
    uuid = tostring(uuid or "")
    if uuid ~= "" then
        local leftover = H._findTool(uuid)
        if leftover and leftover.Parent == LP.Character then
            H._releaseHarvestHold(leftover)
        end
    end
    H._waitHarvestUnequipped(uuid, 0.25)
end

-- After a drop: if uuid already left the bag, destroy matching tools still on character
-- (game sometimes leaves a ghost tool equipped even though the fruit dropped).
function H._stripAfterDrop(tool, uuid)
    H._stripGhost(tool, uuid)
end

function H._toolReady(t)
    if not t then return false end
    local n = t:GetAttribute("ToolDescendants")
    if type(n) == "number" and #t:GetDescendants() < n then return false end
    for _, d in ipairs(t:GetDescendants()) do
        if (d:IsA("Weld") or d:IsA("WeldConstraint")) and (not d.Part0 or not d.Part1) then return false end
    end
    return true
end

function H._equip(t)
    local char, bp = LP.Character, H._backpack()
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not t or not char or not bp or not hum or not t.Parent then return false end
    if t.Parent == char then return true end
    if t.Parent ~= bp then
        if t:IsDescendantOf(bp) then pcall(function() t.Parent = bp end) else return false end
    end
    for _, other in ipairs(char:GetChildren()) do
        if other:IsA("Tool") and other ~= t then
            pcall(function() other.Parent = bp end)
        end
    end
    if t.Parent == bp then pcall(function() t.Parent = char end) end
    if t.Parent == char then return true end
    pcall(function() hum:EquipTool(t) end)
    local dl = os.clock() + HARVEST_EQUIP_WAIT
    while os.clock() < dl do
        if t.Parent == char then return true end
        RunService.Heartbeat:Wait()
    end
    return t.Parent == char
end

-- Dump u14() butuh HarvestedFruit == true plus Id on the equipped tool.
function H._waitHarvestReady(tool, uuid, timeout)
    uuid = tostring(uuid or "")
    local dl = os.clock() + (tonumber(timeout) or HARVEST_EQUIP_WAIT)
    while os.clock() < dl do
        if dropCancel then return nil end
        if not tool or not tool.Parent then
            tool = uuid ~= "" and H._findTool(uuid) or tool
        end
        if tool and tool.Parent == LP.Character then
            local id = tool:GetAttribute("Id")
            if tool:GetAttribute("HarvestedFruit") == true and id and tostring(id) ~= "" then
                if H._toolReady(tool) then return tool end
            end
        end
        RunService.Heartbeat:Wait()
    end
    if tool and tool.Parent == LP.Character then
        local id = tool:GetAttribute("Id")
        if tool:GetAttribute("HarvestedFruit") == true and id and tostring(id) ~= "" then
            return tool
        end
    end
    return nil
end

function H._promote(id)
    id = tostring(id or "")
    if not H._isFruitId(id) then return false end
    local t = H._findTool(id)
    if t then return t.Parent == LP.Character or H._equip(t) end
    local found = nil
    local cons = {}
    local function watch(container)
        if not container then return end
        cons[#cons + 1] = container.ChildAdded:Connect(function(ch)
            if found then return end
            if ch:IsA("Tool") and H._matchId(ch, id) then
                found = ch
            end
        end)
    end
    watch(LP.Character)
    watch(H._backpack())
    H._clearChar()
    H._releaseHarvestHold(nil)
    local f = H._fpu()
    if f then
        if type(f.Pending) ~= "table" then f.Pending = {} end
        f.Pending.Equip = id
        if type(f.RequestPromote) == "function" then pcall(f.RequestPromote, id) end
    end
    H._ensureBackpackNet()
    if H._callable(DropBackpackPromoteFruit) then H._fireNet(DropBackpackPromoteFruit, id) end
    local dl = os.clock() + PROMOTE_WAIT
    while os.clock() < dl do
        if dropCancel then break end
        if found then break end
        t = H._findTool(id)
        if t then
            found = t
            break
        end
        RunService.Heartbeat:Wait()
    end
    for i = 1, #cons do
        pcall(function() cons[i]:Disconnect() end)
    end
    t = found or H._findTool(id)
    if not t or not H._equip(t) then return false end
    return H._waitHarvestReady(t, id, HARVEST_EQUIP_WAIT) ~= nil
end

function H._resolveDropId(t, uuid)
    if t and t.Parent then
        if t:GetAttribute("HarvestedFruit") == true then
            local id = t:GetAttribute("Id")
            if id and tostring(id) ~= "" then return tostring(id) end
        end
        if H._isHarvestInst(t) then
            local id = H._fruitId(t)
            if H._isFruitId(id) then return id end
        end
    end
    return H._isFruitId(uuid) and tostring(uuid) or ""
end

function H._equippedDrop()
    local char = LP.Character
    if not char then return nil, nil end
    for _, t in ipairs(char:GetChildren()) do
        if not t:IsA("Tool") then continue end
        if t:GetAttribute("HarvestedFruit") == true then
            local id = t:GetAttribute("Id")
            if id and tostring(id) ~= "" then return "HarvestedFruits", tostring(id) end
        end
        if H._isHarvestInst(t) then
            local id = H._fruitId(t)
            if H._isFruitId(id) then return "HarvestedFruits", id end
        end
        local petId = t:GetAttribute("PetId")
        if type(petId) == "string" and petId ~= "" then return "Pets", petId end
        for attr, gt in pairs(GIFT_ATTR) do
            local v = t:GetAttribute(attr)
            if v ~= nil and v ~= false and tostring(v) ~= "" then return gt, tostring(v) end
        end
    end
    return nil, nil
end

function H._lastDropLanded()
    return H._countPendingDrops() > lastDropPendingBefore
end

function H._waitDropCooldown()
    if lastDropFireAt <= 0 then return end
    local minUntil = lastDropFireAt + MIN_REQUEST_GAP
    while os.clock() < minUntil do
        if dropCancel then return end
        RunService.Heartbeat:Wait()
    end
    -- Count kadang turun dulu; item di ground belakangan. Tunggu spawn singkat.
    if not H._lastDropLanded() then
        local extraUntil = os.clock() + DROP_LAND_EXTRA
        while os.clock() < extraUntil and not H._lastDropLanded() do
            if dropCancel then return end
            RunService.Heartbeat:Wait()
        end
    end
end

function H._requestDrop(cat, id)
    if not H._ensureDropRemote() then return false end
    cat, id = tostring(cat or ""), tostring(id or "")
    if cat == "" or id == "" then return false end
    H._waitDropCooldown()
    if dropCancel then return false end
    lastDropPendingBefore = H._countPendingDrops()
    local ok = pcall(function()
        if type(RequestDrop) == "table" and RequestDrop.Fire then RequestDrop:Fire(cat, id)
        else H._fireNet(RequestDrop, cat, id) end
    end)
    lastDropFireAt = os.clock()
    return ok
end

function H._hasUuid(uuid, refresh)
    uuid = tostring(uuid or "")
    if uuid == "" then return false end
    if H._findTool(uuid) then return true end
    local bag = H._getBag(refresh == true)
    return type(bag) == "table" and bag[uuid] ~= nil
end

function H._getBag(refresh)
    local now = os.clock()
    if not refresh and bagCache and (now - bagCacheAt) < BAG_CACHE_SEC then return bagCache end
    local a = ag()
    if type(a) == "table" and type(a.GetHarvestFruitBag) == "function" then
        local ok, bag = pcall(a.GetHarvestFruitBag, a, refresh == true)
        if ok and type(bag) == "table" then
            -- Don't overwrite a warm cache with a transient empty bag (causes stop-after-1).
            local count = 0
            for k, _ in pairs(bag) do
                if tostring(k):sub(1, 1) ~= "_" then count += 1 end
            end
            if count > 0 or not bagCache or (now - bagCacheAt) > 1.5 then
                bagCache, bagCacheAt = bag, now
            end
            return (count > 0 and bag) or bagCache or bag
        end
    end
    -- Fetch failed: keep previous cache if fresh enough.
    if bagCache and (now - bagCacheAt) < 2 then return bagCache end
    bagCache, bagCacheAt = {}, now
    return bagCache
end

function H._fav(item)
    if type(item) ~= "table" then return false end
    local a, n = ag(), ng()
    for _, mod in ipairs({ a, n }) do
        if type(mod) == "table" and type(mod.IsHarvestFavorited) == "function" then
            local ok, yes = pcall(mod.IsHarvestFavorited, mod, item)
            if ok and yes then return true end
        end
    end
    local function f(v) return v == true or v == 1 or v == "true" or v == "1" end
    return f(item.IsFavorite) or f(item.Favorite) or f(item.Favorited) or f(item.isFavorite) or f(item.d)
end

function H._expandSel(catKey, sel)
    sel = H._normSet(sel)
    if not next(sel) then return sel end
    local n = ng()
    if type(n) == "table" and type(n.NormalizeSelected) == "function" then
        local ok, out = pcall(n.NormalizeSelected, n, catKey, sel)
        if ok and type(out) == "table" and next(out) then return out end
    end
    return sel
end

function H._matchSel(item, sel)
    if not H._hasSel(sel) then return true end
    sel = H._expandSel("HarvestedFruits", sel)
    local keys = {
        tostring(item.uuid or ""),
        tostring(item.key or ""),
        H._strip(item.name or ""),
        H._fruitBaseName(item.name or ""),
    }
    if type(item.raw) == "table" then
        keys[#keys + 1] = tostring(item.raw.FruitName or item.raw.Fruit or "")
        keys[#keys + 1] = H._fruitBaseName(item.raw.FruitName or item.raw.Fruit or "")
    end
    local norm = {}
    for k, v in pairs(sel) do if v then
        norm[H._normKey(k)] = true
        norm[H._normKey(H._fruitBaseName(k))] = true
    end end
    for _, k in ipairs(keys) do
        if k ~= "" and (sel[k] or norm[H._normKey(k)] or norm[H._normKey(H._fruitBaseName(k))]) then
            return true
        end
    end
    return false
end

function H._bagUuid(key, entry)
    if type(entry) == "table" then
        for _, f in ipairs({ "Id", "id", "UUID", "Uuid", "FruitId", "c" }) do
            local v = entry[f]
            if v and H._isFruitId(v) then return tostring(v) end
        end
    end
    key = tostring(key or "")
    return H._isFruitId(key) and key or ""
end

function H._listHarvest(sel, skipBag)
    sel = H._normSet(sel)
    local out, seen = {}, {}

    local function add(uuid, tool, entry)
        uuid = tostring(uuid or "")
        if uuid == "" or not H._isFruitId(uuid) or seen[uuid] then return end
        local name = H._fruitTypeFrom(entry, tool)
        if name == "" and tool then
            name = H._fruitBaseName(tool:GetAttribute("FruitName") or tool:GetAttribute("Fruit") or tool.Name)
        end
        local item = { uuid = uuid, key = uuid, name = name, raw = entry, tool = tool }
        if not H._matchSel(item, sel) then return end
        -- Fav hanya dilindungi kalau drop-all (tidak pilih jenis). Yang dipilih di UI tetap di-drop.
        if H._fav(item) and not H._hasSel(sel) then return end
        seen[uuid] = true
        out[#out + 1] = { uuid = uuid, tool = tool, name = name }
    end

    H._eachTool(function(t)
        if not H._isHarvestInst(t) then return end
        local id = t:GetAttribute("Id") or t:GetAttribute("UUID")
        if H._isFruitId(id) then
            add(tostring(id), t, {
                FruitName = t:GetAttribute("FruitName") or t:GetAttribute("Fruit") or t.Name,
            })
        end
    end)

    if skipBag then return out end

    local a = ag()
    if type(a) == "table" and type(a.CollectCategoryCandidates) == "function" then
        local ok, rows = pcall(a.CollectCategoryCandidates, a, "HarvestedFruits", sel)
        if ok and type(rows) == "table" then
            for _, row in ipairs(rows) do
                local uuid = tostring(row.ItemKey or "")
                if not H._isFruitId(uuid) then
                    uuid = H._bagUuid(row.ItemKey, row.Entry)
                end
                if uuid ~= "" then add(uuid, H._findTool(uuid), row.Entry) end
            end
        end
    end

    for key, entry in pairs(H._getBag(not skipBag)) do
        if tostring(key):sub(1, 1) ~= "_" then add(H._bagUuid(key, entry), H._findTool(H._bagUuid(key, entry)), entry) end
    end
    return out
end

function H._rawStackCount(t)
    if not t or not t.Parent then return 0 end
    local c = t:GetAttribute("Count")
    if type(c) == "number" then return math.max(0, math.floor(c)) end
    return 1
end

function H._stackCount(t)
    return math.max(0, H._rawStackCount(t))
end

function H._sumStacks(catKey, sel, extraTool)
    local n, seen = 0, {}
    local function add(t)
        if not t or seen[t] then return end
        seen[t] = true
        n += H._rawStackCount(t)
    end
    if extraTool then add(extraTool) end
    for _, slot in ipairs(H._findTools(catKey, sel)) do
        add(slot and slot.tool)
    end
    return n
end

function H._waitStackDecrement(tool, before, timeout)
    before = tonumber(before) or 0
    timeout = tonumber(timeout) or GENERIC_CONFIRM
    local t0 = os.clock()
    while os.clock() - t0 < timeout do
        if dropCancel then return false end
        if not tool or not tool.Parent then
            return before > 0
        end
        if H._rawStackCount(tool) < before then
            return true
        end
        RunService.Heartbeat:Wait()
    end
    if not tool or not tool.Parent then return before > 0 end
    return H._rawStackCount(tool) < before
end

function H._armDropWatch()
    local folder = H._droppedFolder()
    local st = {
        landed = false,
        anyNew = false,
        pendingBefore = H._countPendingDrops(),
        childBefore = 0,
        conn = nil,
        attrConns = {},
    }
    if folder then
        st.childBefore = #folder:GetChildren()
        st.conn = folder.ChildAdded:Connect(function(m)
            if not m or not m:IsA("Model") then return end
            st.anyNew = true
            local function check()
                if st.landed then return end
                if H._isOwnPendingDrop(m) then
                    st.landed = true
                end
            end
            check()
            pcall(function()
                st.attrConns[#st.attrConns + 1] = m:GetAttributeChangedSignal("DroppedBy"):Connect(check)
            end)
            task.defer(check)
        end)
    end
    return st
end

function H._disarmDropWatch(st)
    if st and st.conn then
        pcall(function() st.conn:Disconnect() end)
        st.conn = nil
    end
    if st and type(st.attrConns) == "table" then
        for i = 1, #st.attrConns do
            pcall(function() st.attrConns[i]:Disconnect() end)
        end
        st.attrConns = {}
    end
end

-- Connect ChildAdded BEFORE Fire so same-frame replication is not missed.
function H._awaitDropWatch(st, tool, beforeCount, timeout)
    timeout = tonumber(timeout) or CONFIRM_MAX
    local folder = H._droppedFolder()
    local t0 = os.clock()
    while os.clock() - t0 < timeout do
        if dropCancel then break end
        if st.landed then break end
        if tool and not tool.Parent then
            st.landed = true
            break
        end
        if tool and tool.Parent and beforeCount and H._rawStackCount(tool) < beforeCount then
            st.landed = true
            break
        end
        RunService.Heartbeat:Wait()
    end
    H._disarmDropWatch(st)
    if st.landed then return true end
    if tool and not tool.Parent then return true end
    if tool and beforeCount and H._rawStackCount(tool) < beforeCount then return true end
    if H._countPendingDrops() > st.pendingBefore then return true end
    return false
end

function H._waitDropAck(tool, beforeCount, pendingBefore, timeout)
    local st = H._armDropWatch()
    if pendingBefore ~= nil then st.pendingBefore = pendingBefore end
    return H._awaitDropWatch(st, tool, beforeCount, timeout)
end

function H._confirm(uuid, tool)
    uuid = tostring(uuid or "")
    if tool and not tool.Parent then return true end
    if uuid ~= "" and not H._findTool(uuid) then return true end
    return false
end

function H._confirmGeneric(tool, before)
    return H._waitDropAck(tool, before, nil, GENERIC_CONFIRM)
end

function H._dropHarvest(entry)
    if type(entry) ~= "table" then return false end
    local uuid = tostring(entry.uuid or "")
    if not H._isFruitId(uuid) then return false end
    H._sweepFruitHandles()

    local tool = entry.tool
    local equipped = tool and tool.Parent == LP.Character
    if not equipped then
        if tool and tool.Parent then
            if not H._equip(tool) then return false end
        else
            if not H._promote(uuid) then return false end
        end
    end

    tool = H._waitHarvestReady(H._findTool(uuid) or tool, uuid, HARVEST_EQUIP_WAIT)
    if not (tool and tool.Parent == LP.Character) then
        H._clearChar()
        return false
    end

    local cat, dropId = H._equippedDrop()
    if not dropId or dropId == "" then
        cat, dropId = "HarvestedFruits", H._resolveDropId(tool, uuid)
    end
    if dropId == "" then
        H._clearChar()
        return false
    end
    -- Dump only fires HarvestedFruits + Id from the equipped tool.
    if cat ~= "HarvestedFruits" then
        cat = "HarvestedFruits"
        dropId = H._resolveDropId(tool, uuid)
        if dropId == "" then dropId = uuid end
    end

    local watch = H._armDropWatch()
    if not H._requestDrop("HarvestedFruits", dropId) then
        H._disarmDropWatch(watch)
        H._clearChar()
        return false
    end
    local ok = H._awaitDropWatch(watch, tool, nil, HARVEST_CONFIRM)
    if not ok then
        ok = (not tool or not tool.Parent) or not H._findTool(dropId)
    end
    -- Unequip first so SpawnHandle's end-check (Parent ~= character) calls ClearHandle.
    -- Destroying the tool here leaves workspace.Handles welded to the arm (stuck visual).
    H._releaseHarvestHold(tool)
    H._waitHarvestUnequipped(dropId, 0.3)
    if not ok then
        H._clearChar()
    end
    return ok
end

function H._delay(mul)
    local sec = (tonumber(cfg.drop_delay_sec) or 0) * (tonumber(mul) or 1)
    if sec > 0 then task.wait(sec) end
end

function H._droppedFolder()
    return workspace:FindFirstChild("DroppedItems")
end

function H._disconnectGroundWatch()
    if groundAddConn then pcall(function() groundAddConn:Disconnect() end) end
    if groundRemConn then pcall(function() groundRemConn:Disconnect() end) end
    groundAddConn, groundRemConn, groundWatchFolder = nil, nil, nil
end

function H._ensureGroundWatch()
    local folder = H._droppedFolder()
    if not folder then return end
    if groundWatchFolder == folder and groundAddConn then return end
    H._disconnectGroundWatch()
    groundWatchFolder = folder
    groundAddConn = folder.ChildAdded:Connect(function(m)
        if not m or not m:IsA("Model") then return end
        if dropBusy then ownGroundModels[m] = true end
        local function check()
            if not m.Parent then
                ownGroundModels[m] = nil
                return
            end
            local by = m:GetAttribute("DroppedBy")
            if by == nil then return end
            if H._isOwnPendingDrop(m) then
                ownGroundModels[m] = true
            elseif dropBusy then
                -- DroppedBy belongs to someone else
                ownGroundModels[m] = nil
            end
        end
        task.defer(check)
        pcall(function()
            m:GetAttributeChangedSignal("DroppedBy"):Connect(check)
        end)
    end)
    groundRemConn = folder.ChildRemoved:Connect(function(m)
        ownGroundModels[m] = nil
    end)
end

function H._isOwnPendingDrop(model)
    if not model or not model:IsA("Model") then return false end
    local by = model:GetAttribute("DroppedBy")
    if by == nil then return false end
    local uid = LP.UserId
    return tonumber(by) == uid or tostring(by) == tostring(uid)
end

function H._countPendingDrops()
    H._ensureGroundWatch()
    local folder = H._droppedFolder()
    local n, seen = 0, {}
    if folder then
        for _, m in ipairs(folder:GetChildren()) do
            if H._isOwnPendingDrop(m) or ownGroundModels[m] then
                if m:IsA("Model") then
                    n += 1
                    seen[m] = true
                    ownGroundModels[m] = true
                end
            end
        end
    end
    for m in pairs(ownGroundModels) do
        if seen[m] then continue end
        if typeof(m) == "Instance" and folder and m.Parent == folder then
            n += 1
        else
            ownGroundModels[m] = nil
        end
    end
    return n
end

-- Pause while own pending drops on ground are at the game cap (10).
-- Returns false if cancelled; true when a slot is free.
function H._waitPendingSlot(droppedDone, goal)
    H._ensureGroundWatch()
    while not dropCancel do
        local pending = H._countPendingDrops()
        if pending < MAX_PENDING_DROPS then
            return true, pending
        end
        H._setStatus(string.format(
            "Wait claim %d/%d — ground %d/%d",
            droppedDone or 0, goal or 0, pending, MAX_PENDING_DROPS
        ))
        if H._dropHasTarget() then
            H._stickNearDropTarget()
        end
        task.wait(PENDING_POLL_SEC)
    end
    return false, H._countPendingDrops()
end

function H._slotKey(infoOrEntry)
    if type(infoOrEntry) ~= "table" then return "" end
    local id = infoOrEntry.uuid or infoOrEntry.id
        or (infoOrEntry.info and (infoOrEntry.info.uuid or infoOrEntry.info.key))
        or infoOrEntry.key
    return tostring(id or "")
end

function H._harvestIdGone(uuid)
    uuid = tostring(uuid or "")
    if uuid == "" then return true end
    if H._findTool(uuid) then return false end
    return not H._hasUuid(uuid, true)
end

function H._buildHarvestQueue(sel, goal, exclude)
    exclude = type(exclude) == "table" and exclude or {}
    H._invalidateBag()
    local list = H._listHarvest(sel, false)
    if #list == 0 then
        task.wait(0.2)
        H._invalidateBag()
        list = H._listHarvest(sel, false)
    end
    table.sort(list, function(a, b)
        local na = H._normKey(a.name or "")
        local nb = H._normKey(b.name or "")
        if na == nb then return tostring(a.uuid) < tostring(b.uuid) end
        return na < nb
    end)
    local cap = math.max(1, math.floor(tonumber(goal) or 1))
    local queue = {}
    for i = 1, #list do
        local id = tostring(list[i].uuid or "")
        if id ~= "" and not exclude[id] then
            queue[#queue + 1] = { uuid = id, name = list[i].name }
            if #queue >= cap then break end
        end
    end
    return queue, #list
end

function H._runHarvestJob(goal, sel)
    if not H._ensureBackpackNet() then H._setStatus("Backpack not ready") return end
    H._ensureGroundWatch()
    ownGroundModels = {}

    local doneSet, skipSet = {}, {}
    local queue = H._buildHarvestQueue(sel, goal, doneSet)

    local dropped, qIdx, retries = 0, 1, {}
    stats.dropped = 0
    if #queue == 0 then
        H._setStatus(string.format("Waiting fruits 0/%d", goal))
    else
        H._setStatus(string.format("Dropping 0/%d", goal))
    end

    local function refill()
        -- Scan backpack dari nol. Jangan pakai skipSet/queue lama:
        -- fruit yang sempat "gone" atau UUID yang sama bisa muncul lagi setelah harvest.
        H._invalidateBag()
        local list = H._listHarvest(sel, false)
        if #list == 0 then
            list = H._listHarvest(sel, true)
        end
        if #list == 0 then return false end

        local live = {}
        for i = 1, #list do
            local id = tostring(list[i].uuid or "")
            if id ~= "" then live[id] = list[i] end
        end

        for id in pairs(live) do
            skipSet[id] = nil
            -- Masih di backpack = belum ter-drop (false success / fruit baru).
            if doneSet[id] and (H._findTool(id) or H._hasUuid(id, true)) then
                doneSet[id] = nil
                dropped = math.max(0, dropped - 1)
                stats.dropped = dropped
            end
        end

        table.sort(list, function(a, b)
            local ra = retries[tostring(a.uuid)] or 0
            local rb = retries[tostring(b.uuid)] or 0
            if ra ~= rb then return ra < rb end
            local na = H._normKey(a.name or "")
            local nb = H._normKey(b.name or "")
            if na == nb then return tostring(a.uuid) < tostring(b.uuid) end
            return na < nb
        end)

        local need = math.max(1, goal - dropped)
        queue = {}
        qIdx = 1
        for i = 1, #list do
            local id = tostring(list[i].uuid or "")
            if id ~= "" and not doneSet[id] then
                queue[#queue + 1] = { uuid = id, name = list[i].name, tool = list[i].tool }
                if #queue >= need then break end
            end
        end
        return #queue > 0
    end

    while dropped < goal and not dropCancel do
        if H._dropHasTarget() and not H._stickNearDropTarget() then
            H._setStatus("Too far from target — stopping")
            break
        end
        if not H._waitPendingSlot(dropped, goal) then
            break
        end

        if qIdx > #queue then
            if refill() then
                H._setStatus(string.format("Dropping %d/%d", dropped + 1, goal))
            else
                -- Total belum tercapai: jangan stop, tunggu fruit baru di backpack.
                H._setStatus(string.format("Waiting fruits %d/%d", dropped, goal))
                local waitUntil = os.clock() + 0.35
                while os.clock() < waitUntil and not dropCancel do
                    RunService.Heartbeat:Wait()
                end
                continue
            end
        end

        local entry = queue[qIdx]
        if not entry or doneSet[entry.uuid] or skipSet[entry.uuid] then
            qIdx += 1
            continue
        end

        if H._harvestIdGone(entry.uuid) then
            qIdx += 1
            continue
        end

        H._setStatus(string.format(
            "Dropping %d/%d (%s) ground %d/%d",
            dropped + 1, goal, tostring(entry.name or "fruit"),
            H._countPendingDrops(), MAX_PENDING_DROPS
        ))

        local live = { uuid = entry.uuid, name = entry.name, tool = H._findTool(entry.uuid) }
        if H._dropHarvest(live) then
            dropped += 1
            stats.dropped = dropped
            doneSet[entry.uuid] = true
            retries[entry.uuid] = nil
            qIdx += 1
            H._setStatus(string.format("Dropped %d/%d", dropped, goal))
            H._delay(1)
        else
            if H._harvestIdGone(entry.uuid) then
                qIdx += 1
                continue
            end
            retries[entry.uuid] = (retries[entry.uuid] or 0) + 1
            if retries[entry.uuid] > RETRY_MAX then
                qIdx += 1
            else
                H._delay(0.2)
            end
        end
    end

    stats.dropped = dropped
    H._clearChar()
    H._releaseHarvestHold(nil)
    if dropCancel then H._setStatus(string.format("Stopped %d/%d", dropped, goal))
    elseif dropped >= goal then H._setStatus(string.format("Done %d/%d", dropped, goal))
    else H._setStatus(string.format("Stopped %d/%d", dropped, goal)) end
end

function H._toolInfo(t)
    if not t or not t:IsA("Tool") then return nil end
    if H._isHarvestInst(t) then
        local id = H._fruitId(t)
        return { giftType = "HarvestedFruits", uuid = id, key = id, name = t.Name, tool = t }
    end
    local petId = t:GetAttribute("PetId")
    if type(petId) == "string" and petId ~= "" then return { giftType = "Pets", uuid = petId, key = petId, name = t.Name } end
    for attr, gt in pairs(GIFT_ATTR) do
        local v = t:GetAttribute(attr)
        if v ~= nil and v ~= false and tostring(v) ~= "" then
            return { giftType = gt, uuid = tostring(t:GetAttribute("Id") or v), key = tostring(v), name = tostring(v) }
        end
    end
    return nil
end

function H._matchCat(info, catKey, sel)
    if not info or H._cat(info.giftType) ~= H._cat(catKey) then return false end
    if not H._hasSel(sel) then return true end
    sel = H._expandSel(catKey, sel)
    local keys = { tostring(info.uuid or ""), tostring(info.key or ""), H._strip(info.name or "") }
    local norm = {}
    for k, v in pairs(sel) do if v then norm[H._normKey(k)] = true end end
    for _, k in ipairs(keys) do if k ~= "" and (sel[k] or norm[H._normKey(k)]) then return true end end
    return false
end

function H._findTools(catKey, sel)
    catKey = H._cat(catKey)
    sel = H._hasSel(sel) and H._expandSel(catKey, sel) or {}
    local out = {}

    if H._isPetCat(catKey) then
        local a = ag()
        if type(a) == "table" and type(a.BuildInventoryItems) == "function" then
            local canon = H._petDropCategory(catKey)
            local ok, items = pcall(a.BuildInventoryItems, a, canon)
            if ok and type(items) == "table" then
                for _, it in ipairs(items) do
                    local id = tostring(it.key or "")
                    if id == "" or id == "_none" then continue end
                    local info = {
                        giftType = "Pets",
                        uuid = id,
                        key = id,
                        name = tostring(it.name or id),
                    }
                    if not H._matchCat(info, "Pets", sel) then continue end
                    local tool = H._findPetTool(id)
                    if tool and tool.Parent then
                        out[#out + 1] = { tool = tool, info = info }
                    end
                end
                if #out > 0 then return out end
            end
        end
    end

    local n = ng()
    if type(n) == "table" and type(n.CollectCandidates) == "function" then
        pcall(n.EnsureGiftReady, n, 4)
        local ok, list = pcall(n.CollectCandidates, n, catKey, sel, true)
        if ok and type(list) == "table" then
            for _, item in ipairs(list) do
                local t = item.tool or item.inst
                if t and t.Parent then out[#out + 1] = { tool = t, info = item } end
            end
            if #out > 0 then return out end
        end
    end
    H._eachTool(function(t)
        local info = H._toolInfo(t)
        if H._matchCat(info, catKey, sel) then out[#out + 1] = { tool = t, info = info } end
    end)
    return out
end

function H._dropGeneric(slot)
    local tool = slot and slot.tool
    if not tool or not tool.Parent then return false end
    if tool.Parent ~= LP.Character then
        if not H._equip(tool) then return false end
    end
    local cat, id = H._equippedDrop()
    if not cat or not id then
        H._clearChar()
        return false
    end
    local before = H._rawStackCount(tool)
    if before < 1 then
        return false
    end
    local watch = H._armDropWatch()
    if not H._requestDrop(cat, id) then
        H._disarmDropWatch(watch)
        return false
    end
    -- Stackable: hanya Count turun (atau tool hilang) yang dihitung. ChildAdded saja
    -- sering false-success — Count dari drop sebelumnya replicate telat → UI 100 padahal 50.
    local ok = H._waitStackDecrement(tool, before, GENERIC_CONFIRM)
    if not ok and watch.landed then
        ok = H._waitStackDecrement(tool, before, 0.2)
    end
    H._disarmDropWatch(watch)
    if ok then
        -- Tunggu Count settle 1 frame supaya iterasi berikutnya tidak memakai decrement lama.
        RunService.Heartbeat:Wait()
        if tool and tool.Parent == LP.Character and H._rawStackCount(tool) >= 1 then
            return true
        end
        H._clearChar()
        return true
    end
    H._clearChar()
    return false
end

function H._runGenericJob(goal, catKey, sel)
    H._ensureGroundWatch()
    ownGroundModels = {}
    local startCount = H._sumStacks(catKey, sel)
    if startCount < 1 then H._setStatus("No items") return end
    goal = math.max(1, math.floor(tonumber(goal) or 1))
    H._setStatus(string.format("Dropping 0/%d", goal))

    local dropped, fails, held = 0, 0, nil
    stats.dropped = 0

    while dropped < goal and not dropCancel do
        if H._dropHasTarget() and not H._stickNearDropTarget() then
            H._setStatus("Too far from target — stopping")
            break
        end
        if not H._waitPendingSlot(dropped, goal) then
            break
        end

        local current = H._sumStacks(catKey, sel, held and held.tool)
        dropped = math.max(0, startCount - current)
        stats.dropped = dropped
        if dropped >= goal or current < 1 then break end

        local slot = held
        if not (slot and slot.tool and slot.tool.Parent) then
            local tools = H._findTools(catKey, sel)
            if #tools == 0 then
                local found = false
                for _ = 1, 3 do
                    task.wait(0.04)
                    if dropCancel then break end
                    tools = H._findTools(catKey, sel)
                    if #tools > 0 then found = true break end
                end
                if not found then break end
            end
            slot = tools[1]
            held = slot
        end
        if not slot then break end

        H._setStatus(string.format(
            "Dropping %d/%d (have %d, ground %d/%d)",
            dropped + 1, goal, current, H._countPendingDrops(), MAX_PENDING_DROPS
        ))

        H._dropGeneric(slot)
        current = H._sumStacks(catKey, sel, slot.tool)
        local actual = math.max(0, startCount - current)
        if actual > dropped then
            dropped = actual
            stats.dropped = dropped
            fails = 0
            H._setStatus(string.format("Dropped %d/%d", dropped, goal))
            if not (slot.tool and slot.tool.Parent) then held = nil end
            H._delay(1)
        else
            fails += 1
            held = nil
            if fails >= FAIL_MAX then break end
            H._clearChar()
            H._delay(0.15)
        end
    end

    local finalHave = H._sumStacks(catKey, sel)
    dropped = math.max(dropped, math.max(0, startCount - finalHave))
    H._clearChar()
    stats.dropped = dropped
    H._setStatus(dropped >= goal and string.format("Done %d/%d", dropped, goal) or string.format("Stopped %d/%d", dropped, goal))
end

function H._finish()
    H._teleResumeNow()
    H._clearChar()
    H._disconnectGroundWatch()
    ownGroundModels = {}
    dropBusy = false
    dropCancel = false
    local dd = G.__GAG2_AUTO_DROP_ITEM_DD or rawget(_G, "__GAG2_AUTO_DROP_ITEM_DD")
    if type(dd) == "table" and type(dd.refreshItems) == "function" then pcall(dd.refreshItems, dd) end
    local done = G.__GAG2_AUTO_DROP_DONE or rawget(_G, "__GAG2_AUTO_DROP_DONE")
    if type(done) == "function" then pcall(done, stats.dropped > 0) end
end

function M.ForceReset() dropCancel, dropBusy = true, false H._invalidateBag() end

function M.WaitUntilIdle(timeout)
    local dl = os.clock() + (tonumber(timeout) or 3)
    while dropBusy and os.clock() < dl do task.wait(0.03) end
    return not dropBusy
end

function M.Stop()
    dropCancel = true
    if dropBusy then H._setStatus("Stopping...") end
end

function M.IsBusy() return dropBusy end

function M.GetStats()
    return {
        busy = dropBusy,
        lastStatus = stats.lastStatus,
        dropped = stats.dropped,
        goal = stats.goal,
        pendingGround = H._countPendingDrops(),
        maxPending = MAX_PENDING_DROPS,
    }
end

function H._distanceToPlayer(target)
    local char = LP.Character
    local tchar = target and target.Character
    if not char or not tchar then return math.huge end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local thrp = tchar:FindFirstChild("HumanoidRootPart")
    if not hrp or not thrp then return math.huge end
    return (hrp.Position - thrp.Position).Magnitude
end

function H._resolveTarget()
    local uid = math.floor(tonumber(cfg.target_user_id) or 0)
    if uid > 0 then
        local p = Players:GetPlayerByUserId(uid)
        if p and p ~= LP then return p end
    end
    local name = tostring(cfg.target_name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name ~= "" then
        local lower = name:lower():gsub("^@", "")
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP then
                local label = p.DisplayName .. " (@" .. p.Name .. ")"
                if p.Name:lower() == lower or p.DisplayName:lower() == lower
                    or label:lower() == lower or label:lower():find(lower, 1, true) then
                    return p
                end
            end
        end
    end
    return nil
end

function H._teleport(cf)
    if typeof(cf) ~= "CFrame" then return false end
    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not char or not hrp then return false end
    local ok = pcall(function()
        if char.PrimaryPart then char:PivotTo(cf) else hrp.CFrame = cf end
    end)
    if ok then task.wait(AFTER_TP_SEC) end
    return ok
end

function H._teleportNearTarget(target)
    local tchar = target and target.Character
    local thrp = tchar and tchar:FindFirstChild("HumanoidRootPart")
    if not thrp then return false end
    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    local toUs = hrp.Position - thrp.Position
    local dir = toUs.Magnitude > 1 and toUs.Unit or -thrp.CFrame.LookVector
    local flat = Vector3.new(dir.X, 0, dir.Z)
    if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, -1) else flat = flat.Unit end
    local pos = thrp.Position + flat * TP_STAND_DIST + Vector3.new(0, TP_Y_OFFSET, 0)
    return H._teleport(CFrame.new(pos, thrp.Position))
end

local function _getAutoTeleMod()
    return G.AutoTele or rawget(_G, "AutoTele")
end

function H._teleIsOn()
    local mod = _getAutoTeleMod()
    if type(mod) == "table" and type(mod.IsEnabled) == "function" then
        return mod.IsEnabled() == true
    end
    local s = rawget(_G, "__GAG2_AUTO_TELE") or G.__GAG2_AUTO_TELE
    if type(s) == "table" then return s.enabled == true end
    return G.AUTO_TELE_ENABLED == true or rawget(_G, "AUTO_TELE_ENABLED") == true
end

function H._teleWasRunning()
    local mod = _getAutoTeleMod()
    if type(mod) == "table" and type(mod.IsRunning) == "function" then
        return mod.IsRunning() == true
    end
    return false
end

function H._dropHasTarget()
    local uid = math.floor(tonumber(cfg.target_user_id) or 0)
    local name = tostring(cfg.target_name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    return uid > 0 or name ~= ""
end

function H._isNearDropTarget(target)
    return target and H._distanceToPlayer(target) <= DROP_NEAR_DIST
end

function H._teleportNearTargetOnce(target)
    local n = ng()
    if type(n) == "table" and type(n.TeleportToTarget) == "function" then
        if select(1, n.TeleportToTarget(n, target)) then return true end
    end
    return H._teleportNearTarget(target)
end

function H._needsDropTeleport()
    return H._dropHasTarget() and cfg.teleport_to_target == true
end

function H._beginDropNearTargetSession()
    if not H._needsDropTeleport() then return end
    dropNearTargetActive = true
    teleWasOn = H._teleIsOn() == true
    dropTelePaused = teleWasOn
    G.__GAG2_AUTO_TELE_SUPPRESS = true
    rawset(_G, "__GAG2_AUTO_TELE_SUPPRESS", true)
    local mod = _getAutoTeleMod()
    if type(mod) == "table" and type(mod.Stop) == "function" then
        pcall(mod.Stop, mod)
    end
end

function H._teleKeepPaused()
    if not dropNearTargetActive then return end
    G.__GAG2_AUTO_TELE_SUPPRESS = true
    rawset(_G, "__GAG2_AUTO_TELE_SUPPRESS", true)
    local mod = _getAutoTeleMod()
    if type(mod) == "table" and type(mod.IsRunning) == "function" and type(mod.Stop) == "function" then
        if mod:IsRunning() then pcall(mod.Stop, mod) end
    end
end

function H._teleStopForDrop()
    H._beginDropNearTargetSession()
end

function H._teleResumeNow()
    if not dropNearTargetActive and not dropTelePaused then return end
    local resume = teleWasOn == true
    dropNearTargetActive = false
    dropTelePaused = false
    teleWasOn = false
    G.__GAG2_AUTO_TELE_SUPPRESS = false
    rawset(_G, "__GAG2_AUTO_TELE_SUPPRESS", false)
    if not resume then return end
    local mod = _getAutoTeleMod()
    if type(mod) == "table" and type(mod.IsEnabled) == "function" and mod.IsEnabled() then
        if type(mod.Start) == "function" then
            pcall(mod.Start, mod)
        elseif type(mod.EnsureRunning) == "function" then
            pcall(mod.EnsureRunning, mod)
        end
    end
end

function H._retryTeleportNearTarget(target, maxAttempts, statusPrefix)
    maxAttempts = math.max(1, math.floor(tonumber(maxAttempts) or TP_MAX_ATTEMPTS))
    statusPrefix = tostring(statusPrefix or "Teleporting near")
    for attempt = 1, maxAttempts do
        if dropCancel then return false end
        H._teleKeepPaused()
        H._setStatus(string.format("%s %s (%d/%d)...", statusPrefix, target.Name, attempt, maxAttempts))
        H._teleportNearTargetOnce(target)
        task.wait(TP_RETRY_WAIT)
        if H._isNearDropTarget(target) then
            H._setStatus(string.format("Near %s (%.0f studs)", target.Name, H._distanceToPlayer(target)))
            return true
        end
    end
    return false
end

function H._stickNearDropTarget()
    if not H._dropHasTarget() then return true end
    if cfg.teleport_to_target ~= true then return true end
    H._teleKeepPaused()
    local target = H._resolveTarget()
    if not target then
        H._setStatus("Target player not in server")
        return false
    end
    if H._isNearDropTarget(target) then return true end
    return H._retryTeleportNearTarget(target, TP_STICK_ATTEMPTS, "Returning near")
end

function H._ensureNearDropTarget()
    local uid = math.floor(tonumber(cfg.target_user_id) or 0)
    local name = tostring(cfg.target_name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if uid <= 0 and name == "" then return true end
    if cfg.teleport_to_target ~= true then return true end

    local target = H._resolveTarget()
    if not target then
        H._setStatus("Target player not in server")
        return false
    end
    if H._isNearDropTarget(target) then
        H._setStatus(string.format("Near %s", target.Name))
        return true
    end
    if H._retryTeleportNearTarget(target, TP_MAX_ATTEMPTS, "Teleporting near") then
        return true
    end
    H._setStatus(string.format("Too far (%.0f studs) — teleport failed", H._distanceToPlayer(target)))
    return false
end

function M.TeleportToTarget(targetOrKey)
    local target = targetOrKey
    if typeof(targetOrKey) ~= "Instance" or not targetOrKey:IsA("Player") then
        target = H._resolveTarget()
    end
    if not target then H._setStatus("Select a player in this server") return false, "no_target" end
    local n = ng()
    if type(n) == "table" and type(n.TeleportToTarget) == "function" then
        local ok = select(1, n.TeleportToTarget(n, target))
        if ok then H._setStatus(string.format("Teleported near %s", target.Name)) return true end
    end
    if H._teleportNearTarget(target) then
        H._setStatus(string.format("Teleported near %s", target.Name))
        return true
    end
    H._setStatus("Teleport failed")
    return false, "tp_fail"
end

function M.ApplyConfig(a, b)
    local p = type(b) == "table" and b or type(a) == "table" and a
    if not p then return end
    if p.category then cfg.category = H._cat(p.category) end
    if type(p.selected) == "table" then cfg.selected = H._normSet(p.selected) end
    -- No upper cap on drop_total (game ground pending is throttled separately at 10).
    if p.drop_total then cfg.drop_total = math.max(1, math.floor(tonumber(p.drop_total) or 1)) end
    if p.drop_delay_sec ~= nil then
        cfg.drop_delay_sec = math.clamp(tonumber(p.drop_delay_sec) or 0, 0, 30)
    end
    if p.target_user_id ~= nil then cfg.target_user_id = math.floor(tonumber(p.target_user_id) or 0) end
    if p.target_name ~= nil then cfg.target_name = tostring(p.target_name or "") end
    if p.teleport_to_target ~= nil then cfg.teleport_to_target = (p.teleport_to_target == true) end
end

function M.SyncFromGlobals()
    local s = G.__GAG2_AUTO_DROP or rawget(_G, "__GAG2_AUTO_DROP")
    if type(s) == "table" then M.ApplyConfig(s) end
    local main = G.MAIN or rawget(_G, "MAIN")
    if type(main) == "table" and type(main.auto) == "table" and type(main.auto.dropItem) == "table" then
        M.ApplyConfig(main.auto.dropItem)
    end
end

function M.PrepHarvest() H._invalidateBag() H._getBag(true) end

function M.GetHarvestItemLabels()
    H._invalidateBag()
    local a = ag()
    if type(a) == "table" and type(a.BuildInventoryItems) == "function" then
        local ok, items = pcall(a.BuildInventoryItems, a, "HarvestedFruits")
        if ok and type(items) == "table" and #items > 0 then
            local out = {}
            for _, it in ipairs(items) do out[#out + 1] = { key = it.key, name = it.name, giftType = "HarvestedFruits", count = it.count } end
            table.sort(out, function(x, y) return tostring(x.name) < tostring(y.name) end)
            return out
        end
    end
    local grouped, out = {}, {}
    for uuid, entry in pairs(H._getBag(false)) do
        if tostring(uuid):sub(1, 1) == "_" or H._fav(entry) then continue end
        local label = type(entry) == "table" and tostring(entry.FruitName or "") or "Fruit"
        if label == "" then label = "Fruit" end
        grouped[label] = (grouped[label] or 0) + 1
    end
    for label, count in pairs(grouped) do
        out[#out + 1] = { key = label, name = count > 1 and string.format("%s x %d", label, count) or label, giftType = "HarvestedFruits", count = count }
    end
    table.sort(out, function(x, y) return tostring(x.name) < tostring(y.name) end)
    return out
end

function M.GetPetItemLabels()
    local a = ag()
    if type(a) ~= "table" or type(a.BuildInventoryItems) ~= "function" then return {} end
    local ok, items = pcall(a.BuildInventoryItems, a, "Pets")
    if ok and type(items) == "table" then return items end
    return {}
end

function M.RunNow(a, b)
    if dropBusy then
        M.Stop()
        M.WaitUntilIdle(2)
        if dropBusy then M.ForceReset() end
    end
    local patch = type(b) == "table" and b or type(a) == "table" and b == nil and a
    if patch then M.ApplyConfig(patch) else M.SyncFromGlobals() end

    local catKey = H._cat(cfg.category)
    local sel = H._expandSel(catKey, cfg.selected)
    local goal = math.max(1, math.floor(tonumber(cfg.drop_total) or 1))
    if not H._ensureDropRemote() then H._setStatus("Remote not ready") return false, "remote" end
    if H._isHarvest(catKey) and not H._ensureBackpackNet() then H._setStatus("Backpack not ready") return false end

    dropBusy, dropCancel = true, false
    stats.dropped, stats.goal = 0, goal
    task.spawn(function()
        local ok, err = pcall(function()
            H._beginDropNearTargetSession()
            if not H._ensureNearDropTarget() then return end
            if H._isHarvest(catKey) then H._runHarvestJob(goal, sel) else H._runGenericJob(goal, catKey, sel) end
        end)
        if not ok then H._setStatus("Error") end
        H._finish()
    end)
    return true, "started"
end

function M.DebugDropOne()
    if not H._ensureDropRemote() then return false end
    local t
    H._eachTool(function(x) if not t and H._isHarvestInst(x) then t = x end end)
    return t and H._dropHarvest({ uuid = H._fruitId(t), tool = t })
end

function M.DebugDropHarvest(count, delaySec)
    count = math.max(1, math.floor(tonumber(count) or 5))
    delaySec = math.max(0.05, tonumber(delaySec) or 0.3)
    if not H._ensureDropRemote() or not H._ensureBackpackNet() then return 0 end
    local entries = H._listHarvest({})
    local n, goal = 0, math.min(count, #entries)
    for i = 1, goal do
        if H._dropHarvest(entries[i]) then n += 1 end
        entries = H._listHarvest({})
        task.wait(delaySec)
    end
    return n
end

G.AutoDropModule, G.AutoDrop = M, M
rawset(_G, "AutoDropModule", M)
rawset(_G, "AutoDrop", M)

return M
 end,                       required = false },
    { key = "SectionAutoDrop",         name = "Section Auto Drop",       factory = function() -- section_auto_drop.lua — Drop Item UI (Gift / Drop tab)

local G = (getgenv and getgenv()) or _G
local M = {}

local saveNow, patchAutoOnly, getAutoFn, cleanSelectedMap, mapToArray, arrayToMap, registerFlush

function M.initBridge(bridge)
    if type(bridge) ~= "table" then return end
    saveNow = bridge.saveNow
    patchAutoOnly = bridge.patchAutoOnly
    getAutoFn = bridge.getAuto
    cleanSelectedMap = bridge.cleanSelectedMap
    mapToArray = bridge.mapToArray
    arrayToMap = bridge.arrayToMap
    registerFlush = bridge.registerFlush
end

local function _ensureBridge()
    if type(saveNow) ~= "function" or type(cleanSelectedMap) ~= "function" then
        error("SectionAutoDrop.initBridge belum dipanggil dari tabs_auto.lua")
    end
end

local function getAuto(key)
    if type(getAutoFn) == "function" then return getAutoFn(key) end
    local main = G.MAIN or rawget(_G, "MAIN")
    return type(main) == "table" and type(main.auto) == "table" and main.auto[key] or nil
end

local function _arrayToMap(arr)
    if type(arrayToMap) == "function" then return arrayToMap(arr) end
    local m = {}
    if type(arr) == "table" then
        for _, v in ipairs(arr) do
            if v ~= nil and tostring(v) ~= "" then m[tostring(v)] = true end
        end
        if next(m) then return m end
        for k, v in pairs(arr) do
            if v == true or v == 1 or v == "true" then m[tostring(k)] = true end
        end
    end
    return m
end

if type(G.__GAG2_AUTO_DROP) ~= "table" then
    G.__GAG2_AUTO_DROP = {
        category = "Seeds", selected = {}, drop_total = 1, drop_delay_sec = 0.08,
        target_user_id = 0, target_name = "", teleport_to_target = true,
    }
end
_G.__GAG2_AUTO_DROP = G.__GAG2_AUTO_DROP

local ensureDropStore

local function getNormalGift()
    return G.NormalGiftModule or G.NormalGift or _G.NormalGiftModule or _G.NormalGift
end

local function getAutoDrop()
    return G.AutoDropModule or G.AutoDrop or _G.AutoDropModule or _G.AutoDrop
end

local function safeDdGetSelected(api)
    if type(api) ~= "table" or type(api.getSelected) ~= "function" then return nil end
    local ok, sel = pcall(api.getSelected, api)
    if ok then return sel end
    ok, sel = pcall(api.getSelected)
    if ok then return sel end
    return nil
end

local function normalizeSelected(map)
    local out = cleanSelectedMap(map or {})
    if next(out) then return out end
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" or v == "1" then
            out[tostring(k)] = true
        end
    end
    for _, v in ipairs(map) do
        if v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    return out
end

local function countSelected(map)
    map = normalizeSelected(map or {})
    local n = 0
    for k, v in pairs(map) do
        if v == true and k ~= "_none" then n += 1 end
    end
    return n
end

local function isHarvestCat(cat)
    cat = tostring(cat or ""):lower():gsub("[%s_]+", "")
    return cat == "harvestedfruits" or cat == "harvestedfruit" or cat == "harvestedfruid"
end

local function isPetDropCat(cat)
    cat = tostring(cat or ""):lower():gsub("[%s_]+", "")
    return cat == "pets" or cat == "birds" or cat == "tools"
end

local function readDropCategory()
    local catDd = G.__GAG2_AUTO_DROP_CAT_DD or rawget(_G, "__GAG2_AUTO_DROP_CAT_DD")
    if type(catDd) == "table" and type(catDd.getSelected) == "function" then
        local ok, sel = pcall(catDd.getSelected, catDd)
        if not ok then ok, sel = pcall(catDd.getSelected) end
        if ok and sel ~= nil and tostring(sel) ~= "" and tostring(sel) ~= "_none" then
            G.__GAG2_AUTO_DROP_ACTIVE_CAT = tostring(sel)
            _G.__GAG2_AUTO_DROP_ACTIVE_CAT = G.__GAG2_AUTO_DROP_ACTIVE_CAT
            return tostring(sel)
        end
    end
    local active = G.__GAG2_AUTO_DROP_ACTIVE_CAT or rawget(_G, "__GAG2_AUTO_DROP_ACTIVE_CAT")
    if active ~= nil and tostring(active) ~= "" and tostring(active) ~= "_none" then
        return tostring(active)
    end
    return tostring(ensureDropStore().category or "Seeds")
end

local function buildDropItemList(cat)
    cat = tostring(cat or readDropCategory() or "Seeds")
    if cat == "" or cat == "_none" then return {} end
    local ng = getNormalGift()
    if type(ng) == "table" and type(ng.GetItemsForCategory) == "function" then
        local ok, list = pcall(ng.GetItemsForCategory, ng, cat)
        if ok and type(list) == "table" and #list > 0 then
            return list
        end
    end
    if isHarvestCat(cat) then
        local ad = getAutoDrop()
        if type(ad) == "table" and type(ad.GetHarvestItemLabels) == "function" then
            local ok, list = pcall(ad.GetHarvestItemLabels, ad)
            if ok and type(list) == "table" then return list end
        end
    end
    if isPetDropCat(cat) then
        local ad = getAutoDrop()
        if type(ad) == "table" and type(ad.GetPetItemLabels) == "function" then
            local ok, list = pcall(ad.GetPetItemLabels, ad)
            if ok and type(list) == "table" then return list end
        end
        local ag = G.AutoGiftModule or G.AutoGift or rawget(_G, "AutoGiftModule") or rawget(_G, "AutoGift")
        if type(ag) == "table" and type(ag.BuildInventoryItems) == "function" then
            local canon = (tostring(cat):lower() == "tools") and "Pets" or cat
            local ok, list = pcall(ag.BuildInventoryItems, ag, canon)
            if ok and type(list) == "table" then return list end
        end
    end
    if type(ng) == "table" and type(ng.GetItemsForCategory) == "function" then
        local ok, list = pcall(ng.GetItemsForCategory, ng, cat)
        if ok and type(list) == "table" then return list end
    end
    return {}
end

local function resolveDropSelection(itemDd, cat)
    local store = ensureDropStore()
    local sel = normalizeSelected(store.selected)

    if type(itemDd) == "table" and type(itemDd.getSelected) == "function" then
        local raw = safeDdGetSelected(itemDd)
        if type(raw) == "table" then
            local fromUi = normalizeSelected(raw)
            if countSelected(fromUi) > 0 then
                sel = fromUi
            end
        elseif raw ~= nil and tostring(raw) ~= "" then
            sel = { [tostring(raw)] = true }
        end
    end

    local mainDrop = getAuto("dropItem")
    if countSelected(sel) < 1 and type(mainDrop) == "table" and type(mainDrop.selected) == "table" then
        local fromMain = normalizeSelected(_arrayToMap(mainDrop.selected))
        if countSelected(fromMain) > 0 then
            sel = fromMain
        end
    end

    return sel
end

local function resolveDropTarget(key)
    key = tostring(key or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if key == "" then return 0, "", nil end

    local PlayersSvc = game:GetService("Players")
    local uid = math.floor(tonumber(key) or 0)
    if uid > 0 then
        local p = PlayersSvc:GetPlayerByUserId(uid)
        if p and p ~= PlayersSvc.LocalPlayer then
            return p.UserId, p.Name, p
        end
    end

    local lower = key:lower():gsub("^@", "")
    for _, p in ipairs(PlayersSvc:GetPlayers()) do
        if p ~= PlayersSvc.LocalPlayer then
            local label = p.DisplayName .. " (@" .. p.Name .. ")"
            if p.Name:lower() == lower
                or p.DisplayName:lower() == lower
                or label:lower() == lower
                or label:lower():find(lower, 1, true)
                or lower:find(p.Name:lower(), 1, true) then
                return p.UserId, p.Name, p
            end
        end
    end

    local ng = getNormalGift()
    if type(ng) == "table" and type(ng.ListServerPlayers) == "function" then
        local ok, list = pcall(ng.ListServerPlayers, ng)
        if ok and type(list) == "table" then
            for _, item in ipairs(list) do
                local itemKey = tostring(item.key or "")
                if itemKey == key or itemKey:lower() == lower then
                    local pid = math.floor(tonumber(item.userId or itemKey) or 0)
                    if pid > 0 then
                        local p = PlayersSvc:GetPlayerByUserId(pid)
                        if p then return p.UserId, p.Name, p end
                    end
                end
                local itemName = tostring(item.name or ""):lower()
                if itemName == lower or itemName:find(lower, 1, true) then
                    local pid = math.floor(tonumber(item.userId or item.key) or 0)
                    if pid > 0 then
                        local p = PlayersSvc:GetPlayerByUserId(pid)
                        if p then return p.UserId, p.Name, p end
                    end
                end
            end
        end
    end

    return 0, "", nil
end

local function buildDropPlayerItems()
    local ng = getNormalGift()
    if type(ng) == "table" and type(ng.ListServerPlayers) == "function" then
        local ok, list = pcall(ng.ListServerPlayers, ng)
        if ok and type(list) == "table" then return list end
    end
    return {}
end

local function readDropTeleportToggle()
    local api = G.__GAG2_AUTO_DROP_TP_TOGGLE_API or rawget(_G, "__GAG2_AUTO_DROP_TP_TOGGLE_API")
    if type(api) == "table" and type(api.get) == "function" then
        local ok, v = pcall(api.get, api)
        if ok and v ~= nil then return v == true end
    end
    return nil
end

local function applyDropRuntime()
    local ad = getAutoDrop()
    local s = ensureDropStore()
    if type(ad) == "table" and type(ad.ApplyConfig) == "function" then
        pcall(ad.ApplyConfig, ad, s)
    end
end

ensureDropStore = function()
    local s = G.__GAG2_AUTO_DROP
    if type(s) ~= "table" then
        s = {
            category = "Seeds", selected = {}, drop_total = 1, drop_delay_sec = 0.08,
            target_user_id = 0, target_name = "", teleport_to_target = true,
        }
    end
    s.category = tostring(s.category or "Seeds")
    if s.category == "" then s.category = "Seeds" end
    s.selected = normalizeSelected(s.selected or {})
    s.drop_total = math.max(1, math.floor(tonumber(s.drop_total) or 1))
    local delay = tonumber(s.drop_delay_sec)
    if delay == nil then delay = 0.08 end
    if delay < 0 then delay = 0 end
    if delay > 30 then delay = 30 end
    s.drop_delay_sec = delay
    s.target_user_id = math.floor(tonumber(s.target_user_id) or 0)
    s.target_name = tostring(s.target_name or "")
    if s.teleport_to_target == nil then s.teleport_to_target = true end
    s.teleport_to_target = (s.teleport_to_target == true)

    if not s._hydrated then
        local mainDrop = getAuto("dropItem")
        if type(mainDrop) == "table" then
            if mainDrop.category ~= nil and tostring(mainDrop.category) ~= "" then
                s.category = tostring(mainDrop.category)
            end
            if type(mainDrop.selected) == "table" and next(mainDrop.selected) then
                s.selected = normalizeSelected(_arrayToMap(mainDrop.selected))
            end
            if mainDrop.drop_total ~= nil then
                s.drop_total = math.max(1, math.floor(tonumber(mainDrop.drop_total) or 1))
            end
            if mainDrop.drop_delay_sec ~= nil then
                s.drop_delay_sec = tonumber(mainDrop.drop_delay_sec)
                if s.drop_delay_sec == nil then s.drop_delay_sec = 0.08 end
            end
            if mainDrop.target_user_id ~= nil then
                s.target_user_id = math.floor(tonumber(mainDrop.target_user_id) or 0)
            end
            if mainDrop.target_name ~= nil then
                s.target_name = tostring(mainDrop.target_name or "")
            end
            if mainDrop.teleport_to_target ~= nil then
                s.teleport_to_target = (mainDrop.teleport_to_target == true)
            end
        end
        s._hydrated = true
    end
    if s._drop_pace ~= "v2" then
        local d = tonumber(s.drop_delay_sec)
        if d == 1 or d == 0.5 then s.drop_delay_sec = 0.08 end
        s._drop_pace = "v2"
    end

    G.__GAG2_AUTO_DROP = s
    _G.__GAG2_AUTO_DROP = s
    return s
end
G.__GAG2_ENSURE_AUTO_DROP_STORE = ensureDropStore
_G.__GAG2_ENSURE_AUTO_DROP_STORE = ensureDropStore

local function writeDropToMain()
    local s = ensureDropStore()
    patchAutoOnly("dropItem", {
        category = s.category,
        selected = mapToArray(s.selected),
        drop_total = s.drop_total,
        drop_delay_sec = s.drop_delay_sec,
        _drop_pace = s._drop_pace,
        target_user_id = s.target_user_id,
        target_name = s.target_name,
        teleport_to_target = s.teleport_to_target,
    })
    return s
end

local function writeDropState(opts)
    local s = ensureDropStore()
    if type(opts) == "table" then
        if opts.category ~= nil and tostring(opts.category) ~= "" then
            s.category = tostring(opts.category)
        end
        if type(opts.selected) == "table" then
            if opts.selected[1] ~= nil then
                s.selected = normalizeSelected(_arrayToMap(opts.selected))
            else
                s.selected = normalizeSelected(opts.selected)
            end
        end
        if opts.drop_total ~= nil then
            s.drop_total = math.max(1, math.floor(tonumber(opts.drop_total) or 1))
        end
        if opts.drop_delay_sec ~= nil then
            local d = tonumber(opts.drop_delay_sec)
            if d == nil then d = 0.08 end
            if d < 0 then d = 0 end
            if d > 30 then d = 30 end
            s.drop_delay_sec = d
            s._drop_pace = "v2"
        end
        if opts.target_user_id ~= nil then
            s.target_user_id = math.floor(tonumber(opts.target_user_id) or 0)
        end
        if opts.target_name ~= nil then
            s.target_name = tostring(opts.target_name or "")
        end
        if opts.teleport_to_target ~= nil then
            s.teleport_to_target = (opts.teleport_to_target == true)
        end
    end
    G.__GAG2_AUTO_DROP = s
    _G.__GAG2_AUTO_DROP = s
    return writeDropToMain()
end

local function patchDrop(opts, syncFn)
    writeDropState(opts)
    if syncFn then pcall(syncFn) end
    saveNow()
end

local function flushDropFromUI()
    if G.__GAG2_RESETTING == true then return end
    local opts = {}
    local cat = readDropCategory()
    if cat ~= "" and cat ~= "_none" then opts.category = cat end

    local itemDd = G.__GAG2_AUTO_DROP_ITEM_DD or rawget(_G, "__GAG2_AUTO_DROP_ITEM_DD")
    local sel = resolveDropSelection(itemDd, cat)
    if countSelected(sel) > 0 then opts.selected = sel end

    local totalFn = G.__GAG2_AUTO_DROP_TOTAL or rawget(_G, "__GAG2_AUTO_DROP_TOTAL")
    if type(totalFn) == "function" then
        local n = tonumber(totalFn())
        if n and n >= 1 then opts.drop_total = math.floor(n) end
    end

    local delayFn = G.__GAG2_AUTO_DROP_DELAY or rawget(_G, "__GAG2_AUTO_DROP_DELAY")
    if type(delayFn) == "function" then
        local d = tonumber(delayFn())
        if d ~= nil and d >= 0 then opts.drop_delay_sec = d end
    end

    local playerDd = G.__GAG2_AUTO_DROP_PLAYER_DD or rawget(_G, "__GAG2_AUTO_DROP_PLAYER_DD")
    local playerKey = safeDdGetSelected(playerDd)
    if playerKey ~= nil and tostring(playerKey) ~= "" then
        local uid, name = resolveDropTarget(playerKey)
        if uid > 0 then opts.target_user_id = uid end
        if name ~= "" then opts.target_name = name end
    end

    local tpOn = readDropTeleportToggle()
    if tpOn ~= nil then opts.teleport_to_target = tpOn end

    if next(opts) ~= nil then writeDropState(opts) else writeDropToMain() end
    applyDropRuntime()
end

local function runDropNow(isOn)
    local toggleApi = G.__GAG2_AUTO_DROP_TOGGLE_API or rawget(_G, "__GAG2_AUTO_DROP_TOGGLE_API")
    local ad = getAutoDrop()
    if isOn == false then
        if type(ad) == "table" and type(ad.Stop) == "function" then pcall(ad.Stop, ad) end
        return
    end

    local cat = readDropCategory()
    flushDropFromUI()
    local s = ensureDropStore()
    local itemDd = G.__GAG2_AUTO_DROP_ITEM_DD or rawget(_G, "__GAG2_AUTO_DROP_ITEM_DD")

    if isHarvestCat(cat) then
        if type(ad) == "table" and type(ad.PrepHarvest) == "function" then
            pcall(ad.PrepHarvest, ad, true)
        else
            local ng = getNormalGift()
            if type(ng) == "table" and type(ng.CollectCandidates) == "function" then
                pcall(ng.CollectCandidates, ng, "HarvestedFruits", {}, true)
            end
        end
    end
    if type(itemDd) == "table" and type(itemDd.refreshItems) == "function" then
        pcall(itemDd.refreshItems, itemDd)
    end

    local selMap = resolveDropSelection(itemDd, cat)

    if type(ad) ~= "table" or type(ad.RunNow) ~= "function" then
        G.AUTO_DROP_STATUS = "AutoDrop module not loaded"
        _G.AUTO_DROP_STATUS = G.AUTO_DROP_STATUS
        if type(toggleApi) == "table" and type(toggleApi.set) == "function" then
            pcall(toggleApi.set, false, true)
        end
        return
    end

    task.spawn(function()
        if type(ad.IsBusy) == "function" and ad:IsBusy() then
            if type(ad.Stop) == "function" then pcall(ad.Stop, ad) end
            if type(ad.WaitUntilIdle) == "function" then
                pcall(ad.WaitUntilIdle, ad, 3)
            end
            if ad:IsBusy() and type(ad.ForceReset) == "function" then
                pcall(ad.ForceReset, ad)
            end
        end

        local runCfg = {
            category = cat,
            selected = selMap,
            drop_total = s.drop_total,
            drop_delay_sec = s.drop_delay_sec,
            target_user_id = s.target_user_id,
            target_name = s.target_name,
            teleport_to_target = s.teleport_to_target,
        }

        local ok, err = pcall(function()
            local started, reason = ad:RunNow(runCfg)
            if started == true then
                writeDropToMain()
                saveNow()
                return
            end
            if reason == "busy" and type(ad.ForceReset) == "function" then
                pcall(ad.ForceReset, ad)
                started = ad:RunNow(runCfg)
                if started == true then
                    writeDropToMain()
                    saveNow()
                    return
                end
            end
            local msg = "Drop failed"
            if reason == "busy" then
                msg = "Drop busy — try again"
            elseif reason == "remote" then
                msg = "DroppedItem remote not ready"
            end
            if type(ad.GetStats) == "function" then
                local okSt, st = pcall(ad.GetStats, ad)
                if okSt and type(st) == "table" and st.lastStatus and st.lastStatus ~= "" then
                    msg = tostring(st.lastStatus)
                end
            end
            G.AUTO_DROP_STATUS = msg
            _G.AUTO_DROP_STATUS = G.AUTO_DROP_STATUS
            if type(toggleApi) == "table" and type(toggleApi.set) == "function" then
                pcall(toggleApi.set, false, true)
            end
        end)
        if not ok then
            G.AUTO_DROP_STATUS = "Drop error: " .. tostring(err)
            _G.AUTO_DROP_STATUS = G.AUTO_DROP_STATUS
            if type(ad.ForceReset) == "function" then pcall(ad.ForceReset, ad) end
            if type(toggleApi) == "table" and type(toggleApi.set) == "function" then
                pcall(toggleApi.set, false, true)
            end
        end
    end)
end

local function syncDropAll()
    if G.__GAG2_RESETTING == true then
        writeDropToMain()
        return
    end
    if G.__GAG2_AUTO_DROP_UI_READY == true then
        flushDropFromUI()
    else
        writeDropToMain()
        applyDropRuntime()
    end
end

G.__GAG2_SYNC_AUTO_DROP = syncDropAll
G.__GAG2_FLUSH_AUTO_DROP = flushDropFromUI
_G.__GAG2_SYNC_AUTO_DROP = syncDropAll
_G.__GAG2_FLUSH_AUTO_DROP = flushDropFromUI

function M.initStore()
    _ensureBridge()
    registerFlush("dropItem", flushDropFromUI)
    ensureDropStore()
end

function M.RegisterSubTab(ui)
    if type(ui) ~= "table" then return end
    _ensureBridge()

    G.__GAG2_AUTO_DROP_UI_READY = false
    _G.__GAG2_AUTO_DROP_UI_READY = false

    local DROP = ensureDropStore()
    local bodyDrop = ui:CreateSection("Drop Item", false)

    local _, dropStatusLabel = ui:CreateRowLabel(bodyDrop, "Status: Ready", nil, nil, "info")
    task.spawn(function()
        while dropStatusLabel and dropStatusLabel.Parent do
            pcall(function()
                local txt = "Ready"
                local ad = getAutoDrop()
                if type(ad) == "table" and type(ad.GetStats) == "function" then
                    local okSt, st = pcall(ad.GetStats, ad)
                    if okSt and type(st) == "table" then
                        if st.busy and st.lastStatus and st.lastStatus ~= "" then
                            txt = st.lastStatus
                        elseif not st.busy then
                            local g = tostring(G.AUTO_DROP_STATUS or rawget(_G, "AUTO_DROP_STATUS") or "")
                            if g ~= "" and g ~= "Ready" then txt = g
                            elseif st.lastStatus and st.lastStatus ~= "" and st.lastStatus ~= "Ready" then
                                txt = st.lastStatus
                            end
                        end
                    end
                end
                dropStatusLabel.Text = "Status: " .. txt
            end)
            task.wait(0.4)
        end
    end)

    local dropPlayerInitial = (DROP.target_user_id > 0) and tostring(DROP.target_user_id) or nil
    local _, dropPlayerDd = ui:CreateRowDropdown(bodyDrop, {
        label = "Player",
        placeholder = "Select player in server...",
        mode = "single",
        getItems = buildDropPlayerItems,
        initial = dropPlayerInitial,
        onChanged = function(_, key)
            local uid, name = resolveDropTarget(key)
            patchDrop({
                target_user_id = uid,
                target_name = name,
            }, function()
                applyDropRuntime()
            end)
        end,
    })
    G.__GAG2_AUTO_DROP_PLAYER_DD = dropPlayerDd
    _G.__GAG2_AUTO_DROP_PLAYER_DD = dropPlayerDd

    local function buildCatItems()
        local seen = {}
        local items = {}

        local function addCat(key, name)
            key = tostring(key or "")
            if key == "" or key == "_none" or seen[key] then return end
            seen[key] = true
            items[#items + 1] = { key = key, name = tostring(name or key) }
        end

        local ng = getNormalGift()
        if type(ng) == "table" and type(ng.GetCategoryDefs) == "function" then
            local ok, defs = pcall(ng.GetCategoryDefs, ng)
            if ok and type(defs) == "table" then
                for _, def in ipairs(defs) do
                    addCat(def.key, def.label or def.key)
                end
            end
        end

        local ag = G.AutoGiftModule or G.AutoGift or rawget(_G, "AutoGiftModule") or rawget(_G, "AutoGift")
        if type(ag) == "table" and type(ag.GetCategoryDefs) == "function" then
            local ok, defs = pcall(ag.GetCategoryDefs, ag)
            if ok and type(defs) == "table" then
                for _, def in ipairs(defs) do
                    local key = tostring(def.key or def.name or "")
                    if isPetDropCat(key) then
                        addCat("Pets", "Pets")
                    else
                        addCat(key, def.label or def.name or key)
                    end
                end
            end
        end

        addCat("Pets", "Pets")

        if #items == 0 then
            addCat("Seeds", "Seeds")
        end

        table.sort(items, function(a, b) return tostring(a.name) < tostring(b.name) end)
        return items
    end

    local _, dropCatDd = ui:CreateRowDropdown(bodyDrop, {
        label = "Category",
        placeholder = "Seeds",
        mode = "single",
        getItems = buildCatItems,
        initial = DROP.category,
        onChanged = function(_, key)
            key = tostring(key or "Seeds")
            if key == "_none" then return end
            G.__GAG2_AUTO_DROP_ACTIVE_CAT = key
            _G.__GAG2_AUTO_DROP_ACTIVE_CAT = key
            patchDrop({ category = key, selected = {} }, function()
                local itemDd = G.__GAG2_AUTO_DROP_ITEM_DD or rawget(_G, "__GAG2_AUTO_DROP_ITEM_DD")
                if type(itemDd) == "table" and type(itemDd.setSelected) == "function" then
                    pcall(itemDd.setSelected, {})
                end
                if type(itemDd) == "table" and type(itemDd.refreshItems) == "function" then
                    pcall(itemDd.refreshItems, itemDd)
                end
            end)
        end,
    })
    G.__GAG2_AUTO_DROP_CAT_DD = dropCatDd
    _G.__GAG2_AUTO_DROP_CAT_DD = dropCatDd

    local dropItemInitial = normalizeSelected(DROP.selected)
    local _, dropItemDd = ui:CreateRowDropdown(bodyDrop, {
        label = "Items",
        placeholder = "Empty = drop all in category",
        mode = "multi",
        deferItemLoad = true,
        labelForKey = function(key)
            for _, it in ipairs(buildDropItemList(readDropCategory())) do
                if tostring(it.key or "") == tostring(key) then
                    return tostring(it.name or key)
                end
            end
            return tostring(key or "")
        end,
        getItems = function()
            return buildDropItemList(readDropCategory())
        end,
        initial = dropItemInitial,
        onChanged = function(_, selectedMap)
            patchDrop({ selected = normalizeSelected(selectedMap) })
        end,
    })
    G.__GAG2_AUTO_DROP_ITEM_DD = dropItemDd
    _G.__GAG2_AUTO_DROP_ITEM_DD = dropItemDd

    G.__GAG2_AUTO_DROP_ACTIVE_CAT = DROP.category
    _G.__GAG2_AUTO_DROP_ACTIVE_CAT = DROP.category

    if type(dropCatDd.setSelected) == "function" then pcall(dropCatDd.setSelected, DROP.category) end
    if type(dropItemDd.setSelected) == "function" then pcall(dropItemDd.setSelected, dropItemInitial) end

    local _, dropTotalSetFn = ui:CreateRowInput(bodyDrop, "Total", tostring(DROP.drop_total or 1), function(txt)
        local n = tonumber(txt)
        if n and n >= 1 then patchDrop({ drop_total = math.floor(n) }) end
    end, false)
    G.__GAG2_AUTO_DROP_TOTAL = dropTotalSetFn
    _G.__GAG2_AUTO_DROP_TOTAL = dropTotalSetFn

    local _, dropDelaySetFn = ui:CreateRowInput(bodyDrop, "Delay (sec)", tostring(DROP.drop_delay_sec or 0.08), function(txt)
        local d = tonumber(txt)
        if d ~= nil and d >= 0 then patchDrop({ drop_delay_sec = d }) end
    end, false)
    G.__GAG2_AUTO_DROP_DELAY = dropDelaySetFn
    _G.__GAG2_AUTO_DROP_DELAY = dropDelaySetFn

    local _, _, dropTpToggleApi = ui:CreateRowToggle(
        bodyDrop,
        "Teleport to target",
        DROP.teleport_to_target ~= false,
        function(isOn)
            patchDrop({ teleport_to_target = isOn == true }, function()
                applyDropRuntime()
            end)
        end
    )
    G.__GAG2_AUTO_DROP_TP_TOGGLE_API = dropTpToggleApi
    _G.__GAG2_AUTO_DROP_TP_TOGGLE_API = dropTpToggleApi

    local dropToggleApi
    local _, _, dropStopApi = ui:CreateRowToggle(bodyDrop, "Stop", false, function(isOn)
        if isOn ~= true then return end
        runDropNow(false)
        if type(dropToggleApi) == "table" and type(dropToggleApi.set) == "function" then
            pcall(dropToggleApi.set, false, true)
        end
    end, nil, nil, true)
    G.__GAG2_AUTO_DROP_STOP_API = dropStopApi
    _G.__GAG2_AUTO_DROP_STOP_API = dropStopApi

    local _, _, sendApi = ui:CreateRowToggle(bodyDrop, "Send", false, function(isOn)
        runDropNow(isOn == true)
    end)
    dropToggleApi = sendApi
    G.__GAG2_AUTO_DROP_TOGGLE_API = dropToggleApi
    _G.__GAG2_AUTO_DROP_TOGGLE_API = dropToggleApi

    G.__GAG2_AUTO_DROP_DONE = function(_ok)
        local api = G.__GAG2_AUTO_DROP_TOGGLE_API or rawget(_G, "__GAG2_AUTO_DROP_TOGGLE_API")
        if type(api) == "table" and type(api.set) == "function" then
            pcall(api.set, false, true)
        end
    end
    _G.__GAG2_AUTO_DROP_DONE = G.__GAG2_AUTO_DROP_DONE

    if dropPlayerInitial and type(dropPlayerDd.setSelected) == "function" then
        pcall(dropPlayerDd.setSelected, dropPlayerInitial)
    end
    if type(dropTpToggleApi) == "table" and type(dropTpToggleApi.set) == "function" then
        pcall(dropTpToggleApi.set, DROP.teleport_to_target == true, true)
    end

    G.__GAG2_AUTO_DROP_UI_READY = true
    _G.__GAG2_AUTO_DROP_UI_READY = true
    syncDropAll()

    task.defer(function()
        task.wait(0.6)
        if type(dropItemDd.refreshItems) == "function" then pcall(dropItemDd.refreshItems, dropItemDd) end
        if countSelected(dropItemInitial) > 0 and type(dropItemDd.setSelected) == "function" then
            pcall(dropItemDd.setSelected, dropItemInitial)
        end
    end)
end

G.SectionAutoDrop = M
_G.SectionAutoDrop = M
return M
 end,            required = false },
