    }
    G.PlantListView = PlantListView

    ----------------------------------------------------------------
    -- UI ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬Â State bridge (MAIN.auto.* via State API)
    ----------------------------------------------------------------
    local function getState()
        return G.__GAG2_STATE or rawget(_G, "__GAG2_STATE")
    end

    local _mainFallbackWarned = false

    local function ensureMain()
        local State = getState()
        if type(State) == "table" and type(State.getMain) == "function" then
            local ok, m = pcall(State.getMain)
            if ok and type(m) == "table" then
                G.MAIN = m
                _G.MAIN = m
                return m
            end
            if not ok and not _mainFallbackWarned then
                warn("[GAG2] State.getMain error:", tostring(m))
            end
        end

        local m = rawget(_G, "MAIN") or G.MAIN
        if type(m) == "table" then
            G.MAIN = m
            _G.MAIN = m
            return m
        end

        if not _mainFallbackWarned then
            _mainFallbackWarned = true
            warn("[GAG2] state.lua belum load â€” UI jalan tanpa save/load. Upload state.lua ke server.")
        end
        m = { auto = {}, misc = {} }
        G.MAIN = m
        _G.MAIN = m
        return m
    end

    local function saveNow()
        if G.__GAG2_RESETTING == true then return end
        local State = getState()
        if type(State) == "table" and type(State.saveFromUi) == "function" then
            pcall(State.saveFromUi)
            return
        end
        if type(G.__GAG2_STATE_SAVE) == "function" then
            pcall(G.__GAG2_STATE_SAVE)
        elseif ui and type(ui.SaveState) == "function" then
            pcall(function() ui:SaveState() end)
        end
    end

    local function getAuto(key)
        local State = getState()
        if type(State) == "table" and type(State.getAuto) == "function" then
            local ok, result = pcall(State.getAuto, key)
            if ok and type(result) == "table" then return result end
        end
        local m = ensureMain()
        if type(m) == "table" and type(m.auto) == "table" then
            return m.auto[key] or {}
        end
        return {}
    end

    local function patchAuto(key, partial, syncFn)
        local State = getState()
        if type(State) == "table" and type(State.patchAuto) == "function" then
            pcall(State.patchAuto, key, partial)
        else
            local m = ensureMain()
            if type(m) == "table" and type(partial) == "table" then
                m.auto = m.auto or {}
                local cur = type(m.auto[key]) == "table" and m.auto[key] or {}
                for k, v in pairs(partial) do cur[k] = v end
                m.auto[key] = cur
                G.MAIN = m
                _G.MAIN = m
            end
        end
        if syncFn then pcall(syncFn) end
        saveNow()
    end

    local function registerFlush(id, fn)
        local State = getState()
        if type(State) == "table" and type(State.registerFlush) == "function" then
            pcall(State.registerFlush, id, fn)
        end
    end

    local function autoSave()
        saveNow()
    end

    G.__GAG2_AUTO_SAVE = autoSave
    G.__GAG2_PERSIST_STATE = saveNow
    _G.__GAG2_PERSIST_STATE = saveNow

    local function toggleApiGet(apiKey)
        local api = G[apiKey] or rawget(_G, apiKey)
        if type(api) == "table" and type(api.get) == "function" then
            return api.get() == true
        end
        return nil
    end

    local function persistDisk()
        if G.__GAG2_RESETTING == true then return end
        if G.__GAG2_SAVING_FROM_UI == true then return end
        local State = getState()
        if type(State) == "table" and type(State.persistDisk) == "function" then
            pcall(State.persistDisk)
        elseif type(State) == "table" and type(State.save) == "function" then
            pcall(State.save)
        end
    end

    local function patchAutoOnly(key, partial, skipDisk)
        local State = getState()
        if type(State) == "table" and type(State.patchAuto) == "function" then
            pcall(State.patchAuto, key, partial, { noSync = true })
        else
            local m = ensureMain()
            if type(m) == "table" and type(partial) == "table" then
                m.auto = m.auto or {}
                local cur = type(m.auto[key]) == "table" and m.auto[key] or {}
                for k, v in pairs(partial) do cur[k] = v end
                m.auto[key] = cur
                G.MAIN = m
                _G.MAIN = m
            end
        end
        if skipDisk ~= true then
            persistDisk()
        end
    end

    local function registerToggleFlush(id, autoKey, apiKey, field)
        field = field or "enabled"
        registerFlush(id, function()
            local on = toggleApiGet(apiKey)
            if on == nil then
                local st = getAuto(autoKey)
                if type(st) == "table" then
                    on = (st[field] == true)
                end
            end
            if on == nil then return end
            local State = getState()
            if type(State) == "table" and type(State.patchAuto) == "function" then
                local patch = {}
                patch[field] = on
                pcall(State.patchAuto, autoKey, patch, { noSync = true })
            end
        end)
    end

    local function getMainRef()
        return ensureMain()
    end

    ----------------------------------------------------------------
    -- Auto Claim Seed ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â state persist (survive tab rebuild)
    ----------------------------------------------------------------
    if type(G.__GAG2_CLAIM_SEED) ~= "table" then
        G.__GAG2_CLAIM_SEED = { enabled = false }
    end
    _G.__GAG2_CLAIM_SEED = G.__GAG2_CLAIM_SEED

    local function readClaimSeedEnabled()
        local cs = getAuto("claimSeed")
        if type(cs) == "table" then
            return cs.enabled == true
        end
        local store = G.__GAG2_CLAIM_SEED or rawget(_G, "__GAG2_CLAIM_SEED")
        if type(store) == "table" then
            return store.enabled == true
        end
        return false
    end

    local function _syncClaimSeedGlobals(on)
        on = (on == true)
        if type(G.__GAG2_CLAIM_SEED) ~= "table" then G.__GAG2_CLAIM_SEED = {} end
        G.__GAG2_CLAIM_SEED.enabled = on
        _G.__GAG2_CLAIM_SEED = G.__GAG2_CLAIM_SEED
        AUTO_CLAIM_SEED_ENABLED = on
        G.AUTO_CLAIM_SEED_ENABLED = on
        _G.AUTO_CLAIM_SEED_ENABLED = on
        return on
    end

    local function writeClaimSeedState(on)
        on = _syncClaimSeedGlobals(on)
        local State = getState()
        if type(State) == "table" and type(State.patchAuto) == "function" then
            pcall(State.patchAuto, "claimSeed", { enabled = on }, { noSync = true })
        else
            local m = getMainRef()
            if type(m) == "table" then
                m.auto = m.auto or {}
                m.auto.claimSeed = type(m.auto.claimSeed) == "table" and m.auto.claimSeed or { enabled = false }
                m.auto.claimSeed.enabled = on
                G.MAIN = m
                _G.MAIN = m
            end
        end
        persistDisk()
        return on
    end

    local function applyClaimSeedModuleOnly(on)
        on = (on == true)
        local acs = G.AutoClaimSeed or G.AutoClaimSeedModule or rawget(_G, "AutoClaimSeed")
        if type(acs) ~= "table" or next(acs) == nil then
            warn("[GAG2] Auto Claim Seed module belum loaded â€” re-execute hub")
            return
        end

        -- SetEnabled/ApplyRuntime cuma terima (on), jangan pass module sebagai arg pertama
        if type(acs.SetEnabled) == "function" then
            pcall(acs.SetEnabled, on)
        elseif type(acs.ApplyRuntime) == "function" then
            pcall(acs.ApplyRuntime, on)
        elseif on then
            if type(acs.EnsureRunning) == "function" then
                pcall(acs.EnsureRunning)
            elseif type(acs.Start) == "function" then
                pcall(acs.Start)
            end
        else
            if type(acs.Stop) == "function" then pcall(acs.Stop) end
        end
    end

    local function applyClaimSeedRuntime(on)
        on = (on == true)
        writeClaimSeedState(on)
        applyClaimSeedModuleOnly(on)
    end

    local function syncAutoClaimSeedAll()
        local on = readClaimSeedEnabled()
        _syncClaimSeedGlobals(on)
        local acs = G.AutoClaimSeed or G.AutoClaimSeedModule or rawget(_G, "AutoClaimSeed")
        if type(acs) == "table" and next(acs) ~= nil and on and type(acs.EnsureRunning) == "function" then
            pcall(acs.EnsureRunning)
            return
        end
        applyClaimSeedModuleOnly(on)
    end

    local function saveClaimSeedNow()
        saveNow()
    end

    local function persistClaimSeedBeforeTabChange()
        local toggleOn = toggleApiGet("__GAG2_CLAIM_SEED_TOGGLE_API")
        if toggleOn ~= nil then
            writeClaimSeedState(toggleOn == true)
            return
        end
        writeClaimSeedState(readClaimSeedEnabled())
    end

    local function flushClaimSeedState()
        local toggleOn = toggleApiGet("__GAG2_CLAIM_SEED_TOGGLE_API")
        if toggleOn == nil then return end
        writeClaimSeedState(toggleOn == true)
    end

    registerFlush("claimSeed", flushClaimSeedState)

    G.__GAG2_READ_CLAIM_SEED = readClaimSeedEnabled
    G.__GAG2_WRITE_CLAIM_SEED = writeClaimSeedState
    G.__GAG2_SYNC_AUTO_CLAIM_SEED = syncAutoClaimSeedAll
    G.__GAG2_FLUSH_CLAIM_SEED = flushClaimSeedState
    G.__GAG2_PERSIST_CLAIM_SEED = persistClaimSeedBeforeTabChange
    _G.__GAG2_READ_CLAIM_SEED = readClaimSeedEnabled
    _G.__GAG2_WRITE_CLAIM_SEED = writeClaimSeedState
    _G.__GAG2_SYNC_AUTO_CLAIM_SEED = syncAutoClaimSeedAll
    _G.__GAG2_FLUSH_CLAIM_SEED = flushClaimSeedState
    _G.__GAG2_PERSIST_CLAIM_SEED = persistClaimSeedBeforeTabChange

    ----------------------------------------------------------------
    -- Auto Tele
    ----------------------------------------------------------------
    local function writeAutoTeleToMain()
        local tele = getAuto("autoTele")
        tele = type(tele) == "table" and tele or {}
        G.AUTO_TELE_ENABLED = (tele.enabled == true)
        _G.AUTO_TELE_ENABLED = G.AUTO_TELE_ENABLED
        G.__GAG2_AUTO_TELE = {
            enabled = tele.enabled == true,
            delay = tonumber(tele.delay) or 10,
            selectedLocation = tostring(tele.selectedLocation or "center"),
            hitWerewolf = tele.hitWerewolf == true,
        }
        _G.__GAG2_AUTO_TELE = G.__GAG2_AUTO_TELE
        return tele
    end

    local function readAutoTeleEnabled()
        local tele = getAuto("autoTele")
        return type(tele) == "table" and tele.enabled == true
    end

    local function readAutoTeleHitWerewolf()
        local tele = getAuto("autoTele")
        return type(tele) == "table" and tele.hitWerewolf == true
    end

    local function applyAutoTeleRuntime(on)
        on = (on == true)
        local State = getState()
        if type(State) == "table" and type(State.patchAuto) == "function" then
            pcall(State.patchAuto, "autoTele", { enabled = on })
        end
        writeAutoTeleToMain()

        local at = G.AutoTele or rawget(_G, "AutoTele")
        if type(at) ~= "table" then return end
        if type(at.SetEnabled) == "function" then
            pcall(at.SetEnabled, at, on)
        elseif type(at.ApplyRuntime) == "function" then
            pcall(at.ApplyRuntime, at, on)
        end
    end

    local function applyAutoTeleHitWerewolfRuntime(on)
        on = (on == true)
        local State = getState()
        if type(State) == "table" and type(State.patchAuto) == "function" then
            pcall(State.patchAuto, "autoTele", { hitWerewolf = on })
        end
        writeAutoTeleToMain()

        local at = G.AutoTele or rawget(_G, "AutoTele")
        if type(at) ~= "table" then return end
        if type(at.SetHitWerewolf) == "function" then
            pcall(at.SetHitWerewolf, on)
        elseif type(at.ApplyHitWerewolf) == "function" then
            pcall(at.ApplyHitWerewolf, on)
        end
    end

    local function syncAutoTeleAll()
        writeAutoTeleToMain()
        local on = readAutoTeleEnabled()
        local hitWw = readAutoTeleHitWerewolf()

        local at = G.AutoTele or rawget(_G, "AutoTele")
        if type(at) == "table" then
            if on or hitWw then
                if type(at.EnsureRunning) == "function" then
                    pcall(at.EnsureRunning)
                    return
                end
            elseif type(at.Stop) == "function" then
                pcall(at.Stop)
                return
            end
        end
        applyAutoTeleRuntime(on)
    end

    local function saveAutoTeleNow()
        writeAutoTeleToMain()
        saveNow()
    end

    registerToggleFlush("autoTele", "autoTele", "__GAG2_TELE_ENABLE_TOGGLE_API")
    registerToggleFlush("autoTeleHitWw", "autoTele", "__GAG2_TELE_HIT_WW_TOGGLE_API", "hitWerewolf")

    local function flushAutoTeleState()
        local on = toggleApiGet("__GAG2_TELE_ENABLE_TOGGLE_API")
        local hitWw = toggleApiGet("__GAG2_TELE_HIT_WW_TOGGLE_API")
        local State = getState()
        if type(State) == "table" and type(State.patchAuto) == "function" then
            local partial = {}
            if on ~= nil then partial.enabled = on end
            if hitWw ~= nil then partial.hitWerewolf = hitWw end
            if next(partial) ~= nil then
                pcall(State.patchAuto, "autoTele", partial, { noSync = true })
            end
        end
        writeAutoTeleToMain()
    end

    local function restartAutoTeleIfOn()
        writeAutoTeleToMain()
        if not (readAutoTeleEnabled() or readAutoTeleHitWerewolf()) then return end
        local at = G.AutoTele or rawget(_G, "AutoTele")
        if type(at) ~= "table" then return end
        if type(at.InvalidateCache) == "function" then
            pcall(at.InvalidateCache)
        end
        if type(at.EnsureRunning) == "function" then
            pcall(at.EnsureRunning)
        elseif type(at.ApplyRuntime) == "function" then
            pcall(at.ApplyRuntime, readAutoTeleEnabled())
        end
        if readAutoTeleEnabled() and type(at.TeleportNow) == "function" then
            pcall(at.TeleportNow)
        end
    end

    G.__GAG2_SYNC_AUTO_TELE = syncAutoTeleAll
    G.__GAG2_SAVE_AUTO_TELE = saveAutoTeleNow
    G.__GAG2_WRITE_AUTO_TELE_MAIN = writeAutoTeleToMain
    G.__GAG2_READ_AUTO_TELE = readAutoTeleEnabled
    G.__GAG2_FLUSH_AUTO_TELE = flushAutoTeleState
    _G.__GAG2_SYNC_AUTO_TELE = syncAutoTeleAll
    _G.__GAG2_SAVE_AUTO_TELE = saveAutoTeleNow
    _G.__GAG2_WRITE_AUTO_TELE_MAIN = writeAutoTeleToMain
    _G.__GAG2_READ_AUTO_TELE = readAutoTeleEnabled
    _G.__GAG2_FLUSH_AUTO_TELE = flushAutoTeleState

    ----------------------------------------------------------------
    -- helpers (shared)
    ----------------------------------------------------------------
    local function cleanSelectedMap(selectedMap)
        local out = {}
        if type(selectedMap) ~= "table" then
            return out
        end
        for k, v in pairs(selectedMap) do
            if v == true then
                out[tostring(k)] = true
            elseif type(k) == "number" and (type(v) == "string" or type(v) == "number") then
                local s = tostring(v)
                if s ~= "" then out[s] = true end
            elseif type(k) == "number" and type(v) == "table" then
                local kk = v.key or v.name or v.id
                if kk then out[tostring(kk)] = true end
            elseif type(k) == "string" and type(v) == "table" then
                out[tostring(k)] = true
            end
        end
        return out
    end

    local function mapToArray(map)
        local arr = {}
        if type(map) == "table" then
            for k, v in pairs(map) do
                if v == true then
                    arr[#arr + 1] = tostring(k)
                end
            end
        end
        table.sort(arr)
        return arr
    end

    local function arrayToMap(arr)
        local m = {}
        if type(arr) == "table" then
            for _, v in ipairs(arr) do
                if v ~= nil and tostring(v) ~= "" then
                    m[tostring(v)] = true
                end
            end
            if next(m) then return m end
            for k, v in pairs(arr) do
                if v == true or v == 1 or v == "true" then
                    m[tostring(k)] = true
                end
            end
        end
        return m
    end

    ----------------------------------------------------------------
    -- Pet tab persist (dragonEgg + sellPet + favPet/unfavPet) — flush even when Pet sub-tab closed
    ----------------------------------------------------------------
    local function readDragonEggEnabled()
        local on = toggleApiGet("__GAG2_DRAGON_EGG_ENABLE_API")
        if on ~= nil then return on == true end
        if G.AUTO_DRAGON_EGG_ENABLED == true or rawget(_G, "AUTO_DRAGON_EGG_ENABLED") == true then
            return true
        end
        local st = getAuto("dragonEgg")
        return type(st) == "table" and st.enabled == true
    end

    local function readSellPetEnabled()
        local on = toggleApiGet("__GAG2_SELL_PET_ENABLE_API")
        if on ~= nil then return on == true end
        if G.AUTO_SELL_PET_ENABLED == true or rawget(_G, "AUTO_SELL_PET_ENABLED") == true then
            return true
        end
        local st = getAuto("sellPet")
        return type(st) == "table" and st.enabled == true
    end

    local function readSellPetPets()
        local dd = G.__GAG2_SELL_PET_DROPDOWN_API or rawget(_G, "__GAG2_SELL_PET_DROPDOWN_API")
        if type(dd) == "table" and type(dd.getSelected) == "function" then
            local ok, sel = pcall(dd.getSelected, dd)
            if ok and type(sel) == "table" and next(sel) then
                return mapToArray(cleanSelectedMap(sel))
            end
        end
        local gsel = G.AUTO_SELL_PET_SELECTED or rawget(_G, "AUTO_SELL_PET_SELECTED")
        if type(gsel) == "table" and next(gsel) then
            return mapToArray(cleanSelectedMap(gsel))
        end
        local st = getAuto("sellPet")
        if type(st) == "table" and type(st.pets) == "table" then
            return st.pets
        end
        return {}
    end

    local function writeDragonEggState(on)
        on = (on == true)
        G.AUTO_DRAGON_EGG_ENABLED = on
        _G.AUTO_DRAGON_EGG_ENABLED = on
        patchAutoOnly("dragonEgg", { enabled = on })
        return on
    end

    local function writeSellPetState(on, pets)
        on = (on == true)
        local selMap = cleanSelectedMap(arrayToMap(type(pets) == "table" and pets or {}))
        local petList = mapToArray(selMap)
        G.AUTO_SELL_PET_ENABLED = on
        _G.AUTO_SELL_PET_ENABLED = on
        G.AUTO_SELL_PET_SELECTED = selMap
        _G.AUTO_SELL_PET_SELECTED = selMap
        patchAutoOnly("sellPet", { enabled = on, pets = petList })
        return on, petList
    end

    local function flushDragonEggState()
        writeDragonEggState(readDragonEggEnabled())
    end

    local function flushSellPetState()
        writeSellPetState(readSellPetEnabled(), readSellPetPets())
    end

    local function readFavPetEnabled()
        local on = toggleApiGet("__GAG2_FAV_PET_ENABLE_API")
        if on ~= nil then return on == true end
        if G.AUTO_FAV_PET_ENABLED == true or rawget(_G, "AUTO_FAV_PET_ENABLED") == true then
            return true
        end
        local st = getAuto("favPet")
        return type(st) == "table" and st.enabled == true
    end

    local function readUnfavPetEnabled()
        local on = toggleApiGet("__GAG2_UNFAV_PET_ENABLE_API")
        if on ~= nil then return on == true end
        if G.AUTO_UNFAV_PET_ENABLED == true or rawget(_G, "AUTO_UNFAV_PET_ENABLED") == true then
            return true
        end
        local st = getAuto("unfavPet")
        return type(st) == "table" and st.enabled == true
    end

    local function readFavPetList(autoKey)
        local prefix = (autoKey == "unfavPet") and "AUTO_UNFAV_PET_" or "AUTO_FAV_PET_"
        local gsel = G[prefix .. "SELECTED"] or rawget(_G, prefix .. "SELECTED")
        if type(gsel) == "table" and next(gsel) then
            return mapToArray(cleanSelectedMap(gsel))
        end
        local st = getAuto(autoKey)
        if type(st) == "table" and type(st.pets) == "table" then
            return st.pets
        end
        return {}
    end

    local function readFavPetTypes(autoKey)
        local prefix = (autoKey == "unfavPet") and "AUTO_UNFAV_PET_" or "AUTO_FAV_PET_"
        local gsel = G[prefix .. "TYPES_SELECTED"] or rawget(_G, prefix .. "TYPES_SELECTED")
        if type(gsel) == "table" and next(gsel) then
            return mapToArray(cleanSelectedMap(gsel))
        end
        local st = getAuto(autoKey)
        if type(st) == "table" and type(st.types) == "table" then
            return st.types
        end
        return {}
    end

    local function readFavPetSizes(autoKey)
        local prefix = (autoKey == "unfavPet") and "AUTO_UNFAV_PET_" or "AUTO_FAV_PET_"
        local gsel = G[prefix .. "SIZES_SELECTED"] or rawget(_G, prefix .. "SIZES_SELECTED")
        if type(gsel) == "table" and next(gsel) then
            return mapToArray(cleanSelectedMap(gsel))
        end
        local st = getAuto(autoKey)
        if type(st) == "table" and type(st.sizes) == "table" then
            return st.sizes
        end
        return {}
    end

    local function writeFavPetState(autoKey, prefix, on, pets, types, sizes)
        on = (on == true)
        local petMap = cleanSelectedMap(arrayToMap(type(pets) == "table" and pets or {}))
        local typeMap = cleanSelectedMap(arrayToMap(type(types) == "table" and types or {}))
        local sizeMap = cleanSelectedMap(arrayToMap(type(sizes) == "table" and sizes or {}))
        G[prefix .. "ENABLED"] = on
        _G[prefix .. "ENABLED"] = on
        G[prefix .. "SELECTED"] = petMap
        _G[prefix .. "SELECTED"] = petMap
        G[prefix .. "TYPES_SELECTED"] = typeMap
        _G[prefix .. "TYPES_SELECTED"] = typeMap
        G[prefix .. "SIZES_SELECTED"] = sizeMap
        _G[prefix .. "SIZES_SELECTED"] = sizeMap
        patchAutoOnly(autoKey, {
            enabled = on,
            pets = mapToArray(petMap),
            types = mapToArray(typeMap),
            sizes = mapToArray(sizeMap),
        })
        return on
    end

    local function flushFavPetState()
        writeFavPetState(
            "favPet",
            "AUTO_FAV_PET_",
            readFavPetEnabled(),
            readFavPetList("favPet"),
            readFavPetTypes("favPet"),
            readFavPetSizes("favPet")
        )
    end

    local function flushUnfavPetState()
        writeFavPetState(
            "unfavPet",
            "AUTO_UNFAV_PET_",
            readUnfavPetEnabled(),
            readFavPetList("unfavPet"),
            readFavPetTypes("unfavPet"),
            readFavPetSizes("unfavPet")
        )
    end

