    _G.__GAG2_FLUSH_FAV_PET = flushFavPetState
    _G.__GAG2_FLUSH_UNFAV_PET = flushUnfavPetState

    G.__GAG2_READ_DRAGON_EGG = readDragonEggEnabled
    G.__GAG2_WRITE_DRAGON_EGG = writeDragonEggState
    G.__GAG2_FLUSH_DRAGON_EGG = flushDragonEggState
    _G.__GAG2_READ_DRAGON_EGG = readDragonEggEnabled
