        ----------------------------------------------------------------
        local TELE_LOC_ITEMS = {
            { key = "center", name = "Garden Center" },
            { key = "spawn", name = "Garden Spawn" },
        }

        local function normalizeTeleLoc(v)
            if tostring(v or "") == "spawn" then return "spawn" end
            return "center"
        end

        local TELE = getAuto("autoTele")
        TELE.enabled = (TELE.enabled == true)
        TELE.delay = tonumber(TELE.delay) or 0.5
        if TELE.delay < 0.2 then TELE.delay = 0.2 end
        TELE.selectedLocation = normalizeTeleLoc(TELE.selectedLocation)
        TELE.hitWerewolf = (TELE.hitWerewolf == true)

        TELE.mode = nil
        local teleOn = (TELE.enabled == true)
        local teleHitWwOn = (TELE.hitWerewolf == true)
        writeAutoTeleToMain()

        registerFlush("autoTele", function()
            local on = toggleApiGet("__GAG2_TELE_ENABLE_TOGGLE_API")
            local hitWw = toggleApiGet("__GAG2_TELE_HIT_WW_TOGGLE_API")
            patchAutoOnly("autoTele", {
                enabled = on ~= nil and on or (TELE.enabled == true),
                delay = TELE.delay,
                selectedLocation = TELE.selectedLocation,
                hitWerewolf = hitWw ~= nil and hitWw or (TELE.hitWerewolf == true),
            }, true)
        end)

        local bodyAutoTele = ui:CreateSection("Auto Guard Garden", false)

        _, teleLocDropdownApi = ui:CreateRowDropdown(bodyAutoTele, {
            label       = "Location",
            placeholder = "Garden Center",
            mode        = "single",
            getItems = function() return TELE_LOC_ITEMS end,
            initial = TELE.selectedLocation,
            onChanged = function(_, selectedKey)
                TELE.selectedLocation = normalizeTeleLoc(selectedKey)
                patchAuto("autoTele", { selectedLocation = TELE.selectedLocation }, restartAutoTeleIfOn)
            end,
        })

        ui:CreateRowInput(
            bodyAutoTele,
            "Scan Delay (sec)",
            tostring(TELE.delay),
            function(txt)
                local n = tonumber(txt)
                if n == nil or n < 0.2 then return end
                TELE.delay = n
                patchAuto("autoTele", { delay = n }, restartAutoTeleIfOn)
            end,
            false
        )

        local _, _, teleEnableToggleApi = ui:CreateRowToggle(
            bodyAutoTele,
            "Enable Auto Guard Garden",
            teleOn,
            function(isOn)
                TELE.enabled = (isOn == true)
                patchAuto("autoTele", { enabled = isOn == true }, function()
                    applyAutoTeleRuntime(isOn == true)
                end)
            end
        )
        G.__GAG2_TELE_ENABLE_TOGGLE_API = teleEnableToggleApi
        _G.__GAG2_TELE_ENABLE_TOGGLE_API = teleEnableToggleApi

        if teleEnableToggleApi and type(teleEnableToggleApi.set) == "function" then
            teleEnableToggleApi.set(teleOn, true)
        end

        local _, _, teleHitWwToggleApi = ui:CreateRowToggle(
            bodyAutoTele,
            "Teleport and Hit Werewolf",
            teleHitWwOn,
            function(isOn)
                TELE.hitWerewolf = (isOn == true)
                patchAuto("autoTele", { hitWerewolf = isOn == true }, function()
                    applyAutoTeleHitWerewolfRuntime(isOn == true)
                end)
            end
        )
        G.__GAG2_TELE_HIT_WW_TOGGLE_API = teleHitWwToggleApi
        _G.__GAG2_TELE_HIT_WW_TOGGLE_API = teleHitWwToggleApi

        if teleHitWwToggleApi and type(teleHitWwToggleApi.set) == "function" then
            teleHitWwToggleApi.set(teleHitWwOn, true)
        end

        syncAutoTeleAll()

        ----------------------------------------------------------------
        -- Auto Claim Seed (toggle ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â teleport + ClickPack)
        ----------------------------------------------------------------
        local claimOn = readClaimSeedEnabled()

        local bodyClaimSeed = ui:CreateSection("Auto Claim Seed", false)

        local _, _, claimToggleApi = ui:CreateRowToggle(
            bodyClaimSeed,
            "Enable Auto Claim Seed",
            claimOn,
            function(isOn)
                local on = (isOn == true)
                patchAuto("claimSeed", { enabled = on }, function()
                    _syncClaimSeedGlobals(on)
                    applyClaimSeedModuleOnly(on)
                end)
            end
        )
        G.__GAG2_CLAIM_SEED_TOGGLE_API = claimToggleApi
        _G.__GAG2_CLAIM_SEED_TOGGLE_API = claimToggleApi

        if claimToggleApi and type(claimToggleApi.set) == "function" then
            claimToggleApi.set(claimOn, true)
        end

        applyClaimSeedModuleOnly(claimOn)

        do
            local SectionGardenCards = G.SectionAutoGardenCards or rawget(_G, "SectionAutoGardenCards")
            if type(SectionGardenCards) == "table" and type(SectionGardenCards.Register) == "function" then
                local okGc, errGc = pcall(SectionGardenCards.Register, {
                    ui = ui,
                    getAuto = getAuto,
                    patchAuto = patchAuto,
                    patchAutoOnly = patchAutoOnly,
                    registerFlush = registerFlush,
                    toggleApiGet = toggleApiGet,
                })
                if not okGc then
                    warn("[GAG2] SectionAutoGardenCards.Register error:", tostring(errGc))
                    local bodyErr = ui:CreateSection("Auto Garden Cards", false)
                    ui:CreateRowLabel(bodyErr, "Garden Cards UI error: " .. tostring(errGc), nil, nil, "muted")
                end
            else
                warn("[GAG2] SectionAutoGardenCards tidak ditemukan — upload section_auto_garden_cards.lua")
                local bodyMiss = ui:CreateSection("Auto Garden Cards", false)
                ui:CreateRowLabel(
                    bodyMiss,
                    "(Section belum load — upload section_auto_garden_cards.lua + module/AutoGardenCards.lua)",
                    nil, nil, "muted"
                )
            end
        end

        if type(ui.EndContentLayoutSuspend) == "function" then
            pcall(ui.EndContentLayoutSuspend, ui)
        end
    end, 1)

