    ui:RegisterSubTab("auto", "buy", "Buy", function()
        local MAIN = ensureMain()

        MAIN.auto = MAIN.auto or {}
        MAIN.auto.buy = MAIN.auto.buy or {}

        local BUY_STATE = getAuto("buy")
        BUY_STATE.seed = type(BUY_STATE.seed) == "table" and BUY_STATE.seed or { enabled = false, items = {} }
        BUY_STATE.gear = type(BUY_STATE.gear) == "table" and BUY_STATE.gear or { enabled = false, items = {} }
        BUY_STATE.props = type(BUY_STATE.props) == "table" and BUY_STATE.props or { enabled = false, items = {} }

        BUY_STATE.seed.enabled = (BUY_STATE.seed.enabled == true)
        BUY_STATE.gear.enabled = (BUY_STATE.gear.enabled == true)
        BUY_STATE.props.enabled = (BUY_STATE.props.enabled == true)
        BUY_STATE.seed.items = type(BUY_STATE.seed.items) == "table" and BUY_STATE.seed.items or {}
        BUY_STATE.gear.items = type(BUY_STATE.gear.items) == "table" and BUY_STATE.gear.items or {}
        BUY_STATE.props.items = type(BUY_STATE.props.items) == "table" and BUY_STATE.props.items or {}

        local BUY_SEED_SELECTED = cleanSelectedMap(arrayToMap(BUY_STATE.seed.items))
        local BUY_GEAR_SELECTED = cleanSelectedMap(arrayToMap(BUY_STATE.gear.items))
        local BUY_PROPS_SELECTED = cleanSelectedMap(arrayToMap(BUY_STATE.props.items))

        local AUTO_BUY_SEED_ENABLED = BUY_STATE.seed.enabled
        local AUTO_BUY_GEAR_ENABLED = BUY_STATE.gear.enabled
        local AUTO_BUY_PROPS_ENABLED = BUY_STATE.props.enabled

        local buySeedDropdownApi = nil
        local buyGearDropdownApi = nil
        local buyPropsDropdownApi = nil


        local PET_STORE = syncBuyPetStoreFromMain()
        writeBuyPetToMain()

        local ShopListView = G.ShopListView
        local PetListView = G.PetListView

        local function writeBuyGlobals(skipDisk)
            if type(G.__GAG2_FLUSH_BUY_AUCTION) == "function" then
                pcall(G.__GAG2_FLUSH_BUY_AUCTION)
            end

            local seedApi = G.__GAG2_BUY_SEED_ENABLE_API or rawget(_G, "__GAG2_BUY_SEED_ENABLE_API")
            local gearApi = G.__GAG2_BUY_GEAR_ENABLE_API or rawget(_G, "__GAG2_BUY_GEAR_ENABLE_API")
            local propsApi = G.__GAG2_BUY_PROPS_ENABLE_API or rawget(_G, "__GAG2_BUY_PROPS_ENABLE_API")
            if type(seedApi) == "table" and type(seedApi.get) == "function" then
                BUY_STATE.seed.enabled = (seedApi.get() == true)
            end
            if type(gearApi) == "table" and type(gearApi.get) == "function" then
                BUY_STATE.gear.enabled = (gearApi.get() == true)
            end
            if type(propsApi) == "table" and type(propsApi.get) == "function" then
                BUY_STATE.props.enabled = (propsApi.get() == true)
            end

            local main = ensureMain()
            if type(main) ~= "table" then return end
            main.auto = main.auto or {}
            main.auto.buy = main.auto.buy or {}
            local buy = main.auto.buy

            buy.seed = type(buy.seed) == "table" and buy.seed or { enabled = false, items = {} }
            buy.gear = type(buy.gear) == "table" and buy.gear or { enabled = false, items = {} }
            buy.props = type(buy.props) == "table" and buy.props or { enabled = false, items = {} }

            buy.seed.enabled = (BUY_STATE.seed.enabled == true)
            buy.gear.enabled = (BUY_STATE.gear.enabled == true)
            buy.props.enabled = (BUY_STATE.props.enabled == true)
            buy.seed.items = mapToArray(BUY_SEED_SELECTED)
            buy.gear.items = mapToArray(BUY_GEAR_SELECTED)
            buy.props.items = mapToArray(BUY_PROPS_SELECTED)

            writeBuyPetToMain()
            buy.pet = type(main.auto.buy.pet) == "table" and main.auto.buy.pet or buy.pet

            patchAutoOnly("buy", {
                seed = { enabled = buy.seed.enabled, items = buy.seed.items },
                gear = { enabled = buy.gear.enabled, items = buy.gear.items },
                props = { enabled = buy.props.enabled, items = buy.props.items },
                pet = {
                    enabled = buy.pet.enabled,
                    auto_tame = buy.pet.auto_tame,
                    max_steal_price = buy.pet.max_steal_price,
                    items = type(buy.pet.items) == "table" and buy.pet.items or {},
                },
            }, skipDisk)

            G.AUTO_BUY_SEED_ENABLED = buy.seed.enabled
            _G.AUTO_BUY_SEED_ENABLED = buy.seed.enabled
            G.AUTO_BUY_GEAR_ENABLED = buy.gear.enabled
            _G.AUTO_BUY_GEAR_ENABLED = buy.gear.enabled
            G.AUTO_BUY_PROPS_ENABLED = buy.props.enabled
            _G.AUTO_BUY_PROPS_ENABLED = buy.props.enabled

            G.BUY_SEED_SELECTED = BUY_SEED_SELECTED
            _G.BUY_SEED_SELECTED = BUY_SEED_SELECTED
            G.BUY_GEAR_SELECTED = BUY_GEAR_SELECTED
            _G.BUY_GEAR_SELECTED = BUY_GEAR_SELECTED
            G.BUY_PROPS_SELECTED = BUY_PROPS_SELECTED
            _G.BUY_PROPS_SELECTED = BUY_PROPS_SELECTED

            G.MAIN = main
            _G.MAIN = main
            MAIN = main
            BUY_STATE = buy
        end
        G.__GAG2_PUSH_BUY = writeBuyGlobals
        _G.__GAG2_PUSH_BUY = writeBuyGlobals

        registerFlush("buy", function()
            writeBuyGlobals(true)
        end)

        local function getAutoBuy()
            return G.AutoBuyModule or G.AutoBuy or _G.AutoBuyModule or _G.AutoBuy
        end

        local function syncAutoBuyModule(skipDisk)
            writeBuyGlobals(skipDisk)

            local ab = getAutoBuy()
            if type(ab) ~= "table" then return end

            local function __call(fn, ...)
                if type(ab[fn]) == "function" then
                    pcall(ab[fn], ab, ...)
                end
            end

            __call("SetSelected", "seed", BUY_SEED_SELECTED)
            __call("SetSelected", "gear", BUY_GEAR_SELECTED)
            __call("SetSelected", "props", BUY_PROPS_SELECTED)

            if BUY_STATE.seed.enabled then
                __call("SetEnabled", "seed", true)
            else
                __call("SetEnabled", "seed", false)
            end
            if BUY_STATE.gear.enabled then
                __call("SetEnabled", "gear", true)
            else
                __call("SetEnabled", "gear", false)
            end
            if BUY_STATE.props.enabled then
                __call("SetEnabled", "props", true)
            else
                __call("SetEnabled", "props", false)
            end

            __call("SyncFromGlobals")

            local anyOn = BUY_STATE.seed.enabled or BUY_STATE.gear.enabled or BUY_STATE.props.enabled
            if anyOn then
                __call("Start")
                __call("start")
            else
                __call("Stop")
                __call("stop")
            end
        end

        G.__GAG2_SYNC_AUTO_BUY = syncAutoBuyModule


        -- [NODEHUBWS] Apply ulang selected item Auto Buy ke UI tab Beli yang sedang terbuka
        -- Dipanggil dari id_code_list 173 setelah config dari web diterima.
        local function applyBuyUiFromMain(remoteBuy)
            local buy = type(remoteBuy) == "table" and remoteBuy or getAuto("buy")
            if type(buy) ~= "table" then return false, "buy_not_table" end

            buy.seed = type(buy.seed) == "table" and buy.seed or { enabled = false, items = {} }
            buy.gear = type(buy.gear) == "table" and buy.gear or { enabled = false, items = {} }
            buy.props = type(buy.props) == "table" and buy.props or { enabled = false, items = {} }

            BUY_STATE.seed = BUY_STATE.seed or {}
            BUY_STATE.gear = BUY_STATE.gear or {}
            BUY_STATE.props = BUY_STATE.props or {}

            BUY_STATE.seed.enabled = buy.seed.enabled == true
            BUY_STATE.gear.enabled = buy.gear.enabled == true
            BUY_STATE.props.enabled = buy.props.enabled == true

            BUY_STATE.seed.items = type(buy.seed.items) == "table" and buy.seed.items or {}
            BUY_STATE.gear.items = type(buy.gear.items) == "table" and buy.gear.items or {}
            BUY_STATE.props.items = type(buy.props.items) == "table" and buy.props.items or {}

            BUY_SEED_SELECTED = cleanSelectedMap(arrayToMap(BUY_STATE.seed.items))
            BUY_GEAR_SELECTED = cleanSelectedMap(arrayToMap(BUY_STATE.gear.items))
            BUY_PROPS_SELECTED = cleanSelectedMap(arrayToMap(BUY_STATE.props.items))

            local function setDropdown(api, selected)
                if type(api) == "table" then
                    if type(api.setSelected) == "function" then
                        pcall(api.setSelected, selected)
                    end
                    if type(api.refreshItems) == "function" then
                        pcall(api.refreshItems)
                    elseif type(api.refreshLabel) == "function" then
                        pcall(api.refreshLabel)
                    end
                end
            end

            setDropdown(buySeedDropdownApi, BUY_SEED_SELECTED)
            setDropdown(buyGearDropdownApi, BUY_GEAR_SELECTED)
            setDropdown(buyPropsDropdownApi, BUY_PROPS_SELECTED)

            local seedApi = G.__GAG2_BUY_SEED_ENABLE_API or rawget(_G, "__GAG2_BUY_SEED_ENABLE_API")
            local gearApi = G.__GAG2_BUY_GEAR_ENABLE_API or rawget(_G, "__GAG2_BUY_GEAR_ENABLE_API")
            local propsApi = G.__GAG2_BUY_PROPS_ENABLE_API or rawget(_G, "__GAG2_BUY_PROPS_ENABLE_API")

            if type(seedApi) == "table" and type(seedApi.set) == "function" then pcall(seedApi.set, BUY_STATE.seed.enabled, true) end
            if type(gearApi) == "table" and type(gearApi.set) == "function" then pcall(gearApi.set, BUY_STATE.gear.enabled, true) end
            if type(propsApi) == "table" and type(propsApi.set) == "function" then pcall(propsApi.set, BUY_STATE.props.enabled, true) end

            syncAutoBuyModule()
            return true
        end

        G.__GAG2_APPLY_BUY_UI_FROM_MAIN = applyBuyUiFromMain
        _G.__GAG2_APPLY_BUY_UI_FROM_MAIN = applyBuyUiFromMain


        local bodySeed = ui:CreateSection("Auto Buy Seed", true)
        local bodyGear = ui:CreateSection("Auto Buy Gear", false)
        local bodyProps = ui:CreateSection("Auto Buy Props", false)

        local BUY_LIST_SORT = { sortBy = "price" }

        local function seedItemsForWorld(world)
            if PlantListView and type(PlantListView.buildSeedItems) == "function" then
                return PlantListView.buildSeedItems({
                    sortBy = "price",
                    world = world,
                    showPrice = true,
                }) or {}
            end
            local ab = getAutoBuy()
            if type(ab) == "table" and type(ab.GetLists) == "function" then
                local ok, seeds = pcall(ab.GetLists, ab)
                if ok then return seeds or {} end
            end
            return {}
        end

        local function seedInitialForWorld(world)
            if PlantListView and type(PlantListView.filterSelectedForWorld) == "function" then
                return PlantListView.filterSelectedForWorld(BUY_SEED_SELECTED, world)
            end
            return BUY_SEED_SELECTED
        end

        local function onSeedWorldChanged(world, selectedMap)
            local cleaned = cleanSelectedMap(selectedMap)
            if PlantListView and type(PlantListView.mergeSelectedForWorld) == "function" then
                BUY_SEED_SELECTED = cleanSelectedMap(
                    PlantListView.mergeSelectedForWorld(BUY_SEED_SELECTED, world, cleaned)
                )
            else
                BUY_SEED_SELECTED = cleaned
            end
            patchAuto("buy", { seed = { items = mapToArray(BUY_SEED_SELECTED) } }, syncAutoBuyModule)
        end

        _, buySeedDropdownApi = ui:CreateRowDropdown(bodySeed, {
            label       = "Select Seed (Main)",
            placeholder = "Select Seed (Main)...",
            mode        = "multi",
            preserveItemOrder = true,
            deferItemLoad = true,
            getItems = function()
                return seedItemsForWorld("Main")
            end,
            initial = seedInitialForWorld("Main"),
            onChanged = function(_, selectedMap)
                onSeedWorldChanged("Main", selectedMap)
            end,
        })

        _, buySeedDropdownApi = ui:CreateRowDropdown(bodySeed, {
            label       = "Select Seed (Ghoul Garden)",
            placeholder = "Select Seed (Ghoul Garden)...",
            mode        = "multi",
            preserveItemOrder = true,
            deferItemLoad = true,
            getItems = function()
                return seedItemsForWorld("GhoulGarden")
            end,
            initial = seedInitialForWorld("GhoulGarden"),
            onChanged = function(_, selectedMap)
                onSeedWorldChanged("GhoulGarden", selectedMap)
            end,
        })

        local _, _, seedEnableApi = ui:CreateRowToggle(bodySeed, "Enable Auto Buy Seed", AUTO_BUY_SEED_ENABLED, function(isOn)
            BUY_STATE.seed.enabled = (isOn == true)
            AUTO_BUY_SEED_ENABLED = BUY_STATE.seed.enabled
            patchAuto("buy", { seed = { enabled = isOn == true } }, syncAutoBuyModule)
        end)
        G.__GAG2_BUY_SEED_ENABLE_API = seedEnableApi
        _G.__GAG2_BUY_SEED_ENABLE_API = seedEnableApi

        local function gearItemsForWorld(world)
            if ShopListView and type(ShopListView.buildGearItems) == "function" then
                return ShopListView.buildGearItems({
                    sortBy = "price",
                    world = world,
                    showPrice = true,
                }) or {}
            end
            local ab = getAutoBuy()
            if type(ab) == "table" and type(ab.GetLists) == "function" then
                local ok, _, gears = pcall(ab.GetLists, ab)
                if ok then return gears or {} end
            end
            return {}
        end

        local function gearInitialForWorld(world)
            if ShopListView and type(ShopListView.filterGearSelectedForWorld) == "function" then
                return ShopListView.filterGearSelectedForWorld(BUY_GEAR_SELECTED, world)
            end
            return BUY_GEAR_SELECTED
        end

        local function onGearWorldChanged(world, selectedMap)
            local cleaned = cleanSelectedMap(selectedMap)
            if ShopListView and type(ShopListView.mergeGearSelectedForWorld) == "function" then
                BUY_GEAR_SELECTED = cleanSelectedMap(
                    ShopListView.mergeGearSelectedForWorld(BUY_GEAR_SELECTED, world, cleaned)
                )
            else
                BUY_GEAR_SELECTED = cleaned
            end
            patchAuto("buy", { gear = { items = mapToArray(BUY_GEAR_SELECTED) } }, syncAutoBuyModule)
        end

        _, buyGearDropdownApi = ui:CreateRowDropdown(bodyGear, {
            label       = "Select Gear (Main)",
            placeholder = "Select Gear (Main)...",
            mode        = "multi",
            preserveItemOrder = true,
            deferItemLoad = true,
            getItems = function()
                return gearItemsForWorld("Main")
            end,
            initial = gearInitialForWorld("Main"),
            onChanged = function(_, selectedMap)
                onGearWorldChanged("Main", selectedMap)
            end,
        })

        _, buyGearDropdownApi = ui:CreateRowDropdown(bodyGear, {
            label       = "Select Gear (Ghoul Garden)",
            placeholder = "Select Gear (Ghoul Garden)...",
            mode        = "multi",
            preserveItemOrder = true,
            deferItemLoad = true,
            getItems = function()
                return gearItemsForWorld("GhoulGarden")
            end,
            initial = gearInitialForWorld("GhoulGarden"),
            onChanged = function(_, selectedMap)
                onGearWorldChanged("GhoulGarden", selectedMap)
            end,
        })

        local _, _, gearEnableApi = ui:CreateRowToggle(bodyGear, "Enable Auto Buy Gear", AUTO_BUY_GEAR_ENABLED, function(isOn)
            BUY_STATE.gear.enabled = (isOn == true)
            AUTO_BUY_GEAR_ENABLED = BUY_STATE.gear.enabled
            patchAuto("buy", { gear = { enabled = isOn == true } }, syncAutoBuyModule)
        end)
        G.__GAG2_BUY_GEAR_ENABLE_API = gearEnableApi
        _G.__GAG2_BUY_GEAR_ENABLE_API = gearEnableApi

        local function propsItemsForWorld(world)
            if ShopListView and type(ShopListView.buildPropsItems) == "function" then
                return ShopListView.buildPropsItems({
                    sortBy = "price",
                    world = world,
                    showPrice = true,
                }) or {}
            end
            local ab = getAutoBuy()
            if type(ab) == "table" and type(ab.GetLists) == "function" then
                local ok, _, _, props = pcall(ab.GetLists, ab)
                if ok then return props or {} end
            end
            return {}
        end

        local function propsInitialForWorld(world)
            if ShopListView and type(ShopListView.filterPropsSelectedForWorld) == "function" then
                return ShopListView.filterPropsSelectedForWorld(BUY_PROPS_SELECTED, world)
            end
            return BUY_PROPS_SELECTED
        end

        local function onPropsWorldChanged(world, selectedMap)
            local cleaned = cleanSelectedMap(selectedMap)
            if ShopListView and type(ShopListView.mergePropsSelectedForWorld) == "function" then
                BUY_PROPS_SELECTED = cleanSelectedMap(
                    ShopListView.mergePropsSelectedForWorld(BUY_PROPS_SELECTED, world, cleaned)
                )
            else
                BUY_PROPS_SELECTED = cleaned
            end
            patchAuto("buy", { props = { items = mapToArray(BUY_PROPS_SELECTED) } }, syncAutoBuyModule)
        end

        _, buyPropsDropdownApi = ui:CreateRowDropdown(bodyProps, {
            label       = "Select Crate (Main)",
            placeholder = "Select Crate (Main)...",
            mode        = "multi",
            preserveItemOrder = true,
            deferItemLoad = true,
            getItems = function()
                return propsItemsForWorld("Main")
            end,
            initial = propsInitialForWorld("Main"),
            onChanged = function(_, selectedMap)
                onPropsWorldChanged("Main", selectedMap)
            end,
        })

        _, buyPropsDropdownApi = ui:CreateRowDropdown(bodyProps, {
            label       = "Select Crate (Ghoul Garden)",
            placeholder = "Select Crate (Ghoul Garden)...",
            mode        = "multi",
            preserveItemOrder = true,
            deferItemLoad = true,
            getItems = function()
                return propsItemsForWorld("GhoulGarden")
            end,
            initial = propsInitialForWorld("GhoulGarden"),
            onChanged = function(_, selectedMap)
                onPropsWorldChanged("GhoulGarden", selectedMap)
            end,
        })

        local _, _, propsEnableApi = ui:CreateRowToggle(bodyProps, "Enable Auto Buy Props", AUTO_BUY_PROPS_ENABLED, function(isOn)
            BUY_STATE.props.enabled = (isOn == true)
            AUTO_BUY_PROPS_ENABLED = BUY_STATE.props.enabled
            patchAuto("buy", { props = { enabled = isOn == true } }, syncAutoBuyModule)
        end)
        G.__GAG2_BUY_PROPS_ENABLE_API = propsEnableApi
        _G.__GAG2_BUY_PROPS_ENABLE_API = propsEnableApi

        local SectionBuyAuction = G.SectionAutoBuyAuction or rawget(_G, "SectionAutoBuyAuction")
        if type(SectionBuyAuction) == "table" and type(SectionBuyAuction.Register) == "function" then
            local okAuctionUi, errAuctionUi = pcall(SectionBuyAuction.Register, {
                ui = ui,
                getAuto = getAuto,
                patchAutoOnly = patchAutoOnly,
                saveNow = saveNow,
                registerFlush = registerFlush,
                cleanSelectedMap = cleanSelectedMap,
                arrayToMap = arrayToMap,
                mapToArray = mapToArray,
                PlantListView = PlantListView,
                ShopListView = ShopListView,
            })
            if not okAuctionUi then
                warn("[GAG2] SectionAutoBuyAuction.Register error:", tostring(errAuctionUi))
                local bodyErr = ui:CreateSection("Auto Buy Auction", false)
                ui:CreateRowLabel(bodyErr, "Auction UI error: " .. tostring(errAuctionUi), nil, nil, "muted")
            end
        else
            warn("[GAG2] SectionAutoBuyAuction tidak ditemukan â€” upload section_auto_buy_auction.lua")
            local bodyMiss = ui:CreateSection("Auto Buy Auction", false)
            ui:CreateRowLabel(
                bodyMiss,
                "(Section belum load â€” upload section_auto_buy_auction.lua + module/AutoBuyAuction.lua)",
                nil,
                nil,
                "muted"
            )
        end

        local SectionBuyPet = G.SectionAutoBuyPet or rawget(_G, "SectionAutoBuyPet")
        if type(SectionBuyPet) == "table" and type(SectionBuyPet.Register) == "function" then
            local okPetUi, errPetUi = pcall(SectionBuyPet.Register, {
                ui = ui,
                getStore = ensureBuyPetStore,
                patchStore = patchBuyPet,
                readEnabled = readBuyPetEnabled,
                applyRuntime = applyBuyPetRuntime,
                registerFlush = registerFlush,
                PetListView = G.PetListView or rawget(_G, "PetListView"),
            })
            if not okPetUi then
                warn("[GAG2] SectionAutoBuyPet.Register error:", tostring(errPetUi))
                local bodyErr = ui:CreateSection("Auto Buy Pet", false)
                ui:CreateRowLabel(bodyErr, "Buy Pet UI error: " .. tostring(errPetUi), nil, nil, "muted")
            end
        else
            warn("[GAG2] SectionAutoBuyPet tidak ditemukan ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â upload section_auto_buy_pet.lua")
            local bodyMiss = ui:CreateSection("Auto Buy Pet", false)
            ui:CreateRowLabel(
                bodyMiss,
                "(Section belum load ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â upload section_auto_buy_pet.lua + tabs_auto.lua)",
                nil,
                nil,
                "muted"
            )
        end

        syncAutoBuyModule(true)
        writeBuyGlobals(true)
        applyBuyPetRuntime(readBuyPetEnabled())
    end, 3)

