----------------------------------------------------------------
-- log / RF / plot distance
----------------------------------------------------------------
function H.dbg()
    return G.AUTO_COLLECT_DEBUG == true or _G.AUTO_COLLECT_DEBUG == true
end

function H.log(...)
    if H.dbg() then print("[GAG2-AC]", ...) end
end

function H.warn(...)
    print("[GAG2-AC]", ...)
end

function H.reduceFpsOn()
    return G.REDUCE_FPS_ENABLED == true or rawget(_G, "REDUCE_FPS_ENABLED") == true
end

function H.reduceFpsMod()
    return G.ReduceFPS or G.ReduceFPSModule or rawget(_G, "ReduceFPS") or rawget(_G, "ReduceFPSModule")
end

function H.rfMarkPendingCollect(plantId, fruitId)
    local RF = H.reduceFpsMod()
    if type(RF) == "table" and type(RF.MarkPendingCollect) == "function" then
        pcall(RF.MarkPendingCollect, RF, plantId, fruitId)
    elseif type(RF) == "table" and type(RF.markPendingCollect) == "function" then
        pcall(RF.markPendingCollect, RF, plantId, fruitId)
    end
end

function H.rfClearPendingCollect(plantId, fruitId)
    local RF = H.reduceFpsMod()
    if type(RF) == "table" and type(RF.ClearPendingCollect) == "function" then
        pcall(RF.ClearPendingCollect, RF, plantId, fruitId)
    elseif type(RF) == "table" and type(RF.clearPendingCollect) == "function" then
        pcall(RF.clearPendingCollect, RF, plantId, fruitId)
    end
end

function H.rfStampMutationsNow()
    local RF = H.reduceFpsMod()
    if type(RF) ~= "table" then return end
    if type(RF.StampMutationsNow) == "function" then
        pcall(RF.StampMutationsNow, RF)
    elseif type(RF.stampMutationsNow) == "function" then
        pcall(RF.stampMutationsNow, RF)
    end
end

function H.characterPos()
    local char = LP.Character
    if not char then return nil end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp and hrp:IsA("BasePart") then
        return hrp.Position
    end
    local ok, pos = pcall(function()
        return char:GetPivot().Position
    end)
    return (ok and pos) or nil
end

function H.plotAnchorPos(plot)
    if not plot then return nil end
    for _, name in ipairs({ "PlantArea", "Important", "Ground" }) do
        local n = plot:FindFirstChild(name, true)
        if n then
            if n:IsA("BasePart") then return n.Position end
            if n:IsA("Model") then
                local ok, pos = pcall(function()
                    return n:GetPivot().Position
                end)
                if ok and pos then return pos end
            end
        end
    end
    local part = plot:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

function H.isNearOwnPlot()
    if C.PAUSE_FAR_FROM_PLOT == false then
        return true
    end
    local RF = H.reduceFpsMod()
    if type(RF) == "table" and type(RF.IsNearOwnPlot) == "function" then
        local ok, near = pcall(RF.IsNearOwnPlot, RF)
        if ok and type(near) == "boolean" then
            S.farPaused = not near
            return near
        end
    end
    local now = os.clock()
    if (now - (tonumber(S.nearPlotAt) or 0)) < (C.NEAR_PLOT_CACHE_SEC or 0.4) then
        return S.nearPlotCached ~= false
    end
    S.nearPlotAt = now
    local pos = H.characterPos()
    local plot = S.cachedPlot
    if not (plot and plot.Parent) then
        plot = F.getPlayerPlot(false)
    end
    local anchor = H.plotAnchorPos(plot)
    if not pos or not anchor then
        S.nearPlotCached = true
        S.nearPlotDist = nil
        S.farPaused = false
        return true
    end
    local dist = (pos - anchor).Magnitude
    S.nearPlotDist = dist
    local pauseAt = tonumber(C.NEAR_PLOT_STUDS) or 150
    local resumeAt = tonumber(C.NEAR_PLOT_RESUME_STUDS) or 120
    local near
    if S.nearPlotCached == false then
        near = dist <= resumeAt
    else
        near = dist <= pauseAt
    end
    S.nearPlotCached = near
    S.farPaused = not near
    return near
end

function H.isFarFromOwnPlot()
    return not H.isNearOwnPlot()
end

function H.isResumeCatchup()
    local RF = H.reduceFpsMod()
    if type(RF) == "table" and type(RF.IsResumeCatchup) == "function" then
        local ok, v = pcall(RF.IsResumeCatchup, RF)
        if ok and v == true then
            return true
        end
    end
    local t0 = tonumber(S.resumeCatchupAt) or 0
    if t0 <= 0 then return false end
    return (os.clock() - t0) < (tonumber(C.RESUME_CATCHUP_SEC) or 3.0)
end

function H.eclipseSpawnInMinGap()
    -- Jeda antar fire saja. Jangan kunci 1x per cuaca.
    local minGap = tonumber(C.ECLIPSE_SPAWN_MIN_GAP_SEC) or 0.2
    local gap = F.liveDelay()
    if type(gap) ~= "number" or gap < minGap then
        gap = minGap
    end
    local at = tonumber(S.eclipseSpawnDoneAt) or 0
    if at <= 0 then return false end
    return (os.clock() - at) < gap
end

function H.eclipseShouldHoldMatch()
    -- Jangan pause collect biasa. Eclipse Bloom tetap di-skip (isEclipseSpawnReserved);
    -- kick spawn jalan parallel di worker, bukan nahan antrian match.
    return false
end

----------------------------------------------------------------
-- tiny helpers
----------------------------------------------------------------
function F.remoteCanFire(remote)
    if not remote then return false end
    if type(remote.Fire) == "function" then return true end
    if type(remote.FireServer) == "function" then return true end
    if type(remote.InvokeServer) == "function" then return true end
    return false
end

function F.ensureRemote()
    if S.CollectFruit and F.remoteCanFire(S.CollectFruit) then
        return true
    end
    S.CollectFruit = nil
    local ok, net = pcall(function()
        local sm = ReplicatedStorage:WaitForChild("SharedModules", 8)
        return sm and require(sm:WaitForChild("Networking", 8))
    end)
    if ok and type(net) == "table" and type(net.Garden) == "table" then
        S.CollectFruit = net.Garden.CollectFruit
    end
    return F.remoteCanFire(S.CollectFruit)
end

function F.hasAny(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true then return true end
    end
    return false
end

function F.normalizeSet(src)
    if type(src) ~= "table" then return {} end
    local out = {}
    for i = 1, #src do
        local v = src[i]
        if v ~= nil and tostring(v) ~= "" then out[tostring(v)] = true end
    end
    if next(out) then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then out[tostring(k)] = true end
    end
    return out
end

function F.setToArray(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true then out[#out + 1] = tostring(k) end
    end
    table.sort(out)
    return out
end

function F.canon(s)
    return tostring(s or ""):lower():gsub("[^%w]+", "")
end

function F.idPresent(v)
    return v ~= nil and tostring(v) ~= ""
end

function F.seedIsSingleHarvest(plantName)
    plantName = tostring(plantName or "")
    if plantName == "" then return false end
    if S.singleHarvestReady ~= true then
        S.singleHarvestCache = S.singleHarvestCache or {}
        pcall(function()
            local SeedData = require(ReplicatedStorage.SharedModules.SeedData)
            for _, entry in pairs(SeedData) do
                if type(entry) == "table" and type(entry.SeedName) == "string" then
                    S.singleHarvestCache[entry.SeedName] = (entry.IsSingleHarvest == true)
                end
            end
        end)
        S.singleHarvestReady = true
    end
    return S.singleHarvestCache[plantName] == true
end

function F.plantIsSingleHarvest(plantData, name)
    if type(plantData) == "table" then
        local n = tonumber(plantData.MaxFruitSpawnLocations)
        if n == 0 then return true end
        if n ~= nil and n > 0 then return false end
    end
    return F.seedIsSingleHarvest(name)
end

function F.rowKey(plantId, fruitId)
    return tostring(plantId or "") .. "|" .. tostring(fruitId or "")
end

function F.normalizeDelay(v, default)
    default = default or 0.05
    local d = tonumber(v)
    if d == nil then return default end
    if d < 0 then return 0 end
    return d
end

function F.liveDelay()
    local raw = G.AUTO_COLLECT_DELAY
    if raw == nil then raw = rawget(_G, "AUTO_COLLECT_DELAY") end
    if raw == nil then
        local MAIN = rawget(_G, "MAIN") or G.MAIN
        local ac = MAIN and MAIN.auto and MAIN.auto.collect
        raw = ac and ac.delay
    end
    return F.normalizeDelay(raw, 0.05)
end

function F.fireDelaySec(ac)
    local d = tonumber(ac and ac.delay)
    if d == nil then d = F.liveDelay() end
    d = tonumber(d) or 0
    if d < 0 then d = 0 end
    return d
end

function F.waitAfterFire(ac)
    local d = F.fireDelaySec(ac)
    if d > 0 then
        task.wait(d)
    else
        task.wait()
    end
end

function F.normalizeKgFilter(kg, mode)
    kg = tonumber(kg) or 0
    mode = tostring(mode or "above")
    if kg < 0 then
        kg = math.abs(kg)
        mode = "below"
    end
    if mode ~= "below" then
        mode = "above"
    end
    return kg, mode
end

function F.parseKgRuleInput(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt == "" then
        return 0, "above"
    end
    local n = tonumber(txt)
    if not n then
        return 0, "above"
    end
    if n < 0 then
        return math.abs(n), "below"
    end
    return n, "above"
end

function F.formatKgRule(kg, mode)
    kg = tonumber(kg) or 0
    mode = tostring(mode or "above")
    if kg <= 0 then
        return "0"
    end
    if mode == "below" then
        return "-" .. tostring(kg)
    end
    return tostring(kg)
end

function F.normalizePriceFilter(price, mode)
    price = tonumber(price) or 0
    mode = tostring(mode or "above")
    if price < 0 then
        price = math.floor(math.abs(price))
        mode = "below"
    end
    if mode ~= "below" then
        mode = "above"
    end
    return math.floor(math.max(0, price)), mode
end

function F.parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then return nil end
    local sign = 1
    if txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "juta", 1000000 }, { "jt", 1000000 },
        { "ribu", 1000 }, { "rb", 1000 },
        { "b", 1000000000 }, { "m", 1000000 }, { "k", 1000 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then return n * mult * sign end
        end
    end
    local n = tonumber(txt)
    if n then return n * sign end
    return nil
end

function F.parsePriceRuleInput(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt == "" then
        return 0, "above"
    end
    local n = F.parseScaledNumber(txt) or tonumber(txt)
    if not n then
        return 0, "above"
    end
    if n < 0 then
        return math.abs(n), "below"
    end
    return n, "above"
end

function F.formatPriceRule(price, mode)
    price = tonumber(price) or 0
    mode = tostring(mode or "above")
    if price <= 0 then return "0" end
    if mode == "below" then return "-" .. tostring(price) end
    return tostring(price)
end

function F.isNoMutationKey(name)
    local c = F.canon(name)
    return c == "nomutation" or c == "none" or tostring(name or "") == C.NO_MUTATION_LABEL
end

function F.readEnabled()
    if G.AUTO_COLLECT_FRUIT_ENABLED == true or rawget(_G, "AUTO_COLLECT_FRUIT_ENABLED") == true then
        return true
    end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local ac = MAIN and MAIN.auto and MAIN.auto.collect
    return type(ac) == "table" and ac.enabled == true
end

function F.writeMainCollect(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.collect = MAIN.auto.collect or {}
    for k, v in pairs(patch) do
        MAIN.auto.collect[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

function F.anyRuleHasMutations(ac)
    for _, r in ipairs((ac and ac.rules) or {}) do
        if r and r.enabled ~= false and type(r.mutations) == "table" then
            for _, v in pairs(r.mutations) do
                if v == true then return true end
            end
        end
    end
    return false
end

function F.bootReady(ac)
    if S.rulesReadyAt <= 0 then return false end
    local age = os.clock() - S.rulesReadyAt
    if age < C.BOOT_SETTLE_SEC then return false end
    if not F.anyRuleHasMutations(ac) and age < (C.BOOT_SETTLE_SEC + C.MUT_SYNC_EXTRA_SEC) then
        return false
    end
    return true
end

function F.cycleActive()
    return S.running == true and S.loopAliveId > 0 and S.loopAliveId == S.loopId
end

function F.bagCount()
    return tonumber(LP:GetAttribute("FruitCount"))
end

function F.isBackpackFull()
    local count = tonumber(LP:GetAttribute("FruitCount"))
    local maxCap = tonumber(LP:GetAttribute("MaxFruitCapacity"))
    if count == nil or maxCap == nil or maxCap <= 0 then return false end
    return count >= maxCap
end

function F.isBackpackFullStable()
    if not F.isBackpackFull() then
        S.backpackFullSince = nil
        return false
    end
    local now = os.clock()
    if not S.backpackFullSince then
        S.backpackFullSince = now
                return false
            end
    return (now - S.backpackFullSince) >= 0.6
end

function F.notifyCollectUi()
    S.lastUiNotifyAt = os.clock()
    if type(F.rebuildUiSnap) == "function" then
        pcall(F.rebuildUiSnap)
    end
    local refreshUi = rawget(_G, "__GAG2_REFRESH_COLLECT_UI") or rawget(G, "__GAG2_REFRESH_COLLECT_UI")
    if type(refreshUi) == "function" then
        pcall(refreshUi)
    end
end

function F.noteCollectedSoft()
    if S.readyCache > 0 then
        S.readyCache -= 1
        S.readyCacheAt = os.clock()
    end
    if S.filteredCache > 0 then
        S.filteredCache -= 1
        S.filteredCacheAt = os.clock()
    end
    if S.cycleMatchTotal > 0 then
        S.cycleMatchTotal -= 1
    end
    local now = os.clock()
    if (now - (tonumber(S.lastUiNotifyAt) or 0)) < 0.4 then
        return
    end
    F.notifyCollectUi()
end

----------------------------------------------------------------
-- GetGarden
----------------------------------------------------------------
function F.getGardenSync()
    local now = os.clock()
    if S.gardenSyncMod and (now - S.gardenSyncAt) <= 30 then
        return S.gardenSyncMod
    end
    S.gardenSyncAt = now
    S.gardenSyncMod = nil
    local ps = LP:FindFirstChild("PlayerScripts")
    local c = ps and ps:FindFirstChild("Controllers")
    local m = c and c:FindFirstChild("GardenSyncController")
    if m and m:IsA("ModuleScript") then
        local ok, mod = pcall(require, m)
        if ok and type(mod) == "table" and type(mod.GetGarden) == "function" then
            S.gardenSyncMod = mod
                        end
                    end
    return S.gardenSyncMod
end

function F.getGarden(force)
    local now = os.clock()
    if force ~= true and S.gardenSnap ~= nil
        and (now - (S.gardenSnapAt or 0)) < (C.GARDEN_SNAP_SEC or 0.45) then
        return S.gardenSnap
    end
    local sync = F.getGardenSync()
    if not sync then return nil end
    local g
    pcall(function()
        g = sync:GetGarden(LP.UserId)
    end)
    if type(g) == "table" then
        S.gardenSnap = g
        S.gardenSnapAt = now
        return g
    end
    return nil
end

function F.gardenLoaded()
    local sync = F.getGardenSync()
    if sync and type(sync.IsLocalGardenLoaded) == "function" then
        local ok, v = pcall(function()
            return sync:IsLocalGardenLoaded()
        end)
        if ok and v == true then return true end
    end
    local g = F.getGarden()
    return type(g) == "table" and next(g) ~= nil
end

function F.gardenHasPlant(plantId)
    local g = F.getGarden()
    if type(g) ~= "table" then return nil end
    local plant = g[plantId]
    if type(plant) ~= "table" then
        plant = g[tostring(plantId)]
    end
    return type(plant) == "table"
end

function F.gardenHasFruit(plantId, fruitId)
    if not F.idPresent(fruitId) then
        local has = F.gardenHasPlant(plantId)
        if has == nil then return nil end
        return has
    end
    local g = F.getGarden()
    if type(g) ~= "table" then return nil end
    local plant = g[plantId]
    if type(plant) ~= "table" then
        plant = g[tostring(plantId)]
    end
    if type(plant) ~= "table" then return false end
    local fruits = plant.Fruits or plant.fruits
    if type(fruits) ~= "table" then return false end
    if type(fruits[fruitId]) == "table" then return true end
    local want = tostring(fruitId or "")
    if want ~= "" and type(fruits[want]) == "table" then return true end
    local n = tonumber(fruitId)
    if n ~= nil and type(fruits[n]) == "table" then return true end
                return false
end

function F.moduleBaseWeight(plantName)
    plantName = tostring(plantName or "")
    if plantName == "" then return nil end
    local cached = S.fruitBaseWeightCache[plantName]
    if cached ~= nil then
        return cached > 0 and cached or nil
    end
    local bw = 0
    local ok, folder = pcall(function()
        return ReplicatedStorage:FindFirstChild("PlantGenerationModules")
            and ReplicatedStorage.PlantGenerationModules:FindFirstChild("Fruits")
    end)
    if ok and folder then
        local ms = folder:FindFirstChild(plantName)
        if ms and ms:IsA("ModuleScript") then
            local okReq, mod = pcall(require, ms)
            if okReq and type(mod) == "table" and type(mod.GrowData) == "table" then
                bw = tonumber(mod.GrowData.BaseWeight) or 0
            end
        end
    end
    S.fruitBaseWeightCache[plantName] = bw
    return bw > 0 and bw or nil
end

function F.normalizeMutation(raw)
    if type(raw) == "string" then
        raw = raw:gsub("^%s+", ""):gsub("%s+$", "")
        if raw == "" then return nil end
        return raw
    end
    if type(raw) == "table" then
        local parts = {}
        for k, v in pairs(raw) do
            if v == true then
                parts[#parts + 1] = tostring(k)
            elseif type(v) == "string" and v ~= "" then
                parts[#parts + 1] = v
        end
    end
        if #parts == 0 then return nil end
        table.sort(parts)
        return table.concat(parts, "+")
    end
    return nil
end

function F.mutationFromData(data)
    if type(data) ~= "table" then return "" end
    local mut = F.normalizeMutation(data.Mutation or data.mutation or data.MutationName)
    if not mut and type(data.Mutations) == "table" then
        mut = F.normalizeMutation(data.Mutations)
    end
    if not mut then
        for i = 1, #C.MUT_FLAGS do
            if data[C.MUT_FLAGS[i]] == true then
                mut = C.MUT_FLAGS[i]
                break
                        end
        end
    end
    return mut or ""
end

function F.parseMutationList(mut)
    if type(mut) ~= "string" or mut == "" then return {} end
    local out = {}
    for token in string.gmatch(mut, "[^%+/,;]+") do
        token = token:gsub("^%s+", ""):gsub("%s+$", "")
        if token ~= "" and not F.isNoMutationKey(token) then
            out[#out + 1] = token
        end
    end
    return out
end

function F.fruitHasMutation(row)
    if type(row) ~= "table" then return false end
    local m = tostring(row.mut or "")
    return m ~= "" and not F.isNoMutationKey(m)
end

function F.rowPrice(name, sm, mut)
    local fsv = S.fruitSellValue
    if type(fsv) ~= "table" or type(fsv.calculate) ~= "function" then
        fsv = G.FruitSellValue or _G.FruitSellValue
    end
    if type(fsv) == "table" and type(fsv.calculate) == "function" and sm > 0 then
        local ok, p = pcall(fsv.calculate, name, sm, mut ~= "" and mut or nil, nil, nil)
        if ok and type(p) == "number" and p > 0 then
            return p
            end
        end
    return 0
end

function F.rowFromData(plantId, fruitId, plantName, data, skipPrice, skipKg)
    local sm = tonumber(data.SizeMultiplier) or tonumber(data.SizeMulti) or 0
    local og = tonumber(data.OvertimeGrowth) or 1
    if og <= 0 then og = 1 end
    local kg = 0
    if skipKg ~= true then
        local bw = F.moduleBaseWeight(plantName)
        kg = (bw and bw > 0 and sm > 0) and (bw * sm * og) or 0
    end
    local mut = F.mutationFromData(data)
    local age = tonumber(data.Age) or 0
    local maxAge = tonumber(data.MaxAge) or 0
    local ripe = true
    if maxAge > 0 and age < maxAge then
        ripe = false
    end
    local price = 0
    if skipPrice ~= true then
        price = F.rowPrice(plantName, sm, mut)
    end
    return {
        plantId = tostring(plantId),
        fruitId = tostring(fruitId),
        name = plantName,
        kg = kg,
        price = price,
        mut = mut,
        age = age,
        maxAge = maxAge,
        ripe = ripe,
        sizeMulti = sm,
    }
end

function F.instanceName(model)
    if typeof(model) ~= "Instance" then
        if type(model) == "table" then
            return tostring(model.name or model.PlantName or "")
        end
        return ""
    end
    local n = model:GetAttribute("ItemName")
        or model:GetAttribute("PlantName")
        or model:GetAttribute("SeedName")
        or model:GetAttribute("FruitType")
        or model:GetAttribute("CorePartName")
    if n ~= nil and tostring(n) ~= "" then
        return tostring(n)
    end
    return model.Name
end

function F.rowFromAny(fruit)
    if type(fruit) == "table" and fruit.plantId and fruit.fruitId then
        return fruit
    end
    if typeof(fruit) ~= "Instance" then
        return nil
    end
    local plantId = fruit:GetAttribute("PlantId")
    local fruitId = fruit:GetAttribute("FruitId")
    if F.idPresent(plantId) and F.idPresent(fruitId) then
        local g = F.getGarden()
        local plant = type(g) == "table" and (g[plantId] or g[tostring(plantId)])
        local fruits = type(plant) == "table" and (plant.Fruits or plant.fruits)
        local data = type(fruits) == "table" and (fruits[fruitId] or fruits[tostring(fruitId)])
        local name = tostring(plant and (plant.PlantName or plant.SeedName) or F.instanceName(fruit))
        if type(data) == "table" then
            return F.rowFromData(plantId, fruitId, name, data)
        end
    end
    return {
        plantId = tostring(plantId or ""),
        fruitId = tostring(fruitId or ""),
        name = F.instanceName(fruit),
        kg = tonumber(fruit:GetAttribute("Weight")) or 0,
        price = 0,
        mut = tostring(fruit:GetAttribute("Mutation") or ""),
        ripe = true,
    }
end

function F.plotOwnedByLocal(plot)
    if not plot then return false end
    local uid, name = LP.UserId, LP.Name
    local function match(v)
        if v == nil then return false end
        return v == uid or v == name or tostring(v) == tostring(uid) or tostring(v) == name
    end
    if match(plot:GetAttribute("OwnerId")) then return true end
    if match(plot:GetAttribute("Owner")) then return true end
    if match(plot:GetAttribute("UserId")) then return true end
            return false
end

function F.getPlayerPlot(force)
    local now = os.clock()
    if not force and S.cachedPlot and S.cachedPlot.Parent and (now - S.cachedPlotAt) <= C.PLOT_CACHE_SEC then
        return S.cachedPlot
    end
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then
        S.cachedPlot = nil
        return nil
    end
    local plot
    local id = LP:GetAttribute("PlotId")
    if id ~= nil then
        plot = gardens:FindFirstChild("Plot" .. tostring(id))
    end
    if not plot then
        plot = gardens:FindFirstChild("Plot" .. LP.Name)
    end
    if not plot then
        for _, ch in ipairs(gardens:GetChildren()) do
            if F.plotOwnedByLocal(ch) then
                plot = ch
                break
                end
            end
        end
    S.cachedPlot = plot
    S.cachedPlotAt = now
    return plot
end

----------------------------------------------------------------
-- rules / match
----------------------------------------------------------------
function F.matchSet(selectedMap, value)
    if not F.hasAny(selectedMap) then return true end
    if F.isNoMutationKey(value) then return false end
    local needle = F.canon(value)
    if needle == "normal" or needle == "none" then return false end
    for k, v in pairs(selectedMap) do
        if v == true and not F.isNoMutationKey(k) and F.canon(k) == needle then return true end
    end
    return false
end

function F.selectionHasRealMutation(selectedMap)
    if type(selectedMap) ~= "table" then return false end
    for mutName, on in pairs(selectedMap) do
        if on == true and not F.isNoMutationKey(mutName) then
            return true
        end
    end
    return false
end

function F.matchMutation(selectedMap, row)
    if not F.hasAny(selectedMap) then
        return true
    end
    if type(row) ~= "table" then return false end
    local wantNoMut = selectedMap[C.NO_MUTATION_LABEL] == true
        or selectedMap["No Mutation"] == true
        or selectedMap["None"] == true
    local wantReal = F.selectionHasRealMutation(selectedMap)
    local hasMut = F.fruitHasMutation(row)
    if wantNoMut and not wantReal then
        return not hasMut
    end
    if wantReal and not hasMut then
        return wantNoMut == true
    end
    if wantNoMut and not hasMut then
        return true
    end
    for _, mutName in ipairs(F.parseMutationList(row.mut)) do
        if not F.isNoMutationKey(mutName) and F.matchSet(selectedMap, mutName) then
            return true
        end
    end
    return false
end

function F.matchKg(weight, kg, mode)
    kg, mode = F.normalizeKgFilter(kg, mode)
    weight = tonumber(weight) or 0
    if kg <= 0 then
        return true
    end
    if mode == "below" then
        return weight > 0 and weight <= kg
    end
    return weight >= kg
end

function F.matchPrice(price, filterPrice, mode)
    filterPrice = tonumber(filterPrice) or 0
    if filterPrice <= 0 then return true end
    price = tonumber(price) or 0
    mode = tostring(mode or "above")
    if mode == "below" then
        return price > 0 and price <= filterPrice
    end
    return price >= filterPrice
end

function F.ruleToPersist(rule)
    return {
        id = rule.id,
        enabled = rule.enabled,
        fruits = F.setToArray(rule.fruits),
        mutations = F.setToArray(rule.mutations),
        kg = rule.kg,
        kgMode = rule.kgMode,
        kgRule = rule.kgRule,
        minPrice = rule.minPrice,
        minPriceMode = rule.minPriceMode,
        priceRule = rule.priceRule,
        requireMut = rule.requireMut,
    }
end

function F.normalizeCollectRule(raw)
    raw = type(raw) == "table" and raw or {}
    local fruits = F.normalizeSet(raw.fruits)
    local mutations = F.normalizeSet(raw.mutations)
    local kg, kgMode = F.normalizeKgFilter(raw.kg, raw.kgMode)
    if type(raw.kgRule) == "string" and raw.kgRule:gsub("%s+", "") ~= "" then
        kg, kgMode = F.parseKgRuleInput(raw.kgRule)
    end
    local minPrice, minPriceMode = F.normalizePriceFilter(raw.minPrice, raw.minPriceMode)
    if type(raw.priceRule) == "string" and raw.priceRule:gsub("%s+", "") ~= "" then
        minPrice, minPriceMode = F.parsePriceRuleInput(raw.priceRule)
    end
    return {
        id = tostring(raw.id or ""),
        enabled = raw.enabled ~= false,
        fruits = fruits,
        mutations = mutations,
        kg = kg,
        kgMode = kgMode,
        kgRule = type(raw.kgRule) == "string" and raw.kgRule or F.formatKgRule(kg, kgMode),
        minPrice = minPrice,
        minPriceMode = minPriceMode,
        priceRule = type(raw.priceRule) == "string" and raw.priceRule or F.formatPriceRule(minPrice, minPriceMode),
        requireMut = raw.requireMut == true,
        anyFruit = F.hasAny(fruits),
        anyMut = F.hasAny(mutations),
        anyPrice = minPrice > 0,
    }
end

function F.loadCollectRules(ac)
    ac = type(ac) == "table" and ac or {}
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local mainAc = MAIN and MAIN.auto and MAIN.auto.collect
    -- Argumen pemanggil diutamakan. Global dulu bikin list Sell/Shovel
    -- ketimpa AUTO_COLLECT_RULES (rule "nambah sendiri" + ON/OFF gagal).
    local rawRules, order
    if ac.rules ~= nil then
        rawRules = ac.rules
        order = ac.rulesOrder
    else
        rawRules = G.AUTO_COLLECT_RULES or rawget(_G, "AUTO_COLLECT_RULES")
            or (mainAc and mainAc.rules)
        order = G.AUTO_COLLECT_RULES_ORDER or rawget(_G, "AUTO_COLLECT_RULES_ORDER")
            or (mainAc and mainAc.rulesOrder)
    end
    local byId = {}
    if type(rawRules) == "table" then
        if #rawRules > 0 then
            for _, r in ipairs(rawRules) do
                local norm = F.normalizeCollectRule(r)
                if norm.id == "" then
                    norm.id = "r" .. tostring(_)
                end
                byId[norm.id] = norm
            end
        else
            for id, r in pairs(rawRules) do
                if type(r) == "table" then
                    local norm = F.normalizeCollectRule(r)
                    norm.id = tostring(norm.id ~= "" and norm.id or id)
                    byId[norm.id] = norm
                end
            end
        end
    end
    local out, seen = {}, {}
    if type(order) == "table" then
        for _, id in ipairs(order) do
            id = tostring(id or "")
            local rule = byId[id]
            if rule and not seen[id] then
                seen[id] = true
                out[#out + 1] = rule
            end
        end
    end
    local rest = {}
    for id, rule in pairs(byId) do
        if not seen[id] then
            rest[#rest + 1] = rule
        end
    end
    table.sort(rest, function(a, b)
        return tostring(a.id or "") < tostring(b.id or "")
    end)
    for i = 1, #rest do
        out[#out + 1] = rest[i]
    end
    return out
end

function F.batchFilterKey(ac)
    if type(ac) ~= "table" then return "" end
    local parts = {
        tostring(ac.priority or "off"),
        tostring(#(ac.rules or {})),
        (ac.eclipseSpawnEnabled == true) and "1" or "0",
        tostring(ac.eclipseSpawnKg or 0),
        tostring(ac.eclipseSpawnKgMode or "above"),
    }
    for _, r in ipairs(ac.rules or {}) do
        parts[#parts + 1] = table.concat({
            tostring(r.id or ""),
            (r.enabled == false) and "0" or "1",
            table.concat(F.setToArray(r.fruits), ","),
            table.concat(F.setToArray(r.mutations), ","),
            tostring(r.kg or 0),
            tostring(r.kgMode or "above"),
            tostring(r.minPrice or 0),
            tostring(r.minPriceMode or "above"),
        }, ":")
    end
    return table.concat(parts, "|")
end

function F.matchesCollectRule(row, rule)
    if type(rule) ~= "table" or rule.enabled == false then return false end
    if type(row) ~= "table" then return false end
    if rule.anyFruit and not F.matchSet(rule.fruits, row.name) then return false end
    if rule.kg > 0 then
        local w = tonumber(row.kg) or 0
        if w <= 0 then
            if tostring(rule.kgMode or "above") ~= "below" then
                return false
            end
        elseif not F.matchKg(w, rule.kg, rule.kgMode) then
            return false
        end
    end
    if not F.matchMutation(rule.mutations, row) then
        return false
    end
    if rule.anyPrice and not F.matchPrice(row.price, rule.minPrice, rule.minPriceMode) then
        return false
    end
    return true
end

function F.matchesRules(row, ac)
    local rules = ac and ac.rules
    if type(rules) ~= "table" or #rules == 0 then
        return false
    end
    for _, rule in ipairs(rules) do
        if F.matchesCollectRule(row, rule) then
            return true
        end
    end
    return false
end

function F.isEclipseBloomName(name)
    return F.canon(name) == "eclipsebloom"
end

function F.readEclipseSpawnConfig(ac)
    ac = type(ac) == "table" and ac or {}
    local enabled = G.AUTO_COLLECT_ECLIPSE_SPAWN
    if enabled == nil then enabled = rawget(_G, "AUTO_COLLECT_ECLIPSE_SPAWN") end
    if enabled == nil then enabled = ac.eclipseSpawnEnabled end
    enabled = (enabled == true)
    local kgRule = G.AUTO_COLLECT_ECLIPSE_SPAWN_KG_RULE
        or rawget(_G, "AUTO_COLLECT_ECLIPSE_SPAWN_KG_RULE")
        or ac.eclipseSpawnKgRule
    local kg, kgMode
    if type(kgRule) == "string" and kgRule:gsub("%s+", "") ~= "" then
        kg, kgMode = F.parseKgRuleInput(kgRule)
    else
        kg, kgMode = F.normalizeKgFilter(ac.eclipseSpawnKg, ac.eclipseSpawnKgMode)
    end
    return enabled, kg, kgMode, F.formatKgRule(kg, kgMode)
end

function F.matchesEclipseSpawnKg(row, ac)
    local kg = tonumber(ac and ac.eclipseSpawnKg) or 0
    if kg <= 0 then return true end
    return F.matchKg(tonumber(row.kg) or 0, kg, ac.eclipseSpawnKgMode)
end

function F.isEclipseSpawnReserved(row, ac)
    if not ac or ac.eclipseSpawnEnabled ~= true then return false end
    return F.isEclipseBloomName(row and row.name)
end

function F.isEclipseSpawnCandidate(row, ac)
    if not ac or ac.eclipseSpawnEnabled ~= true then return false end
    if not F.isEclipseBloomName(row and row.name) then return false end
    if not row.ripe then return false end
    return F.matchesEclipseSpawnKg(row, ac) or F.fruitHasMutation(row)
end

----------------------------------------------------------------
-- AC state
----------------------------------------------------------------
function F.getACState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local ac = MAIN and MAIN.auto and MAIN.auto.collect
    ac = type(ac) == "table" and ac or {}
    local delay = F.normalizeDelay(
        G.AUTO_COLLECT_DELAY or rawget(_G, "AUTO_COLLECT_DELAY") or ac.delay,
        0.05
    )
    local priority = tostring(
        G.AUTO_COLLECT_PRIORITY or rawget(_G, "AUTO_COLLECT_PRIORITY") or ac.priority or "off"
    ):lower()
    if priority ~= "price" and priority ~= "rarity" and priority ~= "weight" then
        priority = "off"
    end
    local rules = F.loadCollectRules(ac)
    local eclipseOn, eclipseKg, eclipseKgMode, eclipseKgRule = F.readEclipseSpawnConfig(ac)
    return {
        enabled = F.readEnabled(),
        delay = delay,
        priority = priority,
        filterMode = "rules",
        rules = rules,
        useRules = #rules > 0,
        eclipseSpawnEnabled = eclipseOn,
        eclipseSpawnKg = eclipseKg,
        eclipseSpawnKgMode = eclipseKgMode,
        eclipseSpawnKgRule = eclipseKgRule,
    }
end

function F.getACStateCached()
    local now = os.clock()
    if S.cachedAC and (now - S.cachedACAt) <= C.AC_CACHE_SEC then
        S.cachedAC.enabled = F.readEnabled()
        S.cachedAC.delay = F.liveDelay()
        local pr = G.AUTO_COLLECT_PRIORITY or rawget(_G, "AUTO_COLLECT_PRIORITY")
        if pr then
            pr = tostring(pr):lower()
            if pr == "price" or pr == "rarity" or pr == "weight" then
                S.cachedAC.priority = pr
            end
        end
        if (now - S.rulesReloadAt) >= C.RULES_RELOAD_SEC then
            S.cachedAC.rules = F.loadCollectRules(S.cachedAC)
            S.cachedAC.useRules = #(S.cachedAC.rules or {}) > 0
            S.rulesReloadAt = now
        end
        local MAIN = rawget(_G, "MAIN") or G.MAIN
        local mainAc = MAIN and MAIN.auto and MAIN.auto.collect
        local eclipseOn, eclipseKg, eclipseKgMode, eclipseKgRule = F.readEclipseSpawnConfig(mainAc)
        S.cachedAC.eclipseSpawnEnabled = eclipseOn
        S.cachedAC.eclipseSpawnKg = eclipseKg
        S.cachedAC.eclipseSpawnKgMode = eclipseKgMode
        S.cachedAC.eclipseSpawnKgRule = eclipseKgRule
        return S.cachedAC
    end
    S.cachedAC = F.getACState()
    S.cachedACAt = now
    S.rulesReloadAt = now
    return S.cachedAC
end

function F.clearQueue()
    table.clear(S.matchQueue)
    S.matchIdx = 1
    S.matchBuiltAt = 0
    S.cycleMatchTotal = 0
    S.cycleSkipTotal = 0
end

function F.invalidateACCache(opts)
    opts = type(opts) == "table" and opts or {}
    S.cachedAC = nil
    S.cachedACAt = 0
    S.rulesReloadAt = 0
    if opts.clearQueue == true then
        F.clearQueue()
        table.clear(S.failUntil)
    end
end

function F.dropQueueForLiveRules()
    F.clearQueue()
    table.clear(S.failUntil)
    S.cachedAC = nil
    S.cachedACAt = 0
    S.rulesReloadAt = 0
end

function F.noteFilterAndDropIfChanged()
    local live = F.getACState()
    local newKey = F.batchFilterKey(live)
    local oldKey = S.appliedFilterKey or ""
    S.appliedFilterKey = newKey
    if newKey == oldKey then
        return false
    end
    if oldKey == "" and S.matchBuiltAt <= 0 then
        S.lastFilterKey = newKey
        return false
    end
    F.dropQueueForLiveRules()
    S.lastFilterKey = newKey
    S.appliedFilterKey = newKey
    return true
end

----------------------------------------------------------------
-- weather / eclipse
----------------------------------------------------------------
function F.weatherKey(w)
    if w == nil then return "" end
    return tostring(w)
end

function F.isEclipseWeatherName(w)
    local c = F.canon(w)
    if c == "" then return false end
    if c == "eclipse" or c == "eclipsed" or c == "solareclipse" then return true end
    if c:find("eclipsebloom", 1, true) then return false end
    return c:find("eclipse", 1, true) ~= nil
end

function F.isEclipsePlayingAttr(attrName, val)
    if val ~= true or type(attrName) ~= "string" then return false end
    local base = attrName:match("^(.+)_Playing$")
    if not base then return false end
    return F.isEclipseWeatherName(base)
end

function F.anyEclipsePlayingAttr()
    local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
    if not WeatherValues then return false, nil end
    for _, name in ipairs({ "Eclipse", "Eclipsed", "SolarEclipse", "Solar Eclipse" }) do
        if WeatherValues:GetAttribute(name .. "_Playing") == true then
            return true, name
        end
    end
    for attrName, val in pairs(WeatherValues:GetAttributes()) do
        if F.isEclipsePlayingAttr(attrName, val) then
            local base = attrName:match("^(.+)_Playing$")
            return true, base
        end
    end
    return false, nil
end

function F.readEclipseMapPlaying()
    -- Live = WeatherValues *_Playing. TimeFrozen / ActiveWeather sering nyangkut
    -- setelah Eclipse selesai → hold 77 ripe sampai rejoin.
    local playing, playingName = F.anyEclipsePlayingAttr()
    if playing then
        return true, playingName or "Eclipse"
    end
    local aw = F.weatherKey(workspace:GetAttribute("ActiveWeather"))
    local tf = workspace:GetAttribute("TimeFrozen") == true
    -- AW "Eclipse" + TimeFrozen: mungkin masih live (Playing belom sync).
    -- TimeFrozen sendirian / AW kosong: BUKAN live.
    if tf and aw ~= "" and F.isEclipseWeatherName(aw) then
        return true, aw
    end
    return false, nil
end

function F.refreshEclipseWeather(force)
    local now = os.clock()
    if force ~= true and (now - S.eclWeatherCache.at) <= C.ECLIPSE_WEATHER_CACHE_SEC then
        return S.eclWeatherCache.on == true
    end
    local on, name = F.readEclipseMapPlaying()
    -- Soft recover: TimeFrozen / ActiveWeather sering nyangkut "Eclipse" padahal
    -- cuaca sudah selesai → hold selamanya sampai rejoin. *_Playing = sinyal live.
    -- ActiveWeather kosong juga harus recover (dulu `aw ~= ""` nahan recover).
    if on == true then
        local playing = F.anyEclipsePlayingAttr()
        if playing ~= true then
            local aw = F.weatherKey(workspace:GetAttribute("ActiveWeather"))
            local awIsEcl = aw ~= "" and F.isEclipseWeatherName(aw)
            local tf = workspace:GetAttribute("TimeFrozen") == true
            if tf or awIsEcl or aw == "" then
                if (tonumber(S.eclipseTfSuspectAt) or 0) <= 0 then
                    S.eclipseTfSuspectAt = now
                elseif (now - S.eclipseTfSuspectAt) >= 4 then
                    on = false
                    name = nil
                end
            else
                S.eclipseTfSuspectAt = 0
            end
        else
            S.eclipseTfSuspectAt = 0
        end
    else
        S.eclipseTfSuspectAt = 0
    end
    local prevOn = S.eclWeatherCache.on == true
    local nextOn = (on == true)
    S.eclWeatherCache.at = now
    S.eclWeatherCache.on = nextOn
    S.eclWeatherCache.name = name
    if prevOn ~= nextOn then
            F.onEclipseLiveChanged(prevOn, nextOn)
    end
    return nextOn
end

function F.isEclipseWeather()
    return F.refreshEclipseWeather(false)
end

function F.liveWeatherLabel()
    F.refreshEclipseWeather(false)
    if S.eclWeatherCache.on then
        return tostring(S.eclWeatherCache.name or "Eclipse")
    end
    local aw = F.weatherKey(workspace:GetAttribute("ActiveWeather"))
    if aw == "" then return "?" end
    return aw
end

function F.bindEclipseWeatherWatch()
    if S.eclipseWatchBound then return end
    S.eclipseWatchBound = true
    S.eclipseWatchConns = S.eclipseWatchConns or {}
        for _, c in ipairs(S.eclipseWatchConns) do
            pcall(function() c:Disconnect() end)
        end
        table.clear(S.eclipseWatchConns)

    local function onWeatherSignal()
        F.refreshEclipseWeather(true)
    end

    local wv = ReplicatedStorage:FindFirstChild("WeatherValues")
    if wv then
        S.eclipseWatchConns[#S.eclipseWatchConns + 1] = wv.AttributeChanged:Connect(function(attr)
            if type(attr) == "string" and (attr:find("_Playing", 1, true) or F.isEclipseWeatherName(attr)) then
                onWeatherSignal()
            end
        end)
    else
        task.spawn(function()
            local w = ReplicatedStorage:WaitForChild("WeatherValues", 120)
            if not w or not S.eclipseWatchBound then return end
            S.eclipseWatchConns[#S.eclipseWatchConns + 1] = w.AttributeChanged:Connect(function(attr)
                if type(attr) == "string" and (attr:find("_Playing", 1, true) or F.isEclipseWeatherName(attr)) then
                    onWeatherSignal()
                end
            end)
            onWeatherSignal()
        end)
    end
    pcall(function()
        S.eclipseWatchConns[#S.eclipseWatchConns + 1] =
            workspace:GetAttributeChangedSignal("TimeFrozen"):Connect(onWeatherSignal)
    end)
    pcall(function()
        S.eclipseWatchConns[#S.eclipseWatchConns + 1] =
            workspace:GetAttributeChangedSignal("ActiveWeather"):Connect(onWeatherSignal)
    end)
    onWeatherSignal()
end

----------------------------------------------------------------
-- scan GetGarden
----------------------------------------------------------------
function F.sortMatch(list, priority)
    if type(list) ~= "table" or #list < 2 then return end
    if priority == "price" then
            table.sort(list, function(a, b)
            local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
            if pa ~= pb then return pa > pb end
            return (tonumber(a.kg) or 0) > (tonumber(b.kg) or 0)
        end)
    elseif priority == "weight" or priority == "rarity" then
        table.sort(list, function(a, b)
            local ka, kb = tonumber(a.kg) or 0, tonumber(b.kg) or 0
            if ka ~= kb then return ka > kb end
            return (tonumber(a.price) or 0) > (tonumber(b.price) or 0)
        end)
    end
end

function F.scanNeedPrice(ac)
    if not ac then return false end
    if tostring(ac.priority or "") == "price" then return true end
    local rules = ac.rules
    if type(rules) ~= "table" then return false end
    for i = 1, #rules do
        local rule = rules[i]
        if type(rule) == "table" and rule.enabled ~= false and rule.anyPrice then
    return true
end
    end
    return false
end

function F.scanNeedKg(ac)
    if not ac then return false end
    -- Eclipse spawn: selalu hitung kg (label + sort heaviest), meski filter kg = 0.
    if ac.eclipseSpawnEnabled == true then
        return true
    end
    local pri = tostring(ac.priority or "")
    if pri == "weight" or pri == "rarity" then return true end
    local rules = ac.rules
    if type(rules) ~= "table" then return false end
    for i = 1, #rules do
        local rule = rules[i]
        if type(rule) == "table" and rule.enabled ~= false and (tonumber(rule.kg) or 0) > 0 then
            return true
        end
        end
        return false
end

function F.pushScanRow(row, st)
    if type(row) ~= "table" or not F.idPresent(row.plantId) then return end
    if not row.ripe then return end
    st.ripeN += 1
    local key = F.rowKey(row.plantId, row.fruitId)
    if st.eclOn and F.isEclipseSpawnCandidate(row, st.ac) then
        st.eclipse[#st.eclipse + 1] = row
    end
    if S.pending[key] then return end
    if (tonumber(S.failUntil[key]) or 0) > st.now then
        st.skip += 1
    elseif F.isEclipseSpawnReserved(row, st.ac) then
        st.skip += 1
    elseif F.matchesRules(row, st.ac) then
        st.match[#st.match + 1] = row
    else
        st.skip += 1
    end
end

function F.scanPlantFruits(plantId, plantData, st)
    if type(plantData) ~= "table" then return end
    local name = tostring(
        plantData.PlantName
            or plantData.SeedName
            or plantData.ItemName
            or plantData.FruitName
            or "?"
    )
    if name == "" then name = "?" end
    local fruits = plantData.Fruits or plantData.fruits
    if type(fruits) ~= "table" then
        fruits = {}
    end
    local skipPrice = st.skipPrice
    local skipKg = st.skipKg
    local eclOn = st.eclOn
    local needEclKg = eclOn == true and F.isEclipseBloomName(name)
    local hadFruit = false
    for fruitId, data in pairs(fruits) do
        if type(data) ~= "table" or not F.idPresent(fruitId) then
            continue
        end
        hadFruit = true
        local maxAge = tonumber(data.MaxAge) or 0
        local age = tonumber(data.Age) or 0
        if maxAge > 0 and age < maxAge then
            continue
        end
        local row = F.rowFromData(plantId, fruitId, name, data, skipPrice, skipKg and not needEclKg)
        F.pushScanRow(row, st)
    end
    -- Single-harvest (Carrot/Bamboo): Fruits kosong, panen plant + fruitId ""
    if hadFruit then return end
    if not F.plantIsSingleHarvest(plantData, name) then return end
    local maxAge = tonumber(plantData.MaxAge) or 0
    local age = tonumber(plantData.Age) or 0
    if maxAge > 0 and age < maxAge then return end
    local row = F.rowFromData(plantId, "", name, plantData, skipPrice, skipKg and not needEclKg)
    row.plantHarvest = true
    F.pushScanRow(row, st)
end

function F.scanGarden(ac)
    local garden = F.getGarden()
    local match, eclipse = {}, {}
    if type(garden) ~= "table" then
        return match, 0, eclipse, 0
    end
    local pri = tostring(ac and ac.priority or "off")
    local st = {
        ac = ac,
        now = os.clock(),
        skipPrice = not F.scanNeedPrice(ac),
        skipKg = not F.scanNeedKg(ac),
        eclOn = ac and ac.eclipseSpawnEnabled == true,
        match = match,
        skip = 0,
        eclipse = eclipse,
        ripeN = 0,
    }
    local yieldEvery = tonumber(C.SCAN_YIELD_EVERY) or 0
    local steps = 0
    for plantId, plantData in pairs(garden) do
        F.scanPlantFruits(plantId, plantData, st)
        steps += 1
        if yieldEvery > 0 and steps % yieldEvery == 0 then
                task.wait()
            end
    end
    if pri == "price" or pri == "weight" or pri == "rarity" then
        F.sortMatch(st.match, pri)
    end
    if st.eclOn and #st.eclipse > 1 then
        table.sort(st.eclipse, function(a, b)
            return (tonumber(a.kg) or 0) > (tonumber(b.kg) or 0)
        end)
    end
    return st.match, st.skip, st.eclipse, st.ripeN
end

function F.storeScan(match, skip, eclipse, ripeN)
    local now = os.clock()
    local inN = #match
    S.lastScanMatchN = inN
    S.cycleMatchTotal = inN
    S.cycleSkipTotal = skip
    S.readyCache = ripeN
    S.filteredCache = inN
        S.readyCacheAt = now
        S.filteredCacheAt = now
    S.lastUiScanAt = now
    S.matchQueue = match
    S.matchIdx = 1
    S.matchBuiltAt = now
    S.eclipseCandCache = {
        at = now,
        list = eclipse,
        count = #eclipse,
        bestKg = (eclipse[1] and tonumber(eclipse[1].kg)) or 0,
    }
end

function F.refreshScan(ac)
    if S.scanBusy then return false end
    S.scanBusy = true
    S.scanBusyAt = os.clock()
    S.gardenSnapAt = 0
    local ok, match, skip, eclipse, ripeN = pcall(F.scanGarden, ac)
    S.scanBusy = false
    if not ok then
        H.warn("scan GetGarden fail:", match)
        return false
    end
    F.storeScan(match, skip or 0, eclipse or {}, ripeN or 0)
        return true
end

function F.eclipseListNeedsFill()
    local ac = S.cachedAC
    if not ac or ac.eclipseSpawnEnabled ~= true then return false end
    if F.isBackpackFull() then return false end
    if F.refreshEclipseWeather() then return false end
    local list = S.eclipseCandCache and S.eclipseCandCache.list
    return type(list) ~= "table" or #list <= 0
end

-- Isi ulang kandidat Eclipse saja (jangan reset matchQueue — itu sumber stuck sampai rejoin).
function F.refillEclipseCandOnly(ac)
    ac = ac or F.getACStateCached()
    if not ac or ac.eclipseSpawnEnabled ~= true then
        return 0
    end
    if S.eclipseRefillBusy == true or S.scanBusy == true then
        return tonumber(S.eclipseCandCache and S.eclipseCandCache.count) or 0
    end
    local now = os.clock()
    local gap = tonumber(C.ECLIPSE_CACHE_EMPTY_SCAN_SEC) or 1.5
    local list = S.eclipseCandCache and S.eclipseCandCache.list
    local have = type(list) == "table" and #list > 0
    if have and (now - (tonumber(S.eclipseCandCache.at) or 0)) < gap then
        return #list
    end
    if (not have) and (now - (tonumber(S.eclipseCandCache.at) or 0)) < gap
        and (tonumber(S.eclipseCandCache.at) or 0) > 0 then
        return 0
    end

    S.eclipseRefillBusy = true
    S.gardenSnapAt = 0
    local ok, _match, _skip, eclipse = pcall(F.scanGarden, ac)
    S.eclipseRefillBusy = false
    if not ok or type(eclipse) ~= "table" then
        return 0
    end
    S.eclipseCandCache = {
        at = os.clock(),
        list = eclipse,
        count = #eclipse,
        bestKg = (eclipse[1] and tonumber(eclipse[1].kg)) or 0,
    }
    F.syncEclipseCandMeta()
    return #eclipse
end

function F.queueNeedsRebuild()
    if S.matchBuiltAt <= 0 then return true end
    local ago = os.clock() - S.matchBuiltAt
    -- Antrian match masih ada: jangan full rescan (reset matchIdx).
    -- Eclipse kosong di-handle worker via refillEclipseCandOnly.
    if S.matchIdx <= #S.matchQueue then
        return false
    end
    if F.eclipseListNeedsFill() then
        return ago >= (tonumber(C.ECLIPSE_CACHE_EMPTY_SCAN_SEC) or 1.5)
    end
    -- Scan terakhir 0 match → jeda biar tidak spam GetGarden.
    if (tonumber(S.lastScanMatchN) or 0) <= 0 then
        return ago >= (tonumber(C.SCAN_IDLE_SEC) or 1.25)
    end
    return ago >= (tonumber(C.SCAN_DRAIN_GAP_SEC) or 0.08)
end

function F.peekCachedBreakdown()
    local total = math.max(0, math.floor(tonumber(S.readyCache) or 0))
    local inFilter = math.max(0, math.floor(tonumber(S.filteredCache) or 0))
    if inFilter > total then inFilter = total end
    local outFilter = math.max(0, total - inFilter)
    if S.readyCacheAt <= 0 or S.filteredCacheAt <= 0 then
        return false, {
            total = total,
            inFilter = inFilter,
            outFilter = outFilter,
            pending = true,
        }
    end
    return true, {
        total = total,
        inFilter = inFilter,
        outFilter = outFilter,
        stale = (os.clock() - S.readyCacheAt) > (C.COUNT_STALE_SEC or 45),
        pending = false,
    }
end

function F.refreshCountsAsync(ac, opts)
    opts = type(opts) == "table" and opts or {}
    if S.scanBusy then return false end
    local now = os.clock()
    if not opts.force and S.readyCacheAt > 0 and (now - S.readyCacheAt) < (C.UI_SCAN_MIN_SEC or 2) then
        return false
    end
    task.spawn(function()
        F.refreshScan(ac or F.getACStateCached())
        F.notifyCollectUi()
    end)
    return true
end

----------------------------------------------------------------
-- fire + confirm
----------------------------------------------------------------
function F.fireRemote(plantId, fruitId)
    plantId = tostring(plantId or "")
    fruitId = tostring(fruitId or "")
    -- fruitId "" valid: single-harvest (HarvestPrompt Fire(plantId, fruitId or ""))
    if plantId == "" then return false end
    if not F.ensureRemote() then return false end
            local remote = S.CollectFruit
    local ok = pcall(function()
                    if typeof(remote) == "Instance" then
                        if remote:IsA("RemoteEvent") then
                remote:FireServer(plantId, fruitId)
                            return
                        end
                        if remote:IsA("RemoteFunction") then
                remote:InvokeServer(plantId, fruitId)
                            return
                        end
                    end
        if type(remote.Fire) == "function" then
            remote:Fire(plantId, fruitId)
            return
                    end
                    if type(remote.FireServer) == "function" then
            remote:FireServer(plantId, fruitId)
                        return
                    end
        if type(remote.InvokeServer) == "function" then
            remote:InvokeServer(plantId, fruitId)
                    end
                end)
    return ok
end

function F.collectSucceeded(plantId, fruitId, bagBefore)
    if F.gardenHasFruit(plantId, fruitId) == false then
        return true
    end
    local bag1 = F.bagCount()
    return bagBefore ~= nil and bag1 ~= nil and bag1 > bagBefore
end

function F.confirmAsync(plantId, fruitId, bagBefore, onDone)
    local key = F.rowKey(plantId, fruitId)
    S.pending[key] = os.clock()
    H.rfMarkPendingCollect(plantId, fruitId)
    task.spawn(function()
        task.wait(C.COLLECT_CONFIRM_DELAY)
        local ok = F.collectSucceeded(plantId, fruitId, bagBefore)
        if not ok then
            task.wait(0.75)
            ok = F.collectSucceeded(plantId, fruitId, bagBefore)
        end
        S.pending[key] = nil
        if ok then
            S.totalCollected += 1
            S.lastTickCollected = 1
            S.lastOkAt = os.clock()
            S.failUntil[key] = nil
            F.noteCollectedSoft()
            H.rfClearPendingCollect(plantId, fruitId)
        else
        S.lastTickCollected = 0
            S.lastFailAt = os.clock()
            S.failUntil[key] = os.clock() + (C.COLLECT_FAIL_SKIP_SEC or 1.75)
            H.rfClearPendingCollect(plantId, fruitId)
        end
        if type(onDone) == "function" then
            pcall(onDone, ok)
        end
    end)
end

function F.fireRow(row, tag)
    if type(row) ~= "table" then return false end
    if not F.idPresent(row.plantId) then
        return false
    end
    local key = F.rowKey(row.plantId, row.fruitId)
    if S.pending[key] then return false end
    if (tonumber(S.failUntil[key]) or 0) > os.clock() then return false end
    local bagBefore = F.bagCount()
    if not F.fireRemote(row.plantId, row.fruitId) then
        S.failUntil[key] = os.clock() + (C.COLLECT_FAIL_SKIP_SEC or 1.75)
        S.lastFailAt = os.clock()
        return false
    end
    S.lastFireAt = os.clock()
    S.lastFireTag = tostring(tag or "match")
    if tag == "eclipse" then
        S.eclLastFireAt = S.lastFireAt
        S.eclSkip = "fired"
    end
    F.confirmAsync(row.plantId, row.fruitId, bagBefore, function(ok)
        if tag == "eclipse" and ok ~= true then
            F.readdEclipseCand(row)
        end
    end)
    return true
end

function F.fireNextMatch(ac)
    if H.eclipseShouldHoldMatch() then
        S.lastTickCollected = 0
        return false
    end
    if F.isBackpackFullStable() then
        S.lastTickCollected = 0
        return false
    end
    while S.matchIdx <= #S.matchQueue do
        local row = S.matchQueue[S.matchIdx]
            S.matchIdx += 1
        if row then
            local key = F.rowKey(row.plantId, row.fruitId)
            if S.pending[key] then
                -- skip
            elseif (tonumber(S.failUntil[key]) or 0) > os.clock() then
                -- skip
            elseif F.isEclipseSpawnReserved(row, ac) then
                -- reserved
            else
                return F.fireRow(row, "match")
            end
        end
    end
            return false
        end

function F.syncEclipseCandMeta()
    local list = S.eclipseCandCache.list
    if type(list) ~= "table" then
        S.eclipseCandCache.list = {}
        S.eclipseCandCache.count = 0
        S.eclipseCandCache.bestKg = 0
        S.eclipseSpawnDone = true
        return 0
    end
    S.eclipseCandCache.count = #list
    S.eclipseCandCache.bestKg = (list[1] and tonumber(list[1].kg)) or 0
    if #list <= 0 then
        S.eclipseSpawnDone = true
    else
        S.eclipseSpawnDone = false
    end
    return #list
end

function F.pruneEclipseCand()
    local list = S.eclipseCandCache.list
    if type(list) ~= "table" then
        S.eclipseCandCache.list = {}
        return F.syncEclipseCandMeta()
    end
    for i = #list, 1, -1 do
        local r = list[i]
        if type(r) ~= "table" or not F.idPresent(r.plantId) then
            table.remove(list, i)
        else
            local alive = F.gardenHasFruit(r.plantId, r.fruitId)
            if alive == false then
                table.remove(list, i)
            end
        end
    end
    return F.syncEclipseCandMeta()
end

function F.dropEclipseCand(key)
    local list = S.eclipseCandCache.list
    if type(list) ~= "table" or not key then return end
    for i = #list, 1, -1 do
        local r = list[i]
        if type(r) == "table" and F.rowKey(r.plantId, r.fruitId) == key then
            table.remove(list, i)
        end
    end
    F.syncEclipseCandMeta()
end

function F.readdEclipseCand(row)
    if type(row) ~= "table" then return end
    if not F.idPresent(row.plantId) then return end
    local list = S.eclipseCandCache.list
    if type(list) ~= "table" then
        list = {}
        S.eclipseCandCache.list = list
    end
    local key = F.rowKey(row.plantId, row.fruitId)
    for i = 1, #list do
        local r = list[i]
        if type(r) == "table" and F.rowKey(r.plantId, r.fruitId) == key then
            F.syncEclipseCandMeta()
            return
        end
    end
    list[#list + 1] = row
    F.syncEclipseCandMeta()
end

function F.pickEclipseCand(list)
    if type(list) ~= "table" then return nil end
    local now = os.clock()
    for i = 1, #list do
        local row = list[i]
        if type(row) == "table" and F.idPresent(row.plantId) then
            local key = F.rowKey(row.plantId, row.fruitId)
            if not S.pending[key] and (tonumber(S.failUntil[key]) or 0) <= now then
                return row, key
            end
                end
            end
    return nil
end

function F.tryEclipseSpawnCollect(ac)
    -- Ringan: jangan refreshScan / waitScanIdle (itu yang nahan Auto Collect).
    -- Pakai cache GetGarden dari loop utama + fireRow async.
    if not ac or ac.eclipseSpawnEnabled ~= true then return false end
    if S.eclipseSpawnKickBusy then return false end
    S.eclipseSpawnKickBusy = true
    S.eclKickAt = os.clock()
    local fired = false
    local okRun, err = pcall(function()
        if H.isFarFromOwnPlot() then
            S.eclipseHoldMatch = false
            S.eclSkip = "far"
            return
        end
        if F.refreshEclipseWeather() then
            S.eclipseHoldMatch = false
            S.eclSkip = "hold"
            return
        end
        if F.isBackpackFull() then
            S.eclipseHoldMatch = false
            S.eclSkip = "backpack"
            return
        end
        if not F.ensureRemote() then
            S.eclipseHoldMatch = false
            S.eclSkip = "no_remote"
            return
        end
        F.pruneEclipseCand()
        local row, key = F.pickEclipseCand(S.eclipseCandCache.list)
        -- Cache kosong / semua pending|failUntil → refill GetGarden (tanpa reset match).
        if not row or not key then
            F.refillEclipseCandOnly(ac)
            F.pruneEclipseCand()
            row, key = F.pickEclipseCand(S.eclipseCandCache.list)
        end
        if not row or not key then
            S.eclipseHoldMatch = false
            S.eclSkip = "no_cand"
            return
        end
        S.eclipseHoldMatch = false
        S.eclipseSpawnDone = false
        if not F.fireRow(row, "eclipse") then
            -- Jangan drop: fruit masih di kebun, worker retry setelah failUntil.
            S.eclSkip = "fire_fail"
            return
        end
        S.eclipseSpawnDoneAt = os.clock()
        F.dropEclipseCand(key)
        fired = true
    end)
    S.eclipseSpawnKickBusy = false
    if not okRun then
        H.warn("eclipse spawn collect fail:", err)
        return false
    end
    return fired == true
end

F.kickEclipseSpawnNow = function(reason)
    if S.eclipseSpawnKickBusy then return false end
    if not S.running then return false end
    local ac = F.getACStateCached()
    if not ac or ac.enabled ~= true or ac.eclipseSpawnEnabled ~= true then
        return false
    end
    if F.refreshEclipseWeather(true) then
        S.eclipseHoldMatch = false
        pcall(F.rebuildUiSnap)
        return false
    end
    if H.eclipseSpawnInMinGap() then
        S.eclipseHoldMatch = false
        pcall(F.rebuildUiSnap)
        return false
    end
    if F.isBackpackFull() then
        pcall(F.rebuildUiSnap)
        return false
    end
    S.eclipseHoldMatch = false
    task.spawn(function()
        local ok, err = pcall(function()
            F.tryEclipseSpawnCollect(ac)
            S.eclipseHoldMatch = false
            F.rebuildUiSnap()
            F.notifyCollectUi()
        end)
        if not ok then
            H.warn("eclipse spawn kick fail:", reason, err)
            S.eclipseHoldMatch = false
        end
    end)
    return true
end

F.onEclipseLiveChanged = function(wasOn, nowOn)
    S.eclipseCandCache.at = 0
    if nowOn then
        if S.eclipseLiveSince <= 0 then
            S.eclipseLiveSince = os.clock()
        end
        if (os.clock() - S.eclipseLiveSince) >= 1.5 then
            S.eclipseSpawnDone = false
        end
        S.eclipseHoldMatch = false
        pcall(F.rebuildUiSnap)
        F.notifyCollectUi()
        return
    end
    S.eclipseLiveSince = 0
    if wasOn == true then
        S.eclipseHoldMatch = false
        F.kickEclipseSpawnNow("eclipse_end")
        return
    end
    pcall(F.rebuildUiSnap)
    F.notifyCollectUi()
end

function F.startEclipseWeatherWorker()
    S.eclipseSpawnWorkerId += 1
    local my = S.eclipseSpawnWorkerId
    F.bindEclipseWeatherWatch()
    task.spawn(function()
        while S.running and my == S.eclipseSpawnWorkerId do
            task.wait(C.ECLIPSE_WEATHER_POLL_SEC or 0.5)
            if not S.running or my ~= S.eclipseSpawnWorkerId then return end
            local ac = F.getACStateCached()
            if not ac or ac.enabled ~= true or ac.eclipseSpawnEnabled ~= true then
                S.eclSkip = "ac_off"
                continue
            end
            local live = F.refreshEclipseWeather(true)
            if live then
                if S.eclipseLiveSince <= 0 then
                    S.eclipseLiveSince = os.clock()
                end
                if (os.clock() - S.eclipseLiveSince) >= 1.5 then
                    S.eclipseSpawnDone = false
                end
                S.eclipseHoldMatch = false
                S.eclSkip = "hold"
                continue
            end
            S.eclipseLiveSince = 0
            if F.isBackpackFull() or H.isFarFromOwnPlot() then
                S.eclSkip = F.isBackpackFull() and "backpack" or "far"
                continue
            end
            if H.eclipseSpawnInMinGap() then
                S.eclipseHoldMatch = false
                S.eclSkip = "gap"
                continue
            end
            -- Paksa refill berkala kalau list kosong (buah banyak di GetGarden tapi cache mati).
            if F.eclipseListNeedsFill() then
                F.refillEclipseCandOnly(ac)
            end
            F.tryEclipseSpawnCollect(ac)
        end
    end)
end

function F.agoTxt(at)
    at = tonumber(at) or 0
    if at <= 0 then return "-" end
    return string.format("%.0f", os.clock() - at)
end

-- Kode pendek buat screenshot/paste. STUCK = macet, bukan delay biasa.
function F.buildStuckDiag(ac)
    local now = os.clock()
    local pend, failN = 0, 0
    if type(S.pending) == "table" then
        for _, t in pairs(S.pending) do
            if t then pend += 1 end
        end
    end
    if type(S.failUntil) == "table" then
        for _, untilT in pairs(S.failUntil) do
            if (tonumber(untilT) or 0) > now then failN += 1 end
        end
    end
    local qLeft = math.max(0, #S.matchQueue - S.matchIdx + 1)
    if S.matchIdx > #S.matchQueue then qLeft = 0 end
    local reserved = 0
    if ac and ac.eclipseSpawnEnabled == true then
        for i = S.matchIdx, #S.matchQueue do
            if F.isEclipseSpawnReserved(S.matchQueue[i], ac) then
                reserved += 1
            end
        end
    end
    local matchN = tonumber(S.cycleMatchTotal) or 0
    local fireAgo = (tonumber(S.lastFireAt) or 0) > 0 and (now - S.lastFireAt) or -1
    local beatAgo = (tonumber(S.loopBeatAt) or 0) > 0 and (now - S.loopBeatAt) or -1
    local scanAgo = (tonumber(S.scanBusyAt) or 0) > 0 and (now - S.scanBusyAt) or -1
    local acWhy = tostring(S.loopWait ~= "" and S.loopWait or "ok")
    local stuckAc = false
    if not F.readEnabled() then
        acWhy = "off"
    elseif S.running ~= true then
        acWhy = "no_run"
        stuckAc = true
    elseif (tonumber(S.loopAliveId) or 0) <= 0 then
        acWhy = "no_loop"
        stuckAc = true
    elseif beatAgo >= 0 and beatAgo > 3 then
        acWhy = string.format("loop_freeze %.0fs", beatAgo)
        stuckAc = true
    elseif S.scanBusy == true and scanAgo > 2.5 then
        acWhy = string.format("scan_stuck %.0fs", scanAgo)
        stuckAc = true
    elseif F.isBackpackFull() then
        acWhy = "backpack"
    elseif H.isFarFromOwnPlot() then
        acWhy = "far"
    elseif not F.remoteCanFire(S.CollectFruit) then
        acWhy = "no_remote"
        stuckAc = true
    elseif not F.bootReady(ac) then
        acWhy = "boot"
    elseif qLeft > 0 and reserved >= qLeft and reserved > 0 then
        acWhy = "all_ecl_hold"
    elseif qLeft > 0 and pend > 0 and fireAgo > 2 then
        acWhy = "pending"
    elseif qLeft > 0 and failN > 0 and fireAgo > 3 then
        acWhy = "fail_skip"
    elseif qLeft > 0 and fireAgo > 4 then
        acWhy = string.format("idle_q %.0fs", fireAgo)
        stuckAc = true
    elseif fireAgo > 8 and matchN > 0 then
        acWhy = string.format("no_fire %.0fs", fireAgo)
        stuckAc = true
    elseif matchN <= 0 then
        acWhy = "no_match"
    end

    local eclOn = ac and ac.eclipseSpawnEnabled == true
    local cand = tonumber(S.eclipseCandCache and S.eclipseCandCache.count) or 0
    local eclWhy = "off"
    local stuckEcl = false
    if not eclOn then
        eclWhy = "off"
    elseif not F.readEnabled() or S.running ~= true then
        eclWhy = "ac_off"
        stuckEcl = F.readEnabled() == true and S.running ~= true
    elseif F.isBackpackFull() then
        eclWhy = "backpack"
    elseif H.isFarFromOwnPlot() then
        eclWhy = "far"
    elseif S.eclWeatherCache and S.eclWeatherCache.on == true then
        eclWhy = "hold"
    elseif S.eclipseSpawnKickBusy == true then
        local kAgo = (tonumber(S.eclKickAt) or 0) > 0 and (now - S.eclKickAt) or 0
        if kAgo > 2.5 then
            eclWhy = string.format("kick_stuck %.0fs", kAgo)
            stuckEcl = true
        else
            eclWhy = "firing"
        end
    elseif S.eclipseRefillBusy == true then
        eclWhy = "refill"
    elseif H.eclipseSpawnInMinGap() then
        eclWhy = "gap"
    elseif cand <= 0 then
        eclWhy = tostring(S.eclSkip ~= "" and S.eclSkip or "no_cand")
    else
        local pickRow = F.pickEclipseCand(S.eclipseCandCache and S.eclipseCandCache.list)
        if not pickRow then
            eclWhy = "cand_blocked"
            stuckEcl = true
        else
            local eAgo = (tonumber(S.eclLastFireAt) or 0) > 0 and (now - S.eclLastFireAt) or -1
            if eAgo < 0 or eAgo > 4 then
                eclWhy = string.format("no_fire %.0fs", eAgo < 0 and 99 or eAgo)
                stuckEcl = true
            else
                eclWhy = "ok"
            end
        end
    end

    local wname = "?"
    if S.eclWeatherCache and S.eclWeatherCache.on == true then
        wname = tostring(S.eclWeatherCache.name or "Eclipse")
    else
        wname = tostring(F.weatherKey(workspace:GetAttribute("ActiveWeather")) or "?")
        if wname == "" then wname = "?" end
    end
    local dbg = string.format(
        "ac:%s%s q=%d/%d p=%d f=%d last=%s %ss | ecl:%s%s cand=%d w=%s",
        stuckAc and "STUCK " or "",
        acWhy,
        matchN,
        qLeft,
        pend,
        failN,
        tostring(S.lastFireTag ~= "" and S.lastFireTag or "-"),
        F.agoTxt(S.lastFireAt),
        stuckEcl and "STUCK " or "",
        eclWhy,
        cand,
        wname
    )
    return dbg, acWhy, eclWhy, stuckAc, stuckEcl
end

F.rebuildUiSnap = function()
    local ac = F.getACStateCached()
    local matchIn = math.max(0, math.floor(tonumber(S.cycleMatchTotal) or 0))
    local skipN = math.max(0, math.floor(tonumber(S.cycleSkipTotal) or 0))
    local queueN = math.max(0, #S.matchQueue - S.matchIdx + 1)
    if S.matchIdx > #S.matchQueue then queueN = 0 end
    local ready = matchIn + skipN
    local hasCache = S.matchBuiltAt > 0 or (S.readyCacheAt > 0 and ready > 0)
    local bootWait = (type(ac.rules) == "table" and #ac.rules > 0) and not F.bootReady(ac)
    local scanning = (not hasCache and not bootWait and S.scanBusy == true)
    local runHint = "OFF"
    if F.isBackpackFull() then
        runHint = "backpack full"
    elseif not F.readEnabled() then
        runHint = "OFF"
    elseif H.isFarFromOwnPlot() then
        local d = tonumber(S.nearPlotDist)
        runHint = d and ("far %.0fstu"):format(d) or "far_plot"
    elseif not F.remoteCanFire(S.CollectFruit) then
        runHint = "no remote"
    elseif bootWait then
        runHint = "booting"
    elseif S.loopAliveId > 0 then
        runHint = (S.lastTickCollected == 1) and "collecting" or "running"
    elseif S.running == true then
        runHint = "starting..."
    else
        runHint = "paused"
    end
    local eclOn = ac.eclipseSpawnEnabled == true
    local weatherEcl = S.eclWeatherCache.on == true
    local weather
    if weatherEcl then
        weather = tostring(S.eclWeatherCache.name or "Eclipse")
    else
        local aw = F.weatherKey(workspace:GetAttribute("ActiveWeather"))
        weather = (aw ~= "" and aw) or "?"
    end
    local count = tonumber(S.eclipseCandCache.count) or 0
    local bestKg = tonumber(S.eclipseCandCache.bestKg) or 0
    local phase = "OFF"
    if not eclOn then
        phase = "OFF"
    elseif F.isBackpackFull() then
        phase = "backpack full"
    elseif weatherEcl then
        phase = "hold"
    elseif S.eclipseSpawnKickBusy then
        phase = "collecting"
    elseif count > 0 then
        phase = "ready"
    else
        phase = "no ripe"
    end
    S.uiSnap = {
        at = os.clock(),
        matchIn = matchIn,
        matchOut = skipN,
        matchCached = hasCache,
        matchScanning = scanning,
        matchBooting = bootWait == true and not hasCache,
        batchPending = queueN,
        runHint = runHint,
        enabled = F.readEnabled(),
        running = S.running == true,
        loopAlive = S.loopAliveId > 0,
        backpackFull = F.isBackpackFull(),
        lastTickCollected = S.lastTickCollected,
        eclipseSpawnEnabled = eclOn,
        eclipseSpawnKgRule = ac.eclipseSpawnKgRule or "0",
        weatherEclipse = weatherEcl,
        weather = weather,
        eclipseDone = S.eclipseSpawnDone == true,
        eclipseRetryIn = 0,
        eclipseCount = count,
        eclipseBestKg = bestKg,
        eclipsePhase = phase,
        source = "GetGarden",
        dbg = "",
        acWhy = "",
        eclWhy = "",
        stuckAc = false,
        stuckEcl = false,
    }
    local dbg, acWhy, eclWhy, stuckAc, stuckEcl = F.buildStuckDiag(ac)
    S.uiSnap.dbg = dbg
    S.uiSnap.acWhy = acWhy
    S.uiSnap.eclWhy = eclWhy
    S.uiSnap.stuckAc = stuckAc == true
    S.uiSnap.stuckEcl = stuckEcl == true
    return S.uiSnap
end

        ----------------------------------------------------------------
-- main loop
        ----------------------------------------------------------------
function F.collectLoop(myId)
    S.loopAliveId = myId
    H.log("loop start GetGarden", myId)
    F.ensureRemote()
    F.startEclipseWeatherWorker()
    while S.running and S.loopId == myId do
        S.loopBeatAt = os.clock()
        local ac = F.getACStateCached()
        if not F.readEnabled() then
            S.loopWait = "off"
                task.wait(0.2)
        elseif not F.bootReady(ac) then
            S.loopWait = "boot"
            task.wait(0.15)
        elseif not F.ensureRemote() then
            S.loopWait = "no_remote"
            task.wait(0.5)
        elseif H.isFarFromOwnPlot() or H.isResumeCatchup() then
            S.loopWait = H.isFarFromOwnPlot() and "far" or "resume"
            task.wait(0.25)
        elseif F.isBackpackFullStable() then
            S.loopWait = "backpack"
            if F.queueNeedsRebuild() then
                F.refreshScan(ac)
            end
            F.rebuildUiSnap()
                task.wait(0.45)
        else
            if F.queueNeedsRebuild() then
                S.loopWait = "scan"
                F.refreshScan(ac)
                F.rebuildUiSnap()
            end
            local did = F.fireNextMatch(ac)
                if did then
                S.loopWait = "fire"
                F.waitAfterFire(ac)
            elseif F.queueNeedsRebuild() then
                S.loopWait = "rescan"
                F.refreshScan(ac)
                F.rebuildUiSnap()
            else
                S.loopWait = "idle"
                task.wait(C.IDLE_WAIT_SEC or 0.25)
                end
            end
        end
    S.eclipseSpawnWorkerId += 1
    if S.loopAliveId == myId then S.loopAliveId = 0 end
    H.log("loop end", myId)
end

----------------------------------------------------------------
-- public API
----------------------------------------------------------------
function F.coerceOn(a, b)
    if type(a) == "table" then return b == true end
    return a == true
end

function M.SetEnabled(a, b)
    local on = F.coerceOn(a, b)
    G.AUTO_COLLECT_FRUIT_ENABLED = on
    _G.AUTO_COLLECT_FRUIT_ENABLED = on
    F.writeMainCollect({ enabled = on })
    if on then
        F.invalidateACCache()
        S.running = true
        if S.loopAliveId > 0 and S.loopAliveId == S.loopId then return end
        S.loopId += 1
        local myId = S.loopId
        task.spawn(function()
            local ok, err = pcall(F.collectLoop, myId)
            if not ok then
                H.warn("loop error:", err)
                if S.loopAliveId == myId then S.loopAliveId = 0 end
            end
        end)
    else
        S.running = false
        S.loopId += 1
        F.dropQueueForLiveRules()
    end
end

M.setEnabled = M.SetEnabled
M.Start = function() return M.SetEnabled(true) end
M.start = M.Start
M.Stop = function() return M.SetEnabled(false) end
M.stop = M.Stop
M.HaltLoop = function()
    S.running = false
    S.loopId += 1
    F.dropQueueForLiveRules()
end
M.haltLoop = M.HaltLoop
M.IsRunning = function()
    return S.running == true and S.loopAliveId > 0
end
M.isRunning = M.IsRunning

function M.EnsureRunning()
    if not F.readEnabled() then
        M.HaltLoop()
        return false
    end
    if S.running and S.loopAliveId > 0 and S.loopAliveId == S.loopId then
        return true
    end
    M.Start()
    return S.running and S.loopAliveId > 0
end
M.ensureRunning = M.EnsureRunning

function F.applySet(keyGlobal, keyMain, map)
    map = F.normalizeSet(map)
    G[keyGlobal] = map
    _G[keyGlobal] = map
    F.writeMainCollect({ [keyMain] = F.setToArray(map) })
    F.invalidateACCache()
    return map
end

function M.SetFruits(a, b)
    local map = (type(a) == "table" and b ~= nil) and b or a
    return F.applySet("AUTO_COLLECT_FRUITS_SELECTED", "fruits", map)
end
M.SetSelected = M.SetFruits
M.setSelected = M.SetFruits
M.setFruits = M.SetFruits

function M.SetMutations(a, b)
    local map = (type(a) == "table" and b ~= nil) and b or a
    return F.applySet("AUTO_COLLECT_MUTATIONS_SELECTED", "mutations", map)
end
M.setMutations = M.SetMutations

function M.SetKgFilter(a, b, c)
    local kg, mode
    if type(a) == "table" then
        kg, mode = b, c
    else
        kg, mode = a, b
    end
    kg, mode = F.normalizeKgFilter(kg, mode)
    local rule = F.formatKgRule(kg, mode)
    G.AUTO_COLLECT_KG = kg
    G.AUTO_COLLECT_KG_MODE = mode
    G.AUTO_COLLECT_KG_RULE = rule
    _G.AUTO_COLLECT_KG = kg
    _G.AUTO_COLLECT_KG_MODE = mode
    _G.AUTO_COLLECT_KG_RULE = rule
    F.writeMainCollect({ kg = kg, kgMode = mode, kgRule = rule })
    F.invalidateACCache()
end
M.setKgFilter = M.SetKgFilter

function M.SetFilterMode(_mode)
    G.AUTO_COLLECT_FILTER_MODE = "rules"
    _G.AUTO_COLLECT_FILTER_MODE = "rules"
    F.writeMainCollect({ filterMode = "rules" })
    F.invalidateACCache()
    return "rules"
end
M.setFilterMode = M.SetFilterMode

function M.SetRules(rules, order)
    rules = type(rules) == "table" and rules or {}
    order = type(order) == "table" and order or {}
    G.AUTO_COLLECT_RULES = rules
    _G.AUTO_COLLECT_RULES = rules
    G.AUTO_COLLECT_RULES_ORDER = order
    _G.AUTO_COLLECT_RULES_ORDER = order
    F.writeMainCollect({ rules = rules, rulesOrder = order })
    F.invalidateACCache()
    local dropped = F.noteFilterAndDropIfChanged()
    if #rules > 0 then
        if S.rulesReadyAt <= 0 then
            S.rulesReadyAt = os.clock()
        end
    else
        S.rulesReadyAt = 0
        if not dropped then
            F.dropQueueForLiveRules()
        end
    end
end
M.setRules = M.SetRules

function M.AddRule(rule)
    rule = F.normalizeCollectRule(rule)
    if rule.id == "" then
        rule.id = "r" .. tostring(math.floor(os.clock() * 1000)) .. "_" .. tostring(math.random(1000, 9999))
    end
    local ac = F.getACStateCached()
    local rules, order = {}, {}
    for _, r in ipairs(ac.rules or {}) do
        rules[#rules + 1] = F.ruleToPersist(r)
        order[#order + 1] = r.id
    end
    rules[#rules + 1] = F.ruleToPersist(rule)
    order[#order + 1] = rule.id
    M.SetRules(rules, order)
    return rule.id
end
M.addRule = M.AddRule

function M.RemoveRule(ruleId)
    ruleId = tostring(ruleId or "")
    if ruleId == "" then return end
    local ac = F.getACStateCached()
    local rules, order = {}, {}
    for _, r in ipairs(ac.rules or {}) do
        if r.id ~= ruleId then
            rules[#rules + 1] = F.ruleToPersist(r)
            order[#order + 1] = r.id
        end
    end
    M.SetRules(rules, order)
end
M.removeRule = M.RemoveRule

function M.GetRules()
    local ac = F.getACStateCached()
    return ac.rules or {}, "rules"
end
M.getRules = M.GetRules

function M.SetDelay(a, b)
    local n = F.normalizeDelay(type(a) == "table" and b or a, 0.05)
    G.AUTO_COLLECT_DELAY = n
    _G.AUTO_COLLECT_DELAY = n
    F.writeMainCollect({ delay = n })
    if S.cachedAC then S.cachedAC.delay = n end
end
M.setDelay = M.SetDelay

function M.SetPriority(a, b)
    local mode = (type(a) == "table" and b) or a
    mode = tostring(mode or "off"):lower()
    if mode ~= "price" and mode ~= "rarity" and mode ~= "weight" then
        mode = "off"
    end
    G.AUTO_COLLECT_PRIORITY = mode
    _G.AUTO_COLLECT_PRIORITY = mode
    F.writeMainCollect({ priority = mode })
    if S.cachedAC then S.cachedAC.priority = mode end
    return mode
end
M.setPriority = M.SetPriority

function M.SetEclipseSpawn(cfg)
    cfg = type(cfg) == "table" and cfg or {}
    local enabled = cfg.enabled
    if enabled == nil then enabled = cfg.eclipseSpawnEnabled end
    enabled = (enabled == true)
    local kgRule = cfg.kgRule or cfg.eclipseSpawnKgRule
    local kg, kgMode
    if type(kgRule) == "string" and kgRule:gsub("%s+", "") ~= "" then
        kg, kgMode = F.parseKgRuleInput(kgRule)
    else
        kg, kgMode = F.normalizeKgFilter(cfg.kg or cfg.eclipseSpawnKg, cfg.kgMode or cfg.eclipseSpawnKgMode)
    end
    kgRule = F.formatKgRule(kg, kgMode)
    G.AUTO_COLLECT_ECLIPSE_SPAWN = enabled
    _G.AUTO_COLLECT_ECLIPSE_SPAWN = enabled
    G.AUTO_COLLECT_ECLIPSE_SPAWN_KG_RULE = kgRule
    _G.AUTO_COLLECT_ECLIPSE_SPAWN_KG_RULE = kgRule
    F.writeMainCollect({
        eclipseSpawnEnabled = enabled,
        eclipseSpawnKgRule = kgRule,
        eclipseSpawnKg = kg,
        eclipseSpawnKgMode = kgMode,
    })
    S.eclipseSpawnDone = false
    S.eclipseSpawnDoneAt = 0
    S.eclipseHoldMatch = false
    if S.cachedAC then
        S.cachedAC.eclipseSpawnEnabled = enabled
        S.cachedAC.eclipseSpawnKg = kg
        S.cachedAC.eclipseSpawnKgMode = kgMode
        S.cachedAC.eclipseSpawnKgRule = kgRule
    end
    F.noteFilterAndDropIfChanged()
    if enabled then
        F.bindEclipseWeatherWatch()
        -- Kalau cache Bloom masih kosong, paksa loop utama scan (jangan nunggu 8s).
        local eclList = S.eclipseCandCache and S.eclipseCandCache.list
        if type(eclList) ~= "table" or #eclList <= 0 then
            S.matchBuiltAt = 0
        end
        if F.readEnabled() then
            if not S.running then
                S.running = true
                M.EnsureRunning()
            end
            F.startEclipseWeatherWorker()
            if not F.refreshEclipseWeather(true) then
            F.kickEclipseSpawnNow("toggle_on")
            end
        end
    end
    pcall(F.rebuildUiSnap)
    return {
        enabled = enabled,
        kgRule = kgRule,
        kg = kg,
        kgMode = kgMode,
    }
end
M.setEclipseSpawn = M.SetEclipseSpawn

function M.GetEclipseSpawn()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local on, kg, mode, rule = F.readEclipseSpawnConfig(
        MAIN and MAIN.auto and MAIN.auto.collect
    )
    return {
        enabled = on,
        kg = kg,
        kgMode = mode,
        kgRule = rule,
        done = S.eclipseSpawnDone == true,
        weatherEclipse = F.isEclipseWeather(),
        weather = F.liveWeatherLabel(),
        retryIn = 0,
    }
end
M.getEclipseSpawn = M.GetEclipseSpawn

function M.PeekEclipseSpawnStatus()
    pcall(F.rebuildUiSnap)
    local snap = S.uiSnap or {}
    return {
        enabled = snap.eclipseSpawnEnabled == true,
        kgRule = snap.eclipseSpawnKgRule or "0",
        count = tonumber(snap.eclipseCount) or 0,
        bestAge = 0,
        bestKg = tonumber(snap.eclipseBestKg) or 0,
        bestFruitId = "",
        done = snap.eclipseDone == true,
        weatherEclipse = snap.weatherEclipse == true,
        weather = tostring(snap.weather or "?"),
        backpackFull = snap.backpackFull == true,
        retryIn = tonumber(snap.eclipseRetryIn) or 0,
        phase = snap.eclipsePhase or "OFF",
        cached = true,
    }
end
M.peekEclipseSpawnStatus = M.PeekEclipseSpawnStatus

function M.GetUiSnapshot()
    return F.rebuildUiSnap()
end
M.getUiSnapshot = M.GetUiSnapshot

function M.EstimateFruitValue(model)
    local row = F.rowFromAny(model)
    if row then return tonumber(row.price) or 0 end
    if type(S.fruitSellValue) == "table" and type(S.fruitSellValue.fromFruit) == "function" then
        local ok, p = pcall(S.fruitSellValue.fromFruit, model)
        if ok then return tonumber(p) or 0 end
    end
    return 0
end
M.estimateFruitValue = M.EstimateFruitValue

function M.SyncFromState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local collect = MAIN and MAIN.auto and MAIN.auto.collect
    if type(collect) ~= "table" then
        return false
    end
    local ac = F.getACState()
    M.SetFilterMode("rules")
    local mainRules = collect.rules
    local mainOrder = collect.rulesOrder
    if type(ac.rules) == "table" then
        local rules, order = {}, {}
        for _, r in ipairs(ac.rules) do
            rules[#rules + 1] = F.ruleToPersist(r)
            order[#order + 1] = r.id
        end
        if type(mainRules) == "table" and #mainRules > 0 then
            M.SetRules(mainRules, mainOrder or {})
        else
            M.SetRules(rules, order)
        end
    end
    M.SetDelay(ac.delay)
    M.SetPriority(ac.priority)
    -- Loop dulu, baru Eclipse spawn. Kalau spawn dulu, S.running masih false → kick skip
    -- → user harus toggle / ubah kg supaya SetEclipseSpawn jalan lagi.
    local wantOn = ac.enabled == true or collect.enabled == true
        or G.AUTO_COLLECT_FRUIT_ENABLED == true
        or rawget(_G, "AUTO_COLLECT_FRUIT_ENABLED") == true
    if wantOn then
        G.AUTO_COLLECT_FRUIT_ENABLED = true
        _G.AUTO_COLLECT_FRUIT_ENABLED = true
        F.writeMainCollect({ enabled = true })
        S.running = true
        M.EnsureRunning()
    else
        -- Halt saja. SetEnabled(false) nulis MAIN.enabled=false — itu yang bikin toggle OFF
        -- setelah reload / apply config tanpa enabled.
        M.HaltLoop()
        M.SetEclipseSpawn({
            enabled = ac.eclipseSpawnEnabled == true,
            kgRule = ac.eclipseSpawnKgRule,
            kg = ac.eclipseSpawnKg,
            kgMode = ac.eclipseSpawnKgMode,
        })
        return true
    end
    M.SetEclipseSpawn({
        enabled = ac.eclipseSpawnEnabled == true or collect.eclipseSpawnEnabled == true,
        kgRule = ac.eclipseSpawnKgRule or collect.eclipseSpawnKgRule,
        kg = ac.eclipseSpawnKg,
        kgMode = ac.eclipseSpawnKgMode,
    })
    return true
end
M.syncFromState = M.SyncFromState

do
    local NodeHubWS = G.NodeHubWS or rawget(_G, "NodeHubWS")
if type(NodeHubWS) == "table" and type(NodeHubWS.OnApplyUI) == "function" then
    NodeHubWS.OnApplyUI("gag2", "auto_collect_runtime", function(config, message, bridge, api)
        local collect = api.get(config, "main.auto.collect")
        if type(collect) ~= "table" then return true end
        -- Jangan anggap nil = OFF. Apply parsial / config tanpa enabled mematikan toggle.
        if collect.enabled ~= nil then
            G.AUTO_COLLECT_FRUIT_ENABLED = collect.enabled == true
            _G.AUTO_COLLECT_FRUIT_ENABLED = collect.enabled == true
            if collect.enabled == true then
                F.writeMainCollect({ enabled = true })
            elseif collect.enabled == false then
                F.writeMainCollect({ enabled = false })
            end
        end
            if collect.delay ~= nil then pcall(M.SetDelay, collect.delay) end
            if collect.priority ~= nil then pcall(M.SetPriority, collect.priority) end
            if type(collect.fruits) == "table" then pcall(M.SetFruits, api.selectedMap(collect.fruits)) end
            if type(collect.mutations) == "table" then pcall(M.SetMutations, api.selectedMap(collect.mutations)) end
            if type(collect.rules) == "table" then pcall(M.SetRules, collect.rules, collect.rulesOrder or {}) end
        if collect.kg ~= nil or collect.kgRule ~= nil then
                pcall(M.SetKgFilter, collect.kg or collect.kgRule, collect.kgMode)
        end
            if collect.eclipseSpawnEnabled ~= nil then pcall(M.SetEclipseSpawn, collect) end
            pcall(M.SyncFromState)
        return true
    end)
    end
end

