function M.DumpState()
    local st = M.GetStats()
    local ac = F.getACStateCached()
    H.warn("========== AUTO COLLECT DUMP (GetGarden) ==========")
    H.warn("running:", st.running, "| enabled:", ac.enabled, "| remote:", F.ensureRemote())
    H.warn("ready:", st.readyQueue, "| filtered:", st.filteredQueue, "| pending:", st.batchPending)
    H.warn("last fire:", st.lastTickCollected, "| total fired:", st.totalCollected)
    H.warn("filters: rules=", #(ac.rules or {}), "useRules=", ac.useRules)
    H.warn("priority:", ac.priority)
    H.warn("eclipseSpawn:", ac.eclipseSpawnEnabled == true, "kg=", ac.eclipseSpawnKgRule or ac.eclipseSpawnKg)
    H.warn("bootReady:", F.bootReady(ac), "rulesReadyAt=", S.rulesReadyAt)
    H.warn("gardenLoaded:", F.gardenLoaded())
    for i, r in ipairs(ac.rules or {}) do
        local muts = F.setToArray(r.mutations)
        local fruits = F.setToArray(r.fruits)
        H.warn(string.format(
            "  rule[%d] id=%s on=%s kg=%s/%s muts=%s(%d) fruits=%s(%d) price=%s/%s",
            i,
            tostring(r.id or ""),
            tostring(r.enabled ~= false),
            tostring(r.kgRule or r.kg),
            tostring(r.kgMode or "above"),
            (#muts > 0) and table.concat(muts, ",") or "ANY",
            #muts,
            (#fruits > 0) and table.concat(fruits, ",") or "ANY",
            #fruits,
            tostring(r.priceRule or r.minPrice),
            tostring(r.minPriceMode or "above")
        ))
    end
    H.warn("=======================================")
    return st
end

