function M.DebugFilterScan(a, b)
    local opts = a
    if type(a) == "table" and (type(a.Start) == "function" or type(a.SetEnabled) == "function") then
        opts = b
    end
    opts = type(opts) == "table" and opts or {}
    local maxShow = math.floor(tonumber(opts.maxShow) or 20)
    if maxShow < 1 then maxShow = 20 end
    local function run()
        local ac = F.getACStateCached()
        local t0 = os.clock()
        local match, skip, eclipse, ripeN = F.scanGarden(ac)
        F.storeScan(match, skip, eclipse, ripeN)
        print("========== AUTO COLLECT FILTER DEBUG (GetGarden) ==========")
        print("elapsed:", math.floor((os.clock() - t0) * 1000), "ms")
        print("ripe:", ripeN, "| IN:", #match, "| OUT:", skip, "| eclipse cand:", #eclipse)
        print("rules:", #(ac.rules or {}))
        for i = 1, math.min(maxShow, #match) do
            local r = match[i]
            print(string.format("  IN  %s  %.2fkg  mut=%q  %s/%s",
                r.name, r.kg or 0, tostring(r.mut or ""), r.plantId, r.fruitId))
        end
        print("===========================================================")
        return { inFilter = #match, outFilter = skip, readyTotal = ripeN, source = "GetGarden" }
    end
    if opts.async ~= false then
        task.spawn(run)
        return { async = true }
    end
    return run()
end
