M.countReady = M.CountReady

function M.PeekReadyCount()
    local now = os.clock()
    if (now - S.readyCacheAt) <= C.COUNT_CACHE_SEC then
        return S.readyCache
    end
    if S.readyCacheAt > 0 and (now - S.readyCacheAt) <= C.COUNT_STALE_SEC then
        if not S.scanBusy then
            F.refreshCountsAsync(F.getACStateCached())
        end
        return S.readyCache
    end
    if S.scanBusy then
        return S.readyCache
    end
    F.refreshScan(F.getACStateCached())
    return S.readyCache
end
M.peekReadyCount = M.PeekReadyCount

function M.InvalidateCountCache()
    S.readyCacheAt = 0
    S.filteredCacheAt = 0
    end
M.invalidateCountCache = M.InvalidateCountCache

function M.CountFiltered()
    return math.max(0, math.floor(tonumber(S.filteredCache) or S.cycleMatchTotal or 0))
end
M.countFiltered = M.CountFiltered

function M.CountHarvestForGate()
    M.InvalidateCountCache()
    F.refreshScan(F.getACStateCached())
    return M.CountFiltered()
end
