function M.PeekFilteredCount()
    if F.cycleActive() or S.matchBuiltAt > 0 then
        return math.max(0, math.floor(tonumber(S.cycleMatchTotal) or S.filteredCache or 0))
    end
    if S.readyCacheAt > 0 then
        return math.max(0, math.floor(tonumber(S.filteredCache) or 0))
    end
    F.refreshCountsAsync(F.getACStateCached(), { force = true })
    return math.max(0, math.floor(tonumber(S.filteredCache) or 0))
end
M.peekFilteredCount = M.PeekFilteredCount

function M.PeekHarvestCount()
    local have, br = F.peekCachedBreakdown()
    if have then
        return math.max(0, math.floor(tonumber(br.total) or 0))
    end
    return M.PeekFilteredCount()
end
M.peekHarvestCount = M.PeekHarvestCount

function M.PeekHarvestBreakdown()
    local have, br = F.peekCachedBreakdown()
    local now = os.clock()
    local emptyTrusted = have and (tonumber(br.total) or 0) <= 0 and not F.cycleActive()
        and (now - (tonumber(S.lastUiScanAt) or 0)) >= (C.UI_SCAN_MIN_SEC or 2)
    if ((not have) or emptyTrusted) and not S.scanBusy then
        F.refreshCountsAsync(F.getACStateCached(), { force = true })
        have, br = F.peekCachedBreakdown()
    elseif have and br.stale == true and not S.scanBusy then
        F.refreshCountsAsync(F.getACStateCached())
        have, br = F.peekCachedBreakdown()
    end
    return br
end
M.peekHarvestBreakdown = M.PeekHarvestBreakdown

function M.WarmMatchCounts(a, b)
    local opts = type(a) == "table" and a or (type(b) == "table" and b or {})
    F.refreshCountsAsync(F.getACStateCached(), {
            force = (opts.force == true) or (S.readyCacheAt <= 0),
        })
    local refreshUi = rawget(_G, "__GAG2_REFRESH_COLLECT_UI") or rawget(G, "__GAG2_REFRESH_COLLECT_UI")
    if type(refreshUi) == "function" then
        pcall(refreshUi)
    end
end
