function M.IsHarvestCountsReady()
    -- Rescan GetGarden (scanBusy) jangan blokir watering/sprinkler.
    -- Cukup sudah pernah storeScan sekali.
    if (tonumber(S.matchBuiltAt) or 0) > 0 then
        return true
    end
    if (tonumber(S.lastUiScanAt) or 0) > 0 then
        return true
    end
    if (tonumber(S.readyCacheAt) or 0) > 0 then
        return true
    end
    return false
end
M.isHarvestCountsReady = M.IsHarvestCountsReady

function M.EnsureHarvestCountsReady(a, b)
    local timeoutSec = 45
    if type(a) == "number" then
        timeoutSec = a
    elseif type(b) == "number" then
        timeoutSec = b
    elseif type(a) == "table" and type(b) == "number" then
        timeoutSec = b
    end
    if timeoutSec < 5 then timeoutSec = 5 end
    if timeoutSec > 120 then timeoutSec = 120 end
    if M.IsHarvestCountsReady() then
        return true
    end
    local t0 = os.clock()
    M.WarmMatchCounts({ force = true })
    while (os.clock() - t0) < timeoutSec do
        if M.IsHarvestCountsReady() then
            return true
        end
        if S.scanBusy ~= true then
            M.WarmMatchCounts({ force = true })
        end
        task.wait(0.4)
    end
    return M.IsHarvestCountsReady()
end
M.ensureHarvestCountsReady = M.EnsureHarvestCountsReady

