function F.bindPlotWatch()
    if S.plotWatchBound then return end
    S.plotWatchBound = true
    local function onPlotReady()
        S.cachedPlot = nil
        S.cachedPlotAt = 0
        S.CollectFruit = nil
        S.gardenSyncMod = nil
        S.gardenSyncAt = 0
        if F.readEnabled() and S.rulesReadyAt > 0 then
            pcall(M.EnsureRunning)
        end
    end
    pcall(function()
        LP:GetAttributeChangedSignal("PlotId"):Connect(onPlotReady)
    end)
    task.spawn(function()
        local gardens = workspace:FindFirstChild("Gardens") or workspace:WaitForChild("Gardens", 120)
        if gardens then
            gardens.ChildAdded:Connect(onPlotReady)
            onPlotReady()
        end
    end)
end

