    F.bindPlotWatch()
    if _reloadWasOn then
        F.writeMainCollect({ enabled = true })
        G.AUTO_COLLECT_FRUIT_ENABLED = true
        _G.AUTO_COLLECT_FRUIT_ENABLED = true
    end
    task.spawn(function()
        for _ = 1, 24 do
        local MAIN = rawget(_G, "MAIN") or G.MAIN
            local collect = MAIN and MAIN.auto and MAIN.auto.collect
            if type(collect) == "table" then
                if _reloadWasOn then
                    F.writeMainCollect({ enabled = true })
                end
                pcall(M.SyncFromState)
                return
            end
            task.wait(0.25)
        end
    end)
end)

return M
