if type(NodeHubWS) == "table" and type(NodeHubWS.OnApplyUI) == "function" then
    NodeHubWS.OnApplyUI("gag2", "auto_plant_runtime", function(config, message, bridge, api)
        local plant = api.get(config, "main.auto.plant")
        if type(plant) ~= "table" then return true end

        G.AUTO_PLANT_ENABLED = plant.enabled == true
        _G.AUTO_PLANT_ENABLED = plant.enabled == true
        if plant.delay ~= nil then
            G.AUTO_PLANT_DELAY = tonumber(plant.delay) or 0
            _G.AUTO_PLANT_DELAY = G.AUTO_PLANT_DELAY
        end
        if type(plant.seeds) == "table" then
            G.AUTO_PLANT_SEEDS_SELECTED = api.selectedMap(plant.seeds)
            _G.AUTO_PLANT_SEEDS_SELECTED = G.AUTO_PLANT_SEEDS_SELECTED
        end

        if plant.mode ~= nil and type(M.SetMode) == "function" then pcall(M.SetMode, plant.mode) end
        if plant.plantTotal ~= nil and type(M.SetPlantTotal) == "function" then pcall(M.SetPlantTotal, plant.plantTotal) end
        if plant.plantOnce ~= nil and type(M.SetPlantOnce) == "function" then pcall(M.SetPlantOnce, plant.plantOnce == true) end
        if type(plant.selectedPositions) == "table" and type(M.SetSelectedPositions) == "function" then
            pcall(M.SetSelectedPositions, api.array(plant.selectedPositions))
        elseif plant.selectedPosition ~= nil and type(M.SetSelectedPosition) == "function" then
            pcall(M.SetSelectedPosition, plant.selectedPosition)
        end
        if type(M.SyncFromState) == "function" then pcall(M.SyncFromState) end
