    _, slotDropdownApi = ui:CreateRowDropdown(body, {
        label       = "Slots",
        placeholder = "Select slot...",
        mode        = "multi",
        getItems = function()
            return buildSlotItems()
        end,
        initial = AUTO_PLOT_SELECTED_SLOTS,
        onDeleteItem = function(key)
            key = tostring(key or "")
            if key == "" or key == "_none" then return end

            local mod = G.AutoPlot or G.AutoPlotModule
            local deleted = false
            if type(mod) == "table" and type(mod.DeleteSlot) == "function" then
                local ok, result = pcall(mod.DeleteSlot, key)
                deleted = (ok == true and result ~= false)
            end

            if not deleted then
                local slots = PL_STATE.slots
                if type(slots) == "table" then
                    for i = #slots, 1, -1 do
                        local entry = slots[i]
                        if type(entry) == "table" and tostring(entry.id) == key then
                            table.remove(slots, i)
                            deleted = true
                        end
                    end
                end
                PL_STATE.slots = slots
            else
                syncSlotsFromPersisted()
            end

            AUTO_PLOT_SELECTED_SLOTS[key] = nil
            PL_STATE.selectedSlots = mapToArray(AUTO_PLOT_SELECTED_SLOTS)
            writePlotGlobals()
            if slotDropdownApi and slotDropdownApi.refreshItems then
                slotDropdownApi.refreshItems()
            end
            if slotDropdownApi and slotDropdownApi.setSelected then
                slotDropdownApi.setSelected(AUTO_PLOT_SELECTED_SLOTS)
            end
            patchAuto("plot", {
                slots = PL_STATE.slots,
                selectedSlots = PL_STATE.selectedSlots,
                selectedSlot = PL_STATE.selectedSlot,
            }, syncPlotModule)
        end,
        onChanged = function(_, selectedMap)
            AUTO_PLOT_SELECTED_SLOTS = cleanSelectedMap(selectedMap)
            if AUTO_PLOT_SELECTED_SLOTS._none then
                AUTO_PLOT_SELECTED_SLOTS._none = nil
            end
            PL_STATE.selectedSlots = mapToArray(AUTO_PLOT_SELECTED_SLOTS)
            patchAuto("plot", { selectedSlots = PL_STATE.selectedSlots }, syncPlotModule)
        end,
    })

