        function(isOn)
            if not isOn then
                PL_STATE.saveSlot = false
                writePlotGlobals()
                local mod = G.AutoPlot or G.AutoPlotModule
                if type(mod) == "table" and type(mod.SetSaveSlot) == "function" then
                    pcall(mod.SetSaveSlot, mod, false)
                end
                return
            end

            if type(ui.CloseDropdownOverlays) == "function" then
                pcall(ui.CloseDropdownOverlays, ui)
            end

            G.__GAG2_PLOT_SAVE_TOGGLE_API = saveSlotToggleApi
            PL_STATE.saveSlot = true
            writePlotGlobals()

            local mod = G.AutoPlot or G.AutoPlotModule
            if type(mod) == "table" and type(mod.SaveStandingSlot) == "function" then
                local ok = mod:SaveStandingSlot()
                if not ok then
                    PL_STATE.saveSlot = false
                    writePlotGlobals()
                    if saveSlotToggleApi and saveSlotToggleApi.setOff then
                        saveSlotToggleApi.setOff(true)
                    end
                end
            elseif type(mod) == "table" and type(mod.SetSaveSlot) == "function" then
                pcall(mod.SetSaveSlot, mod, true)
            else
                warn("[GAG2] AutoPlot module not loaded — reload script")
                PL_STATE.saveSlot = false
                if saveSlotToggleApi and saveSlotToggleApi.setOff then
                    saveSlotToggleApi.setOff(true)
                end
            end
        end
    )
    G.__GAG2_PLOT_SAVE_TOGGLE_API = saveSlotToggleApi

    ui:CreateRowInput(
        body,
        "Place Delay (sec)",
        tostring(placeDelayDisplay()),
        function(text)
            local n = tonumber(text)
            if n == nil or n < 0 then return end
            if n > 0 and n < 0.1 then n = 0.1 end
            PL_STATE.placeDelay = n
            patchAuto("plot", { placeDelay = n }, syncPlotModule)
        end,
        false
    )

    ui:CreateRowInput(
        body,
        "Total Place (0 = max)",
        tostring(placeTotalDisplay()),
        function(text)
            local n = tonumber(text)
            if n == nil or n < 0 then return end
            PL_STATE.placeTotal = math.floor(n)
            patchAuto("plot", { placeTotal = PL_STATE.placeTotal }, syncPlotModule)
        end,
        false
    )

    _, _, placeEnableApi = ui:CreateRowToggle(
        body,
        "Auto Place",
        PL_STATE.autoPlace == true,
        function(isOn)
            PL_STATE.autoPlace = (isOn == true)
            patchAuto("plot", { autoPlace = PL_STATE.autoPlace }, syncPlotModule)
        end
    )

    task.spawn(function()
        while body and body.Parent do
            task.wait(1)
            if PL_STATE.autoPot or PL_STATE.autoPlace or PL_STATE.autoCollect or PL_STATE.autoBreak then
                local mod = G.AutoPlot or G.AutoPlotModule
                if type(mod) == "table"
                    and type(mod.IsRunning) == "function"
                    and not mod:IsRunning()
                    and type(mod.Start) == "function" then
                    pcall(mod.Start, mod)
                end
                pcall(refreshPlotStatus)
            end
        end
    end)

    syncPlotModule()
    G.__GAG2_AUTO_PLOT_UI_DONE = true
    _G.__GAG2_AUTO_PLOT_UI_DONE = true
end

G.SectionAutoPlot = M
_G.SectionAutoPlot = M

return M
