function M.SetEnabled(on)
    on = (on == true)
    G.AUTO_SPRINKLER_ENABLED = on
    _G.AUTO_SPRINKLER_ENABLED = on
    _writeMain({ enabled = on })

    if on then
        sessionPlaced = 0
        invalidateAllCaches()
        resetActiveSprinklerType()
        skipGatePaused = false
        lastFruitSlotsAt = 0
        lastCollectCount = 0
        lastSkippedCount = 0
        lastFruitCount = 0
        M._scanReady = false
        M._fruitCountsReady = false
        M._sprinklerScanTrusted = false
        _publishStatus("scanning")
        if not running then
            running = true
            loopId += 1
            local myId = loopId
            -- WAJIB: warm scan (farm + sprinkler settle + C/Sk) selesai dulu, baru mainLoop
            task.spawn(function()
                M.warmInitialScan()
                if running and loopId == myId then
                    M.mainLoop(myId)
                end
            end)
        else
            task.spawn(M.warmInitialScan)
        end
    else
        running = false
        loopId += 1
        M._scanReady = false
        M._fruitCountsReady = false
        M._sprinklerScanTrusted = false
        skipGatePaused = false
        unequipSprinklerTool(nil)
        resetActiveSprinklerType()
        centerAreaCursor = 1
        _publishStatus("idle")
    end
end

