function M.GetStatusText()
    local st = getSprinklerState()
    if not st.enabled then
        return "Off"
    end

    -- Warm scan awal saja. Rescan AC jangan paksa Scanning farm lagi.
    if M._scanReady ~= true or M._fruitCountsReady ~= true or M._sprinklerScanTrusted ~= true then
        lastStatusBase = STATUS_TEXT.scanning
        return _composeStatusText(STATUS_TEXT.scanning, st)
    end

    -- Refresh C/Sk/Bp saat place loop sedang nunggu
    M.refreshStatusCounts(false)

    local pauseCollectAt = math.floor(tonumber(st.pauseCollectFruit) or 0)
    local pauseSkipAt = math.floor(tonumber(st.pauseSkippedFruit) or 0)
    local pauseBackpackAt = math.floor(tonumber(st.pauseBackpackTotal) or 0)
    if pauseCollectAt > 0 and lastCollectCount >= pauseCollectAt then
        lastFailReason = "collect_pause"
        lastStatusBase = STATUS_TEXT.collect_pause
    elseif pauseSkipAt > 0 and lastSkippedCount >= pauseSkipAt then
        lastFailReason = "skip_pause"
        lastStatusBase = STATUS_TEXT.skip_pause
    elseif pauseBackpackAt > 0 and lastBackpackCount >= pauseBackpackAt then
        lastFailReason = "backpack_pause"
        lastStatusBase = STATUS_TEXT.backpack_pause
    elseif st.requireWatering == true
        and next(M._resolveWateringSelectedMap())
        and not M._hasWateringSelectedInInventory() then
        lastFailReason = "watering_pause"
        lastStatusBase = STATUS_TEXT.watering_pause
    elseif lastFailReason == "watering_pause" then
        -- Watering kembali ada — jangan stuck di Paused (watering).
        lastFailReason = ""
        if lastStatusBase == STATUS_TEXT.watering_pause then
            lastStatusBase = STATUS_TEXT.idle or "Waiting"
        end
    elseif lastFailReason == "garden_full" then
        lastStatusBase = STATUS_TEXT.idle or "Waiting"
    end

    local base = lastStatusBase
        or G.__GAG2_SPRINKLER_STATUS
        or _G.__GAG2_SPRINKLER_STATUS
        or _statusMessage(lastFailReason)
    return _composeStatusText(base, st)
end

