    { key = "WateringCanListView",     name = "WateringCanListView",     factory = function() -- WateringCanListView.lua — Grow A Garden 2
-- List watering can dari inventory (attribute WateringCan)

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players           = game:GetService("Players")

local LP = Players.LocalPlayer
local M  = {}
local G  = (getgenv and getgenv()) or _G

local _catalogCache = nil

local function _safeRequire(inst)
    if not inst or not inst:IsA("ModuleScript") then return nil end
    local ok, mod = pcall(require, inst)
    if ok and type(mod) == "table" then return mod end
    return nil
end

local function _normalizeEntry(entry, keyHint)
    if type(entry) ~= "table" then return nil end
    local name = entry.Name or keyHint
    if not name or tostring(name) == "" then return nil end
    return {
        Name         = tostring(name),
        SplashRadius = tonumber(entry.SplashRadius) or 8,
        raw          = entry,
    }
end

local function _loadCatalog()
    if _catalogCache then return _catalogCache end
    local merged = {}
    local root = ReplicatedStorage:FindFirstChild("SharedModules")
    local dataMod = root and root:FindFirstChild("WateringcanData")
    local data = dataMod and _safeRequire(dataMod)
    if type(data) == "table" then
        if #data > 0 then
            for _, entry in ipairs(data) do
                local norm = _normalizeEntry(entry)
                if norm then merged[norm.Name] = norm end
            end
        else
            for key, entry in pairs(data) do
                if type(entry) == "table" then
                    local norm = _normalizeEntry(entry, key)
                    if norm then merged[norm.Name] = norm end
                end
            end
        end
    end
    _catalogCache = merged
    return merged
end

function M.refresh()
    _catalogCache = nil
    return _loadCatalog()
end

function M.getCatalogMap()
    return _loadCatalog()
end

function M.findByName(name)
    if not name then return nil end
    return _loadCatalog()[tostring(name)]
end

local function _iterInventoryContainers()
    local out, seen = {}, {}
    local function add(c)
        if c and not seen[c] then
            seen[c] = true
            out[#out + 1] = c
        end
    end
    add(LP:FindFirstChildOfClass("Backpack"))
    add(LP:FindFirstChild("Backpack"))
    add(LP.Character)
    for _, ch in ipairs(LP:GetChildren()) do
        if ch:IsA("Folder") or ch:IsA("Model") or ch:IsA("Backpack") then
            local n = ch.Name:lower()
            if n:find("backpack") or n:find("ransel") or n:find("tas") or n:find("inventory") then
                add(ch)
            end
        end
    end
    return out
end

function M.buildInventoryWateringCanItems()
    local counts = {}
    for _, container in ipairs(_iterInventoryContainers()) do
        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") then
                local attr = inst:GetAttribute("WateringCan")
                if attr ~= nil then
                    local name = tostring(attr)
                    if name ~= "" then
                        counts[name] = (counts[name] or 0) + 1
                    end
                end
            end
        end
    end

    local out = {}
    for name, count in pairs(counts) do
        local info = M.findByName(name)
        local radius = info and info.SplashRadius or 8
        out[#out + 1] = {
            key   = name,
            name  = name,
            right = ("x%d · r%d"):format(count, radius),
            raw   = info or { Name = name, SplashRadius = radius },
        }
    end
    table.sort(out, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    if #out == 0 then
        return { { key = "_none", name = "(No watering cans in inventory)" } }
    end
    return out
end

G.WateringCanListView = M
_G.WateringCanListView = M

return M
 end,            required = false },
    { key = "AutoWatering",            name = "Auto Watering",           factory = function() -- AutoWatering.lua — Grow A Garden 2
-- Gerak: Move.lua + MOVE_MODE karakter (soft/step/walk/hard) — tanpa PivotTo soft-lock.
-- Position: normal (25 stud datar) / above (descend) / below (ascend).
-- Hold: LockAt untuk step/walk/hard. Soft = tanpa lock. Selesai → Unlock (tanpa return start).
-- Remote: Networking.WateringCan.UseWateringCan:Fire(pos - Vector3(0, 0.3, 0), canName, tool)

local Players           = game:GetService("Players")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local Networking = require(ReplicatedStorage.SharedModules.Networking)
local UseWateringCan = Networking.WateringCan and Networking.WateringCan.UseWateringCan

local LOOP_MIN_SEC    = 0.5
local WATER_COOLDOWN  = 0.5
local TP_SETTLE_BASE  = 0.35
local EQUIP_WAIT_BASE = 0.6
local PRE_FIRE_BASE   = 0.15
local POST_WATER_BASE = 0.35
local UNEQUIP_SETTLE_SEC = 0.35
local WATER_Y_OFFSET  = 0.3
local PLOT_CACHE_SEC  = 2
local BELOW_START     = -30
local ABOVE_START     = 28
local Y_STEP          = 4
local BELOW_Y_MAX     = 12
local ABOVE_Y_MIN     = -6
local NORMAL_STAND_DIST = 25 -- jarak datar dari target (mode normal)
local NORMAL_STAND_Y    = 3  -- sedikit di atas tanah
-- Equip/hover retries only — UseWateringCan must Fire at most once per can.
-- Game TryWater also fires once (0.5s client cooldown); re-Fire burns can uses.
-- Puddle FX often lags 3–5s after Fire — never use FX as success gate / retry trigger.
local MAX_EQUIP_ATTEMPTS = 8
local HOVER_SETTLE    = 0.2
local BOOT_WAIT_MAX   = 240
local POST_READY_DELAY = 0.75
local READY_POLL_SEC  = 0.35

local waterLocked = false
local waterGoalCf = nil
local stopHover

local running      = false
local loopId       = 0
local lastWaterAt  = 0
local plantIndex   = 0
local cachedPlot   = nil
local cachedPlotAt = 0
local teleWasOn    = false
local telePaused   = false
local lastFailReason = ""
local lastFruitCount = 0
local lastSkippedCount = 0
local lastCollectCount = 0
local lastBackpackCount = 0
local lastFruitSlots = 0
local lastFruitSlotsAt = 0
local lastStatusBase = "Idle"
local skipGatePaused = false
local fruitCountsReady = false
local nextActionAt = 0
local lastDelaySec = 0
local statusCountsAt = 0
local STATUS_COUNTS_SEC = 1.0

local STATUS_TEXT = {
    no_plot      = "Plot not found",
    no_plants    = "No plants selected",
    no_targets   = "No matching plants",
    no_can       = "No watering can",
    no_remote    = "Remote missing",
    equip_fail   = "Equip failed",
    tp_fail      = "TP failed",
    fire_fail    = "Fire failed",
    water_fail   = "Water failed",
    scanning     = "Scanning fruits",
    cooldown     = "Wait cooldown",
    working      = "Watering",
    idle         = "Idle",
    done         = "Watered",
    steal_busy   = "Paused (steal)",
    claim_busy   = "Paused (claim seed)",
    buy_busy     = "Paused (buy pet)",
    skip_pause   = "Paused (skip)",
    collect_pause = "Paused (collect)",
    backpack_pause = "Paused (BP)",
    wait_sprinkler = "Wait sprinkler",
    delay_wait   = "Wait delay",
    loading      = "Loading...",
    not_ready    = "Garden not ready",
}

local function _statusMessage(reason)
    reason = tostring(reason or "")
    if reason == "" then return STATUS_TEXT.idle or "Idle" end
    return STATUS_TEXT[reason] or reason
end

local function _stripFruitSuffix(msg)
    msg = tostring(msg or "")
    -- Kalau kebawa full compose lama ("Delay · d40s · C1/2 · …") → ambil base saja.
    local cut = msg:find("%s·%s*[dC]") or msg:find("%s·%s*Sk") or msg:find("%s·%s*Bp")
        or msg:find("%s·%s*Mx")
    if cut then
        msg = msg:sub(1, cut - 1)
    end
    return msg
        :gsub("%s*%(%d+%)%s*$", "")
        :gsub("%s*·%s*delay%s+[%d%.]+s%s*", " · ")
        :gsub("%s*·%s*d[%d%.]+s%s*", " · ")
        :gsub("%s*·%s*C%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*Sk%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*Bp%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*Mx%d+%s*", " · ")
        :gsub("%s*·%s*collect%s+%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*skipped%s+%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*skip%s+%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*backpack%s+%d+(?:/%d+)?%s*", " · ")
        :gsub("%s*·%s*max buah%s+%d+%s*", " · ")
        :gsub("%s*·%s*slots%s+%d+%s*", " · ")
        :gsub("%s*·%s*fruit%s+%d+(?:/%d+)?%s*$", "")
        :gsub("%s*·%s*$", "")
        :gsub("%s+$", "")
end

local function _composeStatusText(base, st)
    local msg = _stripFruitSuffix(base)
    if msg == "" then msg = STATUS_TEXT.idle or "Idle" end
    if #msg > 32 then
        msg = msg:sub(1, 31) .. "…"
    end
    local pauseSkipAt = 0
    local pauseCollectAt = 0
    local pauseBackpackAt = 0
    if type(st) == "table" then
        pauseSkipAt = math.floor(tonumber(st.pauseSkippedFruit) or 0)
        pauseCollectAt = math.floor(tonumber(st.pauseCollectFruit) or 0)
        pauseBackpackAt = math.floor(tonumber(st.pauseBackpackTotal) or 0)
    else
        pauseSkipAt = math.floor(tonumber(G.AUTO_WATERING_PAUSE_SKIPPED_FRUIT or rawget(_G, "AUTO_WATERING_PAUSE_SKIPPED_FRUIT")) or 0)
        pauseCollectAt = math.floor(tonumber(G.AUTO_WATERING_PAUSE_COLLECT_FRUIT or rawget(_G, "AUTO_WATERING_PAUSE_COLLECT_FRUIT")) or 0)
        pauseBackpackAt = math.floor(tonumber(G.AUTO_WATERING_PAUSE_BACKPACK_TOTAL or rawget(_G, "AUTO_WATERING_PAUSE_BACKPACK_TOTAL")) or 0)
    end
    local skipN = math.floor(tonumber(lastSkippedCount) or 0)
    local collectN = math.floor(tonumber(lastCollectCount) or 0)
    local backpackN = math.floor(tonumber(lastBackpackCount) or 0)
    local slots = math.floor(tonumber(lastFruitSlots) or 0)
    local delayLeft = nextActionAt - os.clock()
    local parts = { msg }
    local showDelay = delayLeft > 0.05
        and lastFailReason ~= "skip_pause"
        and lastFailReason ~= "collect_pause"
        and lastFailReason ~= "backpack_pause"
        and lastFailReason ~= "wait_sprinkler"
        and lastFailReason ~= "working"
        and lastFailReason ~= "loading"
        and lastFailReason ~= "not_ready"
    if showDelay then
        if lastFailReason == "delay_wait" or msg == STATUS_TEXT.delay_wait or msg:find("Wait delay", 1, true) then
            parts[1] = string.format("Wait delay %.0fs", delayLeft)
        else
            parts[#parts + 1] = string.format("d%.0fs", delayLeft)
        end
    end
    if pauseCollectAt > 0 then
        parts[#parts + 1] = string.format("C%d/%d", collectN, pauseCollectAt)
    else
        parts[#parts + 1] = string.format("C%d", collectN)
    end
    if pauseSkipAt > 0 then
        parts[#parts + 1] = string.format("Sk%d/%d", skipN, pauseSkipAt)
    else
        parts[#parts + 1] = string.format("Sk%d", skipN)
    end
    if pauseBackpackAt > 0 then
        parts[#parts + 1] = string.format("Bp%d/%d", backpackN, pauseBackpackAt)
    else
        parts[#parts + 1] = string.format("Bp%d", backpackN)
    end
    parts[#parts + 1] = string.format("Mx%d", slots)
    return table.concat(parts, " · ")
end

local function _publishStatus(reason, detail)
    lastFailReason = tostring(reason or "")
    local msg = _statusMessage(lastFailReason)
    lastStatusBase = msg
    local full = _composeStatusText(msg)
    G.__GAG2_WATERING_STATUS = full
    _G.__GAG2_WATERING_STATUS = full
end

local function _isHoldStatus(reason)
    reason = tostring(reason or "")
    return reason == "wait_sprinkler"
        or reason == "no_plants"
        or reason == "no_targets"
        or reason == "no_plot"
        or reason == "no_can"
        or reason == "loading"
        or reason == "not_ready"
        or reason == "collect_pause"
        or reason == "skip_pause"
        or reason == "backpack_pause"
        or reason == "steal_busy"
        or reason == "claim_busy"
        or reason == "buy_busy"
        or reason == "scanning"
end

local function _beginDelayWait(waitSec)
    waitSec = tonumber(waitSec) or 0
    if waitSec < 0 then waitSec = 0 end
    lastDelaySec = waitSec
    nextActionAt = os.clock() + waitSec
    -- Jangan timpa "Wait sprinkler" / pause dengan label Delay.
    if waitSec > 0.05 and not _isHoldStatus(lastFailReason) then
        _publishStatus("delay_wait")
    end
end

local function _writeMain(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.watering = MAIN.auto.watering or {}
    for k, v in pairs(patch) do
        MAIN.auto.watering[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function _normalizeSet(src)
    if type(src) ~= "table" then return {} end
    local out = {}
    for i = 1, #src do
        local v = src[i]
        if v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    if next(out) then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function _canon(s)
    return tostring(s or ""):lower():gsub("[^%w]+", "")
end

local function _selectedMatch(selected, key)
    if not next(selected) then return true end
    local k = tostring(key)
    return selected[k] == true or selected[_canon(k)] == true
end

function M.GetState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.watering
    st = type(st) == "table" and st or {}

    local plants = G.AUTO_WATERING_PLANTS_SELECTED
        or rawget(_G, "AUTO_WATERING_PLANTS_SELECTED")
        or _normalizeSet(st.plants)

    local cans = G.AUTO_WATERING_CANS_SELECTED
        or rawget(_G, "AUTO_WATERING_CANS_SELECTED")
        or _normalizeSet(st.cans)

    local delay = tonumber(st.delay)
    if delay == nil then
        delay = tonumber(G.AUTO_WATERING_DELAY or rawget(_G, "AUTO_WATERING_DELAY")) or 3
    end
    if delay < LOOP_MIN_SEC then delay = LOOP_MIN_SEC end

    local settleDelay = tonumber(st.settleDelay)
    if settleDelay == nil then
        settleDelay = tonumber(G.AUTO_WATERING_SETTLE_DELAY or rawget(_G, "AUTO_WATERING_SETTLE_DELAY")) or 0
    end
    if settleDelay < 0 then settleDelay = 0 end

    local pauseSkippedFruit = tonumber(st.pauseSkippedFruit)
    if pauseSkippedFruit == nil then
        pauseSkippedFruit = tonumber(G.AUTO_WATERING_PAUSE_SKIPPED_FRUIT or rawget(_G, "AUTO_WATERING_PAUSE_SKIPPED_FRUIT")) or 0
    end
    pauseSkippedFruit = math.floor(pauseSkippedFruit)
    if pauseSkippedFruit < 0 then pauseSkippedFruit = 0 end

    local pauseCollectFruit = tonumber(st.pauseCollectFruit)
    if pauseCollectFruit == nil then
        pauseCollectFruit = tonumber(G.AUTO_WATERING_PAUSE_COLLECT_FRUIT or rawget(_G, "AUTO_WATERING_PAUSE_COLLECT_FRUIT")) or 0
    end
    pauseCollectFruit = math.floor(pauseCollectFruit)
    if pauseCollectFruit < 0 then pauseCollectFruit = 0 end

    local pauseBackpackTotal = tonumber(st.pauseBackpackTotal)
    if pauseBackpackTotal == nil then
        pauseBackpackTotal = tonumber(G.AUTO_WATERING_PAUSE_BACKPACK_TOTAL or rawget(_G, "AUTO_WATERING_PAUSE_BACKPACK_TOTAL")) or 0
    end
    pauseBackpackTotal = math.floor(pauseBackpackTotal)
    if pauseBackpackTotal < 0 then pauseBackpackTotal = 0 end

    local tpMode = tostring(st.tpMode or G.AUTO_WATERING_TP_MODE or rawget(_G, "AUTO_WATERING_TP_MODE") or "below"):lower()
    if tpMode == "atas" or tpMode == "top" or tpMode == "over" or tpMode == "above" then
        tpMode = "above"
    elseif tpMode == "normal" or tpMode == "flat" or tpMode == "ground" then
        tpMode = "normal"
    else
        tpMode = "below"
    end

    local requireSprinkler = st.requireSprinkler
    if requireSprinkler == nil then
        requireSprinkler = G.AUTO_WATERING_REQUIRE_SPRINKLER == true
            or rawget(_G, "AUTO_WATERING_REQUIRE_SPRINKLER") == true
    end

    local enabled = st.enabled
    if enabled == nil then
        enabled = G.AUTO_WATERING_ENABLED == true or rawget(_G, "AUTO_WATERING_ENABLED") == true
    end

    return {
        enabled             = (enabled == true),
        plants              = plants,
        cans                = cans,
        delay               = delay,
        settleDelay         = settleDelay,
        pauseSkippedFruit   = pauseSkippedFruit,
        pauseCollectFruit   = pauseCollectFruit,
        pauseBackpackTotal  = pauseBackpackTotal,
        tpMode              = tpMode,
        requireSprinkler    = (requireSprinkler == true),
    }
end

M.getState = M.GetState

local function getPlayerPlot()
    local now = os.clock()
    if cachedPlot and cachedPlot.Parent and (now - cachedPlotAt) <= PLOT_CACHE_SEC then
        return cachedPlot
    end
    cachedPlot = nil
    local plotId = LP:GetAttribute("PlotId")
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then return nil end
    if plotId ~= nil then
        cachedPlot = gardens:FindFirstChild("Plot" .. tostring(plotId))
    end
    if not cachedPlot then
        for _, plot in ipairs(gardens:GetChildren()) do
            local owner = plot:GetAttribute("Owner") or plot:GetAttribute("OwnerId")
            if owner ~= nil and (tostring(owner) == LP.Name or tonumber(owner) == LP.UserId) then
                cachedPlot = plot
                break
            end
        end
    end
    cachedPlotAt = now
    return cachedPlot
end

local function plotRuntimeReady()
    if not LP or not LP.Character then return false end
    local hrp = LP.Character:FindFirstChild("HumanoidRootPart")
    if not (hrp and hrp:IsA("BasePart")) then return false end
    if not workspace:FindFirstChild("Gardens") then return false end
    if LP:GetAttribute("PlotId") == nil then return false end
    local plot = getPlayerPlot()
    return plot ~= nil and plot.Parent ~= nil
end

local function loadingScreenActive()
    if not LP then return false end
    if LP:GetAttribute("LoadingScreenDone") == true then
        return false
    end
    -- Plot sudah ready → jangan block (Active/menu sering nyangkut setelah skip UI)
    if plotRuntimeReady() then
        return false
    end
    if LP:GetAttribute("LoadingScreenActive") == true then
        return true
    end
    if workspace:FindFirstChild("LoadingScreenMenu") ~= nil then
        return true
    end
    return false
end

local function isGameReady()
    if loadingScreenActive() then return false end
    return plotRuntimeReady()
end

local function waitForBootReady(myId)
    local deadline = os.clock() + BOOT_WAIT_MAX
    local settled = false
    while running and loopId == myId do
        if not workspace:FindFirstChild("Gardens") then
            pcall(function()
                workspace:WaitForChild("Gardens", 5)
            end)
        end

        if isGameReady() then
            if not settled then
                cachedPlot = nil
                task.wait(POST_READY_DELAY)
                settled = true
            end
            if isGameReady() then
                cachedPlot = nil
                return true
            end
        end

        if os.clock() >= deadline then
            return isGameReady()
        end

        if loadingScreenActive() then
            _publishStatus("loading")
        else
            _publishStatus("not_ready")
        end
        task.wait(READY_POLL_SEC)
    end
    return false
end

local function _plantsFolderCount(plot)
    if not plot then return 0 end
    local folder = plot:FindFirstChild("Plants")
    return folder and #folder:GetChildren() or 0
end

local function computeSettleSec(plot, st)
    local user = tonumber(st and st.settleDelay)
    if user ~= nil and user > 0 then
        return math.clamp(user, 0.15, 5)
    end
    local n = _plantsFolderCount(plot)
    if n >= 500 then return 1.2
    elseif n >= 300 then return 1.0
    elseif n >= 200 then return 0.8
    elseif n >= 100 then return 0.55
    end
    return TP_SETTLE_BASE
end

local function computeLoopDelay(st, plot)
    local base = tonumber(st and st.delay) or 3
    if base < LOOP_MIN_SEC then base = LOOP_MIN_SEC end
    local n = _plantsFolderCount(plot)
    if n >= 500 then return math.max(base, 3.5)
    elseif n >= 300 then return math.max(base, 3)
    elseif n >= 200 then return math.max(base, 2.5)
    elseif n >= 100 then return math.max(base, 1.5)
    end
    return base
end

local function getAutoCollectMod()
    return G.AutoCollectFruit or G.CollectFruitModule or rawget(_G, "AutoCollectFruit")
        or G.AutoCollect or rawget(_G, "AutoCollect")
end

local function acHarvestCountsReady()
    local AC = getAutoCollectMod()
    if type(AC) ~= "table" then return false end
    if type(AC.IsHarvestCountsReady) == "function" then
        local ok, ready = pcall(AC.IsHarvestCountsReady, AC)
        if ok and ready == true then return true end
    end
    if type(AC.GetStats) == "function" then
        local ok, st = pcall(AC.GetStats, AC)
        if ok and type(st) == "table" then
            if st.matchCached == true then return true end
            local n = (tonumber(st.matchIn) or 0) + (tonumber(st.matchOut) or 0)
            if n > 0 and st.matchBooting ~= true then return true end
        end
    end
    return false
end

local function waitForHarvestCountsReady(myId, timeoutSec)
    timeoutSec = tonumber(timeoutSec) or 60
    local AC = getAutoCollectMod()
    if type(AC) == "table" and type(AC.EnsureHarvestCountsReady) == "function" then
        _publishStatus("scanning")
        local ok, ready = pcall(AC.EnsureHarvestCountsReady, AC, timeoutSec)
        fruitCountsReady = (ok and ready == true) or acHarvestCountsReady()
        return fruitCountsReady
    end
    local t0 = os.clock()
    _publishStatus("scanning")
    while running and loopId == myId and (os.clock() - t0) < timeoutSec do
        if type(AC) == "table" and type(AC.WarmMatchCounts) == "function" then
            pcall(AC.WarmMatchCounts, AC, { force = true })
        end
        if acHarvestCountsReady() then
            fruitCountsReady = true
            return true
        end
        task.wait(0.4)
    end
    fruitCountsReady = acHarvestCountsReady()
    return fruitCountsReady
end

local function getHarvestFilterCounts()
    -- C = semua ripe yang bisa di-collect (Match + Skipped). Sk = out-filter.
    local AC = getAutoCollectMod()
    if type(AC) ~= "table" then return 0, 0 end
    if type(AC.GetStats) == "function" then
        local ok, st = pcall(AC.GetStats, AC)
        if ok and type(st) == "table" then
            local matchIn = math.max(0, math.floor(tonumber(st.matchIn) or 0))
            local matchOut = math.max(0, math.floor(tonumber(st.matchOut) or 0))
            local pending = math.max(0, math.floor(tonumber(st.batchPending) or 0))
            local collectN = matchIn + matchOut
            if pending > matchIn then
                collectN = pending + matchOut
            end
            if st.matchCached == true or collectN > 0 or matchOut > 0 then
                if collectN > 0 or matchOut > 0 or st.matchScanning ~= true then
                    return collectN, matchOut
                end
            end
        end
    end
    if type(AC.PeekHarvestBreakdown) == "function" then
        local ok, br = pcall(AC.PeekHarvestBreakdown, AC)
        if ok and type(br) == "table" and br.pending ~= true then
            local collectN = math.max(0, math.floor(tonumber(br.total) or 0))
            local skipN = math.max(0, math.floor(tonumber(br.outFilter) or 0))
            return collectN, skipN
        end
    end
    if type(AC.PeekReadyCount) == "function" then
        local ok, n = pcall(AC.PeekReadyCount, AC)
        if ok then
            return math.max(0, math.floor(tonumber(n) or 0)), 0
        end
    end
    return 0, 0
end

-- Kapasitas buah / pohon — sama sumber dengan AutoSprinkler (SeedData, bukan #buah current)
local function _plantFruitSlotCount(plant)
    local AS = G.AutoSprinkler or G.AutoSprinklerModule or rawget(_G, "AutoSprinkler")
    if type(AS) == "table" and type(AS.GetPlantFruitSlotCount) == "function" then
        local ok, n = pcall(AS.GetPlantFruitSlotCount, AS, plant)
        if ok and type(n) == "number" then
            return math.max(0, math.floor(n))
        end
    end
    if not plant then return 0 end
    if plant:GetAttribute("Sprinkler") ~= nil or plant:GetAttribute("SprinklerName") ~= nil then
        return 0
    end
    if plant:GetAttribute("PlantId") == nil
        and plant:GetAttribute("SeedName") == nil
        and plant:GetAttribute("ItemName") == nil then
        return 0
    end
    -- fallback ringan kalau AutoSprinkler belum load
    local attrMax = tonumber(plant:GetAttribute("FruitSlots"))
        or tonumber(plant:GetAttribute("MaxFruits"))
        or tonumber(plant:GetAttribute("MaxFruit"))
        or tonumber(plant:GetAttribute("MaxFruitCount"))
    if attrMax and attrMax > 0 then
        return math.floor(attrMax)
    end
    local locs = plant:FindFirstChild("FruitSpawnLocations")
        or plant:FindFirstChild("FruitSpawnLocation")
        or plant:FindFirstChild("SpawnLocations")
    local n = 0
    if locs then
        for _, ch in ipairs(locs:GetChildren()) do
            if ch:IsA("BasePart") then
                n += 1
            end
        end
    end
    if n > 0 then return n end
    if plant:GetAttribute("IsSingleHarvest") == true then return 1 end
    return 1
end

local function countFruitSlots(plot)
    local now = os.clock()
    if (now - lastFruitSlotsAt) <= 2 and lastFruitSlots >= 0 then
        return lastFruitSlots
    end
    local eg = G.EspFruitGarden or rawget(_G, "EspFruitGarden")
    if type(eg) == "table" and type(eg.CountGardenFruitSlots) == "function" then
        local ok, n = pcall(eg.CountGardenFruitSlots, eg)
        if ok and type(n) == "number" and n >= 0 then
            lastFruitSlots = math.floor(n)
            lastFruitSlotsAt = now
            return lastFruitSlots
        end
    end
    local total = 0
    if plot then
        local seen = {}
        local function scan(folder)
            if not folder or seen[folder] then return end
            seen[folder] = true
            -- Hanya GetChildren — JANGAN GetDescendants (garden besar = freeze UI)
            for _, plant in ipairs(folder:GetChildren()) do
                if plant:IsA("Model") then
                    total += _plantFruitSlotCount(plant)
                end
            end
        end
        local important = plot:FindFirstChild("Important")
        scan(plot:FindFirstChild("Plants"))
        scan(plot:FindFirstChild("Plants_Physical"))
        if important then
            scan(important:FindFirstChild("Plants"))
            scan(important:FindFirstChild("Plants_Physical"))
        end
    end
    lastFruitSlots = total
    lastFruitSlotsAt = now
    return total
end

local function refreshStatusCounts(force)
    local now = os.clock()
    if not force and (now - statusCountsAt) < STATUS_COUNTS_SEC then
        return
    end
    statusCountsAt = now

    local plot = getPlayerPlot()
    -- Hormati cache 2s di countFruitSlots (jangan paksa recount tiap status tick)
    countFruitSlots(plot)

    local collectN, skipN = getHarvestFilterCounts()
    lastCollectCount = collectN
    lastSkippedCount = skipN
    lastFruitCount = skipN
    lastBackpackCount = math.max(0, math.floor(tonumber(LP:GetAttribute("FruitCount")) or 0))
end

-- Pause bila collect / skipped / backpack total mencapai threshold (0=off).
local function checkSkippedFruitGate(st, plot)
    local pauseSkipAt = math.floor(tonumber(st and st.pauseSkippedFruit) or 0)
    local pauseCollectAt = math.floor(tonumber(st and st.pauseCollectFruit) or 0)
    local pauseBackpackAt = math.floor(tonumber(st and st.pauseBackpackTotal) or 0)

    -- Load awal: C/Sk belum ada. Rescan AC jangan reset ready (stuck Scanning).
    if fruitCountsReady ~= true then
        if acHarvestCountsReady() then
            fruitCountsReady = true
        else
            skipGatePaused = true
            return false, "scanning", 0
        end
    end

    refreshStatusCounts(true)
    local collectN = lastCollectCount
    local skipN = lastSkippedCount
    local backpackN = lastBackpackCount

    if pauseCollectAt > 0 and collectN >= pauseCollectAt then
        skipGatePaused = true
        return false, "collect_pause", collectN
    end

    if pauseSkipAt > 0 and skipN >= pauseSkipAt then
        skipGatePaused = true
        return false, "skip_pause", skipN
    end

    if pauseBackpackAt > 0 and backpackN >= pauseBackpackAt then
        skipGatePaused = true
        return false, "backpack_pause", backpackN
    end

    skipGatePaused = false
    return true, nil, skipN
end

local function getPlantTypeKey(plant)
    local AS = G.AutoSprinkler or G.AutoSprinklerModule or rawget(_G, "AutoSprinkler")
    if type(AS) == "table" and type(AS.BuildGardenPlantItems) == "function" then
        -- prefer shovel helper if available via sprinkler's chain
    end
    local shovel = G.AutoShovel or rawget(_G, "AutoShovel")
    if type(shovel) == "table" and type(shovel.GetPlantTypeKey) == "function" then
        local ok, key = pcall(shovel.GetPlantTypeKey, shovel, plant)
        if ok and key then return tostring(key) end
    end
    return tostring(
        plant:GetAttribute("SeedName")
            or plant:GetAttribute("ConfigPathName")
            or plant:GetAttribute("CorePartName")
            or plant:GetAttribute("FruitType")
            or plant.Name
    )
end

local function getPlantGroundPos(plant)
    if plant:IsA("BasePart") then return plant.Position end
    local ok, pos = pcall(function() return plant:GetPivot().Position end)
    if ok and typeof(pos) == "Vector3" then return pos end
    local part = plant:FindFirstChildWhichIsA("BasePart", true)
    return part and part.Position or nil
end

local function listTargetPlants(plot, selectedPlants)
    if not plot or not next(selectedPlants) then return {} end
    local folder = plot:FindFirstChild("Plants")
    if not folder then return {} end
    local AS = G.AutoSprinkler or G.AutoSprinklerModule or rawget(_G, "AutoSprinkler")
    local out = {}
    local seen = {}
    local byId = {}
    for _, plant in ipairs(folder:GetChildren()) do
        if plant:IsA("Model") then
            local key = getPlantTypeKey(plant)
            local seed = tostring(
                plant:GetAttribute("SeedName")
                    or plant:GetAttribute("CorePartName")
                    or plant:GetAttribute("FruitType")
                    or ""
            )
            local hit = false
            if type(AS) == "table" and type(AS.isPlantKeySelected) == "function" then
                hit = AS.isPlantKeySelected(key, selectedPlants)
                    or (seed ~= "" and AS.isPlantKeySelected(seed, selectedPlants))
            else
                hit = _selectedMatch(selectedPlants, key)
                    or (seed ~= "" and _selectedMatch(selectedPlants, seed))
            end
            local pid = tostring(plant:GetAttribute("PlantId") or plant.Name)
            byId[pid] = plant
            if hit then
                local pos = getPlantGroundPos(plant)
                if pos then
                    seen[pid] = true
                    out[#out + 1] = { plant = plant, key = key, pos = pos }
                end
            end
        end
    end
    local eg = G.EspFruitGarden or rawget(_G, "EspFruitGarden")
    if type(eg) == "table" and type(eg.GetGardenTable) == "function" then
        local okG, garden = pcall(eg.GetGardenTable, eg)
        if okG and type(garden) == "table" then
            for plantId, plantData in pairs(garden) do
                if type(plantData) == "table" and not seen[tostring(plantId)] then
                    local name = tostring(
                        plantData.PlantName or plantData.SeedName or plantData.ItemName or ""
                    )
                    local hit = _selectedMatch(selectedPlants, name)
                    if type(AS) == "table" and type(AS.isPlantKeySelected) == "function" then
                        hit = AS.isPlantKeySelected(name, selectedPlants)
                    end
                    if hit then
                        local plant = byId[tostring(plantId)] or folder:FindFirstChild(tostring(plantId))
                        local pos = plant and getPlantGroundPos(plant)
                        if not pos and type(eg.WorldPosFromPlantData) == "function" then
                            local okP, world = pcall(eg.WorldPosFromPlantData, eg, plantData, plot)
                            if okP and typeof(world) == "Vector3" then
                                pos = world
                            end
                        end
                        if pos then
                            seen[tostring(plantId)] = true
                            out[#out + 1] = { plant = plant, key = name, pos = pos }
                        end
                    end
                end
            end
        end
    end
    table.sort(out, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return out
end

local function collectPlantAreas(plot)
    local out = {}
    for _, d in ipairs(plot:GetDescendants()) do
        if d:IsA("BasePart") and CollectionService:HasTag(d, "PlantArea") then
            out[#out + 1] = d
        end
    end
    return out
end

local function snapToPlantArea(plot, pos)
    if not plot or not pos then return nil end
    local areas = collectPlantAreas(plot)
    if #areas == 0 then return pos end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = areas
    local originY = pos.Y + 80
    for _, part in ipairs(areas) do
        originY = math.max(originY, part.Position.Y + 80)
    end
    local hit = workspace:Raycast(
        Vector3.new(pos.X, originY, pos.Z),
        Vector3.new(0, -600, 0),
        params
    )
    if hit and CollectionService:HasTag(hit.Instance, "PlantArea") and hit.Instance:IsDescendantOf(plot) then
        return hit.Position
    end
    return pos
end

local function iterInventory()
    local out, seen = {}, {}
    local function add(c)
        if c and not seen[c] then
            seen[c] = true
            out[#out + 1] = c
        end
    end
    add(LP:FindFirstChildOfClass("Backpack"))
    add(LP:FindFirstChild("Backpack"))
    add(LP:FindFirstChild("TasRansel"))
    add(LP.Character)
    for _, ch in ipairs(LP:GetChildren()) do
        if ch:IsA("Folder") or ch:IsA("Model") or ch:IsA("Backpack") then
            local n = ch.Name:lower()
            if n:find("backpack") or n:find("ransel") or n:find("tas") or n:find("inventory") then
                add(ch)
            end
        end
    end
    return out
end

local function _resolveCanGroupName(name, groups)
    if not name or type(groups) ~= "table" then return nil end
    name = tostring(name)
    if groups[name] and #groups[name] > 0 then return name end
    local canon = _canon(name)
    for gname, tools in pairs(groups) do
        if #tools > 0 and _canon(gname) == canon then
            return gname
        end
    end
    return nil
end

local function groupWateringCansByType(selected)
    local groups = {}
    local hasFilter = next(selected) ~= nil
    for _, container in ipairs(iterInventory()) do
        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") then
                local attr = inst:GetAttribute("WateringCan")
                if attr ~= nil then
                    local name = tostring(attr)
                    if name ~= "" and (not hasFilter or _selectedMatch(selected, name)) then
                        local bucket = groups[name]
                        if not bucket then
                            bucket = {}
                            groups[name] = bucket
                        end
                        bucket[#bucket + 1] = inst
                    end
                end
            end
        end
    end
    return groups
end

local function buildWateringCanOrder(selected)
    selected = _normalizeSet(selected)
    local groups = groupWateringCansByType(selected)
    local order, seen = {}, {}

    local function tryAdd(name)
        local gname = _resolveCanGroupName(name, groups)
        if gname and not seen[gname] then
            seen[gname] = true
            order[#order + 1] = gname
        end
    end

    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local arr = type(MAIN) == "table"
        and type(MAIN.auto) == "table"
        and type(MAIN.auto.watering) == "table"
        and MAIN.auto.watering.cans

    if type(arr) == "table" and #arr > 0 then
        for i = 1, #arr do
            tryAdd(arr[i])
        end
    end

    for name in pairs(selected) do
        tryAdd(name)
    end

    for gname, tools in pairs(groups) do
        if not seen[gname] and #tools > 0 then
            seen[gname] = true
            order[#order + 1] = gname
        end
    end

    return order, groups
end

local function getAvailableCanTypes(selected)
    local order, groups = buildWateringCanOrder(selected)
    local avail = {}
    for _, name in ipairs(order) do
        if groups[name] and #groups[name] > 0 then
            avail[#avail + 1] = name
        end
    end
    return avail, groups
end

local function findWateringCanTool(selected, typeName)
    if not typeName then return nil, nil end
    local _, groups = buildWateringCanOrder(selected)
    local resolved = _resolveCanGroupName(typeName, groups)
    local tools = resolved and groups[resolved]
    if type(tools) ~= "table" or #tools == 0 then return nil, nil end
    return tools[1], resolved
end

local function getHRP()
    local ch = LP.Character
    if not ch then return nil end
    local hrp = ch:FindFirstChild("HumanoidRootPart")
    return hrp and hrp:IsA("BasePart") and hrp or nil
end

local function getHum()
    local ch = LP.Character
    return ch and ch:FindFirstChildOfClass("Humanoid") or nil
end

local function _move()
    return G.Move or G.MoveModule or rawget(_G, "Move") or rawget(_G, "MoveModule")
end

local function _claimSeedBusy()
    if G.__GAG2_AUTO_CLAIM_SEED_BUSY == true
        or rawget(_G, "__GAG2_AUTO_CLAIM_SEED_BUSY") == true then
        return true
    end
    local acs = G.AutoClaimSeed or G.AutoClaimSeedModule or rawget(_G, "AutoClaimSeed")
    if type(acs) == "table" and type(acs.GetDiagnostics) == "function" then
        local ok, d = pcall(acs.GetDiagnostics)
        if ok and type(d) == "table" and d.claimBusy == true then
            return true
        end
    end
    return false
end

local function _stealBusy()
    if G.__GAG2_AUTO_STEAL_BUSY == true or rawget(_G, "__GAG2_AUTO_STEAL_BUSY") == true then
        return true
    end
    local steal = G.AutoSteal or G.AutoStealModule or rawget(_G, "AutoSteal")
    if type(steal) == "table" and type(steal.IsRunning) == "function" then
        local ok, on = pcall(steal.IsRunning, steal)
        if ok and on == true then
            -- Hanya block saat malam steal aktif (bukan cuma toggle ON di siang)
            if type(steal.IsNight) == "function" and type(steal.IsDefender) == "function" then
                local okN, night = pcall(steal.IsNight, steal)
                local okD, def = pcall(steal.IsDefender, steal)
                if okN and okD and night == true and def ~= true then
                    return true
                end
            else
                return true
            end
        end
    end
    return false
end

local function _buyPetBusy()
    if G.__GAG2_AUTO_BUY_PET_BUSY == true
        or rawget(_G, "__GAG2_AUTO_BUY_PET_BUSY") == true then
        return true
    end
    local buy = G.AutoBuyPet or G.AutoBuyPetModule or rawget(_G, "AutoBuyPet")
    if type(buy) == "table" and type(buy.GetDiagnostics) == "function" then
        local ok, d = pcall(buy.GetDiagnostics)
        if ok and type(d) == "table" and d.buyBusy == true then
            return true
        end
    end
    return false
end

-- Yield ke steal / claim seed / buy pet / holder prioritas lebih tinggi
-- (jangan tele watering saat claim/buy masih jalan)
local _yieldCacheAt = 0
local _yieldCacheOn = false
local _yieldCacheWhy = nil
local function _shouldYieldForPriority()
    local now = os.clock()
    -- Cache singkat: hot path call berkali-kali per water tick
    if (now - _yieldCacheAt) < 0.12 then
        return _yieldCacheOn, _yieldCacheWhy
    end
    local on, why = false, nil
    if _claimSeedBusy() then
        on, why = true, "claim_busy"
    elseif _stealBusy() then
        on, why = true, "steal_busy"
    elseif _buyPetBusy() then
        on, why = true, "buy_busy"
    else
        local Move = _move()
        if type(Move) == "table" and type(Move.ShouldYield) == "function" then
            local ok, yield, who = pcall(Move.ShouldYield, "water")
            if ok and yield == true then
                local w = string.lower(tostring(who or ""))
                if w:find("claim", 1, true) then
                    on, why = true, "claim_busy"
                elseif w:find("steal", 1, true) then
                    on, why = true, "steal_busy"
                elseif w:find("buy", 1, true) then
                    on, why = true, "buy_busy"
                else
                    on, why = true, "claim_busy"
                end
            end
        end
        -- Extra: Move lock/session holder claim_* / steal_* / buy_*
        if not on and type(Move) == "table" and type(Move.CurrentHolder) == "function" then
            local okH, reason, pri = pcall(Move.CurrentHolder)
            if okH and reason and tonumber(pri) and tonumber(pri) > 50 then
                local r = string.lower(tostring(reason))
                if r:find("claim", 1, true) then
                    on, why = true, "claim_busy"
                elseif r:find("steal", 1, true) then
                    on, why = true, "steal_busy"
                elseif r:find("buy", 1, true) then
                    on, why = true, "buy_busy"
                end
            end
        end
    end
    _yieldCacheAt = now
    _yieldCacheOn = on
    _yieldCacheWhy = why
    return on, why
end

local function _getMoveMode()
    local Move = _move()
    if type(Move) == "table" and type(Move.GetMode) == "function" then
        local ok, mode = pcall(Move.GetMode)
        if ok and type(mode) == "string" then return mode end
    end
    return tostring(G.MOVE_MODE or rawget(_G, "MOVE_MODE") or "walk"):lower()
end

local function unlockWaterPos()
    local Move = _move()
    if waterLocked and type(Move) == "table" and type(Move.Unlock) == "function" then
        pcall(Move.Unlock)
    end
    waterLocked = false
end

local function lockWaterPos(pos)
    local Move = _move()
    if typeof(pos) ~= "Vector3" then return false end
    if type(Move) ~= "table" or type(Move.LockAt) ~= "function" then
        return false
    end
    -- Jangan lawan travel lock prioritas lebih tinggi (claim/steal) — itu yang bikin hang
    if type(Move.ShouldYield) == "function" then
        local okY, yield = pcall(Move.ShouldYield, "water")
        if okY and yield == true then
            return false
        end
    end
    local ok = false
    pcall(function()
        ok = Move.LockAt(pos) == true
    end)
    waterLocked = ok
    return ok
end

-- Travel pakai MOVE_MODE karakter (bukan soft-lock CFrame / PivotTo).
local function travelToWaterCf(cf, groundPos, lookTarget)
    if typeof(cf) ~= "CFrame" then return false end
    if _shouldYieldForPriority() then
        return false
    end
    local Move = _move()
    local mode = _getMoveMode()
    local hrp = getHRP()
    local gpos = typeof(groundPos) == "Vector3" and groundPos or cf.Position
    local flatDist = math.huge
    if hrp then
        local d = hrp.Position - gpos
        flatDist = Vector3.new(d.X, 0, d.Z).Magnitude
    end

    unlockWaterPos()

    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false
    end

    local look = typeof(lookTarget) == "Vector3" and lookTarget or (cf.Position + Vector3.new(0, 0, -1))
    local travelOpts = { mode = mode, reason = "water" }

    -- Walk: Humanoid:MoveTo ke XZ saja (jangan fallback soft — itu yang bikin terasa sama)
    if mode == "walk" then
        local walkCf = CFrame.lookAt(
            Vector3.new(cf.Position.X, gpos.Y + NORMAL_STAND_Y, cf.Position.Z),
            look
        )
        local ok = select(1, pcall(Move.GoTo, walkCf, travelOpts))
        if ok == false then return false end
    else
        local ok = select(1, pcall(Move.GoTo, cf, travelOpts))
        if ok == false then return false end
    end

    if _shouldYieldForPriority() then
        unlockWaterPos()
        return false
    end

    -- Soft: tanpa LockAt (langsung berdiri di tujuan). Mode lain tetap lock biar tidak jatuh (above/below).
    if mode ~= "soft" then
        lockWaterPos(cf.Position)
    end
    waterGoalCf = cf
    return true
end

local function plantLookTarget(plant, groundPos)
    if not plant then
        return groundPos + Vector3.new(0, 10, 0)
    end
    local ok, pivot = pcall(function() return plant:GetPivot().Position end)
    if ok and typeof(pivot) == "Vector3" then
        return pivot
    end
    return groundPos + Vector3.new(0, 10, 0)
end

local function offsetPos(groundPos, yOffset)
    return Vector3.new(groundPos.X, groundPos.Y + yOffset, groundPos.Z)
end

-- Mode normal: berdiri di tanah, jarak datar dari target
local function normalStandPos(groundPos, lookTarget)
    local hrp = getHRP()
    local flat = Vector3.new(0, 0, -1)
    if hrp then
        local d = hrp.Position - groundPos
        flat = Vector3.new(d.X, 0, d.Z)
        if flat.Magnitude < 0.05 then
            local toLook = (typeof(lookTarget) == "Vector3" and lookTarget or groundPos) - groundPos
            flat = Vector3.new(toLook.X, 0, toLook.Z)
        end
        if flat.Magnitude < 0.05 then
            flat = Vector3.new(0, 0, -1)
        else
            flat = flat.Unit
        end
    end
    return Vector3.new(
        groundPos.X + flat.X * NORMAL_STAND_DIST,
        groundPos.Y + NORMAL_STAND_Y,
        groundPos.Z + flat.Z * NORMAL_STAND_DIST
    )
end

local function startHover(groundPos, lookTarget, yOffset, opts)
    opts = type(opts) == "table" and opts or {}
    local pos
    if opts.mode == "normal" then
        pos = normalStandPos(groundPos, lookTarget)
    else
        pos = offsetPos(groundPos, yOffset)
    end
    local cf = CFrame.lookAt(pos, lookTarget)
    travelToWaterCf(cf, (opts.mode == "normal") and pos or groundPos, lookTarget)
    return pos
end

stopHover = function()
    unlockWaterPos()
    waterGoalCf = nil
end

local function _isHoverActive()
    return waterLocked == true or typeof(waterGoalCf) == "CFrame"
end

-- Selesai water: lepas hold saja, tetap di posisi sekarang (tidak kembali ke awal).
local function _stopHoverSession()
    stopHover()
end

local function ensureWateringCanEquipped(tool, equipWaitSec)
    if not tool or not tool:IsA("Tool") then return false, tool end
    local char = LP.Character
    if not char then return false, tool end
    if tool.Parent == char then
        task.wait(0.05)
        return true, tool
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false, tool end

    pcall(function() hum:EquipTool(tool) end)

    local deadline = os.clock() + (equipWaitSec or EQUIP_WAIT_BASE)
    while os.clock() < deadline do
        if tool.Parent == char then
            task.wait(0.05)
            local equipped = char:FindFirstChild(tool.Name)
            if equipped and equipped:IsA("Tool") then
                return true, equipped
            end
            return true, tool
        end
        task.wait(0.03)
    end

    local equipped = char:FindFirstChild(tool.Name)
    if equipped and equipped:IsA("Tool") and equipped.Parent == char then
        return true, equipped
    end
    return tool.Parent == char, tool
end

local function unequipWateringCan(tool)
    local char = LP.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end

    local equipped = tool
    if not (equipped and equipped:IsA("Tool") and equipped.Parent == char) then
        equipped = char:FindFirstChildOfClass("Tool")
        if not equipped and tool then
            equipped = char:FindFirstChild(tool.Name)
        end
    end

    if equipped and equipped:IsA("Tool") and equipped.Parent == char
        and equipped:GetAttribute("WateringCan") ~= nil then
        pcall(function() hum:UnequipTools() end)
    end
end

----------------------------------------------------------------
-- Auto Tele pause / resume → Move.lua
----------------------------------------------------------------
local function _teleStopForWater()
    local Move = _move()
    if type(Move) == "table" and type(Move.PauseAutoTele) == "function" then
        teleWasOn = Move.PauseAutoTele("water") == true
        telePaused = Move.IsAutoTelePaused and Move.IsAutoTelePaused() or teleWasOn
        return
    end
    teleWasOn = false
    telePaused = false
end

local function _teleResumeNow()
    telePaused = false
    teleWasOn = false
    local Move = _move()
    if type(Move) == "table" and type(Move.ResumeAutoTele) == "function" then
        pcall(Move.ResumeAutoTele)
    end
end

local function _withTelePaused(fn)
    local Move = _move()
    if type(Move) == "table" and type(Move.WithAutoTelePaused) == "function" then
        return Move.WithAutoTelePaused("water", fn)
    end
    _teleStopForWater()
    local ok, a, b = pcall(fn)
    _teleResumeNow()
    if not ok then
        error(a)
    end
    return a, b
end

local function getTpModePlan(tpMode)
    tpMode = tostring(tpMode or "below"):lower()
    if tpMode == "normal" then
        return {
            mode   = "normal",
            startY = NORMAL_STAND_Y,
            step   = 0,
            limitY = NORMAL_STAND_Y,
            dir    = 0,
            standDist = NORMAL_STAND_DIST,
        }
    end
    if tpMode == "below" then
        return {
            mode   = "below",
            startY = BELOW_START,
            step   = Y_STEP,
            limitY = BELOW_Y_MAX,
            dir    = 1,
        }
    end
    return {
        mode   = "above",
        startY = ABOVE_START,
        step   = -Y_STEP,
        limitY = ABOVE_Y_MIN,
        dir    = -1,
    }
end

local function nextYOffset(yOffset, plan)
    if not plan or plan.dir == 0 or plan.mode == "normal" then
        return yOffset
    end
    if plan.dir > 0 then
        return math.min(plan.limitY, yOffset + plan.step)
    end
    return math.max(plan.limitY, yOffset + plan.step)
end

-- One can: hover/equip may retry; UseWateringCan Fire exactly once (game TryWater).
local function waterOneCanAtMode(ctx)
    if not UseWateringCan or type(UseWateringCan.Fire) ~= "function" then
        return false, "no_remote"
    end

    local groundPos  = ctx.groundPos
    local lookTarget = ctx.lookTarget
    local firePos    = ctx.firePos
    local tool       = ctx.tool
    local canName    = ctx.canName
    local timing     = ctx.timing or {}
    local plan       = ctx.plan or getTpModePlan("below")

    local preFireSec   = timing.preFireSec or PRE_FIRE_BASE
    local postWaterSec = timing.postWaterSec or POST_WATER_BASE
    local equipWaitSec = timing.equipWaitSec or EQUIP_WAIT_BASE

    local yOffset = plan.startY
    local hoverOpts = (plan.mode == "normal") and { mode = "normal" } or nil
    local useTool = nil

    for attempt = 1, MAX_EQUIP_ATTEMPTS do
        if not running then
            return false, "stopped"
        end
        if _shouldYieldForPriority() then
            local _, whyY = _shouldYieldForPriority()
            return false, whyY or "claim_busy"
        end

        startHover(groundPos, lookTarget, yOffset, hoverOpts)
        if _shouldYieldForPriority() then
            local _, whyY = _shouldYieldForPriority()
            return false, whyY or "claim_busy"
        end
        task.wait(HOVER_SETTLE)

        local equipped
        equipped, useTool = ensureWateringCanEquipped(tool, equipWaitSec)
        if equipped and useTool and useTool.Parent == LP.Character then
            tool = useTool
            break
        end
        useTool = nil
        if attempt >= MAX_EQUIP_ATTEMPTS then
            return false, "equip_fail"
        end
        yOffset = nextYOffset(yOffset, plan)
        task.wait(WATER_COOLDOWN)
    end

    if not useTool or useTool.Parent ~= LP.Character then
        return false, "equip_fail"
    end

    local actualCanName = tostring(useTool:GetAttribute("WateringCan") or "")
    if actualCanName == "" then
        actualCanName = tostring(canName)
    end

    task.wait(preFireSec)
    if not running then
        return false, "stopped"
    end
    if _shouldYieldForPriority() then
        local _, whyY = _shouldYieldForPriority()
        return false, whyY or "claim_busy"
    end

    -- Single Fire — same as game TryWater. Puddle FX can appear 3–5s late;
    -- do not wait/retry on FX (that caused 2–5 sprays per plant).
    UseWateringCan:Fire(firePos, actualCanName, useTool)
    task.wait(math.max(WATER_COOLDOWN, postWaterSec))
    return true, "fired"
end

-- All cans: one hover session, then return to start CFrame
local function waterPlantAllCans(plot, target, selectedCans, st)
    if not UseWateringCan then
        return false, "no_remote"
    end
    if _shouldYieldForPriority() then
        local _, whyY = _shouldYieldForPriority()
        return false, whyY or "claim_busy"
    end

    local settleSec = computeSettleSec(plot, st)
    local timing = {
        preFireSec   = math.max(PRE_FIRE_BASE, settleSec * 0.35),
        postWaterSec = math.max(POST_WATER_BASE, settleSec * 0.45),
        equipWaitSec = math.max(EQUIP_WAIT_BASE, settleSec + 0.25),
    }

    local groundPos = snapToPlantArea(plot, target.pos)
    if not groundPos then
        return false, "tp_fail"
    end

    local avail = select(1, getAvailableCanTypes(selectedCans))
    if #avail == 0 then
        return false, "no_can"
    end

    local tpMode = (st and st.tpMode) or "below"
    local plan = getTpModePlan(tpMode)
    local lookTarget = plantLookTarget(target.plant, groundPos)
    local firePos = groundPos - Vector3.new(0, WATER_Y_OFFSET, 0)
    local hoverOpts = (plan.mode == "normal") and { mode = "normal" } or nil

    local watered = 0
    local usedNames = {}
    local lastReason = nil

    _teleStopForWater()

    local ok, err = pcall(function()
        if _shouldYieldForPriority() then
            local _, whyY = _shouldYieldForPriority()
            lastReason = whyY or "claim_busy"
            return
        end
        startHover(groundPos, lookTarget, plan.startY, hoverOpts)
        if _shouldYieldForPriority() then
            local _, whyY = _shouldYieldForPriority()
            lastReason = whyY or "claim_busy"
            return
        end
        task.wait(HOVER_SETTLE)

        for i, canName in ipairs(avail) do
            if not running then break end
            if _shouldYieldForPriority() then
                local _, whyY = _shouldYieldForPriority()
                lastReason = whyY or "claim_busy"
                break
            end

            local tool = select(1, findWateringCanTool(selectedCans, canName))
            if not tool then
                lastReason = "no_can"
            else
                if watered > 0 then
                    local waitLeft = WATER_COOLDOWN - (os.clock() - lastWaterAt)
                    if waitLeft > 0 then
                        task.wait(waitLeft)
                    end
                end

                _publishStatus("working")

                local canOk, canReason = waterOneCanAtMode({
                    groundPos  = groundPos,
                    lookTarget = lookTarget,
                    plant      = target.plant,
                    firePos    = firePos,
                    tool       = tool,
                    canName    = canName,
                    timing     = timing,
                    plan       = plan,
                })

                if canOk then
                    watered += 1
                    lastWaterAt = os.clock()
                    lastReason = canReason
                    usedNames[#usedNames + 1] = tostring(canName)
                else
                    lastReason = canReason or "water_fail"
                    break
                end

                if i < #avail and watered > 0 then
                    task.wait(WATER_COOLDOWN)
                end
            end
        end
    end)

    -- Lepas hold di tempat (tidak kembali ke posisi awal), lalu unequip.
    _stopHoverSession()
    unequipWateringCan(nil)
    task.wait(UNEQUIP_SETTLE_SEC)
    -- Jangan Resume AutoTele kalau steal masih pegang sesi
    if not _stealBusy() then
        _teleResumeNow()
    else
        telePaused = false
        teleWasOn = false
        -- Lepas depth pause water saja lewat Resume (steal Keep tetap hold)
        local Move = _move()
        if type(Move) == "table" and type(Move.ResumeAutoTele) == "function" then
            pcall(Move.ResumeAutoTele)
        end
    end

    if not ok then
        return false, tostring(err)
    end
    if lastReason == "steal_busy" or lastReason == "claim_busy" or lastReason == "buy_busy" then
        return false, lastReason
    end
    if watered == 0 then
        return false, lastReason or "no_can"
    end
    if watered < #avail then
        return false, lastReason or "water_fail"
    end
    return true, table.concat(usedNames, " + ")
end

local function plotHasSprinkler(plot)
    if not plot then return false end
    local AS = G.AutoSprinkler or G.AutoSprinklerModule or rawget(_G, "AutoSprinkler")
    if type(AS) == "table" and type(AS.HasAnySprinklerOnPlot) == "function" then
        local ok, has = pcall(AS.HasAnySprinklerOnPlot, AS, plot)
        if ok then return has == true end
    end
    if type(AS) == "table" and type(AS.CountExistingSprinklers) == "function" then
        local ok, n = pcall(AS.CountExistingSprinklers, AS, plot)
        if ok then return (tonumber(n) or 0) > 0 end
    end
    -- Fallback ringan kalau AutoSprinkler belum load
    local folder = plot:FindFirstChild("Sprinklers")
    if folder and #folder:GetChildren() > 0 then return true end
    local important = plot:FindFirstChild("Important")
    if important then
        local f2 = important:FindFirstChild("Sprinklers")
        if f2 and #f2:GetChildren() > 0 then return true end
    end
    return false
end

local function tickOnce(st)
    if not st.enabled then
        _publishStatus("idle")
        return false
    end

    if loadingScreenActive() then
        _publishStatus("loading")
        return false
    end

    if not isGameReady() then
        _publishStatus("not_ready")
        return false
    end

    local yieldOn, why = _shouldYieldForPriority()
    if yieldOn then
        _publishStatus(why or "claim_busy")
        return false
    end

    local plot = getPlayerPlot()
    -- First: sprinkler harus ada di farm (kalau toggle ON).
    if st.requireSprinkler == true then
        if not plot then
            _publishStatus("no_plot")
            return false
        end
        if not plotHasSprinkler(plot) then
            _publishStatus("wait_sprinkler")
            return false
        end
    end

    local gateOk, gateReason, skipN = checkSkippedFruitGate(st, plot)
    if not gateOk then
        _publishStatus(gateReason, skipN)
        return false
    end

    local now = os.clock()
    if now - lastWaterAt < WATER_COOLDOWN then
        _publishStatus("cooldown")
        return false
    end

    if not next(st.plants) then
        _publishStatus("no_plants")
        return false
    end

    if not plot then
        _publishStatus("no_plot")
        return false
    end

    local targets = listTargetPlants(plot, st.plants)
    if #targets == 0 then
        _publishStatus("no_targets")
        return false
    end

    plantIndex = (plantIndex % #targets) + 1
    local target = targets[plantIndex]

    local ok, detail = waterPlantAllCans(plot, target, st.cans, st)
    if ok then
        _publishStatus("done")
        return true
    end
    if detail == "fx_remote" or detail == "puddle_fx" or detail == "attr" then
        _publishStatus("water_fail")
        return false
    end
    _publishStatus(detail or "fire_fail")
    return false
end

local function mainLoop(myId)
    fruitCountsReady = false
    if not waitForBootReady(myId) then
        if running and loopId == myId then
            _publishStatus(loadingScreenActive() and "loading" or "not_ready")
        end
    end
    -- Tunggu filter buah AC full dulu — baru boleh water / cek pause C/Sk.
    if running and loopId == myId then
        waitForHarvestCountsReady(myId, 60)
        refreshStatusCounts(true)
        if fruitCountsReady then
            _publishStatus("idle")
        else
            _publishStatus("scanning")
        end
    end

    while running and loopId == myId do
        local st = M.GetState()
        local plot = getPlayerPlot()
        local waitSec = computeLoopDelay(st, plot)
        if st.enabled then
            if loadingScreenActive() then
                _publishStatus("loading")
                waitSec = READY_POLL_SEC
            elseif not isGameReady() then
                _publishStatus("not_ready")
                waitSec = READY_POLL_SEC
            elseif fruitCountsReady ~= true and not acHarvestCountsReady() then
                waitForHarvestCountsReady(myId, 8)
                waitSec = READY_POLL_SEC
            else
                fruitCountsReady = true
                nextActionAt = 0
                local ok, err = pcall(tickOnce, st)
                if not ok then
                    _publishStatus("error", tostring(err))
                end
                -- Pause / wait sprinkler / no plants: poll cepat, jangan overwrite status jadi Delay.
                if _isHoldStatus(lastFailReason) then
                    waitSec = READY_POLL_SEC
                    nextActionAt = 0
                else
                    waitSec = computeLoopDelay(st, getPlayerPlot())
                    _beginDelayWait(waitSec)
                end
            end
        else
            nextActionAt = 0
            _publishStatus("idle")
        end
        task.wait(waitSec)
    end
end

function M.SetEnabled(on)
    on = (on == true)
    G.AUTO_WATERING_ENABLED = on
    _G.AUTO_WATERING_ENABLED = on
    _writeMain({ enabled = on })

    if on then
        plantIndex = 0
        cachedPlot = nil
        skipGatePaused = false
        fruitCountsReady = false
        lastFruitSlotsAt = 0
        nextActionAt = 0
        _publishStatus("scanning")
        if not running then
            running = true
            loopId += 1
            local myId = loopId
            task.spawn(function() mainLoop(myId) end)
        end
    else
        running = false
        loopId += 1
        skipGatePaused = false
        fruitCountsReady = false
        nextActionAt = 0
        _stopHoverSession()
        _teleResumeNow()
        unequipWateringCan(nil)
        _publishStatus("idle")
    end
end

M.setEnabled = M.SetEnabled
function M.Start() return M.SetEnabled(true) end
M.start = M.Start
function M.Stop() return M.SetEnabled(false) end
M.stop = M.Stop

function M.IsEnabled()
    return M.GetState().enabled
end

function M.GetStatusText()
    local st = M.GetState()
    if not st.enabled then
        return "Off"
    end

    -- C/Sk sudah pernah trusted: jangan balik Scanning cuma karena AC sedang rescan.
    if fruitCountsReady ~= true then
        if acHarvestCountsReady() then
            fruitCountsReady = true
            if lastFailReason == "scanning" or lastStatusBase == STATUS_TEXT.scanning then
                lastFailReason = "idle"
                lastStatusBase = STATUS_TEXT.idle
            end
        else
            lastStatusBase = STATUS_TEXT.scanning
            return _composeStatusText(STATUS_TEXT.scanning, st)
        end
    end

    -- Refresh C/Sk/Bp untuk UI (throttle di refreshStatusCounts).
    refreshStatusCounts(false)

    local pauseCollectAt = math.floor(tonumber(st.pauseCollectFruit) or 0)
    local pauseSkipAt = math.floor(tonumber(st.pauseSkippedFruit) or 0)
    local pauseBackpackAt = math.floor(tonumber(st.pauseBackpackTotal) or 0)
    if pauseCollectAt > 0 and lastCollectCount >= pauseCollectAt then
        lastFailReason = "collect_pause"
        lastStatusBase = STATUS_TEXT.collect_pause
    elseif pauseSkipAt > 0 and lastSkippedCount >= pauseSkipAt then
        lastFailReason = "skip_pause"
        lastStatusBase = STATUS_TEXT.skip_pause
    elseif pauseBackpackAt > 0 and lastBackpackCount >= pauseBackpackAt then
        lastFailReason = "backpack_pause"
        lastStatusBase = STATUS_TEXT.backpack_pause
    elseif st.requireSprinkler == true then
        local plot = getPlayerPlot()
        if not plot or not plotHasSprinkler(plot) then
            lastFailReason = "wait_sprinkler"
            lastStatusBase = STATUS_TEXT.wait_sprinkler
        elseif lastFailReason == "wait_sprinkler" then
            -- Sprinkler sudah ada — jangan stuck di Wait sprinkler.
            lastFailReason = nil
            if lastStatusBase == STATUS_TEXT.wait_sprinkler then
                lastStatusBase = nil
            end
        end
    end

    local delayLeft = nextActionAt - os.clock()
    if delayLeft > 0.05 and not _isHoldStatus(lastFailReason) then
        lastFailReason = "delay_wait"
        lastStatusBase = STATUS_TEXT.delay_wait
    end

    -- JANGAN fallback ke __GAG2_WATERING_STATUS (itu sudah full compose → status dobel).
    local base = lastStatusBase or _statusMessage(lastFailReason) or STATUS_TEXT.idle
    return _composeStatusText(base, st)
end

function M.GetFruitCount()
    return math.floor(tonumber(lastFruitCount) or 0)
end

M.getFruitCount = M.GetFruitCount

function M.SyncFromState()
    local st = M.GetState()
    M.SetEnabled(st.enabled)
end

M.syncFromState = M.SyncFromState

function M.BuildGardenPlantItems()
    local AS = G.AutoSprinkler or G.AutoSprinklerModule or rawget(_G, "AutoSprinkler")
    if type(AS) == "table" and type(AS.BuildGardenPlantItems) == "function" then
        local ok, items = pcall(AS.BuildGardenPlantItems, AS)
        if ok and type(items) == "table" then return items end
    end
    return { { key = "_none", name = "(No plants in garden)" } }
end

M.buildGardenPlantItems = M.BuildGardenPlantItems

G.AutoWatering = M
G.AutoWateringModule = M
_G.AutoWatering = M
_G.AutoWateringModule = M

G.__GAG2_WATERING_STATUS = "Off"
_G.__GAG2_WATERING_STATUS = "Off"

return M
 end,                   required = false },
    { key = "SectionAutoWatering",     name = "Section Auto Watering",   factory = function() -- section_auto_watering.lua — UI section Auto Watering (tab Auto)

local G = (getgenv and getgenv()) or _G
local M = {}

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto       = ctx.getAuto
    local patchAuto     = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local registerFlush = ctx.registerFlush
    local cleanSelectedMap = ctx.cleanSelectedMap
    local arrayToMap    = ctx.arrayToMap
    local mapToArray    = ctx.mapToArray
    local toggleApiGet  = ctx.toggleApiGet

    local WateringCanListView = G.WateringCanListView or rawget(_G, "WateringCanListView")

    local W_STATE = getAuto("watering")
    W_STATE.plants = type(W_STATE.plants) == "table" and W_STATE.plants or {}
    W_STATE.cans = type(W_STATE.cans) == "table" and W_STATE.cans or {}
    do
        local m = tostring(W_STATE.tpMode or "below"):lower()
        if m == "atas" or m == "top" or m == "over" or m == "above" then
            m = "above"
        elseif m == "normal" or m == "flat" or m == "ground" then
            m = "normal"
        else
            m = "below"
        end
        W_STATE.tpMode = m
    end

    local AUTO_WATERING_PLANTS_SELECTED = cleanSelectedMap(arrayToMap(W_STATE.plants))
    local AUTO_WATERING_CANS_SELECTED = cleanSelectedMap(arrayToMap(W_STATE.cans))

    G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
    _G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
    G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED
    _G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED

    local function delayDisplay()
        local n = tonumber(W_STATE.delay)
        return (n ~= nil) and n or 3
    end

    local function settleDisplay()
        local n = tonumber(W_STATE.settleDelay)
        return (n ~= nil) and n or 0
    end

    local function pauseSkippedDisplay()
        local n = tonumber(W_STATE.pauseSkippedFruit)
        return (n ~= nil) and n or 0
    end

    local function pauseCollectDisplay()
        local n = tonumber(W_STATE.pauseCollectFruit)
        return (n ~= nil) and n or 0
    end

    local function pauseBackpackDisplay()
        local n = tonumber(W_STATE.pauseBackpackTotal)
        return (n ~= nil) and n or 0
    end

    local function tpModeDisplay()
        local m = tostring(W_STATE.tpMode or "below"):lower()
        if m == "atas" or m == "top" or m == "over" or m == "above" then
            return "above"
        end
        if m == "normal" or m == "flat" or m == "ground" then
            return "normal"
        end
        return "below"
    end

    local function writeWateringGlobals()
        local api = G.__GAG2_WATERING_ENABLE_API or rawget(_G, "__GAG2_WATERING_ENABLE_API")
        if type(api) == "table" and type(api.get) == "function" then
            W_STATE.enabled = (api.get() == true)
        end

        W_STATE.tpMode = tpModeDisplay()

        G.AUTO_WATERING_ENABLED = (W_STATE.enabled == true)
        _G.AUTO_WATERING_ENABLED = G.AUTO_WATERING_ENABLED
        G.AUTO_WATERING_DELAY = tonumber(W_STATE.delay) or 3
        _G.AUTO_WATERING_DELAY = G.AUTO_WATERING_DELAY
        G.AUTO_WATERING_SETTLE_DELAY = tonumber(W_STATE.settleDelay) or 0
        _G.AUTO_WATERING_SETTLE_DELAY = G.AUTO_WATERING_SETTLE_DELAY
        G.AUTO_WATERING_PAUSE_SKIPPED_FRUIT = tonumber(W_STATE.pauseSkippedFruit) or 0
        _G.AUTO_WATERING_PAUSE_SKIPPED_FRUIT = G.AUTO_WATERING_PAUSE_SKIPPED_FRUIT
        G.AUTO_WATERING_PAUSE_COLLECT_FRUIT = tonumber(W_STATE.pauseCollectFruit) or 0
        _G.AUTO_WATERING_PAUSE_COLLECT_FRUIT = G.AUTO_WATERING_PAUSE_COLLECT_FRUIT
        G.AUTO_WATERING_PAUSE_BACKPACK_TOTAL = tonumber(W_STATE.pauseBackpackTotal) or 0
        _G.AUTO_WATERING_PAUSE_BACKPACK_TOTAL = G.AUTO_WATERING_PAUSE_BACKPACK_TOTAL
        G.AUTO_WATERING_TP_MODE = W_STATE.tpMode
        _G.AUTO_WATERING_TP_MODE = W_STATE.tpMode
        G.AUTO_WATERING_REQUIRE_SPRINKLER = (W_STATE.requireSprinkler == true)
        _G.AUTO_WATERING_REQUIRE_SPRINKLER = G.AUTO_WATERING_REQUIRE_SPRINKLER
        G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
        _G.AUTO_WATERING_PLANTS_SELECTED = AUTO_WATERING_PLANTS_SELECTED
        G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED
        _G.AUTO_WATERING_CANS_SELECTED = AUTO_WATERING_CANS_SELECTED

        patchAutoOnly("watering", {
            enabled = (W_STATE.enabled == true),
            plants  = mapToArray(AUTO_WATERING_PLANTS_SELECTED),
            cans    = mapToArray(AUTO_WATERING_CANS_SELECTED),
            delay              = W_STATE.delay,
            settleDelay        = W_STATE.settleDelay,
            pauseSkippedFruit  = W_STATE.pauseSkippedFruit,
            pauseCollectFruit  = W_STATE.pauseCollectFruit,
            pauseBackpackTotal = W_STATE.pauseBackpackTotal,
            tpMode             = W_STATE.tpMode,
            requireSprinkler   = (W_STATE.requireSprinkler == true),
        })
    end

    G.__GAG2_PUSH_WATERING = writeWateringGlobals
    _G.__GAG2_PUSH_WATERING = writeWateringGlobals

    registerFlush("watering", function()
        writeWateringGlobals()
    end)

    writeWateringGlobals()

    local function syncWateringModule()
        writeWateringGlobals()
        local mod = G.AutoWatering or G.AutoWateringModule
        if type(mod) ~= "table" then return end
        if G.AUTO_WATERING_ENABLED then
            if type(mod.Start) == "function" then pcall(mod.Start, mod) end
        else
            if type(mod.Stop) == "function" then pcall(mod.Stop, mod) end
        end
    end

    G.__GAG2_SYNC_AUTO_WATERING = syncWateringModule
    _G.__GAG2_SYNC_AUTO_WATERING = syncWateringModule

    local body = ui:CreateSection("Auto Watering", false)

    local _, statusLbl = ui:CreateRowLabel(body, "Status: —", nil, 1, "accent")
    if statusLbl then
        statusLbl.TextTruncate = Enum.TextTruncate.AtEnd
