    task.spawn(function()
        while body and body.Parent do
            if body.Visible ~= false then
                pcall(function()
                    if statusLbl and statusLbl.Parent then
                        statusLbl.TextTruncate = Enum.TextTruncate.AtEnd
                        local txt = "Status: Off"
                        local mod = G.AutoWatering or G.AutoWateringModule or rawget(_G, "AutoWatering")
                        if type(mod) == "table" and type(mod.GetStatusText) == "function" then
                            local ok, out = pcall(mod.GetStatusText, mod)
                            if ok and type(out) == "string" and out ~= "" then
                                txt = "Status: " .. out
                            end
                        end
                        statusLbl.Text = txt
                    end
                end)
            end
            task.wait(0.4)
        end
    end)

