            local m = tostring(selectedKey or "below"):lower()
            if m == "above" then
                W_STATE.tpMode = "above"
            elseif m == "normal" then
                W_STATE.tpMode = "normal"
            else
                W_STATE.tpMode = "below"
            end
            patchAuto("watering", { tpMode = W_STATE.tpMode }, syncWateringModule)
        end,
    })

    ui:CreateRowInput(
        body,
