    { key = "ShopListView",            name = "ShopListView",            factory = function() -- ShopListView.lua — Grow A Garden 2
-- Gear: SharedModules.GearShopData
-- Props Shop (crates): SharedModules.CrateData → child ModuleScripts per crate

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local SharedModules = ReplicatedStorage:WaitForChild("SharedModules")

local G = (getgenv and getgenv()) or _G

local M = {}

local _gearMapCache = nil
local _gearSourceTag = nil
local _propsMapCache = nil
local _propsSourceTag = nil
local _seedPackCache = nil
local _seedPackSourceTag = nil
local _eggCache = nil
local _eggSourceTag = nil

local GEAR_MODULE_NAMES = { "GearShopData", "GearData", "Gears" }
local SEEDPACK_MODULE_NAMES = { "SeedPackData", "SeedPacks", "SeedPackShopData" }
local EGG_MODULE_NAMES = { "EggData", "Eggs", "EggShopData", "PetEggData" }

local function _safeRequire(inst)
    if not inst or not inst:IsA("ModuleScript") then return nil end
    local ok, mod = pcall(require, inst)
    if ok and type(mod) == "table" then return mod end
    return nil
end

local function _firstModule(names)
    for _, name in ipairs(names) do
        local mod = _safeRequire(SharedModules:FindFirstChild(name))
        if mod then return mod, name end
    end
    return nil, nil
end

local function _unwrapCatalog(mod)
    if type(mod) ~= "table" then return mod end
    if type(mod.Data) == "table" and #mod.Data > 0 then return mod.Data end
    if type(mod.Data) == "table" and next(mod.Data) ~= nil then return mod.Data end
    if type(mod.Gear) == "table" then return mod.Gear end
    if type(mod.Items) == "table" then return mod.Items end
    return mod
end

local function _normalizeWorlds(worlds)
    local out = {}
    if type(worlds) ~= "table" then return out end
    for _, w in pairs(worlds) do
        if type(w) == "string" and w ~= "" then
            out[w] = true
        end
    end
    return out
end

--- Item tanpa Worlds → semua world (sama Worlds.EntryAvailableHere di game).
local function _matchesWorld(info, world)
    if not world or world == "" then return true end
    local worlds = type(info) == "table" and info.Worlds or nil
    if type(worlds) ~= "table" or not next(worlds) then
        return true
    end
    return worlds[world] == true
end

local function _formatPrice(n)
    local PLV = G.PlantListView or rawget(_G, "PlantListView")
    if type(PLV) == "table" and type(PLV.formatSeedPrice) == "function" then
        local ok, s = pcall(PLV.formatSeedPrice, n)
        if ok and type(s) == "string" then return s end
    end
    n = tonumber(n)
    if not n or n ~= n or n < 0 or n == math.huge then return "0" end
    n = math.floor(n + 0.5)
    if n >= 1e9 then return tostring(math.floor(n / 1e9 + 0.5)) .. "b" end
    if n >= 1e6 then return tostring(math.floor(n / 1e6 + 0.5)) .. "m" end
    if n >= 1e3 then return tostring(math.floor(n / 1e3 + 0.5)) .. "k" end
    return tostring(n)
end

local function _normalizeEntry(entry, keyHint, orderHint)
    if type(entry) ~= "table" then return nil end

    local itemName = entry.CrateName or entry.ItemName or entry.GearName or entry.PropName
        or entry.PropId or entry.Name or entry.SeedName or entry.EggName
        or entry.PackName or entry.SeedPackName or keyHint
    if not itemName or tostring(itemName) == "" then return nil end

    local price = entry.Cost or entry.PurchasePrice or entry.Price or entry.FallbackPrice

    return {
        name     = tostring(itemName),
        itemType = entry.ItemType,
        rarity   = entry.Rarity,
        price    = price,
        order    = tonumber(entry.ShopDisplayOrder or entry.LayoutOrder or entry.SeedShopDisplayOrder)
            or tonumber(orderHint) or 9999,
        Worlds   = _normalizeWorlds(entry.Worlds),
        raw      = entry,
    }
end

local function _mergeCatalog(into, data)
    if type(data) ~= "table" then return end

    if #data > 0 then
        for i, entry in ipairs(data) do
            local norm = _normalizeEntry(entry, entry.CrateName, i)
            if norm then into[norm.name] = norm end
        end
        return
    end

    local i = 0
    for key, entry in pairs(data) do
        if type(entry) == "table" then
            i += 1
            local norm = _normalizeEntry(entry, key, i)
            if norm then into[norm.name] = norm end
        end
    end
end

local function _mapToSortedArray(map, opts)
    opts = opts or {}
    local world = opts.world
    local arr = {}
    for _, info in pairs(map) do
        if _matchesWorld(info, world) then
            arr[#arr + 1] = info
        end
    end
    table.sort(arr, function(a, b)
        if a.order ~= b.order then return a.order < b.order end
        return a.name < b.name
    end)
    return arr
end

local function _catalogToItems(map, opts)
    opts = type(opts) == "table" and opts or {}
    local showPrice = opts.showPrice == true
    local out = {}
    for _, info in ipairs(_mapToSortedArray(map, opts)) do
        local name = info.name
        if showPrice then
            name = info.name .. " · " .. _formatPrice(info.price)
        end
        local right = info.rarity
        if not showPrice and info.price then
            local p = tonumber(info.price)
            if p and p > 0 then
                right = right and (tostring(right) .. " · " .. p) or tostring(p)
            end
        end
        out[#out + 1] = {
            key   = info.name,
            name  = name,
            right = right,
            raw   = info,
        }
    end
    return out
end

local function _maybeSortDropdown(items, opts)
    if type(opts) ~= "table" then return items end
    local sortBy = tostring(opts.sortBy or ""):lower()
    if sortBy ~= "rarity" and sortBy ~= "price" then
        return items
    end
    local out = {}
    for i, it in ipairs(items) do
        out[i] = it
    end
    local PLV = G.PlantListView or _G.PlantListView
    if sortBy == "price" then
        if type(PLV) == "table" and type(PLV.sortDropdownByPrice) == "function" then
            return PLV.sortDropdownByPrice(out)
        end
        return out
    end
    if type(PLV) == "table" and type(PLV.sortDropdownByRarity) == "function" then
        return PLV.sortDropdownByRarity(out)
    end
    return out
end

-- Props Shop in-game = crate shop (Sign Crate, Arch Crate, ...)
local function _tryGetCrateEntry(crateApi, crateName, childModule)
    crateName = tostring(crateName or "")

    if type(crateApi) == "table" and type(crateApi.GetData) == "function" and crateName ~= "" then
        -- GAG2: GetData(crateName: string) — jangan pass self/table
        local ok, data = pcall(function()
            return crateApi.GetData(crateName)
        end)
        if ok and type(data) == "table" then
            return data
        end
    end

    if childModule and childModule:IsA("ModuleScript") then
        local ok, mod = pcall(require, childModule)
        if ok and type(mod) == "table" then
            if type(mod.GetData) == "function" then
                local ok2, data = pcall(function()
                    return mod.GetData()
                end)
                if ok2 and type(data) == "table" then
                    return data
                end
            end
            if mod.CrateName or mod.Cost or mod.Rarity or mod.Name then
                return mod
            end
        end
    end

    return nil
end

local function _loadCratesFromCrateData()
    local crateRoot = SharedModules:FindFirstChild("CrateData")
    if not crateRoot or not crateRoot:IsA("ModuleScript") then
        return {}, nil
    end

    local crateApi = _safeRequire(crateRoot)
    if not crateApi then
        return {}, "SharedModules.CrateData (require failed)"
    end

    local out = {}
    local seen = {}
    local order = 0

    local function pushCrate(crateName, data)
        crateName = tostring(crateName or "")
        if crateName == "" or seen[crateName] then return end
        if type(data) ~= "table" then return end

        seen[crateName] = true
        order += 1

        out[#out + 1] = {
            CrateName = data.CrateName or crateName,
            Cost = data.Cost,
            Rarity = data.Rarity,
            RestockChance = data.RestockChance,
            ShopDisplayOrder = data.ShopDisplayOrder or order,
            Worlds = data.Worlds,
            raw = data,
        }
    end

    if type(crateApi.GetAllCrates) == "function" then
        local ok, all = pcall(function()
            return crateApi.GetAllCrates()
        end)
        if not ok then
            ok, all = pcall(function()
                return crateApi.GetAllCrates(crateApi)
            end)
        end
        if ok and type(all) == "table" then
            for key, data in pairs(all) do
                if type(data) == "table" then
                    local name = data.CrateName or data.Name or data.ItemName
                    if not name and type(key) == "string" then
                        name = key
                    end
                    pushCrate(name, data)
                elseif type(key) == "string" then
                    pushCrate(key, { CrateName = key, Name = key })
                end
            end
        end
    end

    for _, child in ipairs(crateRoot:GetChildren()) do
        if child:IsA("ModuleScript") then
            local data = _tryGetCrateEntry(crateApi, child.Name, child)
            if data then
                pushCrate(data.CrateName or child.Name, data)
            end
        end
    end

    return out, "SharedModules.CrateData"
end

local function _getGearMap()
    if _gearMapCache then return _gearMapCache end
    local mod, tag = _firstModule(GEAR_MODULE_NAMES)
    _gearSourceTag = tag or "SharedModules.GearShopData (missing)"
    local map = {}
    _mergeCatalog(map, _unwrapCatalog(mod))
    _gearMapCache = map
    return _gearMapCache
end

local function _getPropsMap()
    if _propsMapCache then return _propsMapCache end
    local data, tag = _loadCratesFromCrateData()
    _propsSourceTag = tag or "SharedModules.CrateData (missing)"
    local map = {}
    _mergeCatalog(map, data)
    _propsMapCache = map
    return _propsMapCache
end

local function _keySetForWorld(map, world)
    local set = {}
    for _, info in pairs(map) do
        if _matchesWorld(info, world) then
            set[info.name] = true
        end
    end
    return set
end

local function _filterSelectedForWorld(map, selectedMap, world)
    local set = _keySetForWorld(map, world)
    local out = {}
    if type(selectedMap) ~= "table" then return out end
    for k, v in pairs(selectedMap) do
        if v == true and set[k] then
            out[k] = true
        end
    end
    return out
end

local function _mergeSelectedForWorld(map, fullMap, world, worldSelectedMap)
    local set = _keySetForWorld(map, world)
    local out = {}
    if type(fullMap) == "table" then
        for k, v in pairs(fullMap) do
            if v == true and not set[k] then
                out[k] = true
            end
        end
    end
    if type(worldSelectedMap) == "table" then
        for k, v in pairs(worldSelectedMap) do
            if v == true and set[k] then
                out[k] = true
            end
        end
    end
    return out
end

function M.getGearSourceTag()
    if _gearSourceTag then return _gearSourceTag end
    local _, tag = _firstModule(GEAR_MODULE_NAMES)
    return tag or "SharedModules.GearShopData (missing)"
end

function M.getPropsSourceTag()
    if _propsSourceTag then return _propsSourceTag end
    local _, tag = _loadCratesFromCrateData()
    return tag or "SharedModules.CrateData (missing)"
end

function M.refresh()
    _gearMapCache = nil
    _gearSourceTag = nil
    _propsMapCache = nil
    _propsSourceTag = nil
    _seedPackCache = nil
    _seedPackSourceTag = nil
    _eggCache = nil
    _eggSourceTag = nil
end

function M.buildGearItems(opts)
    opts = type(opts) == "table" and opts or {}
    return _maybeSortDropdown(_catalogToItems(_getGearMap(), opts), opts)
end

function M.buildPropsItems(opts)
    opts = type(opts) == "table" and opts or {}
    return _maybeSortDropdown(_catalogToItems(_getPropsMap(), opts), opts)
end

M.buildCrateItems = M.buildPropsItems

function M.gearKeySetForWorld(world)
    return _keySetForWorld(_getGearMap(), world)
end

function M.propsKeySetForWorld(world)
    return _keySetForWorld(_getPropsMap(), world)
end

function M.filterGearSelectedForWorld(selectedMap, world)
    return _filterSelectedForWorld(_getGearMap(), selectedMap, world)
end

function M.filterPropsSelectedForWorld(selectedMap, world)
    return _filterSelectedForWorld(_getPropsMap(), selectedMap, world)
end

function M.mergeGearSelectedForWorld(fullMap, world, worldSelectedMap)
    return _mergeSelectedForWorld(_getGearMap(), fullMap, world, worldSelectedMap)
end

function M.mergePropsSelectedForWorld(fullMap, world, worldSelectedMap)
    return _mergeSelectedForWorld(_getPropsMap(), fullMap, world, worldSelectedMap)
end

function M.buildSeedPackItems(opts)
    if not _seedPackCache then
        local mod, tag = _firstModule(SEEDPACK_MODULE_NAMES)
        _seedPackSourceTag = tag or "SharedModules.SeedPackData (missing)"
        local map = {}
        _mergeCatalog(map, _unwrapCatalog(mod))
        _seedPackCache = _catalogToItems(map)
    end
    opts = type(opts) == "table" and opts or {}
    if opts.showPrice == true or opts.world then
        local mod = select(1, _firstModule(SEEDPACK_MODULE_NAMES))
        local map = {}
        _mergeCatalog(map, _unwrapCatalog(mod))
        return _maybeSortDropdown(_catalogToItems(map, opts), opts)
    end
    return _maybeSortDropdown(_seedPackCache, opts)
end

function M.buildEggItems(opts)
    if not _eggCache then
        local mod, tag = _firstModule(EGG_MODULE_NAMES)
        _eggSourceTag = tag or "SharedModules.EggData (missing)"
        local map = {}
        _mergeCatalog(map, _unwrapCatalog(mod))
        _eggCache = _catalogToItems(map)
    end
    opts = type(opts) == "table" and opts or {}
    if opts.showPrice == true or opts.world then
        local mod = select(1, _firstModule(EGG_MODULE_NAMES))
        local map = {}
        _mergeCatalog(map, _unwrapCatalog(mod))
        return _maybeSortDropdown(_catalogToItems(map, opts), opts)
    end
    return _maybeSortDropdown(_eggCache, opts)
end

G.ShopListView = M
_G.ShopListView = M

return M
 end,                   required = false },
    { key = "PetListView",             name = "PetListView",             factory = function() -- PetListView.lua — Grow A Garden 2
-- Catalog pet types + rarity dari SharedData.PetData (fallback: SharedModules.PetModules)

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local SharedData = ReplicatedStorage:WaitForChild("SharedData", 15)
local SharedModules = ReplicatedStorage:WaitForChild("SharedModules", 15)

local M = {}

-- GAG2 pet rarities (SharedData.PetData): Common → Super
local GAG2_RARITY_TIER = {
    Common = 1,
    Uncommon = 2,
    Rare = 3,
    Legendary = 4,
    Mythic = 5,
    Super = 6,
}

local function _tierForRarity(rarityName)
    rarityName = tostring(rarityName or "")
    if rarityName == "" then return 0 end
    if GAG2_RARITY_TIER[rarityName] then
        return GAG2_RARITY_TIER[rarityName]
    end
    local want = rarityName:lower():gsub("[%s_%-]+", "")
    for name, tier in pairs(GAG2_RARITY_TIER) do
        if name:lower():gsub("[%s_%-]+", "") == want then
            return tier
        end
    end
    return 0
end

local function _safeRequire(inst)
    if not inst or not inst:IsA("ModuleScript") then return nil end
    local ok, mod = pcall(require, inst)
    if ok and type(mod) == "table" then return mod end
    return nil
end

local function _loadPetData()
    if not SharedData then return nil, "SharedData.PetData (missing SharedData)" end
    local root = SharedData:FindFirstChild("PetData")
    if not root or not root:IsA("ModuleScript") then
        return nil, "SharedData.PetData (missing)"
    end
    local mod = _safeRequire(root)
    if mod then return mod, "SharedData.PetData" end
    return nil, "SharedData.PetData (require failed)"
end

local function _loadPetModules()
    if not SharedModules then return nil, "SharedModules.PetModules (missing SharedModules)" end
    local root = SharedModules:FindFirstChild("PetModules")
    if not root then return nil, "SharedModules.PetModules (missing)" end

    if root:IsA("ModuleScript") then
        local mod = _safeRequire(root)
        if mod then return mod, "SharedModules.PetModules" end
    end

    local out = {}
    for _, child in ipairs(root:GetChildren()) do
        if child:IsA("ModuleScript") then
            local cfg = _safeRequire(child)
            if cfg then
                out[child.Name] = cfg
            end
        end
    end

    if next(out) then
        return out, "SharedModules.PetModules/*"
    end

    return nil, "SharedModules.PetModules (empty)"
end

local function _loadPetCatalog()
    local catalog, tag = _loadPetData()
    if catalog then return catalog, tag end
    return _loadPetModules()
end

local function _iterCatalog(catalog, fn)
    if type(catalog) ~= "table" then return end
    if catalog[1] ~= nil then
        for _, cfg in ipairs(catalog) do
            fn(nil, cfg)
        end
        return
    end
    for petName, cfg in pairs(catalog) do
        if type(cfg) == "function" then
            -- skip PetData helper methods (GetImage, GetDisplayName, ...)
        elseif type(cfg) == "table" then
            fn(petName, cfg)
        end
    end
end

local function _formatAssetId(raw)
    if raw == nil then return nil end
    if type(raw) == "number" then
        return "rbxassetid://" .. tostring(math.floor(raw))
    end
    local s = tostring(raw)
    if s == "" then return nil end
    if s:find("^rbxassetid://") or s:find("^http") then
        return s
    end
    if s:match("^%d+$") then
        return "rbxassetid://" .. s
    end
    return s
end

local function _resolvePetIcon(petName, cfg, catalog)
    if type(cfg) == "table" then
        local direct = _formatAssetId(cfg.Image or cfg.Icon or cfg.ImageId or cfg.Thumbnail)
        if direct then return direct end
    end
    if type(catalog) == "table" and type(catalog.GetImage) == "function" then
        local ok, img = pcall(catalog.GetImage, petName)
        if ok then
            local formatted = _formatAssetId(img)
            if formatted then return formatted end
        end
    end
    return nil
end

local function _normalizePetEntry(petName, cfg, catalog)
    petName = tostring(petName or "")
    if petName == "" then return nil end

    local rarity = nil
    local displayName = petName
    local assetName = nil
    if type(cfg) == "table" then
        rarity = cfg.Rarity or cfg.DisplayRarity
        displayName = cfg.DisplayName or petName
        assetName = cfg.AssetName or cfg.ModelName
    end

    return {
        name      = displayName,
        key       = petName,
        rarity    = rarity,
        assetName = assetName,
        icon      = _resolvePetIcon(petName, cfg, catalog),
        order     = 9999,
        raw       = cfg,
    }
end

local _petCache = nil
local _sourceTag = nil
local _rarityRank = {}
local _rarityOrder = {}

local function _petModuleRarity(cfg)
    if type(cfg) ~= "table" then return nil end
    local r = cfg.Rarity or cfg.DisplayRarity
    if r == nil or tostring(r) == "" then return nil end
    return tostring(r)
end

local function _petModulePrice(cfg)
    if type(cfg) ~= "table" then return 0 end
    return tonumber(cfg.BasePrice or cfg.PurchasePrice or cfg.Price or cfg.WildPrice or cfg.Cost or cfg.TamePrice) or 0
end

local function _rebuildRarityRank(rarityMaxPrice)
    local list = {}
    for rarity, price in pairs(rarityMaxPrice) do
        list[#list + 1] = { rarity = rarity, price = price }
    end
    table.sort(list, function(a, b)
        local ta = _tierForRarity(a.rarity)
        local tb = _tierForRarity(b.rarity)
        if ta ~= tb then
            if ta > 0 and tb > 0 then return ta > tb end
            if ta > 0 then return true end
            if tb > 0 then return false end
        end
        if a.price ~= b.price then return a.price > b.price end
        return tostring(a.rarity) < tostring(b.rarity)
    end)

    local rank = {}
    local order = {}
    local total = #list
    for i, item in ipairs(list) do
        rank[item.rarity] = total - i + 1
        order[#order + 1] = item.rarity
    end
    return rank, order
end

local function _ingestPetCfg(cfg, rarityMaxPrice)
    local rarity = _petModuleRarity(cfg)
    if not rarity then return end
    local price = _petModulePrice(cfg)
    rarityMaxPrice[rarity] = math.max(rarityMaxPrice[rarity] or 0, price)
end

function M.refreshRarityIndex(extraRarities)
    local rarityMaxPrice = {}

    local catalog = _loadPetCatalog()
    _iterCatalog(catalog, function(_, cfg)
        _ingestPetCfg(cfg, rarityMaxPrice)
    end)

    if type(extraRarities) == "table" then
        for _, rarity in ipairs(extraRarities) do
            rarity = tostring(rarity or "")
            if rarity ~= "" and not rarityMaxPrice[rarity] then
                local tier = _tierForRarity(rarity)
                rarityMaxPrice[rarity] = (tier > 0) and tier or 0
            end
        end
    end

    _rarityRank, _rarityOrder = _rebuildRarityRank(rarityMaxPrice)
    return _rarityRank, _rarityOrder
end

function M.getRarityRank(rarityName)
    rarityName = tostring(rarityName or "")
    if rarityName == "" then return 0 end

    local tier = _tierForRarity(rarityName)
    if tier > 0 then
        return tier
    end

    if next(_rarityRank) == nil then
        M.refreshRarityIndex()
    end
    if _rarityRank[rarityName] then
        return _rarityRank[rarityName]
    end
    local want = rarityName:lower()
    for k, v in pairs(_rarityRank) do
        if tostring(k):lower() == want then
            return v
        end
    end
    return 0
end

function M.getGag2RarityTier(rarityName)
    return _tierForRarity(rarityName)
end

function M.buildRarityItems(extraRarities)
    M.refreshRarityIndex(extraRarities)

    local out = {}
    for _, rarity in ipairs(_rarityOrder) do
        out[#out + 1] = { key = rarity, name = rarity }
    end

    if type(extraRarities) == "table" then
        local known = {}
        for _, item in ipairs(out) do
            known[item.key] = true
        end
        local extras = {}
        for _, rarity in ipairs(extraRarities) do
            rarity = tostring(rarity or "")
            if rarity ~= "" and not known[rarity] then
                extras[#extras + 1] = rarity
                known[rarity] = true
            end
        end
        table.sort(extras)
        for _, rarity in ipairs(extras) do
            out[#out + 1] = { key = rarity, name = rarity }
        end
    end

    return out
end

function M.getRarityColor(rarityName)
    rarityName = tostring(rarityName or "")
    if rarityName == "" then
        return Color3.fromRGB(255, 211, 0)
    end

    local rank = M.getRarityRank(rarityName)
    if next(_rarityOrder) == nil then
        M.refreshRarityIndex()
    end

    local maxRank = #_rarityOrder
    if rank > 0 and maxRank > 0 then
        local t = (maxRank > 1) and ((rank - 1) / (maxRank - 1)) or 0.5
        return Color3.fromHSV(0.08 + t * 0.72, 0.82, 1)
    end

    local h = 0
    for i = 1, #rarityName do
        h = (h + string.byte(rarityName, i) * i) % 360
    end
    return Color3.fromHSV(h / 360, 0.65, 0.95)
end

function M.getSourceTag()
    if _sourceTag then return _sourceTag end
    local _, tag = _loadPetCatalog()
    return tag or "SharedData.PetData (missing)"
end

function M.refresh()
    _petCache = nil
    _sourceTag = nil
    _rarityRank = {}
    _rarityOrder = {}
end

function M.buildPetItems()
    if _petCache then return _petCache end

    local catalog, tag = _loadPetCatalog()
    _sourceTag = tag or "SharedData.PetData (missing)"

    local arr = {}
    _iterCatalog(catalog, function(petName, cfg)
        local info = _normalizePetEntry(petName, cfg, catalog)
        if info then arr[#arr + 1] = info end
    end)

    table.sort(arr, function(a, b)
        return a.name < b.name
    end)

    local out = {}
    for _, info in ipairs(arr) do
        out[#out + 1] = {
            key   = info.key or info.name,
            name  = info.name,
            right = info.rarity,
            icon  = info.icon,
            raw   = info.raw,
        }
    end

    _petCache = out
    return _petCache
end

function M.getPetRarity(petName)
    petName = tostring(petName or "")
    if petName == "" then return nil end
    local want = petName:lower()
    for _, item in ipairs(M.buildPetItems()) do
        local key = tostring(item.key or "")
        local name = tostring(item.name or "")
        if key == petName or name == petName
            or key:lower() == want or name:lower() == want then
            local r = item.right
            if r ~= nil and tostring(r) ~= "" then
                return tostring(r)
            end
        end
    end
    return nil
end

local function _petLookupKeys(raw)
    local s = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if s == "" then return {} end
    local out, seen = {}, {}
    local function push(v)
        v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if v == "" or seen[v] then return end
        seen[v] = true
        out[#out + 1] = v
    end
    push(s)
    local noTraits = s
    while true do
        local stripped = noTraits:gsub("%s*%b()%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if stripped == noTraits or stripped == "" then break end
        noTraits = stripped
        push(noTraits)
    end
    for i = 1, #out do
        local compact = out[i]:gsub("[%s_%-]+", "")
        if compact ~= "" then push(compact) end
    end
    return out
end

function M.getPetIcon(petName)
    petName = tostring(petName or "")
    if petName == "" then return nil end
    local wants = {}
    for _, v in ipairs(_petLookupKeys(petName)) do
        wants[v:lower()] = true
    end
    for _, item in ipairs(M.buildPetItems()) do
        local key = tostring(item.key or "")
        local name = tostring(item.name or "")
        for _, cand in ipairs(_petLookupKeys(key)) do
            if wants[cand:lower()] then return item.icon end
        end
        for _, cand in ipairs(_petLookupKeys(name)) do
            if wants[cand:lower()] then return item.icon end
        end
    end
    -- SharedModules image folders (Big Bee lives under GearImages, not PetData.Image)
    local folders = { "GearImages", "PetImages", "PropImages", "EggImages" }
    local sm = SharedModules
    if sm then
        for _, want in ipairs(_petLookupKeys(petName)) do
            local wantLow = want:lower()
            local wantCompact = wantLow:gsub("[%s_%-]+", "")
            for _, folderName in ipairs(folders) do
                local folder = sm:FindFirstChild(folderName)
                if folder then
                    local inst = folder:FindFirstChild(want)
                    if not inst then
                        for _, child in ipairs(folder:GetChildren()) do
                            local childLow = string.lower(child.Name)
                            if childLow == wantLow or childLow:gsub("[%s_%-]+", "") == wantCompact then
                                inst = child
                                break
                            end
                        end
                    end
                    if inst then
                        local raw = nil
                        if inst:IsA("StringValue") or inst:IsA("IntValue") or inst:IsA("NumberValue") then
                            raw = inst.Value
                        else
                            raw = inst:GetAttribute("Image") or inst:GetAttribute("Icon") or inst:GetAttribute("AssetId")
                        end
                        local formatted = _formatAssetId(raw)
                        if formatted then return formatted end
                    end
                end
            end
        end
    end
    return nil
end

function M.getPetBasePrice(petName)
    petName = tostring(petName or "")
    if petName == "" then return 0 end
    for _, item in ipairs(M.buildPetItems()) do
        if item.key == petName or item.name == petName then
            local raw = item.raw
            if type(raw) == "table" then
                return _petModulePrice(raw)
            end
        end
    end
    return 0
end

return M
 end,                    required = false },
    { key = "FriendStealList",         name = "FriendStealList",         factory = function() -- FriendStealList.lua — search Roblox users + store skip-steal friends (UI only for now)

local Players = game:GetService("Players")
local HttpService = game:GetService("HttpService")

local G = (getgenv and getgenv()) or _G
local M = G.FriendStealList or {}
G.FriendStealList = M

local nameCache = {}
local lastResolveDetail = nil -- { username, attempts={...}, source=, userId= }

local function trim(s)
    return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

local function norm(s)
    return trim(s):lower()
end

function M.remember(userId, username)
    userId = tonumber(userId)
    if not userId or userId <= 0 then return end
    username = trim(username)
    if username ~= "" then
        nameCache[tostring(userId)] = username
    end
end

function M.getUsername(userId)
    userId = tonumber(userId)
    if not userId then return nil end
    local key = tostring(userId)
    if nameCache[key] then return nameCache[key] end
    local plr = Players:GetPlayerByUserId(userId)
    if plr then
        nameCache[key] = plr.Name
        return plr.Name
    end
    return nil
end

function M.normalizeList(raw)
    local out = {}
    local seen = {}
    if type(raw) ~= "table" then return out end

    local function add(uid, name)
        uid = tonumber(uid)
        if not uid or uid <= 0 or seen[uid] then return end
        seen[uid] = true
        name = trim(name)
        if name == "" then name = M.getUsername(uid) or ("UserId:" .. tostring(uid)) end
        M.remember(uid, name)
        out[#out + 1] = { userId = uid, username = name }
    end

    if raw[1] ~= nil then
        for _, row in ipairs(raw) do
            if type(row) == "table" then
                add(row.userId or row.id, row.username or row.name)
            elseif type(row) == "number" or type(row) == "string" then
                add(row, nil)
            end
        end
        return out
    end

    for k, v in pairs(raw) do
        if v == true or type(v) == "table" then
            if type(v) == "table" then
                add(v.userId or v.id or k, v.username or v.name)
            else
                add(k, nil)
            end
        end
    end
    return out
end

function M.toSelectedMap(list)
    local map = {}
    for _, row in ipairs(M.normalizeList(list)) do
        map[tostring(row.userId)] = true
    end
    return map
end

function M.fromSelectedMap(map, list)
    local out = {}
    local merged = {}
    for _, row in ipairs(M.normalizeList(list)) do
        merged[tostring(row.userId)] = row
    end
    if type(map) == "table" then
        for k, on in pairs(map) do
            if on then
                local key = tostring(k)
                local row = merged[key]
                if row then
                    out[#out + 1] = row
                else
                    local uid = tonumber(k)
                    if uid and uid > 0 then
                        local name = M.getUsername(uid) or ("UserId:" .. key)
                        out[#out + 1] = { userId = uid, username = name }
                    end
                end
            end
        end
    end
    table.sort(out, function(a, b)
        return norm(a.username) < norm(b.username)
    end)
    return out
end

function M.displayLabel(userId, list)
    userId = tonumber(userId)
    if not userId then return "" end
    if type(list) == "table" then
        for _, row in ipairs(M.normalizeList(list)) do
            if row.userId == userId and row.username and row.username ~= "" then
                return row.username .. " (" .. tostring(userId) .. ")"
            end
        end
    end
    local name = M.getUsername(userId)
    if name and name ~= "" then
        return name .. " (" .. tostring(userId) .. ")"
    end
    return "UserId:" .. tostring(userId)
end

function M.toDropdownItems(list)
    local items = {}
    for _, row in ipairs(M.normalizeList(list)) do
        items[#items + 1] = {
            key = tostring(row.userId),
            name = row.username .. " (" .. tostring(row.userId) .. ")",
        }
    end
    return items
end

-- Remote resolve cache / anti-spam
local resolveCache = {} -- [norm] = { id=, name=, err=, t= }
local resolvePending = {} -- [norm] = true
local lastResolveAt = 0
local RESOLVE_NEG_TTL = 12 -- jangan cache "not_found" terlalu lama (Redfinger lag sering false-negative)
local RESOLVE_MIN_GAP = 0.45
local lastSearchMessage = nil

local function sanitizeQuery(raw)
    local s = tostring(raw or "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    s = s:gsub("^@", "")
    -- common paste junk: BOM / zero-width / NBSP
    s = s:gsub("\239\187\191", "")
    s = s:gsub("\226\128[\139\140\141]", "")
    s = s:gsub("\194\160", " ")
    s = s:gsub("%c", "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")

    local urlId = s:match("roblox%.com/users/(%d+)")
    if urlId then return urlId end

    -- "Name Name" paste of username with accidental whitespace → compact if valid
    if s:find("%s") and not s:find("://", 1, true) then
        local compact = s:gsub("%s+", "")
        if compact:match("^[%w_]+$") then
            s = compact
        end
    end
    return s
end

function M.getLastSearchMessage()
    return lastSearchMessage
end

function M.clearLastSearchMessage()
    lastSearchMessage = nil
end

function M.clearResolveError(username)
    username = sanitizeQuery(username)
    if username == "" then return end
    local key = norm(username)
    local hit = resolveCache[key]
    if hit and hit.err and not hit.id then
        resolveCache[key] = nil
    end
end

function M.getLastResolveDetail()
    return lastResolveDetail
end

local function _shortErr(err)
    err = tostring(err or "error")
    err = err:gsub("%s+", " ")
    if #err > 80 then
        err = err:sub(1, 77) .. "..."
    end
    return err
end

local function _httpRequest(opts)
    opts = type(opts) == "table" and opts or {}
    local url = tostring(opts.Url or opts.url or "")
    if url == "" then return false, "no_url" end
    local method = tostring(opts.Method or opts.method or "GET"):upper()
    local headers = type(opts.Headers) == "table" and opts.Headers or {}
    local body = opts.Body or opts.body

    local genv = (getgenv and getgenv()) or _G
    local req = (syn and syn.request)
        or (http and http.request)
        or http_request
        or (fluxus and fluxus.request)
        or (genv and genv.request)
        or request
    if type(req) == "function" then
        local ok, res = pcall(req, {
            Url = url,
            Method = method,
            Headers = headers,
            Body = body,
        })
        if not ok then
            return false, _shortErr(res)
        end
        if type(res) ~= "table" then
            return false, "bad_response"
        end
        local code = tonumber(res.StatusCode or res.status_code or res.Status or 0) or 0
        local rbody = res.Body or res.body or res.Data or ""
        return true, {
            StatusCode = code,
            Body = tostring(rbody or ""),
        }
    end

    if method == "GET" and typeof(game.HttpGet) == "function" then
        local ok, rbody = pcall(function()
            return game:HttpGet(url)
        end)
        if not ok then
            return false, _shortErr(rbody)
        end
        return true, { StatusCode = 200, Body = tostring(rbody or "") }
    end
    return false, "no_http"
end

-- Multi-source resolve. return: userId, nameOrErr, detail
-- Sources: cache → Players:GetUserIdFromNameAsync → users.roblox.com HTTP
function M.resolveUsernameDetailed(username, force)
    username = sanitizeQuery(username)
    local detail = {
        username = username,
        attempts = {},
        source = nil,
        userId = 0,
        ok = false,
    }
    lastResolveDetail = detail

    local function addAttempt(api, ok, info)
        detail.attempts[#detail.attempts + 1] = {
            api = api,
            ok = ok == true,
            info = _shortErr(info),
        }
    end

    if username == "" then
        addAttempt("input", false, "empty")
        return nil, "empty", detail
    end

    -- Paste UserId langsung
    local asId = tonumber(username)
    if asId and asId > 0 and not tostring(username):find("%a") then
        local name = M.getUsername(asId) or ("UserId:" .. tostring(asId))
        M.remember(asId, name)
        addAttempt("UserIdPaste", true, tostring(asId))
        detail.ok = true
        detail.userId = asId
        detail.source = "UserIdPaste"
        resolveCache[norm(tostring(asId))] = { id = asId, name = name, t = os.clock() }
        return asId, name, detail
    end

    if username:find("%s") or not username:match("^[%w_]+$") then
        addAttempt("input", false, "invalid_format")
        return nil, "invalid", detail
    end
    if #username < 3 or #username > 20 then
        addAttempt("input", false, "invalid_length")
        return nil, "invalid", detail
    end

    local key = norm(username)
    if force == true then
        M.clearResolveError(username)
    end

    local hit = resolveCache[key]
    if hit and hit.id then
        addAttempt("cache", true, tostring(hit.id))
        detail.ok = true
        detail.userId = hit.id
        detail.source = "cache"
        return hit.id, hit.name or username, detail
    end
    if hit and hit.err and force ~= true and (os.clock() - (hit.t or 0)) < RESOLVE_NEG_TTL then
        addAttempt("cache", false, hit.err .. " (cached)")
        return nil, hit.err, detail
    end

    local spin = 0
    while resolvePending[key] and spin < 100 do
        task.wait(0.05)
        spin += 1
        hit = resolveCache[key]
        if hit and hit.id then
            addAttempt("cache_wait", true, tostring(hit.id))
            detail.ok = true
            detail.userId = hit.id
            detail.source = "cache_wait"
            return hit.id, hit.name or username, detail
        end
    end

    local now = os.clock()
    if force ~= true and (now - lastResolveAt) < RESOLVE_MIN_GAP then
        addAttempt("throttle", false, "rate_limited")
        return nil, "rate_limited", detail
    end

    resolvePending[key] = true
    lastResolveAt = os.clock()

    -- 1) Roblox engine API
    local okAsync, userIdOrErr = pcall(function()
        return Players:GetUserIdFromNameAsync(username)
    end)
    if okAsync and type(userIdOrErr) == "number" and userIdOrErr > 0 then
        M.remember(userIdOrErr, username)
        resolveCache[key] = { id = userIdOrErr, name = username, t = os.clock() }
        resolvePending[key] = nil
        addAttempt("GetUserIdFromNameAsync", true, tostring(userIdOrErr))
        detail.ok = true
        detail.userId = userIdOrErr
        detail.source = "GetUserIdFromNameAsync"
        return userIdOrErr, username, detail
    end
    local asyncErr = okAsync and "not_found" or _shortErr(userIdOrErr)
    addAttempt("GetUserIdFromNameAsync", false, asyncErr)

    -- 2) Official HTTP: users.roblox.com/v1/usernames/users
    local body = HttpService:JSONEncode({
        usernames = { username },
        excludeBannedUsers = false,
    })
    local okHttp, httpRes = _httpRequest({
        Url = "https://users.roblox.com/v1/usernames/users",
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json",
            ["Accept"] = "application/json",
        },
        Body = body,
    })
    if not okHttp then
        addAttempt("HttpUsersApi", false, httpRes)
    else
        local code = tonumber(httpRes.StatusCode) or 0
        local raw = tostring(httpRes.Body or "")
        if code < 200 or code >= 300 then
            addAttempt("HttpUsersApi", false, "HTTP " .. tostring(code) .. " " .. _shortErr(raw))
        else
            local okJson, parsed = pcall(function()
                return HttpService:JSONDecode(raw)
            end)
            if not okJson or type(parsed) ~= "table" then
                addAttempt("HttpUsersApi", false, "bad_json")
            else
                local row = nil
                local data = parsed.data
                if type(data) == "table" then
                    for _, r in ipairs(data) do
                        if type(r) == "table" then
                            local rn = norm(r.name or r.requestedUsername or "")
                            if rn == key or tonumber(r.id) then
                                row = r
                                if rn == key then break end
                            end
                        end
                    end
                    if not row and data[1] then row = data[1] end
                end
                local hid = row and tonumber(row.id) or 0
                if hid > 0 then
                    local hname = trim(row.name or username)
                    M.remember(hid, hname)
                    resolveCache[key] = { id = hid, name = hname, t = os.clock() }
                    resolvePending[key] = nil
                    addAttempt("HttpUsersApi", true, tostring(hid))
                    detail.ok = true
                    detail.userId = hid
                    detail.source = "HttpUsersApi"
                    return hid, hname, detail
                end
                addAttempt("HttpUsersApi", false, "empty_data")
            end
        end
    end

    -- 3) Online players exact (last resort, display/name)
    for _, plr in ipairs(Players:GetPlayers()) do
        if norm(plr.Name) == key then
            M.remember(plr.UserId, plr.Name)
            resolveCache[key] = { id = plr.UserId, name = plr.Name, t = os.clock() }
            resolvePending[key] = nil
            addAttempt("OnlinePlayers", true, tostring(plr.UserId))
            detail.ok = true
            detail.userId = plr.UserId
            detail.source = "OnlinePlayers"
            return plr.UserId, plr.Name, detail
        end
    end
    addAttempt("OnlinePlayers", false, "not_in_server")

    resolvePending[key] = nil

    -- Soft vs hard:
    -- - HTTP empty_data = akun benar-benar tidak ada → not_found (hard)
    -- - HTTP/infra gagal (no_http, timeout, HTTP 4xx/5xx, bad_json) → soft (JANGAN anggap wrong username)
    -- - GetUserIdFromNameAsync "not_found" saja di Redfinger sering false-negative → soft jika HTTP tidak confirm
    local softErr = nil
    local httpConfirmedEmpty = false
    local asyncSaidNotFound = false
    for _, a in ipairs(detail.attempts) do
        if type(a) ~= "table" or a.ok == true then
            -- skip
        elseif a.api == "GetUserIdFromNameAsync" then
            if a.info == "not_found" then
                asyncSaidNotFound = true
            else
                softErr = softErr or tostring(a.info or "async_error")
            end
        elseif a.api == "HttpUsersApi" then
            if a.info == "empty_data" then
                httpConfirmedEmpty = true
            else
                softErr = softErr or tostring(a.info or "http_error")
            end
        end
    end

    local err
    if httpConfirmedEmpty then
        err = "not_found"
    elseif softErr then
        -- prefer explicit no_http / http so verify-loop soft matcher catches it
        local s = tostring(softErr)
        if s == "no_http" or s:find("http", 1, true) or s:find("HTTP", 1, true)
            or s:find("timeout", 1, true) or s:find("rate", 1, true)
            or s:find("throttle", 1, true) or s:find("busy", 1, true) then
            err = s
        else
            err = "http_error:" .. s
        end
    elseif asyncSaidNotFound then
        -- Async-only not_found tanpa konfirmasi HTTP → treat soft (Redfinger false-negative)
        err = "async_not_found_unconfirmed"
    else
        err = "not_found"
    end

    -- Cache hard not_found singkat; soft errors juga di-cache singkat supaya tidak spam,
    -- tapi verify loop harus treat sebagai soft (bukan wrong username).
    resolveCache[key] = { err = err, t = os.clock() }
    return nil, err, detail
end

-- force=true: abaikan cache "not_found" (pakai saat Send / resolve ulang)
function M.resolveUsername(username, force)
    local id, nameOrErr = M.resolveUsernameDetailed(username, force)
    return id, nameOrErr
end

function M.formatResolveAttempts(detail)
    detail = type(detail) == "table" and detail or lastResolveDetail
    if type(detail) ~= "table" or type(detail.attempts) ~= "table" then
        return ""
    end
    local parts = {}
    for _, a in ipairs(detail.attempts) do
        local mark = a.ok and "OK" or "FAIL"
        parts[#parts + 1] = string.format("%s=%s(%s)", tostring(a.api), mark, tostring(a.info or ""))
    end
    return table.concat(parts, " | ")
end

-- Score username vs query: exact > prefix > substring (min 3 chars).
local function scoreUsernameMatch(username, q, qLen)
    local n = norm(username)
    if n == "" or qLen < 1 then return 0 end
    if n == q then return 100 end
    if n:sub(1, qLen) == q then return 80 end
    if qLen >= 3 and n:find(q, 1, true) then return 40 end
    return 0
end

function M.searchUsers(query, limit)
    limit = math.floor(tonumber(limit) or 10)
    if limit < 1 then limit = 10 end

    lastSearchMessage = nil
    query = sanitizeQuery(query)
    if query == "" then
        return {}
    end

    local q = norm(query)
    local qLen = #q
    local candidates = {}
    local seen = {}

    local function addCandidate(userId, username, score)
        userId = tonumber(userId)
        if not userId or userId <= 0 or score <= 0 then return end
        local skey = tostring(userId)
        if seen[skey] then
            for _, c in ipairs(candidates) do
                if c.userId == userId then
                    if score > c.score then
                        c.score = score
                        local u = trim(username)
                        if u ~= "" then c.username = u end
                    end
                    return
                end
            end
            return
        end
        seen[skey] = true
        username = trim(username)
        if username == "" then username = M.getUsername(userId) or ("UserId:" .. skey) end
        M.remember(userId, username)
        candidates[#candidates + 1] = { userId = userId, username = username, score = score }
    end

    -- Local / online match (username + display name) — no network
    for _, plr in ipairs(Players:GetPlayers()) do
        local sName = scoreUsernameMatch(plr.Name, q, qLen)
        local sDisp = scoreUsernameMatch(plr.DisplayName, q, qLen)
        local s = math.max(sName, sDisp)
        if s > 0 then
            addCandidate(plr.UserId, plr.Name, s + 5)
        end
    end

    local remoteErr = nil
    local didRemote = false
    local hasStrongLocal = false
    for _, c in ipairs(candidates) do
        if c.score >= 85 then
            hasStrongLocal = true
            break
        end
    end

    -- Remote resolve only when needed (exact username / userId / profile URL)
    if qLen >= 3 and not query:find("%s") then
        local uid = tonumber(query)
        if uid and uid > 0 then
            didRemote = true
            addCandidate(uid, M.getUsername(uid), 100)
        elseif not hasStrongLocal and query:match("^[%w_]+$") then
            didRemote = true
            local resolvedId, resolvedNameOrErr = M.resolveUsernameDetailed(query, true)
            if resolvedId then
                addCandidate(resolvedId, resolvedNameOrErr, 100)
            else
                remoteErr = resolvedNameOrErr
            end
        end
    end

    table.sort(candidates, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return norm(a.username) < norm(b.username)
    end)

    local out = {}
    for i = 1, math.min(limit, #candidates) do
        local c = candidates[i]
        out[#out + 1] = {
            key = tostring(c.userId),
            name = c.username .. " (" .. tostring(c.userId) .. ")",
        }
    end

    -- Fallback selectable username saat lookup gagal/lag (Redfinger dll).
    -- Key "name:User" → UI bisa select; resolve ulang saat kirim.
    local canFallback = (#out == 0)
        and qLen >= 3
        and not tonumber(query)
        and query:match("^[%w_]+$")
        and not query:find("%s")

    if #out == 0 then
        if qLen < 3 then
            lastSearchMessage = "Min. 3 karakter — pakai exact username (bukan display name)."
        elseif query:find("%s") or not query:match("^[%w_]+$") then
            if not tonumber(query) then
                lastSearchMessage = "Format salah. Paste username saja / UserId / link profil Roblox."
            end
        elseif canFallback then
            -- Tetap tampilkan username fallback (dicek lagi saat kirim); tanpa banner API/lag.
            out[#out + 1] = {
                key = "name:" .. query,
                name = query .. " ⚠ belum terverifikasi",
            }
            lastSearchMessage = nil
        else
            lastSearchMessage = "Username tidak ditemukan. Pakai exact Roblox username, bukan display name."
        end
    else
        lastSearchMessage = nil
    end

    out._searchMessage = lastSearchMessage
    return out
end

-- Parse dropdown key: numeric userId OR "name:Username" fallback.
function M.parseTargetKey(key)
    key = tostring(key or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if key == "" then return nil, nil end
    local uid = tonumber(key)
    if uid and uid > 0 then
        return math.floor(uid), nil
    end
    local name = key:match("^[Nn]ame:(.+)$") or key:match("^@(.+)$")
    if not name then
        if key:match("^[%w_]+$") then
            name = key
        end
    end
    if name then
        name = sanitizeQuery(name)
        if name ~= "" and name:match("^[%w_]+$") then
            return 0, name
        end
    end
    return nil, nil
end

function M.isSkipOwner(ownerUserId, list)
    ownerUserId = tonumber(ownerUserId)
    if not ownerUserId or ownerUserId <= 0 then return false end
    for _, row in ipairs(M.normalizeList(list)) do
        if row.userId == ownerUserId then return true end
    end
    return false
end

return M
 end,                required = false },
    { key = "AutoBuy",                 name = "Auto Buy",                factory = function() -- AutoBuy.lua — Grow A Garden 2
-- Auto buy Seed / Gear / Props dari shop in-game.
-- Selected kosong PER WORLD aktif = buy all world itu
-- (contoh: Main ada Briar Rose, Ghoul Garden kosong → di Ghoul beli semua stock).

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players           = game:GetService("Players")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local SharedModules = ReplicatedStorage:WaitForChild("SharedModules")
local Networking    = require(SharedModules.Networking)

-- GAG2 packets (SharedModules.Networking):
--   SeedShop.PurchaseSeed(seedName)
--   GearShop.PurchaseGear(gearName)
--   CrateShop.PurchaseCrate(crateName)
local EXACT_REMOTES = {
    seed  = { net = Networking.SeedShop,  key = "PurchaseSeed",  path = "Networking.SeedShop.PurchaseSeed" },
    gear  = { net = Networking.GearShop,  key = "PurchaseGear",  path = "Networking.GearShop.PurchaseGear" },
    props = { net = Networking.CrateShop, key = "PurchaseCrate", path = "Networking.CrateShop.PurchaseCrate" },
}

local function _isFirePacket(obj)
    return type(obj) == "table" and type(obj.Fire) == "function"
end

local REMOTE_PATHS = {}
local REMOTES = {}

local function _ensureRemote(catKey)
    if REMOTES[catKey] then return REMOTES[catKey], REMOTE_PATHS[catKey] end

    local exact = EXACT_REMOTES[catKey]
    local pkt = exact and type(exact.net) == "table" and exact.net[exact.key]
    if _isFirePacket(pkt) then
        REMOTES[catKey] = pkt
        REMOTE_PATHS[catKey] = exact.path
        return pkt, exact.path
    end

    REMOTES[catKey] = nil
    REMOTE_PATHS[catKey] = nil
    return nil, nil
end

for _, cat in ipairs({ "seed", "gear", "props" }) do
    _ensureRemote(cat)
end

local StockValues = ReplicatedStorage:FindFirstChild("StockValues")

-- Live stock: ReplicatedStorage.StockValues.<Shop>.Items.<ItemName> (NumberValue)
local STOCK_VALUES_SHOPS = {
    seed  = { "SeedShop" },
    gear  = { "GearShop" },
    props = { "PropShop", "PropsShop", "CrateShop" },
}

local AFTER_BUY_SEC     = 0.45
local STOCK_POLL_SEC    = 2.0   -- ada stock, siap beli
local NO_MONEY_POLL_SEC = 8.0   -- pause per item kalau uang kurang (terkonfirmasi)
local NO_STOCK_POLL_SEC = 30    -- tidak ada stock → scan jarang (override: _G.AUTO_BUY_NO_STOCK_POLL)
-- Per stock: fire 2x, jeda antar burst biar tidak spam remote.
local PARALLEL_BUY_FIRES = 2
local BUY_DEBOUNCE_SEC   = 0.45

local _stockFolderCache = {}
local _stockNodeCache = {}
local _watchConns = {}
local _watchSig = ""
local _buyDebounce = {}
local _priceCache = {}
local _brokeItems = {} -- key -> pause until (os.clock)
local _moneyConns = {}
local _lastMoney = nil

local running = false
local loopId  = 0

----------------------------------------------------------------
local function _dbg()
    return G.AUTO_BUY_DEBUG == true or _G.AUTO_BUY_DEBUG == true
end

local function _log(...)
    if not _dbg() then return end
    print("[GAG2-AB]", ...)
end

if not REMOTES.seed then
    warn("[GAG2-AB] Buy seed remote belum ketemu — jalankan _G.AutoBuy:GetDiagnostics() di console")
elseif _dbg() then
    _log("seed remote =", REMOTE_PATHS.seed)
end

local function _normalizeSet(src)
    if type(src) ~= "table" then return {} end
    local out = {}
    for i = 1, #src do
        local v = src[i]
        if v ~= nil and tostring(v) ~= "" then
            out[tostring(v)] = true
        end
    end
    if next(out) then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function _setToArray(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true then out[#out + 1] = tostring(k) end
    end
    table.sort(out)
    return out
end

local function _hasAnySelected(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true then return true end
    end
    return false
end

-- PlaceId fallback kalau Worlds module belum ready.
local GHOUL_PLACE_IDS = {
    [102868797705537] = true,
    [136420110879676] = true,
}

local function _normWorldId(id)
    if type(id) ~= "string" or id == "" then return nil end
    local low = string.lower(id)
    if low == "ghoulgarden" or low:find("ghoul", 1, true) then return "GhoulGarden" end
    if low == "main" then return "Main" end
    return id
end

local function _getCurrentBuyWorld()
    local afh = G.AutoFallHarvest or G.AutoFallHarvestModule or rawget(_G, "AutoFallHarvest")
    if type(afh) == "table" then
        if type(afh.IsInGhoulGarden) == "function" then
            local ok, inGhoul = pcall(afh.IsInGhoulGarden, afh)
            if ok and inGhoul == true then return "GhoulGarden" end
        end
        if type(afh.IsInMainGarden) == "function" then
            local ok, inMain = pcall(afh.IsInMainGarden, afh)
            if ok and inMain == true then return "Main" end
        end
        if type(afh.GetCurrentWorldId) == "function" then
            local ok, id = pcall(afh.GetCurrentWorldId, afh)
            if ok then
                local w = _normWorldId(id)
                if w then return w end
            end
        end
    end

    if GHOUL_PLACE_IDS[game.PlaceId] == true then
        return "GhoulGarden"
    end

    local worldsInst = SharedModules:FindFirstChild("Worlds")
    if worldsInst and worldsInst:IsA("ModuleScript") then
        local okW, Worlds = pcall(require, worldsInst)
        if okW and type(Worlds) == "table" then
            local id = Worlds.CurrentId or Worlds.CurrentWorld
            if type(Worlds.GetCurrentId) == "function" then
                local okId, v = pcall(Worlds.GetCurrentId, Worlds)
                if okId then id = v end
            end
            local w = _normWorldId(id)
            if w then return w end
        end
    end

    if LP then
        for _, a in ipairs({ "CurrentWorld", "WorldId", "World", "ActiveWorld" }) do
            local v = LP:GetAttribute(a)
            local w = _normWorldId(v)
            if w then return w end
        end
    end

    return "Main"
end

-- Selected per world aktif. Kosong di world itu = buy all (ignore selected world lain).
local function _selectedForActiveWorld(catKey, selected)
    if type(selected) ~= "table" then return {} end
    local world = _getCurrentBuyWorld()

    if catKey == "seed" then
        local PL = G.PlantListView or rawget(_G, "PlantListView")
        if type(PL) == "table" and type(PL.filterSelectedForWorld) == "function" then
            local ok, filtered = pcall(PL.filterSelectedForWorld, selected, world)
            if ok and type(filtered) == "table" then return filtered end
        end
    elseif catKey == "gear" then
        local SL = G.ShopListView or rawget(_G, "ShopListView")
        if type(SL) == "table" and type(SL.filterGearSelectedForWorld) == "function" then
            local ok, filtered = pcall(SL.filterGearSelectedForWorld, selected, world)
            if ok and type(filtered) == "table" then return filtered end
        end
    elseif catKey == "props" then
        local SL = G.ShopListView or rawget(_G, "ShopListView")
        if type(SL) == "table" and type(SL.filterPropsSelectedForWorld) == "function" then
            local ok, filtered = pcall(SL.filterPropsSelectedForWorld, selected, world)
            if ok and type(filtered) == "table" then return filtered end
        end
    end

    return selected
end

local function _writeMainBuy(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.buy = MAIN.auto.buy or {}
    for k, v in pairs(patch) do
        MAIN.auto.buy[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function getBuyState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local buy = MAIN and MAIN.auto and MAIN.auto.buy
    buy = type(buy) == "table" and buy or {}

    local seedOn = (G.AUTO_BUY_SEED_ENABLED == true)
        or (rawget(_G, "AUTO_BUY_SEED_ENABLED") == true)
        or (type(buy.seed) == "table" and buy.seed.enabled == true)

    local gearOn = (G.AUTO_BUY_GEAR_ENABLED == true)
        or (rawget(_G, "AUTO_BUY_GEAR_ENABLED") == true)
        or (type(buy.gear) == "table" and buy.gear.enabled == true)

    local propsOn = (G.AUTO_BUY_PROPS_ENABLED == true)
        or (rawget(_G, "AUTO_BUY_PROPS_ENABLED") == true)
        or (type(buy.props) == "table" and buy.props.enabled == true)

    return {
        seedEnabled  = seedOn,
        gearEnabled  = gearOn,
        propsEnabled = propsOn,
        seedSelected  = _normalizeSet(G.BUY_SEED_SELECTED or rawget(_G, "BUY_SEED_SELECTED") or (buy.seed and buy.seed.items)),
        gearSelected  = _normalizeSet(G.BUY_GEAR_SELECTED or rawget(_G, "BUY_GEAR_SELECTED") or (buy.gear and buy.gear.items)),
        propsSelected = _normalizeSet(G.BUY_PROPS_SELECTED or rawget(_G, "BUY_PROPS_SELECTED") or (buy.props and buy.props.items)),
    }
end

local function _readStockValue(inst)
    if not inst then return 0 end
    if inst:IsA("NumberValue") or inst:IsA("IntValue") then
        return math.max(0, math.floor(tonumber(inst.Value) or 0))
    end
    if inst:IsA("ValueBase") then
        return math.max(0, math.floor(tonumber(inst.Value) or 0))
    end
    if type(inst) == "number" then
        return math.max(0, math.floor(inst))
    end
    if type(inst) == "table" then
        return math.max(0, math.floor(tonumber(inst.Stock or inst.stock or inst.Value or inst.Amount or inst.Count) or 0))
    end
    return 0
end

local function _getStockValuesItemsFolder(catKey)
    local cached = _stockFolderCache[catKey]
    if cached and cached.Parent then return cached end

    if not StockValues then
        StockValues = ReplicatedStorage:FindFirstChild("StockValues")
    end
    if not StockValues then return nil end

    for _, shopName in ipairs(STOCK_VALUES_SHOPS[catKey] or {}) do
        local shop = StockValues:FindFirstChild(shopName)
        local items = shop and shop:FindFirstChild("Items")
        if items then
            _stockFolderCache[catKey] = items
            return items
        end
    end
    return nil
end

local function _getStockNode(catKey, itemName)
    local key = catKey .. "\0" .. itemName
    local node = _stockNodeCache[key]
    if node and node.Parent then return node end

    local folder = _getStockValuesItemsFolder(catKey)
    if not folder then return nil end

    node = folder:FindFirstChild(itemName)
    _stockNodeCache[key] = node
    return node
end

local function _readStockNode(node)
    if not node then return 0 end
    return _readStockValue(node)
end

local function _getLiveStockCount(catKey, itemName)
    local node = _getStockNode(catKey, itemName)
    if node then return _readStockNode(node) end

    local folder = _getStockValuesItemsFolder(catKey)
    if not folder then return nil end
    return 0
end

local function _collectLiveStocks(catKey)
    local folder = _getStockValuesItemsFolder(catKey)
    local out = {}
    if not folder then return out, false end

    for _, child in ipairs(folder:GetChildren()) do
        local count = _readStockValue(child)
        if count > 0 then
            out[child.Name] = count
        end
    end
    return out, true
end

local function _parseMoneyValue(raw)
    if raw == nil then return nil end
    if type(raw) == "number" then return raw end
    local s = tostring(raw):gsub(",", ""):gsub("%s+", "")
    if s == "" then return nil end
    local n = tonumber(s)
    if n then return n end
    local num, suf = s:match("^([%d%.]+)%s*([KMBkmb])?$")
    n = tonumber(num)
    if not n then return nil end
    suf = suf and suf:upper() or ""
    if suf == "K" then return n * 1000 end
    if suf == "M" then return n * 1000000 end
    if suf == "B" then return n * 1000000000 end
    return n
end

-- World: Main=Sheckles, Ghoul=Candy Corn
local MONEY_STAT_NAMES = { "Candy Corn", "Sheckles", "Money", "Cash", "Coins" }

local function _walletStatName()
    local worldsInst = SharedModules:FindFirstChild("Worlds")
    if worldsInst and worldsInst:IsA("ModuleScript") then
        local okW, Worlds = pcall(require, worldsInst)
        if okW and type(Worlds) == "table" then
            if type(Worlds.WalletStatName) == "function" then
                local okN, name = pcall(Worlds.WalletStatName, LP)
                if okN and type(name) == "string" and name ~= "" then return name end
            end
            if type(Worlds.Current) == "table" and type(Worlds.Current.CurrencyName) == "string" then
                return Worlds.Current.CurrencyName
            end
        end
    end
    return nil
end

local function _getMoney()
    local ls = LP:FindFirstChild("leaderstats")
    local prefer = _walletStatName()
    if ls and type(prefer) == "string" then
        local o = ls:FindFirstChild(prefer)
        if o and (o:IsA("IntValue") or o:IsA("NumberValue")) then
            local v = _parseMoneyValue(o.Value)
            if v ~= nil then return v end
        end
    end
    -- leaderstats = angka penuh. Attribute kadang format pendek → salah hitung.
    if ls then
        for _, n in ipairs(MONEY_STAT_NAMES) do
            local o = ls:FindFirstChild(n)
            if o and (o:IsA("IntValue") or o:IsA("NumberValue")) then
                local v = _parseMoneyValue(o.Value)
                if v ~= nil then return v end
            end
        end
    end

    if type(prefer) == "string" then
        local attr = LP:GetAttribute(prefer)
        if attr ~= nil then
            local v = _parseMoneyValue(attr)
            if v ~= nil then return v end
        end
    end
    for _, n in ipairs({ "Candy Corn", "Sheckles" }) do
        local attr = LP:GetAttribute(n)
        if attr ~= nil then
            local v = _parseMoneyValue(attr)
            if v ~= nil then return v end
        end
    end

    return nil
end

local function _mergePriceEntry(prices, entry, keyHint)
    if type(entry) ~= "table" then return end
    local itemName = entry.CrateName or entry.ItemName or entry.GearName
        or entry.PropName or entry.SeedName or entry.Name or keyHint
    if not itemName or tostring(itemName) == "" then return end
    local price = tonumber(entry.Cost or entry.PurchasePrice or entry.Price or entry.FallbackPrice)
    if price and price > 0 then
        prices[tostring(itemName)] = price
    end
end

local function _ensurePrices(catKey)
    if _priceCache[catKey] then return _priceCache[catKey] end

    local prices = {}

    if catKey == "seed" then
        local ok, seedData = pcall(require, SharedModules:WaitForChild("SeedData"))
        if ok and type(seedData) == "table" then
            if #seedData > 0 then
                for _, entry in ipairs(seedData) do
                    _mergePriceEntry(prices, entry)
                end
            else
                for key, entry in pairs(seedData) do
                    _mergePriceEntry(prices, entry, key)
                end
            end
        end
    elseif catKey == "gear" then
        for _, modName in ipairs({ "GearShopData", "GearData", "Gears" }) do
            local inst = SharedModules:FindFirstChild(modName)
            if inst and inst:IsA("ModuleScript") then
                local ok, data = pcall(require, inst)
                if ok and type(data) == "table" then
                    local catalog = data.Data or data.Gear or data.Items or data
                    if type(catalog) == "table" then
                        if #catalog > 0 then
                            for _, entry in ipairs(catalog) do
                                _mergePriceEntry(prices, entry)
                            end
                        else
                            for key, entry in pairs(catalog) do
                                _mergePriceEntry(prices, entry, key)
                            end
                        end
                    end
                end
                break
            end
        end
    elseif catKey == "props" then
        local crateRoot = SharedModules:FindFirstChild("CrateData")
        if crateRoot and crateRoot:IsA("ModuleScript") then
            local ok, crateApi = pcall(require, crateRoot)
            if ok and type(crateApi) == "table" then
                if type(crateApi.GetAllCrates) == "function" then
                    local ok2, all = pcall(function()
                        return crateApi.GetAllCrates()
                    end)
                    if ok2 and type(all) == "table" then
                        for key, entry in pairs(all) do
                            if type(entry) == "table" then
                                _mergePriceEntry(prices, entry, key)
                            end
                        end
                    end
                end
                for _, child in ipairs(crateRoot:GetChildren()) do
                    if child:IsA("ModuleScript") then
                        local ok3, entry = pcall(require, child)
                        if ok3 and type(entry) == "table" then
                            _mergePriceEntry(prices, entry, child.Name)
                        end
                    end
                end
            end
        end
    end

    _priceCache[catKey] = prices
    return prices
end

local function _getItemPrice(catKey, itemName)
    itemName = tostring(itemName or "")
    if itemName == "" then return nil end
    local prices = _ensurePrices(catKey)
    local price = tonumber(prices[itemName])
    if price and price > 0 then return price end

    local canon = itemName:lower():gsub("[^%w]+", "")
    for name, p in pairs(prices) do
        if tostring(name):lower():gsub("[^%w]+", "") == canon then
            p = tonumber(p)
            if p and p > 0 then return p end
        end
    end
    return nil
end

local function _itemKey(catKey, name)
    return tostring(catKey) .. "\0" .. tostring(name)
end

local function _clearBroke()
    table.clear(_brokeItems)
end

local function _noMoneyPollSec()
    local n = tonumber(G.AUTO_BUY_NO_MONEY_POLL or _G.AUTO_BUY_NO_MONEY_POLL) or NO_MONEY_POLL_SEC
    if n < 3 then n = 3 end
    if n > 120 then n = 120 end
    return n
end

local function _skipMoneyCheck()
    return G.AUTO_BUY_SKIP_MONEY_CHECK == true or _G.AUTO_BUY_SKIP_MONEY_CHECK == true
end

local function _isConfirmedPoor(catKey, name)
    if _skipMoneyCheck() then return false end
    local money = _getMoney()
    local price = _getItemPrice(catKey, name)
    return money ~= nil and price ~= nil and price > 0 and money < price
end

local function _markBroke(catKey, name)
    _brokeItems[_itemKey(catKey, name)] = os.clock() + _noMoneyPollSec()
    _log("broke", catKey, name, "money=", _getMoney(), "price=", _getItemPrice(catKey, name))
end

local function _isBroke(catKey, name)
    local untilAt = _brokeItems[_itemKey(catKey, name)]
    return type(untilAt) == "number" and os.clock() < untilAt
end

local function _canAfford(catKey, itemName)
    return not _isConfirmedPoor(catKey, itemName)
end

local function _bindMoneyWatch()
    if #_moneyConns > 0 then return end

    local function onMoneyMaybeChanged()
        local money = _getMoney()
        if money == nil then return end
        if _lastMoney == nil or money > _lastMoney then
            _clearBroke()
        end
        _lastMoney = money
    end

    for _, n in ipairs({ "Candy Corn", "Sheckles" }) do
        table.insert(_moneyConns, LP:GetAttributeChangedSignal(n):Connect(onMoneyMaybeChanged))
    end

    local function hookLeaderstats(ls)
        if not ls then return end
        for _, n in ipairs(MONEY_STAT_NAMES) do
            local o = ls:FindFirstChild(n)
            if o and (o:IsA("IntValue") or o:IsA("NumberValue")) then
                table.insert(_moneyConns, o.Changed:Connect(onMoneyMaybeChanged))
            end
        end
        table.insert(_moneyConns, ls.ChildAdded:Connect(function(ch)
            if ch:IsA("IntValue") or ch:IsA("NumberValue") then
                for _, n in ipairs(MONEY_STAT_NAMES) do
                    if ch.Name == n then
                        table.insert(_moneyConns, ch.Changed:Connect(onMoneyMaybeChanged))
                        onMoneyMaybeChanged()
                        break
                    end
                end
            end
        end))
    end

    hookLeaderstats(LP:FindFirstChild("leaderstats"))
    table.insert(_moneyConns, LP.ChildAdded:Connect(function(ch)
        if ch.Name == "leaderstats" then
            hookLeaderstats(ch)
            onMoneyMaybeChanged()
        end
    end))

    _lastMoney = _getMoney()
end

local function _clearMoneyWatch()
    for _, conn in ipairs(_moneyConns) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(_moneyConns)
end

local function _fireBuy(remote, itemName)
    if not remote or type(remote.Fire) ~= "function" then return false end
    return pcall(function()
        remote:Fire(tostring(itemName))
    end)
end

local function _resolveStocks(catKey)
    local live, hasLive = _collectLiveStocks(catKey)
    if hasLive then return live end
    return {}
end

local function _noStockPollSec()
    local n = tonumber(G.AUTO_BUY_NO_STOCK_POLL or _G.AUTO_BUY_NO_STOCK_POLL) or NO_STOCK_POLL_SEC
    if n < 5 then n = 5 end
    if n > 300 then n = 300 end
    return n
end

local function _hasRelevantStock(st)
    local function catHasStock(catKey, enabled, selected)
        if not enabled then return false end
        -- Filter per world aktif: Main isi + Ghoul kosong → di Ghoul = buy all.
        local worldSelected = _selectedForActiveWorld(catKey, selected)
        local hasFilter = _hasAnySelected(worldSelected)
        if hasFilter then
            for name, on in pairs(worldSelected) do
                if on and (_getLiveStockCount(catKey, tostring(name)) or 0) > 0 then
                    return true
                end
            end
            return false
        end
        return next(_resolveStocks(catKey)) ~= nil
    end

    return catHasStock("seed", st.seedEnabled, st.seedSelected)
        or catHasStock("gear", st.gearEnabled, st.gearSelected)
        or catHasStock("props", st.propsEnabled, st.propsSelected)
end

local function _loopWaitSec(st, bought)
    if bought > 0 then
        return AFTER_BUY_SEC
    end
    if _hasRelevantStock(st) then
        return STOCK_POLL_SEC
    end
    return _noStockPollSec()
end

local function _readStockCount(catKey, name, node)
    if node and node.Parent then
        return _readStockNode(node)
    end
    return _getLiveStockCount(catKey, name) or 0
end

local function _buyItemBurst(catKey, name, remote)
    if not remote then return 0 end
    name = tostring(name)

    if _isBroke(catKey, name) then
        return 0
    end

    if _isConfirmedPoor(catKey, name) then
        _markBroke(catKey, name)
        return 0
    end

    local key = catKey .. "\0" .. name
    if _buyDebounce[key] then return 0 end
    _buyDebounce[key] = true
    task.delay(BUY_DEBOUNCE_SEC, function()
        _buyDebounce[key] = nil
    end)

    local node = _getStockNode(catKey, name)
    local count = _readStockCount(catKey, name, node)
    if count <= 0 then return 0 end

    local bought = 0
    for _ = 1, PARALLEL_BUY_FIRES do
        if not _fireBuy(remote, name) then break end
        bought += 1
    end

    if bought > 0 then
        _brokeItems[_itemKey(catKey, name)] = nil
        _log("buy", catKey, name, "x" .. tostring(bought), "stock~", count)
    end

    return bought
end

local function _watchSignature(st)
    local parts = {
        _getCurrentBuyWorld(),
        st.seedEnabled and "1" or "0",
        st.gearEnabled and "1" or "0",
        st.propsEnabled and "1" or "0",
        table.concat(_setToArray(_selectedForActiveWorld("seed", st.seedSelected)), ","),
        table.concat(_setToArray(_selectedForActiveWorld("gear", st.gearSelected)), ","),
        table.concat(_setToArray(_selectedForActiveWorld("props", st.propsSelected)), ","),
    }
    return table.concat(parts, "|")
end

local function _clearWatchers()
    for _, conn in ipairs(_watchConns) do
        pcall(function() conn:Disconnect() end)
    end
    table.clear(_watchConns)
    _watchSig = ""
end

local function _bindStockWatchers(st)
    local sig = _watchSignature(st)
    if sig == _watchSig then return end
    _clearWatchers()
    _watchSig = sig

    local function bindCat(catKey, enabled, selected)
        if not enabled then return end

        local remote = REMOTES[catKey] or select(1, _ensureRemote(catKey))
        if not remote then return end

        local folder = _getStockValuesItemsFolder(catKey)
        if not folder then return end

        local worldSelected = _selectedForActiveWorld(catKey, selected)
        local hasFilter = _hasAnySelected(worldSelected)

        local function hookNode(node)
            if not node then return end
            _watchConns[#_watchConns + 1] = node.Changed:Connect(function()
                if not running then return end
                if _readStockNode(node) <= 0 then return end
                if hasFilter and not worldSelected[node.Name] then return end
                if _isBroke(catKey, node.Name) then return end
                if _isConfirmedPoor(catKey, node.Name) then
                    _markBroke(catKey, node.Name)
                    return
                end
                task.defer(function()
                    if running then
                        _buyItemBurst(catKey, node.Name, remote)
                    end
                end)
            end)
        end

        if hasFilter then
            for name, on in pairs(worldSelected) do
                if on then hookNode(_getStockNode(catKey, tostring(name))) end
            end
        else
            for _, child in ipairs(folder:GetChildren()) do
                hookNode(child)
            end
            _watchConns[#_watchConns + 1] = folder.ChildAdded:Connect(function(child)
                hookNode(child)
            end)
        end
    end

    bindCat("seed", st.seedEnabled, st.seedSelected)
    bindCat("gear", st.gearEnabled, st.gearSelected)
    bindCat("props", st.propsEnabled, st.propsSelected)
end

local function _processCategory(catKey, enabled, selected, remote)
    if not enabled then return 0 end

    remote = remote or select(1, _ensureRemote(catKey))
    if not remote then
        _log("skip", catKey, "remote missing")
        return 0
    end

    -- Per world: Ghoul kosong = buy all, meski Main masih ada selected.
    local worldSelected = _selectedForActiveWorld(catKey, selected)
    local hasFilter = _hasAnySelected(worldSelected)
    local bought = 0

    if hasFilter then
        for name, on in pairs(worldSelected) do
            if on then
                bought += _buyItemBurst(catKey, tostring(name), remote)
            end
        end
    else
        local stocks = _resolveStocks(catKey)
        for name, count in pairs(stocks) do
            if count > 0 then
                bought += _buyItemBurst(catKey, tostring(name), remote)
            end
        end
    end

    return bought
end

local function buyTick(st)
    st = st or getBuyState()
    local total = 0
    total += _processCategory("seed", st.seedEnabled, st.seedSelected, REMOTES.seed)
    total += _processCategory("gear", st.gearEnabled, st.gearSelected, REMOTES.gear)
    total += _processCategory("props", st.propsEnabled, st.propsSelected, REMOTES.props)
    return total
end

local function buyLoop(myId)
    _log("loop start", myId)
    _bindMoneyWatch()
    while running and myId == loopId do
        local st = getBuyState()
        if st.seedEnabled or st.gearEnabled or st.propsEnabled then
            _bindStockWatchers(st)
            local n = buyTick(st)
            task.wait(_loopWaitSec(st, n))
        else
            _clearWatchers()
            task.wait(0.5)
        end
    end
    _clearWatchers()
    _clearMoneyWatch()
    _log("loop end", myId)
end

