local shovelMissingLogged = false

local function _ensureNetworking()
    if WildPetTame and WildPetTameResult and shovelNetReady then
        return WildPetTame ~= nil
    end
    local ok, net = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules", 10):WaitForChild("Networking", 10))
    end)
    if ok and type(net) == "table" then
        if type(net.Pets) == "table" then
            WildPetTame = net.Pets.WildPetTame
            WildPetTameResult = net.Pets.WildPetTameResult
        end
        if type(net.Shovel) == "table" then
            local sn = net.Shovel
            if type(sn.SwingShovel) == "table" and type(sn.SwingShovel.Fire) == "function" then
                SwingShovel = sn.SwingShovel
            end
            if type(sn.HitPlayer) == "table" and type(sn.HitPlayer.Fire) == "function" then
                HitPlayer = sn.HitPlayer
            end
            shovelNetReady = (SwingShovel ~= nil and HitPlayer ~= nil)
        end
    end
    return WildPetTame ~= nil
end


