local COOLDOWN_PAD_SEC   = 0.25   -- padding setelah cooldown server (10s) habis
local STEAL_MIN_GAP_SEC  = 20.0 -- getgc(true) berat; controller game tidak simpan lot kalau UI tutup
-- RequestSnapshot: server hanya jawab sekali per join (selanjutnya nil ~60ms).
-- Jangan spam — 1 in-flight, jarak minimal, backoff kalau nil.
local REQ_MIN_GAP_SEC    = 6.0
local REQ_BACKOFF_MAX    = 60.0

local GEAR_CATEGORIES = {
    Gear = true, Gears = true,
    Sprinklers = true, Rakes = true, WateringCans = true,
    Trowels = true, Shovels = true, Tools = true,
    Crates = true, Props = true,
}

local SLOT_CATEGORIES = {
    seed     = { Seeds = true, HarvestedFruits = true },
    seedpack = { SeedPacks = true },
    egg      = { Eggs = true },
}

local Networking, Auctioneer, PurchaseLot, RequestSnapshot
local AuctionFlags = nil

local running     = false
local loopId      = 0
local netReady    = false
local snapshot    = {
    lots = {},
