local guiControllerCache = nil

local function _getGuiController()
    if type(guiControllerCache) == "table" then
        return guiControllerCache
    end
    local ps = LP:FindFirstChild("PlayerScripts")
    if not ps then return nil end
    local controllers = ps:FindFirstChild("Controllers")
    if not controllers then return nil end
    local inst = controllers:FindFirstChild("GuiController")
    if not inst then return nil end
    local ok, mod = pcall(require, inst)
    if ok and type(mod) == "table" then
        guiControllerCache = mod
        return mod
    end
    return nil
end

local function _getGuiControllerWait(maxSec)
    maxSec = tonumber(maxSec) or 2
    local deadline = os.clock() + maxSec
    while os.clock() < deadline do
        local gc = _getGuiController()
        if gc then return gc end
        local ps = LP:FindFirstChild("PlayerScripts") or LP:WaitForChild("PlayerScripts", 0.25)
        if ps then
            ps:WaitForChild("Controllers", 0.25)
        end
        task.wait(0.05)
    end
    return _getGuiController()
end

local function _auctionScreenGui()
    local pg = LP:FindFirstChild("PlayerGui")
    local gui = pg and pg:FindFirstChild("Auction")
    if gui and gui:IsA("ScreenGui") then return gui end
    return nil
end

function M.IsAuctionGuiOpen()
    local gui = _auctionScreenGui()
    if gui and gui.Enabled then return true end
    local gc = _getGuiController()
    if gc and type(gc.IsOpen) == "function" then
        local ok, open = pcall(gc.IsOpen, gc, "Auction")
        if ok and open == true then return true end
    end
    return false
end

local OPEN_UI_WAIT_SEC = 2.5

local function _waitAuctionOpen(maxSec)
    maxSec = tonumber(maxSec) or OPEN_UI_WAIT_SEC
    local deadline = os.clock() + maxSec
    while os.clock() < deadline do
        local gui = _auctionScreenGui()
        if gui and gui.Enabled then return true end
        local gc = _getGuiController()
        if gc and type(gc.IsOpen) == "function" then
            local ok, open = pcall(gc.IsOpen, gc, "Auction")
            if ok and open == true then return true end
        end
        task.wait(0.05)
    end
    local gui = _auctionScreenGui()
    return gui ~= nil and gui.Enabled == true
end

local function _openViaGuiController()
    local gc = _getGuiController() or _getGuiControllerWait(2)
    if not gc or type(gc.Open) ~= "function" then
        return false, "GuiController tidak ada"
    end
    local ok, err = pcall(gc.Open, gc, "Auction", nil, { "HUD" })
    if not ok then
        return false, tostring(err)
    end
    return true
end

local function _enableAuctionGuiDirect()
    local gui = _auctionScreenGui()
    if not gui then return false end
    gui.Enabled = true
    return gui.Enabled == true
end

local function _findAuctionPrompt()
    local stand = workspace:FindFirstChild("AuctionStand")
    if not stand then return nil end
    for _, d in stand:GetDescendants() do
        if d:IsA("ProximityPrompt") and d:GetAttribute("DontShow") == nil then
            return d
        end
    end
    return stand:FindFirstChildWhichIsA("ProximityPrompt", true)
end

local function _tpNearPrompt(pp, dist)
    dist = tonumber(dist) or 6
    if not pp then return false end
    local attach = pp.Parent
    if not attach or not attach:IsA("BasePart") then
        attach = pp:FindFirstAncestorWhichIsA("BasePart")
    end
    if not attach then return false end

    local Move = G.Move or G.MoveModule or rawget(_G, "Move")
    if type(Move) == "table" and type(Move.ToNearInstance) == "function" then
        return select(1, Move.ToNearInstance(attach, {
            standDist = dist,
            yOffset = 2,
            mode = "hard",
            wait = 0.2,
        })) == true
    end

    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    local back = -attach.CFrame.LookVector
    local flat = Vector3.new(back.X, 0, back.Z)
    if flat.Magnitude < 0.05 then
        flat = Vector3.new(0, 0, -1)
    else
        flat = flat.Unit
    end
    local pos = attach.Position + flat * dist + Vector3.new(0, 2, 0)
    local cf = CFrame.new(pos, attach.Position)
    if type(Move) == "table" and type(Move.SetCFrame) == "function" then
        return Move.SetCFrame(cf, { wait = 0.2 }) == true
    end
    local ok = pcall(function()
        if char.PrimaryPart then
            char:PivotTo(cf)
        else
            hrp.CFrame = cf
        end
    end)
    if ok then task.wait(0.2) end
    return ok
end

local function _fireAuctionPrompt(pp)
    if not pp then return false end
    local fn = (type(fireproximityprompt) == "function" and fireproximityprompt)
        or rawget(_G, "fireproximityprompt")
    if type(fn) ~= "function" then return false end
    if pcall(fn, pp, true) then return true end
    return pcall(fn, pp)
end

local function _openViaNpc()
    local pp = _findAuctionPrompt()
    if not pp then return false end
    if not _tpNearPrompt(pp, 6) then return false end
    task.wait(0.15)
    return _fireAuctionPrompt(pp)
end

local function _refreshAfterOpen()
    if type(_hookEvents) == "function" then pcall(_hookEvents) end
    if type(_fireRequestSnapshot) == "function" then
        task.delay(0.4, function()
            pcall(_fireRequestSnapshot)
        end)
    end
end

function M.OpenAuctionGui()
    if M.IsAuctionGuiOpen() then
        stats.auctionGuiOpen = true
        _setStatus("Auction UI terbuka")
        return true
    end

    task.spawn(function()
        _setStatus("Membuka Auction UI...")

        local okGc, errGc = _openViaGuiController()
        if okGc and _waitAuctionOpen(1) then
            stats.auctionGuiOpen = true
            stats.lastError = nil
            _setStatus("Auction UI terbuka")
            _refreshAfterOpen()
            return
        end

        if _enableAuctionGuiDirect() and _waitAuctionOpen(0.5) then
            stats.auctionGuiOpen = true
            stats.lastError = nil
            _setStatus("Auction UI terbuka")
            _refreshAfterOpen()
            return
        end

        if _openViaNpc() and _waitAuctionOpen(2) then
            stats.auctionGuiOpen = true
            stats.lastError = nil
            _setStatus("Auction UI terbuka (NPC)")
            _refreshAfterOpen()
            return
        end

        okGc = _openViaGuiController()
        _enableAuctionGuiDirect()
        if _waitAuctionOpen(1.5) then
            stats.auctionGuiOpen = true
            stats.lastError = nil
            _setStatus("Auction UI terbuka")
            _refreshAfterOpen()
            return
        end

        stats.auctionGuiOpen = false
        stats.lastError = errGc or "Gagal buka Auction UI"
        _setStatus("Gagal buka Auction UI")
        _log("open fail", stats.lastError)
    end)

    return true
end

local function _stripSelectSuffix(s)
    s = tostring(s or "")
    s = s:gsub("%s+%+%d+$", "")  -- "Super Sprinkler +1" -> "Super Sprinkler"
    s = s:gsub("%s+x%s+[%d%.]+[kKmMbB]?$", "")
    return s
end

local function _normKey(s)
    return _stripSelectSuffix(s):lower():gsub("[%s_%-%.'']+", "")
end

local function _lotIdKey(lotId)
    return tostring(lotId or "")
end

-- Robux-only diabaikan. Dual currency (robuxPrice + dualCurrency) tetap
-- bisa dibeli Candy Corn/Sheckles via PurchaseLot — sama AuctioneerController BuyButton.
local function _lotIsRobuxOnly(lot)
    return typeof(lot) == "table"
        and lot.robuxPrice ~= nil
        and lot.dualCurrency ~= true
end

local function _normalizeLot(lot)
    if typeof(lot) ~= "table" then return nil end
    local lotId = lot.lotId or lot.id or lot.Id
    if lotId == nil or tostring(lotId) == "" then return nil end
    lot.lotId = tostring(lotId)
    return lot
end

local function _collectLots(rawLots)
    local lots = {}
    if typeof(rawLots) ~= "table" then return lots end

    local function push(lot)
        if _lotIsRobuxOnly(lot) then return end
        lot = _normalizeLot(lot)
        if lot then lots[#lots + 1] = lot end
    end

    if #rawLots > 0 then
        for _, lot in ipairs(rawLots) do push(lot) end
    else
        for _, lot in pairs(rawLots) do push(lot) end
    end
    return lots
end

local function _connectRemoteEvent(remote, handler)
    if not remote then return false end
    local signal = remote.OnClientEvent
    if signal and type(signal.Connect) == "function" then
        eventConns[#eventConns + 1] = signal:Connect(handler)
        return true
    end
    if typeof(remote) == "Instance" and remote:IsA("RemoteEvent") then
        eventConns[#eventConns + 1] = remote.OnClientEvent:Connect(handler)
        return true
    end
    if type(remote.Connect) == "function" then
        eventConns[#eventConns + 1] = remote:Connect(handler)
        return true
    end
    return false
end

local function _findAuctionRemoteEvent(name)
    local ae = Networking and Networking.Auctioneer
    if ae and ae[name] then return ae[name] end
    for _, inst in ipairs(ReplicatedStorage:GetDescendants()) do
        if inst:IsA("RemoteEvent") and inst.Name == name then
            local p = inst.Parent
            while p and p ~= ReplicatedStorage do
                local pn = tostring(p.Name):lower()
                if pn:find("auction") then return inst end
                p = p.Parent
            end
        end
    end
    return nil
end

local function _normalizeSet(src)
    if type(src) ~= "table" then return {} end
    local out = {}
    for i = 1, #src do
        local v = src[i]
        if v ~= nil and tostring(v) ~= "" then out[tostring(v)] = true end
    end
    if next(out) then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then out[tostring(k)] = true end
    end
    return out
end

local function _hasAnySelected(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true then return true end
    end
    return false
end

local function _parseMoneyValue(raw)
    if type(raw) == "number" then return raw end
    local txt = tostring(raw or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then return nil end
    local suffixes = {
        { "juta", 1000000 }, { "jt", 1000000 },
        { "ribu", 1000 }, { "rb", 1000 },
        { "b", 1000000000 }, { "m", 1000000 }, { "k", 1000 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then return math.floor(n * mult) end
        end
    end
    return tonumber(txt)
end

function M.ParseMaxPrice(raw)
    return math.max(0, math.floor(_parseMoneyValue(raw) or 0))
end

function M.FormatMaxPrice(n)
    n = math.floor(tonumber(n) or 0)
    if n <= 0 then return "0" end
    if n >= 1000000000 then return string.format("%.2fB", n / 1000000000) end
    if n >= 1000000 then return string.format("%.2fM", n / 1000000) end
    if n >= 1000 then return string.format("%.1fK", n / 1000) end
    return tostring(n)
end

local function _fmtPrice(n)
    return M.FormatMaxPrice(n)
end

local function _readCatMaxPrice(a, slot, globalKey, legacyMax)
    local cat = type(a[slot]) == "table" and a[slot] or {}
    local v = cat.max_price
    if v ~= nil then
        return M.ParseMaxPrice(v)
    end
    v = G[globalKey]
    if v == nil then v = rawget(_G, globalKey) end
    if v ~= nil then
        return M.ParseMaxPrice(v)
    end
    return M.ParseMaxPrice(legacyMax)
end

local function _maxPriceForSlot(cfg, slot)
    local mp = cfg.max_prices
    if type(mp) ~= "table" then return 0 end
    return math.max(0, math.floor(tonumber(mp[slot]) or 0))
end

_lotSlot = function(category)
    category = tostring(category or "")
    if SLOT_CATEGORIES.seed[category] then return "seed" end
    if SLOT_CATEGORIES.seedpack[category] then return "seedpack" end
    if SLOT_CATEGORIES.egg[category] then return "egg" end
    if GEAR_CATEGORIES[category] then return "gear" end
    return "gear"
end

local function _lookupItemMaxPrice(itemPrices, name)
    name = tostring(name or "")
    if name == "" or type(itemPrices) ~= "table" then return nil end
    local direct = itemPrices[name]
    if direct ~= nil then return M.ParseMaxPrice(direct) end
    local plain = _stripSelectSuffix(name)
    if plain ~= name and itemPrices[plain] ~= nil then
        return M.ParseMaxPrice(itemPrices[plain])
    end
    local nk = _normKey(name)
    for k, v in pairs(itemPrices) do
        if _normKey(k) == nk then return M.ParseMaxPrice(v) end
        if _normKey(_stripSelectSuffix(k)) == nk then return M.ParseMaxPrice(v) end
    end
    return nil
end

-- Harga per item (utama). 0 / belum diisi = skip. Fallback kategori hanya migrasi lama.
local function _maxPriceForLot(cfg, lot)
    local itemPrices = cfg and cfg.item_prices
    local fromItem = _lookupItemMaxPrice(itemPrices, lot and lot.item)
    if fromItem == nil then
        fromItem = _lookupItemMaxPrice(itemPrices, lot and lot._displayName)
    end
    if fromItem == nil and Auctioneer and type(Auctioneer.DisplayName) == "function" and typeof(lot) == "table" then
        local ok, dn = pcall(Auctioneer.DisplayName, lot)
        if ok then fromItem = _lookupItemMaxPrice(itemPrices, dn) end
    end
    if fromItem ~= nil then
        return fromItem
    end
    -- fallback kategori (save lama)
    if lot and lot._matchSlot then
        return _maxPriceForSlot(cfg, lot._matchSlot)
    end
    return _maxPriceForSlot(cfg, _lotSlot(lot and lot.category))
end

local function _priceOk(price, maxPrice)
    if type(price) ~= "number" or price < 0 then return false end
    -- 0 = skip / belum set max price per item
    if type(maxPrice) ~= "number" or maxPrice <= 0 then return false end
    return price <= maxPrice
end

-- World: Main=Sheckles, Ghoul=Candy Corn
local MONEY_STAT_NAMES = { "Candy Corn", "Sheckles", "Money", "Cash", "Coins" }

local function _getMoney()
    local ls = LP:FindFirstChild("leaderstats")
    local prefer = nil
    pcall(function()
        local Worlds = require(ReplicatedStorage.SharedModules.Worlds)
        if type(Worlds) == "table" then
            if type(Worlds.WalletStatName) == "function" then
                prefer = Worlds.WalletStatName(LP)
            elseif type(Worlds.Current) == "table" then
                prefer = Worlds.Current.CurrencyName
            end
        end
    end)
    if ls and type(prefer) == "string" and prefer ~= "" then
        local o = ls:FindFirstChild(prefer)
        if o and (o:IsA("IntValue") or o:IsA("NumberValue")) then
            local v = _parseMoneyValue(o.Value)
            if v ~= nil then return v end
        end
    end
    if ls then
        for _, n in ipairs(MONEY_STAT_NAMES) do
            local o = ls:FindFirstChild(n)
            if o and (o:IsA("IntValue") or o:IsA("NumberValue")) then
                local v = _parseMoneyValue(o.Value)
                if v ~= nil then return v end
            end
        end
    end
    for _, n in ipairs({ prefer, "Candy Corn", "Sheckles" }) do
        if type(n) == "string" then
            local attr = LP:GetAttribute(n)
            if attr ~= nil then
                local v = _parseMoneyValue(attr)
                if v ~= nil then return v end
            end
        end
    end
    return nil
end

local function _getServerTime()
    local ok, t = pcall(function()
        return workspace:GetServerTimeNow()
    end)
    return ok and t or os.time()
end

-- u144 AuctioneerController — parse manifest.lots (skip Robux-only; keep dual)
local function _parseManifestLots(manifestLots)
    local lots = {}
    if typeof(manifestLots) ~= "table" then return lots end
    for _, lot in manifestLots do
        if _lotIsRobuxOnly(lot) then
            continue
        end
        if typeof(lot) == "table" and typeof(lot.lotId) == "string" then
            lots[#lots + 1] = lot
        elseif typeof(lot) == "table" and lot.lotId ~= nil then
            lot.lotId = tostring(lot.lotId)
            if lot.lotId ~= "" then lots[#lots + 1] = lot end
        end
    end
    return lots
end

local function _waitGameAuctioneer(maxSec)
    maxSec = tonumber(maxSec) or 25
    local deadline = os.clock() + maxSec
    while os.clock() < deadline do
        local ps = LP:FindFirstChild("PlayerScripts")
        local controllers = ps and ps:FindFirstChild("Controllers")
        if controllers and controllers:FindFirstChild("AuctioneerController") then
            return true
        end
        task.wait(0.25)
    end
    return false
end

_ensureSnapshotLots = function()
    -- Remote only — tidak scrape GUI (game tidak butuh UI terbuka)
    return snapshot ~= nil and snapshot.lots ~= nil and #snapshot.lots > 0
end

local function _ensureNet()
    if netReady and RequestSnapshot then return true end
    local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        or ReplicatedStorage:WaitForChild("SharedModules", 30)
    if not sm then
        stats.lastError = "SharedModules missing"
        return false
    end
    local netInst = sm:FindFirstChild("Networking") or sm:WaitForChild("Networking", 15)
    if not netInst then
        stats.lastError = "Networking module missing"
        return false
    end
    local ok, net = pcall(require, netInst)
    if not ok or type(net) ~= "table" or type(net.Auctioneer) ~= "table" then
        stats.lastError = "Networking.Auctioneer missing"
        return false
    end
    Networking = net
    local ae = net.Auctioneer
    PurchaseLot = ae.PurchaseLot
    RequestSnapshot = ae.RequestSnapshot
    if not RequestSnapshot then
        stats.lastError = "RequestSnapshot missing"
        return false
    end
    if not AuctionFlags then
        pcall(function()
            local flags = sm:FindFirstChild("Flags")
            local inst = flags and flags:FindFirstChild("AuctioneerFlags")
            if inst then AuctionFlags = require(inst) end
        end)
    end
    netReady = true
    stats.lastError = nil
    _ensureAuctioneer()
    return true
end

_ensureAuctioneer = function()
    if Auctioneer then return true end
    local sm = ReplicatedStorage:FindFirstChild("SharedModules")
    if not sm then return false end
    local ok, mod = pcall(function()
        return require(sm:WaitForChild("Auctioneer", 5))
    end)
    if ok and type(mod) == "table" then
        Auctioneer = mod
        return true
    end
    return false
end

_hasSnapshotData = function()
    return lastSnapshotAt > 0
end

local function _hasLiveLots()
    return snapshot ~= nil and type(snapshot.lots) == "table" and #snapshot.lots > 0
end

local function _isPlainTable(v)
    return type(v) == "table" and typeof(v) == "table"
end

local function _safeGet(t, key)
    if not _isPlainTable(t) then return nil end
    local ok, v = pcall(rawget, t, key)
    if ok then return v end
    return nil
end

local function _isAuctionLot(lot)
    if not _isPlainTable(lot) then return false end
    local id = _safeGet(lot, "lotId")
    if type(id) ~= "string" or id == "" then return false end
    if not string.find(id, "auction:", 1, true) then return false end
    if type(_safeGet(lot, "startPrice")) ~= "number" then return false end
    if type(_safeGet(lot, "rolledAt")) ~= "number" then return false end
    if type(_safeGet(lot, "expiresAt")) ~= "number" then return false end
    return true
end

-- lotId format game: "auction:<rollWindowUnix>:<index>"
local function _parseRollWindowFromLotId(lotId)
    local rw = string.match(tostring(lotId or ""), "^auction:(%d+):")
    return tonumber(rw)
end

local function _rememberRollMeta()
    if not snapshot then return end
    local rw = tonumber(snapshot.rollWindowUnix) or 0
    local ri = tonumber(snapshot.rollIntervalSeconds) or 0
    local ts = tonumber(snapshot.timerShiftSeconds) or 0
    if rw > 0 then lastRollMeta.rollWindowUnix = rw end
    if ri > 0 then lastRollMeta.rollIntervalSeconds = ri end
    lastRollMeta.timerShiftSeconds = ts
end

local function _restoreRollMetaIfMissing()
    if not snapshot then return end
    if (tonumber(snapshot.rollWindowUnix) or 0) <= 0 and lastRollMeta.rollWindowUnix > 0 then
        snapshot.rollWindowUnix = lastRollMeta.rollWindowUnix
    end
    if (tonumber(snapshot.rollIntervalSeconds) or 0) <= 0 and lastRollMeta.rollIntervalSeconds > 0 then
        snapshot.rollIntervalSeconds = lastRollMeta.rollIntervalSeconds
    end
    if (tonumber(snapshot.timerShiftSeconds) or 0) == 0 and lastRollMeta.timerShiftSeconds ~= 0 then
        snapshot.timerShiftSeconds = lastRollMeta.timerShiftSeconds
    end
end

local function _hasRollTimer()
    _restoreRollMetaIfMissing()
    if not snapshot then return false end
    return (tonumber(snapshot.rollWindowUnix) or 0) > 0
        and (tonumber(snapshot.rollIntervalSeconds) or 0) > 0
end

-- Isi/refresh timer dari lotId + expiresAt (jalan meski roll sudah berakhir)
local function _ensureRollMetaFromLots(lots)
    if not snapshot or type(lots) ~= "table" then return false end
    local rw = tonumber(snapshot.rollWindowUnix) or 0
    local ri = tonumber(snapshot.rollIntervalSeconds) or 0
    local bestExp = 0
    local changed = false
    for _, lot in ipairs(lots) do
        if typeof(lot) == "table" then
            local fromId = _parseRollWindowFromLotId(lot.lotId)
            if fromId and fromId > rw then
                rw = fromId
                changed = true
            end
            local exp = tonumber(lot.expiresAt)
            if exp and exp > bestExp then bestExp = exp end
        end
    end
    if rw > 0 and rw ~= (tonumber(snapshot.rollWindowUnix) or 0) then
        snapshot.rollWindowUnix = rw
        changed = true
    elseif rw > 0 and (tonumber(snapshot.rollWindowUnix) or 0) <= 0 then
        snapshot.rollWindowUnix = rw
        changed = true
    end
    if ri <= 0 and bestExp > 0 and rw > 0 and bestExp > rw then
        snapshot.rollIntervalSeconds = math.max(1, math.floor(bestExp - rw))
        changed = true
    end
    if changed then _rememberRollMeta() end
    return _hasRollTimer()
end

-- Steal lot hidup dari AuctioneerController (proven: lot array ketemu di getgc).
-- force=true hanya bootstrap saat fitur ON — getgc(true) sangat berat & freeze client.
-- OFF / idle: JANGAN getgc (poller lama dulu bikin hitch tiap 15s).
local function _stealAllowed()
    if running == true then return true end
    local en = G.AUTO_BUY_AUCTION_ENABLED == true
        or rawget(_G, "AUTO_BUY_AUCTION_ENABLED") == true
    if en then return true end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local a = MAIN and MAIN.auto and MAIN.auto.buy and MAIN.auto.buy.auction
    return type(a) == "table" and a.enabled == true
end

local function _stealLiveAuctionState(force, allowWhenOff)
    if allowWhenOff ~= true and not _stealAllowed() then
        return false
    end
    local needTimer = not _hasRollTimer()
    if awaitingNextRoll and not force and not needTimer then
        return false
    end
    local now = os.clock()
    if not force and (now - lastStealAt) < STEAL_MIN_GAP_SEC then
        return false
    end

    local gc = rawget(G, "getgc") or rawget(_G, "getgc") or (type(getgc) == "function" and getgc) or nil
    if type(gc) ~= "function" then
        _log("steal skip: getgc missing")
        return false
    end

    lastStealAt = now
    local bestLots, bestCount = nil, 0
    local bestStock = nil
    local bestMeta = nil

    local okScan, errScan = pcall(function()
        for _, obj in gc(true) do
            if _isPlainTable(obj) then
                local nOk, n = pcall(function()
                    return #obj
                end)
                if nOk and type(n) == "number" and n >= 1 and n <= 40 and n > bestCount then
                    if _isAuctionLot(_safeGet(obj, 1)) then
                        local parsed, good = {}, true
                        for i = 1, n do
                            local lot = _safeGet(obj, i)
                            if _isAuctionLot(lot) then
                                if not _lotIsRobuxOnly(lot) then
                                    parsed[#parsed + 1] = lot
                                end
                            else
                                good = false
                                break
                            end
                        end
                        if good and #parsed > bestCount then
                            bestLots, bestCount = parsed, #parsed
                        end
                    end
                end

                local rw = _safeGet(obj, "rollWindowUnix")
                if type(rw) == "number" and rw > 0 then
                    local lots = nil
                    local manifest = _safeGet(obj, "manifest")
                    if _isPlainTable(manifest) then
                        local ml = _safeGet(manifest, "lots")
                        if _isPlainTable(ml) then lots = ml end
                    end
                    if not lots then
                        local lf = _safeGet(obj, "lots")
                        if _isPlainTable(lf) then lots = lf end
                    end
                    if _isPlainTable(lots) then
                        local parsed = _parseManifestLots(lots)
                        if #parsed > bestCount then
                            bestLots, bestCount = parsed, #parsed
                            local ri = _safeGet(obj, "rollIntervalSeconds")
                            local ts = _safeGet(obj, "timerShiftSeconds")
                            bestMeta = {
                                rollWindowUnix = rw,
                                rollIntervalSeconds = type(ri) == "number" and ri or 0,
                                timerShiftSeconds = type(ts) == "number" and ts or 0,
                            }
                            local st = _safeGet(obj, "stock")
                            if _isPlainTable(st) then bestStock = st end
                        end
                    end
                end
            end
        end

        if bestLots and not bestStock then
            for _, obj in gc(true) do
                if _isPlainTable(obj) then
                    local hits = 0
                    for i = 1, math.min(#bestLots, 8) do
                        local id = _safeGet(bestLots[i], "lotId")
                        if type(id) == "string" and type(_safeGet(obj, id)) == "number" then
                            hits += 1
                        end
                    end
                    if hits >= 2 then
                        bestStock = obj
                        break
                    end
                end
            end
        end
    end)
    if not okScan then
        _log("steal getgc error", errScan)
        return false
    end
    if not bestLots or bestCount < 1 then
        _log("steal: no live lots in gc")
        return false
    end

    local prevRi = snapshot and tonumber(snapshot.rollIntervalSeconds) or lastRollMeta.rollIntervalSeconds or 0
    local prevRw = snapshot and tonumber(snapshot.rollWindowUnix) or lastRollMeta.rollWindowUnix or 0
    local prevTs = snapshot and tonumber(snapshot.timerShiftSeconds) or lastRollMeta.timerShiftSeconds or 0
    if prevRi <= 0 then prevRi = lastRollMeta.rollIntervalSeconds or 0 end
    if prevRw <= 0 then prevRw = lastRollMeta.rollWindowUnix or 0 end
    snapshot = {
        lots = bestLots,
        stock = _isPlainTable(bestStock) and bestStock or (snapshot and snapshot.stock) or {},
        rollIntervalSeconds = (bestMeta and bestMeta.rollIntervalSeconds and bestMeta.rollIntervalSeconds > 0)
            and bestMeta.rollIntervalSeconds or prevRi or 0,
        rollWindowUnix = (bestMeta and bestMeta.rollWindowUnix and bestMeta.rollWindowUnix > 0)
            and bestMeta.rollWindowUnix or prevRw or 0,
        timerShiftSeconds = (bestMeta and type(bestMeta.timerShiftSeconds) == "number")
            and bestMeta.timerShiftSeconds or prevTs or 0,
    }
    stockMap = snapshot.stock
    lastSnapshotAt = os.clock()
    stats.lastError = nil
    _ensureRollMetaFromLots(bestLots)
    _rememberRollMeta()
    _reconcileSnapshot(_getServerTime())
    awaitingNextRoll = not _hasLiveLots()
    _log("steal ok", #snapshot.lots, "lots (gc)", "timer", _hasRollTimer(), "rw", snapshot.rollWindowUnix, "ri", snapshot.rollIntervalSeconds)
    return _hasLiveLots() or _hasRollTimer()
end

_parseSnapshot = function(raw)
    if typeof(raw) ~= "table" then return false end
    local lots = {}
    local manifest = raw.manifest
    if typeof(manifest) == "table" and typeof(manifest.lots) == "table" then
        lots = _parseManifestLots(manifest.lots)
    elseif typeof(raw.lots) == "table" then
        lots = _collectLots(raw.lots)
    end

  -- Hanya pertahankan lot lama kalau payload tidak bawa daftar lot baru (mis. StockUpdate).
  -- manifest.lots = {} artinya roll baru / kosong — jangan tampilkan 6 lot expired.
    local hasNewLotList = (typeof(manifest) == "table" and manifest.lots ~= nil)
        or typeof(raw.lots) == "table"
    if #lots < 1 and not hasNewLotList and snapshot and snapshot.lots and #snapshot.lots > 0 then
        if typeof(raw.stock) == "table" then
            stockMap = raw.stock
            snapshot.stock = stockMap
        end
        lastSnapshotAt = os.clock()
        return true
    end

    -- Jangan hapus timer roll kalau payload kosong/tidak bawa meta (biar countdown next auction tetap ada)
    local prev = snapshot
    local ri = typeof(raw.rollIntervalSeconds) == "number" and raw.rollIntervalSeconds or 0
    local rw = typeof(raw.rollWindowUnix) == "number" and raw.rollWindowUnix or 0
    local ts = typeof(raw.timerShiftSeconds) == "number" and raw.timerShiftSeconds or 0
    if ri <= 0 and prev then ri = tonumber(prev.rollIntervalSeconds) or 0 end
    if rw <= 0 and prev then rw = tonumber(prev.rollWindowUnix) or 0 end
    if ts == 0 and prev and typeof(raw.timerShiftSeconds) ~= "number" then
        ts = tonumber(prev.timerShiftSeconds) or 0
    end

    snapshot = {
        lots = lots,
        stock = typeof(raw.stock) == "table" and raw.stock
            or (prev and typeof(prev.stock) == "table" and prev.stock)
            or {},
        rollIntervalSeconds = ri,
        rollWindowUnix = rw,
        timerShiftSeconds = ts,
    }
    stockMap = snapshot.stock
    lastSnapshotAt = os.clock()
    if #lots < 1 then
        awaitingNextRoll = true
        stats.lastError = "manifest.lots kosong"
    else
        awaitingNextRoll = false
        stats.lastError = nil
    end
    _ensureRollMetaFromLots(lots)
    _restoreRollMetaIfMissing()
    _rememberRollMeta()
    _reconcileSnapshot(_getServerTime())
    _log("snapshot parsed", #snapshot.lots, "lots", "ri", snapshot.rollIntervalSeconds, "rw", snapshot.rollWindowUnix)
    return true
end

-- RequestSnapshot adalah request/response (Fire yield sampai jawaban / timeout 10s).
-- Server jawab data hanya sekali per join; request berikutnya dijawab nil.
-- Jadi: 1 in-flight saja, jarak minimal REQ_MIN_GAP_SEC, backoff eksponensial saat nil.
_fireRequestSnapshot = function(force)
    if not _ensureNet() or not RequestSnapshot then return false end
    _hookEvents()
    if reqInFlight then return false end
    local now = os.clock()
    if force ~= true and now < reqNextAllowedAt then return false end

    local function callSnapshot()
        if type(RequestSnapshot.Fire) == "function" then
            return RequestSnapshot:Fire()
        end
        if type(RequestSnapshot.InvokeServer) == "function" then
            return RequestSnapshot:InvokeServer()
        end
        return nil
    end
    reqInFlight = true
    local ok, data = pcall(callSnapshot)
    reqInFlight = false
    now = os.clock()
    if not ok then
        stats.lastError = tostring(data)
        reqNilStreak += 1
        reqNextAllowedAt = now + math.min(REQ_BACKOFF_MAX, REQ_MIN_GAP_SEC * (2 ^ math.min(reqNilStreak, 6)))
        return false
    end
    if data ~= nil then
        reqNilStreak = 0
        reqNextAllowedAt = now + REQ_MIN_GAP_SEC
        _parseSnapshot(data)
        _log("RequestSnapshot ok", snapshot and #snapshot.lots or 0, "lots")
        return _hasSnapshotData()
    end
    -- nil = server tolak (sudah pernah kirim / throttle). Backoff, jangan spam.
    reqNilStreak += 1
    reqNextAllowedAt = now + math.min(REQ_BACKOFF_MAX, REQ_MIN_GAP_SEC * (2 ^ math.min(reqNilStreak, 6)))
    _log("RequestSnapshot nil, streak", reqNilStreak, "next in", math.floor(reqNextAllowedAt - now))
    return false
end

_waitForSnapshotSince = function(sinceClock, maxSec, wantLots)
    sinceClock = tonumber(sinceClock) or 0
    maxSec = tonumber(maxSec) or SNAPSHOT_WAIT_SEC
    local deadline = os.clock() + maxSec
    while os.clock() < deadline do
        if wantLots then
            if _hasLiveLots() and lastSnapshotAt >= sinceClock then
                return true
            end
        elseif lastSnapshotAt >= sinceClock then
            return true
        end
        task.wait(0.1)
    end
    if wantLots then
        return _hasLiveLots() and lastSnapshotAt >= sinceClock
    end
    return lastSnapshotAt >= sinceClock
end

_bootstrapAuction = function(waitSec, allowSteal)
    waitSec = tonumber(waitSec) or SNAPSHOT_WAIT_SEC
    if allowSteal == nil then allowSteal = _stealAllowed() end
    if not _ensureNet() then
        stats.lastError = "Networking belum ready"
        return false
    end
    _ensureAuctioneer()
    _hookEvents()
    if not eventsHooked then
        stats.lastError = "gagal hook Snapshot.OnClientEvent"
        return false
    end

    local startedAt = os.clock()
    pcall(_fireRequestSnapshot)
    if _hasLiveLots() then return true end

    -- event sebentar; jangan nunggu full next roll
    if _waitForSnapshotSince(startedAt, math.min(1.25, waitSec), true) then
        return true
    end

    -- FALLBACK getgc: hanya saat fitur ON
    if allowSteal and not awaitingNextRoll and _stealLiveAuctionState(true) then
        return true
    end

    local left = waitSec - (os.clock() - startedAt)
    if left > 0.2 and _waitForSnapshotSince(startedAt, left, true) then
        return true
    end

    pcall(_fireRequestSnapshot)
    if _hasLiveLots() then return true end
    if allowSteal and not awaitingNextRoll and _stealLiveAuctionState(false) then return true end

    if not _hasLiveLots() then
        stats.lastError = stats.lastError or "Snapshot event tidak datang (tunggu roll)"
    end
    return _hasLiveLots() or _hasSnapshotData()
end

local function _requestSnapshot(waitForEvent)
    if waitForEvent == nil then waitForEvent = true end
    return _bootstrapAuction(waitForEvent and SNAPSHOT_WAIT_SEC or 1)
end

local function _readCfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local buy = MAIN and MAIN.auto and MAIN.auto.buy
    local a = type(buy) == "table" and buy.auction or nil
    a = type(a) == "table" and a or {}

    local enabled = (G.AUTO_BUY_AUCTION_ENABLED == true)
        or (rawget(_G, "AUTO_BUY_AUCTION_ENABLED") == true)
        or (a.enabled == true)

    local maxPrice = G.AUTO_BUY_AUCTION_MAX_PRICE
    if maxPrice == nil then maxPrice = rawget(_G, "AUTO_BUY_AUCTION_MAX_PRICE") end
    if maxPrice == nil then maxPrice = a.max_price end
    if maxPrice == nil then maxPrice = a.legacy_max_price end
    local legacyMax = M.ParseMaxPrice(maxPrice)

    local itemPrices = {}
    local rawPrices = G.AUTO_BUY_AUCTION_ITEM_PRICES
    if type(rawPrices) ~= "table" then rawPrices = rawget(_G, "AUTO_BUY_AUCTION_ITEM_PRICES") end
    if type(rawPrices) ~= "table" then rawPrices = a.item_prices end
    if type(rawPrices) == "table" then
        for k, v in pairs(rawPrices) do
            local name = tostring(k or "")
            if name ~= "" then
                itemPrices[name] = M.ParseMaxPrice(v)
            end
        end
    end

    local modeRaw = G.AUTO_BUY_AUCTION_MODE
    if modeRaw == nil then modeRaw = rawget(_G, "AUTO_BUY_AUCTION_MODE") end
    if modeRaw == nil then modeRaw = a.mode end
    local mode = (tostring(modeRaw or "normal"):lower() == "last_chance") and "last_chance" or "normal"

    local minStock = G.AUTO_BUY_AUCTION_LAST_CHANCE_MIN_STOCK
    if minStock == nil then minStock = rawget(_G, "AUTO_BUY_AUCTION_LAST_CHANCE_MIN_STOCK") end
    if minStock == nil then minStock = a.last_chance_min_stock end
    minStock = math.floor(tonumber(minStock) or 100)
    if minStock < 1 then minStock = 1 end

    local timeLeftSec = G.AUTO_BUY_AUCTION_LAST_CHANCE_TIME_LEFT_SEC
    if timeLeftSec == nil then timeLeftSec = rawget(_G, "AUTO_BUY_AUCTION_LAST_CHANCE_TIME_LEFT_SEC") end
    if timeLeftSec == nil then timeLeftSec = a.last_chance_time_left_sec end
    timeLeftSec = math.floor(tonumber(timeLeftSec) or 20)
    if timeLeftSec < 1 then timeLeftSec = 1 end

    return {
        enabled   = enabled,
        mode = mode,
        last_chance_min_stock = minStock,
        last_chance_time_left_sec = timeLeftSec,
        item_prices = itemPrices,
        max_prices = {
            seed = _readCatMaxPrice(a, "seed", "AUTO_BUY_AUCTION_SEED_MAX_PRICE", legacyMax),
            gear = _readCatMaxPrice(a, "gear", "AUTO_BUY_AUCTION_GEAR_MAX_PRICE", legacyMax),
            seedpack = _readCatMaxPrice(a, "seedpack", "AUTO_BUY_AUCTION_SEEDPACK_MAX_PRICE", legacyMax),
            egg = _readCatMaxPrice(a, "egg", "AUTO_BUY_AUCTION_EGG_MAX_PRICE", legacyMax),
        },
        seed      = _normalizeSet(G.BUY_AUCTION_SEED_SELECTED or rawget(_G, "BUY_AUCTION_SEED_SELECTED") or (a.seed and a.seed.items)),
        gear      = _normalizeSet(G.BUY_AUCTION_GEAR_SELECTED or rawget(_G, "BUY_AUCTION_GEAR_SELECTED") or (a.gear and a.gear.items)),
        seedpack  = _normalizeSet(G.BUY_AUCTION_SEEDPACK_SELECTED or rawget(_G, "BUY_AUCTION_SEEDPACK_SELECTED") or (a.seedpack and a.seedpack.items)),
        egg       = _normalizeSet(G.BUY_AUCTION_EGG_SELECTED or rawget(_G, "BUY_AUCTION_EGG_SELECTED") or (a.egg and a.egg.items)),
    }
end

local function _matchesSelected(selected, ...)
    if not _hasAnySelected(selected) then return false end
    for i = 1, select("#", ...) do
        local name = tostring(select(i, ...) or "")
        if name ~= "" then
            if selected[name] == true then return true end
            local plain = _stripSelectSuffix(name)
            if plain ~= name and selected[plain] == true then return true end
            local nk = _normKey(name)
            for k, v in pairs(selected) do
                if v == true and _normKey(k) == nk then return true end
            end
        end
    end
    return false
end

local function _lotDisplayName(lot)
    if Auctioneer and type(Auctioneer.DisplayName) == "function" then
        local ok, name = pcall(Auctioneer.DisplayName, lot)
        if ok and typeof(name) == "string" and name ~= "" then return name end
    end
    return tostring(lot.item or "")
end

local function _lotSelected(lot, cfg)
    local display = _lotDisplayName(lot)
    local item = tostring(lot.item or "")
    for _, slot in ipairs({ "seed", "gear", "seedpack", "egg" }) do
        local selected = cfg[slot]
        if _matchesSelected(selected, item, display) then
            lot._matchSlot = slot
            return true
        end
    end
    return false
end

local function _stockLeft(lot)
    local id = _lotIdKey(lot.lotId)
    return stockMap[id] or stockMap[lot.lotId]
end

local function _isLastChanceMode(cfg)
    return type(cfg) == "table" and tostring(cfg.mode or "normal"):lower() == "last_chance"
end

local function _lastChanceMinStock(cfg)
    local n = math.floor(tonumber(cfg and cfg.last_chance_min_stock) or 100)
    if n < 1 then n = 1 end
    return n
end

local function _lastChanceTimeLeftSec(cfg)
    local n = math.floor(tonumber(cfg and cfg.last_chance_time_left_sec) or 20)
    if n < 1 then n = 1 end
    return n
end

-- Angka stok lot; nil = ∞ / tidak diketahui.
local function _numericStockLeft(lot)
    if typeof(lot) ~= "table" then return nil end
    local left = _stockLeft(lot)
    if left ~= nil then
        local n = tonumber(left)
        if n ~= nil then return math.max(0, math.floor(n)) end
    end
    if lot.stockQuantity ~= nil then
        local q = tonumber(lot.stockQuantity)
        if q ~= nil then return math.max(0, math.floor(q)) end
    end
    return nil
end

local function _lastChanceStockOk(lot, cfg)
    local stock = _numericStockLeft(lot)
    if stock == nil then return false end
    local minStock = _lastChanceMinStock(cfg)
    return stock > 0 and stock <= minStock
end

-- Diisi setelah _rollRefreshRemain tersedia.
local _lotTimeLeftSec
local _lastChanceTimeOk
local _lastChanceReady

local function _lotBuyPriceOk(lot, price, cfg)
    if type(price) ~= "number" or price < 0 then return false, "no_price" end
    if _isLastChanceMode(cfg) then
        local okReady, why = _lastChanceReady(lot, cfg)
        if not okReady then
            return false, why or "wait"
        end
        return true, price
    end
    local maxP = _maxPriceForLot(cfg, lot)
    if type(maxP) ~= "number" or maxP <= 0 then return false, "no_max_price" end
    if not _priceOk(price, maxP) then return false, "over_max" end
    return true, price
end

local function _fmtStockLeft(lot)
    if typeof(lot) ~= "table" then return "-" end
    local left = _stockLeft(lot)
    if left == nil then
        if lot.stockQuantity == nil then
            return "∞"
        end
        local q = tonumber(lot.stockQuantity)
        if q == nil then return "-" end
        return tostring(math.max(0, math.floor(q)))
    end
    local n = tonumber(left)
    if n == nil then return "-" end
    return tostring(math.max(0, math.floor(n)))
end

local function _rollWindowEnd(snap)
    snap = snap or snapshot
    if not snap then return 0 end
    local ri = tonumber(snap.rollIntervalSeconds) or 0
    local rw = tonumber(snap.rollWindowUnix) or 0
    local ts = tonumber(snap.timerShiftSeconds) or 0
    if ri <= 0 or rw <= 0 then return 0 end
    return rw + ri + ts
end

-- Sisa detik sampai refresh/next roll. Kalau window sudah lewat, proyeksi cycle berikutnya.
local function _rollRefreshRemain(serverTime)
    if not snapshot then return nil end
    _restoreRollMetaIfMissing()
    serverTime = serverTime or _getServerTime()
    local ri = tonumber(snapshot.rollIntervalSeconds) or 0
    local endAt = _rollWindowEnd(snapshot)
    if endAt <= 0 then return nil end
    if serverTime < endAt then
        return endAt - serverTime
    end
    if ri <= 0 then return 0 end
    local overdue = serverTime - endAt
    local into = overdue % ri
    if into < 0.05 then return 0 end
    return ri - into
end

-- Sisa detik lot (expiresAt) vs roll window — ambil yang lebih kecil.
_lotTimeLeftSec = function(lot, serverTime)
    serverTime = serverTime or _getServerTime()
    local best = nil
    if typeof(lot) == "table" and typeof(lot.expiresAt) == "number" then
        best = lot.expiresAt - serverTime
    end
    local rollRemain = _rollRefreshRemain(serverTime)
    if type(rollRemain) == "number" then
        if best == nil then
            best = rollRemain
        else
            best = math.min(best, rollRemain)
        end
    end
    return best
end

_lastChanceTimeOk = function(lot, cfg, serverTime)
    local timeLeft = _lotTimeLeftSec(lot, serverTime)
    if type(timeLeft) ~= "number" then return false end
    local thresh = _lastChanceTimeLeftSec(cfg)
    return timeLeft >= 0 and timeLeft <= thresh
end

-- Last Chance trigger: stock left ≤ N  OR  time left ≤ T (harga diabaikan).
_lastChanceReady = function(lot, cfg, serverTime)
    serverTime = serverTime or _getServerTime()
    local stock = _numericStockLeft(lot)
    if stock ~= nil and stock <= 0 then
        return false, "sold_out"
    end
    local stockOk = _lastChanceStockOk(lot, cfg)
    local timeOk = _lastChanceTimeOk(lot, cfg, serverTime)
    if stockOk or timeOk then
        if stockOk and timeOk then return true, "stock_or_time" end
        if stockOk then return true, "stock" end
        return true, "time"
    end
    return false, "wait"
end

local function _fmtRemainClock(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local m = sec // 60
    local s = sec % 60
    if m >= 60 then
        local h = m // 60
        m = m % 60
        return string.format("%dh %02dm %02ds", h, m, s)
    end
    return string.format("%dm %02ds", m, s)
end

local function _isAuctionRollLive(serverTime)
    if not snapshot then return true end
    local endAt = _rollWindowEnd(snapshot)
    if endAt <= 0 then return true end
    return serverTime < endAt
end

local function _lotIsLive(lot, serverTime)
    -- u139 AuctioneerController: sold_out / expired / IsActive
    if typeof(lot) ~= "table" then return false end
    local stockLeft = _stockLeft(lot)
    if lot.stockQuantity ~= nil and stockLeft ~= nil and stockLeft <= 0 then
        return false
    end
    if typeof(lot.expiresAt) == "number" and lot.expiresAt <= serverTime then
        return false
    end
    if Auctioneer and type(Auctioneer.IsActive) == "function" then
        local ok, active = pcall(Auctioneer.IsActive, lot, serverTime, stockLeft)
        if ok and active == false then return false end
    end
    return true
end

_reconcileSnapshot = function(serverTime)
    if not snapshot then return end
    serverTime = serverTime or _getServerTime()
    _restoreRollMetaIfMissing()

    if snapshot.lots and #snapshot.lots > 0 then
        _ensureRollMetaFromLots(snapshot.lots)
    end

    if not _isAuctionRollLive(serverTime) then
        if snapshot.lots and #snapshot.lots > 0 then
            _ensureRollMetaFromLots(snapshot.lots)
            _rememberRollMeta()
            snapshot.lots = {}
            table.clear(burstRunning)
            awaitingNextRoll = true
            _log("roll window ended — cleared lots (timer kept)", snapshot.rollWindowUnix, snapshot.rollIntervalSeconds)
        elseif not awaitingNextRoll then
            awaitingNextRoll = true
        end
        return
    end

    if not snapshot.lots or #snapshot.lots < 1 then return end
    local live = {}
    for _, lot in ipairs(snapshot.lots) do
        if _lotIsLive(lot, serverTime) then
            live[#live + 1] = lot
        end
    end
    if #live ~= #snapshot.lots then
        if #live < 1 then
            _ensureRollMetaFromLots(snapshot.lots)
            _rememberRollMeta()
        end
        snapshot.lots = live
        _log("pruned dead lots", #live)
        if #live < 1 then
            table.clear(burstRunning)
            awaitingNextRoll = true
        end
    end
end

local function _lotAvailable(lot, serverTime)
    if _lotIsRobuxOnly(lot) then
        return false, "robux"
    end
    if not _lotIsLive(lot, serverTime) then
        local stockLeft = _stockLeft(lot)
        if lot.stockQuantity ~= nil and stockLeft ~= nil and stockLeft <= 0 then
            return false, "sold_out"
        end
        if typeof(lot.expiresAt) == "number" and lot.expiresAt <= serverTime then
            return false, "expired"
        end
        return false, "inactive"
    end
    return true
end

local function _lotPriceForBuy(lot, serverTime)
    -- u55: harga selalu dari Auctioneer.CurrentPrice — tidak perlu UI terbuka
    if not _lotIsLive(lot, serverTime) then return nil end
    if not Auctioneer or type(Auctioneer.CurrentPrice) ~= "function" then return nil end
    local ok, price = pcall(Auctioneer.CurrentPrice, lot, serverTime)
    if ok and type(price) == "number" and price == price and price > 0 then
        return math.floor(price)
    end
    return nil
end

local function _lotPrice(lot, serverTime)
    return _lotPriceForBuy(lot, serverTime)
end

-- u139: expired / sold_out / ready + harga dari Auctioneer module
local function _analyzeLot(lot, serverTime)
    serverTime = serverTime or _getServerTime()
    _ensureAuctioneer()
    local stockLeft = _stockLeft(lot)
    local soldOut = lot.stockQuantity ~= nil and stockLeft ~= nil and stockLeft <= 0
    local expired = typeof(lot.expiresAt) == "number" and lot.expiresAt <= serverTime
    local active = nil
    if Auctioneer and type(Auctioneer.IsActive) == "function" then
        local ok, a = pcall(Auctioneer.IsActive, lot, serverTime, stockLeft)
        if ok then active = a end
    end
    local price = _lotPriceForBuy(lot, serverTime)
    local ready = _lotIsLive(lot, serverTime) and active ~= false and price ~= nil
    local state = "ready"
    if soldOut then state = "sold_out"
    elseif expired then state = "expired"
    elseif active == false then state = "inactive"
    elseif not price then state = "no_price"
    else state = "ready"
    end
    return {
        lotId = lot.lotId,
        item = _lotDisplayName(lot),
        price = price,
        stockLeft = stockLeft,
        soldOut = soldOut,
        expired = expired,
        active = active,
        ready = ready,
        state = state,
    }
end

local function _statusForCfg(cfg, serverTime)
    serverTime = serverTime or _getServerTime()
    if not _hasSnapshotData() then
        return "Menunggu snapshot"
    end
    _reconcileSnapshot(serverTime)
    if not snapshot or #snapshot.lots < 1 then
        local remain = _rollRefreshRemain(serverTime)
        local live = _isAuctionRollLive(serverTime)
        if remain ~= nil and remain > 0 then
            if live then
                return "Lot kosong — next ~" .. _fmtRemainClock(remain)
            end
            return "Next auction ~" .. _fmtRemainClock(remain)
        end
        if remain ~= nil and remain <= 0 then
            return "Auction ended — refresh segera"
        end
        return "Lot kosong — tunggu refresh (no timer)"
    end
    local lastChance = _isLastChanceMode(cfg)
    local minStock = _lastChanceMinStock(cfg)
    local timeThresh = _lastChanceTimeLeftSec(cfg)
    for _, lot in ipairs(snapshot.lots) do
        if _lotSelected(lot, cfg) then
            local info = _analyzeLot(lot, serverTime)
            local stockTxt = _fmtStockLeft(lot)
            local timeLeft = _lotTimeLeftSec(lot, serverTime)
            local timeTxt = type(timeLeft) == "number" and _fmtRemainClock(timeLeft) or "-"
            if lastChance then
                local okBuy, why = _lotBuyPriceOk(lot, info.price, cfg)
                if info.ready and okBuy then
                    return string.format("Last Chance · siap %s @ %s · stock %s · time %s",
                        info.item, _fmtPrice(info.price), stockTxt, timeTxt)
                end
                if why == "wait" or why == "wait_stock" then
                    local priceTxt = info.price ~= nil and _fmtPrice(info.price) or "?"
                    return string.format(
                        "Last Chance · %s @ %s · stock left %s / ≤ %d · time left %s / ≤ %ds",
                        info.item, priceTxt, stockTxt, minStock, timeTxt, timeThresh
                    )
                end
                local priceTxt = info.price ~= nil and (" @ " .. _fmtPrice(info.price)) or ""
                return string.format("Last Chance · %s%s: %s · stock %s · time %s",
                    info.item, priceTxt, info.state, stockTxt, timeTxt)
            end
            local maxP = _maxPriceForLot(cfg, lot)
            if info.price and maxP > 0 and info.price > maxP then
                return string.format("%s: %s > max %s · stock %s",
                    info.item, _fmtPrice(info.price), _fmtPrice(maxP), stockTxt)
            end
            if info.ready and info.price and _priceOk(info.price, maxP) then
                return string.format("Siap beli %s @ %s · stock %s",
                    info.item, _fmtPrice(info.price), stockTxt)
            end
            return string.format("%s: %s · stock %s", info.item, info.state, stockTxt)
        end
    end
    return "Scan auction..."
end

local function _refreshProgressStats(cfg)
    cfg = type(cfg) == "table" and cfg or _readCfg()
    if _ensureNet() and not Auctioneer then
        pcall(function()
            local sm = ReplicatedStorage:FindFirstChild("SharedModules")
            if sm then Auctioneer = require(sm:WaitForChild("Auctioneer", 2)) end
        end)
    end
    local serverTime = _getServerTime()
    _reconcileSnapshot(serverTime)
    stats.auctionGuiOpen = M.IsAuctionGuiOpen()
    stats.lotCount = snapshot and #snapshot.lots or 0
    stats.matchedLots = 0
    stats.availableLots = 0
    stats.matchedStock = nil
    stats.matchedStockText = "-"
    if not snapshot or stats.lotCount < 1 then
        _syncStatsGlobals()
        return
    end

    local stockSum = 0
    local stockHasNum = false
    local stockUnlimited = false
    local firstStockTxt = nil

    for _, lot in ipairs(snapshot.lots) do
        if not _lotIsLive(lot, serverTime) then continue end
        if _lotSelected(lot, cfg) then
            stats.matchedLots += 1
            local price = _lotPriceForBuy(lot, serverTime)
            local okBuy = _lotBuyPriceOk(lot, price, cfg)
            if okBuy then
                stats.availableLots += 1
            end
            local txt = _fmtStockLeft(lot)
            if not firstStockTxt then firstStockTxt = txt end
            if txt == "∞" then
                stockUnlimited = true
            else
                local n = tonumber(txt)
                if n ~= nil then
                    stockSum += n
                    stockHasNum = true
                end
            end
        end
    end

    if stockUnlimited and not stockHasNum then
        stats.matchedStock = "∞"
        stats.matchedStockText = "∞"
    elseif stockHasNum then
        stats.matchedStock = stockSum
        stats.matchedStockText = tostring(stockSum)
    else
        stats.matchedStockText = firstStockTxt or "-"
    end
    _syncStatsGlobals()
end

local function _lotStillBuyable(lot, cfg)
    cfg = type(cfg) == "table" and cfg or _readCfg()
    if not cfg.enabled then return false, "off" end
    if not _lotSelected(lot, cfg) then return false, "unselected" end
    if _lotIsRobuxOnly(lot) then return false, "robux" end
    local serverTime = _getServerTime()
    local okAvail, why = _lotAvailable(lot, serverTime)
    if not okAvail then return false, why or "unavailable" end
    local price = _lotPriceForBuy(lot, serverTime)
    local okPrice, priceOrWhy = _lotBuyPriceOk(lot, price, cfg)
    if not okPrice then return false, priceOrWhy end
    price = priceOrWhy
    local money = _getMoney()
    if type(money) == "number" and money < price then
        return false, "no_money"
    end
    return true, price
end

-- Cooldown beli per-player dari AuctioneerFlags (default 10s)
local function _serverCooldownSec()
    local v = nil
    if AuctionFlags and AuctionFlags.PurchaseCooldownSeconds then
        pcall(function()
            local f = AuctionFlags.PurchaseCooldownSeconds
            v = type(f.Get) == "function" and f:Get() or f
        end)
    end
    v = tonumber(v)
    if not v or v <= 0 or v > 120 then v = 10 end
    return v
end

-- Satu paket: Fire 10×5 = 50 remote
local function _fireBurstOnce(lot, firePrice)
    if not PurchaseLot or type(PurchaseLot.Fire) ~= "function" then
        return 0, "no_remote"
    end
    local perFrame = math.max(1, math.floor(tonumber(PARALLEL_BUY_FIRES) or 10))
    local waves = math.max(1, math.floor(tonumber(FIRE_WAVES) or 5))
    local gap = math.max(0, tonumber(FIRE_GAP_SEC) or 0)
    local fired = 0
    local lastErr = nil
    for w = 1, waves do
        for _ = 1, perFrame do
            local okFire, errFire = pcall(function()
                PurchaseLot:Fire(lot.lotId, firePrice)
            end)
            if okFire then
                fired += 1
            else
                lastErr = errFire
            end
        end
        if gap > 0 and w < waves then
            task.wait(gap)
        end
    end
    return fired, lastErr
end

-- Loop: (50 fire → 0.1s) × 5 → delay 5s → ulang selama masih buyable
local function _startBurstLoop(lot, cfg)
    local lotId = _lotIdKey(lot.lotId)
    if lotId == "" then return false, "no_lot" end
    if burstRunning[lotId] then return true, "bursting" end

    local ok0, price0 = _lotStillBuyable(lot, cfg)
    if not ok0 then return false, price0 end

    burstRunning[lotId] = true
    pendingPurchases[lotId] = {
        item = lot.item,
        price = price0,
        at = os.time(),
    }

    task.spawn(function()
        local cycles = 0
        local repeatN = math.max(1, math.floor(tonumber(BURST_REPEAT) or 5))
        local repeatGap = math.max(0, tonumber(BURST_REPEAT_GAP) or 0.1)
        local longGap = math.max(0.5, tonumber(BURST_GAP_SEC) or 5.0)
        local resultWait = math.max(0.3, tonumber(BURST_RESULT_WAIT) or 1.2)
        local pad = math.max(0, tonumber(COOLDOWN_PAD_SEC) or 0.25)
        local okLoop, errLoop = pcall(function()
            while running and burstRunning[lotId] do
                -- Cooldown server (per-player, 10s) masih jalan → burst pasti ditolak "cooldown".
                -- Tunggu sampai habis dulu, jangan buang 250 fire.
                while running and burstRunning[lotId] and os.clock() < serverCooldownUntil do
                    local left = serverCooldownUntil - os.clock()
                    _setStatus(string.format(
                        "%s: cooldown %.1fs · stock %s",
                        tostring(lot.item or "?"), math.max(0, left), _fmtStockLeft(lot)
                    ))
                    task.wait(math.min(0.25, math.max(0.05, left)))
                end
                if not running or not burstRunning[lotId] then break end

                local cfgNow = _readCfg()
                local ok, priceOrWhy = _lotStillBuyable(lot, cfgNow)
                if not ok then
                    _setStatus(string.format(
                        "%s: %s · stock %s",
                        tostring(lot.item or "?"),
                        tostring(priceOrWhy),
                        _fmtStockLeft(lot)
                    ))
                    _log("buy stop", lotId, priceOrWhy)
                    break
                end

                local firePrice = priceOrWhy
                pendingPurchases[lotId] = {
                    item = lot.item,
                    price = firePrice,
                    at = os.time(),
                }
                lastFireInfo[lotId] = pendingPurchases[lotId]
                local burstStart = os.clock()

                local firedTotal = 0
                local lastErr = nil
                for r = 1, repeatN do
                    if not running or not burstRunning[lotId] then break end
                    -- sudah sukses di paket sebelumnya → sisa paket pasti "cooldown", stop
                    if (lastBuyOkAt[lotId] or 0) >= burstStart then break end
                    local okStill, price2 = _lotStillBuyable(lot, _readCfg())
                    if not okStill then
                        priceOrWhy = price2
                        firedTotal = -1
                        break
                    end
                    firePrice = price2
                    pendingPurchases[lotId] = { item = lot.item, price = firePrice, at = os.time() }
                    lastFireInfo[lotId] = pendingPurchases[lotId]
                    local fired, err = _fireBurstOnce(lot, firePrice)
                    if fired < 1 then
                        lastErr = err
                        break
                    end
                    firedTotal += fired
                    if r < repeatN and repeatGap > 0 then
                        task.wait(repeatGap)
                    end
                end

                local now = os.clock()
                purchaseAt[lotId] = now
                purchaseDebounceAt[lotId] = now
                lastPurchaseAt = now

                if firedTotal < 0 then
                    _setStatus(string.format(
                        "%s: %s · stock %s",
                        tostring(lot.item or "?"),
                        tostring(priceOrWhy),
                        _fmtStockLeft(lot)
                    ))
                    break
                end
                if firedTotal < 1 and (lastBuyOkAt[lotId] or 0) < burstStart then
                    stats.lastError = tostring(lastErr or "fire_fail")
                    _setStatus("Fire gagal: " .. tostring(lastErr or "?"))
                    break
                end

                cycles += 1
                _setStatus(string.format(
                    "Beli %s @ %s · stock %s",
                    tostring(lot.item),
                    _fmtPrice(firePrice),
                    _fmtStockLeft(lot)
                ))
                _log("buy", cycles, lotId, lot.item, firePrice, "fires", firedTotal)

                -- Tunggu PurchaseResult sebentar
                local deadline = os.clock() + resultWait
                while running and burstRunning[lotId] and os.clock() < deadline do
                    if (lastBuyOkAt[lotId] or 0) >= burstStart then break end
                    task.wait(0.1)
                end

                if (lastBuyOkAt[lotId] or 0) >= burstStart then
                    -- sukses → burst berikutnya tepat setelah cooldown server habis
                    cooldownUntil[lotId] = serverCooldownUntil + pad
                    local waitSec = math.max(0.1, (serverCooldownUntil + pad) - os.clock())
                    _log("buy ok → next burst in", string.format("%.1fs", waitSec))
                    task.wait(waitSec)
                else
                    -- tidak ada sukses (server: cooldown / harga / dll) → jeda lalu coba lagi
                    cooldownUntil[lotId] = os.clock() + longGap
                    if lastResultReason and lastResultReason ~= "cooldown" then
                        _setStatus(string.format(
                            "%s: ditolak server (%s) · stock %s",
                            tostring(lot.item), tostring(lastResultReason), _fmtStockLeft(lot)
                        ))
                    end
                    task.wait(longGap)
                end
            end
        end)
        if not okLoop then
            stats.lastError = tostring(errLoop)
            _log("buy loop error", lotId, errLoop)
        end

        burstRunning[lotId] = nil
        if pendingPurchases[lotId] then
            pendingPurchases[lotId] = nil
        end
    end)

    return true, "started"
end

local function _tryBuyLot(lot, price, cfg)
    if not PurchaseLot or type(PurchaseLot.Fire) ~= "function" then
        stats.lastError = "PurchaseLot missing"
        return false, "no_remote"
    end
    local lotId = _lotIdKey(lot.lotId)
    if burstRunning[lotId] then
        return true, "bursting"
    end
    return _startBurstLoop(lot, cfg)
end

local function _tick()
    local cfg = _readCfg()
    _refreshProgressStats(cfg)

    if not cfg.enabled then
        _setStatus("Off")
        return LOOP_SEC
    end
    if not _hasAnySelected(cfg.seed) and not _hasAnySelected(cfg.gear)
        and not _hasAnySelected(cfg.seedpack) and not _hasAnySelected(cfg.egg) then
        _setStatus("Pilih item di dropdown")
        return LOOP_SEC
    end
    if not _ensureNet() then
        _setStatus("Auction remote belum ready")
        return LOOP_SEC * 2
    end
    if not eventsHooked then
        _hookEvents()
    end
    local serverTime = _getServerTime()
    _reconcileSnapshot(serverTime)

    -- Antar-roll: Fire ringan; steal hanya kalau timer belum ada (dari lotId di GC)
    if awaitingNextRoll or not _isAuctionRollLive(serverTime) then
        pcall(_fireRequestSnapshot)
        if not _hasRollTimer() then
            pcall(_stealLiveAuctionState, false)
        end
        _setStatus(_statusForCfg(cfg, _getServerTime()))
        return LOOP_SEC * 2
    end

    local needSnap = not _hasLiveLots()
        or (os.clock() - lastSnapshotAt) > SNAPSHOT_EVERY_SEC
    if needSnap then
        if not _hasLiveLots() then
            pcall(_stealLiveAuctionState, false)
        end
        if not _hasLiveLots() then
            -- fire saja; jangan _requestSnapshot(true) yang wait + steal lagi
            pcall(_fireRequestSnapshot)
        end
    end
    if not _hasLiveLots() and not _hasSnapshotData() then
        _setStatus(_statusForCfg(cfg, _getServerTime()))
        return LOOP_SEC
    end

    serverTime = _getServerTime()
    _reconcileSnapshot(serverTime)

    if #snapshot.lots == 0 then
        _setStatus(_statusForCfg(cfg, serverTime))
        return LOOP_SEC
    end

    local holdStatus = nil
    local lastChance = _isLastChanceMode(cfg)
    local minStock = _lastChanceMinStock(cfg)
    local timeThresh = _lastChanceTimeLeftSec(cfg)
    local nearTime = false
    for _, lot in ipairs(snapshot.lots) do
        if _lotSelected(lot, cfg) then
            local okAvail, why = _lotAvailable(lot, serverTime)
            local price = _lotPriceForBuy(lot, serverTime)
            local okBuy, buyWhy = _lotBuyPriceOk(lot, price, cfg)
            local timeLeft = _lotTimeLeftSec(lot, serverTime)
            local timeTxt = type(timeLeft) == "number" and _fmtRemainClock(timeLeft) or "-"
            if lastChance and type(timeLeft) == "number" and timeLeft <= (timeThresh + 5) then
                nearTime = true
            end
            if okAvail and okBuy then
                local bought, reason = _tryBuyLot(lot, price, cfg)
                if reason == "no_money" then
                    _setStatus("Uang tidak cukup (Candy Corn/Sheckles)")
                    return LOOP_SEC * 3
                end
                if bought or reason == "bursting" or reason == "started" then
                    holdStatus = string.format(
                        "%sBeli %s @ %s · stock %s · time %s",
                        lastChance and "Last Chance · " or "",
                        tostring(lot.item),
                        _fmtPrice(price),
                        _fmtStockLeft(lot),
                        timeTxt
                    )
                else
                    holdStatus = string.format("Gagal beli %s (%s)", tostring(lot.item), tostring(reason or "?"))
                end
            elseif not okAvail then
                holdStatus = string.format("%s: %s", tostring(lot.item), tostring(why or "tidak tersedia"))
            elseif not price then
                holdStatus = string.format("Harga %s tidak terbaca", tostring(lot.item))
            elseif lastChance and (buyWhy == "wait" or buyWhy == "wait_stock") then
                holdStatus = string.format(
                    "Last Chance · %s @ %s · stock left %s / ≤ %d · time left %s / ≤ %ds",
                    _lotDisplayName(lot),
                    _fmtPrice(price),
                    _fmtStockLeft(lot),
                    minStock,
                    timeTxt,
                    timeThresh
                )
            elseif buyWhy == "no_max_price" then
                holdStatus = string.format("%s: set max price (0=skip)", _lotDisplayName(lot))
            elseif buyWhy == "over_max" then
                local maxP = _maxPriceForLot(cfg, lot)
                holdStatus = string.format("%s: %s > max %s",
                    _lotDisplayName(lot), _fmtPrice(price), _fmtPrice(maxP))
            end
        end
    end

    if holdStatus then
        _setStatus(holdStatus)
    else
        _setStatus(_statusForCfg(cfg, serverTime))
    end
    _refreshProgressStats(cfg)
    -- Near end: poll lebih cepat biar tidak miss last seconds
    if lastChance and nearTime then
        return 0.2
    end
    return LOOP_SEC
end

local function _hookEventsImpl()
    if eventsHooked or not _ensureNet() then return end
    local ae = Networking.Auctioneer
    local snapRemote = (ae and ae.Snapshot) or _findAuctionRemoteEvent("Snapshot")
    if not snapRemote then
        stats.lastError = "Auctioneer.Snapshot missing"
        return
    end

    local function onSnap(payload)
        if typeof(payload) == "table" then
            _parseSnapshot(payload)
            _reconcileSnapshot(_getServerTime())
            _refreshProgressStats(_readCfg())
            _log("Snapshot event", snapshot and #snapshot.lots or 0, "lots")
        end
    end
    local function onStock(payload)
        -- u149: hanya update stock map
        if typeof(payload) == "table" and typeof(payload.stock) == "table" then
            stockMap = payload.stock
            if snapshot then snapshot.stock = stockMap end
            task.defer(function()
                _reconcileSnapshot(_getServerTime())
                _refreshProgressStats(_readCfg())
            end)
        end
    end
    -- Server: PurchaseResult(lotId, success, reason). Burst 50 fire → 1 sukses + N×"cooldown".
    -- Jangan hapus pending saat gagal (reply "cooldown" bisa datang setelah pending burst berikutnya).
    local function onResult(lotId, success, reason)
        lotId = _lotIdKey(lotId)
        purchaseDebounceAt[lotId] = nil
        if success == true then
            local pending = pendingPurchases[lotId] or lastFireInfo[lotId]
            pendingPurchases[lotId] = nil
            local now = os.clock()
            lastBuyOkAt[lotId] = now
            serverCooldownUntil = now + _serverCooldownSec()
            lastResultReason = nil
            stats.buys += 1
            stats.lastBuy = {
                lotId = lotId,
                item = pending and pending.item or lotId,
                price = pending and pending.price or nil,
                at = os.time(),
            }
            _setStatus(string.format(
                "Beli %s @ %s",
                tostring(pending and pending.item or lotId),
                (pending and pending.price ~= nil) and _fmtPrice(pending.price) or "?"
            ))
            _log("buy ok", lotId, pending and pending.item, pending and pending.price)
        elseif success == false then
            reason = tostring(reason or "?")
            if reason ~= lastResultReason then
                _log("buy rejected", lotId, reason)
            end
            lastResultReason = reason
            if reason ~= "cooldown" then
                -- alasan lain (harga/stok/uang) → tampilkan supaya kelihatan di UI
                stats.lastError = "server: " .. reason
            end
        end
    end

    if not _connectRemoteEvent(snapRemote, onSnap) then
        stats.lastError = "gagal hook Snapshot.OnClientEvent"
        return
    end
    local reqRemote = ae and ae.RequestSnapshot
    if reqRemote then
        _connectRemoteEvent(reqRemote, onSnap)
    end
    local stockRemote = (ae and ae.StockUpdate) or _findAuctionRemoteEvent("StockUpdate")
    _connectRemoteEvent(stockRemote, onStock)
    local resultRemote = (ae and ae.PurchaseResult) or _findAuctionRemoteEvent("PurchaseResult")
    _connectRemoteEvent(resultRemote, onResult)
    eventsHooked = true
    _log("auction events hooked", #eventConns)
end
_hookEvents = _hookEventsImpl

local function _unhookEvents()
    for _, c in ipairs(eventConns) do
        pcall(function() c:Disconnect() end)
    end
    table.clear(eventConns)
end

function M.Start()
    if running then return end
    running = true
    loopId += 1
    local myId = loopId
    _hookEvents()
    task.spawn(function()
        _requestSnapshot(true)
        while running and loopId == myId do
            local waitSec = LOOP_SEC
            local ok, ret = pcall(_tick)
            if ok and type(ret) == "number" then waitSec = ret end
            task.wait(waitSec)
        end
    end)
end

function M.Stop()
    running = false
    loopId += 1
    table.clear(burstRunning)
    _setStatus("Off")
end

function M.EnsureRunning()
    local cfg = _readCfg()
    if cfg.enabled then M.Start() else M.Stop() end
end

function M.SyncFromState()
    M.EnsureRunning()
end

function M.SyncFromGlobals()
    M.EnsureRunning()
end

function M.GetStats()
    local cfg = _readCfg()
    _refreshProgressStats(cfg)
    return {
        lastStatus = stats.lastStatus,
        lastError = stats.lastError,
        lastBuy = stats.lastBuy,
        buys = stats.buys,
        lotCount = stats.lotCount,
        matchedLots = stats.matchedLots,
        availableLots = stats.availableLots,
        matchedStock = stats.matchedStock,
        matchedStockText = stats.matchedStockText,
        snapshotAge = (snapshot and lastSnapshotAt > 0) and math.max(0, os.clock() - lastSnapshotAt) or nil,
        auctionGuiOpen = stats.auctionGuiOpen,
        enabled = cfg.enabled,
        mode = cfg.mode,
        last_chance_min_stock = cfg.last_chance_min_stock,
        last_chance_time_left_sec = cfg.last_chance_time_left_sec,
        running = running,
        max_prices = cfg.max_prices,
        lastResultReason = lastResultReason,
        serverCooldownLeft = math.max(0, serverCooldownUntil - os.clock()),
        reqNilStreak = reqNilStreak,
        reqNextIn = math.max(0, reqNextAllowedAt - os.clock()),
    }
end

function M.GetStatusLine()
    local st = M.GetStats()
    return "Status: " .. tostring(st.lastStatus or "Ready")
end

function M.GetDetailsLine()
    local st = M.GetStats()
    local parts = {
        string.format(
            "Lots %d · Match %d · Buyable %d · Stock %s · Purchases %d",
            tonumber(st.lotCount) or 0,
            tonumber(st.matchedLots) or 0,
            tonumber(st.availableLots) or 0,
            tostring(st.matchedStockText or "-"),
            tonumber(st.buys) or 0
        ),
    }
    local remain = _rollRefreshRemain(_getServerTime())
    if remain ~= nil then
        if (not snapshot or #(snapshot.lots or {}) < 1) then
            parts[#parts + 1] = "Next " .. _fmtRemainClock(remain)
        elseif not _isAuctionRollLive(_getServerTime()) then
            parts[#parts + 1] = "Next " .. _fmtRemainClock(remain)
        else
            parts[#parts + 1] = "Ends " .. _fmtRemainClock(remain)
        end
    end
    if type(st.lastBuy) == "table" then
        parts[#parts + 1] = string.format(
            "Last: %s @ %s",
            tostring(st.lastBuy.item or "?"),
            st.lastBuy.price ~= nil and _fmtPrice(st.lastBuy.price) or "?"
        )
    elseif st.lastError and st.lastError ~= "" and not st.running then
        parts[#parts + 1] = "Err: " .. tostring(st.lastError)
    end
    return table.concat(parts, " · ")
end

function M.GetStatusText()
    return M.GetStatusLine() .. "\n" .. M.GetDetailsLine()
end

function M.RefreshSnapshot()
    return _bootstrapAuction(SNAPSHOT_WAIT_SEC)
end

function M.AnalyzeLots()
    _ensureAuctioneer()
    local serverTime = _getServerTime()
    local out = {}
    if snapshot and snapshot.lots then
        for _, lot in ipairs(snapshot.lots) do
            out[#out + 1] = _analyzeLot(lot, serverTime)
        end
    end
    return out
end

function M.ProbeSnapshot()
    _hookEvents()
    local ok = M.RefreshSnapshot()
    local n = snapshot and #snapshot.lots or 0
    ok = ok or n > 0
    print("[GAG2-ABA] ProbeSnapshot ok=", ok, "lots=", n, "err=", stats.lastError)
    return ok, n, stats.lastError
end

-- Stats poller: OFF = hanya baca cache + Snapshot event (tanpa getgc).
-- ON  = RequestSnapshot ringan; getgc hanya lewat _stealAllowed + rate limit.
local statsLoopId = 0

local function _startStatsPoller()
    statsLoopId += 1
    local myId = statsLoopId
    task.spawn(function()
        -- Boot ringan: hook event dulu (Snapshot/StockUpdate broadcast), lalu 1x RequestSnapshot.
        -- Server hanya jawab RequestSnapshot sekali per join → pastikan game siap sebelum request pertama.
        pcall(function()
            if _ensureNet() then
                _hookEvents()
                _waitGameAuctioneer(8)
                pcall(_fireRequestSnapshot)
            end
        end)

        while statsLoopId == myId do
            local cfg = _readCfg()
            if cfg.enabled ~= true then
                -- OFF: status dari cache; Snapshot.OnClientEvent tetap isi kalau sudah hook.
                if eventsHooked then
                    pcall(function()
                        _reconcileSnapshot(_getServerTime())
                        _refreshProgressStats(cfg)
                    end)
                end
                if not running then
                    _setStatus("Off")
                end
                task.wait(5)
                continue
            end

            -- ON
            if _ensureNet() then
                if not eventsHooked then _hookEvents() end
                local st = _getServerTime()
                _reconcileSnapshot(st)
                -- Snapshot remote ringan OK. getgc hanya kalau belum ada lot & rate-limited.
                if awaitingNextRoll or not _isAuctionRollLive(st) then
                    pcall(_fireRequestSnapshot)
                    if running and not _hasRollTimer() then
                        pcall(_stealLiveAuctionState, false)
                    end
                else
                    local stale = not _hasLiveLots()
                        or (os.clock() - lastSnapshotAt) > SNAPSHOT_EVERY_SEC
                    if stale then
                        pcall(_fireRequestSnapshot)
                        if running and not _hasLiveLots() then
                            pcall(_stealLiveAuctionState, false)
                        end
                    end
                end
                _reconcileSnapshot(_getServerTime())
                _refreshProgressStats(cfg)
                if not running then
                    _setStatus(_statusForCfg(cfg, _getServerTime()))
                end
            else
                _setStatus("Auction remote belum ready")
            end
            task.wait(1.5)
        end
    end)
end

_startStatsPoller()

pcall(function() M.SyncFromState() end)

return M
 end,               required = false },
    { key = "SectionAutoBuyAuction",   name = "Section Auto Buy Auction", factory = function() -- section_auto_buy_auction.lua — Auto Buy Auction (max price per item)

local G = (getgenv and getgenv()) or _G
local M = {}

local function parseScaledPrice(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then return nil end
    local suffixes = {
        { "juta", 1000000 }, { "jt", 1000000 },
        { "ribu", 1000 }, { "rb", 1000 },
        { "b", 1000000000 }, { "m", 1000000 }, { "k", 1000 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then return math.max(0, math.floor(n * mult)) end
        end
    end
    local n = tonumber(txt)
    if n then return math.max(0, math.floor(n)) end
    return nil
end

local function formatScaledPrice(n)
    n = math.floor(tonumber(n) or 0)
    if n <= 0 then return "0" end
    if n >= 1000000000 then return string.format("%.2fB", n / 1000000000) end
    if n >= 1000000 then return string.format("%.2fM", n / 1000000) end
    if n >= 1000 then return string.format("%.1fK", n / 1000) end
    return tostring(n)
end

function M.parseMaxPrice(raw)
    if type(raw) == "number" then
        return math.max(0, math.floor(raw))
    end
    local parsed = parseScaledPrice(raw)
    if parsed ~= nil then return parsed end
    return math.max(0, math.floor(tonumber(raw) or 0))
end

function M.formatMaxPrice(n)
    return formatScaledPrice(n)
end

local function cleanMap(map)
    local out = {}
    if type(map) ~= "table" then return out end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            local key = tostring(k)
            if key ~= "" then out[key] = true end
        end
    end
    return out
end

local function normKey(s)
    return tostring(s or ""):lower():gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
end

local function selectedKeys(selMap)
    local keys = {}
    if type(selMap) ~= "table" then return keys end
    for k, v in pairs(selMap) do
        if v == true then
            keys[#keys + 1] = tostring(k)
        end
    end
    table.sort(keys, function(a, b)
        return normKey(a) < normKey(b)
    end)
    return keys
end

local function loadItemPrices(raw)
    local out = {}
    if type(raw) ~= "table" then return out end
    for k, v in pairs(raw) do
        local name = tostring(k or "")
        if name ~= "" then
            out[name] = M.parseMaxPrice(v)
        end
    end
    return out
end

local function lookupPrice(prices, name)
    name = tostring(name or "")
    if name == "" or type(prices) ~= "table" then return nil end
    if prices[name] ~= nil then return M.parseMaxPrice(prices[name]) end
    local nk = normKey(name)
    for k, v in pairs(prices) do
        if normKey(k) == nk then return M.parseMaxPrice(v) end
    end
    return nil
end

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto = ctx.getAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local saveNow = ctx.saveNow
    local registerFlush = ctx.registerFlush
    local cleanSelectedMap = ctx.cleanSelectedMap or cleanMap
    local arrayToMap = ctx.arrayToMap
    local mapToArrayFn = ctx.mapToArray
    local PlantListView = ctx.PlantListView or G.PlantListView
    local ShopListView = ctx.ShopListView or G.ShopListView

    if type(getAuto) ~= "function" or type(patchAutoOnly) ~= "function" then
        warn("[GAG2] SectionAutoBuyAuction: missing getAuto/patchAutoOnly")
        return
    end

    local BUY = getAuto("buy")
    local A = type(BUY.auction) == "table" and BUY.auction or {}
    local enabled = (A.enabled == true)
    local mode = (tostring(A.mode or "normal"):lower() == "last_chance") and "last_chance" or "normal"
    local lastChanceMinStock = math.floor(tonumber(A.last_chance_min_stock) or 100)
    if lastChanceMinStock < 1 then lastChanceMinStock = 1 end
    local lastChanceTimeLeftSec = math.floor(tonumber(A.last_chance_time_left_sec) or 20)
    if lastChanceTimeLeftSec < 1 then lastChanceTimeLeftSec = 1 end

    local function catItems(key)
        local cat = type(A[key]) == "table" and A[key] or {}
        if type(cat.items) == "table" and cat.items[1] ~= nil and arrayToMap then
            return cleanSelectedMap(arrayToMap(cat.items))
        end
        return cleanSelectedMap(cat.items)
    end

    local SEL_SEED = catItems("seed")
    local SEL_GEAR = catItems("gear")
    local SEL_SEEDPACK = catItems("seedpack")
    local SEL_EGG = catItems("egg")

    local ITEM_PRICES = loadItemPrices(A.item_prices)

    -- Migrasi: harga kategori lama → isi harga item yang belum punya price
    local function migrateCatMax(selMap, catKey)
        local cat = type(A[catKey]) == "table" and A[catKey] or {}
        local catMax = M.parseMaxPrice(cat.max_price)
        if catMax <= 0 then return end
        for _, name in ipairs(selectedKeys(selMap)) do
            if lookupPrice(ITEM_PRICES, name) == nil then
                ITEM_PRICES[name] = catMax
            end
        end
    end
    migrateCatMax(SEL_SEED, "seed")
    migrateCatMax(SEL_GEAR, "gear")
    migrateCatMax(SEL_SEEDPACK, "seedpack")
    migrateCatMax(SEL_EGG, "egg")

    local priceHosts = {} -- [slot] = Frame
    local priceRowApis = {} -- [slot] = { [itemName] = setGet }

    local function pruneItemPrices()
        local keep = {}
        local function mark(sel)
            for _, name in ipairs(selectedKeys(sel)) do
                keep[normKey(name)] = name
            end
        end
        mark(SEL_SEED)
        mark(SEL_GEAR)
        mark(SEL_SEEDPACK)
        mark(SEL_EGG)
        local nextPrices = {}
        for k, v in pairs(ITEM_PRICES) do
            local canon = keep[normKey(k)]
            if canon then
                nextPrices[canon] = M.parseMaxPrice(v)
            end
        end
        ITEM_PRICES = nextPrices
    end

    local function pullPricesFromUI()
        for _, slotApis in pairs(priceRowApis) do
            for name, setGet in pairs(slotApis) do
                if type(setGet) == "function" then
                    local ok, txt = pcall(setGet)
                    if ok then
                        ITEM_PRICES[name] = M.parseMaxPrice(txt)
                    end
                end
            end
        end
    end

    local function buildAuction()
        local enableApi = G.__GAG2_BUY_AUCTION_ENABLE_API or rawget(_G, "__GAG2_BUY_AUCTION_ENABLE_API")
        if type(enableApi) == "table" and type(enableApi.get) == "function" then
            enabled = (enableApi.get() == true)
        end
        pullPricesFromUI()
        pruneItemPrices()
        local pricesCopy = {}
        for k, v in pairs(ITEM_PRICES) do
            pricesCopy[k] = M.parseMaxPrice(v)
        end
        return {
            enabled = enabled,
            mode = mode,
            last_chance_min_stock = lastChanceMinStock,
            last_chance_time_left_sec = lastChanceTimeLeftSec,
            item_prices = pricesCopy,
            seed = { items = mapToArrayFn(SEL_SEED), max_price = 0 },
            gear = { items = mapToArrayFn(SEL_GEAR), max_price = 0 },
            seedpack = { items = mapToArrayFn(SEL_SEEDPACK), max_price = 0 },
            egg = { items = mapToArrayFn(SEL_EGG), max_price = 0 },
