        _G.AUTO_BUY_AUCTION_ENABLED = p.enabled
        G.AUTO_BUY_AUCTION_MODE = p.mode
        _G.AUTO_BUY_AUCTION_MODE = p.mode
        G.AUTO_BUY_AUCTION_LAST_CHANCE_MIN_STOCK = p.last_chance_min_stock
        _G.AUTO_BUY_AUCTION_LAST_CHANCE_MIN_STOCK = p.last_chance_min_stock
        G.AUTO_BUY_AUCTION_LAST_CHANCE_TIME_LEFT_SEC = p.last_chance_time_left_sec
        _G.AUTO_BUY_AUCTION_LAST_CHANCE_TIME_LEFT_SEC = p.last_chance_time_left_sec
        G.AUTO_BUY_AUCTION_ITEM_PRICES = p.item_prices
        _G.AUTO_BUY_AUCTION_ITEM_PRICES = p.item_prices
        G.AUTO_BUY_AUCTION_SEED_MAX_PRICE = 0
        _G.AUTO_BUY_AUCTION_SEED_MAX_PRICE = 0
        G.AUTO_BUY_AUCTION_GEAR_MAX_PRICE = 0
        _G.AUTO_BUY_AUCTION_GEAR_MAX_PRICE = 0
        G.AUTO_BUY_AUCTION_SEEDPACK_MAX_PRICE = 0
        _G.AUTO_BUY_AUCTION_SEEDPACK_MAX_PRICE = 0
        G.AUTO_BUY_AUCTION_EGG_MAX_PRICE = 0
        _G.AUTO_BUY_AUCTION_EGG_MAX_PRICE = 0
