    end

    local BUY_LIST_SORT = { sortBy = "rarity" }
    local body = ui:CreateSection("Auto Buy Auction", false)

    local _, statusLabel = ui:CreateRowLabel(body, "Status: Ready", nil, nil, "info")
    local _, detailsLabel = ui:CreateRowLabel(body, "Lots 0 · Match 0 · Buyable 0 · Stock - · Purchases 0", nil, nil, "info")

