    local function makePriceHost(order)
        local host = Instance.new("Frame")
        host.Name = "ItemPriceHost"
        host.BackgroundTransparency = 1
        host.Size = UDim2.new(1, 0, 0, 0)
        host.AutomaticSize = Enum.AutomaticSize.Y
        host.LayoutOrder = order or (#body:GetChildren() + 1)
        host.Visible = false
        host.Parent = body

        local layout = Instance.new("UIListLayout")
        layout.FillDirection = Enum.FillDirection.Vertical
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 2)
        layout.Parent = host
        return host
    end

    local function rebuildPriceRows(slot, selMap)
        local host = priceHosts[slot]
        if not host then return end

        pullPricesFromUI()

        for _, ch in ipairs(host:GetChildren()) do
            if ch:IsA("GuiObject") and ch.Name ~= "UIListLayout" then
                ch:Destroy()
            end
        end
        priceRowApis[slot] = {}

        local keys = selectedKeys(selMap)
        if #keys < 1 then
            host.Visible = false
            return
        end
        host.Visible = true

        for i, name in ipairs(keys) do
            local cur = lookupPrice(ITEM_PRICES, name)
            if cur == nil then cur = 0 end
            ITEM_PRICES[name] = cur
            local captured = name
            local _, setGet = ui:CreateRowInput(host, tostring(name), M.formatMaxPrice(cur), function(txt)
                ITEM_PRICES[captured] = M.parseMaxPrice(txt)
                saveAuction()
                syncModule()
            end, false, i)
            priceRowApis[slot][name] = setGet
        end
    end

    local nextOrder = 10
    local function catBlock(slot, ddLabel, getItems, selRefGetter, selRefSetter)
        -- urutan: label → dropdown category → input harga item
        local orderTitle = nextOrder
        local orderDd = nextOrder + 1
        local orderHost = nextOrder + 2
        nextOrder += 3

        local title = SLOT_PRICE_TITLE[slot] or ("—— Auction max price · " .. tostring(slot) .. " ——")
        ui:CreateRowLabel(body, title, PRICE_HINT, orderTitle, "info")

        ui:CreateRowDropdown(body, {
            label = ddLabel,
            placeholder = "Select Options",
            mode = "multi",
            preserveItemOrder = true,
            order = orderDd,
            getItems = getItems,
            initial = selRefGetter(),
            onChanged = function(_, selectedMap)
                local cleaned = cleanSelectedMap(selectedMap)
                selRefSetter(cleaned)
                rebuildPriceRows(slot, cleaned)
                saveAuction()
                syncModule()
            end,
        })

        priceHosts[slot] = makePriceHost(orderHost)
        rebuildPriceRows(slot, selRefGetter())
    end

    catBlock("seed", "Select Seed", function()
        if PlantListView and type(PlantListView.buildSeedItems) == "function" then
