    end, function() return SEL_SEED end, function(v) SEL_SEED = v end)

    catBlock("gear", "Select Gear", function()
        if ShopListView and type(ShopListView.buildGearItems) == "function" then
            return ShopListView.buildGearItems(BUY_LIST_SORT) or {}
        end
        return {}
    end, function() return SEL_GEAR end, function(v) SEL_GEAR = v end)

    catBlock("seedpack", "Select Seed Pack", function()
