local function _refreshGiftStatusUi(profile)
    if profile == "once" then
        local onceFn = G.__GAG2_REFRESH_GIFT_ONCE_STATUS or rawget(_G, "__GAG2_REFRESH_GIFT_ONCE_STATUS")
        if type(onceFn) == "function" then
            pcall(onceFn)
        end
        return
    end
    if profile == "loop" then
        local loopFn = G.__GAG2_REFRESH_GIFT_LOOP_STATUS or rawget(_G, "__GAG2_REFRESH_GIFT_LOOP_STATUS")
        if type(loopFn) == "function" then
            pcall(loopFn)
        end
        return
    end
    local onceFn = G.__GAG2_REFRESH_GIFT_ONCE_STATUS or rawget(_G, "__GAG2_REFRESH_GIFT_ONCE_STATUS")
    if type(onceFn) == "function" then
        pcall(onceFn)
    end
    local loopFn = G.__GAG2_REFRESH_GIFT_LOOP_STATUS or rawget(_G, "__GAG2_REFRESH_GIFT_LOOP_STATUS")
    if type(loopFn) == "function" then
        pcall(loopFn)
    end
end

local function _statusProfileKey(profile)
    if profile == "once" or profile == "loop" then
        return profile
    end
    if St.sendJobRunning then
        return "once"
    end
    if St.autoSendRunning and cfg.auto_send == true then
        return "loop"
    end
    if _normalizeSendListMode(cfg.send_list_mode) == "send_total" then
        return "once"
    end
    return St.lastStatusProfile or "loop"
end

_statusProfileKey = _statusProfileKey

local function _formatPriceSendProgress(sentUnits, sentPrice, targetMin, targetMax, batchNum)
    local parts = {
        tostring(sentUnits or 0) .. " buah",
        _formatSellPrice(sentPrice or 0),
        _formatSellPrice(targetMin or 0) .. "–" .. _formatSellPrice(targetMax or 0),
    }
    local msg = "Progress: " .. table.concat(parts, " | ")
    if type(batchNum) == "number" and batchNum > 0 then
        msg = msg .. " (batch " .. tostring(batchNum) .. ")"
    end
    return msg
end

local function _setStatus(msg, err, profile)
    local text = tostring(msg or "")
    profile = _statusProfileKey(profile)
    stats.lastError = err
    if profile == "once" or profile == "loop" then
        St.lastStatusProfile = profile
        if profile == "once" then
            stats.lastStatusOnce = text
            G.AUTO_GIFT_ONCE_STATUS = text
            _G.AUTO_GIFT_ONCE_STATUS = text
        else
            stats.lastStatusLoop = text
            G.AUTO_GIFT_LOOP_STATUS = text
            _G.AUTO_GIFT_LOOP_STATUS = text
        end
        stats.lastStatus = text
        G.AUTO_GIFT_STATUS = text
        _G.AUTO_GIFT_STATUS = text
        _refreshGiftStatusUi(profile)
    else
        stats.lastStatus = text
    end
    if _dbg() and err ~= nil then
        _log("status err:", err)
    end
end

_setStatus = _setStatus

local function _waitSendCooldownWithStatus(profile)
    profile = profile or _statusProfileKey()
    while true do
        local remain = _effectiveSendCooldownRemain()
        if remain <= 0.01 then
            break
        end
        _setStatus("Cooldown kirim berikutnya: " .. tostring(math.ceil(remain)) .. "s...", nil, profile)
        task.wait(math.min(remain, 0.4))
    end
end

local function _waitForNextSend(profile)
    _waitSendCooldownWithStatus(profile)
end

local function _waitSendCooldown(profile)
    _waitSendCooldownWithStatus(profile)
end

local function _canonicalCategory(cat)
    if cat == nil then return "" end
    local key = tostring(cat)
    if key == "" then return "" end
    return SAVE_CATEGORY_ALIASES[key] or key
end

local function _categoryLabel(key)
    key = tostring(key or "")
    if key == "" then return key end
    return key:gsub("(%l)(%u)", "%1 %2")
end

local function _findCatalogModule()
    if St.catalogModuleInst and St.catalogModuleInst.Parent then
        return St.catalogModuleInst
    end
    local function pick(inst)
        if inst and inst:IsA("ModuleScript") and inst.Name == "MailboxItemCatalog" then
            St.catalogModuleInst = inst
            return inst
        end
        return nil
    end
    local function tryKnownPaths(root)
        if not root then return nil end
        local controllers = root:FindFirstChild("Controllers")
        local mailboxCtrl = controllers and controllers:FindFirstChild("MailboxController")
        local m = mailboxCtrl and pick(mailboxCtrl:FindFirstChild("MailboxItemCatalog"))
        if m then return m end
        m = pick(root:FindFirstChild("MailboxItemCatalog", true))
        if m then return m end
        return nil
    end
    local function waitMailboxCatalog(root, waitSec)
        if not root then return nil end
        local ok, inst = pcall(function()
            local controllers = root:WaitForChild("Controllers", waitSec)
            local mailboxCtrl = controllers:WaitForChild("MailboxController", waitSec)
            return mailboxCtrl:WaitForChild("MailboxItemCatalog", waitSec)
        end)
        if ok then
            return pick(inst)
        end
        return nil
    end

    -- StarterPlayerScripts (source template — available before PlayerScripts clone)
    local sps = StarterPlayer:FindFirstChild("StarterPlayerScripts")
    if sps then
        local m = tryKnownPaths(sps)
        if m then return m end
    end

    local ps = LP:FindFirstChild("PlayerScripts")
    if not ps then
        local ok, child = pcall(function()
            return LP:WaitForChild("PlayerScripts", 8)
        end)
        if ok then ps = child end
    end
    if ps then
        local m = tryKnownPaths(ps)
        if m then return m end
        m = waitMailboxCatalog(ps, 6)
        if m then return m end
    end

    if not sps then
        local ok, child = pcall(function()
            return StarterPlayer:WaitForChild("StarterPlayerScripts", 6)
        end)
        if ok then sps = child end
    end
    if sps then
        local m = waitMailboxCatalog(sps, 6)
        if m then return m end
    end
    local pg = LP:FindFirstChild("PlayerGui")
    if pg then
        local m = pick(pg:FindFirstChild("MailboxItemCatalog", true))
        if m then return m end
    end
    local cm = ReplicatedStorage:FindFirstChild("ClientModules")
    if cm then
        local m = pick(cm:FindFirstChild("MailboxItemCatalog", true))
        if m then return m end
    end
    local shared = ReplicatedStorage:FindFirstChild("SharedModules")
    if shared then
        local m = pick(shared:FindFirstChild("MailboxItemCatalog", true))
        if m then return m end
    end
    return pick(ReplicatedStorage:FindFirstChild("MailboxItemCatalog", true))
end

local function _invokeCatalog(methodName, ...)
    if not St.MailboxCatalog then return false, nil end
    local fn = St.MailboxCatalog[methodName]
    if type(fn) ~= "function" then return false, nil end
    local a1, a2, a3, a4 = ...
    local ok, res = pcall(fn, a1, a2, a3, a4)
    if ok then return true, res end
    ok, res = pcall(fn, St.MailboxCatalog, a1, a2, a3, a4)
    if ok then return true, res end
    return false, nil
end

local function _normalizeCategoryList(cats)
    if type(cats) ~= "table" then return {} end
    if #cats > 0 then
        local out = {}
        for _, key in ipairs(cats) do
            if type(key) == "string" and key ~= "" then
                out[#out + 1] = key
            end
        end
        return out
    end
    local out = {}
    for key, val in pairs(cats) do
        if type(val) == "string" and val ~= "" then
            out[#out + 1] = val
        elseif type(key) == "string" and key ~= "" and (val == true or val == 1) then
            out[#out + 1] = key
        end
    end
    table.sort(out)
    return out
end

local function _catalogIsGiftable(cat)
    if not St.MailboxCatalog then return false end
    cat = tostring(cat or "")
    for _, key in ipairs(_normalizeCategoryList(St.MailboxCatalog.Categories)) do
        if key == cat then return true end
    end
    local ok, res = _invokeCatalog("IsGiftable", cat)
    return ok and res == true
end

local function _isExtraGiftCategory(cat)
    return EXTRA_GIFT_CATEGORIES[_canonicalCategory(cat)] == true
end

local function _categoryAllowedForGift(cat)
    return _catalogIsGiftable(cat) or _isExtraGiftCategory(cat)
end

local function _ensureMailboxCatalog(force)
    if force then
        St.MailboxCatalog = nil
        St.catalogLoadedFromGame = false
        St.catalogModuleInst = nil
    end
    if St.MailboxCatalog and St.catalogLoadedFromGame then
        return true
    end
    local modScript = _findCatalogModule()
    if modScript then
        local ok, mod = pcall(require, modScript)
        if ok and type(mod) == "table" and type(mod.Categories) == "table" then
            St.MailboxCatalog = mod
            St.catalogLoadedFromGame = true
            return true
        end
    end
    return false
end

local function _catalogCategories()
    if not _ensureMailboxCatalog() then return {} end
    return _normalizeCategoryList(St.MailboxCatalog.Categories)
end

local function _remoteCallable(remote)
    if remote == nil then return false end
    if type(remote) == "table" then
        return type(remote.Fire) == "function" or type(remote.Invoke) == "function"
    end
    if typeof(remote) == "Instance" then
        return remote:IsA("RemoteFunction") or remote:IsA("RemoteEvent")
    end
    return false
end

local function _callNetworkingRemote(remote, ...)
    if not _remoteCallable(remote) then
        return false, "no_remote"
    end
    local args = table.pack(...)

    local function invoke()
        if type(remote) == "table" then
            if type(remote.Fire) == "function" then
                if args.n > 0 then
                    return remote:Fire(table.unpack(args, 1, args.n))
                end
                return remote:Fire()
            end
            if type(remote.Invoke) == "function" then
                if args.n > 0 then
                    return remote:Invoke(table.unpack(args, 1, args.n))
                end
                return remote:Invoke()
            end
        end
        if typeof(remote) == "Instance" then
            if remote:IsA("RemoteFunction") then
                if args.n > 0 then
                    return remote:InvokeServer(table.unpack(args, 1, args.n))
                end
                return remote:InvokeServer()
            end
            if remote:IsA("RemoteEvent") then
                if args.n > 0 then
                    remote:FireServer(table.unpack(args, 1, args.n))
                else
                    remote:FireServer()
                end
                return nil
            end
        end
        error("networking remote not callable")
    end

    local results = table.pack(pcall(invoke))
    if not results[1] then
        return false, results[2]
    end
    return true, results[2], results[3], results[4], results[5]
end

local function _clearNetworkingCache()
    Net.Networking = nil
    Net.SendBatch = nil
    Net.Lookup = nil
    Net.List = nil
    Net.Claim = nil
    Net.ClaimAll = nil
    Net.ClaimAllProgress = nil
    Net.ClaimAllFinished = nil
    Net.OpenInbox = nil
    Net.IndexProbe = nil
    Net.Updated = nil
    Net.MagicMailList = nil
    Net.MagicMailClaim = nil
    Net.MagicMailUpdated = nil
    Net.BackpackGetLayout = nil
    Net.BackpackPromoteFruit = nil
end

local function _bindMailboxNetworking(net)
    if type(net) ~= "table" then return end
    if type(net.Mailbox) == "table" then
        local mb = net.Mailbox
        Net.SendBatch = mb.SendBatch
        Net.Lookup = mb.LookupPlayer
        Net.List = mb.List
        Net.Claim = mb.Claim
        Net.ClaimAll = mb.ClaimAll
        Net.ClaimAllProgress = mb.ClaimAllProgress
        Net.ClaimAllFinished = mb.ClaimAllFinished
        Net.OpenInbox = mb.OpenInbox
        Net.IndexProbe = mb.IndexProbe
        Net.Updated = mb.Updated
    end
    if type(net.MagicMail) == "table" then
        Net.MagicMailList = net.MagicMail.List
        Net.MagicMailClaim = net.MagicMail.Claim
        Net.MagicMailUpdated = net.MagicMail.Updated
    end
    if type(net.Backpack) == "table" then
        Net.BackpackGetLayout = net.Backpack.GetLayout
        Net.BackpackPromoteFruit = net.Backpack.PromoteFruit
    end
end

local function _ensureNetworking()
    if Net.Networking and _remoteCallable(Net.SendBatch) then
        _bindMailboxNetworking(Net.Networking)
        return true
    end
    local ok, net = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules"):WaitForChild("Networking"))
    end)
    if ok and type(net) == "table" then
        Net.Networking = net
        _bindMailboxNetworking(net)
    end
    return _remoteCallable(Net.SendBatch)
end

local function _ensureGiftingNetworking()
    if not _ensureNetworking() then return false end
    if type(Net.Networking) ~= "table" or type(Net.Networking.Gifting) ~= "table" then
        return false
    end
    Net.GiftingPrompted = Net.Networking.Gifting.Prompted
    Net.GiftingResponse = Net.Networking.Gifting.Response
    Net.GiftingFakeFriendRequest = Net.Networking.Gifting.FakeFriendRequest
    Net.GiftingFakeFriendRequestResponse = Net.Networking.Gifting.FakeFriendRequestResponse
    return Net.GiftingPrompted ~= nil
        and Net.GiftingPrompted.OnClientEvent ~= nil
        and _remoteCallable(Net.GiftingResponse)
end

local function _ensureFakeFriendNetworking()
    if not _ensureGiftingNetworking() then return false end
    return Net.GiftingFakeFriendRequest ~= nil
        and Net.GiftingFakeFriendRequest.OnClientEvent ~= nil
        and _remoteCallable(Net.GiftingFakeFriendRequestResponse)
end

local function _hideGiftingUi()
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return end
    local gifting = pg:FindFirstChild("Gifting")
    if gifting then
        gifting.Enabled = false
    end
end

local function _dismissFakeFriendRequestUi(otherPlayer)
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return end
    local frGui = pg:FindFirstChild("FriendRequest")
    if not frGui then return end
    frGui.Enabled = false
    local frame = frGui:FindFirstChild("Frame")
    if not frame then return end
    if otherPlayer then
        local clone = frame:FindFirstChild("FriendRequest_" .. tostring(otherPlayer.UserId))
        if clone then clone:Destroy() end
    end
    for _, ch in ipairs(frame:GetChildren()) do
        if ch.Name:match("^FriendRequest_") then
            ch:Destroy()
        end
    end
end

local function _declineFakeFriendRequest(otherPlayer)
    if typeof(otherPlayer) ~= "Instance" or not otherPlayer:IsA("Player") then return end
    if not otherPlayer.Parent then return end
    if not _ensureFakeFriendNetworking() then return end
    pcall(_callNetworkingRemote, Net.GiftingFakeFriendRequestResponse, otherPlayer, false)
    _dismissFakeFriendRequestUi(otherPlayer)
end

local function _onFakeFriendRequest(otherPlayer)
    if cfg.suppress_fake_friend_request == false then return end
    _declineFakeFriendRequest(otherPlayer)
end

local function _bindFriendRequestUiGuard()
    if St.friendRequestUiConn then return true end
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return false end
    local frGui = pg:FindFirstChild("FriendRequest")
    if not frGui then return false end
    local frame = frGui:FindFirstChild("Frame")
    if not frame then return false end

    St.friendRequestUiConn = frame.ChildAdded:Connect(function(ch)
        if cfg.suppress_fake_friend_request == false then return end
        if not ch.Name:match("^FriendRequest_") then return end
        task.defer(function()
            if ch.Parent then ch:Destroy() end
            frGui.Enabled = false
            local otherId = ch.Name:match("^FriendRequest_(%d+)$")
            if otherId then
                local other = Players:GetPlayerByUserId(tonumber(otherId) or 0)
                if other then
                    pcall(_declineFakeFriendRequest, other)
                end
            end
        end)
    end)
    return true
end

local function _bindFakeFriendSuppress()
    if St.fakeFriendConn then
        pcall(function() St.fakeFriendConn:Disconnect() end)
        St.fakeFriendConn = nil
    end
    if cfg.suppress_fake_friend_request == false then return false end
    if not _ensureFakeFriendNetworking() then return false end
    St.fakeFriendConn = Net.GiftingFakeFriendRequest.OnClientEvent:Connect(_onFakeFriendRequest)
    _bindFriendRequestUiGuard()
    return true
end

local function _onNormalGiftPrompted(senderPlayer, _itemName)
    if cfg.auto_accept_gift ~= true then return end
    if typeof(senderPlayer) ~= "Instance" or not senderPlayer:IsA("Player") then return end
    if not senderPlayer.Parent then return end
    if not _ensureGiftingNetworking() then return end

    task.defer(function()
        if cfg.auto_accept_gift ~= true then return end
        if not senderPlayer.Parent then return end
        local ok = _callNetworkingRemote(Net.GiftingResponse, senderPlayer, true)
        if ok then
            stats.acceptedNormalGifts = (stats.acceptedNormalGifts or 0) + 1
            _hideGiftingUi()
            _setStatus("Accepted gift from " .. tostring(senderPlayer.Name))
            _log("accepted normal gift from", senderPlayer.Name, _itemName)
        else
            _log("accept normal gift failed from", senderPlayer.Name)
        end
    end)
end

local function _bindNormalGiftAccept()
    if St.acceptGiftConn then
        pcall(function() St.acceptGiftConn:Disconnect() end)
        St.acceptGiftConn = nil
    end
    if not _ensureGiftingNetworking() then return false end
    St.acceptGiftConn = Net.GiftingPrompted.OnClientEvent:Connect(_onNormalGiftPrompted)
    return true
end

local function _applyInboxData(data)
    if type(data) ~= "table" then
        table.clear(St.inboxGifts)
        St.inboxDirty = false
        return
    end

    local box = data.Mailbox
    if type(box) ~= "table" then
        if data.PendingInvites == nil and data.Badge == nil and data.Replyable == nil then
            box = data
        else
            return
        end
    end

    table.clear(St.inboxGifts)
    for giftId, payload in pairs(box) do
        local key = tostring(giftId)
        if key ~= "" and type(payload) == "table" then
            St.inboxGifts[key] = payload
        end
    end
    St.inboxDirty = false
    St.lastInboxRefreshAt = os.clock()
end

local function _applyMagicMailData(data)
    table.clear(St.magicMails)
    if type(data) ~= "table" then
        St.magicMailDirty = false
        return
    end
    for mailId, payload in pairs(data) do
        local key = tostring(mailId)
        if key ~= "" and type(payload) == "table" and type(payload.Item) == "table" then
            St.magicMails[key] = payload
        end
    end
    St.magicMailDirty = false
end

local function _refreshInboxFromServer()
    for _ = 1, 4 do
        if not _ensureNetworking() or not _remoteCallable(Net.OpenInbox) then
            _clearNetworkingCache()
            task.wait(0.25)
            continue
        end

        local ok, data = _callNetworkingRemote(Net.OpenInbox)
        if ok and type(data) == "table" then
            _applyInboxData(data)
            return true
        end
        break
    end
    return false
end

local function _refreshMagicMailFromServer()
    if not _ensureNetworking() or not _remoteCallable(Net.MagicMailList) then
        return false
    end
    local ok, data = _callNetworkingRemote(Net.MagicMailList)
    if ok and type(data) == "table" then
        _applyMagicMailData(data)
        St.lastMagicRefreshAt = os.clock()
        return true
    end
    return false
end

local function _trackMailboxInbox()
    if St.inboxConn then return end
    if not _ensureNetworking() then return end

    if Net.Updated and Net.Updated.OnClientEvent then
        St.inboxConn = Net.Updated.OnClientEvent:Connect(function(data)
            St.inboxDirty = true
            pcall(_applyInboxData, data)
        end)
    end

    if not St.magicMailConn and Net.MagicMailUpdated and Net.MagicMailUpdated.OnClientEvent then
        St.magicMailConn = Net.MagicMailUpdated.OnClientEvent:Connect(function(data)
            St.magicMailDirty = true
            pcall(_applyMagicMailData, data)
        end)
    end

    task.spawn(function()
        task.wait(2)
        pcall(_refreshInboxFromServer)
        pcall(_refreshMagicMailFromServer)
    end)
end

local function _ensurePlayerState()
    if Net.PlayerStateClient then return true end
    local function tryRequire(modInst)
        if not modInst then return false end
        local ok, mod = pcall(require, modInst)
        if ok and type(mod) == "table" then
            Net.PlayerStateClient = mod
            return true
        end
        return false
    end
    local cm = ReplicatedStorage:FindFirstChild("ClientModules")
    if cm and tryRequire(cm:FindFirstChild("PlayerStateClient")) then return true end
    local ok = pcall(function()
        return tryRequire(ReplicatedStorage:WaitForChild("ClientModules", 15):WaitForChild("PlayerStateClient"))
    end)
    return ok and Net.PlayerStateClient ~= nil
end

local function _getInventory(waitSec)
    waitSec = tonumber(waitSec) or 0
    if not _ensurePlayerState() then return nil end
    if type(Net.PlayerStateClient.GetLocalReplica) ~= "function" then return nil end
    local replica = Net.PlayerStateClient:GetLocalReplica()
    local deadline = os.clock() + waitSec
    while not replica and os.clock() < deadline do
        task.wait(0.1)
        replica = Net.PlayerStateClient:GetLocalReplica()
    end
    if not replica or type(replica.Data) ~= "table" then return nil end
    local inv = replica.Data.Inventory
    return type(inv) == "table" and inv or nil
end

local function _entryUniqueId(entry, itemKey)
    if type(entry) == "table" then
        local id = entry.Id or entry.UUID or entry.PetId or entry.InstanceId
            or entry.Guid or entry.UniqueId or entry.PetUUID
        if id ~= nil and tostring(id) ~= "" then
            return tostring(id)
        end
    end
    -- Jangan fallback itemKey: Seeds/Gear stack keyed by name, bukan UUID.
    return nil
end

local function _isUniqueInventoryEntry(entry, itemKey)
    if type(entry) ~= "table" then return false end
    -- Stack mailbox (Name + Count 4957) bukan unique pet/fruit UUID.
    local n = tonumber(entry.Count or entry.Amount or entry.Quantity or entry.Stack or entry.Qty)
    if type(n) == "number" and n > 1 then
        return false
    end
    if _entryUniqueId(entry, itemKey) ~= nil then return true end
    return entry.PetName ~= nil or entry.PetType ~= nil
end

local function _bagHasEntries(bag)
    if type(bag) ~= "table" then return false end
    local nested = bag.List or bag.Items
    if type(nested) == "table" and #nested > 0 then return true end
    for itemKey in pairs(bag) do
        local keyStr = tostring(itemKey)
        if keyStr:sub(1, 1) ~= "_" then
            return true
        end
    end
    return false
end

local function _eachBagEntry(bag, fn)
    if type(bag) ~= "table" or type(fn) ~= "function" then return end
    local nested = bag.List or bag.Items
    if type(nested) == "table" and (bag.List ~= nil or bag.Items ~= nil) and #nested > 0 then
        for idx, entry in ipairs(nested) do
            fn(_entryUniqueId(entry, idx) or tostring(idx), entry)
        end
        return
    end
    for itemKey, entry in pairs(bag) do
        local keyStr = tostring(itemKey)
        if keyStr:sub(1, 1) == "_" then
            continue
        end
        fn(itemKey, entry)
    end
end

local function _normalizeFruitGroupKey(name)
    return tostring(name or ""):lower():gsub("[%s_%-%.'']+", "")
end

-- Egg + EmptyPots bag helpers share one IIFE (saves main-chunk locals)
local EggBagUtil, EmptyPotsBagUtil = (function()
    -- Mailbox send Category is always EmptyPots; stock may still live in legacy bags.
    -- Keep ItemKey identical to inventory keys — remapping/Name-collapse causes "invalid items".
    local EMPTY_POT_BAG_KEYS = { "EmptyPots", "DustyPots", "InstyPots", "Pots", "EmptyPot" }

    local function stackCountLoose(entry)
        if type(entry) == "number" then return entry end
        local n = tonumber(entry)
        if type(n) == "number" then return n end
        if type(entry) == "table" then
            return tonumber(
                entry.Count or entry.Amount or entry.Quantity or entry.Stack or entry.Qty
                    or entry.n or entry.N or entry.Value or entry.value
            )
        end
        return nil
    end

    local function bagHasAny(bag, eachBagEntry)
        if type(bag) ~= "table" then return false end
        if type(eachBagEntry) ~= "function" then return next(bag) ~= nil end
        local found = false
        eachBagEntry(bag, function()
            found = true
        end)
        return found
    end

    -- Mail ItemKey: prefer typed name on List rows; never use bare array indexes
    local function mailStackKey(itemKey, entry)
        if type(entry) == "table" then
            local name = entry.ItemName or entry.PropName or entry.PotName
                or entry.Name or entry.DisplayName
            if name ~= nil and tostring(name) ~= "" then
                local s = tostring(name)
                -- ignore uuid-like Name fields
                if not (s:match("^[%x%-]+$") and #s >= 12) then
                    return s
                end
            end
        end
        local key = tostring(itemKey or "")
        if key == "" or key:sub(1, 1) == "_" then return nil end
        if key:match("^%d+$") then return nil end
        return key
    end

    local function scanEggToolsIntoBag(bag, lp)
        if type(bag) ~= "table" or not lp then return end
        local function scan(root)
            if not root then return end
            for _, inst in ipairs(root:GetChildren()) do
                if inst:IsA("Tool") then
                    local eggName = inst:GetAttribute("Egg")
                    if eggName ~= nil and tostring(eggName) ~= "" then
                        local name = tostring(eggName)
                        local cnt = math.max(1, math.floor(tonumber(inst:GetAttribute("Count")) or 1))
                        bag[name] = (tonumber(bag[name]) or 0) + cnt
                    end
                end
            end
        end
        scan(lp:FindFirstChild("Backpack") or lp:FindFirstChildOfClass("Backpack"))
        scan(lp.Character)
    end

    local function makeCachedBag(buildFn)
        local cache, cacheAt = nil, 0
        local CACHE_SEC = 1.0
        return {
            invalidate = function()
                cache = nil
                cacheAt = 0
            end,
            getBag = function(inv, lp, eachBagEntry)
                local now = os.clock()
                if type(cache) == "table" and (now - cacheAt) < CACHE_SEC then
                    return cache
                end
                local bag = buildFn(inv, lp, eachBagEntry)
                cache = bag
                cacheAt = now
                return bag
            end,
        }
    end

    local egg = makeCachedBag(function(inv, lp, eachBagEntry)
        local bag = {}
        local hasInvEggs = false
        if type(inv) == "table" and type(inv.Eggs) == "table" and type(eachBagEntry) == "function" then
            eachBagEntry(inv.Eggs, function(itemKey, entry)
                local count = stackCountLoose(entry)
                if type(count) == "number" and count > 0 then
                    hasInvEggs = true
                    local name = tostring(itemKey)
                    bag[name] = (tonumber(bag[name]) or 0) + count
                end
            end)
        end
        if not hasInvEggs then
            scanEggToolsIntoBag(bag, lp)
        end
        return bag
    end)

    local function buildEmptyPotsBag(inv, eachBagEntry)
        if type(inv) ~= "table" then
            return {}
        end
        for _, key in ipairs(EMPTY_POT_BAG_KEYS) do
            local src = inv[key]
            if type(src) == "table" and bagHasAny(src, eachBagEntry) then
                -- Flat count map: keep exact inventory keys (e.g. ["Basic Pot"] = 80)
                local allNumeric = true
                local any = false
                for k, v in pairs(src) do
                    if tostring(k):sub(1, 1) == "_" then
                        continue
                    end
                    if k == "List" or k == "Items" then
                        allNumeric = false
                        break
                    end
                    any = true
                    if type(v) ~= "number" and tonumber(v) == nil then
                        local n = stackCountLoose(v)
                        if type(n) ~= "number" then
                            allNumeric = false
                            break
                        end
                    end
                end
                if any and allNumeric then
                    return src
                end

                -- List / mixed rows → stack by mail ItemKey name (not array index)
                local stacked = {}
                local added = false
                if type(eachBagEntry) == "function" then
                    eachBagEntry(src, function(itemKey, entry)
                        local name = mailStackKey(itemKey, entry)
                        local count = stackCountLoose(entry)
                        if not count and type(entry) == "table" and name then
                            count = 1
                        end
                        if name and type(count) == "number" and count > 0 then
                            stacked[name] = (tonumber(stacked[name]) or 0) + count
                            added = true
                        end
                    end)
                end
                if added then
                    return stacked
                end
                return src
            end
        end
        -- Do NOT invent keys from backpack tools — mailbox validates against inventory bags
        return {}
    end

    -- Custom cache: never keep empty bag long (state EmptyPots often syncs late / intermittently)
    -- Use local fns (no self-ref on table) — avoids "attempt to index nil with getBag"
    local emptyCache, emptyCacheAt = nil, 0

    local function invalidateEmptyPots()
        emptyCache = nil
        emptyCacheAt = 0
    end

    local function getEmptyPotsBag(inv, _lp, eachBagEntry)
        local now = os.clock()
        local had = type(emptyCache) == "table" and bagHasAny(emptyCache, eachBagEntry)
        local ttl = had and 1.0 or 0.15
        if type(emptyCache) == "table" and (now - emptyCacheAt) < ttl then
            return emptyCache
        end
        local bag = buildEmptyPotsBag(inv, eachBagEntry)
        emptyCache = bag
        emptyCacheAt = now
        return bag
    end

    local function waitForEmptyPotsBag(getInv, lp, eachBagEntry, waitSec)
        waitSec = tonumber(waitSec) or 0
        local deadline = os.clock() + math.max(0, waitSec)
        local bag = {}
        while true do
            invalidateEmptyPots()
            local inv = type(getInv) == "function" and getInv() or nil
            bag = getEmptyPotsBag(inv, lp, eachBagEntry)
            if bagHasAny(bag, eachBagEntry) then
                return true, bag
            end
            if os.clock() >= deadline then
                break
            end
            task.wait(0.2)
        end
        return false, bag
    end

    local function resolveEmptyPotsKey(bag, itemKey)
        if type(bag) ~= "table" then return nil, 0 end
        local want = tostring(itemKey or ""):gsub("%s*[xX]%s*[%d%.]+%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if want == "" then return nil, 0 end
        local n = stackCountLoose(bag[want])
        if type(n) == "number" and n > 0 then
            return want, n
        end
        local wantLow = string.lower(want)
        local wantCompact = wantLow:gsub("%s+", "")
        for k, v in pairs(bag) do
            local ks = tostring(k)
            if ks:sub(1, 1) ~= "_" and k ~= "List" and k ~= "Items" then
                local cnt = stackCountLoose(v)
                if type(cnt) == "number" and cnt > 0 then
                    local low = string.lower(ks)
                    if low == wantLow or low:gsub("%s+", "") == wantCompact then
                        return ks, cnt
                    end
                end
            end
        end
        return nil, 0
    end

    local emptyPots = {
        invalidate = invalidateEmptyPots,
        getBag = getEmptyPotsBag,
        waitForBag = waitForEmptyPotsBag,
        resolveKey = resolveEmptyPotsKey,
    }

    return egg, emptyPots
end)()

-- Guard: never call nil methods if IIFE failed to pack util
if type(EmptyPotsBagUtil) ~= "table" then
    EmptyPotsBagUtil = {
        invalidate = function() end,
        getBag = function() return {} end,
        waitForBag = function() return false, {} end,
        resolveKey = function() return nil, 0 end,
    }
elseif type(EmptyPotsBagUtil.getBag) ~= "function" then
    EmptyPotsBagUtil.getBag = function() return {} end
    EmptyPotsBagUtil.waitForBag = EmptyPotsBagUtil.waitForBag
        or function() return false, {} end
    EmptyPotsBagUtil.resolveKey = EmptyPotsBagUtil.resolveKey
        or function() return nil, 0 end
    EmptyPotsBagUtil.invalidate = EmptyPotsBagUtil.invalidate or function() end
end

local _isHarvestedFruitsCategory, _resolveHarvestFruitItemKey, _fruitBaseTypeName, _entrySellPrice
local _buildMultiBatchPricePlan, _prepareHarvestBatch, _dedupeInventoryItems, _getInventoryBag
local _batchSendLimit, _categorySendLimit, _isCountBasedCategory, _ensureCfgCategoryTables, _rebuildCategoryDefs
local _planPriceBatch, _pricePoolFromCandidates, _pricePlanSummary, _formatPriceBreakdown, _ensureFsvFresh
local _isHarvestEntryFavorited
local HARVESTED_FRUITS_CAT = "HarvestedFruits"
;(function()
local FRUIT_ID_FIELDS = { "Id", "id", "UUID", "Uuid", "FruitId", "fruitId" }
local FRUIT_NAME_FIELDS = { "FruitName", "Fruit", "Name", "name", "fruitName", "PlantName" }
local FRUIT_WEIGHT_FIELDS = { "Weight", "weight", "Kg", "kg" }
local FRUIT_MUTATION_FIELDS = { "Mutation", "mutation" }

_isHarvestedFruitsCategory = function(cat)
    return _canonicalCategory(cat) == HARVESTED_FRUITS_CAT
end

local function _getFruitSellValueModule()
    local fsv = G.FruitSellValue or rawget(_G, "FruitSellValue")
    if type(fsv) == "table" then return fsv end
    return nil
end

local function _pickFruitField(entry, fields)
    if type(entry) ~= "table" then return nil end
    for _, f in ipairs(fields) do
        local v = entry[f]
        if v ~= nil and tostring(v) ~= "" then return v end
    end
    return nil
end

local function _stackEntryCount(entry)
    if type(entry) == "number" then return entry end
    if type(entry) ~= "table" then
        return tonumber(entry)
    end
    return tonumber(entry.Count or entry.Amount or entry.Quantity or entry.Stack or entry.Qty)
end

local function _isStackInventoryEntry(entry, itemKey)
    if type(entry) == "table" then
        if _isUniqueInventoryEntry(entry, itemKey) then return false end
        local n = _stackEntryCount(entry)
        return type(n) == "number" and n > 0
    end
    local n = tonumber(entry)
    return type(n) == "number" and n > 0
end

local function _bagIsStackedCounts(bag)
    if type(bag) ~= "table" then return false end
    local stackCount, uniqueCount = 0, 0
    _eachBagEntry(bag, function(itemKey, entry)
        if _isUniqueInventoryEntry(entry, itemKey) then
            uniqueCount += 1
        elseif _isStackInventoryEntry(entry, itemKey) then
            stackCount += 1
        end
    end)
    return stackCount > 0 and uniqueCount == 0
end

_dedupeInventoryItems = function(items)
    local out = {}
    local byNorm = {}
    for _, it in ipairs(type(items) == "table" and items or {}) do
        local rawKey = tostring(it.key or it.name or "")
        if rawKey == "" then
            out[#out + 1] = it
            continue
        end
        local baseName = rawKey:gsub("%s*x%s+.+$", "")
        local norm = _normalizeFruitGroupKey(baseName)
        if norm == "" then
            norm = _normalizeFruitGroupKey(rawKey)
        end
        local prev = byNorm[norm]
        if prev then
            prev.count = math.max(tonumber(prev.count) or 0, tonumber(it.count) or 0)
            prev.key = baseName ~= "" and baseName or rawKey
            prev.name = prev.key .. " x " .. M._formatCount(prev.count)
            prev.right = M._formatCount(prev.count)
        else
            local key = baseName ~= "" and baseName or rawKey
            local copy = {
                key = key,
                name = it.name or (key .. " x " .. M._formatCount(it.count)),
                right = it.right,
                count = it.count,
            }
            if copy.name == key then
                copy.name = key .. " x " .. M._formatCount(copy.count)
            end
            byNorm[norm] = copy
            out[#out + 1] = copy
        end
    end
    table.sort(out, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    return out
end

local function _looksLikeLayoutFruitEntry(entry)
    if type(entry) ~= "table" then return false end
    if entry.SeedTool ~= nil or entry.Pet ~= nil then return false end
    if entry.PottedPlant == true then return false end
    if tostring(entry.MainCategory or "") == "Seed" then return false end
    local id = _pickFruitField(entry, FRUIT_ID_FIELDS)
    if type(id) == "string" and id ~= "" and #id >= 8 then return true end
    local name = _pickFruitField(entry, FRUIT_NAME_FIELDS)
    if name ~= nil and tostring(name) ~= "" then return true end
    if entry.HarvestedFruit == true or entry.FruitProxy == true then return true end
    return false
end

local function _collectLayoutFruitEntries(layout, out, depth, seen)
    if depth > 12 or type(layout) ~= "table" then return end
    if seen[layout] then return end
    seen[layout] = true
    if _looksLikeLayoutFruitEntry(layout) then
        out[#out + 1] = layout
        return
    end
    for _, value in pairs(layout) do
        if type(value) == "table" then
            if _looksLikeLayoutFruitEntry(value) then
                out[#out + 1] = value
            else
                _collectLayoutFruitEntries(value, out, depth + 1, seen)
            end
        end
    end
end

local function _layoutFruitToMailEntry(raw)
    if not _looksLikeLayoutFruitEntry(raw) then return nil end
    local id = tostring(_pickFruitField(raw, FRUIT_ID_FIELDS) or "")
    if not _isLikelyFruitInstanceId(id) then return nil end
    return {
        Id = id,
        FruitName = _pickFruitField(raw, FRUIT_NAME_FIELDS),
        Mutation = _pickFruitField(raw, FRUIT_MUTATION_FIELDS),
        Weight = tonumber(_pickFruitField(raw, FRUIT_WEIGHT_FIELDS)),
        SizeMultiplier = raw.SizeMultiplier or raw.SizeMulti,
        IsFavorite = raw.IsFavorite,
        Favorite = raw.Favorite,
        Favorited = raw.Favorited,
        isFavorite = raw.isFavorite,
        d = raw.d,
    }
end

local function _instLooksLikeHarvestedFruit(inst)
    if not inst or type(inst.GetAttribute) ~= "function" then return false end
    if inst:GetAttribute("SeedTool") ~= nil then return false end
    if inst:GetAttribute("Pet") ~= nil then return false end
    if inst:GetAttribute("PottedPlant") == true then return false end
    if tostring(inst:GetAttribute("MainCategory") or "") == "Seed" then return false end
    local fruitName = inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit")
    if fruitName ~= nil and tostring(fruitName) ~= "" then return true end
    if inst:GetAttribute("FruitProxy") == true then return true end
    local hf = inst:GetAttribute("HarvestedFruit")
    if hf == true then return true end
    if type(hf) == "string" and hf ~= "" then return true end
    return false
end

local function _isLikelyFruitInstanceId(id)
    id = tostring(id or "")
    if id == "" then return false end
    if id:find("%s") then return false end
    if #id < 8 then return false end
    if id:match("^[%a'%-]+$") and not id:match("[%d_]") then
        return false
    end
    return true
end

_resolveHarvestFruitItemKey = function(itemKey, entry)
    if type(entry) == "table" then
        local fromEntry = _pickFruitField(entry, FRUIT_ID_FIELDS)
        if fromEntry ~= nil and _isLikelyFruitInstanceId(fromEntry) then
            return tostring(fromEntry)
        end
    end
    local keyStr = tostring(itemKey or "")
    if _isLikelyFruitInstanceId(keyStr) then
        return keyStr
    end
    return nil
end

local function _bagHasOnlyDisplayNameKeys(bag)
    if type(bag) ~= "table" then return false end
    local sawNameKey = false
    local sawIdKey = false
    _eachBagEntry(bag, function(itemKey, entry)
        if _resolveHarvestFruitItemKey(itemKey, entry) then
            sawIdKey = true
        else
            sawNameKey = true
        end
    end)
    return sawNameKey and not sawIdKey
end

local function _findToolByFruitId(id)
    id = tostring(id or "")
    if id == "" then return nil end
    -- Index sekali / ~1.5s — JANGAN GetDescendants per buah (500 buah = spike CPU).
    local now = os.clock()
    if type(_toolByIdCache) ~= "table" or (now - (tonumber(_toolByIdCacheAt) or 0)) > 1.5 then
        local map = {}
        local function index(container)
            if not container then return end
            for _, inst in ipairs(container:GetChildren()) do
                if inst:IsA("Tool") or _instLooksLikeHarvestedFruit(inst) then
                    local tid = tostring(inst:GetAttribute("Id") or inst:GetAttribute("UUID") or "")
                    if tid ~= "" then
                        map[tid] = inst
                    end
                end
            end
        end
        index(LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack"))
        index(LP.Character)
        _toolByIdCache = map
        _toolByIdCacheAt = now
    end
    return _toolByIdCache[id]
end

local function _fruitDisplayName(raw)
    local name = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return nil end
    if name:match("^[%x%-]+$") and #name >= 12 then return nil end
    if _isLikelyFruitInstanceId(name) then return nil end
    return name
end

_fruitBaseTypeName = function(entry, itemKey)
    if type(entry) == "table" then
        local name = _fruitDisplayName(
            entry.FruitName or entry.Fruit or entry.PlantName or entry.Name or entry.DisplayName
        )
        if name then return name end
    end

    local id = _resolveHarvestFruitItemKey(itemKey, entry)
    if id and type(_getBackpackFruitBag) == "function" then
        local bag = _getBackpackFruitBag(false)
        local cached = type(bag) == "table" and bag[id] or nil
        if type(cached) == "table" then
            local name = _fruitDisplayName(
                cached.FruitName or cached.Fruit or cached.PlantName or cached.Name or cached.DisplayName
            )
            if name then return name end
        end
    end

    if id then
        local inst = _findToolByFruitId(id)
        if inst then
            local name = _fruitDisplayName(
                inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") or inst.Name
            )
            if name then return name end
        end
    end

    local key = tostring(itemKey or ""):gsub("%s*%[.-%]", ""):gsub("%s+$", "")
    local name = _fruitDisplayName(key)
    if name then return name end
    return "Fruit"
end

local function _resolvePriceMulti(entry, inst)
    local fsv = _getFruitSellValueModule()
    if inst and fsv and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, inst)
        if ok and type(m) == "number" and m > 0 then return m end
    end
    if type(entry) == "table" then
        local sm = tonumber(entry.SizeMultiplier or entry.SizeMulti)
        if sm and sm > 0 then return sm end
        -- Jangan pakai Weight/kg sebagai SizeMultiplier.
    end
    if inst and type(inst.GetAttribute) == "function" then
        local sm = tonumber(inst:GetAttribute("SizeMultiplier") or inst:GetAttribute("SizeMulti"))
        if sm and sm > 0 then return sm end
    end
    return 0
end

local _fsvRefreshedAt = 0
local _pricePlanEpoch = 0
local _pricePlanPreviewCache = nil

local function _invalidatePricePlanPreview()
    _pricePlanPreviewCache = nil
end

_ensureFsvFresh = function(force)
    local fsv = _getFruitSellValueModule()
    if not fsv or type(fsv.refresh) ~= "function" then
        return fsv
    end
    local now = os.clock()
    if force or (now - _fsvRefreshedAt) > 1 then
        pcall(fsv.refresh, true)
        _fsvRefreshedAt = now
    end
    return fsv
end

_entrySellPrice = function(category, itemKey, entry)
    if not _isHarvestedFruitsCategory(category) then return 0 end

    local id = tostring(_resolveHarvestFruitItemKey(itemKey, entry) or "")
    local now = os.clock()
    if (now - _entryPriceCacheAt) > ENTRY_PRICE_CACHE_SEC then
        _entryPriceByIdCache = {}
        _entryPriceCacheAt = now
    end
    if id ~= "" then
        local cached = _entryPriceByIdCache[id]
        if type(cached) == "number" then
            return cached
        end
    end

    local name = _fruitBaseTypeName(entry, itemKey)
    -- PENTING: arg ke FruitSellValue = SizeMultiplier (bukan Weight kg).
    -- Pakai Weight sebagai multi → harga salah / hampir 0 → web fallback unit×qty (angka kecil).
    local multi = 0
    local mut, decay, bidPrice = nil, nil, 0
    if type(entry) == "table" then
        multi = tonumber(entry.SizeMultiplier or entry.SizeMulti) or 0
        mut = entry.Mutation or entry.mutation
        decay = entry.DecayAlpha
        bidPrice = tonumber(entry.BidPrice or entry.bidPrice) or 0
    end

    local tool = nil
    if id ~= "" then
        tool = _findToolByFruitId(id) -- O(1) via index cache
    end

    local fsv = _getFruitSellValueModule()
    if tool then
        if multi <= 0 and fsv and type(fsv.resolveMulti) == "function" then
            local okM, m = pcall(fsv.resolveMulti, tool)
            if okM and type(m) == "number" and m > 0 then multi = m end
        end
        if multi <= 0 and type(tool.GetAttribute) == "function" then
            multi = tonumber(tool:GetAttribute("SizeMultiplier") or tool:GetAttribute("SizeMulti")) or 0
        end
        if (mut == nil or mut == "") and type(tool.GetAttribute) == "function" then
            mut = tool:GetAttribute("Mutation")
        end
        if decay == nil and type(tool.GetAttribute) == "function" then
            decay = tool:GetAttribute("DecayAlpha")
        end
        if bidPrice <= 0 then
            if fsv and type(fsv.resolveBidPrice) == "function" then
                local okB, b = pcall(fsv.resolveBidPrice, tool)
                if okB and type(b) == "number" and b > 0 then bidPrice = b end
            elseif type(tool.GetAttribute) == "function" then
                bidPrice = tonumber(tool:GetAttribute("BidPrice")) or 0
            end
        end
        if (name == nil or name == "" or name == "Fruit") and type(tool.GetAttribute) == "function" then
            local n = _fruitDisplayName(tool:GetAttribute("FruitName") or tool:GetAttribute("Fruit") or tool.Name)
            if n then name = n end
        end
    end

    if not fsv or multi <= 0 or name == nil or name == "" then
        if id ~= "" then _entryPriceByIdCache[id] = 0 end
        return 0
    end

    local price = 0
    local mode = _harvestPriceCalcMode()
    -- Stats/monitor: pakai base (tanpa remote bid per-buah). Mode stock tetap untuk gift plan.
    if mode == "stock" and id ~= "" and type(fsv.getNpcBidRaw) == "function" then
        -- Hanya pakai bid kalau sudah di-cache (raw>0); jangan spam remote 500×.
        local okBid, raw = pcall(fsv.getNpcBidRaw, id)
        if okBid and type(raw) == "number" and raw > 0 then
            price = math.floor(raw + 0.5)
        end
    end
    if price <= 0 and type(fsv.getBackpackEspPrice) == "function" then
        local ok, p = pcall(fsv.getBackpackEspPrice, name, multi, mut, decay, "base", id, bidPrice)
        if ok and type(p) == "number" and p > 0 then
            price = math.floor(p + 0.5)
        end
    end
    if price <= 0 and type(fsv.calculate) == "function" then
        local ok, p = pcall(fsv.calculate, name, multi, mut, nil, decay)
        if ok and type(p) == "number" and p > 0 then
            price = math.floor(p + 0.5)
            if bidPrice > 0 then price = math.floor(price + bidPrice + 0.5) end
        end
    end

    if id ~= "" then
        _entryPriceByIdCache[id] = price
    end
    return price
end

local _giftPriceApi = nil
local function _giftPrice()
    if _giftPriceApi then
        return _giftPriceApi
    end
    local factory = G.AutoGiftPriceModule or G.AutoGiftPrice
        or rawget(_G, "AutoGiftPriceModule") or rawget(_G, "AutoGiftPrice")
    if type(factory) == "table" and type(factory.create) == "function" then
        _giftPriceApi = factory.create({
            clampBatch = _clampBatch,
            maxBatch = MAX_BATCH,
            formatSellPrice = _formatSellPrice,
            isHarvestedFruitsCategory = _isHarvestedFruitsCategory,
            entrySellPrice = _entrySellPrice,
        })
    end
    return _giftPriceApi
end

_pricePoolFromCandidates = function(candidates)
    local px = _giftPrice()
    if not px then return {} end
    return px.poolFromCandidates(candidates)
end

_formatPriceBreakdown = function(pick)
    local px = _giftPrice()
    if not px then return "" end
    return px.formatBreakdown(pick)
end

_buildMultiBatchPricePlan = function(candidates, targetMin, targetMax, maxItems)
    local px = _giftPrice()
    if not px then return nil, 0, 0, 0 end
    return px.buildMultiBatchPricePlan(candidates, targetMin, targetMax, maxItems)
end

_planPriceBatch = function(candidates, minSum, maxSum, maxItems, usedKeys)
    local px = _giftPrice()
    if not px then return nil, 0, {} end
    return px.planPriceBatch(candidates, minSum, maxSum, maxItems, usedKeys)
end

_pricePlanSummary = function(pick, total, minSum, maxSum, poolSize, batchCount)
    local px = _giftPrice()
    if not px then
        return "Price module belum load — re-execute hub"
    end
    return px.pricePlanSummary(pick, total, minSum, maxSum, poolSize, batchCount)
end

local function _promoteHarvestFruitForMail(id)
    id = tostring(id or "")
    if id == "" or not _isLikelyFruitInstanceId(id) then return false end
    if _findToolByFruitId(id) then return true end
    if not _ensureNetworking() or not _remoteCallable(Net.BackpackPromoteFruit) then
        return false
    end
    local ok = _callNetworkingRemote(Net.BackpackPromoteFruit, id)
    if not ok then return false end
    M.InvalidateHarvestFruitCache()
    for _ = 1, 12 do
        task.wait(0.08)
        if _findToolByFruitId(id) then return true end
    end
    return true
end

_prepareHarvestBatch = function(batch)
    if type(batch) ~= "table" or #batch == 0 then return batch end
    local wantUnfav = (cfg.auto_unfav == true)
    local out = {}
    for _, item in ipairs(batch) do
        if _isHarvestedFruitsCategory(item.Category) then
            local id = _resolveHarvestFruitItemKey(item.ItemKey, nil)
            if not id then
                id = tostring(item.ItemKey or "")
                if id == "" then id = nil end
            end
            if id then
                if wantUnfav then
                    M._GiftUnfav.fire(id)
                    task.wait(0.02)
                end
                _promoteHarvestFruitForMail(id)
                out[#out + 1] = {
                    Category = item.Category,
                    ItemKey = id,
                    Count = item.Count or 1,
                }
            end
        else
            out[#out + 1] = item
        end
    end
    if wantUnfav then
        St.harvestFavCache = nil
        M.InvalidateHarvestFruitCache()
    end
    return out
end

local function _instanceFruitToMailEntry(inst)
    if not _instLooksLikeHarvestedFruit(inst) then return nil end
    local id = inst:GetAttribute("Id") or inst:GetAttribute("UUID") or inst:GetAttribute("FruitId")
    id = tostring(id or "")
    if not _isLikelyFruitInstanceId(id) then return nil end
    return {
        Id = id,
        FruitName = inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") or inst.Name,
        Mutation = inst:GetAttribute("Mutation"),
        Weight = tonumber(inst:GetAttribute("Weight")),
        SizeMultiplier = inst:GetAttribute("SizeMultiplier") or inst:GetAttribute("SizeMulti"),
        IsFavorite = inst:GetAttribute("IsFavorite"),
        Favorite = inst:GetAttribute("Favorite"),
        Favorited = inst:GetAttribute("Favorited"),
        isFavorite = inst:GetAttribute("isFavorite"),
        d = inst:GetAttribute("d"),
    }
end

local function _mergeFavFields(dst, src)
    if type(dst) ~= "table" or type(src) ~= "table" then return dst end
    for _, key in ipairs({ "IsFavorite", "Favorite", "Favorited", "isFavorite", "d" }) do
        if src[key] ~= nil then dst[key] = src[key] end
    end
    return dst
end

local function _mergeHarvestedFruitBag(dst, src)
    dst = type(dst) == "table" and dst or {}
    if type(src) ~= "table" then return dst end
    for itemKey, entry in pairs(src) do
        local keyStr = tostring(itemKey)
        if keyStr:sub(1, 1) ~= "_" and dst[itemKey] == nil then
            dst[itemKey] = entry
        end
    end
    return dst
end

_getBackpackFruitBag = function(forceRefresh)
    local now = os.clock()
    if not forceRefresh and St.harvestFruitBagCache and (now - St.harvestFruitBagCacheAt) < HARVEST_FRUIT_BAG_CACHE_SEC then
        return St.harvestFruitBagCache
    end

    local bag = {}
    local byId = {}

    local function addEntry(entry)
        if type(entry) ~= "table" then return end
        local id = tostring(entry.Id or _pickFruitField(entry, FRUIT_ID_FIELDS) or "")
        if not _isLikelyFruitInstanceId(id) then return end
        entry.Id = id
        if byId[id] then
            _mergeFavFields(bag[id], entry)
            return
        end
        byId[id] = true
        bag[id] = entry
    end

    if _ensureNetworking() and _remoteCallable(Net.BackpackGetLayout) then
        local ok, layout = _callNetworkingRemote(Net.BackpackGetLayout)
        if ok and type(layout) == "table" then
            local raw = {}
            _collectLayoutFruitEntries(layout, raw, 0, {})
            for _, layoutEntry in ipairs(raw) do
                addEntry(_layoutFruitToMailEntry(layoutEntry))
            end
        end
    end

    local function scanContainer(container)
        if not container then return end
        -- Tools biasanya child langsung Backpack — GetChildren, bukan GetDescendants.
        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") or _instLooksLikeHarvestedFruit(inst) then
                addEntry(_instanceFruitToMailEntry(inst))
            end
        end
    end

    scanContainer(LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack"))
    scanContainer(LP.Character)

    St.harvestFruitBagCache = bag
    St.harvestFruitBagCacheAt = now
    return bag
end

function M.InvalidateHarvestFruitCache()
    St.harvestFruitBagCache = nil
    St.harvestFruitBagCacheAt = 0
    EggBagUtil.invalidate()
    EmptyPotsBagUtil.invalidate()
    St.harvestFavCache = nil
    _pricePlanEpoch += 1
    _invalidatePricePlanPreview()
end

local function _truthyFavFlag(val)
    return val == true or val == 1 or val == "true" or val == "1"
end

local function _rawEntryFavorited(entry, depth)
    depth = math.floor(tonumber(depth) or 0)
    if depth > 5 or type(entry) ~= "table" then return false end
    if _truthyFavFlag(entry.IsFavorite) or _truthyFavFlag(entry.Favorite)
        or _truthyFavFlag(entry.Favorited) or _truthyFavFlag(entry.isFavorite)
        or _truthyFavFlag(entry.d) then
        return true
    end
    for _, key in ipairs({ "Attributes", "Data", "Fruit", "Entry", "Item" }) do
        local nested = entry[key]
        if type(nested) == "table" and _rawEntryFavorited(nested, depth + 1) then
            return true
        end
    end
    return false
end

local function _instanceFavorited(inst)
    if not inst or typeof(inst) ~= "Instance" or type(inst.GetAttribute) ~= "function" then
        return false
    end
    return _truthyFavFlag(inst:GetAttribute("IsFavorite"))
        or _truthyFavFlag(inst:GetAttribute("Favorite"))
        or _truthyFavFlag(inst:GetAttribute("Favorited"))
        or _truthyFavFlag(inst:GetAttribute("isFavorite"))
        or _truthyFavFlag(inst:GetAttribute("d"))
end

local function _getAutoFavModule()
    return G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
end

local function _getNormalGiftModule()
    return G.NormalGift or G.NormalGiftModule or rawget(_G, "NormalGift") or rawget(_G, "NormalGiftModule")
end

_isHarvestEntryFavorited = function(itemKey, entry)
    local uuid = _resolveHarvestFruitItemKey(itemKey, entry)
    if not uuid or uuid == "" then return false end

    if type(St.harvestFavCache) ~= "table" then
        St.harvestFavCache = {}
    elseif St.harvestFavCache[uuid] ~= nil then
        return St.harvestFavCache[uuid] == true
    end

    local function cacheResult(yes)
        St.harvestFavCache[uuid] = yes == true
        return yes == true
    end

    local ng = _getNormalGiftModule()
    if type(ng) == "table" and type(ng.IsHarvestFavorited) == "function" then
        local ok, yes = pcall(ng.IsHarvestFavorited, ng, {
            uuid = uuid,
            raw = type(entry) == "table" and entry or nil,
            giftType = "HarvestedFruits",
        })
        if ok and yes == true then
            return cacheResult(true)
        end
    end

    local bagEntry = type(entry) == "table" and entry or nil
    if not bagEntry and type(_getBackpackFruitBag) == "function" then
        local bag = _getBackpackFruitBag(false)
        if type(bag) == "table" then
            bagEntry = bag[uuid]
        end
    end

    if _rawEntryFavorited(bagEntry, 0) then
        return cacheResult(true)
    end

    local inst = _findToolByFruitId(uuid)
    if inst and _instanceFavorited(inst) then
        return cacheResult(true)
    end

    local af = _getAutoFavModule()
    if type(af) == "table" and type(af.IsFruitIdFavorited) == "function" then
        local ok, yes = pcall(af.IsFruitIdFavorited, af, uuid, inst)
        if ok and yes == true then
            return cacheResult(true)
        end
    end

    return cacheResult(false)
end

function M.IsHarvestFavorited(itemKey, entry)
    if type(itemKey) == "table" then
        local row = itemKey
        return _isHarvestEntryFavorited(row.ItemKey or row.uuid or row.id, row.Entry or row.raw or row)
    end
    return _isHarvestEntryFavorited(itemKey, entry)
end

-- Hemat register: tempel ke M (sudah local), jangan buat local baru.
-- Unfav langsung via remote — TIDAK tergantung Auto Fav / Auto Unfav toggle ON/OFF.
M._GiftUnfav = { held = false, settle = 0.4, boostBusyHeld = false, lastIds = nil }
function M._GiftUnfav.skipFavorited()
    return cfg.auto_unfav ~= true
end
function M._GiftUnfav.fire(id, favorited)
    id = tostring(id or "")
    if id == "" then return false end
    favorited = (favorited == true)
    _ensureNetworking()
    local tool = _findToolByFruitId(id)
    if tool and typeof(tool) == "Instance" and type(tool.SetAttribute) == "function" then
        pcall(function()
            if favorited then
                tool:SetAttribute("IsFavorite", true)
                tool:SetAttribute("Favorite", true)
                tool:SetAttribute("Favorited", true)
            else
                tool:SetAttribute("IsFavorite", nil)
                tool:SetAttribute("Favorite", nil)
                tool:SetAttribute("Favorited", nil)
            end
        end)
    end
    local remote = Net.Networking and Net.Networking.Backpack and Net.Networking.Backpack.SetFruitFavorite
    if _remoteCallable(remote) then
        local ok = _callNetworkingRemote(remote, id, favorited)
        return ok == true
    end
    -- Fallback one-shot AutoFav (tetap jalan meski toggle OFF)
    local af = G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
    if type(af) == "table" and type(af.SetFruitFavorite) == "function" then
        local ok = pcall(af.SetFruitFavorite, af, id, favorited)
        return ok == true
    end
    return false
end
function M._GiftUnfav.pause(reason)
    if M._GiftUnfav.held then return end
    M._GiftUnfav.held = true
    M._GiftUnfav.lastIds = nil
    reason = reason or "gift_once"

    -- Tunggu Stock/Daily selesai dulu, lalu kunci flag yang mereka hormati.
    do
        local deadline = os.clock() + 15
        while G.__GAG2_BOOST_SELL_BUSY == true and os.clock() < deadline do
            task.wait(0.05)
        end
        if M._GiftUnfav.boostBusyHeld ~= true then
            G.__GAG2_BOOST_SELL_BUSY = true
            _G.__GAG2_BOOST_SELL_BUSY = true
            M._GiftUnfav.boostBusyHeld = true
        end
    end

    -- Nama runtime = AutoSellFruit (bukan AutoSell)
    local asell = G.AutoSellFruit or G.AutoSell or G.AutoSellModule
        or rawget(_G, "AutoSellFruit") or rawget(_G, "AutoSell") or rawget(_G, "AutoSellModule")
    if type(asell) == "table" and type(asell.PausePeers) == "function" then
        pcall(asell.PausePeers, asell, reason)
        if type(asell.WaitIdle) == "function" then
            pcall(asell.WaitIdle, asell, 15)
        end
    else
        if type(asell) == "table" and type(asell.Pause) == "function" then
            pcall(asell.Pause, asell, reason)
            if type(asell.WaitIdle) == "function" then
                pcall(asell.WaitIdle, asell, 15)
            end
        end
        local af = G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
        if type(af) == "table" and type(af.Pause) == "function" then
            pcall(af.Pause, af, reason)
        end
    end
end
-- completedOk == true: kirim sukses. selain itu (fail/abort/stop): restore fav dulu.
-- Jangan ResumePeers langsung — itu tryAutoSell sebelum Auto Fav sempat jalan.
function M._GiftUnfav.resume(completedOk)
    if not M._GiftUnfav.held then return end
    M._GiftUnfav.held = false

    local af = G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
    local asell = G.AutoSellFruit or G.AutoSell or G.AutoSellModule
        or rawget(_G, "AutoSellFruit") or rawget(_G, "AutoSell") or rawget(_G, "AutoSellModule")

    -- 1) Lepas pause AutoFav dulu
    if type(af) == "table" and type(af.Resume) == "function" then
        pcall(af.Resume, af)
    end

    -- 2) Gift gagal/abort: restore fav buah yang tadi di-unfav untuk kirim
    if completedOk ~= true then
        local ids = M._GiftUnfav.lastIds
        if type(ids) == "table" and #ids > 0 then
            _setStatus("Gift gagal — restore fav " .. tostring(#ids) .. " fruit...")
            for i, id in ipairs(ids) do
                M._GiftUnfav.fire(id, true)
                if i < #ids then task.wait(0.03) end
            end
            local settle = tonumber(M._GiftUnfav.settle) or 0.4
            if settle < 0.25 then settle = 0.25 end
            task.wait(settle)
            M.InvalidateHarvestFruitCache()
            St.harvestFavCache = nil
        end
    end

    -- 3) Kalau AutoSell aktif: sync Auto Fav dulu, baru boleh sell
    local sellOn = (G.AUTO_SELL_ENABLED == true) or (rawget(_G, "AUTO_SELL_ENABLED") == true)
    if not sellOn and type(asell) == "table" and type(asell.IsRunning) == "function" then
        local okR, r = pcall(asell.IsRunning, asell)
        sellOn = okR and r == true
    end
    if sellOn and type(af) == "table" and type(af.SyncBeforeSell) == "function" then
        pcall(af.SyncBeforeSell, af, {
            beforeSell = true,
            fireDelay = 0,
            maxWallSec = 8,
        })
        task.wait(0.12)
    end

    -- 4) Resume AutoSell saja (AutoFav sudah di-resume; jangan ResumePeers)
    if type(asell) == "table" and type(asell.Resume) == "function" then
        pcall(asell.Resume, asell)
    end

    if M._GiftUnfav.boostBusyHeld == true then
        M._GiftUnfav.boostBusyHeld = false
        G.__GAG2_BOOST_SELL_BUSY = false
        _G.__GAG2_BOOST_SELL_BUSY = false
    end
    M._GiftUnfav.lastIds = nil
end
function M._GiftUnfav.shouldHold()
    if cfg.auto_unfav ~= true then return false end
    if type(cfg.categories) == "table" then
        for cat, on in pairs(cfg.categories) do
            if on == true and _isHarvestedFruitsCategory(cat) then
                return true
            end
        end
    end
    return false
end
function M._GiftUnfav.prepare(items)
    if cfg.auto_unfav ~= true then return 0 end
    local harvestOn = M._GiftUnfav.shouldHold()
    if not harvestOn and type(items) == "table" then
        for _, item in ipairs(items) do
            if type(item) == "table" and _isHarvestedFruitsCategory(item.Category) then
                harvestOn = true
                break
            end
        end
    end
    if not harvestOn then return 0 end
    -- Pause SEMUA sell (normal + stock + daily) + fav/unfav SEBELUM unfav
    M._GiftUnfav.pause("gift_once_unfav")

    local ids, seen = {}, {}
    if type(items) == "table" then
        for _, item in ipairs(items) do
            if type(item) == "table" and _isHarvestedFruitsCategory(item.Category) then
                local id = tostring(item.ItemKey or "")
                if id == "" and type(item.Entry) == "table" then
                    id = tostring(item.Entry.Id or item.Entry.UUID or item.Entry.FruitId or "")
                end
                if id ~= "" and not seen[id] then
                    seen[id] = true
                    ids[#ids + 1] = id
                end
            end
        end
    end
    if #ids == 0 then return 0 end
    M._GiftUnfav.lastIds = ids

    _setStatus("Unfav " .. tostring(#ids) .. " fruit sebelum kirim...")
    local n = 0
    for i, id in ipairs(ids) do
        if M._GiftUnfav.fire(id, false) then
            n += 1
        end
        if i < #ids then task.wait(0.03) end
    end
    local settle = tonumber(M._GiftUnfav.settle) or 0.4
    if settle < 0.35 then settle = 0.35 end
    task.wait(settle)
    M.InvalidateHarvestFruitCache()
    St.harvestFavCache = nil
    return n
end

local function _getHarvestedFruitBag(inv)
    local invBag = nil
    if type(inv) == "table" then
        invBag = inv[HARVESTED_FRUITS_CAT] or inv.Fruits or inv.Fruit
    end
    local bpBag = _getBackpackFruitBag(false)
    local invHas = type(invBag) == "table" and _bagHasEntries(invBag)
    local bpHas = type(bpBag) == "table" and _bagHasEntries(bpBag)

    if invHas and _bagHasOnlyDisplayNameKeys(invBag) then
        bpBag = _getBackpackFruitBag(true)
        bpHas = type(bpBag) == "table" and _bagHasEntries(bpBag)
    end

    if bpHas then
        return bpBag
    end
    if invHas and not _bagHasOnlyDisplayNameKeys(invBag) then
        return invBag
    end
    return {}
end

_getInventoryBag = function(inv, category)
    category = _canonicalCategory(category)
    if category == "" then return nil, category end
    if _isHarvestedFruitsCategory(category) then
        return _getHarvestedFruitBag(inv), category
    end
    if category == "Eggs" then
        return EggBagUtil.getBag(inv, LP, _eachBagEntry), category
    end
    if category == "EmptyPots" then
        return EmptyPotsBagUtil.getBag(inv, LP, _eachBagEntry), category
    end
    if type(inv) ~= "table" then return nil, category end
    local fallbacks = CATEGORY_BAG_FALLBACKS[category]
    if type(fallbacks) == "table" then
        local emptyBag = nil
        for _, key in ipairs(fallbacks) do
            local bag = inv[key]
            if type(bag) == "table" then
                if _bagHasEntries(bag) then return bag, category end
                if not emptyBag then emptyBag = bag end
            end
        end
        if emptyBag then return emptyBag, category end
    end
    local emptyBag = nil
    local bag = inv[category]
    if type(bag) == "table" then
        if _bagHasEntries(bag) then return bag, category end
        emptyBag = bag
    end
    local alt = SAVE_CATEGORY_ALIASES[category]
    if alt and type(inv[alt]) == "table" then
        if _bagHasEntries(inv[alt]) then return inv[alt], category end
        if not emptyBag then emptyBag = inv[alt] end
    end
    for legacy, canon in pairs(SAVE_CATEGORY_ALIASES) do
        if canon == category and type(inv[legacy]) == "table" then
            if _bagHasEntries(inv[legacy]) then return inv[legacy], category end
            if not emptyBag then emptyBag = inv[legacy] end
        end
    end
    local lower = category:lower()
    for key, cand in pairs(inv) do
        if type(cand) == "table" and tostring(key):lower() == lower then
            if _bagHasEntries(cand) then return cand, category end
            if not emptyBag then emptyBag = cand end
        end
    end
    return emptyBag, category
end

local function _isUniqueEntryCategory(cat, bag)
    if type(bag) ~= "table" then return false end
    if _bagIsStackedCounts(bag) then return false end
    local hasUnique, hasStack = false, false
    _eachBagEntry(bag, function(itemKey, entry)
        if _isUniqueInventoryEntry(entry, itemKey) then
            hasUnique = true
        elseif _isStackInventoryEntry(entry, itemKey) then
            hasStack = true
        end
    end)
    if hasStack and not hasUnique then return false end
    return hasUnique
end

_isCountBasedCategory = function(cat, inv)
    cat = _canonicalCategory(cat)
    if cat == "" then return true end
    if cat == "EmptyPots" then return true end
    if _isHarvestedFruitsCategory(cat) then return false end
    if PET_LIKE_CATEGORIES[cat] then return false end
    -- Seeds/Gear/Eggs/dll: Count = qty stack. Jangan percaya sniff bag
    -- (entry.Name membuat stack terlihat unique → kirim 1/10 lalu berhenti).
    return true
end

_batchSendLimit = function(candidates, totalRemaining)
    local limit = _clampBatch(cfg.max_per_batch)
    if totalRemaining ~= nil then
        local remain = math.max(0, math.floor(tonumber(totalRemaining) or 0))
        if remain > 0 then
            limit = math.min(limit, remain)
        end
    end
    return limit
end

_categorySendLimit = function(cat)
    local limit = _clampBatch(cfg.max_per_batch)
    cat = _canonicalCategory(cat)
    -- MailboxController: max 20 selected units per gift
    if cat == "EmptyPots" then
        return math.min(limit, MAILBOX_UNIQUE_PER_SEND)
    end
    if not _isCountBasedCategory(cat, _getInventory(0)) then
        limit = math.min(limit, MAILBOX_UNIQUE_PER_SEND)
    end
    return limit
end

_rebuildCategoryDefs = function()
    _ensureMailboxCatalog()
    local defs = {}
    local seen = {}
    local inv = nil
    local okInv, invResult = pcall(_getInventory, 2)
    if okInv then inv = invResult end
    for _, key in ipairs(_catalogCategories()) do
        if _catalogIsGiftable(key) and not seen[key] then
            seen[key] = true
            local bag = inv and _getInventoryBag(inv, key)
            defs[#defs + 1] = {
                key = key,
                label = _categoryLabel(key),
                countBased = key ~= HARVESTED_FRUITS_CAT and PET_LIKE_CATEGORIES[key] ~= true,
            }
        end
    end
    for key in pairs(EXTRA_GIFT_CATEGORIES) do
        if type(key) == "string" and key ~= "" and not seen[key] then
            seen[key] = true
            local bag = _getInventoryBag(inv, key)
            defs[#defs + 1] = {
                key = key,
                label = _categoryLabel(key),
                countBased = key ~= HARVESTED_FRUITS_CAT and PET_LIKE_CATEGORIES[key] ~= true,
            }
        end
    end
    table.sort(defs, function(a, b)
        return tostring(a.key) < tostring(b.key)
    end)
    St.CATEGORY_DEFS = defs
end

local function _defaultSendTotals()
    local totals = {}
    for _, def in ipairs(St.CATEGORY_DEFS) do
        totals[def.key] = MAX_BATCH
    end
    return totals
end

_ensureCfgCategoryTables = function()
    cfg.categories = type(cfg.categories) == "table" and cfg.categories or {}
    cfg.selected = type(cfg.selected) == "table" and cfg.selected or {}
    cfg.send_totals = type(cfg.send_totals) == "table" and cfg.send_totals or {}
    for _, def in ipairs(St.CATEGORY_DEFS) do
        local key = def.key
        if cfg.categories[key] == nil then
            cfg.categories[key] = false
        end
        if type(cfg.selected[key]) ~= "table" then
            cfg.selected[key] = {}
        end
        if cfg.send_totals[key] == nil then
            cfg.send_totals[key] = MAX_BATCH
        end
    end
end

end)()

local _petBaseTypeName, _findInventoryPetEntry, _petGroupDisplayName
;(function()
    local function _petDisplayName(raw)
        local name = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if name == "" then return nil end
        if type(raw) ~= "string" and type(raw) ~= "number" then return nil end
        if name:match("^[%x%-]+$") and #name >= 12 then return nil end
        return name
    end

    -- PetTypes module = Normal / Gold / Rainbow (mutasi), bukan spesies.
    local function _isPetMutationToken(raw)
        local k = string.lower(tostring(raw or "")):gsub("%s+", "")
        return k == "normal" or k == "gold" or k == "rainbow"
    end

    -- Inventory replica sering UUID + PetType/PetSize saja; nama spesies ada di Tool backpack.
    -- Index sekali / 2.5s — jangan GetDescendants Character (itu yang bikin freeze).
    local _petNameById, _petNameByIdAt = nil, 0
    local function _indexBackpackPetNames()
        if _petNameById and (os.clock() - _petNameByIdAt) < 2.5 then
            return _petNameById
        end
        local map = {}
        local function add(inst)
            if not inst or type(inst.GetAttribute) ~= "function" then return end
            if not inst:IsA("Tool") then
                if inst:GetAttribute("Pet") == nil
                    and inst:GetAttribute("PetName") == nil
                    and inst:GetAttribute("PetSpecies") == nil then
                    return
                end
            end
            local id = inst:GetAttribute("Id") or inst:GetAttribute("UUID")
                or inst:GetAttribute("PetId") or inst:GetAttribute("InstanceId")
            if id == nil then return end
            local name = inst:GetAttribute("PetName") or inst:GetAttribute("PetSpecies")
                or inst:GetAttribute("Species")
            if type(name) ~= "string" or name == "" then
                local petAttr = inst:GetAttribute("Pet")
                if type(petAttr) == "string" and petAttr ~= "" then
                    name = petAttr
                end
            end
            name = _petDisplayName(name)
            if name and _isPetMutationToken(name) then
                name = nil
            end
            if not name then
                local tn = _petDisplayName(inst.Name)
                if tn and not _isPetMutationToken(tn) and string.lower(tn) ~= "tool" then
                    name = tn
                end
            end
            if name then
                map[tostring(id)] = name
            end
        end
        local lp = LP or Players.LocalPlayer
        if lp then
            local bp = lp:FindFirstChild("Backpack") or lp:FindFirstChildOfClass("Backpack")
            if bp then
                for _, inst in ipairs(bp:GetDescendants()) do
                    if inst:IsA("Tool") then add(inst) end
                end
            end
            local char = lp.Character
            if char then
                for _, inst in ipairs(char:GetDescendants()) do
                    if inst:IsA("Tool") then add(inst) end
                end
            end
            local refs = workspace:FindFirstChild("PlayerPetReferences")
            local folder = refs and (refs:FindFirstChild(lp.Name) or refs:FindFirstChild(tostring(lp.UserId)))
            if folder then
                for _, slot in ipairs(folder:GetChildren()) do
                    add(slot)
                end
            end
        end
        _petNameById = map
        _petNameByIdAt = os.clock()
        return map
    end

    local function _formatPetLabel(base, petType, petSize)
        base = tostring(base or "Pet")
        local SectionBuyPet = G.SectionAutoBuyPet or rawget(_G, "SectionAutoBuyPet")
        if type(SectionBuyPet) == "table" then
            if type(SectionBuyPet.resolvePetTypeRaw) == "function" then
                petType = SectionBuyPet.resolvePetTypeRaw(petType)
            end
            if type(SectionBuyPet.resolvePetSizeRaw) == "function" then
                petSize = SectionBuyPet.resolvePetSizeRaw(petSize)
            end
        end
        local Webhook = G.Webhook or rawget(_G, "Webhook")
        if type(Webhook) == "table" and type(Webhook.formatPetDisplayName) == "function" then
            local ok, out = pcall(Webhook.formatPetDisplayName, base, petType, petSize)
            if ok and type(out) == "string" and out ~= "" then
                return out
            end
        end
        return base
    end

    -- HOT PATH: hanya field inventory. NO catalog Resolve, NO Backpack tool scan.
    -- (Catalog/tool × 2000 pet = freeze; list & candidate harus tetap ringan.)
    local function _petFromEntryOnly(entry, itemKey)
        local petType, petSize, base
        if type(entry) == "table" then
            petType = entry.PetType or entry.Mutation or entry.mutation
            petSize = entry.PetSize or entry.Size
            -- Spesies dulu. Jangan fallback ke PetType (itu mutasi Rainbow/Gold).
            local speciesFields = {
                entry.PetSpecies, entry.Species, entry.Pet, entry.PetName,
                entry.ItemName, entry.Name, entry.DisplayName,
            }
            for _, field in ipairs(speciesFields) do
                if not _isPetMutationToken(field) then
                    base = _petDisplayName(field)
                    if base then break end
                end
            end
            if not base then
                local t = entry.Type
                if t ~= nil and not _isPetMutationToken(t) then
                    base = _petDisplayName(t)
                end
            end
            if petType == nil and _isPetMutationToken(entry.Type) then
                petType = entry.Type
            end
        end
        if not base then
            local uid = _entryUniqueId(entry, itemKey) or tostring(itemKey or "")
            if uid ~= "" then
                base = _indexBackpackPetNames()[uid]
                if not base and type(St.equippedPetNames) == "table" then
                    base = St.equippedPetNames[uid]
                end
            end
        end
        if not base then
            local fromKey = _petDisplayName(itemKey)
            if fromKey and not _isPetMutationToken(fromKey) then
                base = fromKey
            else
                base = "Pet"
            end
        end
        return _formatPetLabel(base, petType, petSize), base, petType, petSize
    end

    _findInventoryPetEntry = function(_category, _itemKey, hintEntry)
        return hintEntry
    end

    _petBaseTypeName = function(entry, itemKey, _category)
        local _, base = _petFromEntryOnly(entry, itemKey)
        return base
    end

    _petGroupDisplayName = function(entry, itemKey, _category)
        local label = _petFromEntryOnly(entry, itemKey)
        return label
    end
end)()

local function _resolveDisplayName(category, itemKey, entry)
    if PET_LIKE_CATEGORIES[_canonicalCategory(category)] then
        return _petBaseTypeName(entry, itemKey, category)
    end
    if _ensureMailboxCatalog() then
        local ok, name = _invokeCatalog("Resolve", category, itemKey, entry)
        if ok and name ~= nil and tostring(name) ~= "" then
            return tostring(name)
        end
    end
    return tostring(itemKey)
end

local function _groupDisplayName(category, itemKey, entry)
    if _isHarvestedFruitsCategory(category) then
        return _fruitBaseTypeName(entry, itemKey)
    end
    if PET_LIKE_CATEGORIES[_canonicalCategory(category)] then
        return _petGroupDisplayName(entry, itemKey, category)
    end
    return _resolveDisplayName(category, itemKey, entry)
end

local function _mailboxUsable()
    local ok, flags = pcall(function()
        return require(ReplicatedStorage.SharedModules.Flags.MailboxFlags)
    end)
    if ok and type(flags) == "table" and flags.OpenEnabled then
        if type(flags.OpenEnabled.Get) == "function" then
            local okGet, enabled = pcall(flags.OpenEnabled.Get, flags.OpenEnabled)
            if okGet then
                return enabled == true
            end
        elseif type(flags.OpenEnabled) == "function" then
            local okCall, enabled = pcall(flags.OpenEnabled)
            if okCall then
                return enabled == true
            end
        end
    end
    return true
end

local function _isModuleMethodCall(first)
    return type(first) == "table" and type(first.BuildInventoryItems) == "function"
end

local function _categoryArg(first, second)
    if type(second) == "string" then return second end
    if type(first) == "string" then return first end
    return tostring(second or first or "")
end

local function _boolArg(first, second)
    if _isModuleMethodCall(first) then
        return second == true
    end
    return first == true
end

local function _configArg(first, second)
    if _isModuleMethodCall(first) then
        return second
    end
    return first
end

local function _strArg(first, second)
    if type(second) == "string" then return second end
    if type(first) == "string" then return first end
    return tostring(second or first or "")
end

function M.GetInventory(_self)
    return _getInventory(5)
end

function M.GetPlayerStatePath()
    return "ReplicatedStorage.ClientModules.PlayerStateClient -> GetLocalReplica().Data.Inventory"
end

function M.GetCatalogPath()
    if St.catalogModuleInst and St.catalogModuleInst.Parent then
        return St.catalogModuleInst:GetFullName()
    end
    return "StarterPlayer.StarterPlayerScripts.Controllers.MailboxController.MailboxItemCatalog"
end

function M.ReloadCatalog(a, b)
    local force = _boolArg(a, b)
    _ensureMailboxCatalog(force)
    _rebuildCategoryDefs()
    _ensureCfgCategoryTables()
    if not St.catalogLoadedFromGame then
        _setStatus("MailboxItemCatalog not loaded")
    elseif #St.CATEGORY_DEFS == 0 then
        _setStatus("Mailbox categories empty")
    end
end

function M.IsCatalogLoaded(_self)
    return St.catalogLoadedFromGame == true and #St.CATEGORY_DEFS > 0
end

function M.ListInventoryKeys(_self)
    local inv = _getInventory(5)
    if not inv then return {} end
    local keys = {}
    for key, bag in pairs(inv) do
        if type(bag) == "table" then
            keys[#keys + 1] = tostring(key)
        end
    end
    table.sort(keys)
    return keys
end

local function _categoryEnabled(key)
    key = _canonicalCategory(key)
    if cfg.categories[key] == true then return true end
    for legacy, canon in pairs(SAVE_CATEGORY_ALIASES) do
        if canon == key and cfg.categories[legacy] == true then return true end
    end
    return false
end

local function _categorySelected(key)
    key = _canonicalCategory(key)
    local sel = cfg.selected[key]
    if type(sel) ~= "table" then sel = {} end
    local out = _normalizeSet(sel)
    for legacy, canon in pairs(SAVE_CATEGORY_ALIASES) do
        if canon == key then
            local leg = cfg.selected[legacy]
            if type(leg) == "table" then
                for k, v in pairs(_normalizeSet(leg)) do
                    if v == true then out[k] = true end
                end
            end
        end
    end
    return out
end

local function _enabledCategoryKeys()
    local out = {}
    local seen = {}
    for _, def in ipairs(St.CATEGORY_DEFS) do
        if _categoryEnabled(def.key) then
            out[#out + 1] = def.key
            seen[def.key] = true
        end
    end
    -- Multi/Once can enable Harvest before catalog defs are ready; keep those keys.
    if type(cfg.categories) == "table" then
        for key, on in pairs(cfg.categories) do
            if on == true then
                local canon = _canonicalCategory(key)
                if canon ~= "" and not seen[canon] then
                    out[#out + 1] = canon
                    seen[canon] = true
                end
            end
        end
    end
    return out
end

local function _onceUsesPriceMode()
    if _normalizeSendListMode(cfg.send_list_mode) ~= "send_total" then
        return false
    end
    if _normalizeOnceSendMode(cfg.once_send_mode) ~= "price" then
        return false
    end
    for _, cat in ipairs(_enabledCategoryKeys()) do
        if _isHarvestedFruitsCategory(cat) then
            return true
        end
    end
    -- Direct cfg check: ApplyConfig used to drop Harvest when missing from CATEGORY_DEFS.
    if type(cfg.categories) == "table" then
        for key, on in pairs(cfg.categories) do
            if on == true and _isHarvestedFruitsCategory(key) then
                return true
            end
        end
    end
    return false
end

local function _onceSendUnitTarget()
    if cfg.send_all == true then
        return 0
    end
    local first = nil
    for _, cat in ipairs(_enabledCategoryKeys()) do
        local t = cfg.send_totals and cfg.send_totals[cat]
        if t ~= nil then
            local n = _normalizeSendTotalInput(t)
            -- 0 di category manapun = send all (jangan ambil cat pertama yang 20)
            if n == 0 then
                return 0
            end
            if first == nil then
                first = n
            end
        end
    end
    return first or 20
end

local function _matchesSelected(category, name, selectedMap, itemKey, entry)
    if not next(selectedMap) then return false end
    if itemKey ~= nil and selectedMap[tostring(itemKey)] == true then return true end
    local uid = _entryUniqueId(entry, itemKey)
    if uid and selectedMap[uid] == true then return true end
    name = tostring(name or "")
    if name ~= "" and selectedMap[name] == true then return true end

    local cat = _canonicalCategory(category)
    local normName = _normalizeFruitGroupKey(name)
    if PET_LIKE_CATEGORIES[cat] then
        -- Jangan catalog Resolve per pet (2000× = freeze)
        if name ~= "" then
            for k, v in pairs(selectedMap) do
                if v == true then
                    local sk = tostring(k):gsub("%s*x%s+.+$", "")
                    if sk == name then return true end
                    if _normalizeFruitGroupKey(sk) == normName then return true end
                end
            end
        end
        if type(entry) == "table" then
            for _, field in ipairs({ entry.PetType, entry.Type, entry.PetName, entry.Name }) do
                local f = tostring(field or "")
                if f ~= "" and selectedMap[f] == true then
                    return true
                end
            end
        end
        return false
    end

    local norm = name:lower():gsub("[%s_%-]+", "")
    for k, v in pairs(selectedMap) do
        if v == true then
            local sk = tostring(k):gsub("%s*x%s+.+$", "")
            if sk == name then return true end
            if sk:lower():gsub("[%s_%-]+", "") == norm then return true end
            if normName ~= "" and _normalizeFruitGroupKey(sk) == normName then
                return true
            end
        end
    end
    if entry ~= nil and _ensureMailboxCatalog() then
        local ok, resolved = _invokeCatalog("Resolve", category, itemKey, entry)
        if ok and resolved ~= nil and selectedMap[tostring(resolved)] == true then
            return true
        end
    end
    return false
end

local function _loopSendAllWhenUnselected()
    -- loop = kirim semua; send_total (Mail Once) = list kosong juga kirim semua di category
    local mode = _normalizeSendListMode(cfg.send_list_mode)
    return mode == "loop" or mode == "send_total"
end

local function _includeGiftEntry(sendCat, displayName, selectedMap, itemKey, entry, harvestCat)
    if next(selectedMap) then
        return _matchesSelected(sendCat, displayName, selectedMap, itemKey, entry)
    end
    if harvestCat or _loopSendAllWhenUnselected() then
        return true
    end
    return false
end

local function _fruitTypeName(entry, itemKey)
    return _fruitBaseTypeName(entry, itemKey)
end

local function _isEquippedItemLegacy(itemKey, entry)
    if cfg.skip_equipped ~= true then return false end
    if type(entry) == "table" then
        local id = entry.Id or entry.UUID or entry.PetId or entry.InstanceId
            or entry.Guid or entry.UniqueId or entry.PetUUID
        if id ~= nil and St.equippedPets[tostring(id)] then return true end
        if entry.Equipped == true then return true end
    end
    if itemKey ~= nil and St.equippedPets[tostring(itemKey)] then return true end
    return false
end

local function _entryCount(entry)
    if type(entry) == "number" then return entry end
    local n = tonumber(entry)
    if type(n) == "number" then return n end
    if type(entry) == "table" then
        return tonumber(entry.Count or entry.Amount or entry.Quantity or entry.Stack or entry.Qty)
    end
    return nil
end

local function _isOwnedEntry(category, itemKey, entry)
    if type(entry) == "table" then
        if _isUniqueInventoryEntry(entry, itemKey) then
            return true
        end
        local n = _entryCount(entry)
        return type(n) == "number" and n > 0
    end
    local n = tonumber(entry)
    return type(n) == "number" and n > 0
end

local function _isGiftableEntry(category, itemKey, entry)
    category = _canonicalCategory(category)
    if type(entry) == "table" then
        if _isUniqueInventoryEntry(entry, itemKey) then
            if _isEquippedItemLegacy(itemKey, entry) then return false end
            return true
        end
        local n = _entryCount(entry)
        return type(n) == "number" and n > 0
    end
    local n = tonumber(entry)
    return type(n) == "number" and n > 0
end

local function _selectedMapForUi(category)
    local sel = _categorySelected(category)
    if next(sel) then return sel end
    local store = G.__GAG2_AUTO_GIFT or _G.__GAG2_AUTO_GIFT
    if type(store) == "table" and type(store.selected) == "table" then
        local cat = _canonicalCategory(category)
        local raw = store.selected[cat]
        if type(raw) == "table" then
            local out = _normalizeSet(raw)
            if next(out) then return out end
        end
        for legacy, canon in pairs(SAVE_CATEGORY_ALIASES) do
            if canon == cat and type(store.selected[legacy]) == "table" then
                local out = _normalizeSet(store.selected[legacy])
                if next(out) then return out end
            end
        end
    end
    return sel
end

local function _appendSelectedZeroItems(items, category, selectedOverride)
    items = type(items) == "table" and items or {}
    local selectedMap
    if type(selectedOverride) == "table" then
        selectedMap = _normalizeSet(selectedOverride)
    else
        selectedMap = _selectedMapForUi(category)
    end
    if not next(selectedMap) then return items end

    local have = {}
    local haveNorm = {}
    for _, it in ipairs(items) do
        local k = tostring(it.key)
        have[k] = true
        local base = k:gsub("%s*x%s+.+$", "")
        haveNorm[_normalizeFruitGroupKey(base)] = true
    end
    for selKey, on in pairs(selectedMap) do
        if on == true then
            local sk = tostring(selKey)
            local norm = _normalizeFruitGroupKey(sk:gsub("%s*x%s+.+$", ""))
            if not have[sk] and not haveNorm[norm] then
                items[#items + 1] = {
                    key = sk,
                    name = sk .. " x 0",
                    right = "0",
                    count = 0,
                }
            end
        end
    end
    table.sort(items, function(a, b) return a.name < b.name end)
    return items
end

local function _buildInventoryItems(category, selectedOverride)
    category = _canonicalCategory(tostring(category or ""))
    if category == "" then return {} end

    -- Cache pet-like list: refreshItems/WS sering panggil tanpa buka dropdown.
    local useCache = PET_LIKE_CATEGORIES[category] == true and selectedOverride == nil
    if useCache then
        local cached = St._invItemsCache and St._invItemsCache[category]
        if type(cached) == "table" and type(cached.items) == "table"
            and (os.clock() - (cached.at or 0)) < 2.5 then
            return cached.items
        end
    end

    -- List harus cepat: jangan poll/wait di sini (itu yang bikin lag buka dropdown)
    if category == "EmptyPots" then
        EmptyPotsBagUtil.invalidate()
    end

    local inv = _getInventory(10)
    if not inv and not _isHarvestedFruitsCategory(category) and not _isExtraGiftCategory(category) then
        return _appendSelectedZeroItems({}, category, selectedOverride)
    end

    local bag, sendCat = _getInventoryBag(inv, category)
    if type(bag) ~= "table" then return _appendSelectedZeroItems({}, category, selectedOverride) end
    sendCat = sendCat or category

    -- Pets: jangan load Mailbox catalog di sini (Resolve × N pet = lag parah).
    if not PET_LIKE_CATEGORIES[category] then
        _ensureMailboxCatalog()
    end
    if not _categoryAllowedForGift(category) and not next(bag) then
        return _appendSelectedZeroItems({}, category, selectedOverride)
    end

    local items = {}
    local countBased = _isCountBasedCategory(sendCat, inv)

    if countBased then
        _eachBagEntry(bag, function(itemKey, count)
            if type(count) == "table" then
                if _isUniqueInventoryEntry(count, itemKey) and (tonumber(_entryCount(count)) or 0) <= 1 then
                    if _isOwnedEntry(sendCat, itemKey, count) then
                        local typeName = _resolveDisplayName(sendCat, itemKey, count)
                        items[#items + 1] = {
                            key = typeName,
                            name = typeName .. " x 1",
                            right = "1",
                            count = 1,
                        }
                    end
                    return
                end
                count = _entryCount(count) or 0
            else
                count = tonumber(count) or 0
            end
            if _isOwnedEntry(sendCat, itemKey, count) then
                local key = tostring(itemKey)
                local displayName = _resolveDisplayName(sendCat, itemKey, type(count) == "table" and count or nil)
                items[#items + 1] = {
                    key = key,
                    name = displayName .. " x " .. M._formatCount(count),
                    right = M._formatCount(count),
                    count = count,
                }
            end
        end)
        table.sort(items, function(a, b) return a.key < b.key end)
        local out = _appendSelectedZeroItems(items, category, selectedOverride)
        if useCache then
            St._invItemsCache = St._invItemsCache or {}
            St._invItemsCache[category] = { at = os.clock(), items = out }
        end
        return out
    end

    local grouped = {}
    _eachBagEntry(bag, function(itemKey, entry)
        if _isOwnedEntry(sendCat, itemKey, entry) then
            local typeName = _groupDisplayName(sendCat, itemKey, entry)
            local groupKey = _normalizeFruitGroupKey(typeName)
            local slot = grouped[groupKey]
            if not slot then
                slot = { name = typeName, count = 0, value = 0 }
                grouped[groupKey] = slot
            end
            if type(entry) == "number" or (tonumber(entry) and type(entry) ~= "table") then
                local n = math.floor(tonumber(entry) or 0)
                if n > 0 then
                    slot.count += n
                    -- Stack count (number bag): value = unit sell price × qty (total for type).
                    if _isHarvestedFruitsCategory(sendCat) then
                        local unit = tonumber(_entrySellPrice(sendCat, itemKey, nil)) or 0
                        if unit > 0 then
                            slot.value += unit * n
                        end
                    end
                else
                    slot.count += 1
                    if _isHarvestedFruitsCategory(sendCat) then
                        slot.value += tonumber(_entrySellPrice(sendCat, itemKey, entry)) or 0
                    end
                end
            else
                -- Unique fruit rows (UUID → entry): each row is 1 fruit; sum sell prices = total for type.
                slot.count += 1
                if _isHarvestedFruitsCategory(sendCat) then
                    slot.value += tonumber(_entrySellPrice(sendCat, itemKey, entry)) or 0
                end
            end
        end
    end)

    for _, slot in pairs(grouped) do
        local totalVal = math.floor(tonumber(slot.value) or 0)
        items[#items + 1] = {
            key = slot.name,
            name = slot.name .. " x " .. M._formatCount(slot.count),
            right = M._formatCount(slot.count),
            count = slot.count,
            -- value / total_value = TOTAL jual semua fruit tipe ini (bukan harga 1 buah).
            value = totalVal,
            total_value = totalVal,
            value_is_total = true,
        }
    end
    table.sort(items, function(a, b) return a.name < b.name end)
    local out = _appendSelectedZeroItems(_dedupeInventoryItems(items), category, selectedOverride)
    if useCache then
        St._invItemsCache = St._invItemsCache or {}
        St._invItemsCache[category] = { at = os.clock(), items = out }
    end
    return out
end

function M.BuildInventoryItems(a, b, c)
    if _isModuleMethodCall(a) then
        return _buildInventoryItems(_categoryArg(a, b), type(c) == "table" and c or nil)
    end
    if type(b) == "table" then
        return _buildInventoryItems(_categoryArg(a, nil), b)
    end
    return _buildInventoryItems(_categoryArg(a, b), nil)
end

function M.PeekCategory(a, b)
    local category = _canonicalCategory(_categoryArg(a, b))
    _ensureMailboxCatalog()
    local inv = _getInventory(5)
    local bag, sendCat = _getInventoryBag(inv, category)
    print("[AutoGift] peek", category, "bag=", type(bag), "countBased=", inv and _isCountBasedCategory(sendCat, inv))
    if type(bag) == "table" then
        local n = 0
        _eachBagEntry(bag, function(k, e)
            n += 1
            if n <= 5 then
                print("  raw", k, type(e), "giftable=", _isGiftableEntry(sendCat, k, e),
                    "name=", _resolveDisplayName(sendCat, k, e))
            end
        end)
        print("  entries=", n, "ui items=", #_buildInventoryItems(category))
    end
end

M.PackCategory = M.PeekCategory

function M.DebugCategory(a, b)
    local category = _canonicalCategory(_categoryArg(a, b))
    if category == "" then
        warn("[AutoGift] DebugCategory: pass a category name, e.g. DebugCategory(ag, \"Pets\")")
        return
    end
    _ensureMailboxCatalog(true)
    local inv = _getInventory(10)
    local bag, sendCat = _getInventoryBag(inv, category)
    sendCat = sendCat or category
    local lines = {
        "[AutoGift] DebugCategory " .. category,
        "  catalogLoaded=" .. tostring(St.catalogLoadedFromGame),
        "  giftable=" .. tostring(_catalogIsGiftable(category)),
        "  inventory=" .. tostring(inv ~= nil),
        "  bag=" .. tostring(type(bag)),
        "  bagEntries=" .. tostring(bag and _bagHasEntries(bag)),
        "  countBased=" .. tostring(inv and _isCountBasedCategory(sendCat, inv)),
        "  uiItems=" .. tostring(#_buildInventoryItems(category)),
    }
    if type(bag) == "table" then
        local n = 0
        _eachBagEntry(bag, function(k, e)
            n += 1
            if n <= 8 then
                lines[#lines + 1] = "  [" .. n .. "] " .. tostring(k) .. " type=" .. type(e)
                    .. " owned=" .. tostring(_isOwnedEntry(sendCat, k, e))
                    .. " sendable=" .. tostring(_isGiftableEntry(sendCat, k, e))
                    .. " name=" .. tostring(_resolveDisplayName(sendCat, k, e))
            end
        end)
        lines[#lines + 1] = "  rawCount=" .. tostring(n)
    end
    local out = table.concat(lines, "\n")
    print(out)
    return out
end

function M.DebugHarvestSend(a, b)
    local category = _canonicalCategory(_categoryArg(a, b))
    if category == "" then category = "HarvestedFruits" end
    if not _isHarvestedFruitsCategory(category) then
        warn("[AutoGift] DebugHarvestSend: use HarvestedFruits category")
        return nil
    end

    M.InvalidateHarvestFruitCache()
    _ensureMailboxCatalog()

    local lines = { "[AutoGift] DebugHarvestSend " .. category }
    lines[#lines + 1] = "  --- UI list (key = pilih di dropdown, name = tampilan) ---"
    for _, it in ipairs(_buildInventoryItems(category)) do
        lines[#lines + 1] = ("  UI  key=%s  name=%s"):format(
            tostring(it.key or ""),
            tostring(it.name or "")
        )
    end

    lines[#lines + 1] = "  --- Send candidates (ItemKey = yang dikirim ke server) ---"
    local candidates = _collectCandidates()
    local harvestN = 0
    for _, item in ipairs(candidates) do
        if _isHarvestedFruitsCategory(item.Category) then
            harvestN += 1
            if harvestN <= 12 then
                lines[#lines + 1] = ("  SEND  ItemKey=%s  Count=%s"):format(
                    tostring(item.ItemKey or ""),
                    tostring(item.Count or 1)
                )
            end
        end
    end
    lines[#lines + 1] = "  harvestCandidates=" .. tostring(harvestN)
        .. " totalCandidates=" .. tostring(#candidates)
    lines[#lines + 1] = "  mailboxUniquePerSend=" .. tostring(MAILBOX_UNIQUE_PER_SEND)
        .. " (harvested fruits kirim per batch, bukan 100 sekaligus)"

    local out = table.concat(lines, "\n")
    print(out)
    return {
        category = category,
        uiItems = _buildInventoryItems(category),
        candidates = candidates,
        harvestCount = harvestN,
    }
end

M.debugHarvestSend = M.DebugHarvestSend

local function _collectCandidatesForCategory(inv, category, selectedMap, allowUnselected)
    local out = {}
    local cat = _canonicalCategory(tostring(category or ""))
    if cat == "" then return out end

    selectedMap = type(selectedMap) == "table" and selectedMap or {}
    local bag, sendCat = _getInventoryBag(inv, cat)
    local harvestCat = _isHarvestedFruitsCategory(sendCat)
    if not harvestCat and not next(selectedMap) and not allowUnselected then
        return out
    end
    if type(bag) ~= "table" then return out end

    if _isCountBasedCategory(sendCat, inv) then
        -- Stack category: Seed/Gear/dll → Count = qty stack. Unique entry di bag = 1.
        _eachBagEntry(bag, function(itemKey, count)
            local entryTable = (type(count) == "table") and count or nil
            local units = 0
            if entryTable then
                units = math.floor(tonumber(_entryCount(entryTable)) or 0)
                if units < 1 and _isUniqueInventoryEntry(entryTable, itemKey) then
                    units = 1
                end
            else
                units = math.floor(tonumber(count) or 0)
            end
            if units < 1 then
                return
            end
            local displayName = _resolveDisplayName(sendCat, itemKey, entryTable)
            if _isGiftableEntry(sendCat, itemKey, entryTable or units)
                and _includeGiftEntry(sendCat, displayName, selectedMap, itemKey, entryTable, harvestCat) then
                out[#out + 1] = {
                    Category = sendCat,
                    ItemKey = tostring(itemKey),
                    Count = units,
                    SortKey = tostring(itemKey),
                    Entry = entryTable,
                    SellPrice = 0,
                }
            end
        end)
    else
        -- Unique category: Pet/Fruit/dll → tiap entry = 1 unit
        _eachBagEntry(bag, function(itemKey, entry)
            if _isGiftableEntry(sendCat, itemKey, entry) then
                if harvestCat and M._GiftUnfav.skipFavorited() and _isHarvestEntryFavorited(itemKey, entry) then
                    return
                end
                local typeName = _groupDisplayName(sendCat, itemKey, entry)
                if _includeGiftEntry(sendCat, typeName, selectedMap, itemKey, entry, harvestCat) then
                    local mailKey = harvestCat
                        and _resolveHarvestFruitItemKey(itemKey, entry)
                        or tostring(itemKey)
                    if mailKey then
                        local sellPrice = harvestCat and _entrySellPrice(sendCat, itemKey, entry) or 0
                        out[#out + 1] = {
                            Category = sendCat,
                            ItemKey = mailKey,
                            Count = 1,
                            SortKey = typeName .. ":" .. mailKey,
                            Entry = type(entry) == "table" and entry or nil,
                            SellPrice = sellPrice,
                        }
                    end
                end
            end
        end)
    end

    table.sort(out, function(a, b)
        return tostring(a.SortKey) < tostring(b.SortKey)
    end)
    return out
end

function M.CollectCategoryCandidates(a, b, c)
    local category = a
    local selectedMap = b
    if type(a) == "table" and type(b) == "string" then
        category = b
        selectedMap = c
    end
    if type(_ensureFsvFresh) == "function" then
        _ensureFsvFresh(true)
    end
    return _collectCandidatesForCategory(
        _getInventory(0),
        category,
        selectedMap,
        _loopSendAllWhenUnselected()
    )
end

function M.GetHarvestFruitBag(_self, forceRefresh)
    return _getBackpackFruitBag(forceRefresh == true)
end

local function _collectCandidates()
    if type(_ensureFsvFresh) == "function" then
        _ensureFsvFresh(true)
    end
    if _categoryEnabled("EmptyPots") then
        EmptyPotsBagUtil.invalidate()
    end
    local inv = _getInventory(0)

    local out = {}
    for _, def in ipairs(St.CATEGORY_DEFS) do
        local cat = def.key
        if _categoryEnabled(cat) then
            local selectedMap = _categorySelected(cat)
            local harvestCat = _isHarvestedFruitsCategory(cat)
            if not harvestCat and not next(selectedMap) and not _loopSendAllWhenUnselected() then
                continue
            end
            local chunk = _collectCandidatesForCategory(
                inv,
                cat,
                selectedMap,
                _loopSendAllWhenUnselected()
            )
            for _, row in ipairs(chunk) do
                out[#out + 1] = row
            end
        end
    end

    table.sort(out, function(a, b)
        return tostring(a.SortKey) < tostring(b.SortKey)
    end)
    return out
end

local function _sumCandidateUnits(candidates)
    local n = 0
    for _, item in ipairs(candidates) do
        n += math.max(0, math.floor(tonumber(item.Count) or 1))
    end
    return n
end

local function _sumCandidatePrice(candidates)
    local total = 0
    for _, item in ipairs(candidates) do
        local price = math.floor(tonumber(item.SellPrice) or 0)
        if price <= 0 and not _isCountBasedCategory(item.Category, _getInventory(0)) then
            price = _entrySellPrice(item.Category, item.ItemKey, item.Entry)
            item.SellPrice = price
        end
        if price > 0 then
            total += price
        end
    end
    return total
end

function M.CountSendableUnits(_self)
    return _sumCandidateUnits(_collectCandidates())
end

function M.CountSendablePrice(_self)
    return _sumCandidatePrice(_collectCandidates())
end

function M.CheckSendTotalAvailability(_self, target, priceMode)
    target = math.floor(tonumber(target) or 0)
    if target < 1 then
        return true
    end
    if priceMode == nil then
        priceMode = _onceUsesPriceMode()
    else
        priceMode = priceMode == true
    end
    M.InvalidateHarvestFruitCache()
    local candidates = _collectCandidates()
    if priceMode then
        local available = _sumCandidatePrice(candidates)
        if available < 1 then
            return false, "Tidak ada item giftable di inventory untuk category terpilih"
        end
        if available < target then
            return false, "Value kurang: punya "
                .. _formatSellPrice(available)
                .. ", butuh "
                .. _formatSellPrice(target)
        end
    else
        local available = _sumCandidateUnits(candidates)
        if available < 1 then
            if _categoryEnabled("EmptyPots") then
                return false, "EmptyPots belum di PlayerState (kadang sync lambat). Buka Mailbox→Send lalu refresh."
            end
            return false, "Tidak ada item giftable di inventory untuk category terpilih"
        end
        if available < target then
            return false, "Item kurang: punya "
                .. tostring(available)
                .. ", butuh "
                .. tostring(target)
        end
    end
    return true
end

function M.PreviewHarvestPricePlan(_self)
    if not _onceUsesPriceMode() then
        return {
            ok = false,
            text = "Mode count — bukan price search",
        }
    end
    if _normalizeSendTotalInput(cfg.send_total) == 0 then
        return {
            ok = true,
            text = "Send all selected",
        }
    end
    local cacheKey = string.format(
        "mb|%d|%s|%s|%s",
        _pricePlanEpoch,
        tostring(cfg.send_total or 0),
        tostring(cfg.harvest_price_threshold_pct or 0),
        tostring(cfg.harvest_price_calc_mode or "base")
    )
    if type(_pricePlanPreviewCache) == "table" and _pricePlanPreviewCache.key == cacheKey then
        return _pricePlanPreviewCache.val
    end

    local target = _clampSendTotalGoal(cfg.send_total)
    local minSum, maxSum = _priceRangeForRemain(target)
    local candidates = _collectCandidates()
    local batchLimit = math.min(MAILBOX_UNIQUE_PER_SEND, _batchSendLimit(candidates, nil))
    local pick, total, poolSize, batchCount = _buildMultiBatchPricePlan(
        candidates,
        minSum,
        maxSum,
        batchLimit
    )
    local result
    if not pick or #pick == 0 then
        local text = _pricePlanSummary(nil, total or 0, minSum, maxSum, poolSize or 0, batchCount)
        result = {
            ok = false,
            minTotal = minSum,
            maxTotal = maxSum,
            poolSize = poolSize or 0,
            text = text,
        }
    else
        local text = _pricePlanSummary(pick, total, minSum, maxSum, poolSize, batchCount)
        result = {
            ok = true,
            minTotal = minSum,
            maxTotal = maxSum,
            total = total,
            count = #pick,
            poolSize = poolSize,
            batchCount = batchCount,
            breakdown = _formatPriceBreakdown(pick),
            text = text,
        }
    end
    _pricePlanPreviewCache = { key = cacheKey, val = result }
    return result
end

local function _buildBatch(candidates, maxItems, totalRemaining)
    maxItems = _clampBatch(maxItems)
    if totalRemaining ~= nil then
        totalRemaining = math.max(0, math.floor(tonumber(totalRemaining) or 0))
        maxItems = math.min(maxItems, totalRemaining)
    end
    if maxItems <= 0 then return {}, 0 end

    local batch = {}
    local used = 0
    local catUsed = {}
    local unitsLeft = totalRemaining
    local inv = _getInventory(0)

    for _, item in ipairs(candidates) do
        if #batch >= MAILBOX_UNIQUE_PER_SEND then
            break
        end

        local cat = item.Category
        local countBased = _isCountBasedCategory(cat, inv)
        if countBased and used >= maxItems then
            break
        end

        local catLimit = _categorySendLimit(cat)
        local cu = catUsed[cat] or 0
        if cu >= catLimit then
            continue
        end

        local count = tonumber(item.Count) or 1
        if countBased then
            local room = math.min(maxItems - used, catLimit - cu)
            if unitsLeft ~= nil then
                room = math.min(room, unitsLeft)
            end
            count = math.min(count, room)
            -- Pecah Count >9999 jadi beberapa row ItemKey sama (max 20 row/batch).
            while count > 0 and #batch < MAILBOX_UNIQUE_PER_SEND do
                local chunk = math.min(MAILBOX_STACK_PER_ROW, count)
                batch[#batch + 1] = {
                    Category = item.Category,
                    ItemKey = item.ItemKey,
                    Count = chunk,
                    Entry = item.Entry,
                }
                used += chunk
                cu += chunk
                catUsed[cat] = cu
                if unitsLeft ~= nil then
                    unitsLeft -= chunk
                end
                count -= chunk
            end
        elseif unitsLeft == nil or unitsLeft > 0 then
            batch[#batch + 1] = {
                Category = item.Category,
                ItemKey = item.ItemKey,
                Count = 1,
                Entry = item.Entry,
            }
            used += 1
            catUsed[cat] = cu + 1
            if unitsLeft ~= nil then
                unitsLeft -= 1
            end
        end
    end

    return batch, used
end

local _resetSendJobHistory, _flushSendJobHistory, _commitGiftHistory
;(function()
    local function _accumulateSendJobHistory(batchSnap, totalSnap, sendBatchNum, histMsg)
        local acc = St.sendJobHistoryAcc
        if type(acc) ~= "table" then return end
        for _, row in ipairs(batchSnap) do
            if type(row) == "table" then
                acc.rows[#acc.rows + 1] = {
                    Category = row.Category,
                    Name = row.Name,
                    Count = row.Count,
                    UnitPrice = row.UnitPrice,
                }
                if _isHarvestedFruitsCategory(row.Category) then
                    local cnt = math.max(1, math.floor(tonumber(row.Count) or 1))
                    local unit = math.max(0, math.floor(tonumber(row.UnitPrice) or 0))
                    if unit > 0 then
                        acc.totalHarvestPrice = (acc.totalHarvestPrice or 0) + (unit * cnt)
                    end
                end
            end
        end
        acc.totalUnits += math.max(0, math.floor(tonumber(totalSnap) or 0))
        local bn = math.max(1, math.floor(tonumber(sendBatchNum) or 1))
        if bn > acc.batchCount then
            acc.batchCount = bn
        end
        if histMsg and tostring(histMsg) ~= "" then
            acc.lastMsg = tostring(histMsg)
        end
    end

    local function _writeGiftHistoryRecord(batchSnap, totalSnap, sendBatchNum, histMsg, harvestTotalHint)
        if type(batchSnap) ~= "table" or #batchSnap == 0 then return end
        local hist = G.GiftMailHistoryModule or G.GiftMailHistory
            or rawget(_G, "GiftMailHistoryModule") or rawget(_G, "GiftMailHistory")
        if type(hist) ~= "table" then return end

        totalSnap = math.max(0, math.floor(tonumber(totalSnap) or 0))
        sendBatchNum = math.max(1, math.floor(tonumber(sendBatchNum) or 1))
        histMsg = tostring(histMsg or "")

        local harvestTotalPrice = math.max(0, math.floor(tonumber(harvestTotalHint) or 0))
        if harvestTotalPrice <= 0 then
            for _, row in ipairs(batchSnap) do
                if type(row) == "table" and _isHarvestedFruitsCategory(row.Category) then
                    local cnt = math.max(1, math.floor(tonumber(row.Count) or 1))
                    local unit = math.max(0, math.floor(tonumber(row.UnitPrice) or 0))
                    if unit > 0 then
                        harvestTotalPrice += unit * cnt
                    end
                end
            end
        end

        local multiActive = (G.__GAG2_GIFT_MULTI_ACTIVE == true)
            or (rawget(_G, "__GAG2_GIFT_MULTI_ACTIVE") == true)
        local histProfile = multiActive and "multi"
            or ((cfg.auto_send == true) and "loop" or "once")
        -- sendBatchNum = nomor batch kirim mailbox (bukan urutan target Multi)

        local opts = {
            total = totalSnap,
            success = true,
            msg = histMsg,
            sendBatchNum = sendBatchNum,
            cfg = cfg,
            auto_send = cfg.auto_send,
            profile = histProfile,
            harvest_total_price = harvestTotalPrice > 0 and harvestTotalPrice or nil,
        }

        if type(hist.RecordSendBatch) == "function" then
            pcall(hist.RecordSendBatch, batchSnap, opts)
            return
        end
        if type(hist.Record) ~= "function" then return end

        local uid = math.floor(tonumber(cfg.recipient_user_id) or 0)
        local user = tostring(cfg.recipient_username or "")
        local disp = tostring(cfg.recipient_display or "")
        if uid <= 0 then
            local s = G.__GAG2_AUTO_GIFT or rawget(_G, "__GAG2_AUTO_GIFT")
            local p = (type(s) == "table" and type(s.once) == "table") and s.once or s
            if type(p) == "table" then
                uid = math.floor(tonumber(p.recipient_user_id) or 0)
                if user == "" then user = tostring(p.recipient_username or "") end
                if disp == "" then disp = tostring(p.recipient_display or "") end
            end
        end

        pcall(hist.Record, {
            ts = os.time(),
            profile = histProfile,
            success = true,
            recipient_user_id = uid,
            recipient_username = user,
            recipient_display = disp,
            item_count = totalSnap,
            send_batch = sendBatchNum,
            batch_rows = #batchSnap,
            note = tostring(cfg.note or ""),
            message = histMsg,
            items = batchSnap,
        })
    end

    _resetSendJobHistory = function()
        St.sendJobHistoryAcc = {
            rows = {},
            totalUnits = 0,
            totalHarvestPrice = 0,
            batchCount = 0,
            lastMsg = "",
        }
    end

    _flushSendJobHistory = function(jobOk, failReason)
        local acc = St.sendJobHistoryAcc
        St.sendJobHistoryAcc = nil
        if type(acc) ~= "table" or #acc.rows == 0 then return end
        local msg = tostring(acc.lastMsg or "")
        local units = math.max(0, math.floor(tonumber(acc.totalUnits) or 0))
        if jobOk ~= true then
            local why = tostring(failReason or "")
            if why == "" or why == "false" or why == "nil" then
                why = tostring(stats.lastStatus or "")
            end
            msg = "Partial (" .. tostring(units) .. " item terkirim)"
            if why ~= "" then
                msg = msg .. " — " .. why
            end
        elseif msg == "" then
            msg = "Gift sent! (" .. tostring(units) .. " item)"
        end
        _writeGiftHistoryRecord(
            acc.rows,
            acc.totalUnits,
            acc.batchCount,
            msg,
            acc.totalHarvestPrice
        )
    end

    _commitGiftHistory = function(batchSnap, totalSnap, sendBatchNum, histMsg)
        if St.sendJobRunning and type(St.sendJobHistoryAcc) == "table" then
            _accumulateSendJobHistory(batchSnap, totalSnap, sendBatchNum, histMsg)
            return
        end
        _writeGiftHistoryRecord(batchSnap, totalSnap, sendBatchNum, histMsg)
    end
end)()

local function _fireSendBatch(batch, total, sendBatchNum)
    if #batch == 0 or total <= 0 then
        return false, "empty_batch"
    end

    local batchSnap = {}
    for _, row in ipairs(batch) do
        if type(row) == "table" then
            local cat = tostring(row.Category or "")
            local ikey = tostring(row.ItemKey or row.ItemName or "")
            local src = type(row.Entry) == "table" and row.Entry or row
            if _isHarvestedFruitsCategory(cat) then
                local fid = _resolveHarvestFruitItemKey(ikey, src)
                if fid and type(_getBackpackFruitBag) == "function" then
                    local bag = _getBackpackFruitBag(false)
                    if type(bag) == "table" and type(bag[fid]) == "table" then
                        src = bag[fid]
                        ikey = fid
                    end
                end
            elseif PET_LIKE_CATEGORIES[_canonicalCategory(cat)] then
                src = _findInventoryPetEntry(cat, ikey, src)
            end
            local dname = _groupDisplayName(cat, ikey, src)
            if dname:match("^[%x%-]+$") and #dname >= 12 then
                if _isHarvestedFruitsCategory(cat) then
                    dname = _fruitBaseTypeName(src, ikey)
                elseif PET_LIKE_CATEGORIES[_canonicalCategory(cat)] then
                    dname = _petBaseTypeName(src, ikey, cat)
                end
                if dname:match("^[%x%-]+$") and #dname >= 12 then
                    dname = (PET_LIKE_CATEGORIES[_canonicalCategory(cat)] and "Pet")
                        or (cat == "Seeds" and "Seed")
                        or (cat == "Eggs" and "Egg")
                        or (_isHarvestedFruitsCategory(cat) and "Fruit") or cat
                end
            end
            local unitPrice = 0
            if _isHarvestedFruitsCategory(cat) then
                unitPrice = math.floor(tonumber(_entrySellPrice(cat, ikey, src)) or 0)
            end
            batchSnap[#batchSnap + 1] = {
                Category = cat,
                Name = dname,
                Count = math.max(1, math.floor(tonumber(row.Count) or 1)),
                UnitPrice = unitPrice,
            }
        end
    end
    local totalSnap = math.max(0, math.floor(tonumber(total) or 0))

    local note = tostring(cfg.note or "")
    if #note > 100 then note = note:sub(1, 100) end

    if _effectiveSendCooldownRemain() > 0 then
        return false, "cooldown"
    end

    -- Refresh EmptyPots bag right before Fire (state sering muncul/hilang)
    local potBag = nil
    local potUnits = 0
    do
        local needPots = false
        for _, row in ipairs(batch) do
            if type(row) == "table" and _canonicalCategory(row.Category) == "EmptyPots" then
                needPots = true
                break
            end
        end
        if needPots then
            -- Short poll only on send (not on UI list)
            EmptyPotsBagUtil.waitForBag(function()
                return _getInventory(0)
            end, LP, _eachBagEntry, 1.0)
            potBag = EmptyPotsBagUtil.getBag(_getInventory(0), LP, _eachBagEntry)
        end
    end

    local sendBatch = {}
    for _, row in ipairs(batch) do
        if type(row) == "table" then
            local cat = _canonicalCategory(row.Category)
            local ikey = tostring(row.ItemKey or row.ItemName or "")
            -- UI labels sometimes leak "Basic Pot x 80" into keys — mailbox wants bare ItemKey
            ikey = ikey:gsub("%s*[xX]%s*[%d%.]+%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
            if cat ~= "" and ikey ~= "" then
                local count = math.max(1, math.floor(tonumber(row.Count) or 1))
                if cat == "EmptyPots" then
                    local resolvedKey, stock = EmptyPotsBagUtil.resolveKey(potBag, ikey)
                    if not resolvedKey or stock < 1 then
                        _log("EmptyPots skip (not in state):", ikey)
                        continue
                    end
                    ikey = resolvedKey
                    count = math.min(count, stock)
                    local room = MAILBOX_UNIQUE_PER_SEND - potUnits
                    if room <= 0 then
                        break
                    end
                    count = math.min(count, room)
                    potUnits += count
                    cat = "EmptyPots"
                end
                if count > 0 then
                    -- Safety: never send Count >9999 in one row (same ItemKey may repeat).
                    while count > 0 and #sendBatch < MAILBOX_UNIQUE_PER_SEND do
                        local chunk = math.min(MAILBOX_STACK_PER_ROW, count)
                        sendBatch[#sendBatch + 1] = {
                            Category = cat,
                            ItemKey = ikey,
                            Count = chunk,
                        }
                        count -= chunk
                    end
                    if count > 0 then
                        _log("SendBatch row-cap leftover skipped:", ikey, count)
                    end
                end
            end
        end
    end

    if #sendBatch == 0 then
        if potBag ~= nil then
            _setStatus("EmptyPots tidak ada di PlayerState — tunggu sync / buka Mailbox Send")
            return false, "empty_pots_not_in_state"
        end
        return false, "empty_batch"
    end

    do
        local fired = 0
        for _, r in ipairs(sendBatch) do
            fired += math.max(1, math.floor(tonumber(r.Count) or 1))
        end
        if fired > 0 then
            totalSnap = fired
        end
    end

    local function _stockOf(cat, ikey, fruitBag, inv)
        cat = _canonicalCategory(cat)
        ikey = tostring(ikey or "")
        if ikey == "" then return 0 end
        if _isHarvestedFruitsCategory(cat) then
            if type(fruitBag) == "table" and fruitBag[ikey] ~= nil then
                return 1
            end
            return 0
        end
        local bag = inv and _getInventoryBag(inv, cat)
        if type(bag) ~= "table" then return 0 end
        local found = 0
        _eachBagEntry(bag, function(itemKey, entry)
            if tostring(itemKey) ~= ikey then return end
            if type(entry) == "table" then
                if _isUniqueInventoryEntry(entry, itemKey) then
                    found = 1
                else
                    found = math.max(0, math.floor(tonumber(_entryCount(entry)) or 0))
                end
            else
                found = math.max(0, math.floor(tonumber(entry) or 0))
            end
        end)
        return found
    end

    M.InvalidateHarvestFruitCache()
    local fruitBagBefore = type(_getBackpackFruitBag) == "function" and _getBackpackFruitBag(true) or nil
    local invBefore = _getInventory(0)
    local stockBefore = {}
    for i, row in ipairs(sendBatch) do
        if type(row) == "table" then
            stockBefore[i] = _stockOf(row.Category, row.ItemKey, fruitBagBefore, invBefore)
        else
            stockBefore[i] = 0
        end
    end

    local function _commitIfStockDropped(reasonText)
        task.wait(0.25)
        M.InvalidateHarvestFruitCache()
        if type(EmptyPotsBagUtil) == "table" and type(EmptyPotsBagUtil.invalidate) == "function" then
            EmptyPotsBagUtil.invalidate()
        end
        local fruitBagNow = type(_getBackpackFruitBag) == "function" and _getBackpackFruitBag(true) or nil
        local invNow = _getInventory(0)
        local gone = 0
        local keptRows = {}
        for i, row in ipairs(sendBatch) do
            if type(row) ~= "table" then
                continue
            end
            local want = math.max(1, math.floor(tonumber(row.Count) or 1))
            local now = _stockOf(row.Category, row.ItemKey, fruitBagNow, invNow)
            local before = math.max(0, math.floor(tonumber(stockBefore[i]) or 0))
            local drop = math.max(0, before - now)
            if drop <= 0 and before > 0 and now <= 0 then
                drop = want
            end
            drop = math.min(drop, want)
            if drop > 0 then
                gone += drop
                local snap = batchSnap[i]
                local name = (type(snap) == "table" and tostring(snap.Name or "")) or ""
                if name == "" then
                    name = tostring(row.ItemKey or row.Category or "?")
                end
                keptRows[#keptRows + 1] = {
                    Category = row.Category,
                    Name = name,
                    Count = drop,
                    UnitPrice = (type(snap) == "table" and tonumber(snap.UnitPrice)) or 0,
                }
            end
        end
        if gone <= 0 or type(_commitGiftHistory) ~= "function" then
            return false
        end
        local rows = (#keptRows > 0) and keptRows or batchSnap
        local text = "Partial (" .. tostring(gone) .. " item terkirim, " .. tostring(reasonText or "ack gagal") .. ")"
        pcall(_commitGiftHistory, rows, gone, sendBatchNum, text)
        St.lastSendAt = os.clock()
        stats.lastSendAt = St.lastSendAt
        stats.sentBatches += 1
        stats.sentItems += gone
        return true
    end

    _log("SendBatch payload:", cfg.recipient_user_id, sendBatch)

    local ok, success, msg = _callNetworkingRemote(Net.SendBatch, cfg.recipient_user_id, sendBatch, note)

    if not ok then
        local errMsg = tostring(success)
        stats.lastSendError = errMsg
        G.AUTO_GIFT_LAST_SEND_ERROR = errMsg
        _G.AUTO_GIFT_LAST_SEND_ERROR = errMsg
        warn("[GAG2-Gift] SendBatch error:", errMsg)
        _log("SendBatch throw:", errMsg, "batchRows=", #sendBatch, "total=", totalSnap)
        _setStatus("Send error: " .. errMsg, errMsg)
        if _isDailyGiftLimitReason(errMsg, errMsg) then
            return false, "daily_limit"
        end
        if _isCooldownReason(errMsg, errMsg) then
            _noteServerCooldownFromMessage(errMsg)
            return false, "cooldown"
        end
        _commitIfStockDropped("send error: " .. errMsg)
        return false, "send_error"
    end

    -- Game UI: `if v421 then` (truthy). Jangan == true — timeout/Boolean8 selain true
    -- tetap bisa sudah memotong item di server.
    if success then
        St.lastSendAt = os.clock()
        stats.lastSendAt = St.lastSendAt
        stats.sentBatches += 1
        stats.sentItems += totalSnap
        M.InvalidateHarvestFruitCache()
        local text = (msg and tostring(msg) ~= "") and tostring(msg) or ("Gift sent! (" .. tostring(totalSnap) .. " item)")
        _setStatus(text)
        if type(_commitGiftHistory) == "function" then
            pcall(_commitGiftHistory, batchSnap, totalSnap, sendBatchNum, text)
        end
        return true, batch
    end

    local failMsg = tostring((msg and msg ~= "") and msg or "Could not send gift")
    if (not success) and (msg == nil or tostring(msg) == "") then
        failMsg = "SendBatch timeout/no-ack"
    end
    stats.lastSendError = failMsg
    G.AUTO_GIFT_LAST_SEND_ERROR = failMsg
    _G.AUTO_GIFT_LAST_SEND_ERROR = failMsg
    warn("[GAG2-Gift] SendBatch rejected:", failMsg)
    _log("SendBatch rejected:", failMsg, "batchRows=", #sendBatch, "total=", totalSnap)
    _setStatus(failMsg, failMsg)
    if _isDailyGiftLimitReason(failMsg, failMsg) then
        return false, "daily_limit"
    end
    if _isCooldownReason(failMsg, failMsg) then
        _noteServerCooldownFromMessage(failMsg)
        return false, "cooldown"
    end
    _commitIfStockDropped("ack gagal: " .. failMsg)
    return false, msg
end

function M.LookupRecipient(a, b)
    local username = _cleanUsername(_strArg(a, b))
    if username == "" then
        cfg.recipient_user_id = 0
        cfg.recipient_display = ""
        _setStatus("Enter recipient username")
        return false, "empty_username"
    end

    -- Paste UserId langsung (paling andal di Redfinger)
    local asId = tonumber(username)
    if asId and asId > 0 and not tostring(username):find("%a") then
        if asId == LP.UserId then
            _setStatus("UserId sendiri tidak valid")
            return false, "self"
        end
        cfg.recipient_username = username
        cfg.recipient_user_id = asId
        cfg.recipient_display = "UserId:" .. tostring(asId)
        _setStatus("Recipient OK: " .. cfg.recipient_display)
        local profileKey = (_normalizeSendListMode(cfg.send_list_mode) == "loop") and "loop" or "once"
        if type(G.__GAG2_ON_GIFT_RECIPIENT_RESOLVED) == "function" then
            pcall(G.__GAG2_ON_GIFT_RECIPIENT_RESOLVED, {
                profile = profileKey,
                username = username,
                userId = asId,
                display = cfg.recipient_display,
            })
        end
        return true, asId
    end

    -- Sudah verified untuk username yang sama → jangan lookup ulang.
    if cfg.recipient_user_id > 0
        and tostring(cfg.recipient_username or ""):lower() == username:lower() then
        return true, cfg.recipient_user_id
    end

    local now = os.clock()
    local since = now - (tonumber(St.lastLookupAt) or 0)
    if since < LOOKUP_COOLDOWN then
        if cfg.recipient_user_id > 0
            and tostring(cfg.recipient_username or ""):lower() == username:lower() then
            return true, cfg.recipient_user_id
        end
        -- Jangan gagal keras (bikin Send Once stuck) — tunggu sisa cooldown lalu lookup lagi.
        local remain = LOOKUP_COOLDOWN - since
        if remain > 0 then
            _setStatus("Lookup… tunggu " .. string.format("%.1f", remain) .. "s")
            task.wait(remain + 0.05)
        end
    end
    St.lastLookupAt = os.clock()
    _setStatus("Lookup target: " .. username .. "…")

    local userId = 0
    local displayName = ""

    -- 1) Remote mailbox game (sama UI mailbox)
    if _ensureNetworking() and _remoteCallable(Net.Lookup) then
        local ok, uid, disp = _callNetworkingRemote(Net.Lookup, username)
        if ok then
            userId = tonumber(uid) or 0
            displayName = tostring(disp or "")
        end
    end

    -- 2) Fallback Roblox (PlayersAsync / Http / online) — diam, tanpa spam status
    if userId <= 0 then
        local FSL = G.FriendStealList or rawget(_G, "FriendStealList")
        if type(FSL) == "table" and type(FSL.resolveUsernameDetailed) == "function" then
            local rid, rnameOrErr = FSL.resolveUsernameDetailed(username, true)
            rid = tonumber(rid) or 0
            if rid > 0 then
                userId = rid
                displayName = tostring(rnameOrErr or username)
            end
        elseif type(FSL) == "table" and type(FSL.resolveUsername) == "function" then
            local rid, rnameOrErr = FSL.resolveUsername(username, true)
            rid = tonumber(rid) or 0
            if rid > 0 then
                userId = rid
                displayName = tostring(rnameOrErr or username)
            end
        end
    end

    if userId <= 0 or userId == LP.UserId then
        cfg.recipient_user_id = 0
        cfg.recipient_display = ""
        _setStatus("⚠ Target is unverified / wrong. Harap periksa")
        return false, "not_found"
    end

    cfg.recipient_username = username
    cfg.recipient_user_id = userId
    cfg.recipient_display = tostring(displayName ~= "" and displayName or username)
    _setStatus("Recipient OK: " .. cfg.recipient_display .. " (" .. tostring(userId) .. ")")

    local profileKey = (_normalizeSendListMode(cfg.send_list_mode) == "loop") and "loop" or "once"
    if type(G.__GAG2_ON_GIFT_RECIPIENT_RESOLVED) == "function" then
        pcall(G.__GAG2_ON_GIFT_RECIPIENT_RESOLVED, {
            profile = profileKey,
            username = username,
            userId = userId,
            display = cfg.recipient_display,
        })
    end
    return true, userId
end

function M._notifySendJobDone(completedOk, reason)
    -- Flush dulu (sync) sebelum resume unfav yang yield — kalau tidak, job berikutnya
    -- (_resetSendJobHistory) bisa menghapus accumulator sebelum masuk history.
    if type(_flushSendJobHistory) == "function" then
        pcall(_flushSendJobHistory, completedOk == true, reason)
    end
    M._GiftUnfav.resume(completedOk == true)
    if cfg.after_send_mode == "reset" and completedOk then
        local resetKey = (_normalizeSendListMode(cfg.send_list_mode) == "loop")
            and "__GAG2_RESET_GIFT_LOOP" or "__GAG2_RESET_GIFT_ONCE"
        local fn = G[resetKey] or rawget(_G, resetKey)
        if type(fn) ~= "function" then
            fn = G.__GAG2_RESET_GIFT_MAILBOX or rawget(_G, "__GAG2_RESET_GIFT_MAILBOX")
        end
        if type(fn) == "function" then
            pcall(fn)
        end
    end
    local keepToggle = (completedOk ~= true) and _isCooldownReason(reason, stats.lastStatus)
    local doneFn = G.__GAG2_GIFT_SEND_JOB_DONE or _G.__GAG2_GIFT_SEND_JOB_DONE
    if type(doneFn) == "function" then
        pcall(doneFn, completedOk == true, keepToggle)
    end
end

local function _candidateUnitTotal(candidates)
    -- Unit total = stack qty + unique entries (pet/fruit tiap 1), digabung semua category aktif.
    local total = 0
    for _, item in ipairs(candidates or {}) do
        local n = math.floor(tonumber(item.Count) or 0)
        if n < 1 then n = 1 end
        total += n
    end
    return total
end

local function _loopMinSendTotal()
    return _clampSendTotalGoal(cfg.min_send_total or 20)
end

local function _loopWaitingStatusMessage()
    local enabled = _enabledCategoryKeys()
    if #enabled == 0 then
        return "Auto send: menunggu item (belum ada category)"
    end
    M.InvalidateHarvestFruitCache()
    local candidates = _collectCandidates()
    local total = _candidateUnitTotal(candidates)
    local minTotal = _loopMinSendTotal()
    local byCat = {}
    for _, item in ipairs(candidates) do
        local cat = tostring(item.Category or "")
        local n = math.floor(tonumber(item.Count) or 0)
        if n < 1 then n = 1 end
        byCat[cat] = (byCat[cat] or 0) + n
    end
    if total > 0 and total < minTotal then
        local parts = {}
        for _, cat in ipairs(enabled) do
            local n = byCat[cat] or 0
            if n > 0 then
                parts[#parts + 1] = _categoryLabel(cat) .. " " .. tostring(n)
            end
        end
        local detail = (#parts > 0) and (" (" .. table.concat(parts, ", ") .. ")") or ""
        return "Auto send: menunggu min total " .. tostring(total) .. "/" .. tostring(minTotal) .. detail
    end
    local activeParts = {}
    local emptyParts = {}
    for _, cat in ipairs(enabled) do
        local n = byCat[cat] or 0
        local label = _categoryLabel(cat)
        if n > 0 then
            activeParts[#activeParts + 1] = label .. " " .. tostring(n)
        else
            emptyParts[#emptyParts + 1] = label
        end
    end
    if #activeParts > 0 then
        return "Auto send: lanjut " .. table.concat(activeParts, ", ")
    end
    if #emptyParts > 0 then
        return "Auto send: menunggu item (" .. table.concat(emptyParts, ", ") .. " habis)"
    end
    return "Auto send: menunggu item..."
end

function M.SendOnceInternal()
    if cfg.recipient_user_id <= 0 then
        local ok = M.LookupRecipient(cfg.recipient_username)
        if not ok then return false, "no_recipient" end
    end
    if not _mailboxUsable() then
        _setStatus("Mailbox disabled on server")
        return false, "mailbox_disabled"
    end
    if not _ensureNetworking() or not Net.SendBatch then
        _setStatus("SendBatch remote not ready")
        return false, "no_remote"
    end

    if _effectiveSendCooldownRemain() > 0 then
        return false, "cooldown"
    end

    M.InvalidateHarvestFruitCache()
    local candidates = _collectCandidates()
    if #candidates == 0 then
        local enabled = _enabledCategoryKeys()
        local hasSelection = false
        for _, cat in ipairs(enabled) do
            if next(_categorySelected(cat)) then
                hasSelection = true
                break
            end
        end
        if not hasSelection and not _loopSendAllWhenUnselected() then
            _setStatus("Pilih item di list (kosong = tidak kirim)")
            return false, "no_selection"
        end
        local cats = enabled
        local hint = (#cats > 0) and table.concat(cats, ", ") or "none"
        _setStatus("No items to send (" .. hint .. ") — check category & inventory")
        return false, "no_items"
    end

    if _normalizeSendListMode(cfg.send_list_mode) == "loop" then
        local available = _candidateUnitTotal(candidates)
        local minTotal = _loopMinSendTotal()
        if available < minTotal then
            _setStatus(
                "Auto send: menunggu min total " .. tostring(available) .. "/" .. tostring(minTotal),
                nil,
                "loop"
            )
            return false, "below_min"
        end
    end

    local batch, total = _buildBatch(candidates, _batchSendLimit(candidates, nil), nil)
    batch = _prepareHarvestBatch(batch)
    if #batch == 0 then
        return false, "empty_batch"
    end
    total = 0
    for _, item in ipairs(batch) do
        total += math.max(1, math.floor(tonumber(item.Count) or 1))
    end

    return _fireSendBatch(batch, total, 1)
end

function M.SendOnce(_self)
    local ok, res = M.SendOnceInternal()
    if not ok and res == "cooldown" then
        _setStatus("Send cooldown...")
    elseif not ok and res == "no_items" then
        _setStatus("No giftable items")
    end
    return ok, res
end

function M.SetStatus(_self, msg, profile)
    _setStatus(tostring(msg or ""), nil, profile)
end

function M.GetProfileStatus(_self, profileKey)
    profileKey = (tostring(profileKey or ""):lower() == "loop") and "loop" or "once"
    if profileKey == "loop" then
        return stats.lastStatusLoop or "Ready"
    end
    return stats.lastStatusOnce or "Ready"
end

function M.ValidateSendOnceJob(_self)
    if cfg.recipient_user_id <= 0 then
        if tostring(cfg.recipient_username or "") == "" then
            _setStatus("Pilih target dulu")
            return false, "Pilih target dulu"
        end
        local ok = M.LookupRecipient(cfg.recipient_username)
        if not ok then
            -- Jangan timpa pesan detail dari LookupRecipient.
            local msg = tostring(stats.lastStatusOnce or stats.lastStatus or "")
            if msg == "" or msg == "Ready" then
                msg = "Target tidak ditemukan / lookup gagal"
                _setStatus(msg)
            end
            return false, msg
        end
    end
    if not _mailboxUsable() then
        _setStatus("Mailbox disabled on server")
        return false, "Mailbox disabled on server"
    end
    if not _ensureNetworking() or not Net.SendBatch then
        _setStatus("SendBatch remote not ready")
        return false, "SendBatch remote not ready"
    end
    local priceMode = _onceUsesPriceMode()
    local sendAll = (cfg.send_all == true)
    local target
    if priceMode then
        target = _normalizeSendTotalInput(cfg.send_total)
        sendAll = sendAll or (target == 0)
    else
        target = _onceSendUnitTarget()
        sendAll = sendAll or (target == 0)
    end
    if not sendAll and target < 1 then
        local msg = priceMode and "Send total price minimal 1" or "Send total minimal 1"
        _setStatus(msg)
        return false, msg
    end
    local enabled = _enabledCategoryKeys()
    if #enabled == 0 then
        _setStatus("Pilih category dulu — belum ada category aktif")
        return false, "Pilih category dulu — belum ada category aktif"
    end
    local hasSelection = false
    local emptyCats = {}
    for _, cat in ipairs(enabled) do
        if _isHarvestedFruitsCategory(cat) and _onceUsesPriceMode() then
            hasSelection = true
        elseif next(_categorySelected(cat)) then
            hasSelection = true
        else
            emptyCats[#emptyCats + 1] = cat
        end
    end
    if not hasSelection then
        local detail = (#emptyCats > 0) and (" (" .. table.concat(emptyCats, ", ") .. ")") or ""
        local msg = "Pilih item di list — belum ada item terpilih" .. detail
        _setStatus(msg)
        return false, msg
    end
    local candidates = _collectCandidates()
    if priceMode then
        local fruitCount = 0
        for _, item in ipairs(candidates) do
            if _isHarvestedFruitsCategory(item.Category) then
                fruitCount += 1
            end
        end
        local available = _sumCandidatePrice(candidates)
        if available < 1 then
            if fruitCount < 1 then
                local onlyHarvest = true
                for _, cat in ipairs(enabled) do
                    if not _isHarvestedFruitsCategory(cat) then
                        onlyHarvest = false
                        break
                    end
                end
                if onlyHarvest then
                    local msg = "Tidak ada Harvested Fruits di inventory — panen buah dulu"
                    _setStatus(msg)
                    return false, msg
                end
                local msg = "Tidak ada item giftable di inventory untuk category terpilih"
                _setStatus(msg)
                return false, msg
            end
            if not _getFruitSellValueModule() then
                local msg = "FruitSellValue belum load — re-execute hub / upload FruitSellValue.lua"
                _setStatus(msg)
                return false, msg
            end
            local msg = "Ada " .. tostring(fruitCount) .. " buah tapi total value 0 — cek FruitSellValue"
            _setStatus(msg)
            return false, msg
        end
        if not sendAll then
        if available < target then
            local msg = "Value kurang: punya " .. _formatSellPrice(available)
                .. ", butuh " .. _formatSellPrice(target)
            _setStatus(msg)
            return false, msg
        end
        local minSum, maxSum = _priceRangeForRemain(target)
        local batchLimit = math.min(MAILBOX_UNIQUE_PER_SEND, _batchSendLimit(candidates, nil))
        local planPick, _, poolSize = _buildMultiBatchPricePlan(
            candidates,
            minSum,
            maxSum,
            batchLimit
        )
        if not planPick or #planPick == 0 then
            local msg = _pricePlanSummary(nil, 0, minSum, maxSum, poolSize or 0)
            _setStatus(msg)
            return false, msg
        end
        end
    else
        if sendAll then
            if _sumCandidateUnits(candidates) < 1 then
                local msg = "Tidak ada item giftable di inventory untuk yang dipilih"
                _setStatus(msg)
                return false, msg
            end
        else
            local okAvail, errAvail = M.CheckSendTotalAvailability(M, target, false)
            if not okAvail then
                _setStatus(tostring(errAvail or "Item kurang"))
                return false, errAvail
            end
        end
    end
    return true
end

function M.IsSendJobRunning(_self)
    return St.sendJobRunning == true
end

function M.GetSendCooldownRemain(_self)
    return _effectiveSendCooldownRemain()
end

function M.StopSendJob(_self)
    if St.sendJobRunning ~= true then return end
    St.sendJobRunning = false
    M._notifySendJobDone(false, "stopped")
end

function M.StopAutoSend(_self)
    St.autoSendRunning = false
end

function M.IsAutoSendRunning(_self)
    return St.autoSendRunning == true
end

function M.StartAutoSend(_self)
    if St.autoSendRunning then return false end
    St.autoSendRunning = true
    St.autoSendLoopId += 1
    local myId = St.autoSendLoopId
    task.spawn(function()
        task.wait(0.25)
        while St.autoSendRunning and St.autoSendLoopId == myId do
            if cfg.auto_send ~= true or _normalizeSendListMode(cfg.send_list_mode) ~= "loop" then
                task.wait(0.5)
                continue
            end
            if St.sendJobRunning then
                task.wait(0.2)
                continue
            end

            local ok, reason = M.SendOnceInternal()
            if ok then
                _waitForNextSend()
            elseif reason == "no_items" or reason == "empty_batch" or reason == "below_min" then
                _setStatus(_loopWaitingStatusMessage(), nil, "loop")
                _waitNoItemsRetry()
            elseif reason == "cooldown" then
                _waitSendCooldown("loop")
            elseif reason == "daily_limit" or _isDailyGiftLimitReason(reason, stats.lastStatus) then
                -- Limit per username (server) — jangan block global; cooldown biasa + status
                _setStatus("Gift limit target ini — ganti username / tunggu reset", nil, "loop")
                _waitSendCooldown("loop")
            elseif reason == "no_recipient" then
                _setStatus("Auto send: set target username", nil, "loop")
                task.wait(2)
            elseif reason == "mailbox_disabled" or reason == "no_remote" then
                task.wait(2)
            else
                _waitNoItemsRetry()
            end
        end
    end)
    return true
end

function M.ApplyAutoSendRuntime(a, b)
    local on = _boolArg(a, b)
    cfg.auto_send = on
    M.StopAutoSend()
    if on and _normalizeSendListMode(cfg.send_list_mode) == "loop" then
        M.StartAutoSend()
        _setStatus("Auto send ON — looping selected list", nil, "loop")
    elseif not on then
        _setStatus("Auto send OFF", nil, "loop")
    end
    return on
end

;(function()
local function sendJobLoop(myId)
    task.wait(0.05)
    local mode = _normalizeSendListMode(cfg.send_list_mode)

    if mode == "send_total" then
        -- Pause sell/stock/daily SEBELUM validate/plan/unfav (cegah race jual buah unfav)
        if M._GiftUnfav.shouldHold() then
            M._GiftUnfav.pause("gift_once_unfav")
        end

        local okValidate, validateErr = M.ValidateSendOnceJob(M)
        if not okValidate then
            _setStatus(tostring(validateErr or "Validasi gagal"))
            St.sendJobRunning = false
            M._notifySendJobDone(false)
            return
        end

        if _onceUsesPriceMode() and _normalizeSendTotalInput(cfg.send_total) > 0 then
            local target = _clampSendTotalGoal(cfg.send_total)
            cfg.send_total = target
            local targetMin, targetMax = _priceRangeForRemain(target)

            local sentPrice = 0
            local sentUnits = 0
            local batchNum = 0
            local noItemsRetries = 0

            local planCandidates = _collectCandidates()
            local batchLimitPlan = math.min(MAILBOX_UNIQUE_PER_SEND, _batchSendLimit(planCandidates, nil))
            local planPick, planTotal, _, planBatchCount = _buildMultiBatchPricePlan(
                planCandidates,
                targetMin,
                targetMax,
                batchLimitPlan
            )
            local unfavPool = (planPick and #planPick > 0) and planPick or planCandidates
            M._GiftUnfav.prepare(unfavPool)
            if planPick and #planPick > 0 then
                -- Re-plan setelah unfav agar pool sinkron
                planCandidates = _collectCandidates()
                batchLimitPlan = math.min(MAILBOX_UNIQUE_PER_SEND, _batchSendLimit(planCandidates, nil))
                planPick, planTotal, _, planBatchCount = _buildMultiBatchPricePlan(
                    planCandidates,
                    targetMin,
                    targetMax,
                    batchLimitPlan
                )
            end
            if planPick and #planPick > 0 then
                local batchNote = (type(planBatchCount) == "number" and planBatchCount > 1)
                    and (" / " .. tostring(planBatchCount) .. " batch")
                    or ""
                _setStatus(
                    "Mulai kirim: "
                        .. tostring(#planPick)
                        .. " buah "
                        .. _formatSellPrice(planTotal)
                        .. batchNote
                        .. " (target "
                        .. _formatSellPrice(targetMin)
                        .. "–"
                        .. _formatSellPrice(targetMax)
                        .. ")"
                )
            end

            while St.sendJobRunning and St.sendJobId == myId and sentPrice < targetMin do
                if _effectiveSendCooldownRemain() > 0 then
                    _waitSendCooldown()
                    if not St.sendJobRunning or St.sendJobId ~= myId then
                        return
                    end
                end

                local candidates = _collectCandidates()
                if #candidates == 0 then
                    noItemsRetries += 1
                    if noItemsRetries < 3 then
                        _waitNoItemsRetry()
                        continue
                    end
                    _setStatus("Tidak ada item dengan value yang bisa dikirim")
                    St.sendJobRunning = false
                    M._notifySendJobDone(false)
                    return
                end
                noItemsRetries = 0

                local remainMin = math.max(1, targetMin - sentPrice)
                local remainMax = math.max(remainMin, targetMax - sentPrice)
                local batchLimit = math.min(MAILBOX_UNIQUE_PER_SEND, _batchSendLimit(candidates, nil))
                local batch, batchPrice
                if type(_planPriceBatch) == "function" then
                    batch, batchPrice = _planPriceBatch(
                        candidates,
                        remainMin,
                        remainMax,
                        batchLimit
                    )
                end
                if not batch then
                    batch = {}
                    batchPrice = 0
                end
                batch = (type(_prepareHarvestBatch) == "function") and _prepareHarvestBatch(batch) or batch
                if #batch == 0 or batchPrice <= 0 then
                    local pool = _pricePoolFromCandidates(candidates)
                    local msg = _pricePlanSummary(nil, 0, remainMin, remainMax, #pool)
                    _setStatus(msg)
                    St.sendJobRunning = false
                    M._notifySendJobDone(false)
                    return
                end
                local batchUnits = #batch
                batchNum += 1
                _setStatus(
                    "Batch "
                        .. tostring(batchNum)
                        .. ": kirim "
                        .. tostring(batchUnits)
                        .. " buah ("
                        .. _formatSellPrice(batchPrice)
                        .. ")..."
                )

                local ok, reason = _fireSendBatch(batch, batchUnits, batchNum)
                if ok then
                    sentPrice += batchPrice
                    sentUnits += batchUnits
                    _setStatus(_formatPriceSendProgress(sentUnits, sentPrice, targetMin, targetMax, batchNum))
                    if sentPrice >= targetMin and sentPrice <= targetMax then
                        break
                    end
                    _waitForNextSend()
                elseif _isCooldownReason(reason, stats.lastStatus) then
                    _waitSendCooldown()
                    continue
                else
                    local errText = tostring(reason or stats.lastStatus or "Kirim gagal")
                    if errText == "" or errText == "send_error" then
                        errText = tostring(stats.lastStatus or "Kirim gagal (server/network)")
                    end
                    _setStatus("Kirim gagal: " .. errText)
                    St.sendJobRunning = false
                    M._notifySendJobDone(false, reason)
                    return
                end
            end

            if sentPrice >= targetMin and sentPrice <= targetMax then
                _setStatus(
                    "Selesai: "
                        .. tostring(sentUnits)
                        .. " buah | "
                        .. _formatSellPrice(sentPrice)
                        .. " (range "
                        .. _formatSellPrice(targetMin)
                        .. "–"
                        .. _formatSellPrice(targetMax)
                        .. ")"
                )
                St.sendJobRunning = false
                M._notifySendJobDone(true)
            else
                _setStatus(
                    "Berhenti: "
                        .. tostring(sentUnits)
                        .. " buah | "
                        .. _formatSellPrice(sentPrice)
                        .. " / target "
                        .. _formatSellPrice(targetMin)
                        .. "–"
                        .. _formatSellPrice(targetMax)
                )
                St.sendJobRunning = false
                M._notifySendJobDone(false)
            end
            return
        end

        local target = _onceSendUnitTarget()
        local sendAll = (cfg.send_all == true)
            or (_onceUsesPriceMode() and _normalizeSendTotalInput(cfg.send_total) == 0)
            or ((not _onceUsesPriceMode()) and target == 0)
        if target < 1 then
            sendAll = true
        end
        local sentUnits = 0
        local noItemsRetries = 0
        local sendBatchNum = 0
        local failStreak = 0
        local prepCandidates = {}
        do
            M.InvalidateHarvestFruitCache()
            prepCandidates = _collectCandidates()
            M._GiftUnfav.prepare(prepCandidates)
        end
        if sendAll then
            local allN = _sumCandidateUnits(prepCandidates)
            _setStatus("Kirim semua: " .. tostring(allN) .. " item terpilih")
        end
        while St.sendJobRunning and St.sendJobId == myId and (sendAll or sentUnits < target) do
            if _effectiveSendCooldownRemain() > 0 then
                _waitSendCooldown()
                if not St.sendJobRunning or St.sendJobId ~= myId then
                    return
                end
            end

            M.InvalidateHarvestFruitCache()
            EmptyPotsBagUtil.invalidate()
            local candidates = _collectCandidates()
            if #candidates == 0 then
                noItemsRetries += 1
                -- send-all: jangan anggap selesai setelah 1 item (replica kadang kosong sebentar)
                local maxRetry = sendAll and 10 or (_categoryEnabled("EmptyPots") and 5 or 3)
                if noItemsRetries < maxRetry then
                    if _categoryEnabled("EmptyPots") then
                        _setStatus("Menunggu EmptyPots sync... (" .. tostring(noItemsRetries) .. "/" .. tostring(maxRetry) .. ")")
                        EmptyPotsBagUtil.waitForBag(function()
                            return _getInventory(0)
                        end, LP, _eachBagEntry, 0.6)
                    else
                        if sendAll then
                            _setStatus("Menunggu stok terpilih... (" .. tostring(noItemsRetries) .. "/" .. tostring(maxRetry) .. ")")
                            task.wait(0.45)
                        else
                            _waitNoItemsRetry()
                        end
                    end
                    continue
                end
                if sendAll and sentUnits > 0 then
                    _setStatus("Selesai: kirim " .. tostring(sentUnits) .. " item (all selected)")
                    St.sendJobRunning = false
                    M._notifySendJobDone(true)
                    return
                end
                _setStatus("Tidak ada item yang bisa dikirim")
                St.sendJobRunning = false
                M._notifySendJobDone(false)
                return
            end
            noItemsRetries = 0

            local remainUnits = sendAll and nil or (target - sentUnits)
            if remainUnits ~= nil and remainUnits < 1 then
                remainUnits = nil
                sendAll = true
            end
            local batch, batchUnits = _buildBatch(
                candidates,
                _batchSendLimit(candidates, remainUnits),
                remainUnits
            )
            batch = _prepareHarvestBatch(batch)
            if (#batch == 0 or batchUnits <= 0) and #candidates > 0 then
                batch, batchUnits = _buildBatch(
                    candidates,
                    _batchSendLimit(candidates, nil),
                    nil
                )
                batch = _prepareHarvestBatch(batch)
            end
            if #batch == 0 or batchUnits <= 0 then
                if sendAll and sentUnits > 0 then
                    _setStatus("Selesai: kirim " .. tostring(sentUnits) .. " item (all selected)")
                    St.sendJobRunning = false
                    M._notifySendJobDone(true)
                    return
                end
                _setStatus("Batch kosong — tidak ada item yang bisa dikirim")
                St.sendJobRunning = false
                M._notifySendJobDone(false)
                return
            end

            sendBatchNum += 1
            local ok, reason = _fireSendBatch(batch, batchUnits, sendBatchNum)
            if reason == "empty_pots_not_in_state" and noItemsRetries < 5 then
                noItemsRetries += 1
                _setStatus("EmptyPots hilang dari state — retry sync...")
                EmptyPotsBagUtil.waitForBag(function()
                    return _getInventory(0)
                end, LP, _eachBagEntry, 0.8)
                continue
            end
            if ok then
                failStreak = 0
                sentUnits += batchUnits
                if sendAll then
                    _setStatus("Mengirim " .. tostring(sentUnits) .. " (all selected)")
                else
                    _setStatus("Mengirim " .. tostring(sentUnits) .. "/" .. tostring(target))
                    if sentUnits >= target then
                        break
                    end
                end
                _waitForNextSend()
            elseif _isCooldownReason(reason, stats.lastStatus) then
                _waitSendCooldown()
                continue
            else
                failStreak += 1
                local fatal = reason == "daily_limit"
                    or reason == "no_recipient"
                    or reason == "mailbox_disabled"
                    or _isDailyGiftLimitReason(reason, stats.lastStatus)
                if sendAll and not fatal and failStreak < 3 then
                    _setStatus("Batch gagal, lanjut sisa stok (" .. tostring(failStreak) .. "/3)")
                    _waitForNextSend()
                    continue
                end
                local errText = tostring(reason or stats.lastStatus or "Kirim gagal")
                if errText == "" or errText == "send_error" then
                    errText = tostring(stats.lastStatus or "Kirim gagal (server/network)")
                end
                _setStatus("Kirim gagal: " .. errText)
                St.sendJobRunning = false
                M._notifySendJobDone(false, reason)
                return
            end
        end

        if sendAll then
            _setStatus("Selesai: kirim " .. tostring(sentUnits) .. " item (all selected)")
            St.sendJobRunning = false
            M._notifySendJobDone(sentUnits > 0)
        elseif sentUnits >= target then
            _setStatus("Selesai: kirim " .. tostring(sentUnits) .. " item")
            St.sendJobRunning = false
            M._notifySendJobDone(true)
        else
            _setStatus("Berhenti: " .. tostring(sentUnits) .. "/" .. tostring(target))
            St.sendJobRunning = false
            M._notifySendJobDone(false)
        end
        return
    end

    while St.sendJobRunning and St.sendJobId == myId do
        local ok, reason = M.SendOnceInternal()
        if not ok then
            if reason == "no_items" or reason == "empty_batch" or reason == "below_min" then
                _setStatus(_loopWaitingStatusMessage(), nil, "loop")
                _waitNoItemsRetry()
            elseif reason == "cooldown" then
                _waitSendCooldown("loop")
            elseif reason == "daily_limit" or _isDailyGiftLimitReason(reason, stats.lastStatus) then
                _setStatus("Gift limit target ini — ganti username / tunggu reset", nil, "loop")
                _waitSendCooldown("loop")
            elseif reason == "no_recipient" then
                _setStatus("Pilih target / lookup gagal")
                _waitForNextSend()
            elseif reason == "mailbox_disabled" then
                _setStatus("Mailbox disabled on server")
                _waitForNextSend()
            elseif reason == "no_remote" then
                _setStatus("SendBatch remote not ready")
                _waitForNextSend()
            else
                _log("loop skip:", reason)
                _waitNoItemsRetry()
            end
        else
            _waitForNextSend()
        end
    end
end

function M.StartSendJob(_self)
    if St.sendJobRunning then
        return false, "already_running"
    end
    if _normalizeSendListMode(cfg.send_list_mode) == "send_total" then
        local okValidate, validateErr = M.ValidateSendOnceJob(M)
        if not okValidate then
            _setStatus(tostring(validateErr or "Validasi gagal"))
            return false, validateErr
        end
    end
    if type(_flushSendJobHistory) == "function" then
        pcall(_flushSendJobHistory, false, "new_job")
    end
    St.sendJobRunning = true
    St.sendJobId += 1
    if type(_resetSendJobHistory) == "function" then
        _resetSendJobHistory()
    end
    local myId = St.sendJobId
    task.spawn(function()
        sendJobLoop(myId)
    end)
    return true
end
end)()

;(function()
local worldsCache = nil
local worldsCacheAt = 0

local function _getWorlds()
    local now = os.clock()
    if worldsCache ~= nil and (now - worldsCacheAt) < 5 then
        return worldsCache ~= false and worldsCache or nil
    end
    local ok, Worlds = pcall(function()
        return require(ReplicatedStorage.SharedModules.Worlds)
    end)
    worldsCacheAt = now
    if ok and type(Worlds) == "table" then
        worldsCache = Worlds
        return Worlds
    end
    worldsCache = false
    return nil
end

local function _giftHasItems(gift)
    if type(gift) ~= "table" then return false end
    local items = gift.Items
    if type(items) == "table" then
        -- Array form (game UI GiftHasItems)
        if #items > 0 then return true end
        -- Map/dict form (some OpenInbox payloads use string keys → #items == 0)
        for _ in pairs(items) do
            return true
        end
        return false
    end
    if type(gift.Category) == "string" then
        if type(gift.ItemName) == "string" then return true end
        -- SendBatch uses ItemKey; some claim payloads mirror that
        if type(gift.ItemKey) == "string" then return true end
    end
    return false
end

local function _clearStalePendingClaims(maxAgeSec)
    maxAgeSec = tonumber(maxAgeSec) or 60
    local now = os.clock()
    if type(St.pendingClaimAt) ~= "table" then
        St.pendingClaimAt = {}
    end
    -- Assign timestamp to legacy pending (so we don't wipe mid-flight ClaimAll)
    for id in pairs(St.pendingClaims) do
        if St.pendingClaimAt[id] == nil then
            St.pendingClaimAt[id] = now
        end
    end
    for id, t0 in pairs(St.pendingClaimAt) do
        if type(t0) ~= "number" or (now - t0) >= maxAgeSec then
            St.pendingClaims[id] = nil
            St.pendingClaimAt[id] = nil
        end
    end
end

local function _markPendingClaim(id, on)
    id = tostring(id or "")
    if id == "" then return end
    if type(St.pendingClaimAt) ~= "table" then
        St.pendingClaimAt = {}
    end
    if on then
        St.pendingClaims[id] = true
        St.pendingClaimAt[id] = os.clock()
    else
        St.pendingClaims[id] = nil
        St.pendingClaimAt[id] = nil
    end
end

local function _getCurrentWorldId()
    local Worlds = _getWorlds()
    if Worlds then
        local id = Worlds.CurrentId
        if type(id) == "string" and id ~= "" then
            return id
        end
        if type(Worlds.GetCurrentId) == "function" then
            local okGet, v = pcall(Worlds.GetCurrentId, Worlds)
            if okGet and type(v) == "string" and v ~= "" then
                return v
            end
        end
    end
    return "Main"
end

local function _giftOriginWorldId(gift)
    if type(gift) ~= "table" then return "Main" end
    local fromWorld = gift.FromWorld
    if type(fromWorld) ~= "string" or fromWorld == "" then
        return "Main"
    end
    local Worlds = _getWorlds()
    if Worlds and type(Worlds.Worlds) == "table" and Worlds.Worlds[fromWorld] == nil then
        return "Main"
    end
    return fromWorld
end

local function _canClaimGiftHere(gift)
    return _giftOriginWorldId(gift) == _getCurrentWorldId()
end

local function _explainInboxSkips()
    local info = {
        total = 0,
        claimable = 0,
        noItems = 0,
        wrongWorld = 0,
        pending = 0,
        sample = nil,
        currentWorld = _getCurrentWorldId(),
        mailboxUsable = true,
    }
    for giftId, gift in pairs(St.inboxGifts) do
        info.total += 1
        local key = tostring(giftId)
        if not info.sample and type(gift) == "table" then
            local itemN = 0
            if type(gift.Items) == "table" then
                for _ in pairs(gift.Items) do itemN += 1 end
            end
            info.sample = {
                id = key,
                From = gift.From,
                FromName = gift.FromName,
                FromWorld = gift.FromWorld,
                Kind = gift.Kind,
                Category = gift.Category,
                ItemName = gift.ItemName,
                ItemKey = gift.ItemKey,
                itemsArrayLen = type(gift.Items) == "table" and #gift.Items or -1,
                itemsPairCount = itemN,
                hasItems = _giftHasItems(gift),
                canHere = _canClaimGiftHere(gift),
            }
        end
        if St.pendingClaims[key] then
            info.pending += 1
        elseif not _giftHasItems(gift) then
            info.noItems += 1
        elseif not _canClaimGiftHere(gift) then
            info.wrongWorld += 1
        else
            info.claimable += 1
        end
    end
    return info
end

local function _magicMailClaimAllowed()
    local Worlds = _getWorlds()
    if Worlds and type(Worlds.Current) == "table" then
        local features = Worlds.Current.Features
        if type(features) == "table" then
            return features.MagicMailClaim == true
        end
    end
    return false
end

local function _magicMailEnabled()
    local ok, flags = pcall(function()
        return require(ReplicatedStorage.SharedModules.Flags.MagicMailFlags)
    end)
    if ok and type(flags) == "table" and flags.Enabled then
        if type(flags.Enabled.Get) == "function" then
            local okGet, enabled = pcall(flags.Enabled.Get, flags.Enabled)
            if okGet then
                return enabled == true
            end
        end
    end
    return true
end

local function _ensureInboxFresh(force)
    local now = os.clock()
    if force or St.inboxDirty then
        pcall(_refreshInboxFromServer)
        return
    end

    if _remoteCallable(Net.IndexProbe) and (now - St.lastIndexProbeAt) >= INDEX_PROBE_MIN_SEC then
        St.lastIndexProbeAt = now
        local ok, result = _callNetworkingRemote(Net.IndexProbe)
        if ok then
            local idx = tonumber(result) or 0
            if St.lastIndexProbe == nil or idx ~= St.lastIndexProbe then
                St.lastIndexProbe = idx
                pcall(_refreshInboxFromServer)
            end
        end
        return
    end

    if (now - St.lastInboxRefreshAt) >= INBOX_REFRESH_MIN_SEC then
        pcall(_refreshInboxFromServer)
    end
end

local function _ensureMagicMailFresh(force)
    if not _magicMailEnabled() then
        table.clear(St.magicMails)
        return
    end
    if not force and not _magicMailClaimAllowed() then
        return
    end

    local now = os.clock()
    if force or St.magicMailDirty then
        pcall(_refreshMagicMailFromServer)
        St.lastMagicRefreshAt = now
        return
    end

    if (now - (St.lastMagicRefreshAt or 0)) >= INBOX_REFRESH_MIN_SEC then
        pcall(_refreshMagicMailFromServer)
        St.lastMagicRefreshAt = now
    end
end

local function _collectClaimableGifts()
    if not _mailboxUsable() then return {} end
    _clearStalePendingClaims(90)
    _ensureInboxFresh(false)

    local function build()
        local out = {}
        for giftId, gift in pairs(St.inboxGifts) do
            local key = tostring(giftId)
            if key ~= "" and _giftHasItems(gift) and _canClaimGiftHere(gift) and not St.pendingClaims[key] then
                out[#out + 1] = { Id = key, Gift = gift }
            end
        end
        table.sort(out, function(a, b)
            return a.Id < b.Id
        end)
        return out
    end

    local out = build()
    if #out > 0 then
        return out
    end

    if _remoteCallable(Net.List) and (os.clock() - St.lastInboxRefreshAt) >= INBOX_REFRESH_MIN_SEC then
        local ok, data = _callNetworkingRemote(Net.List)
        if ok and type(data) == "table" then
            if type(data.Inbox) == "table" then
                _applyInboxData({ Mailbox = data.Inbox })
            else
                _applyInboxData(data)
            end
            return build()
        end
    end

    return out
end

local function _collectInboxGiftIds()
    local ids = {}
    for _, row in ipairs(_collectClaimableGifts()) do
        ids[#ids + 1] = row.Id
    end
    return ids
end

local function _bindClaimAllEvents()
    if not _ensureNetworking() then return end

    if not St.claimAllProgressConn and Net.ClaimAllProgress and Net.ClaimAllProgress.OnClientEvent then
        St.claimAllProgressConn = Net.ClaimAllProgress.OnClientEvent:Connect(function(giftId)
            if typeof(giftId) ~= "string" then return end
            if St.inboxGifts[giftId] ~= nil then
                St.inboxGifts[giftId] = nil
                stats.claimedGifts += 1
            end
            _markPendingClaim(giftId, false)
        end)
    end

    if not St.claimAllFinishedConn and Net.ClaimAllFinished and Net.ClaimAllFinished.OnClientEvent then
        St.claimAllFinishedConn = Net.ClaimAllFinished.OnClientEvent:Connect(function(result)
            St.claimAllResult = result
            St.claimAllInFlight = false
        end)
    end
end

local function _waitClaimAllFinished(token)
    local deadline = os.clock() + CLAIM_ALL_TIMEOUT_SEC
    while St.claimRunning and St.claimAllToken == token and St.claimAllInFlight do
        if os.clock() >= deadline then
            break
        end
        task.wait(0.05)
    end
    return St.claimAllResult
end

local function _finishClaimAllLocal(result)
    local claimed = 0
    if type(result) == "table" and type(result.Claimed) == "table" then
        for _, giftId in ipairs(result.Claimed) do
            local key = tostring(giftId)
            if key ~= "" then
                if St.inboxGifts[key] ~= nil then
                    claimed += 1
                    stats.claimedGifts += 1
                    St.inboxGifts[key] = nil
                end
                _markPendingClaim(key, false)
            end
        end
    end
    return claimed
end

local function _claimAllBatch(rows)
    if not _remoteCallable(Net.ClaimAll) then
        return 0, "no_claim_all"
    end
    if St.claimAllInFlight then
        return 0, "in_flight"
    end

    local remain = CLAIM_ALL_COOLDOWN_SEC - (os.clock() - St.lastClaimAllAt)
    if remain > 0 then
        return 0, "claim_all_cooldown"
    end

    _bindClaimAllEvents()
    St.claimAllToken += 1
    local token = St.claimAllToken
    St.claimAllResult = nil
    St.claimAllInFlight = true
    local claimedBefore = stats.claimedGifts

    for _, row in ipairs(rows) do
        _markPendingClaim(row.Id, true)
    end

    local firedOk, firedErr = pcall(function()
        return Net.ClaimAll:Fire()
    end)

    if not firedOk then
        St.claimAllInFlight = false
        for _, row in ipairs(rows) do
            _markPendingClaim(row.Id, false)
        end
        return 0, "fire_failed"
    end

    local result = _waitClaimAllFinished(token)
    St.claimAllInFlight = false

    if type(result) ~= "table" or result.Ran ~= false then
        St.lastClaimAllAt = os.clock()
    end

    _finishClaimAllLocal(result)
    local claimed = stats.claimedGifts - claimedBefore

    for _, row in ipairs(rows) do
        _markPendingClaim(row.Id, false)
    end

    St.lastClaimAt = os.clock()
    St.inboxDirty = true

    if claimed > 0 then
        return claimed, nil
    end

    local reason = ""
    if type(result) == "table" then
        if type(result.Reason) == "string" then
            reason = result.Reason
        end
        if reason == "" and type(result.Failed) == "table" then
            for _, fail in ipairs(result.Failed) do
                if type(fail) == "table" and type(fail.Reason) == "string" and fail.Reason ~= "" then
                    reason = fail.Reason
                    break
                end
            end
        end
    elseif firedErr ~= nil then
        reason = tostring(firedErr)
    end
    return 0, reason ~= "" and reason or "claim_all_empty"
end

local function _claimSingles(rows)
    if not _remoteCallable(Net.Claim) then
        return 0, "no_remote"
    end

    local claimed = 0
    local lastErr = nil
    for _, row in ipairs(rows) do
        if not St.claimRunning then
            break
        end
        local giftId = row.Id
        if St.pendingClaims[giftId] then
            continue
        end
        if not _canClaimGiftHere(row.Gift) then
            continue
        end

        local now = os.clock()
        local waitLeft = MIN_CLAIM_SEC - (now - St.lastClaimAt)
        if waitLeft > 0 then
            task.wait(waitLeft)
        end

        _markPendingClaim(giftId, true)
        local ok, success, msg = _callNetworkingRemote(Net.Claim, giftId)
        _markPendingClaim(giftId, false)
        St.lastClaimAt = os.clock()

        if ok and success == true then
            claimed += 1
            stats.claimedGifts += 1
            St.inboxGifts[giftId] = nil
        elseif ok and success ~= true then
            lastErr = tostring(msg ~= "" and msg or "Could not claim gift")
        elseif not ok then
            lastErr = tostring(success or "claim_error")
        end
    end

    if claimed > 0 then
        return claimed, nil
    end
    return 0, lastErr or "claim_failed"
end

local function _claimMagicMails()
    if not _magicMailEnabled() or not _magicMailClaimAllowed() then
        return 0
    end
    if not _remoteCallable(Net.MagicMailClaim) then
        return 0
    end

    _ensureMagicMailFresh(false)
    local ids = {}
    for mailId in pairs(St.magicMails) do
        ids[#ids + 1] = tostring(mailId)
    end
    table.sort(ids)

    local claimed = 0
    for _, mailId in ipairs(ids) do
        if not St.claimRunning then
            break
        end
        if St.pendingClaims["mm:" .. mailId] then
            continue
        end

        _markPendingClaim("mm:" .. mailId, true)
        local ok, success = _callNetworkingRemote(Net.MagicMailClaim, mailId)
        _markPendingClaim("mm:" .. mailId, false)
        St.lastClaimAt = os.clock()

        if ok and success == true then
            claimed += 1
            stats.claimedGifts += 1
            St.magicMails[mailId] = nil
        end
    end
    return claimed
end

function M.ClaimOnce()
    if not cfg.auto_claim_mail then
        return false, "disabled"
    end
    if not _mailboxUsable() then
        _setStatus("Mailbox disabled — cannot claim")
        return false, "mailbox_disabled"
    end
    if not _ensureNetworking() then
        _setStatus("Mailbox networking not ready")
        return false, "no_remote"
    end
    if not (_remoteCallable(Net.Claim) or _remoteCallable(Net.ClaimAll) or _remoteCallable(Net.MagicMailClaim)) then
        _setStatus("Mailbox claim remote not ready")
        return false, "no_remote"
    end

    _bindClaimAllEvents()
    _clearStalePendingClaims(90)

    local claimed = 0
    local rows = _collectClaimableGifts()
    local waitingClaimAll = false

    if #rows >= 2 and _remoteCallable(Net.ClaimAll) then
        local n, err = _claimAllBatch(rows)
        claimed += n
        if n == 0 and (err == "claim_all_cooldown" or err == "in_flight") then
            -- Jangan stuck: ClaimAll CD/in-flight → tetap claim satuan
            waitingClaimAll = (err == "claim_all_cooldown")
            local n2 = _claimSingles(rows)
            claimed += n2
        elseif n == 0 then
            local n2 = _claimSingles(rows)
            claimed += n2
        else
            local leftovers = _collectClaimableGifts()
            if #leftovers > 0 then
                local n2 = _claimSingles(leftovers)
                claimed += n2
            end
        end
    elseif #rows > 0 then
        local n = _claimSingles(rows)
        claimed += n
    end

    claimed += _claimMagicMails()

    if claimed > 0 then
        _setStatus("Claimed " .. tostring(claimed) .. " mail")
        return true, claimed
    end

    if waitingClaimAll then
        return false, "claim_all_cooldown"
    end

    if #rows == 0 then
        local skip = _explainInboxSkips()
        St.lastClaimSkip = skip
        if skip.pending > 0 and skip.claimable == 0 then
            return false, "pending"
        end
        if skip.wrongWorld > 0 then
            return false, "wrong_world"
        end
        if skip.noItems > 0 then
            return false, "no_items"
        end
        if skip.total > 0 then
            return false, "filtered"
        end
        return false, "no_gifts"
    end
    return false, "claim_failed"
end

function M.StartClaim()
    St.claimRunning = true
    St.claimLoopId += 1
    stats.claimRunning = true
    local myId = St.claimLoopId
    St.inboxDirty = true
    St.magicMailDirty = true
    _bindClaimAllEvents()
    task.spawn(function()
        task.wait(0.15)
        while St.claimRunning and St.claimLoopId == myId do
            if not cfg.auto_claim_mail then
                task.wait(0.5)
                continue
            end

            local okCall, resultOrErr, reason = pcall(M.ClaimOnce)
            if not okCall then
                _log("claim error:", resultOrErr)
                task.wait(CLAIM_LOOP_IDLE_SEC)
                continue
            end

            local success = resultOrErr
            if success == true then
                task.wait(CLAIM_LOOP_ACTIVE_SEC)
            elseif reason == "no_gifts" or reason == "wrong_world" then
                if reason == "no_gifts" then
                    St.inboxDirty = true
                    St.magicMailDirty = true
                end
                task.wait(CLAIM_LOOP_IDLE_SEC)
            elseif reason == "cooldown" or reason == "claim_all_cooldown" or reason == "in_flight" then
                task.wait(CLAIM_LOOP_ACTIVE_SEC)
            else
                task.wait(CLAIM_LOOP_IDLE_SEC)
            end
        end
    end)
end

function M.StopClaim()
    St.claimRunning = false
    stats.claimRunning = false
    St.claimAllInFlight = false
    St.claimAllToken += 1
end

