        print("[GAG2-Gift] sample itemsArrayLen=", s.itemsArrayLen, "itemsPairCount=", s.itemsPairCount, "hasItems=", s.hasItems, "canHere=", s.canHere)
        print("[GAG2-Gift] sample Category=", tostring(s.Category), "ItemName=", tostring(s.ItemName), "ItemKey=", tostring(s.ItemKey))
    end
    return skip
