 end,                       required = false },
    { key = "MailControllerGift",      name = "Mail Controller Gift",    factory = function() -- 276_Gag2_mail_controller_gift.lua
-- Standalone Mail Controller gift engine (Mailbox.SendBatch). Zero AutoGift/history.
local M = {}
local G = (getgenv and getgenv()) or _G
local MC_VERSION = "276-20260808h"

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local LocalPlayer = Players.LocalPlayer

local MAX_BATCH_ROWS = 20
local MAX_STACK_COUNT = 9999
-- Game mailbox often returns "Wait 2–4s before sending another gift"; keep ≥5s base.
local SEND_COOLDOWN = 5.0
local COOLDOWN_RETRIES = 5
local DAILY_TOTAL = 50
local DAILY_PAIR = 5

local Net = { Networking = nil, SendBatch = nil, Lookup = nil, PlayerStateClient = nil }
local soft = {
    day_key = "",
    total = 0,
    pair = {},
}
local cancelJobs = {} -- [job_id] = true
local running = false
local pendingQueue = {} -- FIFO { payload, message, bridge }
local harvestBagCache, harvestBagCacheAt = nil, 0

local function now()
    return os.clock()
end

local function mailDayKey()
    -- 07:00 WIB = UTC+7
    local t = os.time() + 7 * 3600
    local d = os.date("!*t", t)
    if (d.hour or 0) < 7 then
        t = t - 86400
        d = os.date("!*t", t)
    end
    return string.format("%04d-%02d-%02d", d.year, d.month, d.day)
end

local function softResetIfNeeded()
    local key = mailDayKey()
    if soft.day_key ~= key then
        soft.day_key = key
        soft.total = 0
        soft.pair = {}
    end
end

local function softCanSend(recipient)
    softResetIfNeeded()
    local r = string.lower(tostring(recipient or ""))
    local usedPair = soft.pair[r] or 0
    if soft.total >= DAILY_TOTAL then return false, "daily_total" end
    if usedPair >= DAILY_PAIR then return false, "daily_recipient" end
    return true
end

local function softMarkSuccess(recipient)
    softResetIfNeeded()
    local r = string.lower(tostring(recipient or ""))
    soft.total = soft.total + 1
    soft.pair[r] = (soft.pair[r] or 0) + 1
end

local function remoteCallable(remote)
    if remote == nil then return false end
    local t = type(remote)
    if t == "table" then return true end
    if type(typeof) == "function" then
        local ok, kind = pcall(typeof, remote)
        return ok and kind == "Instance"
    end
    return t == "userdata"
end

local function callRemote(remote, ...)
    if not remote then return false, "remote_missing" end
    -- Some executors lack table.pack; avoid nil call.
    local n = select("#", ...)
    local args = { ... }
    args.n = n
    local ok, a, b, c = pcall(function()
        local unpackFn = table.unpack or unpack
        if type(remote.InvokeServer) == "function" then
            return remote:InvokeServer(unpackFn(args, 1, args.n))
        end
        if type(remote.FireServer) == "function" then
            return remote:FireServer(unpackFn(args, 1, args.n))
        end
        if type(remote.Fire) == "function" then
            return remote:Fire(unpackFn(args, 1, args.n))
        end
        error("no_fire")
    end)
    if not ok then return false, tostring(a) end
    return true, a, b, c
end

local function ensureNetworking()
    if Net.Networking and remoteCallable(Net.SendBatch) then
        if type(Net.Networking.Backpack) == "table" then
            Net.SetFruitFavorite = Net.Networking.Backpack.SetFruitFavorite or Net.SetFruitFavorite
            Net.PromoteFruit = Net.Networking.Backpack.PromoteFruit or Net.PromoteFruit
            Net.BackpackGetLayout = Net.Networking.Backpack.GetLayout or Net.BackpackGetLayout
        end
        return true
    end
    local ok, net = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules"):WaitForChild("Networking"))
    end)
    if ok and type(net) == "table" and type(net.Mailbox) == "table" then
        Net.Networking = net
        Net.SendBatch = net.Mailbox.SendBatch
        Net.Lookup = net.Mailbox.LookupPlayer
        if type(net.Backpack) == "table" then
            Net.SetFruitFavorite = net.Backpack.SetFruitFavorite
            Net.PromoteFruit = net.Backpack.PromoteFruit
            Net.BackpackGetLayout = net.Backpack.GetLayout
        end
    end
    return remoteCallable(Net.SendBatch)
end

local function setFruitFavorite(id, favorited)
    id = tostring(id or "")
    if id == "" then return false end
    ensureNetworking()
    favorited = favorited == true
    if remoteCallable(Net.SetFruitFavorite) then
        local ok = callRemote(Net.SetFruitFavorite, id, favorited)
        return ok == true
    end
    local af = G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
    if type(af) == "table" and type(af.SetFruitFavorite) == "function" then
        local ok = pcall(af.SetFruitFavorite, af, id, favorited)
        return ok == true
    end
    return false
end

local function promoteFruit(id)
    id = tostring(id or "")
    if id == "" then return false end
    ensureNetworking()
    if not remoteCallable(Net.PromoteFruit) then return false end
    local ok = callRemote(Net.PromoteFruit, id)
    return ok == true
end

-- Pause AutoSell / stock / daily + AutoFav selama kirim (port dari AutoGift).
local sellHold = { held = false, boostBusyHeld = false }

local function pauseSellPeers(reason)
    if sellHold.held then return end
    sellHold.held = true
    reason = reason or "mail_controller_gift"

    do
        local deadline = os.clock() + 15
        while G.__GAG2_BOOST_SELL_BUSY == true and os.clock() < deadline do
            task.wait(0.05)
        end
        if sellHold.boostBusyHeld ~= true then
            G.__GAG2_BOOST_SELL_BUSY = true
            _G.__GAG2_BOOST_SELL_BUSY = true
            sellHold.boostBusyHeld = true
        end
    end

    local asell = G.AutoSellFruit or G.AutoSell or G.AutoSellModule
        or rawget(_G, "AutoSellFruit") or rawget(_G, "AutoSell") or rawget(_G, "AutoSellModule")
    if type(asell) == "table" and type(asell.PausePeers) == "function" then
        pcall(asell.PausePeers, asell, reason)
        if type(asell.WaitIdle) == "function" then
            pcall(asell.WaitIdle, asell, 15)
        end
    else
        if type(asell) == "table" and type(asell.Pause) == "function" then
            pcall(asell.Pause, asell, reason)
            if type(asell.WaitIdle) == "function" then
                pcall(asell.WaitIdle, asell, 15)
            end
        end
        local af = G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
        if type(af) == "table" and type(af.Pause) == "function" then
            pcall(af.Pause, af, reason)
        end
    end
end

local function resumeSellPeers()
    if not sellHold.held then return end
    sellHold.held = false

    local af = G.AutoFav or G.AutoFavModule or rawget(_G, "AutoFav") or rawget(_G, "AutoFavModule")
    local asell = G.AutoSellFruit or G.AutoSell or G.AutoSellModule
        or rawget(_G, "AutoSellFruit") or rawget(_G, "AutoSell") or rawget(_G, "AutoSellModule")

    if type(af) == "table" and type(af.Resume) == "function" then
        pcall(af.Resume, af)
    end

    local sellOn = (G.AUTO_SELL_ENABLED == true) or (rawget(_G, "AUTO_SELL_ENABLED") == true)
    if not sellOn and type(asell) == "table" and type(asell.IsRunning) == "function" then
        local okR, r = pcall(asell.IsRunning, asell)
        sellOn = okR and r == true
    end
    if sellOn and type(af) == "table" and type(af.SyncBeforeSell) == "function" then
        pcall(af.SyncBeforeSell, af, {
            beforeSell = true,
            fireDelay = 0,
            maxWallSec = 8,
        })
        task.wait(0.12)
    end

    if type(asell) == "table" and type(asell.Resume) == "function" then
        pcall(asell.Resume, asell)
    end

    if sellHold.boostBusyHeld == true then
        sellHold.boostBusyHeld = false
        G.__GAG2_BOOST_SELL_BUSY = false
        _G.__GAG2_BOOST_SELL_BUSY = false
    end
end

local function isHarvestFruitCategory(category)
    local cat = string.lower(tostring(category or ""))
    return cat:find("fruit", 1, true) ~= nil
end

local function prepareHarvestBatch(batch, autoUnfav)
    if type(batch) ~= "table" or #batch < 1 then return batch, {} end
    local restored = {}
    local out = {}
    for _, item in ipairs(batch) do
        local cat = tostring(item.Category or "")
        -- Hanya harvest fruit yang butuh unfav/promote; pets/lain tetap as-is.
        if isHarvestFruitCategory(cat) then
            local id = tostring(item.ItemKey or "")
            if id ~= "" then
                if autoUnfav then
                    if setFruitFavorite(id, false) then
                        restored[#restored + 1] = id
                    end
                    task.wait(0.02)
                end
                promoteFruit(id)
                out[#out + 1] = { Category = item.Category, ItemKey = id, Count = item.Count or 1 }
            end
        else
            out[#out + 1] = item
        end
    end
    if autoUnfav and #restored > 0 then
        task.wait(0.35)
        harvestBagCache = nil
        harvestBagCacheAt = 0
    end
    return out, restored
end

local function restoreFavorites(ids)
    if type(ids) ~= "table" then return end
    for i, id in ipairs(ids) do
        setFruitFavorite(id, true)
        if i < #ids then task.wait(0.03) end
    end
    if #ids > 0 then task.wait(0.35) end
end

-- Web Thr% = AutoGift harvest_price_threshold_pct: targetMin=limit, targetMax=limit*(1+thr%).
local function clampThresholdPct(v, defaultPct)
    local n = tonumber(v)
    local pct = math.floor(n ~= nil and n or (tonumber(defaultPct) or 10))
    if pct < 0 then pct = 0 end
    if pct > 100 then pct = 100 end
    return pct
end

local function parseMinFruitValue(v, defaultValue)
    local n = tonumber(v)
    if n == nil then return math.max(0, math.floor(tonumber(defaultValue) or 0)) end
    if n < 0 then n = 0 end
    return math.floor(n + 0.5)
end

local function priceRangeForTarget(target, thresholdPct)
    target = math.max(0, math.floor(tonumber(target) or 0))
    if target <= 0 then return 0, 0 end
    local pct = clampThresholdPct(thresholdPct, 10)
    local maxPrice = math.floor(target * (1 + pct / 100) + 0.5)
    return target, maxPrice
end

local function ensurePlayerState()
    if Net.PlayerStateClient then return true end
    local ok, client = pcall(function()
        return require(ReplicatedStorage:WaitForChild("ClientModules", 15):WaitForChild("PlayerStateClient"))
    end)
    if ok then Net.PlayerStateClient = client end
    return Net.PlayerStateClient ~= nil
end

local function getInventory()
    if not ensurePlayerState() then return nil end
    if type(Net.PlayerStateClient.GetLocalReplica) ~= "function" then return nil end
    local replica = Net.PlayerStateClient:GetLocalReplica()
    if not replica or type(replica.Data) ~= "table" then return nil end
    local inv = replica.Data.Inventory
    return type(inv) == "table" and inv or nil
end

local function entryUniqueId(entry, itemKey)
    if type(entry) == "table" then
        local id = entry.Id or entry.UUID or entry.PetId or entry.InstanceId
            or entry.Guid or entry.UniqueId or entry.PetUUID
        if id ~= nil and tostring(id) ~= "" then return tostring(id) end
    end
    if itemKey ~= nil and tostring(itemKey) ~= "" then return tostring(itemKey) end
    return nil
end

local function stackCount(entry)
    if type(entry) == "number" then return entry end
    if type(entry) == "table" then
        return tonumber(entry.Count or entry.Amount or entry.Quantity or entry.Stack or entry.Qty) or 1
    end
    return tonumber(entry) or 0
end

local function isUuidCategory(cat)
    local c = string.lower(tostring(cat or ""))
    return c == "pets" or c == "pet" or c == "harvestedfruits" or c == "fruits" or c == "fruit"
end

local function isLikelyFruitInstanceId(id)
    id = tostring(id or "")
    if id == "" or id:find("%s") or #id < 8 then return false end
    if id:match("^[%a'%-]+$") and not id:match("[%d_]") then return false end
    return true
end

local function pickFruitField(entry, fields)
    if type(entry) ~= "table" or type(fields) ~= "table" then return nil end
    for _, k in ipairs(fields) do
        local v = entry[k]
        if v ~= nil and tostring(v) ~= "" then return v end
    end
    return nil
end

local FRUIT_ID_FIELDS = { "Id", "id", "UUID", "Uuid", "FruitId", "fruitId" }
local FRUIT_NAME_FIELDS = { "FruitName", "Fruit", "PlantName", "Name", "DisplayName" }

local function bagHasEntries(bag)
    if type(bag) ~= "table" then return false end
    local nested = bag.List or bag.Items
    if type(nested) == "table" and #nested > 0 then return true end
    for itemKey in pairs(bag) do
        if tostring(itemKey):sub(1, 1) ~= "_" then return true end
    end
    return false
end

local function bagHasOnlyDisplayNameKeys(bag)
    if type(bag) ~= "table" then return false end
    local sawName, sawId = false, false
    local nested = bag.List or bag.Items
    local function check(ikey, entry)
        local id = nil
        if type(entry) == "table" then
            id = pickFruitField(entry, FRUIT_ID_FIELDS)
        end
        if (id and isLikelyFruitInstanceId(id)) or isLikelyFruitInstanceId(ikey) then
            sawId = true
        else
            sawName = true
        end
    end
    if type(nested) == "table" and #nested > 0 then
        for idx, entry in ipairs(nested) do check(idx, entry) end
    else
        for ikey, entry in pairs(bag) do
            if tostring(ikey):sub(1, 1) ~= "_" then check(ikey, entry) end
        end
    end
    return sawName and not sawId
end

local function instLooksLikeHarvestedFruit(inst)
    if not inst or type(inst.GetAttribute) ~= "function" then return false end
    if inst:GetAttribute("SeedTool") ~= nil then return false end
    if inst:GetAttribute("Pet") ~= nil then return false end
    if inst:GetAttribute("PottedPlant") == true then return false end
    if tostring(inst:GetAttribute("MainCategory") or "") == "Seed" then return false end
    local fruitName = inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit")
    if fruitName ~= nil and tostring(fruitName) ~= "" then return true end
    if inst:GetAttribute("FruitProxy") == true then return true end
    local hf = inst:GetAttribute("HarvestedFruit")
    if hf == true then return true end
    if type(hf) == "string" and hf ~= "" then return true end
    return false
end

local function instanceFruitToMailEntry(inst)
    if not instLooksLikeHarvestedFruit(inst) then return nil end
    local id = tostring(inst:GetAttribute("Id") or inst:GetAttribute("UUID") or inst:GetAttribute("FruitId") or "")
    if not isLikelyFruitInstanceId(id) then return nil end
    return {
        Id = id,
        FruitName = inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") or inst.Name,
        Mutation = inst:GetAttribute("Mutation"),
        Weight = tonumber(inst:GetAttribute("Weight")),
        SizeMultiplier = inst:GetAttribute("SizeMultiplier") or inst:GetAttribute("SizeMulti"),
        Decay = inst:GetAttribute("DecayAlpha") or inst:GetAttribute("Decay"),
        BidPrice = tonumber(inst:GetAttribute("BidPrice")),
        IsFavorite = inst:GetAttribute("IsFavorite"),
    }
end

local function looksLikeLayoutFruitEntry(entry)
    if type(entry) ~= "table" then return false end
    if entry.SeedTool ~= nil or entry.Pet ~= nil then return false end
    if entry.PottedPlant == true then return false end
    if tostring(entry.MainCategory or "") == "Seed" then return false end
    local id = pickFruitField(entry, FRUIT_ID_FIELDS)
    if type(id) == "string" and id ~= "" and #id >= 8 then return true end
    local name = pickFruitField(entry, FRUIT_NAME_FIELDS)
    if name ~= nil and tostring(name) ~= "" then return true end
    if entry.HarvestedFruit == true or entry.FruitProxy == true then return true end
    return false
end

local function collectLayoutFruitEntries(layout, out, depth, seen)
    if depth > 12 or type(layout) ~= "table" then return end
    if seen[layout] then return end
    seen[layout] = true
    if looksLikeLayoutFruitEntry(layout) then
        out[#out + 1] = layout
        return
    end
    for _, value in pairs(layout) do
        if type(value) == "table" then
            if looksLikeLayoutFruitEntry(value) then
                out[#out + 1] = value
            else
                collectLayoutFruitEntries(value, out, depth + 1, seen)
            end
        end
    end
end

local function getBackpackFruitBag(forceRefresh)
    local now = os.clock()
    if not forceRefresh and harvestBagCache and (now - harvestBagCacheAt) < 2 then
        return harvestBagCache
    end
    local bag, byId = {}, {}
    local function addEntry(entry)
        if type(entry) ~= "table" then return end
        local id = tostring(entry.Id or pickFruitField(entry, FRUIT_ID_FIELDS) or "")
        if not isLikelyFruitInstanceId(id) then return end
        entry.Id = id
        if byId[id] then return end
        byId[id] = true
        bag[id] = entry
    end

    ensureNetworking()
    if remoteCallable(Net.BackpackGetLayout) then
        local ok, layout = callRemote(Net.BackpackGetLayout)
        if ok and type(layout) == "table" then
            local raw = {}
            collectLayoutFruitEntries(layout, raw, 0, {})
            for _, layoutEntry in ipairs(raw) do
                local id = tostring(pickFruitField(layoutEntry, FRUIT_ID_FIELDS) or "")
                if isLikelyFruitInstanceId(id) then
                    addEntry({
                        Id = id,
                        FruitName = pickFruitField(layoutEntry, FRUIT_NAME_FIELDS),
                        Mutation = layoutEntry.Mutation or layoutEntry.mutation,
                        Weight = tonumber(layoutEntry.Weight),
                        SizeMultiplier = layoutEntry.SizeMultiplier or layoutEntry.SizeMulti,
                        Decay = layoutEntry.DecayAlpha or layoutEntry.Decay,
                        BidPrice = tonumber(layoutEntry.BidPrice or layoutEntry.bidPrice),
                        IsFavorite = layoutEntry.IsFavorite,
                    })
                end
            end
        end
    end

    local function scanContainer(container)
        if not container then return end
        local okKids, kids = pcall(function()
            if type(container.GetChildren) ~= "function" then return nil end
            return container:GetChildren()
        end)
        if not okKids or type(kids) ~= "table" then return end
        for _, inst in ipairs(kids) do
            pcall(function()
                if type(inst) == "userdata" or type(inst) == "table" then
                    local isTool = false
                    if type(inst.IsA) == "function" then
                        isTool = inst:IsA("Tool") == true
                    end
                    if isTool or instLooksLikeHarvestedFruit(inst) then
                        addEntry(instanceFruitToMailEntry(inst))
                    end
                end
            end)
        end
    end
    pcall(function()
        scanContainer(LocalPlayer:FindFirstChild("Backpack") or LocalPlayer:FindFirstChildOfClass("Backpack"))
    end)
    pcall(function()
        scanContainer(LocalPlayer.Character)
    end)

    harvestBagCache = bag
    harvestBagCacheAt = now
    return bag
end

-- Sama AutoGift: buah sering di Backpack, bukan Inventory.HarvestedFruits.
local function getHarvestedFruitBag(inv)
    local invBag = nil
    if type(inv) == "table" then
        invBag = inv.HarvestedFruits or inv.Fruits or inv.Fruit
    end
    local bpBag = getBackpackFruitBag(false)
    local invHas = bagHasEntries(invBag)
    local bpHas = bagHasEntries(bpBag)
    if invHas and bagHasOnlyDisplayNameKeys(invBag) then
        bpBag = getBackpackFruitBag(true)
        bpHas = bagHasEntries(bpBag)
    end
    if bpHas then return bpBag, "HarvestedFruits" end
    if invHas and not bagHasOnlyDisplayNameKeys(invBag) then
        return invBag, "HarvestedFruits"
    end
    return {}, "HarvestedFruits"
end

local function findBag(inv, category)
    if type(inv) ~= "table" and not isHarvestFruitCategory(category) then return nil end
    local want = tostring(category or "")
    local wantLower = string.lower(want)
    if isHarvestFruitCategory(want) then
        return getHarvestedFruitBag(inv)
    end
    if type(inv) ~= "table" then return nil, want end
    if inv[want] then return inv[want], want end
    for k, v in pairs(inv) do
        if string.lower(tostring(k)) == wantLower then return v, tostring(k) end
    end
    if wantLower == "pets" or wantLower == "pet" then
        return inv.Pets or inv.Pet, "Pets"
    end
    if wantLower == "seeds" or wantLower == "seed" then
        return inv.Seeds or inv.Seed, "Seeds"
    end
    return nil, want
end

local function entryPrice(entry)
    if type(entry) == "number" then return 0 end
    if type(entry) ~= "table" then return 0 end
    local p = tonumber(entry.Price or entry.SellPrice or entry.TotalValue or entry.Value or entry.value or entry.sell_price)
    if p and p > 0 then return math.floor(p + 0.5) end

    local fsv = G.FruitSellValue or rawget(_G, "FruitSellValue")
    if type(fsv) == "table" and type(fsv.refresh) == "function" then
        pcall(fsv.refresh, true)
    end

    local id = tostring(entry.Id or pickFruitField(entry, FRUIT_ID_FIELDS) or entryUniqueId(entry, nil) or "")
    local name = tostring(pickFruitField(entry, FRUIT_NAME_FIELDS) or "")
    local multi = tonumber(entry.SizeMultiplier or entry.SizeMulti or entry.WeightMulti or entry.Multi) or 0
    local mut = entry.Mutation or entry.Mutations or entry.mutation
    local decay = entry.Decay or entry.DecayAlpha
    local bid = tonumber(entry.BidPrice or entry.bidPrice) or 0

    if multi <= 0 and type(fsv) == "table" and type(fsv.resolveMulti) == "function" and id ~= "" then
        -- resolveMulti expects tool instance when possible; skip if unavailable
    end
    if multi <= 0 then multi = 1 end

    if type(fsv) == "table" and type(fsv.getBackpackEspPrice) == "function" and name ~= "" then
        local ok, v = pcall(fsv.getBackpackEspPrice, name, multi, mut, decay, "base", id, bid)
        if ok and type(v) == "number" and v > 0 then return math.floor(v + 0.5) end
        -- Older signature without bid
        ok, v = pcall(fsv.getBackpackEspPrice, name, multi, mut, decay, "base", id)
        if ok and type(v) == "number" and v > 0 then return math.floor(v + 0.5) end
    end
    return 0
end

local function collectCandidates(category, itemKey, allItems, minFruitValue, maxFruitValue)
    local inv = getInventory()
    local bag, bagName = findBag(inv, category)
    if type(bag) ~= "table" or not bagHasEntries(bag) then
        return {}, bagName or category, "bag_empty"
    end

    local out = {}
    local wantKey = tostring(itemKey or "")
    local uuidMode = isUuidCategory(bagName or category)
    local wantLower = string.lower(wantKey)
    local minV = parseMinFruitValue(minFruitValue, 0)
    local maxV = parseMinFruitValue(maxFruitValue, 0)
    local harvestBag = isHarvestFruitCategory(bagName or category)

    local function fruitInBand(price)
        price = tonumber(price) or 0
        if price <= 0 then return true end -- unknown price: keep; Lua pricing may still fail later
        if minV > 0 and price <= minV then return false end
        if maxV > 0 and price > maxV then return false end
        return true
    end

    local function push(ikey, entry)
        local keyStr = tostring(ikey)
        if keyStr:sub(1, 1) == "_" then return end
        local nm = ""
        if type(entry) == "table" then
            nm = tostring(pickFruitField(entry, FRUIT_NAME_FIELDS) or "")
        end
        if not allItems and wantKey ~= "" then
            local keyOk = keyStr == wantKey or string.lower(keyStr) == wantLower
            local nameOk = nm ~= "" and string.lower(nm) == wantLower
            if not keyOk and not nameOk then return end
        end
        if uuidMode then
            local uid = nil
            if type(entry) == "table" then
                uid = tostring(pickFruitField(entry, FRUIT_ID_FIELDS) or "")
                if not isLikelyFruitInstanceId(uid) then uid = entryUniqueId(entry, ikey) end
            else
                uid = entryUniqueId(entry, ikey)
            end
            if not uid or uid == "" then return end
            if harvestBag and not isLikelyFruitInstanceId(uid) then
                return
            end
            local price = entryPrice(type(entry) == "table" and entry or {})
            if harvestBag and not fruitInBand(price) then
                return
            end
            table.insert(out, {
                Category = bagName or category,
                ItemKey = uid,
                Count = 1,
                uuid = true,
                name = nm ~= "" and nm or uid,
                price = price,
                raw = entry,
            })
        else
            local n = stackCount(entry)
            if n > 0 then
                local displayName = nm ~= "" and nm or keyStr
                local price = entryPrice(type(entry) == "table" and entry or {})
                if harvestBag and not fruitInBand(price) then
                    return
                end
                table.insert(out, {
                    Category = bagName or category,
                    ItemKey = keyStr,
                    Count = n,
                    uuid = false,
                    name = displayName,
                    price = price,
                    raw = entry,
                })
            end
        end
    end

    local nested = bag.List or bag.Items
    if type(nested) == "table" and #nested > 0 then
        for idx, entry in ipairs(nested) do
            push(entryUniqueId(entry, idx) or idx, entry)
        end
    else
        for ikey, entry in pairs(bag) do
            push(ikey, entry)
        end
    end
    return out, bagName or category, (#out > 0) and "ok" or "filtered_empty"
end

local function takeBatch(pool, remaining, uuidMode)
    local batch = {}
    local taken = 0
    while #batch < MAX_BATCH_ROWS and remaining > 0 and #pool > 0 do
        local row = pool[1]
        if row.uuid or uuidMode then
            table.insert(batch, {
                Category = row.Category,
                ItemKey = row.ItemKey,
                Count = 1,
                name = row.name,
                price = row.price,
            })
            table.remove(pool, 1)
            taken = taken + 1
            remaining = remaining - 1
        else
            local give = math.min(MAX_STACK_COUNT, row.Count, remaining)
            if give <= 0 then
                table.remove(pool, 1)
            else
                table.insert(batch, {
                    Category = row.Category,
                    ItemKey = row.ItemKey,
                    Count = give,
                    name = row.name,
                    price = row.price,
                })
                row.Count = row.Count - give
                taken = taken + give
                remaining = remaining - give
                if row.Count <= 0 then table.remove(pool, 1) end
            end
        end
    end
    return batch, taken, remaining, 0
end

-- Mode value: pilih by price. Thr% (web) = boleh overshoot sampai target*(1+thr/100), sama AutoGift.
-- remainMin = sisa menuju targetMin; remainMax = sisa menuju targetMax (cap per fruit/batch).
local function takeBatchByValue(pool, remainMin, remainMax)
    remainMin = math.max(0, math.floor(tonumber(remainMin) or 0))
    remainMax = math.max(remainMin, math.floor(tonumber(remainMax) or remainMin))
    if remainMin <= 0 or #pool < 1 then
        return {}, 0, 0
    end
    table.sort(pool, function(a, b)
        return (tonumber(a.price) or 0) > (tonumber(b.price) or 0)
    end)
    local batch = {}
    local takenItems = 0
    local takenValue = 0
    local i = 1
    local guard = 0
    while #batch < MAX_BATCH_ROWS and takenValue < remainMin and i <= #pool and guard < 500 do
        guard = guard + 1
        local row = pool[i]
        local price = tonumber(row.price) or 0
        local room = remainMax - takenValue
        if row.uuid then
            if price > 0 and price <= room then
                table.insert(batch, {
                    Category = row.Category,
                    ItemKey = row.ItemKey,
                    Count = 1,
                    name = row.name,
                    price = price,
                })
                table.remove(pool, i)
                takenItems = takenItems + 1
                takenValue = takenValue + price
            else
                i = i + 1
            end
        else
            if price <= 0 then
                i = i + 1
            else
                local maxUnits = math.min(MAX_STACK_COUNT, row.Count, math.floor(room / price))
                if maxUnits < 1 then
                    i = i + 1
                else
                    -- Ambil cukup untuk mendekati remainMin, tanpa lewat remainMax.
                    local needUnits = math.ceil((remainMin - takenValue) / price)
                    if needUnits < 1 then needUnits = 1 end
                    local units = math.min(maxUnits, needUnits)
                    table.insert(batch, {
                        Category = row.Category,
                        ItemKey = row.ItemKey,
                        Count = units,
                        name = row.name,
                        price = price,
                    })
                    row.Count = row.Count - units
                    local addVal = units * price
                    takenItems = takenItems + units
                    takenValue = takenValue + addVal
                    if row.Count <= 0 then
                        table.remove(pool, i)
                    else
                        i = i + 1
                    end
                end
            end
        end
    end
    return batch, takenItems, takenValue
end

-- Snapshot tipis untuk History web (tanpa raw / UUID panjang penuh bila perlu).
local function snapshotBatchItems(batch)
    local out = {}
    if type(batch) ~= "table" then return out end
    for _, item in ipairs(batch) do
        local cat = tostring(item.Category or "")
        local key = tostring(item.ItemKey or "")
        local cnt = math.max(1, math.floor(tonumber(item.Count) or 1))
        local name = tostring(item.name or item.Name or item.DisplayName or "")
        if name == "" then
            if #key > 14 then
                name = string.sub(key, 1, 10) .. "…"
            else
                name = key ~= "" and key or "item"
            end
        end
        local unit = math.max(0, math.floor(tonumber(item.price or item.UnitPrice or item.unit_price) or 0))
        out[#out + 1] = {
            category = cat,
            item_key = key,
            name = name,
            count = cnt,
            unit_price = unit,
            price = unit * cnt,
        }
    end
    return out
end

local function parseCooldownSeconds(text)
    local s = string.lower(tostring(text or ""))
    local n = s:match("wait%s+(%d+)%s*s")
    if n then return tonumber(n) end
    n = s:match("wait%s+(%d+)")
    if n then return tonumber(n) end
    if s:find("wait", 1, true) then
        n = s:match("(%d+)%s*s")
        if n then return tonumber(n) end
    end
    return nil
end

local function isCooldownMessage(msg)
    local s = string.lower(tostring(msg or ""))
    if s == "" then return false end
    if s:find("before sending", 1, true) then return true end
    if s:find("wait", 1, true) and s:find("gift", 1, true) then return true end
    if parseCooldownSeconds(msg) then return true end
    return false
end

local function classifyFail(msg)
    local s = string.lower(tostring(msg or ""))
    if s:find("5 gifts to that player", 1, true) or (s:find("already sent", 1, true) and s:find("today", 1, true)) then
        return "daily_recipient"
    end
    if s:find("daily", 1, true) and (s:find("limit", 1, true) or s:find("50", 1, true) or s:find("gift", 1, true)) then
        return "daily_total"
    end
    if isCooldownMessage(msg) then
        return "cooldown"
    end
    return "send_failed"
end

local function getBridge()
    local NodeHubWS = G.NodeHubWS or rawget(_G, "NodeHubWS")
    if type(NodeHubWS) == "table" and type(NodeHubWS.GAG2) == "table" then
        return NodeHubWS.GAG2
    end
    return nil
end

local function sendAck(bridge, packet)
    if type(bridge) == "table" and type(bridge.SendPacket) == "function" then
        pcall(bridge.SendPacket, bridge, packet)
        return
    end
    local NodeHubWS = G.NodeHubWS or rawget(_G, "NodeHubWS")
    if type(NodeHubWS) == "table" and type(NodeHubWS.Send) == "function" then
        pcall(NodeHubWS.Send, packet)
    end
end

local function resolveTaskUserId(task)
    local id = task and (task.recipient_user_id or task.user_id or task.recipient_id)
    if id == nil or id == false or id == 0 or id == "" then
        return nil
    end
    -- Roblox user ids are numeric; coerce string digits.
    local n = tonumber(id)
    if n and n > 0 then return n end
    local s = tostring(id)
    if s ~= "" and s ~= "0" and s ~= "false" and s ~= "nil" then
        return s
    end
    return nil
end

local function runJob(payload, message, bridge)
    if running then
        -- Jangan return busy (hub finalize route lain). Antre payload.
        pendingQueue[#pendingQueue + 1] = {
            payload = payload,
            message = message or {},
            bridge = bridge or getBridge(),
        }
        local NodeHubWS = G.NodeHubWS or rawget(_G, "NodeHubWS")
        local b = bridge or getBridge()
        -- Jangan phase=accepted (Node akan mark running + job_done sebelumnya bisa wipe).
        sendAck(b, {
            type = "mail_controller_gift_ack",
            request_id = message and message.request_id,
            job_id = tostring(payload.job_id or ""),
            akun_game_id = payload.akun_game_id,
            akun_username = payload.akun_username,
            game_id = payload.game_id,
            phase = "queued",
            ok = true,
            success = true,
            queued = true,
            mc_version = MC_VERSION,
            message = "queued_behind_active_job",
        })
        return true, "queued"
    end
    running = true
    local requestId = message and message.request_id
    local jobId = tostring(payload.job_id or "")
    cancelJobs[jobId] = nil
    local pausedSell = false

    local function ack(fields)
        local p = {
            type = "mail_controller_gift_ack",
            request_id = requestId,
            job_id = jobId,
            akun_game_id = payload.akun_game_id,
            akun_username = payload.akun_username,
            game_id = payload.game_id,
        }
        for k, v in pairs(fields) do p[k] = v end
        sendAck(bridge, p)
    end

    local function pumpQueue()
        if running then return end
        if #pendingQueue < 1 then return end
        local nextJob = table.remove(pendingQueue, 1)
        if not nextJob then return end
        if type(task) == "table" and type(task.defer) == "function" then
            task.defer(function()
                M.HandleCommand(nextJob.payload, nextJob.message, nextJob.bridge)
            end)
        else
            M.HandleCommand(nextJob.payload, nextJob.message, nextJob.bridge)
        end
    end

    local function finish(ok, extra)
        if pausedSell then
            resumeSellPeers()
            pausedSell = false
        end
        running = false
        if type(extra) == "table" then
            ack(extra)
        end
        pumpQueue()
        return ok
    end

    ack({ phase = "accepted", ok = true, success = true, mc_version = MC_VERSION })

    if not ensureNetworking() then
        return finish(false, { phase = "job_done", ok = false, success = false, fail_code = "networking_missing" })
    end

    local category = tostring(payload.category or "")
    local itemKey = tostring(payload.item_key or "")
    local allItems = itemKey == ""
    local mode = tostring(payload.mode or payload.send_mode or "total_item")
    local autoUnfav = payload.auto_unfav ~= false and payload.auto_unfav ~= 0 and payload.auto_unfav ~= "0"
    -- Web: price_threshold_pct (Thr%). Alias harvest_price_threshold_pct / threshold_pct.
    local thresholdPct = clampThresholdPct(
        payload.price_threshold_pct or payload.harvest_price_threshold_pct or payload.threshold_pct,
        10
    )
    -- Web Min/Max fruit: skip harvest fruits outside sell-value band (default 50M–500M).
    local minFruitValue = parseMinFruitValue(
        payload.min_fruit_value or payload.harvest_min_fruit_value or payload.min_fruit,
        50000000
    )
    local maxFruitValue = parseMinFruitValue(
        payload.max_fruit_value or payload.harvest_max_fruit_value or payload.max_fruit,
        500000000
    )
    local harvestFruit = isHarvestFruitCategory(category) and isUuidCategory(category)
    local tasks = type(payload.tasks) == "table" and payload.tasks or {}
    local lastSendAt = 0

    -- Pause sell/stock/daily sebelum unfav / SendBatch (cegah race jual buah).
    if harvestFruit then
        pauseSellPeers(autoUnfav and "mail_controller_gift_unfav" or "mail_controller_gift")
        pausedSell = true
    end

    for _, jobTask in ipairs(tasks) do
        if cancelJobs[jobId] then
            ack({ phase = "cancelled", ok = true, success = true })
            break
        end
        local assignmentId = tostring(jobTask.assignment_id or "")
        local recipient = tostring(jobTask.recipient or "")
        local limit = tonumber(jobTask.limit) or 0
        local sentTotal = 0

        if limit <= 0 or recipient == "" then
            ack({
                phase = "task_failed",
                ok = false,
                success = false,
                assignment_id = assignmentId,
                recipient = recipient,
                fail_code = "bad_task",
                sent_total = 0,
                limit = limit,
            })
        else
            local userId = resolveTaskUserId(jobTask)
            if not userId then
                ack({
                    phase = "task_failed",
                    ok = false,
                    success = false,
                    assignment_id = assignmentId,
                    recipient = recipient,
                    fail_code = "missing_user_id",
                    message = "recipient_user_id required from web",
                    sent_total = 0,
                    limit = limit,
                })
            else
                local progress = { sent = 0 }
                local okTask, errTask = xpcall(function()
                local byValue = (mode == "total_value" or mode == "price" or mode == "value")
                local pool, bagName, poolReason = collectCandidates(category, itemKey, allItems, minFruitValue, maxFruitValue)
                local uuidMode = isUuidCategory(category)
                local targetMin, targetMax = limit, limit
                if byValue then
                    -- Resume/fill sering kirim limit=sisa (20M). Thr% harus dari target asli (8B),
                    -- supaya room = originalMax - prior_sent (bukan 20M*1.1=22M).
                    local originalQuota = tonumber(jobTask.original_quota or jobTask.threshold_base) or 0
                    local priorSent = tonumber(jobTask.prior_sent or jobTask.prior_sent_total) or 0
                    if originalQuota > 0 and priorSent >= 0 then
                        local _, absMax = priceRangeForTarget(originalQuota, thresholdPct)
                        local room = math.max(0, absMax - priorSent)
                        targetMin = limit
                        targetMax = math.max(targetMin, room)
                    else
                        targetMin, targetMax = priceRangeForTarget(limit, thresholdPct)
                    end
                end
                local remaining = byValue and targetMin or limit
                sentTotal = 0
                local sentItems = 0
                local failed = false
                local failCode, failMsg

                while (byValue and sentTotal < targetMin or (not byValue and remaining > 0)) and not failed do
                    if cancelJobs[jobId] then
                        ack({ phase = "cancelled", ok = true, success = true, assignment_id = assignmentId })
                        failed = true
                        failCode = "cancelled"
                        break
                    end
                    local can, reason = softCanSend(recipient)
                    if not can then
                        failed = true
                        failCode = reason
                        failMsg = reason
                        break
                    end
                    if #pool < 1 then
                        local okPool0, p0, b0, r0 = pcall(collectCandidates, category, itemKey, allItems, minFruitValue, maxFruitValue)
                        if okPool0 then
                            pool, bagName, poolReason = p0 or {}, b0, r0
                        else
                            pool, poolReason = {}, "collect:" .. tostring(p0)
                        end
                    end

                    local batch, taken, rem, takenValue
                    if byValue then
                        local remainMin = math.max(0, targetMin - sentTotal)
                        local remainMax = math.max(remainMin, targetMax - sentTotal)
                        batch, taken, takenValue = takeBatchByValue(pool, remainMin, remainMax)
                        rem = math.max(0, targetMin - (sentTotal + (tonumber(takenValue) or 0)))
                        remaining = rem
                    else
                        batch, taken, rem = takeBatch(pool, remaining, uuidMode)
                        remaining = rem
                        takenValue = 0
                    end

                    if type(batch) ~= "table" then batch = {} end
                    taken = tonumber(taken) or 0
                    if #batch < 1 or taken < 1 then
                        if byValue and #pool > 0 then
                            -- Pool ada tapi harga 0 / tidak muat band threshold.
                            local priced = 0
                            for _, row in ipairs(pool) do
                                if (tonumber(row.price) or 0) > 0 then priced = priced + 1 end
                            end
                            if priced < 1 then
                                failed = true
                                failCode = "no_priced_stock"
                                failMsg = "pool=" .. tostring(#pool) .. " priced=0 bag=" .. tostring(bagName or category)
                                break
                            end
                        end
                        if byValue and sentTotal > 0 and sentTotal < targetMin then
                            failCode = "value_remainder"
                            failMsg = "remaining value cannot be filled within threshold band"
                            break
                        end
                        failed = true
                        failCode = byValue and "no_priced_stock" or "no_stock"
                        failMsg = tostring(poolReason or failCode) .. " bag=" .. tostring(bagName or category) .. " pool=" .. tostring(#pool)
                        break
                    end

                    local favRestore = {}
                    local itemsSnap = snapshotBatchItems(batch)
                    if isUuidCategory(category) then
                        local okPrep, prepBatch, prepFav = pcall(prepareHarvestBatch, batch, autoUnfav and harvestFruit)
                        if okPrep then
                            batch = type(prepBatch) == "table" and prepBatch or batch
                            favRestore = type(prepFav) == "table" and prepFav or {}
                        end
                    end

                    local okFire, success, msg
                    local cooldownTries = 0
                    while true do
                        local waitLeft = SEND_COOLDOWN - (now() - lastSendAt)
                        if waitLeft > 0 then task.wait(waitLeft) end

                        okFire, success, msg = callRemote(Net.SendBatch, userId, batch, "")
                        lastSendAt = now()

                        if not okFire then
                            break
                        end
                        if success ~= false then
                            break
                        end
                        if cancelJobs[jobId] then
                            break
                        end
                        if isCooldownMessage(msg) and cooldownTries < COOLDOWN_RETRIES then
                            cooldownTries = cooldownTries + 1
                            local sec = parseCooldownSeconds(msg) or SEND_COOLDOWN
                            if sec < SEND_COOLDOWN then sec = SEND_COOLDOWN end
                            task.wait(sec + 0.35)
                            -- Retry same batch (favorites still prepared).
                        else
                            break
                        end
                    end

                    if autoUnfav and type(favRestore) == "table" and #favRestore > 0 then
                        pcall(restoreFavorites, favRestore)
                    end
                    if not okFire then
                        failed = true
                        failCode = "send_error"
                        failMsg = tostring(success)
                        ack({
                            phase = "batch",
                            ok = false,
                            success = false,
                            assignment_id = assignmentId,
                            recipient = recipient,
                            mode = byValue and "total_value" or "total_item",
                            sent_count = 0,
                            sent_value = 0,
                            sent_total = sentTotal,
                            limit = limit,
                            target_min = byValue and targetMin or nil,
                            target_max = byValue and targetMax or nil,
                            price_threshold_pct = byValue and thresholdPct or nil,
                            items = itemsSnap,
                            fail_code = failCode,
                            message = failMsg,
                        })
                        break
                    end
                    if success == false then
                        failCode = classifyFail(msg)
                        failMsg = tostring(msg)
                        failed = true
                        ack({
                            phase = "batch",
                            ok = false,
                            success = false,
                            assignment_id = assignmentId,
                            recipient = recipient,
                            mode = byValue and "total_value" or "total_item",
                            sent_count = 0,
                            sent_value = 0,
                            sent_total = sentTotal,
                            limit = limit,
                            target_min = byValue and targetMin or nil,
                            target_max = byValue and targetMax or nil,
                            price_threshold_pct = byValue and thresholdPct or nil,
                            items = itemsSnap,
                            fail_code = failCode,
                            message = failMsg,
                        })
                        break
                    end

                    softMarkSuccess(recipient)
                    sentItems = sentItems + taken
                    local addMetric = byValue and (tonumber(takenValue) or 0) or taken
                    sentTotal = sentTotal + addMetric
                    progress.sent = sentTotal
                    if not byValue then
                        remaining = rem
                    else
                        remaining = math.max(0, targetMin - sentTotal)
                    end
                    ack({
                        phase = "batch",
                        ok = true,
                        success = true,
                        assignment_id = assignmentId,
                        recipient = recipient,
                        mode = byValue and "total_value" or "total_item",
                        sent_count = taken,
                        sent_value = byValue and (tonumber(takenValue) or 0) or nil,
                        sent_total = sentTotal,
                        limit = limit,
                        target_min = byValue and targetMin or nil,
                        target_max = byValue and targetMax or nil,
                        price_threshold_pct = byValue and thresholdPct or nil,
                        items = itemsSnap,
                        mc_version = MC_VERSION,
                    })

                    -- Inventory berubah setelah SendBatch — jangan pakai pool/cache basi.
                    harvestBagCache = nil
                    harvestBagCacheAt = 0
                    local okPool, newPool, newBag, newReason = pcall(collectCandidates, category, itemKey, allItems, minFruitValue, maxFruitValue)
                    if okPool then
                        pool = type(newPool) == "table" and newPool or {}
                        bagName = newBag or bagName
                        poolReason = newReason or poolReason
                    else
                        pool = {}
                        poolReason = "refresh_failed:" .. tostring(newPool)
                    end

                    if byValue and sentTotal >= targetMin then
                        break
                    end
                end

                progress.sent = sentTotal
                if failed then
                    ack({
                        phase = "task_failed",
                        ok = false,
                        success = false,
                        assignment_id = assignmentId,
                        recipient = recipient,
                        mode = byValue and "total_value" or "total_item",
                        sent_total = sentTotal,
                        limit = limit,
                        target_min = byValue and targetMin or nil,
                        target_max = byValue and targetMax or nil,
                        price_threshold_pct = byValue and thresholdPct or nil,
                        fail_code = failCode or "failed",
                        message = failMsg,
                        mc_version = MC_VERSION,
                    })
                else
                    local underMin = byValue and sentTotal < targetMin
                    ack({
                        phase = "task_done",
                        ok = not underMin,
                        success = not underMin,
                        assignment_id = assignmentId,
                        recipient = recipient,
                        mode = byValue and "total_value" or "total_item",
                        sent_total = sentTotal,
                        limit = limit,
                        target_min = byValue and targetMin or nil,
                        target_max = byValue and targetMax or nil,
                        price_threshold_pct = byValue and thresholdPct or nil,
                        fail_code = underMin and "value_remainder" or nil,
                        message = underMin and ("remainder_value=" .. tostring(math.max(0, targetMin - sentTotal))) or nil,
                        mc_version = MC_VERSION,
                    })
                end
                end, function(err)
                    local tb = ""
                    if type(debug) == "table" and type(debug.traceback) == "function" then
                        tb = debug.traceback(tostring(err), 2)
                    else
                        tb = tostring(err)
                    end
                    return tb
                end) -- xpcall task body
                if not okTask then
                    local crashedSent = tonumber(progress.sent) or sentTotal or 0
                    local lim = tonumber(limit) or 0
                    -- Batch mungkin sudah sukses; crash di refresh pool jangan tipu jadi gagal total.
                    if lim > 0 and crashedSent >= lim then
                        ack({
                            phase = "task_done",
                            ok = true,
                            success = true,
                            assignment_id = assignmentId,
                            recipient = recipient,
                            sent_total = crashedSent,
                            limit = limit,
                            fail_code = nil,
                            message = "recovered_after:" .. tostring(errTask),
                            mc_version = MC_VERSION,
                        })
                    else
                        ack({
                            phase = "task_failed",
                            ok = false,
                            success = false,
                            assignment_id = assignmentId,
                            recipient = recipient,
                            fail_code = "handler_error",
                            message = tostring(errTask),
                            sent_total = crashedSent,
                            limit = limit,
                            mc_version = MC_VERSION,
                        })
                    end
                end
            end
        end
    end

    return finish(true, { phase = "job_done", ok = true, success = true })
end

function M.HandleCommand(payload, message, bridge)
    payload = type(payload) == "table" and payload or {}
    local ok, a, b = pcall(function()
        return runJob(payload, message or {}, bridge or getBridge())
    end)
    if not ok then
        running = false
        resumeSellPeers()
        sendAck(bridge or getBridge(), {
            type = "mail_controller_gift_ack",
            request_id = message and message.request_id,
            job_id = tostring(payload.job_id or ""),
            phase = "job_done",
            ok = false,
            success = false,
            fail_code = "handler_error",
            message = tostring(a),
            mc_version = MC_VERSION,
        })
        -- Lanjut antrean meski command ini crash.
        if #pendingQueue > 0 then
            local nextJob = table.remove(pendingQueue, 1)
            if nextJob then
                if type(task) == "table" and type(task.defer) == "function" then
                    task.defer(function()
                        M.HandleCommand(nextJob.payload, nextJob.message, nextJob.bridge)
                    end)
                else
                    M.HandleCommand(nextJob.payload, nextJob.message, nextJob.bridge)
                end
            end
        end
        return false, tostring(a)
    end
    return a, b
end

function M.HandleCancel(payload, message, bridge)
    payload = type(payload) == "table" and payload or {}
    local jobId = tostring(payload.job_id or "")
    if jobId ~= "" then cancelJobs[jobId] = true end
    sendAck(bridge or getBridge(), {
        type = "mail_controller_gift_ack",
        request_id = message and message.request_id,
        job_id = jobId,
        phase = "cancelled",
        ok = true,
        success = true,
    })
    return true
end

local function install()
    local NodeHubWS = G.NodeHubWS or rawget(_G, "NodeHubWS")
    if type(NodeHubWS) ~= "table" then return end
    if type(NodeHubWS.OnCommand) == "function" then
        NodeHubWS.OnCommand("gag2", "mail_controller_gift", function(commandName, payload, message, bridge)
            return M.HandleCommand(payload, message, bridge)
        end)
        NodeHubWS.OnCommand("gag2", "mail_controller_gift_command", function(commandName, payload, message, bridge)
            return M.HandleCommand(payload, message, bridge)
        end)
        NodeHubWS.OnCommand("gag2", "mail_controller_gift_cancel", function(commandName, payload, message, bridge)
            return M.HandleCancel(payload, message, bridge)
        end)
    end
end

task.defer(install)
task.delay(2, install)

G.MailControllerGift = M
_G.MailControllerGift = M
return M
 end,            required = false },
    { key = "NormalGift",              name = "Normal Gift",             factory = function() -- NormalGift.lua — Grow A Garden 2
-- Nearby player gifts via Networking.Gifting.Send (not mailbox).

local Players           = game:GetService("Players")
