 end,                     required = false },
    { key = "AutoShovel",              name = "Auto Shovel Plant",       factory = function() -- AutoShovel.lua - Grow A Garden 2 (Auto Shovel Plant — hapus plant utuh)
-- Equip shovel -> Networking.Shovel.UseShovel:Fire(plantId, fruitId, shovelType, tool)

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService        = game:GetService("RunService")

