    attempts = 0,
    ok = 0,
    skipped = {},
    lastError = nil,
    lastPlantId = nil,
    lastSkip = nil,
}

local function _dbg()
    return G.AUTO_SHOVEL_DEBUG == true or _G.AUTO_SHOVEL_DEBUG == true
end

local function _log(...)
    if not _dbg() then return end
    print("[GAG2-AS]", ...)
end

local function _enabled()
    local store = G.__GAG2_SHOVEL or rawget(_G, "__GAG2_SHOVEL")
    if type(store) == "table" and store.enabled == true then return true end
    return G.AUTO_SHOVEL_ENABLED == true or rawget(_G, "AUTO_SHOVEL_ENABLED") == true
end

local function _selectedMap()
    local map = G.AUTO_SHOVEL_PLANTS_SELECTED or rawget(_G, "AUTO_SHOVEL_PLANTS_SELECTED")
    if type(map) == "table" then
        if map._none then map._none = nil end
        return map
    end
    local store = G.__GAG2_SHOVEL or rawget(_G, "__GAG2_SHOVEL")
    if type(store) == "table" and type(store.plants) == "table" then
        map = {}
        for _, id in ipairs(store.plants) do
            if id ~= nil and tostring(id) ~= "" and tostring(id) ~= "_none" then
                map[tostring(id)] = true
            end
        end
        return map
    end
    return {}
end

local function _selectedCount()
    local n = 0
    for k, v in pairs(_selectedMap()) do
        if v == true and k ~= "_none" then n = n + 1 end
    end
    return n
end

local function _parseHeightRule(txt)
    txt = tostring(txt or ""):gsub("%s+", "")
    if txt == "" then
        return 0, "above"
    end
    local n = tonumber(txt)
    if not n then
        return 0, "above"
    end
    if n < 0 then
        return math.abs(n), "below"
    end
    return n, "above"
end

local function _heightRule()
    local store = G.__GAG2_SHOVEL or rawget(_G, "__GAG2_SHOVEL")
    if type(store) == "table" and store.heightRule ~= nil then
        return _parseHeightRule(store.heightRule)
    end
    return _parseHeightRule(G.AUTO_SHOVEL_HEIGHT_RULE or rawget(_G, "AUTO_SHOVEL_HEIGHT_RULE"))
end

local function _getPlantHeight(plant)
    if not plant or not plant.Parent then return 0 end

    local rig = plant:FindFirstChild("Rig")
    if rig then
        pcall(function()
            rig.Parent = nil
        end)
    end

    local height = 0
    local ok, size = pcall(function()
        local _, s = plant:GetBoundingBox()
        return s
    end)
    if ok and typeof(size) == "Vector3" and size.Y > 0 then
        height = size.Y
    end

    if rig and rig.Parent == nil then
        pcall(function()
            rig.Parent = plant
        end)
    end

    if height > 0 then
        return height
    end

    -- fallback: hitung dari BasePart (kalau GetBoundingBox gagal)
    local minY, maxY = math.huge, -math.huge
    local found = false
    for _, d in ipairs(plant:GetDescendants()) do
        if d:IsA("BasePart") and d.Transparency < 1 then
            local half = d.Size.Y * 0.5
            local y1 = d.Position.Y - half
            local y2 = d.Position.Y + half
            if y1 < minY then minY = y1 end
            if y2 > maxY then maxY = y2 end
            found = true
        end
    end
    if found and maxY > minY then
        return maxY - minY
    end
    return 0
end

local function _matchHeight(height, threshold, mode)
    height = tonumber(height) or 0
    threshold = tonumber(threshold) or 0
    mode = tostring(mode or "above")
    if threshold <= 0 then
        return true
    end
    if mode == "below" then
        return height > 0 and height <= threshold
    end
    return height >= threshold
end

local function _plantMatchesHeight(plant)
    local threshold, mode = _heightRule()
    -- threshold 0 = no height filter → jangan GetBoundingBox (mahal di plot besar)
    if (tonumber(threshold) or 0) <= 0 then
        return true
    end
    return _matchHeight(_getPlantHeight(plant), threshold, mode)
end

local function _canRun()
    return _enabled() and _selectedCount() >= 1
end

function M.GetSelectedCount()
    return _selectedCount()
end
M.getSelectedCount = M.GetSelectedCount

function M.HasSelection()
    return _selectedCount() >= 1
end
M.hasSelection = M.HasSelection

function M.CanRun()
    return _canRun()
end
M.canRun = M.CanRun

local function _initRemotes()
    if remotesReady then return end
    remotesReady = true
    local ok, Networking = pcall(function()
        return require(ReplicatedStorage.SharedModules.Networking)
    end)
    if not ok or type(Networking) ~= "table" then
        stats.lastError = "Networking require gagal"
        return
    end
    local ShovelNet = Networking.Shovel
    if type(ShovelNet) == "table" and type(ShovelNet.UseShovel) == "table"
        and type(ShovelNet.UseShovel.Fire) == "function" then
        UseShovel = ShovelNet.UseShovel
    end
    if not UseShovel then
        stats.lastError = "UseShovel MISSING"
        warn("[GAG2-AS] UseShovel remote tidak ditemukan")
    end
end

local function _getPlot()
    local plotId = LP and LP:GetAttribute("PlotId")
    if not plotId then return nil end
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then return nil end
    return gardens:FindFirstChild("Plot" .. tostring(plotId))
end

local function _getPlantsFolder()
    local plot = _getPlot()
    return plot and plot:FindFirstChild("Plants") or nil
end

function M.GetPlantDisplayName(plant)
    if not plant then return "?" end
    local fsv = G.FruitSellValue or rawget(_G, "FruitSellValue")
    if type(fsv) == "table" and type(fsv.resolveSeedName) == "function" then
        local ok, n = pcall(fsv.resolveSeedName, plant)
        if ok and type(n) == "string" and n ~= "" then
            return n
        end
    end
    return plant:GetAttribute("SeedName")
        or plant:GetAttribute("ConfigPathName")
        or plant:GetAttribute("CorePartName")
        or plant:GetAttribute("FruitType")
        or plant:GetAttribute("ItemName")
        or plant.Name
end
M.getPlantDisplayName = M.GetPlantDisplayName

local function _normalizePlantToken(v)
    v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if v == "" then return nil end
    local lower = v:lower()
    if lower == "none" or lower == "normal" or lower == "0" then return nil end
    return v
end

local function _mutationNamesFallback()
    local PLV = G.PlantListView or rawget(_G, "PlantListView")
    if type(PLV) == "table" and type(PLV.listMutationNames) == "function" then
        local ok, list = pcall(PLV.listMutationNames, PLV)
        if ok and type(list) == "table" and #list > 0 then return list end
    end
    return { "Gold", "Rainbow" }
end

local function _addMutationToken(seen, out, token)
    token = _normalizePlantToken(token)
    if not token then return end
    local canon = token:lower()
    if seen[canon] then return end
    seen[canon] = token
    out[#out + 1] = token
end

function M.GetPlantMutations(plant)
    local seen, out = {}, {}
    if not plant then return out end

    local fsv = G.FruitSellValue or rawget(_G, "FruitSellValue")
    if type(fsv) == "table" and type(fsv.resolveMutation) == "function" then
        local ok, raw = pcall(fsv.resolveMutation, plant)
        if ok and type(raw) == "string" then
            for token in string.gmatch(raw, "[^%+%,]+") do
                _addMutationToken(seen, out, token)
            end
        end
    end

    local raw = plant:GetAttribute("Mutation")
    if type(raw) == "string" then
        for token in string.gmatch(raw, "[^%+%,]+") do
            _addMutationToken(seen, out, token)
        end
    end

    for _, name in ipairs(_mutationNamesFallback()) do
        if plant:GetAttribute(name) == true then
            _addMutationToken(seen, out, name)
        end
    end

    table.sort(out, function(a, b) return tostring(a) < tostring(b) end)
    return out
end
M.getPlantMutations = M.GetPlantMutations

function M.GetPlantMutation(plant)
    local list = M.GetPlantMutations(plant)
    if #list == 0 then return nil end
    if #list == 1 then return list[1] end
    return table.concat(list, "+")
end
M.getPlantMutation = M.GetPlantMutation

function M.GetPlantVariant(plant)
    if not plant then return nil end
    for _, key in ipairs({ "Variant", "FruitVariant", "SeedVariant" }) do
        local v = _normalizePlantToken(plant:GetAttribute(key))
        if v then return v end
    end
    return nil
end
M.getPlantVariant = M.GetPlantVariant

function M.GetPlantTypeKey(plant)
    local name = M.GetPlantDisplayName(plant)
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then name = plant and plant.Name or "Unknown" end

    local muts = M.GetPlantMutations(plant)
    local label = (#muts > 0) and (table.concat(muts, "+") .. " " .. name) or name

    local variant = M.GetPlantVariant(plant)
    if variant then
        label = label .. " (" .. variant .. ")"
    end
    return label
end
M.getPlantTypeKey = M.GetPlantTypeKey

local function _stripVariantSuffix(key)
    key = tostring(key or "")
    local base = key:match("^(.-) %([^)]+%)$")
    return base or key
end

local function _plantMatchesSelection(plant, sel)
    if not plant or type(sel) ~= "table" then return false end
    local typeKey = M.GetPlantTypeKey(plant)
    if sel[typeKey] then return true end

    local baseKey = _stripVariantSuffix(typeKey)
    if baseKey ~= typeKey and sel[baseKey] then return true end

    -- GetGarden PlantName (RF: mesh/attr bisa kosong)
    local seed = plant:GetAttribute("SeedName")
        or plant:GetAttribute("ConfigPathName")
        or plant:GetAttribute("CorePartName")
        or plant:GetAttribute("FruitType")
        or plant:GetAttribute("ItemName")
    if seed ~= nil and sel[tostring(seed)] then return true end

    -- backward compat: save lama pakai instance Name
    if sel[plant.Name] then return true end

    -- UI GetGarden = "Bean"; GetPlantTypeKey = "Gold Bean"
    local typeCanon = tostring(typeKey):lower():gsub("[^%w]+", "")
    for k, on in pairs(sel) do
        if on == true then
            local ck = tostring(k):lower():gsub("[^%w]+", "")
            if ck ~= "" and typeCanon ~= "" then
                if typeCanon == ck then return true end
                if #ck >= 5 and #typeCanon >= #ck and typeCanon:sub(#typeCanon - #ck + 1) == ck then
                    return true
                end
            end
        end
    end
    return false
end

function M.BuildGardenPlantItems()
    local eg = G.EspFruitGarden or rawget(_G, "EspFruitGarden")
    if type(eg) == "table" and type(eg.ListPlantTypeItems) == "function" then
        local ok, items = pcall(eg.ListPlantTypeItems, eg)
        if ok and type(items) == "table" and #items > 0 and items[1].key ~= "_none" then
            return items
        end
    end

    local items = {}
    local folder = _getPlantsFolder()
    if not folder then
        return { { key = "_none", name = "(No plants in garden)" } }
    end

    local groups = {}
    for _, plant in ipairs(folder:GetChildren()) do
        if plant:IsA("Model") then
            local typeKey = M.GetPlantTypeKey(plant)
            local g = groups[typeKey]
            if not g then
                g = { key = typeKey, name = typeKey, count = 0 }
                groups[typeKey] = g
            end
            g.count = g.count + 1
        end
    end

    for _, g in pairs(groups) do
        items[#items + 1] = {
            key = g.key,
            name = string.format("%s x %d", g.name, g.count),
            count = g.count,
        }
    end

    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)

    if #items == 0 then
        items[1] = { key = "_none", name = "(No plants in garden)" }
    end
    return items
end
M.buildGardenPlantItems = M.BuildGardenPlantItems

local function _coerceSelectionMap(a, b)
    -- support: M.GetMatchBreakdown(sel)  OR  M:GetMatchBreakdown(sel) / pcall(fn, M, sel)
    local sel = a
    if a == M or (type(a) == "table" and type(a.GetMatchBreakdown) == "function") then
        sel = b
    end
    if type(sel) ~= "table" or type(sel.GetMatchBreakdown) == "function" or type(sel.Start) == "function" then
        sel = _selectedMap()
    end
    if sel._none then sel._none = nil end
    return sel
end

function M.GetMatchBreakdown(a, b)
    local sel = _coerceSelectionMap(a, b)

    local out = {
        typeMatch = 0,
        heightMatch = 0,
        heightSkipped = 0,
        hasFolder = false,
        heightRule = tostring((G.__GAG2_SHOVEL and G.__GAG2_SHOVEL.heightRule) or G.AUTO_SHOVEL_HEIGHT_RULE or "0"),
        heightThreshold = 0,
        heightMode = "above",
    }
    local thresh, mode = _heightRule()
    out.heightThreshold = thresh
    out.heightMode = mode

    if not next(sel) then
        return out
    end

    local folder = _getPlantsFolder()
    if not folder then
        return out
    end
    out.hasFolder = true

    for _, plant in ipairs(folder:GetChildren()) do
        if plant:IsA("Model") and _plantMatchesSelection(plant, sel) then
            out.typeMatch = out.typeMatch + 1
            if _plantMatchesHeight(plant) then
                out.heightMatch = out.heightMatch + 1
            else
                out.heightSkipped = out.heightSkipped + 1
            end
        end
    end
    return out
end
M.getMatchBreakdown = M.GetMatchBreakdown

function M.CountMatchingSelected(a, b)
    local sel = _coerceSelectionMap(a, b)
    local br = M.GetMatchBreakdown(sel)
    return br.heightMatch or 0
end
M.countMatchingSelected = M.CountMatchingSelected

function M.GetPlantHeight(plant)
    return _getPlantHeight(plant)
end
M.getPlantHeight = M.GetPlantHeight

function M.GetStats()
    _initRemotes()
    local br = {
        typeMatch = 0,
        heightMatch = 0,
        heightSkipped = 0,
        heightRule = "0",
        heightMode = "above",
        heightThreshold = 0,
        hasFolder = false,
    }
    local okBr, brOrErr = pcall(function()
        return M.GetMatchBreakdown(_selectedMap())
    end)
    if okBr and type(brOrErr) == "table" then
        br = brOrErr
    elseif not okBr then
        stats.lastError = "match_breakdown: " .. tostring(brOrErr)
    end

    local hasShovel = false
    pcall(function()
        hasShovel = _getEquippedShovel() ~= nil
    end)

    return {
        enabled = _enabled(),
        running = running == true,
        remoteReady = UseShovel ~= nil,
        hasShovel = hasShovel,
        canRun = _canRun(),
        selectedCount = _selectedCount(),
        typeMatch = br.typeMatch or 0,
        heightMatch = br.heightMatch or 0,
        heightSkipped = br.heightSkipped or 0,
        heightRule = br.heightRule or "0",
        heightMode = br.heightMode or "above",
        heightThreshold = br.heightThreshold or 0,
        hasFolder = br.hasFolder == true,
        stats = {
            attempts = stats.attempts,
            ok = stats.ok,
            lastError = stats.lastError,
            lastPlantId = stats.lastPlantId,
            lastSkip = stats.lastSkip,
        },
    }
end
M.getStats = M.GetStats

function M.BuildShovelDropdownItems()
    local items = {}
    local seen = {}

    for _, it in ipairs(M.BuildGardenPlantItems()) do
        if it and it.key and it.key ~= "_none" then
            seen[it.key] = true
            items[#items + 1] = it
        end
    end

    local sel = _selectedMap()
    for k, v in pairs(sel) do
        if v == true and k ~= "_none" and not seen[k] then
            items[#items + 1] = {
                key = k,
                name = string.format("%s x 0", k),
                count = 0,
            }
            seen[k] = true
        end
    end

    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)

    if #items == 0 then
        items[1] = { key = "_none", name = "(No plants in garden)" }
    end
    return items
end
M.buildShovelDropdownItems = M.BuildShovelDropdownItems
M.BuildCatalogPlantItems = M.BuildShovelDropdownItems
M.buildCatalogPlantItems = M.BuildShovelDropdownItems

function M.GetActiveTypeKeys()
    local out = {}
    for _, item in ipairs(M.BuildGardenPlantItems()) do
        local k = item and item.key
        if k and k ~= "" and k ~= "_none" then
            out[tostring(k)] = true
        end
    end
    return out
end
M.getActiveTypeKeys = M.GetActiveTypeKeys

-- Legacy: selection pakai katalog lengkap, tidak dipangkas saat plant hilang dari garden.
function M.PruneSelectionToGarden(sel)
    sel = type(sel) == "table" and sel or _selectedMap()
    local out = {}
    for k, v in pairs(sel) do
        if v == true and k ~= "_none" then
            out[k] = true
        end
    end
    return out, false, {}
end
M.pruneSelectionToGarden = M.PruneSelectionToGarden

local function _notifyPlantsChanged()
    local fn = G.__GAG2_ON_SHOVEL_PLANTS_CHANGED or rawget(_G, "__GAG2_ON_SHOVEL_PLANTS_CHANGED")
    if type(fn) == "function" then
        pcall(fn)
    end
end

local _tick -- forward decl (dipakai ChildAdded)

local function _unbindPlantsWatch()
    if plantsConn then plantsConn:Disconnect() plantsConn = nil end
    if plotConn then plotConn:Disconnect() plotConn = nil end
end

local function _bindPlantsWatch(folder)
    _unbindPlantsWatch()
    if not folder then return end
    plantsConn = folder.ChildAdded:Connect(function(ch)
        task.defer(_notifyPlantsChanged)
        -- plant baru: tunggu SeedName lalu coba shovel segera
        if running and ch and ch:IsA("Model") then
            task.spawn(function()
                for _ = 1, 30 do
                    if not running or not ch.Parent then return end
                    if ch:GetAttribute("SeedName") then break end
                    task.wait(0.1)
                end
                if running and _canRun() and type(_tick) == "function" then
                    task.wait(0.2)
                    pcall(_tick)
                end
            end)
        end
    end)
    folder.ChildRemoved:Connect(function()
        task.defer(_notifyPlantsChanged)
    end)
    local plot = folder.Parent
    if plot then
        plotConn = plot.ChildAdded:Connect(function(ch)
            if ch.Name == "Plants" then
                _bindPlantsWatch(ch)
                _notifyPlantsChanged()
            end
        end)
    end
end

local function _getEquippedShovel()
    local char = LP and LP.Character
    if not char then return nil end
    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") and ch:GetAttribute("Shovel") then
            return ch
        end
    end
    return nil
end

local function _equipShovel()
    if _getEquippedShovel() then return true end
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local bp = LP and LP:FindFirstChild("Backpack")
    if not hum or not bp then return false end
    for _, tool in ipairs(bp:GetChildren()) do
        if tool:IsA("Tool") and tool:GetAttribute("Shovel") then
            local ok = pcall(function() hum:EquipTool(tool) end)
            if ok and _getEquippedShovel() then return true end
        end
    end
    return false
end

local function _shovelPlantInst(plant)
    _initRemotes()
    if not UseShovel or not plant or not plant.Parent then return false, "no_plant" end

    if os.clock() - lastShovelAt < SHOVEL_CD then
        return false, "cooldown"
    end

    if not _equipShovel() then
        stats.lastError = "shovel_not_equipped"
        return false, "no_tool"
    end

    local tool = _getEquippedShovel()
    if not tool then return false, "no_tool" end

    local shovelType = tool:GetAttribute("Shovel")
    if shovelType == nil then return false, "no_shovel_attr" end

    local plantId = plant.Name
    local ok, err = pcall(function()
        UseShovel:Fire(plantId, "", shovelType, tool)
    end)
    lastShovelAt = os.clock()
    stats.attempts = stats.attempts + 1
    stats.lastPlantId = plantId

    if ok then
        stats.ok = stats.ok + 1
        _log("UseShovel", plantId, M.GetPlantTypeKey(plant))
        return true, plantId
    end

    stats.lastError = tostring(err)
    return false, "fire_fail"
end

_tick = function()
    if not _canRun() then return end
    if shovelBusy then return end

    local folder = _getPlantsFolder()
    if not folder then return end

    local sel = _selectedMap()
    shovelBusy = true
    pcall(function()
        for _, plant in ipairs(folder:GetChildren()) do
            if _plantMatchesSelection(plant, sel) and _plantMatchesHeight(plant) then
                local ok = _shovelPlantInst(plant)
                if ok then break end
                task.wait(0.05)
            end
        end
    end)
    shovelBusy = false
end

local function shovelLoop(myId)
    _initRemotes()
    _bindPlantsWatch(_getPlantsFolder())
    _log("loop start")

    while running and loopId == myId do
        local ok, err = pcall(_tick)
        if not ok then
            stats.lastError = tostring(err)
            warn("[GAG2-AS] loop error:", err)
        end
        if _canRun() then
            RunService.Heartbeat:Wait()
            task.wait(LOOP_SEC)
        elseif _enabled() then
            task.wait(0.5)
        else
            task.wait(0.5)
        end
    end
    _unbindPlantsWatch()
    _log("loop stop")
end

function M.Start()
    _initRemotes()
    if running then return end
    running = true
    loopId = loopId + 1
    local myId = loopId
    task.spawn(function() shovelLoop(myId) end)
end
M.start = M.Start

function M.Stop()
    running = false
    _unbindPlantsWatch()
end
M.stop = M.Stop

function M.IsRunning()
    return running == true
end

function M.SetEnabled(on)
    on = (on == true)
    if type(G.__GAG2_SHOVEL) ~= "table" then G.__GAG2_SHOVEL = {} end
    G.__GAG2_SHOVEL.enabled = on
    _G.__GAG2_SHOVEL = G.__GAG2_SHOVEL
    G.AUTO_SHOVEL_ENABLED = on
    _G.AUTO_SHOVEL_ENABLED = on
    if on then
        M.ApplyRuntime(true)
    else
        M.Stop()
    end
    return on
end
M.setEnabled = M.SetEnabled

function M.ApplyRuntime(on)
    if on == true and not M.HasSelection() then
        M.Stop()
        stats.lastSkip = "no_selection"
        return false
    end
    if on then M.Start() else M.Stop() end
    return on == true
end
M.applyRuntime = M.ApplyRuntime

function M.SyncFromGlobals()
    M.SetEnabled(_enabled())
end
M.syncFromGlobals = M.SyncFromGlobals
M.SyncFromState = M.SyncFromGlobals
M.syncFromState = M.SyncFromGlobals

function M.ShovelOnce()
    if not _canRun() then return 0 end
    local n = 0
    local sel = _selectedMap()
    local folder = _getPlantsFolder()
    if not folder then return 0 end
    for _, plant in ipairs(folder:GetChildren()) do
        if _plantMatchesSelection(plant, sel) and _plantMatchesHeight(plant) then
            local ok = _shovelPlantInst(plant)
            if ok then n = n + 1 break end
        end
    end
    return n
end
M.shovelOnce = M.ShovelOnce

function M.GetDiagnostics()
    _initRemotes()
    local folder = _getPlantsFolder()
    local active = M.BuildGardenPlantItems()
    local sel = _selectedMap()
    local selCount = 0
    for _ in pairs(sel) do selCount = selCount + 1 end
    local hThresh, hMode = _heightRule()
    return {
        enabled = _enabled(),
        running = running,
        remote = UseShovel ~= nil,
        plantsFolder = folder and folder:GetFullName() or nil,
        plantCount = #active,
        selectedCount = selCount,
        hasSelection = selCount >= 1,
        canRun = _canRun(),
        hasShovel = _getEquippedShovel() ~= nil,
        heightThreshold = hThresh,
        heightMode = hMode,
        matchingCount = M.CountMatchingSelected(sel),
        stats = stats,
    }
end
M.getDiagnostics = M.GetDiagnostics

function M.PrintDiagnostics()
    if _enabled() and not running then M.Start() end
    local d = M.GetDiagnostics()
    print("========== GAG2 Auto Shovel ==========")
    print("enabled:", d.enabled, "| running:", d.running)
    print("remote UseShovel:", d.remote and "OK" or "MISSING")
    print("types:", d.plantCount, "| selected:", d.selectedCount, "| canRun:", d.canRun)
    print("height:", d.heightMode, d.heightThreshold, "| matching:", d.matchingCount)
    print("folder:", d.plantsFolder or "MISSING (PlotId?)")
    print("shovel equipped:", d.hasShovel)
    print("stats ok=", stats.ok, " attempts=", stats.attempts)
    if stats.lastError then print("lastError:", stats.lastError) end
    local sel = _selectedMap()
    for _, item in ipairs(M.BuildShovelDropdownItems()) do
        local mark = sel[item.key] and "[x]" or "[ ]"
        print(" ", mark, item.name)
    end
    print("======================================")
    return d
end
M.printDiagnostics = M.PrintDiagnostics

G.AutoShovel = M
G.AutoShovelModule = M
_G.AutoShovel = M
_G.AutoShovelModule = M

return M
 end,                     required = false },
    { key = "AutoShovelFruit",         name = "Auto Shovel Fruit",       factory = function() -- AutoShovelFruit.lua — shovel fruit di garden by filter rules (UseShovel remote)

