local function _dbg()
    return G.AUTO_SHOVEL_FRUIT_DEBUG == true or _G.AUTO_SHOVEL_FRUIT_DEBUG == true
end

local function _log(...)
    if not _dbg() then return end
    print("[GAG2-ASF]", ...)
end

local function _logThrottled(key, interval, ...)
    if not _dbg() then return end
    interval = tonumber(interval) or PROC_LOG_INTERVAL
    local now = os.clock()
    G.__GAG2_ASF_LOG_AT = type(G.__GAG2_ASF_LOG_AT) == "table" and G.__GAG2_ASF_LOG_AT or {}
    local at = G.__GAG2_ASF_LOG_AT
    local last = tonumber(at[key]) or 0
    if (now - last) < interval then return end
    at[key] = now
    _G.__GAG2_ASF_LOG_AT = at
    print("[GAG2-ASF]", ...)
end

local function _collectMod()
    return G.AutoCollectFruit or G.AutoCollect or G.CollectFruitModule
        or rawget(_G, "AutoCollectFruit") or rawget(_G, "AutoCollect")
end

local function _initRemotes()
    if remotesReady then return end
    remotesReady = true
    local ok, Networking = pcall(function()
        return require(ReplicatedStorage.SharedModules.Networking)
    end)
    if not ok or type(Networking) ~= "table" then
        stats.lastError = "Networking require gagal"
        return
    end
    local ShovelNet = Networking.Shovel
    if type(ShovelNet) == "table" and type(ShovelNet.UseShovel) == "table"
        and type(ShovelNet.UseShovel.Fire) == "function" then
        UseShovel = ShovelNet.UseShovel
    end
    if not UseShovel then
        stats.lastError = "UseShovel MISSING"
        warn("[GAG2-ASF] UseShovel remote tidak ditemukan")
    end
end

local function _readEnabled()
    if G.AUTO_SHOVEL_FRUIT_ENABLED == true or rawget(_G, "AUTO_SHOVEL_FRUIT_ENABLED") == true then
        return true
    end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.shovelFruit
    return type(st) == "table" and st.enabled == true
end

local function _liveDelay()
    local d = G.AUTO_SHOVEL_FRUIT_DELAY or rawget(_G, "AUTO_SHOVEL_FRUIT_DELAY")
    if d == nil then
        local MAIN = rawget(_G, "MAIN") or G.MAIN
        local st = MAIN and MAIN.auto and MAIN.auto.shovelFruit
        d = st and st.delay
    end
    d = tonumber(d) or 0.72
    if d < 0 then d = 0 end
    if d > 5 then d = 5 end
    return d
end

local function _loadRules()
    local rawRules = G.AUTO_SHOVEL_FRUIT_RULES or rawget(_G, "AUTO_SHOVEL_FRUIT_RULES")
    local order = G.AUTO_SHOVEL_FRUIT_RULES_ORDER or rawget(_G, "AUTO_SHOVEL_FRUIT_RULES_ORDER")
    if rawRules == nil or order == nil then
        local MAIN = rawget(_G, "MAIN") or G.MAIN
        local st = MAIN and MAIN.auto and MAIN.auto.shovelFruit
        if type(st) == "table" then
            rawRules = rawRules or st.rules
            order = order or st.rulesOrder
        end
    end
    local ac = _collectMod()
    if type(ac) == "table" and type(ac.NormalizeRulesList) == "function" then
        local ok, rules = pcall(ac.NormalizeRulesList, rawRules, order)
        if ok and type(rules) == "table" then return rules end
    end
    return type(rawRules) == "table" and rawRules or {}
end

local function getState()
    return {
        enabled = _readEnabled(),
        delay = _liveDelay(),
        filterMode = "rules",
        rules = _loadRules(),
    }
end

local function getStateCached()
    local now = os.clock()
    if cachedState and (now - cachedStateAt) <= STATE_CACHE then
        cachedState.enabled = _readEnabled()
        cachedState.delay = _liveDelay()
        return cachedState
    end
    cachedState = getState()
    cachedStateAt = now
    return cachedState
end

local function _trimMetricCache()
    local n = 0
    for _ in pairs(metricCache) do
        n += 1
        if n > MAX_METRIC_CACHE then
            metricCache = {}
            filterMatchCache = {}
            return
        end
    end
end

local function _invalidateGardenList()
    gardenListCache = nil
    gardenListCacheAt = 0
    scanCursor = 0
end

local function _invalidateTargetQueue()
    targetQueue = {}
    targetQueueAt = 0
    scanCursor = 0
end

local function _invalidateCountCache()
    _readyCacheAt = 0
    _filteredCacheAt = 0
end

local function _adjustBreakdownAfterShovel()
    if _readyCache > 0 then _readyCache -= 1 end
    if _filteredCache > 0 then _filteredCache -= 1 end
end

local function _invalidateCache(clearMetrics)
    cachedState = nil
    cachedStateAt = 0
    _invalidateCountCache()
    _invalidateTargetQueue()
    if clearMetrics ~= false then
        metricCache = {}
        filterMatchCache = {}
    end
end

local function _rulesNeedPrice(rules)
    if type(rules) ~= "table" then return false end
    for _, rule in ipairs(rules) do
        if type(rule) == "table" and rule.enabled ~= false and rule.anyPrice then
            if (tonumber(rule.minPrice) or 0) > 0 then return true end
        end
    end
    return false
end

local function _getPlot()
    local plotId = LP and LP:GetAttribute("PlotId")
    if not plotId then return nil end
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then return nil end
    return gardens:FindFirstChild("Plot" .. tostring(plotId))
end

local function _getPlantsFolder()
    local plot = _getPlot()
    return plot and plot:FindFirstChild("Plants") or nil
end

local function _fsv()
    return G.FruitSellValue or rawget(_G, "FruitSellValue")
end

local function _canon(s)
    return tostring(s or ""):lower():gsub("[^%w]+", "")
end

local function _setHasAny(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true then return true end
    end
    return false
end

local function _gardenFruitName(fruit)
    local ac = _collectMod()
    if type(ac) == "table" and type(ac.GetFruitName) == "function" then
        local ok, n = pcall(ac.GetFruitName, fruit)
        if ok and type(n) == "string" and n ~= "" then return n end
    end
    local fsv = _fsv()
    if type(fsv) == "table" and type(fsv.resolveSeedName) == "function" then
        local ok, n = pcall(fsv.resolveSeedName, fruit)
        if ok and type(n) == "string" and n ~= "" then return n end
    end
    return fruit.Name
end

local function _gardenFruitWeight(fruit)
    local fsv = _fsv()
    if type(fsv) == "table" and type(fsv.resolveWeight) == "function" then
        local ok, w = pcall(fsv.resolveWeight, fruit)
        if ok then
            w = tonumber(w) or 0
            if w > 0 then return w end
        end
    end
    return 0
end

local function _gardenFruitPrice(fruit)
    local fsv = _fsv()
    if type(fsv) ~= "table" then return 0 end
    if type(fsv.fromFruit) == "function" then
        local ok, price = pcall(fsv.fromFruit, fruit)
        price = ok and (tonumber(price) or 0) or 0
        if price > 0 then return price end
    end
    if type(fsv.calculate) == "function" then
        local name = _gardenFruitName(fruit)
        local weight = _gardenFruitWeight(fruit)
        if name ~= "" and weight > 0 then
            local mut = nil
            if type(fsv.resolveMutation) == "function" then
                pcall(function() mut = fsv.resolveMutation(fruit) end)
            end
            local ok, price = pcall(
                fsv.calculate,
                name,
                weight,
                mut,
                nil,
                fruit:GetAttribute("DecayAlpha")
            )
            if ok then
                price = tonumber(price) or 0
                if price > 0 then return price end
            end
        end
    end
    return 0
end

local function _metricKey(fruit)
    return fruit and fruit:GetFullName() or ""
end

local function _dropFruitCache(fruit)
    if not fruit then return end
    local key = _metricKey(fruit)
    metricCache[key] = nil
    filterMatchCache[key] = nil
end

local function _getMetrics(fruit, wantPrice)
    wantPrice = (wantPrice == true)
    local key = _metricKey(fruit)
    if key == "" then return "", 0, 0 end
    local now = os.clock()
    local c = metricCache[key]
    if c and (now - c.at) <= METRIC_CACHE_SEC then
        if wantPrice and not c.priceComputed then
            c.price = _gardenFruitPrice(fruit)
            c.priceComputed = true
        end
        return c.name, c.kg, wantPrice and (c.price or 0) or 0
    end
    local name = _gardenFruitName(fruit)
    local kg = _gardenFruitWeight(fruit)
    local price = 0
    local priceComputed = false
    if wantPrice then
        price = _gardenFruitPrice(fruit)
        priceComputed = true
    end
    metricCache[key] = {
        name = name,
        kg = kg,
        price = price,
        priceComputed = priceComputed,
        at = now,
    }
    _trimMetricCache()
    return name, kg, price
end

local function _fruitKey(plantId, fruitId)
    return tostring(plantId or "") .. "|" .. tostring(fruitId or "")
end

local function _markRecentShovel(plantId, fruitId)
    recentShoveled[_fruitKey(plantId, fruitId)] = os.clock()
end

local function _isRecentShovel(plantId, fruitId)
    local key = _fruitKey(plantId, fruitId)
    local t = recentShoveled[key]
    if not t then return false end
    if os.clock() - t > RECENT_SHOVEL_SEC then
        recentShoveled[key] = nil
        return false
    end
    return true
end

local function _matchSet(selectedMap, value)
    if not _setHasAny(selectedMap) then return true end
    local needle = _canon(value)
    for k, v in pairs(selectedMap) do
        if v == true and _canon(k) == needle then return true end
    end
    return false
end

local function _matchKg(weight, kg, mode)
    kg = tonumber(kg) or 0
    mode = tostring(mode or "above")
    if kg < 0 then
        kg = math.abs(kg)
        mode = "below"
    end
    if mode ~= "below" then mode = "above" end
    weight = tonumber(weight) or 0
    if kg <= 0 then return true end
    if mode == "below" then return weight > 0 and weight <= kg end
    return weight >= kg
end

local function _matchPrice(price, filterPrice, mode)
    filterPrice = tonumber(filterPrice) or 0
    if filterPrice <= 0 then return true end
    price = tonumber(price) or 0
    mode = tostring(mode or "above")
    if mode == "below" then return price > 0 and price <= filterPrice end
    return price >= filterPrice
end

local function _parseMutList(inst)
    local raw = inst and inst:GetAttribute("Mutation")
    if type(raw) ~= "string" or raw == "" then return {} end
    local out = {}
    for token in string.gmatch(raw, "[^%+%,]+") do
        token = tostring(token):match("^%s*(.-)%s*$")
        if token and token ~= "" then out[#out + 1] = token end
    end
    return out
end

local function _fruitHasMutation(inst)
    if #_parseMutList(inst) > 0 then return true end
    local fsv = _fsv()
    if type(fsv) == "table" and type(fsv.resolveMutation) == "function" then
        local ok, raw = pcall(fsv.resolveMutation, inst)
        return ok and type(raw) == "string" and raw ~= ""
    end
    return false
end

local function _matchMutation(selectedMap, inst)
    if not _setHasAny(selectedMap) then return true end
    if not inst then return false end
    for mutName, on in pairs(selectedMap) do
        if on == true and inst:GetAttribute(mutName) == true then return true end
    end
    for _, mutName in ipairs(_parseMutList(inst)) do
        if _matchSet(selectedMap, mutName) then return true end
    end
    local fsv = _fsv()
    if type(fsv) == "table" and type(fsv.resolveMutation) == "function" then
        local ok, raw = pcall(fsv.resolveMutation, inst)
        if ok and type(raw) == "string" and raw ~= "" then
            for token in string.gmatch(raw, "[^%+%,]+") do
                if _matchSet(selectedMap, token) then return true end
            end
        end
    end
    return false
end

local function _gardenMatchesRule(fruit, rule, wantPrice)
    if type(rule) ~= "table" or rule.enabled == false then return false end
    local name, kg = _getMetrics(fruit, false)
    if rule.anyFruit and not _matchSet(rule.fruits, name) then return false end
    if (tonumber(rule.kg) or 0) > 0 and not _matchKg(kg, rule.kg, rule.kgMode) then
        return false
    end
    if rule.requireMut == true then
        if rule.anyMut then
            if not _matchMutation(rule.mutations, fruit) then return false end
        elseif not _fruitHasMutation(fruit) then
            return false
        end
    elseif rule.anyMut and not _matchMutation(rule.mutations, fruit) then
        return false
    end
    if rule.anyPrice then
        local _, _, price = _getMetrics(fruit, wantPrice ~= false)
        if not _matchPrice(price, rule.minPrice, rule.minPriceMode) then
            return false
        end
    end
    return true
end

local function _matchesFilter(fruit, st, wantPrice)
    if not fruit or not fruit.Parent then return false end
    local rules = st and st.rules
    if type(rules) ~= "table" or #rules == 0 then return true end
    wantPrice = (wantPrice == true) or _rulesNeedPrice(rules)
    for _, rule in ipairs(rules) do
        if _gardenMatchesRule(fruit, rule, wantPrice) then return true end
    end
    return false
end

local function _matchesFilterCached(fruit, st, needPrice)
    if not fruit or not fruit.Parent then return false end
    local key = _metricKey(fruit)
    if key == "" then return false end
    local now = os.clock()
    local c = filterMatchCache[key]
    if c and (now - c.at) <= FILTER_MATCH_SEC then
        return c.match == true
    end
    local matched = _matchesFilter(fruit, st, needPrice) == true
    filterMatchCache[key] = { match = matched, at = now }
    return matched
end

local function _whyRuleFails(fruit, rule)
    if type(rule) ~= "table" or rule.enabled == false then return "rule disabled" end
    local name, kg = _getMetrics(fruit, false)
    if rule.anyFruit and not _matchSet(rule.fruits, name) then
        return "fruit mismatch (" .. tostring(name) .. ")"
    end
    local ruleKg = tonumber(rule.kg) or 0
    if ruleKg > 0 and not _matchKg(kg, rule.kg, rule.kgMode) then
        if kg <= 0 then return "kg unreadable (0)" end
        if tostring(rule.kgMode or "") == "below" then
            return string.format("kg too high (%.2f > %.2f)", kg, ruleKg)
        end
        return string.format("kg too low (%.2f < %.2f)", kg, ruleKg)
    end
    if rule.requireMut == true then
        if rule.anyMut and not _matchMutation(rule.mutations, fruit) then
            return "mutation mismatch (require)"
        end
        if not rule.anyMut and not _fruitHasMutation(fruit) then
            return "no mutation (require)"
        end
    elseif rule.anyMut and not _matchMutation(rule.mutations, fruit) then
        return "mutation mismatch"
    end
    local rulePrice = tonumber(rule.minPrice) or 0
    if rule.anyPrice and rulePrice > 0 then
        local _, _, price = _getMetrics(fruit, true)
        if not _matchPrice(price, rule.minPrice, rule.minPriceMode) then
            if price <= 0 then return "price unreadable (0)" end
            if tostring(rule.minPriceMode or "") == "below" then
                return string.format("price too high (%s > %s)", tostring(price), tostring(rulePrice))
            end
            return string.format("price too low (%s < %s)", tostring(price), tostring(rulePrice))
        end
    end
    return nil
end

local function _whyFilterFails(fruit, st)
    st = st or getStateCached()
    local rules = st and st.rules
    if type(rules) ~= "table" or #rules == 0 then return nil end
    local reasons = {}
    for i, rule in ipairs(rules) do
        local why = _whyRuleFails(fruit, rule)
        if not why then return nil end
        reasons[#reasons + 1] = "r" .. tostring(i) .. ":" .. why
    end
    return table.concat(reasons, " | ")
end

local function _fruitFilterDetail(fruit, st)
    st = st or getStateCached()
    local name, kg, price = _getMetrics(fruit)
    local matched = _matchesFilter(fruit, st)
    return {
        name = name,
        kg = kg,
        price = price,
        match = matched == true,
        reason = matched and nil or _whyFilterFails(fruit, st),
    }
end

local function _iterGardenFruits()
    local out = {}
    local folder = _getPlantsFolder()
    if not folder then return out end
    for _, plant in ipairs(folder:GetChildren()) do
        local fruits = plant:FindFirstChild("Fruits")
        if fruits then
            local plantId = plant.Name
            for _, fruit in ipairs(fruits:GetChildren()) do
                if fruit:IsA("Model") or fruit:IsA("BasePart") then
                    out[#out + 1] = {
                        plantId = plantId,
                        fruitId = fruit.Name,
                        model = fruit,
                    }
                end
            end
        end
    end
    return out
end

local function _getGardenFruitsCached(force)
    local now = os.clock()
    if not force and gardenListCache and (now - gardenListCacheAt) <= GARDEN_LIST_SEC then
        return gardenListCache
    end
    gardenListCache = _iterGardenFruits()
    gardenListCacheAt = now
    return gardenListCache
end

local function _extendTargetQueue(st)
    st = st or getStateCached()
    local list = _getGardenFruitsCached(false)
    if #list == 0 then return 0 end
    if #targetQueue >= QUEUE_MAX then return 0 end

    local needPrice = _rulesNeedPrice(st.rules)
    local added = 0
    local checked = 0
    while checked < SCAN_CHUNK and #targetQueue < QUEUE_MAX do
        scanCursor += 1
        if scanCursor > #list then scanCursor = 1 end
        checked += 1
        local item = list[scanCursor]
        local fruit = item.model
        if fruit and fruit.Parent and not _isRecentShovel(item.plantId, item.fruitId) then
            if _matchesFilterCached(fruit, st, needPrice) then
                targetQueue[#targetQueue + 1] = item
                added += 1
            end
        end
    end
    if added > 0 then
        targetQueueAt = os.clock()
    end
    return added
end

local function _popNextTarget(st)
    st = st or getStateCached()
    if #targetQueue < QUEUE_MIN then
        _extendTargetQueue(st)
    end
    while #targetQueue > 0 do
        local item = table.remove(targetQueue, 1)
        local fruit = item.model
        if fruit and fruit.Parent and not _isRecentShovel(item.plantId, item.fruitId) then
            return item.plantId, item.fruitId, fruit, true
        end
    end
    if _extendTargetQueue(st) > 0 then
        return _popNextTarget(st)
    end
    return nil, nil, nil, false
end

local function _scanBreakdown(st, applyFilter)
    st = st or getStateCached()
    local ready = 0
    local filtered = 0
    local needPrice = applyFilter and _rulesNeedPrice(st.rules)
    for _, item in ipairs(_getGardenFruitsCached(false)) do
        local fruit = item.model
        if not fruit or not fruit.Parent then continue end
        ready += 1
        if applyFilter and _matchesFilterCached(fruit, st, needPrice) then
            filtered += 1
        end
    end
    return ready, filtered
end

local function _requestBreakdownScan(force)
    breakdownScanGen += 1
    local myGen = breakdownScanGen
    breakdownScanBusy = true
    task.spawn(function()
        local ok, err = pcall(function()
            local st = getStateCached()
            local needPrice = _rulesNeedPrice(st.rules)
            local list = _getGardenFruitsCached(force == true)
            local ready = 0
            local filtered = 0
            local step = 0
            for _, item in ipairs(list) do
                if breakdownScanGen ~= myGen then return end
                local fruit = item.model
                if fruit and fruit.Parent then
                    ready += 1
                    if _matchesFilterCached(fruit, st, needPrice) then
                        filtered += 1
                    end
                end
                step += 1
                if step % BREAKDOWN_SCAN_CHUNK == 0 then
                    _readyCache = ready
                    _filteredCache = filtered
                    _readyCacheAt = os.clock()
                    _filteredCacheAt = _readyCacheAt
                    task.wait(0)
                end
            end
            if breakdownScanGen ~= myGen then return end
            _readyCache = ready
            _filteredCache = filtered
            local now = os.clock()
            _readyCacheAt = now
            _filteredCacheAt = now
        end)
        breakdownScanBusy = false
        if not ok then
            stats.lastError = tostring(err)
            warn("[GAG2-ASF] breakdown scan:", err)
        end
    end)
end

local function _getEquippedShovel()
    local char = LP and LP.Character
    if not char then return nil end
    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") and ch:GetAttribute("Shovel") then
            return ch
        end
    end
    return nil
end

local function _equipShovel()
    if _getEquippedShovel() then return true end
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local bp = LP and LP:FindFirstChild("Backpack")
    if not hum or not bp then
        _log("equip fail: no character/humanoid/backpack")
        return false
    end
    for _, tool in ipairs(bp:GetChildren()) do
        if tool:IsA("Tool") and tool:GetAttribute("Shovel") then
            local ok = pcall(function() hum:EquipTool(tool) end)
            if ok and _getEquippedShovel() then
                if not _equipLogged then
                    _equipLogged = true
                    _log("equip shovel:", tool.Name)
                end
                return true
            end
        end
    end
    _log("equip fail: shovel not found in backpack")
    return false
end

local function _unequipShovel(tool)
    local char = LP and LP.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end

    local equipped = tool
    if not (equipped and equipped:IsA("Tool") and equipped.Parent == char) then
        equipped = _getEquippedShovel()
    end

    if equipped and equipped:IsA("Tool") and equipped.Parent == char
        and equipped:GetAttribute("Shovel") ~= nil then
        pcall(function() hum:UnequipTools() end)
        _log("unequip shovel (filter kosong / no target)")
    end
end

local function _shovelFruit(plantId, fruitId, fruitModel)
    _initRemotes()
    if not UseShovel then
        _log("shovel skip: no remote")
        return false, "no_remote"
    end
    if not _equipShovel() then
        stats.lastError = "shovel_not_equipped"
        return false, "no_tool"
    end
    local tool = _getEquippedShovel()
    if not tool then return false, "no_tool" end
    local shovelType = tool:GetAttribute("Shovel")
    if shovelType == nil then return false, "no_shovel_attr" end

    plantId = tostring(plantId or "")
    fruitId = tostring(fruitId or "")
    if plantId == "" or fruitId == "" then return false, "bad_ids" end

    if _dbg() then
        local name, kg, price = _getMetrics(fruitModel)
        _log(string.format(
            "UseShovel fire plant=%s fruit=%s name=%s kg=%.2f price=%s",
            plantId, fruitId, name, kg or 0, tostring(price or 0)
        ))
    end

    local ok, err = pcall(function()
        UseShovel:Fire(plantId, fruitId, shovelType, tool)
    end)
    stats.attempts += 1
    stats.lastPlantId = plantId
    stats.lastFruitId = fruitId

    if ok then
        lastShovelAt = os.clock()
        stats.ok += 1
        _markRecentShovel(plantId, fruitId)
        _dropFruitCache(fruitModel)
        _adjustBreakdownAfterShovel()
        return true, plantId
    end
    stats.lastError = tostring(err)
    _log("UseShovel FAIL:", tostring(err))
    return false, "fire_fail"
end

local function _findNextTarget(st)
    return _popNextTarget(st)
end

local function _tick()
    if not _readEnabled() then return false, false end
    if shovelBusy then return false, false end
    shovelBusy = true
    local fired = false
    local hadTarget = false
    pcall(function()
        local st = getStateCached()
        local plantId, fruitId, fruitModel, found = _findNextTarget(st)
        hadTarget = found == true
        if not plantId then
            _logThrottled("idle", PROC_LOG_INTERVAL, "idle: no shovel target")
            _unequipShovel()
            return
        end
        local ok, err = _shovelFruit(plantId, fruitId, fruitModel)
        if ok then
            fired = true
        else
            _log("shovel result:", tostring(err))
        end
    end)
    shovelBusy = false
    return fired, hadTarget
end

local function shovelLoop(myId)
    loopAliveId = myId
    _initRemotes()
    _log("loop start", myId)
    task.spawn(function()
        for _ = 1, 4 do
            if not running or loopId ~= myId then break end
            pcall(_extendTargetQueue, getStateCached())
            task.wait(0)
        end
    end)
    _requestBreakdownScan(true)
    while running and loopId == myId do
        local fired = false
        local hadTarget = false
        local ok, err = pcall(function()
            fired, hadTarget = _tick()
        end)
        if not ok then
            stats.lastError = tostring(err)
            warn("[GAG2-ASF] loop error:", err)
            task.wait(0.25)
        elseif not _readEnabled() then
            task.wait(0.5)
        elseif fired then
            task.wait(math.max(_liveDelay(), MIN_LOOP_WAIT))
        elseif hadTarget then
            task.wait(MIN_LOOP_WAIT)
        else
            task.wait(IDLE_SCAN_WAIT)
        end
    end
    if loopAliveId == myId then loopAliveId = 0 end
    _log("loop stop", myId)
end

function M.SetEnabled(a, b)
    local on = (type(a) == "table" and b == true) or (a == true)
    G.AUTO_SHOVEL_FRUIT_ENABLED = on
    _G.AUTO_SHOVEL_FRUIT_ENABLED = on
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.auto = MAIN.auto or {}
        MAIN.auto.shovelFruit = MAIN.auto.shovelFruit or {}
        MAIN.auto.shovelFruit.enabled = on
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end
    _invalidateCache()
    if on then
        running = true
        if loopAliveId > 0 and loopAliveId == loopId then return end
        loopId += 1
        local myId = loopId
        task.spawn(function()
            shovelLoop(myId)
        end)
    else
        running = false
        loopId += 1
        _unequipShovel()
    end
end
