function M.SyncFromState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.shovelFruit
    if type(st) == "table" then
        M.SetRules(st.rules, st.rulesOrder)
        M.SetDelay(st.delay)
    end
    M.SetFilterMode("rules")
    if _readEnabled() then
        M.EnsureRunning()
    else
        M.SetEnabled(false)
    end
end
M.syncFromState = M.SyncFromState
M.SyncFromGlobals = M.SyncFromState
M.syncFromGlobals = M.SyncFromState

function M.PeekHarvestBreakdown()
    local now = os.clock()
    if _readyCacheAt <= 0 or (now - _readyCacheAt) > COUNT_CACHE then
        _requestBreakdownScan(false)
    end
    return {
        inFilter = math.max(0, math.floor(_filteredCache or 0)),
        outFilter = math.max(0, math.floor((_readyCache or 0) - (_filteredCache or 0))),
        scanning = breakdownScanBusy == true,
    }
end
M.peekHarvestBreakdown = M.PeekHarvestBreakdown

function M.PeekFilteredCount()
    return M.PeekHarvestBreakdown().inFilter or 0
end
M.peekFilteredCount = M.PeekFilteredCount

function M.GetStats()
    return {
        enabled = _readEnabled(),
        running = M.IsRunning(),
        debug = _dbg(),
        remoteReady = UseShovel ~= nil,
        loopAlive = loopAliveId > 0,
        stats = stats,
        delay = _liveDelay(),
        ruleCount = #(getStateCached().rules or {}),
    }
end
M.getStats = M.GetStats

function M.SetDebug(on)
    on = (on == true)
    G.AUTO_SHOVEL_FRUIT_DEBUG = on
    _G.AUTO_SHOVEL_FRUIT_DEBUG = on
