M.isDebug = M.IsDebug

function M.DebugFilterScan(opts)
    opts = type(opts) == "table" and opts or {}
    local maxShow = math.floor(tonumber(opts.maxShow) or 20)
    if maxShow < 1 then maxShow = 20 end
    local doPrint = (opts.print ~= false)
    local verbose = (opts.verbose == true) or _dbg()
    _invalidateCache()
    local st = getStateCached()
    local out = {
        ruleCount = #(st.rules or {}),
        readyTotal = 0,
        inFilter = 0,
        outFilter = 0,
        inSamples = {},
        outSamples = {},
    }
    for _, item in ipairs(_getGardenFruitsCached(true)) do
        local fruit = item.model
        if not fruit or not fruit.Parent then continue end
        out.readyTotal += 1
        local detail = _fruitFilterDetail(fruit, st)
        local row = {
            name = detail.name,
            plantId = item.plantId,
            fruitId = item.fruitId,
            kg = detail.kg,
            price = detail.price,
            reason = detail.reason,
        }
        if detail.match then
            out.inFilter += 1
            if #out.inSamples < maxShow then
                out.inSamples[#out.inSamples + 1] = row
            end
        else
            out.outFilter += 1
            if #out.outSamples < maxShow then
                out.outSamples[#out.outSamples + 1] = row
            end
        end
    end
    if doPrint then
        print("========== AUTO SHOVEL FRUIT FILTER DEBUG ==========")
        print("rules:", out.ruleCount, "(OR — kosong = shovel semua fruit di garden)")
        print("ready total:", out.readyTotal, "| IN:", out.inFilter, "| OUT:", out.outFilter)
        for i, row in ipairs(out.inSamples) do
            print(string.format(
                "  [%d] IN  %s  %.2fkg  price=%s  plant=%s fruit=%s",
                i, row.name, tonumber(row.kg) or 0, tostring(row.price or 0),
                row.plantId, row.fruitId
            ))
        end
        for i, row in ipairs(out.outSamples) do
            local line = string.format(
                "  [%d] OUT %s  %.2fkg  price=%s  plant=%s fruit=%s",
                i, row.name, tonumber(row.kg) or 0, tostring(row.price or 0),
                row.plantId, row.fruitId
            )
            if verbose and row.reason then
                line = line .. "  => " .. tostring(row.reason)
            end
            print(line)
        end
        print("====================================================")
    end
    _readyCache = out.readyTotal
    _filteredCache = out.inFilter
    local now = os.clock()
    _readyCacheAt = now
    _filteredCacheAt = now
    return out
end
M.debugFilterScan = M.DebugFilterScan

