    store.mode = nil
    G.__GAG2_AUTO_TELE = store
    _G.__GAG2_AUTO_TELE = store

    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.auto = MAIN.auto or {}
        MAIN.auto.autoTele = MAIN.auto.autoTele or {}
        MAIN.auto.autoTele.hitWerewolf = on
        MAIN.auto.autoTele.mode = nil
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end
    return on
end

local function _cfg()
    local s = _store()
    local delay = nil
    local loc = "center"
    local hitWw = false

    if type(s) == "table" then
        delay = tonumber(s.delay)
        loc = tostring(s.selectedLocation or "center")
        hitWw = (s.hitWerewolf == true)
    end

    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" and type(MAIN.auto) == "table"
        and type(MAIN.auto.autoTele) == "table" then
        local ap = MAIN.auto.autoTele
        if not delay or delay <= 0 then
            delay = tonumber(ap.delay)
        end
        if ap.selectedLocation then
            loc = tostring(ap.selectedLocation)
        end
        if ap.hitWerewolf ~= nil then
            hitWw = (ap.hitWerewolf == true)
        end
    end

    if not delay or delay <= 0 then delay = DEFAULT_DELAY end
    if delay < MIN_DELAY then delay = MIN_DELAY end
    if loc ~= "spawn" then loc = "center" end

    if type(s) == "table" then
        s.delay = delay
        s.selectedLocation = loc
        s.hitWerewolf = hitWw
        s.mode = nil
        G.__GAG2_AUTO_TELE = s
        _G.__GAG2_AUTO_TELE = s
    end

    return {
        enabled = _enabled(),
        delay = delay,
        selectedLocation = loc,
        hitWerewolf = hitWw,
    }
end

local function _hitWwEnabled()
    local store = _store()
    if type(store) == "table" and store.hitWerewolf ~= nil then
        return store.hitWerewolf == true
    end
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" and type(MAIN.auto) == "table"
        and type(MAIN.auto.autoTele) == "table" then
        return MAIN.auto.autoTele.hitWerewolf == true
    end
    return false
end

local function _anyFeatureOn()
    return _enabled() == true or _hitWwEnabled() == true
end

local function _hrp()
    local char = LP and LP.Character
    return char and char:FindFirstChild("HumanoidRootPart") or nil
end

local function _matchOwner(v)
    if v == nil or not LP then return false end
    return v == LP.UserId or v == LP.Name
        or tostring(v) == tostring(LP.UserId) or tostring(v) == LP.Name
end

local function _plotOwnedByLocal(plot)
    if not plot then return false end
    if _matchOwner(plot:GetAttribute("OwnerId")) then return true end
    if _matchOwner(plot:GetAttribute("Owner")) then return true end
    if _matchOwner(plot:GetAttribute("OwnerUserId")) then return true end
    if _matchOwner(plot:GetAttribute("UserId")) then return true end

    for _, child in ipairs(plot:GetChildren()) do
        if child:IsA("ValueBase") then
            local n = child.Name:lower()
            if n:find("owner") or n:find("userid") or n:find("player") then
                if _matchOwner(child.Value) then return true end
            end
        end
    end

    local myPlot = LP:GetAttribute("Plot") or LP:GetAttribute("PlotName")
        or LP:GetAttribute("GardenPlot") or LP:GetAttribute("PlotId")
    if myPlot and plot.Name == tostring(myPlot) then return true end
    if myPlot and plot.Name == ("Plot" .. tostring(myPlot)) then return true end

    return false
end

function M.GetPlayerPlot()
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens or not LP then return nil end

    local plotId = LP:GetAttribute("PlotId")
    local idStr = plotId ~= nil and tostring(plotId) or nil

    if cachedPlot and cachedPlot.Parent then
        if idStr then
            for _, name in ipairs({ "Plot" .. idStr, idStr, "Plot_" .. idStr }) do
                local expected = gardens:FindFirstChild(name)
                if expected and cachedPlot == expected then
                    return cachedPlot
                end
            end
        elseif _plotOwnedByLocal(cachedPlot) then
            return cachedPlot
        end
        cachedPlot = nil
        cachedGardenCf = nil
    end

    if idStr then
        for _, name in ipairs({ "Plot" .. idStr, idStr, "Plot_" .. idStr }) do
            local plot = gardens:FindFirstChild(name)
            if plot then
                cachedPlot = plot
                return plot
            end
        end
    end

    for _, plot in ipairs(gardens:GetChildren()) do
        if _plotOwnedByLocal(plot) then
            cachedPlot = plot
            return plot
        end
    end

    local hrp = _hrp()
    if hrp then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Include
        params.FilterDescendantsInstances = { gardens }
        local hit = workspace:Raycast(hrp.Position + Vector3.new(0, 6, 0), Vector3.new(0, -40, 0), params)
        if hit then
            for _, plot in ipairs(gardens:GetChildren()) do
                if hit.Instance:IsDescendantOf(plot) and _plotOwnedByLocal(plot) then
                    cachedPlot = plot
                    return plot
                end
            end
        end
    end

    return nil
end

local function _clearGeoCache()
    geoCache.plot = nil
    geoCache.at = 0
    geoCache.spawnPart = nil
    geoCache.groundParts = nil
    geoCache.groundRefY = nil
    geoCache.centerCf = nil
    geoCache.plantsFolder = nil
    geoCache.guardZone = nil
    geoCache.guardZoneAt = 0
end

local function _geoCacheFresh(plot)
    return plot
        and geoCache.plot == plot
        and type(geoCache.groundParts) == "table"
        and (os.clock() - (geoCache.at or 0)) <= GEO_CACHE_SEC
end

local function _getPlantsFolder(plot)
    if not plot then return nil end
    if geoCache.plot == plot and geoCache.plantsFolder ~= false then
        return geoCache.plantsFolder
    end
    local folder = plot:FindFirstChild("Plants")
    geoCache.plantsFolder = folder or false
    return folder
end

local function _findPlotSpawnPart(plot)
    if not plot then return nil end
    if geoCache.plot == plot and geoCache.spawnPart and geoCache.spawnPart.Parent then
        return geoCache.spawnPart
    end
    for _, name in ipairs({ "Spawn", "SpawnLocation", "GardenSpawn", "PlotSpawn", "SpawnPoint" }) do
        local inst = plot:FindFirstChild(name, true)
        if inst and inst:IsA("BasePart") then
            geoCache.spawnPart = inst
            return inst
        end
    end
    return nil
end

local function _isGroundPartName(name)
    local n = tostring(name or ""):lower()
    return n:find("soil") or n:find("dirt") or n:find("ground")
        or n:find("farm") or n:find("plot") or n:find("grass")
        or n == "spawn" or n == "spawnlocation" or n == "spawnpoint"
end

-- Skip part di folder Plants (620+ plant) — jauh lebih murah dari walk parent + GetTags.
local function _skipGroundPart(part, plot)
    if not part then return true end
    local plants = _getPlantsFolder(plot)
    if plants and part:IsDescendantOf(plants) then
        return true
    end
    return false
end

local function _scanGroundPartsUncached(plot)
    if not plot then return {} end
    local list, seen = {}, {}
    local function add(inst)
        if inst and inst:IsA("BasePart") and not seen[inst]
            and not _skipGroundPart(inst, plot) then
            seen[inst] = true
            list[#list + 1] = inst
        end
    end

    local gardens = workspace:FindFirstChild("Gardens")
    if gardens and gardens.Parent then
        local ok, parts = pcall(function()
            return gardens:QueryDescendants("BasePart." .. PLANT_AREA_TAG)
        end)
        if ok and type(parts) == "table" then
            for _, inst in ipairs(parts) do
                if inst:IsDescendantOf(plot) then
                    add(inst)
                end
            end
        end
    end

    if #list == 0 then
        for _, inst in ipairs(CollectionService:GetTagged(PLANT_AREA_TAG)) do
            if inst:IsDescendantOf(plot) then
                add(inst)
            end
        end
    end

    local spawn = _findPlotSpawnPart(plot)
    if spawn then add(spawn) end

    if #list == 0 then
        for _, colName in ipairs(PLANT_AREA_COLUMNS) do
            local col = plot:FindFirstChild(colName)
            if col then
                for _, desc in ipairs(col:GetDescendants()) do
                    if desc:IsA("BasePart") then
                        add(desc)
                    end
                end
            end
        end
    end

    if #list == 0 then
        for _, child in ipairs(plot:GetChildren()) do
            if child.Name ~= "Plants" then
                if child:IsA("BasePart") and _isGroundPartName(child.Name) then
                    add(child)
                elseif not child:IsA("Folder") or child.Name ~= "Plants" then
                    for _, desc in ipairs(child:GetDescendants()) do
                        if desc:IsA("BasePart") and _isGroundPartName(desc.Name) then
                            add(desc)
                        end
                    end
                end
            end
        end
    end

    return list
end

local function _getGroundParts(plot)
    if not plot then return {} end
    if _geoCacheFresh(plot) then
        return geoCache.groundParts
    end

    local parts = _scanGroundPartsUncached(plot)
    geoCache.plot = plot
    geoCache.at = os.clock()
    geoCache.groundParts = parts
    geoCache.groundRefY = nil
    geoCache.centerCf = nil
    geoCache.plantsFolder = plot:FindFirstChild("Plants") or false
    return parts
end

local function _collectPlotSurfaces(plot)
    return _getGroundParts(plot)
end

local function _plotGroundRefY(plot, groundParts)
    if plot and geoCache.plot == plot and geoCache.groundRefY then
        return geoCache.groundRefY
    end

    local spawn = _findPlotSpawnPart(plot)
    if spawn then
        local refY = spawn.Position.Y + spawn.Size.Y * 0.5
        if plot and geoCache.plot == plot then
            geoCache.groundRefY = refY
        end
        return refY
    end

    -- Tanpa spawn: pakai permukaan tertinggi (bukan terendah — island berlapis / batu bawah).
    local best = nil
    for _, part in ipairs(groundParts or _getGroundParts(plot)) do
        if part:IsA("BasePart") then
            local topY = part.Position.Y + part.Size.Y * 0.5
            if not best or topY > best then best = topY end
        end
    end
    if plot and geoCache.plot == plot then
        geoCache.groundRefY = best
    end
    return best
end

local function _clampStandY(plot, y, groundParts)
    y = tonumber(y)
    if not y then return nil end
    local ref = _plotGroundRefY(plot, groundParts)
    if ref and y > ref + MAX_GROUND_ABOVE_SPAWN then
        return ref + STAND_CLEARANCE
    end
    return y
end

-- Sample permukaan jalan di XZ: topY TERTINGGI di bawah clamp (hindari layer batu dalam island).
local function _sampleSurfaceTopY(plot, pos, hintY, groundParts)
    if typeof(pos) ~= "Vector3" or not plot then return tonumber(hintY) end
    groundParts = groundParts or _getGroundParts(plot)
    local refY = _plotGroundRefY(plot, groundParts) or tonumber(hintY) or pos.Y
    local bestTop = nil
    local r2 = GROUND_SAMPLE_RADIUS * GROUND_SAMPLE_RADIUS

    for _, part in ipairs(groundParts) do
        if part:IsA("BasePart") then
            local p = part.Position
            local dx, dz = p.X - pos.X, p.Z - pos.Z
            if dx * dx + dz * dz <= r2 then
                local topY = p.Y + part.Size.Y * 0.5
                if topY <= refY + MAX_GROUND_ABOVE_SPAWN then
                    if not bestTop or topY > bestTop then
                        bestTop = topY
                    end
                end
            end
        end
    end

    return bestTop or refY
end

-- Snap Y ke permukaan plot (bukan buah melayang / bukan layer dalam island).
local function _groundStandPos(plot, pos, hintY, groundParts)
    if typeof(pos) ~= "Vector3" then return nil end
    groundParts = groundParts or (plot and _getGroundParts(plot) or nil)
    if not plot then
        local y = tonumber(hintY) or pos.Y
        return Vector3.new(pos.X, y + STAND_CLEARANCE, pos.Z)
    end

    local surfaceY = _sampleSurfaceTopY(plot, pos, hintY, groundParts)
    local standY = (surfaceY or tonumber(hintY) or pos.Y) + STAND_CLEARANCE
    standY = _clampStandY(plot, standY, groundParts) or standY
    return Vector3.new(pos.X, standY, pos.Z)
end

local function _finalizeTargetCf(plot, cf, groundParts)
    if typeof(cf) ~= "CFrame" or not plot then return cf end
    local stand = _groundStandPos(plot, cf.Position, cf.Position.Y, groundParts)
    if not stand then return cf end
    local look = cf.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude > 0.05 then
        return CFrame.lookAt(stand, stand + flat.Unit)
    end
    return CFrame.new(stand)
end

-- Spawn = referensi tanah paling tepercaya — jangan raycast ulang (hindari hit buah).
local function _spawnStandCFrame(part, _plot)
    if not part or not part:IsA("BasePart") then return nil end
    local groundY = part.Position.Y + part.Size.Y * 0.5
    local y = groundY + SPAWN_STAND_OFFSET
    local stand = Vector3.new(part.Position.X, y, part.Position.Z)
    local look = part.CFrame.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude > 0.05 then
        return CFrame.lookAt(stand, stand + flat.Unit)
    end
    return CFrame.new(stand)
end

local function _spawnFallbackCf(plot)
    local spawn = _findPlotSpawnPart(plot)
    if spawn then return _spawnStandCFrame(spawn, plot) end
    return nil
end

-- Titik akhir mode Garden Spawn: maju horizontal saja (bukan local -Z spawn yang bisa ke langit).
local function _spawnForwardCFrame(spawnCf, plot)
    if typeof(spawnCf) ~= "CFrame" then return nil end
    plot = plot or M.GetPlayerPlot()

    local pos = spawnCf.Position
    local look = spawnCf.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude < 0.05 then
        flat = Vector3.new(0, 0, -1)
    else
        flat = flat.Unit
    end

    local xzTarget = Vector3.new(
        pos.X + flat.X * SPAWN_FORWARD_STUDS,
        pos.Y,
        pos.Z + flat.Z * SPAWN_FORWARD_STUDS
    )
    local stand = plot and _groundStandPos(plot, xzTarget, pos.Y) or (xzTarget + Vector3.new(0, STAND_CLEARANCE, 0))
    return CFrame.lookAt(stand, stand + flat)
end

function M.GetGardenPlotCFrame(plot)
    plot = plot or M.GetPlayerPlot()
    if not plot then return nil end

    local spawn = _findPlotSpawnPart(plot)
    if spawn then
        return _spawnStandCFrame(spawn, plot)
    end

    if plot:IsA("Model") then
        local ok, cf = pcall(function() return plot:GetPivot() end)
        if ok and typeof(cf) == "CFrame" then
            return _finalizeTargetCf(plot, cf + TP_OFFSET, _getGroundParts(plot))
        end
    end

    return nil
end

function M.GetGardenCenterCFrame(plot)
    plot = plot or M.GetPlayerPlot()

    if plot and geoCache.plot == plot and geoCache.centerCf
        and (os.clock() - (geoCache.at or 0)) <= GEO_CACHE_SEC then
        cachedGardenCf = geoCache.centerCf
        return geoCache.centerCf
    end

    if plot then
        local groundParts = _getGroundParts(plot)
        local areas = groundParts
        if #areas > 0 then
            local sx, sz, n = 0, 0, 0
            for _, part in ipairs(areas) do
                if part:IsA("BasePart") then
                    local p = part.Position
                    sx = sx + p.X
                    sz = sz + p.Z
                    n = n + 1
                end
            end
            if n > 0 then
                local refY = _plotGroundRefY(plot, groundParts)
                local stand = _groundStandPos(
                    plot,
                    Vector3.new(sx / n, 0, sz / n),
                    refY,
                    groundParts
                )
                cachedGardenCf = CFrame.new(stand)
                geoCache.centerCf = cachedGardenCf
                geoCache.plot = plot
                geoCache.at = os.clock()
                return cachedGardenCf
            end
        end

        if plot:IsA("Model") then
            local okBB, cf, size = pcall(function() return plot:GetBoundingBox() end)
            if okBB and typeof(cf) == "CFrame" and typeof(size) == "Vector3" then
                local refY = _plotGroundRefY(plot, groundParts)
                local stand = _groundStandPos(
                    plot,
                    cf.Position,
                    refY or (cf.Position.Y - size.Y * 0.5),
                    groundParts
                )
                cachedGardenCf = CFrame.new(stand)
                geoCache.centerCf = cachedGardenCf
                geoCache.plot = plot
                geoCache.at = os.clock()
                return cachedGardenCf
            end
            local ok, cf = pcall(function() return plot:GetPivot() end)
            if ok and typeof(cf) == "CFrame" then
                cachedGardenCf = _finalizeTargetCf(plot, cf + TP_OFFSET, groundParts)
                geoCache.centerCf = cachedGardenCf
                geoCache.plot = plot
                geoCache.at = os.clock()
                return cachedGardenCf
            end
        end

        local plotCf = M.GetGardenPlotCFrame(plot)
        if plotCf then
            cachedGardenCf = plotCf
            geoCache.centerCf = plotCf
            geoCache.plot = plot
            geoCache.at = os.clock()
            return cachedGardenCf
        end
    end

    return cachedGardenCf
end

function M.GetGardenSpawnCFrame(plot)
    plot = plot or M.GetPlayerPlot()
    if plot then
        local spawn = _findPlotSpawnPart(plot)
        if spawn then
            return _spawnStandCFrame(spawn, plot)
        end
    end
    return M.GetGardenCenterCFrame(plot)
end

-- Spawn plot: part + CFrame tujuan TP.
local function _getPlotSpawnTarget(plot)
    plot = plot or M.GetPlayerPlot()
    if not plot then return nil, nil end
    local spawnPart = _findPlotSpawnPart(plot)
    if spawnPart then
        return spawnPart, _spawnStandCFrame(spawnPart, plot)
    end
    local cf = M.GetGardenPlotCFrame(plot)
    return nil, cf
end

local function _flatDist(a, b)
    if not a or not b then return nil end
    local dx, dz = a.X - b.X, a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

local function _flatWithinRadius(hrpPos, anchorPos, radius)
    if not hrpPos or not anchorPos then return false end
    return (_flatDist(hrpPos, anchorPos) or 999) <= (tonumber(radius) or SPAWN_RADIUS)
end

-- Verifikasi XZ + Y — cegah dianggap sampai kalau masih melayang di langit.
local function _withinAnchor(hrpPos, anchorPos, radius)
    if not _flatWithinRadius(hrpPos, anchorPos, radius) then return false end
    local dy = hrpPos.Y - anchorPos.Y
    return dy <= MAX_Y_ABOVE_ANCHOR and dy >= -MAX_Y_BELOW_ANCHOR
end

local function _spawnAnchorPos(_spawnPart, spawnCf)
    -- Verifikasi ke titik TP yang sama (bukan part.Position center yang bisa beda visual).
    if spawnCf then return spawnCf.Position end
    return nil
end

local function _atSpawn(hrpPos, spawnPart, spawnCf)
    local anchor = _spawnAnchorPos(spawnPart, spawnCf)
    return _withinAnchor(hrpPos, anchor, SPAWN_RADIUS)
end

local function _atSpawnForward(hrpPos, spawnCf, plot)
    local forwardCf = _spawnForwardCFrame(spawnCf, plot)
    if not forwardCf then return false end
    return _withinAnchor(hrpPos, forwardCf.Position, SPAWN_FORWARD_RADIUS)
end

local function _atCenter(hrpPos, centerCf)
    if not centerCf then return false end
    return _withinAnchor(hrpPos, centerCf.Position, CENTER_RADIUS)
end

local function _loadingScreenActive()
    if not LP then return true end
    -- Selesai resmi
    if LP:GetAttribute("LoadingScreenDone") == true then
        return false
    end
    if LP:GetAttribute("LoadingScreenActive") == true then
        return true
    end
    if workspace:FindFirstChild("LoadingScreenMenu") ~= nil then
        return true
    end
    -- Belum LoadingScreenDone → anggap masih loading (jangan start karena PlotId sudah ada)
    return true
end

-- Raycast tanah valid di XZ (hindari TP ke langit → parachute)
local function _raycastGroundY(xzPos, plot)
    if typeof(xzPos) ~= "Vector3" then return nil end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local exclude = {}
    if LP and LP.Character then
        table.insert(exclude, LP.Character)
    end
    if plot then
        local plants = plot:FindFirstChild("Plants")
        if plants then table.insert(exclude, plants) end
    end
    params.FilterDescendantsInstances = exclude

    local baseY = xzPos.Y
    if baseY ~= baseY then baseY = 50 end -- NaN guard
    local origins = {
        Vector3.new(xzPos.X, baseY + 80, xzPos.Z),
        Vector3.new(xzPos.X, math.max(baseY, 20) + 200, xzPos.Z),
    }
    for _, origin in ipairs(origins) do
        local hit = workspace:Raycast(origin, Vector3.new(0, -500, 0), params)
        if hit then
            return hit.Position.Y
        end
    end
    return nil
end

local function _isTeleportCfSafe(cf, plot)
    if typeof(cf) ~= "CFrame" then return false end
    local pos = cf.Position
    if pos.Y > 450 or pos.Y < -250 then
        return false
    end

    plot = plot or M.GetPlayerPlot()
    local groundY = _raycastGroundY(pos, plot)
    if not groundY and plot then
        groundY = _plotGroundRefY(plot)
    end
    if not groundY then
        return false
    end

    local dy = pos.Y - groundY
    -- terlalu tinggi di atas tanah = jatuh → parachute
    if dy > (MAX_GROUND_ABOVE_SPAWN + 6) then
        return false
    end
    -- Jangan TP ke dalam island / di bawah permukaan
    if dy < -4 then
        return false
    end
    return true
end

local function _snapCfToSafeGround(cf, plot)
    if typeof(cf) ~= "CFrame" then return nil end
    plot = plot or M.GetPlayerPlot()
    local pos = cf.Position
    local groundY = _raycastGroundY(pos, plot)
    if not groundY and plot then
        local stand = _groundStandPos(plot, pos)
        if stand then
            return CFrame.new(stand) * (cf - cf.Position)
        end
        return nil
    end
    if not groundY then return nil end

    local wantY = groundY + STAND_CLEARANCE
    local safe = Vector3.new(pos.X, wantY, pos.Z)
    local look = cf.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude > 0.05 then
        return CFrame.lookAt(safe, safe + flat.Unit)
    end
    return CFrame.new(safe)
end

-- Cukup plot + character — jangan wajibkan part Spawn (nama beda-beda / load telat).
local function _plotRuntimeReady()
    if not LP or not LP.Character then return false end
    if not _hrp() then return false end

    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then return false end

    if LP:GetAttribute("PlotId") == nil then return false end

    local plot = M.GetPlayerPlot()
    return plot ~= nil and plot.Parent ~= nil
end

local function _probeGroundOk(plot, xzHint)
    if not plot then return false end
    local hrp = _hrp()
    local xz = typeof(xzHint) == "Vector3" and xzHint
        or (hrp and hrp.Position)
        or nil

    if xz and _raycastGroundY(xz, plot) ~= nil then
        return true
    end

    local spawn = _findPlotSpawnPart(plot)
    if spawn then
        local spawnXZ = spawn.Position
        if _raycastGroundY(spawnXZ, plot) ~= nil then
            return true
        end
        -- Spawn part sudah ada + surface sample valid
        local surf = _sampleSurfaceTopY(plot, spawnXZ)
        return surf ~= nil
    end

    return xz ~= nil and _sampleSurfaceTopY(plot, xz) ~= nil
end

function M.IsGameReady()
    if _loadingScreenActive() then return false end
    if not _plotRuntimeReady() then return false end
    local plot = M.GetPlayerPlot()
    local hrp = _hrp()
    if not plot or not hrp then return false end
    return _probeGroundOk(plot, hrp.Position)
end
M.isGameReady = M.IsGameReady

local function _invalidatePlotCache()
    cachedPlot = nil
    cachedGardenCf = nil
    _clearGeoCache()
end

local function _waitForBootReady(myId)
    local deadline = os.clock() + BOOT_WAIT_MAX
    local confirmStreak = 0

    while running and loopId == myId do
        if not workspace:FindFirstChild("Gardens") then
            pcall(function()
                workspace:WaitForChild("Gardens", 5)
            end)
        end

        -- WAJIB: loading selesai + ground terkonfirmasi beruntun (kurangi race layer island).
        if not _loadingScreenActive() and _plotRuntimeReady() then
            local plot = M.GetPlayerPlot()
            local groundOk = _probeGroundOk(plot)

            if groundOk then
                confirmStreak += 1
                _invalidatePlotCache()
                if confirmStreak == 1 then
                    task.wait(POST_READY_DELAY)
                else
                    task.wait(BOOT_POLL)
                end
                if confirmStreak >= BOOT_GROUND_CONFIRM
                    and not _loadingScreenActive()
                    and _plotRuntimeReady()
                    and _probeGroundOk(M.GetPlayerPlot()) then
                    M.InvalidateCache()
                    return true
                end
            else
                confirmStreak = 0
            end
        else
            confirmStreak = 0
        end

        if os.clock() >= deadline then
            -- Jangan TP kalau masih loading — lebih aman skip
            if _loadingScreenActive() then
                return false
            end
            -- Timeout: hanya lanjut kalau ground probe OK (jangan TP buta).
            local plot = M.GetPlayerPlot()
            if _plotRuntimeReady() and _probeGroundOk(plot) then
                M.InvalidateCache()
                return true
            end
            return false
        end

        if _loadingScreenActive() then
            _publishGuardStatus("Waiting loading...")
        elseif not _plotRuntimeReady() then
            _publishGuardStatus("Waiting plot...")
        else
            _publishGuardStatus("Waiting ground...")
        end
        task.wait(BOOT_POLL)
    end

    return false
end

local function _delayUnlessStopped(sec, myId)
    sec = tonumber(sec) or 0
    if sec <= 0 then return end
    local deadline = os.clock() + sec
    while running and loopId == myId and os.clock() < deadline do
        task.wait(0.05)
    end
end

local function _buyPetBusy()
    return G.__GAG2_AUTO_BUY_PET_BUSY == true
        or rawget(_G, "__GAG2_AUTO_BUY_PET_BUSY") == true
end

local function _claimSeedBusy()
    return G.__GAG2_AUTO_CLAIM_SEED_BUSY == true
        or rawget(_G, "__GAG2_AUTO_CLAIM_SEED_BUSY") == true
end

-- Soft flag: Auto Steal sedang hold session (eksplisit saja — jangan pakai IsRunning,
-- itu bikin Guard mati selama toggle Steal ON).
local function _stealBusy()
    if G.__GAG2_AUTO_STEAL_BUSY == true
        or rawget(_G, "__GAG2_AUTO_STEAL_BUSY") == true then
        return true
    end
    local AS = G.AutoSteal or G.AutoStealModule
        or rawget(_G, "AutoSteal") or rawget(_G, "AutoStealModule")
    if type(AS) == "table" and type(AS.IsStealBusy) == "function" then
        local ok, on = pcall(AS.IsStealBusy, AS)
        if ok and on == true then return true end
    end
    return false
end

-- Hard suppress: buy/claim/PauseAutoTele — blokir SEMUA
local function _hardSuppressed()
    if _buyPetBusy() then return true end
    if _claimSeedBusy() then return true end
    return G.__GAG2_AUTO_TELE_SUPPRESS == true
        or rawget(_G, "__GAG2_AUTO_TELE_SUPPRESS") == true
end

-- Legacy helper (home / spawn spam)
local function _suppressed()
    if _hardSuppressed() then return true end
    return false
end

local function _pivotTo(cf)
    local char = LP and LP.Character
    local hrp = _hrp()
    if not char or not hrp then return false end
    local ok = pcall(function()
        if char.PrimaryPart then
            char:PivotTo(cf)
        else
            hrp.CFrame = cf
        end
    end)
    if ok then return true end
    ok = pcall(function()
        hrp.CFrame = cf
    end)
    return ok == true
end

-- opts.hard = true → PivotTo instan (rescue). Default → Move mode karakter.
local function _teleport(cf, plot, opts)
    opts = type(opts) == "table" and opts or {}
    if typeof(cf) ~= "CFrame" then return false end
    if _loadingScreenActive() then return false end

    plot = plot or M.GetPlayerPlot()
    if not _isTeleportCfSafe(cf, plot) then
        local snapped = _snapCfToSafeGround(cf, plot)
        if not snapped or not _isTeleportCfSafe(snapped, plot) then
            return false
        end
        cf = snapped
    end

    if opts.hard == true then
        return _pivotTo(cf)
    end

    local mode = opts.mode or _getMoveMode()
    if mode == "hard" then
        return _pivotTo(cf)
    end

    -- Soft/step/walk: jangan fallback PivotTo (itu yang terasa "masih teleport")
    local Move = _getMove()
    if type(Move) == "table" and type(Move.GoTo) == "function" then
        local okCall, moved = pcall(function()
            return Move.GoTo(cf, { mode = mode, reason = "autotele" })
        end)
        return okCall and moved == true
    end

    return false
end

local function _getTeleportButtonRequest()
    if teleportBtnRequest and type(teleportBtnRequest.Fire) == "function" then
        return teleportBtnRequest
    end
    pcall(function()
        local net = require(ReplicatedStorage:WaitForChild("SharedModules", 5):WaitForChild("Networking", 5))
        local node = net and net.TeleportButton and net.TeleportButton.Request
        if type(node) == "table" and type(node.Fire) == "function" then
            teleportBtnRequest = node
            return
        end
        if type(net) == "table" and type(net.TeleportButtonRequest) == "table"
            and type(net.TeleportButtonRequest.Fire) == "function" then
            teleportBtnRequest = net.TeleportButtonRequest
        end
    end)
    return teleportBtnRequest
end

local function _fireGardenButton()
    local node = _getTeleportButtonRequest()
    if not node then return false end
    local ok = pcall(function()
        node:Fire("Garden")
    end)
    if ok == true then
        task.wait(2) -- jeda setelah Fire Garden
    end
    return ok == true
end

local function _nearOwnGarden(plot, hrpPos)
    if not plot or not hrpPos then return false end
    local best = math.huge
    local spawnCf = M.GetGardenSpawnCFrame(plot)
    local centerCf = M.GetGardenCenterCFrame(plot)
    if spawnCf then
        best = math.min(best, _flatDist(hrpPos, spawnCf.Position) or math.huge)
    end
    if centerCf then
        best = math.min(best, _flatDist(hrpPos, centerCf.Position) or math.huge)
    end
    return best <= GARDEN_NEAR_RADIUS
end

-- Official UI path: Fire("Garden") kalau masih jauh dari plot sendiri.
-- Saat Auto Steal busy: jangan Fire Garden (bisa ganggu steal).
local function _bringViaGardenButton(plot)
    if _stealBusy() then return false end
    local hrp = _hrp()
    if not hrp then return false end
    if _nearOwnGarden(plot, hrp.Position) then return true end
    if not _fireGardenButton() then return false end

    local t0 = os.clock()
    while os.clock() - t0 < BUTTON_GARDEN_WAIT do
        if not running then return false end
        hrp = _hrp()
        if hrp and _nearOwnGarden(plot, hrp.Position) then
            task.wait(TP_SETTLE_SEC)
            return true
        end
        task.wait(0.05)
    end
    hrp = _hrp()
    return hrp ~= nil and _nearOwnGarden(plot, hrp.Position)
end

-- Kalau sudah jatuh di bawah island: Fire Garden dulu; fallback snap hard.
local function _rescueIfFallen(plot)
    plot = plot or M.GetPlayerPlot()
    local hrp = _hrp()
    if not plot or not hrp then return false end

    local surfaceY = _sampleSurfaceTopY(plot, hrp.Position)
        or _raycastGroundY(hrp.Position, plot)
        or _plotGroundRefY(plot)
    if not surfaceY then return false end

    local dy = hrp.Position.Y - surfaceY
    if dy >= -VOID_RESCUE_BELOW_Y then
        return false
    end

    -- Prefer TeleportButton Garden (Move rescue) — lebih aman dari PivotTo di void
    local Move = G.Move or rawget(_G, "Move")
    if type(Move) == "table" and type(Move.RescueUnderPlot) == "function" then
        local ok = select(1, pcall(Move.RescueUnderPlot, "autotele_void"))
        if ok then return true end
    end

    local stand = _groundStandPos(plot, hrp.Position, surfaceY)
    if not stand then return false end
    return _teleport(CFrame.new(stand), plot, { hard = true })
end

-- Spam TP tiap 1s sampai XZ + Y dekat anchor (bukan cuma XZ — hindari loop di langit).
local function _ensureAtAnchor(targetCf, anchorPos, myId, radius, maxAttempts, plot, opts)
    opts = type(opts) == "table" and opts or {}
    if typeof(targetCf) ~= "CFrame" or not anchorPos then return false end
    plot = plot or M.GetPlayerPlot()
    maxAttempts = tonumber(maxAttempts) or SPAWN_SPAM_MAX
    local attempts = 0
    local groundParts = plot and _getGroundParts(plot) or nil
    local refY = plot and _plotGroundRefY(plot, groundParts) or nil
    local skipGroundSnap = opts.skipGroundSnap == true

    local function _applySkyFallback()
        if skipGroundSnap then return end
        if not plot then return end
        local fb = _spawnFallbackCf(plot)
        if fb then
            targetCf = fb
            anchorPos = fb.Position
            refY = _plotGroundRefY(plot, _getGroundParts(plot)) or refY
            return
        end
        local fbParts = groundParts or _getGroundParts(plot)
        targetCf = _finalizeTargetCf(plot, targetCf, fbParts)
        anchorPos = targetCf.Position
    end

    if plot and not skipGroundSnap then
        targetCf = _finalizeTargetCf(plot, targetCf, groundParts)
        anchorPos = targetCf.Position
        refY = _plotGroundRefY(plot, groundParts) or refY
        if refY and anchorPos.Y > refY + MAX_GROUND_ABOVE_SPAWN then
            _applySkyFallback()
        end
    end

    while running and loopId == myId and _enabled() and not _suppressed() do
        local hrp = _hrp()
        if not hrp then return false end
        if _withinAnchor(hrp.Position, anchorPos, radius) then
            return true
        end

        local playerSky = refY and hrp.Position.Y > refY + SKY_STUCK_Y
        local targetSky = refY and anchorPos.Y > refY + MAX_GROUND_ABOVE_SPAWN
        if plot and (playerSky or targetSky) and not skipGroundSnap then
            _applySkyFallback()
        end

        if _loadingScreenActive() then
            return false
        end

        _teleport(targetCf, plot)
        attempts += 1
        task.wait(TP_SETTLE_SEC)
        hrp = _hrp()
        if hrp and _withinAnchor(hrp.Position, anchorPos, radius) then
            return true
        end
        if attempts >= maxAttempts then
            return hrp ~= nil and _withinAnchor(hrp.Position, anchorPos, radius)
        end

        if plot and attempts % 3 == 0 and not skipGroundSnap then
            targetCf = _finalizeTargetCf(plot, targetCf, groundParts)
            anchorPos = targetCf.Position
            if refY and anchorPos.Y > refY + MAX_GROUND_ABOVE_SPAWN then
                _applySkyFallback()
            end
        end

        task.wait(math.max(0, SPAWN_SPAM_INTERVAL - TP_SETTLE_SEC))
    end

    return false
end

-- Satu travel per tick — loop delay UI yang handle retry.
-- Jauh dari garden: Fire("Garden"). Sudah dekat: Move.GoTo (Character Move Mode).
local function _tryTeleportToAnchor(targetCf, anchorPos, radius, plot, opts)
    opts = type(opts) == "table" and opts or {}
    if typeof(targetCf) ~= "CFrame" or not anchorPos then return false end
    if _loadingScreenActive() then return false end
    plot = plot or M.GetPlayerPlot()
    local skipGroundSnap = opts.skipGroundSnap == true

    if plot and not skipGroundSnap then
        local groundParts = _getGroundParts(plot)
        local refY = _plotGroundRefY(plot, groundParts)
        targetCf = _finalizeTargetCf(plot, targetCf, groundParts)
        anchorPos = targetCf.Position
        if refY and anchorPos.Y > refY + MAX_GROUND_ABOVE_SPAWN then
            local fb = _spawnFallbackCf(plot)
            if fb then
                targetCf = fb
                anchorPos = fb.Position
            end
        end
    end

    local hrp = _hrp()
    if not hrp then return false end
    if _withinAnchor(hrp.Position, anchorPos, radius) then
        return true
    end

    -- Jarak jauh → Fire button resmi dulu
    if not _nearOwnGarden(plot, hrp.Position) then
        _bringViaGardenButton(plot)
        hrp = _hrp()
        if hrp and _withinAnchor(hrp.Position, anchorPos, radius) then
            return true
        end
    end

    -- Fine-tune pakai Move mode (soft/step/walk/hard)
    _teleport(targetCf, plot)
    task.wait(TP_SETTLE_SEC)
    hrp = _hrp()
    return hrp ~= nil and _withinAnchor(hrp.Position, anchorPos, radius)
end

function M.ResolveTargetCFrame()
    local cfg = _cfg()
    local plot = M.GetPlayerPlot()

    if cfg.selectedLocation == "spawn" then
        local cf = M.GetGardenSpawnCFrame(plot)
        if cf then return _spawnForwardCFrame(cf, plot) or cf end
        return cachedGardenCf
    end

    local cf = M.GetGardenCenterCFrame(plot)
    if cf then return cf end
    return cachedGardenCf
end

function M.ClearSuppress()
    G.__GAG2_AUTO_TELE_SUPPRESS = false
    _G.__GAG2_AUTO_TELE_SUPPRESS = false
end
M.clearSuppress = M.ClearSuppress

----------------------------------------------------------------
-- Auto Guard: detect intruders → Move.GoTo(reason=guard) → shovel hit
----------------------------------------------------------------
local function _ensureShovelNet()
    if shovelNetReady and SwingShovel and HitPlayer then return true end
    local ok, net = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules", 5):WaitForChild("Networking", 5))
    end)
    if not ok or type(net) ~= "table" or type(net.Shovel) ~= "table" then
        return false
    end
    local sn = net.Shovel
    if type(sn.SwingShovel) == "table" and type(sn.SwingShovel.Fire) == "function" then
        SwingShovel = sn.SwingShovel
    end
    if type(sn.HitPlayer) == "table" and type(sn.HitPlayer.Fire) == "function" then
        HitPlayer = sn.HitPlayer
    end
    shovelNetReady = (SwingShovel ~= nil and HitPlayer ~= nil)
    return shovelNetReady
end

local function _getEquippedShovel()
    local char = LP and LP.Character
    if not char then return nil end
    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") and ch:GetAttribute("Shovel") ~= nil then
            return ch
        end
    end
    return nil
end

local function _equipShovel()
    if _getEquippedShovel() then return true end
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local bp = LP and LP:FindFirstChild("Backpack")
    if not hum or not bp then return false end
    for _, tool in ipairs(bp:GetChildren()) do
        if tool:IsA("Tool") and tool:GetAttribute("Shovel") ~= nil then
            local ok = pcall(function() hum:EquipTool(tool) end)
            if ok and _getEquippedShovel() then
                return true
            end
        end
    end
    return false
end

local function _unequipShovel()
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    if _getEquippedShovel() then
        pcall(function() hum:UnequipTools() end)
    end
end

-- Zona jaga: AABB PlantArea/soil di plot, fallback center radius
local function _getGuardZone(plot)
    if not plot then return nil end
    if geoCache.plot == plot and type(geoCache.guardZone) == "table"
        and (os.clock() - (geoCache.guardZoneAt or 0)) < 8
    then
        return geoCache.guardZone
    end

    local minX, minZ = math.huge, math.huge
    local maxX, maxZ = -math.huge, -math.huge
    local n = 0
    local function addPart(p)
        if not p or not p:IsA("BasePart") then return end
        local cf, size = p.CFrame, p.Size
        local hx, hz = size.X * 0.5, size.Z * 0.5
        local corners = {
            cf * Vector3.new( hx, 0,  hz),
            cf * Vector3.new( hx, 0, -hz),
            cf * Vector3.new(-hx, 0,  hz),
            cf * Vector3.new(-hx, 0, -hz),
        }
        for i = 1, #corners do
            local c = corners[i]
            if c.X < minX then minX = c.X end
            if c.X > maxX then maxX = c.X end
            if c.Z < minZ then minZ = c.Z end
            if c.Z > maxZ then maxZ = c.Z end
            n += 1
        end
    end

    local grounds = _getGroundParts(plot)
    if type(grounds) == "table" then
        for _, p in ipairs(grounds) do
            addPart(p)
        end
    end

    local zone
    if n > 0 and minX < maxX and minZ < maxZ then
        local cx = (minX + maxX) * 0.5
        local cz = (minZ + maxZ) * 0.5
        local cy = 0
        local centerCf = M.GetGardenCenterCFrame(plot)
        if centerCf then cy = centerCf.Position.Y end
        zone = {
            cf = CFrame.new(cx, cy, cz),
            hx = (maxX - minX) * 0.5,
            hz = (maxZ - minZ) * 0.5,
        }
    else
        local centerCf = M.GetGardenCenterCFrame(plot) or M.GetGardenSpawnCFrame(plot)
        if centerCf then
            local r = GUARD_ZONE_FALLBACK_R
            zone = { cf = centerCf, hx = r, hz = r }
        end
    end

    geoCache.guardZone = zone
    geoCache.guardZoneAt = os.clock()
    if geoCache.plot ~= plot then
        geoCache.plot = plot
    end
    return zone
end

local function _plotContainsPosition(plot, pos, pad)
    if not plot or typeof(pos) ~= "Vector3" then return false end
    pad = tonumber(pad)
    if pad == nil then pad = GUARD_PLOT_PAD end

    -- Prefer zona tanam (PlantArea / ground) — GetBoundingBox model terlalu besar (plant tinggi)
    local zone = _getGuardZone(plot)
    if zone then
        local localPos = zone.cf:PointToObjectSpace(pos)
        local hx = zone.hx + pad
        local hz = zone.hz + pad
        return math.abs(localPos.X) <= hx and math.abs(localPos.Z) <= hz
    end

    if plot:IsA("Model") then
        local ok, cf, size = pcall(function()
            return plot:GetBoundingBox()
        end)
        if ok and typeof(cf) == "CFrame" and typeof(size) == "Vector3" then
            -- Clamp tinggi bounding: pakai XZ saja, inset besar biar tidak makan tetangga
            local inset = 12
            local localPos = cf:PointToObjectSpace(pos)
            local hx = math.max(8, size.X * 0.5 - inset) + pad
            local hz = math.max(8, size.Z * 0.5 - inset) + pad
            return math.abs(localPos.X) <= hx and math.abs(localPos.Z) <= hz
        end
    end
    return false
end

-- Plot di bawah kaki (raycast Gardens) — paling akurat vs tetangga
local function _findPlotUnderPosition(pos)
    if typeof(pos) ~= "Vector3" then return nil end
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then return nil end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = { gardens }
    local hit = workspace:Raycast(pos + Vector3.new(0, 8, 0), Vector3.new(0, -80, 0), params)
    if not hit or not hit.Instance then return nil end
    for _, plot in ipairs(gardens:GetChildren()) do
        if hit.Instance:IsDescendantOf(plot) then
            return plot
        end
    end
    return nil
end

local function _plotOwnerId(plot)
    if not plot then return nil end
    return tonumber(plot:GetAttribute("OwnerUserId"))
        or tonumber(plot:GetAttribute("UserId"))
        or tonumber(plot:GetAttribute("OwnerId"))
end

-- Intruder = berdiri di ATAS plot kita (raycast), bukan di garden orang lain
local function _isIntruderOnMyPlot(plr, otherHrp, myPlot)
    if not otherHrp or not myPlot then return false end
    local under = _findPlotUnderPosition(otherHrp.Position)
    if under then
        if under ~= myPlot then
            return false -- jelas di plot lain (termasuk garden sendiri)
        end
        return true
    end
    -- Ray miss (lompat/void): fallback zona tanam ketat saja
    return _plotContainsPosition(myPlot, otherHrp.Position, GUARD_PLOT_PAD)
end

-- Clamp XZ ke dalam zona jaga
local function _clampPosToPlot(plot, pos, inset)
    if not plot or typeof(pos) ~= "Vector3" then return pos end
    inset = math.max(0, tonumber(inset) or GUARD_CHASE_INSET)
    local zone = _getGuardZone(plot)
    if zone then
        local localPos = zone.cf:PointToObjectSpace(pos)
        local hx = math.max(1, zone.hx - inset)
        local hz = math.max(1, zone.hz - inset)
        local clamped = Vector3.new(
            math.clamp(localPos.X, -hx, hx),
            localPos.Y,
            math.clamp(localPos.Z, -hz, hz)
        )
        local world = zone.cf:PointToWorldSpace(clamped)
        return Vector3.new(world.X, pos.Y, world.Z)
    end
    return pos
end

function M.IsPositionInOwnPlot(pos)
    local plot = M.GetPlayerPlot()
    if not plot then return false end
    local under = _findPlotUnderPosition(pos)
    if under then return under == plot end
    return _plotContainsPosition(plot, pos, GUARD_PLOT_PAD)
end

local function _findIntruders(plot)
    plot = plot or M.GetPlayerPlot()
    if not plot then return {} end
    local me = _hrp()
    local origin = me and me.Position or nil
    local list = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP then
            local char = plr.Character
            local other = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if other and (not hum or hum.Health > 0) then
                if _isIntruderOnMyPlot(plr, other, plot) then
                    local dist = origin and (other.Position - origin).Magnitude or 0
                    list[#list + 1] = {
                        player = plr,
                        hrp = other,
                        userId = plr.UserId,
                        name = plr.Name,
                        dist = dist,
                    }
                end
            end
        end
    end
    table.sort(list, function(a, b)
        return (a.dist or 0) < (b.dist or 0)
    end)
    return list
end

local function _swingHitPlayer(plr, swingCd, targetCd)
    if not plr then return false end
    if not _ensureShovelNet() then return false end
    if not SwingShovel or not HitPlayer then return false end
    if not _equipShovel() then
        _publishGuardStatus("No shovel")
        return false
    end
    swingCd = tonumber(swingCd) or GUARD_SWING_CD
    targetCd = tonumber(targetCd) or GUARD_TARGET_CD
    local now = os.clock()
    if now - lastSwingAt < swingCd then return false end
    local uid = plr.UserId
    local last = hitTargetAt[uid] or 0
    if now - last < targetCd then return false end

    pcall(function() SwingShovel:Fire() end)
    lastSwingAt = now
    hitTargetAt[uid] = now
    pcall(function() HitPlayer:Fire(uid) end)
    return true
end

local function _chaseIntruder(target)
    if type(target) ~= "table" or not target.hrp or not target.hrp.Parent then
        return false, "gone"
    end
    local plot = M.GetPlayerPlot()
    if not plot then return false, "no_plot" end

    local me = _hrp()
    if not me then return false, "no_hrp" end

    -- Target sudah tidak di plot kita → stop
    if not _isIntruderOnMyPlot(target.player, target.hrp, plot) then
        _publishGuardStatus("Intruder left garden")
        return false, "left_garden"
    end

    -- Kita di luar plot sendiri → pulang hold
    local underMe = _findPlotUnderPosition(me.Position)
    if underMe and underMe ~= plot then
        _publishGuardStatus("Outside plot — return")
        return false, "self_outside"
    end

    local rawPos = target.hrp.Position
    local goalPos = _clampPosToPlot(plot, rawPos, GUARD_CHASE_INSET)
    local dist = (goalPos - me.Position).Magnitude
    lastGuardTargetName = target.name

    local trueDist = (rawPos - me.Position).Magnitude
    if trueDist <= GUARD_HIT_RANGE and _isIntruderOnMyPlot(target.player, target.hrp, plot) then
        _publishGuardStatus(string.format("Hit %s (%.0fst)", tostring(target.name), trueDist))
        _swingHitPlayer(target.player)
        return true, "hit"
    end

    _publishGuardStatus(string.format("Chase %s (%.0fst)", tostring(target.name), dist))
    local Move = _getMove()
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false, "no_move"
    end
    local mode = _getMoveMode()
    if mode == "hard" then
        mode = "walk"
    end
    local look = Vector3.new(rawPos.X, goalPos.Y, rawPos.Z)
    local goal = CFrame.lookAt(goalPos, look)
    local okCall, moved = pcall(function()
        return Move.GoTo(goal, {
            mode = mode,
            reason = "guard",
        })
    end)
    if not (okCall and moved == true) then
        return false, "busy_or_fail"
    end

    me = _hrp()
    if me and target.hrp and target.hrp.Parent then
        if not _isIntruderOnMyPlot(target.player, target.hrp, plot) then
            return false, "left_garden"
        end
        trueDist = (target.hrp.Position - me.Position).Magnitude
        if trueDist <= GUARD_HIT_RANGE then
            _swingHitPlayer(target.player)
            return true, "hit"
        end
    end
    return true, "chase"
end

----------------------------------------------------------------
-- Hit Werewolf: equip shovel → hard TP → Swing+Hit cepat
-- Role WW bisa berpindah antar player (A hit → C jadi WW):
--   rescan SETIAP tick + AttributeChanged (bukan scan sekali di awal)
----------------------------------------------------------------
local hitWwCurrentUid = nil -- sticky target, diverifikasi ulang tiap tick
local hitWwRoleGen = 0 -- naik tiap Defender / Transformed berubah
local hitWwAttrConns = {}
local hitWwPlayersConn = nil
local hitWwPlayersLeaveConn = nil
local hitWwSawLocalDefender = false -- malam ini sempat Defender=true
local hitWwHomeOnceDone = false -- pulang garden sekali saat dapat role
local hitWwGotRole = false -- true saat Reveal/Transformed bilang kita Werewolf
local hitWwBlacklist = {} -- [userId]=true — jangan pukul lagi target yang sudah kita hit
local hitWwKnownUid = nil -- current WW dari Networking.Werewolf.Transformed
local hitWwNetConns = {} -- Reveal / Transformed
local hitWwNetBound = false

local function _resetHitWwNightState()
    hitWwGotRole = false
    hitWwSawLocalDefender = false
    hitWwHomeOnceDone = false
    hitWwCurrentUid = nil
    hitWwKnownUid = nil
    hitWwBlacklist = {}
end

local function _markGotWerewolfRole(why)
    if hitWwGotRole then
        hitWwCurrentUid = nil
        lastGuardTargetName = nil
        return
    end
    hitWwGotRole = true
    hitWwCurrentUid = nil
    hitWwKnownUid = LP and LP.UserId or nil
    lastGuardTargetName = nil
    hitWwRoleGen += 1
    _publishGuardStatus(string.format("HIT WW · sudah WW (%s) → stop", tostring(why or "role")))
end

local function _markLostWerewolfRole(why)
    -- Reveal "Defender" → kita villagers, lanjut cari WW
    hitWwGotRole = false
    if hitWwKnownUid == (LP and LP.UserId) then
        hitWwKnownUid = nil
    end
    hitWwRoleGen += 1
    _publishGuardStatus(string.format("HIT WW · Defender (%s) → cari WW", tostring(why or "reveal")))
end

local function _setKnownWerewolfPlayer(plr, why)
    if not plr or not plr:IsA("Player") then return end
    if plr == LP then
        _markGotWerewolfRole(why or "transformed_self")
        return
    end
    -- Orang lain jadi WW → itu target baru; kita bukan WW
    hitWwGotRole = false
    hitWwKnownUid = plr.UserId
    hitWwCurrentUid = plr.UserId
    hitWwBlacklist[plr.UserId] = nil -- boleh dipukul (dia WW sekarang)
    hitWwRoleGen += 1
    lastGuardTargetName = plr.Name
    _publishGuardStatus(string.format("HIT WW · target %s (%s)", tostring(plr.Name), tostring(why or "transformed")))
end

local function _unbindWerewolfNetWatch()
    for i = 1, #hitWwNetConns do
        pcall(function() hitWwNetConns[i]:Disconnect() end)
    end
    hitWwNetConns = {}
    hitWwNetBound = false
end

-- Game client: Reveal(role) + Transformed(player) = sumber kebenaran role
local function _ensureWerewolfNetWatch()
    if hitWwNetBound then return end
    local ok, net = pcall(function()
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
            or ReplicatedStorage:WaitForChild("SharedModules", 3)
        local n = sm and (sm:FindFirstChild("Networking") or sm:WaitForChild("Networking", 3))
        if n then return require(n) end
        return nil
    end)
    if not ok or type(net) ~= "table" or type(net.Werewolf) ~= "table" then
        return
    end
    local ww = net.Werewolf

    if type(ww.Reveal) == "table" then
        local okC, conn = pcall(function()
            return ww.Reveal.OnClientEvent:Connect(function(role, _animate, _duration)
                role = tostring(role or "")
                if role == "Werewolf" then
                    _markGotWerewolfRole("Reveal")
                elseif role == "Defender" then
                    _markLostWerewolfRole("Reveal")
                end
            end)
        end)
        if okC and conn then
            hitWwNetConns[#hitWwNetConns + 1] = conn
        end
    end

    if type(ww.Transformed) == "table" then
        local okT, connT = pcall(function()
            return ww.Transformed.OnClientEvent:Connect(function(plr)
                if typeof(plr) ~= "Instance" or not plr:IsA("Player") then return end
                _setKnownWerewolfPlayer(plr, "Transformed")
            end)
        end)
        if okT and connT then
            hitWwNetConns[#hitWwNetConns + 1] = connT
        end
    end

    hitWwNetBound = #hitWwNetConns > 0
end

local function _getDefenderAttrName()
    if defenderAttrName then return defenderAttrName end
    defenderAttrName = "Defender"
    pcall(function()
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local mod = sm and sm:FindFirstChild("WerewolfNightData")
        if mod then
            local data = require(mod)
            if type(data) == "table" and type(data.DefenderAttribute) == "string" then
                defenderAttrName = data.DefenderAttribute
            end
        end
    end)
    return defenderAttrName
end

local function _isNight()
    local n = ReplicatedStorage:FindFirstChild("Night")
    if n and (n:IsA("BoolValue") or n:IsA("NumberValue")) then
        return n.Value == true or n.Value == 1
    end
    return nil
end

local function _getDefenderAttr(plr)
    if not plr then return nil end
    local name = _getDefenderAttrName()
    local v = plr:GetAttribute(name)
    if v == nil then v = plr:GetAttribute("Defender") end
    return v
end

-- Live watch attr (backup); Reveal/Transformed lebih akurat
local function _unbindWerewolfAttrWatch()
    for _, c in pairs(hitWwAttrConns) do
        pcall(function() c:Disconnect() end)
    end
    hitWwAttrConns = {}
    if hitWwPlayersConn then
        pcall(function() hitWwPlayersConn:Disconnect() end)
        hitWwPlayersConn = nil
    end
    if hitWwPlayersLeaveConn then
        pcall(function() hitWwPlayersLeaveConn:Disconnect() end)
        hitWwPlayersLeaveConn = nil
    end
end

local function _bindPlayerWerewolfAttr(plr)
    if not plr or hitWwAttrConns[plr] then return end
    local attr = _getDefenderAttrName()
    local function onDefenderChanged()
        hitWwRoleGen += 1
        if plr == LP then
            local v = _getDefenderAttr(LP)
            if v == true then
                hitWwSawLocalDefender = true
                -- Icon game: DefenderAttribute==true → defender icon. Kita defender.
                if hitWwGotRole then
                    _markLostWerewolfRole("attr_defender")
                end
            else
                -- Explicit false saja; nil jangan anggap WW (nanti Reveal/Transformed)
                if _isNight() == true and _getDefenderAttr(LP) == false then
                    _markGotWerewolfRole("attr_false")
                end
            end
            return
        end
        if hitWwCurrentUid and plr.UserId == hitWwCurrentUid then
            if _getDefenderAttr(plr) == true then
                hitWwCurrentUid = nil
                if hitWwKnownUid == plr.UserId then
                    hitWwKnownUid = nil
                end
            end
        end
        -- Hanya update known kalau explicit false (bukan nil)
        if _getDefenderAttr(plr) == false and _isNight() == true and plr ~= LP then
            hitWwKnownUid = plr.UserId
        end
    end
    local ok, conn = pcall(function()
        return plr:GetAttributeChangedSignal(attr):Connect(onDefenderChanged)
    end)
    if ok and conn then
        hitWwAttrConns[plr] = conn
    end
    if attr ~= "Defender" and not hitWwAttrConns[plr.UserId] then
        local ok2, conn2 = pcall(function()
            return plr:GetAttributeChangedSignal("Defender"):Connect(onDefenderChanged)
        end)
        if ok2 and conn2 then
            hitWwAttrConns[plr.UserId] = conn2
        end
    end
end

local function _ensureWerewolfAttrWatch()
    if hitWwPlayersConn then return end
    for _, plr in ipairs(Players:GetPlayers()) do
        _bindPlayerWerewolfAttr(plr)
    end
    hitWwPlayersConn = Players.PlayerAdded:Connect(function(plr)
        _bindPlayerWerewolfAttr(plr)
        hitWwRoleGen += 1
    end)
    hitWwPlayersLeaveConn = Players.PlayerRemoving:Connect(function(plr)
        local c = hitWwAttrConns[plr]
        if c then pcall(function() c:Disconnect() end) end
        hitWwAttrConns[plr] = nil
        local c2 = hitWwAttrConns[plr.UserId]
        if c2 then pcall(function() c2:Disconnect() end) end
        hitWwAttrConns[plr.UserId] = nil
        if hitWwCurrentUid == plr.UserId then
            hitWwCurrentUid = nil
        end
        if hitWwKnownUid == plr.UserId then
            hitWwKnownUid = nil
        end
        hitWwRoleGen += 1
    end)
end

-- Game: DefenderAttribute == true → defender (ada icon).
-- Werewolf = Transformed(player) ATAU DefenderAttribute == false (eksplisit).
-- JANGAN treat nil sebagai WW — itu yang bikin pukul player biasa.
local function _isPlayerWerewolf(plr)
    if not plr or plr == LP then return false end
    if _isNight() ~= true then return false end
    if hitWwGotRole then return false end
    if hitWwBlacklist[plr.UserId] == true then return false end

    -- Sumber utama: Networking.Werewolf.Transformed
    if type(hitWwKnownUid) == "number" and hitWwKnownUid ~= (LP and LP.UserId) then
        return plr.UserId == hitWwKnownUid
    end

    -- Fallback ketat: hanya explicit false (bukan nil)
    return _getDefenderAttr(plr) == false
end

local function _isLocalWerewolf()
    if _isNight() ~= true then
        _resetHitWwNightState()
        return false
    end
    if hitWwGotRole == true then
        return true
    end
    -- Known Transformed ke kita
    if hitWwKnownUid == (LP and LP.UserId) then
        return true
    end
    local v = _getDefenderAttr(LP)
    if v == true then
        hitWwSawLocalDefender = true
        return false
    end
    -- Hanya explicit false (Reveal/Transformed lebih dipercaya)
    if v == false then
        _markGotWerewolfRole("def=false")
        return true
    end
    return false
end

local function _teleHardTo(pos, lookAt)
    if typeof(pos) ~= "Vector3" then return false end
    local me = _hrp()
    local char = LP and LP.Character
    if not me or not char then return false end
    local look = typeof(lookAt) == "Vector3" and lookAt or (pos + Vector3.new(0, 0, -1))
    local cf = CFrame.lookAt(pos, Vector3.new(look.X, pos.Y, look.Z))
    local ok = pcall(function()
        if char.PrimaryPart then
            char:PivotTo(cf)
        else
            me.CFrame = cf
        end
        me.AssemblyLinearVelocity = Vector3.zero
        me.AssemblyAngularVelocity = Vector3.zero
    end)
    return ok == true
end

-- Stop Move yang bisa tarik balik ke garden / posisi lama
local function _stopMoveInterference()
    local Move = _getMove()
    if type(Move) ~= "table" then return end
    if type(Move.Stop) == "function" then
        pcall(Move.Stop)
    end
    if type(Move.StopGroundGuard) == "function" then
        pcall(Move.StopGroundGuard)
    end
end

-- Posisi stand di samping HRP target (hadap target)
local function _standBesideTarget(targetHrp)
    if not targetHrp or not targetHrp.Parent then return nil end
    local me = _hrp()
    local raw = targetHrp.Position
    local from = me and me.Position or (raw + Vector3.new(HIT_WW_LOCK_DIST, 0, 0))
    local flat = Vector3.new(raw.X - from.X, 0, raw.Z - from.Z)
    local offset = Vector3.new(HIT_WW_LOCK_DIST, 0, 0)
    if flat.Magnitude > 1e-3 then
        offset = flat.Unit * HIT_WW_LOCK_DIST
    end
    return raw - offset, raw
end

local function _lockBesideTarget(targetHrp)
    local stand, look = _standBesideTarget(targetHrp)
    if not stand then return false end
    return _teleHardTo(stand, look)
end

local function _stopHitWwPosLock()
    if hitWwPosLockConn then
        pcall(function() hitWwPosLockConn:Disconnect() end)
        hitWwPosLockConn = nil
    end
end

-- Kunci posisi tiap frame selama spam (lawan server/Move snap-back)
local function _startHitWwPosLock(getTargetHrp)
    _stopHitWwPosLock()
    hitWwPosLockConn = RunService.Heartbeat:Connect(function()
        if hitWwGotRole or not _hitWwEnabled() then
            _stopHitWwPosLock()
            return
        end
        local hrp = nil
        if type(getTargetHrp) == "function" then
            local ok, v = pcall(getTargetHrp)
            if ok then hrp = v end
        end
        if hrp and hrp.Parent then
            _lockBesideTarget(hrp)
        end
    end)
end

-- Rescan tiap tick. HANYA WW pasti — jangan pukul player biasa (nil).
local function _findWerewolfTargets()
    _ensureWerewolfNetWatch()
    if hitWwGotRole or _isLocalWerewolf() then
        return {}
    end
    local me = _hrp()
    local origin = me and me.Position or nil

    local function pack(plr)
        if not plr or plr == LP then return nil end
        if hitWwBlacklist[plr.UserId] == true then return nil end
        local char = plr.Character
        local other = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not other or (hum and hum.Health <= 0) then return nil end
        local dist = origin and (other.Position - origin).Magnitude or math.huge
        return {
            player = plr,
            hrp = other,
            userId = plr.UserId,
            name = plr.Name,
            dist = dist,
            def = _getDefenderAttr(plr),
        }
    end

    -- 1) Transformed → exact
    if type(hitWwKnownUid) == "number" and hitWwKnownUid ~= (LP and LP.UserId) then
        local plr = Players:GetPlayerByUserId(hitWwKnownUid)
        if plr and _getDefenderAttr(plr) ~= true then
            local row = pack(plr)
            if row then return { row } end
        end
        if plr and _getDefenderAttr(plr) == true then
            hitWwKnownUid = nil
        end
    end

    -- 2) Explicit DefenderAttribute == false
    local list = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and _getDefenderAttr(plr) == false then
            local row = pack(plr)
            if row then list[#list + 1] = row end
        end
    end
    if #list > 0 then
        table.sort(list, function(a, b)
            return (a.dist or math.huge) < (b.dist or math.huge)
        end)
        return list
    end

    -- 3) Aman: kita pasti Defender, dan tepat 1 player lain bukan Defender
    --    (roles sudah assigned — hindari spam semua yang attr-nya masih nil)
    if _getDefenderAttr(LP) == true then
        local sole = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP and _getDefenderAttr(plr) ~= true then
                local row = pack(plr)
                if row then sole[#sole + 1] = row end
            end
        end
        if #sole == 1 then
            hitWwKnownUid = sole[1].userId
            return sole
        end
    end

    return {}
end

local function _pickWerewolfTarget(targets)
    if type(targets) ~= "table" or #targets == 0 then
        hitWwCurrentUid = nil
        return nil
    end
    -- Sticky: pakai target lama HANYA kalau masih WW di scan terbaru
    if hitWwCurrentUid then
        for i = 1, #targets do
            local t = targets[i]
            if t.userId == hitWwCurrentUid then
                return t
            end
        end
        -- Role sudah pindah (mis. A→C): sticky invalid
        hitWwCurrentUid = nil
    end
    local t = targets[1]
    hitWwCurrentUid = t and t.userId or nil
    return t
end

local function _hitWerewolfTick()
    _ensureWerewolfNetWatch()
    _ensureWerewolfAttrWatch()

    if _isNight() ~= true then
        _resetHitWwNightState()
        _publishGuardStatus("HIT WW · tunggu malam")
        return false, "not_night"
    end

    if _isLocalWerewolf() then
        hitWwCurrentUid = nil
        lastGuardTargetName = nil
        _publishGuardStatus("HIT WW · sudah werewolf → stop")
        return false, "already_ww"
    end

    if not _equipShovel() then
        _publishGuardStatus("HIT WW · no shovel")
        return false, "no_shovel"
    end
    if not _ensureShovelNet() then
        _publishGuardStatus("HIT WW · no remote")
        return false, "no_remote"
    end

    local targets = _findWerewolfTargets()
    local t = _pickWerewolfTarget(targets)
    if not t then
        _publishGuardStatus("HIT WW · no werewolf")
        return false, "empty"
    end

    local me = _hrp()
    if not me or not t.hrp or not t.hrp.Parent then
        hitWwCurrentUid = nil
        return false, "gone"
    end

    if _getDefenderAttr(t.player) == true then
        hitWwCurrentUid = nil
        if hitWwKnownUid == t.userId then hitWwKnownUid = nil end
        _publishGuardStatus(string.format("HIT WW · %s defender → skip", tostring(t.name)))
        return false, "retarget"
    end

    -- Harus dari list finder (Transformed / false / sole-WW). Tolak kalau known ada tapi beda orang.
    if type(hitWwKnownUid) == "number" and hitWwKnownUid ~= (LP and LP.UserId) and hitWwKnownUid ~= t.userId then
        hitWwCurrentUid = nil
        return false, "retarget"
    end

    local raw = t.hrp.Position
    local dist = (raw - me.Position).Magnitude
    lastGuardTargetName = t.name

    -- Matikan Move biar gak di-tarik balik ke garden / posisi lama
    _stopMoveInterference()

    -- Selalu re-lock di samping target dulu (jangan andalkan 1x TP)
    _lockBesideTarget(t.hrp)
    me = _hrp()
    if me and t.hrp and t.hrp.Parent then
        dist = (t.hrp.Position - me.Position).Magnitude
    end

    if dist > HIT_WW_TELE_NEAR then
        _publishGuardStatus(string.format("HIT WW · TP %s (%.0fst)", tostring(t.name), dist))
        _lockBesideTarget(t.hrp)
        task.wait(0.03)
        -- TP ulang 2–3x lawan snap-back
        for _ = 1, 3 do
            _lockBesideTarget(t.hrp)
            task.wait(0.03)
        end
        me = _hrp()
        if me and t.hrp and t.hrp.Parent then
            dist = (t.hrp.Position - me.Position).Magnitude
        end
        if _isLocalWerewolf() then
            _stopHitWwPosLock()
            _publishGuardStatus("HIT WW · sudah werewolf → stop")
            return false, "already_ww"
        end
        if _getDefenderAttr(t.player) == true then
            hitWwCurrentUid = nil
            return false, "retarget"
        end
    end

    if dist <= HIT_WW_RANGE then
        if _isLocalWerewolf() then
            _stopHitWwPosLock()
            return false, "already_ww"
        end

        _startHitWwPosLock(function()
            if not t.player or not t.player.Parent then return nil end
            local char = t.player.Character
            local h = char and char:FindFirstChild("HumanoidRootPart")
            t.hrp = h
            return h
        end)

        -- SPAM: tiap swing re-lock posisi dulu biar hit kena di server
        local t0 = os.clock()
        local swings = 0
        local uid = t.userId
        while (os.clock() - t0) < HIT_WW_SPAM_BURST_SEC do
            if not (_anyFeatureOn() and _hitWwEnabled()) then
                break
            end
            if _isLocalWerewolf() or hitWwKnownUid == (LP and LP.UserId) then
                _stopHitWwPosLock()
                _publishGuardStatus("HIT WW · sudah werewolf → stop")
                return true, "already_ww"
            end
            if not t.player or not t.player.Parent then
                hitWwCurrentUid = nil
                _stopHitWwPosLock()
                return true, "retarget"
            end
            if _getDefenderAttr(t.player) == true then
                hitWwCurrentUid = nil
                if hitWwKnownUid == uid then hitWwKnownUid = nil end
                _stopHitWwPosLock()
                if _isLocalWerewolf() then
                    return true, "already_ww"
                end
                _publishGuardStatus(string.format("HIT WW · %s jadi Defender", tostring(t.name)))
                return true, "retarget"
            end
            if type(hitWwKnownUid) == "number"
                and hitWwKnownUid ~= (LP and LP.UserId)
                and hitWwKnownUid ~= uid then
                hitWwCurrentUid = hitWwKnownUid
                _stopHitWwPosLock()
                return true, "retarget"
            end

            if not t.hrp or not t.hrp.Parent then
                local char = t.player.Character
                t.hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not t.hrp then break end
            end

            -- Kunci posisi SEBELUM fire (ini yang bikin kena)
            _lockBesideTarget(t.hrp)
            local ok = _swingHitPlayer(t.player, HIT_WW_SWING_CD, HIT_WW_TARGET_CD)
            if ok then
                swings += 1
                _publishGuardStatus(string.format(
                    "HIT WW · spam %s x%d (locked)",
                    tostring(t.name), swings
                ))
            end
            -- Keep lock antara swing
            _lockBesideTarget(t.hrp)
            task.wait(HIT_WW_TARGET_CD)
        end

        _stopHitWwPosLock()
        if _isLocalWerewolf() then
            return true, "already_ww"
        end
        _publishGuardStatus(string.format("HIT WW · spam %s x%d · lanjut", tostring(t.name), swings))
        return true, "hit_wait"
    end

    _stopHitWwPosLock()
    _publishGuardStatus(string.format("HIT WW · chase %s (%.0fst)", tostring(t.name), dist))
    -- Jauh: tetap TP mendekat tiap tick
    _lockBesideTarget(t.hrp)
    return true, "far"
end

-- Guard tick: intruder → chase+hit; Hit WW → hard TP; kosong → hold Center/Spawn
local function _holdHomePosition(plot)
    plot = plot or M.GetPlayerPlot()
    if not plot then return false end

    local cfg = _cfg()
    local hrp = _hrp()
    if not hrp then return false end

    local spawnPart, spawnCf = _getPlotSpawnTarget(plot)
    if not spawnCf then return false end

    if cfg.selectedLocation == "spawn" then
        local forwardCf = _spawnForwardCFrame(spawnCf, plot)
        if not forwardCf then return false end
        if _atSpawnForward(hrp.Position, spawnCf, plot) then
            return false
        end
        if not _atSpawn(hrp.Position, spawnPart, spawnCf) then
            local anchor = _spawnAnchorPos(spawnPart, spawnCf)
            _publishGuardStatus("Hold Spawn")
            return _tryTeleportToAnchor(spawnCf, anchor, SPAWN_RADIUS, plot) == true
        end
        _publishGuardStatus("Hold Spawn forward")
        return _tryTeleportToAnchor(
            forwardCf,
            forwardCf.Position,
            SPAWN_FORWARD_RADIUS,
            plot
        ) == true
    end

    local centerCf = M.GetGardenCenterCFrame(plot) or spawnCf
    if not centerCf then return false end
    if _atCenter(hrp.Position, centerCf) then
        return false
    end
    _publishGuardStatus("Hold Center")
    return _tryTeleportToAnchor(centerCf, centerCf.Position, CENTER_RADIUS, plot) == true
end

local function _tick(myId)
    myId = myId or loopId
    if tickBusy then return false end
    if not _anyFeatureOn() or _hardSuppressed() then return false end
    if _loadingScreenActive() then return false end
    if not M.IsGameReady() then return false end

    -- Guard & Hit WW boleh paralel dengan Auto Steal.
    -- Steal hanya blok Fire("Garden") via _bringViaGardenButton.
    local guardOn = _enabled() == true
    local hitWwOn = _hitWwEnabled()
    if not guardOn and not hitWwOn then return false end

    tickBusy = true
    local acted = false
    local useWwPoll = false
    local ok, err = pcall(function()
        local plot = M.GetPlayerPlot()

        if guardOn and _plotRuntimeReady() then
            if not plot then
                _publishGuardStatus("No plot")
            else
                -- Tetap rescue void (helper lama)
                if _rescueIfFallen(plot) then
                    acted = true
                    return
                end

                local intruders = _findIntruders(plot)
                if #intruders > 0 then
                    local target = intruders[1]
                    local did, why = _chaseIntruder(target)
                    if why == "left_garden" or why == "self_outside" then
                        if lastGuardTargetName then
                            _unequipShovel()
                            lastGuardTargetName = nil
                        end
                        if _holdHomePosition(plot) then
                            acted = true
                        end
                        return
                    end
                    acted = did == true or why == "hit" or why == "chase"
                    return
                end
            end
        end

        if hitWwOn then
            local did, why = _hitWerewolfTick()
            if why == "already_ww" then
                -- Stop chase + unequip. Pulang garden:
                --   - Auto Guard ON → hold seperti biasa
                --   - Auto Guard OFF → pulang SEKALI saat dapat role, lalu biarkan jalan manual
                _stopHitWwPosLock()
                _unequipShovel()
                lastGuardTargetName = nil
                hitWwCurrentUid = nil
                plot = plot or M.GetPlayerPlot()

                if guardOn then
                    if plot and _holdHomePosition(plot) then
                        acted = true
                        _publishGuardStatus("HIT WW · @ garden (guard)")
                    else
                        local loc = _cfg().selectedLocation
                        _publishGuardStatus(loc == "spawn" and "HIT WW · @ Spawn" or "HIT WW · @ Center")
                    end
                    return
                end

                if not hitWwHomeOnceDone then
                    hitWwHomeOnceDone = true
                    if plot and _holdHomePosition(plot) then
                        acted = true
                        _publishGuardStatus("HIT WW · pulang garden (sekali)")
                    else
                        _publishGuardStatus("HIT WW · sudah werewolf")
                    end
                    return
                end

                -- Guard OFF + sudah pernah pulang → jangan paksa balik lagi
                _publishGuardStatus("HIT WW · sudah werewolf (bebas)")
                return
            end
            if why == "hit" or why == "hit_wait" or why == "cd" or why == "far" or why == "retarget" or did == true then
                acted = true
                useWwPoll = true
                return
            end
            -- empty / not_night / no_shovel / no_remote → fall through ke hold
        end

        if lastGuardTargetName and not hitWwOn then
            _unequipShovel()
            lastGuardTargetName = nil
        end

        -- Hold home hanya kalau Guard ON
        if guardOn and plot then
            if lastGuardTargetName then
                _unequipShovel()
                lastGuardTargetName = nil
            end
            if _holdHomePosition(plot) then
                acted = true
            else
                local loc = _cfg().selectedLocation
                _publishGuardStatus(loc == "spawn" and "Guard @ Spawn" or "Guard @ Center")
            end
        elseif hitWwOn and not acted then
            -- status sudah di-set oleh _hitWerewolfTick (tunggu malam / no werewolf)
        end
    end)
    tickBusy = false
    if not ok then
        _publishGuardStatus("Error · " .. tostring(err))
        return false
    end
    return acted, useWwPoll
end

local function _loop(myId)
    _publishGuardStatus("Waiting loading...")
    if not _waitForBootReady(myId) then
        while running and loopId == myId do
            if _loadingScreenActive() then
                _publishGuardStatus("Waiting loading...")
            elseif not M.IsGameReady() then
                _publishGuardStatus("Waiting game ready...")
            else
                break
            end
            task.wait(0.35)
        end
        if not (running and loopId == myId) then return end
        if not M.IsGameReady() then return end
    end

    _ensureShovelNet()
    _ensureWerewolfNetWatch()
    _publishGuardStatus("Guard ready")

    while running and loopId == myId do
        local ok = pcall(function()
            -- Hard suppress (buy/claim) blokir semua.
            -- Steal busy: loop tetap jalan supaya Hit WW bisa TP+hit.
            if _anyFeatureOn() and not _hardSuppressed() then
                if _loadingScreenActive() then
                    _publishGuardStatus("Waiting loading...")
                    task.wait(0.35)
                elseif M.IsGameReady() then
                    local acted, useWwPoll = _tick(myId)
                    if acted then
                        task.wait(useWwPoll and HIT_WW_SCAN or GUARD_CHASE_POLL)
                    else
                        task.wait(math.max(MIN_DELAY, _cfg().delay))
                    end
                else
                    task.wait(0.35)
                end
            else
                task.wait(0.5)
            end
        end)
        if not ok then
            task.wait(0.5)
        end
    end
end

function M.GetGuardStatus()
    return lastGuardStatus
end

function M.EnsureRunning()
    if not _anyFeatureOn() then return end
    if not running then
        M.Start()
    end
end

function M.GetDelay()
    return _cfg().delay
end
M.getDelay = M.GetDelay

function M.SetDelay(sec)
    local d = tonumber(sec)
    if not d or d <= 0 then d = DEFAULT_DELAY end
    if d < MIN_DELAY then d = MIN_DELAY end

    local store = _store()
    if type(store) ~= "table" then
        store = { enabled = _enabled(), delay = d, selectedLocation = "center", hitWerewolf = _hitWwEnabled() }
    else
        store.delay = d
        store.mode = nil
    end
    G.__GAG2_AUTO_TELE = store
    _G.__GAG2_AUTO_TELE = store

    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.auto = MAIN.auto or {}
        MAIN.auto.autoTele = MAIN.auto.autoTele or {}
        MAIN.auto.autoTele.delay = d
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end
    return d
end
M.setDelay = M.SetDelay

function M.InvalidateCache()
    cachedPlot = nil
    cachedGardenCf = nil
    _clearGeoCache()
end
M.invalidateCache = M.InvalidateCache

function M.Start()
    if not _anyFeatureOn() then return end
    if running then return end
    -- Bersihkan SUPPRESS sisa PauseAutoTele / steal lama biar Guard hidup lagi
    M.ClearSuppress()
    local Move = _getMove()
    if type(Move) == "table" and type(Move.IsAutoTelePaused) == "function" then
        local okP, paused = pcall(Move.IsAutoTelePaused)
        if okP and paused == true and type(Move.ResumeAutoTele) == "function" then
            -- drain pauseDepth sisa steal/buy
            for _ = 1, 8 do
                pcall(Move.ResumeAutoTele)
                local ok2, still = pcall(Move.IsAutoTelePaused)
                if not (ok2 and still) then break end
            end
        end
    end
    if type(Move) == "table" and type(Move.StopGroundGuard) == "function" then
        pcall(Move.StopGroundGuard)
    end
    if type(Move) == "table" and type(Move.SetNoclip) == "function" then
        pcall(Move.SetNoclip, false)
    end
    running = true
    loopId = loopId + 1
    local myId = loopId
    task.spawn(_loop, myId)
end
M.start = M.Start

function M.Stop()
    running = false
    loopId = loopId + 1
    lastGuardTargetName = nil
    hitWwCurrentUid = nil
    _stopHitWwPosLock()
    _resetHitWwNightState()
    _unbindWerewolfAttrWatch()
    _unbindWerewolfNetWatch()
    _publishGuardStatus("Stopped")
end
M.stop = M.Stop

function M.IsRunning()
    return running == true
end

function M.IsEnabled()
    return _enabled()
end
M.isEnabled = M.IsEnabled

function M.IsHitWerewolfEnabled()
    return _hitWwEnabled()
end
M.isHitWerewolfEnabled = M.IsHitWerewolfEnabled

function M.ApplyRuntime(on)
    if on == nil then on = _enabled() end
    on = _truthy(on)
    _writeEnabled(on)
    if _anyFeatureOn() then
        M.ClearSuppress()
        if running then M.Stop() end
        M.Start()
    else
        M.Stop()
        M.ClearSuppress()
        _unequipShovel()
    end
    return on
end
M.applyRuntime = M.ApplyRuntime

function M.SetEnabled(on)
    return M.ApplyRuntime(on)
end
M.setEnabled = M.SetEnabled

function M.ApplyHitWerewolf(on)
    if on == nil then on = _hitWwEnabled() end
    on = _truthy(on)
    _writeHitWerewolf(on)
    if _anyFeatureOn() then
        M.ClearSuppress()
        if not running then
            M.Start()
        end
    else
        M.Stop()
        M.ClearSuppress()
        _unequipShovel()
    end
    return on
end
M.applyHitWerewolf = M.ApplyHitWerewolf

function M.SetHitWerewolf(on)
    return M.ApplyHitWerewolf(on)
end
M.setHitWerewolf = M.SetHitWerewolf

function M.GoHomeOnce()
    if _loadingScreenActive() then return false end
    if not M.IsGameReady() then return false end
    if not _plotRuntimeReady() then return false end
    local plot = M.GetPlayerPlot()
    if not plot then return false end

    local spawnPart, spawnCf = _getPlotSpawnTarget(plot)
    if not spawnCf then return false end

    local cfg = _cfg()
    if cfg.selectedLocation == "spawn" then
        local forwardCf = _spawnForwardCFrame(spawnCf, plot)
        local targetCf = forwardCf or spawnCf
        local anchor = targetCf.Position
        local radius = forwardCf and SPAWN_FORWARD_RADIUS or SPAWN_RADIUS
        return _tryTeleportToAnchor(targetCf, anchor, radius, plot)
    end

    local centerCf = M.GetGardenCenterCFrame(plot) or spawnCf
    return _tryTeleportToAnchor(centerCf, centerCf.Position, CENTER_RADIUS, plot)
end
M.goHomeOnce = M.GoHomeOnce

function M.TeleportNow()
    if _suppressed() or not _plotRuntimeReady() then return false end
    return M.GoHomeOnce()
end

function M.SyncFromState()
    M.InvalidateCache()
    M.EnsureRunning()
end

M.SyncFromGlobals = M.SyncFromState

-- watchdog: hanya hidupkan loop kalau mati (tidak bypass delay UI)
task.defer(function()
    while true do
        task.wait(1.5)
        -- Steal busy bukan alasan matiin Hit WW — boleh Start ulang
        if _anyFeatureOn() and not running and not _hardSuppressed() and not _buyPetBusy() and not _claimSeedBusy() then
            M.Start()
        end
    end
end)

G.AutoTele = M
G.AutoTeleModule = M
G.AutoGuard = M
G.AutoGuardModule = M
_G.AutoTele = M
_G.AutoTeleModule = M
_G.AutoGuard = M
_G.AutoGuardModule = M

if LP then
    pcall(function()
        LP:GetAttributeChangedSignal("PlotId"):Connect(function()
            _invalidatePlotCache()
        end)
    end)

    pcall(function()
        LP.CharacterAdded:Connect(function()
            _invalidatePlotCache()
        end)
    end)
end

task.defer(function()
    if _anyFeatureOn() then
        M.EnsureRunning()
    end
end)

return M
 end,                       required = false },
    { key = "AutoFallHarvest",         name = "Auto Teleport Ghoul Garden", factory = function() -- AutoFallHarvest.lua
-- Toggle ON: delay 10s → travel event world (Ghoul Garden). Sudah di target → diam.
-- Manual test: _G.AutoFallHarvest.Travel()
-- Save key tetap fall_harvest / AUTO_FALL_HARVEST_ENABLED (toggle lama).

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local WORLD = "GhoulGarden"
local DELAY = 10
-- PlaceId terpisah: Main garden vs event world
local GHOUL_PLACE_IDS = {
    [102868797705537] = true, -- GhoulGarden
    [136420110879676] = true, -- GhoulGardenBotUser
}
local MAIN_PLACE_IDS = {
    [97598239454123] = true,  -- Main
    [73504898027860] = true,  -- Main
}

local running = false
local loopId  = 0

local function enabled()
    if AUTO_FALL_HARVEST_ENABLED == true then return true end
    return G.AUTO_FALL_HARVEST_ENABLED == true
        or rawget(_G, "AUTO_FALL_HARVEST_ENABLED") == true
end

local function req(name)
    local ok, mod = pcall(function()
        return require(ReplicatedStorage.SharedModules[name])
    end)
    return ok and mod or nil
end

local function exec(name)
    local ge = (getgenv and getgenv()) or _G
    if type(ge[name]) == "function" then return ge[name] end
    return rawget(_G, name)
end

function M.GetCurrentWorldId()
    local Worlds = req("Worlds")
    if type(Worlds) == "table" then
        local id = Worlds.CurrentId or Worlds.CurrentWorld
        if type(Worlds.GetCurrentId) == "function" then
            local ok, v = pcall(Worlds.GetCurrentId, Worlds)
            if ok then id = v end
        end
        if type(id) == "string" and id ~= "" then
            return id
        end
    end
    local lp = LP or Players.LocalPlayer
    if lp then
        for _, a in ipairs({ "CurrentWorld", "WorldId", "World", "ActiveWorld" }) do
            local v = lp:GetAttribute(a)
            if type(v) == "string" and v ~= "" then return v end
        end
    end
    return nil
end

function M.GetTargetWorldId()
    local Worlds = req("Worlds")
    if type(Worlds) == "table" and type(Worlds.GetTravelTargets) == "function" then
        local ok, targets = pcall(Worlds.GetTravelTargets, Worlds)
        if ok and type(targets) == "table" then
            for _, t in ipairs(targets) do
                local id = type(t) == "table" and tostring(t.Id or "")
                if id ~= "" and string.lower(id):find("ghoul", 1, true) then
                    return id
                end
            end
        end
    end
    return WORLD
end

function M.IsInGhoulGarden()
    if GHOUL_PLACE_IDS[game.PlaceId] == true then
        return true
    end
    local id = M.GetCurrentWorldId()
    if type(id) ~= "string" then return false end
    local low = string.lower(id)
    return low == "ghoulgarden" or low:find("ghoul", 1, true) ~= nil
end

function M.IsInEventWorld()
    return M.IsInGhoulGarden()
end

function M.IsInMainGarden()
    if MAIN_PLACE_IDS[game.PlaceId] == true then
        return true
    end
    local id = M.GetCurrentWorldId()
    return type(id) == "string" and string.lower(id) == "main"
end

local function fire(node, arg)
    if node == nil then return false end
    local ok = pcall(function()
        if type(node.Fire) == "function" then
            node:Fire(arg)
        elseif type(node.FireServer) == "function" then
            node:FireServer(arg)
        else
            error("nofire")
        end
    end)
    return ok
end

local function travelPaused()
    if G.__GAG2_REJOIN_IN_FLIGHT == true then return true end
    if G.__GAG2_PAUSE_WORLD_TRAVEL == true then return true end
    local PR = G.PSReconnect or rawget(_G, "PSReconnect")
    if type(PR) == "table" and type(PR.IsRejoinInFlight) == "function" then
        local ok, v = pcall(PR.IsRejoinInFlight, PR)
        if ok and v == true then return true end
    end
    return false
end

local function clickEventGui()
    local lp = LP or Players.LocalPlayer
    local pg = lp and lp:FindFirstChild("PlayerGui")
    if not pg then return false end
    local fs, gc = exec("firesignal"), exec("getconnections")
    local hit = false
    for _, d in ipairs(pg:GetDescendants()) do
        if d:IsA("TextLabel") or d:IsA("TextButton") then
            local t = string.lower(tostring(d.Text or ""))
            if t:find("ghoul", 1, true) then
                local btn = d:IsA("GuiButton") and d or d:FindFirstAncestorWhichIsA("GuiButton")
                if btn then
                    if type(fs) == "function" then
                        pcall(fs, btn.Activated)
                        pcall(fs, btn.MouseButton1Click)
                    end
                    if type(gc) == "function" then
                        for _, sig in ipairs({ btn.MouseButton1Click, btn.Activated }) do
                            for _, c in ipairs(gc(sig) or {}) do
                                pcall(function()
                                    if c.Fire then c:Fire()
                                    elseif c.Function then c.Function() end
                                end)
                            end
                        end
                    end
                    pcall(function() btn:Activate() end)
                    hit = true
                end
            end
        end
    end
    return hit
end

local function openAndClick()
    local lp = LP or Players.LocalPlayer
    local ok, ctrl = pcall(function()
        return require(lp.PlayerScripts.Controllers.EventWorldsTeleporterController)
    end)
    if not ok or type(ctrl) ~= "table" then
        return false
    end
    for _, n in ipairs({ "Travel", "RequestTravel", "GoTo", "Teleport", "Select" }) do
        if type(ctrl[n]) == "function" then
            if pcall(ctrl[n], ctrl, M.GetTargetWorldId()) or pcall(ctrl[n], M.GetTargetWorldId()) then
                return true
            end
        end
    end
    if type(ctrl.Open) == "function" then
        pcall(ctrl.Open, ctrl, function() end)
        task.wait(0.45)
        if clickEventGui() then
            return true
        end
    end
    return false
end

local function fireEthan()
    local stand = workspace:FindFirstChild("ExplorerStand")
        or workspace:FindFirstChild("ExplorerStand", true)
    if not stand then return false end
    local prompt = stand:FindFirstChildWhichIsA("ProximityPrompt", true)
    if not prompt then return false end

    local lp = LP or Players.LocalPlayer
    local gc = exec("getconnections")
    if type(gc) == "function" then
        for _, c in ipairs(gc(prompt.Triggered) or {}) do
            pcall(function()
                if c.Fire then c:Fire()
                elseif c.Function then c.Function(lp) end
            end)
        end
    else
        local fpp = exec("fireproximityprompt")
        if type(fpp) == "function" then
            pcall(fpp, prompt)
        else
            return false
        end
    end
    task.wait(0.7)
    return openAndClick() or clickEventGui()
end

function M.Travel()
    if travelPaused() then
        return false
    end
    if M.IsInGhoulGarden() then
        return true
    end

    for _ = 1, 40 do
        local char = LP and LP.Character
        if char and char:FindFirstChild("HumanoidRootPart") then
            break
        end
        task.wait(0.25)
    end

    local worldId = M.GetTargetWorldId()

    local Worlds = req("Worlds")
    if type(Worlds) == "table" then
        for _, n in ipairs({ "RequestTravel", "Travel", "TravelTo", "GoTo" }) do
            if type(Worlds[n]) == "function" then
                if pcall(Worlds[n], Worlds, worldId) or pcall(Worlds[n], worldId) then
                    return true
                end
            end
        end
    end

    local Net = req("Networking")
    if type(Net) == "table" then
        local nodes = {
            Net.Worlds and Net.Worlds.RequestTravel,
            Net.Worlds and Net.Worlds.Travel,
            Net.EventWorlds and Net.EventWorlds.RequestTravel,
            Net.EventWorlds and Net.EventWorlds.Travel,
            Net.EventWorldTeleporter and Net.EventWorldTeleporter.Request,
            Net.TeleportButton and Net.TeleportButton.Request,
            Net.TeleportButtonRequest,
            Net.RequestTravel,
        }
        for _, node in ipairs(nodes) do
            if fire(node, worldId) then
                return true
            end
        end
        for k1, v1 in pairs(Net) do
            local n1 = string.lower(tostring(k1))
            if n1:find("world", 1, true) or n1:find("travel", 1, true) or n1:find("event", 1, true) then
                if fire(v1, worldId) then
                    return true
                end
                if type(v1) == "table" then
                    for k2, v2 in pairs(v1) do
                        local n2 = string.lower(tostring(k2))
                        if n2:find("travel", 1, true) or n2:find("request", 1, true) then
                            if fire(v2, worldId) then
                                return true
                            end
                        end
                    end
                end
            end
        end
    end

    if openAndClick() then return true end
    if fireEthan() then return true end
    if clickEventGui() then
        return true
    end

    return false
end

local function waitSec(sec)
    local t0 = os.clock()
    while os.clock() - t0 < sec do
        if not running or not enabled() then return false end
        if M.IsInGhoulGarden() then return true end
        task.wait(0.2)
    end
    return enabled() and running
end

local function loop(myId)
    while running and loopId == myId and enabled() do
        if travelPaused() then
            task.wait(1)
        elseif M.IsInGhoulGarden() then
            task.wait(2)
        else
            if not waitSec(DELAY) then break end
            if travelPaused() then
                -- skip
            elseif not M.IsInGhoulGarden() then
                M.Travel()
                task.wait(5)
            end
        end
    end
    if loopId == myId then
        running = false
    end
end

function M.Start()
    if not enabled() then
        running = false
        return
    end
    loopId += 1
    running = true
    local id = loopId
    task.spawn(function()
        loop(id)
    end)
end

function M.Stop()
    running = false
    loopId += 1
end

function M.SetEnabled(a, b)
    local on = a
    if type(a) == "table" then
        on = b
    end
    on = (on == true)
    AUTO_FALL_HARVEST_ENABLED = on
    G.AUTO_FALL_HARVEST_ENABLED = on
    _G.AUTO_FALL_HARVEST_ENABLED = on
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.rejoin = MAIN.misc.rejoin or {}
        MAIN.misc.rejoin.fall_harvest = on
        MAIN.auto = MAIN.auto or {}
        MAIN.auto.fallHarvest = type(MAIN.auto.fallHarvest) == "table" and MAIN.auto.fallHarvest or {}
        MAIN.auto.fallHarvest.enabled = on
        if MAIN.auto.fallHarvest.delay == nil then
            MAIN.auto.fallHarvest.delay = 10
        end
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end
    if on then M.Start() else M.Stop() end
end

function M.SyncFromGlobals()
    if enabled() then M.Start() else M.Stop() end
end

G.AutoFallHarvest = M
_G.AutoFallHarvest = M
G.AutoFallHarvestModule = M
_G.AutoFallHarvestModule = M
G.__GAG2_SYNC_AUTO_FALL_HARVEST = M.SyncFromGlobals
_G.__GAG2_SYNC_AUTO_FALL_HARVEST = M.SyncFromGlobals

task.defer(function()
    if enabled() then
        M.Start()
    end
end)

return M
 end,              required = false },
    { key = "AutoClaimSeed",           name = "Auto Claim Seed",         factory = function() -- AutoClaimSeed.lua - Grow A Garden 2
