    SELL_ARRIVE = 28,
    AFTER_TP_SEC = 0.02,
    AFTER_CLAIM_RESCAN = 0.1,
    APPROACH_NEAR_SKIP = 70, -- sudah dekat seed → skip Sell TP
    VERIFY_WAIT = 0.2,
    VERIFY_WAIT_FAST = 0.08,
    CLAIM_COMPLETE_WAIT = 14,
    CLAIM_VERDICT_WAIT = 0.75,
    CLAIM_POLL_SEC = 0.06,
    OPEN_UI_WAIT = 0.18,
    OPEN_UI_POLL = 0.03,
    OPEN_PROMPT_FIND_WAIT = 0.08,
    OPEN_PROMPT_RETRY_SEC = 0.14,
    OPEN_PROMPT_RETRIES = 4,
    VERIFY_POLL = 0.03,
    CLICK_NEAR_DIST = 50,
    BURST_FIRE_GAP = 0,
    LOST_CLAIM_COOLDOWN = 2.5,
    NEARER_SWITCH_STUDS = 5,
    NEARER_CHECK_SEC = 0.45,
    PROMPT_CACHE_SEC = 0.55,
    SAME_SEED_RETRY_WAIT = 0.12,
    SESSION_END_RESCAN = 0.2,
    ALLOW_NEARER_PREEMPT = false,
    SPAWN_CTRL_NAME = "SpawnSeedPackController",
    TP_OFFSET = Vector3.new(0, 3, 0),
}

-- Idle scan: jangan Heartbeat tiap frame (itu spike CPU utama saat claim ON)

-- false = jangan pindah seed sebelum claim sukses / hilang / diambil orang

-- Argumen fire yang terbukti kerja (slot index / UUID / Instance) — dipakai dulu
local preferredFireKind = nil -- "slot" | "uuid" | "instance" | "name"

local running       = false
local loopId        = 0
local claimBusy     = false
local spawnFolder   = nil
local childConn     = nil
local attrConns     = {}
local mapConn       = nil
local fxConn        = nil
local claimedConn   = nil
local claimCooldown = {}
local savedGardenCf = nil
local lastScanInfo  = { count = 0, ready = 0, at = 0 }
local lastFxAt      = 0
local lastFxPos     = nil
local lastClaimedAt = 0
local lastClaimedId = nil
local lastClaimedSeedName = nil
local lastClaimedByUs = false
local claimAttemptStartedAt = 0
local inFlightClaims = {}
local seedPackEffectMod = nil
local teleWasOn = false
local telePaused = false
local spawnCtrl = nil
local spawnCtrlHooked = false
local seedBoolAttrOrder = nil
local gameValidatedSpawns = {}
local seedsFolderWired = false
-- Forward decls: _onGameSpawnClient runs before these are assigned (Lua local scope)
local _prefireRemote
local _queueClaimSession
-- Urutan bool seed di SpawnClient game (decompile) — hanya anchor; sisanya dari Assets.Seeds
local GAME_BOOL_SEED_PRIORITY = { "RainbowSeed", "GoldSeed", "MegaSeed" }

local stats = {
    attempts = 0,
    fired = 0,
    remoteOk = 0,
    teleports = 0,
    clickOk = 0,
    prefire = 0,
    skipped = {},
    lastResult = nil,
    lastSkip = nil,
    lastError = nil,
    lastClaimId = nil,
    lastMethod = nil,
    falseOk = 0,
    lastMs = nil,
}

local function _skip(reason)
    stats.lastSkip = reason
    stats.skipped[reason] = (stats.skipped[reason] or 0) + 1
end

local function _getLP()
    local lp = LP or Players.LocalPlayer
    if lp then LP = lp end
    return lp
end

local function _isLocalPlayerClaim(id)
    local lp = _getLP()
    if not lp or id == nil then return false end
    local s = tostring(id)
    if s == lp.Name then return true end
    if s == tostring(lp.UserId) then return true end
    local n = tonumber(s)
    return n ~= nil and n == lp.UserId
end

local function _getHRP()
    local lp = _getLP()
    if not lp then return nil end
    local char = lp.Character
    if not char then return nil end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp and hrp:IsA("BasePart") then return hrp end
    return nil
end

local function _enabled()
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" and type(MAIN.auto) == "table"
        and type(MAIN.auto.claimSeed) == "table" then
        return MAIN.auto.claimSeed.enabled == true
    end
    local store = G.__GAG2_CLAIM_SEED or rawget(_G, "__GAG2_CLAIM_SEED")
    if type(store) == "table" then
        return store.enabled == true
    end
    return G.AUTO_CLAIM_SEED_ENABLED == true or rawget(_G, "AUTO_CLAIM_SEED_ENABLED") == true
end

local function _writeEnabled(on)
    on = (on == true)
    if type(G.__GAG2_CLAIM_SEED) ~= "table" then G.__GAG2_CLAIM_SEED = {} end
    G.__GAG2_CLAIM_SEED.enabled = on
    _G.__GAG2_CLAIM_SEED = G.__GAG2_CLAIM_SEED
    G.AUTO_CLAIM_SEED_ENABLED = on
    _G.AUTO_CLAIM_SEED_ENABLED = on
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.auto = MAIN.auto or {}
        MAIN.auto.claimSeed = MAIN.auto.claimSeed or {}
        MAIN.auto.claimSeed.enabled = on
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end
    return on
end

local function _dbg(...)
    if G.AUTO_CLAIM_SEED_DEBUG ~= true and rawget(_G, "AUTO_CLAIM_SEED_DEBUG") ~= true then
        return
    end
    warn("[GAG2-ClaimSeed]", ...)
end

local function _dbgSkip(reason, extra)
    _skip(reason)
    if extra ~= nil then
        _dbg("skip:", reason, extra)
    else
        _dbg("skip:", reason)
    end
end

local function _findRemote(net, names)
    if type(net) ~= "table" then return nil end
    for _, name in ipairs(names) do
        local r = net[name]
        if r then
            if type(r.Fire) == "function" or type(r.FireServer) == "function"
                or type(r.InvokeServer) == "function" then
                return r, name
            end
        end
    end
    return nil
end

local function _initRemotes()
    if remotesReady and (ClickPack or OpenSeedPack) then return true end

    local ok, Networking = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules", 10):WaitForChild("Networking", 10))
    end)
    if not ok or type(Networking) ~= "table" then
        stats.lastError = "Networking require gagal"
        remotesReady = false
        return false
    end

    local SeedNet = Networking.SeedPack or Networking.Seedpack or Networking.SeedPacks
    ClickPack, remotePath = _findRemote(SeedNet, { "ClickPack", "ClickSeedPack", "Click" })
    if not ClickPack then
        ClickPack, remotePath = _findRemote(Networking, { "ClickSeedPack", "ClickPack" })
        if ClickPack then remotePath = "Networking." .. tostring(remotePath) end
    else
        remotePath = "Networking.SeedPack." .. tostring(remotePath)
    end

    -- Alternate remote (beberapa build pakai OpenSeedPack)
    if type(SeedNet) == "table" then
        OpenSeedPack = select(1, _findRemote(SeedNet, { "OpenSeedPack", "OpenPack", "Open" }))
    end

    local SpawnNet = Networking.SeedPackSpawn or Networking.SeedpackSpawn
    if type(SpawnNet) == "table" then
        SeedPackFX = SpawnNet.FX
        if not claimedConn and SpawnNet.Claimed and SpawnNet.Claimed.OnClientEvent then
            claimedConn = SpawnNet.Claimed.OnClientEvent:Connect(function(id, seedName)
                lastClaimedAt = os.clock()
                lastClaimedId = id ~= nil and tostring(id) or nil
                lastClaimedSeedName = seedName ~= nil and tostring(seedName) or nil
                lastClaimedByUs = _isLocalPlayerClaim(id)
            end)
        end
    end

    remotesReady = ClickPack ~= nil or OpenSeedPack ~= nil
    if not remotesReady then
        stats.lastError = "ClickPack/OpenSeedPack MISSING"
    end
    return remotesReady
end

local function _getMap()
    return workspace:FindFirstChild("Map")
end

local function _getSpawnFolder()
    if spawnFolder and spawnFolder.Parent then return spawnFolder end
    local map = _getMap()
    if not map then return nil end
    spawnFolder = map:FindFirstChild("SeedPackSpawnServerLocations")
        or map:WaitForChild("SeedPackSpawnServerLocations", 2)
    return spawnFolder
end

local function _truthy(v)
    return v == true or v == 1 or v == "true" or v == "1"
end

local function _getSpawnAttr(inst, name)
    if not inst then return nil end
    local v = inst:GetAttribute(name)
    if v ~= nil then return v end
    return nil
end

local function _getAssetsSeedsFolder()
    local assets = ReplicatedStorage:FindFirstChild("Assets")
    return assets and assets:FindFirstChild("Seeds")
end

local function _refreshSeedBoolAttrOrder()
    local out = {}
    local seen = {}
    for _, attr in ipairs(GAME_BOOL_SEED_PRIORITY) do
        out[#out + 1] = attr
        seen[attr] = true
    end
    local seeds = _getAssetsSeedsFolder()
    if seeds then
        for _, ch in ipairs(seeds:GetChildren()) do
            local attr = ch.Name .. "Seed"
            if not seen[attr] then
                seen[attr] = true
                out[#out + 1] = attr
            end
        end
    end
    seedBoolAttrOrder = out
    if not seedsFolderWired and seeds then
        seedsFolderWired = true
        seeds.ChildAdded:Connect(function()
            _refreshSeedBoolAttrOrder()
        end)
    end
    return out
end

local function _getSeedBoolAttrOrder()
    if not seedBoolAttrOrder then
        _refreshSeedBoolAttrOrder()
    end
    return seedBoolAttrOrder
end

local function _getWatchAttrNames(inst)
    local names = { "SeedPack" }
    local seen = { SeedPack = true }
    for _, attr in ipairs(_getSeedBoolAttrOrder()) do
        if not seen[attr] then
            seen[attr] = true
            names[#names + 1] = attr
        end
    end
    if inst then
        for name in pairs(inst:GetAttributes()) do
            if not seen[name] and name ~= "SeedPack" and name:sub(-4) == "Seed" then
                seen[name] = true
                names[#names + 1] = name
            end
        end
    end
    return names
end

local function _boolSeedActive(inst, attr)
    return inst and inst:GetAttribute(attr) == true
end

local function _resolveSpawnInfo(inst, packHint)
    if not inst then return "unknown", "Normal" end
    local cached = gameValidatedSpawns[inst]
    if type(cached) == "table" and cached.label then
        return cached.label, cached.packName or "Normal"
    end

    local pack = inst:GetAttribute("SeedPack")
    if type(pack) ~= "string" then pack = packHint end
    if type(pack) ~= "string" then pack = nil end

    for _, attr in ipairs(_getSeedBoolAttrOrder()) do
        if _boolSeedActive(inst, attr) then
            local base = attr:gsub("Seed$", "")
            return base .. " Seed", base
        end
    end
    for name, val in pairs(inst:GetAttributes()) do
        if name ~= "SeedPack" and name:sub(-4) == "Seed" and val == true then
            local base = name:gsub("Seed$", "")
            return base .. " Seed", base
        end
    end
    if type(pack) == "string" and pack ~= "" then return pack, pack end
    return inst.Name or "unknown", "Normal"
end

local function _spawnHasAttrs(inst)
    if not inst or not inst.Parent then return false end
    if gameValidatedSpawns[inst] then return true end
    local packName = inst:GetAttribute("SeedPack")
    if type(packName) == "string" and packName ~= "" then return true end
    for _, attr in ipairs(_getSeedBoolAttrOrder()) do
        if _boolSeedActive(inst, attr) then return true end
    end
    for name, val in pairs(inst:GetAttributes()) do
        if name ~= "SeedPack" and name:sub(-4) == "Seed" and val == true then
            return true
        end
    end
    return false
end

local function _waitSpawnReady(inst)
    if not inst or not inst.Parent then return false end
    if _spawnHasAttrs(inst) then return true end
    local deadline = os.clock() + CFG.ATTR_WAIT_SEC
    while inst.Parent and os.clock() < deadline do
        if _spawnHasAttrs(inst) then return true end
        local woke = false
        for _, attr in ipairs(_getWatchAttrNames(inst)) do
            local ok = pcall(function()
                inst:GetAttributeChangedSignal(attr):Wait()
            end)
            if ok then woke = true break end
        end
        if not woke then task.wait(CFG.ATTR_POLL_SEC) end
    end
    return _spawnHasAttrs(inst)
end

local function _partCFrame(inst)
    if not inst then return nil end
    if inst:IsA("BasePart") then return inst.CFrame end
    if inst:IsA("Model") then
        local ok, cf = pcall(function() return inst:GetPivot() end)
        if ok and typeof(cf) == "CFrame" then return cf end
        local part = inst:FindFirstChildWhichIsA("BasePart", true)
        if part then return part.CFrame end
    end
    return nil
end

local function _spawnPosition(inst)
    local cf = _partCFrame(inst)
    return cf and cf.Position or nil
end

local function _childWorldPos(obj)
    if not obj then return nil end
    if obj:IsA("BasePart") then return obj.Position end
    if obj:IsA("Model") then
        local pp = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
        if pp then return pp.Position end
    end
    return nil
end

local function _partWorldPos(inst)
    if not inst then return nil end
    local pos = _spawnPosition(inst)
    if pos then return pos end
    return _childWorldPos(inst)
end

local function _spawnLabel(inst)
    return select(1, _resolveSpawnInfo(inst))
end

local function _findSpawnSeedPackControllerModule()
    local lp = _getLP()
    local roots = {}
    if lp then
        local scripts = lp:FindFirstChild("PlayerScripts")
        local controllers = scripts and scripts:FindFirstChild("Controllers")
        if controllers then roots[#roots + 1] = controllers end
    end
    local starter = game:GetService("StarterPlayer")
    local starterScripts = starter and starter:FindFirstChild("StarterPlayerScripts")
    local starterControllers = starterScripts and starterScripts:FindFirstChild("Controllers")
    if starterControllers then roots[#roots + 1] = starterControllers end

    for _, controllers in ipairs(roots) do
        local modInst = controllers:FindFirstChild(CFG.SPAWN_CTRL_NAME)
        if modInst then return modInst end
    end
    return nil
end

local function _getSpawnSeedPackController()
    if spawnCtrl == false then return nil end
    if type(spawnCtrl) == "table" then return spawnCtrl end

    local modInst = _findSpawnSeedPackControllerModule()
    if not modInst then
        return nil
    end
    local ok, result = pcall(require, modInst)
    if ok and type(result) == "table" then
        spawnCtrl = result
        return spawnCtrl
    end
    spawnCtrl = false
    return nil
end

local function _trackGameValidatedSpawn(serverPart, packHint)
    if not serverPart then return end
    local label, packName = _resolveSpawnInfo(serverPart, packHint)
    gameValidatedSpawns[serverPart] = {
        label = label,
        packName = packName,
        at = os.clock(),
    }
    pcall(function()
        serverPart.Destroying:Connect(function()
            gameValidatedSpawns[serverPart] = nil
        end)
    end)
end

local function _onGameSpawnClient(serverPart, packHint)
    if not serverPart or not serverPart.Parent then return end
    _trackGameValidatedSpawn(serverPart, packHint)
    if not _enabled() or not _spawnHasAttrs(serverPart) then return end
    task.defer(function()
        if not serverPart.Parent or not _enabled() then return end
        _prefireRemote(serverPart, "spawn_client")
        _queueClaimSession("spawn_client")
    end)
end

local function _hookSpawnSeedPackController()
    if spawnCtrlHooked then return true end
    _refreshSeedBoolAttrOrder()

    local ctrl = _getSpawnSeedPackController()
    if not ctrl or type(ctrl.SpawnClient) ~= "function" then
        return false
    end
    if ctrl.__GAG2_ClaimSeedSpawnHook then
        spawnCtrlHooked = true
        return true
    end

    local origSpawnClient = ctrl.SpawnClient
    ctrl.SpawnClient = function(self, serverPart, packHint, ...)
        local ret = origSpawnClient(self, serverPart, packHint, ...)
        pcall(_onGameSpawnClient, serverPart, packHint)
        return ret
    end
    ctrl.__GAG2_ClaimSeedSpawnHook = true
    spawnCtrlHooked = true
    _dbg("SpawnSeedPackController hooked")
    return true
end

local function _ensureSpawnSeedPackController()
    if _hookSpawnSeedPackController() then return true end
    task.spawn(function()
        for _ = 1, 45 do
            if _hookSpawnSeedPackController() then return end
            task.wait(1)
        end
    end)
    return false
end

local function _folderSpawnRoot(inst)
    local folder = _getSpawnFolder()
    if not folder or not inst then return inst end
    local node = inst
    while node and node.Parent and node.Parent ~= folder do
        node = node.Parent
    end
    if node and node.Parent == folder then return node end
    return inst
end

local function _globalSpawnIndex(inst)
    local folder = _getSpawnFolder()
    if not folder then return nil end
    local root = _folderSpawnRoot(inst)
    for i, ch in ipairs(folder:GetChildren()) do
        if ch == root then return tostring(i) end
    end
    return nil
end

local function _findClientSpawnNear(inst)
    local pos = _spawnPosition(inst)
    if not pos then return nil end
    local map = _getMap()
    local client = map and map:FindFirstChild("SeedPackSpawnClient")
    if not client then return nil end
    local best, bestD = nil, 10
    for _, ch in ipairs(client:GetChildren()) do
        local p = _childWorldPos(ch)
        if p then
            local d = (p - pos).Magnitude
            if d < bestD then
                best = ch
                bestD = d
            end
        end
    end
    return best
end

local function _getClaimIds(inst)
    local out = {}
    local seen = {}
    local function add(v)
        if v == nil then return end
        if typeof(v) == "Instance" then return end
        v = tostring(v)
        if v == "" or seen[v] then return end
        if v == "Part" or v == "Model" then return end
        seen[v] = true
        out[#out + 1] = v
    end

    -- Urutan GAG2 lama yang sering benar: slot folder dulu, baru attr UUID/id
    -- (tiap seed beda ID — BUKAN satu ID untuk semua seed)
    add(_globalSpawnIndex(inst))
    if inst and inst.Parent then
        for i, ch in ipairs(inst.Parent:GetChildren()) do
            if ch == inst then add(tostring(i)) break end
        end
    end
    add(_getSpawnAttr(inst, "SpawnId"))
    add(_getSpawnAttr(inst, "Id"))
    add(_getSpawnAttr(inst, "UUID"))
    add(_getSpawnAttr(inst, "Guid"))
    add(_getSpawnAttr(inst, "GUID"))
    add(_getSpawnAttr(inst, "SlotId"))
    add(_getSpawnAttr(inst, "Slot"))
    add(_getSpawnAttr(inst, "Index"))
    add(_getSpawnAttr(inst, "PackId"))
    add(_getSpawnAttr(inst, "SeedPackId"))

    if inst and inst.Name ~= "Part" and inst.Name ~= "Model" then
        add(inst.Name)
    end

    return out
end

local function _primaryClaimId(inst)
    local ids = _getClaimIds(inst)
    return ids[1]
end

local function _classifyFireArg(arg)
    if typeof(arg) == "Instance" then return "instance" end
    local s = tostring(arg or "")
    if s == "" then return nil end
    -- UUID-like
    if #s >= 8 and s:find("%-") then return "uuid" end
    if tonumber(s) ~= nil then return "slot" end
    return "name"
end

local function _rememberWorkingFire(arg)
    local kind = _classifyFireArg(arg)
    if kind then
        preferredFireKind = kind
        stats.lastMethod = (stats.lastMethod or "") .. "|pref=" .. kind
    end
end

-- Argumen Fire untuk 1 seed (unik per spawn). Jangan spam semua jenis tiap tick.
-- full=true → coba slot+uuid (+ Instance sekali). full=false → cuma kandidat utama.
local function _getClaimFireArgs(inst, full)
    local args = {}
    local seen = {}
    local function add(v)
        if v == nil then return end
        local key
        if typeof(v) == "Instance" then
            key = "inst:" .. tostring(v)
        else
            key = "s:" .. tostring(v)
        end
        if seen[key] then return end
        seen[key] = true
        args[#args + 1] = v
    end

    local ids = _getClaimIds(inst)
    local slot = _globalSpawnIndex(inst)
    local uuid = _getSpawnAttr(inst, "UUID") or _getSpawnAttr(inst, "Guid") or _getSpawnAttr(inst, "GUID")
    local spawnId = _getSpawnAttr(inst, "SpawnId") or _getSpawnAttr(inst, "Id")

    local function addPreferred()
        if preferredFireKind == "instance" then
            add(inst)
            local root = _folderSpawnRoot(inst)
            if root and root ~= inst then add(root) end
        elseif preferredFireKind == "uuid" then
            add(uuid)
            add(spawnId)
            add(slot)
        elseif preferredFireKind == "name" then
            if inst then add(inst.Name) end
            add(slot)
            add(spawnId)
        else
            -- default / slot: index folder (paling umum GAG2)
            add(slot)
            add(spawnId)
            add(uuid)
        end
    end

    addPreferred()

    if full then
        -- Backup: sisa string id
        for _, id in ipairs(ids) do
            add(id)
            local n = tonumber(id)
            if n ~= nil then add(n) end
        end
        -- Instance terakhir (beberapa executor ok, server kadang tolak)
        if preferredFireKind ~= "instance" then
            add(inst)
            local root = _folderSpawnRoot(inst)
            if root and root ~= inst then add(root) end
        end
    else
        -- Tick ringan: max 3 kandidat
        while #args > 3 do
            table.remove(args)
        end
    end

    return args
end

local function _distToSpawn(inst)
    local hrp = _getHRP()
    local pos = _partWorldPos(inst) or _spawnPosition(inst)
    if not hrp or not pos then return nil end
    -- XZ saja: nearest dari posisi player saat ini (abaikan beda Y layer)
    local d = hrp.Position - pos
    return Vector3.new(d.X, 0, d.Z).Magnitude
end

local function _distToGarden(inst)
    local pos = _partWorldPos(inst) or _spawnPosition(inst)
    if not pos then return nil end
    local gardenPos = nil
    if savedGardenCf then
        gardenPos = savedGardenCf.Position
    else
        local Move = G.Move or G.MoveModule or rawget(_G, "Move") or rawget(_G, "MoveModule")
        if type(Move) == "table" and type(Move.GetGardenCFrame) == "function" then
            local ok, cf = pcall(Move.GetGardenCFrame)
            if ok and typeof(cf) == "CFrame" then
                gardenPos = cf.Position
                savedGardenCf = cf
            end
        end
    end
    if not gardenPos then return nil end
    return (gardenPos - pos).Magnitude
end

local function _spawnTrackKey(inst)
    if not inst then return nil end
    local id = _getSpawnAttr(inst, "SpawnId") or _getSpawnAttr(inst, "Id")
        or _getSpawnAttr(inst, "UUID") or _getSpawnAttr(inst, "SlotId")
    if id ~= nil then return "id:" .. tostring(id) end
    local gidx = _globalSpawnIndex(inst)
    if gidx then return "slot:" .. gidx end
    local pos = _spawnPosition(inst)
    if pos then
        return string.format("p:%.1f,%.1f,%.1f", pos.X, pos.Y, pos.Z)
    end
    return tostring(inst)
end

local function _claimedDuringAttempt()
    return lastClaimedAt >= claimAttemptStartedAt - 0.02
end

local function _normalizeSeedKey(s)
    if s == nil then return nil end
    s = tostring(s):lower():gsub("%s+", ""):gsub("_", "")
    s = s:gsub("seed$", "")
    if s == "" or s == "nil" then return nil end
    return s
end

local function _spawnSeedKeys(inst)
    local keys = {}
    local function add(v)
        local k = _normalizeSeedKey(v)
        if k then keys[k] = true end
    end
    if not inst then return keys end
    local label, pack = _resolveSpawnInfo(inst)
    add(label)
    add(pack)
    add(_getSpawnAttr(inst, "SeedPack"))
    for _, attr in ipairs(_getSeedBoolAttrOrder()) do
        if _boolSeedActive(inst, attr) then
            add(attr)
            add(attr:gsub("Seed$", ""))
        end
    end
    for name, val in pairs(inst:GetAttributes()) do
        if name ~= "SeedPack" and name:sub(-4) == "Seed" and val == true then
            add(name)
            add(name:gsub("Seed$", ""))
        end
    end
    return keys
end

-- Claimed event seed lain JANGAN dianggap won/lost untuk target saat ini
local function _eventMatchesSpawn(inst)
    if not inst then return false end
    local eventKey = _normalizeSeedKey(lastClaimedSeedName)
    if not eventKey then
        return false
    end
    local keys = _spawnSeedKeys(inst)
    return keys[eventKey] == true
end

local function _weWonClaim(inst)
    if not lastClaimedByUs or not _claimedDuringAttempt() then
        return false
    end
    if not inst then return true end
    if _eventMatchesSpawn(inst) then return true end
    -- Kita yang claim + pack target hilang → sukses (nama event sering beda)
    if not inst.Parent or not _spawnHasAttrs(inst) then
        return true
    end
    return false
end

local function _otherWonClaim(inst)
    if lastClaimedByUs or not _claimedDuringAttempt() then
        return false
    end
    if not inst then return true end
    if _eventMatchesSpawn(inst) then return true end
    -- Player lain claim + seed target hilang → lost
    if not inst.Parent or not _spawnHasAttrs(inst) then
        return true
    end
    return false
end

local function _claimLock(inst)
    local key = _spawnTrackKey(inst)
    if not key or inFlightClaims[key] then return false, key end
    inFlightClaims[key] = true
    return true, key
end

local function _claimUnlock(key)
    if key then inFlightClaims[key] = nil end
end

local function _shouldPrefire(dist)
    return dist == nil or dist <= CFG.PREFIRE_MAX_DIST
end

----------------------------------------------------------------
-- Move helpers (global module/Move.lua) — pola sama AutoBuyPet
----------------------------------------------------------------
local function _move()
    return G.Move or G.MoveModule or rawget(_G, "Move") or rawget(_G, "MoveModule")
end

local function _getMoveMode()
    local Move = _move()
    if type(Move) == "table" and type(Move.GetMode) == "function" then
        local ok, mode = pcall(Move.GetMode)
        if ok and type(mode) == "string" and mode ~= "" then
            return mode
        end
    end
    return tostring(G.MOVE_MODE or rawget(_G, "MOVE_MODE") or "walk"):lower()
end

local function _getGardenCFrame()
    local Move = _move()
    if type(Move) == "table" and type(Move.GetGardenCFrame) == "function" then
        return Move.GetGardenCFrame()
    end
    return nil
end

local function _setNoclip(on)
    local Move = _move()
    if type(Move) == "table" and type(Move.SetNoclip) == "function" then
        pcall(Move.SetNoclip, on == true)
    end
end

local function _dist3(a, b)
    local Move = _move()
    if type(Move) == "table" and type(Move.Distance) == "function" then
        return Move.Distance(a, b)
    end
    if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then return math.huge end
    return (a - b).Magnitude
end

local function _getSellPos()
    local Move = _move()
    if type(Move) == "table" and type(Move.GetSellPos) == "function" then
        return Move.GetSellPos()
    end
    return nil
end

-- opts.fineTune=true → center/spawn (Auto Tele home). Default: Garden button saja.
local function _tpToGarden(opts)
    opts = type(opts) == "table" and opts or {}
    local Move = _move()
    local ok = false
    if type(Move) == "table" and type(Move.ToGarden) == "function" then
        ok = select(1, Move.ToGarden({
            mode = opts.mode or "hard",
            wait = CFG.GARDEN_WAIT,
            fineTune = opts.fineTune == true,
            reason = opts.reason or "claim_seed",
        })) == true
    end
    if ok then
        savedGardenCf = _getGardenCFrame()
        _dbg("tp garden ok")
    else
        _dbg("tp garden fail")
    end
    return ok
end

local function _flatDist3(a, b)
    if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then return math.huge end
    return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
end

local function _tpToSell()
    local Move = _move()
    if type(Move) == "table" and type(Move.ToSell) == "function" then
        local ok = select(1, Move.ToSell({
            mode = "hard",
            arrive = CFG.SELL_ARRIVE,
            wait = CFG.SELL_WAIT,
            reason = "claim_seed",
        })) == true
        _dbg(ok and "tp sell ok" or "tp sell fail")
        return ok
    end
    _dbg("tp sell fail | Move missing")
    return false
end

-- Bandingkan seed→player vs seed→Sell (XZ).
-- Sell lebih dekat → Fire Teleport Sell. Player lebih dekat / sudah dekat → langsung seed.
-- JANGAN TP garden di sini (garden hanya di akhir session kalau Auto Tele ON).
local function _approachBeforeClaim(inst)
    local seedPos = inst and _partWorldPos(inst)
    local hrp = _getHRP()
    local playerPos = hrp and hrp.Position
    local sellPos = _getSellPos()

    if not seedPos or not playerPos then
        _dbg("tp approach=direct (fallback)")
        return "direct"
    end

    local dPlayer = _flatDist3(seedPos, playerPos)
    local dSell = sellPos and _flatDist3(seedPos, sellPos) or math.huge
    _dbg(string.format(
        "approach compare seed→player=%.0f seed→sell=%.0f",
        dPlayer,
        dSell
    ))

    -- Sudah dekat seed dari posisi sekarang → langsung claim
    if dPlayer <= CFG.APPROACH_NEAR_SKIP then
        _dbg("tp approach=direct (near seed)")
        return "direct"
    end

    -- Seed lebih dekat ke Sell daripada ke player → Fire Sell dulu
    if sellPos and dSell + 1 < dPlayer then
        if _tpToSell() then
            _dbg("tp approach=sell")
            return "sell"
        end
        _dbg("tp approach=direct (sell failed)")
        return "direct"
    end

    _dbg("tp approach=direct (player closer)")
    return "direct"
end

local function _teleStopForClaim()
    local Move = _move()
    if type(Move) ~= "table" then
        teleWasOn = false
        telePaused = false
        return
    end
    -- Sudah di-pause (session lanjut / leftover) → jangan Pause lagi (depth++)
    if telePaused or (type(Move.IsAutoTelePaused) == "function" and Move.IsAutoTelePaused()) then
        teleWasOn = true
        telePaused = true
        if type(Move.KeepAutoTelePaused) == "function" then
            pcall(Move.KeepAutoTelePaused)
        end
        _dbg("tele keep paused for claim")
        return
    end
    if type(Move.PauseAutoTele) == "function" then
        teleWasOn = Move.PauseAutoTele("claim") == true
        telePaused = Move.IsAutoTelePaused and Move.IsAutoTelePaused() or teleWasOn
        _dbg(teleWasOn and "tele paused for claim" or "tele pause skip (auto tele off)")
        return
    end
    teleWasOn = false
    telePaused = false
end

local function _teleKeepPaused()
    if not teleWasOn then return end
    telePaused = true
    local Move = _move()
    if type(Move) == "table" and type(Move.KeepAutoTelePaused) == "function" then
        pcall(Move.KeepAutoTelePaused)
    end
end

local function _teleResumeNow()
    telePaused = false
    teleWasOn = false
    local Move = _move()
    if type(Move) == "table" and type(Move.ResumeAutoTele) == "function" then
        pcall(Move.ResumeAutoTele)
    end
end

local function _seedStandCFrame(inst)
    local pos = _partWorldPos(inst)
    local hrp = _getHRP()
    if not pos or not hrp then return nil, nil end
    local standY = hrp.Position.Y
    local stand = Vector3.new(pos.X, standY, pos.Z)
    if CFG.TP_STAND_DIST > 0.05 then
        local flat = Vector3.new(pos.X - hrp.Position.X, 0, pos.Z - hrp.Position.Z)
        if flat.Magnitude > 0.05 then
            local offset = pos - flat.Unit * CFG.TP_STAND_DIST
            stand = Vector3.new(offset.X, standY, offset.Z)
        end
    end
    return CFrame.lookAt(stand, pos), pos
end

local function _inClaimRange(inst)
    local hrp = _getHRP()
    local pos = inst and _partWorldPos(inst)
    if not hrp or typeof(pos) ~= "Vector3" then return false end
    return _dist3(hrp.Position, pos) <= CFG.CLAIM_RANGE
end

local function _seedStillClaimable(inst)
    if not inst or not inst.Parent then return false end
    if not _spawnHasAttrs(inst) then return false end
    local folder = _getSpawnFolder()
    if folder and inst.Parent ~= folder then return false end
    return true
end

-- Ke seed: Character Move Mode. Batalkan travel kalau seed hilang (diambil orang lain).
local function _goToSeed(inst)
    if not _seedStillClaimable(inst) then
        return false, "gone"
    end
    local cf = _seedStandCFrame(inst)
    if not cf then return false, "no_cf" end
    -- Stand tetap (XZ seed) — jangan ikut HRP tiap frame di liveGoal (bikin soft loop)
    local standPos = cf.Position
    local lookPos = select(2, _seedStandCFrame(inst)) or standPos
    local Move = _move()
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false, "no_move"
    end
    local ok, msg = Move.GoTo(cf, {
        mode = _getMoveMode(),
        reason = "claim_seed",
        liveGoal = function()
            if not _seedStillClaimable(inst) then
                return false -- batalkan travel
            end
            -- Tetap XZ seed awal; Y ikut kaki sekarang (walk)
            local hrp = _getHRP()
            local y = hrp and hrp.Position.Y or standPos.Y
            local stand = Vector3.new(standPos.X, y, standPos.Z)
            local look = typeof(lookPos) == "Vector3" and lookPos or stand
            return CFrame.lookAt(stand, Vector3.new(look.X, y, look.Z))
        end,
    })
    if msg == "cancelled" then
        return false, "gone"
    end
    if ok then stats.teleports = stats.teleports + 1 end
    return ok == true, msg
end

local function _stickAtSeed(inst)
    _teleKeepPaused()
    if not inst then return false end
    if not _seedStillClaimable(inst) then return false end
    if _inClaimRange(inst) then return true end
    local ok, why = _goToSeed(inst)
    if why == "gone" then return false end
    return ok == true
end

local function _waitClaimVerdict(maxWait, inst)
    maxWait = tonumber(maxWait) or 0.1
    local deadline = os.clock() + maxWait
    while os.clock() < deadline do
        if not inst or not inst.Parent then
            break
        end
        if _seedStillClaimable(inst) then
            _teleKeepPaused()
        end
        if _weWonClaim(inst) then return true, "claimed_event" end
        if _otherWonClaim(inst) then return false, "lost_to_other" end
        if not _seedStillClaimable(inst) then
            if _weWonClaim(inst) then return true, "claimed_event" end
            if _otherWonClaim(inst) then return false, "lost_to_other" end
            return false, "spawn_gone"
        end
        task.wait(CFG.VERIFY_POLL)
    end
    if _weWonClaim(inst) then return true, "claimed_event" end
    if _otherWonClaim(inst) then return false, "lost_to_other" end
    if not _seedStillClaimable(inst) then return false, "spawn_gone" end
    return nil, nil
end

local function _standCFrame(inst)
    local cf = _partCFrame(inst)
    if not cf then return nil end
    local seedPos = cf.Position
    local standPos = seedPos
    if CFG.TP_STAND_DIST > 0.05 then
        local hrp = _getHRP()
        local flat = Vector3.new(0, 0, -1)
        if hrp then
            flat = seedPos - hrp.Position
            flat = Vector3.new(flat.X, 0, flat.Z)
        end
        if flat.Magnitude < 0.05 then
            flat = Vector3.new(0, 0, -1)
        else
            flat = flat.Unit
        end
        standPos = seedPos - flat * CFG.TP_STAND_DIST
    end
    standPos = standPos + Vector3.new(0, CFG.TP_OFFSET.Y, 0)
    return CFrame.new(standPos, seedPos)
end

local function _canClaim(inst)
    local untilAt = claimCooldown[inst]
    return not (untilAt and os.clock() < untilAt)
end

local function _markClaimed(inst, sec)
    claimCooldown[inst] = os.clock() + (tonumber(sec) or CFG.CLAIM_COOLDOWN)
end

local function _getClickFn()
    if type(fireclickdetector) == "function" then return fireclickdetector end
    if type(rawget(_G, "fireclickdetector")) == "function" then return rawget(_G, "fireclickdetector") end
    return nil
end

local function _getPromptFn()
    if type(fireproximityprompt) == "function" then return fireproximityprompt end
    if type(rawget(_G, "fireproximityprompt")) == "function" then return rawget(_G, "fireproximityprompt") end
    return nil
end

local function _getSeedPackEffect()
    if seedPackEffectMod == false then return nil end
    if seedPackEffectMod then return seedPackEffectMod end
    local lp = _getLP()
    local controllers = lp and lp:FindFirstChild("PlayerScripts")
    controllers = controllers and controllers:FindFirstChild("Controllers")
    if not controllers then seedPackEffectMod = false return nil end

    local tryPaths = {
        { "SeedPackController", "SeedPackEffect" },
        { "SeedPackController", "SeedPackOpen" },
    }
    for _, path in ipairs(tryPaths) do
        local node = controllers
        for _, name in ipairs(path) do
            node = node and node:FindFirstChild(name)
        end
        if node then
            local ok, mod = pcall(require, node)
            if ok and type(mod) == "table" and type(mod.Open) == "function" then
                seedPackEffectMod = mod
                return mod
            end
        end
    end
    seedPackEffectMod = false
    return nil
end

local function _triggerGameOpen(inst)
    local effect = _getSeedPackEffect()
    if not effect then return false end
    local hrp = _getHRP()
    local spawnCf = _partCFrame(inst)
    if not hrp or not spawnCf then return false end

    local label, packName = _resolveSpawnInfo(inst)

    local seedPos = _partWorldPos(inst)
    local stickPos = seedPos
        and Vector3.new(seedPos.X, hrp.Position.Y, seedPos.Z)
        or hrp.Position
    local ok = pcall(function()
        effect.Open(inst.Name, packName, label, stickPos, spawnCf)
    end)
    return ok
end

local function _findClickDetectorNear(nearPos)
    if not nearPos then return nil end
    local roots = {}
    local temp = workspace:FindFirstChild("Temporary")
    if temp then roots[#roots + 1] = temp end
    local map = _getMap()
    if map then
        local client = map:FindFirstChild("SeedPackSpawnClient")
        if client then roots[#roots + 1] = client end
    end

    local best, bestDist = nil, CFG.CLICK_NEAR_DIST
    for _, root in ipairs(roots) do
        for _, obj in ipairs(root:GetDescendants()) do
            if obj:IsA("ClickDetector") then
                local pos = _childWorldPos(obj.Parent) or _childWorldPos(obj:FindFirstAncestorOfClass("Model"))
                if pos then
                    local d = (pos - nearPos).Magnitude
                    if d <= bestDist then
                        best = obj
                        bestDist = d
                    end
                end
            end
        end
    end
    return best
end

local function _findProximityPromptNear(nearPos)
    if not nearPos then return nil end
    local roots = {}
    local map = _getMap()
    if map then
        local client = map:FindFirstChild("SeedPackSpawnClient")
        if client then roots[#roots + 1] = client end
    end
    local folder = _getSpawnFolder()
    if folder then roots[#roots + 1] = folder end

    local best, bestDist = nil, CFG.CLICK_NEAR_DIST
    for _, root in ipairs(roots) do
        for _, obj in ipairs(root:GetDescendants()) do
            if obj:IsA("ProximityPrompt") then
                local pos = _childWorldPos(obj.Parent)
                if pos then
                    local d = (pos - nearPos).Magnitude
                    if d <= bestDist then
                        best = obj
                        bestDist = d
                    end
                end
            end
        end
    end
    return best
end

-- Cache prompt/click per seed — hindari GetDescendants tiap FOLLOW_FIRE tick
local _interactCache = {} -- [inst] = { at=, pp=, cd= }
local function _cachedInteractNear(inst, nearPos)
    if not inst or typeof(nearPos) ~= "Vector3" then return nil, nil end
    local now = os.clock()
    local c = _interactCache[inst]
    if c and (now - c.at) < CFG.PROMPT_CACHE_SEC then
        local pp = c.pp
        local cd = c.cd
        if pp and (not pp.Parent) then pp = nil end
        if cd and (not cd.Parent) then cd = nil end
        if pp or cd then
            return pp, cd
        end
    end
    local pp = _findProximityPromptNear(nearPos)
    local cd = _findClickDetectorNear(nearPos)
    _interactCache[inst] = { at = now, pp = pp, cd = cd }
    return pp, cd
end

local function _clearInteractCache(inst)
    if inst then
        _interactCache[inst] = nil
    else
        table.clear(_interactCache)
    end
end

local function _fireClickDetector(cd)
    if not cd then return false end
    local lp = _getLP()
    local fn = _getClickFn()
    local ok = false
    if fn and lp then
        ok = pcall(fn, cd, 0, lp)
        if ok then
            stats.clickOk = stats.clickOk + 1
            stats.lastMethod = "ClickDetector"
        end
    end
    return ok
end

local function _fireProximityPromptAuto(pp)
    if not pp then return false end
    local fired = false
    local oldHold = nil
    pcall(function()
        pp.Enabled = true
        oldHold = pp.HoldDuration
        pp.HoldDuration = 0
    end)

    local fn = _getPromptFn()
    if fn then
        local ok = pcall(fn, pp)
        if ok then fired = true end
    end

    if type(getconnections) == "function" then
        pcall(function()
            for _, c in ipairs(getconnections(pp.Triggered)) do
                pcall(function()
                    c:Fire(_getLP())
                end)
                fired = true
            end
        end)
    end

    if oldHold ~= nil then
        pcall(function()
            pp.HoldDuration = oldHold
        end)
    end
    return fired
end

local function _fireProximityPromptManual(pp)
    if not pp then return false end
    local oldHold = nil
    pcall(function()
        pp.Enabled = true
        oldHold = pp.HoldDuration
        pp.HoldDuration = 0
    end)

    pcall(function()
        pp:InputHoldBegin()
    end)
    task.wait(0.03)
    pcall(function()
        pp:InputHoldEnd()
    end)

    if oldHold ~= nil then
        pcall(function()
            pp.HoldDuration = oldHold
        end)
    end
    return true
end

-- Prompt auto (fireproximityprompt / connections) + prompt manual (InputHold)
local function _fireProximityPrompt(pp)
    if not pp then return false end
    local a = _fireProximityPromptAuto(pp)
    local b = _fireProximityPromptManual(pp)
    if a or b then
        stats.lastMethod = "ProximityPrompt"
        return true
    end
    return false
end

local function _waitOpenUiClickDetector(inst, onPoll)
    local pos = _partWorldPos(inst)
    if not pos then return nil end
    local deadline = os.clock() + CFG.OPEN_UI_WAIT
    while inst.Parent and os.clock() < deadline do
        _stickAtSeed(inst)
        local cd = _findClickDetectorNear(pos)
        if cd then return cd end
        if type(onPoll) == "function" then onPoll() end
        task.wait(CFG.OPEN_UI_POLL)
    end
    return _findClickDetectorNear(pos)
end

local function _fxNearSpawn(inst)
    if not lastFxPos or lastFxAt < claimAttemptStartedAt - 0.05 then return false end
    local pos = _spawnPosition(inst)
    if not pos then return false end
    return (lastFxPos - pos).Magnitude <= 12
end

local function _packStillActive(inst)
    if not inst or not inst.Parent then return false end
    local folder = _getSpawnFolder()
    if folder and inst.Parent ~= folder then return false end
    return _spawnHasAttrs(inst)
end

local function _resetClaimAttempt()
    claimAttemptStartedAt = os.clock()
    lastClaimedByUs = false
end

local function _waitForClaimComplete(inst, maxWait)
    maxWait = tonumber(maxWait) or CFG.CLAIM_COMPLETE_WAIT
    local deadline = os.clock() + maxWait
    local lastFire = 0

    while running and _enabled() and os.clock() < deadline do
        _stickAtSeed(inst)
        if _weWonClaim(inst) then return true, "claimed_event" end
        if _otherWonClaim(inst) then return false, "lost_to_other" end

        local stillActive = inst and inst.Parent and _packStillActive(inst) and _spawnHasAttrs(inst)
        if not stillActive then
            local ok, reason = _waitClaimVerdict(CFG.CLAIM_VERDICT_WAIT, inst)
            if ok == true then return true, reason or "spawn_cleared" end
            if ok == false then return false, reason end
            if _weWonClaim(inst) then return true, "claimed_event_late" end
            if _otherWonClaim(inst) then return false, "lost_to_other" end
            task.wait(CFG.CLAIM_POLL_SEC)
        else
            if os.clock() - lastFire >= CFG.FOLLOW_FIRE_SEC then
                _fireClickPackBurst(inst, "wait_complete")
                lastFire = os.clock()
            end
            task.wait(CFG.CLAIM_POLL_SEC)
        end
    end

    if _weWonClaim(inst) then return true, "claimed_event_timeout" end
    if _otherWonClaim(inst) then return false, "lost_to_other" end
    return false, "claim_timeout"
end

local function _verifyClaimed(inst, nearPos, tag, maxWait)
    maxWait = tonumber(maxWait) or CFG.VERIFY_WAIT
    local deadline = os.clock() + maxWait
    while os.clock() < deadline do
        _stickAtSeed(inst)
        if _weWonClaim(inst) then return true, "claimed_event" end
        if _otherWonClaim(inst) then return false, "lost_to_other" end
        if _fxNearSpawn(inst) then
            local ok, reason = _waitClaimVerdict(0.35, inst)
            if ok == true then return true, "fx_event" end
            if ok == false then return false, reason end
        end
        if not _packStillActive(inst) then
            local ok, reason = _waitClaimVerdict(math.max(maxWait, 0.35), inst)
            if ok == true then return true, reason end
            if ok == false then return false, reason end
            return false, "spawn_gone_pending"
        end
        task.wait(CFG.VERIFY_POLL)
    end
    if _weWonClaim(inst) then return true, "claimed_event" end
    if _otherWonClaim(inst) then return false, "lost_to_other" end
    if _fxNearSpawn(inst) then
        local ok, reason = _waitClaimVerdict(0.3, inst)
        if ok == true then return true, "fx_event" end
        if ok == false then return false, reason end
    end
    if not _packStillActive(inst) then
        local ok, reason = _waitClaimVerdict(0.35, inst)
        if ok == true then return true, reason end
        if ok == false then return false, reason end
        return false, "spawn_gone_pending"
    end
    return false, nil
end

local function _fireRemoteOne(remote, id)
    if not remote or id == nil then return false, nil end
    local ok, err = false, nil
    local label = typeof(id) == "Instance" and id.Name or tostring(id)

    if type(remote.Fire) == "function" then
        ok, err = pcall(function() remote:Fire(id) end)
    end
    if not ok and type(remote.FireServer) == "function" then
        ok, err = pcall(function() remote:FireServer(id) end)
    end
    if not ok and type(remote.InvokeServer) == "function" then
        ok, err = pcall(function() remote:InvokeServer(id) end)
    end
    if ok then
        stats.remoteOk += 1
        stats.lastClaimId = label
        return true, label
    end
    stats.lastError = tostring(err)
    return false, nil
end

local function _fireClickPackOne(id, tag)
    local ok, label = _fireRemoteOne(ClickPack, id)
    if ok then return true, label end
    if OpenSeedPack then
        ok, label = _fireRemoteOne(OpenSeedPack, id)
        if ok then
            stats.lastMethod = "OpenSeedPack"
            return true, label
        end
    end
    return false, nil
end

local function _fireClickPackBurst(inst, tag, full)
    if (not ClickPack and not OpenSeedPack) or not inst then return {}, 0 end
    local firedIds = {}
    local seen = {}
    local lastArg = nil

    local function fireOne(id)
        if id == nil then return end
        local key = typeof(id) == "Instance" and ("i:" .. tostring(id)) or ("s:" .. tostring(id))
        if seen[key] then return end
        seen[key] = true
        local ok, label = _fireClickPackOne(id, tag)
        if ok then
            firedIds[#firedIds + 1] = label
            lastArg = id
        end
    end

    -- full=true hanya di perform/open; follow tick pakai kandidat utama saja
    local useFull = full == true or tag == "perform" or tag == "open" or tag == "burst"
        or tag == "burst_retry" or tag == "burst_final"
    for _, arg in ipairs(_getClaimFireArgs(inst, useFull)) do
        fireOne(arg)
    end

    if lastArg ~= nil then
        stats._lastFireArg = lastArg
    end
    return firedIds, #firedIds
end

-- Satu tick claim: Fire remote + prompt (hanya saat dalam range)
local function _claimFireAll(inst, tag)
    if not _seedStillClaimable(inst) then return false, "gone" end
    -- Jangan fire dari jauh — cuma hampiri tanpa claim
    if not _inClaimRange(inst) then
        return false, "out_of_range"
    end
    _initRemotes()
    local nearPos = _partWorldPos(inst)
    local fired = false

    local full = (tag == "perform" or tag == "open")
    local _, n = _fireClickPackBurst(inst, tag or "fire", full)
    if n and n > 0 then fired = true end

    if nearPos then
        local pp, cd = _cachedInteractNear(inst, nearPos)
        if pp and _fireProximityPrompt(pp) then
            fired = true
        end
        if cd and _fireClickDetector(cd) then
            fired = true
        end
    end

    -- Open UI game saat perform / full claim (spawn prompt)
    if full then
        pcall(_triggerGameOpen, inst)
        _clearInteractCache(inst)
    end

    return fired, fired and "fire_all" or "no_fire"
end

_prefireRemote = function(inst, tag)
    _initRemotes()
    if not ClickPack or not inst then return end
    stats.prefire = stats.prefire + 1
    _fireClickPackBurst(inst, tag or "prefire")
end

local function _claimSucceeded(inst, nearPos, method, maxWait)
    local ok, reason = _verifyClaimed(inst, nearPos, method, maxWait)
    if ok then
        stats.lastMethod = method .. ":" .. reason
        return true, method
    end
    if reason == "lost_to_other" then
        stats.lastMethod = method .. ":lost_to_other"
    end
    return false, reason
end

local function _tryOpenPromptClaim(inst, nearPos, tag)
    tag = tag or "open"
    _triggerGameOpen(inst)
    _fireClickPackBurst(inst, tag .. "_burst")

    local pp = nil
    local findDeadline = os.clock() + CFG.OPEN_PROMPT_FIND_WAIT
    while not pp and inst.Parent and os.clock() < findDeadline do
        _stickAtSeed(inst)
        pp = _findProximityPromptNear(nearPos)
        if not pp then task.wait(CFG.OPEN_UI_POLL) end
    end
    if not pp then pp = _findProximityPromptNear(nearPos) end
    if not pp then return false end

    local retryDeadline = os.clock() + CFG.OPEN_PROMPT_RETRY_SEC
    local attempt = 0
    while inst.Parent and os.clock() < retryDeadline and attempt < CFG.OPEN_PROMPT_RETRIES do
        attempt = attempt + 1
        _stickAtSeed(inst)
        _fireClickPackBurst(inst, tag .. "_r" .. attempt)
        if not _fireProximityPrompt(pp) then
            task.wait(CFG.OPEN_UI_POLL)
        else
            stats.lastClaimId = _primaryClaimId(inst)
            local remain = retryDeadline - os.clock()
            local maxW = (remain > CFG.VERIFY_WAIT_FAST + 0.01) and CFG.VERIFY_WAIT_FAST or math.min(CFG.VERIFY_WAIT, remain)
            local ok, reason = _claimSucceeded(inst, nearPos, "open_prompt", maxW)
            if ok then return true, "open_prompt" end
            if reason == "lost_to_other" then return false, "lost_to_other" end
        end
    end
    return false
end

local function _performClaim(inst)
    _initRemotes()
    if not inst then return false, nil, {} end

    local nearPos = _partWorldPos(inst)
    local t0 = os.clock()
    local steps = {}

    local function step(name, fn)
        local ts = os.clock()
        _stickAtSeed(inst)
        local ok, a, b = fn()
        steps[#steps + 1] = {
            step = name,
            ok = ok,
            ms = math.floor((os.clock() - ts) * 1000),
            extra = b or a,
        }
        return ok, a, b
    end

    step("fire_all", function()
        -- Fire remote + prompt auto + prompt manual
        local fired, why = _claimFireAll(inst, "perform")
        if why == "gone" then return false, "spawn_gone" end
        if not fired then return false end
        stats.lastClaimId = _primaryClaimId(inst)
        local ok, reason = _claimSucceeded(inst, nearPos, "fire_all", CFG.VERIFY_WAIT_FAST)
        if not ok and reason == "lost_to_other" then return false, "lost_to_other" end
        if not ok and reason == "spawn_gone" then return false, "spawn_gone" end
        return ok
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end
    if steps[#steps].extra == "lost_to_other" or steps[#steps].extra == "spawn_gone" then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return false, stats.lastMethod, steps
    end

    step("prompt_fast", function()
        local pp = _findProximityPromptNear(nearPos)
        if not pp then return false end
        _fireClickPackBurst(inst, "prompt_fast")
        _fireProximityPromptAuto(pp)
        _fireProximityPromptManual(pp)
        stats.lastClaimId = _primaryClaimId(inst)
        local ok, reason = _claimSucceeded(inst, nearPos, "prompt_fast", CFG.VERIFY_WAIT_FAST)
        if not ok and reason == "lost_to_other" then return false, "lost_to_other" end
        return ok
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end
    if steps[#steps].extra == "lost_to_other" then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return false, stats.lastMethod, steps
    end

    step("burst", function()
        local ids, n = _fireClickPackBurst(inst, "burst")
        if n <= 0 then return false end
        local ok, reason = _claimSucceeded(inst, nearPos, "burst", CFG.VERIFY_WAIT_FAST)
        if not ok and reason == "lost_to_other" then return false, "lost_to_other" end
        return ok
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end
    if steps[#steps].extra == "lost_to_other" then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return false, stats.lastMethod, steps
    end

    step("open_prompt", function()
        local ok, extra = _tryOpenPromptClaim(inst, nearPos, "fast")
        if not ok and extra == "lost_to_other" then return false, "lost_to_other" end
        return ok
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end
    if steps[#steps].extra == "lost_to_other" then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return false, stats.lastMethod, steps
    end

    step("burst_retry", function()
        local ids, n = _fireClickPackBurst(inst, "burst_retry")
        if n <= 0 then return false end
        local ok, reason = _claimSucceeded(inst, nearPos, "burst_retry")
        if not ok and reason == "lost_to_other" then return false, "lost_to_other" end
        return ok
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end
    if steps[#steps].extra == "lost_to_other" then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return false, stats.lastMethod, steps
    end

    step("clickdet", function()
        local cd = _findClickDetectorNear(nearPos)
        if not cd then
            cd = _waitOpenUiClickDetector(inst, function()
                _fireClickPackBurst(inst, "poll_burst")
            end)
        end
        if cd and _fireClickDetector(cd) then
            stats.lastClaimId = _primaryClaimId(inst)
            return _claimSucceeded(inst, nearPos, "ClickDetector")
        end
        return false
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end

    step("prompt_retry", function()
        local pp = _findProximityPromptNear(nearPos)
        if pp and _fireProximityPrompt(pp) then
            return _claimSucceeded(inst, nearPos, "ProximityPrompt")
        end
        return false
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end

    step("burst_final", function()
        _fireClickPackBurst(inst, "burst_final")
        return _claimSucceeded(inst, nearPos, "burst_final")
    end)
    if steps[#steps].ok then
        stats.lastMs = math.floor((os.clock() - t0) * 1000)
        return true, stats.lastMethod, steps
    end

    stats.lastMs = math.floor((os.clock() - t0) * 1000)
    return false, nil, steps
end

local function _collectSpawnEntries(folder)
    local out = {}
    if not folder then return out end
    for _, child in ipairs(folder:GetChildren()) do
        out[#out + 1] = child
    end
    return out
end

local function _countReadySpawns(folder)
    if not folder then return 0 end
    local n = 0
    for _, inst in ipairs(_collectSpawnEntries(folder)) do
        if _spawnHasAttrs(inst) and _canClaim(inst) then
            n += 1
        end
    end
    return n
end

local function _collectReadySpawns(folder)
    local out = {}
    if not folder then return out end
    for _, inst in ipairs(_collectSpawnEntries(folder)) do
        if _spawnHasAttrs(inst) and _canClaim(inst) then
            out[#out + 1] = inst
        end
    end
    return out
end

local function _pickNextReadySpawn(batch)
    if type(batch) ~= "table" or #batch == 0 then return nil end
    local best, bestD = nil, math.huge
    for i = 1, #batch do
        local inst = batch[i]
        if inst and inst.Parent then
            local d = _distToSpawn(inst)
            if d ~= nil and d < bestD then
                best = inst
                bestD = d
            elseif d == nil and best == nil then
                best = inst
            end
        end
    end
    return best
end

-- Seed lain yang jauh lebih dekat dari target saat ini (preempt)
local function _findNearerReadySpawn(folder, current, margin)
    margin = tonumber(margin) or CFG.NEARER_SWITCH_STUDS
    if not folder then return nil end
    local batch = _collectReadySpawns(folder)
    if #batch <= 1 then return nil end

    local dCur = current and _distToSpawn(current) or nil
    local gCur = current and _distToGarden(current) or nil
    local bestHrp, bestHrpD = nil, math.huge
    local bestGarden, bestGardenD = nil, math.huge

    for _, inst in ipairs(batch) do
        if inst and inst ~= current and inst.Parent then
            local d = _distToSpawn(inst)
            if d ~= nil and d < bestHrpD then
                bestHrp = inst
                bestHrpD = d
            end
            local g = _distToGarden(inst)
            if g ~= nil and g < bestGardenD then
                bestGarden = inst
                bestGardenD = g
            end
        end
    end

    -- Lebih dekat ke karakter
    if bestHrp and (dCur == nil or bestHrpD + 0.05 < (dCur - margin)) then
        return bestHrp
    end
    -- Seed baru dekat garden/base, target sekarang jauh dari garden
    if bestGarden and gCur ~= nil and bestGardenD < 55 and bestGardenD + margin < gCur then
        return bestGarden
    end
    return nil
end

local function _followClaimSeed(inst)
    if not inst or not inst.Parent or not _spawnHasAttrs(inst) then
        return false, "invalid"
    end

    local locked, lockKey = _claimLock(inst)
    if not locked then
        _dbgSkip("in_flight", inst.Name)
        return false, "in_flight"
    end

    stats.attempts += 1
    _resetClaimAttempt()
    local label = _spawnLabel(inst)
    _dbg("follow start:", label, inst.Name)
    local success = false
    local failReason = "claim_fail"
    local switchTarget = nil
    local t0 = os.clock()
    local folder = _getSpawnFolder()

    local okRun, errRun = pcall(function()
        -- Abort segera kalau seed hilang saat perjalanan
        local goOk, goWhy = _goToSeed(inst)
        if goWhy == "gone" or not _seedStillClaimable(inst) then
            local okV, reasonV = _waitClaimVerdict(CFG.CLAIM_VERDICT_WAIT, inst)
            if okV then
                success = true
                stats.lastResult = label .. " / " .. tostring(reasonV or "claimed_on_approach")
                stats.lastMethod = reasonV
            else
                failReason = reasonV or "spawn_gone"
            end
            return
        end
        if CFG.AFTER_TP_SEC > 0 then task.wait(CFG.AFTER_TP_SEC) end

        local lastFire = 0
        local lastFullClaim = 0
        local lastNearerCheck = 0

        while running and _enabled() and os.clock() - t0 < CFG.MAX_FOLLOW_SEC do
            -- Seed hilang / diambil orang lain → STOP travel, jangan lanjut ke lokasi kosong
            if not _seedStillClaimable(inst) then
                local ok, reason = _waitClaimVerdict(CFG.CLAIM_VERDICT_WAIT, inst)
                if ok then
                    success = true
                    stats.lastResult = label .. " / " .. tostring(reason or "cleared")
                    stats.lastMethod = reason
                else
                    failReason = reason or "spawn_gone"
                end
                break
            end

            if _otherWonClaim(inst) then
                failReason = "lost_to_other"
                break
            end
            if _weWonClaim(inst) then
                success = true
                stats.lastResult = label .. " / claimed_event"
                stats.lastMethod = "claimed_event"
                break
            end

            if not _inClaimRange(inst) then
                local moved, moveWhy = _goToSeed(inst)
                if moveWhy == "gone" or not _seedStillClaimable(inst) then
                    local okG, reasonG = _waitClaimVerdict(CFG.CLAIM_VERDICT_WAIT, inst)
                    if okG then
                        success = true
                        stats.lastResult = label .. " / " .. tostring(reasonG or "cleared")
                        stats.lastMethod = reasonG
                    else
                        failReason = reasonG or "spawn_gone"
                    end
                    break
                end
            else
                _teleKeepPaused()
            end

            -- Sticky: jangan pindah seed sebelum sukses (kecuali flag ON)
            if CFG.ALLOW_NEARER_PREEMPT and os.clock() - lastNearerCheck >= CFG.NEARER_CHECK_SEC then
                lastNearerCheck = os.clock()
                local nearer = _findNearerReadySpawn(folder, inst, CFG.NEARER_SWITCH_STUDS)
                if nearer then
                    failReason = "switch_nearer"
                    switchTarget = nearer
                    _dbg("follow switch nearer:", _spawnLabel(nearer), "from", label)
                    break
                end
            end

            local now = os.clock()
            -- Fire HANYA saat sudah dalam range (kalau masih jalan → cuma go)
            if _inClaimRange(inst) and now - lastFire >= CFG.FOLLOW_FIRE_SEC then
                lastFire = now
                _claimFireAll(inst, "follow_fire")
            end

            if _inClaimRange(inst) and now - lastFullClaim >= 0.55 then
                lastFullClaim = now
                local claimOk = false
                pcall(function()
                    claimOk = select(1, _performClaim(inst)) == true
                end)
                if claimOk or _weWonClaim(inst) then
                    if stats._lastFireArg ~= nil then
                        _rememberWorkingFire(stats._lastFireArg)
                    end
                    success = true
                    stats.lastResult = label .. " / " .. tostring(stats.lastMethod or "perform")
                    break
                end
                if _otherWonClaim(inst) then
                    failReason = "lost_to_other"
                    break
                end
                if not _seedStillClaimable(inst) then
                    failReason = "spawn_gone"
                    break
                end
            end

            if _weWonClaim(inst) then
                if stats._lastFireArg ~= nil then
                    _rememberWorkingFire(stats._lastFireArg)
                end
                success = true
                stats.lastResult = label .. " / claimed_event"
                stats.lastMethod = "claimed_event"
                break
            end

            task.wait(CFG.STICK_SEC)
        end

        if not success and failReason ~= "switch_nearer" and failReason ~= "lost_to_other"
            and failReason ~= "spawn_gone"
            and os.clock() - t0 >= CFG.MAX_FOLLOW_SEC then
            failReason = "follow_timeout"
            _skip("follow_timeout")
        end
    end)

    _claimUnlock(lockKey)
    if not okRun then
        stats.lastError = tostring(errRun)
        _dbg("follow error:", errRun)
        return false, "error", nil
    elseif success then
        _dbg("follow ok:", label, "ms=", math.floor((os.clock() - t0) * 1000))
        return true, "ok", nil
    else
        _dbg("follow fail:", label, failReason)
        return false, failReason, switchTarget
    end
end

local function _holdClaimMoveSession()
    local Move = _move()
    if type(Move) == "table" and type(Move.HoldSession) == "function" then
        pcall(Move.HoldSession, "claim_seed")
    end
end

local function _releaseClaimMoveSession()
    local Move = _move()
    if type(Move) == "table" and type(Move.ReleaseSession) == "function" then
        pcall(Move.ReleaseSession, "claim_seed")
    end
end

local function _processClaimSession(folder)
    if not folder or not _enabled() or claimBusy then
        return 0
    end
    if _countReadySpawns(folder) <= 0 then
        return 0
    end

    claimBusy = true
    G.__GAG2_AUTO_CLAIM_SEED_BUSY = true
    _G.__GAG2_AUTO_CLAIM_SEED_BUSY = true
    -- Hold sepanjang session: watering/modul prioritas lebih rendah tidak boleh nyerobot
    -- di sela GoTo (itu penyebab tele ke watering saat jalan ke seed).
    _holdClaimMoveSession()
    _dbg("session start | ready=", _countReadySpawns(folder))

    local claimed = 0
    local stickyInst = nil
    local approachedFor = nil
    local ok, err = pcall(function()
        _teleStopForClaim()

        while running and _enabled() do
            _holdClaimMoveSession() -- refresh hold tiap putaran
            -- Rescan dari posisi player saat ini (jangan pulang garden dulu)
            local batch = _collectReadySpawns(folder)
            if #batch == 0 then
                -- Seed attrs kadang delay hilang/muncul — tunggu sebentar lalu rescan
                task.wait(CFG.SESSION_END_RESCAN)
                batch = _collectReadySpawns(folder)
                if #batch == 0 then
                    _dbg("session no ready after rescan")
                    break
                end
            end

            local nearest = _pickNextReadySpawn(batch)
            local inst = nearest

            -- Sticky keras: jangan preempt ke seed lain sebelum target selesai
            if stickyInst and stickyInst.Parent and _spawnHasAttrs(stickyInst) and _canClaim(stickyInst) then
                local stillReady = false
                for _, sp in ipairs(batch) do
                    if sp == stickyInst then
                        stillReady = true
                        break
                    end
                end
                if stillReady then
                    inst = stickyInst
                elseif CFG.ALLOW_NEARER_PREEMPT then
                    local nearer = _findNearerReadySpawn(folder, stickyInst, CFG.NEARER_SWITCH_STUDS)
                    if nearer then
                        inst = nearer
                        _dbg("session preempt nearer:", _spawnLabel(nearer), "was", _spawnLabel(stickyInst))
                    end
                end
            end

            if not inst or not inst.Parent or not _spawnHasAttrs(inst) or not _canClaim(inst) then
                _dbg("session break | invalid spawn pick")
                break
            end

            stickyInst = inst

            -- Approach Sell/direct hanya saat ganti target (bukan tiap retry)
            if approachedFor ~= inst then
                if not _seedStillClaimable(inst) then
                    stickyInst = nil
                    approachedFor = nil
                    _dbgSkip("spawn_gone_before_approach", inst.Name)
                else
                    _approachBeforeClaim(inst)
                    -- Setelah approach, seed bisa sudah diambil orang lain
                    if not _seedStillClaimable(inst) then
                        stickyInst = nil
                        approachedFor = nil
                        _markClaimed(inst, 0.2)
                        _dbgSkip("spawn_gone_after_approach", inst.Name)
                    else
                        approachedFor = inst
                    end
                end
            end

            if not stickyInst or not _seedStillClaimable(inst) then
                -- Target invalid setelah approach — lanjut seed lain
            else
                local followOk, followReason, switchTo = _followClaimSeed(inst)
                if followOk then
                    claimed += 1
                    stats.fired += 1
                    _markClaimed(inst, CFG.CLAIM_COOLDOWN)
                    _dbg("session claimed:", _spawnLabel(inst), "total=", claimed,
                        "readyLeft=", _countReadySpawns(folder))
                    stickyInst = nil
                    approachedFor = nil
                    task.wait(CFG.AFTER_CLAIM_RESCAN)
                elseif followReason == "switch_nearer" then
                    if switchTo and switchTo.Parent and _spawnHasAttrs(switchTo) and _canClaim(switchTo) then
                        stickyInst = switchTo
                    else
                        stickyInst = nil
                    end
                    approachedFor = nil
                    _dbgSkip("switch_nearer", inst.Name)
                elseif followReason == "spawn_gone" or followReason == "lost_to_other" then
                    -- Seed diambil orang lain / hilang → segera ganti target terdekat
                    _markClaimed(inst, 0.2)
                    _dbgSkip(followReason, inst.Name)
                    stickyInst = nil
                    approachedFor = nil
                elseif _seedStillClaimable(inst) and _canClaim(inst) then
                    -- Belum sukses claim → JANGAN ditinggal; sticky retry
                    _dbgSkip("claim_retry_same", tostring(followReason or "fail") .. ":" .. tostring(inst.Name))
                    stickyInst = inst
                    task.wait(CFG.SAME_SEED_RETRY_WAIT)
                else
                    stickyInst = nil
                    approachedFor = nil
                    if inst then _markClaimed(inst, 0.25) end
                    _dbgSkip("claim_fail", inst and inst.Name or "?")
                end
            end
        end
    end)

    if not ok then
        stats.lastError = tostring(err)
        _dbg("session error:", err)
    end

    -- Habis seed baru pulang garden / resume Auto Tele
    local leftover = _countReadySpawns(folder)
    if leftover <= 0 then
        task.wait(CFG.SESSION_END_RESCAN)
        leftover = _countReadySpawns(folder)
    end

    if leftover > 0 and running and _enabled() then
        -- Masih ada seed — jangan garden / jangan resume / JANGAN lepas hold
        -- (watering tetap di-block sampai session berikutnya ambil alih)
        _dbg("session continue later | leftover=", leftover)
        claimBusy = false
        G.__GAG2_AUTO_CLAIM_SEED_BUSY = false
        _G.__GAG2_AUTO_CLAIM_SEED_BUSY = false
        return claimed
    end

    if teleWasOn then
        pcall(function()
            _tpToGarden({ mode = _getMoveMode(), fineTune = true, reason = "claim_seed" })
        end)
    end
    pcall(_teleResumeNow)
    _releaseClaimMoveSession()
    claimBusy = false
    G.__GAG2_AUTO_CLAIM_SEED_BUSY = false
    _G.__GAG2_AUTO_CLAIM_SEED_BUSY = false
    _dbg("session end | claimed=", claimed, "leftover=", leftover)
    _clearInteractCache()
    return claimed
end

_queueClaimSession = function(source)
    if claimBusy or not _enabled() then return false end
    local folder = _getSpawnFolder() or spawnFolder
    if not folder then
        _dbgSkip("no_spawn_folder")
        return false
    end
    _dbg("queue session:", tostring(source or "scan"))
    task.spawn(function()
        if claimBusy or not _enabled() then return end
        _processClaimSession(folder)
    end)
    return true
end

local function _scanFolder(folder)
    if not folder then
        _dbgSkip("no_spawn_folder")
        return 0
    end
    -- Busy: jangan scan folder tiap loop (GetChildren + attrs = spike)
    if claimBusy then
        return 0
    end
    local entries = _collectSpawnEntries(folder)
    local readyList = {}
    for _, inst in ipairs(entries) do
        if inst and inst.Parent and _spawnHasAttrs(inst) then
            readyList[#readyList + 1] = inst
        end
    end
    lastScanInfo.count = #entries
    lastScanInfo.ready = #readyList
    lastScanInfo.at = os.clock()

    if #readyList > 0 then
        _dbg("scan ready=", #readyList, "total=", #entries, "busy=", claimBusy)
    end

    if #readyList == 0 then return 0 end
    return _processClaimSession(folder)
end

local function _unbindAttrWatchers()
    for inst, conns in pairs(attrConns) do
        if type(conns) == "table" then
            for _, conn in ipairs(conns) do
                if conn and conn.Disconnect then conn:Disconnect() end
            end
        end
        attrConns[inst] = nil
    end
end

local function _bindSpawnInst(inst)
    if not inst or not inst.Parent or attrConns[inst] then return end
    local conns = {}
    for _, attr in ipairs(_getWatchAttrNames(inst)) do
        local ok, sig = pcall(function() return inst:GetAttributeChangedSignal(attr) end)
        if ok and sig and type(sig.Connect) == "function" then
            conns[#conns + 1] = sig:Connect(function()
                pcall(function()
                    if _enabled() and inst.Parent and _spawnHasAttrs(inst) then
                        task.spawn(function() _prefireRemote(inst, "attr_" .. attr) end)
                        _queueClaimSession("attr:" .. attr)
                    end
                end)
            end)
        end
    end
    if #conns > 0 then attrConns[inst] = conns end
end

local function _bindFolder(folder)
    if not folder then return end
    if childConn then childConn:Disconnect() childConn = nil end
    _unbindAttrWatchers()
    for _, child in ipairs(folder:GetChildren()) do _bindSpawnInst(child) end
    childConn = folder.ChildAdded:Connect(function(child)
        if not child then return end
        _bindSpawnInst(child)
        task.spawn(function()
            if _spawnHasAttrs(child) then
                _prefireRemote(child, "child_prefire")
                _queueClaimSession("child")
                return
            end
            local deadline = os.clock() + CFG.ATTR_WAIT_SEC
            while child.Parent and os.clock() < deadline do
                if _spawnHasAttrs(child) then
                    _prefireRemote(child, "child_wait")
                    _queueClaimSession("child-wait")
                    return
                end
                task.wait(CFG.ATTR_POLL_SEC)
            end
        end)
    end)
end

local function _ensureMapWatch()
    if mapConn then return end
    local map = _getMap()
    if not map then
        mapConn = workspace.ChildAdded:Connect(function(child)
            if not child or not child.Name then return end
            if child.Name == "Map" then
                spawnFolder = nil
                _ensureWatchers()
            end
        end)
        return
    end
    mapConn = map.ChildAdded:Connect(function(child)
        if not child or not child.Name then return end
        if child.Name == "SeedPackSpawnServerLocations" then
            spawnFolder = child
            _bindFolder(child)
        end
    end)
end

local function _ensureWatchers()
    _ensureMapWatch()
    _ensureSpawnSeedPackController()
    local folder = _getSpawnFolder()
    if folder and folder ~= spawnFolder then
        spawnFolder = folder
        _bindFolder(folder)
    end
    return folder
end

local function _bindFx()
    if fxConn then return end
    _initRemotes()
    if not SeedPackFX or not SeedPackFX.OnClientEvent then return end
    fxConn = SeedPackFX.OnClientEvent:Connect(function(pos)
        lastFxAt = os.clock()
        if typeof(pos) == "Vector3" then lastFxPos = pos end
    end)
end

local function claimLoop(myId)
    loopAliveId = myId
    _initRemotes()
    _bindFx()
    _dbg("loop start | id=", myId)
    while running and loopId == myId do
        local ok, err = pcall(function()
            if not _enabled() then
                task.wait(0.5)
                return
            end
            if not _initRemotes() then
                _dbg("loop wait remote")
                task.wait(0.5)
                return
            end
            if not savedGardenCf then savedGardenCf = _getGardenCFrame() end
            local folder = _ensureWatchers()
            local claimed = _scanFolder(folder)
            -- Saat sesi claim aktif, loop idle lebih longgar (event/queue yang jalan)
            if claimBusy then
                task.wait(0.35)
            elseif CFG.SCAN_SEC <= 0 then
                RunService.Heartbeat:Wait()
            else
                task.wait(CFG.SCAN_SEC)
            end
        end)
        if not ok then
            stats.lastError = tostring(err)
            _dbg("loop error:", err)
            task.wait(0.5)
        end
    end
    if loopAliveId == myId then loopAliveId = 0 end
    _dbg("loop stop | id=", myId)
end

function M.ClaimOnce()
    if not _enabled() then return 0 end
    return _scanFolder(_ensureWatchers())
end
M.claimOnce = M.ClaimOnce

function M.EnsureRunning()
    if not _enabled() then
        M.Stop()
        return false
    end
    if running and loopAliveId > 0 and loopAliveId == loopId then
        return true
    end
    M.Start()
    return running
end
M.ensureRunning = M.EnsureRunning

function M.Start()
    _initRemotes()
    if not _enabled() then
        running = false
        return
    end
    if running and loopAliveId > 0 and loopAliveId == loopId then
        return
    end
    running = true
    loopId = loopId + 1
    local myId = loopId
    savedGardenCf = savedGardenCf or _getGardenCFrame()
    _ensureWatchers()
    _bindFx()
    task.spawn(function() claimLoop(myId) end)
end
M.start = M.Start

function M.Stop()
    running = false
    loopId += 1
    pcall(_setNoclip, false)
    if claimBusy then
        _teleResumeNow()
        claimBusy = false
        G.__GAG2_AUTO_CLAIM_SEED_BUSY = false
        _G.__GAG2_AUTO_CLAIM_SEED_BUSY = false
    end
    pcall(_releaseClaimMoveSession)
    if childConn then childConn:Disconnect() childConn = nil end
    _unbindAttrWatchers()
end
M.stop = M.Stop

function M.IsRunning()
