 end,                  required = false },
    { key = "AutoGardenCards",         name = "Auto Garden Cards",       factory = function() -- AutoGardenCards.lua — Grow A Garden 2
-- Enable ON: flip 1 kartu → FREE ClaimFree. Berbayar: Skip / Drop Tier. Tidak beli Robux.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local CFG = {
    DELAY_DEFAULT = 0.4,
    DELAY_MIN = 0.15,
    DELAY_MAX = 2,
    REFRESH_GAP = 8, -- sama debounce game requestRefresh
    REVEAL_DEBOUNCE = 0.35,
    PAID_WAIT = 1.25,
    EMPTY_WAIT = 0.8,
}

local S = {
    running = false,
    loopId = 0,
    loopAliveId = 0,
    board = nil,
    hint = "Off",
    lastRevealAt = 0,
    lastRefreshAt = 0,
    lastDropAt = 0,
    lastClaimAt = 0,
    bound = false,
}

local function _normalizeDelay(raw)
    local n = tonumber(raw)
    if n == nil then n = CFG.DELAY_DEFAULT end
    if n < CFG.DELAY_MIN then n = CFG.DELAY_MIN end
    if n > CFG.DELAY_MAX then n = CFG.DELAY_MAX end
    return n
end

local function _normalizePaidMode(raw)
    local s = tostring(raw or "drop"):lower()
    if s == "skip" then
        return "skip"
    end
    return "drop"
end

local function readCfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.gardenCards
    local enabled = G.AUTO_GARDEN_CARDS_ENABLED
    if enabled == nil then enabled = rawget(_G, "AUTO_GARDEN_CARDS_ENABLED") end
    if enabled == nil and type(st) == "table" then enabled = st.enabled end
    local delay = G.AUTO_GARDEN_CARDS_DELAY
    if delay == nil then delay = rawget(_G, "AUTO_GARDEN_CARDS_DELAY") end
    if delay == nil and type(st) == "table" then delay = st.delay end
    local paid = G.AUTO_GARDEN_CARDS_PAID_MODE
    if paid == nil then paid = rawget(_G, "AUTO_GARDEN_CARDS_PAID_MODE") end
    if paid == nil and type(st) == "table" then paid = st.paidMode end
    return {
        enabled = enabled == true,
        delay = _normalizeDelay(delay),
        paidMode = _normalizePaidMode(paid),
    }
end

local function setHint(txt)
    S.hint = tostring(txt or "")
end

local function req(path)
    local ok, mod = pcall(function()
        local cur = ReplicatedStorage
        for part in string.gmatch(path, "[^%.]+") do
            cur = cur:FindFirstChild(part)
            if not cur then return nil end
        end
        return require(cur)
    end)
    return ok and mod or nil
end

local function getNetCards()
    local net = req("SharedModules.Networking")
    if type(net) ~= "table" then return nil end
    local cards = net.GardenCards
    return type(cards) == "table" and cards or nil
end

local function getGuiController()
    local ps = LP and LP:FindFirstChild("PlayerScripts")
    local controllers = ps and ps:FindFirstChild("Controllers")
    local mod = controllers and controllers:FindFirstChild("GuiController")
    if not mod then return nil end
    local ok, gui = pcall(require, mod)
    return (ok and type(gui) == "table") and gui or nil
end

local function getGardenCardsController()
    local ps = LP and LP:FindFirstChild("PlayerScripts")
    local controllers = ps and ps:FindFirstChild("Controllers")
    if not controllers then return nil end
    local mod = controllers:FindFirstChild("GardenCardsController")
    if not mod then
        for _, child in ipairs(controllers:GetChildren()) do
            if string.find(string.lower(child.Name), "gardencard", 1, true) then
                mod = child
                break
            end
        end
    end
    if not mod then return nil end
    local ok, ctrl = pcall(require, mod)
    return (ok and type(ctrl) == "table") and ctrl or nil
end

local function fireNode(node, ...)
    if node == nil then return false, nil end
    local args = { ... }
    local ok, a = pcall(function()
        if type(node.Fire) == "function" then
            return node:Fire(unpack(args))
        end
        if type(node.Invoke) == "function" then
            return node:Invoke(unpack(args))
        end
        if typeof(node) == "Instance" then
            if node:IsA("RemoteFunction") then
                return node:InvokeServer(unpack(args))
            end
            if node:IsA("RemoteEvent") then
                node:FireServer(unpack(args))
                return true
            end
        end
        if type(node.FireServer) == "function" then
            node:FireServer(unpack(args))
            return true
        end
        if type(node.InvokeServer) == "function" then
            return node:InvokeServer(unpack(args))
        end
        error("nofire")
    end)
    return ok, a
end

function M.OpenGui()
    local gui = getGuiController()
    if type(gui) == "table" then
        if type(gui.IsOpen) == "function" then
            local okOpen, open = pcall(gui.IsOpen, gui, "GardenCards")
            if okOpen and open == true then
                return true
            end
        end
        if type(gui.Open) == "function" then
            local ok = pcall(gui.Open, gui, "GardenCards")
            if ok then return true end
        end
    end

    local ctrl = getGardenCardsController()
    if type(ctrl) == "table" and type(ctrl.Open) == "function" then
        local ok = pcall(ctrl.Open, ctrl)
        if ok then return true end
    end

    local cards = getNetCards()
    if cards then
        local ok = select(1, fireNode(cards.Open))
        return ok == true
    end
    return false
end

function M.CloseGui()
    local gui = getGuiController()
    if type(gui) == "table" and type(gui.Close) == "function" then
        local ok = pcall(gui.Close, gui, "GardenCards")
        return ok == true
    end
    return false
end

local function adoptBoard(board)
    if type(board) == "table" then
        S.board = board
        return true
    end
    return false
end

local function boardFromReplica()
    local PSC = req("ClientModules.PlayerStateClient")
    if type(PSC) ~= "table" then return nil end
    local replica = nil
    pcall(function()
        if type(PSC.GetLocalReplica) == "function" then
            replica = PSC:GetLocalReplica()
        end
    end)
    if type(replica) ~= "table" and type(PSC.WaitForLocalReplica) == "function" then
        pcall(function()
            replica = PSC:WaitForLocalReplica(0.05)
        end)
    end
    local data = replica and replica.Data
    if type(data) == "table" and type(data.GardenCards) == "table" then
        return data.GardenCards
    end
    return nil
end

local function refreshBoard(force)
    local now = os.clock()
    if not force and S.lastRefreshAt > 0 and (now - S.lastRefreshAt) < CFG.REFRESH_GAP then
        if type(S.board) == "table" then return S.board end
    end
    local cards = getNetCards()
    if cards then
        local ok, result = fireNode(cards.Refresh)
        if ok and adoptBoard(result) then
            S.lastRefreshAt = now
            return S.board
        end
        ok, result = fireNode(cards.Open)
        if ok and adoptBoard(result) then
            S.lastRefreshAt = now
            return S.board
        end
    end
    if adoptBoard(boardFromReplica()) then
        S.lastRefreshAt = now
        return S.board
    end
    return S.board
end

local function bindSync()
    if S.bound then return end
    S.bound = true
    local cards = getNetCards()
    if cards and cards.Sync and cards.Sync.OnClientEvent then
        pcall(function()
            cards.Sync.OnClientEvent:Connect(function(payload)
                adoptBoard(payload)
            end)
        end)
    end
    local PSC = req("ClientModules.PlayerStateClient")
    if type(PSC) == "table" and type(PSC.WaitForLocalReplica) == "function" then
        task.spawn(function()
            local replica = nil
            pcall(function()
                replica = PSC:WaitForLocalReplica(30)
            end)
            if type(replica) ~= "table" then return end
            if type(replica.Data) == "table" then
                adoptBoard(replica.Data.GardenCards)
            end
            if type(replica.OnChange) == "function" then
                pcall(function()
                    replica:OnChange(function(_path, segs)
                        if type(segs) == "table" and segs[1] == "GardenCards" then
                            adoptBoard(replica.Data and replica.Data.GardenCards)
                        end
                    end)
                end)
            end
        end)
    end
end

local function rewardLabel(entry)
    if type(entry) ~= "table" then return "?" end
    local reward = entry.Reward
    local catalog = req("SharedModules.RewardCatalog")
    if type(catalog) == "table" and type(catalog.Resolve) == "function" and type(reward) == "table" then
        local ok, resolved = pcall(catalog.Resolve, reward, LP)
        if ok and type(resolved) == "table" then
            local name = tostring(resolved.DisplayName or "")
            if name ~= "" then return name end
        end
    end
    if type(reward) == "table" then
        local name = reward.Type or reward.Name or reward.Id
        if name ~= nil and tostring(name) ~= "" then
            return tostring(name)
        end
    end
    if entry.Meta == true then return "Grand Prize" end
    return "?"
end

local function findPending(board)
    if type(board) ~= "table" or type(board.Revealed) ~= "table" then
        return nil, nil
    end
    local firstIdx, firstEntry = nil, nil
    for i = 1, 5 do
        local entry = board.Revealed[tostring(i)]
        if type(entry) == "table" and entry.Purchased ~= true then
            if entry.Meta == true then
                return i, entry
            end
            if firstIdx == nil then
                firstIdx, firstEntry = i, entry
            end
        end
    end
    return firstIdx, firstEntry
end

local function emptySlots(board)
    local out = {}
    local revealed = (type(board) == "table" and type(board.Revealed) == "table") and board.Revealed or {}
    for i = 1, 5 do
        if revealed[tostring(i)] == nil then
            out[#out + 1] = i
        end
    end
    return out
end

local function claimSeq(board, entry)
    if type(entry) == "table" and type(entry.Seq) == "number" then
        return entry.Seq
    end
    if type(board) == "table" and type(board.RevealedCount) == "number" then
        return board.RevealedCount
    end
    return 1
end

local function serverSeconds()
    local SC = req("ClientModules.ServerClock")
    if type(SC) == "table" and type(SC.Seconds) == "function" then
        local ok, n = pcall(SC.Seconds, SC)
        if ok and type(n) == "number" then
            return n
        end
    end
    return os.time()
end

local function formatResetCaption(leftSec)
    leftSec = tonumber(leftSec) or 0
    if leftSec <= 0 then
        return "New cards ready!"
    end
    local GCC = req("ClientModules.GardenCardsCountdown")
    if type(GCC) == "table" and type(GCC.Caption) == "function" then
        local ok, cap = pcall(GCC.Caption, leftSec)
        if (not ok or type(cap) ~= "string") and type(GCC) == "table" then
            ok, cap = pcall(GCC.Caption, GCC, leftSec)
        end
        if ok and type(cap) == "string" and cap ~= "" then
            return cap
        end
    end
    local sec = math.max(0, math.floor(leftSec + 0.5))
    local d = math.floor(sec / 86400)
    sec = sec % 86400
    local h = math.floor(sec / 3600)
    sec = sec % 3600
    local m = math.floor(sec / 60)
    if d > 0 then
        return string.format("Reset In %dd %dh", d, h)
    end
    if h > 0 then
        return string.format("Reset In %dh %dm", h, m)
    end
    if m > 0 then
        return string.format("Reset In %dm", m)
    end
    return string.format("Reset In %ds", sec)
end

local function resetCaptionFromBoard(board)
    if type(board) ~= "table" then return nil end
    local expires = tonumber(board.ExpiresAt) or 0
    if expires <= 0 then return nil end
    return formatResetCaption(expires - serverSeconds())
end

local function withReset(hint)
    local reset = resetCaptionFromBoard(S.board)
    if type(hint) ~= "string" or hint == "" then
        return reset or "—"
    end
    if reset then
        return hint .. " · " .. reset
    end
    return hint
end

local function stepOnce(cfg)
    bindSync()
    local board = S.board
    if type(board) ~= "table" then
        board = refreshBoard(true)
    end
    if type(board) ~= "table" then
        board = boardFromReplica()
        adoptBoard(board)
    end
    if type(board) ~= "table" then
        setHint("no board")
        return CFG.EMPTY_WAIT
    end

    local tier = math.clamp(tonumber(board.Tier) or 1, 1, 5)
    local pendingIdx, pending = findPending(board)

    if pending then
        local price = tonumber(pending.Price) or 0
        local name = rewardLabel(pending)
        if price <= 0 then
            local cards = getNetCards()
            if not cards then
                setHint(("T%d claim FREE %s (no net)"):format(tier, name))
                return CFG.EMPTY_WAIT
            end
            local now = os.clock()
            if (now - S.lastClaimAt) < CFG.REVEAL_DEBOUNCE then
                setHint(("T%d claim FREE %s"):format(tier, name))
                return CFG.REVEAL_DEBOUNCE
            end
            S.lastClaimAt = now
            setHint(("T%d claim FREE %s"):format(tier, name))
            fireNode(cards.ClaimFree, claimSeq(board, pending))
            return cfg.delay
        end

        if cfg.paidMode == "drop" and tier > 1 then
            local cards = getNetCards()
            local now = os.clock()
            if (now - S.lastDropAt) < 1.5 then
                setHint(("T%d paid %s · drop wait"):format(tier, name))
                return CFG.PAID_WAIT
            end
            S.lastDropAt = now
            setHint(("T%d paid %s · drop"):format(tier, name))
            if cards then
                fireNode(cards.DropTier)
            end
            return math.max(cfg.delay, 0.8)
        end

        -- Tier 1 + Drop: game tidak bisa drop lebih rendah → stuck sampai board reset
        setHint(("T%d paid %s · %s"):format(tier, name, cfg.paidMode == "drop" and "drop N/A" or "skip"))
        refreshBoard(false)
        return CFG.PAID_WAIT
    end

    if board.CanReveal == true then
        local slots = emptySlots(board)
        if #slots <= 0 then
            setHint(("T%d no slot"):format(tier))
            return CFG.EMPTY_WAIT
        end
        local now = os.clock()
        if (now - S.lastRevealAt) < CFG.REVEAL_DEBOUNCE then
            setHint(("T%d flip"):format(tier))
            return CFG.REVEAL_DEBOUNCE
        end
        local slot = slots[math.random(1, #slots)]
        local cards = getNetCards()
        if not cards then
            setHint(("T%d flip %d (no net)"):format(tier, slot))
            return CFG.EMPTY_WAIT
        end
        S.lastRevealAt = now
        setHint(("T%d flip %d"):format(tier, slot))
        fireNode(cards.Reveal, slot)
        return cfg.delay
    end

    local expires = tonumber(board.ExpiresAt) or 0
    if expires > 0 then
        local left = expires - serverSeconds()
        if left <= 0 then
            refreshBoard(true)
            setHint(("T%d wait / refresh"):format(tier))
            return CFG.EMPTY_WAIT
        end
        setHint(("T%d wait"):format(tier))
        return math.min(CFG.EMPTY_WAIT, math.max(0.5, left))
    end

    refreshBoard(false)
    setHint(("T%d wait"):format(tier))
    return CFG.EMPTY_WAIT
end

local function loop(myId)
    S.loopAliveId = myId
    bindSync()
    refreshBoard(true)
    while S.running and myId == S.loopId do
        local cfg = readCfg()
        if not cfg.enabled then
            break
        end
        local waitSec = CFG.EMPTY_WAIT
        local ok, err = pcall(function()
            waitSec = stepOnce(cfg) or cfg.delay
        end)
        if not ok then
            setHint("err " .. tostring(err))
            waitSec = CFG.EMPTY_WAIT
        end
        task.wait(tonumber(waitSec) or cfg.delay)
    end
    if S.loopAliveId == myId then
        S.loopAliveId = 0
    end
    if not readCfg().enabled then
        setHint("Off")
    end
end

function M.GetStatusText()
    if not readCfg().enabled then
        return "Off"
    end
    local base
    if S.running and S.loopAliveId > 0 then
        base = (S.hint ~= "" and S.hint) or "running"
    else
        base = (S.hint ~= "" and S.hint) or "starting"
    end
    return withReset(base)
end

function M.SetDelay(n)
    n = _normalizeDelay(n)
    G.AUTO_GARDEN_CARDS_DELAY = n
    _G.AUTO_GARDEN_CARDS_DELAY = n
    return n
end

function M.SetPaidMode(mode)
    mode = _normalizePaidMode(mode)
    G.AUTO_GARDEN_CARDS_PAID_MODE = mode
    _G.AUTO_GARDEN_CARDS_PAID_MODE = mode
    return mode
end

function M.SetEnabled(on)
    on = (on == true)
    G.AUTO_GARDEN_CARDS_ENABLED = on
    _G.AUTO_GARDEN_CARDS_ENABLED = on
    if on then
        S.running = true
        if S.loopAliveId > 0 and S.loopAliveId == S.loopId then
            return true
        end
        S.loopId += 1
        local myId = S.loopId
        task.spawn(function()
            local ok, err = pcall(loop, myId)
            if not ok then
                setHint("loop err")
                warn("[GAG2] AutoGardenCards loop:", err)
                if S.loopAliveId == myId then
                    S.loopAliveId = 0
                end
            end
        end)
        return true
    end
    S.running = false
    S.loopId += 1
    setHint("Off")
    return false
end

M.setEnabled = M.SetEnabled
M.Start = function() return M.SetEnabled(true) end
M.start = M.Start
M.Stop = function() return M.SetEnabled(false) end
M.stop = M.Stop
M.IsRunning = function()
    return S.running == true and S.loopAliveId > 0
end
M.isRunning = M.IsRunning

function M.EnsureRunning()
    if not readCfg().enabled then
        M.Stop()
        return false
    end
    if S.running and S.loopAliveId > 0 and S.loopAliveId == S.loopId then
        return true
    end
    return M.Start()
end
M.ensureRunning = M.EnsureRunning

function M.SyncFromGlobals()
    local cfg = readCfg()
    M.SetDelay(cfg.delay)
    M.SetPaidMode(cfg.paidMode)
    if cfg.enabled then
        M.EnsureRunning()
    else
        M.Stop()
    end
end

function M.ApplyConfig(cfg)
    cfg = type(cfg) == "table" and cfg or {}
    if cfg.delay ~= nil then M.SetDelay(cfg.delay) end
    if cfg.paidMode ~= nil then M.SetPaidMode(cfg.paidMode) end
    if cfg.enabled ~= nil then M.SetEnabled(cfg.enabled == true) end
end

G.AutoGardenCards = M
G.AutoGardenCardsModule = M
_G.AutoGardenCards = M
_G.AutoGardenCardsModule = M

return M
 end,                required = false },
    { key = "SectionAutoGardenCards",  name = "Section Auto Garden Cards", factory = function() -- section_auto_garden_cards.lua — UI Auto Garden Cards (tab Auto)
-- Enable ON: flip + claim FREE. Paid: Skip / Drop Tier. Tidak beli Robux.
-- Open GUI = momentary one-shot (tidak sticky / tidak save).

local G = (getgenv and getgenv()) or _G
local M = {}

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto = ctx.getAuto
    local patchAuto = ctx.patchAuto
    local registerFlush = ctx.registerFlush
    local toggleApiGet = ctx.toggleApiGet

    if type(G.__GAG2_GARDEN_CARDS) ~= "table" then
        G.__GAG2_GARDEN_CARDS = {
            enabled = false,
            delay = 0.4,
            paidMode = "drop",
        }
    end
    _G.__GAG2_GARDEN_CARDS = G.__GAG2_GARDEN_CARDS

    local function normalizePaidMode(raw)
        local s = tostring(raw or "drop"):lower()
        if s == "skip" then
            return "skip"
        end
        return "drop"
    end

    local function normalizeDelay(raw)
        local n = tonumber(raw)
        if n == nil then n = 0.4 end
        if n < 0.15 then n = 0.15 end
        if n > 2 then n = 2 end
        return n
    end

    local function readState()
        local st = type(getAuto) == "function" and getAuto("gardenCards") or nil
        st = type(st) == "table" and st or {}
        local store = G.__GAG2_GARDEN_CARDS or rawget(_G, "__GAG2_GARDEN_CARDS") or {}
        return {
            enabled = (st.enabled == true) or (st.enabled == nil and store.enabled == true),
            delay = normalizeDelay(st.delay ~= nil and st.delay or store.delay),
            paidMode = normalizePaidMode(st.paidMode or store.paidMode),
        }
    end

    local function syncGlobals(st)
        st = type(st) == "table" and st or readState()
        st.enabled = (st.enabled == true)
        st.delay = normalizeDelay(st.delay)
        st.paidMode = normalizePaidMode(st.paidMode)
        if type(G.__GAG2_GARDEN_CARDS) ~= "table" then G.__GAG2_GARDEN_CARDS = {} end
        G.__GAG2_GARDEN_CARDS.enabled = st.enabled
        G.__GAG2_GARDEN_CARDS.delay = st.delay
        G.__GAG2_GARDEN_CARDS.paidMode = st.paidMode
        G.__GAG2_GARDEN_CARDS.openGui = nil
        _G.__GAG2_GARDEN_CARDS = G.__GAG2_GARDEN_CARDS
        G.AUTO_GARDEN_CARDS_ENABLED = st.enabled
        _G.AUTO_GARDEN_CARDS_ENABLED = st.enabled
        G.AUTO_GARDEN_CARDS_DELAY = st.delay
        _G.AUTO_GARDEN_CARDS_DELAY = st.delay
        G.AUTO_GARDEN_CARDS_PAID_MODE = st.paidMode
        _G.AUTO_GARDEN_CARDS_PAID_MODE = st.paidMode
        G.AUTO_GARDEN_CARDS_OPEN_GUI = false
        _G.AUTO_GARDEN_CARDS_OPEN_GUI = false
        return st
    end

    local function applyModule(st)
        st = syncGlobals(st)
        local mod = G.AutoGardenCards or G.AutoGardenCardsModule or rawget(_G, "AutoGardenCards")
        if type(mod) ~= "table" then
            warn("[GAG2] Auto Garden Cards module belum loaded")
            return st
        end
        if type(mod.ApplyConfig) == "function" then
            pcall(mod.ApplyConfig, {
                enabled = st.enabled,
                delay = st.delay,
                paidMode = st.paidMode,
            })
        else
            if type(mod.SetDelay) == "function" then pcall(mod.SetDelay, st.delay) end
            if type(mod.SetPaidMode) == "function" then pcall(mod.SetPaidMode, st.paidMode) end
            if type(mod.SetEnabled) == "function" then
                pcall(mod.SetEnabled, st.enabled)
            elseif st.enabled and type(mod.EnsureRunning) == "function" then
                pcall(mod.EnsureRunning)
            elseif not st.enabled and type(mod.Stop) == "function" then
                pcall(mod.Stop)
            end
        end
        return st
    end

    local function patchState(partial)
        partial = type(partial) == "table" and partial or {}
        partial.openGui = nil
        local cur = readState()
        for k, v in pairs(partial) do
            cur[k] = v
        end
        cur = syncGlobals(cur)
        if type(patchAuto) == "function" then
            patchAuto("gardenCards", {
                enabled = cur.enabled,
                delay = cur.delay,
                paidMode = cur.paidMode,
            }, function()
                applyModule(cur)
            end)
        else
            applyModule(cur)
        end
        return cur
    end

    local function openGuiOnce()
        -- One-shot: buka GUI, tidak sticky / tidak save
        G.AUTO_GARDEN_CARDS_OPEN_GUI = false
        _G.AUTO_GARDEN_CARDS_OPEN_GUI = false
        local mod = G.AutoGardenCards or G.AutoGardenCardsModule or rawget(_G, "AutoGardenCards")
        if type(mod) == "table" and type(mod.OpenGui) == "function" then
            pcall(mod.OpenGui, mod)
        end
    end

    local function syncAll()
        applyModule(readState())
    end

    local function flushState()
        local st = readState()
        if type(toggleApiGet) == "function" then
            local toggleOn = toggleApiGet("__GAG2_GARDEN_CARDS_TOGGLE_API")
            if toggleOn ~= nil then st.enabled = (toggleOn == true) end
        end
        syncGlobals(st)
    end

    if type(registerFlush) == "function" then
        registerFlush("gardenCards", flushState)
    end
    G.__GAG2_SYNC_AUTO_GARDEN_CARDS = syncAll
    _G.__GAG2_SYNC_AUTO_GARDEN_CARDS = syncAll

    local GC_STATE = readState()
    local body = ui:CreateSection("Auto Garden Cards", false)

    local _, statusLbl = ui:CreateRowLabel(body, "Status: Off", nil, 1, "accent")
    if statusLbl then
        statusLbl.TextTruncate = Enum.TextTruncate.AtEnd
    end
    task.spawn(function()
        while body and body.Parent do
            if body.Visible ~= false then
                pcall(function()
                    if statusLbl and statusLbl.Parent then
                        local txt = "Status: Off"
                        local mod = G.AutoGardenCards or G.AutoGardenCardsModule or rawget(_G, "AutoGardenCards")
                        if type(mod) == "table" and type(mod.GetStatusText) == "function" then
                            local ok, out = pcall(mod.GetStatusText, mod)
                            if ok and type(out) == "string" and out ~= "" then
                                txt = "Status: " .. out
                            end
                        end
                        statusLbl.Text = txt
                    end
                end)
            end
            task.wait(0.5)
        end
    end)

    local _, delayFn = ui:CreateRowInput(
        body,
        "Delay (sec)",
        tostring(GC_STATE.delay),
        function(txt)
            local n = tonumber(txt)
            if n == nil then return end
            GC_STATE = patchState({ delay = n })
        end,
        false
    )
    if type(delayFn) == "function" then
        pcall(delayFn, tostring(GC_STATE.delay))
    end
    G.__GAG2_GARDEN_CARDS_DELAY_API = delayFn
    _G.__GAG2_GARDEN_CARDS_DELAY_API = delayFn

    ui:CreateRowDropdown(body, {
        label = "If paid",
        placeholder = "Drop Tier",
        mode = "single",
        getItems = function()
            return {
                { key = "drop", name = "Drop Tier" },
                { key = "skip", name = "Skip (don't buy Robux)" },
            }
        end,
        initial = GC_STATE.paidMode,
        onChanged = function(modeOrKey, selectedKey)
            local key = selectedKey
            if type(key) ~= "string" or key == "" or key == "single" or key == "multi" then
                key = modeOrKey
            end
            GC_STATE = patchState({ paidMode = normalizePaidMode(key) })
        end,
    })

    -- Momentary: ON sekali buka GUI, lalu auto OFF (tidak save)
    local _, _, openGuiApi = ui:CreateRowToggle(
        body,
        "Open Garden Cards GUI",
        false,
        function(isOn)
            if isOn == true then
                openGuiOnce()
            end
        end,
        nil,
        nil,
        true
    )
    G.__GAG2_GARDEN_CARDS_OPEN_GUI_API = openGuiApi
    _G.__GAG2_GARDEN_CARDS_OPEN_GUI_API = openGuiApi
    if openGuiApi and type(openGuiApi.set) == "function" then
        openGuiApi.set(false, true)
    end

    local _, _, toggleApi = ui:CreateRowToggle(
        body,
        "Enable Auto Garden Cards",
        GC_STATE.enabled,
        function(isOn)
            GC_STATE = patchState({ enabled = isOn == true })
        end
    )
    G.__GAG2_GARDEN_CARDS_TOGGLE_API = toggleApi
    _G.__GAG2_GARDEN_CARDS_TOGGLE_API = toggleApi
    if toggleApi and type(toggleApi.set) == "function" then
        toggleApi.set(GC_STATE.enabled, true)
    end
    applyModule(GC_STATE)
end

G.SectionAutoGardenCards = M
_G.SectionAutoGardenCards = M

return M
 end,    required = false },
    { key = "AutoDragonEgg",           name = "Auto Dragon Egg",         factory = function() -- AutoDragonEgg.lua — Grow A Garden 2
-- Hatch DragonEgg via ProximityPrompt (getconnections / fireproximityprompt / firesignal).
-- Tidak simulasi tombol E (hindari harvest buah besar).

local Players           = game:GetService("Players")
local CollectionService = game:GetService("CollectionService")
local RunService        = game:GetService("RunService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

M.ModuleVersion = "20260701c"

local LOOP_MIN_SEC     = 0.35
local NO_EGG_WAIT_SEC  = 1.0
local POST_HATCH_SEC   = 1.5
local TP_SETTLE_SEC    = 0.2
local PROMPT_WAIT_SEC  = 0.5

local running = false
local loopId  = 0
local lastStatus = "idle"

local function _log(...)
    if G.AUTO_DRAGON_EGG_DEBUG == true or rawget(_G, "AUTO_DRAGON_EGG_DEBUG") == true then
        print("[GAG2-DragonEgg]", ...)
    end
end

local function _publishStatus(msg)
    lastStatus = tostring(msg or "")
    G.__GAG2_DRAGON_EGG_STATUS = lastStatus
    _G.__GAG2_DRAGON_EGG_STATUS = lastStatus
end

local function _writeMain(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.dragonEgg = MAIN.auto.dragonEgg or {}
    for k, v in pairs(patch) do
        MAIN.auto.dragonEgg[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function _enabled()
    local api = G.__GAG2_DRAGON_EGG_ENABLE_API or rawget(_G, "__GAG2_DRAGON_EGG_ENABLE_API")
    if type(api) == "table" and type(api.get) == "function" then
        local ok, v = pcall(api.get, api)
        if ok then return v == true end
    end
    if G.AUTO_DRAGON_EGG_ENABLED == true or rawget(_G, "AUTO_DRAGON_EGG_ENABLED") == true then
        return true
    end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.dragonEgg
    return type(st) == "table" and st.enabled == true
end

local function _getLP()
    local lp = LP or Players.LocalPlayer
    if lp then LP = lp end
    return lp
end

-- Executor API (getconnections dll.) sering di getgenv(), bukan _G
local function _execFn(name)
    local genv = (getgenv and getgenv()) or _G
    if type(genv[name]) == "function" then return genv[name] end
    if type(rawget(_G, name)) == "function" then return rawget(_G, name) end
    local syn = genv.syn or rawget(_G, "syn")
    if type(syn) == "table" and type(syn[name]) == "function" then return syn[name] end
    local flux = genv.fluxus or rawget(_G, "fluxus")
    if type(flux) == "table" and type(flux[name]) == "function" then return flux[name] end
    return nil
end

function M.GetEgg()
    local lp = _getLP()
    if not lp then return nil end

    for _, inst in ipairs(CollectionService:GetTagged("DragonEggInstance")) do
        if inst:IsA("Model") and inst:GetAttribute("DragonEggOwner") == lp.UserId then
            return inst
        end
    end

    local plotId = lp:GetAttribute("PlotId")
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens or plotId == nil then return nil end

    local plot = gardens:FindFirstChild("Plot" .. tostring(plotId))
    if not plot then return nil end

    local direct = plot:FindFirstChild("DragonEgg")
    if direct then return direct end

    for _, inst in ipairs(plot:GetDescendants()) do
        if inst:IsA("Model") then
            if inst.Name == "DragonEgg" or inst:GetAttribute("DragonEggOwner") == lp.UserId then
                return inst
            end
        end
    end

    return nil
end

local function _getPrompt(egg)
    if not egg then return nil, nil end
    local main = egg:FindFirstChild("Main")
    local prompt = main and main:FindFirstChildOfClass("ProximityPrompt")
    if not prompt then
        prompt = egg:FindFirstChildWhichIsA("ProximityPrompt", true)
    end
    return prompt, main
end

local function _tpToEgg(main, egg)
    local lp = _getLP()
    local char = lp and lp.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end

    local part = main
    if not part or not part:IsA("BasePart") then
        part = egg and egg:FindFirstChildWhichIsA("BasePart", true)
    end
    if not part then return false end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function() hum:UnequipTools() end) end

    local eggPos = part.Position
    hrp.CFrame = CFrame.new(eggPos + Vector3.new(0, 3, 0), eggPos)
    task.wait(TP_SETTLE_SEC)
    return true
end

local function _eggGone(egg)
    return not egg or not egg.Parent
end

local function _triggerPrompt(prompt, egg)
    local lp = _getLP()
    if not prompt or not lp then return false, "no_prompt" end

    local getconnections = _execFn("getconnections")
    if type(getconnections) == "function" then
        for _, c in getconnections(prompt.Triggered) do
            if type(c.Function) == "function" then
                _log("getconnections.Triggered")
                local ok, err = pcall(c.Function, lp)
                _log("  ->", ok, err)
                task.wait(PROMPT_WAIT_SEC)
                if _eggGone(egg) then return true, "getconnections" end
            end
        end
    end

    local fireproximityprompt = _execFn("fireproximityprompt")
    if type(fireproximityprompt) == "function" then
        _log("fireproximityprompt")
        pcall(fireproximityprompt, prompt, 0)
        task.wait(PROMPT_WAIT_SEC)
        if _eggGone(egg) then return true, "fireproximityprompt" end
    end

    local firesignal = _execFn("firesignal")
    if type(firesignal) == "function" then
        _log("firesignal.Triggered")
        pcall(firesignal, prompt.Triggered, lp)
        task.wait(PROMPT_WAIT_SEC)
        if _eggGone(egg) then return true, "firesignal" end
    end

    if not getconnections and not fireproximityprompt and not firesignal then
        return false, "no_executor_api"
    end

    return false, "prompt_fired_no_hatch"
end

function M.TryHatchOnce()
    local egg = M.GetEgg()
    if not egg or not egg.Parent then
        return false, "no_egg"
    end

    local prompt, main = _getPrompt(egg)
    if not prompt or not prompt.Enabled then
        return false, "no_prompt"
    end

    if not _tpToEgg(main, egg) then
        return false, "tp_fail"
    end

    _publishStatus("Hatching...")
    local ok, how = _triggerPrompt(prompt, egg)

    if _eggGone(egg) then
        _publishStatus("Hatched")
        return true, how or "hatched"
    end

    if ok then
        _publishStatus("Hatched")
        return true, how
    end

    _publishStatus(how == "no_executor_api" and "No executor API" or "Hatch failed")
    return false, how or "trigger_fail"
end

local function _loop(myId)
    while running and loopId == myId and _enabled() do
        local egg = M.GetEgg()
        if egg and egg.Parent then
            M.TryHatchOnce()
            if not (M.GetEgg() and M.GetEgg().Parent) then
                task.wait(POST_HATCH_SEC)
            else
                task.wait(LOOP_MIN_SEC)
            end
        else
            _publishStatus("Waiting for DragonEgg...")
            task.wait(NO_EGG_WAIT_SEC)
        end
        RunService.Heartbeat:Wait()
    end

    if loopId == myId then
        running = false
        _publishStatus("Stopped")
    end
end

function M.Start()
    if not _enabled() then
        running = false
        return
    end

    loopId += 1
    running = true
    local myId = loopId
    _publishStatus("Running")
    task.spawn(function() _loop(myId) end)
end
M.start = M.Start

function M.Stop()
    running = false
    loopId += 1
    _publishStatus("Stopped")
end
M.stop = M.Stop

function M.Restart()
    if not _enabled() then
        M.Stop()
        return
    end
    M.Start()
end
M.restart = M.Restart

function M.IsRunning()
    return running == true
end

function M.SetEnabled(on)
    on = (on == true)
    _writeMain({ enabled = on })
    G.AUTO_DRAGON_EGG_ENABLED = on
    _G.AUTO_DRAGON_EGG_ENABLED = on
    if on then
        M.Start()
    else
        M.Stop()
    end
    return on
end
M.setEnabled = M.SetEnabled

function M.ApplyRuntime(on)
    M.SetEnabled(on == true)
end
M.applyRuntime = M.ApplyRuntime

function M.SyncFromGlobals()
    local on = _enabled()
    G.AUTO_DRAGON_EGG_ENABLED = on
    _G.AUTO_DRAGON_EGG_ENABLED = on
    if on then
        M.Start()
    else
        M.Stop()
    end
end
M.syncFromGlobals = M.SyncFromGlobals

function M.GetStatus()
    return lastStatus
end

G.AutoDragonEgg = M
G.AutoDragonEggModule = M
_G.AutoDragonEgg = M
_G.AutoDragonEggModule = M

return M
 end,                  required = false },
    { key = "SectionAutoDragonEgg",    name = "Section Auto Dragon Egg", factory = function() -- section_auto_dragon_egg.lua — UI Auto Dragon Egg (tab Auto → Pet)

local G = (getgenv and getgenv()) or _G
local M = {}

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto       = ctx.getAuto
    local patchAuto     = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly

    local DE_STATE = getAuto("dragonEgg")
    DE_STATE.enabled = (DE_STATE.enabled == true)
    if G.AUTO_DRAGON_EGG_ENABLED == true or rawget(_G, "AUTO_DRAGON_EGG_ENABLED") == true then
        DE_STATE.enabled = true
    end

    local function dragonEggSnapshot()
        local api = G.__GAG2_DRAGON_EGG_ENABLE_API or rawget(_G, "__GAG2_DRAGON_EGG_ENABLE_API")
        if type(api) == "table" and type(api.get) == "function" then
            DE_STATE.enabled = (api.get() == true)
        end
        return { enabled = (DE_STATE.enabled == true) }
    end

    local function writeDragonEggGlobals()
        local snap = dragonEggSnapshot()
        G.AUTO_DRAGON_EGG_ENABLED = snap.enabled
        _G.AUTO_DRAGON_EGG_ENABLED = G.AUTO_DRAGON_EGG_ENABLED
        patchAutoOnly("dragonEgg", snap)
    end

    local function syncDragonEggModule()
        writeDragonEggGlobals()
        local mod = G.AutoDragonEgg or G.AutoDragonEggModule or rawget(_G, "AutoDragonEgg")
        if type(mod) ~= "table" then return end
        if G.AUTO_DRAGON_EGG_ENABLED then
            if type(mod.Restart) == "function" then
                pcall(mod.Restart, mod)
            elseif type(mod.SetEnabled) == "function" then
                pcall(mod.SetEnabled, mod, true)
            elseif type(mod.Start) == "function" then
                pcall(mod.Start, mod)
            end
        else
            if type(mod.SetEnabled) == "function" then pcall(mod.SetEnabled, mod, false)
            elseif type(mod.Stop) == "function" then pcall(mod.Stop, mod) end
        end
    end

    local function persistDragonEgg()
        writeDragonEggGlobals()
        if type(patchAuto) == "function" then
            patchAuto("dragonEgg", dragonEggSnapshot(), syncDragonEggModule)
        else
            syncDragonEggModule()
        end
    end

    G.__GAG2_PUSH_DRAGON_EGG = writeDragonEggGlobals
    _G.__GAG2_PUSH_DRAGON_EGG = writeDragonEggGlobals
    G.__GAG2_SYNC_AUTO_DRAGON_EGG = syncDragonEggModule
    _G.__GAG2_SYNC_AUTO_DRAGON_EGG = syncDragonEggModule

    writeDragonEggGlobals()

    local body = ui:CreateSection("Auto Hatch Egg", false)
    local dragonOn = DE_STATE.enabled == true

    local _, _, enableApi = ui:CreateRowToggle(
        body,
        "Enabled Auto Hatch Dragon Egg",
        dragonOn,
        function(isOn)
            DE_STATE.enabled = (isOn == true)
            persistDragonEgg()
        end
    )

    G.__GAG2_DRAGON_EGG_ENABLE_API = enableApi
    _G.__GAG2_DRAGON_EGG_ENABLE_API = enableApi

    if enableApi and type(enableApi.set) == "function" then
        enableApi.set(dragonOn, true)
    end

    syncDragonEggModule()
end

G.SectionAutoDragonEgg = M
_G.SectionAutoDragonEgg = M

return M
