function M._store()
    local st = rawget(G, "__GAG2_AUTO_STEAL") or rawget(_G, "__GAG2_AUTO_STEAL")
    if type(st) ~= "table" then
        st = {
            enabled = false,
            move_mode = "orbit",
            travel_mode = "walk",
            plants = {},
            mutations = {},
            min_kg = 0,
            min_price = 0,
            delay = 0.05,
            buff_only = false,
            buff_offmoon = true, -- Method ON: di luar Gold/Rainbow Moon tetap steal biasa
            dog_avoid = false, -- default OFF (ON = lite avoid; berat kalau ON + scan penuh)
            steal_range = 100,
        }
        G.__GAG2_AUTO_STEAL = st
        _G.__GAG2_AUTO_STEAL = st
    end
    return st
end

function M._publish(msg)
    msg = tostring(msg or "")
    if M.S.lastStatus == msg then return end
    M.S.lastStatus = msg
    G.__GAG2_STEAL_STATUS = M.S.lastStatus
    _G.__GAG2_STEAL_STATUS = M.S.lastStatus
end

function M._setPhase(ph, msg)
    local nextPh = tostring(ph or "Idle")
    local samePh = M.S.phase == nextPh
    M.S.phase = nextPh
    if msg ~= nil then
        local s = tostring(msg)
        if samePh and M.S.lastStatus == s then return end
        M._publish(s)
    end
end

function M._syncFromGlobals()
    local st = M._store()
    if G.AUTO_STEAL_ENABLED == true or rawget(_G, "AUTO_STEAL_ENABLED") == true then
        st.enabled = true
    end
    local g = rawget(G, "__GAG2_AUTO_STEAL") or rawget(_G, "__GAG2_AUTO_STEAL")
    if type(g) == "table" then
        for k, v in pairs(g) do
            if v ~= nil then st[k] = v end
            end
        end
    return st
end

function M._arrayToSet(arr)
    local set = {}
    if type(arr) ~= "table" then return set end
    if arr[1] ~= nil then
        for _, v in ipairs(arr) do
            local k = tostring(v or "")
            if k ~= "" then set[k] = true end
        end
        return set
    end
    for k, v in pairs(arr) do
        if v == true then set[tostring(k)] = true
        elseif type(k) == "number" and (type(v) == "string" or type(v) == "number") then
            set[tostring(v)] = true
        end
    end
    return set
end

function M._copyArray(arr)
    local out = {}
    if type(arr) ~= "table" then return out end
    if arr[1] ~= nil then
        for _, v in ipairs(arr) do out[#out + 1] = v end
        return out
    end
    for k, v in pairs(arr) do
        if v == true then out[#out + 1] = tostring(k) end
    end
    return out
end

function M._normalizeFilters(src)
    src = type(src) == "table" and src or {}
    local f = {
        plants = M._copyArray(src.plants),
        mutations = M._copyArray(src.mutations),
        min_kg = tonumber(src.min_kg) or 0,
        min_price = tonumber(src.min_price) or 0,
        delay = tonumber(src.delay) or 0.05,
        buff_only = (src.buff_only == true),
        -- default ON: Method di luar Gold/Rainbow Moon → steal biasa
        buff_offmoon = (src.buff_offmoon ~= false),
        dog_avoid = (src.dog_avoid == true), -- default OFF (hindari lag)
        move_mode = tostring(src.move_mode or "orbit"):lower(),
        travel_mode = tostring(src.travel_mode or "walk"):lower(),
        steal_range = tonumber(src.steal_range) or 100,
    }
    if f.move_mode == "nearest_garden" then f.move_mode = "nearest" end
    if f.move_mode == "highest_price" then f.move_mode = "highest" end
    if f.move_mode ~= "nearest" and f.move_mode ~= "highest" and f.move_mode ~= "off" then
        f.move_mode = "orbit"
    end
    local tm = f.travel_mode
    if tm ~= "soft" and tm ~= "step" and tm ~= "walk" and tm ~= "hard" then
        f.travel_mode = "walk"
    end
    if f.min_kg < 0 then f.min_kg = 0 end
    if f.min_price < 0 then f.min_price = 0 end
    if math.abs((tonumber(f.delay) or 0) - 0.35) < 1e-6 then f.delay = 0.05 end
    if f.delay < 0.02 then f.delay = 0.05 end
    if f.steal_range < 1 then f.steal_range = 1 end
    if f.steal_range > M.C.MAX_STEAL_DIST then f.steal_range = M.C.MAX_STEAL_DIST end
    return f
end

function M._filters(override)
    local st = M._store()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local mainSteal = MAIN and MAIN.auto and MAIN.auto.steal
    local base = type(mainSteal) == "table" and mainSteal or st
    local merged = {}
    for k, v in pairs(base) do merged[k] = v end
    for k, v in pairs(st) do if v ~= nil then merged[k] = v end end
    if type(override) == "table" then
        for k, v in pairs(override) do if v ~= nil then merged[k] = v end end
    end
    return M._normalizeFilters(merged)
end

function M._plantSet() return M._arrayToSet(M._filters().plants) end
function M._mutSet() return M._arrayToSet(M._filters().mutations) end

function M._matchName(set, name)
    if not next(set) then return true end
    name = tostring(name or "")
    if name == "" then return false end
    if set[name] then return true end
    local low = string.lower(name)
    for k in pairs(set) do
        if string.lower(tostring(k)) == low then return true end
    end
    return false
end

function M._matchMut(set, mut)
    if not next(set) then return true end
    mut = tostring(mut or "")
    if mut == "" then return set["No Mutation"] == true or set["None"] == true end
    if set[mut] then return true end
    local low = string.lower(mut)
    for k in pairs(set) do
        if string.lower(tostring(k)) == low then return true end
    end
    return false
end

function M._rowPassesFilters(r)
    if type(r) ~= "table" then return false end
    local f = M._filters()
    -- Method seed: longgar — 1 buah apa saja (filter fruit UI diabaikan)
    if f.buff_only == true
        and M.IsGoldOrRainbowMoon() == true
        and (M.S.buffMethodPhase == "seed" or M.S.buffMethodPhase == nil)
    then
        return true
    end
    -- Method wait/done: jangan ambil target
    if f.buff_only == true and M.IsGoldOrRainbowMoon() == true then
        local ph = M.S.buffMethodPhase
        if ph == "wait_buff" or ph == "done" then
            return false
        end
    end
    if not M._matchName(M._plantSet(), r.seed) then return false end
    if not M._matchMut(M._mutSet(), r.mut or r.mutation) then return false end
    if f.min_kg > 0 and (tonumber(r.kg) or 0) < f.min_kg then return false end
    if f.min_price > 0 and (tonumber(r.price) or 0) < f.min_price then return false end
    return true
end

function M._stealRange()
    return math.min(M._filters().steal_range or M.C.MAX_STEAL_DIST, M.C.MAX_STEAL_DIST)
end

function M._farmDelay()
    return M._filters().delay or 0.05
end

function M._moveMode()
    return M._filters().move_mode or "orbit"
end

M._util = {}

function M._util.hrp()
    local c = LP.Character
    return c and c:FindFirstChild("HumanoidRootPart")
end

function M._util.flatDist(pos)
    local h = M._util.hrp()
    if not h or typeof(pos) ~= "Vector3" then return math.huge end
    local d = h.Position - pos
    return Vector3.new(d.X, 0, d.Z).Magnitude
end

function M._util.modelPos(model)
    if not model then return nil end
    local pos = nil
    pcall(function()
        if model.PrimaryPart then pos = model.PrimaryPart.Position
        else
            local pp = model:FindFirstChildWhichIsA("BasePart", true)
            if pp then pos = pp.Position end
                    end
                end)
    return pos
end

function M._util.fmtPrice(n)
    n = tonumber(n) or 0
    local a = math.abs(n)
    if a >= 1e9 then return string.format("%.2fb", n / 1e9) end
    if a >= 1e6 then return string.format("%.2fm", n / 1e6) end
    if a >= 1e3 then return string.format("%.2fk", n / 1e3) end
    return tostring(math.floor(n + 0.5))
end

function M._util.isStealPrompt(p)
    if not p or not p:IsA("ProximityPrompt") then return false end
    if not p:IsDescendantOf(workspace) then return false end
    if CollectionService:HasTag(p, M.C.PROMPT_TAG) then return true end
    local at = string.lower(tostring(p.ActionText or ""))
    local ot = string.lower(tostring(p.ObjectText or ""))
    local nm = string.lower(tostring(p.Name or ""))
    if at == "steal" or ot == "steal" then return true end
    if string.find(at, "steal", 1, true) or string.find(ot, "steal", 1, true) then return true end
    if nm == "stealprompt" or string.find(nm, "steal", 1, true) then return true end
    return false
end

function M._util.targetFromPrompt(prompt)
    if not prompt or not prompt.Parent then return nil end
    local best, cur = nil, prompt.Parent
    for _ = 1, 12 do
        if not cur or cur == workspace or cur == game then break end
        if cur:IsA("Model") then
            if cur:GetAttribute("FruitId") ~= nil then return cur end
            if cur:GetAttribute("PlantId") ~= nil and cur:GetAttribute("UserId") ~= nil and not best then
                best = cur
            elseif not best then best = cur end
        end
        cur = cur.Parent
    end
    return best
end

function M._util.walkModels(model, fn, maxDepth)
    maxDepth = maxDepth or 8
    local node, depth = model, 0
    while node and depth < maxDepth do
        if node:IsA("Model") then
            local stop = fn(node)
            if stop ~= nil then return stop end
        end
        if node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    return nil
end

function M._util.getFSV()
    local f = G.FruitSellValue or G.FruitSellValueModule or rawget(_G, "FruitSellValue")
    return type(f) == "table" and f or nil
end

function M._util.ownerName(uid)
    uid = tonumber(uid)
    if not uid then return "?" end
    if M.S.ownerNameCache[uid] then return M.S.ownerNameCache[uid] end
    local plr = Players:GetPlayerByUserId(uid)
    if plr then
        M.S.ownerNameCache[uid] = plr.Name
        return plr.Name
    end
    local name = tostring(uid)
    M.S.ownerNameCache[uid] = name
    return name
end

function M._util.resolveOwnerAsync(uid)
    uid = tonumber(uid)
    if not uid or M.S.ownerNamePending[uid] then return end
    local plr = Players:GetPlayerByUserId(uid)
    if plr then M.S.ownerNameCache[uid] = plr.Name return end
    M.S.ownerNamePending[uid] = true
    task.spawn(function()
        local ok, name = pcall(Players.GetNameFromUserIdAsync, Players, uid)
        if ok and type(name) == "string" and name ~= "" then M.S.ownerNameCache[uid] = name end
        M.S.ownerNamePending[uid] = nil
    end)
end

function M._util.flatUnitXZ(v)
    local f = Vector3.new(v.X, 0, v.Z)
    if f.Magnitude < 1e-4 then return Vector3.new(0, 0, 1) end
    return f.Unit
end

function M._util.farmTargetKey(t)
    if type(t) ~= "table" then return nil end
    return string.format("%s_%s_%s", tostring(t.ownerUserId), tostring(t.plantId), tostring(t.fruitId or ""))
end

function M._util.markTried(key)
    if key then M.S.farmTriedKeys[key] = true end
end

function M._util.clearTried(key)
    if key then M.S.farmTriedKeys[key] = nil end
end

function M._util.isTried(key)
    return key and M.S.farmTriedKeys[key] == true
end

function M._util.bumpFail(key)
    if not key then return 0 end
    local n = (M.S.failAttempts[key] or 0) + 1
    M.S.failAttempts[key] = n
    M.S.failTotal += 1
    local maxFail = math.max(2, math.floor(tonumber(M.C.STAND_FAIL_MAX) or 4))
    if n >= maxFail then
        M._util.markTried(key)
    else
        -- retry + stand lebih dekat
        M._util.clearTried(key)
    end
    return n
end

function M._util.failCount(key)
    if not key then return 0 end
    return tonumber(M.S.failAttempts[key]) or 0
end

M._flags = {}

function M._flags.get()
    if M.S.stealFlagsTried then return M.S.stealFlagsMod end
    M.S.stealFlagsTried = true
    local ok, mod = pcall(function()
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local flags = sm and sm:FindFirstChild("Flags")
        local m = flags and flags:FindFirstChild("StealFlags")
        if m then return require(m) end
        m = sm and sm:FindFirstChild("StealFlags")
        if m then return require(m) end
        return nil
    end)
    if ok and type(mod) == "table" then M.S.stealFlagsMod = mod end
    return M.S.stealFlagsMod
end

function M._flags.isPlantStealable(seedName)
    seedName = tostring(seedName or "")
    if seedName == "" or seedName == "?" then return true end
    local flags = M._flags.get()
    if type(flags) ~= "table" or type(flags.IsPlantStealable) ~= "function" then return true end
    local ok, v = pcall(flags.IsPlantStealable, seedName)
    if ok then return v == true end
    return true
end

function M._flags.holdDuration(seedName)
    seedName = tostring(seedName or "")
    if seedName == "" or seedName == "?" then return 0 end
    local flags = M._flags.get()
    if type(flags) ~= "table" or type(flags.GetStealHoldDuration) ~= "function" then return 0 end
    local ok, v = pcall(flags.GetStealHoldDuration, seedName)
    if ok and type(v) == "number" and v > 0 then return v end
    return 0
end

function M._flags.resolveHold(seedName, prompt)
    local ph = prompt and tonumber(prompt.HoldDuration) or 0
    if not ph or ph < 0 then ph = 0 end
    local fh = M._flags.holdDuration(seedName)
    if fh > ph then return fh end
    return ph
end

function M._flags.resolveSeed(model, plant, seedFallback)
    local function attr(inst)
        if not inst then return nil end
        local a = inst:GetAttribute("SeedName") or inst:GetAttribute("CorePartName")
        if a ~= nil and tostring(a) ~= "" then return tostring(a) end
        return nil
    end
    return attr(plant) or attr(model) or tostring(seedFallback or "")
end

M._price = {}

function M._price.looksLikeId(s)
    s = tostring(s or "")
    if s == "" or s == "?" then return true end
    if s:find("_", 1, true) and s:find("-", 1, true) then return true end
        return false
    end

function M._price.kgFromAttr(model)
    local walked = M._util.walkModels(model, function(node)
        local sm = tonumber(node:GetAttribute("SizeMulti")) or 1
        local og = tonumber(node:GetAttribute("OvertimeGrowth")) or 1
        if og <= 0 then og = 1 end
        local bw = tonumber(node:GetAttribute("BaseWeight"))
        if bw and bw > 0 and sm > 0 then return bw * sm * og end
        local w = tonumber(node:GetAttribute("Weight"))
        if w and w > 0 then
            if bw and bw > 0 and math.abs(w - bw) <= 1e-3 and sm <= 1.0001 then return nil end
            return w
        end
        return nil
    end)
    return (type(walked) == "number" and walked > 0) and walked or 0
end

function M._price.resolveKg(model)
    if not model then return 0 end
    local fromAttr = M._price.kgFromAttr(model)
    if fromAttr > 0 then return fromAttr end
    local fsv = M._util.getFSV()
    if fsv and type(fsv.resolveWeight) == "function" then
        local ok, w = pcall(fsv.resolveWeight, model)
        if ok and type(w) == "number" and w > 0 then return w end
    end
    local plant = model.Parent
    if plant and (plant.Name == "Fruits" or plant.Name == "Fruit") then plant = plant.Parent end
    if plant and plant ~= model and plant:IsA("Model") then
        fromAttr = M._price.kgFromAttr(plant)
        if fromAttr > 0 then return fromAttr end
        if fsv and type(fsv.resolveWeight) == "function" then
            local ok, w = pcall(fsv.resolveWeight, plant)
            if ok and type(w) == "number" and w > 0 then return w end
        end
    end
    return 0
end

function M._price.moduleBaseWeight(seedName)
    seedName = tostring(seedName or "")
    if seedName == "" or seedName == "?" then return nil end
    local cached = M.S.bwModCache[seedName]
    if cached ~= nil then return cached > 0 and cached or nil end
    local bw = nil
    pcall(function()
        local folder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
        folder = folder and folder:FindFirstChild("Fruits")
        local modScript = folder and folder:FindFirstChild(seedName)
        if not (modScript and modScript:IsA("ModuleScript")) then return end
        local mod = require(modScript)
        bw = type(mod) == "table" and type(mod.GrowData) == "table" and tonumber(mod.GrowData.BaseWeight) or nil
    end)
    M.S.bwModCache[seedName] = (bw and bw > 0) and bw or 0
    return bw
end

function M._price.pickTypeName(model)
    if not model then return nil end
    for _, k in ipairs({ "CorePartName", "FruitName", "FruitType", "ItemName", "SeedName", "DisplayName" }) do
        local v = model:GetAttribute(k)
        if v ~= nil and tostring(v) ~= "" and not M._price.looksLikeId(v) then return tostring(v) end
    end
    return nil
end

function M._price.resolveSeed(model)
    if not model then return "?" end
    local fsv = M._util.getFSV()
    if fsv and type(fsv.resolveSeedName) == "function" then
        local ok, n = pcall(fsv.resolveSeedName, model)
        if ok and type(n) == "string" and n ~= "" and not M._price.looksLikeId(n) then return n end
    end
    local n = M._price.pickTypeName(model)
    if n then return n end
    local node, depth = model.Parent, 0
    while node and depth < 8 do
        if node:IsA("Model") then
            n = M._price.pickTypeName(node)
            if n then return n end
        end
        if node.Name == "Plants" or node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    local fallback = tostring(model.Name or "?")
    if M._price.looksLikeId(fallback) then return "?" end
    return fallback
end

function M._price.resolveMutation(model)
    if not model then return "" end
    local raw = model:GetAttribute("Mutation") or model:GetAttribute("Mutations") or model:GetAttribute("MutationName")
    if type(raw) == "string" then
        local low = raw:lower()
        if raw ~= "" and low ~= "none" and low ~= "nomutation" then return raw end
    end
    local fsv = M._util.getFSV()
    if fsv and type(fsv.resolveMutation) == "function" then
        local ok, m = pcall(fsv.resolveMutation, model)
        if ok and type(m) == "string" and m ~= "" then
            local low = m:lower()
            if low ~= "none" and low ~= "nomutation" then return m end
        end
    end
    return ""
end

function M._price.calc(name, multi, mut, decay)
    local fsv = M._util.getFSV()
    local calcFn = nil
    if fsv and type(fsv.calculate) == "function" then
        calcFn = function(n, m, mu, d) return fsv.calculate(n, m, mu, nil, d) end
    else
        local ok, calc = pcall(function()
            local sm = ReplicatedStorage:FindFirstChild("SharedModules")
            local mod = sm and sm:FindFirstChild("FruitValueCalc")
            if mod then return require(mod) end
            return nil
        end)
        if ok and type(calc) == "function" then
            calcFn = function(n, m, mu, d) return calc(n, m, mu, nil, d) end
    end
end
    if not calcFn or not multi or multi <= 0 or name == "" or name == "?" then return 0 end
    local mutArg = (mut ~= "" and mut) or nil
    local ok, v = pcall(calcFn, name, multi, mutArg, decay)
    if ok and type(v) == "number" and v > 0 then return v end
    if mutArg then
        ok, v = pcall(calcFn, name, multi, nil, decay)
        if ok and type(v) == "number" and v > 0 then return v end
    end
    return 0
end

function M._price.resolveMulti(model, kgHint, seedHint)
    if not model then return 0 end
    local fsv = M._util.getFSV()
    if fsv and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, model)
        if ok and type(m) == "number" and m > 0 then return m end
    end
    local sm = tonumber(model:GetAttribute("SizeMulti"))
    if sm and sm > 0 then return sm end
    local sm2 = M._util.walkModels(model, function(node)
        local v = tonumber(node:GetAttribute("SizeMulti"))
        if v and v > 0 then return v end
        return nil
    end)
    if type(sm2) == "number" and sm2 > 0 then return sm2 end
    local kg = tonumber(kgHint) or M._price.resolveKg(model)
    local seedName = tostring(seedHint or "")
    if kg > 0 and seedName ~= "" and seedName ~= "?" then
        local bwMod = M._price.moduleBaseWeight(seedName)
        if bwMod and bwMod > 0 then
            local m = kg / bwMod
            if m > 0 and m <= 50 then return m end
        end
    end
    if seedName ~= "" and seedName ~= "?" then return 1 end
    return 0
end

function M._price.resolve(model, seed, mut, multi, kgHint)
    if not model then return 0 end
    local name = tostring(seed or "")
    if name == "" or name == "?" or M._price.looksLikeId(name) then name = M._price.resolveSeed(model) end
    if name == "" or name == "?" then return 0 end
    local tagged = tonumber(model:GetAttribute("SellPrice")) or tonumber(model:GetAttribute("Price")) or tonumber(model:GetAttribute("Value"))
    if tagged and tagged > 0 then return tagged end
    multi = tonumber(multi) or 0
    if multi <= 0 then multi = M._price.resolveMulti(model, kgHint, name) end
    if multi <= 0 then multi = 1 end
    local decay = model:GetAttribute("DecayAlpha")
    local price = M._price.calc(name, multi, mut, decay)
    if price > 0 then return price end
    local fsv = M._util.getFSV()
    if fsv and type(fsv.fromFruit) == "function" then
        local ok, v = pcall(fsv.fromFruit, model)
        if not ok then ok, v = pcall(fsv.fromFruit, fsv, model) end
        if ok and type(v) == "number" and v > 0 then return v end
    end
    return 0
end

M._scan = {}

function M._scan.readFruit(model, prompt)
    if not model then return nil end
    local plant = model
    if model.Parent and (model.Parent.Name == "Fruits" or model.Parent.Name == "Fruit") then
        plant = model.Parent.Parent
    end
    local ownerId = tonumber(model:GetAttribute("UserId"))
    local plantId = model:GetAttribute("PlantId")
    local fruitId = model:GetAttribute("FruitId")
    if fruitId == nil then fruitId = "" end
    if plant and plant ~= model then
        ownerId = ownerId or tonumber(plant:GetAttribute("UserId"))
        plantId = plantId or plant:GetAttribute("PlantId")
        if fruitId == "" and plant:GetAttribute("FruitId") ~= nil then fruitId = plant:GetAttribute("FruitId") end
    end
    if ownerId and ownerId == LP.UserId then return nil end
    if not ownerId or plantId == nil then return nil end

    local seed = M._price.resolveSeed(model)
    local mut = M._price.resolveMutation(model)
    local kg = M._price.resolveKg(model)
    if kg <= 0 and plant and plant ~= model then kg = M._price.resolveKg(plant) end
    local multi = M._price.resolveMulti(model, kg, seed)
    if not multi or multi <= 0 then multi = 1 end
    local price = M._price.resolve(model, seed, mut, multi, kg)
    if price <= 0 and plant and plant ~= model then
        local seed2 = M._price.resolveSeed(plant)
        price = M._price.resolve(plant, seed2, mut, multi, kg)
        if seed == "?" and seed2 ~= "?" then seed = seed2 end
    end
    if price <= 0 and seed ~= "?" then
        price = M._price.calc(seed, 1, mut, model:GetAttribute("DecayAlpha"))
    end
    if ownerId then M._util.resolveOwnerAsync(ownerId) end

    local pos = M._util.modelPos(model)
    local dist = pos and M._util.flatDist(pos) or math.huge
    local flagSeed = M._flags.resolveSeed(model, plant, seed)
    local stealable = M._flags.isPlantStealable(flagSeed)
    local hold = M._flags.resolveHold(flagSeed, prompt)

    return {
        model = model,
        prompt = prompt,
        seed = seed,
        mut = mut,
        mutation = mut,
        kg = kg,
        price = price,
        multi = multi,
        ownerUserId = ownerId,
        ownerName = M._util.ownerName(ownerId),
        plantId = plantId,
        fruitId = fruitId,
        position = pos,
        dist = dist,
        hold = hold or 0,
        flagSeed = flagSeed,
        stealable = stealable,
        hasPrompt = prompt ~= nil and prompt.Parent ~= nil,
    }
end

function M._scan.cheapFromPrompt(prompt)
    if not prompt or not M._util.isStealPrompt(prompt) then return nil end
    local model = M._util.targetFromPrompt(prompt)
    if not model or model:GetAttribute("_GAG2FruitShell") == true then return nil end
    local plant = model
    if model.Parent and (model.Parent.Name == "Fruits" or model.Parent.Name == "Fruit") then plant = model.Parent.Parent end
    local ownerId = tonumber(model:GetAttribute("UserId"))
    local plantId = model:GetAttribute("PlantId")
    local fruitId = model:GetAttribute("FruitId")
    if fruitId == nil then fruitId = "" end
    if plant and plant ~= model then
        ownerId = ownerId or tonumber(plant:GetAttribute("UserId"))
        plantId = plantId or plant:GetAttribute("PlantId")
        if fruitId == "" and plant:GetAttribute("FruitId") ~= nil then fruitId = plant:GetAttribute("FruitId") end
    end
    if ownerId and ownerId == LP.UserId then return nil end
    if not ownerId or plantId == nil then return nil end
    local seedFallback = tostring(model:GetAttribute("SeedName") or model:GetAttribute("CorePartName") or "")
    local flagSeed = M._flags.resolveSeed(model, plant, seedFallback)
    if not M._flags.isPlantStealable(flagSeed) then return nil end
    local pos = M._util.modelPos(model)
    return {
        model = model,
        prompt = prompt,
        ownerUserId = ownerId,
        plantId = plantId,
        fruitId = fruitId,
        flagSeed = flagSeed,
        stealable = true,
        position = pos,
        dist = M._util.flatDist(pos),
    }
end

function M._scan.takeNearestPerOwner(cands, cap)
    cap = tonumber(cap) or M.C.PER_PLOT_CAP
    local byOwner = {}
    for i = 1, #(cands or {}) do
        local c = cands[i]
        local oid = tonumber(c.ownerUserId) or 0
        byOwner[oid] = byOwner[oid] or {}
        byOwner[oid][#byOwner[oid] + 1] = c
    end
    local out = {}
    for _, bucket in pairs(byOwner) do
        table.sort(bucket, function(a, b) return (a.dist or math.huge) < (b.dist or math.huge) end)
        local n = math.min(#bucket, cap)
        for i = 1, n do out[#out + 1] = bucket[i] end
    end
    return out
end

function M._scan.refreshDist(rows)
    local kept = {}
    for i = 1, #(rows or {}) do
        local r = rows[i]
        if type(r) ~= "table" then continue end
        local model = r.model
        if not (model and model.Parent) then continue end
        local prompt = r.prompt
        if not (prompt and prompt.Parent) then
            prompt = M._scan.stealPromptUnder(model)
            r.prompt = prompt
        end
        if not (prompt and prompt.Parent) then continue end
        r.hasPrompt = true
        local pos = r.position
        if typeof(pos) ~= "Vector3" then
            pos = M._util.modelPos(model)
            r.position = pos
        end
        if typeof(pos) == "Vector3" then r.dist = M._util.flatDist(pos) end
        kept[#kept + 1] = r
    end
    M.S.lastRows = kept
    return kept
end

function M._scan.removeKey(key)
    if not key or type(M.S.lastRows) ~= "table" then return end
    local kept = {}
    for i = 1, #M.S.lastRows do
        local r = M.S.lastRows[i]
        if M._util.farmTargetKey(r) ~= key then
            kept[#kept + 1] = r
        end
    end
    M.S.lastRows = kept
end

function M._scan.sortRows(rows)
    table.sort(rows, function(a, b)
        local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
        if pa ~= pb then return pa > pb end
        return (a.dist or math.huge) < (b.dist or math.huge)
    end)
end

function M._scan.clearWatch()
    for i = 1, #M.S.liveScanConns do pcall(function() M.S.liveScanConns[i]:Disconnect() end) end
    M.S.liveScanConns = {}
end

function M._scan.bindWatch()
    M._scan.clearWatch()
    local function mark(why)
        M.S.scanDirty = true
        M.S.scanDirtyWhy = tostring(why or "dirty")
    end
    pcall(function()
        M.S.liveScanConns[#M.S.liveScanConns + 1] = CollectionService:GetInstanceAddedSignal(M.C.PROMPT_TAG):Connect(function()
            mark("prompt_added")
        end)
        M.S.liveScanConns[#M.S.liveScanConns + 1] = CollectionService:GetInstanceRemovedSignal(M.C.PROMPT_TAG):Connect(function()
            mark("prompt_removed")
        end)
    end)
    local gardens = workspace:FindFirstChild("Gardens")
    if gardens then
        M.S.liveScanConns[#M.S.liveScanConns + 1] = gardens.ChildAdded:Connect(function(ch)
            mark("plot_added:" .. tostring(ch and ch.Name))
        end)
        M.S.liveScanConns[#M.S.liveScanConns + 1] = gardens.ChildRemoved:Connect(function(ch)
            mark("plot_removed:" .. tostring(ch and ch.Name))
        end)
    end
    local n = ReplicatedStorage:FindFirstChild("Night")
    if n then
        M.S.liveScanConns[#M.S.liveScanConns + 1] = n:GetPropertyChangedSignal("Value"):Connect(function()
            if n.Value == true or n.Value == 1 then mark("night_start") end
        end)
    end
    M.S.liveScanConns[#M.S.liveScanConns + 1] = Players.PlayerAdded:Connect(function(plr)
        mark("player_added:" .. tostring(plr and plr.Name))
        task.delay(2, function()
            mark("player_added_delay:" .. tostring(plr and plr.Name))
        end)
    end)
end

function M.InvalidateScan(why)
    M.S.scanDirty = true
    M.S.scanDirtyWhy = tostring(why or "dirty")
end

function M._scan.stealPromptUnder(model)
    if not model then return nil end
    local found = nil
    pcall(function()
        for _, d in ipairs(model:GetDescendants()) do
            if M._util.isStealPrompt(d) then found = d break end
        end
    end)
    return found
end

function M._scan.doScan()
    -- Farm list = StealPrompt only (mirror steal test listMode "prompt")
    local cheap, seenPrompt = {}, {}
    local nProcessed = 0
    local function maybeYield()
        nProcessed += 1
        if nProcessed % 80 == 0 then task.wait() end
    end
    for _, p in ipairs(CollectionService:GetTagged(M.C.PROMPT_TAG)) do
        if not seenPrompt[p] then
            seenPrompt[p] = true
            local c = M._scan.cheapFromPrompt(p)
            if c then cheap[#cheap + 1] = c end
        end
        maybeYield()
    end
    if #cheap == 0 then
        local gardens = workspace:FindFirstChild("Gardens")
        if gardens then
            for _, plot in ipairs(gardens:GetChildren()) do
                for _, d in ipairs(plot:GetDescendants()) do
                    if d:IsA("ProximityPrompt") and not seenPrompt[d] then
                        local at = string.lower(tostring(d.ActionText or ""))
                        if at == "steal" or string.find(at, "steal", 1, true) then
                            seenPrompt[d] = true
                            local c = M._scan.cheapFromPrompt(d)
                            if c then cheap[#cheap + 1] = c end
                        end
                    end
                end
                maybeYield()
            end
        end
    end
    local kept = M._scan.takeNearestPerOwner(cheap, M.C.PER_PLOT_CAP)
    local rows, seenFruit, seenKey = {}, {}, {}
    for i = 1, #kept do
        local c = kept[i]
        local info = M._scan.readFruit(c.model, c.prompt)
        if info and info.model and not seenFruit[info.model] then
            local key = string.format("%s|%s|%s", tostring(info.ownerUserId or ""), tostring(info.plantId or ""), tostring(info.fruitId or ""))
            if key == "||" or not seenKey[key] then
                seenFruit[info.model] = true
                if key ~= "||" then seenKey[key] = true end
                info.hasPrompt = true
                info.stealable = true
                info.flagSeed = info.flagSeed or c.flagSeed
                info.dist = c.dist or info.dist
                info.position = c.position or info.position
                -- filter di pick (steal test); tetap apply di sini supaya list UI/filter konsisten
                if M._rowPassesFilters(info) then rows[#rows + 1] = info end
            end
        end
        maybeYield()
    end
    M._scan.sortRows(rows)
    M.S.lastRows = rows
    M.S.lastScanAt = os.clock()
    M.S.scanDirty = false
    M.S.scanDirtyWhy = ""
    return rows
end

function M._scan.isLiveRow(r)
    if type(r) ~= "table" then return false end
    local model = r.model
    if not (model and model.Parent) then return false end
    local prompt = r.prompt
    if not (prompt and prompt.Parent) then
        prompt = M._scan.stealPromptUnder(model)
        r.prompt = prompt
    end
    if not (prompt and prompt.Parent) then return false end
    r.hasPrompt = true
    return true
end

function M._scan.ensure(force)
    if force == true or M.S.scanDirty == true then return M._scan.doScan() end
    local age = os.clock() - (M.S.lastScanAt or 0)
    if M.S.lastRows and #M.S.lastRows > 0 and age < M.C.FARM_RESCAN then
        -- cache hanya dist+prune; buah mati langsung di-drop
        return M._scan.refreshDist(M.S.lastRows)
    end
    return M._scan.doScan()
end

-- Fire: cache boleh, tapi WAJIB live-prune tiap tick (jangan fire target mati)
function M._scan.ensureForFire()
    if M.S.scanDirty == true then
        return M._scan.doScan()
    end
    local age = os.clock() - (M.S.lastScanAt or 0)
    local ttl = tonumber(M.C.FARM_FIRE_RESCAN) or 0.35
    if (not M.S.lastRows) or #M.S.lastRows == 0 or age >= ttl then
        return M._scan.doScan()
    end
    return M._scan.refreshDist(M.S.lastRows)
end

function M._defenderAttr()
    if M.S.defenderAttr then return M.S.defenderAttr end
    M.S.defenderAttr = "Defender"
    pcall(function()
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local mod = sm and sm:FindFirstChild("WerewolfNightData")
        if mod then
            local data = require(mod)
            if type(data) == "table" and type(data.DefenderAttribute) == "string" then
                M.S.defenderAttr = data.DefenderAttribute
        end
    end
    end)
    return M.S.defenderAttr
end

function M.IsNight()
    local n = ReplicatedStorage:FindFirstChild("Night")
    if n and (n:IsA("BoolValue") or n:IsA("NumberValue")) then
        return n.Value == true or n.Value == 1
    end
    return false
end

function M.IsDefender()
    local name = M._defenderAttr()
    local v = LP:GetAttribute(name)
    if v == nil then v = LP:GetAttribute("Defender") end
    return v == true
end

function M.NeedsWerewolfRole()
    if M.C.MAIN_PLACE[game.PlaceId] == true then return false end
    if M.C.FALL_PLACE[game.PlaceId] == true then return true end
    local AFH = G.AutoFallHarvest or rawget(_G, "AutoFallHarvest")
    if type(AFH) == "table" then
        if type(AFH.IsInMainGarden) == "function" then
            local ok, v = pcall(AFH.IsInMainGarden, AFH)
            if ok and v == true then return false end
        end
        if type(AFH.IsInFallHarvest) == "function" then
            local ok, v = pcall(AFH.IsInFallHarvest, AFH)
            if ok and v == true then return true end
        end
    end
    return false
end

function M.IsDefenderBlocking()
    return M.NeedsWerewolfRole() == true and M.IsDefender() == true
end

function M.StealGateOk()
    if M.IsNight() ~= true then return false, "not_night" end
    if M.IsDefenderBlocking() then return false, "defender" end
    return true, "ok"
end

function M.GetCarryCount()
    local char = LP.Character
    if not char then return 0 end
    local n = 0
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Model") and child:FindFirstChild("FruitAnchor", true) then n += 1 end
    end
    return n
end

function M.GetCarryValue()
    return tonumber(LP:GetAttribute("StolenCarryValue")) or 0
end

function M.IsCarrying()
    return M.GetCarryCount() > 0 or M.GetCarryValue() > 0
end

function M.GetStealCarryLimit()
    for _, name in ipairs(M.C.LIMIT_ATTRS) do
        local v = tonumber(LP:GetAttribute(name))
        if v and v > 0 then return math.floor(v) end
    end
    return nil
end

function M.GetStackCap()
    return M.C.STACK_CAP
end

function M.IsCarryFull()
    local lim = M.GetStealCarryLimit()
    if lim and lim > 0 and M.GetCarryCount() >= lim then return true end
    return M.GetCarryCount() >= M.C.CARRY_RETURN_AT
end

function M._charHasBuff(char)
    if not char then return false end
    if char:GetAttribute("Rainbow") == true or char:GetAttribute("Gold") == true then return true end
    local okR, hasR = pcall(function() return CollectionService:HasTag(char, "RainbowHighlight") end)
    if okR and hasR then return true end
    local okG, hasG = pcall(function() return CollectionService:HasTag(char, "GoldHighlight") end)
    if okG and hasG then return true end
    return false
end

function M._ownerHasBuff(userId)
    userId = tonumber(userId)
    if not userId or userId <= 0 then return false end
    local plr = Players:GetPlayerByUserId(userId)
    if not plr then return false end
    return M._charHasBuff(plr.Character)
end

function M.OwnerHasRainbowOrGoldBuff(userId)
    return M._ownerHasBuff(userId)
end

-- Buff Rainbow/Gold di character lokal (diri sendiri) — cache singkat anti CPU spike
function M.LocalHasRainbowOrGoldBuff()
    local now = os.clock()
    if type(M.S.buffCacheAt) == "number" and (now - M.S.buffCacheAt) < 0.35 then
        return M.S.buffCacheVal == true
    end
    local plr = LP or Players.LocalPlayer
    local v = M._charHasBuff(plr and plr.Character) == true
    M.S.buffCacheAt = now
    M.S.buffCacheVal = v
    return v
end

function M._weatherKey(name)
    return (tostring(name or ""):lower():gsub("%s+", ""):gsub("_", ""):gsub("%-", ""))
end

local function _keyIsGoldOrRainbowMoon(k)
    if type(k) ~= "string" or k == "" then return false end
    if k == "goldmoon" or k == "rainbowmoon" then return true end
    if string.find(k, "goldmoon", 1, true) then return true end
    if string.find(k, "rainbowmoon", 1, true) then return true end
    return false
end

-- GoldMoon / RainbowMoon — di-cache ~0.75s (dipanggil tiap tick fire+walk → spike CPU kalau full scan)
function M.IsGoldOrRainbowMoon()
    local now = os.clock()
    if type(M.S.moonCacheAt) == "number" and (now - M.S.moonCacheAt) < 0.75 then
        return M.S.moonCacheOk == true, M.S.moonCacheName
    end

    local aw = workspace:GetAttribute("ActiveWeather")
    local k = M._weatherKey(aw)
    if _keyIsGoldOrRainbowMoon(k) then
        M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, true, aw
        return true, aw
    end

    for _, attr in ipairs({ "Weather", "MoonWeather", "NightWeather", "ActiveMoon" }) do
        local v = workspace:GetAttribute(attr)
        if _keyIsGoldOrRainbowMoon(M._weatherKey(v)) then
            M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, true, v
            return true, v
        end
    end

    local wv = ReplicatedStorage:FindFirstChild("WeatherValues")
    if wv then
        if wv:GetAttribute("GoldMoon_Playing") == true then
            M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, true, "GoldMoon"
            return true, "GoldMoon"
        end
        if wv:GetAttribute("RainbowMoon_Playing") == true then
            M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, true, "RainbowMoon"
            return true, "RainbowMoon"
        end
        -- Jangan GetAttributes() tiap tick — terlalu mahal; cukup attr spesifik di atas
    end

    local WP = G.WeatherPredict or rawget(_G, "WeatherPredict")
    if type(WP) == "table" and type(WP.IsWeatherLive) == "function" then
        local okG, liveG = pcall(WP.IsWeatherLive, WP, "GoldMoon")
        if okG and liveG == true then
            M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, true, "GoldMoon"
            return true, "GoldMoon"
        end
        local okR, liveR = pcall(WP.IsWeatherLive, WP, "RainbowMoon")
        if okR and liveR == true then
            M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, true, "RainbowMoon"
            return true, "RainbowMoon"
        end
    end

    M.S.moonCacheAt, M.S.moonCacheOk, M.S.moonCacheName = now, false, aw
    return false, aw
end

function M.IsPlayerDefender(plr)
    if not plr then return false end
    local name = M._defenderAttr()
    local v = plr:GetAttribute(name)
    if v == nil then v = plr:GetAttribute("Defender") end
    return v == true
end

-- Owner target boleh di-seed steal: bukan defender
function M.IsOwnerNonDefender(userId)
    userId = tonumber(userId)
    if not userId or userId <= 0 then return false end
    local plr = Players:GetPlayerByUserId(userId)
    if not plr then return true end -- owner offline → anggap boleh
    return M.IsPlayerDefender(plr) ~= true
end

M._buffMethod = {}

function M._buffMethod.enabled()
    return M.GetBuffOnly() == true
end

function M._buffMethod.reset()
    M.S.buffMethodPhase = "seed"
    M.S.buffMethodStopAfterDeposit = false
    M.S.buffMethodSeedPending = false
    -- Hanya skip seed kalau SUDAH buff + moon aktif (benar-benar siap farm)
    if M.LocalHasRainbowOrGoldBuff() and M.IsGoldOrRainbowMoon() == true then
        M.S.buffMethodPhase = "farm"
        M.S.buffMethodStopAfterDeposit = true
    end
end

function M._buffMethod.phase()
    if not M._buffMethod.enabled() then return nil end
    if type(M.S.buffMethodPhase) ~= "string" then
        M._buffMethod.reset()
    end
    return M.S.buffMethodPhase
end

function M._buffMethod.isSeed()
    return M._buffMethod.enabled()
        and M.IsGoldOrRainbowMoon() == true
        and M._buffMethod.phase() == "seed"
end

-- Gate tiap tick fire/walk. "run" | "idle" | "stop"
-- Carry 1 → stop steal, DIAM di tempat (jangan garden / deposit) sampai buff.
-- Setelah buff → farm normal.
function M._buffMethod.preFarmTick()
    if not M._buffMethod.enabled() then return "run" end

    local moonOk = M.IsGoldOrRainbowMoon() == true

    -- Tanpa Gold/Rainbow Moon (day / moon biasa / weather lain)
    if not moonOk then
        if M.S.buffMethodPhase == "done" then
            return "stop"
        end
        -- wait_buff: tetap diam di tempat nunggu buff (jangan garden/deposit)
        if M.S.buffMethodPhase == "wait_buff" then
            if M.LocalHasRainbowOrGoldBuff() then
                M.S.buffMethodPhase = "farm"
                M.S.buffMethodStopAfterDeposit = true
                M._setPhase("BuffFarm", "BUFF · got buff → farm")
                return "run"
            end
            M._setPhase("BuffWait", "BUFF · wait buff @ garden")
            return "idle"
        end
        if M.S.buffMethodPhase == "farm" then
            if M.LocalHasRainbowOrGoldBuff() then
                return "run"
            end
            M.S.buffMethodPhase = "wait_buff"
            M._setPhase("BuffWait", "BUFF · wait buff @ garden")
            return "idle"
        end
        -- Toggle "Steal normal (no Moon)" ON → steal biasa (fase seed dibersihkan)
        if M.GetBuffOffmoon() == true then
            if M.S.buffMethodPhase == "seed" or M.S.buffMethodPhase == nil then
                M.S.buffMethodPhase = nil
                M.S.buffMethodStopAfterDeposit = false
                M.S.buffMethodSeedPending = false
            end
            return "run"
        end
        M._setPhase("BuffSeed", "BUFF · wait Gold/Rainbow Moon")
        return "idle"
    end

    -- Moon aktif → pastikan fase method jalan
    if type(M.S.buffMethodPhase) ~= "string" then
        M._buffMethod.reset()
    end

    local ph = M.S.buffMethodPhase

    if ph == "done" then
        return "stop"
    end

    if ph == "seed" then
        -- Carry sudah 1 → STOP steal, diam (jangan garden / deposit)
        if M.GetCarryCount() >= 1 then
            M.S.buffMethodSeedPending = false
            M.S.buffMethodPhase = "wait_buff"
            M._setPhase("BuffSeed", "BUFF · steal → garden")
            return "idle"
        end
        if M.S.buffMethodSeedPending == true then
            M._setPhase("BuffSeed", "BUFF · steal carry x1")
            return "idle"
        end
        M._setPhase("BuffSeed", "BUFF · steal carry x1")
        return "run"
    end

    if ph == "wait_buff" then
        -- Belum buff: diam di tempat, jangan steal / garden / deposit
        if M.LocalHasRainbowOrGoldBuff() then
            M.S.buffMethodPhase = "farm"
            M.S.buffMethodStopAfterDeposit = true
            M._setPhase("BuffFarm", "BUFF · got buff → farm")
            return "run"
        end
        M._setPhase("BuffWait", "BUFF · wait buff @ garden")
        return "idle"
    end

    if ph == "farm" then
        if not M.LocalHasRainbowOrGoldBuff() then
            M.S.buffMethodPhase = "wait_buff"
            M._setPhase("BuffWait", "BUFF · wait buff @ garden")
            return "idle"
        end
        return "run"
    end

    return "run"
end

function M._buffMethod.onDepositOk(reason)
    if not M._buffMethod.enabled() then return end
    -- Deposit method hanya relevan saat Gold/Rainbow Moon (atau baru selesai seed)
    if M.IsGoldOrRainbowMoon() ~= true
        and M.S.buffMethodPhase ~= "seed"
        and M.S.buffMethodPhase ~= "farm"
        and M.S.buffMethodPhase ~= "wait_buff" then
        return
    end
    reason = tostring(reason or "")
    local ph = M.S.buffMethodPhase

    -- Seed deposit lama (jika sempat) → tetap masuk wait_buff, jangan steal
    if ph == "seed" or reason == "buff_seed" or reason == "home_seed" then
        M.S.buffMethodSeedPending = false
        M.S.buffMethodPhase = "wait_buff"
        M._setPhase("BuffWait", "BUFF · wait buff @ garden")
        return
    end

    -- Deposit pertama saat fase farm → stop Auto Steal
    if ph == "farm" and M.S.buffMethodStopAfterDeposit == true then
        M.S.buffMethodPhase = "done"
        M._setPhase("BuffDone", "BUFF · deposit done → stop")
        task.defer(function()
            pcall(function() M.SetEnabled(false) end)
        end)
    end
end

function M.SetBuffOnly(on)
    local st = M._store()
    st.buff_only = (on == true)
    if st.buff_only then
        M._buffMethod.reset()
    else
        M.S.buffMethodPhase = nil
        M.S.buffMethodStopAfterDeposit = false
    end
    return st.buff_only
end

function M.GetBuffOnly()
    return M._filters().buff_only == true
end

function M.SetBuffOffmoon(on)
    local st = M._store()
    st.buff_offmoon = (on == true)
    return st.buff_offmoon
end

function M.GetBuffOffmoon()
    -- default true kalau belum di-set
    local f = M._filters()
    return f.buff_offmoon ~= false
end

function M.SetDogAvoid(on)
    local st = M._store()
    st.dog_avoid = (on == true)
    return st.dog_avoid
end

function M.GetDogAvoid()
    -- default OFF
    return M._filters().dog_avoid == true
end

function M.GetMoveMode()
    return M._moveMode()
end

function M.SetMoveMode(mode)
    local st = M._store()
    mode = tostring(mode or "orbit"):lower()
    if mode == "nearest_garden" then mode = "nearest" end
    if mode == "highest_price" then mode = "highest" end
    if mode ~= "nearest" and mode ~= "highest" and mode ~= "off" then mode = "orbit" end
    st.move_mode = mode
    return st.move_mode
end

function M.GetTravelMode()
    return M._filters().travel_mode or "walk"
end

function M.SetTravelMode(mode)
    local st = M._store()
    mode = tostring(mode or "walk"):lower()
    if mode ~= "soft" and mode ~= "step" and mode ~= "walk" and mode ~= "hard" then mode = "walk" end
    st.travel_mode = mode
    return st.travel_mode
end

function M._parseHudTimer()
    local now = os.clock()
    if M.S.hudTimerCacheSec ~= nil and (now - M.S.hudTimerCacheAt) < 0.75 then
        return M.S.hudTimerCacheSec
    end
    M.S.hudTimerCacheAt = now
    M.S.hudTimerCacheSec = nil
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return nil end
    local best = nil
    pcall(function()
        for _, d in ipairs(pg:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then
                local t = tostring(d.Text or ""):gsub("%s+", " ")
                -- "2m 23s" / "2m23s" (boleh ada teks di sekitar)
                local m, s = t:match("(%d+)%s*m%s*(%d+)%s*s")
                if m then
                    local sec = tonumber(m) * 60 + tonumber(s)
                    if sec and sec > 0 and sec < 1200 and (not best or sec < best) then
                        best = sec
                    end
                else
                    -- "2:30" / "0:45"
                    local mm, ss = t:match("(%d+)%s*:%s*(%d%d)")
                    if mm then
                        local sec = tonumber(mm) * 60 + tonumber(ss)
                        if sec and sec > 0 and sec < 1200 and (not best or sec < best) then
                            best = sec
                        end
                    else
                        local sOnly = t:match("^(%d+)%s*s$")
                        if sOnly then
                            local sec = tonumber(sOnly)
                            if sec and sec > 0 and sec < 1200 and (not best or sec < best) then
                                best = sec
                            end
                        end
                    end
                end
            end
        end
    end)
    M.S.hudTimerCacheSec = best
    return best
end

-- Sisa malam (detik). Prioritas: PhaseDuration server → HUD → estimasi clock.
function M.GetNightRemainingSec()
    if M.IsNight() ~= true then return 0 end

    local phase = workspace:GetAttribute("ActivePhase")
    local phaseEnd = workspace:GetAttribute("PhaseDuration")
    if type(phaseEnd) == "number" then
        local phaseOk = true
        if type(phase) == "string" and phase ~= "" then
            local pl = string.lower(phase)
            phaseOk = (pl == "night") or string.find(pl, "night", 1, true) ~= nil
        end
        if phaseOk then
            local okNow, now = pcall(function()
                return workspace:GetServerTimeNow()
            end)
            if okNow and type(now) == "number" then
                local left = phaseEnd - now
                if left < 0 then left = 0 end
                -- Sanity: fase malam biasanya < 20 menit
                if left <= 1200 then
                    return left
                end
            end
        end
    end

    local hud = M._parseHudTimer()
    if type(hud) == "number" and hud >= 0 then return hud end

    if type(M.S.nightStartedAt) ~= "number" then return math.huge end
    local dur = tonumber(M.S.lastNightDuration) or 0
    if dur < 60 then dur = M.C.DEFAULT_NIGHT_DUR end
    local left = dur - (os.clock() - M.S.nightStartedAt)
    if left < 0 then left = 0 end
    return left
end

M._move = {}

function M._move.api()
    local g = (getgenv and getgenv()) or G
    local m = (type(g.GAG2) == "table" and g.GAG2.Move)
        or (type(g.NodeHub) == "table" and g.NodeHub.Move)
        or g.Move or G.Move or G.MoveModule or rawget(_G, "Move")
    return type(m) == "table" and m or nil
end

function M._move.goTo(cf, reason, priority)
    local Move = M._move.api()
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then return false, "no_move" end
    local mode = M.GetTravelMode()
    if mode ~= "walk" and mode ~= "soft" and mode ~= "step" and mode ~= "hard" then mode = "walk" end
    local why = tostring(reason or "steal")
    if not string.find(string.lower(why), "steal", 1, true) then why = "steal" end
    local pri = tonumber(priority) or 100
    local callOk, moved, err = pcall(Move.GoTo, cf, { mode = mode, reason = why, priority = pri })
    if not callOk then return false, tostring(moved) end
    if moved then return true, mode end
    return false, tostring(err or "goto_fail")
end

function M._move.goHome(opts)
    opts = type(opts) == "table" and opts or {}
    local Move = M._move.api()
    local mode = opts.mode or M.GetTravelMode()
    if mode ~= "walk" and mode ~= "soft" and mode ~= "step" and mode ~= "hard" then mode = "walk" end
    local pri = tonumber(opts.priority) or 110
    local reason = tostring(opts.reason or "steal_flee")
    if not string.find(string.lower(reason), "steal", 1, true) then
        reason = "steal_flee"
    end

    -- Pastikan bisa jalan (stun/ragdoll residual)
    pcall(function()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hum then
            hum.PlatformStand = false
            hum.Sit = false
        end
        if hrp then
            hrp.Anchored = false
        end
    end)

    if type(Move) == "table" and type(Move.ToGarden) == "function" then
        local callOk, moved, err = pcall(Move.ToGarden, {
            reason = reason,
            fineTune = true,
            mode = mode,
            priority = pri,
            buttonWait = tonumber(opts.buttonWait) or 2.5,
        })
        if callOk and moved then
            task.wait(0.2)
            return true, tostring(err or "garden")
        end
        if not callOk then
            return false, "togarden_err:" .. tostring(moved)
        end
        -- ToGarden false → fallback GoTo di bawah; simpan err
        opts._lastErr = tostring(err or "togarden_fail")
    end

    if type(Move) == "table" and type(Move.GetGardenCFrame) == "function" then
        local okCf, cf = pcall(Move.GetGardenCFrame)
        if okCf and typeof(cf) == "CFrame" then
            local ok, why = M._move.goTo(cf, reason, pri)
            if ok then
                task.wait(0.2)
                return true, why
            end
            return false, tostring(why or opts._lastErr or "goto_fail")
        end
        return false, "no_garden_cf"
    end
    return false, opts._lastErr or "no_move"
end

function M._move.deposit(reason, timeoutSec)
    reason = tostring(reason or "deposit")
    timeoutSec = tonumber(timeoutSec) or M.C.NIGHT_DEPOSIT_TO
    if M.GetCarryCount() <= 0 then
        M.S.returningHome = false
        -- Carry kosong tapi seed baru selesai fire → tetap masuk wait_buff
        if M._buffMethod.enabled() and (M.S.buffMethodPhase == "seed")
            and (reason == "buff_seed" or reason == "home_seed") then
            M._buffMethod.onDepositOk(reason)
        end
        return true, "empty"
    end
    if M.S.returningHome then return false, "busy" end
    M.S.returningHome = true
    M._publish(string.format("HOME %s C%d", reason, M.GetCarryCount()))
    local t0 = os.clock()
    while M.GetCarryCount() > 0 and (os.clock() - t0) < timeoutSec do
        M._move.goHome()
        task.wait(0.45)
    end
    local left = M.GetCarryCount()
    M.S.returningHome = false
    if left > 0 then
        M._publish(string.format("HOME FAIL C%d", left))
        return false, "timeout"
    end
    M._publish("HOME · deposited")
    M._buffMethod.onDepositOk(reason)
    return true, "ok"
end

function M._move.shouldReturnHome()
    if M.S.returningHome then return true, "returning" end
    local carry = M.GetCarryCount()
    if carry <= 0 then return false, "no_carry" end
    -- Method wait_buff / seed+carry: JANGAN pulang/deposit — diam pegang buah nunggu buff
    if M._buffMethod.enabled() then
        local ph = M.S.buffMethodPhase
        if ph == "wait_buff" then
            return false, "wait_buff"
        end
        if ph == "seed" and carry >= 1 then
            return false, "seed_hold"
        end
    end
    if carry >= M.C.CARRY_RETURN_AT then return true, "carry_full" end
    if M.IsNight() == false then return true, "night_end" end
    local left = M.GetNightRemainingSec()
    if type(left) == "number" and left < math.huge and left <= M.C.NIGHT_RETURN_LEAD then
        return true, "night_ending"
    end
    return false, "ok"
end

function M._move.tryDeposit(reasonHint)
    local need, why = M._move.shouldReturnHome()
    if not need then return false, why end
    if why == "returning" then return false, "busy" end
    return M._move.deposit(reasonHint or why)
end

-- Dog/Hedgehog: jaga jarak stand (bukan kabur garden). Stun = delay lalu lanjut.
M._dog = {}
M._flee = {}

function M._flee.busy()
    return M.S.fleeing == true
end

function M._flee.safeHere()
    return LP:GetAttribute("IsInOwnGarden") == true
        or LP:GetAttribute("InSafeZone") == true
end

function M._flee.cancelSteal()
    local net = M._net.get()
    if not net then return end
    local cancel = net.CancelSteal
    if type(cancel) == "table" and type(cancel.Fire) == "function" then
        pcall(function() cancel:Fire() end)
    elseif typeof(cancel) == "Instance" and cancel:IsA("RemoteEvent") then
        pcall(function() cancel:FireServer() end)
    end
end

function M._flee.stopJump()
    M.S.fleeJumpToken += 1
end

function M._flee.resumeFarmLabel()
    if not M.S.running then return end
    if M.GetBuffOnly() then
        M._setPhase("BuffFarm", string.format("BUFF · resume %s/%s", M._moveMode(), M.GetTravelMode()))
    else
        M._setPhase("Farm", string.format("FARM resume %s/%s", M._moveMode(), M.GetTravelMode()))
    end
end

function M._dog.isDefenseSpecies(species)
    local defense = M.C.FLEE_DEFENSE
    return type(defense) == "table" and defense[tostring(species or "")] == true
end

function M._dog.enabled()
    return M.GetDogAvoid() == true
end

function M._dog.isDefenseSlot(slot)
    if not slot or not slot.Parent then return false end
    local species = slot:GetAttribute("PetSpecies")
    if type(species) ~= "string" or species == "" then return false end
    return M._dog.isDefenseSpecies(species)
end

function M._dog.flatDist(a, b)
    local dx = a.X - b.X
    local dz = a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

function M._dog.nearRadius()
    return tonumber(M.C.DOG_NEAR_RADIUS) or 120
end

function M._dog.safeStuds()
    return tonumber(M.C.DOG_SAFE_STUDS) or 70
end

-- Cache posisi Dog/Hedgehog saja (skip slot kosong). Refresh jarang.
function M._dog.defensePositions(force)
    if not M._dog.enabled() then
        M.S.dogPosCache = {}
        return M.S.dogPosCache
    end
    local ttl = tonumber(M.C.DOG_CACHE_TTL) or 0.75
    local now = os.clock()
    if not force and type(M.S.dogPosCache) == "table" and (now - (M.S.dogPosCacheAt or 0)) < ttl then
        return M.S.dogPosCache
    end
    local list = {}
    local root = workspace:FindFirstChild("PlayerPetReferences")
    if root then
        local myName = LP.Name
        local defense = M.C.FLEE_DEFENSE
        for _, folder in ipairs(root:GetChildren()) do
            if folder:IsA("Folder") and folder.Name ~= myName then
                for _, slot in ipairs(folder:GetChildren()) do
                    if slot:IsA("BasePart") then
                        local species = slot:GetAttribute("PetSpecies")
                        if type(species) == "string" and species ~= "" and defense[species] == true then
                            list[#list + 1] = slot.Position
                        end
                    end
                end
            end
        end
    end
    M.S.dogPosCache = list
    M.S.dogPosCacheAt = now
    return list
end

-- Pusat map dari cache saja (jangan rebuild plot di hot path)
function M._dog.mapCenterFlat()
    local refs = M.S.plotBackCache
    if type(refs) == "table" and #refs > 0 then
        local sx, sz, n = 0, 0, 0
        for i = 1, #refs do
            local p = refs[i].pos
            if typeof(p) == "Vector3" then
                sx += p.X
                sz += p.Z
                n += 1
            end
        end
        if n > 0 then return Vector3.new(sx / n, 0, sz / n) end
    end
    local me = M._util.hrp()
    if me then return Vector3.new(me.Position.X, 0, me.Position.Z) end
    return Vector3.zero
end

-- Jarak dog terdekat ke pos (hanya dog dalam radius dari anchor)
function M._dog.minDistAt(pos, anchor, maxFromAnchor)
    if typeof(pos) ~= "Vector3" then return math.huge end
    local list = M._dog.defensePositions(false)
    if #list == 0 then return math.huge end
    local best = math.huge
    local useAnchor = typeof(anchor) == "Vector3"
    local maxA = tonumber(maxFromAnchor) or M._dog.nearRadius()
    local maxA2 = maxA * maxA
    local ax, az = useAnchor and anchor.X or 0, useAnchor and anchor.Z or 0
    local px, pz = pos.X, pos.Z
    for i = 1, #list do
        local p = list[i]
        if useAnchor then
            local dax = p.X - ax
            local daz = p.Z - az
            if (dax * dax + daz * daz) > maxA2 then continue end
        end
        local dx = p.X - px
        local dz = p.Z - pz
        local d2 = dx * dx + dz * dz
        if d2 < best then best = d2 end
    end
    if best >= math.huge then return math.huge end
    return math.sqrt(best)
end

function M._dog.minDistFromMe()
    local me = M._util.hrp()
    if not me then return math.huge end
    return M._dog.minDistAt(me.Position, me.Position, M._dog.nearRadius())
end

function M._dog.nearestDefensePos(fromPos)
    if typeof(fromPos) ~= "Vector3" then return nil, math.huge end
    local list = M._dog.defensePositions(false)
    local bestD2, bestPos = math.huge, nil
    local maxA = M._dog.nearRadius()
    local maxA2 = maxA * maxA
    local fx, fz = fromPos.X, fromPos.Z
    for i = 1, #list do
        local p = list[i]
        local dx = p.X - fx
        local dz = p.Z - fz
        local d2 = dx * dx + dz * dz
        if d2 <= maxA2 and d2 < bestD2 then
            bestD2, bestPos = d2, p
        end
    end
    if not bestPos then return nil, math.huge end
    return bestPos, math.sqrt(bestD2)
end

-- Stand murah: arah dalam pulau, 1–2 arah saja (tanpa raycast / ring 360°)
function M._dog.pickSafeStand(fruitPos, preferStand)
    if typeof(fruitPos) ~= "Vector3" then return nil end
    local me = M._util.hrp()
    if not me then return nil end
    local stealR = M._stealRange()
    preferStand = tonumber(preferStand) or math.min(85, math.max(35, stealR - 20))
    local safeR = M._dog.safeStuds()
    local y = me.Position.Y
    local center = M._dog.mapCenterFlat()
    local inward = M._util.flatUnitXZ(center - fruitPos)
    if inward.Magnitude < 1e-3 then
        inward = M._util.flatUnitXZ(me.Position - fruitPos)
    end
    local side = Vector3.new(-inward.Z, 0, inward.X)
    local candidates = {
        fruitPos + inward * preferStand,
        fruitPos + M._util.flatUnitXZ(inward * 0.7 + side * 0.3) * preferStand,
        fruitPos + M._util.flatUnitXZ(inward * 0.7 - side * 0.3) * preferStand,
        fruitPos + inward * math.max(25, preferStand - 20),
        me.Position,
    }
    local bestPos, bestScore = nil, -1e9
    for i = 1, #candidates do
        local stand = candidates[i]
        local dFruit = M._dog.flatDist(stand, fruitPos)
        if dFruit > stealR then continue end
        local dDog = M._dog.minDistAt(stand, me.Position, M._dog.nearRadius())
        if dDog <= safeR then continue end
        local standR = M._dog.flatDist(stand, center)
        local fruitR = M._dog.flatDist(fruitPos, center)
        if standR > fruitR + 10 then continue end -- tolak arah jurang
        local score = (fruitR - standR) * 2 - math.abs(dFruit - preferStand)
        if score > bestScore then
            bestScore = score
            bestPos = Vector3.new(stand.X, y, stand.Z)
        end
    end
    if not bestPos then return nil end
    return CFrame.lookAt(bestPos, Vector3.new(fruitPos.X, bestPos.Y, fruitPos.Z)), bestPos
end

function M._dog.fruitHasSafeStand(fruitPos)
    -- Lite: cukup dog tidak nempel buah
    if typeof(fruitPos) ~= "Vector3" then return false end
    local skip = tonumber(M.C.DOG_FRUIT_SKIP) or 12
    local d = M._dog.minDistAt(fruitPos, fruitPos, M._dog.nearRadius())
    return d >= skip
end

-- Reposisi murah: dorong ke pusat pulau. Tanpa bestSafeInRange / raycast.
function M._dog.repositionIfTooClose()
    if not M._dog.enabled() then return false end
    if M.S.fleeing or M.S.returningHome then return false end
    if M._flee.safeHere() then return false end
    local now = os.clock()
    local cd = tonumber(M.C.DOG_REPOS_COOLDOWN) or 0.8
    if (now - (M.S.dogReposAt or 0)) < cd then return false end

    local me = M._util.hrp()
    if not me then return false end
    local safeR = M._dog.safeStuds()
    local nearPos, dDog = M._dog.nearestDefensePos(me.Position)
    if not nearPos or dDog > safeR then return false end

    M.S.dogReposAt = now
    local center = M._dog.mapCenterFlat()
    local toCenter = Vector3.new(center.X - me.Position.X, 0, center.Z - me.Position.Z)
    if toCenter.Magnitude < 1e-3 then
        toCenter = Vector3.new(me.Position.X - nearPos.X, 0, me.Position.Z - nearPos.Z)
    end
    if toCenter.Magnitude < 1e-3 then return false end
    local step = math.max(20, safeR - dDog + 10)
    local goal = me.Position + toCenter.Unit * step
    M._publish(string.format("DOG · inward d%.0f", dDog))
    M._move.goTo(CFrame.lookAt(goal, Vector3.new(nearPos.X, goal.Y, nearPos.Z)), "steal")
    return true
end

function M._flee.isRagdolled()
    local char = LP.Character
    if not char then return false end
    if char:GetAttribute("Ragdolled") == true then return true end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum and hum.PlatformStand == true then return true end
    return false
end

function M._flee.pauseAfterHit(why)
    why = tostring(why or "stun")
    if M.S.fleeing then return false, "busy" end
    M.S.fleeing = true
    M._flee.stopJump()
    M._flee.cancelSteal()
    local delay = tonumber(M.C.FLEE_HIT_DELAY) or 3
    M._setPhase("StunWait", string.format("STUN · wait %.0fs lalu steal", delay))
    M._publish(string.format("STUN · %s delay %.0fs", why, delay))

    local c0 = os.clock()
    while M.S.running and (os.clock() - c0) < delay do
        task.wait(0.2)
    end

    M.S.fleeing = false
    M.S.petDistCache = {}
    M.S.dogPosCache = nil
    M.S.dogPosCacheAt = 0
    M.S.dogReposAt = 0
    M._flee.resumeFarmLabel()
    if M.S.running then
        M._publish("STUN · done → farm")
    end
    return true, "ok"
end

function M._flee.tick()
    if not M.S.running then return end
    if M.S.fleeing or M.S.returningHome then return end
    if M._flee.safeHere() then return end
    if M._flee.isRagdolled() then
        M._flee.pauseAfterHit("stun")
        return
    end
    -- Toggle OFF → tidak reposisi dog
    if M._dog.enabled() then
        M._dog.repositionIfTooClose()
    end
end

function M._flee.monitor(myId)
    local poll = tonumber(M.C.FLEE_POLL) or 0.12
    while M.S.running and M.S.loopId == myId do
        pcall(M._flee.tick)
        task.wait(poll)
    end
    M._flee.stopJump()
    M.S.fleeing = false
end

function M._move.bindNightWatch()
    if M.S.nightWatchConn then pcall(function() M.S.nightWatchConn:Disconnect() end) M.S.nightWatchConn = nil end
    local n = ReplicatedStorage:FindFirstChild("Night")
    if not n then return end
    M.S.lastNightWas = (n.Value == true or n.Value == 1)
    if M.S.lastNightWas == true and M.S.nightStartedAt == nil then M.S.nightStartedAt = os.clock() end
    M.S.nightWatchConn = n:GetPropertyChangedSignal("Value"):Connect(function()
        local on = (n.Value == true or n.Value == 1)
        local was = M.S.lastNightWas
        M.S.lastNightWas = on
        if was ~= true and on == true then
            M.S.nightStartedAt = os.clock()
            M.S.hudTimerCacheSec = nil
            M.S.nightTotal = 0
            M.S.failTotal = 0
            M.S.skipTotal = 0
            M.S.fireTotal = 0
            M.S.farmTriedKeys = {}
            M.S.failAttempts = {}
            M.S.scanDirty = true
            M.S.scanDirtyWhy = "night_start"
            if M.S.running then
                M._publish(string.format("NIGHT %s/%s", M._moveMode(), M.GetTravelMode()))
            end
        elseif was == true and on ~= true then
            if type(M.S.nightStartedAt) == "number" then
                local dur = os.clock() - M.S.nightStartedAt
                if dur >= 45 then M.S.lastNightDuration = dur end
            end
            M.S.nightStartedAt = nil
            M.S.hudTimerCacheSec = nil
            if M.S.running or M.GetCarryCount() > 0 then
                task.spawn(function()
                    if M.GetCarryCount() > 0 then M._move.deposit("night_end_watch") end
                end)
            end
        end
    end)
end

M._orbit = {}

-- Jarak stand ke buah: makin banyak fail → makin dekat
function M._orbit.preferStandFor(t)
    local stealR = M._stealRange()
    local base = math.min(85, math.max(35, stealR - 20))
    local key = type(t) == "table" and M._util.farmTargetKey(t) or nil
    local n = M._util.failCount(key)
    if n <= 0 then return base end
    local steps = M.C.STAND_FAIL_STEPS
    if type(steps) ~= "table" or #steps == 0 then
        steps = { 80, 55, 35, 22 }
    end
    local idx = math.min(math.max(n, 1), #steps)
    local want = tonumber(steps[idx]) or base
    if want > base then want = base end
    if want < 12 then want = 12 end
    return want
end

function M._orbit.nudgeCloser(t, failN)
    if type(t) ~= "table" or typeof(t.position) ~= "Vector3" then return false end
    if M.S.fleeing or M.S.returningHome then return false end
    local prefer = M._orbit.preferStandFor(t)
    M._publish(string.format(
        "FAIL#%d closer → stand%.0f $%s",
        tonumber(failN) or 0,
        prefer,
        M._util.fmtPrice(t.price)
    ))
    return M._orbit.goToFruitStand(t)
end

function M._orbit.backSideAxes(ref, mapCenter)
    local cf, size = ref.CFrame, ref.Size
    local outWanted = M._util.flatUnitXZ(ref.Position - mapCenter)
    local axes = {
        { n = cf.LookVector, half = size.Z * 0.5 },
        { n = -cf.LookVector, half = size.Z * 0.5 },
        { n = cf.RightVector, half = size.X * 0.5 },
        { n = -cf.RightVector, half = size.X * 0.5 },
    }
    local back, bestDot = axes[1], -math.huge
    for i = 1, #axes do
        local a = axes[i]
        local nFlat = Vector3.new(a.n.X, 0, a.n.Z)
        if nFlat.Magnitude > 1e-4 then
            local d = nFlat.Unit:Dot(outWanted)
            if d > bestDot then bestDot, back = d, a end
        end
    end
    local side
    if back.n == cf.LookVector or back.n == -cf.LookVector then
        side = { n = cf.RightVector, half = size.X * 0.5 }
    else
        side = { n = cf.LookVector, half = size.Z * 0.5 }
    end
    return back, side
end

function M._orbit.backCorners(ref, mapCenter, pad)
    pad = tonumber(pad) or M.C.BACK_PAD
    local back, side = M._orbit.backSideAxes(ref, mapCenter)
    local y = ref.Position.Y + M.C.BACK_Y_OFF
    local backN = M._util.flatUnitXZ(back.n)
    local sideN = M._util.flatUnitXZ(side.n)
    local midBack = ref.Position + back.n * back.half + backN * pad
    local bl = midBack - sideN * side.half
    local br = midBack + sideN * side.half
    return {
        { pos = Vector3.new(bl.X, y, bl.Z), tag = "BL", halfBack = back.half, halfSide = side.half },
        { pos = Vector3.new(br.X, y, br.Z), tag = "BR", halfBack = back.half, halfSide = side.half },
    }
end

function M._orbit.ensureCorners(r, mapCenter)
    local corners = M._orbit.backCorners(r.ref, mapCenter, M.C.BACK_PAD)
    if r.spawn and r.spawn:IsA("BasePart") then
        local spawnR = (Vector3.new(r.spawn.Position.X, 0, r.spawn.Position.Z) - mapCenter).Magnitude
        local mid = (corners[1].pos + corners[2].pos) * 0.5
        local midR = (Vector3.new(mid.X, 0, mid.Z) - mapCenter).Magnitude
        if midR + 1 < spawnR then
            local cf, size = r.ref.CFrame, r.ref.Size
            local outWanted = M._util.flatUnitXZ(r.pos - mapCenter)
            local axes = {
                { n = cf.LookVector, half = size.Z * 0.5 },
                { n = -cf.LookVector, half = size.Z * 0.5 },
                { n = cf.RightVector, half = size.X * 0.5 },
                { n = -cf.RightVector, half = size.X * 0.5 },
            }
            local backAx, worst = axes[1], math.huge
            for i = 1, #axes do
                local a = axes[i]
                local nFlat = Vector3.new(a.n.X, 0, a.n.Z)
                if nFlat.Magnitude > 1e-4 then
                    local d = nFlat.Unit:Dot(outWanted)
                    if d < worst then worst, backAx = d, a end
                end
            end
            local side
            if backAx.n == cf.LookVector or backAx.n == -cf.LookVector then
                side = { n = cf.RightVector, half = size.X * 0.5 }
            else
                side = { n = cf.LookVector, half = size.Z * 0.5 }
            end
            local y = r.pos.Y + M.C.BACK_Y_OFF
            local backN = M._util.flatUnitXZ(backAx.n)
            local sideN = M._util.flatUnitXZ(side.n)
            local midBack = r.pos + backAx.n * backAx.half + backN * M.C.BACK_PAD
            local bl = midBack - sideN * side.half
            local br = midBack + sideN * side.half
            corners = {
                { pos = Vector3.new(bl.X, y, bl.Z), tag = "BL" },
                { pos = Vector3.new(br.X, y, br.Z), tag = "BR" },
            }
        end
    end
    return corners
end

function M._orbit.buildPlotRefs()
    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then return {} end
    local refs, sx, sz, n = {}, 0, 0, 0
    for _, plot in ipairs(gardens:GetChildren()) do
        if string.match(plot.Name, "^Plot%d+") then
            local ref = plot:FindFirstChild("PlotSizeReference", true)
            local spawn = plot:FindFirstChild("SpawnPoint", true)
            if ref and ref:IsA("BasePart") then
                local p = ref.Position
                refs[#refs + 1] = { plot = plot, ref = ref, spawn = spawn, pos = p, size = ref.Size }
                sx += p.X; sz += p.Z; n += 1
        end
    end
    end
    if n <= 0 then return {} end
    local mapCenter = Vector3.new(sx / n, 0, sz / n)
    for _, r in ipairs(refs) do
        r.corners = M._orbit.ensureCorners(r, mapCenter)
        r.back = (r.corners[1].pos + r.corners[2].pos) * 0.5
        local flat = Vector3.new(r.pos.X - mapCenter.X, 0, r.pos.Z - mapCenter.Z)
        r.ang = math.atan2(flat.Z, flat.X)
        local oid = tonumber(r.plot:GetAttribute("OwnerUserId")) or tonumber(r.plot:GetAttribute("UserId")) or tonumber(r.plot:GetAttribute("OwnerId"))
        r.ownerUserId = oid
        r.isOwn = (oid == LP.UserId) or (tostring(r.plot:GetAttribute("Owner") or "") == LP.Name)
    end
    table.sort(refs, function(a, b) return (a.ang or 0) < (b.ang or 0) end)
    return refs
end

function M._orbit.getPlotRefs(force)
    local now = os.clock()
    if force or not M.S.plotBackCache or (now - M.S.plotBackCacheAt) > 20 then
        M.S.plotBackCache = M._orbit.buildPlotRefs()
        M.S.plotBackCacheAt = now
        M.S.orbitWpCache = nil
    end
    return M.S.plotBackCache or {}
end

function M._orbit.buildWaypoints(force)
    local refs = M._orbit.getPlotRefs(force)
    local waypoints, sx, sz, n = {}, 0, 0, 0
    for i = 1, #refs do
        local r = refs[i]
        if not r.isOwn and typeof(r.pos) == "Vector3" then sx += r.pos.X; sz += r.pos.Z; n += 1 end
    end
    local mapCenter = n > 0 and Vector3.new(sx / n, 0, sz / n) or Vector3.zero
    for i = 1, #refs do
        local r = refs[i]
        if r.isOwn then continue end
        local corners = r.corners or M._orbit.ensureCorners(r, mapCenter)
        r.corners = corners
        for _, c in ipairs(corners) do
            local flat = Vector3.new(c.pos.X - mapCenter.X, 0, c.pos.Z - mapCenter.Z)
            waypoints[#waypoints + 1] = {
                pos = c.pos, tag = c.tag, plot = r.plot, plotName = r.plot and r.plot.Name or "?",
                plotPos = r.pos, ownerUserId = r.ownerUserId, ang = math.atan2(flat.Z, flat.X),
            }
        end
    end
    table.sort(waypoints, function(a, b)
        if a.ang == b.ang then return tostring(a.tag) < tostring(b.tag) end
        return a.ang < b.ang
    end)
    return waypoints, mapCenter
end

function M._orbit.getWaypoints(force)
    local now = os.clock()
    if force or not M.S.orbitWpCache or (now - M.S.orbitWpCacheAt) > 20 then
        M.S.orbitWpCache = { M._orbit.buildWaypoints(force) }
        M.S.orbitWpCacheAt = now
    end
    return M.S.orbitWpCache[1] or {}
end

function M._orbit.nearestStart(waypoints)
    local me = M._util.hrp()
    if not me or type(waypoints) ~= "table" or #waypoints == 0 then return 1 end
    local bestD, start = math.huge, 1
    for i, w in ipairs(waypoints) do
        local d = (Vector3.new(w.pos.X, 0, w.pos.Z) - Vector3.new(me.Position.X, 0, me.Position.Z)).Magnitude
        if d < bestD then bestD, start = d, i end
    end
    return start
end

function M._orbit.goCorner(w)
    if type(w) ~= "table" or typeof(w.pos) ~= "Vector3" then return false end
    local look = w.plotPos or w.pos
    local cf = CFrame.lookAt(w.pos, Vector3.new(look.X, w.pos.Y, look.Z))
    M._publish(string.format("ORBIT %s %s", tostring(w.plotName), tostring(w.tag)))
    local ok = M._move.goTo(cf, "steal")
    task.wait(0.15)
    return ok
end

function M._orbit.goToFruitStand(t)
    if type(t) ~= "table" or typeof(t.position) ~= "Vector3" then return false end
    local pos = t.position
    local d = M._util.flatDist(pos)
    t.dist = d
    local preferStand = M._orbit.preferStandFor(t)
    local me = M._util.hrp()
    if not me then return false end
    local stealR = M._stealRange()
    local tol = math.max(8, preferStand * 0.25)

    -- Toggle dog OFF: stand biasa ke buah (tanpa filter dog / raycast)
    if not M._dog.enabled() then
        if d <= stealR and d <= (preferStand + tol) then
            return true
        end
        local dir = M._util.flatUnitXZ(Vector3.new(me.Position.X - pos.X, 0, me.Position.Z - pos.Z))
        local goalPos = Vector3.new(pos.X, me.Position.Y, pos.Z) + dir * preferStand
        local cf = CFrame.lookAt(goalPos, Vector3.new(pos.X, goalPos.Y, pos.Z))
        M._publish(string.format(
            "MOVE $%s fruit%.0f stand%.0f (dog off)",
            M._util.fmtPrice(t.price), d, preferStand
        ))
        M._move.goTo(cf, "steal")
        task.wait(0.2)
        return true
    end

    local safeR = M._dog.safeStuds()
    local dDogMe = M._dog.minDistFromMe()
    if d <= stealR and d <= (preferStand + tol) and dDogMe > safeR then
        return true
    end

    local cf = M._dog.pickSafeStand(pos, preferStand)
    if cf then
        M._publish(string.format(
            "MOVE safe $%s fruit%.0f stand%.0f dog>%.0f",
            M._util.fmtPrice(t.price), d, preferStand, safeR
        ))
        M._move.goTo(cf, "steal")
        task.wait(0.2)
        return true
    end

    M._publish(string.format("SKIP dog-near $%s", M._util.fmtPrice(t.price)))
    return false
end

function M._orbit.getOwnPlot(force)
    local refs = M._orbit.getPlotRefs(force == true)
    for i = 1, #refs do
        if refs[i].isOwn then return refs[i] end
    end
    return nil
end

function M._orbit.goOwnCorner(own, corner)
    if type(own) ~= "table" or type(corner) ~= "table" or typeof(corner.pos) ~= "Vector3" then
        return false
    end
    local look = own.pos or corner.pos
    -- hadap ke luar / ke tetangga, bukan ke center plot
    local meLook = look
    if typeof(own.pos) == "Vector3" then
        local mid = corner.pos
        local outward = Vector3.new(mid.X - own.pos.X, 0, mid.Z - own.pos.Z)
        if outward.Magnitude > 1e-3 then
            meLook = mid + outward.Unit * 8
                end
            end
    local cf = CFrame.lookAt(corner.pos, Vector3.new(meLook.X, corner.pos.Y, meLook.Z))
    M._publish(string.format("NEAR own %s", tostring(corner.tag or "?")))
    local ok = M._move.goTo(cf, "steal")
    task.wait(0.15)
    return ok
end

M._net = {}

function M._net.get()
    local now = os.clock()
    if M.S.stealNet and (now - M.S.stealNetAt) < 8 then return M.S.stealNet end
    M.S.stealNetAt = now
    local ok, Net = pcall(function()
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local n = sm and sm:FindFirstChild("Networking")
        if n then
            local m = require(n)
            if type(m) == "table" and type(m.Steal) == "table" then return m.Steal end
        end
        return nil
    end)
    if ok and type(Net) == "table" then M.S.stealNet = Net return Net end
    local stealFolder = nil
                    pcall(function()
        local net = ReplicatedStorage:FindFirstChild("Networking") or ReplicatedStorage:FindFirstChild("Remotes")
        if net then stealFolder = net:FindFirstChild("Steal") end
    end)
    if stealFolder then
        M.S.stealNet = {
            BeginSteal = stealFolder:FindFirstChild("BeginSteal"),
            CompleteSteal = stealFolder:FindFirstChild("CompleteSteal"),
            CancelSteal = stealFolder:FindFirstChild("CancelSteal"),
        }
        return M.S.stealNet
    end
    M.S.stealNet = nil
    return nil
end

function M._net.refreshPrompt(t)
    if type(t) ~= "table" or not t.model or not t.model.Parent then return end
    if not t.prompt or not t.prompt.Parent then
        t.prompt = M._scan.stealPromptUnder(t.model)
        t.hasPrompt = t.prompt ~= nil
        end
    end

function M._net.verifySuccess(carryBefore)
    local t0 = os.clock()
    while (os.clock() - t0) < M.C.FAIL_POLL_MAX do
        if M.GetCarryCount() > carryBefore then return true end
        if (os.clock() - t0) >= M.C.FAIL_POLL_MIN then
            if M.GetCarryCount() > carryBefore then return true end
        end
        task.wait(0.05)
    end
    return M.GetCarryCount() > carryBefore
end

function M.StealTarget(t)
    if M.S.fleeing then return false, "fleeing" end
    if type(t) ~= "table" then return false, "bad_target" end
    M._net.refreshPrompt(t)
    if not (t.hasPrompt == true or (t.prompt and t.prompt.Parent)) then return false, "no_prompt" end
    if not t.ownerUserId or not t.plantId then return false, "missing_ids" end
    if typeof(t.position) == "Vector3" then t.dist = M._util.flatDist(t.position) end
    if (tonumber(t.dist) or math.huge) > M._stealRange() then return false, "too_far" end
    local flagSeed = t.flagSeed or t.seed
    if t.stealable == false or not M._flags.isPlantStealable(flagSeed) then return false, "not_stealable" end
    local net = M._net.get()
    if not net or type(net.BeginSteal) ~= "table" or type(net.BeginSteal.Fire) ~= "function" then
        if t.prompt and fireproximityprompt then
            pcall(fireproximityprompt, t.prompt)
            return true, "prompt"
        end
        return false, "no_remote"
    end
    local hold = M._flags.resolveHold(flagSeed, t.prompt)
    if tonumber(t.hold) and tonumber(t.hold) > hold then hold = tonumber(t.hold) end
    local okBegin = pcall(function() net.BeginSteal:Fire(t.ownerUserId, t.plantId, t.fruitId) end)
    if not okBegin then return false, "begin_fail" end
    -- Mirror StealController / steal test: HoldDuration==0 → Complete hampir langsung
    if hold <= 0 then task.wait(0.05) else task.wait(hold) end
    if type(net.CompleteSteal) == "table" and type(net.CompleteSteal.Fire) == "function" then
        pcall(function() net.CompleteSteal:Fire() end)
    end
    return true, "ok"
end

M._pick = {}

function M._pick.bestInRange(rows)
    rows = rows or M.S.lastRows or {}
    local maxD = M._stealRange()
    local best, bestPrice, bestD = nil, -1, math.huge
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not M._scan.isLiveRow(r) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        if not M._rowPassesFilters(r) then continue end
        local key = M._util.farmTargetKey(r)
        if M._util.isTried(key) then continue end
        local dMe = typeof(r.position) == "Vector3" and M._util.flatDist(r.position) or (tonumber(r.dist) or math.huge)
        if typeof(r.position) ~= "Vector3" and r.model then
            r.position = M._util.modelPos(r.model)
            dMe = M._util.flatDist(r.position)
        end
        r.dist = dMe
        if dMe > maxD then continue end
        local p = tonumber(r.price) or 0
        if p > bestPrice or (p == bestPrice and dMe < bestD) then best, bestPrice, bestD = r, p, dMe end
    end
    return best
end

-- Method seed: 1 buah apa saja. Prefer non-defender + in-range; fallback terdekat.
-- inRangeOnly=true → hanya ≤ steal_range (untuk fire)
function M._pick.bestSeedTarget(rows, inRangeOnly)
    rows = rows or M.S.lastRows or {}
    local maxD = M._stealRange()
    local bestNear, bestNearD = nil, math.huge
    local bestNd, bestNdD = nil, math.huge -- non-defender prefer
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not (r.hasPrompt == true or (r.prompt and r.prompt.Parent) or M._scan.isLiveRow(r)) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        -- seed: abaikan filter UI (pakai _rowPassesFilters yang sudah longgar di fase seed)
        if not M._rowPassesFilters(r) then continue end
        local key = M._util.farmTargetKey(r)
        if M._util.isTried(key) then continue end
        if typeof(r.position) ~= "Vector3" then
            if r.model then r.position = M._util.modelPos(r.model) else continue end
        end
        local dMe = M._util.flatDist(r.position)
        r.dist = dMe
        if inRangeOnly == true and dMe > maxD then continue end
        local nonDef = M.IsOwnerNonDefender(r.ownerUserId) == true
        if nonDef and dMe < bestNdD then
            bestNd, bestNdD = r, dMe
        end
        if dMe < bestNearD then
            bestNear, bestNearD = r, dMe
        end
    end
    return bestNd or bestNear
end

-- Prefer buah in-range; dog ON = skip buah yang nempel dog (1 cek jarak, tanpa ring/raycast)
function M._pick.bestSafeInRange(rows)
    if not M._dog.enabled() then
        return M._pick.bestInRange(rows)
    end
    rows = rows or M.S.lastRows or {}
    local maxD = M._stealRange()
    local skip = tonumber(M.C.DOG_FRUIT_SKIP) or 12
    local nearR = M._dog.nearRadius()
    -- Warm cache sekali untuk loop ini
    M._dog.defensePositions(false)
    local best, bestScore = nil, -1e9
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not M._scan.isLiveRow(r) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        if not M._rowPassesFilters(r) then continue end
        local key = M._util.farmTargetKey(r)
        if M._util.isTried(key) then continue end
        if typeof(r.position) ~= "Vector3" then
            if r.model then r.position = M._util.modelPos(r.model) else continue end
        end
        local dMe = M._util.flatDist(r.position)
        r.dist = dMe
        if dMe > maxD then continue end
        local dDogFruit = M._dog.minDistAt(r.position, r.position, nearR)
        if dDogFruit < skip then continue end
        local p = tonumber(r.price) or 0
        local score = p - dMe
        if score > bestScore then
            bestScore = score
            best = r
        end
    end
    if best then return best end
    return M._pick.bestInRange(rows)
end

function M._pick.bestGlobal(rows)
    rows = rows or M.S.lastRows or {}
    local best, bestP, bestD = nil, -1, math.huge
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not (r.hasPrompt == true or (r.prompt and r.prompt.Parent)) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        if not M._rowPassesFilters(r) then continue end
        local key = M._util.farmTargetKey(r)
        if M._util.isTried(key) then continue end
        local dMe = typeof(r.position) == "Vector3" and M._util.flatDist(r.position) or math.huge
        local p = tonumber(r.price) or 0
        if p > bestP or (p == bestP and dMe < bestD) then best, bestP, bestD = r, p, dMe end
    end
    return best
end

function M._pick.neighborPlot(rows)
    local refs = M._orbit.getPlotRefs(true)
    if #refs == 0 then return nil end
    local ownIdx = nil
    for i, r in ipairs(refs) do if r.isOwn then ownIdx = i break end end
    local cands = {}
    if ownIdx then
        local left = refs[((ownIdx - 2) % #refs) + 1]
        local right = refs[(ownIdx % #refs) + 1]
        if left and not left.isOwn then cands[#cands + 1] = left end
        if right and not right.isOwn and right ~= left then cands[#cands + 1] = right end
    else
        local me = M._util.hrp()
        local scored = {}
        for _, r in ipairs(refs) do
            if r.isOwn then continue end
            local d = math.huge
            if me and typeof(r.pos) == "Vector3" then
                d = (Vector3.new(r.pos.X - me.Position.X, 0, r.pos.Z - me.Position.Z)).Magnitude
            end
            scored[#scored + 1] = { r = r, d = d }
        end
        table.sort(scored, function(a, b) return a.d < b.d end)
        for i = 1, math.min(2, #scored) do cands[#cands + 1] = scored[i].r end
    end
    local bestR, bestScore = nil, -1
    rows = rows or M.S.lastRows or {}
    for _, r in ipairs(cands) do
        local oid = tonumber(r.ownerUserId)
        local total, top = 0, 0
        for i = 1, #rows do
            local info = rows[i]
            if info.stealable == false then continue end
            if oid and tonumber(info.ownerUserId) ~= oid then continue end
            if not M._rowPassesFilters(info) then continue end
            local p = tonumber(info.price) or 0
            total += p
            if p > top then top = p end
        end
        local score = total + top * 0.25
        if score > bestScore then bestR, bestScore = r, score end
    end
    if bestR then bestR._score = bestScore end
    return bestR, cands
end

-- Score buah yang reachable dari posisi (pojok plot sendiri) dalam maxDist
function M._pick.scoreReachableFrom(rows, fromPos, maxDist)
    if typeof(fromPos) ~= "Vector3" then return 0, nil end
    maxDist = tonumber(maxDist) or M._stealRange()
    rows = rows or M.S.lastRows or {}
    local total, best, bestP = 0, nil, -1
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not (r.hasPrompt == true or (r.prompt and r.prompt.Parent)) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        if not M._rowPassesFilters(r) then continue end
        local key = M._util.farmTargetKey(r)
        if M._util.isTried(key) then continue end
        if typeof(r.position) ~= "Vector3" then continue end
        local d = Vector3.new(r.position.X - fromPos.X, 0, r.position.Z - fromPos.Z).Magnitude
        if d > maxDist then continue end
        local p = tonumber(r.price) or 0
        total += p
        if p > bestP or (p == bestP and d < ((best and best._fromD) or math.huge)) then
            best, bestP = r, p
            best._fromD = d
        end
    end
    return total + math.max(0, bestP) * 0.25, best
end

-- Buah tetangga kiri/kanan (boleh jauh) — buat decide maju mendekat
function M._pick.bestNeighborFruit(rows, own)
    rows = rows or M.S.lastRows or {}
    local _, cands = M._pick.neighborPlot(rows)
    cands = cands or {}
    if #cands == 0 then
        -- fallback: global terbaik
        return M._pick.bestGlobal(rows)
    end
    local allow = {}
    for _, pl in ipairs(cands) do
        local oid = tonumber(pl.ownerUserId)
        if oid then allow[oid] = true end
    end
    local best, bestP, bestD = nil, -1, math.huge
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not (r.hasPrompt == true or (r.prompt and r.prompt.Parent)) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        if not allow[tonumber(r.ownerUserId) or -1] then continue end
        if not M._rowPassesFilters(r) then continue end
        local key = M._util.farmTargetKey(r)
        if M._util.isTried(key) then continue end
        local dMe = typeof(r.position) == "Vector3" and M._util.flatDist(r.position) or math.huge
        local p = tonumber(r.price) or 0
        if p > bestP or (p == bestP and dMe < bestD) then best, bestP, bestD = r, p, dMe end
    end
    return best
end

function M._pick.bestOwnCorner(own, rows)
    if type(own) ~= "table" or type(own.corners) ~= "table" then return nil, -1 end
    local maxD = M._stealRange()
    local bestC, bestScore = nil, -1
    for i = 1, #own.corners do
        local c = own.corners[i]
        if typeof(c.pos) == "Vector3" then
            local score = M._pick.scoreReachableFrom(rows, c.pos, maxD)
            if score > bestScore then bestC, bestScore = c, score end
        end
    end
    return bestC, bestScore
end

function M._pick.bestOnPlot(rows, plot)
    if type(plot) ~= "table" then return nil end
    local oid = tonumber(plot.ownerUserId)
    local best, bestP, bestD = nil, -1, math.huge
    rows = rows or M.S.lastRows or {}
    for i = 1, #rows do
        local r = rows[i]
        if r.stealable == false then continue end
        if not (r.hasPrompt == true or (r.prompt and r.prompt.Parent)) then continue end
        if not r.ownerUserId or not r.plantId then continue end
        if oid and tonumber(r.ownerUserId) ~= oid then continue end
        if not M._rowPassesFilters(r) then continue end
        if typeof(plot.pos) == "Vector3" and typeof(r.position) == "Vector3" then
            local dp = Vector3.new(r.position.X - plot.pos.X, 0, r.position.Z - plot.pos.Z).Magnitude
            if dp > M.C.PLOT_STEAL_RANGE then continue end
        end
        local dMe = typeof(r.position) == "Vector3" and M._util.flatDist(r.position) or math.huge
        local p = tonumber(r.price) or 0
        if p > bestP or (p == bestP and dMe < bestD) then best, bestP, bestD = r, p, dMe end
    end
    return best
end

M._farm = {}

-- Fire async 1× (full StealFlags hold) — tidak blok walk loop (sama steal test)
function M._farm.fireAsync(t)
    if type(t) ~= "table" or M.S.fleeing then return end
    task.spawn(function()
        if M.S.fleeing then return end
        local key = M._util.farmTargetKey(t)
        local carryBefore = M.GetCarryCount()
        local ok = select(1, M.StealTarget(t))
        local maxFail = math.max(2, math.floor(tonumber(M.C.STAND_FAIL_MAX) or 4))

        local function onFail()
            local n = M._util.bumpFail(key)
            if M._buffMethod.enabled() and M.S.buffMethodPhase == "seed" then
                M.S.buffMethodSeedPending = false
            end
            -- Fail → dekati stand (nearest / highest walk ikut goToFruitStand)
            if n < maxFail then
                task.spawn(function()
                    if M.S.running and not M.S.fleeing then
                        M._orbit.nudgeCloser(t, n)
                    end
                end)
            end
        end

        if not ok then
            onFail()
            return
        end
        -- verify di background (tidak blok fire loop)
        if M._net.verifySuccess(carryBefore) then
            M.S.nightTotal += 1
            if key then M.S.failAttempts[key] = nil end
            M._scan.removeKey(key)
            M.InvalidateScan("stolen")
            if M._buffMethod.enabled() and M.S.buffMethodPhase == "seed" then
                M.S.buffMethodSeedPending = false
            end
        else
            onFail()
        end
    end)
end

function M._farm.runFire(myId)
    local emptyStreak = 0
    while M.S.running and M.S.loopId == myId do
        if M.S.returningHome or M.S.fleeing then task.wait(0.2) continue end

        local bm = M._buffMethod.preFarmTick()
        if bm == "stop" then break end
        if bm == "idle" then
            -- wait_buff / tunggu moon: jangan spam 0.35s — hemat CPU
            local ph = M.S.buffMethodPhase
            if ph == "wait_buff" then
                task.wait(1.0)
            else
                task.wait(0.5)
            end
            continue
        end
        if bm == "home_seed" then
            M._move.deposit("buff_seed")
            task.wait(0.15)
            continue
        end

        local needHome, homeWhy = M._move.shouldReturnHome()
        if needHome and homeWhy ~= "returning" then
            M._move.tryDeposit(homeWhy)
            task.wait(0.15)
            continue
        end
        local okG, whyG = M.StealGateOk()
            if not okG then
            if (whyG == "not_night" or whyG == "defender") and M.GetCarryCount() > 0 then
                M._move.tryDeposit(whyG)
            end
            task.wait(0.35)
            continue
        end
        if M.C.FARM_TOTAL > 0 and M.S.fireTotal >= M.C.FARM_TOTAL then break end
        local left = M.GetNightRemainingSec()
        if M.GetCarryCount() > 0 and type(left) == "number" and left <= M.C.NIGHT_RETURN_LEAD then
            -- seed method: jangan nunggu night lead — sudah di-handle carry 1
            if not (M._buffMethod.enabled() and M._buffMethod.phase() == "seed") then
                M._move.tryDeposit("night_ending")
                task.wait(0.15)
                continue
            end
        end
        -- list live saja — jangan fire dari cache mati
        local okScan, rows = pcall(M._scan.ensureForFire)
        if okScan then M.S.lastRows = rows else rows = M._scan.refreshDist(M.S.lastRows or {}) end
        local t
        if M._buffMethod.isSeed() then
            -- Seed: jangan pakai dog-safe filter (sering kosong) — ambil buah in-range apa saja
            t = M._pick.bestSeedTarget(rows, true)
            if not t then
                emptyStreak += 1
                if emptyStreak >= 4 then
                    M.S.farmTriedKeys = {}
                    M.S.failAttempts = {}
                    emptyStreak = 0
                    M.InvalidateScan("seed_empty")
                end
                M._setPhase("BuffSeed", "BUFF · steal carry x1")
                task.wait(0.25)
                continue
            end
        else
            t = M._pick.bestSafeInRange(rows)
        end
        if not t then
            emptyStreak += 1
            if emptyStreak >= 8 then
                M.S.farmTriedKeys = {}
                M.S.failAttempts = {}
                emptyStreak = 0
                M.InvalidateScan("fire_empty")
            end
            if M.GetCarryCount() >= math.max(8, math.floor(M.C.CARRY_RETURN_AT * 0.5)) then
                M._move.tryDeposit("empty_targets")
            end
            task.wait(math.max(M._farmDelay(), 0.08))
            continue
        end
        -- double-check live tepat sebelum fire (anti race stolen)
        if not M._scan.isLiveRow(t) then
            local deadKey = M._util.farmTargetKey(t)
            M._scan.removeKey(deadKey)
            M._util.markTried(deadKey)
            M.InvalidateScan("stale_target")
            task.wait(0.02)
            continue
        end
        emptyStreak = 0
        local key = M._util.farmTargetKey(t)
        if key then M._util.markTried(key) end
        -- Seed method: max 1 fire pending biar carry tidak > 1
        if M._buffMethod.enabled() and M._buffMethod.phase() == "seed" then
            if M.GetCarryCount() >= 1 or M.S.buffMethodSeedPending == true then
                task.wait(0.1)
                continue
            end
            M.S.buffMethodSeedPending = true
            M._setPhase("BuffSeed", "BUFF · steal carry x1")
        end
        M._publish(string.format(
            "STEAL $%s",
            M._util.fmtPrice(t.price)
        ))
        M._farm.fireAsync(t)
        M.S.fireTotal += 1
        task.wait(M._farmDelay())
    end
end

function M._farm.runWalkOrbit(myId)
    while M.S.running and M.S.loopId == myId do
        if M.S.returningHome or M.S.fleeing then task.wait(0.25) continue end
        local bm = M._buffMethod.preFarmTick()
        if bm == "stop" then return end
        if bm == "idle" then task.wait(0.35) continue end
        if bm == "home_seed" then
            M._move.deposit("buff_seed")
            task.wait(0.15)
            continue
        end
        local needHome, homeWhy = M._move.shouldReturnHome()
        if needHome and homeWhy ~= "returning" then
            M._move.tryDeposit(homeWhy)
            task.wait(0.15)
            continue
        end
        local okG, whyG = M.StealGateOk()
        if not okG then
            if (whyG == "not_night" or whyG == "defender") and M.GetCarryCount() > 0 then
                M._move.tryDeposit(whyG)
            end
            task.wait(0.4)
            continue
        end
        if M._moveMode() ~= "orbit" then return end
        local waypoints = M._orbit.getWaypoints(true)
        if #waypoints == 0 then task.wait(1) continue end
        local start = M._orbit.nearestStart(waypoints)
        local i = start
        for _ = 1, #waypoints do
            if not M.S.running or M.S.loopId ~= myId then return end
            if M.S.returningHome or M.S.fleeing then break end
            bm = M._buffMethod.preFarmTick()
            if bm == "stop" then return end
            if bm == "idle" or bm == "home_seed" then break end
            needHome = M._move.shouldReturnHome()
            if needHome then break end
            if not M.StealGateOk() then break end
            M._orbit.goCorner(waypoints[i])
            i = (i % #waypoints) + 1
        end
        if M.GetCarryCount() > 0 then M._move.tryDeposit("orbit_lap") end
        task.wait(0.15)
    end
end

function M._farm.runWalkNearest(myId)
    local altCorner = 1
    while M.S.running and M.S.loopId == myId do
        if M.S.returningHome or M.S.fleeing then task.wait(0.25) continue end
        local bm = M._buffMethod.preFarmTick()
        if bm == "stop" then return end
        if bm == "idle" then task.wait(0.35) continue end
        if bm == "home_seed" then
            M._move.deposit("buff_seed")
            task.wait(0.15)
            continue
        end
        local needHome, homeWhy = M._move.shouldReturnHome()
        if needHome and homeWhy ~= "returning" then
            M._move.tryDeposit(homeWhy)
            task.wait(0.15)
            continue
        end
        local okG, whyG = M.StealGateOk()
        if not okG then
            if (whyG == "not_night" or whyG == "defender") and M.GetCarryCount() > 0 then
                M._move.tryDeposit(whyG)
            end
            task.wait(0.4)
            continue
        end
        if M._moveMode() ~= "nearest" then return end

        local rows = M._scan.ensure(false)
        local own = M._orbit.getOwnPlot(false)
        if not own then
            own = M._orbit.getOwnPlot(true)
        end
        if not own or type(own.corners) ~= "table" or #own.corners == 0 then
            -- fallback lama: ke plot tetangga kalau own plot belum ketemu
            local plot = M._pick.neighborPlot(rows)
            if plot then
                local fruit = M._pick.bestOnPlot(rows, plot)
                if fruit then M._orbit.goToFruitStand(fruit) end
            end
            task.wait(0.8)
            continue
        end

        -- 1) Pilih pojok kiri/kanan plot sendiri yang paling banyak buah ≤100
        local corner, score = M._pick.bestOwnCorner(own, rows)
        if not corner then
            corner = own.corners[((altCorner - 1) % #own.corners) + 1]
            score = 0
        end
        M._orbit.goOwnCorner(own, corner)

        local campUntil = os.clock() + 14
        local advanced = false
        while M.S.running and M.S.loopId == myId and os.clock() < campUntil do
            if M.S.returningHome or M.S.fleeing then break end
            needHome = M._move.shouldReturnHome()
            if needHome then break end
            if not M.StealGateOk() then break end
            if M._moveMode() ~= "nearest" then return end

            rows = M._scan.ensure(false)
            -- 2) Dari sini: ada buah dist player ≤100? diam — fire loop yang steal
            local inRange = M._pick.bestSafeInRange(rows)
            local dogOk = (not M._dog.enabled()) or (M._dog.minDistFromMe() > M._dog.safeStuds())
            if inRange and dogOk then
                M._publish(string.format(
                    "NEAR stay $%s %.0fst%s",
                    M._util.fmtPrice(inRange.price), tonumber(inRange.dist) or -1,
                    M._dog.enabled() and " dogOk" or ""
                ))
                task.wait(0.35)
                continue
            end
            if inRange then
                M._orbit.goToFruitStand(inRange)
                task.wait(0.2)
                continue
            end

            -- 3) Tidak ada dalam 100 → maju mendekat ke buah tetangga kiri/kanan
            local fruit = M._pick.bestNeighborFruit(rows, own)
            if fruit and typeof(fruit.position) == "Vector3" then
                local d = M._util.flatDist(fruit.position)
                fruit.dist = d
                if d > M._stealRange() then
                    M._publish(string.format(
                        "NEAR close $%s %.0fst",
                        M._util.fmtPrice(fruit.price), d
                    ))
                    M._orbit.goToFruitStand(fruit)
                    advanced = true
                    task.wait(0.25)
                else
                    task.wait(0.35)
                end
            else
                -- kosong di sisi ini → ganti pojok
                break
            end
            task.wait(0.2)
        end

        -- ganti pojok BL↔BR tiap cycle
        altCorner += 1
        if not advanced and M.GetCarryCount() > 0 then
            M._move.tryDeposit("nearest_camp")
        end
        task.wait(0.15)
    end
end

function M._farm.runWalkHighest(myId)
    local lastMoveAt = 0
    while M.S.running and M.S.loopId == myId do
        if M.S.returningHome or M.S.fleeing then task.wait(0.25) continue end
        local bm = M._buffMethod.preFarmTick()
        if bm == "stop" then return end
        if bm == "idle" then task.wait(0.35) continue end
        if bm == "home_seed" then
            M._move.deposit("buff_seed")
            task.wait(0.15)
            continue
        end
        local needHome, homeWhy = M._move.shouldReturnHome()
        if needHome and homeWhy ~= "returning" then
            M._move.tryDeposit(homeWhy)
            task.wait(0.15)
            continue
        end
        local okG, whyG = M.StealGateOk()
        if not okG then
            if (whyG == "not_night" or whyG == "defender") and M.GetCarryCount() > 0 then
                M._move.tryDeposit(whyG)
            end
            task.wait(0.4)
            continue
        end
        if M._moveMode() ~= "highest" then return end
        local rows = M._scan.ensure(false)
        local fruit = M._pick.bestGlobal(rows)
        if not fruit then task.wait(0.5) continue end
        local now = os.clock()
        if (now - lastMoveAt) >= 0.85 then
            lastMoveAt = now
            M._orbit.goToFruitStand(fruit)
        end
        task.wait(0.2)
    end
end

function M._farm.runWalk(myId)
    local lastSeedMoveAt = 0
    while M.S.running and M.S.loopId == myId do
        local bm = M._buffMethod.preFarmTick()
        if bm == "stop" then break end
        if bm == "idle" then
            local ph = M.S.buffMethodPhase
            if ph == "wait_buff" then
                task.wait(1.0)
            else
                task.wait(0.5)
            end
            continue
        end
        if bm == "home_seed" then
            M._move.deposit("buff_seed")
            task.wait(0.15)
            continue
        end
        -- Seed method: paksa ke buah terdekat (throttle move biar gak spam GoTo)
        if M._buffMethod.isSeed() then
            if M.S.returningHome or M.S.fleeing then
                task.wait(0.2)
                continue
            end
            local now = os.clock()
            if (now - lastSeedMoveAt) < 0.55 then
                task.wait(0.2)
                continue
            end
            lastSeedMoveAt = now
            local rows = M._scan.ensure(false)
            local fruit = M._pick.bestSeedTarget(rows, false)
            if fruit then
                M._publish(string.format(
                    "BUFF · steal carry x1 · $%s",
                    M._util.fmtPrice(fruit.price)
                ))
                M._orbit.goToFruitStand(fruit)
            else
                M._setPhase("BuffSeed", "BUFF · steal carry x1")
                -- Jangan InvalidateScan tiap tick kosong — bikin rescan spam
                task.wait(0.45)
            end
            task.wait(0.2)
            continue
        end
        local mode = M._moveMode()
        if mode == "off" then
            task.wait(0.5)
        elseif mode == "nearest" then
            M._farm.runWalkNearest(myId)
        elseif mode == "highest" then
            M._farm.runWalkHighest(myId)
        else
            M._farm.runWalkOrbit(myId)
        end
        -- mode loops exit when mode changes (inner checks) or stop
        if M.S.running and M.S.loopId == myId then
            task.wait(0.15)
        end
    end
end

function M._compat(on)
    local RF = G.ReduceFPS or rawget(_G, "ReduceFPS") or G.ReduceFPSModule or rawget(_G, "ReduceFPSModule")
    if type(RF) ~= "table" or type(RF.SetStealCompat) ~= "function" then return false end
    pcall(RF.SetStealCompat, RF, on == true)
    M.S.compatHeld = (on == true)
    return true
end

-- Auto Guard / watering cek flag ini (blok Fire Garden saat steal).
-- JANGAN PauseAutoTele: Stop seluruh AutoTele (Hit WW + Guard ikut mati).
function M._setStealBusy(on)
    on = (on == true)
    G.__GAG2_AUTO_STEAL_BUSY = on
    _G.__GAG2_AUTO_STEAL_BUSY = on
    M.S.stealBusy = on

    local Move = M._move.api()
    if type(Move) ~= "table" then return on end

    if on then
        if type(Move.HoldSession) == "function" then
            pcall(Move.HoldSession, "steal")
        end
        M.S.telePausedBySteal = false
    else
        if type(Move.ReleaseSession) == "function" then
            pcall(Move.ReleaseSession, "steal")
        end
        M.S.telePausedBySteal = false
    end
    return on
end

function M.IsStealBusy()
    return M.S.stealBusy == true
        or G.__GAG2_AUTO_STEAL_BUSY == true
        or rawget(_G, "__GAG2_AUTO_STEAL_BUSY") == true
end

function M.IsEnabled()
    local st = M._store()
    if G.AUTO_STEAL_ENABLED == true or rawget(_G, "AUTO_STEAL_ENABLED") == true then return true end
    return st.enabled == true
end

function M.SetEnabled(on)
    on = (on == true)
    local st = M._store()
    st.enabled = on
    G.AUTO_STEAL_ENABLED = on
    _G.AUTO_STEAL_ENABLED = on
    if on then M.Start() else M.Stop() end
    return on
end

function M.IsRunning()
    return M.S.running == true
end

function M.Start()
    if M.S.running then return true end
    M._syncFromGlobals()
    if not M.IsEnabled() then return false end
    M.S.loopId += 1
    local myId = M.S.loopId
    M.S.running = true
    M.S.fireTotal = 0
    M.S.farmTriedKeys = {}
    M.S.failAttempts = {}
    M.S.returningHome = false
    M.S.fleeing = false
    M.S.fleeJumpToken += 1
    M.S.petDistCache = {}
    M.S.dogPosCache = nil
    M.S.dogPosCacheAt = 0
    M.S.dogReposAt = 0
    M.S.scanDirty = true
    M.S.scanDirtyWhy = "farm_start"
    if M.GetBuffOnly() then
        M._buffMethod.reset()
    else
        M.S.buffMethodPhase = nil
        M.S.buffMethodStopAfterDeposit = false
    end
    M._setStealBusy(true)
    M._move.bindNightWatch()
    M._scan.bindWatch()
    M._compat(true)
    if M.GetBuffOnly() then
        M._setPhase("BuffSeed", string.format("BUFF METHOD · %s/%s", M._moveMode(), M.GetTravelMode()))
    else
        M._setPhase("Farm", string.format("FARM %s/%s", M._moveMode(), M.GetTravelMode()))
    end
    task.spawn(function() M._flee.monitor(myId) end)
    task.spawn(function() M._farm.runFire(myId) end)
    task.spawn(function()
        M._farm.runWalk(myId)
        if M.GetCarryCount() > 0 then M._move.deposit("farm_stop") end
        if M.S.running and M.S.loopId == myId then M.S.running = false end
        if M.S.loopId == myId then
            M._setStealBusy(false)
            M._publish(string.format("STOP ok%d fail%d", M.S.nightTotal, M.S.failTotal))
        end
    end)
    return true
end

function M.Stop()
    M.S.running = false
    M.S.loopId += 1
    M.S.fleeing = false
    M._flee.stopJump()
    M._setStealBusy(false)
    if M.GetCarryCount() > 0 then task.spawn(function() M._move.deposit("stop") end) end
    M._compat(false)
    M._setPhase("Idle", "STOPPED")
    return true
end

function M.Restart()
    M.Stop()
    task.wait(0.15)
    return M.Start()
end

function M.SetFilters(partial)
    partial = type(partial) == "table" and partial or {}
    local cur = M._filters()
    for k, v in pairs(partial) do
        if k ~= "max_price" then cur[k] = v end
    end
    cur = M._normalizeFilters(cur)
    local st = M._store()
    for k, v in pairs(cur) do st[k] = v end
    st.max_price = nil
    st.enabled = M.IsEnabled()
    G.__GAG2_AUTO_STEAL = st
    _G.__GAG2_AUTO_STEAL = st
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.auto = MAIN.auto or {}
        MAIN.auto.steal = MAIN.auto.steal or {}
        for k, v in pairs(cur) do MAIN.auto.steal[k] = v end
        MAIN.auto.steal.max_price = nil
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end
    local RF = G.ReduceFPS or rawget(_G, "ReduceFPS")
    if type(RF) == "table" and type(RF.RefreshStealKeep) == "function" then
        pcall(RF.RefreshStealKeep, RF)
    end
    return cur
end

function M.GetFilters()
    return M._filters()
end

function M.StealOnce(opts)
    opts = type(opts) == "table" and opts or {}
    if not opts.ignoreNight and M.IsNight() ~= true then return false, "not_night" end
    if not opts.ignoreDefender and M.IsDefenderBlocking() then return false, "defender" end
    local rows = M._scan.doScan()
    local t = M._pick.bestSafeInRange(rows)
    if not t then
        M.S.skipTotal += 1
        return false, "empty"
    end
    local carryBefore = M.GetCarryCount()
    local ok, why = M.StealTarget(t)
    if ok and M._net.verifySuccess(carryBefore) then
        M.S.nightTotal += 1
        M._util.markTried(M._util.farmTargetKey(t))
        return true, "ok", t
    end
    M._util.bumpFail(M._util.farmTargetKey(t))
    return false, why or "fail", t
end

function M.StealOrbitOnce(_opts)
    local okG, whyG = M.StealGateOk()
    if not okG then return false, whyG end
    local waypoints = M._orbit.getWaypoints(true)
    if #waypoints == 0 then return false, "no_plots" end
    local start = M._orbit.nearestStart(waypoints)
    M._orbit.goCorner(waypoints[start])
    return true, "orbit_step"
end

function M.StealNearestOnce(_opts)
    local okG, whyG = M.StealGateOk()
    if not okG then return false, whyG end
    local rows = M._scan.ensure(false)
    local plot = M._pick.neighborPlot(rows)
    if not plot then return false, "no_plot" end
    local fruit = M._pick.bestOnPlot(rows, plot)
    if not fruit then return false, "empty" end
    M._orbit.goToFruitStand(fruit)
    return true, "nearest_step"
end

function M.StealHighestOnce(_opts)
    local okG, whyG = M.StealGateOk()
    if not okG then return false, whyG end
    local rows = M._scan.ensure(false)
    local fruit = M._pick.bestGlobal(rows)
    if not fruit then return false, "empty" end
    M._orbit.goToFruitStand(fruit)
    return true, "highest_step"
end

function M.ClearStolenOwnerMemory()
    table.clear(M.S.stolenOwners)
    G.__GAG2_STEAL_OWNERS = M.S.stolenOwners
    _G.__GAG2_STEAL_OWNERS = M.S.stolenOwners
end

function M.GetStolenOwners()
    local out = {}
    for uid, name in pairs(M.S.stolenOwners) do
        out[#out + 1] = { userId = uid, name = name }
    end
    table.sort(out, function(a, b) return tostring(a.name) < tostring(b.name) end)
    return out
end

function M.IsQuestStealActive()
    return M.S.questStealActive == true
end

function M.GetScanRows()
    return M.S.lastRows, M.S.lastScanAt
end

function M.GetStatus()
    local phase = tostring(M.S.phase or "Idle")
    local raw = tostring(M.S.lastStatus or "")
    local low = string.lower(raw)
    local act = "idle"
    if not M.IsEnabled() then
        act = "off"
    elseif M.S.fleeing or string.find(low, "flee", 1, true) or string.find(low, "stun", 1, true) then
        act = (string.find(low, "stun", 1, true) and "stun") or "flee"
    elseif M.S.returningHome or string.find(low, "home", 1, true) then
        act = "home"
    elseif string.find(low, "fire", 1, true) or string.find(low, "steal", 1, true) then
        act = "steal"
    elseif string.find(low, "near", 1, true) then
        act = "near"
    elseif string.find(low, "orbit", 1, true) then
        act = "orbit"
    elseif string.find(low, "move", 1, true) then
        act = "move"
    elseif M.S.running then
        act = "run"
    elseif M.IsEnabled() then
        act = "on"
    end
    return {
        night = M.IsNight(),
        carrying = M.IsCarrying(),
        carryValue = M.GetCarryValue(),
        carryCount = M.GetCarryCount(),
        running = M.S.running == true,
        fleeing = M.S.fleeing == true,
        enabled = M.IsEnabled(),
        status = act,
        lastStatus = raw,
        phase = phase,
        action = act,
        moduleVersion = M.ModuleVersion,
        dogAvoid = M.GetDogAvoid(),
        moveMode = M.GetMoveMode(),
        travelMode = M.GetTravelMode(),
        nightTotal = M.S.nightTotal,
        failTotal = M.S.failTotal,
        skipTotal = M.S.skipTotal,
        fireTotal = M.S.fireTotal,
        defender = M.IsDefender(),
        questSteal = M.S.questStealActive,
        scanRows = type(M.S.lastRows) == "table" and #M.S.lastRows or 0,
        lastScanAt = M.S.lastScanAt,
    }
end

function M.GetLiveDebug()
    return {
        ver = M.ModuleVersion,
        phase = M.S.phase,
        status = M.S.lastStatus,
        moveMode = M.GetMoveMode(),
        travelMode = M.GetTravelMode(),
        fireLoop = M.S.running == true,
        walkLoop = M.S.running == true and M._moveMode() ~= "off",
        night = M.IsNight() == true,
        carry = M.GetCarryCount(),
        carryValue = M.GetCarryValue(),
        nightTotal = M.S.nightTotal,
        failTotal = M.S.failTotal,
        skipTotal = M.S.skipTotal,
        tried = M.S.farmTriedKeys,
        failAttempts = M.S.failAttempts,
        nightLeft = M.GetNightRemainingSec(),
    }
end

G.AutoSteal = M
G.AutoStealModule = M
_G.AutoSteal = M
_G.AutoStealModule = M
G.__GAG2_AUTO_STEAL_BUSY = false
_G.__GAG2_AUTO_STEAL_BUSY = false

return M
 end,                       required = false },
    { key = "SectionAutoSteal",        name = "Section Auto Steal",      factory = function() -- section_auto_steal.lua — UI Auto Steal (tab Auto)

local G = (getgenv and getgenv()) or _G
local M = {}

local function parseScaledNumber(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", "")
    if txt == "" then return nil end
    local sign = 1
    if txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end
    local suffixes = {
        { "juta", 1000000 }, { "jt", 1000000 },
        { "ribu", 1000 }, { "rb", 1000 },
        { "b", 1000000000 }, { "m", 1000000 }, { "k", 1000 },
    }
    for _, pair in ipairs(suffixes) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local n = tonumber(txt:sub(1, -#suf - 1))
            if n then return n * mult * sign end
        end
    end
    local n = tonumber(txt)
    if n then return n * sign end
    return nil
end

local function formatShort(n)
    n = tonumber(n) or 0
    local abs = math.abs(n)
    if abs >= 1e9 then return string.format("%.2fb", n / 1e9) end
    if abs >= 1e6 then return string.format("%.2fm", n / 1e6) end
    if abs >= 1e3 then return string.format("%.2fk", n / 1e3) end
    if math.floor(n) == n then return tostring(math.floor(n)) end
    return string.format("%.2f", n)
end

local function normalizePathMode(mm)
    mm = tostring(mm or "orbit"):lower()
    if mm == "nearest_garden" then mm = "nearest" end
    if mm == "highest_price" then mm = "highest" end
    if mm ~= "nearest" and mm ~= "highest" and mm ~= "off" then mm = "orbit" end
    return mm
end

local function normalizeTravelMode(tm)
    tm = tostring(tm or "walk"):lower()
    if tm ~= "soft" and tm ~= "step" and tm ~= "hard" then tm = "walk" end
    return tm
end

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto       = ctx.getAuto
    local patchAuto     = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local registerFlush = ctx.registerFlush
    local cleanSelectedMap = ctx.cleanSelectedMap
    local arrayToMap = ctx.arrayToMap
    local mapToArray = ctx.mapToArray

    local PlantListView = ctx.PlantListView
        or G.PlantListView
        or rawget(_G, "PlantListView")

    local ST = getAuto("steal")
    if type(ST) ~= "table" then ST = {} end
    ST.enabled = (ST.enabled == true)
    ST.plants = type(ST.plants) == "table" and ST.plants or {}
    ST.mutations = type(ST.mutations) == "table" and ST.mutations or {}
    ST.min_kg = tonumber(ST.min_kg) or 0
    ST.min_price = tonumber(ST.min_price) or 0
    ST.delay = tonumber(ST.delay) or 0.05
    -- migrate legacy default 0.35 → steal-test 0.05
    if math.abs(ST.delay - 0.35) < 1e-6 then ST.delay = 0.05 end
    ST.buff_only = (ST.buff_only == true)
    ST.buff_offmoon = (ST.buff_offmoon ~= false)
    ST.dog_avoid = (ST.dog_avoid == true) -- default OFF (hindari lag)
    ST.move_mode = normalizePathMode(ST.move_mode)
    ST.travel_mode = normalizeTravelMode(ST.travel_mode)
    do
        local sr = tonumber(ST.steal_range)
        if sr == nil then sr = 100 end
        if sr < 1 then sr = 1 end
        if sr > 100 then sr = 100 end
        ST.steal_range = sr
    end
    ST.max_price = nil
    if ST.min_kg < 0 then ST.min_kg = 0 end
    if ST.min_price < 0 then ST.min_price = 0 end
    if ST.delay < 0.02 then ST.delay = 0.02 end

    if G.AUTO_STEAL_ENABLED == true or rawget(_G, "AUTO_STEAL_ENABLED") == true then
        ST.enabled = true
    end

    local plantsSelected = cleanSelectedMap(arrayToMap(ST.plants))
    local mutSelected = cleanSelectedMap(arrayToMap(ST.mutations))

    local function snapshot()
        local api = G.__GAG2_STEAL_ENABLE_API or rawget(_G, "__GAG2_STEAL_ENABLE_API")
        if type(api) == "table" and type(api.get) == "function" then
            ST.enabled = (api.get() == true)
        end
        return {
            enabled = (ST.enabled == true),
            plants = mapToArray(plantsSelected),
            mutations = mapToArray(mutSelected),
            min_kg = tonumber(ST.min_kg) or 0,
            min_price = tonumber(ST.min_price) or 0,
            delay = tonumber(ST.delay) or 0.05,
            buff_only = (ST.buff_only == true),
            buff_offmoon = (ST.buff_offmoon ~= false),
            dog_avoid = (ST.dog_avoid == true),
            move_mode = ST.move_mode or "orbit",
            travel_mode = ST.travel_mode or "walk",
            steal_range = tonumber(ST.steal_range) or 100,
        }
    end

    local function writeGlobals()
        local snap = snapshot()
        G.AUTO_STEAL_ENABLED = snap.enabled
        _G.AUTO_STEAL_ENABLED = snap.enabled
        G.__GAG2_AUTO_STEAL = snap
        _G.__GAG2_AUTO_STEAL = snap
        if type(patchAutoOnly) == "function" then
            patchAutoOnly("steal", snap)
        end
    end

    local function syncModule()
        writeGlobals()
        local mod = G.AutoSteal or G.AutoStealModule or rawget(_G, "AutoSteal")
        if type(mod) ~= "table" then return end
        if type(mod.SetFilters) == "function" then
            pcall(function()
                mod.SetFilters({
                    plants = ST.plants,
                    mutations = ST.mutations,
                    min_kg = ST.min_kg,
                    min_price = ST.min_price,
                    delay = ST.delay,
                    buff_only = ST.buff_only == true,
                    buff_offmoon = ST.buff_offmoon ~= false,
                    dog_avoid = ST.dog_avoid == true,
                    move_mode = ST.move_mode or "orbit",
                    travel_mode = ST.travel_mode or "walk",
                    steal_range = tonumber(ST.steal_range) or 100,
                })
                if type(mod.SetDogAvoid) == "function" then
                    pcall(mod.SetDogAvoid, ST.dog_avoid == true)
                end
            end)
        end
        if G.AUTO_STEAL_ENABLED then
            if type(mod.Restart) == "function" then
                pcall(mod.Restart, mod)
            elseif type(mod.SetEnabled) == "function" then
                pcall(mod.SetEnabled, mod, true)
            elseif type(mod.Start) == "function" then
                pcall(mod.Start, mod)
            end
        else
            if type(mod.SetEnabled) == "function" then
                pcall(mod.SetEnabled, mod, false)
            elseif type(mod.Stop) == "function" then
                pcall(mod.Stop, mod)
            end
        end
    end

    local function persist(partial)
        if type(partial) == "table" then
            for k, v in pairs(partial) do
                ST[k] = v
            end
        end
        writeGlobals()
        if type(patchAuto) == "function" then
            patchAuto("steal", snapshot(), syncModule)
        else
            syncModule()
        end
    end

    G.__GAG2_SYNC_AUTO_STEAL = syncModule
    _G.__GAG2_SYNC_AUTO_STEAL = syncModule
    G.__GAG2_PUSH_STEAL = writeGlobals
    _G.__GAG2_PUSH_STEAL = writeGlobals

    if type(registerFlush) == "function" then
        registerFlush("steal", function()
            writeGlobals()
        end)
    end

    writeGlobals()

    local body = ui:CreateSection("Auto Steal", false)

    local statusRow, statusLbl = ui:CreateRowLabel(
        body,
        "Day · C0 · $0",
        "OFF · orbit/walk",
        nil,
        "accent"
    )
    local statusSub = nil
    if statusRow then
        for _, ch in ipairs(statusRow:GetChildren()) do
            if ch:IsA("TextLabel") and ch ~= statusLbl then
                statusSub = ch
                break
            end
        end
        statusRow.Size = UDim2.new(1, 0, 0, 36)
        if statusLbl then
            statusLbl.TextTruncate = Enum.TextTruncate.AtEnd
            statusLbl.TextWrapped = false
        end
        if statusSub then
            statusSub.TextTruncate = Enum.TextTruncate.AtEnd
            statusSub.TextWrapped = false
        end
    end

    local function shortAct(info, enabled)
        if not enabled then return "off" end
        local act = type(info) == "table" and tostring(info.action or info.status or "") or ""
        act = string.lower(act)
        if act == "fire" then act = "steal" end
        if act == "off" or act == "home" or act == "steal" or act == "near"
            or act == "orbit" or act == "move" or act == "run" or act == "on"
            or act == "flee" then
            return act
        end
        local raw = type(info) == "table" and tostring(info.lastStatus or "") or ""
        local low = string.lower(raw)
        if string.find(low, "home", 1, true) then return "home" end
        if string.find(low, "flee", 1, true) then return "flee" end
        if string.find(low, "fire", 1, true) or string.find(low, "steal", 1, true) then return "steal" end
        if string.find(low, "near", 1, true) then return "near" end
        if string.find(low, "orbit", 1, true) then return "orbit" end
        if string.find(low, "move", 1, true) then return "move" end
        if type(info) == "table" and info.running == true then return "run" end
        return "on"
    end

    local function refreshStatus()
        if not (statusLbl and statusLbl.Parent) then return end
        local mod = G.AutoSteal or rawget(_G, "AutoSteal")
        local night, value, count = false, 0, 0
        local moveMode = tostring(ST.move_mode or "orbit")
        local travelMode = tostring(ST.travel_mode or "walk")
        local info = nil
        local running = false

        if type(mod) == "table" then
            if type(mod.GetStatus) == "function" then
                local ok, s = pcall(mod.GetStatus, mod)
                if ok and type(s) == "table" then info = s end
            end
            if type(info) == "table" then
                night = info.night == true
                count = tonumber(info.carryCount) or 0
                value = tonumber(info.carryValue) or 0
                running = info.running == true
                if type(info.moveMode) == "string" and info.moveMode ~= "" then
                    moveMode = info.moveMode
                end
                if type(info.travelMode) == "string" and info.travelMode ~= "" then
                    travelMode = info.travelMode
                end
            else
                if type(mod.IsNight) == "function" then
                    local ok, v = pcall(mod.IsNight, mod)
                    if ok then night = v == true end
                end
                if type(mod.GetCarryCount) == "function" then
                    local ok, v = pcall(mod.GetCarryCount, mod)
                    if ok then count = tonumber(v) or 0 end
                end
                if type(mod.GetCarryValue) == "function" then
                    local ok, v = pcall(mod.GetCarryValue, mod)
                    if ok then value = tonumber(v) or 0 end
                end
            end
            if type(mod.GetMoveMode) == "function" then
                local okMm, mm = pcall(mod.GetMoveMode, mod)
                if okMm and type(mm) == "string" and mm ~= "" then moveMode = mm end
            end
            if type(mod.GetTravelMode) == "function" then
                local okTm, tm = pcall(mod.GetTravelMode, mod)
                if okTm and type(tm) == "string" and tm ~= "" then travelMode = tm end
            end
        else
            local RS = game:GetService("ReplicatedStorage")
            local n = RS:FindFirstChild("Night")
            night = n ~= nil and n.Value == true
            local lp = game:GetService("Players").LocalPlayer
            value = lp and (tonumber(lp:GetAttribute("StolenCarryValue")) or 0) or 0
        end

        local act = shortAct(info, ST.enabled == true)
        statusLbl.Text = string.format(
            "%s · C%d · $%s",
            night and "Night" or "Day",
            count,
            formatShort(value)
        )
        if statusSub and statusSub.Parent then
            local detail = ""
            if type(info) == "table" and type(info.lastStatus) == "string" and info.lastStatus ~= "" then
                detail = tostring(info.lastStatus)
                if #detail > 24 then
                    detail = string.sub(detail, 1, 24) .. "…"
                end
            end
            if detail ~= "" and act ~= "off" then
                statusSub.Text = string.format("%s · %s/%s · %s", string.upper(act), moveMode, travelMode, detail)
            else
                statusSub.Text = string.format(
                    "%s · %s/%s%s",
                    string.upper(act),
                    moveMode,
                    travelMode,
                    running and " · run" or ""
                )
            end
        end
    end

    task.defer(function()
        pcall(refreshStatus)
    end)
    task.spawn(function()
        while body and body.Parent do
            task.wait(1.0)
            if body.Visible ~= false then
                pcall(refreshStatus)
            end
        end
    end)

