            ST.buff_offmoon = (isOn == true)
            persist({ buff_offmoon = ST.buff_offmoon })
            local mod = G.AutoSteal or rawget(_G, "AutoSteal")
            if type(mod) == "table" and type(mod.SetBuffOffmoon) == "function" then
