            ST.enabled = (isOn == true)
            persist({ enabled = ST.enabled })
        end
    )

    G.__GAG2_STEAL_ENABLE_API = enableApi
    _G.__GAG2_STEAL_ENABLE_API = enableApi
    if enableApi and type(enableApi.set) == "function" then
        enableApi.set(ST.enabled == true, true)
    end

    syncModule()
end

G.SectionAutoSteal = M
_G.SectionAutoSteal = M

return M
 end,              required = false },
    { key = "AutoKillMonster",         name = "Auto Kill Monster",       factory = function() -- Auto Kill Monster — Ghoul Garden
-- Equip shovel → SwingShovel → HitMonsterFromClientToServer { Id }
-- Optional same swing: HitPumpkinFromClientToServer (Pumpkin Guts)

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G
local M = {}

local HIT_RANGE = 13
local PUMPKIN_HIT = 12
local TREE_Y = 6
local TP_HORIZ = 16
local TP_CD = 0.9
local SWING_CD = 0.72
local MOVE_PRI = 60
local TYPE_ORDER = { "GiantSpider", "Skeleton", "Zombie" }
local TYPE_LABEL = {
    GiantSpider = "Giant Spider",
    Skeleton = "Skeleton",
    Zombie = "Zombie",
}

local running = false
local loopId = 0
local lastSwingAt = 0
local lastPumpkinTpAt = 0
local statusText = "off"
local netOk = false
local SwingShovel, HitMonster, HitPumpkin

local function _writeMain(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.killMonster = MAIN.auto.killMonster or {}
    for k, v in pairs(patch) do
        MAIN.auto.killMonster[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function _typesFrom(src)
    local out = {}
    if type(src) ~= "table" then return out end
    for i = 1, #src do
        local k = tostring(src[i] or "")
        if k ~= "" then out[k] = true end
    end
    if next(out) then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        end
    end
    return out
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.killMonster
    local types = _typesFrom(st and st.types)
    if G.AUTO_KILL_MONSTER_TYPES ~= nil then
        types = _typesFrom(G.AUTO_KILL_MONSTER_TYPES)
    end
    local smash = true
    if st and st.smashPumpkin ~= nil then smash = (st.smashPumpkin == true) end
    if G.AUTO_KILL_SMASH_PUMPKIN ~= nil then smash = (G.AUTO_KILL_SMASH_PUMPKIN == true) end
    local enabled = (st and st.enabled == true) or (G.AUTO_KILL_MONSTER_ENABLED == true)
    return {
        enabled = enabled == true,
        types = types,
        smashPumpkin = smash,
    }
end

local function setStatus(s)
    statusText = tostring(s or "")
    G.AUTO_KILL_MONSTER_STATUS = statusText
    _G.AUTO_KILL_MONSTER_STATUS = statusText
end

function M.GetStatus()
    return statusText
end
M.getStatus = M.GetStatus

function M.BuildTypeItems()
    local items = {}
    for i = 1, #TYPE_ORDER do
        local k = TYPE_ORDER[i]
        items[#items + 1] = { key = k, name = TYPE_LABEL[k] or k }
    end
    return items
end
M.buildTypeItems = M.BuildTypeItems

local function inGhoul()
    local afh = G.AutoFallHarvest or G.AutoFallHarvestModule
    if type(afh) == "table" and type(afh.IsInGhoulGarden) == "function" then
        local ok, v = pcall(afh.IsInGhoulGarden, afh)
        if ok then return v == true end
    end
    local pid = game.PlaceId
    return pid == 102868797705537 or pid == 136420110879676 or pid == 120978386897995
end

local function getMove()
    return G.Move or G.MoveModule or rawget(_G, "Move")
end

local function hrp()
    local char = LP and LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function typeAllowed(st, typ)
    if not next(st.types) then return true end
    typ = tostring(typ or "")
    if st.types[typ] == true then return true end
    for k, v in pairs(st.types) do
        if v == true and string.lower(k) == string.lower(typ) then
            return true
        end
    end
    return false
end

local function initNet()
    if netOk and SwingShovel and HitMonster then return true end
    local ok, NW = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules"):WaitForChild("Networking"))
    end)
    if not ok or type(NW) ~= "table" then return false end
    SwingShovel = NW.Shovel and NW.Shovel.SwingShovel
    HitMonster = NW.Monster and NW.Monster.HitMonsterFromClientToServer
    HitPumpkin = NW.Pumpkin and NW.Pumpkin.HitPumpkinFromClientToServer
    netOk = SwingShovel ~= nil and HitMonster ~= nil
    return netOk
end

local function equipShovel()
    local char = LP and LP.Character
    if not char then return false end
    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") and ch:GetAttribute("Shovel") then
            return true
        end
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local bp = LP:FindFirstChild("Backpack")
    if not hum or not bp then return false end
    for _, tool in ipairs(bp:GetChildren()) do
        if tool:IsA("Tool") and tool:GetAttribute("Shovel") then
            local ok = pcall(function()
                hum:EquipTool(tool)
            end)
            if ok then return true end
        end
    end
    return false
end

local function pickMonster(st, origin)
    local folder = workspace:FindFirstChild("Monsters")
    if not folder then return nil end
    local best, bestD
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("BasePart") then
            local id = child:GetAttribute("MonsterId")
            local typ = child:GetAttribute("MonsterType")
            if type(id) == "string" and child:GetAttribute("Dead") ~= true and typeAllowed(st, typ) then
                local d = (child.Position - origin).Magnitude
                if not bestD or d < bestD then
                    bestD = d
                    best = {
                        kind = "monster",
                        id = id,
                        pos = child.Position,
                        dist = d,
                        label = TYPE_LABEL[tostring(typ)] or tostring(typ or "Monster"),
                    }
                end
            end
        end
    end
    return best
end

local function pickPumpkin(origin)
    local folder = workspace:FindFirstChild("Pumpkins")
    if not folder then return nil end
    local best, bestD
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("Model") then
            local id = child:GetAttribute("PumpkinId")
            if type(id) == "string" and child:GetAttribute("Burst") ~= true then
                local root = child:FindFirstChild("Root")
                local pos = (root and root:IsA("BasePart") and root.Position) or child:GetPivot().Position
                local d = (pos - origin).Magnitude
                if not bestD or d < bestD then
                    bestD = d
                    best = {
                        kind = "pumpkin",
                        id = id,
                        pos = pos,
                        dist = d,
                        label = "Pumpkin",
                    }
                end
            end
        end
    end
    return best
end

local function approach(pos, opts)
    opts = type(opts) == "table" and opts or {}
    local Move = getMove()
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false, "no_move"
    end
    if type(Move.ShouldYield) == "function" then
        local y = Move.ShouldYield("kill", MOVE_PRI)
        if y then return false, "busy" end
    end
    local root = hrp()
    if not root then return false, "no_char" end
    local from = root.Position
    local dir = pos - from
    local flat = Vector3.new(dir.X, 0, dir.Z)
    local mag = flat.Magnitude
    if mag < 1 then mag = 1 end
    local standY = opts.ground == true and from.Y or pos.Y
    local back = opts.ground == true and 4 or 8
    local near = Vector3.new(pos.X, standY, pos.Z) - (flat / mag) * back
    near = Vector3.new(near.X, standY, near.Z)
    local look = Vector3.new(pos.X, standY, pos.Z)
    local goOpts = {
        reason = "kill",
        priority = MOVE_PRI,
    }
    if opts.mode then goOpts.mode = opts.mode end
    local ok, err = pcall(Move.GoTo, CFrame.new(near, look), goOpts)
    if not ok then return false, tostring(err) end
    return err == true or err == nil, err
end

local function tpToPumpkin(pos)
    local Move = getMove()
    local root = hrp()
    if not root then return false, "no_char" end
    if type(Move) == "table" and type(Move.ShouldYield) == "function" then
        local y = Move.ShouldYield("kill", MOVE_PRI)
        if y then return false, "busy" end
    end
    local from = root.Position
    local flat = Vector3.new(pos.X - from.X, 0, pos.Z - from.Z)
    local mag = flat.Magnitude
    if mag < 0.2 then
        flat = Vector3.new(0, 0, 1)
        mag = 1
    end
    local stand = pos - (flat / mag) * 3
    stand = Vector3.new(stand.X, pos.Y, stand.Z)
    local cf = CFrame.new(stand, pos)
    local goOpts = {
        reason = "kill",
        priority = MOVE_PRI,
        mode = "hard",
    }
    if type(Move) == "table" then
        if type(Move.HardTo) == "function" then
            local ok, a = pcall(Move.HardTo, cf, goOpts)
            if ok and a ~= false then return true, a end
        end
        if type(Move.GoTo) == "function" then
            local ok, a = pcall(Move.GoTo, cf, goOpts)
            if ok and a ~= false then return true, a end
        end
    end
    local ok = pcall(function()
        root.CFrame = cf
    end)
    return ok, ok and "hrp" or "tp_fail"
end

local function swingHit(target)
    if os.clock() - lastSwingAt < SWING_CD then
        return false, "cd"
    end
    if not equipShovel() then
        setStatus("no shovel")
        return false, "no_tool"
    end
    if not initNet() then
        setStatus("no remote")
        return false, "no_net"
    end
    pcall(function()
        SwingShovel:Fire()
    end)
    if target.kind == "monster" then
        pcall(function()
            HitMonster:Fire({ Id = target.id })
        end)
    elseif target.kind == "pumpkin" and HitPumpkin then
        pcall(function()
            HitPumpkin:Fire({ Id = target.id })
        end)
    end
    lastSwingAt = os.clock()
    return true
end

local function tick()
    local st = getState()
    if not st.enabled then
        setStatus("off")
        return
    end
    if not inGhoul() then
        setStatus("not on Ghoul")
        return
    end
    local root = hrp()
    if not root then
        setStatus("no character")
        return
    end
    local origin = root.Position
    local target = pickMonster(st, origin)
    if not target and st.smashPumpkin then
        target = pickPumpkin(origin)
    end
    if not target then
        setStatus("waiting spawn")
        return
    end
    local delta = target.pos - origin
    local d3 = delta.Magnitude
    local horiz = Vector3.new(delta.X, 0, delta.Z).Magnitude
    local dy = delta.Y
    local hitRange = (target.kind == "pumpkin") and PUMPKIN_HIT or HIT_RANGE
    if d3 <= hitRange then
        setStatus("hitting " .. target.label)
        swingHit(target)
        return
    end
    if target.kind == "pumpkin" and dy >= TREE_Y and horiz <= TP_HORIZ then
        if os.clock() - lastPumpkinTpAt < TP_CD then
            setStatus("tp pumpkin")
            return
        end
        lastPumpkinTpAt = os.clock()
        setStatus("tp pumpkin")
        tpToPumpkin(target.pos)
        return
    end
    setStatus("moving " .. target.label)
    approach(target.pos, {
        ground = target.kind == "pumpkin" and dy >= TREE_Y,
    })
end

local function mainLoop(myId)
    while running and loopId == myId do
        pcall(tick)
        task.wait(0.35)
    end
end

function M.SetEnabled(on)
    on = (on == true)
    G.AUTO_KILL_MONSTER_ENABLED = on
    _G.AUTO_KILL_MONSTER_ENABLED = on
    _writeMain({ enabled = on })
    if on then
        running = true
        loopId += 1
        local myId = loopId
        setStatus("on")
        task.spawn(function()
            mainLoop(myId)
        end)
    else
        running = false
        setStatus("off")
    end
end
M.setEnabled = M.SetEnabled
function M.Stop()
    M.SetEnabled(false)
end
M.stop = M.Stop

function M.SetTypes(src)
    local map = _typesFrom(src)
    local arr = {}
    for k, v in pairs(map) do
        if v == true then arr[#arr + 1] = k end
    end
    G.AUTO_KILL_MONSTER_TYPES = map
    _G.AUTO_KILL_MONSTER_TYPES = map
    _writeMain({ types = arr })
end
M.setTypes = M.SetTypes

function M.SetSmashPumpkin(on)
    on = (on ~= false)
    G.AUTO_KILL_SMASH_PUMPKIN = on
    _G.AUTO_KILL_SMASH_PUMPKIN = on
    _writeMain({ smashPumpkin = on })
end
M.setSmashPumpkin = M.SetSmashPumpkin

function M.SyncFromState()
    local st = getState()
    M.SetSmashPumpkin(st.smashPumpkin)
    M.SetTypes(st.types)
    M.SetEnabled(st.enabled)
end
M.syncFromState = M.SyncFromState

