 end,                 required = false },
    { key = "AutoCauldron",            name = "Auto Cauldron",           factory = function() -- Auto Cauldron / Brewing — Ghoul Garden
-- Request / StartBrew(recipeName) / Reveal / SaveCraft + Sync

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")

local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G
local M = {}

local MOVE_PRI = 55
local NEAR = 12
local REQ_GAP = 2.5

local running = false
local loopId = 0
local statusText = "off"
local lastReqAt = 0
local cache = nil
local hooked = false
local Request, StartBrew, Reveal, SaveCraft, Sync, RecMod, IngMod, CharmMod

local function _writeMain(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.cauldron = MAIN.auto.cauldron or {}
    for k, v in pairs(patch) do
        MAIN.auto.cauldron[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function getState()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.cauldron
    local enabled = (st and st.enabled == true) or (G.AUTO_CAULDRON_ENABLED == true)
    local recipe = ""
    if st and type(st.recipe) == "string" then recipe = st.recipe end
    if type(G.AUTO_CAULDRON_RECIPE) == "string" and G.AUTO_CAULDRON_RECIPE ~= "" then
        recipe = G.AUTO_CAULDRON_RECIPE
    end
    local useCharm = true
    if st and st.useCharm ~= nil then useCharm = (st.useCharm == true) end
    if G.AUTO_CAULDRON_USE_CHARM ~= nil then useCharm = (G.AUTO_CAULDRON_USE_CHARM == true) end
    local loopOn = true
    if st and st.loop ~= nil then loopOn = (st.loop == true) end
    if G.AUTO_CAULDRON_LOOP ~= nil then loopOn = (G.AUTO_CAULDRON_LOOP == true) end
    return {
        enabled = enabled == true,
        recipe = recipe,
        useCharm = useCharm,
