local function reqMod(name)
    local ok, mod = pcall(function()
        return require(ReplicatedStorage.SharedModules[name])
    end)
    return ok and mod or nil
end

local function initNet()
    if Request and StartBrew and Reveal then return true end
    local NW = reqMod("Networking")
    if type(NW) ~= "table" or type(NW.Cauldron) ~= "table" then return false end
    Request = NW.Cauldron.Request
    StartBrew = NW.Cauldron.StartBrew
    Reveal = NW.Cauldron.Reveal
    SaveCraft = NW.Cauldron.SaveCraft
    Sync = NW.Cauldron.Sync
    RecMod = reqMod("CauldronRecipes")
    IngMod = reqMod("CauldronIngredientData")
    CharmMod = reqMod("CauldronCharmData")
    if Sync and hooked == false then
        local ev = Sync.OnClientEvent
        if ev and type(ev.Connect) == "function" then
            hooked = true
            ev:Connect(function(payload)
                if type(payload) == "table" then
                    cache = payload
                    lastReqAt = os.clock()
                end
            end)
        end
    end
    return Request ~= nil and StartBrew ~= nil and Reveal ~= nil
end

local function refresh(force)
    if not initNet() then return nil end
    if not force and cache and (os.clock() - lastReqAt) < REQ_GAP then
        return cache
    end
    local ok, st = pcall(function()
        return Request:Fire()
    end)
    if ok and type(st) == "table" then
        cache = st
        lastReqAt = os.clock()
    end
    return cache
end

local function brewRec(st)
    local b = st and st.Brew
    if type(b) == "table" then return b end
    return {}
end

local function recipesOf(st)
    local list = st and st.Recipes
    if type(list) ~= "table" then return {} end
    return list
end

function M.BuildRecipeItems()
    local st = refresh(false)
    local items = {}
    for _, r in ipairs(recipesOf(st)) do
        if type(r) == "table" and type(r.Name) == "string" then
            local disp = r.Display and r.Display.DisplayName or r.Name
            items[#items + 1] = { key = r.Name, name = tostring(disp) }
        end
    end
    return items
end
M.buildRecipeItems = M.BuildRecipeItems

local function findRecipe(st, name)
    if type(name) ~= "string" or name == "" then return nil end
    for _, r in ipairs(recipesOf(st)) do
        if type(r) == "table" and r.Name == name then
            return r
        end
    end
    return nil
end

local function needText(r)
    if type(r) ~= "table" or type(r.Ingredients) ~= "table" then return "" end
    local parts = {}
    for _, ing in ipairs(r.Ingredients) do
        local n = ing.ItemName or ing.Authored or "?"
        local need = tonumber(ing.Count) or 1
        local have = tonumber(ing.Owned)
        if have == nil and IngMod and type(IngMod.CountIn) == "function" then
            local ok, v = pcall(IngMod.CountIn, n)
            if ok then have = tonumber(v) or 0 end
        end
        have = tonumber(have) or 0
        parts[#parts + 1] = string.format("%s %d/%d", n, have, need)
    end
    return table.concat(parts, ", ")
end

local function hasAll(r)
    if RecMod and type(RecMod.HasAll) == "function" then
        local ok, v = pcall(RecMod.HasAll, r)
        if ok and v == true then return true end
        if ok and v == false then return false end
    end
    if type(r) ~= "table" or type(r.Ingredients) ~= "table" then return false end
    for _, ing in ipairs(r.Ingredients) do
        local need = tonumber(ing.Count) or 1
        local have = tonumber(ing.Owned)
        if have == nil then return false end
        if have < need then return false end
    end
    return true
end

local function hrp()
    local char = LP and LP.Character
    return char and char:FindFirstChild("HumanoidRootPart")
end

local function cauldronPos()
    local tagged = CollectionService:GetTagged("WitchCauldronPot")
    local inst = tagged and tagged[1]
    if inst then
        if inst:IsA("Model") then return inst:GetPivot().Position end
        if inst:IsA("BasePart") then return inst.Position end
    end
    local fold = workspace:FindFirstChild("WitchCauldron")
    if fold then
        local m = fold:FindFirstChild("WitchCauldron")
        m = m and (m:FindFirstChild("WitchCauldron") or m)
        if m then
            if m:IsA("Model") then return m:GetPivot().Position end
            if m:IsA("BasePart") then return m.Position end
        end
    end
    return nil
end

local function nearPot()
    local pos = cauldronPos()
    local root = hrp()
    if not pos or not root then return false, pos end
    return (root.Position - pos).Magnitude <= NEAR, pos
end

local function goPot(pos)
    local Move = G.Move or G.MoveModule or rawget(_G, "Move")
    if type(Move) ~= "table" or type(Move.GoTo) ~= "function" then
        return false
    end
    if type(Move.ShouldYield) == "function" and Move.ShouldYield("brew", MOVE_PRI) then
        return false
    end
    local root = hrp()
    if not root then return false end
    local dir = pos - root.Position
    local flat = Vector3.new(dir.X, 0, dir.Z)
    local mag = flat.Magnitude
    if mag < 1 then mag = 1 end
    local near = pos - (flat / mag) * 6
    near = Vector3.new(near.X, pos.Y, near.Z)
    pcall(Move.GoTo, CFrame.new(near, pos), { reason = "brew", priority = MOVE_PRI })
    return true
end

local function remainSec(st)
    local b = brewRec(st)
    local fin = tonumber(b.FinishesAt) or 0
    local now = tonumber(st.Now) or os.time()
    local left = math.floor(fin - now)
    if left < 0 then left = 0 end
    return left
end

local function fmtTime(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local m = math.floor(sec / 60)
    local s = sec % 60
    return string.format("%d:%02d", m, s)
end

local function stopSaved()
    G.AUTO_CAULDRON_ENABLED = false
    _G.AUTO_CAULDRON_ENABLED = false
    _writeMain({ enabled = false })
    running = false
    setStatus("done")
    local api = G.__GAG2_CAULDRON_ENABLE_API or rawget(_G, "__GAG2_CAULDRON_ENABLE_API")
    if type(api) == "table" and type(api.setOff) == "function" then
        pcall(api.setOff, true)
    end
end

local function tick()
    local st = getState()
    if not st.enabled then
        setStatus("off")
        return
    end
    if not inGhoul() then
        setStatus("not on Ghoul")
        return
    end
    if not initNet() then
        setStatus("no remote")
        return
    end
    local info = refresh(false)
    if type(info) ~= "table" then
        setStatus("no cauldron")
        return
    end
    if info.Enabled == false then
        setStatus("cauldron off")
        return
    end
    if info.NightOnly == true and info.IsNight ~= true then
        setStatus("waiting night")
        return
    end

    local close, pos = nearPot()
    if pos and not close then
        setStatus("moving cauldron")
        goPot(pos)
        return
    end

    local b = brewRec(info)
    local state = tostring(b.State or "Empty")
    if state == "Brewing" then
        setStatus("brewing " .. fmtTime(remainSec(info)))
        return
    end
    if state == "Ready" then
        setStatus("ready collect")
        local packed
        local ok = pcall(function()
            packed = table.pack(Reveal:Fire())
        end)
        local suc = ok and packed and packed[1]
        local err = packed and packed[2]
        local failed = packed and packed[3]
        if suc then
            cache = nil
            lastReqAt = 0
            if failed == true then
                setStatus("failed")
            else
                setStatus("collected")
                if st.loop ~= true then
                    stopSaved()
                end
            end
        elseif type(err) == "string" and err ~= "" then
            setStatus(err)
        end
        task.wait(0.6)
        return
    end
    if state == "Saving" then
        if st.useCharm and SaveCraft then
            local charms = tonumber(info.Charms)
            if charms == nil and CharmMod and type(CharmMod.CountIn) == "function" then
                local okc, n = pcall(CharmMod.CountIn)
                if okc then charms = tonumber(n) or 0 end
            end
            charms = tonumber(charms) or 0
            if charms > 0 then
                setStatus("saving charm")
                pcall(function()
                    SaveCraft:Fire()
                end)
                cache = nil
                lastReqAt = 0
                return
            end
        end
        setStatus("failed no charm")
        return
    end

    -- Empty
    local recName = st.recipe
    if recName == "" then
        local first = recipesOf(info)[1]
        recName = first and first.Name or ""
    end
    local rec = findRecipe(info, recName)
    if not rec then
        setStatus("recipe not in rotation")
        return
    end
    if not hasAll(rec) then
        local need = needText(rec)
        setStatus(need ~= "" and ("need " .. need) or "need ingredients")
        return
    end
    setStatus("start " .. tostring(rec.Display and rec.Display.DisplayName or rec.Name))
    local packed
    local ok = pcall(function()
        packed = table.pack(StartBrew:Fire(rec.Name))
    end)
    local suc = ok and packed and packed[1]
    local err = packed and packed[2]
    if suc then
        cache = nil
        lastReqAt = 0
        setStatus("brewing")
    elseif type(err) == "string" and err ~= "" then
        setStatus(err)
    else
        setStatus("start failed")
    end
end

local function mainLoop(myId)
    while running and loopId == myId do
        pcall(tick)
        task.wait(0.8)
    end
end

function M.SetEnabled(on)
    on = (on == true)
    G.AUTO_CAULDRON_ENABLED = on
    _G.AUTO_CAULDRON_ENABLED = on
    _writeMain({ enabled = on })
    if on then
        running = true
        loopId += 1
        local myId = loopId
        setStatus("on")
        task.spawn(function()
            mainLoop(myId)
        end)
    else
        running = false
        setStatus("off")
    end
end
M.setEnabled = M.SetEnabled
function M.Stop()
    M.SetEnabled(false)
end
M.stop = M.Stop

function M.SetRecipe(name)
    name = tostring(name or "")
    G.AUTO_CAULDRON_RECIPE = name
    _G.AUTO_CAULDRON_RECIPE = name
    _writeMain({ recipe = name })
end
M.setRecipe = M.SetRecipe

function M.SetUseCharm(on)
    on = (on == true)
    G.AUTO_CAULDRON_USE_CHARM = on
    _G.AUTO_CAULDRON_USE_CHARM = on
    _writeMain({ useCharm = on })
end
M.setUseCharm = M.SetUseCharm

function M.SetLoop(on)
    on = (on ~= false)
    G.AUTO_CAULDRON_LOOP = on
    _G.AUTO_CAULDRON_LOOP = on
    _writeMain({ loop = on })
end
M.setLoop = M.SetLoop

function M.SyncFromState()
    local st = getState()
    M.SetRecipe(st.recipe)
    M.SetUseCharm(st.useCharm)
    M.SetLoop(st.loop)
    M.SetEnabled(st.enabled)
end
M.syncFromState = M.SyncFromState

if type(NodeHubWS) == "table" and type(NodeHubWS.OnApplyUI) == "function" then
    NodeHubWS.OnApplyUI("gag2", "auto_cauldron", function(config, message, bridge, api)
        if type(api) ~= "table" or type(api.get) ~= "function" then return true end
        local c = api.get(config, "main.auto.cauldron")
        if type(c) ~= "table" then return true end
        if c.recipe ~= nil then pcall(M.SetRecipe, c.recipe) end
        if c.useCharm ~= nil then pcall(M.SetUseCharm, c.useCharm == true) end
        if c.loop ~= nil then pcall(M.SetLoop, c.loop ~= false) end
        pcall(M.SetEnabled, c.enabled == true)
        return true
    end)
end

return M
 end,                    required = false },
    { key = "AutoSellPet",             name = "Auto Sell Pet",           factory = function() -- AutoSellPet.lua — Grow A Garden 2
-- Equip pet → Networking.NPCS.SellPet:Fire(PetId)

local Players    = game:GetService("Players")
local RunService = game:GetService("RunService")
local RS         = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

M.ModuleVersion = "20260821a"

local LOOP_MIN_SEC      = 0.35
local NO_MATCH_WAIT_SEC = 1.0
local SELL_GAP_SEC      = 0.45

local running = false
local loopId  = 0
local lastStatus = "idle"
local Net = nil

local function _log(...)
    if G.AUTO_SELL_PET_DEBUG == true or rawget(_G, "AUTO_SELL_PET_DEBUG") == true then
        print("[GAG2-SellPet]", ...)
    end
end

local function _publishStatus(msg)
    lastStatus = tostring(msg or "")
    G.__GAG2_SELL_PET_STATUS = lastStatus
    _G.__GAG2_SELL_PET_STATUS = lastStatus
end

local function _writeMain(patch)
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return end
    MAIN.auto = MAIN.auto or {}
    MAIN.auto.sellPet = MAIN.auto.sellPet or {}
    for k, v in pairs(patch) do
        MAIN.auto.sellPet[k] = v
    end
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function _normName(s)
    return tostring(s or ""):lower():gsub("[%s_%-%(%)%,]+", "")
end

local function _resolvePetTrait(tool, kind)
    if not tool then return nil end
    local SectionBuyPet = G.SectionAutoBuyPet or rawget(_G, "SectionAutoBuyPet")
    if kind == "type" then
        local raw = tool:GetAttribute("PetType") or tool:GetAttribute("Type")
        if type(SectionBuyPet) == "table" and type(SectionBuyPet.resolvePetTypeRaw) == "function" then
            return SectionBuyPet.resolvePetTypeRaw(raw)
        end
        return raw
    end
    local raw = tool:GetAttribute("PetSize") or tool:GetAttribute("Size")
    if type(SectionBuyPet) == "table" and type(SectionBuyPet.resolvePetSizeRaw) == "function" then
        return SectionBuyPet.resolvePetSizeRaw(raw)
    end
    return raw
end

local function _petDisplayKey(petName, petType, petSize)
    local Webhook = G.Webhook or rawget(_G, "Webhook")
    if type(Webhook) == "table" and type(Webhook.formatPetDisplayName) == "function" then
        return Webhook.formatPetDisplayName(petName, petType, petSize)
    end
    return tostring(petName or "")
end

local function _getNet()
    if Net and Net.NPCS then return Net end
    local ok, mod = pcall(function()
        local sm = RS:FindFirstChild("SharedModules") or RS:WaitForChild("SharedModules", 10)
        return require(sm:WaitForChild("Networking"))
    end)
    if ok and type(mod) == "table" then
        Net = mod
        return Net
    end
    return nil
end

local function _selectedMap()
    local dd = G.__GAG2_SELL_PET_DROPDOWN_API or rawget(_G, "__GAG2_SELL_PET_DROPDOWN_API")
    if type(dd) == "table" and type(dd.getSelected) == "function" then
        local ok, sel = pcall(dd.getSelected, dd)
        if ok and type(sel) == "table" and next(sel) ~= nil then
            return sel
        end
    end

    local map = G.AUTO_SELL_PET_SELECTED or rawget(_G, "AUTO_SELL_PET_SELECTED")
    if type(map) == "table" and next(map) ~= nil then
        return map
    end

    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local pets = MAIN and MAIN.auto and MAIN.auto.sellPet and MAIN.auto.sellPet.pets
    if type(pets) ~= "table" then return {} end
    local out = {}
    for _, name in ipairs(pets) do
        local key = tostring(name or "")
        if key ~= "" then out[key] = true end
    end
    return out
end

local function _enabled()
    local api = G.__GAG2_SELL_PET_ENABLE_API or rawget(_G, "__GAG2_SELL_PET_ENABLE_API")
    if type(api) == "table" and type(api.get) == "function" then
        local ok, v = pcall(api.get, api)
        if ok then return v == true end
    end
    if G.AUTO_SELL_PET_ENABLED == true or rawget(_G, "AUTO_SELL_PET_ENABLED") == true then
        return true
    end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto.sellPet
    return type(st) == "table" and st.enabled == true
end

local function _isSelectedPet(info, selected)
    if type(info) ~= "table" or next(selected) == nil then return false end

    local displayKey = _petDisplayKey(info.name, info.petType, info.petSize)
    if selected[displayKey] == true then return true end

    local normDisplay = _normName(displayKey)
    for key, on in pairs(selected) do
        if on == true then
            local sk = tostring(key):gsub("%s*x%s+.+$", "")
            if sk == displayKey then return true end
            if _normName(sk) == normDisplay then return true end
        end
    end
    return false
end

local function _getLP()
    local lp = LP or Players.LocalPlayer
    if lp then LP = lp end
    return lp
end

local function _isFavorited(tool, petId)
    if tool and type(tool.GetAttribute) == "function" then
        local v = tool:GetAttribute("IsFavorite")
        if v == true or v == 1 or v == "true" or v == "1" then return true end
        v = tool:GetAttribute("Favorite") or tool:GetAttribute("Favorited")
        if v == true or v == 1 or v == "true" or v == "1" then return true end
    end
    local id = tostring(petId or "")
    if id == "" and tool and type(tool.GetAttribute) == "function" then
        id = tostring(tool:GetAttribute("PetId") or tool:GetAttribute("PetID") or "")
    end
    if id ~= "" then
        local favCache = G.__GAG2_FAV_PET_CACHE or rawget(_G, "__GAG2_FAV_PET_CACHE")
        if type(favCache) == "table" and favCache[id] == true then return true end
        local unfavCache = G.__GAG2_UNFAV_PET_CACHE or rawget(_G, "__GAG2_UNFAV_PET_CACHE")
        if type(unfavCache) == "table" and unfavCache[id] == true then return false end
    end
    return false
end

local function _petInfo(tool)
    if not tool or not tool:IsA("Tool") then return nil end

    local petAttr = tool:GetAttribute("Pet")
    local petName = petAttr
        or tool:GetAttribute("PetName")
        or tool:GetAttribute("PetType")

    if petAttr == nil and petName == nil then
        return nil
    end

    local petId = tool:GetAttribute("PetId")
        or tool:GetAttribute("PetID")
        or tool:GetAttribute("Id")
        or tool:GetAttribute("UUID")
        or tool:GetAttribute("InstanceId")

    if not petId then return nil end

    return {
        tool = tool,
        id = tostring(petId),
        name = tostring(petAttr or petName or tool.Name),
        petType = _resolvePetTrait(tool, "type"),
        petSize = _resolvePetTrait(tool, "size"),
        favorite = _isFavorited(tool, petId),
    }
end

local function _scanTools(container, add)
    if not container then return end
    for _, inst in ipairs(container:GetChildren()) do
        if inst:IsA("Tool") then add(inst) end
    end
    for _, inst in ipairs(container:GetDescendants()) do
        if inst:IsA("Tool") then add(inst) end
    end
end

function M.CollectPets()
    local lp = _getLP()
    if not lp then return {} end

    local out, seen = {}, {}
    local function add(tool)
        local info = _petInfo(tool)
        if info and not seen[info.id] then
            seen[info.id] = true
            out[#out + 1] = info
        end
    end

    _scanTools(lp:FindFirstChild("Backpack") or lp:FindFirstChildOfClass("Backpack"), add)
    _scanTools(lp.Character, add)

    return out
end

function M.CollectMatchingPets()
    local selected = _selectedMap()
    if next(selected) == nil then return {} end

    local out = {}
    for _, p in ipairs(M.CollectPets()) do
        if p.favorite == true then
            continue
        end
        if _isSelectedPet(p, selected) then
            out[#out + 1] = p
        end
    end
    return out
end

local function _equipTool(tool)
    local lp = _getLP()
    if not lp or not tool then return false end

    if not tool.Parent then return false end

    local char = lp.Character
    if not char then
        char = lp.CharacterAdded:Wait()
        task.wait(0.2)
    end

    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return false end

    local bp = lp:FindFirstChild("Backpack") or lp:FindFirstChildOfClass("Backpack")
    if tool.Parent ~= bp and tool.Parent ~= char then
        return false
    end

    if char:FindFirstChildOfClass("Tool") and char:FindFirstChildOfClass("Tool") ~= tool then
        pcall(function() hum:UnequipTools() end)
        task.wait(0.15)
    end

    pcall(function() hum:EquipTool(tool) end)

    for _ = 1, 12 do
        if tool.Parent == char then return true end
        local equipped = char:FindFirstChildOfClass("Tool")
        if equipped and _petInfo(equipped) then return true end
        task.wait(0.05)
    end

    return tool.Parent == char
end

local function _equippedPetInfo(fallback)
    local lp = _getLP()
    local char = lp and lp.Character
    if not char then return fallback end
    local tool = char:FindFirstChildOfClass("Tool")
    return (tool and _petInfo(tool)) or fallback
end

local function _sellReason(res)
    if type(res) == "table" then
        return tostring(res.Reason or res.reason or res.Message or res.message or "")
    end
    return tostring(res or "")
end

local function _refreshSellPetDropdown()
    local fn = G.__GAG2_REFRESH_SELL_PET_DROPDOWN or rawget(_G, "__GAG2_REFRESH_SELL_PET_DROPDOWN")
    if type(fn) == "function" then
        pcall(fn)
    end
end

local function _sellPet(petId)
    local net = _getNet()
    local pkt = net and net.NPCS and net.NPCS.SellPet
    if not pkt or type(pkt.Fire) ~= "function" then
        return false, "no_SellPet"
    end

    local ok, res = pcall(function()
        return pkt:Fire(petId)
    end)
    if not ok then return false, res end
    if type(res) == "table" and res.Success then
        return true, res
    end
    return false, res
end

function M.SellOnePet(p)
    if type(p) ~= "table" or not p.tool then
        return false, "bad_pet"
    end

    if not p.tool.Parent then
        return false, "tool_gone"
    end

    if _isFavorited(p.tool, p.id) then
        return false, "favorite"
    end

    if not _equipTool(p.tool) then
        _log("equip failed", p.name)
        return false, "equip_failed"
    end

    local info = _equippedPetInfo(p)
    if not info or not info.id then
        return false, "no_pet_id"
    end

    local ok, res = _sellPet(info.id)
    if ok then
        if info.tool and info.tool.Parent then
            pcall(function() info.tool:Destroy() end)
        end
        _log("sold", info.name, info.id, res and res.SellPrice)
        task.defer(_refreshSellPetDropdown)
        return true, res
    end

    _log("sell failed", info.name, info.id, _sellReason(res))
    return false, res
end

function M.TrySellOnce()
    local selected = _selectedMap()
    if next(selected) == nil then
        return false, "no_selection"
    end

    local pets = M.CollectMatchingPets()
    if #pets == 0 then
        return false, "no_pets"
    end

    local p = pets[1]
    _publishStatus("Selling " .. tostring(p.name))
    local ok, res = M.SellOnePet(p)
    if ok then
        _publishStatus("Sold " .. tostring(p.name))
        return true, res
    end

    _publishStatus("Sell failed: " .. tostring(p.name) .. " (" .. _sellReason(res) .. ")")
    return false, res
end

local function _loop(myId)
    while running and loopId == myId and _enabled() do
        local selected = _selectedMap()
        if next(selected) == nil then
            _publishStatus("Select pets to sell")
            task.wait(NO_MATCH_WAIT_SEC)
        else
            local pets = M.CollectMatchingPets()
            if #pets == 0 then
                local anyMatch = false
                for _, p in ipairs(M.CollectPets()) do
                    if _isSelectedPet(p, selected) then
                        anyMatch = true
                        break
                    end
                end
                if anyMatch then
                    _publishStatus("Skip favorite pets")
                else
                    _publishStatus("Waiting for pets...")
                end
                task.wait(NO_MATCH_WAIT_SEC)
            else
                M.TrySellOnce()
                task.wait(SELL_GAP_SEC)
            end
        end
        RunService.Heartbeat:Wait()
    end

    if loopId == myId then
        running = false
        _publishStatus("Stopped")
    end
end

function M.Start()
    if not _enabled() then
        running = false
        return
    end

    loopId += 1
    running = true
    local myId = loopId
    _publishStatus("Running")
    task.spawn(function() _loop(myId) end)
end
M.start = M.Start

function M.Stop()
    running = false
    loopId += 1
    _publishStatus("Stopped")
end
M.stop = M.Stop

function M.Restart()
    if not _enabled() then
        M.Stop()
        return
    end
    M.Start()
end
M.restart = M.Restart

function M.IsRunning()
    return running == true
end

function M.SetEnabled(on)
    on = (on == true)
    _writeMain({ enabled = on })
    G.AUTO_SELL_PET_ENABLED = on
    _G.AUTO_SELL_PET_ENABLED = on
    if on then
        M.Start()
    else
        M.Stop()
    end
    return on
end
M.setEnabled = M.SetEnabled

function M.ApplyRuntime(on)
    M.SetEnabled(on == true)
end
M.applyRuntime = M.ApplyRuntime

function M.SyncFromGlobals()
    local on = _enabled()
    G.AUTO_SELL_PET_ENABLED = on
    _G.AUTO_SELL_PET_ENABLED = on
    if on then
        M.Start()
    else
        M.Stop()
    end
end
M.syncFromGlobals = M.SyncFromGlobals

function M.GetStatus()
    return lastStatus
end

G.AutoSellPet = M
G.AutoSellPetModule = M
_G.AutoSellPet = M
_G.AutoSellPetModule = M

return M
 end,                     required = false },
    { key = "SectionAutoSellPet",      name = "Section Auto Sell Pet",   factory = function() -- section_auto_sell_pet.lua — UI Auto Sell Pet (tab Auto → Pet)

local G = (getgenv and getgenv()) or _G
local M = {}

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto       = ctx.getAuto
    local patchAuto     = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local cleanSelectedMap = ctx.cleanSelectedMap
    local arrayToMap = ctx.arrayToMap
    local mapToArray = ctx.mapToArray
    local function getAutoGiftModule()
        return G.AutoGift or G.AutoGiftModule or rawget(_G, "AutoGift") or rawget(_G, "AutoGiftModule")
    end

    local SP_STATE = getAuto("sellPet")
    SP_STATE.enabled = (SP_STATE.enabled == true)
    SP_STATE.pets = type(SP_STATE.pets) == "table" and SP_STATE.pets or {}

    if G.AUTO_SELL_PET_ENABLED == true or rawget(_G, "AUTO_SELL_PET_ENABLED") == true then
        SP_STATE.enabled = true
    end

    local petsSelected = cleanSelectedMap(arrayToMap(SP_STATE.pets))
    local gsel = G.AUTO_SELL_PET_SELECTED or rawget(_G, "AUTO_SELL_PET_SELECTED")
    if type(gsel) == "table" and next(gsel) then
        petsSelected = cleanSelectedMap(gsel)
        SP_STATE.pets = mapToArray(petsSelected)
    end

    local function sellPetSnapshot()
        local api = G.__GAG2_SELL_PET_ENABLE_API or rawget(_G, "__GAG2_SELL_PET_ENABLE_API")
        if type(api) == "table" and type(api.get) == "function" then
            SP_STATE.enabled = (api.get() == true)
        end

        local dd = G.__GAG2_SELL_PET_DROPDOWN_API or rawget(_G, "__GAG2_SELL_PET_DROPDOWN_API")
        if type(dd) == "table" and type(dd.getSelected) == "function" then
            local ok, sel = pcall(dd.getSelected, dd)
            if ok and type(sel) == "table" then
                petsSelected = cleanSelectedMap(sel)
            end
        end

        return {
            enabled = (SP_STATE.enabled == true),
            pets = mapToArray(petsSelected),
        }
    end

    local function writeSellPetGlobals()
        local snap = sellPetSnapshot()

        G.AUTO_SELL_PET_ENABLED = snap.enabled
        _G.AUTO_SELL_PET_ENABLED = G.AUTO_SELL_PET_ENABLED

        petsSelected = cleanSelectedMap(arrayToMap(snap.pets))
        G.AUTO_SELL_PET_SELECTED = petsSelected
        _G.AUTO_SELL_PET_SELECTED = petsSelected

        SP_STATE.pets = snap.pets
        patchAutoOnly("sellPet", snap)
    end

    local function syncSellPetModule()
        writeSellPetGlobals()
        local mod = G.AutoSellPet or G.AutoSellPetModule or rawget(_G, "AutoSellPet")
        if type(mod) ~= "table" then
            warn("[GAG2] AutoSellPet module belum loaded — re-execute hub")
            return
        end
        if G.AUTO_SELL_PET_ENABLED then
            if type(mod.Restart) == "function" then
                pcall(mod.Restart, mod)
            elseif type(mod.SetEnabled) == "function" then
                pcall(mod.SetEnabled, mod, true)
            elseif type(mod.Start) == "function" then
                pcall(mod.Start, mod)
            end
        else
            if type(mod.SetEnabled) == "function" then
                pcall(mod.SetEnabled, mod, false)
            elseif type(mod.Stop) == "function" then
                pcall(mod.Stop, mod)
            end
        end
    end

    local function persistSellPet()
        writeSellPetGlobals()
        if type(patchAuto) == "function" then
            patchAuto("sellPet", sellPetSnapshot(), syncSellPetModule)
        else
            syncSellPetModule()
        end
    end

    G.__GAG2_PUSH_SELL_PET = writeSellPetGlobals
    _G.__GAG2_PUSH_SELL_PET = writeSellPetGlobals
    G.__GAG2_SYNC_AUTO_SELL_PET = syncSellPetModule
    _G.__GAG2_SYNC_AUTO_SELL_PET = syncSellPetModule

    writeSellPetGlobals()

    local body = ui:CreateSection("Auto Sell Pet", false)
    local sellOn = SP_STATE.enabled == true

    local function currentSellPetSelected()
        local dd = G.__GAG2_SELL_PET_DROPDOWN_API or rawget(_G, "__GAG2_SELL_PET_DROPDOWN_API")
        if type(dd) == "table" and type(dd.getSelected) == "function" then
            local ok, sel = pcall(dd.getSelected, dd)
            if ok and type(sel) == "table" then
                return cleanSelectedMap(sel)
            end
        end
        local gsel = G.AUTO_SELL_PET_SELECTED or rawget(_G, "AUTO_SELL_PET_SELECTED")
        if type(gsel) == "table" and next(gsel) then
            return cleanSelectedMap(gsel)
        end
        return cleanSelectedMap(petsSelected)
    end

    local function refreshSellPetDropdown()
        local dd = G.__GAG2_SELL_PET_DROPDOWN_API or rawget(_G, "__GAG2_SELL_PET_DROPDOWN_API")
        if type(dd) == "table" and type(dd.refreshItems) == "function" then
            pcall(dd.refreshItems, dd)
        end
    end

    local _, petDdApi = ui:CreateRowDropdown(body, {
        label = "Pet list (skip favorite)",
        placeholder = "Choose pets...",
        mode = "multi",
        deferItemLoad = true,
        labelForKey = function(key)
            return tostring(key or "")
        end,
        getItems = function()
            local ag = getAutoGiftModule()
            if type(ag) == "table" and type(ag.BuildInventoryItems) == "function" then
                local ok, items = pcall(ag.BuildInventoryItems, ag, "Pets", currentSellPetSelected())
                if ok and type(items) == "table" then return items end
            end
            return {}
        end,
        initial = petsSelected,
        onChanged = function(_, selectedMap)
            petsSelected = cleanSelectedMap(selectedMap)
            SP_STATE.pets = mapToArray(petsSelected)
            persistSellPet()
        end,
    })

    G.__GAG2_SELL_PET_DROPDOWN_API = petDdApi
    _G.__GAG2_SELL_PET_DROPDOWN_API = petDdApi
    G.__GAG2_REFRESH_SELL_PET_DROPDOWN = refreshSellPetDropdown
    _G.__GAG2_REFRESH_SELL_PET_DROPDOWN = refreshSellPetDropdown

    task.defer(function()
        if petDdApi and type(petDdApi.setSelected) == "function" and next(petsSelected) then
            petDdApi.setSelected(petsSelected)
            if type(petDdApi.refreshLabel) == "function" then
                petDdApi.refreshLabel()
            end
        end
    end)

    local _, _, enableApi = ui:CreateRowToggle(
        body,
        "Enabled Auto Sell Pet",
        sellOn,
        function(isOn)
            SP_STATE.enabled = (isOn == true)
            persistSellPet()
        end
    )

    G.__GAG2_SELL_PET_ENABLE_API = enableApi
    _G.__GAG2_SELL_PET_ENABLE_API = enableApi

    if enableApi and type(enableApi.set) == "function" then
        enableApi.set(sellOn, true)
    end

    syncSellPetModule()
end

G.SectionAutoSellPet = M
_G.SectionAutoSellPet = M

return M
 end,            required = false },
    { key = "AutoFavPet",              name = "Auto Fav Pet",            factory = function() -- AutoFavPet.lua — Grow A Garden 2
-- Auto favorite / unfavorite pets (Networking.Backpack.SetPetFavorite)
-- Dump: InventoryController.ToggleFavorite → SetPetFavorite:Fire(PetId, bool)
-- Attributes: Pet, PetId, PetType (Rainbow), PetSize (Big/Huge), IsFavorite

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

M.ModuleVersion = "20260818a"

local SetPetFavorite
local FIRE_DELAY    = 0.05
local IDLE_WAIT_SEC = 1
local CAND_CACHE_SEC = 4.0

pcall(function()
    local Networking = require(ReplicatedStorage.SharedModules.Networking)
    SetPetFavorite = Networking and Networking.Backpack and Networking.Backpack.SetPetFavorite
end)

local running = { fav = false, unfav = false }
local loopId  = { fav = 0, unfav = 0 }

local favCache = {}
local unfavCache = {}
do
    local extFav = G.__GAG2_FAV_PET_CACHE or rawget(_G, "__GAG2_FAV_PET_CACHE")
    if type(extFav) == "table" then favCache = extFav end
    local extUnfav = G.__GAG2_UNFAV_PET_CACHE or rawget(_G, "__GAG2_UNFAV_PET_CACHE")
    if type(extUnfav) == "table" then unfavCache = extUnfav end
end

local stats = {
    favProcessed   = 0,
    unfavProcessed = 0,
    lastStatus     = "Ready",
    lastError      = nil,
}

local candCache = {
    fav   = { n = 0, at = 0, key = "" },
    unfav = { n = 0, at = 0, key = "" },
}

local function _syncCache()
    G.__GAG2_FAV_PET_CACHE = favCache
    _G.__GAG2_FAV_PET_CACHE = favCache
    G.__GAG2_UNFAV_PET_CACHE = unfavCache
    _G.__GAG2_UNFAV_PET_CACHE = unfavCache
end

local function _dbg()
    return G.AUTO_FAV_PET_DEBUG == true or rawget(_G, "AUTO_FAV_PET_DEBUG") == true
end

local function _log(...)
    if _dbg() then print("[GAG2-FavPet]", ...) end
end

local function _setStatus(msg, err)
    stats.lastStatus = tostring(msg or "")
    stats.lastError = err
    G.AUTO_FAV_PET_STATUS = stats.lastStatus
    _G.AUTO_FAV_PET_STATUS = stats.lastStatus
end

local function _ensureRemote()
    if SetPetFavorite and type(SetPetFavorite.Fire) == "function" then
        return true
    end
    local ok, net = pcall(function()
        return require(ReplicatedStorage.SharedModules.Networking)
    end)
    if ok and type(net) == "table" and type(net.Backpack) == "table" then
        SetPetFavorite = net.Backpack.SetPetFavorite
    end
    return SetPetFavorite ~= nil and type(SetPetFavorite.Fire) == "function"
end

local function _truthyAttr(v)
    return v == true or v == 1 or v == "true" or v == "1"
end

local function _canon(s)
    return tostring(s or ""):lower():gsub("[%s_%-%(%)%,%.]+", "")
end

local function _hasAny(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then return true end
    end
    return false
end

local function _normalizeSet(src)
    if type(src) ~= "table" then return {} end
    local out = {}
    for i = 1, #src do
        local v = src[i]
        if v ~= nil and tostring(v) ~= "" then out[tostring(v)] = true end
    end
    if next(out) then return out end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then out[tostring(k)] = true end
    end
    return out
end

local function _selectedMap(live, fallback)
    if type(live) == "table" and next(live) then
        return _normalizeSet(live)
    end
    return _normalizeSet(fallback)
end

local function _buyPetSection()
    return G.SectionAutoBuyPet or rawget(_G, "SectionAutoBuyPet")
end

local function _resolvePetType(raw)
    local sec = _buyPetSection()
    if type(sec) == "table" and type(sec.resolvePetTypeRaw) == "function" then
        local ok, v = pcall(sec.resolvePetTypeRaw, raw)
        if ok and v ~= nil and tostring(v) ~= "" then return tostring(v) end
    end
    if raw == nil or raw == "" then return "Normal" end
    local s = tostring(raw):gsub("^%s+", ""):gsub("%s+$", "")
    if s == "" then return "Normal" end
    if _canon(s) == "rainbow" then return "Rainbow" end
    return s
end

local function _resolvePetSize(raw)
    local sec = _buyPetSection()
    if type(sec) == "table" and type(sec.resolvePetSizeRaw) == "function" then
        local ok, v = pcall(sec.resolvePetSizeRaw, raw)
        if ok and v ~= nil and tostring(v) ~= "" then return tostring(v) end
    end
    if raw == nil or raw == "" then return "Normal" end
    local s = tostring(raw):gsub("^%s+", ""):gsub("%s+$", "")
    if s == "" then return "Normal" end
    local c = _canon(s)
    if c == "big" then return "Big" end
    if c == "huge" then return "Huge" end
    if c == "normal" then return "Normal" end
    return s
end

local function _typeMatches(raw, allowed)
    if not _hasAny(allowed) then return true end
    local sec = _buyPetSection()
    if type(sec) == "table" and type(sec.typeMatchesRule) == "function" then
        local ok, v = pcall(sec.typeMatchesRule, raw, allowed)
        if ok then return v == true end
    end
    local want = _canon(_resolvePetType(raw))
    for k, on in pairs(allowed) do
        if on == true and _canon(k) == want then return true end
    end
    return false
end

local function _sizeMatches(raw, allowed)
    if not _hasAny(allowed) then return true end
    local sec = _buyPetSection()
    if type(sec) == "table" and type(sec.sizeMatchesRule) == "function" then
        local ok, v = pcall(sec.sizeMatchesRule, raw, allowed)
        if ok then return v == true end
    end
    local want = _canon(_resolvePetSize(raw))
    for k, on in pairs(allowed) do
        if on == true and _canon(k) == want then return true end
    end
    return false
end

local function _prefix(mode)
    return (mode == "unfav") and "AUTO_UNFAV_PET_" or "AUTO_FAV_PET_"
end

local function _mainKey(mode)
    return (mode == "unfav") and "unfavPet" or "favPet"
end

local function _getFilterState(mode)
    mode = (mode == "unfav") and "unfav" or "fav"
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.auto and MAIN.auto[_mainKey(mode)]
    st = type(st) == "table" and st or {}

    local prefix = _prefix(mode)
    local apiKey = (mode == "unfav") and "__GAG2_UNFAV_PET_ENABLE_API" or "__GAG2_FAV_PET_ENABLE_API"
    local enabled = (st.enabled == true)
    local api = G[apiKey] or rawget(_G, apiKey)
    if type(api) == "table" and type(api.get) == "function" then
        local ok, v = pcall(api.get, api)
        if ok then enabled = (v == true) end
    elseif G[prefix .. "ENABLED"] == true or rawget(_G, prefix .. "ENABLED") == true then
        enabled = true
    end

    return {
        enabled = enabled,
        pets    = _selectedMap(G[prefix .. "SELECTED"] or rawget(_G, prefix .. "SELECTED"), st.pets),
        types   = _selectedMap(G[prefix .. "TYPES_SELECTED"] or rawget(_G, prefix .. "TYPES_SELECTED"), st.types),
        sizes   = _selectedMap(G[prefix .. "SIZES_SELECTED"] or rawget(_G, prefix .. "SIZES_SELECTED"), st.sizes),
    }
end

local function _isFavorited(tool)
    if not tool or type(tool.GetAttribute) ~= "function" then return false end
    if _truthyAttr(tool:GetAttribute("IsFavorite")) then return true end
    if _truthyAttr(tool:GetAttribute("Favorite")) then return true end
    if _truthyAttr(tool:GetAttribute("Favorited")) then return true end
    return false
end

local function _petId(tool)
    if not tool or type(tool.GetAttribute) ~= "function" then return "" end
    local id = tool:GetAttribute("PetId")
        or tool:GetAttribute("PetID")
        or tool:GetAttribute("Id")
        or tool:GetAttribute("UUID")
    if id == nil then return "" end
    return tostring(id)
end

local function _petName(tool)
    if not tool then return "" end
    return tostring(
        tool:GetAttribute("Pet")
        or tool:GetAttribute("PetName")
        or tool:GetAttribute("PetSpecies")
        or tool.Name
        or ""
    )
end

local function _isPetTool(inst)
    if not inst or not inst.Parent then return false end
    if not inst:IsA("Tool") then return false end
    if type(inst.GetAttribute) ~= "function" then return false end
    if inst:GetAttribute("PetId") ~= nil then return true end
    if inst:GetAttribute("Pet") ~= nil then return true end
    return false
end

local function _matchPetName(name, selected)
    if not _hasAny(selected) then return true end
    name = tostring(name or "")
    if selected[name] == true then return true end
    local cn = _canon(name)
    if cn == "" then return false end
    for k, on in pairs(selected) do
        if on == true then
            local sk = tostring(k):gsub("%s*%b()%s*$", ""):gsub("%s*x%s+.+$", "")
            if sk == name or _canon(sk) == cn or _canon(k) == cn then
                return true
            end
        end
    end
    return false
end

local function _matchesFilters(tool, ac)
    if not tool then return false end
    if not _matchPetName(_petName(tool), ac.pets) then return false end
    if not _typeMatches(tool:GetAttribute("PetType") or tool:GetAttribute("Type"), ac.types) then
        return false
    end
    if not _sizeMatches(tool:GetAttribute("PetSize") or tool:GetAttribute("Size"), ac.sizes) then
        return false
    end
    return true
end

local function _getLP()
    local lp = LP or Players.LocalPlayer
    if lp then LP = lp end
    return lp
end

local function _eachPetTool(fn)
    if type(fn) ~= "function" then return end
    local lp = _getLP()
    if not lp then return end
    local seen = {}
    local function scan(root)
        if not root then return end
        for _, inst in ipairs(root:GetChildren()) do
            if not seen[inst] and _isPetTool(inst) then
                seen[inst] = true
                fn(inst)
            end
        end
    end
    scan(lp:FindFirstChild("Backpack") or lp:FindFirstChildOfClass("Backpack"))
    scan(lp.Character)
end

local function _isFavCached(id)
    id = tostring(id or "")
    return id ~= "" and favCache[id] == true
end

local function _isUnfavCached(id)
    id = tostring(id or "")
    return id ~= "" and unfavCache[id] == true
end

local function _markFavCached(id)
    id = tostring(id or "")
    if id == "" then return end
    favCache[id] = true
    unfavCache[id] = nil
    _syncCache()
end

local function _markUnfavCached(id)
    id = tostring(id or "")
    if id == "" then return end
    unfavCache[id] = true
    favCache[id] = nil
    _syncCache()
end

local function _fireFavorite(tool, on)
    if not tool or not _ensureRemote() then
        return false, "no_remote"
    end
    local id = _petId(tool)
    if id == "" then
        return false, "no_id"
    end
    on = (on == true)
    if typeof(tool) == "Instance" and type(tool.SetAttribute) == "function" then
        tool:SetAttribute("IsFavorite", on and true or nil)
    end
    if on then
        _markFavCached(id)
    else
        _markUnfavCached(id)
    end
    task.spawn(function()
        pcall(function()
            SetPetFavorite:Fire(id, on)
        end)
    end)
    return true
end

local function _collectPending(mode, ac)
    local wantOn = (mode == "fav")
    local list = {}
    _eachPetTool(function(tool)
        local id = _petId(tool)
        if id == "" then return end
        if not _matchesFilters(tool, ac) then return end
        local fav = _isFavorited(tool)
        if wantOn then
            if fav or _isFavCached(id) then return end
        elseif not fav or _isUnfavCached(id) then
            return
        end
        list[#list + 1] = tool
    end)
    return list
end

local function _candidateCacheKey(mode, ac)
    local nPet, nType, nSize = 0, 0, 0
    if type(ac.pets) == "table" then for _ in pairs(ac.pets) do nPet += 1 end end
    if type(ac.types) == "table" then for _ in pairs(ac.types) do nType += 1 end end
    if type(ac.sizes) == "table" then for _ in pairs(ac.sizes) do nSize += 1 end end
    return table.concat({
        mode,
        ac.enabled and "1" or "0",
        tostring(nPet),
        tostring(nType),
        tostring(nSize),
    }, ":")
end

local function _runPass(mode)
    local ac = _getFilterState(mode)
    local wantOn = (mode == "fav")
    local list = _collectPending(mode, ac)
    if #list == 0 then
        return false, "no_items", 0
    end

    local okCount = 0
    _setStatus(((mode == "fav") and "Fav pet" or "Unfav pet") .. (" scan: %d..."):format(#list))
    _log("pass", mode, #list)

    for i = 1, #list do
        if _fireFavorite(list[i], wantOn) then
            okCount += 1
            if wantOn then
                stats.favProcessed += 1
            else
                stats.unfavProcessed += 1
            end
        end
        if i < #list and FIRE_DELAY > 0 then
            task.wait(FIRE_DELAY)
        end
    end

    if okCount > 0 then
        _setStatus(("%s: %d pet"):format(wantOn and "Fav pet" or "Unfav pet", okCount))
        return true, "done", okCount
    end
    if not _ensureRemote() then
        _setStatus("Fav pet: remote belum ready")
        return false, "no_remote", 0
    end
    return false, "no_items", 0
end

local function _loop(mode, myId)
    task.wait(0.05)
    while running[mode] and loopId[mode] == myId do
        local ac = _getFilterState(mode)
        if not ac.enabled then
            task.wait(0.5)
        else
            local ok, reason = _runPass(mode)
            if reason == "no_items" then
                _setStatus((mode == "fav") and "Fav pet: idle" or "Unfav pet: idle")
                task.wait(IDLE_WAIT_SEC)
            elseif ok then
                task.wait(0.05)
            else
                task.wait(0.25)
            end
        end
    end
end

local function _start(mode)
    mode = (mode == "unfav") and "unfav" or "fav"
    if running[mode] then return false end
    running[mode] = true
    loopId[mode] += 1
    local myId = loopId[mode]
    task.spawn(function()
        _loop(mode, myId)
    end)
    return true
end

local function _stop(mode)
    mode = (mode == "unfav") and "unfav" or "fav"
    running[mode] = false
    loopId[mode] += 1
end

function M.CountCandidates(mode)
    mode = (mode == "unfav") and "unfav" or "fav"
    local ac = _getFilterState(mode)
    local n = #_collectPending(mode, ac)
    local cache = candCache[mode]
    cache.n = n
    cache.at = os.clock()
    cache.key = _candidateCacheKey(mode, ac)
    return n
end

function M.PeekCandidateCount(mode)
    mode = (mode == "unfav") and "unfav" or "fav"
    local ac = _getFilterState(mode)
    local cache = candCache[mode]
    local now = os.clock()
    local key = _candidateCacheKey(mode, ac)
    if cache.key == key and (now - cache.at) <= CAND_CACHE_SEC then
        return cache.n
    end
    return M.CountCandidates(mode)
end

function M.SetFavEnabled(on)
    on = (on == true)
    G.AUTO_FAV_PET_ENABLED = on
    _G.AUTO_FAV_PET_ENABLED = on
    _stop("fav")
    if on then _start("fav") end
    return on
end

function M.SetUnfavEnabled(on)
    on = (on == true)
    G.AUTO_UNFAV_PET_ENABLED = on
    _G.AUTO_UNFAV_PET_ENABLED = on
    _stop("unfav")
    if on then _start("unfav") end
    return on
end

function M.StartFav() return _start("fav") end
function M.StopFav() _stop("fav") end
function M.StartUnfav() return _start("unfav") end
function M.StopUnfav() _stop("unfav") end

function M.Start()
    M.SyncFromState()
end

function M.Stop()
    _stop("fav")
    _stop("unfav")
end

function M.Restart()
    M.Stop()
    M.Start()
end

function M.IsRunning()
    return running.fav == true or running.unfav == true
end

function M.SyncFromState()
    local fav = _getFilterState("fav")
    local unfav = _getFilterState("unfav")
    M.StopFav()
    M.StopUnfav()
    if fav.enabled then M.StartFav() end
    if unfav.enabled then M.StartUnfav() end
    if fav.enabled and unfav.enabled then
        _setStatus("Fav + Unfav pet aktif")
    elseif fav.enabled then
        _setStatus("Fav pet aktif")
    elseif unfav.enabled then
        _setStatus("Unfav pet aktif")
    else
        _setStatus("Ready")
    end
end

M.syncFromState = M.SyncFromState
M.syncFromGlobals = M.SyncFromState
M.start = M.Start
M.stop = M.Stop
M.restart = M.Restart
M.peekCandidateCount = M.PeekCandidateCount

function M.GetStats()
    return {
        lastStatus = stats.lastStatus,
        lastError = stats.lastError,
        favProcessed = stats.favProcessed,
        unfavProcessed = stats.unfavProcessed,
        favRunning = running.fav,
        unfavRunning = running.unfav,
        favReady = M.PeekCandidateCount("fav"),
        unfavReady = M.PeekCandidateCount("unfav"),
    }
end

function M.ClearCache()
    table.clear(favCache)
    table.clear(unfavCache)
    _syncCache()
end

G.AutoFavPet = M
G.AutoFavPetModule = M
_G.AutoFavPet = M
_G.AutoFavPetModule = M

return M
 end,                      required = false },
    { key = "SectionAutoFavPet",       name = "Section Auto Fav Pet",    factory = function() -- section_auto_fav_pet.lua — UI Auto Fav / Auto Unfav Pet (tab Auto → Pet)
-- Filter: pet name + type (Rainbow) + size (Big/Huge) dari dump SharedData.PetTypes / PetSizes

local G = (getgenv and getgenv()) or _G
local M = {}

local FALLBACK_TYPES = {
    { key = "Normal", name = "Normal" },
    { key = "Rainbow", name = "RAINBOW" },
}

local FALLBACK_SIZES = {
    { key = "Normal", name = "Normal" },
    { key = "Big", name = "Big" },
