function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto = ctx.getAuto
    local patchAuto = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local registerFlush = ctx.registerFlush
    local cleanSelectedMap = ctx.cleanSelectedMap
    local arrayToMap = ctx.arrayToMap
    local mapToArray = ctx.mapToArray
    local toggleApiGet = ctx.toggleApiGet

    local function buildBlock(key, sectionTitle, toggleLabel, enableApiGlobal)
        local ST = getAuto(key)
        if type(ST) ~= "table" then ST = {} end
        ST.pets = type(ST.pets) == "table" and ST.pets or {}
        ST.types = type(ST.types) == "table" and ST.types or {}
        ST.sizes = type(ST.sizes) == "table" and ST.sizes or {}

        local prefix = (key == "unfavPet") and "AUTO_UNFAV_PET_" or "AUTO_FAV_PET_"
        local petsSelected = cleanSelectedMap(arrayToMap(ST.pets))
        local typesSelected = cleanSelectedMap(arrayToMap(ST.types))
        local sizesSelected = cleanSelectedMap(arrayToMap(ST.sizes))

        G[prefix .. "SELECTED"] = petsSelected
        _G[prefix .. "SELECTED"] = petsSelected
        G[prefix .. "TYPES_SELECTED"] = typesSelected
        _G[prefix .. "TYPES_SELECTED"] = typesSelected
        G[prefix .. "SIZES_SELECTED"] = sizesSelected
        _G[prefix .. "SIZES_SELECTED"] = sizesSelected
        G[prefix .. "ENABLED"] = (ST.enabled == true)
        _G[prefix .. "ENABLED"] = G[prefix .. "ENABLED"]

        local function writeGlobals()
            local api = G[enableApiGlobal] or rawget(_G, enableApiGlobal)
            if type(api) == "table" and type(api.get) == "function" then
                ST.enabled = (api.get() == true)
            end

            G[prefix .. "ENABLED"] = (ST.enabled == true)
            _G[prefix .. "ENABLED"] = G[prefix .. "ENABLED"]
            G[prefix .. "SELECTED"] = petsSelected
            _G[prefix .. "SELECTED"] = petsSelected
            G[prefix .. "TYPES_SELECTED"] = typesSelected
            _G[prefix .. "TYPES_SELECTED"] = typesSelected
            G[prefix .. "SIZES_SELECTED"] = sizesSelected
            _G[prefix .. "SIZES_SELECTED"] = sizesSelected

            patchAutoOnly(key, {
                enabled = (ST.enabled == true),
                pets = mapToArray(petsSelected),
                types = mapToArray(typesSelected),
                sizes = mapToArray(sizesSelected),
            })
        end

        local function syncModule()
            writeGlobals()
            local mod = G.AutoFavPet or G.AutoFavPetModule or rawget(_G, "AutoFavPet")
            if type(mod) ~= "table" then return end
            if type(mod.SyncFromState) == "function" then
                pcall(mod.SyncFromState, mod)
            elseif type(mod.syncFromGlobals) == "function" then
                pcall(mod.syncFromGlobals, mod)
            end
        end

        if key == "favPet" then
            G.__GAG2_SYNC_AUTO_FAV_PET = syncModule
            _G.__GAG2_SYNC_AUTO_FAV_PET = syncModule
        else
            G.__GAG2_SYNC_AUTO_UNFAV_PET = syncModule
            _G.__GAG2_SYNC_AUTO_UNFAV_PET = syncModule
        end

        registerFlush(key, function()
            writeGlobals()
        end)

        writeGlobals()

        local body = ui:CreateSection(sectionTitle, false)
        local peekMode = (key == "unfavPet") and "unfav" or "fav"

        local function countReady()
            local mod = G.AutoFavPet or G.AutoFavPetModule or rawget(_G, "AutoFavPet")
            if type(mod) == "table" and type(mod.PeekCandidateCount) == "function" then
                local ok, n = pcall(mod.PeekCandidateCount, mod, peekMode)
                if ok and type(n) == "number" then return n end
            end
            if type(mod) == "table" and type(mod.CountCandidates) == "function" then
                local ok, n = pcall(mod.CountCandidates, mod, peekMode)
                if ok and type(n) == "number" then return n end
            end
            return 0
        end

        local _, statusTitle = ui:CreateRowLabel(
            body,
            "Ready: ...",
            nil,
            nil,
            "muted"
        )

        local function refreshStatus()
            if statusTitle and statusTitle.Parent then
                statusTitle.Text = ("Ready: %d pet"):format(countReady())
            end
        end

        task.defer(function()
            pcall(refreshStatus)
        end)

        task.spawn(function()
            while body and body.Parent do
                task.wait(5)
                pcall(refreshStatus)
            end
        end)

        ui:CreateRowDropdown(body, {
            label = "Select Pet",
            placeholder = "All Pet...",
            mode = "multi",
            getItems = buildPetItems,
            initial = petsSelected,
            onChanged = function(_, selectedMap)
                petsSelected = cleanSelectedMap(selectedMap)
                G[prefix .. "SELECTED"] = petsSelected
                _G[prefix .. "SELECTED"] = petsSelected
                ST.pets = mapToArray(petsSelected)
                patchAuto(key, { pets = ST.pets }, syncModule)
            end,
        })

        ui:CreateRowDropdown(body, {
            label = "Select Type",
            placeholder = "All Type...",
            mode = "multi",
            getItems = buildTypeItems,
            initial = typesSelected,
            onChanged = function(_, selectedMap)
                typesSelected = cleanSelectedMap(selectedMap)
                G[prefix .. "TYPES_SELECTED"] = typesSelected
                _G[prefix .. "TYPES_SELECTED"] = typesSelected
                ST.types = mapToArray(typesSelected)
                patchAuto(key, { types = ST.types }, syncModule)
            end,
        })

        ui:CreateRowDropdown(body, {
            label = "Select Size",
            placeholder = "All Size...",
            mode = "multi",
            getItems = buildSizeItems,
            initial = sizesSelected,
            onChanged = function(_, selectedMap)
                sizesSelected = cleanSelectedMap(selectedMap)
                G[prefix .. "SIZES_SELECTED"] = sizesSelected
                _G[prefix .. "SIZES_SELECTED"] = sizesSelected
                ST.sizes = mapToArray(sizesSelected)
                patchAuto(key, { sizes = ST.sizes }, syncModule)
            end,
        })

        local _, _, enableApi = ui:CreateRowToggle(
            body,
            toggleLabel,
            (ST.enabled == true),
            function(isOn)
                ST.enabled = (isOn == true)
                patchAuto(key, { enabled = ST.enabled }, syncModule)
            end
        )

        G[enableApiGlobal] = enableApi
        _G[enableApiGlobal] = enableApi

        registerFlush(key .. "_toggle", function()
            local on = toggleApiGet(enableApiGlobal)
            if on == nil then return end
            patchAutoOnly(key, { enabled = on })
        end)

        syncModule()
        return body
    end

    buildBlock("favPet", "Auto Fav Pet", "Enable Auto Fav Pet", "__GAG2_FAV_PET_ENABLE_API")
    buildBlock("unfavPet", "Auto Unfav Pet", "Enable Auto Unfav Pet", "__GAG2_UNFAV_PET_ENABLE_API")

    G.__GAG2_AUTO_FAV_PET_UI_DONE = true
    _G.__GAG2_AUTO_FAV_PET_UI_DONE = true
end

G.SectionAutoFavPet = M
_G.SectionAutoFavPet = M

return M
 end,             required = false },
    { key = "AutoSellStock",           name = "Auto Sell Stock",         factory = function() -- AutoSellStock.lua — Grow A Garden 2
-- Jual per tipe buah yang Fruit Stock multiplier >= minMult.
-- Match → soft-pause peers → unfav tipe match (opsional) → SellFruit → resume.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

M.ModuleVersion = "20260715a"

local LOOP_SEC       = 2.5
local STOCK_CACHE_SEC = 8
local SELL_GAP       = 0.04
local UNFAV_SETTLE   = 0.2
local DAILY_MULT_FALLBACK = 2.2

local busy = false
local running = false
