----------------------------------------------------------------
-- evaluate (tanpa pause)
----------------------------------------------------------------
-- Total backpack = fav + unfav (bukan PreviewSellAll yang exclude fav).
local bpTotalsCache = { at = 0, count = 0, value = 0 }
local BP_TOTALS_CACHE_SEC = 5

local function _backpackTotals(force)
    local now = os.clock()
    if not force and (now - bpTotalsCache.at) < BP_TOTALS_CACHE_SEC and bpTotalsCache.at > 0 then
        return bpTotalsCache.count, bpTotalsCache.value
    end

    local count = tonumber(LP:GetAttribute("FruitCount")) or 0
    local totalValue = 0
    local scanned = 0

    -- Prefer total yang sama dengan badge ESP backpack.
    local esp = G.EspFruitBackpack or _G.EspFruitBackpack
    if type(esp) == "table" and type(esp.ScanFruits) == "function" and type(esp.GetEntryPrice) == "function" then
        local ok, list = pcall(esp.ScanFruits, esp)
        if ok and type(list) == "table" then
            local seen = {}
            for _, e in ipairs(list) do
                if type(e) == "table" then
                    local id = tostring(e.id or "")
                    local key = id ~= "" and id or (tostring(e.name or "") .. ":" .. tostring(e.multi or 0))
                    if not seen[key] then
                        seen[key] = true
                        scanned += 1
                        local okp, p = pcall(esp.GetEntryPrice, esp, e, false)
                        p = (okp and tonumber(p)) or 0
                        if p > 0 then totalValue += p end
                    end
                end
            end
        end
    end

    if scanned <= 0 or totalValue <= 0 then
        totalValue = 0
        scanned = 0
        _eachFruitTool(function(tool)
            scanned += 1
            totalValue += _toolPrice(tool)
        end)
    end

    if count <= 0 then
        count = scanned
    end
    bpTotalsCache.at = now
    bpTotalsCache.count = count
    bpTotalsCache.value = totalValue
    return count, totalValue
end

function M.Evaluate(opts)
    opts = type(opts) == "table" and opts or {}
    local cfg = M.GetConfig()
    local out = {
        ready = false,
        reason = "disabled",
        estimate = 0,
        matchCount = 0,
        matchNames = {},
        matchTypes = {},
        bpTypes = {},
        matchIds = {},
        backpackCount = 0,
        backpackValue = 0,
        minMult = tonumber(cfg.minMult) or 1,
    }
    if cfg.enabled ~= true and opts.ignoreEnabled ~= true then
        return out
    end

    local entries = _requestStock(opts.forceStock == true)
    local bpCount, bpValue = _backpackTotals(opts.forceTotals == true)
    out.backpackCount = bpCount
    out.backpackValue = bpValue

    local minMult = tonumber(cfg.minMult) or 1
    out.minMult = minMult

    -- Scan semua tipe di BP (untuk status), + match yang lolos minMult.
    local nameSet = {}
    local typeMap = {} -- match ≥ minMult
    local bpMap = {}   -- semua tipe di backpack + stock X
    local ids = {}
    local estimate = 0
    local matchCount = 0
    local seenId = {}

    _eachFruitTool(function(tool)
        local name = _fruitName(tool)
        if name == "" then return end
        local mult = _multForName(entries, name)
        local id = _fruitId(tool)
        if id ~= "" and seenId[id] then return end
        if id ~= "" then seenId[id] = true end

        local bp = bpMap[name]
        if not bp then
            bp = { name = name, mult = mult, count = 0 }
            bpMap[name] = bp
        end
        bp.count += 1
        if mult > (tonumber(bp.mult) or 0) then
            bp.mult = mult
        end

        if mult < minMult then return end
        local fav = _isFavorited(tool)
        if fav and cfg.autoUnfav ~= true then
            return
        end
        matchCount += 1
        nameSet[name] = true
        if id ~= "" then
            ids[#ids + 1] = id
        end
        estimate += _toolStockedPrice(tool, mult)
        local row = typeMap[name]
        if not row then
            row = { name = name, mult = mult, count = 0 }
            typeMap[name] = row
        end
        row.count += 1
        if mult > (tonumber(row.mult) or 0) then
            row.mult = mult
        end
    end)

    local function sortTypes(map)
        local list = {}
        for _, row in pairs(map) do
            list[#list + 1] = row
        end
        table.sort(list, function(a, b)
            local ma, mb = tonumber(a.mult) or 0, tonumber(b.mult) or 0
            if ma ~= mb then return ma > mb end
            return tostring(a.name) < tostring(b.name)
        end)
        return list
    end

    local matchTypes = sortTypes(typeMap)
    local bpTypes = sortTypes(bpMap)
    local bestMult = 0
    if bpTypes[1] then
        bestMult = tonumber(bpTypes[1].mult) or 0
    end

    out.matchCount = matchCount
    out.matchNames = nameSet
    out.matchTypes = matchTypes
    out.bpTypes = bpTypes
    out.bpTypeCount = #bpTypes
    out.bestMult = bestMult
    out.matchIds = ids
    out.estimate = estimate
    do
        local seen, n = {}, 0
        if type(entries) == "table" then
            for k in pairs(entries) do
                if type(k) == "string" then
                    local lk = string.lower(k)
                    if not seen[lk] then
                        seen[lk] = true
                        n += 1
                    end
                end
            end
        end
        out.stockEntryCount = n
    end

    local minN = math.max(1, math.floor(tonumber(cfg.minBackpackCount) or 1))
    local minV = math.max(0, tonumber(cfg.minTotalValue) or 0)
    if bpCount < minN then
        out.reason = "count"
        return out
    end
    if minV > 0 and bpValue < minV then
        out.reason = "value"
        return out
    end

    if matchCount <= 0 then
        out.reason = "no_match"
        return out
    end

    out.ready = true
    out.reason = "ok"
    return out
end

M.evaluate = M.Evaluate

local function _dailyEstimateFallback()
    local daily = _autoDaily()
    if type(daily) == "table" and type(daily.Evaluate) == "function" then
        local ok, probe = pcall(daily.Evaluate, daily, { ignoreEnabled = false })
        if ok and type(probe) == "table" then
            return probe
        end
    end
    return nil
end

local function _shouldYieldToDaily(stockEst)
    local probe = _dailyEstimateFallback()
    if not probe or probe.ready ~= true then return false end
    local dEst = tonumber(probe.estimate) or 0
    -- Prefer Daily on tie (1x / ~12h opportunity).
    return dEst >= (tonumber(stockEst) or 0)
end

----------------------------------------------------------------
-- sell
----------------------------------------------------------------
local function _sellMatched(ids)
    local sold = 0
    local favorited = 0
    for i, id in ipairs(ids) do
        if id and id ~= "" then
            local ok, res = _npcFire("SellFruit", id)
            local success = ok and (
                res == true
                or (type(res) == "table" and (res.Success == true or res.success == true))
                or type(res) == "number"
            )
            if success then
                sold += 1
            elseif type(res) == "table" and (res.Reason == "Favorited" or res.reason == "Favorited") then
                favorited += 1
            end
            if i < #ids then
                task.wait(SELL_GAP)
            end
        end
    end
    return sold, favorited
end

function M.RunOnce(opts)
    opts = type(opts) == "table" and opts or {}
    if busy or G.__GAG2_BOOST_SELL_BUSY == true then
        return false, "busy"
    end
    if not M.IsEnabled() then
        return false, "disabled"
    end

    local probe = M.Evaluate(opts)
    if not probe.ready then
        _setStatus("Stock wait: " .. tostring(probe.reason))
        return false, probe.reason, probe
    end

    if _shouldYieldToDaily(probe.estimate) then
        _setStatus("YIELD Daily (lebih besar)")
        return false, "yield_daily", probe
    end

    busy = true
    G.__GAG2_BOOST_SELL_BUSY = true
    _G.__GAG2_BOOST_SELL_BUSY = true
    _setStatus(string.format("Stock sell %d fruits...", probe.matchCount))

    local heldOk, sold, favBlocked, detail = M.WithPeerHold(function()
        local cfg = M.GetConfig()
        if cfg.autoUnfav == true then
            local af = _autoFav()
            if type(af) == "table" then
                -- Jangan pcall(fn, self, ...) — UnfavBy* signature tanpa self
                if type(af.UnfavByFruitIds) == "function" and type(probe.matchIds) == "table" and #probe.matchIds > 0 then
                    pcall(function()
                        af.UnfavByFruitIds(probe.matchIds, { fireDelay = 0.03 })
                    end)
                elseif type(af.UnfavByFruitNames) == "function" then
                    pcall(function()
                        af.UnfavByFruitNames(probe.matchNames, { fireDelay = 0.03 })
                    end)
                end
                task.wait(UNFAV_SETTLE)
            end
        end
        local again = M.Evaluate({ ignoreEnabled = true, forceStock = false, forceTotals = true })
        local ids = again.matchIds
        if type(ids) ~= "table" or #ids == 0 then
            ids = probe.matchIds
        end
        local n, favN = _sellMatched(ids)
        return n, favN, again
    end, "stock")

    busy = false
    G.__GAG2_BOOST_SELL_BUSY = false
    _G.__GAG2_BOOST_SELL_BUSY = false

    if not heldOk then
        _setStatus("Stock error: " .. tostring(sold))
        return false, sold
    end

    local nSold = tonumber(sold) or 0
    local nFav = tonumber(favBlocked) or 0
    if nSold > 0 then
        _setStatus(string.format("Stock sold %d", nSold))
        return true, { sold = nSold, estimate = probe.estimate }, detail
    end
    if nFav > 0 then
        _setStatus(string.format("Stock blocked fav %d — enable Auto unfav", nFav))
        return false, "favorited", detail
    end
    _setStatus("Stock sell failed / empty")
    return false, "sell_failed", detail
end

M.runOnce = M.RunOnce

----------------------------------------------------------------
-- loop
----------------------------------------------------------------
local function _loop(myId)
    while running and loopId == myId do
        if M.IsEnabled() and not busy and G.__GAG2_BOOST_SELL_BUSY ~= true then
            pcall(M.RunOnce)
        end
        task.wait(LOOP_SEC)
    end
end

function M.Start()
    M.SetEnabled(true)
    if running then return true end
    running = true
    loopId += 1
    local myId = loopId
    task.spawn(function()
        _loop(myId)
    end)
    _setStatus("Stock ON")
    return true
end

function M.Stop()
    running = false
    M.SetEnabled(false)
    _setStatus("Stock OFF")
end

M.start = M.Start
M.stop = M.Stop

function M.IsRunning()
    return running == true
end

M.isRunning = M.IsRunning

G.AutoSellStock = M
G.AutoSellStockModule = M
_G.AutoSellStock = M
_G.AutoSellStockModule = M

return M
 end,                   required = false },
    { key = "SectionAutoSellStock",    name = "Section Auto Sell Stock", factory = function() -- section_auto_sell_stock.lua — UI Auto Sell Stock Price (tab Auto)

local G = (getgenv and getgenv()) or _G
local M = {}

-- Suffix panjang dulu (qi sebelum q, am sebelum m).
local VALUE_SUFFIXES = {
    { "juta", 1e6 }, { "jt", 1e6 },
    { "ribu", 1e3 }, { "rb", 1e3 },
    { "dc", 1e33 }, { "no", 1e30 }, { "oc", 1e27 },
    { "sp", 1e24 }, { "sx", 1e21 },
    { "qi", 1e18 }, { "qn", 1e18 },
    { "qa", 1e15 }, { "qd", 1e15 },
    { "t", 1e12 }, { "b", 1e9 }, { "m", 1e6 }, { "k", 1e3 },
}

local function abbrev(n)
    n = tonumber(n) or 0
    if n <= 0 then return "0" end
    local units = {
        { 1e33, "Dc" }, { 1e30, "No" }, { 1e27, "Oc" },
        { 1e24, "Sp" }, { 1e21, "Sx" },
        { 1e18, "Qi" }, { 1e15, "Qa" },
        { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" },
    }
    for _, u in ipairs(units) do
        if n >= u[1] then
            local v = n / u[1]
            if math.abs(v - math.floor(v + 0.5)) < 1e-6 then
                return string.format("%d%s", math.floor(v + 0.5), u[2])
            end
            return string.format("%.2f%s", v, u[2]):gsub("%.?0+([A-Za-z])", "%1")
        end
    end
    return tostring(math.floor(n + 0.5))
end

-- "1b", "1 qi", "1.5Qa", "1am" (huruf 2+: aa=1e63, ab=1e66, ... am=1e99)
local function parseScaledValue(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", ".")
    if txt == "" then return nil end
    local sign = 1
    if txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end

    for _, pair in ipairs(VALUE_SUFFIXES) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local numPart = txt:sub(1, -#suf - 1)
            local n = tonumber(numPart)
            if n then return n * mult * sign end
        end
    end

    -- alphabetical 2–3 huruf (aa, am, aaa, ...), jangan tabrak k/m/b/t
    local numPart, letters = txt:match("^([%d%.]+)([a-z]+)$")
    if numPart and letters and #letters >= 2 then
        local n = tonumber(numPart)
        if n then
            local idx = 0
            for i = 1, #letters do
                local c = letters:byte(i) - 96
                if c < 1 or c > 26 then
                    idx = nil
                    break
                end
                idx = idx * 26 + (c - 1)
            end
            if idx ~= nil then
                -- aa => idx 0 => 1e63; each step ×1000
                local exp = 63 + idx * 3
                return n * (10 ^ exp) * sign
            end
        end
    end

    local n = tonumber(txt)
    if n then return n * sign end
    return nil
end

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto = ctx.getAuto
    local patchAuto = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local registerFlush = ctx.registerFlush

    local ST = getAuto("sellStock")
    if type(ST) ~= "table" then ST = {} end
    if ST.minMult == nil then ST.minMult = 1 end
    if ST.minBackpackCount == nil then ST.minBackpackCount = 1 end
    if ST.minTotalValue == nil then ST.minTotalValue = 0 end
    ST.enabled = (ST.enabled == true)
    ST.autoUnfav = (ST.autoUnfav == true)

    local function snapshot()
        local api = G.__GAG2_SELL_STOCK_ENABLE_API or rawget(_G, "__GAG2_SELL_STOCK_ENABLE_API")
        if type(api) == "table" and type(api.get) == "function" then
            ST.enabled = (api.get() == true)
        end
        return {
            enabled = (ST.enabled == true),
            minMult = tonumber(ST.minMult) or 1,
            minBackpackCount = math.max(1, math.floor(tonumber(ST.minBackpackCount) or 1)),
            minTotalValue = math.max(0, tonumber(ST.minTotalValue) or 0),
            autoUnfav = (ST.autoUnfav == true),
        }
    end

    local function writeGlobals()
        local snap = snapshot()
        for k, v in pairs(snap) do ST[k] = v end
        G.AUTO_SELL_STOCK = snap
        _G.AUTO_SELL_STOCK = snap
        if type(patchAutoOnly) == "function" then
            patchAutoOnly("sellStock", snap)
        end
    end

    local function syncModule()
        writeGlobals()
        local snap = snapshot()
        local mod = G.AutoSellStock or G.AutoSellStockModule or rawget(_G, "AutoSellStock")
        if type(mod) == "table" then
            if type(mod.SetConfig) == "function" then
                pcall(mod.SetConfig, mod, snap)
            elseif type(mod.setConfig) == "function" then
                pcall(mod.setConfig, mod, snap)
            end
            if snap.enabled then
                if type(mod.Start) == "function" then pcall(mod.Start, mod) end
            else
                if type(mod.Stop) == "function" then pcall(mod.Stop, mod) end
            end
        end
    end

    local function persist()
        writeGlobals()
        if type(patchAuto) == "function" then
            patchAuto("sellStock", snapshot(), syncModule)
        else
            syncModule()
        end
    end

    G.__GAG2_PUSH_SELL_STOCK = writeGlobals
    _G.__GAG2_PUSH_SELL_STOCK = writeGlobals
    G.__GAG2_SYNC_AUTO_SELL_STOCK = syncModule
    _G.__GAG2_SYNC_AUTO_SELL_STOCK = syncModule

    if type(registerFlush) == "function" then
        registerFlush("sellStock", writeGlobals)
    end

    writeGlobals()

    local function formatMult(m)
        m = tonumber(m) or 1
        local rounded = math.floor(m * 100 + 0.5) / 100
        if rounded == math.floor(rounded) then
            return string.format("X%d", rounded)
        end
        local s = string.format("X%.2f", rounded):gsub("0+$", ""):gsub("%.$", "")
        return s
    end

    local function matchTypesShort(matchTypes, limit)
        limit = limit or 5
        if type(matchTypes) ~= "table" or #matchTypes == 0 then return "-" end
        local parts = {}
        for i = 1, math.min(limit, #matchTypes) do
            local row = matchTypes[i]
            local name = tostring(row.name or "?")
            local n = tonumber(row.count) or 0
            local x = formatMult(row.mult)
            if n > 1 then
                parts[#parts + 1] = string.format("%s %s×%d", name, x, n)
            else
                parts[#parts + 1] = string.format("%s %s", name, x)
            end
        end
        if #matchTypes > limit then
            parts[#parts + 1] = "+" .. tostring(#matchTypes - limit)
        end
        return table.concat(parts, ", ")
    end

    local function reasonLabel(reason)
        reason = tostring(reason or "")
        if reason == "ok" then return "READY"
        elseif reason == "disabled" then return "OFF"
        elseif reason == "count" then return "WAIT COUNT"
        elseif reason == "value" then return "WAIT VALUE"
        elseif reason == "no_match" then return "NO MATCH"
        end
        return reason ~= "" and string.upper(reason) or "?"
    end

    local function evalStock()
        local mod = G.AutoSellStock or G.AutoSellStockModule or rawget(_G, "AutoSellStock")
        if type(mod) ~= "table" or type(mod.Evaluate) ~= "function" then return nil end
        local ok, probe = pcall(mod.Evaluate, mod, { ignoreEnabled = true })
        if ok and type(probe) == "table" then
            G.__GAG2_SELL_STOCK_PROBE = probe
            _G.__GAG2_SELL_STOCK_PROBE = probe
            return probe
        end
        return nil
    end

    local function peerDailyProbe()
        -- Jangan Evaluate Daily di sini (bikin UI tab Auto nunggu). Pakai cache.
        local cached = G.__GAG2_SELL_DAILY_PROBE or rawget(_G, "__GAG2_SELL_DAILY_PROBE")
        if type(cached) == "table" then return cached end
        return nil
    end

    local function statusText()
        local minMult = tonumber(ST.minMult) or 1
        local enabled = (ST.enabled == true)

        local probe = evalStock()
        local bp = probe and tonumber(probe.backpackCount) or (tonumber(game:GetService("Players").LocalPlayer:GetAttribute("FruitCount")) or 0)
        local bpVal = probe and tonumber(probe.backpackValue) or 0
        local reason = probe and probe.reason or "…"
        local state = enabled and reasonLabel(reason) or "OFF"
        local est = probe and tonumber(probe.estimate) or 0
        local typeList = probe and probe.matchTypes
        local typeN = (type(typeList) == "table" and #typeList) or 0
        local bpList = probe and probe.bpTypes
        local bpTypeN = (type(bpList) == "table" and #bpList) or 0
        local bestMult = probe and tonumber(probe.bestMult) or 0
        local stockN = probe and tonumber(probe.stockEntryCount) or 0

        local vs = ""
        local daily = peerDailyProbe()
        local dailyOn = false
        do
            local dmod = G.AutoSellDaily or rawget(_G, "AutoSellDaily")
            dailyOn = type(dmod) == "table" and type(dmod.IsEnabled) == "function" and dmod.IsEnabled(dmod) == true
        end
        if dailyOn and daily and probe and probe.ready == true and daily.ready == true then
            local dEst = tonumber(daily.estimate) or 0
            if dEst > est then
                vs = string.format(" · Daily better (%s)", abbrev(dEst))
            else
                vs = string.format(" · ahead of Daily (%s)", abbrev(dEst))
            end
        end

        local line1 = string.format("%s · ≥X%.2g", state, minMult)
        do
            local mod = G.AutoSellStock or rawget(_G, "AutoSellStock")
            if enabled and type(mod) == "table" and type(mod.GetStatus) == "function" then
                local okS, st = pcall(mod.GetStatus, mod)
                if okS and type(st) == "string" and st ~= "" then
                    local low = string.lower(st)
                    if low:find("yield", 1, true) or low:find("sold", 1, true)
                        or low:find("sell ", 1, true) or low:find("blocked", 1, true)
                        or low:find("error", 1, true) or low:find("failed", 1, true) then
                        line1 = st
                    end
                end
            end
        end
        local line2
        if typeN > 0 then
            line2 = string.format("BP %d · %s · %s · est %s%s",
                bp, abbrev(bpVal), matchTypesShort(typeList, 5), abbrev(est), vs)
        elseif bpTypeN > 0 then
            line2 = string.format("BP %d · %s · best %s · %s%s",
                bp, abbrev(bpVal), formatMult(bestMult), matchTypesShort(bpList, 5), vs)
        else
            line2 = string.format("BP %d · %s · waiting stock data (%d)%s",
                bp, abbrev(bpVal), stockN, vs)
        end
        return line1, line2
    end

    local body = ui:CreateSection("Auto Sell Stock Price", false)

    local function bindStatusRow(titleLbl)
        if not titleLbl then return end
        titleLbl.TextTruncate = Enum.TextTruncate.AtEnd
        if titleLbl.Parent then
            for _, ch in ipairs(titleLbl.Parent:GetChildren()) do
                if ch:IsA("TextLabel") and ch ~= titleLbl then
                    ch.TextTruncate = Enum.TextTruncate.AtEnd
                end
            end
        end
    end

    local _, statusTitle = ui:CreateRowLabel(body, "…", "Loading stock status…", nil, "accent")
    bindStatusRow(statusTitle)

    local function setStatusLines(lineA, lineB)
        if not (statusTitle and statusTitle.Parent) then return end
        statusTitle.Text = lineA or ""
        for _, ch in ipairs(statusTitle.Parent:GetChildren()) do
            if ch:IsA("TextLabel") and ch ~= statusTitle then
                ch.Text = lineB or ""
                break
            end
        end
    end

    local statusBusy = false
    local function refreshStatus()
        if statusBusy then return end
        statusBusy = true
        task.spawn(function()
            local ok, l1, l2 = pcall(function()
                return statusText()
            end)
            if ok then
                setStatusLines(l1, l2)
            end
            statusBusy = false
        end)
    end

    local function scheduleStatus()
        task.defer(refreshStatus)
    end

    ui:CreateRowInput(
        body,
        "Min stock (X)",
        tostring(tonumber(ST.minMult) or 1),
        function(txt)
            local n = tonumber(txt)
            if n == nil or n < 0 then return end
            ST.minMult = n
            persist()
            scheduleStatus()
        end,
        false
    )

    ui:CreateRowInput(
        body,
        "Min backpack count",
        tostring(tonumber(ST.minBackpackCount) or 1),
        function(txt)
            local n = tonumber(txt)
            if n == nil or n < 1 then return end
            ST.minBackpackCount = math.floor(n)
            persist()
            scheduleStatus()
        end,
        false
    )

    local _, setMinValue = ui:CreateRowInput(
        body,
        "Min backpack value (eg 1m 1b)",
        abbrev(tonumber(ST.minTotalValue) or 0),
        function(txt)
            local n = parseScaledValue(txt)
            if n == nil or n < 0 then return end
            ST.minTotalValue = n
            if type(setMinValue) == "function" then
                setMinValue(abbrev(n))
            end
            persist()
            scheduleStatus()
        end,
        false
    )

    ui:CreateRowToggle(
        body,
        "Auto unfav on match",
        (ST.autoUnfav == true),
        function(isOn)
            ST.autoUnfav = (isOn == true)
            persist()
            scheduleStatus()
        end
    )

    local _, _, enableApi = ui:CreateRowToggle(
        body,
        "Enable",
        (ST.enabled == true),
        function(isOn)
            ST.enabled = (isOn == true)
            persist()
            scheduleStatus()
        end
    )
    G.__GAG2_SELL_STOCK_ENABLE_API = enableApi
    _G.__GAG2_SELL_STOCK_ENABLE_API = enableApi

    task.spawn(function()
        while body and body.Parent do
            task.wait(5)
            pcall(refreshStatus)
        end
    end)

    task.defer(function()
        syncModule()
        scheduleStatus()
    end)
end

G.SectionAutoSellStock = M
_G.SectionAutoSellStock = M

return M
 end,          required = false },
    { key = "AutoSellDaily",           name = "Auto Sell Daily",         factory = function() -- AutoSellDaily.lua — Grow A Garden 2
-- Daily Deal Steven (~base x 2.2, 1x / ~12h per account).
-- Match → soft-pause peers → unfav semua (opsional) → UseDailyDealAll → resume.

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

M.ModuleVersion = "20260714c"

local LOOP_SEC     = 4.0
local UNFAV_SETTLE = 0.25
local DAILY_MULT_FALLBACK = 2.2
local DEAL_CACHE_SEC = 3.0

local busy = false
local running = false
local loopId = 0
local lastStatus = ""
local dealCache = { at = 0, data = nil }

local Networking
pcall(function()
    Networking = require(ReplicatedStorage.SharedModules.Networking)
end)

local FruitProxyUtil
pcall(function()
    FruitProxyUtil = require(ReplicatedStorage.SharedModules.FruitProxyUtil)
end)

local SellFlags
pcall(function()
    local sm = ReplicatedStorage:FindFirstChild("SharedModules")
    local flags = sm and sm:FindFirstChild("Flags")
    local inst = flags and flags:FindFirstChild("SellFlags") or (sm and sm:FindFirstChild("SellFlags"))
    if inst then SellFlags = require(inst) end
end)

local function _defaults()
    return {
        enabled          = false,
        minBackpackCount = 1,
        minTotalValue    = 0,
        autoUnfav        = false,
    }
end

local function _getMainCfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) ~= "table" then return nil end
    MAIN.auto = MAIN.auto or {}
    if type(MAIN.auto.sellDaily) ~= "table" then
        MAIN.auto.sellDaily = _defaults()
    end
    return MAIN.auto.sellDaily
end

local function _publish(cfg)
    G.AUTO_SELL_DAILY = cfg
    _G.AUTO_SELL_DAILY = cfg
end

local function _setStatus(msg)
    lastStatus = tostring(msg or "")
    G.AUTO_SELL_DAILY_STATUS = lastStatus
    _G.AUTO_SELL_DAILY_STATUS = lastStatus
end

local function _autoSellFruit()
    -- Runtime name = AutoSellFruit (lihat AutoGift / main_ui). Jangan ambil Stock/Daily/Pet.
    local as = G.AutoSellFruit or rawget(_G, "AutoSellFruit")
    if type(as) ~= "table" then
        as = G.AutoSell or G.AutoSellModule
            or rawget(_G, "AutoSell") or rawget(_G, "AutoSellModule")
    end
    if type(as) ~= "table" then return nil end
    if as == M then return nil end
    if as == G.AutoSellStock or as == G.AutoSellStockModule then return nil end
    if as == G.AutoSellDaily or as == G.AutoSellDailyModule then return nil end
    if as == G.AutoSellPet or as == G.AutoSellPetModule then return nil end
    if type(as.PausePeers) ~= "function" and type(as.Pause) ~= "function" then
        return nil
    end
    return as
end

local function _autoFav()
    return G.AutoFav or G.AutoFavModule or _G.AutoFav or _G.AutoFavModule
end

local function _autoStock()
    return G.AutoSellStock or G.AutoSellStockModule or _G.AutoSellStock
end

local function _fsv()
    return G.FruitSellValue or _G.FruitSellValue
end

local function _net()
    if type(Networking) == "table" then return Networking end
    pcall(function()
        Networking = require(ReplicatedStorage.SharedModules.Networking)
    end)
    return Networking
end

local function _npcFire(name, ...)
    local net = _net()
    local pkt = net and net.NPCS and net.NPCS[name]
    if not pkt or type(pkt.Fire) ~= "function" then
        return false, "missing_" .. tostring(name)
    end
    local args = table.pack(...)
    local results = table.pack(pcall(function()
        if args.n > 0 then
            return pkt:Fire(table.unpack(args, 1, args.n))
        end
        return pkt:Fire()
    end))
    if not results[1] then
        return false, results[2]
    end
    return true, results[2], results[3], results[4]
end

----------------------------------------------------------------
local function _fruitId(tool)
    if not tool or type(tool.GetAttribute) ~= "function" then return "" end
    return tostring(tool:GetAttribute("Id") or tool:GetAttribute("id")
        or tool:GetAttribute("UUID") or tool:GetAttribute("Uuid")
        or tool:GetAttribute("FruitId") or tool:GetAttribute("fruitId")
        or tool:GetAttribute("c") or "")
end

local function _isFavorited(tool)
    if not tool or type(tool.GetAttribute) ~= "function" then return false end
    local function truthy(v)
        return v == true or v == 1 or v == "true" or v == "1"
    end
    return truthy(tool:GetAttribute("IsFavorite"))
        or truthy(tool:GetAttribute("Favorite"))
        or truthy(tool:GetAttribute("Favorited"))
end

local function _normName(s)
    return string.lower((tostring(s or ""):gsub("%s+", "")))
end

local function _isNonFruitName(name)
    local n = _normName(name)
    if n == "" then return false end
    if n:find("seed", 1, true) then return true end
    if n == "shovel" or n == "wateringcan" or n == "build" then return true end
    return n:find("sprinkler", 1, true) ~= nil
        or n:find("sprink", 1, true) ~= nil
        or n:find("gear", 1, true) ~= nil
        or n:find("watering", 1, true) ~= nil
        or n:find("fertilizer", 1, true) ~= nil
        or n:find("egg", 1, true) ~= nil
        or n:find("trap", 1, true) ~= nil
end

local function _isFruitTool(inst)
    if not inst or not inst.Parent then return false end
    if inst:GetAttribute("SeedTool") or inst:GetAttribute("Pet") then return false end
    if inst:GetAttribute("PottedPlant") == true then return false end
    local cat = tostring(inst:GetAttribute("MainCategory") or "")
    if cat == "Seed" or cat == "Gear" or cat == "Egg" or cat == "Tool" or cat == "Pet" then
        return false
    end
    if FruitProxyUtil and type(FruitProxyUtil.IsFruitInstance) == "function" then
        local ok, yes = pcall(FruitProxyUtil.IsFruitInstance, inst)
        if ok and yes then
            local nm = tostring(inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") or inst.Name or "")
            if _isNonFruitName(nm) then return false end
            return true
        end
        if ok and yes == false then return false end
    end
    if inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") then
        local nm = tostring(inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") or "")
        if _isNonFruitName(nm) then return false end
        return true
    end
    if inst:GetAttribute("FruitProxy") == true then return true end
    local hf = inst:GetAttribute("HarvestedFruit")
    if hf == true or (type(hf) == "string" and hf ~= "") then return true end
    if inst:GetAttribute("Id") and inst:GetAttribute("Weight") then return true end
    return false
end

local function _eachFruitTool(fn)
    if type(fn) ~= "function" then return end
    local seen = {}
    local function scan(root)
        if not root then return end
        for _, inst in ipairs(root:GetChildren()) do
            if not seen[inst] and _isFruitTool(inst) then
                seen[inst] = true
                fn(inst)
            end
        end
    end
    scan(LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack"))
    scan(LP.Character)
end

local function _espPriceMode()
    local fsv = _fsv()
    if fsv and type(fsv.getEspPriceMode) == "function" then
        local ok, m = pcall(fsv.getEspPriceMode)
        if ok and type(m) == "string" and m ~= "" then
            return (string.lower(m) == "stock") and "stock" or "base"
        end
    end
    local mode = G.FRUIT_BACKPACK_ESP_PRICE_MODE or rawget(_G, "FRUIT_BACKPACK_ESP_PRICE_MODE")
    return (tostring(mode or ""):lower() == "stock") and "stock" or "base"
end

-- Harga per buah = jalur yang sama dengan EspFruitBackpack.
local function _toolPrice(tool)
    if not tool then return 0 end
    local fsv = _fsv()
    local name = tostring(tool:GetAttribute("FruitName") or tool:GetAttribute("Fruit") or "")
    if name == "" and fsv and type(fsv.resolveSeedName) == "function" then
        local ok, n = pcall(fsv.resolveSeedName, tool)
        if ok and n ~= nil then name = tostring(n) end
    end
    local id = _fruitId(tool)
    local bid = tonumber(tool:GetAttribute("BidPrice")) or 0
    local multi = 0
    if fsv and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, tool)
        if ok and type(m) == "number" then multi = m end
    end
    if multi <= 0 then
        multi = tonumber(tool:GetAttribute("SizeMultiplier") or tool:GetAttribute("SizeMulti")) or 0
    end
    local mut = tool:GetAttribute("Mutation")
    local decay = tool:GetAttribute("DecayAlpha")
    local mode = _espPriceMode()

    if fsv and type(fsv.getBackpackEspPrice) == "function" and name ~= "" and multi > 0 then
        local ok, p = pcall(fsv.getBackpackEspPrice, name, multi, mut, decay, mode,
            id ~= "" and id or nil, bid)
        if ok and type(p) == "number" and p > 0 then return p end
    end

    local esp = G.EspFruitBackpack or _G.EspFruitBackpack
    if type(esp) == "table" and type(esp.GetEntryPrice) == "function" then
        local ok, p = pcall(esp.GetEntryPrice, esp, {
            id = id, name = name, multi = multi, mut = mut, decay = decay, bidPrice = bid, tool = tool,
        }, false)
        if ok and type(p) == "number" and p > 0 then return p end
    end

    if fsv and type(fsv.fromFruit) == "function" then
        local ok, p = pcall(fsv.fromFruit, tool, LP)
        if ok and type(p) == "number" and p > 0 then return p end
    end
    return bid
end

local function _dailyDealPrice(baseValue)
    baseValue = tonumber(baseValue) or 0
    if baseValue <= 0 then return 0 end
    if type(SellFlags) ~= "table" then
        pcall(function()
            local sm = ReplicatedStorage:FindFirstChild("SharedModules")
            local flags = sm and sm:FindFirstChild("Flags")
            local inst = flags and flags:FindFirstChild("SellFlags") or (sm and sm:FindFirstChild("SellFlags"))
            if inst then SellFlags = require(inst) end
        end)
    end
    if type(SellFlags) == "table" and type(SellFlags.DailyDealPrice) == "function" then
        local ok, v = pcall(SellFlags.DailyDealPrice, baseValue)
        if ok and type(v) == "number" and v > 0 then return v end
    end
    local mult = DAILY_MULT_FALLBACK
    if type(SellFlags) == "table" and type(SellFlags.DailyDealMultiplier) == "table"
        and type(SellFlags.DailyDealMultiplier.Get) == "function" then
        local ok, m = pcall(SellFlags.DailyDealMultiplier.Get, SellFlags.DailyDealMultiplier)
        if ok and type(m) == "number" and m > 0 then mult = m end
    end
    return math.floor(baseValue * mult + 0.5)
end

----------------------------------------------------------------
----------------------------------------------------------------
-- Soft-pause AutoSellFruit + AutoFav (toggle/state tidak diubah).
-- Prefer API resmi AutoSellFruit.PausePeers / WithPeerHold.
----------------------------------------------------------------
function M.HoldPeers(reason)
    reason = reason or "daily"
    local as = _autoSellFruit()
    if type(as) == "table" and type(as.PausePeers) == "function" then
        -- Panggil tanpa self palsu: PausePeers(reason), bukan PausePeers(module, reason)
        local ok = pcall(function()
            as.PausePeers(reason)
        end)
        return ok == true
    end
    if type(as) == "table" and type(as.Pause) == "function" then
        pcall(function()
            as.Pause(reason)
        end)
    end
    local af = _autoFav()
    if type(af) == "table" and type(af.Pause) == "function" then
        pcall(function()
            af.Pause(reason)
        end)
    end
    return true
end

function M.ReleasePeers()
    local as = _autoSellFruit()
    if type(as) == "table" and type(as.ResumePeers) == "function" then
        local ok = pcall(function()
            as.ResumePeers()
        end)
        return ok == true
    end
    local af = _autoFav()
    if type(af) == "table" and type(af.Resume) == "function" then
        pcall(function()
            af.Resume()
        end)
    end
    if type(as) == "table" and type(as.Resume) == "function" then
        pcall(function()
            as.Resume()
        end)
    end
    return true
end

function M.WithPeerHold(fn, reason, idleTimeout)
    if type(fn) ~= "function" then
        return false, "bad_fn"
    end
    reason = reason or "daily"
    idleTimeout = idleTimeout or 15

    -- Satu pintu resmi: pause sell+fav → wait idle → fn → resume
    local as = _autoSellFruit()
    if type(as) == "table" and type(as.WithPeerHold) == "function" then
        local okCall, heldOk, a, b, c = pcall(function()
            return as.WithPeerHold(fn, reason, idleTimeout)
        end)
        if okCall then
            return heldOk, a, b, c
        end
        return false, heldOk
    end

    M.HoldPeers(reason)
    if type(as) == "table" and type(as.WaitIdle) == "function" then
        pcall(function()
            as.WaitIdle(idleTimeout)
        end)
    else
        task.wait(0.15)
    end
    local ok, a, b, c = pcall(fn)
    M.ReleasePeers()
    if not ok then
        return false, a
    end
    return true, a, b, c
end

M.holdPeers = M.HoldPeers
M.releasePeers = M.ReleasePeers
M.withPeerHold = M.WithPeerHold

----------------------------------------------------------------
function M.GetConfig()
    local cfg = _getMainCfg()
    return type(cfg) == "table" and cfg or _defaults()
end

function M.SetConfig(cfg)
    if type(cfg) ~= "table" then return M.GetConfig() end
    local cur = _getMainCfg()
    if not cur then return cfg end
    if cfg.enabled ~= nil then cur.enabled = (cfg.enabled == true) end
    if cfg.minBackpackCount ~= nil then
        cur.minBackpackCount = math.max(1, math.floor(tonumber(cfg.minBackpackCount) or 1))
    end
    if cfg.minTotalValue ~= nil then
        cur.minTotalValue = math.max(0, tonumber(cfg.minTotalValue) or 0)
    end
    if cfg.autoUnfav ~= nil then cur.autoUnfav = (cfg.autoUnfav == true) end
    _publish(cur)
    return cur
end

M.setConfig = M.SetConfig
M.getConfig = M.GetConfig

function M.SetEnabled(on)
    return M.SetConfig({ enabled = on == true })
end

M.setEnabled = M.SetEnabled

function M.IsEnabled()
    return M.GetConfig().enabled == true
end

M.isEnabled = M.IsEnabled

function M.IsBusy()
    return busy == true or G.__GAG2_BOOST_SELL_BUSY == true
end

M.isBusy = M.IsBusy

function M.SyncFromState()
    local cfg = M.GetConfig()
    _publish(cfg)
    if cfg.enabled then
        M.Start()
    else
        M.Stop()
    end
    return cfg
end

M.syncFromState = M.SyncFromState

function M.GetStatus()
    return lastStatus
end

----------------------------------------------------------------
local function _checkDeal(force)
    local now = os.clock()
    if not force and dealCache.data and (now - dealCache.at) < DEAL_CACHE_SEC then
        return dealCache.data
    end
    local ok, res = _npcFire("CheckDailyDeal")
    if ok and type(res) == "table" then
        dealCache.data = res
        dealCache.at = now
        return res
    end
    return dealCache.data
end

local function _previewSell()
    local ok, a = _npcFire("PreviewSellAll")
    if ok and type(a) == "table" then return a end
    return nil
end

-- Cache scan total (fav+unfav) supaya status/gate tidak berat.
local bpScanCache = { at = 0, total = 0, favExtra = 0, allCount = 0, favCount = 0 }
local BP_SCAN_CACHE_SEC = 5

local function _sumAllBaseAndFav(force)
    local now = os.clock()
    if not force and (now - bpScanCache.at) < BP_SCAN_CACHE_SEC and bpScanCache.at > 0 then
        return bpScanCache.total, bpScanCache.favExtra, bpScanCache.allCount, bpScanCache.favCount
    end
    local total = 0
    local favExtra = 0
    local favCount = 0
    local allCount = 0

    -- Total prefer jalur ESP (sama badge backpack).
    local esp = G.EspFruitBackpack or _G.EspFruitBackpack
    if type(esp) == "table" and type(esp.ScanFruits) == "function" and type(esp.GetEntryPrice) == "function" then
        local ok, list = pcall(esp.ScanFruits, esp)
        if ok and type(list) == "table" then
            local seen = {}
            for _, e in ipairs(list) do
                if type(e) == "table" then
                    local id = tostring(e.id or "")
                    local key = id ~= "" and id or (tostring(e.name or "") .. ":" .. tostring(e.multi or 0))
                    if not seen[key] then
                        seen[key] = true
                        allCount += 1
                        local okp, p = pcall(esp.GetEntryPrice, esp, e, false)
                        p = (okp and tonumber(p)) or 0
                        if p > 0 then total += p end
                    end
                end
            end
        end
    end

    -- Fav extra tetap dari tool scan (untuk estimate Daily).
    local toolTotal = 0
    local toolCount = 0
    _eachFruitTool(function(tool)
        toolCount += 1
        local p = _toolPrice(tool)
        toolTotal += p
        if _isFavorited(tool) then
            favCount += 1
            favExtra += p
        end
    end)
    if total <= 0 then
        total = toolTotal
    end
    if allCount <= 0 then
        allCount = toolCount
    end

    bpScanCache.at = now
    bpScanCache.total = total
    bpScanCache.favExtra = favExtra
    bpScanCache.allCount = allCount
    bpScanCache.favCount = favCount
    return total, favExtra, allCount, favCount
end

function M.Evaluate(opts)
    opts = type(opts) == "table" and opts or {}
    local cfg = M.GetConfig()
    local out = {
        ready = false,
        reason = "disabled",
        estimate = 0,
        available = false,
        timeRemaining = 0,
        backpackCount = 0,
        backpackValue = 0,
        baseValue = 0,
    }
    if cfg.enabled ~= true and opts.ignoreEnabled ~= true then
        return out
    end

    -- Hitung total BP dulu (fav+unfav) — tetap diisi meski Daily CD.
    local scanTotal, favExtra, scanCount, favCount = _sumAllBaseAndFav(opts.forceTotals == true)
    local bpCount = tonumber(LP:GetAttribute("FruitCount")) or 0
    if bpCount < scanCount then bpCount = scanCount end
    local totalValue = scanTotal

    local preview = _previewSell()
    if totalValue <= 0 and type(preview) == "table" then
        -- Fallback jika scan tool = 0 (FSV belum ready): pakai Preview + fav extra.
        local pv = tonumber(preview.TotalValue or preview.totalValue
            or preview.TotalSellValue or preview.SellPrice) or 0
        totalValue = pv + math.max(0, favExtra)
        if totalValue <= 0 then
            totalValue = tonumber(preview.TotalBaseValue or preview.totalBaseValue) or 0
            if cfg.autoUnfav == true then
                totalValue = totalValue + math.max(0, favExtra)
            end
        end
    end

    out.backpackCount = bpCount
    out.backpackValue = totalValue
    out.favCount = favCount

    -- Daily payout estimate (tampilkan juga saat CD).
    local baseValue = 0
    if type(preview) == "table" then
        baseValue = tonumber(preview.TotalBaseValue or preview.totalBaseValue) or 0
    end
    if baseValue <= 0 then
        if cfg.autoUnfav == true then
            baseValue = scanTotal > 0 and scanTotal or totalValue
        else
            baseValue = math.max(0, (scanTotal > 0 and scanTotal or totalValue) - favExtra)
        end
    elseif cfg.autoUnfav == true and favExtra > 0 then
        baseValue = baseValue + favExtra
    end
    out.baseValue = baseValue
    out.estimate = _dailyDealPrice(baseValue)

    local deal = _checkDeal(opts.forceDeal == true)
    if type(deal) ~= "table" then
        out.reason = "no_deal"
        return out
    end
    out.available = (deal.Available == true)
    out.timeRemaining = tonumber(deal.TimeRemaining or deal.Remaining) or 0
    if not out.available then
        out.reason = "cooldown"
        return out
    end

    local minN = math.max(1, math.floor(tonumber(cfg.minBackpackCount) or 1))
    local minV = math.max(0, tonumber(cfg.minTotalValue) or 0)
    if bpCount < minN then
        out.reason = "count"
        return out
    end
    if minV > 0 and totalValue < minV then
        out.reason = "value"
        return out
    end

    -- Without autoUnfav, need at least some sellable (non-fav) fruit.
    if cfg.autoUnfav ~= true then
        local sellable = math.max(0, scanCount - favCount)
        if type(preview) == "table" then
            local pc = tonumber(preview.FruitCount or preview.fruitCount)
            if pc ~= nil then sellable = pc end
        end
        if sellable <= 0 then
            out.reason = "all_favorited"
            return out
        end
    end

    out.ready = true
    out.reason = "ok"
    return out
end

M.evaluate = M.Evaluate

local function _shouldYieldToStock(dailyEst)
    local stock = _autoStock()
    if type(stock) ~= "table" or type(stock.Evaluate) ~= "function" then
        return false
    end
    if type(stock.IsEnabled) == "function" and not stock.IsEnabled(stock) then
        return false
    end
    local ok, probe = pcall(stock.Evaluate, stock)
    if not ok or type(probe) ~= "table" or probe.ready ~= true then
        return false
    end
    local sEst = tonumber(probe.estimate) or 0
    -- Stock wins only if strictly greater; tie → Daily.
    return sEst > (tonumber(dailyEst) or 0)
end

function M.RunOnce(opts)
    opts = type(opts) == "table" and opts or {}
    if busy or G.__GAG2_BOOST_SELL_BUSY == true then
        return false, "busy"
    end
    if not M.IsEnabled() then
        return false, "disabled"
    end

    local probe = M.Evaluate(opts)
    if not probe.ready then
        if probe.reason == "cooldown" then
            _setStatus(string.format("Daily CD (%ds)", math.floor(probe.timeRemaining or 0)))
        else
            _setStatus("Daily wait: " .. tostring(probe.reason))
        end
        return false, probe.reason, probe
    end

    if _shouldYieldToStock(probe.estimate) then
        _setStatus("Daily yield to Stock (more sheckles)")
        return false, "yield_stock", probe
    end

    busy = true
    G.__GAG2_BOOST_SELL_BUSY = true
    _setStatus(string.format("Daily deal (est %s)...", tostring(math.floor(probe.estimate + 0.5))))

    local heldOk, okSell, payload = M.WithPeerHold(function()
        local cfg = M.GetConfig()
        if cfg.autoUnfav == true then
            local af = _autoFav()
            if type(af) == "table" and type(af.UnfavAllFavorited) == "function" then
                pcall(function()
                    af.UnfavAllFavorited({ fireDelay = 0.03 })
                end)
                task.wait(UNFAV_SETTLE)
            end
        end
        local ok, res = _npcFire("UseDailyDealAll")
        if not ok then
            return false, res
        end
        if type(res) == "table" then
            if res.Success == true or res.success == true then
                return true, res
            end
            return false, res.Reason or res.reason or "failed"
        end
        if res == true then
            return true, { Success = true }
        end
        return false, "failed"
    end, "daily")

    busy = false
    G.__GAG2_BOOST_SELL_BUSY = false
    dealCache.at = 0
    dealCache.data = nil

    if not heldOk then
        _setStatus("Daily error: " .. tostring(okSell))
        return false, okSell
    end

    if okSell == true then
        _setStatus(string.format("Daily OK (est %s)", tostring(math.floor(probe.estimate + 0.5))))
        return true, payload or { Success = true }, probe
    end

    _setStatus("Daily failed: " .. tostring(okSell))
    return false, okSell, payload
end

M.runOnce = M.RunOnce

----------------------------------------------------------------
local function _loop(myId)
    while running and loopId == myId do
        if M.IsEnabled() and not busy and G.__GAG2_BOOST_SELL_BUSY ~= true then
            pcall(M.RunOnce)
        end
        task.wait(LOOP_SEC)
    end
end

function M.Start()
    M.SetEnabled(true)
    if running then return true end
    running = true
    loopId += 1
    local myId = loopId
    task.spawn(function()
        _loop(myId)
    end)
    _setStatus("Daily ON")
    return true
end

function M.Stop()
    running = false
    M.SetEnabled(false)
    _setStatus("Daily OFF")
end

M.start = M.Start
M.stop = M.Stop

function M.IsRunning()
    return running == true
end

M.isRunning = M.IsRunning

G.AutoSellDaily = M
G.AutoSellDailyModule = M
_G.AutoSellDaily = M
_G.AutoSellDailyModule = M

return M
 end,                   required = false },
    { key = "SectionAutoSellDaily",    name = "Section Auto Sell Daily", factory = function() -- section_auto_sell_daily.lua — UI Auto Sell Daily Deal (tab Auto)

local G = (getgenv and getgenv()) or _G
local M = {}

local VALUE_SUFFIXES = {
    { "juta", 1e6 }, { "jt", 1e6 },
    { "ribu", 1e3 }, { "rb", 1e3 },
    { "dc", 1e33 }, { "no", 1e30 }, { "oc", 1e27 },
    { "sp", 1e24 }, { "sx", 1e21 },
    { "qi", 1e18 }, { "qn", 1e18 },
    { "qa", 1e15 }, { "qd", 1e15 },
    { "t", 1e12 }, { "b", 1e9 }, { "m", 1e6 }, { "k", 1e3 },
}

local function abbrev(n)
    n = tonumber(n) or 0
    if n <= 0 then return "0" end
    local units = {
        { 1e33, "Dc" }, { 1e30, "No" }, { 1e27, "Oc" },
        { 1e24, "Sp" }, { 1e21, "Sx" },
        { 1e18, "Qi" }, { 1e15, "Qa" },
        { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" },
    }
    for _, u in ipairs(units) do
        if n >= u[1] then
            local v = n / u[1]
            if math.abs(v - math.floor(v + 0.5)) < 1e-6 then
                return string.format("%d%s", math.floor(v + 0.5), u[2])
            end
            return string.format("%.2f%s", v, u[2]):gsub("%.?0+([A-Za-z])", "%1")
        end
    end
    return tostring(math.floor(n + 0.5))
end

local function parseScaledValue(txt)
    txt = tostring(txt or ""):lower():gsub("%s+", ""):gsub(",", ".")
    if txt == "" then return nil end
    local sign = 1
    if txt:sub(1, 1) == "-" then
        sign = -1
        txt = txt:sub(2)
    end

    for _, pair in ipairs(VALUE_SUFFIXES) do
        local suf, mult = pair[1], pair[2]
        if #txt > #suf and txt:sub(-#suf) == suf then
            local numPart = txt:sub(1, -#suf - 1)
            local n = tonumber(numPart)
            if n then return n * mult * sign end
        end
    end

    local numPart, letters = txt:match("^([%d%.]+)([a-z]+)$")
    if numPart and letters and #letters >= 2 then
        local n = tonumber(numPart)
        if n then
            local idx = 0
            for i = 1, #letters do
                local c = letters:byte(i) - 96
                if c < 1 or c > 26 then
                    idx = nil
                    break
                end
                idx = idx * 26 + (c - 1)
            end
            if idx ~= nil then
                local exp = 63 + idx * 3
                return n * (10 ^ exp) * sign
            end
        end
    end

    local n = tonumber(txt)
    if n then return n * sign end
    return nil
end

local function formatRemainSec(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local h = sec // 3600
    local m = (sec % 3600) // 60
    local s = sec % 60
    if h > 0 then return string.format("%dh %02dm", h, m) end
    if m > 0 then return string.format("%dm %02ds", m, s) end
    return string.format("%ds", s)
end

function M.Register(ctx)
    if type(ctx) ~= "table" or type(ctx.ui) ~= "table" then return end

    local ui = ctx.ui
    local getAuto = ctx.getAuto
    local patchAuto = ctx.patchAuto
    local patchAutoOnly = ctx.patchAutoOnly
    local registerFlush = ctx.registerFlush

    local ST = getAuto("sellDaily")
    if type(ST) ~= "table" then ST = {} end
    if ST.minBackpackCount == nil then ST.minBackpackCount = 1 end
    if ST.minTotalValue == nil then ST.minTotalValue = 0 end
    ST.enabled = (ST.enabled == true)
    ST.autoUnfav = (ST.autoUnfav == true)

    local function snapshot()
        local api = G.__GAG2_SELL_DAILY_ENABLE_API or rawget(_G, "__GAG2_SELL_DAILY_ENABLE_API")
        if type(api) == "table" and type(api.get) == "function" then
            ST.enabled = (api.get() == true)
        end
        return {
            enabled = (ST.enabled == true),
            minBackpackCount = math.max(1, math.floor(tonumber(ST.minBackpackCount) or 1)),
            minTotalValue = math.max(0, tonumber(ST.minTotalValue) or 0),
            autoUnfav = (ST.autoUnfav == true),
        }
    end

    local function writeGlobals()
        local snap = snapshot()
        for k, v in pairs(snap) do ST[k] = v end
        G.AUTO_SELL_DAILY = snap
        _G.AUTO_SELL_DAILY = snap
        if type(patchAutoOnly) == "function" then
            patchAutoOnly("sellDaily", snap)
        end
    end

    local function syncModule()
        writeGlobals()
        local mod = G.AutoSellDaily or G.AutoSellDailyModule or rawget(_G, "AutoSellDaily")
        if type(mod) == "table" then
            if type(mod.SetConfig) == "function" then
                pcall(mod.SetConfig, mod, snapshot())
            elseif type(mod.setConfig) == "function" then
                pcall(mod.setConfig, mod, snapshot())
            end
            if snapshot().enabled then
                if type(mod.Start) == "function" then pcall(mod.Start, mod) end
            else
                if type(mod.Stop) == "function" then pcall(mod.Stop, mod) end
            end
        end
    end

    local function persist()
        writeGlobals()
        if type(patchAuto) == "function" then
            patchAuto("sellDaily", snapshot(), syncModule)
        else
            syncModule()
        end
    end

    G.__GAG2_PUSH_SELL_DAILY = writeGlobals
    _G.__GAG2_PUSH_SELL_DAILY = writeGlobals
    G.__GAG2_SYNC_AUTO_SELL_DAILY = syncModule
    _G.__GAG2_SYNC_AUTO_SELL_DAILY = syncModule

    if type(registerFlush) == "function" then
        registerFlush("sellDaily", writeGlobals)
    end

    writeGlobals()

    local function reasonLabel(reason, probe)
        reason = tostring(reason or "")
        if reason == "ok" then return "READY"
        elseif reason == "disabled" then return "OFF"
        elseif reason == "count" then return "WAIT COUNT"
        elseif reason == "value" then return "WAIT VALUE"
        elseif reason == "cooldown" then
            return "COOLDOWN " .. formatRemainSec(probe and probe.timeRemaining)
        elseif reason == "all_favorited" then return "ALL FAV"
        elseif reason == "no_deal" then return "UNAVAILABLE"
        end
        return reason ~= "" and string.upper(reason) or "?"
    end

    local function evalDaily()
        local mod = G.AutoSellDaily or G.AutoSellDailyModule or rawget(_G, "AutoSellDaily")
        if type(mod) ~= "table" or type(mod.Evaluate) ~= "function" then return nil end
        local ok, probe = pcall(mod.Evaluate, mod, { ignoreEnabled = true })
        if ok and type(probe) == "table" then
            G.__GAG2_SELL_DAILY_PROBE = probe
            _G.__GAG2_SELL_DAILY_PROBE = probe
            return probe
        end
        return nil
    end

    local function peerStockProbe()
        local cached = G.__GAG2_SELL_STOCK_PROBE or rawget(_G, "__GAG2_SELL_STOCK_PROBE")
        if type(cached) == "table" then return cached end
        return nil
    end

    local function statusText()
        local enabled = (ST.enabled == true)

        local probe = evalDaily()
        local bp = probe and tonumber(probe.backpackCount) or (tonumber(game:GetService("Players").LocalPlayer:GetAttribute("FruitCount")) or 0)
        local bpVal = probe and tonumber(probe.backpackValue) or 0
        local baseV = probe and tonumber(probe.baseValue) or 0
        local est = probe and tonumber(probe.estimate) or 0
        local favN = probe and tonumber(probe.favCount) or 0
        local reason = probe and probe.reason or "…"
        local state = enabled and reasonLabel(reason, probe) or "OFF"

        local vs = ""
        local stock = peerStockProbe()
        local stockOn = false
        do
            local smod = G.AutoSellStock or rawget(_G, "AutoSellStock")
            stockOn = type(smod) == "table" and type(smod.IsEnabled) == "function" and smod.IsEnabled(smod) == true
        end
        if stockOn and stock and probe and probe.ready == true and stock.ready == true then
            local sEst = tonumber(stock.estimate) or 0
            if sEst > est then
                vs = string.format(" · Stock better (%s)", abbrev(sEst))
            else
                vs = string.format(" · ahead of Stock (%s)", abbrev(sEst))
            end
        end

        local line1 = state
        if favN > 0 then
            line1 = string.format("%s · fav %d", state, favN)
        end
        local line2 = string.format("BP %d · %s · base %s → deal %s%s",
            bp, abbrev(bpVal), abbrev(baseV), abbrev(est), vs)
        return line1, line2
    end

    local body = ui:CreateSection("Auto Sell Daily Deal", false)

    local function bindStatusRow(titleLbl)
        if not titleLbl then return end
        titleLbl.TextTruncate = Enum.TextTruncate.AtEnd
        if titleLbl.Parent then
            for _, ch in ipairs(titleLbl.Parent:GetChildren()) do
                if ch:IsA("TextLabel") and ch ~= titleLbl then
                    ch.TextTruncate = Enum.TextTruncate.AtEnd
                end
            end
        end
    end

    local _, statusTitle = ui:CreateRowLabel(body, "…", "Loading daily status…", nil, "accent")
    bindStatusRow(statusTitle)

    local function setStatusLines(lineA, lineB)
        if not (statusTitle and statusTitle.Parent) then return end
        statusTitle.Text = lineA or ""
        for _, ch in ipairs(statusTitle.Parent:GetChildren()) do
            if ch:IsA("TextLabel") and ch ~= statusTitle then
                ch.Text = lineB or ""
                break
            end
        end
    end

    local statusBusy = false
    local function refreshStatus()
        if statusBusy then return end
        statusBusy = true
        task.spawn(function()
            local ok, l1, l2 = pcall(function()
                return statusText()
            end)
            if ok then
                setStatusLines(l1, l2)
            end
            statusBusy = false
        end)
    end

    local function scheduleStatus()
        task.defer(refreshStatus)
    end

    ui:CreateRowInput(
        body,
        "Min backpack count",
        tostring(tonumber(ST.minBackpackCount) or 1),
        function(txt)
            local n = tonumber(txt)
            if n == nil or n < 1 then return end
            ST.minBackpackCount = math.floor(n)
            persist()
            scheduleStatus()
        end,
        false
    )

    local _, setMinValue = ui:CreateRowInput(
        body,
        "Min backpack value (eg 1m 1b)",
        abbrev(tonumber(ST.minTotalValue) or 0),
        function(txt)
            local n = parseScaledValue(txt)
            if n == nil or n < 0 then return end
            ST.minTotalValue = n
            if type(setMinValue) == "function" then
                setMinValue(abbrev(n))
            end
            persist()
            scheduleStatus()
        end,
        false
    )

    ui:CreateRowToggle(
        body,
        "Auto unfav all",
        (ST.autoUnfav == true),
        function(isOn)
            ST.autoUnfav = (isOn == true)
            persist()
            scheduleStatus()
        end
    )

    local _, _, enableApi = ui:CreateRowToggle(
        body,
        "Enable",
        (ST.enabled == true),
        function(isOn)
            ST.enabled = (isOn == true)
            persist()
            scheduleStatus()
        end
    )
    G.__GAG2_SELL_DAILY_ENABLE_API = enableApi
    _G.__GAG2_SELL_DAILY_ENABLE_API = enableApi

    task.spawn(function()
        while body and body.Parent do
            task.wait(5)
            pcall(refreshStatus)
        end
    end)

    task.defer(function()
        syncModule()
        scheduleStatus()
    end)
end

G.SectionAutoSellDaily = M
_G.SectionAutoSellDaily = M

return M
 end,          required = false },
    { key = "AutoMergeEclipseBloom",   name = "Auto Merge Eclipse Bloom", factory = function() -- AutoMergeEclipseBloom.lua — Grow A Garden 2
