-- Export
----------------------------------------------------------------
local G = (getgenv and getgenv()) or _G
G.AutoHopServer = M
G.AutoHopServerModule = M
_G.AutoHopServer = M
_G.AutoHopServerModule = M
G.__GAG2_SYNC_AUTO_HOP = function()
    local applyFn = G.applyAutoHopModule or _G.applyAutoHopModule
    if type(applyFn) == "function" then
        pcall(applyFn)
    else
        M.SyncFromGlobals()
    end
end
_G.__GAG2_SYNC_AUTO_HOP = G.__GAG2_SYNC_AUTO_HOP

return M
 end,                   required = false },
    { key = "AutoHopFruit",            name = "Auto Hop Fruit",          factory = function() -- AutoHopFruit.lua — Grow A Garden 2 (SIMPLE)
-- 1) Tunggu loading screen selesai
-- 2) Scan StealPrompt garden ORANG LAIN sampai selesai
-- 3) Baru hop kalau target fruit tidak ada
-- Scan Delay = jeda antar siklus (min 60s)

local M = {}

local Players = game:GetService("Players")
local CollectionService = game:GetService("CollectionService")
local HttpService = game:GetService("HttpService")

local G = (getgenv and getgenv()) or _G
local LP = Players.LocalPlayer

local PROMPT_TAG = "StealPrompt"
local SCAN_DELAY_MIN = 60
local SCAN_DELAY_MAX = 600
local SCAN_DELAY_DEFAULT = 60
-- Kalau awalnya ADA target fruit, lalu habis (di-steal) → tunggu grace ini sebelum hop
local EMPTY_GRACE_SEC = 60
-- Delay awal sebelum hop/scan pertama (setelah enable / load)
local FIRST_HOP_DELAY_SEC = 30
-- Jangan balik ke server yang sama: simpan max N JobId ke file, penuh → reset
local VISITED_MAX = 20
local VISITED_DIR = "growagarden2"

local _running = false
local _thread = nil
local _enabled = false
local _scanDelay = SCAN_DELAY_DEFAULT
local _fruits = {}
local _fruitSet = {}

local _lastStatus = "idle"
local _lastMatch = ""
local _nextCheckAt = 0
local _lastHopAt = 0
local _hopLockUntil = 0
local _busy = false

-- Track per-server: pernah ketemu target → kalau hilang, grace 60s dulu
local _trackedJobId = ""
local _seenTargetOnServer = false
local _missingSince = 0
local _emptyRetries = 0
local EMPTY_RETRY_MAX = 2
local _wasLoading = false
local _startupWait = false -- true selama delay awal 30s sebelum hop pertama
local _visitedJobs = {} -- cache memory dari file

local function now()
    return os.clock()
end

----------------------------------------------------------------
-- Visited JobId file (anti balik ke server sama)
-- growagarden2/autohop_fruit_visited_<user>.json
-- max 20 → reset → isi lagi
----------------------------------------------------------------
local FS_OK = (type(readfile) == "function" and type(writefile) == "function" and type(isfile) == "function")

local function safeUserName()
    local lp = LP or Players.LocalPlayer
    local s = tostring((lp and lp.Name) or "player")
    s = s:gsub("[^%w%-_.]", "_"):gsub("_+", "_")
    return s:sub(1, 48)
end

local function visitedFilePath()
    return VISITED_DIR .. "/autohop_fruit_visited_" .. safeUserName() .. ".json"
end

local function ensureVisitedFolder()
    if type(makefolder) ~= "function" then return end
    if type(isfolder) == "function" and isfolder(VISITED_DIR) then return end
    pcall(function() makefolder(VISITED_DIR) end)
end

local function loadVisitedFromFile()
    _visitedJobs = {}
    if not FS_OK then return _visitedJobs end
    local path = visitedFilePath()
    if not isfile(path) then return _visitedJobs end
    local ok, raw = pcall(readfile, path)
    if not ok or type(raw) ~= "string" or raw == "" then return _visitedJobs end
    local okJ, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not okJ or type(data) ~= "table" then return _visitedJobs end
    local placeId = tonumber(data.placeId) or 0
    if placeId ~= 0 and placeId ~= tonumber(game.PlaceId) then
        return _visitedJobs -- beda place → ignore
    end
    local jobs = data.jobs
    if type(jobs) ~= "table" then return _visitedJobs end
    local out, seen = {}, {}
    for _, jid in ipairs(jobs) do
        jid = tostring(jid or "")
        if jid ~= "" and not seen[jid] then
            seen[jid] = true
            out[#out + 1] = jid
        end
    end
    _visitedJobs = out
    return _visitedJobs
end

local function saveVisitedToFile()
    if not FS_OK then return false end
    ensureVisitedFolder()
    local payload = {
        placeId = tonumber(game.PlaceId) or 0,
        jobs = _visitedJobs,
        max = VISITED_MAX,
        updatedAt = os.time(),
    }
    local okJ, s = pcall(function() return HttpService:JSONEncode(payload) end)
    if not okJ or type(s) ~= "string" then return false end
    local ok = pcall(writefile, visitedFilePath(), s)
    return ok == true
end

local function getVisitedList()
    if type(_visitedJobs) ~= "table" then
        loadVisitedFromFile()
    end
    return _visitedJobs
end

local function pushVisitedJob(jobId, why)
    jobId = tostring(jobId or "")
    if jobId == "" then return getVisitedList() end
    local list = getVisitedList()
    for _, v in ipairs(list) do
        if tostring(v) == jobId then
            return list
        end
    end
    -- Penuh (20) → reset dulu, lalu mulai isi lagi
    if #list >= VISITED_MAX then
        _visitedJobs = {}
        list = _visitedJobs
    end
    list[#list + 1] = jobId
    _visitedJobs = list
    saveVisitedToFile()
    return list
end

local function clampDelay(v)
    v = math.floor(tonumber(v) or SCAN_DELAY_DEFAULT)
    if v < SCAN_DELAY_MIN then v = SCAN_DELAY_MIN end
    if v > SCAN_DELAY_MAX then v = SCAN_DELAY_MAX end
    return v
end

----------------------------------------------------------------
-- Loading screen gate (sama Move / AutoTele)
----------------------------------------------------------------
local function isLoadingScreenActive()
    local Move = G.Move or G.MoveModule or rawget(_G, "Move")
    if type(Move) == "table" and type(Move.IsLoadingScreenActive) == "function" then
        local ok, v = pcall(Move.IsLoadingScreenActive, Move)
        if ok then return v == true end
    end
    local lp = LP or Players.LocalPlayer
    if not lp then return true end
    if lp:GetAttribute("LoadingScreenDone") == true then return false end
    if lp:GetAttribute("LoadingScreenActive") == true then return true end
    if workspace:FindFirstChild("LoadingScreenMenu") ~= nil then return true end
    return true
end

----------------------------------------------------------------
-- Config
----------------------------------------------------------------
local function normalizeFruitList(list)
    local out, seen = {}, {}
    if type(list) ~= "table" then return out end
    local function push(raw)
        local s = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" or seen[s] then return end
        seen[s] = true
        out[#out + 1] = s
    end
    if rawget(list, 1) ~= nil then
        for _, v in ipairs(list) do push(v) end
    else
        for k, v in pairs(list) do
            if v == true or v == 1 or v == "true" then
                push(k)
            elseif type(v) == "string" or type(v) == "number" then
                push(v)
            end
        end
    end
    table.sort(out)
    return out
end

local function rebuildFruitSet()
    _fruitSet = {}
    for _, name in ipairs(_fruits) do
        local low = string.lower(tostring(name))
        if low ~= "" then
            _fruitSet[low] = true
            _fruitSet[tostring(name)] = true
        end
    end
end

local function matchFruitName(seed)
    seed = tostring(seed or "")
    if seed == "" or seed == "?" then return false end
    if _fruitSet[seed] == true then return true end
    local low = string.lower(seed)
    if _fruitSet[low] == true then return true end
    for _, name in ipairs(_fruits) do
        local n = string.lower(tostring(name))
        if n ~= "" and (low == n or string.find(low, n, 1, true) or string.find(n, low, 1, true)) then
            return true
        end
    end
    return false
end

local function syncLocalFromState()
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    local ahf = type(MAIN) == "table"
        and type(MAIN.misc) == "table"
        and type(MAIN.misc.rejoin) == "table"
        and MAIN.misc.rejoin.auto_hop_fruit
    ahf = type(ahf) == "table" and ahf or nil

    _enabled = (ahf and ahf.enabled == true)
        or (G.AUTO_HOP_FRUIT_ENABLED == true)
        or (rawget(_G, "AUTO_HOP_FRUIT_ENABLED") == true)
    _scanDelay = clampDelay(
        (ahf and ahf.scan_delay)
            or G.AUTO_HOP_FRUIT_SCAN_DELAY
            or rawget(_G, "AUTO_HOP_FRUIT_SCAN_DELAY")
            or SCAN_DELAY_DEFAULT
    )
    _fruits = normalizeFruitList(
        (ahf and ahf.fruits)
            or G.AUTO_HOP_FRUIT_LIST
            or rawget(_G, "AUTO_HOP_FRUIT_LIST")
            or _fruits
    )
    rebuildFruitSet()
end

----------------------------------------------------------------
-- Simple fruit resolve
----------------------------------------------------------------
local function looksLikeId(s)
    s = tostring(s or "")
    return s == "" or (#s >= 20 and s:match("^[0-9a-fA-F%-]+$") ~= nil)
end

local function fruitModelFromPrompt(prompt)
    if not prompt or not prompt.Parent then return nil end
    local cur = prompt.Parent
    for _ = 1, 8 do
        if not cur then break end
        if cur:IsA("Model") and cur:GetAttribute("FruitId") ~= nil then
            return cur
        end
        cur = cur.Parent
    end
    cur = prompt.Parent
    while cur do
        if cur:IsA("Model") then return cur end
        cur = cur.Parent
    end
    return nil
end

local function isStealPrompt(p)
    if not p or not p:IsA("ProximityPrompt") then return false end
    if CollectionService:HasTag(p, PROMPT_TAG) then return true end
    local nm = string.lower(tostring(p.Name or ""))
    local at = string.lower(tostring(p.ActionText or ""))
    return nm == "stealprompt" or at == "steal" or string.find(at, "steal", 1, true) ~= nil
end

local function seedFromModel(model)
    if not model then return "?" end
    local keys = { "SeedName", "CorePartName", "FruitName", "FruitType", "ItemName", "DisplayName" }
    for _, k in ipairs(keys) do
        local v = model:GetAttribute(k)
        if v ~= nil and tostring(v) ~= "" and not looksLikeId(v) then
            return tostring(v)
        end
    end
    local plant = model
    if model.Parent and (model.Parent.Name == "Fruits" or model.Parent.Name == "Fruit") then
        plant = model.Parent.Parent
    end
    if plant and plant ~= model then
        for _, k in ipairs(keys) do
            local v = plant:GetAttribute(k)
            if v ~= nil and tostring(v) ~= "" and not looksLikeId(v) then
                return tostring(v)
            end
        end
    end
    local fsv = G.FruitSellValue or G.FruitSellValueModule or rawget(_G, "FruitSellValue")
    if fsv and type(fsv.resolveSeedName) == "function" then
        local ok, n = pcall(fsv.resolveSeedName, model)
        if ok and type(n) == "string" and n ~= "" and not looksLikeId(n) then
            return n
        end
    end
    local fb = tostring(model.Name or "")
    if fb ~= "" and not looksLikeId(fb) then return fb end
    return "?"
end

----------------------------------------------------------------
-- SCAN: StealPrompt other gardens — harus selesai sebelum hop
----------------------------------------------------------------
-- return: found(bool), name, checked, total
local function scanWorldForTargetFruit()
    local lp = LP or Players.LocalPlayer
    local myId = lp and lp.UserId
    local tagged = CollectionService:GetTagged(PROMPT_TAG)
    local total = #tagged
    local checked = 0
    local foundName = nil

    _lastStatus = ("scanning 0/%d..."):format(total)

    for i = 1, total do
        if not _enabled or not _running then
            return nil, nil, checked, total -- aborted
        end

        local prompt = tagged[i]
        if prompt and prompt.Parent and isStealPrompt(prompt) then
            local model = fruitModelFromPrompt(prompt)
            if model and model:IsA("Model") and model:GetAttribute("_GAG2FruitShell") ~= true then
                local ownerId = tonumber(model:GetAttribute("UserId"))
                local plant = model
                if model.Parent and (model.Parent.Name == "Fruits" or model.Parent.Name == "Fruit") then
                    plant = model.Parent.Parent or model
                end
                if not ownerId and plant then
                    ownerId = tonumber(plant:GetAttribute("UserId"))
                end
                -- skip garden sendiri
                if ownerId and (not myId or ownerId ~= myId) then
                    local seed = seedFromModel(model)
                    checked += 1
                    if (not foundName) and matchFruitName(seed) then
                        foundName = seed
                        -- tetap lanjut sampai selesai? user bilang selesai scan dulu sebelum hop.
                        -- Found = tidak hop, boleh early stop (lebih cepat).
                        _lastStatus = ("scan FOUND %s (%d/%d)"):format(seed, i, total)
                        return true, foundName, checked, total
                    end
                end
            end
        end

        if i % 80 == 0 or i == total then
            _lastStatus = ("scanning %d/%d · checked %d..."):format(i, total, checked)
            task.wait()
        end
    end

    if total <= 0 or checked <= 0 then
        _lastStatus = ("scan empty (%d prompts / %d fruits)"):format(total, checked)
        return nil, nil, checked, total -- world belum siap
    end

    if foundName then
        _lastStatus = ("scan DONE found %s (%d)"):format(foundName, checked)
        return true, foundName, checked, total
    end

    _lastStatus = ("scan DONE missing (%d/%d)"):format(checked, total)
    return false, nil, checked, total
end

----------------------------------------------------------------
-- Hop / track
-- Scan Delay = jeda WAJIB antar scan & antar hop (min 60s)
----------------------------------------------------------------
local function getAutoHop()
    return G.AutoHopServer or _G.AutoHopServer
        or G.AutoHopServerModule or _G.AutoHopServerModule
end

local function currentJobId()
    return tostring(game.JobId or "")
end

local function delaySec()
    return math.max(SCAN_DELAY_MIN, _scanDelay)
end

local function armDelay(extra)
    local d = delaySec() + (tonumber(extra) or 0)
    local t = now() + d
    if t > _nextCheckAt then _nextCheckAt = t end
    if t > _hopLockUntil then _hopLockUntil = t end
    return d
end

local function hopReady()
    if now() < _hopLockUntil then return false end
    if _lastHopAt > 0 and (now() - _lastHopAt) < delaySec() then return false end
    return true
end

local function hopWaitLeft()
    local a = math.max(0, _hopLockUntil - now())
    local b = 0
    if _lastHopAt > 0 then
        b = math.max(0, delaySec() - (now() - _lastHopAt))
    end
    return math.ceil(math.max(a, b))
end

local function onNewServer(why)
    _trackedJobId = currentJobId()
    _seenTargetOnServer = false
    _missingSince = 0
    _emptyRetries = 0
    _lastMatch = ""
    -- Catat JobId server baru supaya tidak balik ke sini
    if why == "job_changed" then
        pushVisitedJob(_trackedJobId, "arrive")
    end
    -- Setelah hop/pindah: tunggu sisa Scan Delay dari last hop (min sampai delay penuh)
    if why == "job_changed" and _lastHopAt > 0 then
        local readyAt = math.max(now(), _lastHopAt + delaySec())
        _nextCheckAt = readyAt
        _hopLockUntil = math.max(_hopLockUntil, readyAt)
        local n = #getVisitedList()
        _lastStatus = ("new server · wait %ds · visited %d/%d"):format(
            math.max(0, math.ceil(readyAt - now())), n, VISITED_MAX
        )
    end
end

local function ensureServerTrack()
    local job = currentJobId()
    if job == "" then return end
    if _trackedJobId == "" then
        _trackedJobId = job
        return
    end
    if job ~= _trackedJobId then
        onNewServer("job_changed")
    end
end

local function doHop(why)
    if not hopReady() then
        local left = hopWaitLeft()
        _lastStatus = ("hop cooldown · %ds"):format(left)
        _nextCheckAt = math.max(_nextCheckAt, now() + left)
        return false, "cooldown"
    end

    local AH = getAutoHop()
    if type(AH) ~= "table" or type(AH.ForceHopNow) ~= "function" then
        _lastStatus = "AutoHopServer missing"
        armDelay(0)
        return false, "no_autohop"
    end

    if type(AH.GetStatus) == "function" then
        local stOk, st = pcall(AH.GetStatus)
        if stOk and type(st) == "table" and (st.sessionActive or st.inFlight) then
            _lastStatus = "hop in progress"
            -- jangan spam ForceHopNow; cek lagi sebentar
            _nextCheckAt = math.max(_nextCheckAt, now() + 2)
            return false, "busy"
        end
    end

    -- Lock DULU sebelum tele (anti spam)
    _lastHopAt = now()
    local d = armDelay(0)

    -- Simpan JobId server sekarang → jangan hop balik ke sini
    local curJob = currentJobId()
    pushVisitedJob(curJob, why or "prehop")
    local visited = getVisitedList()
    _lastStatus = ("hopping · next %ds · visited %d/%d"):format(d, #visited, VISITED_MAX)

    local ok, a, b = pcall(AH.ForceHopNow, "fruit_missing", {
        allowDisabled = true,
        force = true,
        preferMostPlayers = true,
        maxCandidates = 1, -- 1 hop per delay, jangan burst 3 job
        diffServers = VISITED_MAX,
        extraVisited = visited,
    })
    if ok and a == true then
        _lastStatus = ("teleporting · next check %ds · visited %d/%d"):format(
            math.ceil(_nextCheckAt - now()), #visited, VISITED_MAX
        )
        return true
    end
    _lastStatus = ("hop fail · wait %ds"):format(math.ceil(_nextCheckAt - now()))
    return false, tostring((ok and (b or a)) or a or "fail")
end

----------------------------------------------------------------
-- Loop
-- loading → scan 1x → ada = stay | kosong = hop
-- SELALU tunggu Scan Delay (min 60) sebelum scan/hop berikutnya
-- grace 60s hanya jika tadi ADA lalu hilang (stolen)
----------------------------------------------------------------
local function tickOnce()
    syncLocalFromState()

    if not _enabled then
        _lastStatus = "off"
        return
    end
    if #_fruits == 0 then
        _lastStatus = "no fruit selected"
        return
    end
    if _busy then return end

    if isLoadingScreenActive() then
        _wasLoading = true
        _lastStatus = "waiting loading screen..."
        return
    end

    if _wasLoading then
        _wasLoading = false
        if _trackedJobId == "" then
            _trackedJobId = currentJobId()
        else
            ensureServerTrack()
        end
        -- Jangan hapus delay awal 30s; kalau belum di-arm, arm sekarang
        if _lastHopAt <= 0 then
            if _startupWait and _nextCheckAt > now() then
                -- keep remaining startup delay
            else
                _nextCheckAt = now() + FIRST_HOP_DELAY_SEC
                _startupWait = true
                _lastStatus = ("startup wait %ds"):format(FIRST_HOP_DELAY_SEC)
            end
        end
    end

    ensureServerTrack()

    if now() < _nextCheckAt then
        local left = math.ceil(_nextCheckAt - now())
        if _startupWait and _lastHopAt <= 0 then
            _lastStatus = ("startup wait %ds"):format(left)
        elseif _missingSince > 0 and _seenTargetOnServer then
            local graceLeft = math.max(0, math.ceil(EMPTY_GRACE_SEC - (now() - _missingSince)))
            _lastStatus = ("empty after steal · grace %ds"):format(graceLeft)
        elseif _lastMatch ~= "" then
            _lastStatus = ("watching %s · %ds"):format(_lastMatch, left)
        elseif _lastHopAt > 0 and hopWaitLeft() > 0 then
            _lastStatus = ("wait %ds (scan delay)"):format(left)
        else
            _lastStatus = ("wait %ds"):format(left)
        end
        return
    end

    if _startupWait then
        _startupWait = false
    end

    -- SCAN 1x selesai dulu
    _busy = true
    _lastStatus = "scanning world..."
    local ok, found, name, checked, total = pcall(function()
        return scanWorldForTargetFruit()
    end)
    _busy = false

    if not ok then
        _lastStatus = "scan err: " .. tostring(found)
        armDelay(0)
        return
    end

    -- World belum siap: max 2x retry 8s, lalu anggap missing
    if found == nil then
        _emptyRetries += 1
        if _emptyRetries <= EMPTY_RETRY_MAX then
            _nextCheckAt = now() + 8
            _lastStatus = ("scan empty · retry %d/%d"):format(_emptyRetries, EMPTY_RETRY_MAX)
            return
        end
        _emptyRetries = 0
        found = false
        checked, total = checked or 0, total or 0
    end

    if found == true then
        _seenTargetOnServer = true
        _missingSince = 0
        _lastMatch = tostring(name or "?")
        armDelay(0)
        _lastStatus = ("watching %s · next %ds"):format(_lastMatch, delaySec())
        return
    end

    _lastMatch = ""

    -- Pernah ada → grace 60s, baru hop (tetap hormati scan delay)
    if _seenTargetOnServer then
        if _missingSince <= 0 then
            _missingSince = now()
            _nextCheckAt = now() + EMPTY_GRACE_SEC
            _lastStatus = ("was present, now empty · grace %ds"):format(EMPTY_GRACE_SEC)
            return
        end
        if (now() - _missingSince) < EMPTY_GRACE_SEC then
            local left = math.ceil(EMPTY_GRACE_SEC - (now() - _missingSince))
            _nextCheckAt = now() + left
            _lastStatus = ("empty after steal · grace %ds"):format(left)
            return
        end
        if not hopReady() then
            local left = hopWaitLeft()
            _nextCheckAt = now() + left
            _lastStatus = ("grace done · hop cooldown %ds"):format(left)
            return
        end
        _lastStatus = "empty after grace · hop"
        doHop("stolen empty")
        return
    end

    -- Dari awal tidak ada → hop (hanya jika delay sudah lewat)
    if not hopReady() then
        local left = hopWaitLeft()
        _nextCheckAt = now() + left
        _lastStatus = ("missing · hop cooldown %ds"):format(left)
        return
    end
    _lastStatus = ("missing (%s/%s) · hop"):format(tostring(checked), tostring(total))
    doHop("missing from start")
end

local function loop()
    while _running do
        local ok, err = pcall(tickOnce)
        if not ok then
            _busy = false
            _lastStatus = "err: " .. tostring(err)
        end
        task.wait(0.5)
    end
end

----------------------------------------------------------------
-- Public API
----------------------------------------------------------------
function M.IsRunning()
    return _running == true
end

function M.IsEnabled()
    return _enabled == true
end

function M.GetStatus()
    syncLocalFromState()
    if _enabled and not _running then
        M.Start()
    end
    local left = 0
    if _hopLockUntil > now() then
        left = math.ceil(_hopLockUntil - now())
    elseif _nextCheckAt > now() then
        left = math.ceil(_nextCheckAt - now())
    end
    return {
        running = _running,
        enabled = _enabled,
        scanDelay = _scanDelay,
        nextCheckIn = math.max(0, left),
        fruits = _fruits,
        fruitCount = #_fruits,
        lastMatch = _lastMatch,
        status = _lastStatus,
        scanBusy = _busy,
        loading = isLoadingScreenActive(),
        visitedCount = #getVisitedList(),
        visitedMax = VISITED_MAX,
        visitedFile = visitedFilePath(),
    }
end

function M.GetVisited()
    return getVisitedList()
end

function M.ClearVisited()
    _visitedJobs = {}
    saveVisitedToFile()
    return true
end

function M.SetScanDelay(sec, maybeSec)
    if type(sec) == "table" then sec = maybeSec end
    _scanDelay = clampDelay(sec)
    G.AUTO_HOP_FRUIT_SCAN_DELAY = _scanDelay
    _G.AUTO_HOP_FRUIT_SCAN_DELAY = _scanDelay
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.rejoin = MAIN.misc.rejoin or {}
        MAIN.misc.rejoin.auto_hop_fruit = MAIN.misc.rejoin.auto_hop_fruit or {}
        MAIN.misc.rejoin.auto_hop_fruit.scan_delay = _scanDelay
    end
    return _scanDelay
end

function M.SetFruits(list, maybeList)
    if type(list) == "table" and (list.SetFruits == M.SetFruits or list.GetStatus == M.GetStatus) then
        list = maybeList
    end
    _fruits = normalizeFruitList(list)
    rebuildFruitSet()
    G.AUTO_HOP_FRUIT_LIST = _fruits
    _G.AUTO_HOP_FRUIT_LIST = _fruits
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.rejoin = MAIN.misc.rejoin or {}
        MAIN.misc.rejoin.auto_hop_fruit = MAIN.misc.rejoin.auto_hop_fruit or {}
        MAIN.misc.rejoin.auto_hop_fruit.fruits = _fruits
    end
    -- Fruit list berubah → scan ulang, tapi tetap hormati hop cooldown / startup delay
    if _lastHopAt > 0 and not hopReady() then
        _nextCheckAt = now() + hopWaitLeft()
    elseif _startupWait and _nextCheckAt > now() then
        -- keep startup wait
    else
        _nextCheckAt = 0
    end
    return _fruits
end

function M.GetFruits()
    return _fruits
end

function M.Start()
    if _running then return end
    syncLocalFromState()
    loadVisitedFromFile()
    _busy = false
    _wasLoading = isLoadingScreenActive()
    _trackedJobId = currentJobId()
    _seenTargetOnServer = false
    _missingSince = 0
    _emptyRetries = 0
    -- Catat server awal juga (supaya hop pertama tidak balik ke sini nanti)
    if _trackedJobId ~= "" then
        pushVisitedJob(_trackedJobId, "start")
    end
    -- Jangan bypass Scan Delay kalau baru saja hop
    if _lastHopAt > 0 and not hopReady() then
        local left = hopWaitLeft()
        _nextCheckAt = now() + left
        _hopLockUntil = math.max(_hopLockUntil, _nextCheckAt)
        _startupWait = false
        _lastStatus = ("starting · cooldown %ds"):format(left)
    else
        -- Delay awal 30s sebelum scan/hop pertama
        _nextCheckAt = now() + FIRST_HOP_DELAY_SEC
        _startupWait = true
        _lastStatus = ("startup wait %ds"):format(FIRST_HOP_DELAY_SEC)
    end
    _running = true
    _thread = task.spawn(loop)
end

function M.Stop()
    _running = false
    _busy = false
    _lastStatus = "off"
end

function M.SetEnabled(on, maybeOn)
    if type(on) == "table" then on = maybeOn end
    on = (on == true)
    _enabled = on
    G.AUTO_HOP_FRUIT_ENABLED = on
    _G.AUTO_HOP_FRUIT_ENABLED = on
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.rejoin = MAIN.misc.rejoin or {}
        MAIN.misc.rejoin.auto_hop_fruit = MAIN.misc.rejoin.auto_hop_fruit or {}
        MAIN.misc.rejoin.auto_hop_fruit.enabled = on
    end
    if on then
        M.Start()
    else
        M.Stop()
    end
    return on
end

function M.SyncFromGlobals()
    syncLocalFromState()
    M.SetScanDelay(_scanDelay)
    M.SetFruits(_fruits)
    M.SetEnabled(_enabled)
end

M.syncFromGlobals = M.SyncFromGlobals

function M.CheckNow()
    -- scan manual saja; jangan clear hop cooldown
    return scanWorldForTargetFruit()
end

G.AutoHopFruit = M
G.AutoHopFruitModule = M
_G.AutoHopFruit = M
_G.AutoHopFruitModule = M

task.defer(function()
    pcall(function()
        syncLocalFromState()
        loadVisitedFromFile()
        if _enabled then M.Start() end
    end)
end)

return M
 end,                     required = false },
    -- WeatherKick paling awal (sebelum ReduceFPS). Predict dulu karena Kick pakai API-nya.
    { key = "WeatherPredict",          name = "Weather Predict",         factory = function() -- WeatherPredict.lua — Grow A Garden 2
-- Live cycle + moon/map weather prediction overlay

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local COLOR_BG     = Color3.fromRGB(8, 8, 12)
local COLOR_PANEL  = Color3.fromRGB(14, 14, 20)
local COLOR_YELLOW = Color3.fromRGB(255, 211, 0)
local COLOR_LIVE   = Color3.fromRGB(120, 255, 175)
local COLOR_MUTED  = Color3.fromRGB(175, 178, 190)
local MOON_PALETTE = {
    Color3.fromRGB(255, 140, 220),
    Color3.fromRGB(255, 210, 90),
    Color3.fromRGB(255, 95, 95),
    Color3.fromRGB(180, 200, 255),
    Color3.fromRGB(140, 255, 200),
}

local running      = false
local overlayGui   = nil
local overlayGen   = 0
local initDone     = false

local cycle            = { phases = {}, cycleSec = 600, nightIdx = 3, dayIdx = 1, nightPhase = nil }
local weatherRows      = {}
local cycleWeatherRows = {}
local skipPhaseWeathers = {}
local mapWeatherSeedMult = 1000

local function _enabled()
    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" and type(MAIN.misc) == "table"
        and type(MAIN.misc.weather_predict) == "table"
        and MAIN.misc.weather_predict.enabled == true then
        return true
    end
    return G.WEATHER_PREDICT_ENABLED == true or rawget(_G, "WEATHER_PREDICT_ENABLED") == true
end

local function _writeEnabled(on)
    on = (on == true)
    G.WEATHER_PREDICT_ENABLED = on
    _G.WEATHER_PREDICT_ENABLED = on

    local MAIN = G.MAIN or rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.weather_predict = MAIN.misc.weather_predict or {}
        MAIN.misc.weather_predict.enabled = on
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end

    local STATE = G.STATE or rawget(_G, "STATE")
    if type(STATE) == "table" then
        STATE.weather_predict = STATE.weather_predict or {}
        STATE.weather_predict.enabled = on
    end
    return on
end

local function fmtSec(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    local h = math.floor(sec / 3600)
    local m = math.floor((sec % 3600) / 60)
    local s = sec % 60
    if h > 0 then return string.format("%dh%02dm", h, m) end
    if m > 0 then return string.format("%dm%02ds", m, s) end
    return string.format("%ds", s)
end

local function fmtClock(unixTs)
    unixTs = math.floor(tonumber(unixTs) or 0)
    if unixTs <= 0 then return "?" end
    return os.date("%H:%M", unixTs)
end

-- Semua timing ikut server game (bukan os.time() lokal — bisa selisih ~10 menit)
local function now()
    return workspace:GetServerTimeNow()
end

local function serverNow()
    return now()
end

local function activePhase()
    return workspace:GetAttribute("ActivePhase")
end

local function activeWeather()
    return workspace:GetAttribute("ActiveWeather")
end

local function loadModule(name)
    local SM = ReplicatedStorage:FindFirstChild("SharedModules")
    if not SM then return nil end
    local ok, mod = pcall(function() return require(SM:WaitForChild(name, 5)) end)
    if not ok then return nil end
    return mod
end

local function weatherOccurrence(entry)
    if type(entry) ~= "table" then return nil end
    local occ = entry.Occurrence or entry.Occurance or entry.Chance or entry.Weight
    if type(occ) == "number" and occ > 0 then return occ end
    return nil
end

local function phaseWeatherChance(w)
    if type(w) == "number" and w > 0 then return w end
    if type(w) == "table" then
        local c = w.Chance or w.Weight or w.Occurrence or w.Occurance
        if type(c) == "number" and c > 0 then return c end
    end
    return nil
end

local function buildSkipPhaseWeathers(built)
    local skip = {}
    if not built or not built.phases then return skip end
    for _, p in ipairs(built.phases) do
        if type(p.name) == "string" then
            skip[p.name] = true
        end
        for wName in pairs(p.weathers or {}) do
            if type(wName) == "string" and wName == p.name then
                skip[wName] = true
            end
        end
    end
    return skip
end

local function isSelectableWeather(name)
    return type(name) == "string" and name ~= "" and not skipPhaseWeathers[name]
end

local function getNightMoonNames()
    local names = {}
    local night = cycle.nightPhase
    if not night then return names end
    for wName in pairs(night.weathers or {}) do
        if isSelectableWeather(wName) then
            names[#names + 1] = wName
        end
    end
    table.sort(names)
    return names
end

local function moonLineColor(moonName)
    local moons = getNightMoonNames()
    for i, name in ipairs(moons) do
        if name == moonName then
            return MOON_PALETTE[(i - 1) % #MOON_PALETTE + 1]
        end
    end
    return COLOR_MUTED
end

local function buildPhases(tcd)
    if not tcd or type(tcd.Data) ~= "table" then return nil end
    local phases = {}
    for phaseName, entry in pairs(tcd.Data) do
        if type(entry) == "table" then
            phases[#phases + 1] = {
                name = phaseName,
                duration = entry.Lasts or 0,
                order = entry.StartOrder or 99,
                weathers = entry.Weathers or {},
            }
        end
    end
    table.sort(phases, function(a, b) return a.order < b.order end)
    local cycleSec, offset = 0, 0
    for _, p in ipairs(phases) do
        p.offset = offset
        cycleSec = cycleSec + p.duration
        offset = offset + p.duration
    end
    local nightIdx, nightPhase, dayIdx = nil, nil, nil
    for i, p in ipairs(phases) do
        if p.name == "Night" then nightIdx, nightPhase = i, p end
        if p.name == "Day" or p.name == "Morning" then dayIdx = i end
    end
    if not dayIdx then dayIdx = 1 end
    return { phases = phases, cycleSec = cycleSec, nightIdx = nightIdx, dayIdx = dayIdx, nightPhase = nightPhase }
end

local function rollPhaseWeather(phase, rng)
    if not phase or not phase.weathers then return nil end
    local entries = {}
    for wName, w in pairs(phase.weathers) do
        local chance = phaseWeatherChance(w)
        if type(wName) == "string" and chance then
            entries[#entries + 1] = { name = wName, chance = chance }
        end
    end
    if #entries == 0 then return nil end
    table.sort(entries, function(a, b) return a.name < b.name end)
    local total = 0
    for _, e in ipairs(entries) do total = total + e.chance end
    if total <= 0 then return nil end
    local roll = rng:NextNumber() * total
    local acc = 0
    for _, e in ipairs(entries) do
        acc = acc + e.chance
        if roll <= acc then return e.name end
    end
    return entries[1].name
end

local function getPhaseByName(name)
    for i, p in ipairs(cycle.phases) do
        if p.name == name then return p, i end
    end
    return nil, nil
end

local function getCycleState()
    local phaseName = activePhase()
    local phaseEnd = workspace:GetAttribute("PhaseDuration")
    if not phaseName or type(phaseEnd) ~= "number" then return nil end

    local remaining = math.max(0, phaseEnd - serverNow())
    local phase, phaseIdx = getPhaseByName(phaseName)
    if not phase then return nil end

    return {
        phaseIndex = phaseIdx,
        phaseName = phaseName,
        phase = phase,
        weather = activeWeather(),
        remaining = remaining,
        elapsed = math.max(0, phase.duration - remaining),
        phaseEnd = phaseEnd,
    }
end

local function cycleIndex()
    local st = getCycleState()
    if not st or not cycle.phases or #cycle.phases == 0 then
        return math.floor(serverNow() / math.max(cycle.cycleSec, 1))
    end

    local elapsed = 0
    for i, p in ipairs(cycle.phases) do
        if i < st.phaseIndex then
            elapsed = elapsed + p.duration
        elseif i == st.phaseIndex then
            elapsed = elapsed + math.max(0, p.duration - st.remaining)
            break
        end
    end

    local cycleStart = serverNow() - elapsed
    return math.floor(cycleStart / math.max(cycle.cycleSec, 1))
end

local function predictPhaseWeather(cycleIdx, phaseIdx)
    local phase = cycle.phases[phaseIdx]
    if not phase then return nil end
    return rollPhaseWeather(phase, Random.new(cycleIdx * 1000 + phaseIdx))
end

local function weatherKey(name)
    if type(name) ~= "string" then return "" end
    return string.lower((name:gsub("[%s_%-]", "")))
end

local function weatherMatches(mapName, rolledName)
    if type(mapName) ~= "string" or type(rolledName) ~= "string" then return false end
    local mk = weatherKey(mapName)
    local rk = weatherKey(rolledName)
    if mk == "" or rk == "" then return false end
    return mk == rk
end

local function rollWeatherDataEvent(rng)
    if not rng or #weatherRows == 0 then return nil end
    local entries = {}
    for _, entry in ipairs(weatherRows) do
        if type(entry.Name) == "string" then
            local occ = entry.Occurrence or entry.Occurance or entry.Chance or entry.Weight
            if type(occ) ~= "number" or occ <= 0 then
                occ = 1
            end
            entries[#entries + 1] = { name = entry.Name, chance = occ }
        end
    end
    if #entries == 0 then return nil end
    table.sort(entries, function(a, b) return a.name < b.name end)
    local total = 0
    for _, e in ipairs(entries) do total = total + e.chance end
    if total <= 0 then return nil end
    local roll = rng:NextNumber() * total
    local acc = 0
    for _, e in ipairs(entries) do
        acc = acc + e.chance
        if roll <= acc then return e.name end
    end
    return entries[1].name
end

local function predictMapWeather(cycleIdx)
    local dayIdx = cycle.dayIdx or 1
    local rng = Random.new(cycleIdx * mapWeatherSeedMult + dayIdx)
    local fromData = rollWeatherDataEvent(rng)
    if fromData then return fromData end
    local dayPhase = cycle.phases[dayIdx]
    if dayPhase then
        return rollPhaseWeather(dayPhase, rng)
    end
    return nil
end

local function calibrateMapSeed()
    local st = getCycleState()
    if not st then return end
    local live = activeWeather()
    if type(live) ~= "string" or live == "" or not isSelectableWeather(live) then return end
    if cycle.nightIdx and st.phaseIndex == cycle.nightIdx then return end

    local ci = cycleIndex()
    local dayIdx = cycle.dayIdx or 1
    local dayPhase = cycle.phases[dayIdx]
    for _, mult in ipairs({ 1000, 10000, 1, 9973, 1337, 7777 }) do
        local rng = Random.new(ci * mult + dayIdx)
        local pred = rollWeatherDataEvent(rng)
        if pred and weatherMatches(pred, live) then
            mapWeatherSeedMult = mult
            return
        end
        if dayPhase then
            local phasePred = rollPhaseWeather(dayPhase, rng)
            if phasePred == live or weatherMatches(phasePred, live) then
                mapWeatherSeedMult = mult
                return
            end
        end
    end
end

local function predictDayWeather(cycleIdx)
    local dayIdx = cycle.dayIdx or 1
    local fromData = predictMapWeather(cycleIdx)
    if fromData and isSelectableWeather(fromData) then return fromData end
    local fromPhase = predictPhaseWeather(cycleIdx, dayIdx)
    if fromPhase and isSelectableWeather(fromPhase) then return fromPhase end
    return fromData or fromPhase
end

local function predictNightWeather(cycleIdx)
    if not cycle.nightIdx then return nil end
    return predictPhaseWeather(cycleIdx, cycle.nightIdx)
end

local function cycleStartTime(cycleIdx)
    local st = getCycleState()
    if not st then return nil end
    local ci = cycleIndex()
    local elapsed = 0
    for i, p in ipairs(cycle.phases) do
        if i < st.phaseIndex then
            elapsed = elapsed + p.duration
        elseif i == st.phaseIndex then
            elapsed = elapsed + math.max(0, p.duration - st.remaining)
            break
        end
    end
    return serverNow() - elapsed + (cycleIdx - ci) * cycle.cycleSec
end

local function phaseStartTime(cycleIdx, phaseIdx)
    local cs = cycleStartTime(cycleIdx)
    if not cs or not cycle.phases[phaseIdx] then return nil end
    return cs + (cycle.phases[phaseIdx].offset or 0)
end

local function secondsUntilPhase(cycleIdx, phaseIdx)
    local startT = phaseStartTime(cycleIdx, phaseIdx)
    if not startT then return 0 end
    return math.max(0, startT - serverNow())
end

local function upcomingPhaseWeathers(maxCount)
    maxCount = maxCount or 10
    local out = {}
    local st = getCycleState()
    if not st or #cycle.phases == 0 then return out end

    local now = serverNow()
    local ci = cycleIndex()
    local pi = st.phaseIndex
    local cyc = ci
    local limit = maxCount + #cycle.phases * 2

    for _ = 1, limit do
        pi = pi + 1
        if pi > #cycle.phases then
            pi = 1
            cyc = cyc + 1
        end
        local wName
        if pi == cycle.dayIdx then
            wName = predictDayWeather(cyc)
        elseif pi == cycle.nightIdx then
            wName = predictPhaseWeather(cyc, pi)
        end
        if wName and isSelectableWeather(wName) then
            local inSec = secondsUntilPhase(cyc, pi)
            out[#out + 1] = {
                name = wName,
                phaseName = cycle.phases[pi].name,
                cycleIdx = cyc,
                phaseIdx = pi,
                inSec = inSec,
                at = now + inSec,
            }
            if #out >= maxCount then break end
        end
    end
    return out
end

local function phaseRemaining()
    local st = getCycleState()
    return st and st.remaining or nil
end

local function dur(name, fallback)
    local p = getPhaseByName(name)
    return p and p.duration or fallback
end

local function secondsUntilNightCycle(offset)
    offset = offset or 0
    local st = getCycleState()
    if not st then return 0 end

    local rem = st.remaining
    local cur = st.phaseName
    local nightIdx = cycle.nightIdx

    if offset == 0 then
        if cur == "Night" then return 0 end
        if cur == "Sunset" then return rem end
        if cur == "Day" then return rem + dur("Sunset", 30) end
        return rem
    end

    local toCycleEnd = rem
    for i = st.phaseIndex + 1, #cycle.phases do
        toCycleEnd = toCycleEnd + cycle.phases[i].duration
    end

    local beforeNight = 0
    if nightIdx and nightIdx > 1 then
        for i = 1, nightIdx - 1 do
            beforeNight = beforeNight + (cycle.phases[i].duration or 0)
        end
    else
        beforeNight = dur("Day", 450) + dur("Sunset", 30)
    end

    return toCycleEnd + (offset - 1) * cycle.cycleSec + beforeNight
end

local function findNextMoon(moonName, maxCycles)
    maxCycles = maxCycles or 60
    local now = serverNow()
    local ci = cycleIndex()
    local cur = activePhase()
    local weather = activeWeather()

    for offset = 0, maxCycles do
        local predicted = predictNightWeather(ci + offset)
        if not weatherMatches(moonName, predicted or "") then
            -- skip cycle
        elseif offset == 0 and cur == "Night" then
            if weatherMatches(moonName, weather or "") then
                return { inSec = 0, cycleIdx = ci, live = true }
            end
        else
            local sec = secondsUntilNightCycle(offset)
            return { inSec = sec, cycleIdx = ci + offset, at = now + sec }
        end
    end
    return nil
end

local function readMapWeather(name)
    local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
    if not WeatherValues then
        return { playing = false, endsIn = nil, endsAt = nil }
    end
    local playing = WeatherValues:GetAttribute(name .. "_Playing")
    local endTime = WeatherValues:GetAttribute(name .. "_EndTime")
    local startTime = WeatherValues:GetAttribute(name .. "_StartTime")
    local duration = WeatherValues:GetAttribute(name .. "_Duration")
    local now = serverNow()

    local endsIn = nil
    if playing == true then
        if type(startTime) == "number" and startTime > 1e9
            and type(duration) == "number" and duration > 0 then
            endsIn = math.max(0, (startTime + duration) - now)
        elseif type(endTime) == "number" and endTime > 1e9 then
            endsIn = math.max(0, endTime - now)
        elseif type(endTime) == "number" and endTime > 0 and endTime < 1e6 then
            endsIn = math.max(0, endTime)
        end
    end

    return {
        playing = playing == true,
        endsIn = endsIn,
        endsAt = (endsIn ~= nil) and fmtClock(now + endsIn) or nil,
    }
end

local function findNextMapWeather(mapName, maxCycles)
    maxCycles = maxCycles or 120
    local st = getCycleState()
    if not st or not cycle.dayIdx then return nil end

    local now = serverNow()
    local ci = cycleIndex()
    local dayIdx = cycle.dayIdx
    local row = readMapWeather(mapName)
    if row.playing then
        return { inSec = 0, live = true, at = now, name = mapName }
    end

    local live = activeWeather()
    if weatherMatches(mapName, live) then
        return { inSec = 0, live = true, at = now, name = live }
    end

    for offset = 0, maxCycles do
        local cyc = ci + offset
        local rolled = predictDayWeather(cyc)
        if rolled and weatherMatches(mapName, rolled) then
            local inSec = secondsUntilPhase(cyc, dayIdx)
            if offset == 0 and st.phaseIndex > dayIdx then
                -- Day phase sudah lewat di cycle ini, coba cycle berikutnya
            elseif inSec <= 0 and offset == 0 and st.phaseIndex == dayIdx then
                if weatherMatches(mapName, live) then
                    return { inSec = 0, live = true, at = now, name = rolled, cycleIdx = cyc }
                end
            else
                return {
                    inSec = inSec,
                    live = false,
                    at = now + inSec,
                    name = rolled,
                    cycleIdx = cyc,
                    phaseIdx = dayIdx,
                }
            end
        end
    end
    return nil
end

local function loadWeatherEventRows(wd)
    local rows = {}
    if not wd or type(wd.Data) ~= "table" then return rows end

    if wd.Data[1] then
        for _, entry in ipairs(wd.Data) do
            if type(entry) == "table" then rows[#rows + 1] = entry end
        end
    else
        for name, entry in pairs(wd.Data) do
            if type(entry) == "table" then
                if type(entry.Name) ~= "string" then entry.Name = name end
                rows[#rows + 1] = entry
            elseif type(name) == "string" then
                rows[#rows + 1] = { Name = name, Occurrence = entry }
            end
        end
        table.sort(rows, function(a, b) return tostring(a.Name) < tostring(b.Name) end)
    end
    return rows
end

local function loadWeatherRowsFromValues()
    local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
    if not WeatherValues then return {} end
    local rows, seen = {}, {}
    for attrName in pairs(WeatherValues:GetAttributes()) do
        if type(attrName) == "string" then
            local base = attrName:match("^(.+)_Playing$")
            if base and not seen[base] then
                seen[base] = true
                rows[#rows + 1] = { Name = base, Occurrence = 1 }
            end
        end
    end
    table.sort(rows, function(a, b) return a.Name < b.Name end)
    return rows
end

local function buildCycleWeatherRows()
    local rows, seen = {}, {}
    for _, phase in ipairs(cycle.phases) do
        for wName, w in pairs(phase.weathers or {}) do
            if isSelectableWeather(wName) and not seen[wName] then
                seen[wName] = true
                rows[#rows + 1] = {
                    Name = wName,
                    Occurrence = phaseWeatherChance(w) or 1,
                    Phase = phase.name,
                    Source = "TimeCycleData",
                }
            end
        end
    end
    table.sort(rows, function(a, b) return a.Name < b.Name end)
    return rows
end

local function ensureInit()
    if initDone then return true end

    local built = buildPhases(loadModule("TimeCycleData"))
    if built then cycle = built end
    skipPhaseWeathers = buildSkipPhaseWeathers(cycle)

    weatherRows = loadWeatherEventRows(loadModule("WeatherData"))
    for _, row in ipairs(weatherRows) do
        row.Source = "WeatherData"
    end

    cycleWeatherRows = buildCycleWeatherRows()

    if #weatherRows == 0 then
        weatherRows = loadWeatherRowsFromValues()
        for _, row in ipairs(weatherRows) do
            row.Source = "WeatherValues"
        end
    end

    calibrateMapSeed()
    initDone = true
    return true
end

function M.GetLines()
    ensureInit()
    calibrateMapSeed()
    local lines = {}
    local st = getCycleState()
    local rem = st and st.remaining or phaseRemaining()
    local cur = activePhase()
    local weather = activeWeather()
    local ci = cycleIndex()

    if cur then
        local predicted = st and predictPhaseWeather(ci, st.phaseIndex) or nil
        local sub = fmtSec(rem or 0) .. " left"
        if predicted and predicted ~= weather then
            sub = sub .. " · pred ~" .. tostring(predicted)
        end
        lines[#lines + 1] = {
            text = string.format("%s · %s", cur, weather or predicted or "?"),
            sub = sub,
            live = true,
            kind = "cycle",
        }
    else
        lines[#lines + 1] = {
            text = "Waiting ActivePhase...",
            sub = "join server cycle",
            live = false,
            kind = "info",
        }
    end

    local upcoming = upcomingPhaseWeathers(10)
    if #upcoming > 0 then
        lines[#lines + 1] = { text = "Upcoming Weather", sub = "", live = false, kind = "divider" }
        for _, hit in ipairs(upcoming) do
            local liveNow = hit.inSec <= 0
            lines[#lines + 1] = {
                text = hit.name,
                sub = liveNow and "LIVE NOW"
                    or string.format("%s · %s · %s", hit.phaseName or "?", fmtSec(hit.inSec), fmtClock(hit.at)),
                live = liveNow,
                kind = "weather",
            }
        end
    end

    local nextOff = (cur == "Night") and 1 or 0
    local nightIn = secondsUntilNightCycle(nextOff)
    local nextMoon = predictNightWeather(ci + nextOff)
    lines[#lines + 1] = {
        text = "Next Night",
        sub = string.format("%s → %s", fmtSec(nightIn), nextMoon or "?"),
        live = false,
        kind = "night",
    }

    for _, moon in ipairs(getNightMoonNames()) do
        local hit = findNextMoon(moon, 60)
        if hit then
            if hit.live then
                lines[#lines + 1] = {
                    text = moon,
                    sub = "LIVE NOW",
                    live = true,
                    kind = "moon",
                    moon = moon,
                }
            else
                lines[#lines + 1] = {
                    text = moon,
                    sub = string.format("%s · ~%s", fmtSec(hit.inSec), fmtClock(hit.at)),
                    live = false,
                    kind = "moon",
                    moon = moon,
                }
            end
        end
    end

    lines[#lines + 1] = {
        text = string.format("Cycle %s · idx %d", fmtSec(cycle.cycleSec), ci),
        sub = "Tonight ~" .. tostring(predictNightWeather(ci) or "?"),
        live = false,
        kind = "meta",
    }

    lines[#lines + 1] = { text = "Map Weather", sub = "", live = false, kind = "divider" }

    for _, entry in ipairs(weatherRows) do
        local n = entry.Name
        if type(n) == "string" then
            local row = readMapWeather(n)
            if row.playing then
                lines[#lines + 1] = {
                    text = n,
                    sub = string.format("LIVE %s · %s", row.endsAt or "?", fmtSec(row.endsIn)),
                    live = true,
                    kind = "map",
                }
            else
                local hit = findNextMapWeather(n, 120)
                local sub
                if hit then
                    if hit.live then
                        sub = "LIVE NOW"
                    else
                        sub = string.format("~%s · %s", fmtSec(hit.inSec), fmtClock(hit.at))
                    end
                elseif weatherOccurrence(entry) then
                    sub = "Occ " .. weatherOccurrence(entry)
                else
                    sub = "idle"
                end
                lines[#lines + 1] = {
                    text = n,
                    sub = sub,
                    live = hit and hit.live == true or false,
                    kind = "map",
                }
            end
        end
    end

    return lines
end

function M.GetWeatherNames()
    ensureInit()
    local names, seen = {}, {}

    local function addName(n)
        if isSelectableWeather(n) and not seen[n] then
            seen[n] = true
            names[#names + 1] = n
        end
    end

    for _, entry in ipairs(weatherRows) do
        addName(entry.Name)
    end

    for _, entry in ipairs(cycleWeatherRows) do
        addName(entry.Name)
    end

    for _, entry in ipairs(loadWeatherRowsFromValues()) do
        addName(entry.Name)
    end

    table.sort(names)
    return names
end

function M.GetWeatherRows()
    ensureInit()
    local out, seen = {}, {}
    local function push(entry)
        local n = entry.Name
        if not isSelectableWeather(n) or seen[n] then return end
        seen[n] = true
        out[#out + 1] = entry
    end
    for _, entry in ipairs(weatherRows) do push(entry) end
    for _, entry in ipairs(cycleWeatherRows) do push(entry) end
    for _, entry in ipairs(loadWeatherRowsFromValues()) do
        entry.Source = entry.Source or "WeatherValues"
        push(entry)
    end
    table.sort(out, function(a, b) return tostring(a.Name) < tostring(b.Name) end)
    return out
end

function M.GetWeatherOptions()
    local names = M.GetWeatherNames()
    local items = {}
    for _, name in ipairs(names) do
        items[#items + 1] = { key = name, name = name }
    end
    return items
end

function M.GetPhaseNames()
    ensureInit()
    local names = {}
    for _, phase in ipairs(cycle.phases) do
        if type(phase.name) == "string" and phase.name ~= "" then
            names[#names + 1] = phase.name
        end
    end
    table.sort(names)
    return names
end

function M.PhaseMatches(phaseName, livePhase)
    if type(phaseName) ~= "string" or type(livePhase) ~= "string" then return false end
    return weatherKey(phaseName) == weatherKey(livePhase)
end

M.phaseMatches = M.PhaseMatches

local KICK_PREFIX_PHASE   = "P:"
local KICK_PREFIX_WEATHER = "W:"

local function weatherDataDuration(name)
    name = tostring(name or "")
    if name == "" then return nil end
    ensureInit()
    local key = weatherKey(name)

    -- Event map (Rain/Eclipse/…) → Lasts di WeatherData
    for _, entry in ipairs(weatherRows or {}) do
        if type(entry) == "table" and weatherKey(entry.Name) == key then
            local d = tonumber(entry.Lasts or entry.Last or entry.Duration or entry.Length)
            if d and d > 0 then return d end
        end
    end

    -- Cycle/moon (Moon/Bloodmoon/…) → lama fase di TimeCycleData (biasanya Night)
    for _, entry in ipairs(cycleWeatherRows or {}) do
        if type(entry) == "table" and weatherKey(entry.Name) == key then
            local d = tonumber(dur(entry.Phase, nil))
            if d and d > 0 then return d end
            local night = cycle.nightPhase
            if night and tonumber(night.duration) and night.duration > 0 then
                return tonumber(night.duration)
            end
        end
    end

    return nil
end

-- Terima pemanggilan WP.GetWeatherDuration(name) maupun WP:GetWeatherDuration(name) / pcall(..., WP, name)
function M.GetWeatherDuration(name, maybeName)
    if type(name) ~= "string" then
        name = maybeName
    end
    return weatherDataDuration(name)
end

function M.GetKickTargetOptions()
    local items = {}

    for _, opt in ipairs(M.GetWeatherOptions()) do
        local wName = opt.key or opt.name
        if type(wName) == "string" and wName ~= "" then
            local dur = weatherDataDuration(wName)
            local label = opt.name or wName
            if dur then
                local m = math.floor(dur / 60)
                local s = math.floor(dur % 60)
                if m > 0 then
                    label = string.format("%s (%dm%02ds)", label, m, s)
                else
                    label = string.format("%s (%ds)", label, s)
                end
            end
            items[#items + 1] = {
                key = KICK_PREFIX_WEATHER .. wName,
                name = label,
                kind = "weather",
                weather = wName,
                duration = dur,
            }
        end
    end

    return items
end

function M.WeatherMatches(mapName, rolledName)
    return weatherMatches(mapName, rolledName)
end

M.weatherMatches = M.WeatherMatches

-- Terima pemanggilan WP.IsWeatherLive(name) maupun WP:IsWeatherLive(name) / pcall(..., WP, name)
-- Hanya sinyal live nyata (ActiveWeather / WeatherValues._Playing).
-- Prediksi cycle TIDAK dihitung live — bip bisa beda dari ActiveWeather ("Day")
-- dan bikin WeatherKick false-match (mis. Lightning 300s saat Map: Eclipse).
function M.IsWeatherLive(name, maybeName)
    if type(name) ~= "string" then
        name = maybeName
    end
    ensureInit()
    name = tostring(name or "")
    if name == "" then return false, nil end

    local live = activeWeather()
    if weatherMatches(name, live or "") then
        return true, live
    end

    if readMapWeather(name).playing then
        return true, name
    end

    return false, nil
end

function M.GetLiveMapWeathers()
    ensureInit()
    local out = {}
    for _, entry in ipairs(weatherRows) do
        local n = entry.Name
        if type(n) == "string" and readMapWeather(n).playing then
            out[#out + 1] = n
        end
    end
    table.sort(out)
    return out
end

function M.GetSnapshot()
    local st = getCycleState()
    return {
        running = running,
        phase = st and st.phaseName or activePhase(),
        weather = st and st.weather or activeWeather(),
        remaining = st and st.remaining or phaseRemaining(),
        lines = M.GetLines(),
    }
end

local function destroyOverlay()
    overlayGen += 1

    local pg = LP and LP:FindFirstChild("PlayerGui")
    if pg then
        local old = pg:FindFirstChild("GAG2_WX_PRED")
        if old then
            pcall(function() old:Destroy() end)
        end
    end

    if overlayGui then
        pcall(function() overlayGui:Destroy() end)
        overlayGui = nil
    end
end

local function lineColor(line)
    if line.live then return COLOR_LIVE end
    if line.kind == "moon" and line.moon then
        return moonLineColor(line.moon)
    end
    if line.kind == "divider" then return COLOR_YELLOW end
    return COLOR_MUTED
end

local function createOverlay()
    local myGen = overlayGen

    local pg = LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui", 5)
    if not pg then return false end

    local gui = Instance.new("ScreenGui")
    gui.Name = "GAG2_WX_PRED"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.Enabled = true
    gui.DisplayOrder = 10050
    gui.Parent = pg
    overlayGui = gui

    local frame = Instance.new("Frame")
    frame.Name = "Panel"
    frame.Size = UDim2.fromOffset(340, 200)
    frame.Position = UDim2.new(0, 14, 0.24, 0)
    frame.BackgroundColor3 = COLOR_BG
    frame.BackgroundTransparency = 0.08
    frame.BorderSizePixel = 0
    frame.Parent = gui
    Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 10)

    local stroke = Instance.new("UIStroke")
    stroke.Color = COLOR_YELLOW
    stroke.Thickness = 1.2
    stroke.Transparency = 0.35
    stroke.Parent = frame

    local accent = Instance.new("Frame")
    accent.Size = UDim2.new(1, 0, 0, 3)
    accent.BackgroundColor3 = COLOR_YELLOW
    accent.BorderSizePixel = 0
    accent.Parent = frame
    Instance.new("UICorner", accent).CornerRadius = UDim.new(0, 10)

    local header = Instance.new("TextLabel")
    header.Size = UDim2.new(1, -16, 0, 22)
    header.Position = UDim2.fromOffset(10, 8)
    header.BackgroundTransparency = 1
    header.Font = Enum.Font.GothamBold
    header.TextSize = 13
    header.TextXAlignment = Enum.TextXAlignment.Left
    header.TextColor3 = COLOR_YELLOW
    header.Text = "WEATHER PREDICT"
    header.Parent = frame

    local badge = Instance.new("TextLabel")
    badge.Size = UDim2.fromOffset(52, 16)
    badge.Position = UDim2.new(1, -60, 0, 10)
    badge.BackgroundColor3 = Color3.fromRGB(25, 55, 35)
    badge.BackgroundTransparency = 0.2
    badge.Font = Enum.Font.GothamBold
    badge.TextSize = 9
    badge.Text = "LIVE"
    badge.TextColor3 = COLOR_LIVE
    badge.Parent = frame
    Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 6)

    local list = Instance.new("ScrollingFrame")
    list.Name = "List"
    list.Size = UDim2.new(1, -12, 1, -38)
    list.Position = UDim2.fromOffset(6, 34)
    list.BackgroundTransparency = 1
    list.BorderSizePixel = 0
    list.ScrollBarThickness = 3
    list.ScrollBarImageColor3 = COLOR_YELLOW
    list.CanvasSize = UDim2.new()
    list.AutomaticCanvasSize = Enum.AutomaticSize.Y
    list.Parent = frame

    local layout = Instance.new("UIListLayout")
    layout.Padding = UDim.new(0, 4)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = list

    local rows = {}

    local function render()
        if myGen ~= overlayGen or not overlayGui or overlayGui ~= gui or not gui.Parent then
            return
        end
        local lines = M.GetLines()
        local yPad = 0

        for i, line in ipairs(lines) do
            local row = rows[i]
            if not row then
                row = Instance.new("Frame")
                row.BackgroundColor3 = COLOR_PANEL
                row.BackgroundTransparency = line.kind == "divider" and 1 or 0.35
                row.BorderSizePixel = 0
                row.Size = UDim2.new(1, -4, 0, line.kind == "divider" and 18 or 34)
                row.Parent = list
                Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)

                local title = Instance.new("TextLabel")
                title.Name = "Title"
                title.BackgroundTransparency = 1
                title.Position = UDim2.fromOffset(8, 4)
                title.Size = UDim2.new(1, -12, 0, 14)
                title.Font = Enum.Font.GothamMedium
                title.TextSize = 11
                title.TextXAlignment = Enum.TextXAlignment.Left
                title.Parent = row

                local sub = Instance.new("TextLabel")
                sub.Name = "Sub"
                sub.BackgroundTransparency = 1
                sub.Position = UDim2.fromOffset(8, 18)
                sub.Size = UDim2.new(1, -12, 0, 12)
                sub.Font = Enum.Font.Gotham
                sub.TextSize = 10
                sub.TextXAlignment = Enum.TextXAlignment.Left
                sub.TextColor3 = COLOR_MUTED
                sub.Parent = row

                rows[i] = { frame = row, title = title, sub = sub }
            end

            local r = rows[i]
            if not r or not r.title or not r.title.Parent then
                -- overlay destroyed mid-render
            else
            r.frame.Visible = true
            r.frame.LayoutOrder = i
            r.frame.Size = UDim2.new(1, -4, 0, line.kind == "divider" and 18 or 34)

            local col = lineColor(line)
            r.title.Text = line.text or ""
            r.title.TextColor3 = col
            r.sub.Text = line.sub or ""
            r.sub.Visible = (line.sub or "") ~= ""
            if line.kind == "divider" then
                r.title.Text = "— " .. (line.text or "") .. " —"
                r.sub.Visible = false
            end
            yPad += r.frame.AbsoluteSize.Y + 4
            end
        end

        for i = #lines + 1, #rows do
            if rows[i] then rows[i].frame.Visible = false end
        end
    end

    render()

    task.spawn(function()
        while myGen == overlayGen and overlayGui == gui and gui.Parent do
            task.wait(1)
            if myGen ~= overlayGen or overlayGui ~= gui or not gui.Parent then
                break
            end
            render()
        end
    end)

    return true
end

function M.Start()
    ensureInit()
    running = true
    _G.GAG2_WEATHER_STOP = false
    destroyOverlay()

    local ok = createOverlay()
    if not ok or not overlayGui or not overlayGui.Parent then
        running = false
        return false
    end

    G.GAG2_WEATHER = {
        cycle = cycle,
        state = getCycleState,
        predictPhase = predictPhaseWeather,
        predictMap = predictMapWeather,
        predictDay = predictDayWeather,
        predictNight = predictNightWeather,
        upcoming = upcomingPhaseWeathers,
        nextMap = findNextMapWeather,
        nextMoon = findNextMoon,
        nextNightIn = function(offset) return secondsUntilNightCycle(offset or 0) end,
        readMap = readMapWeather,
        GetLines = M.GetLines,
        GetWeatherNames = M.GetWeatherNames,
        GetWeatherOptions = M.GetWeatherOptions,
        GetPhaseNames = M.GetPhaseNames,
        GetKickTargetOptions = M.GetKickTargetOptions,
        GetWeatherDuration = M.GetWeatherDuration,
        GetWeatherRows = M.GetWeatherRows,
        WeatherMatches = M.WeatherMatches,
        IsWeatherLive = M.IsWeatherLive,
        GetLiveMapWeathers = M.GetLiveMapWeathers,
        PhaseMatches = M.PhaseMatches,
    }
    _G.GAG2_WEATHER = G.GAG2_WEATHER
    return true
end

M.start = M.Start

function M.Stop()
    running = false
    _G.GAG2_WEATHER_STOP = true
    destroyOverlay()
end

M.stop = M.Stop

function M.IsRunning()
    return running == true
end

function M.SetEnabled(on)
    on = (on == true)
    _writeEnabled(on)
    if on then
        return M.Start()
    end
    M.Stop()
    return on
end

function M.EnsureRunning()
    if _enabled() then
        M.Start()
    else
        M.Stop()
    end
end

M.ensureRunning = M.EnsureRunning

function M.SyncFromGlobals()
    M.EnsureRunning()
end

M.syncFromGlobals = M.SyncFromGlobals

G.__GAG2_SYNC_WEATHER_PREDICT = function()
    M.SyncFromGlobals()
end
_G.__GAG2_SYNC_WEATHER_PREDICT = G.__GAG2_SYNC_WEATHER_PREDICT

return M
 end,                required = false, early = true },
    { key = "WeatherKick",             name = "Weather Kick",            factory = function() -- WeatherKick.lua
-- Disconnect saat weather match (ActiveWeather / map event / moon prediksi) → tunggu delay → rejoin

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace       = game:GetService("Workspace")
local CoreGui         = game:GetService("CoreGui")
local GuiService      = game:GetService("GuiService")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G

local MODULE_VER = 21
if G.__WEATHER_KICK_VER == MODULE_VER and type(G.WeatherKick) == "table" then
    return G.WeatherKick
end
G.__WEATHER_KICK_VER = MODULE_VER
G.__WEATHER_KICK_LOADED = true

local PREFIX_PHASE   = "P:"
local PREFIX_WEATHER = "W:"
local FALLBACK_AUTO_DELAY = 60

local M = {}
M._running = false
M._thread = nil
M._kickBusy = false
M._weatherConn = nil
M._phaseConn = nil
M._mapConn = nil
M.DEBUG = false
-- true = hide Roblox disconnect prompt. Juga ikut HIDE_PROMPT_ENABLED.
M.HIDE_KICK_PROMPT = false

local Lighting = game:GetService("Lighting")

local function shouldHideKickPrompt()
    if M.HIDE_KICK_PROMPT == true then return true end
    if G.HIDE_PROMPT_ENABLED == true or rawget(_G, "HIDE_PROMPT_ENABLED") == true then
        return true
    end
    return false
end

local function clearKickBlur()
    pcall(function()
        for _, v in ipairs(Lighting:GetChildren()) do
            if v:IsA("BlurEffect") then
                v.Enabled = false
                pcall(function() v.Size = 0 end)
            end
        end
    end)
    pcall(function()
        for _, v in ipairs(CoreGui:GetDescendants()) do
            if v:IsA("BlurEffect") then
                v.Enabled = false
                pcall(function() v.Size = 0 end)
            end
        end
    end)
    local R = G.PSReconnect or rawget(_G, "PSReconnect")
    if type(R) == "table" and type(R.HideRobloxPrompt) == "function" then
        pcall(R.HideRobloxPrompt, R)
    end
end

local function dprint(...)
    if M.DEBUG ~= true then return end
    print("[WeatherKick]", ...)
end

local function truthy(v)
    return (v == true) or (v == 1) or (v == "true") or (v == "1")
end

-- 0 = auto sesuai durasi weather yang match; 1..600 = fixed sec
local function clampDelay(n)
    n = math.floor(tonumber(n) or 60)
    if n < 0 then n = 0 end
    if n > 600 then n = 600 end
    return n
end

local function getWeatherPredict()
    return G.WeatherPredict or G.WeatherPredictModule
        or rawget(_G, "WeatherPredict") or rawget(_G, "WeatherPredictModule")
end

local function defaultWeatherName()
    local WP = getWeatherPredict()
    if type(WP) == "table" and type(WP.GetWeatherNames) == "function" then
        local ok, names = pcall(WP.GetWeatherNames, WP)
        if ok and type(names) == "table" and type(names[1]) == "string" and names[1] ~= "" then
            return names[1]
        end
    end
    return ""
end

local function normalizeNameList(input, legacyName)
    local list = {}
    local seen = {}

    local function add(name)
        name = tostring(name or "")
        if name ~= "" and not seen[name] then
            seen[name] = true
            table.insert(list, name)
        end
    end

    if type(input) == "table" then
        for _, w in ipairs(input) do
            add(w)
        end
    elseif type(input) == "string" then
        add(input)
    end

    if legacyName ~= nil then
        add(legacyName)
    end

    return list
end

local function splitSelectedKeys(selected)
    local weathers, cycles = {}, {}
    local seenW = {}
    if type(selected) ~= "table" then return weathers, cycles end
    for _, rawKey in ipairs(selected) do
        local key = tostring(rawKey or "")
        if key:sub(1, 2) == PREFIX_WEATHER then
            local name = key:sub(3)
            if name ~= "" and not seenW[name] then
                seenW[name] = true
                table.insert(weathers, name)
            end
        end
    end
    table.sort(weathers)
    return weathers, cycles
end

local function buildSelectedFromLegacy(wk)
    local selected, seen = {}, {}
    local function add(key)
        key = tostring(key or "")
        if key == "" or seen[key] then return end
        if key:sub(1, 2) ~= PREFIX_WEATHER then return end
        seen[key] = true
        table.insert(selected, key)
    end
    if type(wk.weathers) == "table" then
        for _, name in ipairs(wk.weathers) do
            add(PREFIX_WEATHER .. tostring(name))
        end
    end
    if #selected == 0 and type(wk.weather) == "string" and wk.weather ~= "" then
        add(PREFIX_WEATHER .. wk.weather)
    end
    return selected
end

local function normalizeWeathers(input, legacyWeather)
    if type(input) == "table" then
        if type(input.weathers) == "table" then
            return normalizeNameList(input.weathers)
        end
        if type(input.cycles) == "table" or type(input.phases) == "table" then
            return normalizeNameList(nil)
        end
        return normalizeNameList(input, input.weather or input.selected_weather)
    end
    return normalizeNameList(input, legacyWeather)
end

local function normalizeCycles(input)
    if type(input) == "table" then
        if type(input.cycles) == "table" then
            return normalizeNameList(input.cycles)
        end
        if type(input.phases) == "table" then
            return normalizeNameList(input.phases)
        end
    end
    return normalizeNameList(input)
end

local function normalizeSelection(input, legacyWeather, legacyCycles)
    local weathers, cycles

    if type(input) == "table" and (type(input.weathers) == "table" or type(input.cycles) == "table" or type(input.phases) == "table") then
        weathers = normalizeWeathers(input)
        cycles = normalizeCycles(input)
    else
        weathers = normalizeWeathers(input, legacyWeather)
        cycles = normalizeCycles(legacyCycles)
    end

    return weathers, cycles
end

local function selectionToText(weathers)
    local parts = {}
    if type(weathers) == "table" then
        for _, name in ipairs(weathers) do
            table.insert(parts, tostring(name))
        end
    end
    if #parts == 0 then return "?" end
    if #parts <= 3 then
        return table.concat(parts, ", ")
    end
    return table.concat(parts, ", ", 1, 3) .. "..."
end

local function publishGlobals(enabled, weathers, delay, selected)
    G.WEATHER_KICK_ENABLED = enabled
    G.WEATHER_KICK_WEATHERS = weathers
    G.WEATHER_KICK_CYCLES = {}
    G.WEATHER_KICK_SELECTED = selected or {}
    G.WEATHER_KICK_REJOIN_DELAY_SEC = delay
    _G.WEATHER_KICK_ENABLED = enabled
    _G.WEATHER_KICK_WEATHERS = weathers
    _G.WEATHER_KICK_CYCLES = {}
    _G.WEATHER_KICK_SELECTED = selected or {}
    _G.WEATHER_KICK_REJOIN_DELAY_SEC = delay
end

local function getMainRejoin()
    local main = G.MAIN or _G.MAIN
    if type(main) == "table" and type(main.misc) == "table" and type(main.misc.rejoin) == "table" then
        return main.misc.rejoin
    end
    return nil
end

local function normalizeWeatherKick(wk)
    wk = type(wk) == "table" and wk or {}
    wk.enabled = (wk.enabled == true)
    if type(wk.selected) == "table" then
        wk.weathers = select(1, splitSelectedKeys(wk.selected))
    else
        wk.weathers = normalizeWeathers(wk)
    end
    wk.cycles = {}
    wk.rejoin_delay_sec = clampDelay(wk.rejoin_delay_sec)
    return wk
end

local function selectedKeysFromWeathers(weathers)
    local selected = {}
    for _, name in ipairs(weathers or {}) do
        selected[#selected + 1] = PREFIX_WEATHER .. tostring(name)
    end
    return selected
end

local function getCfg()
    local enabled, weathers, delay

    local rjMain = getMainRejoin()
    if type(rjMain) == "table" and type(rjMain.weather_kick) == "table" then
        local wk = normalizeWeatherKick(rjMain.weather_kick)
        enabled = wk.enabled
        weathers = wk.weathers
        delay = wk.rejoin_delay_sec
    end

    local STATE = G.STATE or _G.STATE
    if type(STATE) == "table" and type(STATE.rejoin) == "table" and type(STATE.rejoin.weather_kick) == "table" then
        local wk = normalizeWeatherKick(STATE.rejoin.weather_kick)
        if enabled == nil then enabled = wk.enabled end
        if weathers == nil or #weathers == 0 then weathers = wk.weathers end
        if delay == nil then delay = wk.rejoin_delay_sec end
    end

    if type(G.__WEATHER_KICK_SAVED) == "table" then
        if enabled == nil and G.__WEATHER_KICK_SAVED.enabled ~= nil then
            enabled = truthy(G.__WEATHER_KICK_SAVED.enabled)
        end
        if type(G.__WEATHER_KICK_SAVED.selected) == "table" then
            weathers = select(1, splitSelectedKeys(G.__WEATHER_KICK_SAVED.selected))
        end
        if (weathers == nil or #weathers == 0) and type(G.__WEATHER_KICK_SAVED.weathers) == "table" then
            weathers = normalizeNameList(G.__WEATHER_KICK_SAVED.weathers)
        end
        if (weathers == nil or #weathers == 0) and G.__WEATHER_KICK_SAVED.weather ~= nil then
            weathers = normalizeNameList(G.__WEATHER_KICK_SAVED.weather)
        end
        if delay == nil and G.__WEATHER_KICK_SAVED.rejoin_delay_sec ~= nil then
            delay = G.__WEATHER_KICK_SAVED.rejoin_delay_sec
        end
    end

    if enabled == nil then
        enabled = (G.WEATHER_KICK_ENABLED == true) or (rawget(_G, "WEATHER_KICK_ENABLED") == true)
    end
    if weathers == nil or #weathers == 0 then
        local sel = G.WEATHER_KICK_SELECTED or rawget(_G, "WEATHER_KICK_SELECTED")
        if type(sel) == "table" and #sel > 0 then
            weathers = select(1, splitSelectedKeys(sel))
        end
    end
    if weathers == nil or #weathers == 0 then
        weathers = G.WEATHER_KICK_WEATHERS or rawget(_G, "WEATHER_KICK_WEATHERS")
        weathers = normalizeNameList(weathers)
    end
    if delay == nil then
        delay = G.WEATHER_KICK_REJOIN_DELAY_SEC or rawget(_G, "WEATHER_KICK_REJOIN_DELAY_SEC")
    end

    enabled = (enabled == true)
    weathers = normalizeWeathers({ weathers = weathers })
    delay = clampDelay(delay)

    -- Runtime globals (UI / Apply) win over stale MAIN mirror
    if type(G.WEATHER_KICK_ENABLED) == "boolean" then
        enabled = (G.WEATHER_KICK_ENABLED == true)
    elseif rawget(_G, "WEATHER_KICK_ENABLED") ~= nil then
        enabled = (_G.WEATHER_KICK_ENABLED == true)
    end
    if type(G.WEATHER_KICK_WEATHERS) == "table" and #G.WEATHER_KICK_WEATHERS > 0 then
        weathers = normalizeNameList(G.WEATHER_KICK_WEATHERS)
    end
    if G.WEATHER_KICK_REJOIN_DELAY_SEC ~= nil then
        delay = clampDelay(G.WEATHER_KICK_REJOIN_DELAY_SEC)
    end
    weathers = normalizeWeathers({ weathers = weathers })

    local cycles = {}
    local selected = selectedKeysFromWeathers(weathers)

    publishGlobals(enabled, weathers, delay, selected)

    return enabled, weathers, cycles, delay
end

local function liveStr(v)
    if v == nil then return "" end
    return tostring(v)
end

local function nameKey(s)
    s = liveStr(s):gsub("^%s+", ""):gsub("%s+$", "")
    return string.lower(s:gsub("[%s_%-]", ""))
end

local function weatherMatches(selected, live)
    local sk = nameKey(selected)
    local lk = nameKey(live)
    if sk == "" or lk == "" then return false end
    return sk == lk
end

local function phaseMatches(selected, live)
    local sk = nameKey(selected)
    local lk = nameKey(live)
    if sk == "" or lk == "" then return false end
    return sk == lk
end

local function activeWeather()
    return Workspace:GetAttribute("ActiveWeather")
end

local function activePhase()
    return Workspace:GetAttribute("ActivePhase")
end

local function weatherMatchesAny(weathers, live)
    if type(weathers) ~= "table" or #weathers == 0 then return false end
    live = liveStr(live)
    if live == "" then return false end
    for _, selected in ipairs(weathers) do
        if weatherMatches(selected, live) then
            return true
        end
    end
    return false
end

local function readMapWeatherPlaying(name)
    name = tostring(name or "")
    if name == "" then return false end

    local GAG2 = G.GAG2_WEATHER or rawget(_G, "GAG2_WEATHER")
    if type(GAG2) == "table" and type(GAG2.readMap) == "function" then
        local ok, row = pcall(GAG2.readMap, name)
        if ok and type(row) == "table" and row.playing == true then
            return true
        end
    end

    local WP = getWeatherPredict()
    if type(WP) == "table" and type(WP.IsWeatherLive) == "function" then
        local ok, hit, source = pcall(function()
            return WP:IsWeatherLive(name)
        end)
        if ok and hit == true then
            return true
        end
    end

    local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
    if WeatherValues and WeatherValues:GetAttribute(name .. "_Playing") == true then
        return true
    end
    return false
end

local function isSelectedWeatherLive(selectedName)
    selectedName = tostring(selectedName or "")
    if selectedName == "" then return false, nil end

    local WP = getWeatherPredict()
    if type(WP) == "table" and type(WP.IsWeatherLive) == "function" then
        local ok, live, source = pcall(function()
            return WP:IsWeatherLive(selectedName)
        end)
        if ok and live == true then
            return true, source or selectedName
        end
    end

    local liveWeather = activeWeather()
    if weatherMatches(selectedName, liveWeather or "") then
        return true, liveWeather
    end

    if readMapWeatherPlaying(selectedName) then
        return true, selectedName
    end

    return false, nil
end

local function weatherMatchesAnySelected(weathers)
    if type(weathers) ~= "table" or #weathers == 0 then return false, nil end
    for _, selected in ipairs(weathers) do
        local hit, source = isSelectedWeatherLive(selected)
        if hit then
            return true, source
        end
    end
    return false, nil
end

local function getLiveMapWeatherNames()
    local WP = getWeatherPredict()
    if type(WP) == "table" and type(WP.GetLiveMapWeathers) == "function" then
        local ok, list = pcall(WP.GetLiveMapWeathers, WP)
        if ok and type(list) == "table" then
            return list
        end
    end

    local out = {}
    local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
    if not WeatherValues then return out end
    for attrName in pairs(WeatherValues:GetAttributes()) do
        if type(attrName) == "string" then
            local base = attrName:match("^(.+)_Playing$")
            if base and WeatherValues:GetAttribute(attrName) == true then
                out[#out + 1] = base
            end
        end
    end
    table.sort(out)
    return out
end

local function phaseMatchesAny(cycles, live)
    if type(cycles) ~= "table" or #cycles == 0 then return false end
    live = liveStr(live)
    if live == "" then return false end
    for _, selected in ipairs(cycles) do
        if phaseMatches(selected, live) then
            return true
        end
    end
    return false
end

local function serverNow()
    local ok, t = pcall(function()
        return Workspace:GetServerTimeNow()
    end)
    if ok and type(t) == "number" then return t end
    return os.time()
end

local function weatherConfigDuration(name)
    name = tostring(name or "")
    if name == "" then return nil end

    local WP = getWeatherPredict()
    if type(WP) == "table" and type(WP.GetWeatherDuration) == "function" then
        -- Jangan pass WP sebagai arg pertama: GetWeatherDuration(name), bukan method self
        local ok, sec = pcall(WP.GetWeatherDuration, name)
        if (not ok or type(sec) ~= "number" or sec <= 0) then
            ok, sec = pcall(WP.GetWeatherDuration, WP, name)
        end
        if ok and type(sec) == "number" and sec > 0 then
            return math.floor(sec)
        end
    end

    local SM = ReplicatedStorage:FindFirstChild("SharedModules")
    local wdInst = SM and SM:FindFirstChild("WeatherData")
    if not wdInst then return nil end
    local ok, wd = pcall(require, wdInst)
    if not ok or type(wd) ~= "table" or type(wd.Data) ~= "table" then return nil end

    local key = nameKey(name)
    local function entryDur(entry)
        if type(entry) ~= "table" then return nil end
        local d = tonumber(entry.Lasts or entry.Last or entry.Duration or entry.Length)
        if d and d > 0 then return math.floor(d) end
        return nil
    end

    if wd.Data[1] then
        for _, entry in ipairs(wd.Data) do
            if type(entry) == "table" and nameKey(entry.Name) == key then
                return entryDur(entry)
            end
        end
    else
        for wName, entry in pairs(wd.Data) do
            local n = (type(entry) == "table" and entry.Name) or wName
            if nameKey(n) == key then
                return entryDur(entry)
            end
        end
    end
    return nil
end

local function weatherLiveRemaining(name)
    name = tostring(name or "")
    if name == "" then return nil end
    local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
    if not WeatherValues then return nil end
    if WeatherValues:GetAttribute(name .. "_Playing") ~= true then return nil end

    local t = serverNow()
    local startTime = WeatherValues:GetAttribute(name .. "_StartTime")
    local duration = tonumber(WeatherValues:GetAttribute(name .. "_Duration"))
    local endTime = WeatherValues:GetAttribute(name .. "_EndTime")

    if type(startTime) == "number" and startTime > 1e9 and type(duration) == "number" and duration > 0 then
        return math.max(1, math.floor((startTime + duration) - t))
    end
    if type(endTime) == "number" and endTime > 1e9 then
        return math.max(1, math.floor(endTime - t))
    end
    if type(duration) == "number" and duration > 0 then
        return math.floor(duration)
    end
    return nil
end

-- delay cfg 0 → pakai durasi weather dari list/config (sama seperti label di UI);
-- sisa live hanya fallback kalau config tidak ketemu
local function resolveRejoinDelay(cfgDelay, weatherName)
    cfgDelay = clampDelay(cfgDelay)
    if cfgDelay > 0 then
        return cfgDelay, "fixed"
    end

    local cfg = weatherConfigDuration(weatherName)
    if cfg and cfg > 0 then
        return math.min(600, cfg), "weather_duration"
    end

    local rem = weatherLiveRemaining(weatherName)
    if rem and rem > 0 then
        return math.min(600, rem), "live_remaining"
    end

    return FALLBACK_AUTO_DELAY, "fallback"
end

local function hideDisconnectPrompt()
    if not shouldHideKickPrompt() then return end
    pcall(function()
        GuiService:ClearError()
    end)

    pcall(function()
        local gui = CoreGui:FindFirstChild("RobloxPromptGui")
        if not gui then return end
        gui.Enabled = false
        for _, v in ipairs(gui:GetDescendants()) do
            if v:IsA("GuiObject") then
                v.Visible = false
            end
        end
    end)
    clearKickBlur()
end

local function startAntiPrompt()
    if not shouldHideKickPrompt() then return end
    if G.__WEATHER_KICK_ANTI_PROMPT == true then return end
    G.__WEATHER_KICK_ANTI_PROMPT = true
    task.spawn(function()
        while shouldHideKickPrompt() do
            hideDisconnectPrompt()
            task.wait(0.05)
        end
        G.__WEATHER_KICK_ANTI_PROMPT = nil
    end)
end

local function doKick(reason, weatherName)
    reason = tostring(reason or "weather")
    weatherName = tostring(weatherName or activeWeather() or "")
    local _, _, _, cfgDelay = getCfg()
    cfgDelay = clampDelay(cfgDelay)
    local delay, delaySource = resolveRejoinDelay(cfgDelay, weatherName)
    local hidePrompt = shouldHideKickPrompt()

    dprint("KICK NOW:", reason, "| cfgDelay=", cfgDelay, "| effective=", delay, "(" .. delaySource .. ")")

    G.__WEATHER_KICK_REJOIN_PENDING = true
    _G.__WEATHER_KICK_REJOIN_PENDING = true
    -- delay efektif untuk PSReconnect (cfg 0 tetap tersimpan di MAIN)
    G.__WEATHER_KICK_PENDING_DELAY = delay
    _G.__WEATHER_KICK_PENDING_DELAY = delay
    G.__WEATHER_KICK_PENDING_WEATHER = weatherName
    _G.__WEATHER_KICK_PENDING_WEATHER = weatherName

    -- Signal monitor before Kick: script still alive, intentional weather kick / rejoin.
    pcall(function()
        local send = G.NodeHubWS_SendStats or _G.NodeHubWS_SendStats
        if type(send) ~= "function" and type(G.NodeHubWS) == "table" then
            send = G.NodeHubWS.SendStats
        end
        if type(send) == "function" then
            send(nil, "weather_kick", {
                status = "offline",
                reason = "weather_kick",
            })
        end
    end)

    if hidePrompt then
        startAntiPrompt()
        hideDisconnectPrompt()
        task.wait(0.15)
        hideDisconnectPrompt()
    end

    -- kalau hide prompt ON: kick kosong; kalau OFF: tampilkan keterangan
    local msg = ""
    if not hidePrompt then
        msg = string.format(
            "WeatherKick: %s | rejoin %ds%s",
            reason,
            delay,
            (cfgDelay == 0) and " (auto weather)" or ""
        )
    end

    local ok, err = pcall(function()
        LP:Kick(msg)
    end)

    if not ok then
        dprint("Kick failed:", tostring(err))
        G.__WEATHER_KICK_REJOIN_PENDING = nil
        _G.__WEATHER_KICK_REJOIN_PENDING = nil
        G.__WEATHER_KICK_PENDING_DELAY = nil
        _G.__WEATHER_KICK_PENDING_DELAY = nil
    end

    if hidePrompt then
        task.defer(hideDisconnectPrompt)
        task.delay(0.2, hideDisconnectPrompt)
        task.delay(0.5, hideDisconnectPrompt)
    end
    return ok
end

local function tryKickForMatch()
    if M._kickBusy then return end

    local enabled, weathers = getCfg()
    if not enabled then return end
    if #weathers == 0 then return end

    local weatherHit, matchSource = weatherMatchesAnySelected(weathers)
    if not weatherHit then return end

    M._kickBusy = true
    local reason = "weather match: " .. tostring(matchSource or activeWeather())
    dprint("Match:", selectionToText(weathers), "~", reason)
    dprint("Match disconnect:", reason, "| selected:", selectionToText(weathers))
    doKick(reason, matchSource or activeWeather())

    task.delay(120, function()
        M._kickBusy = false
    end)
end

function M.GetWeatherOptions()
    local WP = getWeatherPredict()
    if type(WP) == "table" and type(WP.GetKickTargetOptions) == "function" then
        local ok, items = pcall(WP.GetKickTargetOptions, WP)
        if ok and type(items) == "table" and #items > 0 then
            return items
        end
    end
    if type(WP) == "table" and type(WP.GetWeatherOptions) == "function" then
        local ok, items = pcall(WP.GetWeatherOptions, WP)
        if ok and type(items) == "table" and #items > 0 then
            return items
        end
    end
    return {}
end

function M.GetStatus()
    local enabled, weathers, _, delay = getCfg()
    local liveWeather = activeWeather()
    local livePhase = activePhase()
    local liveMap = getLiveMapWeatherNames()
    local weatherHit, matchSource = weatherMatchesAnySelected(weathers)
    local previewWeather = matchSource or (weathers and weathers[1]) or liveWeather
    local effectiveDelay, delaySource = resolveRejoinDelay(delay, previewWeather)
    return {
        enabled = enabled,
        selected = weathers,
        selected_weathers = weathers,
        selected_cycles = {},
        selected_text = selectionToText(weathers),
        live = matchSource or liveWeather,
        live_weather = liveWeather,
        live_map = liveMap,
        live_phase = livePhase,
        live_weather_type = typeof(liveWeather),
        live_phase_type = typeof(livePhase),
        matched = weatherHit,
        matched_weather = weatherHit,
        matched_source = matchSource,
        matched_phase = false,
        rejoin_delay_sec = delay,
        rejoin_delay_auto = (delay == 0),
        rejoin_delay_effective = effectiveDelay,
        rejoin_delay_source = delaySource,
        hide_kick_prompt = (M.HIDE_KICK_PROMPT == true),
        running = M._running == true,
        kickBusy = M._kickBusy == true,
    }
end

local function jsonList(t)
    if type(t) ~= "table" then return "[]" end
    local parts = {}
    for i, v in ipairs(t) do
        parts[i] = string.format("%q", tostring(v))
    end
    return "[" .. table.concat(parts, ", ") .. "]"
end

function M.DebugDump(opts)
    opts = type(opts) == "table" and opts or {}
    local st = M.GetStatus()
    local lines = {
        "=== WeatherKick Debug ===",
        "module_ver=" .. tostring(MODULE_VER),
        "running=" .. tostring(st.running),
        "enabled=" .. tostring(st.enabled),
        "kickBusy=" .. tostring(st.kickBusy),
        "selected_text=" .. tostring(st.selected_text),
        "weathers=" .. jsonList(st.selected_weathers),
        "cycles=" .. jsonList(st.selected_cycles),
        "live_phase=" .. tostring(st.live_phase) .. " (" .. tostring(st.live_phase_type) .. ")",
        "live_weather=" .. tostring(st.live_weather) .. " (" .. tostring(st.live_weather_type) .. ")",
        "live_map=" .. jsonList(st.live_map),
        "matched_source=" .. tostring(st.matched_source),
        "matched=" .. tostring(st.matched),
        "matched_phase=" .. tostring(st.matched_phase),
        "matched_weather=" .. tostring(st.matched_weather),
        "rejoin_delay_sec=" .. tostring(st.rejoin_delay_sec),
    }
    if type(st.selected_cycles) == "table" and st.selected_cycles[1] ~= nil then
        lines[#lines + 1] = "phase_key="
            .. nameKey(st.selected_cycles[1]) .. " vs " .. nameKey(st.live_phase)
    end
    if type(st.selected_weathers) == "table" and st.selected_weathers[1] ~= nil then
        lines[#lines + 1] = "weather_key="
            .. nameKey(st.selected_weathers[1]) .. " vs " .. nameKey(st.live_weather)
    end
    lines[#lines + 1] = "WEATHER_KICK_ENABLED=" .. tostring(G.WEATHER_KICK_ENABLED)
    lines[#lines + 1] = "WEATHER_KICK_SELECTED=" .. jsonList(G.WEATHER_KICK_SELECTED)
    lines[#lines + 1] = "WEATHER_KICK_CYCLES=" .. jsonList(G.WEATHER_KICK_CYCLES)
    lines[#lines + 1] = "WEATHER_KICK_WEATHERS=" .. jsonList(G.WEATHER_KICK_WEATHERS)
    local main = G.MAIN or _G.MAIN
    if type(main) == "table" and type(main.misc) == "table"
        and type(main.misc.rejoin) == "table"
        and type(main.misc.rejoin.weather_kick) == "table" then
        local wk = main.misc.rejoin.weather_kick
        lines[#lines + 1] = "MAIN.selected=" .. jsonList(wk.selected)
        lines[#lines + 1] = "MAIN.enabled=" .. tostring(wk.enabled)
    end
    for _, line in ipairs(lines) do
        if opts.warn == true then
            warn(line)
        else
            print(line)
        end
    end
    if opts.testKick == true then
        warn("[WeatherKick] testKick — manual kick")
        M.KickNow("debug_testKick")
    end
    return st
end

G.GAG2DebugWeatherKick = function(opts) return M.DebugDump(opts) end
_G.GAG2DebugWeatherKick = G.GAG2DebugWeatherKick

function M.KickNow(reason)
    return doKick(reason or "manual")
end

function M.IsRunning()
    return M._running == true
end

function M.Apply(selfOrEnabled, maybeEnabled, maybeSelection, maybeDelay)
    local enabled, selection, delay
    local forcedEnabled = nil

    if selfOrEnabled == M then
        enabled = maybeEnabled
        selection = maybeSelection
        delay = maybeDelay
        if maybeEnabled ~= nil then
            forcedEnabled = truthy(maybeEnabled)
        end
    else
        enabled = selfOrEnabled
        selection = maybeEnabled
        delay = maybeSelection
        if selfOrEnabled ~= nil then
            forcedEnabled = truthy(selfOrEnabled)
        end
    end

    if enabled ~= nil then
        enabled = truthy(enabled)
        G.WEATHER_KICK_ENABLED = enabled
        _G.WEATHER_KICK_ENABLED = enabled
    end

    if selection ~= nil then
        local weathers, selectedKeys
        if type(selection) == "table" and selection[1] ~= nil then
            selectedKeys = selection
            weathers = select(1, splitSelectedKeys(selection))
        elseif type(selection) == "table" and type(selection.selected) == "table" then
            selectedKeys = selection.selected
            weathers = select(1, splitSelectedKeys(selection.selected))
        else
            weathers = normalizeWeathers(selection)
            selectedKeys = selectedKeysFromWeathers(weathers)
        end
        publishGlobals(
            forcedEnabled ~= nil and forcedEnabled or (G.WEATHER_KICK_ENABLED == true),
            weathers,
            G.WEATHER_KICK_REJOIN_DELAY_SEC or 60,
            selectedKeysFromWeathers(weathers)
        )
    end
    if delay ~= nil then
        delay = clampDelay(delay)
        G.WEATHER_KICK_REJOIN_DELAY_SEC = delay
        _G.WEATHER_KICK_REJOIN_DELAY_SEC = delay
    end

    enabled, weathers, _, delay = getCfg()
    if forcedEnabled ~= nil then
        enabled = forcedEnabled
    end
    local selectedKeys = selectedKeysFromWeathers(weathers)
    publishGlobals(enabled, weathers, delay, selectedKeys)
    G.__WEATHER_KICK_SAVED = {
        enabled = enabled,
        selected = selectedKeys,
        rejoin_delay_sec = delay,
    }

    if enabled then
        M._ensureRunning()
    elseif M._running then
        M.Stop("disabled")
    end
end

function M.SetEnabled(on)
    M.Apply((on == true), {
        weathers = G.WEATHER_KICK_WEATHERS or G.WEATHER_KICK_SELECTED,
    }, G.WEATHER_KICK_REJOIN_DELAY_SEC)
end

local function disconnectSignal(conn)
    if conn then
        pcall(function() conn:Disconnect() end)
    end
end

function M._ensureRunning()
    if M._running then
        -- already polling; still check immediately after config change
        task.defer(tryKickForMatch)
        return
    end
    M._running = true
    M._kickBusy = false

    dprint("Started")

    disconnectSignal(M._weatherConn)
    disconnectSignal(M._phaseConn)
    disconnectSignal(M._mapConn)
    M._weatherConn = nil
    M._phaseConn = nil
    M._mapConn = nil

    pcall(function()
        M._weatherConn = Workspace:GetAttributeChangedSignal("ActiveWeather"):Connect(function()
            task.defer(tryKickForMatch)
        end)
    end)

    -- Jangan WaitForChild di thread boot (bisa nahan/freeze sampai 10s).
    -- Bind WeatherValues di background, retry singkat kalau belum ada.
    task.spawn(function()
        local WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
        if not WeatherValues then
            for _ = 1, 20 do
                if M._running ~= true then return end
                task.wait(0.25)
                WeatherValues = ReplicatedStorage:FindFirstChild("WeatherValues")
                if WeatherValues then break end
            end
        end
        if not WeatherValues or M._running ~= true then return end
        disconnectSignal(M._mapConn)
        M._mapConn = WeatherValues.AttributeChanged:Connect(function()
            task.defer(tryKickForMatch)
        end)
    end)

    M._thread = task.spawn(function()
        task.wait(2)
        tryKickForMatch()
        while M._running do
            tryKickForMatch()
            task.wait(2)
        end
    end)
end

function M.Start()
    local enabled = select(1, getCfg())
    if enabled ~= true then
        dprint("Start aborted: disabled")
        return
    end
    M._ensureRunning()
end

function M.Stop(reason)
    if M._running ~= true then return end
    M._running = false
    M._thread = nil
    disconnectSignal(M._weatherConn)
    disconnectSignal(M._phaseConn)
    disconnectSignal(M._mapConn)
    M._weatherConn = nil
    M._phaseConn = nil
    M._mapConn = nil
    dprint("Stop:", tostring(reason or "manual"))
end

function M.SyncFromState()
    M.Apply()
end

M.syncFromGlobals = M.SyncFromState

G.WeatherKick = M
_G.WeatherKick = M

return M
 end,                  required = false, early = true },
