-- ReduceFPS sudah urus garden → jangan scan/strip ulang (itu yang bikin "gak guna"/CPU buang)
local function reduceFpsOwnsGarden()
    if G.REMOVE_GARDEN_ACTIVE == true or rawget(_G, "REMOVE_GARDEN_ACTIVE") == true then
        return true
    end
    if G.REDUCE_FPS_ENABLED == true or rawget(_G, "REDUCE_FPS_ENABLED") == true then
        return true
    end
    local mod = G.ReduceFPS or rawget(_G, "ReduceFPS")
    if type(mod) == "table" and type(mod.IsEnabled) == "function" then
        local ok, on = pcall(mod.IsEnabled, mod)
        if ok and on then return true end
    end
    return false
end

-- AutoCollect sedang fire → jangan GetDescendants plot (saingi frame = collect putus).
local function autoCollectBusy()
    local AC = G.AutoCollect or rawget(_G, "AutoCollect")
    if type(AC) == "table" and type(AC.IsRunning) == "function" then
        local ok, on = pcall(AC.IsRunning, AC)
        if ok and on == true then return true end
    end
    return false
end

-- Sprinkler radius sejati di garden (bukan soil/plot flat part)
local function isExplicitSprinklerRadius(inst)
    if not inst then return false end
    local n = string.lower(tostring(inst.Name or ""))
    return n == "sprinklerradius"
        or n:find("sprinklerradius", 1, true) ~= nil
        or n == "radiusring"
        or n:find("rangeradius", 1, true) ~= nil
end

local function isGardenDecorName(name)
    if not name then return false end
    if GARDEN_DECOR_EXACT[name] == true then return true end
    if FX_NAME_EXACT[name] == true then return true end
    local lower = string.lower(tostring(name))
    -- exact-ish dekor; hindari "plant" / "fruit" / "harvest"
    if lower == "leaf" or lower == "claw" or lower == "fireleaf"
        or lower == "petal" or lower == "thorn" then
        return true
    end
    if lower:find("movingtexture", 1, true) or lower:find("dragonfire", 1, true) then
        return true
    end
    return false
end

local function safeDestroy(inst)
    if not inst or not inst.Parent then return false end
    if isWateringCanProtected(inst) then return false end
    -- Gardens: blok Destroy struktural; izinkan dekor Leaf/Claw + sprinkler radius
    if isUnderGardens(inst) and (inst:IsA("BasePart") or inst:IsA("Model") or inst:IsA("Folder")) then
        if isExplicitSprinklerRadius(inst) or isGardenDecorName(inst.Name) then
            -- ok destroy dekor
        else
            return false
        end
    end
    return pcall(function() inst:Destroy() end) == true
end

-- Yield helper (shared counter per pass)
local function makeYielder()
    local n = 0
    local t0 = os.clock()
    return function()
        n += 1
        if n >= STRIP_BATCH or (os.clock() - t0) >= STRIP_SLICE_SEC then
            n = 0
            t0 = os.clock()
            task.wait()
        end
    end
end

-- Matikan FX dulu biar GPU langsung hemat, baru Destroy
local function killFx(inst)
    if not inst or not inst.Parent then return false end
    pcall(function()
        if inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")
            or inst:IsA("Fire") or inst:IsA("Smoke") or inst:IsA("Sparkles") then
            inst.Enabled = false
        elseif inst:IsA("Light") then
            inst.Enabled = false
        elseif inst:IsA("Highlight") or inst:IsA("SelectionBox") then
            inst.Enabled = false
        end
    end)
    return safeDestroy(inst)
end

local function isProtectedName(name)
    return PROTECT_NAME[name] == true
end

-- Legacy name — weather VFX sekarang BOLEH di-strip (mutasi Eclipse lewat network, bukan mesh sky).
local function isEclipseWeatherVfx(_inst)
    return false
end

local function isWeatherNamed(name)
    if not name then return false end
    if WEATHER_NAME_EXACT[name] == true then return true end
    local lower = string.lower(tostring(name))
    for _, needle in ipairs(WEATHER_NAME_CONTAINS) do
        if string.find(lower, needle, 1, true) then
            return true
        end
    end
    return false
end

local function isUnderWeatherRoot(inst)
    if not inst then return false end
    local node = inst
    for _ = 1, 10 do
        if not node or node == Workspace then break end
        if isWeatherNamed(node.Name) then return true end
        node = node.Parent
    end
    return false
end

local function nameIsFx(name)
    local lower = string.lower(tostring(name or ""))
    if lower:find("wateringcan", 1, true) then
        return false
    end
    if FX_NAME_EXACT[name] then return true end
    for _, needle in ipairs(FX_NAME_CONTAINS) do
        if string.find(lower, needle, 1, true) then
            return true
        end
    end
    return false
end

local function isNodeHubHost(inst)
    if not inst then return false end
    local n = tostring(inst.Name or "")
    if n == "NodeHubLoadingHost" or n == "NodeHubHostGui" then
        return true
    end
    local okAttr, marked = pcall(function()
        return inst:GetAttribute("GAG2HubHost") == true
    end)
    if okAttr and marked then
        return true
    end
    local ok, anc = pcall(function()
        return inst:FindFirstAncestor("NodeHubLoadingHost") ~= nil
            or (inst:FindFirstAncestorWhichIsA("BasePart")
                and inst:FindFirstAncestorWhichIsA("BasePart"):GetAttribute("GAG2HubHost") == true)
    end)
    return ok and anc == true
end

-- Loading screen game (Workspace.LoadingScreenMenu) — flat disc + ProgressBar.
-- JANGAN strip/Destroy: false-positive sprinkler radius → error "Bar is not a valid member of ProgressBar".
local function isLoadingScreenGui(inst)
    if not inst then return false end
    local n = tostring(inst.Name or "")
    if n == "LoadingScreenMenu" or n == "ProgressBar" or n == "LoadingGui" then
        return true
    end
    local ok, hit = pcall(function()
        return inst:FindFirstAncestor("LoadingScreenMenu") ~= nil
            or inst:FindFirstAncestor("LoadingGui") ~= nil
    end)
    return ok and hit == true
end

-- Lingkaran range sprinkler / gear (sering di Character saat equip)
local function isSprinklerRangeVisual(inst)
    if not inst then return false end
    if isNodeHubHost(inst) then return false end
    if isLoadingScreenGui(inst) then return false end
    if isWateringCanProtected(inst) then return false end
    -- Tanah/plot/plant di Gardens MIRIP flat disc — JANGAN pakai heuristic size di sini
    if isUnderGardens(inst) then
        return isExplicitSprinklerRadius(inst)
    end

    local n = tostring(inst.Name or "")
    local lower = string.lower(n)
    if n == "SprinklerRadius" or lower:find("sprinklerradius", 1, true) then
        return true
    end
    -- "Radius" sendirian terlalu generic (bisa nama part plot) — hanya di tool/character
    if lower == "radius" or lower:find("radiusring", 1, true) or lower:find("rangeindicator", 1, true)
        or lower:find("rangepreview", 1, true) or lower:find("placementradius", 1, true)
        or lower:find("gearradius", 1, true) or lower:find("coverageradius", 1, true) then
        return true
    end

    -- flat disc heuristic: HANYA di luar Gardens (tool / Temporary / character)
    if inst:IsA("BasePart") then
        local ok, size = pcall(function() return inst.Size end)
        if ok and size then
            local sx, sy, sz = size.X, size.Y, size.Z
            local mx = math.max(sx, sy, sz)
            local mn = math.min(sx, sy, sz)
            local mid = sx + sy + sz - mx - mn
            if mx >= 8 and mid >= 8 and mn <= 2 then
                local tr = 0
                pcall(function() tr = inst.Transparency end)
                if tr >= 0.15 or (inst.Material == Enum.Material.ForceField)
                    or (inst.Material == Enum.Material.Neon)
                    or (inst.Material == Enum.Material.Glass) then
                    -- wajib di bawah sprinkler tool / ClientHandle
                    local p = inst.Parent
                    for _ = 1, 6 do
                        if not p then break end
                        if p:IsA("Tool") and (p:GetAttribute("Sprinkler") ~= nil
                            or string.lower(tostring(p.Name or "")):find("sprinkler", 1, true)) then
                            return true
                        end
                        if p:GetAttribute("ClientHandle") == true then
                            return true
                        end
                        local pn = string.lower(tostring(p.Name or ""))
                        if pn:find("sprinkler", 1, true) or pn == "build" or pn == "handle" then
                            if mx >= 10 then return true end
                        end
                        p = p.Parent
                    end
                end
            end
        end
    end
    return false
end

-- JANGAN destroy Handle/Build — HeldHandleSelfHeal akan clone ulang (lebih lag)
local function isSprinklerHandleRoot(inst)
    if not inst then return false end
    if inst:GetAttribute("ClientHandle") == true then
        local n = tostring(inst.Name or "")
        return n == "Handle" or n == "Build"
    end
    return false
end

local function killSprinklerRange(inst)
    if not inst or not inst.Parent then return false end
    if isNodeHubHost(inst) then return false end
    if isLoadingScreenGui(inst) then return false end
    if isWateringCanProtected(inst) then return false end
    if isSprinklerHandleRoot(inst) then
        -- strip isi radius saja, biarkan Handle hidup
        local killed = false
        for _, d in ipairs(inst:GetDescendants()) do
            if isSprinklerRangeVisual(d) and not isWateringCanProtected(d) then
                pcall(function() d:Destroy() end)
                killed = true
                bump("sprinkler_range")
            end
        end
        return killed
    end

    -- nuke part radius (bukan Handle)
    for _, d in ipairs(inst:GetDescendants()) do
        if isWateringCanProtected(d) then
            -- skip
        elseif d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail")
            or d:IsA("Decal") or d:IsA("Texture") or d:IsA("Light") then
            pcall(function() d:Destroy() end)
        end
    end
    if safeDestroy(inst) then
        bump("sprinkler_range")
        return true
    end
    pcall(function()
        if inst:IsA("BasePart") then
            inst.Transparency = 1
            inst.LocalTransparencyModifier = 1
            inst.CanCollide = false
            inst.CanQuery = false
            inst.CastShadow = false
            inst.Size = Vector3.new(0.05, 0.05, 0.05)
            bump("sprinkler_range_hide")
        end
    end)
    return true
end

local function disableToolVfx(root)
    if not root then return end
    for _, d in ipairs(root:GetDescendants()) do
        if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam")
            or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") or d:IsA("Light") then
            pcall(function() d.Enabled = false end)
            bump("sprinkler_vfx_off")
        elseif d:IsA("Decal") or d:IsA("Texture") then
            pcall(function() d.Transparency = 1 end)
        end
    end
end

local ATTR_STRIPPED = "_GAG2RL_SprStrip"

local function stripSprinklerTool(tool)
    if not tool or not tool:IsA("Tool") then return end
    if tool:GetAttribute("Sprinkler") == nil then
        local n = string.lower(tostring(tool.Name or ""))
        if not n:find("sprinkler", 1, true) then return end
    end

    -- Hanya bunuh radius + matikan VFX sekali; jangan GetDescendants 3x tiap heartbeat
    local function killRadiusNamed(root)
        for _, name in ipairs({ "SprinklerRadius", "RadiusRing", "RangeIndicator", "RangePreview" }) do
            local hit = root:FindFirstChild(name, true)
            if hit and not isSprinklerHandleRoot(hit) then
                killSprinklerRange(hit)
            end
        end
    end
    killRadiusNamed(tool)

    -- VFX sekali (mark biar heartbeat murah)
    if tool:GetAttribute(ATTR_STRIPPED) ~= true then
        pcall(function() tool:SetAttribute(ATTR_STRIPPED, true) end)
        disableToolVfx(tool)
        for _, d in ipairs(tool:GetDescendants()) do
            if isSprinklerRangeVisual(d) and not isSprinklerHandleRoot(d) then
                killSprinklerRange(d)
            end
        end
    end
end

-- Bersihkan TEMPLATE di RS (one-shot, tanpa live hook)
local function stripSprinklerAssetTemplates()
    local RS = game:GetService("ReplicatedStorage")
    local assets = RS:FindFirstChild("Assets")
    local folder = assets and assets:FindFirstChild("Sprinklers")
    if not folder then
        bump("sprinkler_assets_missing")
        return
    end

    local function cleanRoot(root)
        disableToolVfx(root)
        local list = root:GetDescendants()
        for i = #list, 1, -1 do
            local d = list[i]
            if isSprinklerRangeVisual(d) then
                pcall(function() d:Destroy() end)
                bump("sprinkler_asset_radius")
            elseif d:IsA("MeshPart") then
                pcall(function()
                    if d.TextureID ~= "" then d.TextureID = "" end
                    d.CastShadow = false
                end)
            elseif d:IsA("Decal") or d:IsA("Texture") then
                pcall(function() d:Destroy() end)
            end
        end
        if isSprinklerRangeVisual(root) then
            pcall(function() root:Destroy() end)
            bump("sprinkler_asset_radius")
        end
    end

    for _, child in ipairs(folder:GetChildren()) do
        cleanRoot(child)
    end
    bump("sprinkler_assets_cleaned")
end

----------------------------------------------------------------
-- config from MAIN / globals
----------------------------------------------------------------
local function _cfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local perf = MAIN and MAIN.misc and MAIN.misc.perf
    perf = type(perf) == "table" and perf or {}

    local enabled = (G.REDUCE_LAG_ENABLED == true)
        or (rawget(_G, "REDUCE_LAG_ENABLED") == true)
        or (perf.reduce_lag == true)

    return { enabled = enabled == true }
end

----------------------------------------------------------------
-- lighting / terrain / quality
----------------------------------------------------------------
local function optimizeLighting()
    pcall(function() Lighting.GlobalShadows = false end)
    pcall(function()
        if Lighting.Technology ~= Enum.Technology.Compatibility then
            Lighting.Technology = Enum.Technology.Compatibility
        end
    end)
    pcall(function()
        Lighting.EnvironmentDiffuseScale = 0
        Lighting.EnvironmentSpecularScale = 0
        Lighting.Brightness = math.min(Lighting.Brightness, 1)
        Lighting.FogEnd = 1e9
        Lighting.FogStart = 0
    end)
    for _, child in ipairs(Lighting:GetChildren()) do
        local className = child.ClassName
        if LIGHTING_WEATHER_KEEP[className] then
            -- Sky: jangan Destroy (Parent locked)
            continue
        end
        if className == "Clouds" then
            -- matikan awan weather (Rain/Aurora/Eclipse sky) — jangan Destroy
            pcall(function()
                child.Enabled = false
                child.Cover = 0
                child.Density = 0
            end)
            bump("clouds_off")
            continue
        end
        if LIGHTING_FX_CLASSES[className] then
            if safeDestroy(child) then bump("lighting_fx") end
        elseif child:IsA("PostEffect") then
            pcall(function() child.Enabled = false end)
            if safeDestroy(child) then bump("lighting_fx") end
        end
    end
    bump("lighting")
end

local function optimizeTerrain()
    if not Terrain then return end
    pcall(function()
        Terrain.Decoration = false
        Terrain.WaterWaveSize = 0
        Terrain.WaterWaveSpeed = 0
        Terrain.WaterReflectance = 0
        Terrain.WaterTransparency = 1
    end)
    bump("terrain")
end

local function optimizeQuality()
    pcall(function()
        if typeof(settings) == "function" then
            local ren = settings().Rendering
            if ren then
                pcall(function() ren.QualityLevel = Enum.QualityLevel.Level01 end)
                pcall(function() ren.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level01 end)
            end
        end
    end)
    bump("quality")
end

-- Strip VFX weather (Rain/Snow/Lightning/Starfall/Aurora/Eclipse sky/dll)
local function stripWeatherVisuals()
    pcall(optimizeLighting)

    local function nukeFxTree(root)
        if not root or not root.Parent then return end
        if isUnderGardens(root) then return end
        if isLoadingScreenGui(root) or isNodeHubHost(root) then return end
        local list = root:GetDescendants()
        local yield = makeYielder()
        for i = #list, 1, -1 do
            if not running then return end
            local d = list[i]
            local cls = d.ClassName
            if DESTROY_CLASSES[cls]
                or cls == "ParticleEmitter" or cls == "Beam" or cls == "Trail"
                or cls == "Fire" or cls == "Smoke" or cls == "Sparkles"
                or cls == "Highlight" or cls == "BillboardGui" or cls == "SurfaceGui" then
                if killFx(d) then bump("weather_fx") end
            elseif FLATTEN_CLASSES[cls] then
                pcall(function()
                    d.Transparency = 1
                    d.LocalTransparencyModifier = 1
                    d.CastShadow = false
                    d.CanCollide = false
                    d.CanQuery = false
                    d.Anchored = true
                    if d:IsA("MeshPart") then d.TextureID = "" end
                end)
                bump("weather_hide")
            end
            yield()
        end
        -- root weather folder/model: buang total kalau aman
        if (root:IsA("Model") or root:IsA("Folder") or root:IsA("BasePart"))
            and isWeatherNamed(root.Name)
            and root.Parent == Workspace then
            if safeDestroy(root) then bump("weather_root") end
        end
    end

    for _, root in ipairs(Workspace:GetChildren()) do
        if root == getGardensFolder() then continue end
        if isLoadingScreenGui(root) then continue end
        if isWeatherNamed(root.Name) then
            nukeFxTree(root)
        elseif root.Name == "Temporary" or root.Name == "Effects" or root.Name == "FX"
            or root.Name == "VFX" or root.Name == "Debris" then
            -- isi Temporary sering rain/snow drop
            for _, ch in ipairs(root:GetChildren()) do
                if isWeatherNamed(ch.Name) or DESTROY_CLASSES[ch.ClassName] then
                    nukeFxTree(ch)
                    if isWeatherNamed(ch.Name) and safeDestroy(ch) then
                        bump("weather_temp")
                    end
                elseif DESTROY_CLASSES[ch.ClassName] then
                    if killFx(ch) then bump("weather_temp") end
                end
            end
        end
    end

    -- Camera weather particles
    local cam = Workspace.CurrentCamera
    if cam then
        for _, d in ipairs(cam:GetDescendants()) do
            if DESTROY_CLASSES[d.ClassName] or isWeatherNamed(d.Name) then
                if killFx(d) or safeDestroy(d) then bump("weather_cam") end
            end
        end
    end

    bump("weather_strip")
end

----------------------------------------------------------------
-- instance strip
----------------------------------------------------------------
local function shouldSkip(inst, char)
    if not inst or not inst.Parent then return true end
    if isWateringCanProtected(inst) then return true end
    if isLoadingScreenGui(inst) then return true end
    if isEclipseWeatherVfx(inst) then return true end
    -- SELALU boleh bersihin range sprinkler (meski di character sendiri)
    if isSprinklerRangeVisual(inst) or nameIsFx(inst.Name) and (
        tostring(inst.Name) == "SprinklerRadius"
        or string.lower(tostring(inst.Name)):find("sprinkler", 1, true)
        or string.lower(tostring(inst.Name)):find("radius", 1, true)
    ) then
        return false
    end
    if isProtectedName(inst.Name) then return true end
    if inst:IsA("BaseScript") or inst:IsA("ModuleScript") then return true end
    if inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") or inst:IsA("BindableEvent") then
        return true
    end
    if inst:IsA("ProximityPrompt") or inst:IsA("ValueBase") then return true end
    if char and (inst == char or inst:IsDescendantOf(char)) then
        -- character body skip, kecuali range visual (sudah di-handle di atas)
        return true
    end

    local ok, full = pcall(function() return inst:GetFullName() end)
    if ok and type(full) == "string" then
        if full:find("PlayerGui", 1, true) then return true end
        if full:find("PlayerScripts", 1, true) then return true end
        if full:find("ReplicatedStorage", 1, true) then return true end
        if full:find("StarterGui", 1, true) then return true end
        if full:find("CoreGui", 1, true) then return true end
        if full:find("NodeHubLoadingHost", 1, true) then return true end
        if full:find("LoadingScreenMenu", 1, true) then return true end
        if full:find("LoadingGui", 1, true) then return true end
        -- Preview/FX short-lived di Temporary — jangan flatten Part di sini
        if full:find("Temporary", 1, true) and (
            string.lower(tostring(inst.Name)):find("preview", 1, true)
            or string.lower(tostring(inst.Name)):find("watering", 1, true)
        ) then
            return true
        end
    end
    if not inst:IsDescendantOf(Workspace) then return true end
    return false
end

local function processInstance(inst, char)
    if isWateringCanProtected(inst) then return end
    if isNodeHubHost(inst) then return end
    if isLoadingScreenGui(inst) then return end
    if isProtectedName(inst.Name) then return end

    -- Gardens: ReduceFPS owner → skip total (kecuali SprinklerRadius eksplisit)
    if isUnderGardens(inst) then
        if isExplicitSprinklerRadius(inst) then
            killSprinklerRange(inst)
            return
        end
        if reduceFpsOwnsGarden() then
            return
        end
        local cls = inst.ClassName
        -- Dekor Leaf/Claw (Speed Hub style) — Model/Part aman dihancurkan
        if isGardenDecorName(inst.Name) and (inst:IsA("Model") or inst:IsA("BasePart") or DESTROY_CLASSES[cls]) then
            if safeDestroy(inst) or killFx(inst) then
                bump("garden_decor")
            end
            return
        end
        if DESTROY_CLASSES[cls] or nameIsFx(inst.Name) then
            if killFx(inst) then bump("garden_fx") end
            return
        end
        -- Flatten visual (jangan Destroy plant/fruit root)
        if FLATTEN_CLASSES[cls] then
            pcall(function()
                if inst.CastShadow then
                    inst.CastShadow = false
                    bump("garden_shadow")
                end
                if inst.Material ~= Enum.Material.SmoothPlastic then
                    inst.Material = Enum.Material.SmoothPlastic
                    bump("garden_material")
                end
                if inst:IsA("MeshPart") and inst.TextureID ~= "" then
                    inst.TextureID = ""
                    bump("garden_mesh_tex")
                end
            end)
        elseif cls == "SpecialMesh" then
            pcall(function()
                if inst.TextureId ~= "" then
                    inst.TextureId = ""
                    bump("garden_special_tex")
                end
            end)
        end
        return
    end

    -- Weather VFX (Rain/Snow/Eclipse sky/dll) — prioritas tinggi
    if isWeatherNamed(inst.Name) or isUnderWeatherRoot(inst) then
        local cls = inst.ClassName
        if DESTROY_CLASSES[cls] or nameIsFx(inst.Name) or isWeatherNamed(inst.Name) then
            if killFx(inst) or safeDestroy(inst) then bump("weather_live") end
            return
        end
        if FLATTEN_CLASSES[cls] then
            pcall(function()
                inst.Transparency = 1
                inst.LocalTransparencyModifier = 1
                inst.CastShadow = false
            end)
            bump("weather_live")
            return
        end
    end

    if isSprinklerRangeVisual(inst) then
        killSprinklerRange(inst)
        return
    end

    if shouldSkip(inst, char) then return end
    local cls = inst.ClassName

    if nameIsFx(inst.Name) then
        if killFx(inst) then bump("fx_named") end
        return
    end

    if DESTROY_CLASSES[cls] then
        if killFx(inst) then bump("destroy_" .. cls) end
        return
    end

    -- Popup/damage Billboards di dunia (bukan harvest)
    if cls == "BillboardGui" or cls == "SurfaceGui" then
        local n = string.lower(tostring(inst.Name or ""))
        if n:find("damage", 1, true) or n:find("popup", 1, true)
            or n:find("float", 1, true) or n:find("notif", 1, true)
            or n:find("combat", 1, true) then
            if safeDestroy(inst) then bump("world_gui") end
        end
        return
    end

    if cls == "MeshPart" then
        pcall(function()
            if inst.TextureID ~= "" then
                inst.TextureID = ""
                bump("mesh_tex")
            end
            if inst.CastShadow then
                inst.CastShadow = false
                bump("shadow_off")
            end
        end)
    elseif cls == "SpecialMesh" then
        pcall(function()
            if inst.TextureId ~= "" then
                inst.TextureId = ""
                bump("special_tex")
            end
        end)
    end

    if FLATTEN_CLASSES[cls] then
        pcall(function()
            if inst.CastShadow then
                inst.CastShadow = false
                bump("shadow_off")
            end
        end)
        pcall(function()
            if inst.Material ~= Enum.Material.SmoothPlastic then
                inst.Material = Enum.Material.SmoothPlastic
                bump("material")
            end
        end)
    end
end

local function sweepSprinklerRange(root)
    if not root then return end
    if root:IsA("Tool") then
        stripSprinklerTool(root)
        return
    end
    -- tools di character / backpack
    for _, ch in ipairs(root:GetChildren()) do
        if ch:IsA("Tool") then
            stripSprinklerTool(ch)
        end
    end
    local list = root:GetDescendants()
    for i = #list, 1, -1 do
        local inst = list[i]
        if inst:IsA("Tool") then
            stripSprinklerTool(inst)
        elseif isSprinklerRangeVisual(inst) and not isSprinklerHandleRoot(inst) then
            killSprinklerRange(inst)
        end
    end
end

local function stripWorkspace()
    local char = LocalPlayer and LocalPlayer.Character
    if char then sweepSprinklerRange(char) end
    if LocalPlayer and LocalPlayer:FindFirstChild("Backpack") then
        sweepSprinklerRange(LocalPlayer.Backpack)
    end

    -- JANGAN Workspace:GetDescendants() penuh — garden 2–3k plant = CPU spike.
    -- Scan per-child Workspace; skip Gardens saat ReduceFPS aktif.
    -- Yield tiap batch biar tidak freeze.
    local gardens = getGardensFolder()
    -- Skip Gardens saat RF ON ATAU AutoCollect fire (RF OFF + lag strip plot = hitch collect).
    local skipGarden = gardens ~= nil and (reduceFpsOwnsGarden() or autoCollectBusy())
    local yield = makeYielder()

    local function processList(list)
        for i = #list, 1, -1 do
            if not running then return end
            processInstance(list[i], char)
            yield()
        end
    end

    for _, root in ipairs(Workspace:GetChildren()) do
        if not running then return end
        if root == gardens and skipGarden then
            continue
        end
        if root.Name == "LoadingScreenMenu" or root.Name == "LoadingGui" then
            continue
        end
        processInstance(root, char)
        yield()
        -- Gardens: proses per-plot (bukan 1 GetDescendants raksasa)
        if root == gardens and not skipGarden then
            for _, plot in ipairs(root:GetChildren()) do
                if not running then return end
                processInstance(plot, char)
                processList(plot:GetDescendants())
                task.wait() -- jeda antar plot
            end
        else
            processList(root:GetDescendants())
            task.wait() -- jeda antar root Workspace
        end
    end
    bump("world_strip")
end

local function stripOtherCharacters()
    local yield = makeYielder()
    for _, plr in ipairs(Players:GetPlayers()) do
        if not running then return end
        if plr == LocalPlayer then continue end
        local char = plr.Character
        if not char then continue end

        -- Nametag / health bar = draw call gratis
        pcall(function()
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.NameDisplayDistance = 0
                hum.HealthDisplayDistance = 0
                pcall(function()
                    hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                end)
            end
        end)

        -- Accessory / clothes / FX — gain FPS nyata di server rame
        for _, ch in ipairs(char:GetChildren()) do
            if ch:IsA("Accessory") or ch:IsA("Hat") then
                if safeDestroy(ch) then bump("other_char") end
            end
            yield()
        end

        for _, inst in ipairs(char:GetDescendants()) do
            if not running then return end
            local cls = inst.ClassName
            if DESTROY_CLASSES[cls] or cls == "Shirt" or cls == "Pants"
                or cls == "ShirtGraphic" or cls == "CharacterMesh"
                or cls == "BodyColors"
                or cls == "BillboardGui" or cls == "SurfaceGui"
                or cls == "Accessory" or cls == "Hat" then
                if safeDestroy(inst) then bump("other_char") end
            elseif FLATTEN_CLASSES[cls] then
                pcall(function()
                    inst.CastShadow = false
                    if inst:IsA("MeshPart") then
                        inst.TextureID = ""
                    end
                    -- sembunyikan mesh non-inti (hemat draw)
                    local n = tostring(inst.Name or "")
                    if n ~= "HumanoidRootPart" and n ~= "Head"
                        and n ~= "UpperTorso" and n ~= "LowerTorso"
                        and n ~= "Torso" and n ~= "HumanoidRootPart" then
                        if n:find("Arm", 1, true) or n:find("Leg", 1, true)
                            or n:find("Hand", 1, true) or n:find("Foot", 1, true) then
                            inst.LocalTransparencyModifier = 1
                        end
                    end
                end)
            end
            yield()
        end
        task.wait() -- jeda antar player
    end
    bump("other_char_pass")
end

local function hookLive(myToken)
    table.insert(conns, Workspace.DescendantAdded:Connect(function(inst)
        if not running or myToken ~= token then return end
        -- Skip garden spawn spam saat RF ON / AutoCollect (ratusan ChildAdded/detik)
        if isUnderGardens(inst) and (reduceFpsOwnsGarden() or autoCollectBusy()) then
            if isExplicitSprinklerRadius(inst) then
                killSprinklerRange(inst)
            end
            return
        end
        -- FX: matikan sync (1 frame) biar GPU tidak render dulu
        if DESTROY_CLASSES[inst.ClassName] and not isEclipseWeatherVfx(inst) then
            pcall(function()
                if inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")
                    or inst:IsA("Fire") or inst:IsA("Smoke") or inst:IsA("Sparkles")
                    or inst:IsA("Light") then
                    inst.Enabled = false
                end
            end)
            -- Particle/VFX: Destroy di frame ini (jangan defer). RF dulu pegang
            -- Parent=nil di array kuat → native leak. Destroy segera = RAM balik.
            if not isUnderGardens(inst) then
                processInstance(inst, LocalPlayer and LocalPlayer.Character)
                return
            end
        end
        task.defer(function()
            if not running or myToken ~= token then return end
            processInstance(inst, LocalPlayer and LocalPlayer.Character)
        end)
    end))

    table.insert(conns, Lighting.ChildAdded:Connect(function(child)
        if not running or myToken ~= token then return end
        local className = child.ClassName
        if LIGHTING_WEATHER_KEEP[className] then return end
        if LIGHTING_FX_CLASSES[className] then
            task.defer(function()
                if not child.Parent then return end
                if LIGHTING_WEATHER_KEEP[child.ClassName] then return end
                if safeDestroy(child) then bump("lighting_fx_live") end
            end)
        end
    end))

    table.insert(conns, Players.PlayerAdded:Connect(function(plr)
        table.insert(conns, plr.CharacterAdded:Connect(function()
            task.wait(0.4)
            if running and myToken == token then
                stripOtherCharacters()
            end
        end))
    end))

    -- Character sendiri: strip sprinkler tool radius SEGERA (jangan destroy Handle)
    local function bindChar(char)
        if not char then return end
        sweepSprinklerRange(char)

        table.insert(conns, char.DescendantAdded:Connect(function(inst)
            if not running or myToken ~= token then return end
            -- sync segera — delay = 1 frame lag spike sudah ke-render
            if isSprinklerRangeVisual(inst) and not isSprinklerHandleRoot(inst) then
                killSprinklerRange(inst)
                return
            end
            if inst:GetAttribute("ClientHandle") == true then
                stripSprinklerTool(inst:FindFirstAncestorOfClass("Tool") or inst.Parent)
                return
            end
            if inst:IsA("Tool") then
                stripSprinklerTool(inst)
            end
        end))

        table.insert(conns, char.ChildAdded:Connect(function(ch)
            if not running or myToken ~= token then return end
            if ch:IsA("Tool") then
                stripSprinklerTool(ch)
                -- clone handle muncul beberapa frame kemudian
                task.defer(function()
                    if running then stripSprinklerTool(ch) end
                end)
                task.delay(0.1, function()
                    if running and ch.Parent then stripSprinklerTool(ch) end
                end)
                task.delay(0.35, function()
                    if running and ch.Parent then stripSprinklerTool(ch) end
                end)
            end
        end))

        -- tool yang sudah dipegang
        for _, ch in ipairs(char:GetChildren()) do
            if ch:IsA("Tool") then stripSprinklerTool(ch) end
        end
    end

    if LocalPlayer then
        if LocalPlayer.Character then
            bindChar(LocalPlayer.Character)
        end
        table.insert(conns, LocalPlayer.CharacterAdded:Connect(function(char)
            task.wait(0.1)
            if running and myToken == token then
                bindChar(char)
            end
        end))

        local bp = LocalPlayer:FindFirstChild("Backpack")
        if bp then
            table.insert(conns, bp.ChildAdded:Connect(function(ch)
                if running and ch:IsA("Tool") then
                    stripSprinklerTool(ch)
                end
            end))
        end
    end

    -- heartbeat RINGAN: cuma cari SprinklerRadius (bukan full GetDescendants tool)
    local acc = 0
    table.insert(conns, RunService.Heartbeat:Connect(function(dt)
        if not running or myToken ~= token then return end
        acc += dt
        if acc < 0.5 then return end
        acc = 0
        local char = LocalPlayer and LocalPlayer.Character
        if not char then return end
        for _, ch in ipairs(char:GetChildren()) do
            if ch:IsA("Tool") and (ch:GetAttribute("Sprinkler") ~= nil
                or string.lower(ch.Name):find("sprinkler", 1, true)) then
                local radius = ch:FindFirstChild("SprinklerRadius", true)
                if radius and not isSprinklerHandleRoot(radius) then
                    killSprinklerRange(radius)
                end
                -- radius kadang nama "Radius" di ClientHandle
                local handle = ch:FindFirstChild("Handle") or ch:FindFirstChildWhichIsA("BasePart")
                if handle then
                    local r2 = handle:FindFirstChild("SprinklerRadius", true)
                        or handle:FindFirstChild("RadiusRing", true)
                    if r2 and not isSprinklerHandleRoot(r2) then
                        killSprinklerRange(r2)
                    end
                end
            end
        end
    end))
end

----------------------------------------------------------------
-- API
----------------------------------------------------------------

local function worldLooksReady()
    if not LocalPlayer then return false end
    if not Workspace:FindFirstChild("Gardens") then return false end
    if LocalPlayer:GetAttribute("PlotId") == nil then return false end
    if not LocalPlayer.Character then return false end
    return true
end

local function gardenLoadLooksDone()
    if not LocalPlayer then return false end
    if LocalPlayer:GetAttribute("LoadingScreenDone") == true then
        return true
    end
    local total = tonumber(LocalPlayer:GetAttribute("GardenLoadingTotal"))
    local prog = tonumber(LocalPlayer:GetAttribute("GardenLoadingProgress")) or 0
    if total and total > 0 and prog >= total then
        return true
    end
    -- ReduceFPS sudah jalan = garden sudah di-handle
    if G.REMOVE_GARDEN_ACTIVE == true or rawget(_G, "REMOVE_GARDEN_ACTIVE") == true then
        return true
    end
    return false
end

local function isLoadingActive()
    if not LocalPlayer then return false end
    -- Dunia + plot siap → jangan stuck di LoadingScreenActive / menu sisa
    if worldLooksReady() and gardenLoadLooksDone() then
        return false
    end
    if LocalPlayer:GetAttribute("LoadingScreenDone") == true then
        return false
    end
    if LocalPlayer:GetAttribute("LoadingScreenActive") == true then
        -- Active sering nyangkut setelah skip loading UI — kalau plot sudah ada, anggap selesai
        if worldLooksReady() then
            return false
        end
        return true
    end
    local menu = Workspace:FindFirstChild("LoadingScreenMenu")
    if menu ~= nil then
        local active = true
        pcall(function()
            if menu:IsA("ScreenGui") and menu.Enabled == false then
                active = false
            end
        end)
        if active then
            if worldLooksReady() then
                return false
            end
            return true
        end
    end
    return false
end

local function hubModulesReady()
    if G.__GROWAGARDEN2_MODULES_READY == true then return true end
    if rawget(_G, "__GROWAGARDEN2_MODULES_READY") == true then return true end
    return false
end

-- Tunggu hub selesai load module + game/plot siap (bukan loop strip)
local function waitReadyOnce(myToken, timeoutSec)
    timeoutSec = tonumber(timeoutSec) or 90
    local t0 = os.clock()
    while running and myToken == token do
        if (os.clock() - t0) >= timeoutSec then
            return hubModulesReady() or worldLooksReady() or game:IsLoaded()
        end
        local hubOk = hubModulesReady()
        local gameOk = game:IsLoaded() and worldLooksReady() and gardenLoadLooksDone()
        if not gameOk then
            gameOk = game:IsLoaded() and worldLooksReady() and not isLoadingActive()
        end
        if hubOk and gameOk then
            -- settle singkat supaya spawn FX terakhir sempat masuk
            task.wait(0.75)
            return true
        end
        task.wait(0.25)
    end
    return false
end

-- Event (bukan loop): weather ganti → strip VFX lagi
local weatherHooked = false
local function bindWeatherStripEvents()
    if weatherHooked then return end
    weatherHooked = true

    pcall(function()
        table.insert(conns, Workspace:GetAttributeChangedSignal("ActiveWeather"):Connect(function()
            if not running then return end
            task.defer(function()
                if running then pcall(stripWeatherVisuals) end
            end)
        end))
    end)

    pcall(function()
        local wv = ReplicatedStorage:FindFirstChild("WeatherValues")
        if not wv then
            wv = ReplicatedStorage:WaitForChild("WeatherValues", 5)
        end
        if not wv then return end
        table.insert(conns, wv.AttributeChanged:Connect(function(attr)
            if not running then return end
            if type(attr) == "string" and string.find(attr, "_Playing", 1, true) then
                task.defer(function()
                    if running then pcall(stripWeatherVisuals) end
                end)
            end
        end))
    end)

    -- ChildAdded di Workspace: root weather baru (Rain/Snow/dll)
    pcall(function()
        table.insert(conns, Workspace.ChildAdded:Connect(function(ch)
            if not running or not ch then return end
            if isWeatherNamed(ch.Name) then
                task.defer(function()
                    if running and ch.Parent then pcall(stripWeatherVisuals) end
                end)
            end
        end))
    end)
    bump("weather_hooks")
end

-- Staged oneshot — fase pelan, yield antar tahap (anti-freeze)
local function runOneshotAggressive()
    local t0 = os.clock()
    local function phase(name, fn)
        if not running then return end
        bump("phase_" .. name)
        pcall(fn)
        if running then
            task.wait(PHASE_GAP)
        end
    end

    -- 1) murah dulu (lighting/quality) — efek langsung terasa
    phase("quality", optimizeQuality)
    phase("lighting", optimizeLighting)
    phase("terrain", optimizeTerrain)
    phase("sprinkler_assets", stripSprinklerAssetTemplates)

    -- 2) weather VFX
    phase("weather", stripWeatherVisuals)

    -- 3) sprinkler di char/backpack
    phase("sprinkler_char", function()
        local char = LocalPlayer and LocalPlayer.Character
        if char then sweepSprinklerRange(char) end
        if LocalPlayer then
            local bp = LocalPlayer:FindFirstChild("Backpack")
            if bp then sweepSprinklerRange(bp) end
        end
    end)

    -- 4) player lain (bertahap)
    phase("other_chars", stripOtherCharacters)

    -- 5) world / garden strip (paling berat — sudah ada yield dalam)
    phase("world", stripWorkspace)

    -- 6) pass ke-2 SETELAH jeda (bukan langsung) — tangkap FX yang spawn belakangan
    if running then
        task.wait(PASS2_DELAY)
    end
    phase("weather2", stripWeatherVisuals)
    phase("other_chars2", stripOtherCharacters)
    phase("world2", stripWorkspace)
    phase("lighting2", optimizeLighting)

    -- Hook weather ganti (event). Bukan loop Heartbeat.
    if running then
        bindWeatherStripEvents()
    end

    bump("oneshot_done")
    firedOnce = true
    bump("oneshot_ms", math.floor((os.clock() - t0) * 1000))
end

function M.Stop()
    running = false
    firedOnce = false
    weatherHooked = false
    token += 1
    disc()
    G.REDUCE_LAG_ENABLED = false
    _G.REDUCE_LAG_ENABLED = false
end

-- opts.force = true → jalan 1× lagi meski sudah pernah
function M.Start(opts)
    opts = type(opts) == "table" and opts or {}
    local force = opts.force == true

    if firedOnce and running and not force then
        return true
    end

    running = true
    token += 1
    local myToken = token
    if force or not firedOnce then
        stats = {}
    end
    disc()

    G.REDUCE_LAG_ENABLED = true
    _G.REDUCE_LAG_ENABLED = true

    task.spawn(function()
        if not running or myToken ~= token then return end
        local ok = waitReadyOnce(myToken, 90)
        if not running or myToken ~= token then return end
        if not ok and not worldLooksReady() and not hubModulesReady() then
            return
        end
        runOneshotAggressive()
    end)

    return true
end

function M.SetEnabled(on)
    on = (on == true)
    G.REDUCE_LAG_ENABLED = on
    _G.REDUCE_LAG_ENABLED = on

    local MAIN = rawget(_G, "MAIN") or G.MAIN
    if type(MAIN) == "table" then
        MAIN.misc = MAIN.misc or {}
        MAIN.misc.perf = type(MAIN.misc.perf) == "table" and MAIN.misc.perf or {}
        MAIN.misc.perf.reduce_lag = on
        G.MAIN = MAIN
        _G.MAIN = MAIN
    end

    if on then
        -- toggle ON ulang = force oneshot baru
        firedOnce = false
        M.Start({ force = true })
    else
        M.Stop()
    end
end
M.setEnabled = M.SetEnabled

function M.IsEnabled()
    return running
end
M.isRunning = M.IsEnabled

function M.SyncFromGlobals()
    local cfg = _cfg()
    G.REDUCE_LAG_ENABLED = cfg.enabled
    _G.REDUCE_LAG_ENABLED = cfg.enabled
    if cfg.enabled then
        M.Start()
    else
        if running then
            M.Stop()
        end
    end
end

function M.GetStats()
    return {
        version = "v2.5-vfx-destroy-now",
        running = running,
        firedOnce = firedOnce,
        weatherHooked = weatherHooked,
        enabled = _cfg().enabled,
        stats = stats,
        worldReady = worldLooksReady(),
        hubReady = hubModulesReady(),
        activeWeather = Workspace:GetAttribute("ActiveWeather"),
        loadingActive = isLoadingActive(),
        loadingDoneAttr = LocalPlayer and LocalPlayer:GetAttribute("LoadingScreenDone") == true,
        skipGarden = reduceFpsOwnsGarden(),
        fpsOwnsGarden = reduceFpsOwnsGarden(),
    }
end

function M.DumpDebug()
    local s = M.GetStats()
    local parts = {}
    for k, v in pairs(s.stats or {}) do
        parts[#parts + 1] = tostring(k) .. "=" .. tostring(v)
    end
    table.sort(parts)
    print(string.format(
        "[ReduceLag] dump %s running=%s fired=%s hub=%s world=%s | %s",
        tostring(s.version),
        tostring(s.running),
        tostring(s.firedOnce),
        tostring(s.hubReady),
        tostring(s.worldReady),
        table.concat(parts, " ")
    ))
    return s
end
M.dumpDebug = M.DumpDebug

_G.__GAG2_REDUCE_LAG = {
    start = function() M.Start({ force = true }) end,
    stop = function() M.Stop() end,
    stats = function() return M.GetStats() end,
    dump = M.DumpDebug,
    sync = function() M.SyncFromGlobals() end,
    stripNow = function()
        firedOnce = false
        running = true
        G.REDUCE_LAG_ENABLED = true
        _G.REDUCE_LAG_ENABLED = true
        runOneshotAggressive()
        return M.GetStats()
    end,
    stripWeather = function()
        running = true
        pcall(stripWeatherVisuals)
        return M.GetStats()
    end,
}

G.ReduceLag = M
G.ReduceLagModule = M
_G.ReduceLag = M
_G.ReduceLagModule = M

return M
 end,                      required = false, early = true },
    { key = "ReduceFPS",               name = "Reduce FPS",              factory = function() --[[
    ReduceFPS.lua — Grow A Garden 2 (v10.23.7 eclipse-pos-vanilla)

    OWN: kerangka pohon saja (Base + FruitSpawnLocations + Fruits kosong + attrs).
         Jangan Destroy plant Model. Jangan 2000 fruit shell / HarvestPrompt.
         Auto Collect = GetGarden (tidak butuh RF shell).
         Watering / sprinkler / trowel / pot = pivot Base + PlantArea.
    OTHER: sama seperti dulu (1 shell/tipe, steal keep top-N, wipe).
    Mutasi AC: tulis ke GetGarden. Jangan StampMutationsNow massal ke shell.
    Eclipse own top-N: tetap FVC asli (beam), bukan 2000 shell.

    API:
      RestoreSoft() / RestoreFull() / DestroyFruit / pruneOwnFruits() / cleanupLooseProxies()
      DisablePlantCull(true|false) / RestoreCulledPlants()
