local LP = Players.LocalPlayer
if not LP then LP = Players.PlayerAdded:Wait() end

local G = (getgenv and getgenv()) or _G
local M = {}

-- Debug HUD: jangan local baru (chunk sudah mepet 200 register).
G.__GAG2_RF_JOB = function(name, fn)
    G.__GAG2_RF_PHASE = name
    local p = rawget(G, "__GAG2_RF_PROF")
    if type(p) ~= "function" then
        return fn()
    end
    return p(name, fn)
end

