local function stripBudgetYield()
    if (os.clock() - S.stripBudgetT) >= A.STRIP_BUDGET then
        task.wait()
        S.stripBudgetT = os.clock()
    end
end

local function useGameManagedFruits()
    return CONFIG.gameManagedFruits ~= false
end

local function installFruitProxyYieldGate()
    -- v2: hanya FPU — biar reload overwrite flag lama yang sempat wrap Networking
    if rawget(G, "__GAG2_FPU_YIELD_GATE_V2") == true then return true end
    local sm = ReplicatedStorage:FindFirstChild("SharedModules")
    local mod = sm and sm:FindFirstChild("FruitProxyUtil")
    if not mod then return false end
    local ok, FPU = pcall(require, mod)
    if not ok or type(FPU) ~= "table" then return false end

    local skip = {
        IsFruitInstance = true,
        isFruitInstance = true,
    }
    for k, v in pairs(FPU) do
        if type(v) == "function" and not skip[k] and not string.find(tostring(k), "__gag2", 1, true) then
            local orig = v
            if type(orig) == "function" then
                FPU[k] = function(...)
                    while S.fpuYieldActive >= A.FPU_YIELD_MAX do
                        task.wait(0.04)
                    end
                    S.fpuYieldActive += 1
                    local results = table.pack(pcall(orig, ...))
                    S.fpuYieldActive -= 1
                    if not results[1] then
                        local err = tostring(results[2] or "")
                        if err:find("128 yielded", 1, true) or err:find("yielded threads", 1, true) then
                            task.wait(0.25)
                            return nil
                        end
                        error(results[2], 0)
                    end
                    return table.unpack(results, 2, results.n)
                end
            end
        end
    end

    G.__GAG2_FPU_YIELD_GATE_V2 = true
    _G.__GAG2_FPU_YIELD_GATE_V2 = true
    -- clear flag lama biar tidak menyesatkan
    G.__GAG2_PACKET_YIELD_GATE = nil
    _G.__GAG2_PACKET_YIELD_GATE = nil
    return true
end

local function tagHarvestPrompt(prompt)
    if not prompt or not prompt.Parent then return end
    pcall(function()
        if not CollectionService:HasTag(prompt, "HarvestPrompt") then
            prompt:AddTag("HarvestPrompt")
        end
    end)
end

----------------------------------------------------------------
local function debugOn()
    if G.REDUCE_FPS_DEBUG == false or rawget(_G, "REDUCE_FPS_DEBUG") == false then return false end
    if G.REDUCE_FPS_DEBUG == true or rawget(_G, "REDUCE_FPS_DEBUG") == true then return true end
    return CONFIG.debug == true
end

local function dlog(fmt, ...)
    if not debugOn() then return end
    local ok, msg = pcall(string.format, tostring(fmt), ...)
    print("[ReduceFPS] " .. (ok and msg or tostring(fmt)))
end

local function markActive()
    local on = S.alive and S.running
    G.REMOVE_GARDEN_ACTIVE = on
    _G.REMOVE_GARDEN_ACTIVE = on
end

local function disc(t)
    for _, c in ipairs(t) do pcall(function() c:Disconnect() end) end
    table.clear(t)
end

local function sliceYield()
    if (os.clock() - S.yieldT) >= A.SLICE then
        task.wait()
        S.yieldT = os.clock()
    end
end

local function stealKeepOn()
    return (S.stealCompatRef or 0) > 0 or S.gardenModeSteal == true
end

S.otherPaused = function()
    if stealKeepOn() then return false end
    return CONFIG.pauseOtherGardens ~= false
end

local function _cfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local perf = MAIN and MAIN.misc and MAIN.misc.perf
    perf = type(perf) == "table" and perf or {}
    -- MAIN.misc.perf.enabled = sumber kebenaran (toggle OFF harus menang).
    -- Jangan OR dengan global stale — itu bikin Remove Garden "selalu ON".
    local enabled
    if perf.enabled ~= nil then
        enabled = (perf.enabled == true)
    else
        enabled = (G.REDUCE_FPS_ENABLED == true)
            or (rawget(_G, "REDUCE_FPS_ENABLED") == true)
    end
    CONFIG.clearOtherPlants = enabled == true
    -- Strip visual own = kerangka pohon. Jangan Destroy own (lihat destroyIfOtherPlant).
    CONFIG.stripOwnVisual = enabled == true
    if perf.own_no_fruit_shells == false then
        CONFIG.ownNoFruitShells = false
    else
        CONFIG.ownNoFruitShells = true
    end
    if perf.hide_own == false or perf.strip_own == false then
        CONFIG.stripOwnVisual = false
    end
    if perf.block_visual_init ~= nil then
        CONFIG.blockVisualInit = perf.block_visual_init == true
    else
        CONFIG.blockVisualInit = enabled == true
    end
    do
        local gm = tostring(perf.garden_mode or G.REDUCE_FPS_GARDEN_MODE or rawget(_G, "REDUCE_FPS_GARDEN_MODE") or "normal"):lower()
        S.gardenModeSteal = (gm == "steal")
    end
    if perf.pause_other_gardens == false then
        CONFIG.pauseOtherGardens = false
    else
        CONFIG.pauseOtherGardens = true
    end
    if stealKeepOn() then
        -- Steal / Garden Mode steal: izinkan spawn buah other; trim ke top-N
        CONFIG.blockOtherSpawn = false
    elseif perf.block_other_spawn ~= nil then
        CONFIG.blockOtherSpawn = perf.block_other_spawn == true
    else
        CONFIG.blockOtherSpawn = enabled == true
    end
    local keepN = tonumber(perf.steal_keep_fruits)
    if keepN == nil then
        keepN = tonumber(G.REDUCE_FPS_STEAL_KEEP) or tonumber(rawget(_G, "REDUCE_FPS_STEAL_KEEP"))
    end
    if keepN ~= nil then
        CONFIG.stealKeepFruits = math.floor(math.max(0, keepN))
    elseif type(CONFIG.stealKeepFruits) ~= "number" or CONFIG.stealKeepFruits < 0 then
        CONFIG.stealKeepFruits = 50
    end
    if type(perf.restore_batch_size) == "number" and perf.restore_batch_size > 0 then
        CONFIG.restoreBatchSize = math.floor(perf.restore_batch_size)
    end
    if type(perf.restore_batch_delay) == "number" and perf.restore_batch_delay >= 0 then
        CONFIG.restoreBatchDelay = perf.restore_batch_delay
    end
    if type(perf.restore_fruit_batch_size) == "number" and perf.restore_fruit_batch_size > 0 then
        CONFIG.restoreFruitBatchSize = math.floor(perf.restore_fruit_batch_size)
    end
    if type(perf.restore_fruit_batch_delay) == "number" and perf.restore_fruit_batch_delay >= 0 then
        CONFIG.restoreFruitBatchDelay = perf.restore_fruit_batch_delay
    end
    if perf.restore_rehide ~= nil then
        CONFIG.restoreRehide = perf.restore_rehide == true
    end
    if perf.restore_full_visual ~= nil then
        CONFIG.restoreFullVisual = perf.restore_full_visual == true
    end
    -- Debug runtime-only (Misc toggle / _G) — tidak baca MAIN.misc.perf.debug
    CONFIG.debug = (G.REDUCE_FPS_DEBUG == true) or (rawget(_G, "REDUCE_FPS_DEBUG") == true)
    if perf.restore_on_stop ~= nil then
        CONFIG.restoreOnStop = perf.restore_on_stop == true
    end
    if perf.disable_plant_cull ~= nil then
        CONFIG.disablePlantCull = perf.disable_plant_cull == true
    end
    if perf.pause_far_from_plot ~= nil then
        CONFIG.pauseFarFromPlot = perf.pause_far_from_plot == true
    end
    do
        local cap = perf.fps_cap or perf.fpsCap or G.REDUCE_FPS_CAP or rawget(_G, "REDUCE_FPS_CAP")
        if type(cap) == "number" then
            CONFIG.fpsCap = cap
        end
    end
    local render = perf.render
    if render == nil then render = true end
    CONFIG.mode = (render == false) and "nuclear" or "brutal"
    return { enabled = enabled == true, debug = CONFIG.debug }
end

----------------------------------------------------------------
-- Plot ownership
----------------------------------------------------------------
local function owned(plot)
    if not plot then return false end
    local u, n = LP.UserId, LP.Name
    local function m(v)
        return v ~= nil and (v == u or v == n or tostring(v) == tostring(u))
    end
    return m(plot:GetAttribute("OwnerId")) or m(plot:GetAttribute("Owner"))
        or m(plot:GetAttribute("OwnerUserId")) or m(plot:GetAttribute("UserId"))
end

local function isOwnPlot(plot)
    if not plot or not plot.Parent then return false end
    if S.cachedPlot and plot == S.cachedPlot then return true end
    if owned(plot) then
        S.cachedPlot = plot
        return true
    end
    local id = LP:GetAttribute("PlotId")
    if id ~= nil and plot.Name == ("Plot" .. tostring(id)) then
        S.cachedPlot = plot
        return true
    end
    if plot.Name == ("Plot" .. LP.Name) then
        S.cachedPlot = plot
        return true
    end
    return false
end

local function myPlot()
    if S.cachedPlot and S.cachedPlot.Parent then return S.cachedPlot end
    local g = Workspace:FindFirstChild("Gardens")
    if not g then return nil end
    local id = LP:GetAttribute("PlotId")
    if id ~= nil then
        local p = g:FindFirstChild("Plot" .. tostring(id))
        if p then S.cachedPlot = p return p end
        -- PlotId ada tapi model belom — jangan pakai plot lain
        return nil
    end
    for _, p in ipairs(g:GetChildren()) do
        if owned(p) then S.cachedPlot = p return p end
    end
    local byName = g:FindFirstChild("Plot" .. LP.Name)
    if byName then S.cachedPlot = byName return byName end
    return nil
end

local function plotOwnerUserId(plot)
    if not plot then return nil end
    local v = plot:GetAttribute("OwnerUserId")
        or plot:GetAttribute("OwnerId")
        or plot:GetAttribute("UserId")
        or plot:GetAttribute("Owner")
    local n = tonumber(v)
    if n then return n end
    if type(v) == "string" and v ~= "" then
        if v == LP.Name then return LP.UserId end
        local plr = Players:FindFirstChild(v)
        if plr then return plr.UserId end
    end
    return nil
end

----------------------------------------------------------------
-- FAR / CulledPlants (PlantCullingController) — anti CPU jauh↔dekat
----------------------------------------------------------------
local function culledPlantsFolder()
    return ReplicatedStorage:FindFirstChild("CulledPlants")
end

local function isInCulledFolder(inst)
    if not inst then return false end
    local f = culledPlantsFolder()
    return f ~= nil and inst:IsDescendantOf(f)
end

local function plotAnchorPos(plot)
    if not plot then return nil end
    local sp = plot:FindFirstChild("SpawnPoint")
    if sp and sp:IsA("BasePart") then
        return sp.Position
    end
    if sp and sp:IsA("Model") then
        local ok, cf = pcall(function() return sp:GetPivot() end)
        if ok and cf then return cf.Position end
    end
    local ok, cf = pcall(function() return plot:GetPivot() end)
    if ok and cf then return cf.Position end
    return nil
end

local function viewerPosForCull()
    -- Samakan PlantCullingController: kamera dulu
    local cam = Workspace.CurrentCamera
    if cam then
        return cam.CFrame.Position
    end
    local ch = LP.Character
    local hrp = ch and (ch:FindFirstChild("HumanoidRootPart") or ch.PrimaryPart)
    if hrp and hrp:IsA("BasePart") then
        return hrp.Position
    end
    return nil
end

local function gameCullRange()
    if LP:GetAttribute("AutoQualityActive") == true then
        local aq = tonumber(LP:GetAttribute("AutoQualityCullRange"))
        if aq and aq > 0 then return aq end
    end
    local settings = LP:FindFirstChild("Settings")
    local r = settings and settings:FindFirstChild("Plant_Cull_Range")
    if r then
        local v = tonumber(r.Value)
        if v and v > 0 then return v end
    end
    return 0
end

local function ownCulledHeavy()
    local f = culledPlantsFolder()
    if not f then return false end
    local n = 0
    for _, ch in ipairs(f:GetChildren()) do
        if ch:IsA("Model") and tonumber(ch:GetAttribute("UserId")) == LP.UserId then
            n += 1
            if n >= 15 then return true end
        end
    end
    return false
end

local function isResumeCatchup()
    local t0 = tonumber(S.resumeCatchupAt) or 0
    if t0 <= 0 then return false end
    return (os.clock() - t0) < (tonumber(CONFIG.resumeCatchupSec) or 3.0)
end

local function isNearOwnPlot()
    if CONFIG.pauseFarFromPlot == false then
        S.farPaused = false
        return true
    end
    local now = os.clock()
    if (now - (tonumber(S.nearPlotAt) or 0)) < (tonumber(CONFIG.nearPlotCacheSec) or 0.35) then
        return S.nearPlotCached ~= false
    end
    S.nearPlotAt = now
    local plot = myPlot()
    local anchor = plotAnchorPos(plot)
    local pos = viewerPosForCull()
    if not pos or not anchor then
        -- Ragu: kalau banyak own di CulledPlants → anggap jauh
        local heavy = ownCulledHeavy()
        S.nearPlotCached = not heavy
        S.farPaused = heavy
        S.nearPlotDist = nil
        return not heavy
    end
    local dist = (pos - anchor).Magnitude
    S.nearPlotDist = dist
    local pauseAt = tonumber(CONFIG.nearPlotStuds) or 150
    local resumeAt = tonumber(CONFIG.nearPlotResumeStuds) or 120
    local cull = gameCullRange()
    if cull > 0 then
        -- Mulai pause mendekati titik cull game (jangan kerja berat pas plant di-parent keluar)
        pauseAt = math.min(pauseAt, cull * 0.95)
        resumeAt = math.min(resumeAt, cull * 0.85)
    end
    local near
    if S.nearPlotCached == false then
        near = dist <= resumeAt
    else
        near = dist <= pauseAt
    end
    if near and ownCulledHeavy() and dist > resumeAt * 0.5 then
        -- Masih banyak culled → tahan soft-resume sebentar
        near = false
    end
    S.nearPlotCached = near
    S.farPaused = not near
    return near
end

local function isFarFromOwnPlot()
    return not isNearOwnPlot()
end

local function clearOwnWorkQueues()
    table.clear(Q.fruitShell)
    table.clear(Q.fruitShellQueued)
    table.clear(Q.plantStrip)
    table.clear(Q.plantStripQueued)
end

local function pauseOwnShellPromptsFar()
    local function mutePrompt(model)
        if not model or not model:IsA("Model") then return end
        if model:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true and model:GetAttribute("FruitId") == nil then
            return
        end
        local pr = model:FindFirstChild("HarvestPrompt", true)
        if not pr or not pr:IsA("ProximityPrompt") then return end
        pcall(function()
            pr:SetAttribute("Collected", true)
            pr.Enabled = false
            pr.MaxActivationDistance = 0
            if CollectionService:HasTag(pr, "HarvestPrompt") then
                pr:RemoveTag("HarvestPrompt")
            end
        end)
    end
    local function mutePlantTree(plant)
        if not plant or not plant:IsA("Model") then return end
        mutePrompt(plant)
        local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
        if ff then
            for _, fruit in ipairs(ff:GetChildren()) do
                mutePrompt(fruit)
            end
        end
    end
    local plot = myPlot()
    if plot then
        local folders = {}
        local important = plot:FindFirstChild("Important")
        for _, name in ipairs({ "Plants", "Plants_Physical", "PhysicalPlants" }) do
            local f = plot:FindFirstChild(name)
            if f then folders[#folders + 1] = f end
            if important then
                local f2 = important:FindFirstChild(name)
                if f2 then folders[#folders + 1] = f2 end
            end
        end
        for _, folder in ipairs(folders) do
            for _, plant in ipairs(folder:GetChildren()) do
                mutePlantTree(plant)
            end
        end
    end
    local culled = culledPlantsFolder()
    if culled then
        for _, plant in ipairs(culled:GetChildren()) do
            if tonumber(plant:GetAttribute("UserId")) == LP.UserId then
                mutePlantTree(plant)
            end
        end
    end
end

local function noteFarNearEdge()
    local far = isFarFromOwnPlot()
    if far and not S.wasFarPaused then
        S.wasFarPaused = true
        S.farPromptPaused = true
        clearOwnWorkQueues()
        pcall(pauseOwnShellPromptsFar)
        dlog("FAR pause dist=%s cull=%s", tostring(S.nearPlotDist), tostring(gameCullRange()))
    elseif (not far) and S.wasFarPaused then
        S.wasFarPaused = false
        S.farPromptPaused = false
        S.resumeCatchupAt = os.clock()
        clearOwnWorkQueues() -- jangan stampede antrean lama
        dlog("NEAR soft-resume %ss", tostring(CONFIG.resumeCatchupSec))
    elseif far then
        if not S.farPromptPaused then
            S.farPromptPaused = true
            pcall(pauseOwnShellPromptsFar)
        end
    end
    return far
end

local function startFarNearWatcher(myToken)
    if CONFIG.pauseFarFromPlot == false then
        return
    end
    task.spawn(function()
        while S.alive and myToken == S.token do
            pcall(noteFarNearEdge)
            task.wait(0.4)
        end
    end)
end

-- PlantCullingController: range>0 → Parent ke ReplicatedStorage.CulledPlants.
-- Paksa range=0 + restore → folder Plants tidak dikosongin saat jauh.
local function plotForCulledUserId(uid)
    uid = tonumber(uid)
    if not uid then return nil end
    if uid == LP.UserId then return myPlot() end
    local gardens = Workspace:FindFirstChild("Gardens")
    if not gardens then return nil end
    local plr = Players:GetPlayerByUserId(uid)
    if plr then
        local id = plr:GetAttribute("PlotId")
        if id ~= nil then
            local p = gardens:FindFirstChild("Plot" .. tostring(id))
            if p then return p end
        end
    end
    for _, p in ipairs(gardens:GetChildren()) do
        if plotOwnerUserId(p) == uid then
            return p
        end
    end
    return nil
end

local function restoreAllCulledPlants()
    local folder = culledPlantsFolder()
    if not folder then return 0 end
    local n = 0
    local kids = folder:GetChildren()
    for i = 1, #kids do
        local plant = kids[i]
        if plant:IsA("Model") then
            local plot = plotForCulledUserId(plant:GetAttribute("UserId"))
            local plantsFolder = plot and plot:FindFirstChild("Plants")
            if plantsFolder and pcall(function()
                plant.Parent = plantsFolder
            end) then
                n += 1
            end
        end
        if i % 40 == 0 then
            task.wait()
        end
    end
    return n
end

local function forcePlantCullRangeZero()
    local settings = LP:FindFirstChild("Settings")
    if not settings then
        settings = LP:WaitForChild("Settings", 3)
    end
    local r = settings and settings:FindFirstChild("Plant_Cull_Range")
    if r then
        pcall(function()
            if tonumber(r.Value) ~= 0 then
                r.Value = 0
            end
        end)
        if not S.cullRangeConn and r:IsA("ValueBase") then
            S.cullRangeConn = r.Changed:Connect(function()
                if not S.alive or CONFIG.disablePlantCull == false then return end
                pcall(function()
                    if tonumber(r.Value) ~= 0 then
                        r.Value = 0
                    end
                end)
            end)
            table.insert(B.conns, S.cullRangeConn)
        end
    end
    pcall(function()
        if LP:GetAttribute("AutoQualityActive") == true then
            local aq = tonumber(LP:GetAttribute("AutoQualityCullRange"))
            if aq and aq ~= 0 then
                LP:SetAttribute("AutoQualityCullRange", 0)
            end
        end
    end)
end

local function startPlantCullDisabler(myToken)
    if CONFIG.disablePlantCull == false then
        return
    end
    S.cullDisableToken += 1
    local my = S.cullDisableToken
    task.spawn(function()
        task.wait(0.2)
        while S.alive and myToken == S.token and my == S.cullDisableToken do
            if CONFIG.disablePlantCull == false then break end
            forcePlantCullRangeZero()
            local n = restoreAllCulledPlants()
            if n > 0 then
                dlog("plantCull OFF restored=%d", n)
            end
            task.wait(1.0)
        end
    end)
end

-- Hanya true kalau PASTI plot orang lain. Ragu → false (jangan sentuh).
local function isConfirmedOtherPlot(plot)
    if not plot or not plot.Parent then return false end
    if isOwnPlot(plot) then return false end
    if owned(plot) then return false end

    local id = LP:GetAttribute("PlotId")
    if id ~= nil and plot.Name == ("Plot" .. tostring(id)) then
        return false
    end

    local mine = myPlot()
    if not mine or not mine.Parent then
        -- Plot sendiri belum ketahuan → jangan clear siapapun
        return false
    end
    if plot == mine then return false end

    local oid = plotOwnerUserId(plot)
    if oid == nil then return false end
    if oid == LP.UserId then return false end
    return true
end

-- Plant/fruit milik sendiri? Ragu → true (fail-safe: jangan Destroy)
local function isOwnPlantContext(inst)
    if not inst then return true end
    local uid = tonumber(inst:GetAttribute("UserId"))
    if uid == LP.UserId then return true end
    if uid ~= nil and uid ~= LP.UserId then return false end
    local p = inst
    for _ = 1, 14 do
        if not p then break end
        local par = p.Parent
        if par and par.Name == "Gardens" then
            if isOwnPlot(p) then return true end
            if isConfirmedOtherPlot(p) then return false end
            return true
        end
        p = par
    end
    return true
end

local function destroyIfOtherPlant(inst, plot)
    if not inst or not inst.Parent then return false end
    if isInCulledFolder(inst) then return false end -- biarkan PlantCullingController
    if plot and not isConfirmedOtherPlot(plot) then return false end
    if isOwnPlantContext(inst) then return false end
    local ok = pcall(function() inst:Destroy() end)
    return ok == true
end

local function getPVC()
    local ps = LP:FindFirstChild("PlayerScripts")
    local c = ps and ps:FindFirstChild("Controllers")
    local m = c and c:FindFirstChild("PlantVisualizerController")
    if not m then return nil end
    local ok, mod = pcall(require, m)
    return (ok and type(mod) == "table") and mod or nil
end

local function getFVC()
    local ps = LP:FindFirstChild("PlayerScripts")
    local c = ps and ps:FindFirstChild("Controllers")
    local m = c and c:FindFirstChild("FruitVisualizerController")
    if not m then return nil end
    local ok, mod = pcall(require, m)
    return (ok and type(mod) == "table") and mod or nil
end

local function listPlantFolders(plot, userId)
    local out, seen = {}, {}
    local function add(f)
        if f and f.Parent and not seen[f] and f:IsDescendantOf(plot) then
            seen[f] = true
            out[#out + 1] = f
        end
    end
    if not plot then return out end
    local important = plot:FindFirstChild("Important")
    for _, name in ipairs({ "Plants", "Plants_Physical", "PhysicalPlants" }) do
        add(plot:FindFirstChild(name))
        if important then add(important:FindFirstChild(name)) end
    end
    local vis = getPVC()
    if vis and type(vis.GetPlantsFolder) == "function" and userId then
        local ok, f = pcall(vis.GetPlantsFolder, vis, userId)
        if ok then add(f) end
    end
    return out
end

----------------------------------------------------------------
-- Keep / helpers
----------------------------------------------------------------
local KEEP_FOLDER = {
    Fruits = true,
    Fruit = true,
    FruitSpawnLocations = true,
    FruitSpawnLocation = true,
    SpawnLocations = true,
    [A.PLANT_STASH] = true, -- jangan stash ulang
    [A.STASH_NAME] = true,
}

local function isKeepPart(inst)
    if not inst or not inst:IsA("BasePart") then return false end
    local n = tostring(inst.Name or "")
    if n == "HarvestPart" or n == "Harvest" or n == "CollectProxy" then return true end
    if CollectionService:HasTag(inst, A.PLANTAREA) then return true end
    if n:find("Spawn", 1, true) or n:find("Location", 1, true) then return true end
    return false
end

local function isKeepInstance(inst)
    if not inst then return true end
    if isKeepPart(inst) then return true end
    if inst:IsA("ProximityPrompt") or inst:IsA("ValueBase") or inst:IsA("Attachment") then
        return true
    end
    if inst:IsA("Folder") and KEEP_FOLDER[inst.Name] then return true end
    return false
end

local function isSprinkler(i)
    if not i then return false end
    if i:IsA("Model") and i:GetAttribute("SprinklerId") then return true end
    local c = i.Parent
    while c and c ~= game do
        if c.Name == "Sprinklers" then return true end
        c = c.Parent
    end
    return false
end

local function isFruitModel(model)
    if not model then return false end
    if model:GetAttribute("FruitId") ~= nil then return true end
    local p = model.Parent
    return p ~= nil and (p.Name == "Fruits" or p.Name == "Fruit")
end

local function underFruitsFolder(inst)
    local p = inst
    for _ = 1, 12 do
        if not p then return false end
        if p.Name == "Fruits" or p.Name == "Fruit" then return true end
        if p.Name == "Gardens" then return false end
        p = p.Parent
    end
    return false
end

local function hideHarvestWanted()
    if G.HIDE_HARVEST_PROMPT_ENABLED == true then return true end
    if rawget(_G, "HIDE_HARVEST_PROMPT_ENABLED") == true then return true end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local cfg = MAIN and MAIN.misc and MAIN.misc.hide_harvest_prompt
    return type(cfg) == "table" and cfg.enabled == true
end

local function ensureProxy(model)
    -- Hanya Model plant/fruit. JANGAN Folder Fruits / Part lepas (orphan di Fruits).
    if not model or not model:IsA("Model") then return nil, nil end
    if model.Name == "Fruits" or model.Name == "Fruit" then return nil, nil end
    local par = model.Parent
    if par and (par.Name == "Fruits" or par.Name == "Fruit") then
        -- fruit UUID: soft shell pakai HarvestPart/ShellBody saja (bukan CollectProxy plant)
        if model:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
            return nil, nil
        end
    end
    local hp = model:FindFirstChild("HarvestPart")
    if not (hp and hp:IsA("BasePart")) then
        hp = Instance.new("Part")
        hp.Name = "HarvestPart"
        hp.Size = Vector3.new(1.5, 1.5, 1.5)
        hp.Transparency = 1
        hp.Anchored = true
        hp.CanCollide = false
        hp.CanQuery = false
        hp.CastShadow = false
        hp.Parent = model
    end
    local proxy = model:FindFirstChild("CollectProxy")
    if not (proxy and proxy:IsA("BasePart")) then
        proxy = Instance.new("Part")
        proxy.Name = "CollectProxy"
        proxy.Size = Vector3.new(3, 3, 3)
        proxy.Transparency = 1
        proxy.Anchored = true
        proxy.CanCollide = false
        proxy.CanQuery = true
        proxy.CastShadow = false
        proxy.Parent = model
    else
        pcall(function() proxy.CanQuery = true end)
    end
    pcall(function()
        local cf = model:GetPivot()
        hp.CFrame = cf
        proxy.CFrame = cf
        if model:IsA("Model") then model.PrimaryPart = proxy end
    end)
    return hp, proxy
end

local LOOSE_PROXY_NAMES = {
    CollectProxy = true,
    HarvestPart = true,
    ShellBody = true,
    Harvest = true,
}

-- Hapus CollectProxy/HarvestPart/ShellBody yang nyasar langsung di folder Fruits
local function cleanupLooseFruitProxies(plant)
    if not plant then return 0 end
    local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
    if not folder then return 0 end
    local n = 0
    for _, ch in ipairs(folder:GetChildren()) do
        -- Part lepas ATAU Model kosong bernama proxy (bukan fruit UUID)
        if ch:IsA("BasePart") and LOOSE_PROXY_NAMES[ch.Name] then
            if pcall(function() ch:Destroy() end) then n += 1 end
        elseif ch:IsA("Model") and LOOSE_PROXY_NAMES[ch.Name] and ch:GetAttribute("FruitId") == nil then
            if pcall(function() ch:Destroy() end) then n += 1 end
        end
    end
    return n
end

local function cleanupAllOwnLooseProxies()
    local plot = myPlot()
    if not plot then return 0 end
    local n = 0
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if plant:IsA("Model") then
                n += cleanupLooseFruitProxies(plant)
            end
        end
    end
    if n > 0 then
        dlog("cleanupLooseProxies removed=%d", n)
    end
    return n
end

local function bindFruitsFolderCleanup(folder)

    if not folder or B.fruitsFolderBound[folder] then return end
    B.fruitsFolderBound[folder] = folder.ChildAdded:Connect(function(ch)
        if not S.alive then return end
        if ch:IsA("BasePart") and LOOSE_PROXY_NAMES[ch.Name] then
            task.defer(function()
                if ch.Parent == folder then
                    pcall(function() ch:Destroy() end)
                end
            end)
        end
    end)
    -- bersihkan yang sudah ada
    cleanupLooseFruitProxies(folder.Parent)
end

-- Type name helpers (Other Sprinkler UI butuh SeedName di model, bukan di fruit/child)
local function looksLikeTypeId(s)
    s = tostring(s or "")
    if s == "" then return true end
    if s:match("^%d+_[%x%-]+") then return true end
    if #s >= 32 and s:match("^[%x%-]+$") then return true end
    if s:find("_", 1, true) and s:find("-", 1, true) and not s:match("^[%a][%a%d ]*$") then
        return true
    end
    return false
end

local function normalizeTypeName(v)
    if type(v) ~= "string" then return nil end
    v = v:gsub("^%s+", ""):gsub("%s+$", "")
    if v == "" or looksLikeTypeId(v) then return nil end
    local tail = v:match("([^/]+)$")
    if tail and not looksLikeTypeId(tail) then return tail end
    return v
end

local function seedNameFromData(data)
    if type(data) ~= "table" then return nil end
    for _, k in ipairs({
        "SeedName", "PlantName", "ItemName", "ConfigPathName",
        "CorePartName", "FruitType", "FruitName", "Type", "Name",
    }) do
        local n = normalizeTypeName(data[k])
        if n then return n end
    end
    return nil
end

local function pickTypeFromInst(inst)
    if not inst then return nil end
    for _, key in ipairs({
        "SeedName", "PlantName", "FruitType", "FruitName",
        "ItemName", "CorePartName", "ConfigPathName",
    }) do
        local n = normalizeTypeName(inst:GetAttribute(key))
        if n then return n end
    end
    return nil
end

local function discoverPlantTypeName(plant)
    if not plant then return nil end
    local n = pickTypeFromInst(plant)
    if n then return n end
    for _, ch in ipairs(plant:GetChildren()) do
        n = pickTypeFromInst(ch)
        if n then return n end
        if ch.Name == "Fruits" or ch.Name == "Fruit" then
            for _, fruit in ipairs(ch:GetChildren()) do
                n = pickTypeFromInst(fruit)
                if n then return n end
            end
        end
    end
    return nil
end

local function stampPlantTypeAttrs(plant, data)
    if not plant then return nil end
    local name = seedNameFromData(data) or discoverPlantTypeName(plant)
    if not name then
        local uid = tonumber(plant:GetAttribute("UserId"))
        local pid = plant:GetAttribute("PlantId")
        if uid and pid ~= nil then
            local ps = LP:FindFirstChild("PlayerScripts")
            local c = ps and ps:FindFirstChild("Controllers")
            local m = c and c:FindFirstChild("GardenSyncController")
            if m then
                pcall(function()
                    local sync = require(m)
                    if type(sync) == "table" and type(sync.GetPlant) == "function" then
                        name = seedNameFromData(sync:GetPlant(uid, pid))
                    end
                end)
            end
        end
    end
    if not name then return nil end
    pcall(function()
        if plant:GetAttribute("SeedName") == nil then
            plant:SetAttribute("SeedName", name)
        end
        if plant:GetAttribute("ItemName") == nil then
            plant:SetAttribute("ItemName", name)
        end
    end)
    return name
end

local function stripOtherPlantShell(plant, data)
    if not plant or not plant.Parent then return end
    -- proxy dulu selagi geometry masih ada (pivot benar untuk watering)
    ensureProxy(plant)
    stampPlantTypeAttrs(plant, data)
    for _, c in ipairs(plant:GetChildren()) do
        if not isKeepInstance(c) then
            if c:IsA("Folder") and (c.Name == "Fruits" or c.Name == "Fruit") then
                pcall(function() c:ClearAllChildren() end)
            else
                pcall(function() c:Destroy() end)
            end
        end
    end
end

local function folderHasTypedPlant(folder, typeName, except)
    if not folder or not typeName then return false end
    local want = string.lower(tostring(typeName))
    for _, ch in ipairs(folder:GetChildren()) do
        if ch ~= except and ch:IsA("Model") and not isSprinkler(ch) then
            local k = normalizeTypeName(ch:GetAttribute("SeedName"))
                or normalizeTypeName(ch:GetAttribute("ItemName"))
                or discoverPlantTypeName(ch)
            if k and string.lower(k) == want then
                return true
            end
        end
    end
    return false
end

local function plantTypeKey(plant)
    -- stamp dulu dari child/fruit sebelum strip (UI sprinkler baca SeedName di model)
    local name = stampPlantTypeAttrs(plant)
        or normalizeTypeName(plant:GetAttribute("SeedName"))
        or normalizeTypeName(plant:GetAttribute("ConfigPathName"))
        or normalizeTypeName(plant:GetAttribute("ItemName"))
        or discoverPlantTypeName(plant)
    if name and name ~= "" then return name end
    -- jangan pakai plant.Name (UUID) — itu bikin keep semua + tipe UI kosong
    return "_pending"
end

local function tunePrompt(pr)
    if not pr or not pr:IsA("ProximityPrompt") then return end
    pcall(function()
        if hideHarvestWanted() then
            pr.Enabled = false
            pr.MaxActivationDistance = 0
            return
        end
        pr.Enabled = true
        pr.MaxActivationDistance = 32
        pr.RequiresLineOfSight = false
        pr.HoldDuration = 0
    end)
end

----------------------------------------------------------------
-- OWN hide: LTM only (jangan reparent — biar restore 100%)
----------------------------------------------------------------
local function ltmTree(inst, on)
    if not inst then return end
    local mod = on and 1 or 0
    local function one(p)
        if not p:IsA("BasePart") then return end
        if isKeepPart(p) then return end
        pcall(function()
            p.LocalTransparencyModifier = mod
            if on then
                p.CastShadow = false
                if p.Name ~= "CollectProxy" and p.Name ~= "HarvestPart" then
                    p.CanCollide = false
                end
            end
        end)
    end
    if inst:IsA("BasePart") then one(inst) end
    for _, d in ipairs(inst:GetDescendants()) do
        if d:IsA("BasePart") then
            one(d)
        elseif on and (d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam")
            or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles")
            or d:IsA("Highlight") or d:IsA("SelectionBox")) then
            pcall(function() d.Enabled = false end)
        elseif (not on) and (d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam")
            or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles")) then
            pcall(function() d.Enabled = true end)
        end
    end
end

-- nama lama: stashVisual — sekarang LTM only (no Parent move)
local function stashVisual(inst, homePlant)
    if not inst or not inst.Parent or not homePlant then return false end
    if isKeepInstance(inst) then return false end
    if inst.Name == A.PLANT_STASH or inst.Name == A.STASH_NAME then return false end
    if B.stashMap[inst] then
        ltmTree(inst, true)
        return false
    end
    -- legacy: kalau sempat ter-reparent ke _GAG2Stash, kembalikan dulu ke plant
    if inst.Parent and inst.Parent.Name == A.PLANT_STASH and inst.Parent.Parent == homePlant then
        pcall(function() inst.Parent = homePlant end)
    end
    B.stashMap[inst] = homePlant
    ltmTree(inst, true)
    B.stats.stashed += 1
    return true
end

----------------------------------------------------------------
-- Garden spawn (LoadingScreen attrs) — BUKAN tunggu click/skip UI
----------------------------------------------------------------
local function countOwnPlants()
    local plot = myPlot()
    if not plot then return 0 end
    local n = 0
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        n += #folder:GetChildren()
    end
    return n
end

local function isGardenSpawnComplete()
    -- Jangan nunggu LoadingScreenDone / click — itu UI only (+ hold 5s)
    if LP:GetAttribute("LoadingScreenDone") == true then
        return true
    end
    local total = tonumber(LP:GetAttribute("GardenLoadingTotal"))
    local prog = tonumber(LP:GetAttribute("GardenLoadingProgress")) or 0
    if total and total > 0 then
        return prog >= total
    end
    return false
end

local function waitGardenSpawnComplete(timeoutSec)
    G.__GAG2_RF_PHASE = "waitGarden"
    timeoutSec = tonumber(timeoutSec) or 90
    local t0 = os.clock()
    local lastCount, stableAt = -1, os.clock()
    local sawGardenJob = false
    local dataLoadedAt = nil
    dlog("waitGardenSpawn begin (GardenLoading* attrs only, skip UI hold/click)")
    while os.clock() - t0 < timeoutSec do
        local total = tonumber(LP:GetAttribute("GardenLoadingTotal"))
        local prog = tonumber(LP:GetAttribute("GardenLoadingProgress")) or 0
        if total and total > 0 then
            sawGardenJob = true
        end
        if CollectionService:HasTag(LP, "DataLoaded") and not dataLoadedAt then
            dataLoadedAt = os.clock()
        end

        local count = countOwnPlants()
        if count ~= lastCount then
            lastCount = count
            stableAt = os.clock()
        end
        local stable = (os.clock() - stableAt) >= 1.0

        -- Path A: garden job selesai (progress == total) + plant count settle
        if sawGardenJob and total and total > 0 and prog >= total and stable then
            dlog("waitGardenSpawn OK job %d/%d plants=%d ms=%.0f",
                prog, total, count, (os.clock() - t0) * 1000)
            task.wait(0.3)
            G.__GAG2_RF_PHASE = "idle"
            return true
        end

        -- Path B: loading UI sudah selesai (user skip / hide loading)
        if LP:GetAttribute("LoadingScreenDone") == true and stable then
            dlog("waitGardenSpawn via LoadingScreenDone plants=%d", count)
            G.__GAG2_RF_PHASE = "idle"
            return true
        end

        -- Path C: DataLoaded lama, tidak pernah ada GardenLoadingTotal (garden kosong / attr hilang)
        if dataLoadedAt and not sawGardenJob and CollectionService:HasTag(LP, "ControllersStarted")
            and (os.clock() - dataLoadedAt) >= 3.0 and stable then
            dlog("waitGardenSpawn no-job path plants=%d ms=%.0f", count, (os.clock() - t0) * 1000)
            G.__GAG2_RF_PHASE = "idle"
            return true
        end

        task.wait(0.12)
    end
    dlog("waitGardenSpawn timeout plants=%d complete=%s",
        countOwnPlants(), tostring(isGardenSpawnComplete()))
    G.__GAG2_RF_PHASE = "idle"
    return isGardenSpawnComplete() or myPlot() ~= nil
end

----------------------------------------------------------------
-- FRUIT: LTM only (detect tetap)
----------------------------------------------------------------
local function hideFruit(model)
    if not model or not model.Parent then return 0 end
    if not model:IsA("Model") then return 0 end
    -- debug_show_top10_heaviest: jangan hide ulang
    if model:GetAttribute("_GAG2KeepVisual") == true then return 0 end
    -- soft shell: jangan CollectProxy; part hanya di dalam UUID
    if model:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
        ensureProxy(model)
    end
    local n = 0
    for _, d in ipairs(model:GetDescendants()) do
        if d:IsA("ProximityPrompt") then
            tunePrompt(d)
        elseif d:IsA("BasePart") then
            pcall(function()
                d.LocalTransparencyModifier = 1
                d.CastShadow = false
                if d.Name == "CollectProxy" then
                    d.CanQuery = true
                else
                    d.CanCollide = false
                end
            end)
            n += 1
        elseif d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam")
            or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
            pcall(function() d.Enabled = false end)
        end
    end
    pcall(function() model:SetAttribute(A.FRUIT_ATTR, true) end)
    local fp = model.Parent
    if fp and (fp.Name == "Fruits" or fp.Name == "Fruit") then
        cleanupLooseFruitProxies(fp.Parent)
    end
    B.stats.fruits += 1
    return n
end

----------------------------------------------------------------
-- POHON: LTM hide. Fruits folder → hideFruit.
----------------------------------------------------------------
local function hidePlantTree(plant)
    if not plant or not plant.Parent then return 0 end
    if isSprinkler(plant) then return 0 end
    if isFruitModel(plant) then return hideFruit(plant) end

    ensureProxy(plant)
    local n = 0
    local kids = plant:GetChildren()
    for i = 1, #kids do
        local ch = kids[i]
        if isKeepInstance(ch) then
            if ch:IsA("Folder") and (ch.Name == "Fruits" or ch.Name == "Fruit") then
                bindFruitsFolderCleanup(ch)
                cleanupLooseFruitProxies(plant)
                for _, fruit in ipairs(ch:GetChildren()) do
                    if fruit:IsA("Model") and fruit:GetAttribute("FruitId") ~= nil then
                        n += hideFruit(fruit)
                    elseif fruit:IsA("BasePart") and LOOSE_PROXY_NAMES[fruit.Name] then
                        pcall(function() fruit:Destroy() end)
                    end
                    sliceYield()
                end
            end
        elseif ch:IsA("Model") and isFruitModel(ch) then
            n += hideFruit(ch)
        else
            if stashVisual(ch, plant) then
                n += 1
            end
        end
        if i % A.BATCH == 0 then sliceYield() end
    end

    pcall(function() plant:SetAttribute(A.TREE_ATTR, true) end)
    return n
end

----------------------------------------------------------------
-- RESTORE own plants (LTM clear + legacy stash folders)
----------------------------------------------------------------
local function findOwnPlantByKey(key)
    key = tostring(key or "")
    if key == "" then return nil end
    local plot = myPlot()
    if not plot then return nil end
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if tostring(plant:GetAttribute("PlantId") or "") == key
                or plant.Name == key then
                return plant
            end
        end
    end
    return nil
end

local function restoreInstToPlant(inst, home)
    if not inst or not inst.Parent or not home or not home.Parent then return false end
    if inst.Parent ~= home then
        local ok = pcall(function()
            inst.Parent = home
        end)
        if not (ok and inst.Parent == home) then
            return false
        end
    end
    ltmTree(inst, false)
    return true
end

local function restoreOwnPlants()
    local t0 = os.clock()
    local n = 0
    local dead = {}

    for inst, home in pairs(B.stashMap) do
        if not inst or not inst.Parent then
            dead[#dead + 1] = inst
        else
            local target = (home and home.Parent) and home or inst.Parent
            if target and target.Name == A.PLANT_STASH then
                target = target.Parent
            end
            if target then
                if restoreInstToPlant(inst, target) then
                    n += 1
                    B.stats.restored += 1
                else
                    ltmTree(inst, false)
                    n += 1
                    B.stats.restored += 1
                end
            end
            dead[#dead + 1] = inst
        end
        if n % A.BATCH == 0 then sliceYield() end
    end
    for i = 1, #dead do
        B.stashMap[dead[i]] = nil
    end

    local plot = myPlot()
    if plot then
        for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
            for _, plant in ipairs(folder:GetChildren()) do
                local bucket = plant:FindFirstChild(A.PLANT_STASH)
                if bucket and bucket:IsA("Folder") then
                    local kids = bucket:GetChildren()
                    for i = 1, #kids do
                        if restoreInstToPlant(kids[i], plant) then
                            n += 1
                            B.stats.restored += 1
                        end
                        if i % A.BATCH == 0 then sliceYield() end
                    end
                    if #bucket:GetChildren() == 0 then
                        pcall(function() bucket:Destroy() end)
                    end
                end

                ltmTree(plant, false)
                pcall(function() plant:SetAttribute(A.TREE_ATTR, nil) end)

                local fr = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                if fr then
                    for _, fruit in ipairs(fr:GetChildren()) do
                        pcall(function() fruit:SetAttribute(A.FRUIT_ATTR, nil) end)
                        ltmTree(fruit, false)
                    end
                end
                n += 1
                sliceYield()
            end
        end
    end

    local root = LP:FindFirstChild("PlayerGui")
    root = root and root:FindFirstChild(A.STASH_NAME)
    if not root then root = LP:FindFirstChild(A.STASH_NAME) end
    if root then
        for _, bucket in ipairs(root:GetChildren()) do
            local home = findOwnPlantByKey(bucket.Name)
            if home then
                local kids = bucket:GetChildren()
                for i = 1, #kids do
                    if restoreInstToPlant(kids[i], home) then
                        n += 1
                        B.stats.restored += 1
                    end
                    if i % A.BATCH == 0 then sliceYield() end
                end
            end
            if #bucket:GetChildren() == 0 then
                pcall(function() bucket:Destroy() end)
            end
        end
        if #root:GetChildren() == 0 then
            pcall(function() root:Destroy() end)
        end
    end

    table.clear(B.stashMap)
    dlog("RestoreOwn cleared=%d plants=%d ms=%.0f", n, countOwnPlants(), (os.clock() - t0) * 1000)
    return n
end

----------------------------------------------------------------
-- Restore dari garden DATA (PVC / GardenSync) — jalur resmi game
----------------------------------------------------------------
local function getNetworking()
    local ok, net = pcall(function()
        return require(ReplicatedStorage:WaitForChild("SharedModules"):WaitForChild("Networking", 5))
    end)
    return (ok and type(net) == "table") and net or nil
end

local function getGardenSync()
    local ps = LP:FindFirstChild("PlayerScripts")
    local c = ps and ps:FindFirstChild("Controllers")
    local m = c and c:FindFirstChild("GardenSyncController")
    if not m then return nil end
    local ok, mod = pcall(require, m)
    return (ok and type(mod) == "table") and mod or nil
end

local function requestGardensFire(force)
    -- Global: reload RF jangan dobel-spam (hitch engine, bukan Lua Heartbeat).
    if force ~= true then
        local now = os.clock()
        local gap = tonumber(CONFIG.requestGardensMinSec) or 12
        if (now - (tonumber(G.__GAG2_RG_AT) or 0)) < gap then
            return false
        end
        G.__GAG2_RG_AT = now
    else
        G.__GAG2_RG_AT = os.clock()
    end
    local net = getNetworking()
    local rg = net and net.Garden and net.Garden.RequestGardens
    if not rg then
        dlog("RequestGardens missing")
        return false
    end
    local ok, err = pcall(function()
        if type(rg.Fire) == "function" then
            rg:Fire()
        elseif type(rg) == "function" then
            rg()
        end
    end)
    if not ok then
        dlog("RequestGardens fail: %s", tostring(err))
        return false
    end
    dlog("RequestGardens fired")
    return true
end

local function reconcileLocalGarden()
    local sync = getGardenSync()
    if not sync then
        dlog("GardenSyncController missing")
        return false
    end
    if type(sync.ReconcileLocalGarden) == "function" then
        local ok, err = pcall(function()
            sync:ReconcileLocalGarden()
        end)
        if not ok then
            dlog("ReconcileLocalGarden fail: %s", tostring(err))
            return false
        end
        dlog("ReconcileLocalGarden ok")
        return true
    end
    return false
end

-- Isi ulang plant visual yang hilang dari cache PVC (sama OnPlantVisualCheck)
local function respawnMissingOwnPlants()
    local sync = getGardenSync()
    local pvc = getPVC()
    if not sync or not pvc then return 0 end
    if type(sync.GetGarden) ~= "function" or type(pvc.SpawnPlantFromData) ~= "function" then
        return 0
    end
    local garden = nil
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then return 0 end

    local n = 0
    for plantId, data in pairs(garden) do
        if type(data) == "table" then
            local existing = nil
            if type(pvc.GetSpawnedPlant) == "function" then
                pcall(function()
                    existing = pvc:GetSpawnedPlant(LP.UserId, plantId)
                end)
            end
            local need = (not existing) or (typeof(existing) == "Instance" and not existing.Parent)
            if need then
                local ok = pcall(function()
                    pvc:SpawnPlantFromData(LP.UserId, plantId, data)
                end)
                if ok then
                    n += 1
                    B.stats.restored += 1
                end
                sliceYield()
            end
        end
    end
    if n > 0 then
        dlog("respawnMissingOwnPlants count=%d", n)
    end
    return n
end

