local function isGardenLoadingNow()
    if LP:GetAttribute("LoadingScreenActive") == true then
        return true
    end
    if LP:GetAttribute("LoadingScreenDone") == true then
        return false
    end
    local total = tonumber(LP:GetAttribute("GardenLoadingTotal"))
    local prog = tonumber(LP:GetAttribute("GardenLoadingProgress")) or 0
    if total and total > 0 then
        return prog < total
    end
    return false
end

----------------------------------------------------------------
-- BLOCK visual init (anti CPU spike saat loading)
----------------------------------------------------------------
-- Strip mesh SAJA. Jangan hancurkan Model / Folder Fruits / attrs (PlantId/FruitId).
-- PENTING: FruitSpawnLocations BasePart HARUS tetap — FVC SpawnFruitFromData gagal diam tanpa itu.
local function isDetectKeepInstance(d)
    if not d then return true end
    if isKeepInstance(d) then return true end
    if d:IsA("ProximityPrompt") or d:IsA("Attachment") or d:IsA("ValueBase") then
        return true
    end
    -- ESP GAG2 (garden/backpack): jangan di-strip → hindari recreate Billboard tiap poll
    if d:IsA("BillboardGui") then
        local nm = d.Name
        if nm == "_GAG2FG_ESP" or nm == "_GAG2FBP_ESP"
            or nm == "SprinklerTimerUI"
            or d:GetAttribute("_GAG2_ESP") == true then
            return true
        end
    end
    if d.Name == "HarvestPart" or d.Name == "CollectProxy" or d.Name == "ShellBody"
        or d.Name == "_GAG2BeamHit" or d.Name == A.PLANT_STASH then
        -- orphan lepas di folder Fruits → jangan keep (biar cleanup bisa destroy)
        local p = d.Parent
        if p and (p.Name == "Fruits" or p.Name == "Fruit") and d:IsA("BasePart") then
            return false
        end
        return true
    end
    -- GardenSync: plant.Base (index) — kalau hilang, update mutasi live error & skip
    if d.Name == "Base" and d:IsA("BasePart") then
        return true
    end
    -- Auto pot pickup/break
    if d.Name == "PotVisual" or d.Name == "Pot" then
        return true
    end
    if d:IsA("Folder") and (d.Name == "Fruits" or d.Name == "Fruit"
        or d.Name == "FruitSpawnLocations" or d.Name == "FruitSpawnLocation"
        or d.Name == "SpawnLocations") then
        return true
    end
    -- spawn locator parts (anak FruitSpawnLocations)
    if d:IsA("BasePart") then
        local p = d.Parent
        if p and (p.Name == "FruitSpawnLocations" or p.Name == "FruitSpawnLocation"
            or p.Name == "SpawnLocations") then
            return true
        end
        local n = tostring(d.Name or "")
        if n:find("Spawn", 1, true) or n:find("Location", 1, true) then
            return true
        end
    end
    -- container model fruit/plant — jangan Destroy; anak visual di-strip terpisah
    if d:IsA("Model") and (d:GetAttribute("FruitId") ~= nil or d:GetAttribute("PlantId") ~= nil) then
        return true
    end
    return false
end

-- GardenSyncController akses plant.Base — harus ada meski visual di-strip
local function ensurePlantSyncBase(plant)
    if not plant or not plant:IsA("Model") or not plant.Parent then return nil end
    if plant:GetAttribute("PlantId") == nil then return nil end
    local base = plant:FindFirstChild("Base")
    if base and base:IsA("BasePart") then
        pcall(function()
            base.Transparency = 1
            base.CanCollide = false
            base.CanQuery = false
            base.CanTouch = false
            base.CastShadow = false
            base.Anchored = true
            base.LocalTransparencyModifier = 1
        end)
        return base
    end
    local cf = nil
    pcall(function() cf = plant:GetPivot() end)
    if not cf then
        local pp = plant.PrimaryPart
        if pp and pp:IsA("BasePart") then cf = pp.CFrame end
    end
    if not cf then
        for _, d in ipairs(plant:GetDescendants()) do
            if d:IsA("BasePart") then
                cf = d.CFrame
                break
            end
        end
    end
    if not cf then return nil end
    local ok, part = pcall(function()
        local p = Instance.new("Part")
        p.Name = "Base"
        p.Size = Vector3.new(0.2, 0.2, 0.2)
        p.Transparency = 1
        p.CanCollide = false
        p.CanQuery = false
        p.CanTouch = false
        p.CastShadow = false
        p.Anchored = true
        p.Massless = true
        p.CFrame = cf
        p.Parent = plant
        return p
    end)
    return ok and part or nil
end

-- Pastikan FruitSpawnLocations punya BasePart (FVC + status Mx sprinkler/watering)
-- Kapasitas = max buah / pohon (SeedData), BUKAN jumlah buah yang sedang ada.
local function seedFruitCapacity(seedName)

    seedName = tostring(seedName or "")
    if seedName == "" then return nil end
    local cached = B._seedSlotCache[seedName]
    if cached == false then return nil end
    if type(cached) == "number" then return cached end
    local n = nil
    pcall(function()
        local pvc = getPVC()
        if pvc and type(pvc.GetSeedData) == "function" then
            local e = pvc:GetSeedData(seedName)
            if type(e) == "table" then
                if e.IsSingleHarvest == true then n = 1 end
                n = n or tonumber(e.FruitSlots) or tonumber(e.MaxFruits) or tonumber(e.MaxFruit)
                    or tonumber(e.MaxFruitCount) or tonumber(e.FruitAmount) or tonumber(e.FruitsPerPlant)
                    or tonumber(e.FruitSpawnCount) or tonumber(e.FruitSpawnAmount)
            end
        end
        if n == nil and pvc and type(pvc.IsSingleHarvestPlant) == "function" then
            local ok, single = pcall(pvc.IsSingleHarvestPlant, pvc, seedName)
            if ok and single == true then n = 1 end
        end
    end)
    if n == nil then
        pcall(function()
            local SeedData = require(ReplicatedStorage.SharedModules.SeedData)
            local e = type(SeedData) == "table" and SeedData[seedName]
            if type(e) ~= "table" and type(SeedData) == "table" then
                local want = string.lower(seedName)
                for k, v in pairs(SeedData) do
                    if type(v) == "table" then
                        local nm = tostring(v.SeedName or v.Name or k)
                        if string.lower(nm) == want then e = v break end
                    end
                end
            end
            if type(e) == "table" then
                if e.IsSingleHarvest == true then n = 1 end
                n = n or tonumber(e.FruitSlots) or tonumber(e.MaxFruits) or tonumber(e.MaxFruit)
                    or tonumber(e.MaxFruitCount) or tonumber(e.FruitAmount) or tonumber(e.FruitsPerPlant)
            end
        end)
    end
    -- Kapasitas nyata bisa 300+/pohon — JANGAN clamp 64 (Mx sprinkler jadi undercount)
    if n and n > 0 then
        B._seedSlotCache[seedName] = math.clamp(math.floor(n), 1, 2048)
        return B._seedSlotCache[seedName]
    end
    B._seedSlotCache[seedName] = false
    return nil
end

-- Kapasitas buah/pohon (untuk attr + Mx). Locator fisik tetap dibatasi terpisah.
local function desiredFruitSpawnSlots(plant)

    if not plant then return 1 end
    local n = tonumber(plant:GetAttribute("FruitSlots"))
        or tonumber(plant:GetAttribute("MaxFruits"))
        or tonumber(plant:GetAttribute("MaxFruit"))
        or tonumber(plant:GetAttribute("MaxFruitCount"))
        or tonumber(plant:GetAttribute("FruitCountMax"))
    if not n or n <= 0 then
        local seedName = plant:GetAttribute("SeedName")
            or plant:GetAttribute("ItemName")
            or plant:GetAttribute("ConfigPathName")
        n = seedFruitCapacity(seedName)
    end
    if n and n > 0 then
        n = math.clamp(math.floor(n), 1, A.FRUIT_CAP_MAX)
        pcall(function()
            local cur = tonumber(plant:GetAttribute("FruitSlots"))
            if cur == nil or cur < n then
                plant:SetAttribute("FruitSlots", n)
            end
        end)
        return n
    end
    local folder = plant:FindFirstChild("FruitSpawnLocations")
        or plant:FindFirstChild("FruitSpawnLocation")
        or plant:FindFirstChild("SpawnLocations")
    local lc = 0
    if folder then
        for _, ch in ipairs(folder:GetChildren()) do
            if ch:IsA("BasePart") then lc += 1 end
        end
    end
    -- Jangan pakai #Fruits sebagai kapasitas (under-count saat buah belum penuh)
    return math.clamp(math.max(lc, 1), 1, A.FRUIT_CAP_MAX)
end

local function ensureFruitSpawnLocations(plant, minSlots)
    if not plant or not plant.Parent then return nil end
    local folder = plant:FindFirstChild("FruitSpawnLocations")
        or plant:FindFirstChild("FruitSpawnLocation")
        or plant:FindFirstChild("SpawnLocations")
    if not folder then
        folder = Instance.new("Folder")
        folder.Name = "FruitSpawnLocations"
        folder.Parent = plant
    end
    local parts = {}
    for _, ch in ipairs(folder:GetChildren()) do
        if ch:IsA("BasePart") then
            parts[#parts + 1] = ch
        end
    end
    -- attr kapasitas penuh; part locator cukup sedikit (anti lag)
    local cap = desiredFruitSpawnSlots(plant)
    local want = math.max(
        math.floor(tonumber(minSlots) or 0),
        math.min(cap, A.FRUIT_LOC_PARTS_MAX),
        #parts
    )
    -- FVC pakai GetChildren()[SpawnLocationIndex]. Kalau index > cap, slot wajib ada.
    local needIdx = math.floor(tonumber(minSlots) or 0)
    want = math.clamp(want, 1, math.max(A.FRUIT_LOC_PARTS_MAX, needIdx))
    local cf = plant:GetPivot()
    while #parts < want do
        local p = Instance.new("Part")
        p.Name = tostring(#parts + 1)
        p.Size = Vector3.new(0.5, 0.5, 0.5)
        p.Transparency = 1
        p.Anchored = true
        p.CanCollide = false
        p.CanTouch = false
        p.CanQuery = false
        p.CastShadow = false
        p.CFrame = cf
        p.Parent = folder
        parts[#parts + 1] = p
    end
    for i = 1, #parts do
        pcall(function()
            parts[i].Transparency = 1
            parts[i].CanCollide = false
            parts[i].CastShadow = false
        end)
    end
    return folder, parts
end

local function _pickDataNum(data, keys)
    if type(data) ~= "table" then return nil end
    for i = 1, #keys do
        local v = tonumber(data[keys[i]])
        if v ~= nil then return v end
    end
    return nil
end

-- FVC SpawnFruitFromData: SetAttribute("SizeMulti", p225.SizeMultiplier or 1)
-- Hanya field sync itu — jangan tebak Scale/Size/FruitScale.
local function _pickDisplaySizeMulti(data)
    local sm = _pickDataNum(data, { "SizeMultiplier", "SizeMulti" })
    if sm and sm > 0 then return sm end
    return nil
end

-- FVC CalculateFruitWeight: GrowData.BaseWeight * SizeMulti * overtime
local function _pickDisplayWeight(data, bw, sm, og)
    bw = tonumber(bw)
    sm = tonumber(sm)
    og = tonumber(og) or 1
    if og <= 0 then og = 1 end
    if bw and bw > 0 and sm and sm > 0 then
        return bw * sm * og
    end
    return nil
end

-- FVC u4[PlantName].GrowData.BaseWeight (bukan attr Weight di model)
local _fruitBwCache = {}
local function _fruitModuleBaseWeight(plantName)
    plantName = tostring(plantName or "")
    if plantName == "" then return nil end
    local cached = _fruitBwCache[plantName]
    if cached ~= nil then
        return cached > 0 and cached or nil
    end
    local bw = nil
    pcall(function()
        local folder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
        folder = folder and folder:FindFirstChild("Fruits")
        local modScript = folder and folder:FindFirstChild(plantName)
        if not (modScript and modScript:IsA("ModuleScript")) then return end
        local mod = require(modScript)
        bw = type(mod) == "table" and type(mod.GrowData) == "table"
            and tonumber(mod.GrowData.BaseWeight) or nil
    end)
    _fruitBwCache[plantName] = (bw and bw > 0) and bw or 0
    return bw
end

-- Cache: seed → true/false (HANYA flag IsSingleHarvest, bukan MaxFruits==1)
local function seedIsSingleHarvest(seedName)

    seedName = tostring(seedName or "")
    if seedName == "" then return false end
    local cached = B._seedSingleHarvestCache[seedName]
    if cached ~= nil then return cached == true end
    local single = false
    pcall(function()
        local pvc = getPVC()
        if pvc and type(pvc.IsSingleHarvestPlant) == "function" then
            local ok, v = pcall(pvc.IsSingleHarvestPlant, pvc, seedName)
            if ok and v == true then single = true end
        end
        if not single and pvc and type(pvc.GetSeedData) == "function" then
            local e = pvc:GetSeedData(seedName)
            if type(e) == "table" and e.IsSingleHarvest == true then single = true end
        end
    end)
    if not single then
        pcall(function()
            local SeedData = require(ReplicatedStorage.SharedModules.SeedData)
            local e = type(SeedData) == "table" and SeedData[seedName]
            if type(e) ~= "table" and type(SeedData) == "table" then
                local want = string.lower(seedName)
                for k, v in pairs(SeedData) do
                    if type(v) == "table" then
                        local nm = tostring(v.SeedName or v.Name or k)
                        if string.lower(nm) == want then e = v break end
                    end
                end
            end
            if type(e) == "table" and e.IsSingleHarvest == true then single = true end
        end)
    end
    B._seedSingleHarvestCache[seedName] = single
    return single
end

local function plantIsSingleHarvest(plantData, plant)
    if type(plantData) == "table" then
        if plantData.IsSingleHarvest == true or plantData.SingleHarvest == true then
            return true
        end
    end
    if typeof(plant) == "Instance" and plant:GetAttribute("IsSingleHarvest") == true then
        return true
    end
    local seedName = nil
    if type(plantData) == "table" then
        seedName = plantData.SeedName or plantData.ItemName or plantData.PlantName or plantData.FruitType
    end
    if typeof(plant) == "Instance" then
        seedName = seedName
            or plant:GetAttribute("SeedName")
            or plant:GetAttribute("ItemName")
            or plant:GetAttribute("FruitType")
    end
    return seedIsSingleHarvest(seedName)
end

local function resolveFruitDataFromSync(plantId, fruitId, fallback)
    local data = type(fallback) == "table" and fallback or nil
    local sync = getGardenSync()
    if not sync or type(sync.GetPlant) ~= "function" then return data end
    local plantData = nil
    pcall(function()
        plantData = sync:GetPlant(LP.UserId, plantId)
    end)
    if type(plantData) ~= "table" then return data end
    local fruits = plantData.Fruits or plantData.fruits or plantData.Fruit
    local want = tostring(fruitId or "")

    -- Single-harvest / plant-level: Age di plant sync, FruitId ""
    if type(fruits) ~= "table" or next(fruits) == nil or want == "" then
        if want == "" or plantIsSingleHarvest(plantData, nil) then
            if data == nil then return plantData end
            -- Jangan copy Mutation dari plant → fruit (AC anggap buah polos bermutasi).
            local skipMut = {
                Mutation = true, mutation = true, MutationName = true,
                Mutations = true, mutations = true, Mut = true, mut = true,
                FruitMutation = true,
                Gold = true, Rainbow = true, Glow = true, Electric = true,
                Frozen = true, Bloodlit = true, Chained = true, Starstruck = true,
                Aurora = true, Ignited = true, Eclipsed = true, Veil = true,
            }
            for k, v in pairs(plantData) do
                if data[k] == nil
                    and k ~= "Fruits" and k ~= "fruits" and k ~= "Fruit"
                    and not skipMut[k] then
                    data[k] = v
                end
            end
            return data
        end
        if type(fruits) ~= "table" then
            if data == nil then data = plantData end
            return data
        end
    end

    local found = nil
    if want ~= "" then
        if #fruits > 0 then
            for i = 1, #fruits do
                local d = fruits[i]
                if type(d) == "table" then
                    local id = d.FruitId or d.fruitId or d.Id or d.id or d.UUID or d.Uuid
                    if tostring(id) == want then found = d break end
                end
            end
        else
            for fid, d in pairs(fruits) do
                if tostring(fid) == want and type(d) == "table" then
                    found = d
                    break
                elseif type(d) == "table" then
                    local id = d.FruitId or d.fruitId or d.Id or d.id
                    if tostring(id) == want then found = d break end
                end
            end
        end
    end
    if type(found) == "table" then
        if type(data) == "table" then
            for k, v in pairs(found) do
                if data[k] == nil then data[k] = v end
            end
            -- Mutasi live: SELALU ambil dari sync (jangan keblokir data stale / shell lama)
            for _, key in ipairs({
                "Mutation", "mutation", "MutationName", "Mutations", "mutations", "Mut",
                "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
                "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed",
            }) do
                if found[key] ~= nil then
                    data[key] = found[key]
                end
            end
            return data
        end
        return found
    end
    return data
end

-- Game cuma kasih HarvestPrompt kalau mature. Soft shell kita dulu nempel ke SEMUA
-- buah → match filter besar tapi CollectFruit server tolak (Fire client tetap "ok").
local function fruitDataHarvestReady(data, model)
    data = type(data) == "table" and data or {}
    local isShell = model and model:GetAttribute(A.FRUIT_SHELL_ATTR) == true
    local age = _pickDataNum(data, { "Age", "age" })
    local maxAge = _pickDataNum(data, { "MaxAge", "maxAge" })
    if model then
        if age == nil then age = tonumber(model:GetAttribute("Age")) end
        if maxAge == nil then maxAge = tonumber(model:GetAttribute("MaxAge")) end
    end

    -- Soft shell: Age/MaxAge WAJIB. Flag Grown/CanHarvest sering true padahal Age < MaxAge
    -- (debug: fakeTagged=178 saat tagged=648).
    if isShell then
        if maxAge == nil or age == nil then
            return false
        end
        return age + 1e-4 >= maxAge
    end

    if data.CanHarvest == true or data.Harvestable == true
        or data.IsReady == true or data.Grown == true
        or data.Ready == true or data.IsGrown == true then
        return true
    end
    local progress = _pickDataNum(data, { "Progress", "GrowthProgress", "GrowProgress", "Percent" })
    if progress ~= nil then
        if progress >= 0.999 or (progress > 1 and progress >= 99.9) then
            return true
        end
        if progress < 0.999 and progress <= 1 then
            return false
        end
    end
    if maxAge == nil then
        return true
    end
    if age == nil then
        return false
    end
    return age + 1e-4 >= maxAge
end

-- AutoCollect: immature = Collected (+ untag). Ripe = clear Collected + tag.
-- (Enabled sering false karena Hide Harvest — jangan andalkan Enabled untuk ripe gate.)
local function applyShellCollectGate(model, ready)
    if not model then return end
    local pr = model:FindFirstChild("HarvestPrompt", true)
    if not pr or not pr:IsA("ProximityPrompt") then return end
    -- FAR pause OFF default: jangan untag semua shell (Info Fruits 0 / AC kosong).
    if ready and CONFIG.pauseFarFromPlot ~= false
        and (S.farPaused == true or isInCulledFolder(model) or isFarFromOwnPlot()) then
        ready = false
    end
    if ready then
        -- AC pending confirm: jangan clear Collected (ripe poll tiap 1.5s)
        local pid = model:GetAttribute("PlantId")
        local fid = model:GetAttribute("FruitId")
        if pid ~= nil and fid ~= nil then
            local uid = tonumber(model:GetAttribute("UserId")) or LP.UserId
            local pkey = string.format("%s_%s_%s", tostring(uid), tostring(pid), tostring(fid))
            local exp = S.pendingCollect[pkey]
            if type(exp) == "number" and os.clock() <= exp then
                return
            end
        end
        pcall(function()
            pr:SetAttribute("Collected", nil)
            pr.MaxActivationDistance = 32
            tagHarvestPrompt(pr)
            tunePrompt(pr) -- boleh Enabled=false jika Hide Harvest; tag tetap
        end)
    else
        pcall(function()
            pr:SetAttribute("Collected", true)
            pr.Enabled = false
            pr.MaxActivationDistance = 0
            if CollectionService:HasTag(pr, "HarvestPrompt") then
                pr:RemoveTag("HarvestPrompt")
            end
        end)
    end
end

-- Nama mutasi dari game (MutationData / PlantListView) — cache, bukan list manual
local MUT_DATA_SKIP = {

    age = true, maxage = true, weight = true, baseweight = true, sizemulti = true,
    overtimegrowth = true, overtime = true, progress = true, scale = true,
    fruitid = true, plantid = true, userid = true, id = true, uuid = true,
    seedname = true, itemname = true, plantname = true, fruittype = true,
    variant = true, canharvest = true, harvestable = true, isready = true,
    grown = true, ready = true, isgrown = true, mutation = true, mutations = true,
    mutationname = true, fruits = true, position = true, cframe = true,
}

local function listGameMutationNames()
    if S._mutNameCache then return S._mutNameCache end
    local names, seen = {}, {}
    local function push(n)
        n = tostring(n or ""):match("^%s*(.-)%s*$")
        if not n or n == "" then return end
        local low = string.lower(n)
        if MUT_DATA_SKIP[low] or low == "none" or low == "normal" or low == "nomutation" then
            return
        end
        if seen[low] then return end
        seen[low] = true
        names[#names + 1] = n
    end
    pcall(function()
        local sm = ReplicatedStorage:FindFirstChild("SharedModules")
        local md = sm and sm:FindFirstChild("MutationData")
        if not md then return end
        local function scan(folder)
            if not folder then return end
            for _, ch in ipairs(folder:GetChildren()) do
                if ch:IsA("ModuleScript") then
                    push(ch.Name)
                elseif ch:IsA("Folder") then
                    scan(ch)
                end
            end
        end
        scan(md)
    end)
    pcall(function()
        local PLV = G.PlantListView or rawget(_G, "PlantListView")
        if type(PLV) == "table" and type(PLV.listMutationNames) == "function" then
            local ok, list = pcall(PLV.listMutationNames, PLV)
            if ok and type(list) == "table" then
                for _, n in ipairs(list) do push(n) end
            end
        end
    end)
    S._mutNameCache = names
    return names
end

local function stampMutationAttrs(model, data)
    if not model then return end
    data = type(data) == "table" and data or {}
    local found, seen = {}, {}
    local function add(name)
        name = tostring(name or ""):match("^%s*(.-)%s*$")
        if not name or name == "" then return end
        -- pecah kalau ketimpa "Glow+Glow"
        if string.find(name, "[%+%,%/]", 1) then
            for token in string.gmatch(name, "[^%+%,%/]+") do add(token) end
            return
        end
        local low = string.lower(name)
        if MUT_DATA_SKIP[low] or low == "none" or low == "normal" or low == "nomutation" then
            return
        end
        if seen[low] then return end
        seen[low] = true
        found[#found + 1] = name
    end

    -- 1) data GardenSync / mirror dulu (sumber truth live / rejoin)
    local raw = data.Mutation or data.mutation or data.MutationName
        or data.Mut or data.mut or data.FruitMutation
    if type(raw) == "string" and raw ~= "" then add(raw) end
    if type(raw) == "table" then
        if type(raw.Name) == "string" then add(raw.Name)
        elseif type(raw.Mutation) == "string" then add(raw.Mutation) end
    end

    -- 2) string Mutation di MODEL (MutationController listen ini)
    local onModel = model:GetAttribute("Mutation")
    if type(onModel) == "string" and onModel ~= "" then add(onModel) end

    local list = data.Mutations or data.mutations
    if type(list) == "table" then
        if #list > 0 then
            for i = 1, #list do add(list[i]) end
        else
            for k, v in pairs(list) do
                if v == true then add(k)
                elseif type(v) == "string" then add(v) end
            end
        end
    elseif type(list) == "string" and list ~= "" then
        add(list)
    end

    local gameNames = listGameMutationNames()
    -- Hanya nama mutasi resmi dari data sync / model. JANGAN pairs(data) semua bool
    -- (flag plant lain sering ikut → stamp Mutation palsu → AC lolos filter).
    for i = 1, #gameNames do
        local n = gameNames[i]
        if data[n] == true or model:GetAttribute(n) == true then add(n) end
    end

    if #found == 0 then return end

    -- MutationController.GetMutationModule(name) butuh NAMA MODULE EXACT
    -- ("Eclipsed"), BUKAN "Gold+Eclipsed" — itu yang bikin Eclipse gak apply
    -- sementara Gold/Glow spawn (nama tunggal) tetap aman.
    local primary = nil
    for _, pref in ipairs({
        "Eclipsed", "Veil", "Ignited", "Aurora", "Chained", "Starstruck",
        "Bloodlit", "Electric", "Frozen", "Glow", "Rainbow", "Gold",
    }) do
        if seen[string.lower(pref)] then
            primary = pref
            break
        end
    end
    if not primary then primary = found[1] end

    pcall(function()
        for i = 1, #gameNames do
            local n = gameNames[i]
            if model:GetAttribute(n) == true and not seen[string.lower(n)] then
                model:SetAttribute(n, nil)
            end
        end
        if type(onModel) == "string" and onModel ~= "" then
            for token in string.gmatch(onModel, "[^%+%,%/]+") do
                local t = tostring(token):match("^%s*(.-)%s*$")
                if t and t ~= "" and not seen[string.lower(t)] then
                    model:SetAttribute(t, nil)
                end
            end
        end
        model:SetAttribute("Mutation", primary)
        for i = 1, #found do
            model:SetAttribute(found[i], true)
        end
    end)
end

-- Mutation live: weather/FVC nulis ke fruit game. Soft shell client-only →
-- harus masuk cache FVC + lookup GetFruit jatuh ke shell, baru attr kebaca AC.
-- mutListenBound / mutMirroring / mutLive → di S/B (hemat local register)

local function lookupOwnFruitShell(fruitId, plantId)
    if fruitId == nil then return nil end
    local wantFid = tostring(fruitId)
    local wantPid = plantId ~= nil and tostring(plantId) or nil
    local plot = myPlot()
    if not plot then return nil end
    -- Ringan: cuma folder Plants (jangan GetTagged HarvestPrompt tiap lookup — CPU spike)
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if not plant:IsA("Model") then continue end
            if wantPid then
                local pid = plant:GetAttribute("PlantId")
                if pid ~= nil and tostring(pid) ~= wantPid then continue end
            end
            local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if not ff then continue end
            for _, ch in ipairs(ff:GetChildren()) do
                if ch:IsA("Model") and tostring(ch:GetAttribute("FruitId") or "") == wantFid then
                    return ch
                end
            end
        end
    end
    return nil
end

-- Soft shell: cuma HarvestPart/ShellBody (ringan, bukan GetDescendants)
local function softShellSetBeamQuery(shell, on)
    if not shell or shell:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then return end
    for _, name in ipairs({ "HarvestPart", "ShellBody", "CollectProxy" }) do
        local p = shell:FindFirstChild(name)
        if p and p:IsA("BasePart") then
            pcall(function()
                p.CanQuery = on == true
            end)
        end
    end
end

local function unregisterFruitShellFromFvc(fruitId)
    if fruitId == nil then return end
    local FVC = getFVC()
    if type(FVC) ~= "table" then return end
    local fid = tostring(fruitId)
    pcall(function()
        for _, key in ipairs({
            "Fruits", "fruits", "FruitCache", "fruitCache",
            "SpawnedFruits", "spawnedFruits", "_fruits", "FruitModels",
        }) do
            local t = rawget(FVC, key)
            if type(t) == "table" then
                t[fid] = nil
                t[fruitId] = nil
            end
        end
    end)
end

-- FVC OnFruitVisualCheck: `if not u3[userId_plantId_fruitId] then Spawn...`
-- u3 = upvalue privat — registerFruitShellInFvc ke FVC.Fruits TIDAK cukup.
local function fvcFruitKey(userId, plantId, fruitId)
    return string.format("%s_%s_%s", tostring(userId or LP.UserId), tostring(plantId), tostring(fruitId))
end

local function getDebugLib()
    local dbg = rawget(G, "debug") or rawget(_G, "debug")
    if type(dbg) == "table" then return dbg end
    if type(debug) == "table" then return debug end
    return nil
end

local function getFvcU3()
    if type(B.fvcU3) == "table" then return B.fvcU3 end
    local FVC = getFVC()
    if type(FVC) ~= "table" then return nil end
    -- Pakai orig GetSpawnedFruit (bukan wrapper) supaya upvalue = u3 privat
    local fn = B.fvcBackup.GetSpawnedFruit or FVC.GetSpawnedFruit
    if type(fn) ~= "function" then return nil end
    local dbg = getDebugLib()
    local getuv = dbg and dbg.getupvalue
    if type(getuv) ~= "function" and type(getupvalue) == "function" then
        getuv = getupvalue
    end
    if type(getuv) ~= "function" then return nil end
    for i = 1, 8 do
        local ok, a, b = pcall(getuv, fn, i)
        if not ok then break end
        -- debug.getupvalue → name, value | beberapa executor → value saja
        local val = nil
        if type(b) == "table" then
            val = b
        elseif type(a) == "table" then
            val = a
        end
        if type(val) == "table" then
            B.fvcU3 = val
            return val
        end
    end
    return nil
end

local function isPendingCollect(plantId, fruitId, userId)
    local key = fvcFruitKey(userId or LP.UserId, plantId, fruitId)
    local exp = S.pendingCollect[key]
    if type(exp) ~= "number" then return false end
    if os.clock() > exp then
        S.pendingCollect[key] = nil
        return false
    end
    return true
end

local function markPendingCollect(plantId, fruitId, userId, ttlSec)
    if plantId == nil or fruitId == nil then return end
    local key = fvcFruitKey(userId or LP.UserId, plantId, fruitId)
    local ttl = tonumber(ttlSec) or S.pendingCollectSec or 5.0
    S.pendingCollect[key] = os.clock() + math.max(0.5, ttl)
end

local function clearPendingCollect(plantId, fruitId, userId)
    if plantId == nil then return end
    S.pendingCollect[fvcFruitKey(userId or LP.UserId, plantId, fruitId)] = nil
end

local function bindSoftShellInFvcU3(shell, userId, plantId, fruitId)
    if not shell or plantId == nil or fruitId == nil then return end
    local t = getFvcU3()
    if type(t) ~= "table" then return end
    local key = fvcFruitKey(userId or LP.UserId, plantId, fruitId)
    -- Jangan overwrite fruit game hidup
    local cur = t[key]
    if typeof(cur) == "Instance" and cur.Parent and cur:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true
        and cur ~= shell then
        return
    end
    t[key] = shell
end

local function unbindSoftShellFromFvcU3(userId, plantId, fruitId)
    if plantId == nil or fruitId == nil then return end
    local t = getFvcU3()
    if type(t) ~= "table" then return end
    local key = fvcFruitKey(userId or LP.UserId, plantId, fruitId)
    local cur = t[key]
    if cur == nil then return end
    if typeof(cur) == "Instance" and cur:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
        return -- jangan hapus entry fruit game
    end
    t[key] = nil
end

-- Biar weather/MutationController nemu shell (bukan cuma fruit game di cache FVC).
-- Eclipse: soft shell luar top-N JANGAN register + CanQuery off (anti beam miss).
local function registerFruitShellInFvc(shell, fruitId)
    if not shell or fruitId == nil then return end
    local pid = shell:GetAttribute("PlantId")
    local isLive = shell:GetAttribute("_GAG2EclipseLive") == true
    local ecl = S.mutLive and S.mutLive.isEclipse and S.mutLive.isEclipse() == true
    if ecl and not isLive then
        local top = S.mutLive.isTopHeavy and S.mutLive.isTopHeavy(fruitId, pid) == true
        if not top then
            unregisterFruitShellFromFvc(fruitId)
            softShellSetBeamQuery(shell, false)
            return
        end
    end
    local FVC = getFVC()
    if type(FVC) ~= "table" then return end
    local fid = tostring(fruitId)
    pcall(function()
        for _, key in ipairs({
            "Fruits", "fruits", "FruitCache", "fruitCache",
            "SpawnedFruits", "spawnedFruits", "_fruits", "FruitModels",
        }) do
            local t = rawget(FVC, key)
            if type(t) == "table" then
                t[fid] = shell
                t[fruitId] = shell
            end
        end
        for k, v in pairs(FVC) do
            if type(v) == "table" and type(k) == "string" then
                local low = string.lower(k)
                if low:find("fruit", 1, true)
                    and (low:find("cache", 1, true) or low:find("spawn", 1, true) or low == "fruits") then
                    local sample = nil
                    for _, x in pairs(v) do
                        sample = x
                        break
                    end
                    if sample == nil or typeof(sample) == "Instance" then
                        v[fid] = shell
                        v[fruitId] = shell
                    end
                end
            end
        end
    end)
    -- Non-eclipse / top-N: pastikan prompt query hidup
    if shell:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
        softShellSetBeamQuery(shell, true)
        local uid = tonumber(shell:GetAttribute("UserId")) or LP.UserId
        local pid = shell:GetAttribute("PlantId")
        if pid ~= nil and fruitId ~= nil then
            bindSoftShellInFvcU3(shell, uid, pid, fruitId)
        end
    end
end

local function findMatchingShells(plantId, fruitId)
    local out = {}
    local plot = myPlot()
    if not plot then return out end
    local wantFid = tostring(fruitId or "")
    local wantPid = plantId ~= nil and tostring(plantId) or nil
    for _, plant in ipairs(plot:GetChildren()) do
        if not plant:IsA("Model") then continue end
        local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
        if not folder then continue end
        for _, ch in ipairs(folder:GetChildren()) do
            if ch:IsA("Model") and ch:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                if tostring(ch:GetAttribute("FruitId") or "") ~= wantFid then continue end
                if wantPid then
                    local pid = ch:GetAttribute("PlantId")
                    if pid ~= nil and tostring(pid) ~= wantPid then continue end
                end
                out[#out + 1] = ch
            end
        end
    end
    return out
end

local function mirrorMutationFromSource(source)
    if S.mutMirroring or not source or not source.Parent then return end
    local mut = source:GetAttribute("Mutation")
    S.mutMirroring = true
    pcall(function()
        -- Shell / fruit: string Mutation → boolean Glow/Gold/… (AC filter)
        stampMutationAttrs(source, nil)
        if type(mut) ~= "string" or mut == "" then
            return
        end
        local fruitId = source:GetAttribute("FruitId")
        local plantId = source:GetAttribute("PlantId")
        if fruitId == nil and source:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
            return
        end
        if source:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
            registerFruitShellInFvc(source, fruitId)
            return
        end
        for _, shell in ipairs(findMatchingShells(plantId, fruitId)) do
            if shell ~= source and shell.Parent then
                if shell:GetAttribute("Mutation") ~= mut then
                    shell:SetAttribute("Mutation", mut)
                    stampMutationAttrs(shell, { Mutation = mut })
                end
                registerFruitShellInFvc(shell, fruitId)
            end
        end
    end)
    S.mutMirroring = false
end

local function bindFruitMutationListener(fruit, opts)
    if not fruit or B.mutListenBound[fruit] then return end
    if fruit:GetAttribute("FruitId") == nil and fruit:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
        return
    end
    B.mutListenBound[fruit] = true
    pcall(function()
        fruit:GetAttributeChangedSignal("Mutation"):Connect(function()
            if fruit.Parent then mirrorMutationFromSource(fruit) end
        end)
    end)
    -- Bulk bind (buka plot besar) jangan stamp semua sekaligus → hitch.
    if opts and opts.deferStamp == true then
        return
    end
    if fruit:GetAttribute("Mutation") ~= nil then
        mirrorMutationFromSource(fruit)
    end
end

local function hookMutationController()
    if S.mutationControllerHooked then return end
    pcall(function()
        local ps = LP:FindFirstChild("PlayerScripts")
        if not ps then return end
        local controllers = ps:FindFirstChild("Controllers")
            or ps:FindFirstChild("ClientControllers")
            or ps:FindFirstChild("controllers")
        local mod = controllers and controllers:FindFirstChild("MutationController")
        if not mod then
            for _, d in ipairs(ps:GetDescendants()) do
                if d:IsA("ModuleScript") and d.Name == "MutationController" then
                    mod = d
                    break
                end
            end
        end
        if not mod then return end
        local mc = require(mod)
        if type(mc) ~= "table" or type(mc.ApplyMutation) ~= "function" then return end
        if mc._GAG2MutMirror then
            S.mutationControllerHooked = true
            return
        end
        -- Soft/Eclipse: ATTR SAJA. Jangan orig ApplyMutation (VFX × ribuan buah = freeze).
        local orig = mc.ApplyMutation
        mc.ApplyMutation = function(self, model)
            local soft = (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual))
                and not useGameManagedFruits()
            if soft and typeof(model) == "Instance" then
                if model:GetAttribute("FruitId") == nil and model:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
                    return nil
                end
                local mut = model:GetAttribute("Mutation")
                if model:GetAttribute("Eclipsed") == true then
                    pcall(function()
                        model:SetAttribute("Mutation", "Eclipsed")
                        model:SetAttribute("Eclipsed", true)
                    end)
                elseif type(mut) == "string" and string.find(mut, "+", 1, true) then
                    local first = mut:match("^([^+,]+)")
                    if first then
                        pcall(function()
                            model:SetAttribute("Mutation", first:match("^%s*(.-)%s*$"))
                        end)
                    end
                end
                return nil
            end
            local ok, res = pcall(orig, self, model)
            if ok then return res end
            return nil
        end
        mc._GAG2MutMirror = true
        S.mutationControllerHooked = true
        dlog("MutationController.ApplyMutation hooked (attr-only, no VFX)")
    end)
end

local function bindPlotMutationMirror(plot)
    if not plot then return end
    table.insert(B.plotConns, plot.DescendantAdded:Connect(function(inst)
        if not (inst:IsA("Model") or inst:IsA("Tool")) then return end
        task.defer(function()
            if not S.alive or not inst.Parent then return end
            if inst:GetAttribute("FruitId") == nil and inst:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
                return
            end
            bindFruitMutationListener(inst)
        end)
    end))
    -- Jangan GetDescendants() plot (ribu-an part). Cuma Fruits folder.
    task.spawn(function()
        local n = 0
        for _, plant in ipairs(plot:GetChildren()) do
            if not S.alive then return end
            if not plant:IsA("Model") then continue end
            local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if not folder then continue end
            for _, ch in ipairs(folder:GetChildren()) do
                if not S.alive then return end
                if ch:IsA("Model")
                    and (ch:GetAttribute("FruitId") ~= nil or ch:GetAttribute(A.FRUIT_SHELL_ATTR) == true) then
                    bindFruitMutationListener(ch, { deferStamp = true })
                    if ch:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true
                        and type(ch:GetAttribute("Mutation")) == "string"
                        and ch:GetAttribute("Mutation") ~= "" then
                        mirrorMutationFromSource(ch)
                    end
                    n += 1
                    if n >= 25 then
                        n = 0
                        task.wait()
                    end
                end
            end
        end
    end)
end

-- Soft shell + Eclipse LITE (3000 buah): JANGAN orig mesh/VFX.
-- Data Eclipsed = RequestGardens → sync → SetAttribute saja.
S.mutLive = {
