    stampBusy = false,
    stampLast = 0,
    ready = false,
    stampMinGap = 3.0, -- force=true dulu nembus gap → stampMut spam
    bootDelay = 4.0,
    eclipseConn = nil,
    timeFrozenConn = nil,
    eclipseAt = 0,
    eclipseGrow = false,
    refreshQueued = false,
    refreshLast = 0,
    posReportLast = 0,
    posReportLastN = 0,
    posReportBusy = false,
    posSent = {},
    posLoopRunning = false,
    posWaveList = nil,
    posWaveClean = 0,
    posFillAt = 0,
    -- Top-N terberat: FVC asli lalu hide mesh saat Eclipse (soft shell UUID tidak kena beam).
    eclipseTopN = 0, -- 0 = tanpa FVC; mutasi = report posisi ke server
    eclipseRefillBelow = 5, -- sisa live ≤ ini → rank ulang + refill
    topHeavyIds = nil,
    topHeavyList = nil,
    beamHooked = false,
    beamConn = nil,
    eclWaveN = 0,
    eclWaveAt = 0,
    eclCount = 0,
    eclCycleNew = 0,
    eclCycleBase = 0,
    eclCycleStart = 0,
    eclScanOk = false,
    eclScanBusy = false,
    eclScanQueued = false,
    -- FruitId → true saat SpawnFruit asli (sebelum KeepVisual sempat di-set)
    pendingKeep = {},
    -- true selama 1x origSpawn (mesh bisa muncul sebelum FruitId/KeepVisual)
    spawnGuard = false,
    refillQueued = false,
    refillLast = 0,
    presenceBusy = false,
    presenceLastN = 0,
    liveStamped = 0,
    fruitMutHooked = false,
}
S.mutLive.isEclipse = function()
    return S.mutLive.eclipseGrow == true
        or Workspace:GetAttribute("TimeFrozen") == true
end
S.mutLive.dataIsEclipsed = function(data)
    if type(data) ~= "table" then return false end
    if data.Eclipsed == true then return true end
    local raw = data.Mutation or data.mutation or data.MutationName
    if type(raw) == "string" then
        local s = string.lower(raw)
        return string.find(s, "eclipse", 1, true) ~= nil
    elseif type(raw) == "table" then
        local n = raw.Name or raw.Mutation
        if type(n) == "string" and string.find(string.lower(n), "eclipse", 1, true) then
            return true
        end
    end
    return false
end
S.mutLive.countEclipsedGarden = function()
    local ecl, ripe, polos = 0, 0, 0
    S.mutLive.eclScanOk = false
    local sync = getGardenSync()
    if not (sync and type(sync.GetGarden) == "function") then
        return ecl, ripe, polos
    end
    local garden
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then
        return ecl, ripe, polos
    end
    for plantId, plantData in pairs(garden) do
        if type(plantData) ~= "table" then continue end
        local entries = fruitEntriesFromPlantData(plantData, nil, plantId)
        for i = 1, #entries do
            local e = entries[i]
            if type(e.data) ~= "table" then continue end
            local age = _pickDataNum(e.data, { "Age", "age" })
            local maxAge = _pickDataNum(e.data, { "MaxAge", "maxAge" })
            if maxAge and maxAge > 0 then
                if not age or (age + 1e-4) < maxAge then continue end
            end
            ripe += 1
            if S.mutLive.dataIsEclipsed(e.data) then
                ecl += 1
            else
                polos += 1
            end
        end
    end
    S.mutLive.eclScanOk = true
    return ecl, ripe, polos
end
S.mutLive.applyEclCount = function(ecl, intoCycle)
    if S.mutLive.eclScanOk ~= true then
        return 0
    end
    if G.__GAG2_ECL_SEEN ~= nil then
        G.__GAG2_ECL_SEEN = nil
    end
    -- Stok kebun saja. Gain session/cycle = own beam, bukan delta GetGarden.
    S.mutLive.eclCount = tonumber(ecl) or 0
    G.__GAG2_ECL_BOOT = true
    return 0
end
S.mutLive.pollEclGain = function(intoCycle, tries)
    tries = math.max(1, math.floor(tonumber(tries) or 1))
    if S.mutLive.eclScanBusy == true then
        S.mutLive.eclScanQueued = true
        return
    end
    S.mutLive.eclScanBusy = true
    task.spawn(function()
        for i = 1, tries do
            if not S.alive then break end
            local ecl = S.mutLive.countEclipsedGarden()
            S.mutLive.applyEclCount(ecl, false)
            if S.mutLive.eclScanOk == true then
                pcall(S.mutLive.syncEclStats, "wave")
                break
            end
            if i < tries then
                task.wait(0.4)
            end
        end
        S.mutLive.eclScanBusy = false
        if S.mutLive.eclScanQueued == true then
            S.mutLive.eclScanQueued = false
            S.mutLive.pollEclGain(false, 3)
        end
    end)
end
S.mutLive.resetEclWaveCycle = function()
    S.mutLive.eclWaveN = 0
    S.mutLive.eclWaveAt = os.clock()
    S.mutLive.eclCycleNew = 0
    S.mutLive.eclCycleStart = os.clock()
    S.mutLive.eclScanQueued = false
    local ecl = S.mutLive.countEclipsedGarden()
    S.mutLive.applyEclCount(ecl, false)
    pcall(S.mutLive.syncEclStats, "start")
end
S.mutLive.ensureEclStats = function()
    local st = G.__GAG2_ECL_STATS
    if type(st) ~= "table" then
        st = {}
        G.__GAG2_ECL_STATS = st
    end
    if tonumber(st.sessionAt) == nil then
        st.sessionAt = os.clock()
    end
    if tonumber(st.sessionUnix) == nil then
        st.sessionUnix = os.time()
    end
    st.sessionNew = tonumber(st.sessionNew) or 0
    st.sessionWaves = tonumber(st.sessionWaves) or 0
    st.sessionCycles = tonumber(st.sessionCycles) or 0
    st.lastCycleNew = tonumber(st.lastCycleNew) or 0
    st.lastCycleWaves = tonumber(st.lastCycleWaves) or 0
    st.cycleNew = tonumber(st.cycleNew) or 0
    st.cycleWaves = tonumber(st.cycleWaves) or 0
    st.gardenEcl = tonumber(st.gardenEcl) or 0
    return st
end
S.mutLive.syncEclStats = function(kind)
    local st = S.mutLive.ensureEclStats()
    st.cycleNew = tonumber(S.mutLive.eclCycleNew) or 0
    st.cycleWaves = tonumber(S.mutLive.eclWaveN) or 0
    st.gardenEcl = tonumber(S.mutLive.eclCount) or st.gardenEcl
    st.cycleLive = S.mutLive.isEclipse() == true
    if kind == "start" then
        st.cycleLive = true
        st.cycleNew = 0
        st.cycleWaves = 0
    elseif kind == "end" then
        st.lastCycleNew = tonumber(S.mutLive.eclCycleNew) or 0
        st.lastCycleWaves = tonumber(S.mutLive.eclWaveN) or 0
        if st.cycleLive == true or st.lastCycleWaves > 0 or st.lastCycleNew > 0 then
            st.sessionCycles += 1
        end
        st.cycleLive = false
    end
    st.updatedAt = os.clock()
    G.__GAG2_ECL_STATS = st
    return st
end
S.mutLive.finishEclWaveCycle = function()
    local ecl = S.mutLive.countEclipsedGarden()
    S.mutLive.applyEclCount(ecl, false)
    pcall(S.mutLive.syncEclStats, "end")
end
S.mutLive.beamOnOwnPlot = function(pos)
    if typeof(pos) ~= "Vector3" then
        return false
    end
    local anchor = plotAnchorPos(myPlot())
    if not anchor then
        return false
    end
    return (pos - anchor).Magnitude <= 140
end
S.mutLive.onEclipseBeamWave = function(pos, dur)
    if S.mutLive.beamOnOwnPlot(pos) ~= true then
        return
    end
    S.mutLive.eclWaveAt = os.clock()
    S.mutLive.eclWaveN = (tonumber(S.mutLive.eclWaveN) or 0) + 1
    S.mutLive.eclCycleNew = (tonumber(S.mutLive.eclCycleNew) or 0) + 1
    local st = S.mutLive.ensureEclStats()
    st.sessionNew = (tonumber(st.sessionNew) or 0) + 1
    st.sessionWaves = (tonumber(st.sessionWaves) or 0) + 1
    pcall(S.mutLive.syncEclStats, "wave")
    local waitSec = (tonumber(dur) or 0) + 0.85
    task.delay(waitSec, function()
        if not S.alive then return end
        S.mutLive.pollEclGain(false, 4)
    end)
end
-- Key unik: FruitId saja BENTROK antar plant
S.mutLive.fruitKey = function(plantId, fruitId)
    if fruitId == nil then return nil end
    return tostring(plantId or "") .. "|" .. tostring(fruitId)
end
-- Posisi dunia = rumus FVC. Jangan hash di pivot (itu bukan buah).
-- 1) buah live: pusat mesh (Heartbeat FVC: BasePart Transparency ~= 1, skip PrimaryPart)
-- 2) else locator: FruitSpawnLocations:GetChildren()[SpawnLocationIndex] (SpawnFruitFromData)
S.mutLive.fruitWorldPos = function(plant, data, plantId, fruitId)
    if typeof(plant) ~= "Instance" then
        return nil
    end
    if fruitId ~= nil then
        local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
        if ff then
            local want = tostring(fruitId)
            for _, ch in ipairs(ff:GetChildren()) do
                if ch:IsA("Model") and tostring(ch:GetAttribute("FruitId") or "") == want then
                    local acc = 0
                    local sum = Vector3.new(0, 0, 0)
                    local pp = ch.PrimaryPart
                    for _, d in ipairs(ch:GetDescendants()) do
                        if d:IsA("BasePart") and d ~= pp and d.Transparency < 0.999 then
                            sum = sum + d.Position
                            acc += 1
                        end
                    end
                    if acc > 0 then
                        return sum / acc
                    end
                    local ok, piv = pcall(function()
                        return ch:GetPivot().Position
                    end)
                    if ok and typeof(piv) == "Vector3" then
                        return piv
                    end
                    break
                end
            end
        end
    end
    local locFolder = plant:FindFirstChild("FruitSpawnLocations")
    local idx = tonumber(data and data.SpawnLocationIndex)
    if not (locFolder and idx and idx >= 1) then
        return nil
    end
    local loc = locFolder:GetChildren()[idx]
    if loc and loc:IsA("BasePart") then
        return loc.Position
    end
    return nil
end
-- 1 Fire per gelombang. Gelombang berikutnya (5s) boleh Fire lagi kalau masih polos + top-N.
S.mutLive.fireFruitPos = function(ev, plantId, fruitId, pos, _key)
    if not (ev and type(ev.Fire) == "function") then return 0 end
    if typeof(pos) ~= "Vector3" then return 0 end
    local ok = pcall(function()
        ev:Fire(tostring(plantId), tostring(fruitId), pos)
    end)
    if not ok then return 0 end
    return 1
end
-- Buah yang boleh SpawnFruit/FVC asli saat Eclipse (harus ada di ranking top-N)
S.mutLive.isTopHeavy = function(fruitId, plantId)
    local set = S.mutLive.topHeavyIds
    if type(set) ~= "table" or next(set) == nil then return false end
    if fruitId == nil then return false end
    local key = S.mutLive.fruitKey(plantId, fruitId)
    return key ~= nil and set[key] == true
end
S.mutLive.mirrorEclipsedAttr = function(fruit)
    if not fruit or not fruit.Parent then return false end
    local ok = pcall(function()
        fruit:SetAttribute("Eclipsed", true)
        fruit:SetAttribute("Mutation", "Eclipsed")
    end)
    -- Live top-N baru kena mutasi → cek refill (kalau ≥5 mutasi / clean sisa ≤5)
    if ok and fruit:GetAttribute("_GAG2EclipseLive") == true and S.mutLive.isEclipse() then
        S.mutLive.queueRefill(1.2)
    end
    return ok
end
-- kg tampilan = Weight, atau BaseWeight×SizeMulti×OvertimeGrowth (JANGAN BaseWeight mentah)
S.mutLive.fruitKg = function(data, shell)
    local function fromInst(inst)
        if typeof(inst) ~= "Instance" then return nil end
        local bw = tonumber(inst:GetAttribute("BaseWeight"))
        local sm = tonumber(inst:GetAttribute("SizeMulti"))
        local og = tonumber(inst:GetAttribute("OvertimeGrowth")) or 1
        if bw and bw > 0 and sm and sm > 0 then
            return bw * sm * og
        end
        local w = tonumber(inst:GetAttribute("Weight"))
            or tonumber(inst:GetAttribute("DisplayWeight"))
            or tonumber(inst:GetAttribute("HarvestWeight"))
        -- Jangan pakai Weight == BaseWeight mentah (~9kg)
        if w and bw and bw > 0 and math.abs(w - bw) <= 1e-3 then
            w = nil
        end
        if w and w > 0 then return w end
        return nil
    end
    local function fromData(t)
        if type(t) ~= "table" then return nil end
        local w = tonumber(t.Weight or t.weight or t.Kg or t.kg
            or t.DisplayWeight or t.HarvestWeight)
        if w and w > 0 then return w end
        -- FVC: SizeMulti attr ← data.SizeMultiplier; BaseWeight dari GrowData
        local sm = tonumber(t.SizeMultiplier or t.SizeMulti)
        local og = tonumber(t.OvertimeGrowth) or 1
        local bw = tonumber(t.BaseWeight or t.baseWeight)
        if (not bw or bw <= 0) and t.PlantName then
            bw = _fruitModuleBaseWeight(t.PlantName)
        end
        if bw and bw > 0 and sm and sm > 0 then
            return bw * sm * og
        end
        return nil
    end
    local kg = fromInst(shell)
    if not kg then kg = fromData(data) end
    if (not kg or kg <= 0) and typeof(shell) == "Instance" then
        local FSV = rawget(G, "FruitSellValue") or rawget(_G, "FruitSellValue")
        if type(FSV) == "table" and type(FSV.resolveWeight) == "function" then
            local ok, val = pcall(FSV.resolveWeight, shell)
            if ok and type(val) == "number" and val > 0 then
                kg = val
            end
        end
    end
    return tonumber(kg) or 0
end
-- Live top-N: pilih buah TANPA mutasi (biar beam Eclipse nempel ke yang masih polos)
S.mutLive.fruitHasMutation = function(data, shell)
    if typeof(shell) == "Instance" then
        if shell:GetAttribute("Eclipsed") == true then return true end
        local mut = shell:GetAttribute("Mutation")
        if type(mut) == "string" then
            local s = string.lower((mut:match("^%s*(.-)%s*$")) or "")
            if s ~= "" and s ~= "none" and s ~= "normal" and s ~= "nomutation" then
                return true
            end
        end
        for _, k in ipairs({
            "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
            "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil",
        }) do
            if shell:GetAttribute(k) == true then return true end
        end
    end
    if type(data) == "table" then
        local raw = data.Mutation or data.mutation or data.MutationName or data.Mut or data.FruitMutation
        if type(raw) == "string" then
            local s = string.lower((raw:match("^%s*(.-)%s*$")) or "")
            if s ~= "" and s ~= "none" and s ~= "normal" and s ~= "nomutation" then
                return true
            end
        elseif type(raw) == "table" then
            local n = raw.Name or raw.Mutation
            if type(n) == "string" and n ~= "" then return true end
        end
        for _, k in ipairs({
            "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
            "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil",
        }) do
            if data[k] == true then return true end
        end
    end
    return false
end
-- Pilih N buah terberat TANPA mutasi untuk fokus Eclipse live
-- Key = plantId|fruitId (FruitId bentrok antar plant)
S.mutLive.refreshTopHeavy = function()
    local topN = math.max(0, math.floor(tonumber(S.mutLive.eclipseTopN) or tonumber(CONFIG.eclipseTopN) or 0))
    if topN <= 0 then
        S.mutLive.topHeavyIds = {}
        S.mutLive.topHeavyList = {}
        return 0
    end
    local sync = getGardenSync()
    local ranked = {}
    local byKey = {}
    if sync and type(sync.GetGarden) == "function" then
        local garden = nil
        pcall(function()
            garden = sync:GetGarden(LP.UserId)
        end)
        if type(garden) == "table" then
            for plantId, plantData in pairs(garden) do
                if type(plantData) ~= "table" then continue end
                local entries = fruitEntriesFromPlantData(plantData, nil, plantId)
                for i = 1, #entries do
                    local e = entries[i]
                    if e.id == nil or tostring(e.id) == "" then continue end
                    if S.mutLive.fruitHasMutation(e.data, nil) then continue end
                    local key = S.mutLive.fruitKey(plantId, e.id)
                    if not key or byKey[key] then continue end
                    local row = {
                        id = tostring(e.id),
                        plantId = plantId,
                        key = key,
                        w = S.mutLive.fruitKg(e.data, nil),
                        data = e.data,
                    }
                    ranked[#ranked + 1] = row
                    byKey[key] = row
                end
            end
        end
    end
    -- Lengkapi / koreksi kg dari shell (BaseWeight×SizeMulti)
    local plot = myPlot()
    if plot then
        local steps = 0
        for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
            for _, plant in ipairs(folder:GetChildren()) do
                if not plant:IsA("Model") then continue end
                local pid = plant:GetAttribute("PlantId")
                local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                if not ff then continue end
                for _, ch in ipairs(ff:GetChildren()) do
                    if not ch:IsA("Model") then continue end
                    local fid = ch:GetAttribute("FruitId")
                    if fid == nil then continue end
                    local key = S.mutLive.fruitKey(pid, fid)
                    if not key then continue end
                    local row = byKey[key]
                    -- Sudah punya mutasi di shell → jangan masuk / buang dari kandidat
                    if S.mutLive.fruitHasMutation(row and row.data or nil, ch) then
                        if row then
                            byKey[key] = nil
                            row._drop = true
                        end
                        continue
                    end
                    local sw = S.mutLive.fruitKg(row and row.data or nil, ch)
                    if row then
                        if sw > (row.w or 0) then row.w = sw end
                        row.shell = ch
                    else
                        row = {
                            id = tostring(fid),
                            plantId = pid,
                            key = key,
                            w = sw,
                            shell = ch,
                        }
                        ranked[#ranked + 1] = row
                        byKey[key] = row
                    end
                    steps += 1
                    if steps % 80 == 0 then task.wait() end
                end
            end
        end
    end
    -- Buang yang di-mark drop (sudah mutasi saat scan shell)
    if next(byKey) ~= nil or #ranked > 0 then
        local kept = {}
        for i = 1, #ranked do
            local r = ranked[i]
            if r and not r._drop and byKey[r.key] == r then
                kept[#kept + 1] = r
            end
        end
        ranked = kept
    end
    table.sort(ranked, function(a, b)
        if a.w == b.w then return tostring(a.key) < tostring(b.key) end
        return a.w > b.w
    end)
    local set, list = {}, {}
    local n = math.min(topN, #ranked)
    for i = 1, n do
        local r = ranked[i]
        set[r.key] = true
        list[i] = r
    end
    if n == 0 then
        S.mutLive.topHeavyIds = nil
        S.mutLive.topHeavyList = {}
        dlog("eclipse topHeavy EMPTY (sync/shell 0)")
        return 0
    end
    S.mutLive.topHeavyIds = set
    S.mutLive.topHeavyList = list
    local light = ranked[n] and ranked[n].w or 0
    local heavy = ranked[1] and ranked[1].w or 0
    dlog("eclipse topHeavy n=%d / %d kg=%.1f..%.1f (no-mut, key=plant|fruit)", n, #ranked, light, heavy)
    return n
end

-- Ringan: soft shell luar top-N → unregister FVC + CanQuery off (1× scan, FindFirstChild saja)
S.mutLive.shieldSoftShellsOutsideTopN = function()
    if not S.mutLive.isEclipse() then return 0 end
    local set = S.mutLive.topHeavyIds
    if type(set) ~= "table" then set = {} end
    local plot = myPlot()
    if not plot then return 0 end
    local n, steps = 0, 0
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if not plant:IsA("Model") then continue end
            local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if not ff then continue end
            local pid = plant:GetAttribute("PlantId")
            for _, ch in ipairs(ff:GetChildren()) do
                if not ch:IsA("Model") then continue end
                if ch:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then continue end
                if ch:GetAttribute("_GAG2EclipseLive") == true then continue end
                local fid = ch:GetAttribute("FruitId")
                if fid == nil then continue end
                if set[S.mutLive.fruitKey(pid, fid) or ""] == true then continue end
                unregisterFruitShellFromFvc(fid)
                softShellSetBeamQuery(ch, false)
                n += 1
                steps += 1
                if steps % 100 == 0 then task.wait() end
            end
        end
    end
    if n > 0 then dlog("eclipse shield softShell off=%d", n) end
    return n
end

-- LTM cepat (1 frame) biar mesh spawn tidak flash/spike render
local function hideEclipseFruitLight(fruit)
    if not fruit or not fruit.Parent then return end
    local kids = fruit:GetDescendants()
    local lim = math.min(#kids, 80)
    for i = 1, lim do
        local d = kids[i]
        if d:IsA("BasePart") then
            pcall(function()
                d.LocalTransparencyModifier = 1
                d.CastShadow = false
            end)
        elseif d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail")
            or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
            pcall(function()
                d.Enabled = false
            end)
        end
    end
end

-- FVC asli + mark live + hide mesh (bukan soft shell UUID)
-- opts.deferStrip=true → strip mesh di frame belakangan (anti spike)
S.mutLive.markEclipseLiveHidden = function(fruit, fruitId, opts)
    if not (fruit and fruit.Parent) then return false end
    opts = type(opts) == "table" and opts or {}
    pcall(function()
        fruit:SetAttribute(A.FRUIT_SHELL_ATTR, nil)
        fruit:SetAttribute("_GAG2EclipseLive", true)
        fruit:SetAttribute("_GAG2KeepVisual", nil)
    end)
    registerFruitShellInFvc(fruit, fruitId)
    hideEclipseFruitLight(fruit)
    -- FVC reportFruitWorldPosition: BasePart Transparency ~= 1 (skip PrimaryPart).
    -- HarvestPart/CollectProxy = Transparency 1 → QueryDescendants kosong.
    local function keepBeamHit()
        if not (fruit and fruit.Parent) then return end
        local hit = fruit:FindFirstChild("_GAG2BeamHit")
        if not (hit and hit:IsA("BasePart")) then
            hit = Instance.new("Part")
            hit.Name = "_GAG2BeamHit"
            hit.Size = Vector3.new(1.2, 1.2, 1.2)
            hit.Anchored = true
            hit.CanCollide = false
            hit.CanTouch = false
            hit.CanQuery = true
            hit.CastShadow = false
            hit.Massless = true
            hit.Parent = fruit
        end
        pcall(function()
            hit.Transparency = 0.99
            hit.LocalTransparencyModifier = 1
            hit.CanQuery = true
            hit.CFrame = fruit:GetPivot()
        end)
    end
    keepBeamHit()
    local deferStrip = opts.deferStrip ~= false
    if type(stripHeavyVisual) == "function" then
        if deferStrip then
            local delaySec = math.max(0.02, tonumber(CONFIG.eclipseStripDefer) or 0.06)
            task.defer(function()
                task.wait(delaySec)
                if fruit.Parent and fruit:GetAttribute("_GAG2EclipseLive") == true then
                    pcall(stripHeavyVisual, fruit)
                    keepBeamHit()
                end
            end)
        else
            pcall(stripHeavyVisual, fruit)
            keepBeamHit()
        end
    end
    return true
end
-- Hitung status top-N live: total live / masih polos / sudah mutasi / hilang
S.mutLive.countEclipseLiveStats = function()
    local list = S.mutLive.topHeavyList
    local out = { live = 0, clean = 0, mutated = 0, gone = 0, listed = 0 }
    if type(list) ~= "table" then return out end
    out.listed = #list
    for i = 1, #list do
        local r = list[i]
        local shell = r.shell
        if not (shell and shell.Parent) then
            shell = lookupOwnFruitShell(r.id, r.plantId)
            if shell then r.shell = shell end
        end
        if not (shell and shell.Parent) then
            out.gone += 1
            continue
        end
        if shell:GetAttribute("_GAG2EclipseLive") == true then
            out.live += 1
            if S.mutLive.fruitHasMutation(r.data, shell) then
                out.mutated += 1
            else
                out.clean += 1
            end
        end
    end
    return out
end
S.mutLive.countEclipseLive = function()
    return S.mutLive.countEclipseLiveStats().live
end
-- Soft shell tidak cukup untuk beam: spawn FVC asli lalu hide visual untuk top-N.
-- Top-N buah, TAPI 1 spawn / gap (bukan N× FVC 1 frame).
S.mutLive.ensurePresence = function()
    local liveN = math.max(0, math.floor(tonumber(S.mutLive.eclipseTopN) or tonumber(CONFIG.eclipseTopN) or 0))
    if liveN <= 0 then
        S.mutLive.presenceLastN = 0
        return 0
    end
    if S.mutLive.presenceBusy == true then
        return tonumber(S.mutLive.presenceLastN) or 0
    end
    S.mutLive.presenceBusy = true
    local okAll, result = pcall(function()
        if type(S.mutLive.topHeavyList) ~= "table" or #S.mutLive.topHeavyList == 0 then
            S.mutLive.refreshTopHeavy()
        end
        local list = S.mutLive.topHeavyList or {}
        if #list == 0 then return 0 end
        local FVC = getFVC()
        local origSpawn = B.fvcBackup and B.fvcBackup.SpawnFruitFromData
        if type(origSpawn) ~= "function" then return 0 end
        local n = 0
        local pending = S.mutLive.pendingKeep
        if type(pending) ~= "table" then
            pending = {}
            S.mutLive.pendingKeep = pending
        end
        local gap = math.max(0.03, tonumber(CONFIG.eclipseSpawnGap) or 0.10)
        local t0 = os.clock()
        for i = 1, #list do
            if not S.alive or not S.mutLive.isEclipse() then break end
            local r = list[i]
            local fidKey = r.key or S.mutLive.fruitKey(r.plantId, r.id) or tostring(r.id)
            local old = lookupOwnFruitShell(r.id, r.plantId)
            -- Sudah live → re-hide ringan saja, jangan respawn / strip berat sync
            if old and old.Parent and old:GetAttribute("_GAG2EclipseLive") == true then
                hideEclipseFruitLight(old)
                registerFruitShellInFvc(old, r.id)
                r.shell = old
                n += 1
                continue
            end
            pending[fidKey] = true
            if old and old.Parent and old:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                pcall(function() old:Destroy() end)
            end
            local fruit = nil
            -- FVC SpawnFruitFromData butuh FruitSpawnLocations[SpawnLocationIndex]
            pcall(function()
                local pvc = getPVC()
                local plant = nil
                if pvc and type(pvc.GetSpawnedPlant) == "function" then
                    plant = pvc:GetSpawnedPlant(LP.UserId, r.plantId)
                end
                if typeof(plant) == "Instance" then
                    local idx = tonumber(r.data and r.data.SpawnLocationIndex) or 1
                    ensureFruitSpawnLocations(plant, idx)
                end
            end)
            S.mutLive.spawnGuard = true
            local ok, res = pcall(origSpawn, FVC, LP.UserId, r.plantId, r.id, r.data or {})
            S.mutLive.spawnGuard = false
            if ok and typeof(res) == "Instance" then
                fruit = res
            else
                fruit = lookupOwnFruitShell(r.id, r.plantId)
            end
            if fruit and fruit.Parent then
                -- attrs + LTM sekarang; Destroy mesh di frame belakangan
                S.mutLive.markEclipseLiveHidden(fruit, r.id, { deferStrip = true })
                r.shell = fruit
                n += 1
            end
            pending[fidKey] = nil
            -- kunci anti-spike: 1 FVC per gap (10 buah ≈ 1s tersebar, bukan 1 frame)
            if i < #list then
                task.wait(gap)
            end
        end
        dlog("eclipse ensurePresence REAL+hide=%d / %d gap=%.2fs ms=%.0f",
            n, #list, gap, (os.clock() - t0) * 1000)
        return n
    end)
    S.mutLive.presenceBusy = false
    local n = (okAll and tonumber(result)) or 0
    S.mutLive.presenceLastN = n
    return n
end
-- Refill top-10 (tanpa mutasi):
--   • ≥5 sudah kena mutasi → rank ulang + isi polos baru
--   • ≥5 hilang / di-collect (live≤5 atau gone) → sama
-- Throttle ketat — JANGAN panggil dari tiap soft-shell create.
S.mutLive.queueRefill = function(delaySec)
    if not S.mutLive.isEclipse() then return end
    if useGameManagedFruits() then return end
    if not (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)) then return end
    if S.mutLive.refillQueued then return end
    if S.mutLive.presenceBusy == true then return end
    S.mutLive.refillQueued = true
    delaySec = math.max(0.5, tonumber(delaySec) or 1.5)
    task.defer(function()
        task.wait(delaySec)
        S.mutLive.refillQueued = false
        if not S.alive or not S.mutLive.isEclipse() then return end
        if S.mutLive.presenceBusy == true then return end
        local now = os.clock()
        if (now - (S.mutLive.refillLast or 0)) < 3.0 then return end
        local need = math.max(0, math.floor(tonumber(S.mutLive.eclipseTopN) or tonumber(CONFIG.eclipseTopN) or 0))
        if need <= 0 then
            -- Pos = gelombang 5s. Jangan scan GetGarden 2× di refill.
            return
        end
        local low = math.max(1, math.floor(
            tonumber(S.mutLive.eclipseRefillBelow) or tonumber(CONFIG.eclipseRefillBelow) or 5
        ))
        local st = S.mutLive.countEclipseLiveStats()
        local needRefill = false
        local why = ""
        -- 5+ kena mutasi
        if st.mutated >= low then
            needRefill = true
            why = string.format("mutated=%d≥%d", st.mutated, low)
        -- 5+ hilang/collect (live sisa ≤5)
        elseif st.live <= low then
            needRefill = true
            why = string.format("live=%d≤%d gone=%d", st.live, low, st.gone)
        -- masih kurang slot polos (<10 clean)
        elseif st.clean < need then
            needRefill = true
            why = string.format("clean=%d<%d", st.clean, need)
        end
        if not needRefill then
            dlog("eclipse refill skip live=%d clean=%d mut=%d need=%d",
                st.live, st.clean, st.mutated, need)
            return
        end
        S.mutLive.refillLast = now
        dlog("eclipse refill WHY %s → top up no-mut to %d", why, need)
        -- Rank ulang: hanya terberat tanpa mutasi
        pcall(S.mutLive.refreshTopHeavy)
        local okP, nP = pcall(S.mutLive.ensurePresence)
        local st2 = S.mutLive.countEclipseLiveStats()
        dlog("eclipse refill done clean=%d/%d mut=%d spawned~%s",
            st2.clean, need, st2.mutated, tostring(nP))
    end)
end
-- RequestGardens + stamp Eclipsed (jarang). Bukan tiap shell / tiap beam spam.
S.mutLive.queueEclipseRefresh = function(delaySec)
    if not S.mutLive.isEclipse() then return end
    if useGameManagedFruits() then return end
    if not (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)) then return end
    if S.mutLive.refreshQueued then return end
    S.mutLive.refreshQueued = true
    delaySec = math.max(0.8, tonumber(delaySec) or 1.5)
    task.defer(function()
        task.wait(delaySec)
        S.mutLive.refreshQueued = false
        if not S.alive or not S.mutLive.isEclipse() then return end
        local now = os.clock()
        -- stamp saja (posisi = gelombang 5s, jangan RequestGardens+scan dobel)
        if (now - (S.mutLive.refreshLast or 0)) < 8.0 then return end
        S.mutLive.refreshLast = now
        S.mutLive.ready = true
        if S.alive and S.mutLive.isEclipse() then
            pcall(stampShellMutationsFromSyncFast, true, { eclipsedOnly = true, ignoreGap = true })
            S.mutLive.queueRefill(2.0)
        end
    end)
end

local function queueLiveMutationStamp(delaySec)
    if not S.mutLive.ready then return end
    if not (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)) then return end
    if useGameManagedFruits() then return end
    delaySec = tonumber(delaySec) or 1.5
    if rawget(G, "__GAG2MutStampQueued") then return end
    G.__GAG2MutStampQueued = true
    task.defer(function()
        task.wait(delaySec)
        G.__GAG2MutStampQueued = nil
        if S.alive and S.mutLive.ready then
            pcall(stampShellMutationsFromSyncFast, false)
        end
    end)
end

-- Daftarkan shell ke cache FVC biar MutationController nemu (tanpa spawn mesh)
local function registerAllOwnShellsInFvc()
    if useGameManagedFruits() then return 0 end
    local plot = myPlot()
    if not plot then return 0 end
    local n = 0
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if not plant:IsA("Model") then continue end
            local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if not ff then continue end
            for _, ch in ipairs(ff:GetChildren()) do
                if ch:IsA("Model") then
                    local fid = ch:GetAttribute("FruitId")
                    if fid ~= nil then
                        registerFruitShellInFvc(ch, fid)
                        n += 1
                    end
                end
            end
        end
    end
    return n
end

-- Server EclipseBeam target = ObjectPositionService.CreateServerValue(plantId, fruitId, pos).
-- 10 terberat. Fire tiap 1s. Kalau sisa polos ≤5 → rank ulang isi 10 lagi. <10 tetap dikirim.
S.mutLive.fillPosWaveFromGarden = function(garden, cap)
    local ranked, byKey = {}, {}
    local plantSteps = 0
    for plantId, plantData in pairs(garden) do
        if type(plantData) ~= "table" then continue end
        local pname = plantData.PlantName or plantData.plantName
        local entries = fruitEntriesFromPlantData(plantData, nil, plantId)
        for i = 1, #entries do
            local e = entries[i]
            if e.id == nil or tostring(e.id) == "" then continue end
            if type(e.data) == "table" and pname and e.data.PlantName == nil then
                e.data.PlantName = pname
            end
            if S.mutLive.fruitHasMutation(e.data, nil) then continue end
            if fruitDataHarvestReady(e.data, nil) ~= true then continue end
            local age = _pickDataNum(e.data, { "Age", "age" })
            local maxAge = _pickDataNum(e.data, { "MaxAge", "maxAge" })
            if maxAge and maxAge > 0 then
                if not age or (age + 1e-4) < maxAge then continue end
            end
            local key = S.mutLive.fruitKey(plantId, e.id)
            if not key or byKey[key] then continue end
            ranked[#ranked + 1] = {
                id = tostring(e.id),
                plantId = plantId,
                key = key,
                w = S.mutLive.fruitKg(e.data, nil) or 0,
                data = e.data,
            }
            byKey[key] = true
        end
        plantSteps += 1
        if plantSteps % 40 == 0 then task.wait() end
    end
    table.sort(ranked, function(a, b)
        if a.w == b.w then return tostring(a.key) < tostring(b.key) end
        return a.w > b.w
    end)
    local take = math.min(cap, #ranked)
    local list = {}
    for i = 1, take do
        list[i] = ranked[i]
    end
    S.mutLive.posWaveList = list
    S.mutLive.posWaveClean = take
    return list, #ranked
end

S.mutLive.reportPositionsToServer = function()
    local net = getNetworking()
    local ev = net and net.ObjectPositionService and net.ObjectPositionService.CreateServerValue
    if not (ev and type(ev.Fire) == "function") then
        dlog("eclipse pos-report: CreateServerValue missing")
        return 0
    end
    if S.mutLive.posReportBusy then
        return tonumber(S.mutLive.posReportLastN) or 0
    end
    S.mutLive.posReportBusy = true
    local cap = math.floor(tonumber(CONFIG.eclipsePosTopN) or 10)
    if cap <= 0 then cap = 10 end
    if cap > A.FRUIT_CAP_MAX then cap = A.FRUIT_CAP_MAX end
    local low = math.floor(tonumber(CONFIG.eclipsePosRefillBelow) or 5)
    if low < 1 then low = 1 end
    if low > cap then low = cap end
    local sync = getGardenSync()
    if not (sync and type(sync.GetGarden) == "function") then
        S.mutLive.posReportBusy = false
        return 0
    end
    local garden = nil
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then
        S.mutLive.posReportBusy = false
        return 0
    end
    local list = S.mutLive.posWaveList
    local still = 0
    if type(list) == "table" and #list > 0 then
        for i = 1, #list do
            local r = list[i]
            local pd = garden[r.plantId] or garden[tostring(r.plantId)]
            if type(pd) ~= "table" then continue end
            local entries = fruitEntriesFromPlantData(pd, nil, r.plantId)
            for j = 1, #entries do
                local e = entries[j]
                if tostring(e.id) ~= r.id then continue end
                r.data = e.data
                if S.mutLive.fruitHasMutation(e.data, nil) then break end
                if fruitDataHarvestReady(e.data, nil) ~= true then break end
                local age = _pickDataNum(e.data, { "Age", "age" })
                local maxAge = _pickDataNum(e.data, { "MaxAge", "maxAge" })
                if maxAge and maxAge > 0 and (not age or (age + 1e-4) < maxAge) then break end
                still += 1
                break
            end
        end
    end
    S.mutLive.posWaveClean = still
    local ripeN = 0
    local needFill = type(list) ~= "table" or #list == 0 or still <= low
    if needFill then
        local lastFill = tonumber(S.mutLive.posFillAt) or 0
        local minGap = 5
        if type(list) ~= "table" or #list == 0 then
            minGap = 8
        end
        if (os.clock() - lastFill) >= minGap then
            local filled
            filled, ripeN = S.mutLive.fillPosWaveFromGarden(garden, cap)
            list = filled
            still = type(list) == "table" and #list or 0
            S.mutLive.posWaveClean = still
            S.mutLive.posFillAt = os.clock()
            dlog("eclipse pos-refill clean=%d ripePolos=%d cap=%d", still, ripeN, cap)
        end
    end
    if type(list) ~= "table" or #list == 0 then
        S.mutLive.posReportLast = os.clock()
        S.mutLive.posReportLastN = 0
        S.mutLive.posReportBusy = false
        return 0
    end
    local pvc = getPVC()
    local plantCache = {}
    local n, steps, skipped = 0, 0, 0
    for i = 1, #list do
        local r = list[i]
        if S.mutLive.fruitHasMutation(r.data, nil) then continue end
        local pid = r.plantId
        local plant = plantCache[pid]
        if plant == nil then
            plant = false
            if pvc and type(pvc.GetSpawnedPlant) == "function" then
                pcall(function()
                    plant = pvc:GetSpawnedPlant(LP.UserId, pid)
                end)
            end
            plantCache[pid] = plant
        end
        if typeof(plant) == "Instance" then
            local idx = tonumber(r.data and r.data.SpawnLocationIndex) or 1
            pcall(ensureFruitSpawnLocations, plant, idx)
        end
        local pos = S.mutLive.fruitWorldPos(plant, r.data, pid, r.id)
        if typeof(pos) ~= "Vector3" and typeof(plant) == "Instance" then
            pcall(function()
                pos = plant:GetPivot().Position
            end)
        end
        if typeof(pos) ~= "Vector3" then
            skipped += 1
            continue
        end
        local fired = S.mutLive.fireFruitPos(ev, pid, r.id, pos, r.key)
        if fired > 0 then n += 1 end
        steps += 1
        if steps % 5 == 0 then task.wait() end
    end
    S.mutLive.posReportLast = os.clock()
    S.mutLive.posReportLastN = n
    S.mutLive.posReportBusy = false
    local heavy = list[1] and list[1].w or 0
    local light = list[#list] and list[#list].w or 0
    dlog("eclipse pos-wave n=%d skip=%d hold=%d kg=%.1f..%.1f",
        n, skipped, #list, light, heavy)
    return n
end

-- Tiap 1s: Fire set 10. Scan penuh hanya saat refill (sisa ≤5).
S.mutLive.startPosWaveLoop = function(myToken)
    if S.mutLive.posLoopRunning then return end
    S.mutLive.posLoopRunning = true
    local tok = myToken or S.token
    task.spawn(function()
        while S.alive and tok == S.token and S.mutLive.isEclipse() do
            if not S.mutLive.posReportBusy then
                pcall(S.mutLive.reportPositionsToServer)
            end
            local gap = tonumber(CONFIG.eclipsePosInterval) or 1
            if gap < 1 then gap = 1 end
            local untilT = os.clock() + gap
            while os.clock() < untilT do
                if not S.alive or tok ~= S.token or not S.mutLive.isEclipse() then
                    S.mutLive.posLoopRunning = false
                    return
                end
                task.wait(0.2)
            end
        end
        S.mutLive.posLoopRunning = false
    end)
end

local function onEclipseForShellMut(myToken)
    local now = os.clock()
    if (now - (S.mutLive.eclipseAt or 0)) < 15.0 then return end
    S.mutLive.eclipseAt = now
    task.spawn(function()
        if not S.alive or myToken ~= S.token then return end
        if useGameManagedFruits() then return end
        if not (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)) then return end
        S.mutLive.ready = true
        S.mutLive.eclipseGrow = true
        S.mutLive.posSent = {}
        S.mutLive.posWaveList = nil
        S.mutLive.posWaveClean = 0
        S.mutLive.posFillAt = 0
        S.mutLive.posReportBusy = false
        pcall(S.mutLive.resetEclWaveCycle)
        -- Sync dulu (join mid-Eclipse: GetGarden sering kosong)
        local fired = requestGardensFire()
        local liveN = math.max(0, math.floor(tonumber(S.mutLive.eclipseTopN) or tonumber(CONFIG.eclipseTopN) or 0))
        local topN, present = 0, 0
        if liveN > 0 then
            for attempt = 1, 6 do
                if not S.alive or myToken ~= S.token or not S.mutLive.isEclipse() then return end
                task.wait(attempt == 1 and 0.8 or 1.0)
                local okR, nOrErr = pcall(S.mutLive.refreshTopHeavy)
                if okR then
                    topN = tonumber(nOrErr) or 0
                end
                if topN > 0 then break end
            end
        else
            task.wait(0.8)
        end
        if liveN > 0 and topN > 0 then
            pcall(S.mutLive.shieldSoftShellsOutsideTopN)
            local okP, nP = pcall(S.mutLive.ensurePresence)
            if okP then present = tonumber(nP) or 0 end
            pcall(S.mutLive.shieldSoftShellsOutsideTopN)
        end
        pcall(S.mutLive.startPosWaveLoop, myToken)
        task.wait(0.6)
        if not S.alive or myToken ~= S.token then return end
        local stamped = 0
        pcall(function()
            stamped = stampShellMutationsFromSyncFast(true, { eclipsedOnly = true, ignoreGap = true }) or 0
        end)
        dlog("eclipse beam-prep top=%d real=%d posLoop=%s rg=%s stamped=%d",
            topN, present, tostring(S.mutLive.posLoopRunning), tostring(fired), stamped)
    end)
end

-- Server kirim EclipseBeam(pos, duration) saat mutasi kena — pull sync setelah beam land
local function hookEclipseBeamSync(myToken)
    if S.mutLive.beamHooked then return end
    local function bindBeam(ev, src)
        if not ev or S.mutLive.beamHooked then return false end
        local signal = ev.OnClientEvent
        if typeof(ev) == "Instance" and ev:IsA("RemoteEvent") then
            signal = ev.OnClientEvent
        elseif type(ev) == "table" and ev.OnClientEvent then
            signal = ev.OnClientEvent
        else
            return false
        end
        S.mutLive.beamHooked = true
        S.mutLive.beamConn = signal:Connect(function(pos, dur)
            if not S.alive or myToken ~= S.token then return end
            pcall(S.mutLive.onEclipseBeamWave, pos, dur)
            if S.mutLive.beamOnOwnPlot(pos) then
                task.delay((tonumber(dur) or 0) + 0.6, function()
                    if S.alive and myToken == S.token and S.mutLive.isEclipse() then
                        S.mutLive.queueEclipseRefresh(0.1)
                    end
                end)
            end
        end)
        dlog("EclipseBeam hook ON via %s", tostring(src))
        return true
    end
    pcall(function()
        local netMod = ReplicatedStorage:FindFirstChild("SharedModules")
        netMod = netMod and netMod:FindFirstChild("Networking")
        if netMod then
            local ok, net = pcall(require, netMod)
            if ok and type(net) == "table" then
                local we = net.WeatherEffects
                if type(we) == "table" and bindBeam(we.EclipseBeam, "Networking.WeatherEffects") then
                    return
                end
            end
        end
        for _, d in ipairs(ReplicatedStorage:GetDescendants()) do
            if d:IsA("RemoteEvent") and string.lower(d.Name) == "eclipsebeam" then
                if bindBeam(d, d:GetFullName()) then return end
            end
        end
    end)
end

local function hookEclipseShellMut(myToken)
    local function isEclipsePlayingAttr(name, val)
        if val ~= true or type(name) ~= "string" then return false end
        local base = name:match("^(.+)_Playing$")
        if not base then return false end
        local c = string.lower((base:gsub("%s+", "")))
        if c:find("eclipsebloom", 1, true) then return false end
        return c == "eclipse" or c == "eclipsed" or c == "solareclipse"
            or c:find("eclipse", 1, true) ~= nil
    end
    if S.mutLive.eclipseConn then
        pcall(function() S.mutLive.eclipseConn:Disconnect() end)
        S.mutLive.eclipseConn = nil
    end
    if S.mutLive.timeFrozenConn then
        pcall(function() S.mutLive.timeFrozenConn:Disconnect() end)
        S.mutLive.timeFrozenConn = nil
    end
    local wv = ReplicatedStorage:FindFirstChild("WeatherValues")
    if wv then
        S.mutLive.eclipseConn = wv.AttributeChanged:Connect(function(attr)
            if not S.alive or myToken ~= S.token then return end
            local ok, val = pcall(function() return wv:GetAttribute(attr) end)
            if ok and isEclipsePlayingAttr(attr, val) then
                onEclipseForShellMut(myToken)
            end
        end)
        for attrName, val in pairs(wv:GetAttributes()) do
            if isEclipsePlayingAttr(attrName, val) then
                onEclipseForShellMut(myToken)
                break
            end
        end
    end
    -- Decompile WeatherController: TimeFrozen=true saat Eclipse start
    S.mutLive.timeFrozenConn = Workspace:GetAttributeChangedSignal("TimeFrozen"):Connect(function()
        if not S.alive or myToken ~= S.token then return end
        if Workspace:GetAttribute("TimeFrozen") == true then
            S.mutLive.eclipseGrow = true
            onEclipseForShellMut(myToken)
        else
            S.mutLive.eclipseGrow = false
            S.mutLive.posLoopRunning = false
            pcall(S.mutLive.finishEclWaveCycle)
            -- Pulihkan soft shell ke FVC + CanQuery (AC/prompt)
            task.defer(function()
                if S.alive and myToken == S.token then
                    pcall(registerAllOwnShellsInFvc)
                end
            end)
        end
    end)
    if Workspace:GetAttribute("TimeFrozen") == true then
        S.mutLive.eclipseGrow = true
        onEclipseForShellMut(myToken)
    end
    hookEclipseBeamSync(myToken)
end

local function hookGardenSyncForMutation()
    if S.mutLive.gardenSyncHooked then return end
    local sync = getGardenSync()
    if type(sync) ~= "table" then return end
    S.mutLive.gardenSyncHooked = true
    for k, v in pairs(sync) do
        if type(v) ~= "function" or type(k) ~= "string" then continue end
        if sync["__GAG2Mut_" .. k] then continue end
        local low = string.lower(k)
        if low:sub(1, 3) == "get" or low:sub(1, 2) == "is" or low == "new" then
            continue
        end
        if low:find("update", 1, true) or low:find("apply", 1, true)
            or low:find("patch", 1, true) or low:find("reconcile", 1, true)
            or low:find("handle", 1, true) or low:find("process", 1, true)
            or low:find("receive", 1, true) or low:find("onfruit", 1, true)
            or low:find("ongarden", 1, true) or low:find("mutat", 1, true)
            or (low:find("fruit", 1, true) and (low:find("set", 1, true) or low:find("add", 1, true)))
        then
            sync["__GAG2Mut_" .. k] = v
            sync[k] = function(self, ...)
                -- Pause kebun orang: jangan antri SpawnPlant/Fruit 3×1200 (HP drop 2fps)
                if S.otherPaused and S.otherPaused() then
                    if low == "handlegardenssync" then
                        local payload = ...
                        if type(payload) == "table" then
                            local mine = payload[LP.UserId] or payload[tostring(LP.UserId)]
                            local filtered = {}
                            if mine ~= nil then
                                filtered[LP.UserId] = mine
                            end
                            local okS, aS, bS, cS, dS = pcall(v, self, filtered)
                            if okS then return aS, bS, cS, dS end
                            return nil
                        end
                    else
                        local uid = tonumber((select(1, ...)))
                        if uid and uid ~= LP.UserId then
                            return nil
                        end
                    end
                end
                local ok, a, b, c, d = pcall(v, self, ...)
                -- Jangan stamp-all tiap Age/update — itu yang bikin stampMut ×100 + hitch 500ms.
                if low:find("mutat", 1, true) then
                    queueLiveMutationStamp(1.5)
                end
                if ok then return a, b, c, d end
                return nil
            end
        end
    end
    dlog("GardenSync mutation stamp hooks installed")
end

-- GardenSync TIDAK nulis fruit.Mutation saat weather. FVC cuma SetAttribute
-- kalau u3[userId_plantId_fruitId] ada. Soft shell sering miss u3 → buah polos.
-- (bukan chunk local — file sudah di limit 200 register)
S.mutLive.applyLive = function(userId, plantId, fruitId, mutName)
    if fruitId == nil then return false end
    if typeof(userId) == "number" and userId ~= LP.UserId then return false end
    local name = mutName
    if type(name) ~= "string" then name = "" end
    name = name:match("^%s*(.-)%s*$") or ""
    local low = string.lower(name)
    if low == "none" or low == "normal" or low == "nomutation" then
        name = ""
    end

    local sync = getGardenSync()
    if sync and type(sync.GetPlant) == "function" then
        pcall(function()
            local plant = sync:GetPlant(userId or LP.UserId, plantId)
            if type(plant) ~= "table" then return end
            if type(plant.Fruits) ~= "table" then
                plant.Fruits = {}
            end
            local f = plant.Fruits[fruitId]
            if f == nil then f = plant.Fruits[tostring(fruitId)] end
            if type(f) ~= "table" then
                f = { FruitId = fruitId }
                plant.Fruits[fruitId] = f
            end
            if name == "" then
                f.Mutation = nil
            else
                f.Mutation = name
                f[name] = true
            end
        end)
    end

    local shell = lookupOwnFruitShell(fruitId, plantId)
    if not (shell and shell.Parent) then
        pcall(enqueueFruitShell, userId or LP.UserId, plantId, fruitId, { FruitId = fruitId, Mutation = name ~= "" and name or nil })
        return false
    end
    pcall(function()
            if name == "" then
                shell:SetAttribute("Mutation", nil)
                for _, k in ipairs({
                    "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
                    "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil",
                }) do
                    if shell:GetAttribute(k) == true then
                        shell:SetAttribute(k, nil)
                    end
                end
            else
                shell:SetAttribute("Mutation", name)
                stampMutationAttrs(shell, { Mutation = name })
            end
    end)
    bindSoftShellInFvcU3(shell, userId or LP.UserId, plantId, fruitId)
    bindFruitMutationListener(shell)
    S.mutLive.liveStamped = (tonumber(S.mutLive.liveStamped) or 0) + 1
    return true
end

S.mutLive.hookFruitMut = function()
    if S.mutLive.fruitMutHooked then return end
    local sync = getGardenSync()
    if type(sync) == "table" and type(sync.OnFruitMutationUpdated) == "function" then
        local ok = pcall(function()
            sync:OnFruitMutationUpdated(function(userId, plantId, fruitId, mutName)
                pcall(S.mutLive.applyLive, userId, plantId, fruitId, mutName)
            end)
        end)
        if ok then
            S.mutLive.fruitMutHooked = true
            dlog("OnFruitMutationUpdated → applyLive")
            return
        end
    end
    pcall(function()
        local netMod = ReplicatedStorage:FindFirstChild("SharedModules")
        netMod = netMod and netMod:FindFirstChild("Networking")
        if not netMod then return end
        local ok, net = pcall(require, netMod)
        if not (ok and type(net) == "table" and net.Garden and net.Garden.FruitMutationUpdated) then
            return
        end
        local ev = net.Garden.FruitMutationUpdated
        local signal = ev.OnClientEvent
        if not signal then return end
        signal:Connect(function(userId, plantId, fruitId, mutName)
            pcall(S.mutLive.applyLive, userId, plantId, fruitId, mutName)
        end)
        S.mutLive.fruitMutHooked = true
        dlog("FruitMutationUpdated remote → applyLive")
    end)
end

-- Hook Eclipse segera. Jangan stamp-all di boot (CPU spike).
local function startLiveMutationSync(myToken)
    task.spawn(function()
        if not S.alive or myToken ~= S.token then return end
        S.mutLive.ready = true
        hookGardenSyncForMutation()
        S.mutLive.hookFruitMut()
        hookEclipseShellMut(myToken)
        if Workspace:GetAttribute("TimeFrozen") == true then
            onEclipseForShellMut(myToken)
        end
        while S.alive and myToken == S.token do
            task.wait(20.0)
            if not S.alive or myToken ~= S.token then return end
            if not (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)) then
                continue
            end
            -- LITE: paling sering 1× / ~8–20s (bukan tiap spawn ×3000)
            if Workspace:GetAttribute("TimeFrozen") == true then
                S.mutLive.queueEclipseRefresh(0.5)
            end
        end
    end)
end

-- Boot lama: mirror attr saja, TANPA scan FVC / GardenSync hook
local function startMutationMirror()
    hookMutationController()
    local plot = myPlot()
    if plot then
        bindPlotMutationMirror(plot)
    end
end

local function stampFruitDetectAttrs(model, plantId, fruitId, fruitData, plant)
    if not model then return end
    -- PlantId HARUS sama tipe/value dengan plant model (server CollectFruit ketat)
    local pid = plantId
    if typeof(plant) == "Instance" then
        local fromPlant = plant:GetAttribute("PlantId")
        if fromPlant ~= nil then
            pid = fromPlant
        end
    end
    local data = resolveFruitDataFromSync(pid or plantId, fruitId, fruitData) or {}
    local fid = fruitId
    if type(data) == "table" then
        -- FruitId "" = single-harvest — jangan ambil data.Id (sering = PlantId → collect gagal)
        local fromData = data.FruitId or data.fruitId
        if fromData ~= nil then
            fid = fromData
        elseif tostring(fruitId or "") ~= "" then
            fromData = data.Id or data.id or data.UUID or data.Uuid
            if fromData ~= nil then fid = fromData end
        end
    end
    pcall(function()
        -- HarvestPromptController baca PlantId/FruitId HANYA dari model ancestor prompt
        model:SetAttribute("FruitId", fid)
        model:SetAttribute("PlantId", pid)
        model:SetAttribute("UserId", LP.UserId)
        model:SetAttribute(A.FRUIT_SHELL_ATTR, true)
        if tostring(fid or "") == "" then
            model:SetAttribute("_GAG2PlantHarvest", true)
        else
            model:SetAttribute("_GAG2PlantHarvest", nil)
        end

        -- Mirror FVC SpawnFruitFromData attrs (+ BaseWeight cache utk INFO tanpa panggil FVC)
        local plantName = data.PlantName or data.SeedName or data.ItemName or data.FruitType
        if (plantName == nil or plantName == "") and typeof(plant) == "Instance" then
            plantName = plant:GetAttribute("CorePartName")
                or plant:GetAttribute("SeedName")
                or plant:GetAttribute("ItemName")
                or plant:GetAttribute("FruitType")
                or discoverPlantTypeName(plant)
        end
        local n = nil
        if plantName ~= nil then
            n = normalizeTypeName(plantName) or tostring(plantName)
            if n and n ~= "" then
                model:SetAttribute("CorePartName", n) -- FVC CalculateFruitWeight
                model:SetAttribute("SeedName", n)
                model:SetAttribute("ItemName", n)
                model:SetAttribute("FruitType", n)
            end
        end

        local age = _pickDataNum(data, { "Age", "age" })
        local maxAge = _pickDataNum(data, { "MaxAge", "maxAge" })
        -- FVC: SizeMulti = p225.SizeMultiplier or 1
        local sm = _pickDisplaySizeMulti(data) or 1
        local og = _pickDataNum(data, { "OvertimeGrowth" }) or 1
        -- FVC: BaseWeight dari Fruits[PlantName].GrowData (bukan sync Weight)
        local bw = _fruitModuleBaseWeight(n)
            or _pickDataNum(data, { "BaseWeight", "baseWeight", "BaseKg" })
        local w = _pickDisplayWeight(data, bw, sm, og)
        if maxAge ~= nil then model:SetAttribute("MaxAge", maxAge) end
        if age ~= nil then model:SetAttribute("Age", age) end
        if bw ~= nil then model:SetAttribute("BaseWeight", bw) end
        model:SetAttribute("SizeMulti", sm)
        if og ~= nil then model:SetAttribute("OvertimeGrowth", og) end
        -- FVC tidak set attr Weight; cache hasil rumus yang sama utk INFO/ESP
        if w and w > 0 then
            model:SetAttribute("Weight", w)
        else
            model:SetAttribute("Weight", nil)
        end
        if data.Variant ~= nil then model:SetAttribute("Variant", data.Variant) end
    end)
    -- Mutation string + boolean (Glow/Gold/Rainbow) — AC baca dari attr buah
    stampMutationAttrs(model, data)
    bindFruitMutationListener(model)
    registerFruitShellInFvc(model, fid)
    -- Soft shell: tag HarvestPrompt hanya kalau mature (akurasi CollectFruit)
    applyShellCollectGate(model, fruitDataHarvestReady(data, model))
end

-- HarvestPromptController.rebuildHarvestPartCache skip nama "HarvestPart".
-- Perlu ≥1 BasePart lain supaya prompt di-track & posisi OK.
local function ensureShellBodyPart(model, cf)
    -- WAJIB Model buah (UUID). Jangan Folder Fruits / Part lepas.
    if not model or not model:IsA("Model") then return nil end
    if model.Name == "Fruits" or model.Name == "Fruit" then return nil end
    local body = model:FindFirstChild("ShellBody")
    if body and body:IsA("BasePart") then
        return body
    end
    body = Instance.new("Part")
    body.Name = "ShellBody"
    body.Size = Vector3.new(1.2, 1.2, 1.2)
    body.Transparency = 1
    body.Anchored = true
    body.CanCollide = false
    body.CanTouch = false
    body.CanQuery = true -- HarvestPromptController cache butuh part queryable
    body.CastShadow = false
    body.CFrame = cf or model:GetPivot()
    body.Parent = model
    return body
end

local function markFruitPromptsCollected(model)
    if not model then return end
    for _, d in ipairs(model:GetDescendants()) do
        if d:IsA("ProximityPrompt") then
            pcall(function()
                d:SetAttribute("Collected", true)
                d.Enabled = false
                d.MaxActivationDistance = 0
                d:RemoveTag("HarvestPrompt")
            end)
        end
    end
    if model:IsA("ProximityPrompt") then
        pcall(function()
            model:SetAttribute("Collected", true)
            model.Enabled = false
            model:RemoveTag("HarvestPrompt")
        end)
    end
end

local function cancelQueuedFruitShell(plantId, fruitId)
    local key = string.format("%s_%s_%s", tostring(LP.UserId), tostring(plantId), tostring(fruitId))
    Q.fruitShellQueued[key] = nil
    for i = #Q.fruitShell, 1, -1 do
        local job = Q.fruitShell[i]
        if job and tostring(job.plantId) == tostring(plantId)
            and tostring(job.fruitId) == tostring(fruitId) then
            table.remove(Q.fruitShell, i)
        end
    end
end

local function liveFruitIdSet(plantData)
    local live = {}
    if type(plantData) ~= "table" then return live end
    local fruits = plantData.Fruits or plantData.fruits or plantData.Fruit
    if type(fruits) ~= "table" then return live end
    if #fruits > 0 then
        for i = 1, #fruits do
            local d = fruits[i]
            if type(d) == "table" then
                local id = d.FruitId or d.fruitId or d.Id or d.id or d.UUID or d.Uuid
                if id ~= nil then live[tostring(id)] = true end
            elseif d ~= nil then
                live[tostring(d)] = true
            end
        end
    else
        for fruitId, d in pairs(fruits) do
            if type(d) == "table" then
                local id = d.FruitId or d.fruitId or d.Id or d.id or fruitId
                live[tostring(id)] = true
            elseif d == true or type(d) == "string" or type(d) == "number" then
                live[tostring(fruitId)] = true
            end
        end
    end
    return live
end

local function findOwnPlantModel(plantId)
    local pvc = getPVC()
    local plant = nil
    if pvc and type(pvc.GetSpawnedPlant) == "function" then
        pcall(function()
            plant = pvc:GetSpawnedPlant(LP.UserId, plantId)
        end)
    end
    if typeof(plant) == "Instance" and plant.Parent then return plant end
    local plot = myPlot()
    if not plot then return nil end
    local want = tostring(plantId)
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, ch in ipairs(folder:GetChildren()) do
            if ch:IsA("Model") and tostring(ch:GetAttribute("PlantId") or ch.Name) == want then
                return ch
            end
        end
    end
    return nil
end

local function isFruitInSync(plantId, fruitId)
    plantId = tostring(plantId or "")
    fruitId = tostring(fruitId or "")
    if plantId == "" or fruitId == "" then return false end
    local sync = getGardenSync()
    if not sync or type(sync.GetPlant) ~= "function" then
        return true -- unknown → jangan destroy
    end
    local plantData = nil
    pcall(function()
        plantData = sync:GetPlant(LP.UserId, plantId)
    end)
    if type(plantData) ~= "table" then
        return false
    end
    local live = liveFruitIdSet(plantData)
    -- sync kosong / format beda → jangan mass-delete buah valid
    if next(live) == nil then
        return true
    end
    return live[fruitId] == true
end

-- Hanya buang shell yang TIDAK ada di GardenSync. MaxFruits bukan batas server.
local function pruneOrphanShellsOnPlant(plant, liveSet)
    if not plant then return 0 end
    if type(liveSet) ~= "table" or next(liveSet) == nil then return 0 end
    local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
    if not folder then return 0 end
    local n = 0
    for _, ch in ipairs(folder:GetChildren()) do
        if ch:IsA("Model") then
            local fid = tostring(ch:GetAttribute("FruitId") or "")
            if fid ~= "" and liveSet[fid] ~= true then
                markFruitPromptsCollected(ch)
                if pcall(function() ch:Destroy() end) then
                    n += 1
                end
            end
        end
    end
    return n
end

local function destroyOwnFruitShell(plantId, fruitId)
    plantId = tostring(plantId or "")
    fruitId = tostring(fruitId or "")
    if plantId == "" or fruitId == "" then return false end
    cancelQueuedFruitShell(plantId, fruitId)
    clearPendingCollect(plantId, fruitId, LP.UserId)
    unbindSoftShellFromFvcU3(LP.UserId, plantId, fruitId)
    unregisterFruitShellFromFvc(fruitId)
    local plant = findOwnPlantModel(plantId)
    if typeof(plant) ~= "Instance" then return false end
    local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
    if not folder then return false end
    local killed = false
    local wasEclipseLive = S.mutLive.isTopHeavy(fruitId, plantId)
    for _, ch in ipairs(folder:GetChildren()) do
        if tostring(ch:GetAttribute("FruitId") or "") == fruitId then
            if ch:GetAttribute("_GAG2EclipseLive") == true then
                wasEclipseLive = true
            end
            markFruitPromptsCollected(ch)
            if pcall(function() ch:Destroy() end) then
                killed = true
                S.statsPrunedFruits += 1
            end
        end
    end
    if killed and wasEclipseLive and S.mutLive.isEclipse() then
        S.mutLive.queueRefill(1.5)
    end
    return killed
end

-- Aman: destroy shell HANYA kalau fruit sudah tidak ada di GardenSync (collect benar-benar sukses)
local function destroyOwnFruitShellIfGone(plantId, fruitId)
    if isFruitInSync(plantId, fruitId) then
        return false
    end
    return destroyOwnFruitShell(plantId, fruitId)
end

-- Hapus shell/fruit client yang sudah tidak ada di GardenSync (setelah collect)
local function pruneOrphanOwnFruits()
    local sync = getGardenSync()
    local pvc = getPVC()
    if not sync or not pvc then return 0 end
    if type(sync.GetGarden) ~= "function" or type(pvc.GetSpawnedPlant) ~= "function" then
        return 0
    end
    local garden = nil
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then return 0 end

    local n = 0
    for plantId, plantData in pairs(garden) do
        if type(plantData) == "table" then
            local plant = nil
            pcall(function()
                plant = pvc:GetSpawnedPlant(LP.UserId, plantId)
            end)
            if typeof(plant) == "Instance" and plant.Parent then
                n += cleanupLooseFruitProxies(plant)
                local live = liveFruitIdSet(plantData)
                local cut = pruneOrphanShellsOnPlant(plant, live)
                n += cut
                S.statsPrunedFruits += cut
            end
        end
    end

    -- plant yang sudah hilang dari sync: bersihkan fruit folder di model sisa
    local plot = myPlot()
    if plot then
        for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
            for _, plant in ipairs(folder:GetChildren()) do
                if plant:IsA("Model") then
                    local pid = plant:GetAttribute("PlantId")
                    if pid ~= nil and garden[pid] == nil and garden[tostring(pid)] == nil then
                        local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                        if ff then
                            for _, ch in ipairs(ff:GetChildren()) do
                                markFruitPromptsCollected(ch)
                                if pcall(function() ch:Destroy() end) then
                                    n += 1
                                    S.statsPrunedFruits += 1
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return n
end

-- Shell fruit RINGAN: Model + FruitId + 1 invisible HarvestPart + HarvestPrompt (AutoCollect)
-- TANPA mesh / CollectProxy / FVC clone — anti freeze
local function ensureDetectFruitShell(plant, plantId, fruitId, fruitData)
    if not plant or not plant.Parent then return nil, false end
    -- nil ditolak; "" = single-harvest CollectFruit(plantId, "")
    if fruitId == nil then return nil, false end
    -- AC sudah fire: jangan recreate sampai sync confirm / TTL
    if isPendingCollect(plantId, fruitId, LP.UserId) then
        return nil, false
    end
    ensureFruitSpawnLocations(plant)
    local fruits = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
    if not fruits then
        fruits = Instance.new("Folder")
        fruits.Name = "Fruits"
        fruits.Parent = plant
    end

    bindFruitsFolderCleanup(fruits)
    cleanupLooseFruitProxies(plant)

    local fidKey = tostring(fruitId)
    if fidKey == "" then fidKey = "_plant" end
    local key = string.format("%s_%s_%s", tostring(LP.UserId), tostring(plantId), fidKey)
    local existing = fruits:FindFirstChild(key)
    if not existing then
        for _, ch in ipairs(fruits:GetChildren()) do
            if ch:IsA("Model") and ch:GetAttribute(A.FRUIT_SHELL_ATTR) == true
                and tostring(ch:GetAttribute("FruitId") or "") == tostring(fruitId) then
                existing = ch
                break
            end
        end
    end
    if existing and existing.Parent and existing:IsA("Model") then
        stampFruitDetectAttrs(existing, plantId, fruitId, fruitData, plant)
        registerFruitShellInFvc(existing, fruitId)
        ensureShellBodyPart(existing, existing:GetPivot())
        local pr = existing:FindFirstChild("HarvestPrompt", true)
        if not pr then
            local hp = existing:FindFirstChild("HarvestPart")
            if not (hp and hp:IsA("BasePart")) then
                hp = Instance.new("Part")
                hp.Name = "HarvestPart"
                hp.Size = Vector3.new(1, 1, 1)
                hp.Transparency = 1
                hp.Anchored = true
                hp.CanCollide = false
                hp.CanQuery = true
                hp.CastShadow = false
                hp.CFrame = plant:GetPivot()
                hp.Parent = existing
                existing.PrimaryPart = hp
            end
            pr = Instance.new("ProximityPrompt")
            pr.Style = Enum.ProximityPromptStyle.Custom
            pr.Name = "HarvestPrompt"
            pr.ActionText = "Harvest"
            pr.HoldDuration = 0
            pr.MaxActivationDistance = 10
            pr.RequiresLineOfSight = false
            pr.Parent = hp
        end
        -- stamp sudah gate ripe; pastikan ulang dari data sync
        local data = resolveFruitDataFromSync(plantId, fruitId, fruitData) or {}
        applyShellCollectGate(existing, fruitDataHarvestReady(data, existing))
        bindSoftShellInFvcU3(existing, LP.UserId, plantId, fruitId)
        return existing, false
    end

    local data = type(fruitData) == "table" and fruitData or {}
    local cf = plant:GetPivot()
    local locFolder = plant:FindFirstChild("FruitSpawnLocations")
    local idx = tonumber(data.SpawnLocationIndex)
    if locFolder and idx and idx >= 1 then
        local loc = locFolder:GetChildren()[idx]
        if loc and loc:IsA("BasePart") then cf = loc.CFrame end
    end

    local model = Instance.new("Model")
    model.Name = key
    stampFruitDetectAttrs(model, plantId, fruitId, data, plant)

    -- Body dulu (bukan HarvestPart) — controller cache parts dari sini
    ensureShellBodyPart(model, cf)

    local hp = Instance.new("Part")
    hp.Name = "HarvestPart"
    hp.Size = Vector3.new(1, 1, 1)
    hp.Transparency = 1
    hp.Anchored = true
    hp.CanCollide = false
    hp.CanTouch = false
    hp.CanQuery = true
    hp.CastShadow = false
    hp.CFrame = cf
    hp.Parent = model
    model.PrimaryPart = hp

    local prompt = Instance.new("ProximityPrompt")
    prompt.Style = Enum.ProximityPromptStyle.Custom
    prompt.Name = "HarvestPrompt"
    prompt.ActionText = "Harvest"
    prompt.HoldDuration = 0
    prompt.MaxActivationDistance = 10
    prompt.RequiresLineOfSight = false
    prompt.Enabled = true
    prompt.Parent = hp
    local syncData = resolveFruitDataFromSync(plantId, fruitId, data) or data
    applyShellCollectGate(model, fruitDataHarvestReady(syncData, model))

    model.Parent = fruits
    registerFruitShellInFvc(model, fruitId)
    bindSoftShellInFvcU3(model, LP.UserId, plantId, fruitId)
    -- JANGAN queueEclipseRefresh di sini (spam ×1000 shell = lag).
    -- Kekurangan top-N diurus loop 20s / beam / collect → queueRefill.
    return model, true
end

local function drainFruitShellQueue()
    if Q.fruitShellDraining then return end
    Q.fruitShellDraining = true
    task.spawn(function()
        while #Q.fruitShell > 0 do
            -- FAR: jangan buat soft shell (plant sering di CulledPlants)
            while S.alive and (S.farPaused == true or isFarFromOwnPlot()) and #Q.fruitShell > 0 do
                task.wait(0.4)
                pcall(noteFarNearEdge)
            end
            if #Q.fruitShell == 0 then break end
            local loading = isGardenLoadingNow()
            local catching = isResumeCatchup()
            local liveOn = S.alive == true or S.running == true
            local batch, delaySec
            if loading then
                batch = tonumber(CONFIG.loadShellBatch) or 2
                delaySec = tonumber(CONFIG.loadShellDelay) or 0.18
            elseif catching then
                batch = tonumber(CONFIG.resumeShellBatch) or 1
                delaySec = tonumber(CONFIG.resumeShellDelay) or 0.28
            elseif liveOn then
                batch = tonumber(CONFIG.liveShellBatch) or 10
                delaySec = tonumber(CONFIG.liveShellDelay) or 0.05
            else
                batch = tonumber(CONFIG.restoreFruitBatchSize) or 3
                delaySec = tonumber(CONFIG.restoreFruitBatchDelay) or 0.12
            end
            batch = math.max(1, math.floor(batch))
            delaySec = math.max(0.02, tonumber(delaySec) or 0.05)
            if not S.alive and not S.running then
                -- Stop sedang restore: tetap drain pelan
            end
            G.__GAG2_RF_JOB("fruitShell", function()
                for _ = 1, batch do
                    if S.farPaused == true or isFarFromOwnPlot() then break end
                    local job = table.remove(Q.fruitShell, 1)
                    if not job then break end
                    local qk = job.key
                    Q.fruitShellQueued[qk] = nil
                    if isPendingCollect(job.plantId, job.fruitId, job.userId) then
                        continue
                    end
                    local pvc = getPVC()
                    local plant = nil
                    if pvc and type(pvc.GetSpawnedPlant) == "function" then
                        pcall(function()
                            plant = pvc:GetSpawnedPlant(job.userId, job.plantId)
                        end)
                    end
                    -- Skip plant yang sedang di-cull (bukan di Plot.Plants)
                    if typeof(plant) == "Instance" and plant.Parent and not isInCulledFolder(plant) then
                        local shell, created = ensureDetectFruitShell(plant, job.plantId, job.fruitId, job.data)
                        if created then B.stats.fruits += 1 end
                        if shell and shell.Parent then
                            -- Eclipse: registerFruitShellInFvc auto-block luar top-N + CanQuery off
                            registerFruitShellInFvc(shell, job.fruitId)
                            bindSoftShellInFvcU3(shell, job.userId, job.plantId, job.fruitId)
                        end
                    end
                end
            end)
            if #Q.fruitShell > 0 then
                task.wait(delaySec)
            end
        end
        Q.fruitShellDraining = false
        -- sekali saja setelah antrean kosong: cek top-N kurang? (bukan per shell)
        if S.alive and S.mutLive.isEclipse() and not isFarFromOwnPlot() then
            S.mutLive.queueRefill(2.5)
        end
    end)
end

local function enqueueFruitShell(userId, plantId, fruitId, data)
    if isPendingCollect(plantId, fruitId, userId) then return end
    if CONFIG.ownNoFruitShells ~= false
        and (tonumber(userId) or LP.UserId) == LP.UserId then
        if not (S.mutLive.isEclipse() and S.mutLive.isTopHeavy(fruitId, plantId)) then
            return
        end
    end
    -- Own shell: jangan antre saat FAR (hindari backlog → spike saat dekat)
    if (tonumber(userId) or LP.UserId) == LP.UserId
        and CONFIG.pauseFarFromPlot ~= false
        and (S.farPaused == true or isFarFromOwnPlot()) then
        return
    end
    local key = string.format("%s_%s_%s", tostring(userId), tostring(plantId), tostring(fruitId))
    if Q.fruitShellQueued[key] then return end
    Q.fruitShellQueued[key] = true
    local job = {
        key = key,
        userId = userId,
        plantId = plantId,
        fruitId = fruitId,
        data = data,
    }
    -- Ripe dulu biar Auto Collect tetap dapat target, unripe ngantri.
    local ripe = false
    if type(data) == "table" then
        ripe = fruitDataHarvestReady(data, nil) == true
    end
    if ripe then
        table.insert(Q.fruitShell, 1, job)
    else
        Q.fruitShell[#Q.fruitShell + 1] = job
    end
    drainFruitShellQueue()
end

stripHeavyVisual = function(model)
    if not model or not model.Parent then return 0 end
    -- debug_show_top10_heaviest: jangan strip ulang
    if model:GetAttribute("_GAG2KeepVisual") == true then return 0 end
    local isPlant = model:GetAttribute("PlantId") ~= nil and not isFruitModel(model)
    if isPlant then
        if CONFIG.ownNoFruitShells == false then
            ensureProxy(model) -- CollectProxy di PLANT saja
        end
        cleanupLooseFruitProxies(model)
    elseif model:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
        ensureProxy(model) -- buah game-managed
    end
    -- soft shell: jangan ensureProxy (CollectProxy); HarvestPart/ShellBody di UUID
    local kill = {}
    for _, d in ipairs(model:GetDescendants()) do
        -- strip plant: jangan sentuh isi folder Fruits (finalizeFruit yang urus)
        if isPlant and underFruitsFolder(d) then
            continue
        end
        if isDetectKeepInstance(d) then
            -- keep
        elseif d:IsA("BasePart") or d:IsA("MeshPart") or d:IsA("SpecialMesh")
            or d:IsA("Decal") or d:IsA("Texture")
            or d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail")
            or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles")
            or d:IsA("Highlight") or d:IsA("SelectionBox")
            or d:IsA("BillboardGui") or d:IsA("SurfaceGui")
            or d:IsA("Sound") or d:IsA("WrapLayer") or d:IsA("WrapTarget") then
            kill[#kill + 1] = d
        end
    end
    local n = 0
    for i = 1, #kill do
        if pcall(function() kill[i]:Destroy() end) then
            n += 1
        end
        -- Destroy massal di garden 2–3k buah = spike; yield sering
        if i % 28 == 0 then
            stripBudgetYield()
        end
    end
    if isPlant then
        if CONFIG.ownNoFruitShells == false then
            ensureProxy(model)
        end
        cleanupLooseFruitProxies(model)
        ensurePlantSyncBase(model)
    elseif model:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then
        ensureProxy(model)
    end
    if n > 0 then
        B.statsBlocked.stripped += 1
        B.stats.stashed += 1
    end
    return n
end

-- Setelah FVC/InitFruit game selesai → strip mesh, prompt game tetap
local function stripFruitAfterGameSpawn(fruit)
    if not fruit then return end
    task.defer(function()
        task.wait(0.08)
        if not fruit.Parent or not S.visualBlockActive then return end
        if fruit:GetAttribute("_GAG2KeepVisual") == true then
            bindFruitMutationListener(fruit)
            stampMutationAttrs(fruit, nil)
            return
        end
        if CONFIG.stripOwnVisual then
            stripHeavyVisual(fruit)
        end
        -- Mutation string game → boolean (sebelum weather / setelah InitFruit)
        bindFruitMutationListener(fruit)
        stampMutationAttrs(fruit, nil)
    end)
end

-- Strip plant + buah di dalamnya; attrs tetap (detect-safe)
-- opts.light=true: mid-session ON (garden sudah penuh) — skip resolveGardenSync per buah
stripPlantKeepDetect = function(plant, opts)
    if not plant or not plant.Parent then return 0 end
    opts = type(opts) == "table" and opts or {}
    local light = opts.light == true
    local plantId = plant:GetAttribute("PlantId")
    local n = stripHeavyVisual(plant)
    ensurePlantSyncBase(plant)
    stripBudgetYield()

    local function finalizeFruit(f)
        if not (f and f:IsA("Model")) then return end
        if f:GetAttribute("_GAG2KeepVisual") == true then
            bindFruitMutationListener(f)
            stampMutationAttrs(f, nil)
            return
        end
        if CONFIG.ownNoFruitShells ~= false and S.running then
            if S.mutLive.isEclipse() then
                local fid = f:GetAttribute("FruitId")
                if fid ~= nil and S.mutLive.isTopHeavy(fid, plantId) then
                    return
                end
            end
            pcall(function() f:Destroy() end)
            return
        end
        if f:GetAttribute("FruitId") == nil then return end
        -- soft shell attr dulu supaya stripHeavyVisual tidak pasang CollectProxy
        if not useGameManagedFruits() then
            pcall(function() f:SetAttribute(A.FRUIT_SHELL_ATTR, true) end)
        end
        n += stripHeavyVisual(f)
        -- game-managed: jangan rewrite attrs / ShellBody — biarkan prompt game
        if plantId ~= nil and f:GetAttribute("PlantId") == nil then
            pcall(function()
                f:SetAttribute("PlantId", plantId)
            end)
        end
        if not useGameManagedFruits() then
            local fruitId = f:GetAttribute("FruitId")
            if fruitId ~= nil then
                ensureShellBodyPart(f, f:GetPivot())
                local pr = f:FindFirstChild("HarvestPrompt", true)
                if not pr then
                    local hp = f:FindFirstChild("HarvestPart")
                    if not (hp and hp:IsA("BasePart")) then
                        hp = f:FindFirstChild("ShellBody")
                    end
                    if hp and hp:IsA("BasePart") then
                        pr = Instance.new("ProximityPrompt")
                        pr.Style = Enum.ProximityPromptStyle.Custom
                        pr.Name = "HarvestPrompt"
                        pr.ActionText = "Harvest"
                        pr.HoldDuration = 0
                        pr.RequiresLineOfSight = false
                        pr.Parent = hp
                    end
                end
                if light then
                    -- Attr buah game sudah ada — jangan GetPlant/sync per buah (itu yang bikin lama)
                    bindFruitMutationListener(f)
                    stampMutationAttrs(f, nil)
                    local age = tonumber(f:GetAttribute("Age"))
                    local maxAge = tonumber(f:GetAttribute("MaxAge"))
                    local ready = (age ~= nil and maxAge ~= nil and age >= maxAge)
                    applyShellCollectGate(f, ready == true)
                else
                    -- stamp + gate ripe-only (jangan force-tag semua)
                    stampFruitDetectAttrs(f, plantId or f:GetAttribute("PlantId"), fruitId, nil, plant)
                end
            end
        else
            local pr = f:FindFirstChild("HarvestPrompt", true)
            if pr then tunePrompt(pr) end
        end
        stripBudgetYield()
    end

    local fruits = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
    if fruits then
        bindFruitsFolderCleanup(fruits)
        cleanupLooseFruitProxies(plant)
        for _, f in ipairs(fruits:GetChildren()) do
            if CONFIG.ownNoFruitShells ~= false and S.running
                and f:GetAttribute("_GAG2KeepVisual") ~= true then
                pcall(function() f:Destroy() end)
            else
                finalizeFruit(f)
            end
        end
        cleanupLooseFruitProxies(plant)
    end
    for _, ch in ipairs(plant:GetChildren()) do
        if ch:IsA("Model") and ch:GetAttribute("FruitId") ~= nil then
            finalizeFruit(ch)
        end
    end
    ensureFruitSpawnLocations(plant)
    if CONFIG.ownNoFruitShells == false then
        ensureProxy(plant)
    end
    cleanupLooseFruitProxies(plant)
    return n
end

-- Strip plant lewat Heartbeat budget (anti freeze loading ×1000+ plant)
enqueuePlantStrip = function(plant)
    if typeof(plant) ~= "Instance" or not plant.Parent then
        return
    end
    if isInCulledFolder(plant) then
        return
    end
    if isSprinkler(plant) then
        return
    end
    if plant:GetAttribute(A.TREE_ATTR) == true then
        return
    end
    -- FAR: jangan antre strip own (PlantCulling sudah pindah ke CulledPlants)
    if CONFIG.pauseFarFromPlot ~= false and (S.farPaused == true or isFarFromOwnPlot()) then
        return
    end
    if Q.plantStripQueued[plant] then
        return
    end
    Q.plantStripQueued[plant] = true
    Q.plantStrip[#Q.plantStrip + 1] = plant
    if Q.plantStripConn then
        return
    end
    Q.plantStripConn = RunService.Heartbeat:Connect(function()
        if not S.alive then
            return
        end
        G.__GAG2_RF_JOB("stripPlant", function()
            if CONFIG.pauseFarFromPlot ~= false and (S.farPaused == true or isFarFromOwnPlot()) then
                return
            end
            local loading = isGardenLoadingNow()
            local catching = isResumeCatchup()
            local budget = math.max(1, math.floor(tonumber(
                catching and CONFIG.resumeStripPerFrame or CONFIG.loadStripPerFrame
            ) or 4))
            if not loading and not catching then
                budget = math.max(budget, 8)
            end
            local n = 0
            while n < budget and #Q.plantStrip > 0 do
                if S.farPaused == true then break end
                local p = table.remove(Q.plantStrip, 1)
                if typeof(p) == "Instance" then
                    Q.plantStripQueued[p] = nil
                    if p.Parent and not isInCulledFolder(p)
                        and p:GetAttribute(A.TREE_ATTR) ~= true and S.visualBlockActive
                        and CONFIG.stripOwnVisual then
                        if CONFIG.blockVisualInit then
                            stripPlantKeepDetect(p, { light = loading or catching })
                        else
                            stripHeavyVisual(p)
                        end
                        pcall(function()
                            p:SetAttribute(A.TREE_ATTR, true)
                        end)
                        n += 1
                    end
                end
            end
            if #Q.plantStrip == 0 and Q.plantStripConn then
                pcall(function()
                    Q.plantStripConn:Disconnect()
                end)
                Q.plantStripConn = nil
            end
        end)
    end)
end

local function patchPlantModules()
    if #B.plantBackups > 0 then return #B.plantBackups end
    local folder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
    folder = folder and folder:FindFirstChild("Plants")
    if not folder then return 0 end
    local n = 0
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("ModuleScript") then
            local ok, mod = pcall(require, child)
            if ok and type(mod) == "table" then
                B.plantBackups[#B.plantBackups + 1] = {
                    mod = mod,
                    InitPlant = mod.InitPlant,
                    BeginPlantGrowth = mod.BeginPlantGrowth,
                }
                mod.BeginPlantGrowth = function() end
                mod.InitPlant = function(plant)
                    B.statsBlocked.plantInit += 1
                    if plant then
                        pcall(function()
                            plant:AddTag("InitializationComplete")
                            plant:SetAttribute("PlantGrowthReady", true)
                        end)
                        -- antre strip (jangan Destroy sync di sini)
                        if S.visualBlockActive and CONFIG.stripOwnVisual then
                            enqueuePlantStrip(plant)
                        end
                    end
                end
                n += 1
            end
        end
    end
    dlog("patched plant modules=%d", n)
    return n
end

local function restorePlantModules()
    for i = 1, #B.plantBackups do
        local b = B.plantBackups[i]
        if b and b.mod then
            if b.InitPlant then b.mod.InitPlant = b.InitPlant end
            if b.BeginPlantGrowth then b.mod.BeginPlantGrowth = b.BeginPlantGrowth end
        end
    end
    table.clear(B.plantBackups)
end

patchFruitModules = function()
    if #B.fruitBackups > 0 then return #B.fruitBackups end
    local folder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
    folder = folder and folder:FindFirstChild("Fruits")
    if not folder then return 0 end
    local n = 0
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("ModuleScript") then
            local ok, mod = pcall(require, child)
            if ok and type(mod) == "table" then
                B.fruitBackups[#B.fruitBackups + 1] = {
                    mod = mod,
                    BeginFruitGrowth = mod.BeginFruitGrowth,
                    InitFruit = mod.InitFruit,
                }
                mod.BeginFruitGrowth = function() end
                local origInit = mod.InitFruit
                mod.InitFruit = function(fruit, ...)
                    B.statsBlocked.fruitInit += 1
                    if not fruit then return end
                    if CONFIG.ownNoFruitShells ~= false then
                        if fruit:GetAttribute("_GAG2KeepVisual") == true then
                            if type(origInit) == "function" then
                                pcall(origInit, fruit, ...)
                            end
                            return
                        end
                        -- Eclipse top-N / spawnGuard: JANGAN Destroy.
                        -- FVC SpawnFruitFromData wait HasTag("InitializationComplete") —
                        -- Destroy di sini = hang forever + CreateServerValue/u3 tidak selesai.
                        local keep = S.mutLive.spawnGuard == true
                            or fruit:GetAttribute("_GAG2EclipseLive") == true
                        local fid = fruit:GetAttribute("FruitId")
                        local pid = fruit:GetAttribute("PlantId")
                        if not keep and S.mutLive and type(S.mutLive.pendingKeep) == "table" then
                            local fk = S.mutLive.fruitKey and S.mutLive.fruitKey(pid, fid)
                            if (fk and S.mutLive.pendingKeep[fk])
                                or (fid ~= nil and S.mutLive.pendingKeep[tostring(fid)]) then
                                keep = true
                            end
                        end
                        if not keep and fid ~= nil and S.mutLive.isEclipse
                            and S.mutLive.isEclipse() and S.mutLive.isTopHeavy
                            and S.mutLive.isTopHeavy(fid, pid) then
                            keep = true
                        end
                        if keep then
                            pcall(function() fruit:AddTag("InitializationComplete") end)
                            return
                        end
                        local uid = tonumber(fruit:GetAttribute("UserId"))
                        if uid == nil or uid == LP.UserId then
                            -- Tag dulu. Jangan Destroy: FVC wait tag di instance yang sudah hilang.
                            pcall(function() fruit:AddTag("InitializationComplete") end)
                            return
                        end
                    end
                    -- game-managed saja. Eclipse LITE: jangan InitFruit mesh (×3000 = freeze)
                    if useGameManagedFruits() and type(origInit) == "function" then
                        pcall(origInit, fruit, ...)
                        stripFruitAfterGameSpawn(fruit)
                        return
                    end
                    pcall(function() fruit:AddTag("InitializationComplete") end)
                    task.defer(function()
                        if fruit.Parent and S.visualBlockActive and CONFIG.stripOwnVisual then
                            stripHeavyVisual(fruit)
                        end
                    end)
                end
                n += 1
            end
        end
    end
    dlog("patched fruit modules=%d", n)
    return n
end

restoreFruitModules = function()
    for i = 1, #B.fruitBackups do
        local b = B.fruitBackups[i]
        if b and b.mod then
            if b.BeginFruitGrowth then b.mod.BeginFruitGrowth = b.BeginFruitGrowth end
            if b.InitFruit then b.mod.InitFruit = b.InitFruit end
        end
    end
    table.clear(B.fruitBackups)
end

patchFVC = function()
    local FVC = getFVC()
    if not FVC or FVC.__GAG2RF9 then return FVC ~= nil end
    B.fvcBackup = {
        UpdateFruitAges = FVC.UpdateFruitAges,
        UpdateFruitGrowthData = FVC.UpdateFruitGrowthData,
        ApplyOversizedCollision = FVC.ApplyOversizedCollision,
        SpawnFruitFromData = FVC.SpawnFruitFromData,
    }
    -- Jangan stub total: buah baru tidak pernah SpawnFruitFromData → Info Fruits 0 sampai rejoin.
    -- Throttle orig (masuk hook SpawnFruitFromData → soft shell, bukan mesh tiap frame).
    FVC.UpdateFruitAges = function(self, ...)
        local now = os.clock()
        if (now - (tonumber(S.lastAgeTick) or 0)) < 2.5 then
            return
        end
        S.lastAgeTick = now
        local orig = B.fvcBackup and B.fvcBackup.UpdateFruitAges
        if type(orig) == "function" then
            pcall(orig, self, ...)
        end
    end
    FVC.ApplyOversizedCollision = function() end
    if type(B.fvcBackup.UpdateFruitGrowthData) == "function" then
        local origGrow = B.fvcBackup.UpdateFruitGrowthData
        local function tableHasMut(a)
            if type(a) ~= "table" then return false end
            local mut = a.Mutation or a.mutation or a.MutationName
            if type(mut) == "string" and mut ~= "" then return true end
            return a.Glow == true or a.Gold == true or a.Rainbow == true
                or a.Starstruck == true or a.Eclipsed == true or a.Chained == true
                or a.Aurora == true or a.Ignited == true or a.Bloodlit == true
                or a.Electric == true or a.Frozen == true
        end
        -- Soft: stamp payload → shell. JANGAN origGrow (rebuild MegaBloom mesh).
        -- Age/MaxAge: WAJIB (UpdateFruitAges di-stub → tanpa ini ripe gate delay ~20s).
        local function applyAgeGateToShell(shell, data)
            if not (shell and shell.Parent) or type(data) ~= "table" then return end
            if shell:GetAttribute(A.FRUIT_SHELL_ATTR) ~= true then return end
            local age = _pickDataNum(data, { "Age", "age" })
            local maxAge = _pickDataNum(data, { "MaxAge", "maxAge" })
            -- FVC: SizeMulti ← SizeMultiplier; BaseWeight ← GrowData; og ← OvertimeGrowth
            local sm = _pickDisplaySizeMulti(data)
            local og = _pickDataNum(data, { "OvertimeGrowth" })
            local plantName = data.PlantName
                or shell:GetAttribute("CorePartName")
                or shell:GetAttribute("SeedName")
            local bw = _fruitModuleBaseWeight(plantName)
                or _pickDataNum(data, { "BaseWeight", "baseWeight", "BaseKg" })
            local w = _pickDisplayWeight(data, bw, sm or tonumber(shell:GetAttribute("SizeMulti")), og or 1)
            pcall(function()
                if age ~= nil then shell:SetAttribute("Age", age) end
                if maxAge ~= nil then shell:SetAttribute("MaxAge", maxAge) end
                if bw ~= nil then shell:SetAttribute("BaseWeight", bw) end
                if sm ~= nil and sm > 0 then
                    shell:SetAttribute("SizeMulti", sm)
                end
                if og ~= nil then shell:SetAttribute("OvertimeGrowth", og) end
                if w and w > 0 then
                    shell:SetAttribute("Weight", w)
                end
            end)
            applyShellCollectGate(shell, fruitDataHarvestReady(data, shell))
        end
        local function stampAgeGateFromGrowthArgs(args)
            args = type(args) == "table" and args or {}
            local n = 0
            local function tryAge(fid, pid, data)
                if fid == nil or type(data) ~= "table" then return end
                -- Butuh setidaknya Age/MaxAge/Weight supaya tidak spam shell lookup kosong
                if _pickDataNum(data, { "Age", "age" }) == nil
                    and _pickDataNum(data, { "MaxAge", "maxAge" }) == nil
                    and _pickDataNum(data, { "Weight", "weight", "Kg", "kg" }) == nil
                    and _pickDataNum(data, { "BaseWeight", "baseWeight" }) == nil then
                    return
                end
                local shell = lookupOwnFruitShell(fid, pid)
                if not (shell and shell.Parent) then return end
                applyAgeGateToShell(shell, data)
                n += 1
            end
            for i = 1, #args do
                local a = args[i]
                if type(a) == "table" then
                    local fid = a.FruitId or a.fruitId or a.Id or a.id
                    local pid = a.PlantId or a.plantId
                    if fid ~= nil then
                        tryAge(fid, pid, a)
                    end
                elseif typeof(a) == "Instance" then
                    local fid = a:GetAttribute("FruitId")
                    local pid = a:GetAttribute("PlantId")
                    local data = args[i + 1]
                    if type(data) == "table" then
                        tryAge(fid, pid, data)
                    end
                end
            end
            if #args >= 3 then
                local last = args[#args]
                local fid = args[#args - 1]
                local pid = args[#args - 2]
                if type(last) == "table"
                    and (type(fid) == "string" or typeof(fid) == "number") then
                    tryAge(fid, pid, last)
                end
            end
            return n
        end
        local function stampFromGrowthArgs(args)
            args = type(args) == "table" and args or {}
            local n = 0
            local function tryStamp(fid, pid, data)
                if fid == nil or type(data) ~= "table" or not tableHasMut(data) then return end
                local isEcl = data.Eclipsed == true
                    or (type(data.Mutation) == "string" and string.lower(data.Mutation) == "eclipsed")
                local shell = lookupOwnFruitShell(fid, pid)
                if not (shell and shell.Parent) then return end
                registerFruitShellInFvc(shell, fid)
                if isEcl then
                    S.mutLive.mirrorEclipsedAttr(shell)
                else
                    stampMutationAttrs(shell, data)
                end
                applyAgeGateToShell(shell, data)
                n += 1
            end
            for i = 1, #args do
                local a = args[i]
                if type(a) == "table" and tableHasMut(a) then
                    local fid = a.FruitId or a.fruitId or a.Id or a.id
                    local pid = a.PlantId or a.plantId
                    if fid ~= nil then
                        tryStamp(fid, pid, a)
                    end
                elseif typeof(a) == "Instance" then
                    local fid = a:GetAttribute("FruitId")
                    local pid = a:GetAttribute("PlantId")
                    local data = args[i + 1]
                    if type(data) == "table" and tableHasMut(data) then
                        tryStamp(fid, pid, data)
                    end
                end
            end
            -- (plantId, fruitId, data) / (userId, plantId, fruitId, data)
            if #args >= 3 then
                local last = args[#args]
                local fid = args[#args - 1]
                local pid = args[#args - 2]
                if type(last) == "table" and tableHasMut(last)
                    and (type(fid) == "string" or typeof(fid) == "number") then
                    tryStamp(fid, pid, last)
                end
            end
            return n
        end
        FVC.UpdateFruitGrowthData = function(self, ...)
            local args = { ... }
            local soft = (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual))
                and not useGameManagedFruits()
            if soft then
                -- Eclipse weather = FX only; mutasi masuk lewat growth/sync.
                -- WAJIB origGrow saat TimeFrozen supaya payload Eclipsed land.
                if S.mutLive.isEclipse() then
                    local ok, a, b, c, d = pcall(origGrow, self, table.unpack(args))
                    pcall(stampAgeGateFromGrowthArgs, args)
                    pcall(stampFromGrowthArgs, args)
                    -- Strip mesh yang kebawa, tapi jangan tiap call GetDescendants massal:
                    -- cuma buah yang ada di args.
                    pcall(function()
                        for i = 1, #args do
                            local t = args[i]
                            local fid = nil
                            if type(t) == "table" then
                                fid = t.FruitId or t.fruitId or t.Id or t.id
                            elseif typeof(t) == "Instance" then
                                fid = t:GetAttribute("FruitId")
                            end
                            if fid ~= nil then
                                local shell = lookupOwnFruitShell(fid, nil)
                                if shell and shell.Parent
                                    and shell:GetAttribute("_GAG2KeepVisual") ~= true
                                    and type(stripHeavyVisual) == "function" then
                                    stripHeavyVisual(shell)
                                end
                            end
                        end
                    end)
                    if ok then return a, b, c, d end
                    return nil
                end
                -- Age/ripe dulu (tanpa mutasi), baru stamp mutasi kalau ada
                pcall(stampAgeGateFromGrowthArgs, args)
                pcall(stampFromGrowthArgs, args)
                return nil
            end
            local ok, a, b, c, d = pcall(origGrow, self, table.unpack(args))
            if ok then return a, b, c, d end
            return nil
        end
    end
    -- Soft shell tidak masuk cache FVC → RemoveFruit bawaan miss. Wrap semua remove/destroy fruit.
    for k, v in pairs(FVC) do
        if type(v) == "function" and type(k) == "string" and B.fvcBackup[k] == nil then
            local low = string.lower(k)
            if low:find("fruit", 1, true)
                and (low:find("remove", 1, true) or low:find("destroy", 1, true)
                    or low:find("despawn", 1, true) or low:find("delete", 1, true)
                    or low:find("clear", 1, true)) then
                B.fvcBackup[k] = v
                FVC[k] = function(self, a, b, c, ...)
                    local plantId, fruitId = b, c
                    if typeof(a) ~= "number" then
                        plantId, fruitId = a, b
                    elseif typeof(b) == "number" and typeof(c) ~= "nil" and tostring(c):find("-", 1, true) then
                        -- (userId, plantId, fruitId)
                        plantId, fruitId = b, c
                    end
                    if plantId ~= nil and fruitId ~= nil and fruitId ~= "" then
                        pcall(destroyOwnFruitShell, plantId, fruitId)
                    end
                    local ok, r1, r2, r3 = pcall(v, self, a, b, c, ...)
                    if ok then return r1, r2, r3 end
                    return nil
                end
            end
        end
    end
    if type(FVC.SpawnFruitFromData) == "function" then
        local orig = B.fvcBackup.SpawnFruitFromData
        FVC.SpawnFruitFromData = function(self, userId, plantId, fruitId, data, ...)
            if CONFIG.blockOtherSpawn and typeof(userId) == "number" and userId ~= LP.UserId then
                B.statsBlocked.otherFruitSkip += 1
                return nil
            end
            local isOwn = typeof(userId) == "number" and userId == LP.UserId
            -- OWN skeleton: jangan mesh buah, jangan soft shell. Eclipse top-N tetap FVC.
            if isOwn and CONFIG.ownNoFruitShells ~= false
                and (S.visualBlockActive or CONFIG.stripOwnVisual) then
                if S.mutLive.isEclipse() and S.mutLive.isTopHeavy(fruitId, plantId) and type(orig) == "function" then
                    local pk = S.mutLive.pendingKeep
                    if type(pk) ~= "table" then
                        pk = {}
                        S.mutLive.pendingKeep = pk
                    end
                    local fk = S.mutLive.fruitKey(plantId, fruitId) or tostring(fruitId)
                    pk[fk] = true
                    S.mutLive.spawnGuard = true
                    local okE, resultE = pcall(orig, self, userId, plantId, fruitId, data, ...)
                    S.mutLive.spawnGuard = false
                    pk[fk] = nil
                    if okE and typeof(resultE) == "Instance" then
                        S.mutLive.markEclipseLiveHidden(resultE, fruitId)
                        B.stats.fruits += 1
                        return resultE
                    end
                end
                B.statsBlocked.fruitInit += 1
                return nil
            end
            -- Own fruit: biarkan game spawn (AutoCollect akurat), strip mesh belakangan
            if isOwn and useGameManagedFruits() and type(orig) == "function" then
                local ok, result = pcall(orig, self, userId, plantId, fruitId, data, ...)
                if ok then
                    if typeof(result) == "Instance" then
                        stripFruitAfterGameSpawn(result)
                        B.stats.fruits += 1
                    end
                    return result
                end
                -- fallback shell hanya kalau FVC gagal
                enqueueFruitShell(userId, plantId, fruitId, data)
                return nil
            end
            -- Legacy soft shell (gameManagedFruits=false)
            local soft = S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)
            if soft and isOwn then
                -- AC pending: OnFruitVisualCheck jangan recreate (u3 miss → spam Spawn)
                if isPendingCollect(plantId, fruitId, userId) then
                    return nil
                end
                -- Eclipse top-N: FVC ASLI (server kirim beam). Lainnya soft shell.
                if S.mutLive.isEclipse() and S.mutLive.isTopHeavy(fruitId, plantId) and type(orig) == "function" then
                    local pk = S.mutLive.pendingKeep
                    if type(pk) ~= "table" then
                        pk = {}
                        S.mutLive.pendingKeep = pk
                    end
                    local fk = S.mutLive.fruitKey(plantId, fruitId) or tostring(fruitId)
                    pk[fk] = true
                    S.mutLive.spawnGuard = true
                    local okE, resultE = pcall(orig, self, userId, plantId, fruitId, data, ...)
                    S.mutLive.spawnGuard = false
                    pk[fk] = nil
                    if okE and typeof(resultE) == "Instance" then
                        -- FVC asli lalu hide mesh (bukan soft shell)
                        S.mutLive.markEclipseLiveHidden(resultE, fruitId)
                        B.stats.fruits += 1
                        return resultE
                    end
                end
                local pvc = getPVC()
                local plant = nil
                if pvc and type(pvc.GetSpawnedPlant) == "function" then
                    pcall(function()
                        plant = pvc:GetSpawnedPlant(userId, plantId)
                    end)
                end
                if typeof(plant) == "Instance" and plant.Parent then
                    -- Shell yang SUDAH ADA: return (isi u3, anti VisualCheck spam).
                    -- Shell BARU: antre. Jangan Instance.new di sini (spike 1800/3s).
                    local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                    local existing = nil
                    if folder then
                        for _, ch in ipairs(folder:GetChildren()) do
                            if ch:IsA("Model")
                                and tostring(ch:GetAttribute("FruitId") or "") == tostring(fruitId) then
                                existing = ch
                                break
                            end
                        end
                    end
                    if existing and existing.Parent then
                        stampFruitDetectAttrs(existing, plantId, fruitId, data, plant)
                        registerFruitShellInFvc(existing, fruitId)
                        bindSoftShellInFvcU3(existing, userId, plantId, fruitId)
                        bindFruitMutationListener(existing)
                        return existing
                    end
                end
                enqueueFruitShell(userId, plantId, fruitId, data)
                return nil
            end
            local ok, result = pcall(orig, self, userId, plantId, fruitId, data, ...)
            if ok then return result end
            return nil
        end
    end

    -- FVC.UpdateFruitMutation cuma nulis attr kalau u3 hit. Soft shell sering miss.
    if type(FVC.UpdateFruitMutation) == "function" and B.fvcBackup.UpdateFruitMutation == nil then
        local origMut = FVC.UpdateFruitMutation
        B.fvcBackup.UpdateFruitMutation = origMut
        FVC.UpdateFruitMutation = function(self, userId, plantId, fruitId, mutName, ...)
            local ok, res = pcall(origMut, self, userId, plantId, fruitId, mutName, ...)
            pcall(S.mutLive.applyLive, userId, plantId, fruitId, mutName)
            if ok then return res end
            return nil
        end
    end

    -- Weather/mutasi: GetFruit(...) sering nil kalau soft shell → fallback shell sendiri
    for k, v in pairs(FVC) do
        if type(v) == "function" and type(k) == "string" and B.fvcBackup[k] == nil then
            local low = string.lower(k)
            local isGet = low:find("get", 1, true) or low:find("find", 1, true)
            local isFruit = low:find("fruit", 1, true)
            if isGet and isFruit
                and not low:find("folder", 1, true)
                and not low:find("data", 1, true)
                and not low:find("spawn", 1, true)
                and not low:find("remove", 1, true)
                and not low:find("destroy", 1, true)
                and not low:find("age", 1, true)
                and not low:find("weight", 1, true)
                and not low:find("growth", 1, true)
            then
                B.fvcBackup[k] = v
                FVC[k] = function(self, ...)
                    local ok, result = pcall(v, self, ...)
                    if ok and typeof(result) == "Instance" and result.Parent then
                        -- Kalau GetFruit balikin instance mati/non-shell, tetap prefer shell live
                        if result:GetAttribute(A.FRUIT_SHELL_ATTR) == true
                            or result:GetAttribute("FruitId") ~= nil then
                            return result
                        end
                    end
                    local args = { ... }
                    local fruitId, plantId = nil, nil
                    -- (plantId, fruitId) / (userId, plantId, fruitId) — fruitId string ATAU number
                    if #args >= 2 then
                        local last = args[#args]
                        if type(last) == "string" or typeof(last) == "number" then
                            fruitId = last
                            local prev = args[#args - 1]
                            if prev ~= nil and prev ~= LP.UserId then
                                plantId = prev
                            elseif #args >= 3 then
                                plantId = args[#args - 1]
                            end
                        end
                    elseif #args == 1 and (type(args[1]) == "string" or typeof(args[1]) == "number") then
                        fruitId = args[1]
                    end
                    if fruitId ~= nil then
                        local shell = lookupOwnFruitShell(fruitId, plantId)
                        if shell then
                            registerFruitShellInFvc(shell, fruitId)
                            return shell
                        end
                    end
                    if ok then return result end
                    return nil
                end
            end
        end
    end

    -- GetSpawnedFruit baca u3 privat — isi ulang dari soft shell hidup
    if type(FVC.GetSpawnedFruit) == "function" and B.fvcBackup.GetSpawnedFruit == nil then
        local origGet = FVC.GetSpawnedFruit
        B.fvcBackup.GetSpawnedFruit = origGet
        pcall(getFvcU3) -- cache upvalue u3 sedini mungkin
        FVC.GetSpawnedFruit = function(self, userId, plantId, fruitId, ...)
            local ok, result = pcall(origGet, self, userId, plantId, fruitId, ...)
            if ok and typeof(result) == "Instance" and result.Parent then
                return result
            end
            if plantId ~= nil and fruitId ~= nil then
                local shell = lookupOwnFruitShell(fruitId, plantId)
                if shell and shell.Parent then
                    bindSoftShellInFvcU3(shell, userId or LP.UserId, plantId, fruitId)
                    registerFruitShellInFvc(shell, fruitId)
                    return shell
                end
            end
            if ok then return result end
            return nil
        end
    end

    FVC.__GAG2RF9 = true
    dlog("patched FVC game-fruit=%s + fruit-lookup→shell u3=%s",
        tostring(useGameManagedFruits()), tostring(type(B.fvcU3) == "table"))
    return true
end

restoreFVC = function()
    local FVC = getFVC()
    if not FVC or not FVC.__GAG2RF9 then
        -- legacy flag
        if FVC and FVC.__GAG2RF5 then
            for k, v in pairs(B.fvcBackup) do
                if v ~= nil then FVC[k] = v end
            end
            FVC.__GAG2RF5 = nil
        end
        table.clear(B.fvcBackup)
        return
    end
    for k, v in pairs(B.fvcBackup) do
        if v ~= nil then FVC[k] = v end
    end
    FVC.__GAG2RF9 = nil
    table.clear(B.fvcBackup)
    B.fvcU3 = nil
    table.clear(S.pendingCollect)
end

local function patchPVC()
    local PVC = getPVC()
    if not PVC or PVC.__GAG2RF9 then return PVC ~= nil end
    table.clear(B.pvcBackup)
    local n = 0
    for k, v in pairs(PVC) do
        if type(v) == "function" and type(k) == "string" then
            local low = string.lower(k)
            if k ~= "GetPlantsFolder" and k ~= "GetSpawnedPlant" and k ~= "GetPlantGrowthData"
                and k ~= "SpawnPlantFromData" and k ~= "RemovePlantById" and k ~= "AddHarvestPrompt"
                and k ~= "AddMissingPrompts" and k ~= "GetSeedData" and k ~= "IsSingleHarvestPlant"
                and not low:find("get", 1, true)
                and (low:find("visual", 1, true) or low:find("render", 1, true)
                    or low:find("refresh", 1, true) or low:find("update", 1, true)
                    or low:find("growthsfx", 1, true) or low:find("age", 1, true)) then
                B.pvcBackup[k] = v
                PVC[k] = function() end
                n += 1
            end
        end
    end
    if type(PVC.AddGrowthSFX) == "function" then
        B.pvcBackup.AddGrowthSFX = PVC.AddGrowthSFX
        PVC.AddGrowthSFX = function() end
        n += 1
    end
    if type(PVC.SpawnPlantFromData) == "function" then
        B.pvcBackup.SpawnPlantFromData = PVC.SpawnPlantFromData
        local orig = B.pvcBackup.SpawnPlantFromData
        PVC.SpawnPlantFromData = function(self, userId, plantId, data, ...)
            local uid = tonumber(userId)
            if CONFIG.blockOtherSpawn and uid ~= nil and uid ~= LP.UserId then
                if S.otherPaused and S.otherPaused() then
                    B.statsBlocked.otherPlantSkip += 1
                    return nil
                end
                -- Jangan skip total: sprinkler other butuh 1 shell/tipe + SeedName.
                local typeName = seedNameFromData(data)
                if not typeName and type(self.GetSeedData) == "function" then
                    pcall(function()
                        typeName = seedNameFromData(self:GetSeedData(data))
                    end)
                end
                local folder = nil
                if type(self.GetPlantsFolder) == "function" then
                    pcall(function() folder = self:GetPlantsFolder(uid) end)
                end
                if typeName and folder and folderHasTypedPlant(folder, typeName) then
                    B.statsBlocked.otherPlantSkip += 1
                    return nil
                end
                local ok, result = pcall(orig, self, userId, plantId, data, ...)
                task.defer(function()
                    local plant = nil
                    if type(self.GetSpawnedPlant) == "function" then
                        pcall(function()
                            plant = self:GetSpawnedPlant(userId, plantId)
                        end)
                    end
                    if typeof(plant) ~= "Instance" or not plant.Parent then return end
                    pcall(function()
                        plant:SetAttribute("UserId", uid)
                        plant:SetAttribute("PlantId", plantId)
                    end)
                    local stamped = stampPlantTypeAttrs(plant, data) or typeName
                    if stamped and folder and folderHasTypedPlant(folder, stamped, plant) then
                        if destroyIfOtherPlant(plant, nil) then
                            B.stats.destroyedPlants += 1
                            B.statsBlocked.otherPlantSkip += 1
                        end
                        return
                    end
                    stripOtherPlantShell(plant, data)
                end)
                if ok then return result end
                return nil
            end
            local ok, result = pcall(orig, self, userId, plantId, data, ...)
            if uid == nil or uid == LP.UserId then
                task.defer(function()
                    local plant = result
                    if typeof(plant) ~= "Instance" or not plant.Parent then
                        plant = nil
                        if type(self.GetSpawnedPlant) == "function" then
                            pcall(function()
                                plant = self:GetSpawnedPlant(userId, plantId)
                            end)
                        end
                    end
                    if typeof(plant) == "Instance" and plant.Parent and S.visualBlockActive
                        and CONFIG.stripOwnVisual then
                        enqueuePlantStrip(plant)
                    end
                end)
            end
            if ok then return result end
            return nil
        end
        n += 1
    end
    PVC.__GAG2RF9 = true
    dlog("patched PVC block-fn=%d", n)
    return true
end

local function restorePVC()
    local PVC = getPVC()
    if not PVC then
        table.clear(B.pvcBackup)
        return
    end
    if PVC.__GAG2RF9 then
        for k, v in pairs(B.pvcBackup) do
            if v ~= nil then PVC[k] = v end
        end
        -- legacy RF5 keys
        for k, v in pairs(PVC) do
            if type(k) == "string" and k:sub(1, 9) == "__GAG2RF5_" then
                PVC[k:sub(10)] = v
                PVC[k] = nil
            end
        end
        PVC.__GAG2RF9 = nil
        PVC.__GAG2RF5 = nil
    elseif PVC.__GAG2RF5 then
        for k, v in pairs(PVC) do
            if type(k) == "string" and k:sub(1, 9) == "__GAG2RF5_" then
                PVC[k:sub(10)] = v
                PVC[k] = nil
            end
        end
        PVC.__GAG2RF5 = nil
    end
    table.clear(B.pvcBackup)
end

startPrevent = function()
    -- Soft shell OFF kalau fruit diurus game (default)
    S.forceSoftFruits = (not useGameManagedFruits()) and (CONFIG.stripOwnVisual == true)
    if not CONFIG.blockVisualInit then
        patchFruitModules()
        for _ = 1, 20 do
            if not S.alive then return end
            if patchFVC() and patchPVC() then break end
            task.wait(0.1)
        end
        S.visualBlockActive = true
        return
    end
    S.visualBlockActive = true
    local pn = patchPlantModules()
    local fn = patchFruitModules()
    dlog("startPrevent plants=%d fruits=%d gameFruit=%s", pn, fn, tostring(useGameManagedFruits()))
    -- PVC/FVC mungkin belom ada saat boot — poll
    task.spawn(function()
        for _ = 1, 40 do
            if not S.alive or not S.visualBlockActive then return end
            local okF = patchFVC()
            local okP = patchPVC()
            if okF and okP then
                dlog("startPrevent PVC/FVC ready")
                return
            end
            task.wait(0.1)
        end
    end)
end

stopPrevent = function()
    S.visualBlockActive = false
    -- jangan matikan S.forceSoftFruits di sini — restore soft masih butuh anti-mesh
    restoreFVC()
    restorePVC()
    restoreFruitModules()
    restorePlantModules()
    dlog("stopPrevent (InitPlant restored) softFruit=%s", tostring(S.forceSoftFruits))
end

local function waitPlantReady(plant, timeoutSec)
    if not plant then return false end
    local t0 = os.clock()
    local lim = timeoutSec or 2.5
    while plant.Parent and (os.clock() - t0) < lim do
        if plant:HasTag("InitializationComplete") or plant:GetAttribute("PlantGrowthReady") == true then
            return true
        end
        if plant:GetAttribute("PlantId") ~= nil and plant:GetAttribute("SeedName") ~= nil then
            -- attrs sudah ada; InitPlant asli kadang lambat — cukup untuk detect
            if (os.clock() - t0) >= 0.35 then
                return true
            end
        end
        task.wait()
    end
    return plant.Parent ~= nil
end

local function gardenEntryList(garden)
    local list = {}
    for plantId, data in pairs(garden) do
        if type(data) == "table" then
            list[#list + 1] = { id = plantId, data = data }
        end
    end
    table.sort(list, function(a, b)
        return tostring(a.id) < tostring(b.id)
    end)
    return list
end

local function resolvePlantData(sync, plantId, fallback)
    local data = fallback
    if sync and type(sync.GetPlant) == "function" then
        pcall(function()
            local d = sync:GetPlant(LP.UserId, plantId)
            if type(d) == "table" then
                data = d
            end
        end)
    end
    return data
end

-- plantData.Fruits → list { id, data } (map atau array)
-- Single-harvest (IsSingleHarvest saja): Fruits kosong → 1 entry FruitId=""
-- (forward-declared — dipanggil dari S.mutLive.refreshTopHeavy di atas)
fruitEntriesFromPlantData = function(plantData, plant, plantId)
    local out = {}
    if type(plantData) ~= "table" then return out end
    local fruits = plantData.Fruits or plantData.fruits or plantData.Fruit

    local function push(fruitId, data)
        if fruitId == nil then return end
        local id = fruitId
        local d = data
        if type(d) ~= "table" then
            d = { FruitId = id }
        else
            id = d.FruitId or d.fruitId or d.Id or d.id or d.UUID or d.Uuid or fruitId
        end
        if id == nil or tostring(id) == "" then return end
        out[#out + 1] = { id = id, data = d }
    end

    if type(fruits) == "table" then
        -- JANGAN pakai index array sebagai FruitId (bikin shell palsu → LIVE > MaxFruits)
        if #fruits > 0 then
            for i = 1, #fruits do
                local d = fruits[i]
                if type(d) == "table" then
                    local fid = d.FruitId or d.fruitId or d.Id or d.id or d.UUID or d.Uuid
                    if fid ~= nil then
                        push(fid, d)
                    end
                elseif d ~= nil then
                    -- Array UUID string (sama liveFruitIdSet) — jangan skip → 0 shell
                    push(d, { FruitId = d })
                end
            end
        else
            for fruitId, d in pairs(fruits) do
                if type(d) == "table" then
                    push(d.FruitId or d.fruitId or d.Id or d.id or d.UUID or d.Uuid or fruitId, d)
                elseif d == true or type(d) == "string" or type(d) == "number" then
                    push(fruitId, { FruitId = fruitId })
                end
            end
        end
    end

    -- Hanya IsSingleHarvest resmi — jangan heuristik Age (itu bikin match palsu)
    if #out == 0 and plantIsSingleHarvest(plantData, plant) then
        out[1] = { id = "", data = plantData }
    end
    return out
end

-- Soft default: shell UUID only, batch kecil (anti freeze). FullVisual: FVC (berat, opt-in).
local function spawnFruitsForPlant(fvc, plant, plantId, plantData, opts)
    opts = type(opts) == "table" and opts or {}
    if typeof(plant) ~= "Instance" or not plant.Parent then return 0 end
    local fullVisual = opts.fullVisual == true
    if CONFIG.ownNoFruitShells ~= false and (S.running or S.alive) and not fullVisual then
        ensureFruitSpawnLocations(plant)
        local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
        if ff then
            for _, ch in ipairs(ff:GetChildren()) do
                if ch:GetAttribute("_GAG2KeepVisual") ~= true then
                    pcall(function() ch:Destroy() end)
                end
            end
        end
        return 0
    end
    local entries = fruitEntriesFromPlantData(plantData, plant, plantId)
    if #entries == 0 then return 0 end

    local fruitBatch = math.max(1, math.floor(tonumber(opts.fruitBatchSize) or CONFIG.restoreFruitBatchSize or 3))
    local fruitDelay = math.max(0, tonumber(opts.fruitBatchDelay) or CONFIG.restoreFruitBatchDelay or 0.12)

    local n = 0
    local sinceWait = 0
    for i = 1, #entries do
        local e = entries[i]
        if isPendingCollect(plantId, e.id, LP.UserId) then
            continue
        end

        pcall(function()
            plant:AddTag("InitializationComplete")
            plant:SetAttribute("PlantGrowthReady", true)
        end)
        ensureFruitSpawnLocations(plant)

        local plantLevel = tostring(e.id or "") == ""
        -- Soft shell cuma saat Remove Garden ON. OFF/full → FVC game (HarvestPrompt asli).
        local preferGame = fullVisual
            or useGameManagedFruits()
            or not (S.running == true or S.alive == true)
        if (not plantLevel) and preferGame
            and fvc and type(fvc.SpawnFruitFromData) == "function" then
            -- Game spawn / full visual — AutoCollect pakai prompt game
            local ok = pcall(function()
                fvc:SpawnFruitFromData(LP.UserId, plantId, e.id, e.data)
            end)
            if ok then
                n += 1
                B.stats.fruits += 1
                if not fullVisual and CONFIG.stripOwnVisual and (S.running or S.alive) then
                    -- strip sudah di-hook SpawnFruitFromData / InitFruit
                end
            elseif S.running or S.alive then
                local _, created = ensureDetectFruitShell(plant, plantId, e.id, e.data)
                if created then n += 1; B.stats.fruits += 1 end
            end
        elseif S.running or S.alive then
            -- Soft shell (UUID buah ATAU single-harvest FruitId="") — hanya saat ON
            local _, created = ensureDetectFruitShell(plant, plantId, e.id, e.data)
            if created then
                n += 1
                B.stats.fruits += 1
            end
        end

        sinceWait += 1
        if sinceWait >= fruitBatch then
            sinceWait = 0
            if fruitDelay > 0 then
                task.wait(fruitDelay)
            else
                task.wait()
            end
        end
    end
    return n
end

local function respawnMissingOwnFruits(opts)
    opts = type(opts) == "table" and opts or {}
    local sync = getGardenSync()
    local fvc = getFVC()
    local pvc = getPVC()
    if not sync or type(sync.GetGarden) ~= "function" then return 0 end

    local garden = nil
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then return 0 end

    local rehide = opts.rehide
    local fullVisual = opts.fullVisual == true or CONFIG.restoreFullVisual == true
    if rehide == nil then
        rehide = (CONFIG.restoreRehide ~= false) and not fullVisual
    end

    local total = 0
    local list = gardenEntryList(garden)
    for i = 1, #list do
        local entry = list[i]
        local plant = nil
        if pvc and type(pvc.GetSpawnedPlant) == "function" then
            pcall(function()
                plant = pvc:GetSpawnedPlant(LP.UserId, entry.id)
            end)
        end
        if typeof(plant) == "Instance" and plant.Parent then
            local data = resolvePlantData(sync, entry.id, entry.data)
            -- inject PlantName ke tiap fruit data (FVC / CorePartName)
            if type(data) == "table" and data.PlantName then
                local fruits = data.Fruits or data.fruits
                if type(fruits) == "table" then
                    for _, fd in pairs(fruits) do
                        if type(fd) == "table" and fd.PlantName == nil then
                            fd.PlantName = data.PlantName
                        end
                    end
                end
            end
            total += spawnFruitsForPlant(fvc, plant, entry.id, data, {
                rehide = rehide == true,
                fullVisual = fullVisual,
            })
        end
        if i % 10 == 0 then sliceYield() end
    end
    if total > 0 then
        dlog("respawnMissingOwnFruits count=%d rehide=%s", total, tostring(rehide))
    end
    return total
end

-- Hapus shell → spawn ulang A.BATCH (pelan). rehide = strip mesh setelah tiap batch.
local function rebuildOwnGardenVisuals(opts)
    opts = type(opts) == "table" and opts or {}
    local sync = getGardenSync()
    local pvc = getPVC()
    local fvc = getFVC()
    if not sync or not pvc then return 0 end
    if type(sync.GetGarden) ~= "function" or type(pvc.SpawnPlantFromData) ~= "function" then
        return 0
    end
    local garden = nil
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then return 0 end

    local batchSize = math.max(1, math.floor(tonumber(opts.batchSize) or CONFIG.restoreBatchSize or 6))
    local batchDelay = math.max(0, tonumber(opts.batchDelay) or CONFIG.restoreBatchDelay or 0.45)
    local fullVisual = opts.fullVisual == true or CONFIG.restoreFullVisual == true
    local rehide = opts.rehide
    if rehide == nil then
        rehide = (CONFIG.restoreRehide ~= false) and not fullVisual
    end
    if fullVisual then rehide = false end

    local list = gardenEntryList(garden)
    dlog("rebuild gradual total=%d batch=%d delay=%.2f rehide=%s",
        #list, batchSize, batchDelay, tostring(rehide))

    local removed = 0
    for i = 1, #list do
        if type(pvc.RemovePlantById) == "function" then
            local ok = pcall(function()
                pvc:RemovePlantById(LP.UserId, list[i].id)
            end)
            if ok then removed += 1 end
        end
        -- yield sering biar gak freeze 1 frame 800 Destroy
        if i % 5 == 0 then
            task.wait()
        end
    end
    dlog("rebuild: removed shells=%d", removed)

    requestGardensFire(true)
    task.wait(0.15)
    reconcileLocalGarden()
    task.wait(0.2)

    -- FVC kadang belom ready pas Stop → tunggu sebentar
    if not fvc then
        for _ = 1, 30 do
            fvc = getFVC()
            if fvc and type(fvc.SpawnFruitFromData) == "function" then break end
            task.wait(0.1)
        end
    end

    -- refresh garden data setelah sync (Fruits sering lengkap di sini)
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) == "table" then
        list = gardenEntryList(garden)
    end

    local spawned = 0
    local fruitsSpawned = 0
    local total = #list
    for i = 1, total, batchSize do
        local last = math.min(i + batchSize - 1, total)
        for j = i, last do
            local entry = list[j]
            local plantData = resolvePlantData(sync, entry.id, entry.data)
            local existing = nil
            if type(pvc.GetSpawnedPlant) == "function" then
                pcall(function()
                    existing = pvc:GetSpawnedPlant(LP.UserId, entry.id)
                end)
            end
            local need = (not existing) or (typeof(existing) == "Instance" and not existing.Parent)
            if need then
                local ok = pcall(function()
                    pvc:SpawnPlantFromData(LP.UserId, entry.id, plantData)
                end)
                if ok then
                    spawned += 1
                    B.stats.restored += 1
                end
            end
            local plant = nil
            if type(pvc.GetSpawnedPlant) == "function" then
                pcall(function()
                    plant = pvc:GetSpawnedPlant(LP.UserId, entry.id)
                end)
            end
            if typeof(plant) == "Instance" then
                waitPlantReady(plant, 2.0)
                -- plant shell ≠ fruit: shell UUID (soft) / FVC (full)
                if not fvc then fvc = getFVC() end
                fruitsSpawned += spawnFruitsForPlant(fvc, plant, entry.id, plantData, {
                    fullVisual = fullVisual,
                    fruitBatchSize = CONFIG.restoreFruitBatchSize,
                    fruitBatchDelay = CONFIG.restoreFruitBatchDelay,
                })
                if rehide then
                    stripPlantKeepDetect(plant)
                end
            end
            sliceYield()
        end
        dlog("rebuild batch %d-%d / %d plants=%d fruits=%d", i, last, total, spawned, fruitsSpawned)
        if last < total and batchDelay > 0 then
            task.wait(batchDelay)
        end
    end

    dlog("rebuild DONE plants=%d fruits=%d rehide=%s fruitBatch=%d",
        spawned, fruitsSpawned, tostring(rehide), tonumber(CONFIG.restoreFruitBatchSize) or 3)
    return spawned + fruitsSpawned
end

restoreGardenFromData = function(reason, opts)
    opts = type(opts) == "table" and opts or {}
    local t0 = os.clock()
    local fullVisual = opts.fullVisual == true or CONFIG.restoreFullVisual == true
    -- Soft shell + re-patch FVC HANYA kalau Remove Garden masih ON.
    -- Stop/OFF + soft: FVC tetap asli — kalau patch lagi, soft shell dibuat lalu
    -- AutoCollect._purgeStaleSoftShells / skip shell → Match/Skipped/Watering=0.
    local softOk = (not fullVisual) and (S.running == true or S.alive == true)
    S.forceSoftFruits = softOk
    stopPrevent()
    if softOk then
        pcall(patchFVC)
    end
    local cleared = restoreOwnPlants()
    local rebuilt = rebuildOwnGardenVisuals(opts)
    local fruits = respawnMissingOwnFruits(opts)
    if softOk then
        S.forceSoftFruits = CONFIG.stripOwnVisual == true and (S.running == true or S.alive == true)
    else
        S.forceSoftFruits = false
    end
    dlog("restoreGardenFromData reason=%s cleared=%d rebuilt=%d fruitsMiss=%d softFruit=%s full=%s ms=%.0f",
        tostring(reason), cleared or 0, rebuilt or 0, fruits or 0,
        tostring(S.forceSoftFruits), tostring(fullVisual), (os.clock() - t0) * 1000)
    return (cleared or 0) + (rebuilt or 0) + (fruits or 0)
end

restoreAfterGardenReady = function(reason, opts)
    opts = type(opts) == "table" and opts or {}
    S.restoreGen += 1
    local gen = S.restoreGen
    task.spawn(function()
        waitGardenSpawnComplete(90)
        if gen ~= S.restoreGen then return end
        restoreGardenFromData(reason, opts)
        dlog("restore pass1 reason=%s", tostring(reason))
        local rehide = opts.rehide
        if rehide == nil then
            rehide = (CONFIG.restoreRehide ~= false) and not (opts.fullVisual or CONFIG.restoreFullVisual)
        end
        local wantFull = opts.fullVisual == true or CONFIG.restoreFullVisual == true
        for _, delaySec in ipairs({ 1.2, 2.8 }) do
            task.wait(delaySec)
            if gen ~= S.restoreGen then return end
            reconcileLocalGarden()
            -- settle ringan: cuma isi fruit yang masih kosong (sudah di-throttle)
            respawnMissingOwnFruits({
                rehide = rehide == true,
                fullVisual = wantFull,
            })
            if not rehide then
                respawnMissingOwnPlants()
            end
            dlog("restore settle +%.1fs reason=%s rehide=%s", delaySec, tostring(reason), tostring(rehide))
        end
        -- OFF/full: pastikan ripe punya HarvestPrompt (sumber angka AC/Watering/Sprinkler)
        if wantFull and not S.running and gen == S.restoreGen then
            task.wait(0.6)
            if gen ~= S.restoreGen or S.running then return end
            local FVC = getFVC()
            if FVC and type(FVC.AddMissingPrompts) == "function" then
                pcall(function() FVC:AddMissingPrompts() end)
                dlog("restore AddMissingPrompts reason=%s", tostring(reason))
            end
        end
    end)
    return true
end

----------------------------------------------------------------
-- Own strip
----------------------------------------------------------------
-- opts.fast=true: strip lebih cepat setelah loading (budget longgar, yield jarang)
-- opts.skipDone=true: lewati plant yang sudah A.TREE_ATTR (gelombang progresif)
local function stripOwnPlot(plot, opts)
    if not plot or not CONFIG.stripOwnVisual then return end
    opts = type(opts) == "table" and opts or {}
    local fast = opts.fast == true
    local skipDone = opts.skipDone == true
    local useQueue = opts.useQueue == true
    local maxPerWave = tonumber(opts.maxPerWave)
    local budget = fast and 0.010 or A.STRIP_BUDGET
    local yieldEvery = fast and 10 or 3
    S.yieldT = os.clock()
    S.stripBudgetT = os.clock()
    local t0 = os.clock()
    local folders = listPlantFolders(plot, LP.UserId)
    -- Hitung kasar buah: kalau sudah penuh (ON setelah load) pakai light strip
    local fruitGuess = 0
    for _, folder in ipairs(folders) do
        for _, plant in ipairs(folder:GetChildren()) do
            if plant:IsA("Model") then
                local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                if ff then fruitGuess += #ff:GetChildren() end
            end
        end
        if fruitGuess > 250 then break end
    end
    local light = fruitGuess >= 200 or isGardenLoadingNow()
    if light then
        dlog("stashOwn LIGHT mode (fruits≈%d+) — yield agresif, skip sync stamp", fruitGuess)
    end
    local plants, skipped = 0, 0
    for _, folder in ipairs(folders) do
        local kids = folder:GetChildren()
        dlog("stashOwn %s count=%d fast=%s queue=%s max=%s",
            folder:GetFullName(), #kids, tostring(fast), tostring(useQueue), tostring(maxPerWave))
        for i = 1, #kids do
            if not S.alive then return end
            if maxPerWave and plants >= maxPerWave then
                dlog("stashOwn wave cap plants=%d skip=%d ms=%.0f", plants, skipped, (os.clock() - t0) * 1000)
                return
            end
            local plant = kids[i]
            if isSprinkler(plant) then continue end
            if skipDone and plant:GetAttribute(A.TREE_ATTR) == true then
                skipped += 1
                continue
            end
            if useQueue then
                enqueuePlantStrip(plant)
                plants += 1
            elseif CONFIG.blockVisualInit then
                stripPlantKeepDetect(plant, { light = light })
                pcall(function() plant:SetAttribute(A.TREE_ATTR, true) end)
                plants += 1
            else
                hidePlantTree(plant)
                plants += 1
            end
            if not useQueue then
                if (os.clock() - S.stripBudgetT) >= budget then
                    task.wait()
                    S.stripBudgetT = os.clock()
                end
                if plants % yieldEvery == 0 then
                    task.wait()
                end
            elseif plants % 20 == 0 then
                task.wait()
            end
        end
    end
    dlog("stashOwn DONE plants=%d skip=%d stashed=%d fruits=%d light=%s fast=%s ms=%.0f",
        plants, skipped, B.stats.stashed, B.stats.fruits, tostring(light), tostring(fast),
        (os.clock() - t0) * 1000)
end

-- forward: dipakai ChildAdded other sebelum definisi penuh di bawah
local scheduleStealKeepTrim

-- kg untuk rank steal keep (reuse mutLive.fruitKg kalau ada)
local function stealFruitKg(fruit)
    if typeof(fruit) ~= "Instance" then return 0 end
    local ml = S.mutLive
    if type(ml) == "table" and type(ml.fruitKg) == "function" then
        local ok, kg = pcall(ml.fruitKg, nil, fruit)
        if ok and type(kg) == "number" and kg > 0 then
            return kg
        end
    end
    local bw = tonumber(fruit:GetAttribute("BaseWeight"))
    local sm = tonumber(fruit:GetAttribute("SizeMulti"))
    local og = tonumber(fruit:GetAttribute("OvertimeGrowth")) or 1
    if bw and bw > 0 and sm and sm > 0 then
        return bw * sm * og
    end
    local w = tonumber(fruit:GetAttribute("Weight"))
        or tonumber(fruit:GetAttribute("DisplayWeight"))
        or tonumber(fruit:GetAttribute("HarvestWeight"))
    if w and bw and bw > 0 and math.abs(w - bw) <= 1e-3 then
        w = nil
    end
    if w and w > 0 then return w end
    local FSV = rawget(G, "FruitSellValue") or rawget(_G, "FruitSellValue")
    if type(FSV) == "table" and type(FSV.resolveWeight) == "function" then
        local ok, val = pcall(FSV.resolveWeight, FSV, fruit)
        if not ok then ok, val = pcall(FSV.resolveWeight, fruit) end
        if ok and type(val) == "number" and val > 0 then return val end
    end
    return 0
end

local function stealKeepLimit()
    local n = tonumber(CONFIG.stealKeepFruits)
    if n == nil then n = 50 end
    if n < 0 then n = 0 end
    if n > 2000 then n = 2000 end
    return math.floor(n)
end

-- Baca filter Auto Steal (empty plant/mut + min 0 = any → top kg)
local function stealKeepFilter()
    local st = rawget(_G, "__GAG2_AUTO_STEAL") or G.__GAG2_AUTO_STEAL
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local steal = MAIN and MAIN.auto and MAIN.auto.steal
    local src = {}
    if type(steal) == "table" then
        for k, v in pairs(steal) do src[k] = v end
    end
    if type(st) == "table" then
        for k, v in pairs(st) do
            if v ~= nil then src[k] = v end
        end
    end

    local function toSet(arr)
        local set, n = {}, 0
        if type(arr) ~= "table" then return set, 0 end
        if arr[1] ~= nil then
            for _, v in ipairs(arr) do
                local k = tostring(v or "")
                if k ~= "" and not set[k] then
                    set[k] = true
                    n += 1
                end
            end
            return set, n
        end
        for k, v in pairs(arr) do
            if v == true then
                local key = tostring(k)
                if key ~= "" and not set[key] then
                    set[key] = true
                    n += 1
                end
            end
        end
        return set, n
    end

    local plantSet, plantN = toSet(src.plants)
    local mutSet, mutN = toSet(src.mutations)
    local minKg = tonumber(src.min_kg) or 0
    local minPrice = tonumber(src.min_price) or 0
    if minKg < 0 then minKg = 0 end
    if minPrice < 0 then minPrice = 0 end
    local any = (plantN == 0 and mutN == 0 and minKg <= 0 and minPrice <= 0)
    return {
        any = any,
        plants = plantSet,
        plantN = plantN,
        mutations = mutSet,
        mutN = mutN,
        min_kg = minKg,
        min_price = minPrice,
    }
end

local function stealNameInSet(set, name)
    if not next(set) then return true end
    name = tostring(name or "")
    if name == "" then return false end
    if set[name] then return true end
    local low = string.lower(name)
    for k in pairs(set) do
        if string.lower(tostring(k)) == low then return true end
    end
    return false
end

local function stealMutInSet(set, mut)
    if not next(set) then return true end
    mut = tostring(mut or "")
    if mut == "" then
        return set["No Mutation"] == true or set["None"] == true
    end
    if set[mut] then return true end
    local low = string.lower(mut)
    for k in pairs(set) do
        if string.lower(tostring(k)) == low then return true end
    end
    return false
end

local function stealFruitPrice(fruit)
    local FSV = rawget(G, "FruitSellValue") or rawget(_G, "FruitSellValue")
    if type(FSV) == "table" and type(FSV.fromFruit) == "function" then
        local ok, v = pcall(FSV.fromFruit, fruit)
        if ok and type(v) == "number" and v > 0 then return v end
    end
    return tonumber(fruit:GetAttribute("SellPrice"))
        or tonumber(fruit:GetAttribute("Price"))
        or 0
end

local function stealFruitMatchesFilter(fruit, plant, filt)
    if not filt or filt.any == true then return true end
    local seed = tostring(
        fruit:GetAttribute("SeedName")
            or fruit:GetAttribute("CorePartName")
            or (plant and (plant:GetAttribute("SeedName") or plant:GetAttribute("CorePartName")))
            or ""
    )
    if not stealNameInSet(filt.plants, seed) then return false end

    local mut = tostring(fruit:GetAttribute("Mutation") or "")
    if mut == "" and plant then
        mut = tostring(plant:GetAttribute("Mutation") or "")
    end
    if not stealMutInSet(filt.mutations, mut) then return false end

    local kg = stealFruitKg(fruit)
    if filt.min_kg > 0 and kg < filt.min_kg then return false end
    if filt.min_price > 0 and stealFruitPrice(fruit) < filt.min_price then return false end
    return true
end

-- Steal ON: per other plot — filter Auto Steal; any → top-N kg; ada filter → keep yang match (cap N, rank kg)
local function clearOtherPlotKeepTopFruits(plot)
    if not plot or not CONFIG.clearOtherPlants or not isConfirmedOtherPlot(plot) then return end
    local ownerId = plotOwnerUserId(plot)
    if ownerId == nil or ownerId == LP.UserId then return end
    if isOwnPlot(plot) then return end
    S.yieldT = os.clock()
    local t0 = os.clock()
    local limit = stealKeepLimit()
    local filt = stealKeepFilter()
    local folders = listPlantFolders(plot, ownerId)
    local ranked = {}
    local plantsIn, fruitsIn, matched = 0, 0, 0

    local function consider(fruit, plant)
        if not fruit or not fruit.Parent then return end
        fruitsIn += 1
        if not stealFruitMatchesFilter(fruit, plant, filt) then return end
        matched += 1
        ranked[#ranked + 1] = {
            fruit = fruit,
            plant = plant,
            kg = stealFruitKg(fruit),
            pid = tostring(plant and plant:GetAttribute("PlantId") or plant and plant.Name or ""),
            fid = tostring(fruit:GetAttribute("FruitId") or ""),
        }
    end

    for _, folder in ipairs(folders) do
        for _, plant in ipairs(folder:GetChildren()) do
            if not plant:IsA("Model") or isSprinkler(plant) then continue end
            plantsIn += 1
            if ownerId and plant:GetAttribute("UserId") == nil then
                pcall(function() plant:SetAttribute("UserId", ownerId) end)
            end
            local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if ff then
                for _, fruit in ipairs(ff:GetChildren()) do
                    if fruit:IsA("Model") and fruit:GetAttribute("FruitId") ~= nil then
                        consider(fruit, plant)
                    end
                end
            end
            if plant:GetAttribute("FruitId") ~= nil then
                consider(plant, plant)
            end
            sliceYield()
        end
    end

    -- Player baru: plot/plant sudah ada tapi buah belom replicate.
    -- Jangan wipe (keep=0 → destroy semua). Tunggu spawn, trim belakangan.
    if fruitsIn <= 0 then
        if plantsIn > 0 then
            dlog("stealKeep DEFER %s plants=%d fruits=0 (wait spawn)", plot.Name, plantsIn)
            scheduleStealKeepTrim(plot)
        else
            dlog("stealKeep SKIP %s empty plot", plot.Name)
        end
        return
    end

    -- Filter Auto Steal gak match apa-apa → jangan kosongin kebun (biarkan, trim lagi nanti)
    if matched <= 0 then
        dlog("stealKeep DEFER %s fruits=%d match=0 (filter miss)", plot.Name, fruitsIn)
        scheduleStealKeepTrim(plot)
        return
    end

    -- Keep Fruits 0 = tampilkan semua (jangan wipe). Own garden tidak tersentuh.
    if limit <= 0 then
        dlog("stealKeep %s keepALL fruitsIn=%d match=%d ms=%.0f",
            plot.Name, fruitsIn, matched, (os.clock() - t0) * 1000)
        return
    end

    table.sort(ranked, function(a, b)
        if a.kg ~= b.kg then return a.kg > b.kg end
        if a.pid ~= b.pid then return a.pid < b.pid end
        return a.fid < b.fid
    end)

    local keepFruit = {}
    local keepPlant = {}
    local kept = 0
    for i = 1, #ranked do
        if kept >= limit then break end
        local e = ranked[i]
        if e.fruit and e.fruit.Parent and not keepFruit[e.fruit] then
            keepFruit[e.fruit] = true
            if e.plant then keepPlant[e.plant] = true end
            kept += 1
        end
    end

    local destroyed = 0
    for _, folder in ipairs(folders) do
        local kids = folder:GetChildren()
        for i = 1, #kids do
            local plant = kids[i]
            if isSprinkler(plant) then continue end
            if not plant:IsA("Model") then
                if destroyIfOtherPlant(plant, plot) then
                    destroyed += 1
                    B.stats.destroyedPlants += 1
                end
                continue
            end
            if keepPlant[plant] then
                local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                if ff then
                    for _, fruit in ipairs(ff:GetChildren()) do
                        if fruit:IsA("Model") and fruit:GetAttribute("FruitId") ~= nil
                            and not keepFruit[fruit] then
                            if destroyIfOtherPlant(fruit, plot) then
                                destroyed += 1
                                B.stats.destroyedPlants += 1
                            end
                        end
                    end
                end
            else
                if destroyIfOtherPlant(plant, plot) then
                    destroyed += 1
                    B.stats.destroyedPlants += 1
                end
            end
            if i % A.BATCH == 0 then sliceYield() end
        end
    end

    dlog("stealKeep %s mode=%s fruitsIn=%d match=%d keep=%d/%d destroyed=%d ms=%.0f",
        plot.Name, filt.any and "any_kg" or "filter", fruitsIn, matched, kept, limit, destroyed,
        (os.clock() - t0) * 1000)
end

scheduleStealKeepTrim = function(plot)
    if not plot then return end
    if type(S.stealKeepPending) ~= "table" then
        S.stealKeepPending = setmetatable({}, { __mode = "k" })
    end
    if S.stealKeepPending[plot] then return end
    S.stealKeepPending[plot] = true
    task.spawn(function()
        -- Retry: buah player baru sering belom ada di 0.2s pertama
        local delays = { 0.35, 1.0, 2.0, 4.0 }
        for i = 1, #delays do
            task.wait(delays[i])
            if not S.alive or not stealKeepOn() then
                S.stealKeepPending[plot] = nil
                return
            end
            if not isConfirmedOtherPlot(plot) then
                S.stealKeepPending[plot] = nil
                return
            end
            clearOtherPlotKeepTopFruits(plot)
            -- Kalau sudah ada buah yang di-trim, stop retry
            local ownerId = plotOwnerUserId(plot)
            local hasFruit = false
            for _, folder in ipairs(listPlantFolders(plot, ownerId)) do
                for _, plant in ipairs(folder:GetChildren()) do
                    if not plant:IsA("Model") then continue end
                    local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
                    if ff and #ff:GetChildren() > 0 then
                        hasFruit = true
                        break
                    end
                    if plant:GetAttribute("FruitId") ~= nil then
                        hasFruit = true
                        break
                    end
                end
                if hasFruit then break end
            end
            if hasFruit then break end
        end
        S.stealKeepPending[plot] = nil
    end)
end

local function bindFolderLive(folder, isOther, plot)
    if not folder or B.folderBound[folder] then return end
    B.folderBound[folder] = true
    local bucket = isOther and B.otherConns or B.plotConns

    table.insert(bucket, folder.ChildAdded:Connect(function(ch)
        if not S.alive then return end
        if isOther then
            if not CONFIG.clearOtherPlants then return end
            if S.otherPaused and S.otherPaused() then
                task.defer(function()
                    task.wait(0.05)
                    if not ch.Parent or not isConfirmedOtherPlot(plot) then return end
                    if isOwnPlantContext(ch) or isSprinkler(ch) then return end
                    if destroyIfOtherPlant(ch, plot) then
                        B.stats.destroyedPlants += 1
                    end
                end)
                return
            end
            -- Steal compat: re-trim top-N kg (bukan keep-1-tipe)
            if stealKeepOn() then
                scheduleStealKeepTrim(plot)
                return
            end
            task.defer(function()
                task.wait(0.1)
                if not ch.Parent or not isConfirmedOtherPlot(plot) then return end
                if isOwnPlantContext(ch) then return end
                if isSprinkler(ch) then return end
                if not ch:IsA("Model") then
                    destroyIfOtherPlant(ch, plot)
                    return
                end
                local ownerId = plotOwnerUserId(plot)
                if ownerId and ownerId ~= LP.UserId and ch:GetAttribute("UserId") == nil then
                    pcall(function() ch:SetAttribute("UserId", ownerId) end)
                end
                -- tunggu SeedName sebentar (InitPlant kadang lambat)
                for _ = 1, 12 do
                    if stampPlantTypeAttrs(ch) or discoverPlantTypeName(ch) then break end
                    task.wait(0.05)
                    if not ch.Parent then return end
                end
                if not isConfirmedOtherPlot(plot) or isOwnPlantContext(ch) then return end
                local key = plantTypeKey(ch)
                if key ~= "_pending" and folderHasTypedPlant(folder, key, ch) then
                    if destroyIfOtherPlant(ch, plot) then
                        B.stats.destroyedPlants += 1
                    end
                    return
                end
                if key == "_pending" then
                    for _, sib in ipairs(folder:GetChildren()) do
                        if sib ~= ch and sib:IsA("Model") and not isSprinkler(sib)
                            and plantTypeKey(sib) == "_pending" then
                            if destroyIfOtherPlant(ch, plot) then
                                B.stats.destroyedPlants += 1
                            end
                            return
                        end
                    end
                end
                stripOtherPlantShell(ch)
            end)
        else
            if not CONFIG.stripOwnVisual then return end
            task.defer(function()
                if ch.Parent and not isSprinkler(ch) then
                    enqueuePlantStrip(ch)
                end
            end)
        end
    end))

    if isOther then
        -- buah baru di bawah plant keep → re-trim top-N
        table.insert(bucket, folder.DescendantAdded:Connect(function(d)
            if not S.alive or not stealKeepOn() then return end
            if d:IsA("Model") and d:GetAttribute("FruitId") ~= nil then
                scheduleStealKeepTrim(plot)
            end
        end))
    end

    if not isOther then
        table.insert(bucket, folder.DescendantAdded:Connect(function(d)
            if not S.alive or not CONFIG.stripOwnVisual then return end
            if d:IsA("ProximityPrompt") then
                tunePrompt(d)
                return
            end
            -- ESP Billboard GAG2 — biarkan (stripHeavyVisual juga keep via isDetectKeepInstance)
            if d:IsA("BillboardGui") and isDetectKeepInstance(d) then
                return
            end
            -- Base / spawn locator / detect-keep: jangan di-stash (GardenSync butuh Base)
            if isDetectKeepInstance(d) then return end
            -- jangan re-stash yang sudah di dalam _GAG2Stash
            local p = d.Parent
            for _ = 1, 8 do
                if not p then break end
                if p.Name == A.PLANT_STASH or p.Name == A.STASH_NAME then return end
                p = p.Parent
            end
            if underFruitsFolder(d) then
                -- Pending spawn: jangan kill mesh mid-FVC. Setelah live → strip OK (hide).
                if S.mutLive.spawnGuard == true then return end
                local keepAnc = d
                local pending = S.mutLive.pendingKeep
                for _ = 1, 10 do
                    if not keepAnc then break end
                    if keepAnc:IsA("Model") then
                        if keepAnc:GetAttribute("_GAG2KeepVisual") == true then
                            return
                        end
                        if keepAnc:GetAttribute("_GAG2EclipseLive") == true then
                            return
                        end
                        local fid = keepAnc:GetAttribute("FruitId")
                        if fid ~= nil and type(pending) == "table" then
                            local pid = keepAnc:GetAttribute("PlantId")
                            local fk = S.mutLive.fruitKey and S.mutLive.fruitKey(pid, fid)
                            if (fk and pending[fk] == true) or pending[tostring(fid)] == true then
                                return
                            end
                        end
                    end
                    keepAnc = keepAnc.Parent
                end
                -- Soft: DESTROY mesh buah baru (LTM saja sering kebuka lagi → kristal MegaBloom kelihatan)
                if d:IsA("BasePart") or d:IsA("MeshPart") then
                    if isDetectKeepInstance(d) then return end
                    local nm = d.Name
                    if nm == "HarvestPart" or nm == "ShellBody" or nm == "CollectProxy" then
                        pcall(function()
                            d.Transparency = 1
                            d.LocalTransparencyModifier = 1
                            d.CastShadow = false
                        end)
                    else
                        pcall(function() d:Destroy() end)
                    end
                elseif d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail")
                    or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles")
                    or d:IsA("SpecialMesh") or d:IsA("Decal") or d:IsA("Texture") then
                    pcall(function() d:Destroy() end)
                elseif d:IsA("Model") and isFruitModel(d) then
                    task.defer(function()
                        if not d.Parent then return end
                        if d:GetAttribute("_GAG2KeepVisual") == true then return end
                        bindFruitMutationListener(d)
                        stampMutationAttrs(d, nil)
                        if d:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                            hideFruit(d)
                        else
                            stripHeavyVisual(d)
                        end
                    end)
                end
                return
            end
            -- Buah di luar folder Fruits (kadang MegaBloom)
            if d:IsA("Model") and isFruitModel(d) then
                task.defer(function()
                    if not d.Parent then return end
                    if d:GetAttribute("_GAG2KeepVisual") == true then return end
                    bindFruitMutationListener(d)
                    stampMutationAttrs(d, nil)
                    if d:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                        hideFruit(d)
                    else
                        stripHeavyVisual(d)
                    end
                end)
                return
            end
            -- Visual pohon baru → DESTROY mesh (stash masih bisa kelihatan / di-restore game)
            local plant = d:FindFirstAncestorOfClass("Model")
            while plant and plant.Parent and plant.Parent.Name ~= "Plants"
                and plant.Parent.Name ~= "Plants_Physical"
                and plant.Parent.Name ~= "PhysicalPlants" do
                local up = plant.Parent
                if up:IsA("Model") and up:GetAttribute("PlantId") ~= nil then
                    plant = up
                else
                    break
                end
            end
            if plant and not isFruitModel(plant) then
                if d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail")
                    or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles")
                    or d:IsA("SpecialMesh") or d:IsA("Decal") or d:IsA("Texture")
                    or d:IsA("Highlight") then
                    pcall(function() d:Destroy() end)
                    return
                end
                if (d:IsA("BasePart") or d:IsA("MeshPart")) and not isDetectKeepInstance(d) then
                    pcall(function() d:Destroy() end)
                    return
                end
                local top = d
                while top.Parent and top.Parent ~= plant do
                    top = top.Parent
                end
                if top.Parent == plant and not isDetectKeepInstance(top) then
                    if CONFIG.blockVisualInit then
                        if top:IsA("Model") then
                            stripHeavyVisual(top)
                        else
                            pcall(function() top:Destroy() end)
                        end
                    else
                        stashVisual(top, plant)
                    end
                end
            end
        end))
    end
end

local function bindOwnPlotLive(plot)
    if not plot then return end
    for _, f in ipairs(listPlantFolders(plot, LP.UserId)) do
        bindFolderLive(f, false, plot)
    end
end

local function bindOwnPlot(plot, opts)
    stripOwnPlot(plot, opts)
    bindOwnPlotLive(plot)
end

----------------------------------------------------------------
-- Other: Destroy keep 1 (no restore) — atau keep top-N buah saat stealCompat
----------------------------------------------------------------
local function clearOtherPlot(plot)
    if not plot or not CONFIG.clearOtherPlants or not isConfirmedOtherPlot(plot) then return end
    local ownerId = plotOwnerUserId(plot)
    -- Double guard: jangan pernah clear plot sendiri
    if ownerId == nil or ownerId == LP.UserId then return end
    if isOwnPlot(plot) then return end

    if stealKeepOn() then
        clearOtherPlotKeepTopFruits(plot)
        for _, folder in ipairs(listPlantFolders(plot, ownerId)) do
            bindFolderLive(folder, true, plot)
        end
        return
    end

    -- Pause: hapus semua tanaman orang (bukan keep-1-tipe)
    if S.otherPaused and S.otherPaused() then
        S.yieldT = os.clock()
        local t0 = os.clock()
        local destroyed, plantsIn = 0, 0
        for _, folder in ipairs(listPlantFolders(plot, ownerId)) do
            local kids = folder:GetChildren()
            plantsIn += #kids
            for i = 1, #kids do
                local p = kids[i]
                if not isSprinkler(p) then
                    if destroyIfOtherPlant(p, plot) then
                        destroyed += 1
                        B.stats.destroyedPlants += 1
                    end
                    if i % A.BATCH == 0 then sliceYield() end
                end
            end
            bindFolderLive(folder, true, plot)
        end
        dlog("clearOther PAUSE %s plantsIn=%d destroyed=%d ms=%.0f",
            plot.Name, plantsIn, destroyed, (os.clock() - t0) * 1000)
        return
    end

    S.yieldT = os.clock()
    local t0 = os.clock()
    local folders = listPlantFolders(plot, ownerId)
    local destroyed, plantsIn = 0, 0
    for _, folder in ipairs(folders) do
        local kids = folder:GetChildren()
        plantsIn += #kids
        local kept, kill = {}, {}
        for i = 1, #kids do
            local p = kids[i]
            if isSprinkler(p) then
            elseif p:IsA("Model") then
                if ownerId and p:GetAttribute("UserId") == nil then
                    pcall(function() p:SetAttribute("UserId", ownerId) end)
                end
                local key = plantTypeKey(p)
                local prev = kept[key]
                if prev then
                    local prevScore = (prev:GetAttribute("SeedName") ~= nil) and 1 or 0
                    local curScore = (p:GetAttribute("SeedName") ~= nil) and 1 or 0
                    if curScore > prevScore then
                        kill[#kill + 1] = prev
                        kept[key] = p
                    else
                        kill[#kill + 1] = p
                    end
                else
                    kept[key] = p
                end
            else
                kill[#kill + 1] = p
            end
        end
        for i = 1, #kill do
            if destroyIfOtherPlant(kill[i], plot) then
                destroyed += 1
                B.stats.destroyedPlants += 1
            end
            if i % A.BATCH == 0 then sliceYield() end
        end
        for _, p in pairs(kept) do
            if p and p.Parent and not isOwnPlantContext(p) then
                stripOtherPlantShell(p)
            end
        end
        bindFolderLive(folder, true, plot)
    end
    dlog("clearOther %s plantsIn=%d destroyed=%d ms=%.0f",
        plot.Name, plantsIn, destroyed, (os.clock() - t0) * 1000)
end

local function clearAllOthers()
    local g = Workspace:FindFirstChild("Gardens")
    if not g or not myPlot() then return end
    local t0 = os.clock()
    local n = 0
    for _, p in ipairs(g:GetChildren()) do
        if not S.alive then return end
        if isConfirmedOtherPlot(p) then
            if not B.otherBound[p] then
                B.otherBound[p] = true
                table.insert(B.otherConns, p.ChildAdded:Connect(function(ch)
                    if ch.Name == "Plants" or ch.Name == "Important" or ch.Name == "Plants_Physical" then
                        task.defer(function()
                            task.wait(0.2)
                            if S.alive and isConfirmedOtherPlot(p) then clearOtherPlot(p) end
                        end)
                    end
                end))
            end
            clearOtherPlot(p)
            n += 1
            task.wait()
        end
    end
    dlog("clearAllOthers plots=%d ms=%.0f", n, (os.clock() - t0) * 1000)
end

----------------------------------------------------------------
-- Graphics / boot
----------------------------------------------------------------
local function applyGraphics()
    pcall(function()
        Lighting.GlobalShadows = false
        Lighting.Technology = Enum.Technology.Compatibility
        Lighting.EnvironmentDiffuseScale = 0
        Lighting.EnvironmentSpecularScale = 0
        Lighting.Brightness = math.min(Lighting.Brightness, 1)
        pcall(function() Lighting.FogEnd = 1e9 end)
        for _, fx in ipairs(Lighting:GetChildren()) do
            if fx:IsA("PostEffect") or fx:IsA("BloomEffect") or fx:IsA("BlurEffect")
                or fx:IsA("ColorCorrectionEffect") or fx:IsA("SunRaysEffect")
                or fx:IsA("DepthOfFieldEffect") then
                fx.Enabled = false
            end
        end
    end)
    pcall(function()
        local terrain = Workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            terrain.Decoration = false
            terrain.WaterWaveSize = 0
            terrain.WaterWaveSpeed = 0
            terrain.WaterReflectance = 0
            terrain.WaterTransparency = 1
        end
    end)
    pcall(function()
        local ren = settings().Rendering
        ren.QualityLevel = Enum.QualityLevel.Level01
        pcall(function() ren.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level01 end)
        pcall(function() ren.EditQualityLevel = Enum.QualityLevel.Level01 end)
    end)
    -- Uncap: fpsCap<=0 → setfpscap(0). Angka >0 = hard cap executor.
    local cap = tonumber(CONFIG.fpsCap)
    pcall(function()
        if type(setfpscap) ~= "function" then return end
        if not cap or cap <= 0 then
            setfpscap(0)
        else
            setfpscap(math.floor(cap))
        end
    end)
    if CONFIG.mode == "nuclear" then
        pcall(function() RunService:Set3dRenderingEnabled(false) end)
    end
end

B.muteAll = function()
    if CONFIG.muteSounds then
        pcall(function() SoundService.Volume = 0 end)
    end
end

local function bindSprinklerRadius()
    local function kill(inst)
        local n = string.lower(tostring(inst.Name or ""))
        if n:find("sprinklerradius", 1, true) then
            pcall(function() inst:Destroy() end)
        end
    end
    local function bindChar(char)
        if not char then return end
        table.insert(B.conns, char.DescendantAdded:Connect(function(d)
            if S.alive then kill(d) end
        end))
    end
    if LP.Character then bindChar(LP.Character) end
    table.insert(B.conns, LP.CharacterAdded:Connect(function(c)
        task.defer(function() if S.alive then bindChar(c) end end)
    end))
end

local function startReconcile(myToken)
    task.spawn(function()
        local gap = tonumber(CONFIG.otherReconcileSec) or 25
        while S.alive and myToken == S.token do
            task.wait(gap)
            if not S.alive or myToken ~= S.token then return end
            G.__GAG2_RF_JOB("reconcileOther", function()
                -- game/weather sering restore FX — re-apply graphics supaya FPS tetap tinggi
                pcall(applyGraphics)
                local g = Workspace:FindFirstChild("Gardens")
                if not g or not myPlot() then return end
                for _, p in ipairs(g:GetChildren()) do
                    if not S.alive then return end
                    if isConfirmedOtherPlot(p) then
                        if stealKeepOn() then
                            clearOtherPlotKeepTopFruits(p)
                            task.wait()
                        else
                            clearOtherPlot(p)
                            task.wait()
                        end
                    end
                end
            end)
        end
    end)
end

S.mutLive.dataHasMutation = function(data)
    if type(data) ~= "table" then return false, nil end
    local raw = data.Mutation or data.mutation or data.MutationName or data.Mut or data.FruitMutation
    if type(raw) == "string" then
        local s = raw:match("^%s*(.-)%s*$")
        if s and s ~= "" and string.lower(s) ~= "none" and string.lower(s) ~= "normal" then
            return true, s
        end
    elseif type(raw) == "table" then
        local n = raw.Name or raw.Mutation
        if type(n) == "string" and n ~= "" then return true, n end
    end
    for _, k in ipairs({ "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
        "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil" }) do
        if data[k] == true then return true, k end
    end
    return false, nil
end

-- Key HARUS plantId|fruitId. FruitId saja bentrok (banyak buah FruitId=1)
-- → stamp Mutation ke shell polos → AC lolos filter mutasi.
local function indexOwnFruitsByFruitId(opts)
    opts = type(opts) == "table" and opts or {}
    local now = os.clock()
    local cached = S._shellIdx
    if type(cached) == "table" and opts.fresh ~= true
        and (now - (tonumber(S._shellIdxAt) or 0)) < 2.5 then
        return cached
    end
    local byFid = {}
    local plot = myPlot()
    if not plot then return byFid end

    local function put(plantId, fruitId, model)
        if not model then return end
        plantId = tostring(plantId or "")
        if plantId == "" then
            plantId = tostring(model:GetAttribute("PlantId") or "")
        end
        if fruitId == nil then
            fruitId = model:GetAttribute("FruitId")
        end
        if plantId == "" or fruitId == nil then return end
        byFid[plantId .. "|" .. tostring(fruitId)] = model
        local legacy = tostring(fruitId)
        if byFid[legacy] == nil then
            byFid[legacy] = model
        end
    end

    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if not plant:IsA("Model") then continue end
            local plantId = plant:GetAttribute("PlantId")
            local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if ff then
                for _, ch in ipairs(ff:GetChildren()) do
                    if ch:IsA("Model") then
                        put(ch:GetAttribute("PlantId") or plantId, ch:GetAttribute("FruitId"), ch)
                    end
                end
            end
        end
    end
    -- GetTagged mahal di garden 1200. Cuma perlu saat Eclipse / index fresh sengaja.
    if opts.withPrompts == true or (S.mutLive.isEclipse and S.mutLive.isEclipse()) then
        for _, prompt in ipairs(CollectionService:GetTagged("HarvestPrompt")) do
            if not (prompt:IsA("ProximityPrompt") and prompt:IsDescendantOf(plot)) then continue end
            local node = prompt.Parent
            for _ = 1, 12 do
                if not node then break end
                if node:IsA("Model") then
                    local fid = node:GetAttribute("FruitId")
                    if fid ~= nil then
                        put(node:GetAttribute("PlantId"), fid, node)
                        break
                    end
                    if node:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                        break
                    end
                end
                if node.Name == "Gardens" then break end
                node = node.Parent
            end
        end
    end
    S._shellIdx = byFid
    S._shellIdxAt = now
    return byFid
end

-- Ringan: tulis attr ke shell yang SUDAH ADA. Jangan GetDescendants / ApplyMutation.
stampShellMutationsFromSyncFast = function(force, opts)
    opts = type(opts) == "table" and opts or {}
    local eclipsedOnly = opts.eclipsedOnly == true
    local topHeavyOnly = opts.topHeavyOnly == true
    if not S.mutLive.ready and not force then return 0 end
    if S.mutLive.stampBusy then return 0 end
    if useGameManagedFruits() then return 0 end
    if not S.alive and not force then return 0 end
    if CONFIG.stripOwnVisual ~= true and not force then return 0 end
    local ignoreGap = opts.ignoreGap == true
    local now = os.clock()
    if (not ignoreGap) and (now - S.mutLive.stampLast) < S.mutLive.stampMinGap then return 0 end
    S.mutLive.stampBusy = true
    S.mutLive.stampLast = now
    S.mutLive.ready = true
    if topHeavyOnly and (type(S.mutLive.topHeavyIds) ~= "table" or next(S.mutLive.topHeavyIds) == nil) then
        pcall(function() S.mutLive.refreshTopHeavy() end)
    end

    local stamped, checked = 0, 0
    local okWork, err = pcall(function()
        local sync = getGardenSync()
        if not sync or type(sync.GetGarden) ~= "function" then return end
        local garden = nil
        pcall(function()
            garden = sync:GetGarden(LP.UserId)
        end)
        if type(garden) ~= "table" then return end

        local shells = indexOwnFruitsByFruitId({
            withPrompts = false,
        })
        local steps, queued = 0, 0
        local tBudget = os.clock()
        local function visit(plantId, fruitId, data)
            if type(data) ~= "table" then
                data = { FruitId = fruitId }
            else
                fruitId = data.FruitId or data.fruitId or data.Id or data.id or data.UUID or fruitId
            end
            if fruitId == nil or tostring(fruitId) == "" then return end
            local has, mutName = S.mutLive.dataHasMutation(data)
            if not has then return end
            if topHeavyOnly and not S.mutLive.isTopHeavy(fruitId, plantId) then return end
            local isEcl = (data.Eclipsed == true)
                or (type(mutName) == "string" and string.lower(mutName) == "eclipsed")
            if eclipsedOnly and not isEcl then return end
            checked += 1
            local shell = shells[tostring(plantId) .. "|" .. tostring(fruitId)]
                or shells[tostring(fruitId)]
            if not (shell and shell.Parent) then
                if queued < 12 then
                    pcall(enqueueFruitShell, LP.UserId, plantId, fruitId, data)
                    queued += 1
                    S._shellIdxAt = 0
                end
                return
            end
            local shellPid = tostring(shell:GetAttribute("PlantId") or "")
            if shellPid ~= "" and shellPid ~= tostring(plantId) then
                return
            end
            local cur = tostring(shell:GetAttribute("Mutation") or "")
            if type(mutName) == "string" and mutName ~= ""
                and string.lower(cur) == string.lower(mutName)
                and (isEcl or shell:GetAttribute(mutName) == true) then
                return
            end
            if isEcl then
                S.mutLive.mirrorEclipsedAttr(shell)
            else
                stampMutationAttrs(shell, data)
            end
            stamped += 1
            steps += 1
            if (os.clock() - tBudget) >= 0.006 then
                task.wait()
                tBudget = os.clock()
            end
        end
        for plantId, plantData in pairs(garden) do
            if not S.alive then return end
            if type(plantData) ~= "table" then continue end
            local fruits = plantData.Fruits or plantData.fruits or plantData.Fruit
            if type(fruits) ~= "table" then continue end
            if #fruits > 0 then
                for fi = 1, #fruits do
                    local d = fruits[fi]
                    if type(d) == "table" then
                        visit(plantId, d.FruitId or d.fruitId or d.Id or d.id, d)
                    end
                end
            else
                for fruitId, d in pairs(fruits) do
                    if type(d) == "table" then
                        visit(plantId, d.FruitId or d.fruitId or fruitId, d)
                    elseif d == true or type(d) == "string" or type(d) == "number" then
                        visit(plantId, fruitId, { FruitId = fruitId })
                    end
                end
            end
        end
    end)
    S.mutLive.stampBusy = false
    if not okWork then
        dlog("mut-stamp-fast err: %s", tostring(err))
        return 0
    end
    if stamped > 0 or checked > 0 then
        dlog("mut-stamp-fast checked=%d stamped=%d eclipsedOnly=%s",
            checked, stamped, tostring(eclipsedOnly))
    end
    return stamped
end

-- RINGAN: enable/disable tag shell dari Age/MaxAge GardenSync.
-- opts.ageOnly=true → skip stamp mutasi + enqueue + FVC bind.
-- opts.plantBatch>0 → potong per tick (anti stall 1200 pohon).
syncOwnShellHarvestFromSync = function(opts)
    opts = type(opts) == "table" and opts or {}
    -- AC GetGarden; eclipse top-N punya ensurePresence sendiri. Jangan scan 1200 pohon.
    if CONFIG.ownNoFruitShells ~= false then
        return 0
    end
    local ageOnly = opts.ageOnly == true
    if useGameManagedFruits() then return 0 end
    if not (S.forceSoftFruits or (S.visualBlockActive and CONFIG.stripOwnVisual)) then
        return 0
    end
    -- stamp mutasi punya loop sendiri; jangan dobel di sini
    local sync = getGardenSync()
    local pvc = getPVC()
    if not sync or not pvc then return 0 end
    if type(sync.GetGarden) ~= "function" then
        return 0
    end
    local garden = nil
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    if type(garden) ~= "table" then return 0 end

    local plantById = {}
    do
        local plot = myPlot()
        if plot then
            for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
                for _, plant in ipairs(folder:GetChildren()) do
                    if plant:IsA("Model") then
                        local pid = plant:GetAttribute("PlantId")
                        if pid ~= nil then
                            plantById[pid] = plant
                            plantById[tostring(pid)] = plant
                        end
                    end
                end
            end
        end
    end

    local ids = S._ripeIds
    local nowClock = os.clock()
    if type(ids) ~= "table" or not ageOnly or ((nowClock - (tonumber(S._ripeIdsAt) or 0)) > 8) then
        ids = {}
        for pid, pdata in pairs(garden) do
            if type(pdata) == "table" then
                ids[#ids + 1] = pid
            end
        end
        S._ripeIds = ids
        S._ripeIdsAt = nowClock
        if not ageOnly then
            S._ripeIdx = 1
        end
    end
    local nIds = #ids
    local batch = math.floor(tonumber(opts.plantBatch) or 0)
    if not ageOnly or batch <= 0 or nIds <= batch then
        batch = nIds
        S._ripeIdx = 1
    end
    local startIdx = math.max(1, math.floor(tonumber(S._ripeIdx) or 1))
    if startIdx > nIds then startIdx = 1 end

    local enabled, disabled, scanned, queued = 0, 0, 0, 0
    local fillCap = math.max(1, math.floor(tonumber(CONFIG.liveFillCap) or 400))
    local processed = 0
    local idCursor = startIdx
    while processed < batch and processed < nIds do
        local plantId = ids[idCursor]
        idCursor += 1
        if idCursor > nIds then idCursor = 1 end
        processed += 1
        local plantData = garden[plantId]
        if type(plantData) ~= "table" then continue end
        local plant = plantById[plantId] or plantById[tostring(plantId)]
        if typeof(plant) ~= "Instance" or not plant.Parent then
            if type(pvc.GetSpawnedPlant) == "function" then
                pcall(function()
                    plant = pvc:GetSpawnedPlant(LP.UserId, plantId)
                end)
            end
        end
        if typeof(plant) ~= "Instance" or not plant.Parent then continue end

        local folder = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
        if not folder then continue end

        local entries, byId
        if ageOnly then
            byId = {}
            local fruits = plantData.Fruits or plantData.fruits or plantData.Fruit
            if type(fruits) == "table" then
                if #fruits > 0 then
                    for fi = 1, #fruits do
                        local d = fruits[fi]
                        if type(d) == "table" then
                            local fid = d.FruitId or d.fruitId or d.Id or d.id or d.UUID
                            if fid ~= nil then byId[tostring(fid)] = d end
                        end
                    end
                else
                    for fruitId, d in pairs(fruits) do
                        if type(d) == "table" then
                            local fid = d.FruitId or d.fruitId or d.Id or d.id or fruitId
                            byId[tostring(fid)] = d
                        end
                    end
                end
            end
        else
            entries = fruitEntriesFromPlantData(plantData, plant, plantId)
            if #entries == 0 then continue end
            byId = {}
            for ei = 1, #entries do
                byId[tostring(entries[ei].id)] = entries[ei].data
            end
            if queued < fillCap then
                local haveId = {}
                for _, ch0 in ipairs(folder:GetChildren()) do
                    if not ch0:IsA("Model") then continue end
                    local fid0 = ch0:GetAttribute("FruitId")
                    if fid0 ~= nil or ch0:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                        haveId[tostring(fid0 or "")] = true
                    end
                end
                for ei = 1, #entries do
                    if queued >= fillCap then break end
                    local e = entries[ei]
                    local fid = tostring(e.id or "")
                    if haveId[fid] then continue end
                    if isPendingCollect(plantId, e.id, LP.UserId) then continue end
                    pcall(enqueueFruitShell, LP.UserId, plantId, e.id, e.data)
                    queued += 1
                    haveId[fid] = true
                end
            end
        end

        for _, ch in ipairs(folder:GetChildren()) do
            if not ch:IsA("Model") then continue end
            local isShell = ch:GetAttribute(A.FRUIT_SHELL_ATTR) == true
            local fidAttr = ch:GetAttribute("FruitId")
            -- FruitId "" valid (plant-harvest); nil tanpa flag = skip
            if fidAttr == nil and ch:GetAttribute("_GAG2PlantHarvest") ~= true then
                continue
            end
            local fid = tostring(fidAttr or "")
            if (not ageOnly) and isShell then
                bindSoftShellInFvcU3(ch, LP.UserId, plantId, fidAttr)
            end
            if not ageOnly then
                bindFruitMutationListener(ch)
            end

            local data = byId and byId[fid]
            if type(data) ~= "table" and fid == "" then
                data = plantData
            end

            -- Mutasi: jarang (full sync). Poll cepat = Age/gate saja.
            if not ageOnly then
                if type(data) == "table" then
                    stampMutationAttrs(ch, data)
                else
                    stampMutationAttrs(ch, nil)
                end
            end

            -- Ripe gate / weight cuma soft shell
            if not isShell then
                scanned += 1
                continue
            end

            if type(data) ~= "table" then
                local pr0 = ch:FindFirstChild("HarvestPrompt", true)
                local wasOff = pr0
                    and pr0:IsA("ProximityPrompt")
                    and CollectionService:HasTag(pr0, "HarvestPrompt")
                    and pr0:GetAttribute("Collected") ~= true
                if pr0 then
                    applyShellCollectGate(ch, false)
                    if wasOff then disabled += 1 end
                end
                scanned += 1
                continue
            end

            local age = _pickDataNum(data, { "Age", "age" })
            local maxAge = _pickDataNum(data, { "MaxAge", "maxAge" })
            local prevAge = tonumber(ch:GetAttribute("Age"))
            local prevMax = tonumber(ch:GetAttribute("MaxAge"))
            if ageOnly and age ~= nil and maxAge ~= nil
                and age == prevAge and maxAge == prevMax then
                scanned += 1
                continue
            end

            local pr = ch:FindFirstChild("HarvestPrompt", true)
            local wasOn = pr
                and pr:IsA("ProximityPrompt")
                and CollectionService:HasTag(pr, "HarvestPrompt")
                and pr:GetAttribute("Collected") ~= true
            if not ageOnly then
                local sm = _pickDisplaySizeMulti(data)
                local og = _pickDataNum(data, { "OvertimeGrowth" })
                local plantName = data.PlantName
                    or ch:GetAttribute("CorePartName")
                    or ch:GetAttribute("SeedName")
                local bw = _fruitModuleBaseWeight(plantName)
                    or _pickDataNum(data, { "BaseWeight", "baseWeight", "BaseKg" })
                local w = _pickDisplayWeight(data, bw, sm or tonumber(ch:GetAttribute("SizeMulti")), og or 1)
                pcall(function()
                    if bw ~= nil then ch:SetAttribute("BaseWeight", bw) end
                    if sm ~= nil and sm > 0 then
                        ch:SetAttribute("SizeMulti", sm)
                    end
                    if og ~= nil then ch:SetAttribute("OvertimeGrowth", og) end
                    if w and w > 0 then
                        ch:SetAttribute("Weight", w)
                    end
                end)
            end
            pcall(function()
                if age ~= nil then ch:SetAttribute("Age", age) end
                if maxAge ~= nil then ch:SetAttribute("MaxAge", maxAge) end
            end)

            -- strict: cuma Age>=MaxAge (sama multi-buah — anti match palsu)
            local ready = fruitDataHarvestReady(data, ch)
            if ready then
                if not pr then
                    ensureShellBodyPart(ch, ch:GetPivot())
                    local hp = ch:FindFirstChild("HarvestPart") or ch:FindFirstChild("ShellBody")
                    if hp and hp:IsA("BasePart") then
                        pr = Instance.new("ProximityPrompt")
                        pr.Style = Enum.ProximityPromptStyle.Custom
                        pr.Name = "HarvestPrompt"
                        pr.ActionText = "Harvest"
                        pr.HoldDuration = 0
                        pr.RequiresLineOfSight = false
                        pr.Parent = hp
                    end
                end
                if not wasOn then
                    applyShellCollectGate(ch, true)
                    enabled += 1
                end
            else
                if pr then
                    applyShellCollectGate(ch, false)
                    if wasOn then disabled += 1 end
                end
            end

            scanned += 1
            if (not ageOnly) and scanned % 120 == 0 then
                task.wait()
            end
        end
    end
    S._ripeIdx = idCursor
    if enabled > 0 or disabled > 0 or queued > 0 then
        dlog("ripe-strict on=%d off=%d scanned=%d queued=%d ageOnly=%s batch=%d/%d",
            enabled, disabled, scanned, queued, tostring(ageOnly), processed, nIds)
    end
    return enabled
end

-- Soft shell tidak di-track FVC → setelah collect tetap ada + AutoCollect counter stuck.
-- Ripe-gate: batch 250 pohon / 0.3s (full garden ~1.5s, tanpa stall 0.5s).
-- Prune orphan tetap jarang (~5s).
local function startFruitShellPrune(myToken)
    task.spawn(function()
        task.wait(2.0)
        if not S.alive or myToken ~= S.token then return end
        pcall(cleanupAllOwnLooseProxies)
        local lastRipe = 0
        local lastFullRipe = 0
        local lastPrune = 0
        while S.alive and myToken == S.token do
            local tickSec = tonumber(CONFIG.ripeTickSec) or 0.3
            task.wait(tickSec)
            if not S.alive or myToken ~= S.token then return end
            if not (S.forceSoftFruits or CONFIG.stripOwnVisual) then continue end
            pcall(noteFarNearEdge)
            if CONFIG.pauseFarFromPlot ~= false and (S.farPaused == true or isFarFromOwnPlot()) then
                continue
            end
            if isResumeCatchup() then
                continue
            end
            local now = os.clock()
            -- ownNoFruitShells: jangan prune 1200 GetSpawnedPlant tiap 5s (CPU spike)
            local pruneGap = 20.0
            if CONFIG.ownNoFruitShells == false then
                pruneGap = 5.0
            end
            if now - lastPrune >= pruneGap then
                lastPrune = now
                pcall(cleanupAllOwnLooseProxies)
                if CONFIG.ownNoFruitShells == false then
                    local n = 0
                    pcall(function()
                        n = pruneOrphanOwnFruits()
                    end)
                    if n > 0 then
                        dlog("prune orphan shells=%d total=%d", n, S.statsPrunedFruits)
                    end
                end
            end
            if CONFIG.ownNoFruitShells ~= false then
                continue
            end
            if now - lastRipe >= tickSec then
                lastRipe = now
                local full = (now - lastFullRipe) >= 5.0
                if full then lastFullRipe = now end
                local batch = 0
                if not full then
                    batch = math.max(80, math.floor(tonumber(CONFIG.ripePlantBatch) or 250))
                end
                pcall(syncOwnShellHarvestFromSync, {
                    ageOnly = not full,
                    plantBatch = batch,
                })
            end
        end
    end)
end

local function waitReady()
    G.__GAG2_RF_PHASE = "waitReady"
    local t0 = os.clock()
    while S.alive and os.clock() - t0 < 50 do
        if Workspace:FindFirstChild("Gardens") and LP:GetAttribute("PlotId") and LP.Character then
            task.wait(0.1)
            if myPlot() then
                dlog("waitReady %s ms=%.0f", myPlot().Name, (os.clock() - t0) * 1000)
                G.__GAG2_RF_PHASE = "idle"
                return true
            end
        end
        task.wait(0.15)
    end
    G.__GAG2_RF_PHASE = "idle"
    return myPlot() ~= nil
end

local function applyAll()
    G.__GAG2_RF_PHASE = "applyAll"
    local t0 = os.clock()
    applyGraphics()
    B.muteAll()
    local plot = myPlot()
    if not plot then
        dlog("applyAll no plot")
        G.__GAG2_RF_PHASE = "idle"
        return
    end
    startPrevent()
    markActive()
    -- Strip lebih awal: bind live + gelombang progresif SELAMA loading, final strip cepat setelah selesai
    task.spawn(function()
        local p0 = myPlot() or plot
        disc(B.plotConns)
        table.clear(B.folderBound)
        -- SEGERA: listener + antre strip gelombang 1 (budget/frame, anti freeze)
        if p0 then
            bindOwnPlotLive(p0)
            pcall(stripOwnPlot, p0, {
                fast = true,
                skipDone = true,
                useQueue = true,
                maxPerWave = tonumber(CONFIG.loadStripWaveMax) or 40,
            })
        end

        local total = tonumber(LP:GetAttribute("GardenLoadingTotal")) or 0
        local loading = (LP:GetAttribute("LoadingScreenActive") == true or total > 0)
        if loading then
            dlog("applyAll progressive QUEUE strip during garden spawn…")
            local waitDone = false
            task.spawn(function()
                waitGardenSpawnComplete(120)
                waitDone = true
            end)
            local waveMax = tonumber(CONFIG.loadStripWaveMax) or 40
            while S.alive and not waitDone do
                task.wait(1.2)
                if not S.alive or waitDone then break end
                local p = myPlot() or p0
                if p then
                    for _, f in ipairs(listPlantFolders(p, LP.UserId)) do
                        bindFolderLive(f, false, p)
                    end
                    -- enqueue sisa saja; Heartbeat yang strip pelan
                    pcall(stripOwnPlot, p, {
                        fast = true,
                        skipDone = true,
                        useQueue = true,
                        maxPerWave = waveMax,
                    })
                end
            end
            task.wait(0.1)
        else
            task.wait(0.2)
        end
        if not S.alive then return end

        -- Finalize: JANGAN re-strip semua (skipDone=false = freeze garden besar).
        -- Cover sisa via queue; clear other di background.
        local p = myPlot() or p0
        if p then
            pcall(stripOwnPlot, p, {
                fast = true,
                skipDone = true,
                useQueue = true,
                maxPerWave = tonumber(CONFIG.loadStripWaveMax) or 40,
            })
        end
        disc(B.plotConns)
        table.clear(B.folderBound)
        if p or myPlot() then
            bindOwnPlotLive(myPlot() or p)
        end
        startMutationMirror()
        task.spawn(function()
            task.wait(0.4)
            if not S.alive then return end
            clearAllOthers()
            -- sisa plant yang belum A.TREE_ATTR — antre lagi pelan
            local p2 = myPlot()
            if p2 then
                pcall(stripOwnPlot, p2, { skipDone = true, useQueue = true })
            end
        end)
        -- AC GetGarden: jangan AddMissingPrompts massal (128 yielded + shell)
        task.defer(function()
            if not S.alive then return end
            if CONFIG.ownNoFruitShells ~= false then
                dlog("skip AddMissingPrompts (ownNoFruitShells)")
                return
            end
            task.wait(2.0)
            if not S.alive then return end
            local FVC = getFVC()
            if FVC and type(FVC.AddMissingPrompts) == "function" then
                pcall(function() FVC:AddMissingPrompts() end)
            end
        end)
        dlog("applyAll DONE ms=%.0f stashed=%d fruits=%d plantQ=%d shellQ=%d destroyedOther=%d",
            (os.clock() - t0) * 1000, B.stats.stashed, B.stats.fruits,
            #Q.plantStrip, #Q.fruitShell, B.stats.destroyedPlants)
        G.__GAG2_RF_PHASE = "idle"
    end)
end

local function bindGardens(g)
    if not g then return end
    table.insert(B.conns, g.ChildAdded:Connect(function(ch)
        if not S.alive then return end
        task.spawn(function()
            -- Steal ON: tunggu plot sempat spawn buah (0.25s sering kosong → wipe bug)
            local waitSec = stealKeepOn() and 1.25 or 0.35
            task.wait(waitSec)
            if not S.alive or not isConfirmedOtherPlot(ch) then return end
            if stealKeepOn() then
                -- Bind live dulu, trim top-N setelah buah ada (defer aman)
                local ownerId = plotOwnerUserId(ch)
                for _, folder in ipairs(listPlantFolders(ch, ownerId)) do
                    bindFolderLive(folder, true, ch)
                end
                scheduleStealKeepTrim(ch)
            else
                clearOtherPlot(ch)
            end
        end)
    end))
end

----------------------------------------------------------------
-- CPU: matikan Heartbeat/RenderStepped game (1200 pohon / VFX). Restore di Stop.
----------------------------------------------------------------
function M.RestoreGameHeartbeats()
    local bySrc = B.gameHbBySrc
    local n = 0
    if type(bySrc) == "table" then
        for _, conn in pairs(bySrc) do
            pcall(function()
                if conn and conn.Enable then
                    conn:Enable()
                elseif conn then
                    conn.Enabled = true
                end
            end)
            n += 1
        end
        table.clear(bySrc)
    end
    if type(B.gameHbCons) == "table" then
        table.clear(B.gameHbCons)
    end
    B.gameHbOff = 0
    if n > 0 then
        dlog("game Heartbeat restored=%d", n)
    end
    return n
end

function M.BypassGameHeartbeats()
    if CONFIG.bypassGameHeartbeat == false then
        return 0
    end
    if type(getconnections) ~= "function" then
        return 0
    end
    local skip = B.gameHbSkip
    if type(skip) ~= "table" or #skip == 0 then
        return 0
    end
    if type(B.gameHbBySrc) ~= "table" then
        B.gameHbBySrc = {}
    end
    local function srcOf(conn)
        local fn = conn and conn.Function
        if type(fn) ~= "function" then
            return ""
        end
        local s = ""
        pcall(function()
            s = tostring(debug.info(fn, "s") or "")
        end)
        return s
    end
    local function should(src)
        for i = 1, #skip do
            if string.find(src, skip[i], 1, true) then
                return true
            end
        end
        return false
    end
    local added = 0
    local function scan(sig)
        if not sig then
            return
        end
        local ok, cons = pcall(getconnections, sig)
        if not ok or type(cons) ~= "table" then
            return
        end
        for i = 1, #cons do
            local conn = cons[i]
            local src = srcOf(conn)
            if src ~= "" and should(src) then
                pcall(function()
                    if conn.Disable then
                        conn:Disable()
                    else
                        conn.Enabled = false
                    end
                end)
                if B.gameHbBySrc[src] == nil then
                    added += 1
                end
                B.gameHbBySrc[src] = conn
            end
        end
    end
    scan(RunService.Heartbeat)
    pcall(function()
        scan(RunService.RenderStepped)
    end)
    pcall(function()
        scan(RunService.PreRender)
    end)
    local total = 0
    for _ in pairs(B.gameHbBySrc) do
        total += 1
    end
    B.gameHbOff = total
    if added > 0 then
        dlog("game Heartbeat off +%d total=%d", added, total)
    end
    return added
end

function M.RestoreWorldParticles()
    local n = 0
    local set = B.mutedParticleSet
    if type(set) == "table" then
        for pe in pairs(set) do
            if typeof(pe) == "Instance" and pe.Parent then
                pcall(function()
                    pe.Enabled = true
                end)
                n += 1
            end
        end
        table.clear(set)
    end
    if type(B.mutedParticles) == "table" then
        table.clear(B.mutedParticles)
    end
    B.muteDidFull = false
    B.muteAddedConn = nil
    if n > 0 then
        dlog("world particles restored=%d", n)
    end
    return n
end

function M.MuteWorldParticles()
    if CONFIG.muteWorldParticles == false then
        return 0
    end
    if type(B.mutedParticleSet) ~= "table" then
        B.mutedParticleSet = setmetatable({}, { __mode = "k" })
    end
    -- Array kuat dihapus: PE cuaca unparent tiap detik, ref kuat = native tidak ter-GC.
    if type(B.mutedParticles) == "table" and #B.mutedParticles > 0 then
        table.clear(B.mutedParticles)
    end
    local function mutePe(d)
        if typeof(d) ~= "Instance" or d.ClassName ~= "ParticleEmitter" then
            return false
        end
        if d.Enabled == true then
            pcall(function()
                d.Enabled = false
            end)
        end
        B.mutedParticleSet[d] = true
        return true
    end
    if B.muteAddedConn == nil then
        local conn
        conn = Workspace.DescendantAdded:Connect(function(d)
            if not S.alive or not S.running then
                return
            end
            mutePe(d)
        end)
        B.muteAddedConn = conn
        table.insert(B.conns, conn)
    end
    -- Remute yang masih hidup (cuaca kadang nyalain lagi). Weak key: yang Parent=nil ter-GC.
    local live = 0
    for pe in pairs(B.mutedParticleSet) do
        if typeof(pe) == "Instance" and pe.Parent then
            live += 1
            if pe.ClassName == "ParticleEmitter" and pe.Enabled == true then
                pcall(function()
                    pe.Enabled = false
                end)
            end
        end
    end
    if B.muteDidFull == true then
        return live
    end
    -- Sekali di Start: matikan PE yang sudah ada. Jangan ulang tiap 30/90s.
    B.muteDidFull = true
    local added = 0
    local ok, descendants = pcall(function()
        return Workspace:GetDescendants()
    end)
    if ok and type(descendants) == "table" then
        for i = 1, #descendants do
            local d = descendants[i]
            if d.ClassName == "ParticleEmitter" then
                mutePe(d)
                added += 1
            end
        end
    end
    if added > 0 then
        dlog("world particles off once=%d", added)
    end
    return added
end

----------------------------------------------------------------
-- API
----------------------------------------------------------------
-- Soft: batch spawn → strip mesh (PlantId/FruitId/proxy tetap → AutoCollect/Trowel OK)
function M.RestoreSoft()
    return restoreAfterGardenReady("RestoreSoft", {
        rehide = true,
        fullVisual = false,
        batchSize = CONFIG.restoreBatchSize,
        batchDelay = CONFIG.restoreBatchDelay,
    })
end
M.restoreSoft = M.RestoreSoft

-- Full: batch spawn, biarkan visual (pelan, anti spike)
function M.RestoreFull()
    return restoreAfterGardenReady("RestoreFull", {
        rehide = false,
        fullVisual = true,
        batchSize = CONFIG.restoreBatchSize,
        batchDelay = CONFIG.restoreBatchDelay,
    })
end
M.restoreFull = M.RestoreFull

function M.RestoreOwn()
    if CONFIG.restoreFullVisual then
        return M.RestoreFull()
    end
    return M.RestoreSoft()
end
M.restoreOwn = M.RestoreOwn
M.Restore = M.RestoreOwn
M.RestoreGarden = M.RestoreOwn

function M.RestoreGardenNow(opts)
    opts = type(opts) == "table" and opts or {
        rehide = CONFIG.restoreRehide ~= false and not CONFIG.restoreFullVisual,
        fullVisual = CONFIG.restoreFullVisual == true,
    }
    return restoreGardenFromData("RestoreGardenNow", opts)
end
M.restoreGardenNow = M.RestoreGardenNow

-- opts.quiet = true → cleanup saja, JANGAN restore (dipakai Start / reload)
-- Hapus semua soft shell di plot sendiri (penting saat Remove Garden OFF)
local function destroyAllOwnFruitShells()
    local plot = myPlot()
    if not plot then return 0 end
    local n = 0
    for _, folder in ipairs(listPlantFolders(plot, LP.UserId)) do
        for _, plant in ipairs(folder:GetChildren()) do
            if not plant:IsA("Model") then continue end
            local ff = plant:FindFirstChild("Fruits") or plant:FindFirstChild("Fruit")
            if ff then
                for _, ch in ipairs(ff:GetChildren()) do
                    if ch:IsA("Model") and ch:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                        if pcall(function() ch:Destroy() end) then
                            n += 1
                        end
                    end
                end
            end
            for _, ch in ipairs(plant:GetChildren()) do
                if ch:IsA("Model") and ch:GetAttribute(A.FRUIT_SHELL_ATTR) == true then
                    if pcall(function() ch:Destroy() end) then
                        n += 1
                    end
                end
            end
        end
        task.wait()
    end
    if n > 0 then
        dlog("destroy own soft shells=%d", n)
    end
    return n
end

function M.Stop(opts)
    opts = type(opts) == "table" and opts or {}
    local quiet = opts.quiet == true or opts.noRestore == true
    local wasRunning = S.running or S.alive

    dlog("STOP quiet=%s wasRunning=%s stashed=%d destroyedOther=%d",
        tostring(quiet), tostring(wasRunning), B.stats.stashed, B.stats.destroyedPlants)

    S.alive = false
    S.running = false
    pcall(M.RestoreGameHeartbeats)
    pcall(M.RestoreWorldParticles)
    S.mutLive.ready = false
    S.mutLive.eclipseGrow = false
    S.mutLive.posLoopRunning = false
    S.mutLive.posWaveList = nil
    S.mutLive.posWaveClean = 0
    S.mutLive.refreshQueued = false
    S.mutLive.refreshLast = 0
    S.mutLive.topHeavyIds = nil
    S.mutLive.topHeavyList = nil
    G.__GAG2MutStampQueued = nil
    S.mutLive.eclipseAt = 0
    if S.mutLive.eclipseConn then
        pcall(function() S.mutLive.eclipseConn:Disconnect() end)
        S.mutLive.eclipseConn = nil
    end
    if S.mutLive.timeFrozenConn then
        pcall(function() S.mutLive.timeFrozenConn:Disconnect() end)
        S.mutLive.timeFrozenConn = nil
    end
    if S.mutLive.beamConn then
        pcall(function() S.mutLive.beamConn:Disconnect() end)
        S.mutLive.beamConn = nil
    end
    S.mutLive.beamHooked = false
    S.token += 1
    -- batalkan restore yang sedang nunggu LoadingScreenDone (biar gak freeze setelah skip)
    if quiet or not wasRunning then
        S.restoreGen += 1
    end
    stopPrevent()
    disc(B.conns)
    disc(B.plotConns)
    disc(B.otherConns)
    for folder, c in pairs(B.fruitsFolderBound) do
        pcall(function()
            if c then c:Disconnect() end
        end)
        B.fruitsFolderBound[folder] = nil
    end
    table.clear(B.fruitsFolderBound)
    table.clear(B.otherBound)
    table.clear(B.folderBound)
    table.clear(Q.plantStrip)
    table.clear(Q.plantStripQueued)
    if Q.plantStripConn then
        pcall(function()
            Q.plantStripConn:Disconnect()
        end)
        Q.plantStripConn = nil
    end
    -- Matikan Remove Garden: buang soft shell supaya AutoCollect pakai buah game lagi
    S.forceSoftFruits = false
    if wasRunning and not quiet then
        pcall(destroyAllOwnFruitShells)
    end
    S.cachedPlot = nil
    pcall(function() RunService:Set3dRenderingEnabled(true) end)
    G.REDUCE_FPS_ENABLED = false
    _G.REDUCE_FPS_ENABLED = false
    markActive()

    -- OFF → SELALU full visual (FVC asli + HarvestPrompt game).
    -- Soft restore on Stop dulu re-patch FVC + soft shell, lalu AC purge shell → count 0.
    if wasRunning and CONFIG.restoreOnStop and not quiet then
        restoreAfterGardenReady("Stop", { rehide = false, fullVisual = true })
    end
end

function M.Start()
    if S.running then return true end
    -- JANGAN panggil Stop biasa: itu ngantri restore → freeze pas loading skip selesai
    S.restoreGen += 1
    M.Stop({ quiet = true })

    _cfg()
    S.alive = true
    S.running = true
    S.token += 1
    local myToken = S.token
    S.cachedPlot = nil
    B.stats = { destroyedPlants = 0, stashed = 0, fruits = 0, restored = 0 }
    B.statsBlocked = { plantInit = 0, fruitInit = 0, otherPlantSkip = 0, otherFruitSkip = 0, stripped = 0 }
    table.clear(B.stashMap)
    table.clear(Q.fruitShell)
    table.clear(Q.fruitShellQueued)
    Q.fruitShellDraining = false
    table.clear(Q.plantStrip)
    table.clear(Q.plantStripQueued)
    if Q.plantStripConn then
        pcall(function()
            Q.plantStripConn:Disconnect()
        end)
        Q.plantStripConn = nil
    end
    S.mutLive.ready = false
    S.mutLive.eclipseGrow = false
    S.mutLive.posLoopRunning = false
    S.mutLive.posWaveList = nil
    S.mutLive.posWaveClean = 0
    S.mutLive.refreshQueued = false
    S.mutLive.refreshLast = 0
    G.__GAG2MutStampQueued = nil

    G.REDUCE_FPS_ENABLED = true
    _G.REDUCE_FPS_ENABLED = true
    -- Production: log ReduceFPS OFF (SetDebug(true) kalau mau trace).
    G.REDUCE_FPS_DEBUG = false
    _G.REDUCE_FPS_DEBUG = false
    CONFIG.debug = false
    markActive()
    G.__GAG2_RF_PHASE = "boot"
    -- Uncap FPS + graphics dulu (sebelum strip berat) biar frame budget langsung naik
    pcall(applyGraphics)
    -- Gate FruitProxyUtil saja (jangan sentuh CollectFruit/Packet)
    pcall(installFruitProxyYieldGate)
    -- PENTING: block InitPlant SEBELUM plot/garden spawn (anti CPU spike)
    startPrevent()
    pcall(M.BypassGameHeartbeats)
    dlog("START v10.23.4-fx fpsCap=%s stripPerFrame=%d waveMax=%d plantBatch=%d",
        tostring(CONFIG.fpsCap),
        tonumber(CONFIG.loadStripPerFrame) or 4,
        tonumber(CONFIG.loadStripWaveMax) or 40,
        tonumber(CONFIG.restoreBatchSize) or 4)

    task.spawn(function()
        if not S.alive or myToken ~= S.token then return end
        applyGraphics()
        B.muteAll()
        bindSprinklerRadius()
        -- pastikan patch nempel kalau Plants folder belom ready di Start sync
        if CONFIG.blockVisualInit then
            patchPlantModules()
            patchFruitModules()
        end
        hookMutationController()
        local g = Workspace:FindFirstChild("Gardens") or Workspace:WaitForChild("Gardens", 25)
        bindGardens(g)
        table.insert(B.conns, LP:GetAttributeChangedSignal("PlotId"):Connect(function()
            S.cachedPlot = nil
            disc(B.plotConns)
            table.clear(B.folderBound)
            task.defer(function()
                task.wait(0.2)
                if S.alive and waitReady() then applyAll() end
            end)
        end))
        startPlantCullDisabler(myToken)
        startFarNearWatcher(myToken) -- no-op kecuali pauseFarFromPlot=true
        pcall(M.BypassGameHeartbeats)
        task.spawn(function()
            pcall(M.MuteWorldParticles)
        end)
        task.spawn(function()
            while S.alive and myToken == S.token do
                task.wait(30)
                if not S.alive or myToken ~= S.token then
                    return
                end
                pcall(M.BypassGameHeartbeats)
            end
        end)
        if waitReady() and S.alive and myToken == S.token then
            applyAll()
            startReconcile(myToken)
            startFruitShellPrune(myToken)
            startLiveMutationSync(myToken)
        else
            -- plot belom siap saat boot — poll sampai ada
            for _ = 1, 60 do
                if not S.alive or myToken ~= S.token then return end
                task.wait(1)
                if myPlot() then
                    applyAll()
                    startReconcile(myToken)
                    startFruitShellPrune(myToken)
                    startLiveMutationSync(myToken)
                    return
                end
            end
            dlog("START aborted: plot never ready")
        end
    end)
    return true
end

