-- Auto Steal: ref-count. ON → other garden keep top-N kg buah; OFF → clear agresif lagi.
function M.SetStealCompat(on)
    local prev = S.stealCompatRef or 0
    if on == true then
        S.stealCompatRef = prev + 1
    else
        S.stealCompatRef = math.max(0, prev - 1)
    end
    local now = S.stealCompatRef
    G.__GAG2_STEAL_COMPAT = now > 0
    _G.__GAG2_STEAL_COMPAT = now > 0
    if (prev <= 0 and now > 0) or (prev > 0 and now <= 0) then
        _cfg()
        if S.alive and CONFIG.clearOtherPlants then
            task.spawn(function()
                clearAllOthers()
                if stealKeepOn() then
                    pcall(requestGardensFire, true)
                end
            end)
        end
        dlog("SetStealCompat %s ref=%d keepN=%d",
            now > 0 and "ON" or "OFF", now, stealKeepLimit())
    end
    return now
end
M.setStealCompat = M.SetStealCompat

function M.IsStealCompat()
    return (S.stealCompatRef or 0) > 0
end
