function M.GetStats()
    local left = 0
    for _ in pairs(B.stashMap) do left += 1 end
    local peN = 0
    if type(B.mutedParticleSet) == "table" then
        for pe in pairs(B.mutedParticleSet) do
            if typeof(pe) == "Instance" and pe.Parent then
                peN += 1
            end
        end
    end
    return {
        enabled = S.running,
        plot = S.cachedPlot and S.cachedPlot.Name,
        stats = B.stats,
        stashLeft = left,
        debug = debugOn(),
        version = "v10.23.17-pe-weak",
        eclWaveN = tonumber(S.mutLive.eclWaveN) or 0,
        eclCycleNew = tonumber(S.mutLive.eclCycleNew) or 0,
        eclCount = tonumber(S.mutLive.eclCount) or 0,
        eclSessionNew = tonumber((G.__GAG2_ECL_STATS and G.__GAG2_ECL_STATS.sessionNew) or 0) or 0,
        gameHbOff = tonumber(B.gameHbOff) or 0,
        particlesOff = peN,
        u3Ok = type(getFvcU3()) == "table",
        mutLiveReady = S.mutLive.ready == true,
        eclipsePosTopN = tonumber(CONFIG.eclipsePosTopN) or 10,
        eclipsePosInterval = tonumber(CONFIG.eclipsePosInterval) or 1,
        eclipsePosRefillBelow = tonumber(CONFIG.eclipsePosRefillBelow) or 5,
        posReportLastN = tonumber(S.mutLive.posReportLastN) or 0,
        posWaveClean = tonumber(S.mutLive.posWaveClean) or 0,
        posLoopRunning = S.mutLive.posLoopRunning == true,
        mutLiveStamped = tonumber(S.mutLive.liveStamped) or 0,
        fpsCap = CONFIG.fpsCap,
        plantStripQueue = #Q.plantStrip,
        visualBlockActive = S.visualBlockActive,
        blocked = B.statsBlocked,
        prunedFruits = S.statsPrunedFruits,
        fruitShellQueue = #Q.fruitShell,
        farPaused = S.farPaused == true,
