-- Job timer untuk debug HUD (tanpa local baru — limit 200)
G.__GAG2_RF_WRAP = function(name, fn)
    if type(fn) ~= "function" then return fn end
    return function(...)
        local n = select("#", ...)
        local a1, a2, a3, a4, a5 = ...
        if n <= 0 then
            return G.__GAG2_RF_JOB(name, fn)
        elseif n == 1 then
            return G.__GAG2_RF_JOB(name, function()
                return fn(a1)
            end)
        elseif n == 2 then
            return G.__GAG2_RF_JOB(name, function()
                return fn(a1, a2)
            end)
        elseif n == 3 then
            return G.__GAG2_RF_JOB(name, function()
                return fn(a1, a2, a3)
            end)
        elseif n == 4 then
            return G.__GAG2_RF_JOB(name, function()
                return fn(a1, a2, a3, a4)
            end)
        end
        return G.__GAG2_RF_JOB(name, function()
            return fn(a1, a2, a3, a4, a5)
        end)
    end
end
