function M.GetLockedPos()
    return lockedPos
end

function M.LockAt(pos)
    if typeof(pos) ~= "Vector3" then return false end
    local hrp = getHRP()
    local hum = getHum()
    if not hrp or not hum or hum.Health <= 0 then return false end

    if flyRestore.platformStand == nil then
        flyRestore.platformStand = hum.PlatformStand
        flyRestore.autoRotate = hum.AutoRotate
    end

    lockedPos = pos
    M.SetNoclip(true)
    applySoftLock(hrp, hum, pos)

    if not lockConn then
        lockConn = RunService.Heartbeat:Connect(function()
            if typeof(lockedPos) ~= "Vector3" then return end
            hrp = getHRP()
            hum = getHum()
            if not hrp or not hum or hum.Health <= 0 then return end
            applySoftLock(hrp, hum, lockedPos)
        end)
    end
    return true
end

function M.MoveLock(pos)
    return M.LockAt(pos)
end

function M.Unlock()
    stopLockLoop()
    lockedPos = nil
    M.SetNoclip(false)
    restoreHumanoid()
end

local function surfaceSafePos(fromPos)
    if typeof(fromPos) ~= "Vector3" then
        local hrp = getHRP()
        fromPos = hrp and hrp.Position or Vector3.zero
    end
    local origin = Vector3.new(fromPos.X, fromPos.Y + 200, fromPos.Z)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local char = LP.Character
    if char then
        params.FilterDescendantsInstances = { char }
    end
    local hit = workspace:Raycast(origin, Vector3.new(0, -500, 0), params)
    if hit then
        return hit.Position + Vector3.new(0, 5, 0)
    end
    return Vector3.new(fromPos.X, math.max(fromPos.Y, 5) + 8, fromPos.Z)
