-- Hanya kalau sedang lock/noclip. Idle → no-op (penting saat load + toggle off)
function M.ReleaseToSurface()
    if not M.IsLocked() and not M.IsNoclipEnabled() then
        return false
    end
    local from = lockedPos
    local hrp = getHRP()
    if not from and hrp then from = hrp.Position end
    local safe = surfaceSafePos(from)
    M.SetNoclip(true)
    applySoftLock(getHRP(), getHum(), safe)
    task.wait()
    stopLockLoop()
    lockedPos = nil
    M.SetNoclip(false)
    restoreHumanoid()
    return true
