    { key = "Move",                    name = "Move",                    factory = function() -- Move.lua — global travel / teleport helpers (GAG2)
-- Mode UI: MISC → ⚙ → Character → Move Mode (G.MOVE_MODE)
--   soft | step | walk | hard
-- Garden AutoTele loop (center/spawn) tetap di AutoTele.lua — travel pakai Move mode
-- TeleportButton Garden/Sell dipakai otomatis saat jauh (bukan pilihan UI)
--
-- Priority lock (anti tabrakan): 1 travel aktif.
-- Prioritas lebih tinggi bisa preempt; lebih rendah → return false,"busy" (tanpa antrian spam).

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G
local M = {}

----------------------------------------------------------------
-- Loading gate — jangan travel sebelum LoadingScreenDone
----------------------------------------------------------------
function M.IsLoadingScreenActive()
    if not LP then return true end
    if LP:GetAttribute("LoadingScreenDone") == true then
        return false
    end
    if LP:GetAttribute("LoadingScreenActive") == true then
        return true
    end
    if workspace:FindFirstChild("LoadingScreenMenu") ~= nil then
        return true
    end
    return true
end

function M.WaitUntilLoaded(timeoutSec)
    timeoutSec = tonumber(timeoutSec) or 120
    local t0 = os.clock()
    while M.IsLoadingScreenActive() do
        if (os.clock() - t0) >= timeoutSec then
            return false
        end
        task.wait(0.25)
    end
    return true
end

----------------------------------------------------------------
-- Mode list (single source of truth for UI)
----------------------------------------------------------------
M.MODE_ITEMS = {
    { key = "soft", name = "Soft" },
    { key = "step", name = "Step" },
    { key = "walk", name = "Walk" },
    { key = "hard", name = "Hard" },
}

local VALID_MODES = {
    soft = true,
    step = true,
    walk = true,
    hard = true,
}

-- Tunable defaults (soft / step / walk) — hard tidak pakai speed
local DEFAULT_SOFT_SPEED = 30
local DEFAULT_STEP_SPEED = 30
local DEFAULT_WALK_SPEED = 30
local SOFT_MAX_SEC = 8.0
local ARRIVE_OK = 4
local HOLD_CHECK = 0.35
local STEP_WAIT = 0.05
local WALK_TIMEOUT = 12
local GARDEN_TP_OFFSET = Vector3.new(0, 3, 0)
local GARDEN_NEAR_RADIUS = 55
local SELL_ARRIVE = 28
local DEFAULT_UNDER_Y = -7

local speeds = {
    soft = DEFAULT_SOFT_SPEED,
    step = DEFAULT_STEP_SPEED,
    walk = DEFAULT_WALK_SPEED,
}

local noclipConns = {}
local groundGuardConn = nil
local busy = false
local pauseDepth = 0
local teleWasOn = false
local pauseReason = nil

----------------------------------------------------------------
-- Priority lock (single holder, no queue spam)
-- Higher number = more important. Infer reason from PauseAutoTele when set.
----------------------------------------------------------------
local MOVE_PRIORITY = {
    steal = 100,
    steal_return = 100,
    steal_night = 100,
    steal_start = 100,
    steal_quest_done = 100,
    steal_orbit = 100,
    plot_back = 100, -- orbit belakang garden (sama prio steal)
    plot_back_corner = 100, -- siku BL/BR orbit_plot_back
    steal_range = 100,
    buy = 90,
    buy_pet = 90,
    auction = 90,
    claim = 80,
    claim_seed = 80,
    claim_drop = 80,
    guard = 75,
    autoguard = 75,
    drop = 70,
    gift = 70,
    normal_gift = 70,
    kill = 60,
    brew = 55,
    water = 50,
    watering = 50,
    sprinkler_other = 40,
    dragon_egg = 30,
    dragon = 30,
    move = 20,
    tele = 10,
    autotele = 10,
}

local lock = {
    busy = false,
    reason = nil,
    priority = 0,
    gen = 0,
}
-- Session hold: blokir travel prioritas lebih rendah ANTARA GoTo
-- (steal malam tetap pegang kontrol meski lagi fire prompt, bukan travel).
local session = {
    active = false,
    reason = nil,
    priority = 0,
}
local moveGen = 0

local function sameOwnerFamily(a, b)
    a = string.lower(tostring(a or ""))
    b = string.lower(tostring(b or ""))
    if a == "" or b == "" then return false end
    if a == b then return true end
    local pa = string.match(a, "^([a-z]+)")
    local pb = string.match(b, "^([a-z]+)")
    return pa ~= nil and pa == pb
end

function M.PriorityOf(reason)
    local key = string.lower(tostring(reason or "move"))
    -- steal_* / buy_* → fallback ke prefix utama
    local pri = MOVE_PRIORITY[key]
    if pri ~= nil then return pri end
    local prefix = string.match(key, "^([a-z]+)")
    if prefix and MOVE_PRIORITY[prefix] ~= nil then
        return MOVE_PRIORITY[prefix]
    end
    return MOVE_PRIORITY.move
end

function M.IsBusy()
    return lock.busy == true or busy == true or session.active == true
end

function M.CurrentHolder()
    if lock.busy then
        return lock.reason, lock.priority
    end
    if session.active then
        return session.reason, session.priority
    end
    return nil, 0
end

function M.GetSessionHold()
    if not session.active then
        return nil, 0
    end
    return session.reason, session.priority
end

-- Hold sesi (bukan travel aktif). Lower priority → beginTravel return busy.
function M.HoldSession(reason, priority)
    reason = tostring(reason or "move")
    local pri = tonumber(priority)
    if pri == nil then
        pri = M.PriorityOf(reason)
    end
    if session.active then
        if pri < session.priority then
            return false, "busy"
        end
        if pri == session.priority and not sameOwnerFamily(reason, session.reason) then
            return false, "busy"
        end
    end
    session.active = true
    session.reason = reason
    session.priority = pri
    return true
end

function M.ReleaseSession(reason)
    if not session.active then return end
    if reason ~= nil and tostring(reason) ~= "" then
        if not sameOwnerFamily(reason, session.reason) then
            return
        end
    end
    session.active = false
    session.reason = nil
    session.priority = 0
end

-- true kalau caller harus yield ke holder prioritas lebih tinggi
function M.ShouldYield(reason, priority)
    local pri = tonumber(priority)
    if pri == nil then
        pri = M.PriorityOf(reason or "move")
    end
    if session.active and session.priority > pri then
        return true, session.reason
    end
    if lock.busy and lock.priority > pri then
        return true, lock.reason
    end
    return false, nil
end

local function resolveTravelReason(opts, fallback)
    opts = type(opts) == "table" and opts or {}
    if opts.reason ~= nil and tostring(opts.reason) ~= "" then
        return tostring(opts.reason)
    end
    if opts.owner ~= nil and tostring(opts.owner) ~= "" then
        return tostring(opts.owner)
    end
    if type(pauseReason) == "string" and pauseReason ~= "" then
        return pauseReason
    end
    return fallback or "tele"
end

-- beginTravel → ok, gen | false, "busy"
local function beginTravel(opts, fallbackReason)
    opts = type(opts) == "table" and opts or {}
    if opts.skipLock == true or opts._internal == true then
        moveGen += 1
        return true, moveGen
    end

    local reason = resolveTravelReason(opts, fallbackReason)
    local pri = tonumber(opts.priority)
    if pri == nil then
        pri = M.PriorityOf(reason)
    end

    -- Session hold (steal malam, dll): blokir prioritas lebih rendah
    if session.active and pri < session.priority then
        return false, "busy"
    end
    if session.active and pri == session.priority and not sameOwnerFamily(reason, session.reason) then
        return false, "busy"
    end

    if lock.busy then
        if pri > lock.priority then
            -- Preempt lower-priority travel (loops check gen)
            moveGen += 1
            lock.gen = moveGen
            lock.busy = false
            busy = false
        elseif pri == lock.priority and sameOwnerFamily(reason, lock.reason) then
            -- Same owner family: replace previous travel
            moveGen += 1
            lock.gen = moveGen
            lock.busy = false
            busy = false
        else
            return false, "busy"
        end
    end

    moveGen += 1
    lock.busy = true
    lock.reason = reason
    lock.priority = pri
    lock.gen = moveGen
    busy = true
    return true, lock.gen
end

local function endTravel(gen)
    if gen == nil then
        lock.busy = false
        lock.reason = nil
        lock.priority = 0
        busy = false
        return
    end
    if gen ~= lock.gen then
        return -- preempted; newer holder owns lock
    end
    lock.busy = false
    lock.reason = nil
    lock.priority = 0
    busy = false
end

local function isCancelled(gen)
    return gen == nil or gen ~= lock.gen
end

function M.TryAcquire(reason, priority)
    return beginTravel({ reason = reason, priority = priority }, reason or "move")
end

function M.Release(gen)
    endTravel(gen)
end

local function clampSoftSpeed(n)
    n = math.floor(tonumber(n) or DEFAULT_SOFT_SPEED)
    if n < 1 then n = 1 end
    if n > 300 then n = 300 end
    return n
end

local function clampStepSpeed(n)
    n = math.floor(tonumber(n) or DEFAULT_STEP_SPEED)
    if n < 1 then n = 1 end
    if n > 400 then n = 400 end
    return n
end

local function clampWalkSpeed(n)
    n = math.floor(tonumber(n) or DEFAULT_WALK_SPEED)
    if n < 1 then n = 1 end
    if n > 200 then n = 200 end
    return n
end

function M.GetSpeeds()
    -- Prioritas: global UI → MAIN → cache internal
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local cfg = (type(MAIN) == "table" and type(MAIN.misc) == "table" and MAIN.misc.character) or nil
    local soft = G.MOVE_SOFT_SPEED
    if soft == nil then soft = rawget(_G, "MOVE_SOFT_SPEED") end
    if soft == nil and type(cfg) == "table" then soft = cfg.soft_speed end
    if soft == nil then soft = speeds.soft end

    local step = G.MOVE_STEP_SPEED
    if step == nil then step = rawget(_G, "MOVE_STEP_SPEED") end
    if step == nil and type(cfg) == "table" then step = cfg.step_speed end
    if step == nil then step = speeds.step end

    local walk = G.MOVE_WALK_SPEED
    if walk == nil then walk = rawget(_G, "MOVE_WALK_SPEED") end
    if walk == nil and type(cfg) == "table" then walk = cfg.walk_speed end
    if walk == nil then walk = speeds.walk end

    return {
        soft = clampSoftSpeed(soft),
        step = clampStepSpeed(step),
        walk = clampWalkSpeed(walk),
    }
end

function M.SetSpeeds(tbl)
    tbl = type(tbl) == "table" and tbl or {}
    if tbl.soft ~= nil then speeds.soft = clampSoftSpeed(tbl.soft) end
    if tbl.step ~= nil then speeds.step = clampStepSpeed(tbl.step) end
    if tbl.walk ~= nil then speeds.walk = clampWalkSpeed(tbl.walk) end
    G.MOVE_SOFT_SPEED = speeds.soft
    _G.MOVE_SOFT_SPEED = speeds.soft
    G.MOVE_STEP_SPEED = speeds.step
    _G.MOVE_STEP_SPEED = speeds.step
    G.MOVE_WALK_SPEED = speeds.walk
    _G.MOVE_WALK_SPEED = speeds.walk
    return M.GetSpeeds()
end

function M.ModesWithSpeed()
    return { "soft", "step", "walk" }
end

----------------------------------------------------------------
-- Basics
----------------------------------------------------------------
function M.NormalizeMode(mode)
    mode = tostring(mode or "walk"):lower()
    if mode == "button" then return "walk" end -- legacy
    if VALID_MODES[mode] then return mode end
    return "walk"
end

function M.GetMode()
    local mode = G.MOVE_MODE or G.CHARACTER_MOVE_MODE
        or rawget(_G, "MOVE_MODE") or rawget(_G, "CHARACTER_MOVE_MODE")
    if mode == nil then
        local MAIN = rawget(_G, "MAIN") or G.MAIN
        local cfg = MAIN and MAIN.misc and MAIN.misc.character
        if type(cfg) == "table" then mode = cfg.move_mode end
    end
    return M.NormalizeMode(mode)
end

function M.SetMode(mode)
    mode = M.NormalizeMode(mode)
    G.MOVE_MODE = mode
    _G.MOVE_MODE = mode
    G.CHARACTER_MOVE_MODE = mode
    _G.CHARACTER_MOVE_MODE = mode
    return mode
end

function M.GetModeItems()
    return M.MODE_ITEMS
end

function M.GetChar()
    return LP and LP.Character
end

function M.GetHRP(char)
    char = char or M.GetChar()
    if not char then return nil end
    local hrp = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
    return hrp and hrp:IsA("BasePart") and hrp or nil
end

function M.GetHum(char)
    char = char or M.GetChar()
    return char and char:FindFirstChildOfClass("Humanoid") or nil
end

function M.ResolveGoal(goal)
    if typeof(goal) == "CFrame" then
        return goal
    elseif typeof(goal) == "Vector3" then
        return CFrame.new(goal)
    elseif typeof(goal) == "Instance" then
        if goal:IsA("BasePart") then
            return goal.CFrame
        elseif goal:IsA("Model") then
            return goal:GetPivot()
        elseif goal:IsA("Attachment") then
            return goal.WorldCFrame
        end
    elseif type(goal) == "table" and goal.X and goal.Y and goal.Z then
        return CFrame.new(goal.X, goal.Y, goal.Z)
    end
    return nil
end

function M.Distance(a, b)
    local pa = typeof(a) == "CFrame" and a.Position or a
    local pb = typeof(b) == "CFrame" and b.Position or b
    if typeof(pa) ~= "Vector3" or typeof(pb) ~= "Vector3" then return math.huge end
    return (pa - pb).Magnitude
end

local function setPos(char, hrp, cf)
    pcall(function()
        if char.PrimaryPart then
            char:PivotTo(cf)
        else
            hrp.CFrame = cf
        end
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)
end

function M.ZeroVelocity(hrp)
    hrp = hrp or M.GetHRP()
    if not hrp then return end
    pcall(function()
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)
end

function M.SetCFrame(cf, opts)
    opts = type(opts) == "table" and opts or {}
    if typeof(cf) ~= "CFrame" then return false end

    local gen = opts._gen
    local acquired = false
    if opts.skipLock ~= true and opts._internal ~= true then
        local okLock, genOrErr = beginTravel(opts, "move")
        if not okLock then
            return false
        end
        gen = genOrErr
        acquired = true
    end

    if gen and isCancelled(gen) then
        if acquired then endTravel(gen) end
        return false
    end

    local char = M.GetChar()
    local hrp = M.GetHRP(char)
    if not char or not hrp then
        if acquired then endTravel(gen) end
        return false
    end
    setPos(char, hrp, cf)
    if opts.zeroVelocity ~= false then
        M.ZeroVelocity(hrp)
    end
    local waitSec = tonumber(opts.wait)
    if waitSec and waitSec > 0 then
        task.wait(waitSec)
    end
    if acquired then endTravel(gen) end
    return true
end

----------------------------------------------------------------
-- Noclip (session)
-- CanCollide off = tembus plant/dinding, tapi Humanoid tak punya lantai
-- → stick ground (raycast) supaya walk tidak jatuh tembus tanah / tenggelam di pagar.
----------------------------------------------------------------
local function _isFenceLikePart(inst)
    if not inst then return true end
    local n = string.lower(tostring(inst.Name or ""))
    if n:find("fence", 1, true) or n:find("rail", 1, true) or n:find("barrier", 1, true)
        or n:find("gate", 1, true) or n:find("wall", 1, true) or n:find("post", 1, true)
        or n:find("pole", 1, true) or n:find("rope", 1, true) or n:find("hedge", 1, true)
    then
        return true
    end
    -- Part tipis/vertikal = pagar/dinding, bukan lantai
    if inst:IsA("BasePart") then
        local s = inst.Size
        if s.Y > 2 and math.min(s.X, s.Z) < 1.25 then
            return true
        end
    end
    return false
end

local STAND_ABOVE_GROUND = 4 -- HRP di atas permukaan (simple, jangan HipHeight ribet)

-- Ray dari sedikit di atas HRP ke BAWAH (bukan dari langit).
-- Kalau dari Y+80, di map multi-layer kena lantai atas → karakter ke "langit".
-- Skip pagar/dinding (fence-like / Normal tidak horizontal) supaya stick Y pakai lantai asli.
local function rayTopGround(hrp, char)
    if not hrp then return nil end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local exclude = { char or hrp }
    params.FilterDescendantsInstances = exclude
    params.IgnoreWater = true
    local origin = hrp.Position + Vector3.new(0, 2.5, 0)
    local remaining = 40
    for _ = 1, 8 do
        if remaining <= 0.1 then
            return nil
        end
        local hit = workspace:Raycast(origin, Vector3.new(0, -remaining, 0), params)
        if not hit then
            return nil
        end
        local inst = hit.Instance
        if _isFenceLikePart(inst) or hit.Normal.Y < 0.35 then
            exclude[#exclude + 1] = inst
            params.FilterDescendantsInstances = exclude
            local consumed = origin.Y - hit.Position.Y
            remaining = remaining - consumed - 0.05
            origin = hit.Position + Vector3.new(0, -0.05, 0)
        else
            return hit
        end
    end
    return nil
end

-- Walk + noclip: CanCollide off → bisa tembus lantai.
-- HANYA koreksi kalau HRP sudah di BAWAH permukaan (benar-benar tenggelam).
-- Jangan angkat ke STAND_ABOVE_GROUND tiap frame — itu bikin naik-turun + MoveTo mati
-- (gejala Auto Buy Pet: TP garden lalu diam).
local function stickWalkGround(hrp, char)
    if not hrp then return end
    local hit = rayTopGround(hrp, char)
    if not hit then return end
    local floorY = hit.Position.Y
    local pos = hrp.Position
    local v = hrp.AssemblyLinearVelocity

    -- Masih di atas lantai → jangan sentuh CFrame (biar Humanoid:MoveTo jalan)
    if pos.Y >= floorY + 1.25 then
        if v.Y < -8 then
            hrp.AssemblyLinearVelocity = Vector3.new(v.X, 0, v.Z)
        end
        return
    end

    local wantY = floorY + STAND_ABOVE_GROUND
    if wantY - pos.Y > 10 then return end
    local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
    pcall(function()
        local horiz = Vector3.new(v.X, 0, v.Z)
        local cf = CFrame.new(pos.X, wantY, pos.Z) * CFrame.Angles(0, yaw, 0)
        if char and char.PrimaryPart then
            char:PivotTo(cf)
        else
            hrp.CFrame = cf
        end
        hrp.AssemblyLinearVelocity = horiz
    end)
end

local function standYFromHit(hrp, hum, hit)
    if not hit then return nil end
    return hit.Position.Y + STAND_ABOVE_GROUND
end

function M.GetGroundStandY(hrp, hum, char)
    hrp = hrp or M.GetHRP()
    char = char or M.GetChar()
    local hit = rayTopGround(hrp, char)
    return standYFromHit(hrp, hum, hit)
end

-- Hanya angkat kalau tenggelam di bawah permukaan di dekat kaki. Jangan tarik naik jauh.
function M.SnapToGround()
    local char = M.GetChar()
    local hrp = M.GetHRP(char)
    local hum = M.GetHum(char)
    if not char or not hrp then return false end
    local hit = rayTopGround(hrp, char)
    if not hit then return false end
    local floorY = hit.Position.Y
    -- Sudah di atas lantai → jangan sentuh (anti naik-turun / freeze MoveTo)
    if hrp.Position.Y >= floorY + 1.25 then
        return false
    end
    local wantY = floorY + STAND_ABOVE_GROUND
    -- Jangan angkat lebih dari ~8 stud (bukan teleport ke layer lain)
    if wantY - hrp.Position.Y > 8 then
        return false
    end
    local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
    local v = hrp.AssemblyLinearVelocity
    pcall(function()
        local cf = CFrame.new(hrp.Position.X, wantY, hrp.Position.Z) * CFrame.Angles(0, yaw, 0)
        if char.PrimaryPart then
            char:PivotTo(cf)
        else
            hrp.CFrame = cf
        end
        hrp.AssemblyLinearVelocity = Vector3.new(v.X, 0, v.Z)
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)
    pcall(function()
        if hum then
            hum.PlatformStand = false
            hrp.Anchored = false
        end
    end)
    return true
end

-- Guard anti-tenggelam: HANYA kalau masuk ke dalam/bawah lantai di bawah kaki
local travelBusy = false -- true saat GoTo jalan → jangan ganggu animasi walk

local function _groundGuardTick()
    if travelBusy then return end
    local char = M.GetChar()
    local hrp = M.GetHRP(char)
    if not char or not hrp then return end
    if hrp.Anchored then return end
    local hit = rayTopGround(hrp, char)
    if not hit then return end
    local wantY = hit.Position.Y + STAND_ABOVE_GROUND
    -- Tenggelam = HRP di bawah permukaan lantai yang kena ray dari kaki
    if hrp.Position.Y < hit.Position.Y + 1 then
        if wantY - hrp.Position.Y > 8 then return end
        local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
        setPos(char, hrp, CFrame.new(hrp.Position.X, wantY, hrp.Position.Z) * CFrame.Angles(0, yaw, 0))
        local v = hrp.AssemblyLinearVelocity
        if v.Y < 0 then
            hrp.AssemblyLinearVelocity = Vector3.new(v.X, 0, v.Z)
        end
    end
end

function M.IsGroundGuard()
    return groundGuardConn ~= nil
end

function M.StartGroundGuard()
    if groundGuardConn then return true end
    groundGuardConn = RunService.Heartbeat:Connect(_groundGuardTick)
    G.__GAG2_GROUND_GUARD = true
    _G.__GAG2_GROUND_GUARD = true
    return true
end

function M.StopGroundGuard()
    if groundGuardConn then
        pcall(function() groundGuardConn:Disconnect() end)
        groundGuardConn = nil
    end
    G.__GAG2_GROUND_GUARD = false
    _G.__GAG2_GROUND_GUARD = false
end

----------------------------------------------------------------
-- Under-plot rescue
-- Walk noclip / glitch → jatuh ke bawah deck garden (lihat underside).
-- HANYA rescue kalau benar-benar di bawah lantai (ray UP kena underside
-- floor-like). Jangan pakai GetBoundingBox plot (buah/pohon bikin surface
-- Y salah → spam Fire Garden → Auto Buy Pet / steal mati).
----------------------------------------------------------------
local UNDER_PLOT_BELOW_Y = 18
local UNDER_PLOT_RAY_UP = 120
local UNDER_PLOT_CHECK_SEC = 0.5
local UNDER_PLOT_COOLDOWN = 8
local underPlotConn = nil
local underPlotBusy = false
local lastUnderCheckAt = 0
local lastUnderRescueAt = 0
local lastUnderWhy = ""

local function _isFloorLikePart(inst)
    if not inst or not inst:IsA("BasePart") then return false end
    local n = string.lower(tostring(inst.Name or ""))
    if n:find("floor", 1, true) or n:find("ground", 1, true) or n:find("island", 1, true)
        or n:find("deck", 1, true) or n:find("soil", 1, true) or n:find("grass", 1, true)
        or n:find("plot", 1, true) or n:find("baseplate", 1, true) or n:find("platform", 1, true)
        or n:find("terrain", 1, true) or n:find("farm", 1, true)
    then
        return true
    end
    local s = inst.Size
    -- Deck plot biasanya lebar + relatif pipih (bukan batang pohon)
    if s.Y <= 8 and math.min(s.X, s.Z) >= 14 then
        return true
    end
    return false
end

local function _underPlantFolder(inst, plot)
    if not inst or not plot then return false end
    local plants = plot:FindFirstChild("Plants")
    if plants and inst:IsDescendantOf(plants) then return true end
    if inst:GetAttribute("FruitId") ~= nil or inst:GetAttribute("PlantId") ~= nil then
        return true
    end
    local cur = inst.Parent
    while cur and cur ~= plot do
        if cur:IsA("Model") then
            if cur:GetAttribute("FruitId") ~= nil or cur:GetAttribute("PlantId") ~= nil then
                return true
            end
        end
        cur = cur.Parent
    end
    return false
end

-- Surface Y: spawn / garden CF saja — JANGAN GetBoundingBox (tinggi karena tanaman).
local function _ownPlotSurfaceY(plot)
    plot = plot or M.GetPlayerPlot()
    if not plot then return nil end
    local spawn = plot:FindFirstChild("Spawn", true)
        or plot:FindFirstChild("SpawnLocation", true)
        or plot:FindFirstChild("SpawnPoint", true)
        or plot:FindFirstChild("GardenSpawn", true)
    if spawn and spawn:IsA("BasePart") then
        return spawn.Position.Y + spawn.Size.Y * 0.5
    end
    local gcf = M.GetGardenCFrame()
    if typeof(gcf) == "CFrame" then
        return gcf.Position.Y - (GARDEN_TP_OFFSET.Y or 3)
    end
    return nil
end

local function _buyPetActive()
    if G.__GAG2_AUTO_BUY_PET_BUSY == true or rawget(_G, "__GAG2_AUTO_BUY_PET_BUSY") == true then
        return true
    end
    local ABP = G.AutoBuyPet or G.AutoBuyPetModule or rawget(_G, "AutoBuyPet")
    if type(ABP) == "table" and type(ABP.GetStatus) == "function" then
        local ok, st = pcall(ABP.GetStatus, ABP)
        if ok and type(st) == "table" and st.buyBusy == true then
            return true
        end
    end
    return false
end

local function _shouldSkipUnderRescue()
    if underPlotBusy then return true end
    if M.IsLoadingScreenActive() then return true end
    -- Jangan ganggu Auto Buy Pet / Auto Steal (Fire Garden bikin fitur mati)
    if _buyPetActive() then return true end
    if G.__GAG2_AUTO_STEAL_BUSY == true or rawget(_G, "__GAG2_AUTO_STEAL_BUSY") == true then
        return true
    end
    if session.active then
        local r = tostring(session.reason or "")
        if r == "buy_pet" or r == "buy" or r:find("steal", 1, true) then
            return true
        end
    end
    if lock.busy then
        local r = tostring(lock.reason or "")
        if r == "buy_pet" or r == "buy" or r:find("steal", 1, true) then
            return true
        end
    end
    return false
end

function M.IsUnderPlot(hrp, char)
    hrp = hrp or M.GetHRP()
    char = char or M.GetChar()
    if not hrp then return false, nil end
    if M.IsLoadingScreenActive() then return false, nil end

    local plot = M.GetPlayerPlot()
    local gardens = workspace:FindFirstChild("Gardens")
    local pos = hrp.Position
    local surfY = _ownPlotSurfaceY(plot)

    -- Wajib: ray ke atas kena underside lantai (Normal ke bawah)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { char or hrp }
    params.IgnoreWater = true
    local hit = workspace:Raycast(pos, Vector3.new(0, UNDER_PLOT_RAY_UP, 0), params)
    if not hit or hit.Normal.Y >= -0.35 then
        return false, nil
    end

    local inst = hit.Instance
    if not _isFloorLikePart(inst) then
        return false, nil
    end
    if plot and _underPlantFolder(inst, plot) then
        return false, nil
    end

    local inOwnPlot = plot and inst:IsDescendantOf(plot)
    local inGardens = gardens and inst:IsDescendantOf(gardens)
    if not inOwnPlot and not inGardens then
        return false, nil
    end

    -- Harus benar-benar di bawah permukaan hit (bukan cuma di bawah atap/kanopi tipis)
    local underDeck = pos.Y < (hit.Position.Y - 4)
    if not underDeck then
        return false, nil
    end
    -- Kalau punya surface spawn: harus jauh di bawahnya
    if surfY and pos.Y > (surfY - UNDER_PLOT_BELOW_Y) then
        return false, nil
    end

    lastUnderWhy = inOwnPlot and "under_own_underside" or "under_garden_floor"
    return true, lastUnderWhy
end

function M.GetUnderPlotWhy()
    return lastUnderWhy
end

function M.RescueUnderPlot(why)
    if _shouldSkipUnderRescue() then return false, "skip" end
    if (os.clock() - lastUnderRescueAt) < UNDER_PLOT_COOLDOWN then
        return false, "cooldown"
    end

    -- Double-check masih stuck (hindari race dengan buy pet)
    local stuck = select(1, M.IsUnderPlot())
    if not stuck then return false, "not_stuck" end

    underPlotBusy = true
    lastUnderRescueAt = os.clock()
    lastUnderWhy = tostring(why or lastUnderWhy or "rescue")
    M.SetNoclip(false)
    M.StopGroundGuard()

    local ok, msg = false, "fail"
    local fired = false
    pcall(function()
        fired = M.FireTeleportButton("Garden") == true
    end)
    if fired then
        ok, msg = true, "garden_button"
    else
        local ok2, msg2 = false, "no_button"
        pcall(function()
            ok2, msg2 = M.ToGarden({ fineTune = false, buttonWait = 2.5 })
        end)
        ok, msg = ok2 == true, tostring(msg2 or "to_garden")
    end

    task.wait(0.25)
    if select(1, M.IsUnderPlot()) then
        local cf = M.GetGardenCFrame()
        if typeof(cf) == "CFrame" then
            pcall(function()
                M.SetNoclip(true)
                M.SetCFrame(cf, { skipLock = true, _internal = true })
                M.SetNoclip(false)
                M.SnapToGround()
            end)
            ok, msg = true, "hard_fallback"
        end
    end

    underPlotBusy = false
    return ok, msg
end

function M.IsUnderPlotRescue()
    return underPlotConn ~= nil
end

function M.StartUnderPlotRescue()
    if underPlotConn then return true end
    underPlotConn = RunService.Heartbeat:Connect(function()
        if _shouldSkipUnderRescue() then return end
        local t = os.clock()
        if (t - lastUnderCheckAt) < UNDER_PLOT_CHECK_SEC then return end
        lastUnderCheckAt = t
        if (t - lastUnderRescueAt) < UNDER_PLOT_COOLDOWN then return end

        local stuck, why = M.IsUnderPlot()
        if not stuck then return end
        task.spawn(function()
            M.RescueUnderPlot(why)
        end)
    end)
    G.__GAG2_UNDER_PLOT_RESCUE = true
    _G.__GAG2_UNDER_PLOT_RESCUE = true
    return true
end

function M.StopUnderPlotRescue()
    if underPlotConn then
        pcall(function() underPlotConn:Disconnect() end)
        underPlotConn = nil
    end
    G.__GAG2_UNDER_PLOT_RESCUE = false
    _G.__GAG2_UNDER_PLOT_RESCUE = false
end

function M.IsNoclip()
    return #noclipConns > 0
end

function M.SetNoclip(on)
    if on == true and #noclipConns > 0 then
        return -- sudah ON — jangan reconnect tiap frame (bikin nabrak)
    end
    for _, c in ipairs(noclipConns) do
        pcall(function() c:Disconnect() end)
    end
    table.clear(noclipConns)
    pcall(function()
        RunService:UnbindFromRenderStep("GAG2_MoveNoclip")
    end)
    if on ~= true then return end

    local char = M.GetChar()
    if not char then return end

    local parts = {}
    local function refreshParts(c)
        table.clear(parts)
        for _, p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") then
                parts[#parts + 1] = p
            end
        end
    end
    refreshParts(char)
    local lastRefresh = os.clock()

    local function applyNoCollide()
        local c = M.GetChar()
        if not c then return end
        if c ~= char or (os.clock() - lastRefresh) > 0.75 then
            char = c
            refreshParts(c)
            lastRefresh = os.clock()
        end
        for i = 1, #parts do
            local p = parts[i]
            if p and p.Parent then
                p.CanCollide = false
                p.CanTouch = false
            end
        end
    end

    table.insert(noclipConns, RunService.Stepped:Connect(applyNoCollide))
    pcall(function()
        RunService:BindToRenderStep("GAG2_MoveNoclip", Enum.RenderPriority.Character.Value - 1, applyNoCollide)
    end)
end

----------------------------------------------------------------
-- AutoTele pause / resume (shared by claim/buy/water/drop/…)
----------------------------------------------------------------
function M.GetAutoTele()
    return G.AutoTele or rawget(_G, "AutoTele")
end

function M.AutoTeleIsOn()
    local mod = M.GetAutoTele()
    if type(mod) == "table" then
        if type(mod.IsEnabled) == "function" and mod.IsEnabled() == true then
            return true
        end
        -- Hit WW saja (Guard OFF) tetap dianggap "on" biar Pause/Resume tidak drop
        if type(mod.IsHitWerewolfEnabled) == "function" and mod.IsHitWerewolfEnabled() == true then
            return true
        end
    end
    local s = rawget(_G, "__GAG2_AUTO_TELE") or G.__GAG2_AUTO_TELE
    if type(s) == "table" then
        if s.enabled == true or s.hitWerewolf == true then return true end
    end
    return G.AUTO_TELE_ENABLED == true or rawget(_G, "AUTO_TELE_ENABLED") == true
end

function M.AutoTeleWasRunning()
    local mod = M.GetAutoTele()
    if type(mod) == "table" and type(mod.IsRunning) == "function" then
        return mod.IsRunning() == true
    end
    return false
end

function M.IsAutoTelePaused()
    return pauseDepth > 0
end

function M.PauseAutoTele(reason)
    pauseReason = reason or pauseReason or "move"
    if pauseDepth == 0 then
        -- Cukup Auto Tele ENABLED (jangan wajib IsRunning — kalau loop lagi off, tetap pulang garden)
        teleWasOn = M.AutoTeleIsOn() == true
    elseif M.AutoTeleIsOn() then
        teleWasOn = true
    end
    pauseDepth = pauseDepth + 1
    G.__GAG2_AUTO_TELE_SUPPRESS = true
    _G.__GAG2_AUTO_TELE_SUPPRESS = true
    local mod = M.GetAutoTele()
    if type(mod) == "table" and type(mod.Stop) == "function" then
        pcall(mod.Stop, mod)
    end
    return teleWasOn
end


function M.KeepAutoTelePaused()
    if pauseDepth <= 0 then return end
    G.__GAG2_AUTO_TELE_SUPPRESS = true
    _G.__GAG2_AUTO_TELE_SUPPRESS = true
    local mod = M.GetAutoTele()
    if type(mod) == "table" and type(mod.IsRunning) == "function"
        and mod.IsRunning() and type(mod.Stop) == "function" then
        pcall(mod.Stop, mod)
    end
end

function M.ResumeAutoTele()
    if pauseDepth > 0 then
        pauseDepth = pauseDepth - 1
    end
    if pauseDepth > 0 then
        M.KeepAutoTelePaused()
        return
    end

    local resume = teleWasOn
    teleWasOn = false
    pauseReason = nil
    G.__GAG2_AUTO_TELE_SUPPRESS = false
    _G.__GAG2_AUTO_TELE_SUPPRESS = false

    local mod = M.GetAutoTele()
    if type(mod) == "table" and type(mod.ClearSuppress) == "function" then
        pcall(mod.ClearSuppress, mod)
    end
    if not resume then return end
    local shouldStart = false
    if type(mod) == "table" then
        if type(mod.IsEnabled) == "function" and mod.IsEnabled() == true then
            shouldStart = true
        elseif type(mod.IsHitWerewolfEnabled) == "function" and mod.IsHitWerewolfEnabled() == true then
            shouldStart = true
        end
    end
    if shouldStart then
        if type(mod.Start) == "function" then
            pcall(mod.Start, mod)
        elseif type(mod.EnsureRunning) == "function" then
            pcall(mod.EnsureRunning, mod)
        end
    end
end

function M.WithAutoTelePaused(reason, fn)
    if type(reason) == "function" then
        fn = reason
        reason = "move"
    end
    M.PauseAutoTele(reason)
    local ok, a, b, c = pcall(fn)
    M.ResumeAutoTele()
    if not ok then
        error(a)
    end
    return a, b, c
end

----------------------------------------------------------------
-- Garden / Sell helpers
----------------------------------------------------------------
local function matchPlotOwner(v)
    if v == nil or not LP then return false end
    return v == LP.UserId or v == LP.Name
        or tostring(v) == tostring(LP.UserId) or tostring(v) == LP.Name
end

function M.GetPlayerPlot()
    local mod = M.GetAutoTele()
    if type(mod) == "table" and type(mod.GetPlayerPlot) == "function" then
        local ok, plot = pcall(mod.GetPlayerPlot, mod)
        if ok and plot then return plot end
    end

    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens or not LP then return nil end

    local plotId = LP:GetAttribute("PlotId")
    local idStr = plotId ~= nil and tostring(plotId) or nil
    if idStr then
        for _, name in ipairs({ "Plot" .. idStr, idStr, "Plot_" .. idStr }) do
            local plot = gardens:FindFirstChild(name)
            if plot then return plot end
        end
    end

    for _, plot in ipairs(gardens:GetChildren()) do
        if matchPlotOwner(plot:GetAttribute("OwnerId"))
            or matchPlotOwner(plot:GetAttribute("Owner"))
            or matchPlotOwner(plot:GetAttribute("OwnerUserId"))
            or matchPlotOwner(plot:GetAttribute("UserId")) then
            return plot
        end
    end

    local myPlot = LP:GetAttribute("Plot") or LP:GetAttribute("PlotName")
        or LP:GetAttribute("GardenPlot") or LP:GetAttribute("PlotId")
    if myPlot then
        for _, name in ipairs({ tostring(myPlot), "Plot" .. tostring(myPlot), "Plot_" .. tostring(myPlot) }) do
            local plot = gardens:FindFirstChild(name)
            if plot then return plot end
        end
    end
    return nil
end

function M.GetGardenCFrame()
    local mod = M.GetAutoTele()
    if type(mod) == "table" then
        local cf = nil
        if type(mod.ResolveTargetCFrame) == "function" then
            cf = mod.ResolveTargetCFrame()
        elseif type(mod.GetGardenCenterCFrame) == "function" then
            cf = mod.GetGardenCenterCFrame()
        end
        if typeof(cf) == "CFrame" then return cf end
    end

    local plot = M.GetPlayerPlot()
    if not plot then return nil end

    local spawn = plot:FindFirstChild("Spawn", true)
        or plot:FindFirstChild("SpawnLocation", true)
        or plot:FindFirstChild("SpawnPoint", true)
    if spawn and spawn:IsA("BasePart") then
        return spawn.CFrame + GARDEN_TP_OFFSET
    end

    if plot:IsA("Model") then
        local ok, cf = pcall(function() return plot:GetPivot() end)
        if ok and typeof(cf) == "CFrame" then
            return cf + GARDEN_TP_OFFSET
        end
    end
    return nil
end

local BUTTON_AFTER_DELAY = 2 -- jeda setelah Fire Garden (Sell = 0; ToSell sudah poll arrive)

function M.FireTeleportButton(label, afterWait)
    if M.IsLoadingScreenActive() then
        if not M.WaitUntilLoaded(120) then
            return false
        end
    end
    local fired = false
    pcall(function()
        local net = require(ReplicatedStorage:WaitForChild("SharedModules", 5):WaitForChild("Networking", 5))
        local node = net and (net.TeleportButtonRequest or (net.TeleportButton and net.TeleportButton.Request))
        if type(node) == "table" and type(node.Fire) == "function" then
            node:Fire(tostring(label))
            fired = true
        end
    end)
    if fired then
        -- Matikan noclip/guard supaya TP game bisa mendarat normal (bukan float di langit)
        M.StopGroundGuard()
        M.SetNoclip(false)
        local prevBusy = travelBusy
        travelBusy = true
        local w = tonumber(afterWait)
        if w == nil then
            w = (tostring(label) == "Sell") and 0 or BUTTON_AFTER_DELAY
        end
        if w > 0 then
            task.wait(w)
        else
            task.wait(0.35)
        end
        pcall(function()
            local hrp = M.GetHRP()
            local hum = M.GetHum()
            if hrp then
                hrp.Anchored = false
                M.ZeroVelocity(hrp)
            end
            if hum then
                hum.PlatformStand = false
            end
        end)
        M.SetNoclip(false)
        travelBusy = prevBusy
    end
    return fired
end

local function instWorldPos(inst)
    if not inst then return nil end
    if inst:IsA("BasePart") then return inst.Position end
    if inst:IsA("Model") then
        local p = inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart", true)
        return p and p.Position or nil
    end
    if inst:IsA("Attachment") then return inst.WorldPosition end
    return nil
end

local function getSellPart()
    local tp = workspace:FindFirstChild("Teleports")
    local sell = tp and tp:FindFirstChild("Sell")
    if sell then return sell end
    local map = workspace:FindFirstChild("Map")
    local stands = map and map:FindFirstChild("Stands")
    return stands and stands:FindFirstChild("Sell") or nil
end

function M.GetSellPos()
    return instWorldPos(getSellPart())
end

----------------------------------------------------------------
-- Travel modes
----------------------------------------------------------------
local function stillThere(hrp, goalCf, okDist)
    task.wait(HOLD_CHECK)
    if not hrp or not hrp.Parent then return false, math.huge end
    local d = M.Distance(hrp.Position, goalCf.Position)
    return d <= (okDist or ARRIVE_OK), d
end

local function releaseTravelPose(hrp, hum, wasAnchored)
    M.ZeroVelocity(hrp)
    pcall(function()
        if hrp then hrp.Anchored = wasAnchored == true end
    end)
    M.ZeroVelocity(hrp)
    pcall(function()
        if hum then
            hum.PlatformStand = false
            hum.AutoRotate = true
        end
    end)
    -- Noclip OFF setelah travel — biar bisa berdiri normal (jangan float/sliding)
    M.SetNoclip(false)
    M.ZeroVelocity(hrp)
end

-- liveGoal: CFrame/Vector3 = update tujuan; false = batalkan travel; nil = tetap tujuan lama
local function resolveLiveGoal(goalCf, opts)
    opts = type(opts) == "table" and opts or {}
    if type(opts.liveGoal) ~= "function" then
        return goalCf.Position, false
    end
    local ok, g = pcall(opts.liveGoal)
    if not ok then
        return goalCf.Position, false
    end
    if g == false then
        return nil, true -- explicit cancel
    end
    if g == nil then
        return nil, false -- no update
    end
    if typeof(g) == "CFrame" then return g.Position, false end
    if typeof(g) == "Vector3" then return g, false end
    return goalCf.Position, false
end

local function resolveLiveGoalPos(goalCf, opts)
    local pos, cancelled = resolveLiveGoal(goalCf, opts)
    if cancelled then return nil end
    return pos -- may be nil (= keep previous)
end

-- Travel simple: Anchor + CFrame XZ (Y terkunci) = tembus pagar, tidak jatuh
local function goCFrameSlide(goalCf, gen, speed, tag, opts)
    local char = M.GetChar()
    local hrp = M.GetHRP(char)
    local hum = M.GetHum(char)
    if not char or not hrp then return false, "no_char" end
    opts = type(opts) == "table" and opts or {}

    local wasAnchored = hrp.Anchored
    pcall(function()
        if hum then
            if hum.Sit then hum.Sit = false end
            hum.PlatformStand = true
        end
        hrp.Anchored = true
    end)
    M.SetNoclip(true)
    M.ZeroVelocity(hrp)

    local startPos = hrp.Position
    local lockY = startPos.Y -- kunci Y: jangan raycast / jangan jatuh
    local goalPos = goalCf.Position
    local live = type(opts.liveGoal) == "function"
    if live then
        local livePos, cancelledLive = resolveLiveGoal(goalCf, opts)
        if cancelledLive then
            releaseTravelPose(hrp, hum, wasAnchored)
            return false, "cancelled"
        end
        if livePos then goalPos = livePos end
    end
    local flatGoal = Vector3.new(goalPos.X, lockY, goalPos.Z)
    local flatStart = Vector3.new(startPos.X, lockY, startPos.Z)
    local dist = (flatStart - flatGoal).Magnitude
    speed = math.max(tonumber(speed) or 30, 1)
    local duration = math.max(0.05, dist / speed)
    if duration > SOFT_MAX_SEC then duration = SOFT_MAX_SEC end

    local lookFlat = Vector3.new(goalCf.LookVector.X, 0, goalCf.LookVector.Z)
    local lookAt = flatGoal + ((lookFlat.Magnitude > 0.05) and lookFlat.Unit or Vector3.new(0, 0, -1))

    local cancelled = false
    local cancelReason = "preempted"
    local t0 = os.clock()
    local lastLive = 0
    while os.clock() - t0 < duration do
        if isCancelled(gen) or not char.Parent then
            cancelled = true
            break
        end
        hrp = M.GetHRP(char) or hrp
        if not hrp then
            cancelled = true
            break
        end
        if live and (os.clock() - lastLive) >= 0.12 then
            lastLive = os.clock()
            local livePos, cancelledLive = resolveLiveGoal(goalCf, opts)
            if cancelledLive then
                cancelled = true
                cancelReason = "cancelled"
                break
            end
            -- Soft/step: HANYA cancel / update kalau tujuan benar-benar pindah jauh.
            -- Jangan restart lerp tiap frame (liveGoal yang ikut HRP = infinite loop / freeze).
            if livePos then
                local flatNew = Vector3.new(livePos.X, lockY, livePos.Z)
                if (flatNew - flatGoal).Magnitude > 3 then
                    goalPos = livePos
                    flatGoal = flatNew
                    lookAt = flatGoal + ((lookFlat.Magnitude > 0.05) and lookFlat.Unit or Vector3.new(0, 0, -1))
                    flatStart = Vector3.new(hrp.Position.X, lockY, hrp.Position.Z)
                    dist = (flatStart - flatGoal).Magnitude
                    duration = math.max(0.05, dist / speed)
                    if duration > SOFT_MAX_SEC then duration = SOFT_MAX_SEC end
                    t0 = os.clock()
                end
            end
        end
        -- Tetap anchor + noclip tiap frame
        pcall(function()
            hrp.Anchored = true
        end)
        if not M.IsNoclip() then
            M.SetNoclip(true)
        end

        local a = math.clamp((os.clock() - t0) / duration, 0, 1)
        local p = flatStart:Lerp(flatGoal, a)
        p = Vector3.new(p.X, lockY, p.Z)
        setPos(char, hrp, CFrame.lookAt(p, lookAt))
        M.ZeroVelocity(hrp)
        RunService.Heartbeat:Wait()
    end

    if not cancelled then
        hrp = M.GetHRP(char) or hrp
        if hrp then
            setPos(char, hrp, CFrame.lookAt(flatGoal, lookAt))
            M.ZeroVelocity(hrp)
        end
    end
    releaseTravelPose(hrp, hum, wasAnchored)
    if cancelled then return false, cancelReason end
    return true, tag or "soft"
end

local function goSoft(goalCf, gen, opts)
    return goCFrameSlide(goalCf, gen, M.GetSpeeds().soft, "soft", opts)
end

local function goStep(goalCf, gen, opts)
    return goCFrameSlide(goalCf, gen, M.GetSpeeds().step, "step", opts)
end

local function applyWalkSpeed(hum, inputSpeed)
    if not hum then return end
    inputSpeed = tonumber(inputSpeed) or 0
    local gameSpeed = tonumber(hum.WalkSpeed) or 0
    if gameSpeed < inputSpeed then
        hum.WalkSpeed = inputSpeed
    end
end

-- Walk = Humanoid:MoveTo + CanCollide off (tembus pagar).
-- Stick ground tiap frame: noclip hilangkan lantai → tanpa stick = masuk ke bawah.
local function goWalk(goalCf, gen, opts)
    local char = M.GetChar()
    local hrp = M.GetHRP(char)
    local hum = M.GetHum(char)
    if not char or not hrp or not hum then return false, "no_char" end
    opts = type(opts) == "table" and opts or {}
    local live = type(opts.liveGoal) == "function"

    local wasWalkSpeed = hum.WalkSpeed
    pcall(function()
        if hum.Sit then hum.Sit = false end
        hum.PlatformStand = false
        hrp.Anchored = false
        applyWalkSpeed(hum, M.GetSpeeds().walk)
    end)
    M.SetNoclip(true)
    stickWalkGround(hrp, char)

    local finished = false
    local cancelled = false
    local cancelReason = "preempted"
    local conn
    local stickConn
    conn = hum.MoveToFinished:Connect(function(reached)
        if reached then finished = true end
    end)
    -- Stepped = setelah physics; cegah jatuh tembus sebelum Heartbeat loop
    stickConn = RunService.Stepped:Connect(function()
        local c = M.GetChar()
        local root = M.GetHRP(c)
        if root then
            stickWalkGround(root, c)
        end
    end)

    local function cleanupWalk()
        if conn then
            pcall(function() conn:Disconnect() end)
            conn = nil
        end
        if stickConn then
            pcall(function() stickConn:Disconnect() end)
            stickConn = nil
        end
    end

    local goalPos, cancelledLive0 = resolveLiveGoal(goalCf, opts)
    if cancelledLive0 then
        cleanupWalk()
        M.SetNoclip(false)
        return false, "cancelled"
    end
    goalPos = goalPos or goalCf.Position

    local function issueMoveTo()
        hrp = M.GetHRP(M.GetChar()) or hrp
        hum = M.GetHum(M.GetChar()) or hum
        char = M.GetChar() or char
        if not hrp or not hum then return end
        local livePos, cancelledLive = resolveLiveGoal(goalCf, opts)
        if cancelledLive then
            cancelled = true
            cancelReason = "cancelled"
            return
        end
        if livePos then goalPos = livePos end
        if not M.IsNoclip() then M.SetNoclip(true) end
        pcall(function()
            hrp.Anchored = false
            hum.PlatformStand = false
        end)
        stickWalkGround(hrp, char)
        -- Y ikut kaki (sudah di-stick) — jangan paksa Y goal
        hum:MoveTo(Vector3.new(goalPos.X, hrp.Position.Y, goalPos.Z))
    end
    issueMoveTo()
    if cancelled then
        cleanupWalk()
        M.SetNoclip(false)
        return false, cancelReason
    end

    local flatDist0 = Vector3.new(goalPos.X - hrp.Position.X, 0, goalPos.Z - hrp.Position.Z).Magnitude
    local speed = math.max(M.GetSpeeds().walk, tonumber(wasWalkSpeed) or 16, 1)
    local timeout = math.clamp((flatDist0 / speed) + 2.5, 4, 45)
    if live then
        timeout = math.max(timeout, 20)
    end

    local t0 = os.clock()
    local lastReissue = 0
    -- Reissue jarang (walk biasa); liveGoal (chase) lebih sering
    local reissueEvery = live and 0.2 or 1.0
    while not finished and os.clock() - t0 < timeout do
        if isCancelled(gen) then
            cancelled = true
            cancelReason = "preempted"
            break
        end
        char = M.GetChar()
        hrp = M.GetHRP(char)
        hum = M.GetHum(char)
        if not char or not hrp or not hum then break end

        stickWalkGround(hrp, char)

        local livePos, cancelledLive = resolveLiveGoal(goalCf, opts)
        if cancelledLive then
            cancelled = true
            cancelReason = "cancelled"
            break
        end
        if livePos then goalPos = livePos end

        local flat = Vector3.new(goalPos.X - hrp.Position.X, 0, goalPos.Z - hrp.Position.Z)
        if flat.Magnitude <= ARRIVE_OK then
            finished = true
            break
        end

        if (os.clock() - lastReissue) >= reissueEvery then
            lastReissue = os.clock()
            applyWalkSpeed(hum, M.GetSpeeds().walk)
            issueMoveTo()
            if cancelled then break end
        end
        RunService.Heartbeat:Wait()
    end

    cleanupWalk()

    pcall(function()
        hum = M.GetHum()
        if hum then
            hum:Move(Vector3.zero, false)
            if wasWalkSpeed then hum.WalkSpeed = wasWalkSpeed end
        end
    end)
    -- Noclip cuma selama walk travel; setelah sampai → OFF biar berdiri normal
    M.SetNoclip(false)
    -- Rescue tenggelam saja (jangan Snap agresif — bikin freeze chase buy pet)

    if cancelled then return false, cancelReason end

    hrp = M.GetHRP(M.GetChar())
    goalPos = resolveLiveGoalPos(goalCf, opts) or goalPos
    local ok = false
    if hrp then
        local flat = Vector3.new(hrp.Position.X - goalPos.X, 0, hrp.Position.Z - goalPos.Z)
        ok = flat.Magnitude <= (ARRIVE_OK + 2)
    end
    return ok, ok and "walk" or "walk_fail"
end

local function goHard(goalCf, gen, opts)
    if isCancelled(gen) then return false, "preempted" end
    M.SetNoclip(true)
    local ok = M.SetCFrame(goalCf, { skipLock = true, _internal = true }) and true or false
    M.SetNoclip(false)
    return ok, "hard"
end

local METHODS = {
    soft = goSoft,
    step = goStep,
    walk = goWalk,
    hard = goHard,
}

function M.GoTo(goal, opts)
    opts = type(opts) == "table" and opts or {}
    if M.IsLoadingScreenActive() then
        if not M.WaitUntilLoaded(120) then
            return false, "loading"
        end
    end
    travelBusy = true

    local okLock, genOrErr = beginTravel(opts, "tele")
    if not okLock then
        travelBusy = false
        return false, genOrErr
    end
    local gen = genOrErr

    local cf = M.ResolveGoal(goal)
    if not cf then
        endTravel(gen)
        travelBusy = false
        return false, "bad_goal"
    end

    local method = M.NormalizeMode(opts.mode or opts.method or M.GetMode())
    local fn = METHODS[method] or goSoft
    local ok, msg = false, "fail"
    local ran, a, b = pcall(fn, cf, gen, opts)
    if ran then
        ok, msg = a, b
    else
        ok, msg = false, tostring(a)
    end

    local waitSec = tonumber(opts.wait)
    if ok and waitSec and waitSec > 0 and not isCancelled(gen) then
        task.wait(waitSec)
    end

    endTravel(gen)
    travelBusy = false
    M.SetNoclip(false)
    return ok, msg
end

function M.SoftTo(cf, opts)
    opts = type(opts) == "table" and opts or {}
    opts.mode = "soft"
    return M.GoTo(cf, opts)
end

function M.HardTo(cf, opts)
    opts = type(opts) == "table" and opts or {}
    opts.mode = "hard"
    return M.GoTo(cf, opts)
end

function M.ToCFrame(cf, opts)
    return M.GoTo(cf, opts)
end

function M.UnderTarget(worldPos, yOffset, lookAt)
    if typeof(worldPos) ~= "Vector3" then return nil end
    yOffset = tonumber(yOffset) or DEFAULT_UNDER_Y
    lookAt = typeof(lookAt) == "Vector3" and lookAt or worldPos
    local under = Vector3.new(worldPos.X, worldPos.Y + yOffset, worldPos.Z)
    return CFrame.new(under, lookAt), under
end

function M.ToUnder(worldPos, opts)
    opts = type(opts) == "table" and opts or {}
    local cf = M.UnderTarget(worldPos, opts.yOffset, opts.lookAt)
    if not cf then return false, "bad_pos" end
    opts.mode = M.NormalizeMode(opts.mode or opts.method or M.GetMode())
    return M.GoTo(cf, opts)
end

function M.ToGarden(opts)
    opts = type(opts) == "table" and opts or {}
    if M.IsLoadingScreenActive() then
        if not M.WaitUntilLoaded(120) then
            return false, "loading"
        end
    end
    local mode = M.NormalizeMode(opts.mode or opts.method or M.GetMode())
    local cf = M.GetGardenCFrame()
    if typeof(cf) ~= "CFrame" then return false, "no_garden" end

    local arrive = opts.arrive or GARDEN_NEAR_RADIUS
    local hrp = M.GetHRP()
    local alreadyNear = hrp and M.Distance(hrp.Position, cf.Position) <= arrive

    -- Jauh: pakai TeleportButton resmi dulu (otomatis, bukan mode UI)
    if not alreadyNear and M.FireTeleportButton("Garden") then
        local t0 = os.clock()
        while os.clock() - t0 < (opts.buttonWait or 2.5) do
            hrp = M.GetHRP()
            if hrp and M.Distance(hrp.Position, cf.Position) <= arrive then
                break
            end
            task.wait(0.05)
        end
        alreadyNear = true
    end

    -- Fine-tune center/spawn HANYA kalau opts.fineTune = true (jangan ikut Auto Tele ON —
    -- approach buy/claim pakai Garden button saja, jangan hard-TP ke center).
    if opts.fineTune ~= true then
        local waitSec = tonumber(opts.wait)
        if waitSec and waitSec > 0 then task.wait(waitSec) end
        return true, "garden_button"
    end

    local ok, msg = M.GoTo(cf, {
        mode = mode,
        wait = opts.wait,
        reason = resolveTravelReason(opts, "move"),
        priority = opts.priority,
    })
    return ok, msg
end

function M.ToSell(opts)
    opts = type(opts) == "table" and opts or {}
    if M.IsLoadingScreenActive() then
        if not M.WaitUntilLoaded(120) then
            return false, "loading"
        end
    end
    local sellPos = M.GetSellPos()
    if not sellPos then return false, "no_sell" end

    local hrp = M.GetHRP()
    local arrive = opts.arrive or SELL_ARRIVE
    if hrp and M.Distance(hrp.Position, sellPos) <= arrive then
        return true, "already_near"
    end

    local mode = M.NormalizeMode(opts.mode or opts.method or M.GetMode())
    -- afterWait=0: jangan nunggu 2s setelah Fire Sell (langsung poll sampai arrive)
    if M.FireTeleportButton("Sell", 0) then
        local t0 = os.clock()
        while os.clock() - t0 < (opts.buttonWait or 2.5) do
            hrp = M.GetHRP()
            sellPos = M.GetSellPos() or sellPos
            if hrp and sellPos and M.Distance(hrp.Position, sellPos) <= arrive then
                -- Pastikan tidak nyangkut anchor setelah TP game
                pcall(function()
                    hrp.Anchored = false
                    local hum = M.GetHum()
                    if hum then hum.PlatformStand = false end
                end)
                local waitSec = tonumber(opts.wait)
                if waitSec and waitSec > 0 then task.wait(waitSec) end
                return true, "sell_button"
            end
            task.wait(0.05)
        end
    end

    sellPos = M.GetSellPos() or sellPos
    -- Walk: goal di tanah sell (tanpa +Y) biar tidak ke langit; hard/soft boleh offset
    local goalPos = (mode == "walk") and sellPos or (sellPos + GARDEN_TP_OFFSET)
    local cf = CFrame.new(goalPos)
    return M.GoTo(cf, {
        mode = mode,
        wait = opts.wait,
        reason = resolveTravelReason(opts, "move"),
        priority = opts.priority,
    })
end

function M.ToNearPlayer(player, opts)
    opts = type(opts) == "table" and opts or {}
    local tchar = player and player.Character
    local thrp = tchar and tchar:FindFirstChild("HumanoidRootPart")
    if not thrp then return false, "no_target" end

    local hrp = M.GetHRP()
    if not hrp then return false, "no_char" end

    local standDist = tonumber(opts.standDist) or 3.5
    local yOffset = tonumber(opts.yOffset) or 0
    local toUs = hrp.Position - thrp.Position
    local dir = toUs.Magnitude > 1 and toUs.Unit or -thrp.CFrame.LookVector
    local flat = Vector3.new(dir.X, 0, dir.Z)
    if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, -1) else flat = flat.Unit end
    local pos = thrp.Position + flat * standDist + Vector3.new(0, yOffset, 0)
    local cf = CFrame.new(pos, thrp.Position)
    return M.GoTo(cf, {
        mode = opts.mode or opts.method or "hard",
        wait = opts.wait,
        reason = resolveTravelReason(opts, "drop"),
        priority = opts.priority,
    })
end

function M.ToNearInstance(inst, opts)
    opts = type(opts) == "table" and opts or {}
    local pos = instWorldPos(inst)
    if not pos then return false, "no_inst" end
    local standDist = tonumber(opts.standDist) or 6
    local hrp = M.GetHRP()
    local flat = Vector3.new(0, 0, 1)
    if hrp then
        local d = hrp.Position - pos
        flat = Vector3.new(d.X, 0, d.Z)
        if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, 1) else flat = flat.Unit end
    end
    local stand = pos + flat * standDist + Vector3.new(0, tonumber(opts.yOffset) or 0, 0)
    return M.GoTo(CFrame.new(stand, pos), {
        mode = opts.mode or opts.method or "hard",
        wait = opts.wait,
        reason = resolveTravelReason(opts, "auction"),
        priority = opts.priority,
    })
end

----------------------------------------------------------------
-- Fly lock (delegate FlyNoclip)
----------------------------------------------------------------
local function getFly()
    return G.FlyNoclip or G.FlyNoclipModule or rawget(_G, "FlyNoclip")
end

function M.LockAt(pos)
    local Fly = getFly()
    if type(Fly) == "table" and type(Fly.LockAt) == "function" then
        return Fly.LockAt(pos)
    end
    if typeof(pos) ~= "Vector3" then return false end
    return M.SetCFrame(CFrame.new(pos))
end

function M.Unlock()
    local Fly = getFly()
    if type(Fly) == "table" and type(Fly.Unlock) == "function" then
        return Fly.Unlock()
    end
    M.SetNoclip(false)
    M.StopGroundGuard()
end

----------------------------------------------------------------
-- Sync
----------------------------------------------------------------
function M.SyncFromGlobals()
    M.SetMode(M.GetMode())
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local cfg = MAIN and MAIN.misc and MAIN.misc.character
    local soft = G.MOVE_SOFT_SPEED or rawget(_G, "MOVE_SOFT_SPEED")
    local step = G.MOVE_STEP_SPEED or rawget(_G, "MOVE_STEP_SPEED")
    local walk = G.MOVE_WALK_SPEED or rawget(_G, "MOVE_WALK_SPEED")
    if type(cfg) == "table" then
        if soft == nil then soft = cfg.soft_speed end
        if step == nil then step = cfg.step_speed end
        if walk == nil then walk = cfg.walk_speed end
    end
    M.SetSpeeds({
        soft = soft or DEFAULT_SOFT_SPEED,
        step = step or DEFAULT_STEP_SPEED,
        walk = walk or DEFAULT_WALK_SPEED,
    })
end

function M.Stop()
    while pauseDepth > 0 do
        M.ResumeAutoTele()
    end
    M.SetNoclip(false)
    M.StopGroundGuard()
    travelBusy = false
    moveGen += 1
    lock.gen = moveGen
    lock.busy = false
    lock.reason = nil
    lock.priority = 0
    busy = false
    session.active = false
    session.reason = nil
    session.priority = 0
end

-- Debug / status (tanpa spam log)
function M.GetLockStatus()
    return {
        busy = lock.busy == true or session.active == true,
        reason = lock.busy and lock.reason or session.reason,
        priority = lock.busy and lock.priority or (session.active and session.priority or 0),
        gen = lock.gen,
        session = session.active == true,
        sessionReason = session.reason,
        sessionPriority = session.priority,
        groundGuard = groundGuardConn ~= nil,
        underPlotRescue = underPlotConn ~= nil,
        underPlotWhy = lastUnderWhy,
    }
end

G.Move = M
G.MoveModule = M
_G.Move = M
_G.MoveModule = M

-- GroundGuard jangan auto-start (bisa float saat pegang buah).
-- Under-plot rescue: ON — deteksi jatuh ke bawah deck → Fire TeleportButton Garden.
task.defer(function()
    M.StopGroundGuard()
    M.SetNoclip(false)
    M.StartUnderPlotRescue()
end)

return M
 end,                           required = false },
    { key = "EspFruitBackpack",        name = "ESP Fruit Backpack",      factory = function() -- EspFruitBackpack.lua — ESP harga buah di backpack
-- UI: label slot + total coin S (backpack) + total value garden G (kiri Search)
-- Total value garden independen dari ESP garden; hitung async agar UI tidak freeze.
-- Scan: versi baru (backpack buka saja, 1 detik UI, re-fetch harga 0 tiap scan, re-fetch harga >0 tiap 3 detik)

local Players           = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local TAG_SLOT           = "_GAG2FBP_ESP"
local TAG_TOTAL          = "_GAG2FBP_TOTAL"
local TAG_TOTAL_VAL      = "_GAG2FBP_TOTAL_VAL"
local TAG_GARDEN_TOTAL   = "_GAG2FBP_GARDEN_TOTAL"
local TAG_GARDEN_VAL     = "_GAG2FBP_GARDEN_TOTAL_VAL"

local COL_SLOT_BG      = Color3.fromRGB(18, 22, 16)
local COL_SLOT_STROKE  = Color3.fromRGB(255, 210, 60)
local COL_SLOT_TEXT    = Color3.fromRGB(255, 244, 190)
local COL_TOTAL_BG     = Color3.fromRGB(20, 24, 30)
local COL_TOTAL_STROKE = Color3.fromRGB(255, 210, 60)
local COL_TOTAL_TEXT   = Color3.fromRGB(255, 236, 120)
local COL_COIN         = Color3.fromRGB(255, 196, 45)
local COL_GARDEN_BG    = Color3.fromRGB(16, 28, 20)
local COL_GARDEN_STROKE = Color3.fromRGB(74, 222, 128)
local COL_GARDEN_TEXT  = Color3.fromRGB(187, 247, 208)
local COL_GARDEN_ICON  = Color3.fromRGB(34, 197, 94)

local SCAN_SEC = 1.0
local REFRESH_CACHED_SEC = 3.0
local FETCH_WAIT_SEC = 2.5
-- Badge G: UI poll 2s, tapi kick SumRipe jarang (kebun besar = spike ~1s).
local GARDEN_SCAN_SEC = 2.0
local GARDEN_VALUE_KICK_SEC = 20.0
local _lastGardenValueKickAt = 0

local running    = false
local scanThread = nil
local gardenThread = nil
local bpOpen     = false
local lastCachedRefreshAt = 0
local lastPriceMode = nil
local priceByKey = {}
local gardenCache = { count = 0, total = 0 }
local backpackValueCache = { count = 0, total = 0, at = 0, ready = false }
-- Harus di atas ClearPriceCache/SyncFromGlobals (kalau di bawah, ClearPriceCache
-- nulis global nil → SyncFromGlobals error → Start() tidak jalan → label ESP hilang).
local typeValueCache = { at = 0, rows = nil, total = 0, count = 0, ready = false }
local TYPE_VALUE_CACHE_SEC = 5
local typeValueFetchAt = 0
local TYPE_VALUE_FETCH_GAP = 4
local TYPE_VALUE_FETCH_MAX = 32 -- max buah di-fetch per wave (hindari spike)

local function _invalidateTypeValueCache()
    typeValueCache.at = 0
    typeValueCache.ready = false
end

local FruitProxyUtil
local FruitSellValue
pcall(function() FruitProxyUtil = require(ReplicatedStorage.SharedModules.FruitProxyUtil) end)
pcall(function() FruitSellValue = require(script.Parent.FruitSellValue) end)
if type(FruitSellValue) ~= "table" then
    FruitSellValue = G.FruitSellValue or _G.FruitSellValue
end

local ID_FIELDS    = { "Id", "id", "UUID", "Uuid", "FruitId" }
local NAME_FIELDS  = { "FruitName", "Fruit", "Name" }
local MULTI_FIELDS = { "SizeMultiplier", "SizeMulti" }
local KG_FIELDS    = { "Weight", "Kg" }
local MUT_FIELDS   = { "Mutation" }

local function _cfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.fruit_backpack_esp
    st = type(st) == "table" and st or {}
    local mode = G.FRUIT_BACKPACK_ESP_PRICE_MODE or rawget(_G, "FRUIT_BACKPACK_ESP_PRICE_MODE") or st.price_mode
    if tostring(mode or ""):lower() ~= "stock" then
        mode = "base"
    else
        mode = "stock"
    end
    return {
        enabled = (G.FRUIT_BACKPACK_ESP_ENABLED == true)
            or (rawget(_G, "FRUIT_BACKPACK_ESP_ENABLED") == true)
            or (st.enabled == true),
        price_mode = mode,
    }
end

local function _fsv()
    local f = FruitSellValue or G.FruitSellValue or _G.FruitSellValue
    return type(f) == "table" and f or nil
end

local function _formatPrice(n)
    n = tonumber(n) or 0
    if n <= 0 then return "0" end
    if n >= 1e9 then return string.format("%.2fB", n / 1e9) end
    if n >= 1e6 then return string.format("%.2fM", n / 1e6) end
    if n >= 1e3 then return string.format("%.1fk", n / 1e3) end
    return tostring(math.floor(n))
end

local function _norm(s)
    return tostring(s or ""):lower():gsub("[%s_%-%.'']+", "")
end

local function _nameOk(a, b)
    a, b = _norm(a), _norm(b)
    if a == "" or b == "" then return false end
    if a == b then return true end
    if #a >= 3 and (a:find(b, 1, true) or b:find(a, 1, true)) then return true end
    return false
end

local function _kgTol(kg)
    return math.max(0.5, (tonumber(kg) or 0) * 0.15)
end

local function _isSeedName(name)
    name = _norm(name)
    if name == "" then return false end
    return name:find("seed", 1, true) ~= nil
        or name == "shovel" or name == "wateringcan"
end

local function _isNonFruitSlot(name)
    name = _norm(name)
    if name == "" then return false end
    if _isSeedName(name) then return true end
    return name:find("sprinkler", 1, true) ~= nil
        or name:find("sprink", 1, true) ~= nil
        or name:find("gear", 1, true) ~= nil
        or name:find("watering", 1, true) ~= nil
        or name:find("fertilizer", 1, true) ~= nil
        or name:find("trap", 1, true) ~= nil
end

local function _isVisible(inst)
    if not inst then return false end
    local cur = inst
    while cur and cur ~= game do
        if cur:IsA("GuiObject") and cur.Visible == false then return false end
        if cur:IsA("ScreenGui") and cur.Enabled == false then return false end
        cur = cur.Parent
    end
    return true
end

local function _pick(t, fields)
    if type(t) ~= "table" then return nil end
    for _, f in ipairs(fields) do
        local v = t[f]
        if v ~= nil and tostring(v) ~= "" then return v end
    end
    return nil
end

local function _fruitId(inst)
    if not inst then return "" end
    return tostring(inst:GetAttribute("Id") or inst:GetAttribute("id")
        or inst:GetAttribute("UUID") or inst:GetAttribute("FruitId") or "")
end

local function _entryKey(e)
    local id = tostring(e.id or "")
    if id ~= "" and #id >= 8 then return id end
    return _norm(e.name) .. "|" .. tostring(math.floor((e.kg or 0) * 100))
end

local function _priceCacheKey(e, mode)
    local key = _entryKey(e) .. "|m:" .. tostring(mode or _cfg().price_mode)
    if tostring(mode or _cfg().price_mode) == "base" then
        local bid = tonumber(e.bidPrice) or 0
        if bid <= 0 and e.tool and type(e.tool.GetAttribute) == "function" then
            bid = tonumber(e.tool:GetAttribute("BidPrice")) or 0
        end
        if bid > 0 then
            key = key .. "|bid:" .. tostring(math.floor(bid))
        end
    end
    return key
end

local function _syncPriceModeCache()
    local mode = _cfg().price_mode
    if lastPriceMode ~= mode then
        lastPriceMode = mode
        table.clear(priceByKey)
        lastCachedRefreshAt = 0
    end
    return mode
end

local function _isFruit(inst)
    if not inst then return false end
    if FruitProxyUtil and type(FruitProxyUtil.IsFruitInstance) == "function" then
        local ok, yes = pcall(FruitProxyUtil.IsFruitInstance, inst)
        if ok and yes then return true end
    end
    if inst:GetAttribute("SeedTool") or inst:GetAttribute("Pet") then return false end
    if inst:GetAttribute("PottedPlant") == true then return false end
    if tostring(inst:GetAttribute("MainCategory") or "") == "Seed" then return false end
    if inst:GetAttribute("FruitName") or inst:GetAttribute("Fruit") then return true end
    if inst:GetAttribute("FruitProxy") == true then return true end
    local hf = inst:GetAttribute("HarvestedFruit")
    if hf == true or (type(hf) == "string" and hf ~= "") then return true end
    return false
end

local function _toolEntry(tool)
    local fsv = _fsv()
    -- Prefer FruitName/Fruit. Jangan timpa dengan resolveSeedName (itu bikin
    -- "Moon Bloom" → "Moon Bloom Seed" di HarvestedFruits).
    local fruitAttr = tool:GetAttribute("FruitName") or tool:GetAttribute("Fruit")
    local name = tostring(fruitAttr or "")
    if name == "" then
        name = tostring(tool.Name or "")
        if fsv and type(fsv.resolveFruitName) == "function" then
            local ok, n = pcall(fsv.resolveFruitName, tool)
            if ok and type(n) == "string" and n ~= "" then name = n end
        elseif fsv and type(fsv.resolveSeedName) == "function" then
            local ok, n = pcall(fsv.resolveSeedName, tool)
            if ok and type(n) == "string" and n ~= "" then name = n end
        end
    end
    name = tostring(name):gsub("%s+[Ss]eed%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
    local kg = tonumber(tool:GetAttribute("Weight")) or 0
    if fsv and type(fsv.resolveWeight) == "function" then
        local ok, w = pcall(fsv.resolveWeight, tool)
        if ok and type(w) == "number" and w > 0 then kg = w end
    end
    local multi = tonumber(tool:GetAttribute("SizeMultiplier") or tool:GetAttribute("SizeMulti")) or 0
    if fsv and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, tool)
        if ok and type(m) == "number" and m > 0 then multi = m end
    end
    local bidPrice = 0
    if fsv and type(fsv.resolveBidPrice) == "function" then
        local ok, b = pcall(fsv.resolveBidPrice, tool)
        if ok and type(b) == "number" and b > 0 then bidPrice = b end
    else
        bidPrice = tonumber(tool:GetAttribute("BidPrice")) or 0
    end
    return {
        id = _fruitId(tool), name = name, kg = kg, multi = multi,
        mut = tool:GetAttribute("Mutation"), decay = tool:GetAttribute("DecayAlpha"),
        bidPrice = bidPrice, tool = tool,
    }
end

local function _layoutFruit(raw)
    if type(raw) ~= "table" then return false end
    if raw.SeedTool or raw.Pet or raw.PottedPlant == true then return false end
    if tostring(raw.MainCategory or "") == "Seed" then return false end
    local name = tostring(_pick(raw, NAME_FIELDS) or "")
    if _isNonFruitSlot(name) then return false end
    local id = _pick(raw, ID_FIELDS)
    if type(id) == "string" and #id >= 8 then return true end
    return name ~= ""
end

local function _collectLayout(layout, out, depth, seen)
    if depth > 12 or type(layout) ~= "table" or seen[layout] then return end
    seen[layout] = true
    if _layoutFruit(layout) then out[#out + 1] = layout return end
    for _, v in pairs(layout) do
        if type(v) == "table" then
            if _layoutFruit(v) then out[#out + 1] = v
            else _collectLayout(v, out, depth + 1, seen) end
        end
    end
end

local function _getLayout()
    local ok, net = pcall(function()
        return require(ReplicatedStorage.SharedModules.Networking)
    end)
    if not ok or type(net.Backpack) ~= "table" then return nil end
    local r = net.Backpack.GetLayout
    if not r then return nil end
    local ok2, layout
    if type(r) == "table" and r.Fire then ok2, layout = pcall(function() return r:Fire() end)
    elseif type(r) == "userdata" and r.InvokeServer then ok2, layout = pcall(function() return r:InvokeServer() end)
    elseif type(r) == "function" then ok2, layout = pcall(r) end
    return ok2 and type(layout) == "table" and layout or nil
end

local function _mergeFruitEntry(cur, e)
    if not cur or not e then return end
    if e.name ~= "" and (cur.name or "") == "" then cur.name = e.name end
    if e.multi > 0 and (cur.multi or 0) <= 0 then cur.multi = e.multi end
    if e.kg > 0 and (cur.kg or 0) <= 0 then cur.kg = e.kg end
    if e.mut and not cur.mut then cur.mut = e.mut end
    if e.decay ~= nil and cur.decay == nil then cur.decay = e.decay end
    if e.tool and not cur.tool then cur.tool = e.tool end
    local curBid = tonumber(cur.bidPrice) or 0
    local newBid = tonumber(e.bidPrice) or 0
    if newBid > curBid then cur.bidPrice = newBid end
end

local function _syncEntryBidFromTool(e)
    if not e or not e.tool or type(e.tool.GetAttribute) ~= "function" then return end
    if (tonumber(e.bidPrice) or 0) > 0 then return end
    local fsv = _fsv()
    local bid = 0
    if fsv and type(fsv.resolveBidPrice) == "function" then
        local ok, b = pcall(fsv.resolveBidPrice, e.tool)
        if ok and type(b) == "number" and b > 0 then bid = b end
    else
        bid = tonumber(e.tool:GetAttribute("BidPrice")) or 0
    end
    if bid > 0 then e.bidPrice = bid end
end

local function _linkBackpackTools(byId, list)
    local bp = LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack")
    if not bp then return end
    for _, inst in ipairs(bp:GetChildren()) do
        if _isFruit(inst) then
            local id = _fruitId(inst)
            local entry = (id ~= "" and byId[id]) or nil
            if entry then
                if not entry.tool then entry.tool = inst end
                _syncEntryBidFromTool(entry)
            end
        end
    end
    for _, e in ipairs(list) do
        if e.tool and (e.tool.Parent == bp or (LP.Character and e.tool:IsDescendantOf(LP.Character))) then
            _syncEntryBidFromTool(e)
        end
    end
end

local function _allFruits()
    local byId, list = {}, {}
    local function add(e)
        if e.name == "" and e.id == "" then return end
        local id = tostring(e.id or "")
        if id ~= "" and byId[id] then
            _mergeFruitEntry(byId[id], e)
            return
        end
        list[#list + 1] = e
        if id ~= "" then byId[id] = e end
    end
    local function scanChildren(root)
        if not root then return end
        for _, inst in ipairs(root:GetChildren()) do
            if _isFruit(inst) then add(_toolEntry(inst)) end
        end
    end
    -- Instance fisik dulu (punya BidPrice + tool); layout UI hanya melengkapi metadata.
    scanChildren(LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack"))
    scanChildren(LP.Character)
    local layout = _getLayout()
    if layout then
        local raw = {}
        _collectLayout(layout, raw, 0, {})
        for _, r in ipairs(raw) do
            add({
                id = tostring(_pick(r, ID_FIELDS) or ""),
                name = tostring(_pick(r, NAME_FIELDS) or ""),
                kg = tonumber(_pick(r, KG_FIELDS)) or 0,
                multi = tonumber(_pick(r, MULTI_FIELDS)) or 0,
                mut = _pick(r, MUT_FIELDS), decay = r.DecayAlpha, tool = nil,
            })
        end
    end
    _linkBackpackTools(byId, list)
    return list, byId
end

local function _fetchPrice(e, force)
    local mode = _syncPriceModeCache()
    local key = _priceCacheKey(e, mode)
    if not force then
        local cached = priceByKey[key]
        if cached and cached > 0 then return cached end
    end
    local fsv = _fsv()
    if not fsv then return 0 end

    local multi = e.multi or 0
    if multi <= 0 and e.tool and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, e.tool)
        if ok and type(m) == "number" then multi = m end
    end

    if multi > 0 and e.name ~= "" and type(fsv.getBackpackEspPrice) == "function" then
        local fruitId = tostring(e.id or "")
        local bidPrice = tonumber(e.bidPrice) or 0
        if bidPrice <= 0 and e.tool then
            if type(fsv.resolveBidPrice) == "function" then
                local okBid, b = pcall(fsv.resolveBidPrice, e.tool)
                if okBid and type(b) == "number" and b > 0 then bidPrice = b end
            elseif type(e.tool.GetAttribute) == "function" then
                bidPrice = tonumber(e.tool:GetAttribute("BidPrice")) or 0
            end
        end
        if bidPrice > 0 then e.bidPrice = bidPrice end
        local ok, p = pcall(fsv.getBackpackEspPrice, e.name, multi, e.mut, e.decay, mode, fruitId, bidPrice)
        if ok and type(p) == "number" and p > 0 then
            local prev = priceByKey[key]
            priceByKey[key] = p
            if prev ~= p then
                _invalidateTypeValueCache()
            end
            return p
        end
    end
    return priceByKey[key] or 0
end

local function _usedKey(e)
    local id = tostring(e.id or "")
    if id ~= "" then return id end
    return "n:" .. _norm(e.name) .. "|" .. tostring(math.floor((e.kg or 0) * 100))
end

local function _matchFruit(uiName, uiKg, uiId, list, byId, used)
    uiId = tostring(uiId or "")
    uiKg = tonumber(uiKg) or 0
    if uiId ~= "" and byId[uiId] and not used[uiId] then
        used[uiId] = true
        return byId[uiId]
    end
    local best, bestDiff = nil, math.huge
    for _, e in ipairs(list) do
        local key = _usedKey(e)
        if not used[key] and _nameOk(uiName, e.name) then
            local diff = math.abs((e.kg or 0) - uiKg)
            if diff <= _kgTol(uiKg) and diff < bestDiff then
                bestDiff = diff
                best = e
            end
        end
    end
    if best then used[_usedKey(best)] = true return best end

    if uiName == "" then
        local bestKg, bestKgDiff = nil, math.huge
        for _, e in ipairs(list) do
            local key = _usedKey(e)
            if not used[key] then
                local diff = math.abs((e.kg or 0) - uiKg)
                if uiKg > 0 and diff <= _kgTol(uiKg) and diff < bestKgDiff then
                    bestKgDiff = diff
                    bestKg = e
                end
            end
        end
        if bestKg then used[_usedKey(bestKg)] = true return bestKg end
    end
    return nil
end

local function _parseKg(text)
    text = tostring(text or "")
    if text:match("^[xX]%d") then return nil end
    return tonumber(text:match("([%d%.]+)%s*[kK][gG]"))
end

local function _getBackpackGui()
    local pg = LP:FindFirstChild("PlayerGui")
    return pg and pg:FindFirstChild("BackpackGui")
end

local function _findInventoryHeader(inventory)
    if not inventory then return nil end
    local hdr = inventory:FindFirstChild("FruitInventory")
    if hdr and hdr:IsA("TextLabel") and hdr.Visible then return hdr end
    for _, lbl in ipairs(inventory:GetDescendants()) do
        if lbl:IsA("TextLabel") and lbl.Visible and lbl.Text:match("%d+/%d+") then
            return lbl
        end
    end
    return nil
end

local function _findSearchAnchor(inventory)
    if not inventory then return nil end
    local search = inventory:FindFirstChild("Search")
    if search and search:IsA("GuiObject") then
        if search:IsA("TextBox") then return search end
        local tb = search:FindFirstChildWhichIsA("TextBox", true)
        -- Anchor ke frame Search (lebih stabil untuk posisi badge kanan)
        return search
    end
    for _, d in ipairs(inventory:GetDescendants()) do
        if d:IsA("TextBox") and _isVisible(d) then
            local hint = (tostring(d.PlaceholderText) .. " " .. d.Name):lower()
            if hint:find("search", 1, true) then
                local p = d.Parent
                if p and p:IsA("GuiObject") and p.Name:lower():find("search", 1, true) then
                    return p
                end
                return d
            end
        end
    end
    return nil
end

local function _findBackpackContextFromGui(sg)
    local backpack = sg:FindFirstChild("Backpack")
    if not backpack then return nil end
    local inventory = backpack:FindFirstChild("Inventory")
    if not inventory or not inventory:IsA("GuiObject") then return nil end
    if not inventory.Visible or not _isVisible(inventory) then return nil end

    local scroll = inventory:FindFirstChild("ScrollingFrame")
    local grid = scroll and (scroll:FindFirstChild("UIGridFrame") or scroll)
    local searchBox = _findSearchAnchor(inventory)
    local hotbar = backpack:FindFirstChild("Hotbar")

    return {
        screenGui = sg,
        searchBox = searchBox,
        fruitHeader = _findInventoryHeader(inventory),
        fruitGrid = grid,
        hotbar = hotbar,
        inventory = inventory,
    }
end

local function _findAncestorNamed(inst, name)
    local cur = inst
    while cur and cur ~= game do
        if cur.Name == name then return cur end
        cur = cur.Parent
    end
    return nil
end

local function _findBackpackContextGeneric()
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return nil end
    for _, inst in ipairs(pg:GetDescendants()) do
        if inst:IsA("TextBox") and _isVisible(inst) then
            local hint = (inst.PlaceholderText .. " " .. inst.Text .. " " .. inst.Name):lower()
            if hint:find("search", 1, true) then
                local sg = inst:FindFirstAncestorWhichIsA("ScreenGui")
                if sg and sg.Enabled then
                    local inventory = _findAncestorNamed(inst, "Inventory")
                    if inventory and inventory:IsA("GuiObject") and inventory.Visible then
                        return _findBackpackContextFromGui(sg)
                    end
                end
            end
        end
    end
    return nil
end

local function _findBackpackContext()
    local sg = _getBackpackGui()
    if sg and sg.Enabled then
        local ctx = _findBackpackContextFromGui(sg)
        if ctx then return ctx end
    end
    return _findBackpackContextGeneric()
end

local function _isHotbarArea(inst)
    local cur = inst
    while cur and cur ~= game do
        local n = cur.Name:lower()
        if n:find("hotbar", 1, true) or n:find("toolbar", 1, true)
            or n:find("quickslot", 1, true) or n:find("bottombar", 1, true)
            or n:find("slotbar", 1, true) or n:find("equipped", 1, true) then
            return true
        end
        cur = cur.Parent
    end
    return false
end

local function _isHotbarContainer(inst)
    if not inst or not inst:IsA("GuiObject") then return false end
    return _isHotbarArea(inst)
end

local function _findHotbarRoots(ctx)
    local roots, seen = {}, {}
    if ctx and ctx.hotbar and ctx.hotbar:IsA("GuiObject") and _isVisible(ctx.hotbar) then
        roots[#roots + 1] = ctx.hotbar
        return roots
    end
    local sg = ctx and ctx.screenGui
    if not sg then return roots end

    for _, inst in ipairs(sg:GetDescendants()) do
        if inst.Name == "Hotbar" and inst:IsA("Frame") and _isVisible(inst) and not seen[inst] then
            seen[inst] = true
            roots[#roots + 1] = inst
        end
    end
    return roots
end

local function _inGrid(inst, grid)
    if not inst or not grid then return false end
    if _isHotbarArea(inst) then return false end
    return inst == grid or inst:IsDescendantOf(grid)
end

----------------------------------------------------------------
-- UI slot scan
----------------------------------------------------------------

local function _findSlotRoot(kgLabel)
    if kgLabel and kgLabel.Name == "ToolCount" then
        local p = kgLabel.Parent
        if p and (p:IsA("TextButton") or p:IsA("Frame") or p:IsA("ImageButton")) then
            return p
        end
    end
    local cur = kgLabel.Parent
    for _ = 1, 6 do
        if not cur then break end
        if cur:IsA("Frame") or cur:IsA("ImageButton") or cur:IsA("TextButton") then
            local w, h = cur.AbsoluteSize.X, cur.AbsoluteSize.Y
            if w >= 40 and h >= 40 and w <= 220 and h <= 220 then
                return cur
            end
        end
        cur = cur.Parent
    end
    return kgLabel.Parent
end

local function _slotNameFromRoot(root, kgLabel)
    if root then
        local toolName = root:FindFirstChild("ToolName")
        if toolName and toolName:IsA("TextLabel") and toolName.Visible and toolName.Text ~= "" then
            return toolName.Text
        end
    end
    if root and type(root.GetAttribute) == "function" then
        local attr = root:GetAttribute("FruitName") or root:GetAttribute("Fruit")
            or root:GetAttribute("SeedName") or root:GetAttribute("ItemName")
        if attr ~= nil and tostring(attr) ~= "" then return tostring(attr) end
    end
    local best, bestLen = nil, 0
    for _, lbl in ipairs(root:GetDescendants()) do
        if lbl:IsA("TextLabel") and lbl ~= kgLabel and lbl.Visible and lbl.Name ~= "ToolCount" then
            local t = lbl.Text
            if t ~= "" and not t:match("%d+/%d+") and not _parseKg(t) and not t:lower():find("search", 1, true) then
                if #t > bestLen then bestLen = #t best = t end
            end
        end
    end
    return best or ""
end

local function _slotId(root)
    if not root then return "" end
    return tostring(root:GetAttribute("Id") or root:GetAttribute("id")
        or root:GetAttribute("UUID") or root:GetAttribute("FruitId") or "")
end

local function _ensureSlotLabel(root)
    local lbl = root:FindFirstChild(TAG_SLOT)
    if lbl and not lbl:IsA("TextLabel") then lbl:Destroy() lbl = nil end
    if not lbl then
        lbl = Instance.new("TextLabel")
        lbl.Name = TAG_SLOT
        lbl.BorderSizePixel = 0
        lbl.Font = Enum.Font.GothamMedium
        lbl.TextSize = 10
        lbl.TextXAlignment = Enum.TextXAlignment.Center
        lbl.TextYAlignment = Enum.TextYAlignment.Center
        lbl.Parent = root
        Instance.new("UICorner", lbl).CornerRadius = UDim.new(0, 5)
        local stroke = Instance.new("UIStroke")
        stroke.Name = "_GAG2FBP_STROKE"
        stroke.Thickness = 1
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = lbl
    end
    local stroke = lbl:FindFirstChild("_GAG2FBP_STROKE")
    if stroke and stroke:IsA("UIStroke") then
        stroke.Color = COL_SLOT_STROKE
        stroke.Transparency = 0.25
    end
    lbl.BackgroundTransparency = 0.08
    lbl.BackgroundColor3 = COL_SLOT_BG
    lbl.TextColor3 = COL_SLOT_TEXT
    lbl.TextStrokeTransparency = 1
    lbl.AnchorPoint = Vector2.new(0.5, 0.5)
    lbl.Position = UDim2.new(0.5, 0, 0.43, -2)
    lbl.Size = UDim2.new(0.86, 0, 0, 15)
    lbl.ZIndex = (root.ZIndex or 1) + 5
    return lbl
end

local function _styleTotalChildren(root, baseZ)
    local z = math.max(baseZ + 12, 2)
    root.ZIndex = z
    for _, ch in ipairs(root:GetDescendants()) do
        if ch:IsA("GuiObject") then ch.ZIndex = z + 1 end
    end
    for _, ch in ipairs(root:GetChildren()) do
        if ch:IsA("GuiObject") then ch.ZIndex = z + 2 end
    end
end

local function _getBadgeParent(searchBox, fruitHeader, inventory)
    -- Prefer parent Search (Inventory), jangan tersangkut di Fruit header kiri
    if searchBox and searchBox:IsA("GuiObject") then
        local p = searchBox.Parent
        if p and p:IsA("GuiObject") then return p end
    end
    if inventory and inventory:IsA("GuiObject") then
        return inventory
    end
    local anchor = fruitHeader
    if not anchor or not anchor:IsA("GuiObject") then return nil end
    local parent = anchor.Parent
    if not parent or not parent:IsA("GuiObject") then return nil end
    return parent
end

local function _detachLegacyTotalsRow(parent)
    if not parent then return end
    local row = parent:FindFirstChild("_GAG2FBP_TOTALS_ROW")
    if not row then return end
    for _, name in ipairs({ TAG_TOTAL, TAG_GARDEN_TOTAL }) do
        local ch = row:FindFirstChild(name)
        if ch then ch.Parent = parent end
    end
    pcall(function() row:Destroy() end)
end

local function _layoutTotalBadges(parent, gardenRoot, backpackRoot, searchBox, fruitHeader)
    if not parent or not parent:IsA("GuiObject") then return end

    local sx, sy, zBase
    if searchBox and searchBox:IsA("GuiObject") then
        -- Selalu di kanan Search (jangan pakai Fruit header kiri — itu yang merusak posisi)
        sy = searchBox.AbsolutePosition.Y - parent.AbsolutePosition.Y - 10
        sx = (searchBox.AbsolutePosition.X - parent.AbsolutePosition.X) + searchBox.AbsoluteSize.X
        zBase = searchBox.ZIndex or 1
    else
        -- Fallback kanan inventory, bukan di atas "100/250 Fruits"
        sx = math.max(80, parent.AbsoluteSize.X - 12)
        sy = 40
        zBase = 1
        if fruitHeader and fruitHeader:IsA("GuiObject") then
            sy = (fruitHeader.AbsolutePosition.Y - parent.AbsolutePosition.Y) + fruitHeader.AbsoluteSize.Y + 4
        end
    end

    local z = math.max(zBase, 1) + 30

    if backpackRoot and backpackRoot.Parent == parent then
        backpackRoot.AnchorPoint = Vector2.new(1, 1)
        backpackRoot.Position = UDim2.fromOffset(sx, sy)
        backpackRoot.Visible = true
        _styleTotalChildren(backpackRoot, z)
    end

    if gardenRoot and gardenRoot.Parent == parent and gardenRoot.Visible ~= false then
        gardenRoot.AnchorPoint = Vector2.new(1, 1)
        local bpW = 0
        if backpackRoot and backpackRoot.Parent == parent and backpackRoot.Visible ~= false then
            bpW = backpackRoot.AbsoluteSize.X
            if bpW < 8 then bpW = 72 end
        end
        -- Pakai lebar backpack (AbsoluteSize), bukan AbsolutePosition — lebih stabil
        gardenRoot.Position = UDim2.fromOffset(sx - bpW - 8, sy)
        _styleTotalChildren(gardenRoot, z)
    end
end

local function _deferLayoutBadges(parent, gardenRoot, backpackRoot, searchBox, fruitHeader)
    task.defer(function()
        if not (parent and parent.Parent) then return end
        _layoutTotalBadges(parent, gardenRoot, backpackRoot, searchBox, fruitHeader)
        -- Pass ke-2 setelah AutomaticSize settle
        task.defer(function()
            if parent and parent.Parent then
                _layoutTotalBadges(parent, gardenRoot, backpackRoot, searchBox, fruitHeader)
            end
        end)
    end)
end

local function _readGardenValueSummary()
    local eg = G.EspFruitGarden or rawget(_G, "EspFruitGarden")
    if type(eg) ~= "table" then return { count = 0, total = 0 } end

    -- Peek cache dulu. Jangan kick SumRipe kalau cache sudah ready (reconnect/monitor jangan ganggu).
    local now = os.clock()
    if type(eg.PeekGardenValue) == "function" then
        local ok, sum = pcall(eg.PeekGardenValue, eg)
        if ok and type(sum) == "table" and (sum.ready == true or (tonumber(sum.count) or 0) > 0) then
            local cacheAge = tonumber(sum.at) and (now - tonumber(sum.at)) or 999
            if cacheAge < GARDEN_VALUE_KICK_SEC then
                return {
                    count = tonumber(sum.count) or 0,
                    total = tonumber(sum.total) or 0,
                }
            end
        end
    end
    if (now - _lastGardenValueKickAt) >= GARDEN_VALUE_KICK_SEC then
        _lastGardenValueKickAt = now
        if type(eg.ComputeGardenValue) == "function" then
            pcall(eg.ComputeGardenValue, eg)
        elseif type(eg.computeGardenValue) == "function" then
            pcall(eg.computeGardenValue, eg)
        end
    end

    if type(eg.PeekGardenValue) == "function" then
        local ok, sum = pcall(eg.PeekGardenValue, eg)
        if ok and type(sum) == "table" then
            return {
                count = tonumber(sum.count) or 0,
                total = tonumber(sum.total) or 0,
            }
        end
    end

    return {
        count = tonumber(gardenCache.count) or 0,
        total = tonumber(gardenCache.total) or 0,
    }
end

local function _tickGardenBadge()
    if not running or not _cfg().enabled or not bpOpen then return end
    local ctx = _findBackpackContext()
    if not ctx then return end

    local summary = _readGardenValueSummary()
    gardenCache.count = summary.count
    gardenCache.total = summary.total

    -- Hanya update teks; posisi badge tetap di-_layout dari _scanOnce.
    local parent = _getBadgeParent(ctx.searchBox, ctx.fruitHeader, ctx.inventory)
    if not parent then return end
    local gardenRoot = parent:FindFirstChild(TAG_GARDEN_TOTAL)
    if not gardenRoot then
        gardenRoot = _ensureGardenTotalLabel(parent)
    end
    if gardenRoot then
        gardenRoot.Visible = true
        _setGardenTotalText(gardenRoot, gardenCache)
    end
end

local function _gardenLoop()
    while running do
        if _cfg().enabled and bpOpen then
            pcall(_tickGardenBadge)
        end
        task.wait(GARDEN_SCAN_SEC)
    end
end

