local function _clearAllEsp()
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return end
    for _, inst in ipairs(pg:GetDescendants()) do
        if inst.Name == TAG_SLOT
            or inst.Name == TAG_TOTAL
            or inst.Name == TAG_GARDEN_TOTAL
            or inst.Name == "_GAG2FBP_TOTALS_ROW" then
            pcall(function() inst:Destroy() end)
        end
    end
end

----------------------------------------------------------------
-- Scan: tampilkan SEMUA ESP dulu (cepat), tiap 1 detik retry yang masih 0
----------------------------------------------------------------

local function _collectUiSlots(ctx)
    local slots, seen = {}, {}
    local areas, areaSeen = {}, {}
    local function addArea(inst)
        if inst and _isVisible(inst) and not areaSeen[inst] then
            areaSeen[inst] = true
            areas[#areas + 1] = inst
        end
    end
    addArea(ctx.fruitGrid)
    addArea(ctx.hotbar)
    for _, hb in ipairs(_findHotbarRoots(ctx)) do addArea(hb) end
    if #areas == 0 then return slots end

    for _, area in ipairs(areas) do
        for _, lbl in ipairs(area:GetDescendants()) do
            if lbl:IsA("TextLabel") and lbl.Visible and lbl.Name ~= TAG_SLOT then
                if lbl.Name ~= "ToolCount" and not _parseKg(lbl.Text) then
                    continue
                end
                local kg = _parseKg(lbl.Text)
                if kg and kg > 0 and not lbl.Text:match("%d+/%d+") then
                    local root = _findSlotRoot(lbl)
                    if root and not seen[root] and _isVisible(root) then
                        local uiName = _slotNameFromRoot(root, lbl)
                        if not _isNonFruitSlot(uiName) then
                            seen[root] = true
                            slots[#slots + 1] = {
                                root = root,
                                name = uiName,
                                kg = kg,
                                id = _slotId(root),
                            }
                        end
                    end
                end
            end
        end
    end
    return slots
end

local function _cachedPrice(entry)
    if not entry then return 0 end
    return priceByKey[_priceCacheKey(entry, _cfg().price_mode)] or 0
end

local function _sumInventoryTotal(fruits)
    local seen, total = {}, 0
    for _, e in ipairs(fruits) do
        local key = _usedKey(e)
        if not seen[key] then
            seen[key] = true
            _syncEntryBidFromTool(e)
            local price = _cachedPrice(e)
            if price <= 0 then
                price = _fetchPrice(e, false)
            end
            if price > 0 then total += price end
        end
    end
    return total
end

local function _fetchEntriesBatch(entries, predicate)
    local mode = _syncPriceModeCache()
    local toFetch, seenKey = {}, {}
    for _, entry in ipairs(entries) do
        if entry then
            local key = _priceCacheKey(entry, mode)
            if predicate(entry, key) and not seenKey[key] then
                seenKey[key] = true
                toFetch[#toFetch + 1] = entry
            end
        end
    end
    if #toFetch == 0 then return end

    local MAX_FETCH_THREADS = 8
    local idx = 1
    local left = #toFetch
    local deadline = os.clock() + FETCH_WAIT_SEC

    while left > 0 and os.clock() < deadline do
        local batch = math.min(MAX_FETCH_THREADS, left, #toFetch - idx + 1)
        if batch <= 0 then break end
        for _ = 1, batch do
            local entry = toFetch[idx]
            idx += 1
            task.spawn(function()
                pcall(_fetchPrice, entry, true)
                left -= 1
            end)
        end
        task.wait(0.05)
    end
end

local function _fetchAllMissing(entries)
    _fetchEntriesBatch(entries, function(_, key)
        return (priceByKey[key] or 0) <= 0
    end)
end

local function _refreshCachedPrices(entries)
    _fetchEntriesBatch(entries, function(_, key)
        return (priceByKey[key] or 0) > 0
    end)
end

local function _scanOnce(ctx)
    local slots = _collectUiSlots(ctx)
    local fruits, byId = _allFruits()
    if #slots == 0 and #fruits == 0 then return false end

    local used, rows, entries = {}, {}, {}

    for _, slot in ipairs(slots) do
        local entry = _matchFruit(slot.name, slot.kg, slot.id, fruits, byId, used)
        rows[#rows + 1] = { slot = slot, entry = entry }
        if entry then entries[#entries + 1] = entry end
    end

    _fetchAllMissing(fruits)

    local now = os.clock()
    if (now - lastCachedRefreshAt) >= REFRESH_CACHED_SEC then
        lastCachedRefreshAt = now
        task.spawn(function()
            pcall(_refreshCachedPrices, fruits)
        end)
    end

    local total, seen, hasPending = _sumInventoryTotal(fruits), {}, false
    do
        local uniq, n = {}, 0
        for _, e in ipairs(fruits) do
            local key = _usedKey(e)
            if not uniq[key] then
                uniq[key] = true
                n += 1
            end
        end
        local prevTotal = tonumber(backpackValueCache.total) or 0
        backpackValueCache.count = n
        backpackValueCache.total = total
        backpackValueCache.at = os.clock()
        backpackValueCache.ready = true
        -- Total berubah → invalidate type cache biar web/monitor ikut update (tanpa fetch berat).
        if math.abs(total - prevTotal) > math.max(1, prevTotal * 0.02) then
            _invalidateTypeValueCache()
        end
    end
    for _, row in ipairs(rows) do
        seen[row.slot.root] = true
        local esp = _ensureSlotLabel(row.slot.root)
        esp.Visible = true
        if row.entry then _syncEntryBidFromTool(row.entry) end
        local price = _cachedPrice(row.entry)
        if price <= 0 then hasPending = true end
        esp.Text = _formatPrice(price)
    end

    local parent = _getBadgeParent(ctx.searchBox, ctx.fruitHeader, ctx.inventory)
    local totalRoot = parent and _ensureTotalLabel(ctx.fruitHeader, ctx.searchBox, ctx.inventory)
    if totalRoot then _setTotalText(totalRoot, total) end

    -- Badge G tampil langsung (0 / cache); value dihitung async di worker.
    do
        local summary = _readGardenValueSummary()
        if summary then
            gardenCache.count = summary.count
            gardenCache.total = summary.total
        end
    end
    local gardenRoot = parent and _ensureGardenTotalLabel(parent)
    if gardenRoot then
        gardenRoot.Visible = true
        _setGardenTotalText(gardenRoot, gardenCache)
    end

    if parent then
        _layoutTotalBadges(parent, gardenRoot, totalRoot, ctx.searchBox, ctx.fruitHeader)
        _deferLayoutBadges(parent, gardenRoot, totalRoot, ctx.searchBox, ctx.fruitHeader)
    end

    for _, inst in ipairs(ctx.screenGui:GetDescendants()) do
        if inst.Name == TAG_SLOT and inst.Parent and not seen[inst.Parent] then
            inst:Destroy()
        end
    end
    return hasPending
end

local function _scanLoop()
    while running do
        if _cfg().enabled then
            local ctx = _findBackpackContext()
            if ctx then
                bpOpen = true
                pcall(function() _scanOnce(ctx) end)
            else
                if bpOpen then
                    bpOpen = false
                    _clearAllEsp()
                end
            end
        end
        task.wait(SCAN_SEC)
    end
end

function M.SetEnabled(a, b)
    local on = a
    if type(a) == "table" then
        on = b
    end
    on = (on == true)
    G.FRUIT_BACKPACK_ESP_ENABLED = on
    _G.FRUIT_BACKPACK_ESP_ENABLED = on
    if on then M.Start() else M.Stop() end
end

function M.IsEnabled()
    return running
end

function M.Start()
    if running then return true end
    running = true
    G.FRUIT_BACKPACK_ESP_ENABLED = true
    _G.FRUIT_BACKPACK_ESP_ENABLED = true
    if scanThread then task.cancel(scanThread) end
    scanThread = task.spawn(_scanLoop)
    if gardenThread then task.cancel(gardenThread) end
    gardenThread = task.spawn(_gardenLoop)
    return true
end

function M.ClearPriceCache()
    table.clear(priceByKey)
    lastCachedRefreshAt = 0
    backpackValueCache.count = 0
    backpackValueCache.total = 0
    backpackValueCache.at = 0
    backpackValueCache.ready = false
    if type(typeValueCache) == "table" then
        typeValueCache.at = 0
        typeValueCache.rows = nil
        typeValueCache.total = 0
        typeValueCache.count = 0
        typeValueCache.ready = false
    end
    typeValueFetchAt = 0
end

function M.SetPriceMode(mode)
    mode = (tostring(mode or ""):lower() == "stock") and "stock" or "base"
    G.FRUIT_BACKPACK_ESP_PRICE_MODE = mode
    _G.FRUIT_BACKPACK_ESP_PRICE_MODE = mode
    G.FRUIT_PRICE_INCLUDE_FRIEND_BOOST = (mode == "stock")
    _G.FRUIT_PRICE_INCLUDE_FRIEND_BOOST = (mode == "stock")
    local fsv = _fsv()
    if fsv then
        if type(fsv.setEspPriceMode) == "function" then
            pcall(fsv.setEspPriceMode, mode)
        elseif type(fsv.clearBidCache) == "function" then
            pcall(fsv.clearBidCache)
        end
    end
    lastPriceMode = nil
    M.ClearPriceCache()
end

function M.Stop()
    running = false
    bpOpen = false
    lastCachedRefreshAt = 0
    if scanThread then task.cancel(scanThread) scanThread = nil end
    if gardenThread then task.cancel(gardenThread) gardenThread = nil end
    -- Jangan clear priceByKey / value cache: monitor masih butuh saat ESP off.
    gardenCache.count = 0
    gardenCache.total = 0
    G.FRUIT_BACKPACK_ESP_ENABLED = false
    _G.FRUIT_BACKPACK_ESP_ENABLED = false
    _clearAllEsp()
end

function M.SyncFromGlobals()
    local cfg = _cfg()
    local prevMode = lastPriceMode
    G.FRUIT_BACKPACK_ESP_ENABLED = cfg.enabled
    _G.FRUIT_BACKPACK_ESP_ENABLED = cfg.enabled
    G.FRUIT_BACKPACK_ESP_PRICE_MODE = cfg.price_mode
    _G.FRUIT_BACKPACK_ESP_PRICE_MODE = cfg.price_mode
    -- Clear harga hanya kalau mode berubah / baru enable — jangan wipe saat ESP dimatikan.
    if prevMode ~= nil and prevMode ~= cfg.price_mode then
        lastPriceMode = nil
        pcall(M.ClearPriceCache)
    else
        lastPriceMode = cfg.price_mode
    end
    if cfg.enabled then M.Start() else M.Stop() end
    return cfg
end

-- API untuk AutoFav / modul lain: scan + harga sama seperti ESP backpack (cepat, cache)
function M.ScanFruits()
    return _allFruits()
end

function M.GetCachedEntryPrice(entry)
    if not entry then return 0 end
    _syncEntryBidFromTool(entry)
    local mode = _syncPriceModeCache()
    return priceByKey[_priceCacheKey(entry, mode)] or 0
end

function M.GetEntryPrice(entry, force)
    if not entry then return 0 end
    _syncEntryBidFromTool(entry)
    if not force then
        local cached = M.GetCachedEntryPrice(entry)
        if cached > 0 then return cached end
    end
    return _fetchPrice(entry, force == true)
end

-- Total value buah di backpack (sama sumber harga dengan badge S di ESP).
function M.PeekBackpackValue()
    return {
        count = backpackValueCache.count,
        total = backpackValueCache.total,
        ready = backpackValueCache.ready == true,
    }
end

M.peekBackpackValue = M.PeekBackpackValue

-- Total value per tipe fruit. Cache singkat; recompute kalau Peek/ESP total berubah.
-- Fetch missing hanya saat ESP off (ESP on → scan loop yang isi harga).
function M.GetValueByType(a, b)
    local force = false
    local opts = a
    if type(a) == "table" and type(a.GetValueByType) == "function" then
        opts = b
    end
    if type(opts) == "table" then
        force = opts.force == true
    elseif opts == true then
        force = true
    end

    local now = os.clock()
    local peekTotal = tonumber(backpackValueCache.total) or 0
    local peekReady = backpackValueCache.ready == true

    if not force and type(typeValueCache.rows) == "table"
        and (now - (tonumber(typeValueCache.at) or 0)) < TYPE_VALUE_CACHE_SEC then
        local cachedTotal = tonumber(typeValueCache.total) or 0
        local stillValid = true
        if peekReady and peekTotal > 0 and cachedTotal > 0 then
            local ratio = cachedTotal / peekTotal
            if ratio < 0.88 or ratio > 1.12 then
                stillValid = false -- inventory/harga berubah → hitung ulang dari cache harga
            end
        elseif peekReady and peekTotal > 0 and cachedTotal <= 0 then
            stillValid = false
        end
        if stillValid then
            return {
                rows = typeValueCache.rows,
                total = typeValueCache.total,
                count = typeValueCache.count,
                ready = typeValueCache.ready == true,
                source = "EspFruitBackpack.GetValueByType.cache",
            }
        end
    end

    local fruits = _allFruits()
    local grouped, seen = {}, {}
    local total, count, priced = 0, 0, 0
    local missingList = {}
    local function _accumulate(fruitsList)
        grouped, seen = {}, {}
        total, count, priced = 0, 0, 0
        missingList = {}
        for _, e in ipairs(fruitsList) do
            local uk = _usedKey(e)
            if not seen[uk] then
                seen[uk] = true
                count += 1
                _syncEntryBidFromTool(e)
                local price = _cachedPrice(e)
                if price <= 0 then
                    missingList[#missingList + 1] = e
                end
                local name = tostring(e.name or "")
                -- Harvested fruit label: buang suffix "Seed" kalau masih ikut dari shop resolver.
                name = name:gsub("%s+[Ss]eed%s*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
                if name ~= "" then
                    local key = _norm(name)
                    local slot = grouped[key]
                    if not slot then
                        slot = { name = name, count = 0, value = 0 }
                        grouped[key] = slot
                    end
                    slot.count += 1
                    if price > 0 then
                        slot.value += price
                        total += price
                        priced += 1
                    end
                elseif price > 0 then
                    total += price
                    priced += 1
                end
            end
        end
    end
    _accumulate(fruits)

    -- ESP scan hanya isi harga saat UI backpack terbuka (bpOpen).
    -- Kalau backpack tertutup / peek masih 0, fetch sync terbatas di sini
    -- supaya monitor tidak kirim fruit count dengan value 0 selamanya.
    local scanFillingPrices = running == true and _cfg().enabled == true and bpOpen == true
    local needFetch = #missingList > 0 and (not scanFillingPrices or peekTotal <= 0 or total <= 0)
    if needFetch and (now - typeValueFetchAt) >= TYPE_VALUE_FETCH_GAP then
        typeValueFetchAt = now
        local batch = {}
        local n = math.min(TYPE_VALUE_FETCH_MAX, #missingList)
        for i = 1, n do
            batch[i] = missingList[i]
        end
        -- Sync (bukan spawn): stats tick menunggu batch kecil supaya value ikut.
        pcall(_fetchAllMissing, batch)
        _accumulate(fruits)
    end

    local rows = {}
    for _, slot in pairs(grouped) do
        rows[#rows + 1] = {
            name = slot.name,
            count = math.floor(tonumber(slot.count) or 0),
            value = math.floor(tonumber(slot.value) or 0),
        }
    end
    table.sort(rows, function(a, b)
        local va, vb = tonumber(a.value) or 0, tonumber(b.value) or 0
        if va ~= vb then return va > vb end
        return tostring(a.name) < tostring(b.name)
    end)

    local pricesReady = (count == 0) or (total > 0 and priced > 0)
    typeValueCache.at = now
    typeValueCache.rows = rows
    typeValueCache.total = total
    typeValueCache.count = count
    typeValueCache.ready = pricesReady

    -- Samakan badge S cache (boleh naik/turun).
    if pricesReady or (peekReady and peekTotal > 0) then
        local useTotal = total
        local useCount = count
        if (not pricesReady or total <= 0) and peekTotal > 0 then
            useTotal = peekTotal
            useCount = tonumber(backpackValueCache.count) or count
        end
        backpackValueCache.count = useCount
        backpackValueCache.total = useTotal
        backpackValueCache.at = now
        backpackValueCache.ready = true
    elseif count > 0 and total > 0 then
        backpackValueCache.count = count
        backpackValueCache.total = total
        backpackValueCache.at = now
        backpackValueCache.ready = true
    end

    return {
        rows = rows,
        total = (total > 0 and total) or peekTotal,
        count = count,
        ready = pricesReady or (peekReady and peekTotal > 0) or total > 0,
        source = "EspFruitBackpack.GetValueByType",
        esp_enabled = _cfg().enabled == true,
    }
end

M.getValueByType = M.GetValueByType

function M.ComputeBackpackValue(a, b)
    local force = false
    local opts = a
    if type(a) == "table" and type(a.ComputeBackpackValue) == "function" then
        opts = b
    end
    if type(opts) == "table" then
        force = opts.force == true
    elseif opts == true then
        force = true
    end

    -- Pakai cache singkat kalau tidak force (hindari block tiap tick stats).
    if not force and backpackValueCache.ready and (os.clock() - (backpackValueCache.at or 0)) < 3 then
        return M.PeekBackpackValue()
    end

    local fruits = _allFruits()
    _fetchAllMissing(fruits)

    local seen, count, total = {}, 0, 0
    for _, e in ipairs(fruits) do
        local key = _usedKey(e)
        if not seen[key] then
            seen[key] = true
            count += 1
            _syncEntryBidFromTool(e)
            local price = _cachedPrice(e)
            if price <= 0 then
                price = _fetchPrice(e, false)
            end
            if price > 0 then total += price end
        end
    end

    backpackValueCache.count = count
    backpackValueCache.total = total
    backpackValueCache.at = os.clock()
    backpackValueCache.ready = true

    return {
        count = count,
        total = total,
        ready = true,
        source = "EspFruitBackpack",
    }
end

M.computeBackpackValue = M.ComputeBackpackValue

M.scanFruits = M.ScanFruits
M.getEntryPrice = M.GetEntryPrice
M.getCachedEntryPrice = M.GetCachedEntryPrice

G.EspFruitBackpack = M
_G.EspFruitBackpack = M

return M
 end,               required = false },
    { key = "EspFruitGarden",          name = "ESP Fruit Garden",        factory = function() -- EspFruitGarden.lua — ESP buah di plot (nama, kg, rarity, harga)
-- Tampilkan top N buah di plot sesuai priority (kg / price) dari UI.

local Players           = game:GetService("Players")
local RunService        = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
if not LP then
    Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
    LP = Players.LocalPlayer
end
if not LP then
    LP = Players.PlayerAdded:Wait()
end
local G  = (getgenv and getgenv()) or _G
local M  = {}

local TAG_ROOT  = "_GAG2FG_ESP"
local HARVEST_TAG = "HarvestPrompt"
-- Sync GetGarden 5–7 detik (ESP + badge G). Jangan poll sub-detik.
local POLL_SEC_LIGHT = 6.0
local POLL_SEC_MED   = 6.0
local POLL_SEC_HEAVY = 7.0
local POLL_SEC_RF_LIGHT = 6.0
local POLL_SEC_RF_MED   = 6.5
local POLL_SEC_RF_HEAVY = 7.0
local PLOT_CACHE_SEC = 3.0
local DEFAULT_MAX_ESP = 100
-- Saat priority price: prefilter by kg dulu, baru hitung harga (hindari price × 1000 buah)
local PRICE_PREFILTER_MULT = 2
local MAX_PRICE_EVAL = 48
local PROMPT_COMPACT_EVERY = 8
local ESP_FSV_SOFT_SEC = 30
local ESP_HARD_LABEL_CAP = 250 -- hard cap Billboard, meski UI max_esp lebih besar
local SCAN_YIELD_EVERY = 220 -- yield saat scan massal biar frame aman

local COL_BG     = Color3.fromRGB(18, 22, 16)
local COL_STROKE = Color3.fromRGB(255, 210, 60)
local COL_GLOW   = Color3.fromRGB(255, 196, 45)

local RARITY_HEX = {
    common    = "#9CA3AF",
    uncommon  = "#34D399",
    rare      = "#60A5FA",
    epic      = "#A78BFA",
    legendary = "#FB923C",
    mythic    = "#F87171",
    divine    = "#FBBF24",
    secret    = "#F472B6",
    super     = "#E879F9",
}

local running = false
local conn = nil
local tickGen = 0
local tickBusy = false
local lastPoll = 0
local nextPollSec = POLL_SEC_LIGHT
local lastFsvSoftAt = 0
local cachedPlot = nil
local cachedPlotAt = 0
local espByKey = {}
local espPriceCache = {} -- [key] = { price, sig }
local summaryCache = { count = 0, total = 0 }
-- Total ripe GetGarden (badge G backpack). Dideklarasi di atas supaya ESP scan bisa pakai cache yang sama.
local gardenValueCache = { count = 0, total = 0, at = 0, ready = false }

-- Matikan instance lama (reload script) supaya Heartbeat lama tidak terus buat ESP
do
    local prev = G.EspFruitGarden or rawget(_G, "EspFruitGarden")
    if type(prev) == "table" and prev ~= M and type(prev.Stop) == "function" then
        pcall(prev.Stop, prev)
    end
end

-- Incremental harvest-prompt index (hindari plot:GetDescendants tiap tick)
local promptCache = {}
local promptSet = {}
local promptPlot = nil
local promptConns = {}
local promptScanGen = 0
local lastFruitCount = 0

local FruitSellValue
pcall(function()
    FruitSellValue = require(script.Parent.FruitSellValue)
end)
if type(FruitSellValue) ~= "table" then
    FruitSellValue = G.FruitSellValue or _G.FruitSellValue
end

local function _normalizePriority(v)
    v = tostring(v or ""):lower()
    if v == "price" then return "price" end
    return "kg"
end

local function _clampMaxEsp(n)
    n = math.floor(tonumber(n) or DEFAULT_MAX_ESP)
    if n < 1 then n = 1 end
    if n > 5000 then n = 5000 end
    -- Billboard mahal: cap label aktif biar CPU aman
    if n > ESP_HARD_LABEL_CAP then n = ESP_HARD_LABEL_CAP end
    return n
end

local function _fruitSetFrom(src)
    if type(src) ~= "table" then return {} end
    local out = {}
    if src[1] ~= nil then
        for _, v in ipairs(src) do
            local s = tostring(v)
            if s ~= "" then out[s] = true end
        end
    else
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            end
        end
    end
    return out
end

local function _canonFruitName(s)
    return tostring(s or ""):lower():gsub("[%s_%-]+", "")
end

local function _hasFruitFilter(map)
    if type(map) ~= "table" then return false end
    for _, v in pairs(map) do
        if v == true then return true end
    end
    return false
end

local function _matchFruitFilter(selectedMap, name)
    if not _hasFruitFilter(selectedMap) then return true end
    local needle = _canonFruitName(name)
    if needle == "" then return false end
    for k, v in pairs(selectedMap) do
        if v == true and _canonFruitName(k) == needle then
            return true
        end
    end
    return false
end

local function _cfg()
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local st = MAIN and MAIN.misc and MAIN.misc.fruit_garden_esp
    st = type(st) == "table" and st or {}
    -- Jangan OR semua sumber: satu yang true menahan ESP tetap hidup saat toggle OFF
    local enabled
    if G.FRUIT_GARDEN_ESP_ENABLED ~= nil then
        enabled = (G.FRUIT_GARDEN_ESP_ENABLED == true)
    elseif rawget(_G, "FRUIT_GARDEN_ESP_ENABLED") ~= nil then
        enabled = (rawget(_G, "FRUIT_GARDEN_ESP_ENABLED") == true)
    else
        enabled = (st.enabled == true)
    end
    local priority = G.FRUIT_GARDEN_ESP_PRIORITY
        or rawget(_G, "FRUIT_GARDEN_ESP_PRIORITY")
        or st.priority
    local maxEsp = G.FRUIT_GARDEN_ESP_MAX
        or rawget(_G, "FRUIT_GARDEN_ESP_MAX")
        or st.max_esp
    local fruits = G.FRUIT_GARDEN_ESP_FRUITS_SELECTED
        or rawget(_G, "FRUIT_GARDEN_ESP_FRUITS_SELECTED")
        or st.fruits
    return {
        enabled = enabled,
        priority = _normalizePriority(priority),
        max_esp = _clampMaxEsp(maxEsp),
        fruits = _fruitSetFrom(fruits),
    }
end

-- Remove Garden / ReduceFPS ON → plot tetap penuh HarvestPrompt (soft shell)
local function _reduceGardenActive()
    if G.REDUCE_FPS_ENABLED == true or rawget(_G, "REDUCE_FPS_ENABLED") == true then
        return true
    end
    local MAIN = rawget(_G, "MAIN") or G.MAIN
    local perf = MAIN and MAIN.misc and MAIN.misc.perf
    return type(perf) == "table" and perf.enabled == true
end

local function _formatPrice(n)
    n = tonumber(n) or 0
    if n <= 0 then return "0" end
    if n >= 1e9 then return string.format("%.2fB", n / 1e9) end
    if n >= 1e6 then return string.format("%.2fM", n / 1e6) end
    if n >= 1e3 then return string.format("%.1fk", n / 1e3) end
    return tostring(math.floor(n))
end

local function _matchOwner(v)
    if v == nil or not LP then return false end
    return v == LP.UserId or v == LP.Name
        or tostring(v) == tostring(LP.UserId) or tostring(v) == LP.Name
end

local function _plotOwned(plot)
    if not plot then return false end
    if _matchOwner(plot:GetAttribute("OwnerId")) then return true end
    if _matchOwner(plot:GetAttribute("Owner")) then return true end
    if _matchOwner(plot:GetAttribute("OwnerUserId")) then return true end
    if _matchOwner(plot:GetAttribute("UserId")) then return true end

    for _, child in ipairs(plot:GetChildren()) do
        if child:IsA("ValueBase") then
            local n = child.Name:lower()
            if n:find("owner") or n:find("userid") or n:find("player") then
                if _matchOwner(child.Value) then return true end
            end
        end
    end

    local myPlot = LP:GetAttribute("Plot") or LP:GetAttribute("PlotName")
        or LP:GetAttribute("GardenPlot") or LP:GetAttribute("PlotId")
    if myPlot and plot.Name == tostring(myPlot) then return true end
    if myPlot and plot.Name == ("Plot" .. tostring(myPlot)) then return true end
    return false
end

local function _findPlotInGardens(gardens, plotId)
    if not gardens or plotId == nil then return nil end
    local idStr = tostring(plotId)
    for _, name in ipairs({ "Plot" .. idStr, idStr, "Plot_" .. idStr }) do
        local plot = gardens:FindFirstChild(name)
        if plot then return plot end
    end
    return nil
end

local function _getPlot(force)
    local now = os.clock()
    if not force and cachedPlot and cachedPlot.Parent and (now - cachedPlotAt) <= PLOT_CACHE_SEC then
        return cachedPlot
    end

    local autoTele = G.AutoTele or G.AutoTeleModule or rawget(_G, "AutoTele")
    if type(autoTele) == "table" and type(autoTele.GetPlayerPlot) == "function" then
        local ok, plot = pcall(autoTele.GetPlayerPlot, autoTele)
        if ok and plot and plot.Parent then
            cachedPlot = plot
            cachedPlotAt = now
            return plot
        end
    end

    local gardens = workspace:FindFirstChild("Gardens")
    if not gardens then
        cachedPlot = nil
        cachedPlotAt = now
        return nil
    end

    local plotId = LP:GetAttribute("PlotId")
    local byId = _findPlotInGardens(gardens, plotId)
    if byId then
        cachedPlot = byId
        cachedPlotAt = now
        return byId
    end

    for _, plot in ipairs(gardens:GetChildren()) do
        if _plotOwned(plot) then
            cachedPlot = plot
            cachedPlotAt = now
            return plot
        end
    end

    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Include
        params.FilterDescendantsInstances = { gardens }
        local hit = workspace:Raycast(hrp.Position + Vector3.new(0, 6, 0), Vector3.new(0, -40, 0), params)
        if hit then
            for _, plot in ipairs(gardens:GetChildren()) do
                if hit.Instance:IsDescendantOf(plot) then
                    cachedPlot = plot
                    cachedPlotAt = now
                    return plot
                end
            end
        end
    end

    local byName = gardens:FindFirstChild("Plot" .. LP.Name)
    cachedPlot = byName
    cachedPlotAt = now
    return byName
end

local function _isHarvestPrompt(prompt)
    if not prompt or not prompt:IsA("ProximityPrompt") then return false end
    if CollectionService:HasTag(prompt, HARVEST_TAG) then return true end
    local action = tostring(prompt.ActionText or ""):lower()
    if action:find("harvest", 1, true) or action:find("collect", 1, true) then
        return true
    end
    local obj = tostring(prompt.ObjectText or ""):lower()
    if obj:find("harvest", 1, true) or obj:find("fruit", 1, true) then
        return true
    end
    return tostring(prompt.Name or ""):lower():find("harvest", 1, true) ~= nil
end

-- Setelah collect / RF immature: Collected. Enabled diabaikan (Hide Harvest sering false).
-- RF ON: wajib tag HarvestPrompt (immature shell = untagged, nama tetap "HarvestPrompt").
local function _promptHarvestLive(prompt)
    if not prompt or not prompt.Parent then return false end
    if not prompt:IsA("ProximityPrompt") then return false end
    if prompt:GetAttribute("Collected") then return false end
    if _reduceGardenActive() then
        local tagged = false
        pcall(function()
            tagged = CollectionService:HasTag(prompt, HARVEST_TAG)
        end)
        if not tagged then return false end
        return true
    end
    if not _isHarvestPrompt(prompt) then return false end
    return true
end

local function _wipe(t)
    for k in pairs(t) do
        t[k] = nil
    end
end

local function _clearPromptCache()
    for _, c in ipairs(promptConns) do
        pcall(function() c:Disconnect() end)
    end
    for i = #promptConns, 1, -1 do promptConns[i] = nil end
    for i = #promptCache, 1, -1 do promptCache[i] = nil end
    _wipe(promptSet)
    promptPlot = nil
    promptScanGen = 0
end

local function _tryIndexPrompt(prompt)
    if not prompt or not prompt:IsA("ProximityPrompt") then return end
    if promptSet[prompt] then return end
    -- RF ON: soft-shell immature tetap nama "HarvestPrompt" tapi UNTAGGED.
    -- Index nama-only → cache 30k+ padahal buah ~4k (AC ikut lambat).
    if _reduceGardenActive() then
        local tagged = false
        pcall(function()
            tagged = CollectionService:HasTag(prompt, HARVEST_TAG)
        end)
        if not tagged then return end
    elseif not _isHarvestPrompt(prompt) then
        return
    end
    promptSet[prompt] = true
    promptCache[#promptCache + 1] = prompt
end

local function _compactPromptCache()
    local live = {}
    for i = 1, #promptCache do
        local p = promptCache[i]
        if p and p.Parent and promptSet[p] then
            -- RF: buang yang kehilangan tag (immature / seal)
            if _reduceGardenActive() then
                local tagged = false
                pcall(function()
                    tagged = CollectionService:HasTag(p, HARVEST_TAG)
                end)
                if not tagged then
                    promptSet[p] = nil
                    continue
                end
            end
            live[#live + 1] = p
        elseif p then
            promptSet[p] = nil
        end
    end
    promptCache = live
end

local function _rebuildPromptCache(plot)
    _clearPromptCache()
    if not plot or not plot.Parent then return end
    promptPlot = plot

    -- RF: GetTagged saja (mature). GetDescendants nama-only = kembung parah.
    -- Monitor/INFO juga harus GetTagged dulu — plot kosong pun GetDescendants bisa 1000ms+.
    do
        local okTag, tagged = pcall(function()
            return CollectionService:GetTagged(HARVEST_TAG)
        end)
        if okTag and type(tagged) == "table" then
            for i = 1, #tagged do
                local p = tagged[i]
                if p and p:IsA("ProximityPrompt") and p:IsDescendantOf(plot) then
                    _tryIndexPrompt(p)
                end
            end
        elseif not _reduceGardenActive() then
            -- Fallback jarang: hanya kalau CollectionService gagal
            for _, d in ipairs(plot:GetDescendants()) do
                if d:IsA("ProximityPrompt") then
                    _tryIndexPrompt(d)
                end
            end
        end
    end

    table.insert(promptConns, plot.DescendantAdded:Connect(function(d)
        if d:IsA("ProximityPrompt") then
            _tryIndexPrompt(d)
        end
    end))
    table.insert(promptConns, plot.DescendantRemoving:Connect(function(d)
        if promptSet[d] then
            promptSet[d] = nil
        end
    end))

    local okTagAdd, tagAddSignal = pcall(function()
        return CollectionService:GetInstanceAddedSignal(HARVEST_TAG)
    end)
    if okTagAdd and tagAddSignal then
        table.insert(promptConns, tagAddSignal:Connect(function(inst)
            if promptPlot and inst:IsA("ProximityPrompt") and inst:IsDescendantOf(promptPlot) then
                _tryIndexPrompt(inst)
            end
        end))
    end
end

local function _ensurePromptCache(plot)
    if not plot then
        _clearPromptCache()
        return promptCache
    end
    if promptPlot ~= plot then
        _rebuildPromptCache(plot)
    end
    promptScanGen += 1
    if promptScanGen % PROMPT_COMPACT_EVERY == 0 then
        _compactPromptCache()
    end
    return promptCache
end

local function _adaptivePollSec(fruitCount)
    fruitCount = tonumber(fruitCount) or 0
    local rf = _reduceGardenActive()
    if fruitCount >= 800 then
        return rf and POLL_SEC_RF_HEAVY or POLL_SEC_HEAVY
    end
    if fruitCount >= 350 then
        return rf and POLL_SEC_RF_MED or POLL_SEC_MED
    end
    if rf and fruitCount >= 120 then
        return POLL_SEC_RF_LIGHT
    end
    return rf and POLL_SEC_RF_LIGHT or POLL_SEC_LIGHT
end

-- top sorted descending (index 1 = terbaik). Evict worst di ujung.
local function _betterByKg(a, b)
    if a.kg ~= b.kg then return a.kg > b.kg end
    return a.key < b.key
end

local function _pushTopByKg(top, item, maxKeep)
    local n = #top
    if n < maxKeep then
        top[n + 1] = item
        local i = n + 1
        while i > 1 and _betterByKg(top[i], top[i - 1]) do
            top[i], top[i - 1] = top[i - 1], top[i]
            i -= 1
        end
        return
    end
    local worst = top[n]
    if item.kg < worst.kg then return end
    if item.kg == worst.kg and item.key >= worst.key then return end
    top[n] = item
    local i = n
    while i > 1 and _betterByKg(top[i], top[i - 1]) do
        top[i], top[i - 1] = top[i - 1], top[i]
        i -= 1
    end
end

local function _fruitFromPrompt(prompt)
    if not prompt or not prompt.Parent then return nil end
    local node, best = prompt.Parent, nil
    while node do
        if node:IsA("Model") then
            local pid = node:GetAttribute("PlantId")
            if pid ~= nil and tostring(pid) ~= "" then
                best = node
                if node:GetAttribute("FruitId") ~= nil then return node end
            end
        end
        if node.Name == "Gardens" then break end
        node = node.Parent
    end
    return best or prompt.Parent:FindFirstAncestorWhichIsA("Model")
end

local function _resolveIds(model)
    if not model then return "", "" end
    local plantId, fruitId = "", ""
    local node, depth = model, 0
    while node and depth < 12 do
        if node:IsA("Model") then
            if plantId == "" then
                local p = node:GetAttribute("PlantId")
                if p ~= nil and tostring(p) ~= "" then plantId = tostring(p) end
            end
            if fruitId == "" then
                local f = node:GetAttribute("FruitId")
                if f ~= nil and tostring(f) ~= "" then fruitId = tostring(f) end
            end
        end
        if node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    return plantId, fruitId
end

local function _fsv()
    local f = FruitSellValue or G.FruitSellValue or _G.FruitSellValue
    return type(f) == "table" and f or nil
end

local function _parseKgText(text)
    return tonumber(tostring(text or ""):match("([%d%.]+)%s*[kK][gG]"))
end

local function _parsePriceText(text)
    text = tostring(text or "")
    if text:lower():find("kg", 1, true) then return nil end
    local s = text:gsub(",", "")
    local n = tonumber(s:match("([%d%.]+)%s*[kK]"))
    if n then return n * 1000 end
    n = tonumber(s:match("([%d%.]+)%s*[mM]"))
    if n then return n * 1000000 end
    n = tonumber(s:match("([%d%.]+)%s*[bB]"))
    if n then return n * 1000000000 end
    n = tonumber(s:match("[$%s]*([%d%.]+)"))
    if n and n > 0 then return n end
    return nil
end

local function _readGameBillboard(model)
    if not model then return nil, nil, nil end
    local kg, price, rarity = nil, nil, nil
    for _, d in ipairs(model:GetDescendants()) do
        if d:IsA("TextLabel") and d.Name ~= TAG_ROOT then
            local t = d.Text or ""
            local w = _parseKgText(t)
            if w and w > 0 and (not kg or w > kg) then kg = w end
            local p = _parsePriceText(t)
            if p and p > 0 and (not price or p < price) then price = p end
            if not rarity and t ~= "" and not _parseKgText(t) and not _parsePriceText(t) then
                local low = t:lower()
                if low:find("common") or low:find("uncommon") or low:find("rare")
                    or low:find("epic") or low:find("legend") or low:find("myth")
                    or low:find("divine") or low:find("secret") then
                    rarity = t
                end
            end
        end
    end
    return kg, price, rarity
end

local function _walkModels(model, fn, maxDepth)
    maxDepth = maxDepth or 12
    local node, depth = model, 0
    while node and depth < maxDepth do
        if node:IsA("Model") then
            local stop = fn(node)
            if stop then return stop end
        end
        if node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    return nil
end

-- FVC CalculateFruitWeight: GrowData.BaseWeight * (SizeMulti or 1) * overtime
-- Shell RF stamp: BaseWeight + SizeMulti + OvertimeGrowth (+ Weight cache rumus sama)
local function _kgFromAttributes(model)
    local walked = _walkModels(model, function(node)
        local sm = tonumber(node:GetAttribute("SizeMulti")) or 1
        local og = tonumber(node:GetAttribute("OvertimeGrowth")) or 1
        if og <= 0 then og = 1 end
        local bw = tonumber(node:GetAttribute("BaseWeight"))
        if bw and bw > 0 and sm > 0 then
            return bw * sm * og
        end
        -- Weight cache dari stamp RF (= rumus FVC). Abaikan kalau = BaseWeight mentah.
        local w = tonumber(node:GetAttribute("Weight"))
        if w and w > 0 then
            if bw and bw > 0 and math.abs(w - bw) <= 1e-3 and sm <= 1.0001 then
                return nil
            end
            return w
        end
        return nil
    end)
    return (type(walked) == "number" and walked > 0) and walked or 0
end

-- Fast path untuk mass scan: attr dulu (NO FruitVisualizer / GetDescendants)
local function _displayKgCheap(model)
    if not model then return 0 end

    local fromAttr = _kgFromAttributes(model)
    if fromAttr > 0 then return fromAttr end

    -- Fallback jarang: resolveWeight (bisa hit FruitVisualizer — mahal)
    local fsv = _fsv()
    if fsv and type(fsv.resolveWeight) == "function" then
        local ok, w = pcall(fsv.resolveWeight, model)
        if ok and type(w) == "number" and w > 0 then return w end
    end
    return 0
end

local function _displayKg(model, allowBillboard)
    if allowBillboard == nil then allowBillboard = true end

    local cheap = _displayKgCheap(model)
    if cheap > 0 then return cheap end
    if not allowBillboard then return 0 end

    local bbKg = select(1, _readGameBillboard(model))
    if bbKg and bbKg > 0 then return bbKg end

    local node, depth = model, 0
    while node and depth < 6 do
        if node:IsA("Model") then
            for _, d in ipairs(node:GetDescendants()) do
                if d:IsA("TextLabel") then
                    local w = _parseKgText(d.Text)
                    if w and w > 0 then return w end
                end
            end
        end
        if node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    return 0
end

-- Single-harvest / shell: Model.Name sering "UserId_UUID" — jangan dipakai sebagai type.
local function _looksLikeIdName(s)
    s = tostring(s or "")
    if s == "" or s == "?" then return true end
    if s:find("_", 1, true) and s:find("-", 1, true) then return true end
    return false
end

local _NAME_ATTRS = {
    "CorePartName", "FruitName", "FruitType", "ItemName", "SeedName", "DisplayName",
}

local function _pickTypeName(model)
    if not model then return nil end
    for i = 1, #_NAME_ATTRS do
        local v = model:GetAttribute(_NAME_ATTRS[i])
        if v ~= nil and tostring(v) ~= "" and not _looksLikeIdName(v) then
            return tostring(v)
        end
    end
    return nil
end

local function _fruitName(model)
    if not model then return "?" end
    local fsv = FruitSellValue or _fsv()
    if fsv and type(fsv.resolveSeedName) == "function" then
        local ok, n = pcall(fsv.resolveSeedName, model)
        if ok and type(n) == "string" and n ~= "" and not _looksLikeIdName(n) then
            return n
        end
    end
    local n = _pickTypeName(model)
    if n then return n end
    -- Single-harvest: HarvestPrompt di pohon — SeedName ada di ancestor plant
    local node, depth = model.Parent, 0
    while node and depth < 8 do
        if node:IsA("Model") then
            n = _pickTypeName(node)
            if n then return n end
        end
        if node.Name == "Plants" or node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    local fallback = tostring(model.Name or "?")
    if _looksLikeIdName(fallback) then return "?" end
    return fallback
end

local function _fruitNameCheap(model)
    if not model then return "?" end
    local n = _pickTypeName(model)
    if n then return n end
    -- Single-harvest: model = plant (Name UUID) → ambil SeedName dari diri/ancestor
    local node, depth = model, 0
    while node and depth < 8 do
        if node:IsA("Model") then
            n = _pickTypeName(node)
            if n then return n end
        end
        if node.Name == "Plants" or node.Name == "Gardens" then break end
        node = node.Parent
        depth += 1
    end
    local fallback = tostring(model.Name or "?")
    if _looksLikeIdName(fallback) then return "?" end
    return fallback
end

local function _fruitRarity(model, name)
    name = tostring(name or "")
    local fsv = _fsv()
    if fsv and type(fsv.getRarity) == "function" and name ~= "" then
        local ok, r = pcall(fsv.getRarity, name)
        if ok and type(r) == "string" and r ~= "" then return r end
    end
    -- Jangan GetDescendants di sini — rarity dari nama cukup untuk ESP mass
    return nil
end

local function _normalizeMutation(raw)
    if raw == nil then return nil end
    if type(raw) == "string" then
        raw = raw:match("^%s*(.-)%s*$")
        if raw == "" or raw:lower() == "none" or raw:lower() == "nomutation" then
            return nil
        end
        return raw
    end
    if type(raw) == "table" then
        local parts = {}
        for _, v in ipairs(raw) do
            if type(v) == "string" and v ~= "" then parts[#parts + 1] = v end
        end
        if #parts > 0 then return table.concat(parts, ",") end
    end
    return nil
end

-- Mutasi buah saja — jangan naik ke plant (parent Fruits → Plant).
local function _mutationAttrsOnNode(node)
    if not node then return nil end
    local s = _normalizeMutation(node:GetAttribute("Mutation"))
        or _normalizeMutation(node:GetAttribute("Mutations"))
        or _normalizeMutation(node:GetAttribute("MutationName"))
    if s then return s end
    -- RF soft shell: kadang cuma bool Gold/Eclipsed tanpa string Mutation
    for _, name in ipairs({
        "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
        "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil",
    }) do
        if node:GetAttribute(name) == true then
            return _normalizeMutation(name)
        end
    end
    return nil
end

local function _fruitMutation(model)
    if not model then return nil end
    local norm = _mutationAttrsOnNode(model)
    if norm then return norm end
    local fsv = _fsv()
    if fsv and type(fsv.resolveMutation) == "function" then
        local ok, m = pcall(fsv.resolveMutation, model)
        if ok then
            norm = _normalizeMutation(m)
            if norm then return norm end
        end
    end
    return nil
end

-- ESP mass: attribute Mutation di fruit model saja (tanpa walk parent/plant)
local function _fruitMutationCheap(model)
    if not model then return nil end
    return _mutationAttrsOnNode(model)
end

local function _derivePriceMulti(model)
    local fsv = _fsv()
    local kg = 0
    if fsv and type(fsv.resolveWeight) == "function" then
        local ok, w = pcall(fsv.resolveWeight, model)
        if ok then kg = tonumber(w) or 0 end
    end
    if kg <= 0 then
        kg = tonumber(_displayKg(model)) or 0
    end
    if kg <= 0 then return 0 end

    local derived = _walkModels(model, function(node)
        local bw = tonumber(node:GetAttribute("BaseWeight"))
        local og = tonumber(node:GetAttribute("OvertimeGrowth")) or 1
        if bw and bw > 0 then
            local m = kg / bw / og
            if m > 0 and m <= 25 then return m end
        end
        return nil
    end)
    return tonumber(derived) or 0
end

local function _resolvePriceMulti(model)
    if not model then return 0 end

    local fsv = _fsv()
    if fsv and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, model)
        if ok and type(m) == "number" and m > 0 and m <= 25 then
            return m
        end
    end

    local multOnly = _walkModels(model, function(node)
        local m = tonumber(node:GetAttribute("SizeMultiplier"))
        if m and m > 0 and m <= 25 then return m end
        return nil
    end)
    if type(multOnly) == "number" then return multOnly end

    local fromAttr = _walkModels(model, function(node)
        local m = tonumber(node:GetAttribute("SizeMulti"))
        if m and m > 0 and m <= 25 then return m end
        return nil
    end)
    if type(fromAttr) == "number" then return fromAttr end

    local ok, derived = pcall(_derivePriceMulti, model)
    if ok and type(derived) == "number" and derived > 0 then
        return derived
    end
    return 0
end

local function _mutationVariants(mut)
    if type(mut) ~= "string" or mut == "" then return { nil } end
    local out, seen = {}, {}
    local function add(v)
        if v == nil then
            if not seen["__nil__"] then
                seen["__nil__"] = true
                out[#out + 1] = nil
            end
            return
        end
        v = tostring(v):match("^%s*(.-)%s*$")
        if v == "" or seen[v] then return end
        seen[v] = true
        out[#out + 1] = v
    end
    add(mut)
    for token in string.gmatch(mut, "[^%+%,]+") do
        add(token)
    end
    add(nil)
    return out
end

local function _calcWithMutations(fsv, name, multi, mut, decay)
    if type(fsv.calculate) ~= "function" or multi <= 0 or name == "" then
        return 0
    end
    for _, variant in ipairs(_mutationVariants(mut)) do
        local ok, p = pcall(fsv.calculate, name, multi, variant, LP, decay)
        if ok and type(p) == "number" and p > 0 then return p end
    end
    return 0
end

local function _resolveDecay(model)
    return _walkModels(model, function(node)
        local d = node:GetAttribute("DecayAlpha")
        if d ~= nil then return d end
        return nil
    end)
end

local function _isHarvestFruitId(fid)
    fid = tostring(fid or "")
    if fid == "" or #fid < 8 then return false end
    if fid:match("^%d+_[%x%-]+") then return false end
    if fid:match("^[%x%-]+$") and #fid >= 32 then return true end
    return #fid >= 16
end

-- ESP price: lokal FruitValueCalc saja (NO NPC bid / getBackpackPrice) + cache per key.
local function _espPriceCached(fruit, key, nameHint)
    if not fruit or not fruit.Parent then return 0 end
    local fsv = _fsv()
    if not fsv or type(fsv.calculate) ~= "function" then return 0 end

    local name = tostring(nameHint or "")
    if name == "" or name == "?" then
        name = _fruitNameCheap(fruit)
    end
    if name == "" or name == "?" then
        name = _fruitName(fruit)
    end
    name = tostring(name or "")
    if name == "" or name == "?" then return 0 end

    local multi = 0
    if type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, fruit)
        if ok then multi = tonumber(m) or 0 end
    end
    if multi <= 0 then
        multi = tonumber(fruit:GetAttribute("SizeMultiplier") or fruit:GetAttribute("SizeMulti")) or 0
    end
    if multi <= 0 then
        local ok, m = pcall(_resolvePriceMulti, fruit)
        if ok then multi = tonumber(m) or 0 end
    end
    if multi <= 0 then return 0 end

    local mut = _fruitMutationCheap(fruit)
    local decay = fruit:GetAttribute("DecayAlpha")
    local sig = name .. "|" .. multi .. "|" .. tostring(mut or "") .. "|" .. tostring(decay or "")

    if key then
        local cached = espPriceCache[key]
        if cached and cached.sig == sig then
            return cached.price
        end
    end

    local price = 0
    local ok, p = pcall(fsv.calculate, name, multi, mut, nil, decay)
    if ok and type(p) == "number" and p > 0 then
        price = p
    elseif type(fsv.calculate) == "function" and mut ~= nil then
        -- 1 fallback tanpa mutation (bukan loop semua variant)
        ok, p = pcall(fsv.calculate, name, multi, nil, nil, decay)
        if ok and type(p) == "number" and p > 0 then
            price = p
        end
    end

    if key and price > 0 then
        espPriceCache[key] = { price = price, sig = sig }
    end
    return price
end

-- Harga dari GetGarden SizeMultiplier — tidak butuh mesh buah.
local function _espPriceFromMulti(name, sm, mut, key)
    name = tostring(name or "")
    sm = tonumber(sm) or 0
    if name == "" or name == "?" or sm <= 0 then return 0 end
    local fsv = _fsv()
    if not fsv or type(fsv.calculate) ~= "function" then return 0 end
    local sig = name .. "|" .. tostring(sm) .. "|" .. tostring(mut or "")
    if key then
        local cached = espPriceCache[key]
        if cached and cached.sig == sig and (tonumber(cached.price) or 0) > 0 then
            return cached.price
        end
    end
    local price = 0
    local ok, p = pcall(fsv.calculate, name, sm, mut, nil, nil)
    if ok and type(p) == "number" and p > 0 then
        price = p
    elseif mut ~= nil then
        ok, p = pcall(fsv.calculate, name, sm, nil, nil, nil)
        if ok and type(p) == "number" and p > 0 then
            price = p
        end
    end
    if key and price > 0 then
        espPriceCache[key] = { price = price, sig = sig }
    end
    return price
end

-- Legacy helper (jarang dipakai); tetap lokal, tanpa bid remote.
local function _fruitPrice(model, name, opts)
    if not model then return 0 end
    opts = type(opts) == "table" and opts or {}
    local key = nil
    local plantId, fruitId = _resolveIds(model)
    if plantId ~= "" then
        key = plantId .. "|" .. fruitId
    end
    local price = _espPriceCached(model, key, name)
    if price > 0 then return price end
    if opts.allowBillboard == true then
        local _, bbPrice = _readGameBillboard(model)
        return tonumber(bbPrice) or 0
    end
    return 0
end

local function _softRefreshFsvForEsp()
    local now = os.clock()
    if (now - lastFsvSoftAt) < ESP_FSV_SOFT_SEC then return end
    lastFsvSoftAt = now
    local fsv = _fsv()
    if fsv and type(fsv.refresh) == "function" then
        pcall(fsv.refresh, false)
    end
end

local function _adornee(model)
    if not model then return nil end
    if model.PrimaryPart and model.PrimaryPart:IsA("BasePart") then
        return model.PrimaryPart
    end
    return model:FindFirstChildWhichIsA("BasePart", true)
end

-- ESP nempel di kerangka pohon (Base), bukan buah / FruitSpawnLocations.
local function _plantAdornee(plant)
    if not plant then return nil end
    local base = plant:FindFirstChild("Base")
    if base and base:IsA("BasePart") then return base end
    if plant.PrimaryPart and plant.PrimaryPart:IsA("BasePart") then
        return plant.PrimaryPart
    end
    for _, ch in ipairs(plant:GetChildren()) do
        if ch:IsA("BasePart") and ch.Name ~= "HarvestPart" then
            return ch
        end
    end
    return nil
end

local function _plotAnchor(plot)
    if not plot then return nil end
    local sp = plot:FindFirstChild("SpawnPoint")
    if sp and sp:IsA("BasePart") then return sp end
    if sp and sp:IsA("Model") then
        if sp.PrimaryPart and sp.PrimaryPart:IsA("BasePart") then
            return sp.PrimaryPart
        end
        return sp:FindFirstChildWhichIsA("BasePart")
    end
    return nil
end

local function _plantFromInst(inst)
    local node = inst
    local depth = 0
    while node and depth < 12 do
        if node:IsA("Model")
            and node:GetAttribute("FruitId") == nil
            and (node:FindFirstChild("Base") or node:FindFirstChild("FruitSpawnLocations"))
        then
            return node
        end
        if node.Name == "Plants" or node.Name == "Gardens" then
            break
        end
        node = node.Parent
        depth += 1
    end
    return nil
end

-- Offset di sekitar pohon (8 arah + ring). Bukan di SpawnPoint plot.
local function _offsetAroundPlant(slot)
    slot = math.max(1, math.floor(tonumber(slot) or 1))
    local around = (slot - 1) % 8
    local ring = math.floor((slot - 1) / 8)
    local angle = around * (math.pi * 0.25)
    local radius = 7 + ring * 6
    local y = 4.5 + (around % 4) * 2.2 + ring * 1.8
    if around == 0 then
        y += 2.5
    elseif around == 4 then
        y -= 1.2
    end
    return Vector3.new(math.cos(angle) * radius, y, math.sin(angle) * radius)
end

local function _destroyEsp(key)
    local rec = espByKey[key]
    if rec and rec.gui then
        pcall(function() rec.gui:Destroy() end)
    end
    espByKey[key] = nil
end

local function _notifySummaryChanged()
    local cb = M.OnSummaryChanged
    if type(cb) ~= "function" then return end
    pcall(cb, summaryCache.count, summaryCache.total)
end

local function _resetSummaryCache()
    summaryCache.count = 0
    summaryCache.total = 0
    _notifySummaryChanged()
end

local function _refreshSummaryCache()
    local count = 0
    local total = 0
    for _, rec in pairs(espByKey) do
        if rec and rec.gui and rec.gui.Parent then
            count += 1
            total += tonumber(rec.price) or 0
        end
    end
    summaryCache.count = count
    summaryCache.total = total
    _notifySummaryChanged()
end

local function _isOurEspGui(inst)
    return inst
        and inst:IsA("BillboardGui")
        and (inst.Name == TAG_ROOT or inst:GetAttribute("_GAG2_ESP") == true)
end

local function _sweepOrphanEsp(root)
    if not root then return end
    for _, d in ipairs(root:GetDescendants()) do
        if _isOurEspGui(d) then
            pcall(function() d:Destroy() end)
        end
    end
end

local function _clearAllEsp()
    for key in pairs(espByKey) do
        _destroyEsp(key)
    end
    espByKey = {}
    local plot = cachedPlot
    if not (plot and plot.Parent) then
        pcall(function()
            plot = _getPlot(true)
        end)
    end
    if plot and plot.Parent then
        _sweepOrphanEsp(plot)
    end
    _resetSummaryCache()
end

local function _escRich(s)
    return tostring(s or ""):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
end

local function _rarityHex(rarity)
    local key = tostring(rarity or ""):lower():gsub("[%s_]+", "")
    return RARITY_HEX[key] or "#94A3B8"
end

local function _buildRichLine(name, kg, rarity, mutation, price)
    local dot = '<font color="#475569"> · </font>'
    local segments = {}

    if type(rarity) == "string" and rarity ~= "" then
        segments[#segments + 1] = string.format(
            '<font color="%s"><b>%s</b></font>',
            _rarityHex(rarity),
            _escRich(rarity)
        )
    end

    segments[#segments + 1] = string.format(
        '<font color="#F8FAFC"><b>%s</b></font>',
        _escRich(tostring(name))
    )

    if type(mutation) == "string" and mutation ~= "" then
        segments[#segments + 1] = string.format(
            '<font color="#FDE047">%s</font>',
            _escRich(mutation)
        )
    end

    segments[#segments + 1] = string.format(
        '<font color="#86EFAC">%.2fkg</font>',
        tonumber(kg) or 0
    )

    segments[#segments + 1] = string.format(
        '<font color="#FACC15"><b>%s</b></font>',
        _escRich(_formatPrice(price))
    )

    return dot .. table.concat(segments, dot)
end

local function _resizeEsp(rec)
    if not rec or not rec.lineLbl or not rec.gui then return end
    local lbl = rec.lineLbl
    local padX, padY = 16, 8
    local bounds = lbl.TextBounds
    local w = math.max(48, math.ceil(bounds.X) + padX)
    local h = math.max(22, math.ceil(bounds.Y) + padY)
    rec.gui.Size = UDim2.fromOffset(w, h)
end

local function _applyEspOffset(gui, offset)
    if not gui then return end
    offset = offset or Vector3.new(0, 4, 0)
    local ok = pcall(function()
        gui.ExtentsOffsetWorldSpace = offset
    end)
    if ok then
        gui.StudsOffset = Vector3.zero
    else
        gui.StudsOffset = offset
    end
end

local function _ensureEsp(key, adornee, offset)
    offset = offset or _offsetAroundPlant(1)
    local rec = espByKey[key]
    if rec and rec.gui and rec.gui.Parent and rec.adornee == adornee then
        _applyEspOffset(rec.gui, offset)
        return rec
    end
    if rec then _destroyEsp(key) end
    if not adornee then return nil end

    local bb = Instance.new("BillboardGui")
    bb.Name = TAG_ROOT
    bb:SetAttribute("_GAG2_ESP", true)
    bb.Size = UDim2.fromOffset(48, 22)
    bb.AlwaysOnTop = true
    bb.MaxDistance = 220
    bb.Enabled = true
    bb.Adornee = adornee
    bb.Parent = adornee
    _applyEspOffset(bb, offset)

    local frame = Instance.new("Frame")
    frame.Name = "Bg"
    frame.BackgroundColor3 = COL_BG
    frame.BackgroundTransparency = 0.12
    frame.BorderSizePixel = 0
    frame.Size = UDim2.fromScale(1, 1)
    frame.Parent = bb
    Instance.new("UICorner", frame).CornerRadius = UDim.new(1, 0)

    local stroke = Instance.new("UIStroke")
    stroke.Color = COL_STROKE
    stroke.Thickness = 1
    stroke.Transparency = 0.22
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = frame

    local glow = Instance.new("UIStroke")
    glow.Name = "Glow"
    glow.Color = COL_GLOW
    glow.Thickness = 2.5
    glow.Transparency = 0.78
    glow.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    glow.Parent = frame

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 8)
    pad.PaddingRight = UDim.new(0, 8)
    pad.PaddingTop = UDim.new(0, 4)
    pad.PaddingBottom = UDim.new(0, 4)
    pad.Parent = frame

    local lineLbl = Instance.new("TextLabel")
    lineLbl.Name = "Line"
    lineLbl.BackgroundTransparency = 1
    lineLbl.Size = UDim2.fromScale(1, 1)
    lineLbl.Font = Enum.Font.GothamMedium
    lineLbl.TextSize = 11
    lineLbl.TextXAlignment = Enum.TextXAlignment.Center
    lineLbl.TextYAlignment = Enum.TextYAlignment.Center
    lineLbl.TextWrapped = false
    lineLbl.TextTruncate = Enum.TextTruncate.None
    lineLbl.RichText = true
    lineLbl.TextColor3 = Color3.fromRGB(248, 250, 252)
    lineLbl.TextStrokeTransparency = 0.6
    lineLbl.TextStrokeColor3 = Color3.fromRGB(15, 23, 42)
    lineLbl.Parent = frame

    rec = {
        gui = bb,
        frame = frame,
        adornee = adornee,
        lineLbl = lineLbl,
    }
    espByKey[key] = rec
    return rec
end

local function _setEspText(rec, name, kg, rarity, mutation, price)
    if not rec then return false end
    price = tonumber(price) or 0
    kg = tonumber(kg) or 0
    local sig = tostring(name or "")
        .. "|" .. string.format("%.3f", kg)
        .. "|" .. tostring(rarity or "")
        .. "|" .. tostring(mutation or "")
        .. "|" .. tostring(math.floor(price + 0.5))
    if rec.sig == sig and rec.gui and rec.gui.Parent then
        return false
    end
    rec.sig = sig
    rec.price = price
    if rec.gui then
        rec.gui.Enabled = true
    end
    if rec.lineLbl then
        rec.lineLbl.Text = _buildRichLine(name, kg, rarity, mutation, price)
        _resizeEsp(rec)
    end
    return true
end

local function _scanGardenCandidates(plot)
    local seen = {}
    local cfg = _cfg()
    local priority = cfg.priority
    local limit = cfg.max_esp

    -- Streaming top-K by kg: akurat untuk top N, tanpa alokasi array 2–3k kandidat
    local keepN = limit
    if priority == "price" then
        keepN = math.min(
            math.max(limit * PRICE_PREFILTER_MULT, limit),
            MAX_PRICE_EVAL
        )
    end
    if keepN < 1 then keepN = 1 end

    local top = {}
    local scanned = 0

    -- GetGarden dulu: Reduce FPS menghapus mesh/prompt, data ripe+kg tetap di sync.
    local garden = type(M.GetGardenTable) == "function" and M.GetGardenTable() or nil

    if type(garden) == "table" then
        if type(gardenValueCache.bwCache) ~= "table" then
            gardenValueCache.bwCache = {}
        end
        local bwCache = gardenValueCache.bwCache
        local fruitsFolder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
        fruitsFolder = fruitsFolder and fruitsFolder:FindFirstChild("Fruits")

        local function moduleBaseWeight(name)
            name = tostring(name or "")
            if name == "" then return nil end
            local cached = bwCache[name]
            if cached ~= nil then
                return cached > 0 and cached or nil
            end
            local bw = 0
            if fruitsFolder then
                local ms = fruitsFolder:FindFirstChild(name)
                if ms and ms:IsA("ModuleScript") then
                    local ok, mod = pcall(require, ms)
                    if ok and type(mod) == "table" and type(mod.GrowData) == "table" then
                        bw = tonumber(mod.GrowData.BaseWeight) or 0
                    end
                end
            end
            bwCache[name] = bw
            return bw > 0 and bw or nil
        end

        local function mutFromData(data)
            local mut = _normalizeMutation(data.Mutation or data.mutation or data.MutationName)
            if mut then return mut end
            if type(data.Mutations) == "table" then
                mut = _normalizeMutation(data.Mutations)
                if mut then return mut end
            end
            if not gardenValueCache.mutFlags then
                gardenValueCache.mutFlags = {
                    "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
                    "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil",
                }
            end
            local flags = gardenValueCache.mutFlags
            for i = 1, #flags do
                if data[flags[i]] == true then
                    return flags[i]
                end
            end
            return nil
        end

        for plantId, plantData in pairs(garden) do
            if type(plantData) == "table" then
                local name = tostring(
                    plantData.PlantName
                        or plantData.SeedName
                        or plantData.ItemName
                        or plantData.FruitName
                        or "?"
                )
                if name == "" then name = "?" end
                local bw = moduleBaseWeight(name)
                local fruits = plantData.Fruits or plantData.fruits
                if type(fruits) == "table" then
                    for fid, data in pairs(fruits) do
                        if type(data) == "table" then
                            local age = tonumber(data.Age) or 0
                            local maxAge = tonumber(data.MaxAge) or 0
                            if maxAge > 0 and age < maxAge then continue end
                            local sm = tonumber(data.SizeMultiplier) or tonumber(data.SizeMulti) or 0
                            local og = tonumber(data.OvertimeGrowth) or 1
                            if og <= 0 then og = 1 end
                            local kg = (bw and bw > 0 and sm > 0) and (bw * sm * og) or 0
                            if kg <= 0 then continue end
                            if not _matchFruitFilter(cfg.fruits, name) then continue end
                            local key = tostring(plantId) .. "|" .. tostring(fid)
                            if seen[key] then continue end
                            seen[key] = true
                            scanned += 1
                            local mut = mutFromData(data)
                            local pos = plantData.Positions or plantData.Position
                            local posX, posY, posZ = 0, 0, 0
                            if type(pos) == "table" then
                                posX = tonumber(pos.PosX or pos.X or pos[1]) or 0
                                posY = tonumber(pos.PosY or pos.Y or pos[2]) or 0
                                posZ = tonumber(pos.PosZ or pos.Z or pos[3]) or 0
                            end
                            _pushTopByKg(top, {
                                key = key,
                                fruit = nil,
                                plantId = tostring(plantId),
                                fruitId = tostring(fid),
                                posX = posX,
                                posY = posY,
                                posZ = posZ,
                                adornee = nil,
                                name = name,
                                kg = kg,
                                mutation = mut,
                                rarity = _fruitRarity(nil, name),
                                price = 0,
                                sm = sm,
                                fromGarden = true,
                            }, keepN)
                        end
                    end
                end
            end
            if scanned > 0 and scanned % SCAN_YIELD_EVERY == 0 then
                task.wait()
            end
        end
    end

    -- Fallback: plot masih punya HarvestPrompt (RF off / GetGarden kosong)
    if scanned == 0 then
        local prompts = _ensurePromptCache(plot)
        for i = 1, #prompts do
            local prompt = prompts[i]
            if not prompt or not promptSet[prompt] then
                continue
            end
            if not _promptHarvestLive(prompt) then continue end

            local fruit = _fruitFromPrompt(prompt)
            if not fruit or not fruit.Parent then continue end
            local plantId, fruitId = _resolveIds(fruit)
            if plantId == "" then continue end
            local key = plantId .. "|" .. fruitId
            if seen[key] then continue end
            seen[key] = true

            local plant = _plantFromInst(fruit)
            local ad = _plantAdornee(plant)
            if not ad or not ad.Parent then continue end

            local name = _fruitNameCheap(fruit)
            if not _matchFruitFilter(cfg.fruits, name) then continue end

            scanned += 1
            _pushTopByKg(top, {
                key = key,
                fruit = fruit,
                adornee = ad,
                name = name,
                kg = tonumber(_displayKgCheap(fruit)) or 0,
            }, keepN)

            if scanned % SCAN_YIELD_EVERY == 0 then
                task.wait()
            end
        end
    end

    lastFruitCount = scanned
    nextPollSec = 6.0

    -- Harga selalu dihitung untuk top N (bukan hanya priority=price), supaya label tidak 0.
    if #top > 0 then
        for i = 1, #top do
            local item = top[i]
            if (tonumber(item.price) or 0) <= 0 then
                if item.fromGarden then
                    item.price = _espPriceFromMulti(item.name, item.sm, item.mutation, item.key)
                else
                    item.price = _espPriceCached(item.fruit, item.key, item.name)
                end
            end
            item.priced = true
        end
        if priority == "price" then
            table.sort(top, function(a, b)
                local pa = tonumber(a.price) or 0
                local pb = tonumber(b.price) or 0
                if pa ~= pb then return pa > pb end
                if a.kg ~= b.kg then return a.kg > b.kg end
                return a.key < b.key
            end)
        end
    end

    local outN = math.min(limit, #top)
    local out = table.create(outN)
    for i = 1, outN do
        out[i] = top[i]
    end

    -- Nempel di Base pohon (PlantId). Offset 8 arah di sekitar pohon, bukan SpawnPoint plot.
    local byId = {}
    local folder = plot and plot:FindFirstChild("Plants")
    if folder then
        for _, plant in ipairs(folder:GetChildren()) do
            if plant:IsA("Model") then
                local pid = plant:GetAttribute("PlantId")
                if pid ~= nil then
                    byId[tostring(pid)] = plant
                end
                byId[plant.Name] = plant
            end
        end
    end
    local important = plot and plot:FindFirstChild("Important")
    local extra = important and important:FindFirstChild("Plants")
    if extra then
        for _, plant in ipairs(extra:GetChildren()) do
            if plant:IsA("Model") then
                local pid = plant:GetAttribute("PlantId")
                if pid ~= nil then
                    byId[tostring(pid)] = plant
                end
                byId[plant.Name] = plant
            end
        end
    end
    local used = {}
    for i = 1, outN do
        local item = out[i]
        local pid = tostring(item.plantId or item.key)
        used[pid] = (used[pid] or 0) + 1
        local slot = used[pid]
        local plant = byId[pid]
        local ad = _plantAdornee(plant)
        if ad then
            item.adornee = ad
            item.espOffset = _offsetAroundPlant(slot)
        else
            local anchor = _plotAnchor(plot)
            local lx = tonumber(item.posX) or 0
            local ly = tonumber(item.posY) or 0
            local lz = tonumber(item.posZ) or 0
            local around = _offsetAroundPlant(slot)
            item.adornee = anchor
            item.espOffset = Vector3.new(lx, ly, lz) + around
        end
    end
    return out
end

local function _tick()
    if not running or not _cfg().enabled then return end
    if tickBusy then return end

    local now = os.clock()
    if (now - lastPoll) < nextPollSec then return end
    lastPoll = now
    tickBusy = true

    local myGen = tickGen
    task.spawn(function()
        local function stillLive()
            -- Jangan re-check _cfg().enabled di tengah scan: save/sync globals bisa
            -- flip false sebentar lalu ESP ikut di-clear padahal masih running.
            return running and myGen == tickGen
        end

        local ok, err = pcall(function()
            if not stillLive() then return end

            local plot = _getPlot()
            if not plot then
                if stillLive() then
                    _clearPromptCache()
                    _clearAllEsp()
                end
                return
            end

            -- Soft refresh (bukan force tiap poll)
            _softRefreshFsvForEsp()

            if not stillLive() then return end

            local seen = {}
            local topList = _scanGardenCandidates(plot)

            if not stillLive() then return end

            for i, item in ipairs(topList) do
                if not stillLive() then
                    _clearAllEsp()
                    return
                end
                seen[item.key] = true

                local name = item.name
                if (name == "" or name == "?") and item.fruit then
                    name = _fruitNameCheap(item.fruit)
                end
                if (name == "" or name == "?") and item.fruit then
                    name = _fruitName(item.fruit)
                end

                local kg = tonumber(item.kg) or 0
                if kg <= 0 and item.fruit then
                    kg = tonumber(_displayKgCheap(item.fruit)) or 0
                end

                local rarity = item.rarity or _fruitRarity(item.fruit, name)
                local mutation = item.mutation
                if mutation == nil and item.fruit then
                    mutation = _fruitMutationCheap(item.fruit)
                end
                local price = tonumber(item.price) or 0
                if price <= 0 then
                    if item.fromGarden then
                        price = _espPriceFromMulti(name, item.sm, mutation, item.key)
                    elseif item.fruit and item.fruit.Parent then
                        price = _espPriceCached(item.fruit, item.key, name)
                    end
                end

                -- GetGarden: nempel Base pohon. Jangan fallback SpawnPoint (itu numpuk di pintu plot).
                if item.fromGarden then
                    if not item.adornee or not item.adornee.Parent then
                        _destroyEsp(item.key)
                        espPriceCache[item.key] = nil
                        seen[item.key] = nil
                        continue
                    end
                elseif not item.fruit or not item.fruit.Parent then
                    _destroyEsp(item.key)
                    espPriceCache[item.key] = nil
                    seen[item.key] = nil
                    continue
                end

                local rec = _ensureEsp(item.key, item.adornee, item.espOffset)
                if rec then
                    rec.fruit = item.fruit
                    rec.fromGarden = item.fromGarden == true
                    _setEspText(rec, name, kg, rarity, mutation, price)
                end

                -- Yield tipis tiap 20 label supaya frame tidak spike
                if i % 20 == 0 then
                    task.wait()
                    if not stillLive() then
                        _clearAllEsp()
                        return
                    end
                end
            end

            if not stillLive() then
                _clearAllEsp()
                return
            end

            for key, rec in pairs(espByKey) do
                local dead = not seen[key]
                    or (rec and rec.adornee and not rec.adornee.Parent)
                    or (rec and rec.fromGarden ~= true and rec.fruit and not rec.fruit.Parent)
                if dead then
                    _destroyEsp(key)
                    espPriceCache[key] = nil
                end
            end

            _refreshSummaryCache()
        end)

        tickBusy = false
        if not ok then
            warn("[EspFruitGarden] tick:", err)
        end
    end)
end

function M.GetEspSummary()
    if not running then
        return { count = 0, total = 0, active = false }
    end
    return {
        count = summaryCache.count,
        total = summaryCache.total,
        active = true,
    }
end

M.getEspSummary = M.GetEspSummary

-- Total value seluruh buah di plot — independen dari ESP garden.
-- Alur ringan:
--   1) ListGardenFruitsByPlant (GetGarden ripe + harga)
--   2) cache count/total untuk badge G backpack
--   3) fallback instance hanya jika GetGarden gagal
local VALUE_LIST_SEC = 6.0
local VALUE_BATCH = 400
local VALUE_BATCH_RF = 220 -- Remove Garden: batch lebih kecil biar frame smooth
local VALUE_IDLE_POLL = 0.5
local VALUE_FSV_SOFT_SEC = 30
local valueTagFallbackGen = 0

local valueJob = {
    plot = nil,
    list = {},
    idx = 1,
    count = 0,
    total = 0,
    listAt = 0,
    ready = false,
    wanted = false,
    forceList = false,
    fsvAt = 0,
}
local valueWorker = nil
local valuePriceCache = {} -- [key] = { price, sig }

local function _fruitValueKey(fruit)
    if not fruit then return nil end
    local plantId, fruitId = _resolveIds(fruit)
    if plantId ~= "" then
        return plantId .. "|" .. fruitId
    end
    for _, key in ipairs({ "FruitId", "Id", "id", "UUID", "Uuid" }) do
        local v = fruit:GetAttribute(key)
        if v ~= nil and tostring(v) ~= "" then
            return key .. ":" .. tostring(v)
        end
    end
    return "inst:" .. tostring(fruit)
end

-- Resolve input murah (attr/multi/mut) → signature. Calculate hanya kalau cache miss.
local function _resolveGardenPriceInputs(fruit)
    if not fruit or not fruit.Parent then return nil end

    local name = _fruitNameCheap(fruit)
    if name == "" or name == "?" then
        name = _fruitName(fruit)
    end
    name = tostring(name or "")
    if name == "" or name == "?" then return nil end

    local fsv = _fsv()
    local multi = 0
    if fsv and type(fsv.resolveMulti) == "function" then
        local ok, m = pcall(fsv.resolveMulti, fruit)
        if ok then multi = tonumber(m) or 0 end
    end
    if multi <= 0 then
        -- FVC steal/price: SizeMulti (attr dari sync SizeMultiplier)
        multi = tonumber(fruit:GetAttribute("SizeMulti")) or 0
    end
    if multi <= 0 then return nil end

    local mut = fruit:GetAttribute("Mutation")
    if (mut == nil or mut == "") and fsv and type(fsv.resolveMutation) == "function" then
        local ok, m = pcall(fsv.resolveMutation, fruit)
        if ok then mut = m end
    end
    if type(mut) == "string" then
        local low = mut:lower()
        if mut == "" or low == "none" or low == "nomutation" then
            mut = nil
        end
    end

    local decay = fruit:GetAttribute("DecayAlpha")
    local sig = name .. "|" .. multi .. "|" .. tostring(mut or "") .. "|" .. tostring(decay or "")
    return name, multi, mut, decay, sig
end

local function _priceFruitCached(fruit)
    local key = _fruitValueKey(fruit)
    local name, multi, mut, decay, sig = _resolveGardenPriceInputs(fruit)
    if not sig then return 0 end

    if key then
        local cached = valuePriceCache[key]
        if cached and cached.sig == sig then
            return cached.price
        end
    end

    local fsv = _fsv()
    local price = 0
    if fsv and type(fsv.calculate) == "function" then
        local ok, p = pcall(fsv.calculate, name, multi, mut, nil, decay)
        if ok and type(p) == "number" and p > 0 then
            price = p
        end
    end
    if key then
        valuePriceCache[key] = { price = price, sig = sig }
    end
    return price
end

local function _pruneValuePriceCache(aliveKeys)
    for key in pairs(valuePriceCache) do
        if not aliveKeys[key] then
            valuePriceCache[key] = nil
        end
    end
end

local function _tryAddGardenFruit(prompt, seenInst, seenKey, list)
    if not _promptHarvestLive(prompt) then return end

    local fruit = _fruitFromPrompt(prompt)
    if not fruit or not fruit.Parent then return end
    -- RF off: soft shell sisa jangan masuk INFO (bikin total Fruits kedip / tidak akurat)
    if fruit:GetAttribute("_GAG2FruitShell") == true and not _reduceGardenActive() then
        return
    end
    if seenInst[fruit] then return end

    local key = _fruitValueKey(fruit)
    if key and seenKey[key] then return end

    seenInst[fruit] = true
    if key then seenKey[key] = true end
    list[#list + 1] = fruit
end

-- Ringan: promptCache dulu. GetTagged (seluruh game) hanya fallback berkala.
local function _collectGardenFruitList(plot)
    local list = {}
    if not plot or not plot.Parent then return list end

    local seenInst, seenKey = {}, {}
    local fromCache = 0

    if promptPlot ~= plot or #promptCache == 0 then
        _ensurePromptCache(plot)
    end

    if promptPlot == plot then
        for i = 1, #promptCache do
            local prompt = promptCache[i]
            if prompt and promptSet[prompt] then
                local before = #list
                _tryAddGardenFruit(prompt, seenInst, seenKey, list)
                if #list > before then
                    fromCache += 1
                    if fromCache % SCAN_YIELD_EVERY == 0 then
                        task.wait()
                    end
                end
            end
        end
    end

    -- Cache hangat: skip GetTagged hampir selalu (mahal di world penuh tag).
    -- Tiap 5 siklus / cache kosong → fallback tag supaya akurat.
    valueTagFallbackGen += 1
    local needTag = (fromCache == 0) or (valueTagFallbackGen % 5 == 0)
    if not needTag then
        return list
    end

    local okTag, tagged = pcall(function()
        return CollectionService:GetTagged(HARVEST_TAG)
    end)
    if okTag and type(tagged) == "table" then
        for i = 1, #tagged do
            local prompt = tagged[i]
            if prompt and prompt:IsDescendantOf(plot) then
                _tryAddGardenFruit(prompt, seenInst, seenKey, list)
            end
            if i % SCAN_YIELD_EVERY == 0 then
                task.wait()
            end
        end
    end

    return list
end

local function _valueListSecForCount(n)
    n = tonumber(n) or 0
    local rf = _reduceGardenActive()
    if rf then
        -- Remove Garden + kebun besar: jangan SumRipe tiap 5–6s (CPU spike ~1s).
        if n >= 1500 then return 25.0 end
        if n >= 800 then return 18.0 end
        if n >= 350 then return 12.0 end
        return 8.0
    end
    if n >= 1500 then return 30.0 end
    if n >= 800 then return 20.0 end
    if n >= 350 then return 12.0 end
    return 8.0
end

local function _valueBatchSize(n)
    n = tonumber(n) or 0
    if _reduceGardenActive() then
        if n >= 800 then return 160 end
        return VALUE_BATCH_RF
    end
    if n <= VALUE_BATCH then return n end
    return VALUE_BATCH
end

local function _resetValueJobEmpty()
    valueJob.plot = nil
    valueJob.list = {}
    valueJob.idx = 1
    valueJob.count = 0
    valueJob.total = 0
    valueJob.ready = true
    table.clear(valuePriceCache)
    gardenValueCache.count = 0
    gardenValueCache.total = 0
    gardenValueCache.ready = true
    gardenValueCache.at = os.clock()
end

local function _softRefreshFsv(force)
    local now = os.clock()
    if not force and (now - (valueJob.fsvAt or 0)) < VALUE_FSV_SOFT_SEC then
        return
    end
    local fsv = _fsv()
    if fsv and type(fsv.refresh) == "function" then
        -- soft refresh (hormati REFRESH_SEC di FruitSellValue)
        pcall(fsv.refresh, false)
        valueJob.fsvAt = now
    end
end

local function _valueWorkerLoop()
    while valueWorker ~= nil do
        if not valueJob.wanted then
            task.wait(0.25)
            continue
        end

        local plot = _getPlot()
        if not plot then
            _resetValueJobEmpty()
            valueJob.wanted = false
            task.wait(0.5)
            continue
        end

        local now = os.clock()
        local listSec = _valueListSecForCount(valueJob.count or lastFruitCount)
        local needList = valueJob.forceList
            or valueJob.plot ~= plot
            or (now - (valueJob.listAt or 0)) >= listSec
            or (#valueJob.list == 0 and not valueJob.ready)

        if needList then
            valueJob.forceList = false
            _softRefreshFsv(false)
            valueJob.plot = plot
            local usedSync = false
            if type(M.SumRipeGardenValue) == "function" then
                local okS, sum = pcall(M.SumRipeGardenValue, M)
                if okS and type(sum) == "table" and sum.ok == true then
                    usedSync = true
                    valueJob.list = {}
                    valueJob.count = math.max(0, math.floor(tonumber(sum.count) or 0))
                    valueJob.total = tonumber(sum.total) or 0
                    valueJob.idx = 1
                    valueJob.listAt = os.clock()
                    valueJob.ready = true
                    gardenValueCache.count = valueJob.count
                    gardenValueCache.total = valueJob.total
                    gardenValueCache.ready = true
                    gardenValueCache.at = os.clock()
                end
            end
            if usedSync then
                task.wait()
                continue
            end
            -- Jangan fallback prompt (RF = 0 buah) — biarkan cache lama.
            valueJob.list = {}
            valueJob.idx = 1
            valueJob.listAt = os.clock()
            valueJob.ready = gardenValueCache.ready == true
            task.wait()
            continue
        end

        local list = valueJob.list
        local n = #list
        if n <= 0 or valueJob.idx > n then
            valueJob.ready = true
            if n > 0 then
                gardenValueCache.count = n
                gardenValueCache.total = valueJob.total
            elseif type(valueJob.count) == "number" then
                gardenValueCache.count = valueJob.count
                gardenValueCache.total = tonumber(valueJob.total) or gardenValueCache.total
            end
            gardenValueCache.ready = true
            gardenValueCache.at = os.clock()
            -- Tidur sampai hampir waktunya rescan list (bukan spin 0.4s)
            local remain = _valueListSecForCount(n) - (os.clock() - (valueJob.listAt or 0))
            if remain < 0.05 then remain = 0.05 end
            if remain > VALUE_IDLE_POLL then remain = VALUE_IDLE_POLL end
            task.wait(remain)
            continue
        end

        local from = valueJob.idx
        local batch = _valueBatchSize(n)
        if batch < 1 then batch = 1 end
        local to = math.min(from + batch - 1, n)
        local sum = valueJob.total
        local alive = valueJob._alive
        if from == 1 or type(alive) ~= "table" then
            alive = {}
            valueJob._alive = alive
        end

        for i = from, to do
            local fruit = list[i]
            if fruit and fruit.Parent then
                local key = _fruitValueKey(fruit)
                if key then alive[key] = true end
                sum += _priceFruitCached(fruit)
            end
        end
        valueJob.total = sum
        valueJob.idx = to + 1

        gardenValueCache.count = n
        local finished = (valueJob.idx > n)
        if finished or gardenValueCache.total <= 0 or sum >= gardenValueCache.total then
            gardenValueCache.total = sum
        end
        gardenValueCache.ready = finished
        valueJob.ready = finished
        gardenValueCache.at = os.clock()

        if finished then
            _pruneValuePriceCache(alive)
            valueJob._alive = nil
        end
        task.wait()
    end
end

local function _ensureValueWorker()
    if valueWorker ~= nil then return end
    valueWorker = true
    task.spawn(function()
        local ok, err = pcall(_valueWorkerLoop)
        valueWorker = nil
        if not ok then
            warn("[EspFruitGarden] value worker:", err)
        end
    end)
end

function M.PeekGardenValue()
    return {
        count = gardenValueCache.count,
        total = gardenValueCache.total,
        ready = gardenValueCache.ready == true,
        at = gardenValueCache.at,
    }
end

M.peekGardenValue = M.PeekGardenValue

-- Non-blocking: hanya minta worker + kembalikan cache.
function M.ComputeGardenValue(a, b)
    local force = a
    if type(a) == "table" then
        force = b
    end
    force = (force == true)

    valueJob.wanted = true
    if force then
        valueJob.forceList = true
    end
    _ensureValueWorker()
    return M.PeekGardenValue()
end

M.computeGardenValue = M.ComputeGardenValue

function M.SummarizeUnharvested()
    return M.ComputeGardenValue()
end

function M.ClearGardenValueCache()
    table.clear(valuePriceCache)
    valueJob.forceList = true
    valueJob.idx = 1
    valueJob.total = 0
    valueJob.ready = false
    gardenValueCache.ready = false
end

-- Plain-text line mirip ESP garden (tanpa rich text).
function M.FormatFruitInfoLine(entry)
    entry = type(entry) == "table" and entry or {}
    local parts = {}
    local rarity = tostring(entry.rarity or "")
    if rarity ~= "" then parts[#parts + 1] = rarity end
    parts[#parts + 1] = tostring(entry.name or "?")
    local mut = tostring(entry.mutation or "")
    if mut ~= "" then parts[#parts + 1] = mut end
    parts[#parts + 1] = string.format("%.2fkg", tonumber(entry.kg) or 0)
    parts[#parts + 1] = _formatPrice(entry.price)
    return table.concat(parts, " · ")
end

M.formatFruitInfoLine = M.FormatFruitInfoLine

local function _plantTypeName(model)
    if not model then return "?" end
    local n = _pickTypeName(model)
    if n then return n end
    local fallback = tostring(model.Name or "?")
    if _looksLikeIdName(fallback) then return "?" end
    return fallback
end

-- Plant per type: GetGarden PlantName dulu, folder hanya fallback.
-- Hindari GetDescendants penuh.
local function _countPlantsByType(plot)
    local byName = {}
    local total = 0
    local source = "none"

    -- GetGarden dulu (PlantName akurat, tidak tergantung mesh).
    local ok, syncTotal, syncBy, syncSrc = pcall(function()
        local sync = gardenValueCache.syncMod
        if type(sync) ~= "table" then
            local ps = LP and LP:FindFirstChild("PlayerScripts")
            local controllers = ps and ps:FindFirstChild("Controllers")
            local mod = controllers and controllers:FindFirstChild("GardenSyncController")
            if not mod then return 0, {}, "none" end
            local okReq, got = pcall(require, mod)
            if not okReq or type(got) ~= "table" or type(got.GetGarden) ~= "function" then
                return 0, {}, "none"
            end
            gardenValueCache.syncMod = got
            sync = got
        end
        local garden
        pcall(function()
            garden = sync:GetGarden(LP.UserId)
        end)
        if type(garden) ~= "table" then return 0, {}, "none" end

        local t, map = 0, {}
        for plantId, plantData in pairs(garden) do
            if type(plantData) == "table" then
                t += 1
                local nm = tostring(
                    plantData.PlantName
                        or plantData.SeedName
                        or plantData.FruitName
                        or plantData.Name
                        or plantData.CorePartName
                        or plantId
                )
                if nm == "" then nm = "?" end
                map[nm] = (map[nm] or 0) + 1
            end
        end
        return t, map, "GetGarden"
    end)

    if ok and type(syncTotal) == "number" and syncTotal > 0 then
        return syncTotal, type(syncBy) == "table" and syncBy or {}, tostring(syncSrc or "GetGarden")
    end

    if plot and plot.Parent then
        for _, folderName in ipairs({ "Plants", "Plants_Physical", "PhysicalPlants" }) do
            local folder = plot:FindFirstChild(folderName)
            if folder then
                local n = 0
                for _, child in ipairs(folder:GetChildren()) do
                    if child:IsA("Model") then
                        n += 1
                        total += 1
                        local key = _plantTypeName(child)
                        byName[key] = (byName[key] or 0) + 1
                    end
                end
                if n > 0 then
                    source = folderName
                    break
                end
            end
        end
    end

    if total > 0 then
        return total, byName, source
    end
    return 0, {}, source
end

local function _ensureGroup(byName, name)
    local g = byName[name]
    if not g then
        g = {
            name = name,
            plants = 0,
            count = 0,
            total = 0,
            fruits = {},
        }
        byName[name] = g
    end
    return g
end

-- List buah dari GetGarden (u2) — tidak scan HarvestPrompt di plot.
-- Hanya ripe: Age >= MaxAge (MaxAge 0/kosong = ripe).
-- kg = BaseWeight(module) * SizeMultiplier * OvertimeGrowth
-- price = FruitSellValue.calculate(nama, SizeMultiplier, mutasi)
-- Return:
--   {
--     groups = { { name, plants, count, total, fruits = {...} } },
--     plants, count, total, ready, plant_source?, error?
--   }
function M.ListGardenFruitsByPlant(a, b)
    local opts = {}
    if type(a) == "table" then
        if type(b) == "table" then
            opts = b
        elseif type(a.ListGardenFruitsByPlant) ~= "function" then
            opts = a
        end
    end

    _softRefreshFsv(false)

    local summaryOnly = opts.summary == true or opts.summaryOnly == true
    local maxFruitRows = tonumber(opts.maxFruitRows)
    if maxFruitRows == nil then
        maxFruitRows = summaryOnly and 0 or -1
    end
    maxFruitRows = math.floor(maxFruitRows)
    -- < 0 = semua buah. 0 = header saja. > 0 = cap.
    local mutAgg = {}

    local function bumpMut(mut, price)
        local key = tostring(mut or "")
        if key == "" or key == "nil" then key = "None" end
        local row = mutAgg[key]
        if not row then
            row = { name = key, count = 0, total = 0 }
            mutAgg[key] = row
        end
        row.count += 1
        row.total += tonumber(price) or 0
    end

    local function pushTopFruit(list, entry, cap)
        cap = tonumber(cap) or 0
        if cap <= 0 or type(entry) ~= "table" then return end
        local n = #list
        if n < cap then
            list[n + 1] = entry
            return
        end
        local worstI, worstP, worstK = 1, tonumber(list[1].price) or 0, tonumber(list[1].kg) or 0
        for i = 2, n do
            local p = tonumber(list[i].price) or 0
            local k = tonumber(list[i].kg) or 0
            if p < worstP or (p == worstP and k < worstK) then
                worstI = i
                worstP = p
                worstK = k
            end
        end
        local ep = tonumber(entry.price) or 0
        local ek = tonumber(entry.kg) or 0
        if ep > worstP or (ep == worstP and ek > worstK) then
            list[worstI] = entry
        end
    end

    local function mutationList()
        local list = {}
        for _, row in pairs(mutAgg) do
            list[#list + 1] = row
        end
        table.sort(list, function(a, b)
            local ta, tb = tonumber(a.total) or 0, tonumber(b.total) or 0
            if ta ~= tb then return ta > tb end
            local ca, cb = tonumber(a.count) or 0, tonumber(b.count) or 0
            if ca ~= cb then return ca > cb end
            if a.name == "None" then return false end
            if b.name == "None" then return true end
            return tostring(a.name) < tostring(b.name)
        end)
        return list
    end

    local garden = type(M.GetGardenTable) == "function" and M.GetGardenTable() or nil

    if type(garden) ~= "table" then
        local plot = _getPlot(opts.force == true)
        if not plot then
            return {
                groups = {},
                plants = 0,
                count = 0,
                total = 0,
                ready = true,
                error = "GetGarden empty",
            }
        end
        local plantTotal, plantsByName, plantSource = _countPlantsByType(plot)
        local list = _collectGardenFruitList(plot)
        local byName, grandTotal, fruitN = {}, 0, 0
        for name, n in pairs(plantsByName) do
            local g = _ensureGroup(byName, tostring(name))
            g.plants = tonumber(n) or 0
        end
        for i = 1, #list do
            local fruit = list[i]
            if fruit and fruit.Parent then
                local name = _fruitNameCheap(fruit)
                if name == "" or name == "?" or _looksLikeIdName(name) then
                    name = _fruitName(fruit)
                end
                if name == "" or name == "?" or _looksLikeIdName(name) then
                    name = _plantTypeName(fruit)
                end
                name = tostring(name or "?")
                if name == "" or _looksLikeIdName(name) then name = "?" end
                local kg = tonumber(_displayKgCheap(fruit)) or 0
                if kg <= 0 then continue end
                local age = tonumber(fruit:GetAttribute("Age")) or 0
                local maxAge = tonumber(fruit:GetAttribute("MaxAge")) or 0
                if maxAge > 0 and age < maxAge then continue end
                local rarity = _fruitRarity(fruit, name)
                local mut = _fruitMutationCheap(fruit)
                local price = tonumber(_priceFruitCached(fruit)) or 0
                grandTotal += price
                fruitN += 1
                local g = _ensureGroup(byName, name)
                g.count += 1
                g.total += price
                local entry = {
                    name = name,
                    kg = kg,
                    rarity = rarity,
                    mutation = mut,
                    price = price,
                }
                entry.line = M.FormatFruitInfoLine(entry)
                g.fruits[#g.fruits + 1] = entry
            end
        end
        local groups = {}
        for _, g in pairs(byName) do
            table.sort(g.fruits, function(a, b)
                local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
                if pa ~= pb then return pa > pb end
                local ka, kb = tonumber(a.kg) or 0, tonumber(b.kg) or 0
                if ka ~= kb then return ka > kb end
                return tostring(a.mutation or "") < tostring(b.mutation or "")
            end)
            groups[#groups + 1] = g
        end
        table.sort(groups, function(a, b)
            local pa, pb = tonumber(a.plants) or 0, tonumber(b.plants) or 0
            if pa ~= pb then return pa > pb end
            local ta, tb = tonumber(a.total) or 0, tonumber(b.total) or 0
            if ta ~= tb then return ta > tb end
            local ca, cb = tonumber(a.count) or 0, tonumber(b.count) or 0
            if ca ~= cb then return ca > cb end
            return tostring(a.name) < tostring(b.name)
        end)
        return {
            groups = groups,
            plants = plantTotal,
            count = fruitN,
            total = grandTotal,
            plant_source = plantSource,
            ready = true,
        }
    end

    if type(gardenValueCache.bwCache) ~= "table" then
        gardenValueCache.bwCache = {}
    end
    local bwCache = gardenValueCache.bwCache
    local fruitsFolder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
    fruitsFolder = fruitsFolder and fruitsFolder:FindFirstChild("Fruits")

    local function moduleBaseWeight(name)
        name = tostring(name or "")
        if name == "" then return nil end
        local cached = bwCache[name]
        if cached ~= nil then
            return cached > 0 and cached or nil
        end
        local bw = 0
        if fruitsFolder then
            local ms = fruitsFolder:FindFirstChild(name)
            if ms and ms:IsA("ModuleScript") then
                local ok, mod = pcall(require, ms)
                if ok and type(mod) == "table" and type(mod.GrowData) == "table" then
                    bw = tonumber(mod.GrowData.BaseWeight) or 0
                end
            end
        end
        bwCache[name] = bw
        return bw > 0 and bw or nil
    end

    local fsv = _fsv()
    local byName = {}
    local plantTotal, fruitN, grandTotal, steps = 0, 0, 0, 0

    for plantId, plantData in pairs(garden) do
        if type(plantData) == "table" then
            plantTotal += 1
            local name = tostring(
                plantData.PlantName
                    or plantData.SeedName
                    or plantData.ItemName
                    or plantData.FruitName
                    or "?"
            )
            if name == "" then name = "?" end
            local g = _ensureGroup(byName, name)
            g.plants += 1

            local bw = moduleBaseWeight(name)
            local fruits = plantData.Fruits or plantData.fruits
            if type(fruits) == "table" then
                for fid, data in pairs(fruits) do
                    if type(data) == "table" then
                        local age = tonumber(data.Age) or 0
                        local maxAge = tonumber(data.MaxAge) or 0
                        if maxAge > 0 and age < maxAge then continue end
                        local sm = tonumber(data.SizeMultiplier) or tonumber(data.SizeMulti) or 0
                        local og = tonumber(data.OvertimeGrowth) or 1
                        if og <= 0 then og = 1 end
                        local kg = (bw and bw > 0 and sm > 0) and (bw * sm * og) or 0
                        if kg > 0 then
                            local mut = _normalizeMutation(data.Mutation or data.mutation or data.MutationName)
                            if not mut and type(data.Mutations) == "table" then
                                mut = _normalizeMutation(data.Mutations)
                            end
                            if not mut then
                                if not gardenValueCache.mutFlags then
                                    gardenValueCache.mutFlags = {
                                        "Gold", "Rainbow", "Glow", "Electric", "Frozen", "Bloodlit",
                                        "Chained", "Starstruck", "Aurora", "Ignited", "Eclipsed", "Veil",
                                    }
                                end
                                local flags = gardenValueCache.mutFlags
                                for i = 1, #flags do
                                    if data[flags[i]] == true then
                                        mut = flags[i]
                                        break
                                    end
                                end
                            end
                            local rarity = g._rarity
                            if rarity == nil then
                                rarity = _fruitRarity(nil, name)
                                g._rarity = rarity
                            end
                            local price = 0
                            local cacheKey = tostring(plantId) .. "|" .. tostring(fid)
                            local sig = name .. "|" .. tostring(sm) .. "|" .. tostring(mut or "")
                            local cached = valuePriceCache[cacheKey]
                            if cached and cached.sig == sig and (tonumber(cached.price) or 0) > 0 then
                                price = cached.price
                            elseif fsv and type(fsv.calculate) == "function" and sm > 0 then
                                local okP, p = pcall(fsv.calculate, name, sm, mut, nil, nil)
                                if okP and type(p) == "number" and p > 0 then
                                    price = p
                                end
                                if price > 0 then
                                    valuePriceCache[cacheKey] = { price = price, sig = sig }
                                end
                            end
                            grandTotal += price
                            fruitN += 1
                            g.count += 1
                            g.total += price
                            bumpMut(mut, price)
                            local fruitRow = {
                                name = name,
                                kg = kg,
                                rarity = rarity,
                                mutation = mut,
                                price = price,
                            }
                            if maxFruitRows < 0 then
                                g.fruits[#g.fruits + 1] = fruitRow
                            else
                                pushTopFruit(g.fruits, fruitRow, maxFruitRows)
                            end
                        end
                    end
                end
            end
        end
        steps += 1
        if steps % 40 == 0 then
            task.wait()
        end
    end

    local groups = {}
    for _, g in pairs(byName) do
        if maxFruitRows ~= 0 and #g.fruits > 1 then
            table.sort(g.fruits, function(a, b)
                local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
                if pa ~= pb then return pa > pb end
                local ka, kb = tonumber(a.kg) or 0, tonumber(b.kg) or 0
                if ka ~= kb then return ka > kb end
                return tostring(a.mutation or "") < tostring(b.mutation or "")
            end)
        end
        groups[#groups + 1] = g
    end
    table.sort(groups, function(a, b)
        local pa, pb = tonumber(a.plants) or 0, tonumber(b.plants) or 0
        if pa ~= pb then return pa > pb end
        local ta, tb = tonumber(a.total) or 0, tonumber(b.total) or 0
        if ta ~= tb then return ta > tb end
        local ca, cb = tonumber(a.count) or 0, tonumber(b.count) or 0
        if ca ~= cb then return ca > cb end
        return tostring(a.name) < tostring(b.name)
    end)

    gardenValueCache.count = fruitN
    gardenValueCache.total = grandTotal
    gardenValueCache.ready = true
    gardenValueCache.at = os.clock()
    return {
        groups = groups,
        plants = plantTotal,
        count = fruitN,
        total = grandTotal,
        mutations = mutationList(),
        plant_source = "GetGarden",
        ready = true,
    }
end

M.listGardenFruitsByPlant = M.ListGardenFruitsByPlant

-- Ringan: count + total ripe GetGarden saja (badge G). Tidak bangun list INFO.
function M.SumRipeGardenValue()
    local now = os.clock()
    local cached = gardenValueCache.syncSummary
    local cacheSec = 12
    if _reduceGardenActive() then
        cacheSec = 20
    end
    if type(cached) == "table" and cached.ok == true and (now - (tonumber(gardenValueCache.syncSummaryAt) or 0)) < cacheSec then
        return cached
    end
    local garden = type(M.GetGardenTable) == "function" and M.GetGardenTable() or nil
    if type(garden) ~= "table" then
        if type(cached) == "table" then
            return cached
        end
        return {
            ok = false,
            count = tonumber(gardenValueCache.count) or 0,
            total = tonumber(gardenValueCache.total) or 0,
        }
    end
    _softRefreshFsv(false)
    if type(gardenValueCache.bwCache) ~= "table" then
        gardenValueCache.bwCache = {}
    end
    local bwCache = gardenValueCache.bwCache
    local fruitsFolder = ReplicatedStorage:FindFirstChild("PlantGenerationModules")
    fruitsFolder = fruitsFolder and fruitsFolder:FindFirstChild("Fruits")
    local fruitN, grandTotal, plantTotal, steps = 0, 0, 0, 0
    local byName = {}
    for plantId, plantData in pairs(garden) do
        if type(plantData) == "table" then
            plantTotal += 1
            local name = tostring(
                plantData.PlantName
                    or plantData.SeedName
                    or plantData.ItemName
                    or plantData.FruitName
                    or "?"
            )
            if name == "" then name = "?" end
            local grp = byName[name]
            if not grp then
                grp = { name = name, plants = 0, count = 0, total = 0 }
                byName[name] = grp
            end
            grp.plants += 1
            local bw = bwCache[name]
            if bw == nil then
                bw = 0
                if fruitsFolder then
                    local ms = fruitsFolder:FindFirstChild(name)
                    if ms and ms:IsA("ModuleScript") then
                        local ok, mod = pcall(require, ms)
                        if ok and type(mod) == "table" and type(mod.GrowData) == "table" then
                            bw = tonumber(mod.GrowData.BaseWeight) or 0
                        end
                    end
                end
                bwCache[name] = bw
            end
            local fruits = plantData.Fruits or plantData.fruits
            if type(fruits) == "table" and bw > 0 then
                for fid, data in pairs(fruits) do
                    if type(data) == "table" then
                        local age = tonumber(data.Age) or 0
                        local maxAge = tonumber(data.MaxAge) or 0
                        if maxAge > 0 and age < maxAge then continue end
                        local sm = tonumber(data.SizeMultiplier) or tonumber(data.SizeMulti) or 0
                        local og = tonumber(data.OvertimeGrowth) or 1
                        if og <= 0 then og = 1 end
                        if sm <= 0 then continue end
                        local kg = bw * sm * og
                        if kg <= 0 then continue end
                        local mut = _normalizeMutation(data.Mutation or data.mutation or data.MutationName)
                        if not mut and type(data.Mutations) == "table" then
                            mut = _normalizeMutation(data.Mutations)
                        end
                        local key = tostring(plantId) .. "|" .. tostring(fid)
                        local price = _espPriceFromMulti(name, sm, mut, key)
                        fruitN += 1
                        grandTotal += tonumber(price) or 0
                        grp.count += 1
                        grp.total += tonumber(price) or 0
                    end
                end
            end
        end
        steps += 1
        -- Yield lebih sering biar spike 1 frame tidak 1000ms (kebun 2k+ buah).
        local yieldEvery = _reduceGardenActive() and 40 or 80
        if steps % yieldEvery == 0 then
            task.wait()
        end
    end
    gardenValueCache.count = fruitN
    gardenValueCache.total = grandTotal
    gardenValueCache.ready = true
    gardenValueCache.at = os.clock()
    local groups = {}
    for _, g in pairs(byName) do
        groups[#groups + 1] = {
            name = g.name,
            plants = g.plants,
            fruits = g.count,
            count = g.count,
            value = g.total,
            total = g.total,
        }
    end
    table.sort(groups, function(a, b)
        local pa, pb = tonumber(a.plants) or 0, tonumber(b.plants) or 0
        if pa ~= pb then return pa > pb end
        return tostring(a.name) < tostring(b.name)
    end)
    local summary = {
        ok = true,
        count = fruitN,
        fruits = fruitN,
        total = grandTotal,
        value = grandTotal,
        plants = plantTotal,
        types = #groups,
        groups = groups,
        ready = true,
        source = "GetGarden",
    }
    gardenValueCache.syncSummary = summary
    gardenValueCache.syncSummaryAt = os.clock()
    return summary
end

M.sumRipeGardenValue = M.SumRipeGardenValue

-- Index HarvestPrompt plot sendiri (ESP/INFO). AutoCollect tidak pakai ini.
