function M.Start()
    if running then return true end
    tickGen += 1
    running = true
    tickBusy = false
    G.FRUIT_GARDEN_ESP_ENABLED = true
    _G.FRUIT_GARDEN_ESP_ENABLED = true
    cachedPlot = nil
    cachedPlotAt = 0
    lastPoll = 0
    lastFsvSoftAt = 0
    nextPollSec = POLL_SEC_LIGHT
    lastFruitCount = 0
    table.clear(espPriceCache)
    _clearPromptCache()
