end

function M.GetGardenTable()
    local sync = gardenValueCache.syncMod
    if sync == false then
        local failAt = tonumber(gardenValueCache.syncFailAt) or 0
        if (os.clock() - failAt) < 5 then
            return nil
        end
        gardenValueCache.syncMod = nil
        sync = nil
    end
    if type(sync) ~= "table" then
        local ps = LP and LP:FindFirstChild("PlayerScripts")
        local controllers = ps and ps:FindFirstChild("Controllers")
        local mod = controllers and controllers:FindFirstChild("GardenSyncController")
        if not mod then
            gardenValueCache.syncMod = false
            gardenValueCache.syncFailAt = os.clock()
            return nil
        end
        local okReq, got = pcall(require, mod)
        if okReq and type(got) == "table" and type(got.GetGarden) == "function" then
            gardenValueCache.syncMod = got
            sync = got
        else
            gardenValueCache.syncMod = false
            gardenValueCache.syncFailAt = os.clock()
            return nil
        end
    end
    local garden
    pcall(function()
        garden = sync:GetGarden(LP.UserId)
    end)
    return type(garden) == "table" and garden or nil
end

M.getGardenTable = M.GetGardenTable

function M.ListPlantTypeItems()
    local garden = M.GetGardenTable()
    if type(garden) ~= "table" then
        return nil
    end
    local groups = {}
    local n = 0
    for plantId, plantData in pairs(garden) do
        if type(plantData) == "table" then
            n += 1
            local name = tostring(
                plantData.PlantName
                    or plantData.SeedName
                    or plantData.ItemName
                    or plantData.FruitName
                    or plantId
            )
            if name == "" then name = "?" end
            local g = groups[name]
            if not g then
                g = { key = name, name = name, count = 0 }
                groups[name] = g
            end
            g.count += 1
        end
    end
    local items = {}
    for _, g in pairs(groups) do
        items[#items + 1] = {
            key = g.key,
            name = string.format("%s x %d", g.name, g.count),
            count = g.count,
        }
    end
    table.sort(items, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)
    if #items == 0 then
        items[1] = { key = "_none", name = "(No plants in garden)" }
    end
    return items
end

M.listPlantTypeItems = M.ListPlantTypeItems

function M.CountGardenFruitSlots()
    local garden = M.GetGardenTable()
    if type(garden) ~= "table" then
        return nil
    end
    if type(gardenValueCache.slotCache) ~= "table" then
        gardenValueCache.slotCache = {}
    end
    local slotCache = gardenValueCache.slotCache
    local function seedCapacity(seedName)
        seedName = tostring(seedName or "")
        if seedName == "" then return nil end
        local cached = slotCache[seedName]
        if cached == false then return nil end
        if type(cached) == "number" then return cached end
        local n = nil
        pcall(function()
            local SeedData = require(ReplicatedStorage.SharedModules.SeedData)
            local e = type(SeedData) == "table" and SeedData[seedName]
            if type(e) ~= "table" and type(SeedData) == "table" then
                local want = string.lower(seedName)
                for k, v in pairs(SeedData) do
                    if type(v) == "table" then
                        local nm = tostring(v.SeedName or v.Name or k)
                        if string.lower(nm) == want then
                            e = v
                            break
                        end
                    end
                end
            end
            if type(e) == "table" then
                if e.IsSingleHarvest == true then n = 1 end
                n = n or tonumber(e.FruitSlots) or tonumber(e.MaxFruits) or tonumber(e.MaxFruit)
                    or tonumber(e.MaxFruitCount) or tonumber(e.FruitAmount) or tonumber(e.FruitsPerPlant)
            end
        end)
        if n and n > 0 then
            slotCache[seedName] = math.floor(n)
            return slotCache[seedName]
        end
        slotCache[seedName] = false
        return nil
    end
    local total = 0
    local plants = 0
    for _, plantData in pairs(garden) do
        if type(plantData) == "table" then
            plants += 1
            local name = tostring(
                plantData.PlantName or plantData.SeedName or plantData.ItemName or ""
            )
            local cap = seedCapacity(name)
            if not cap or cap <= 0 then
                local fruits = plantData.Fruits or plantData.fruits
                local fn = 0
                if type(fruits) == "table" then
                    for _, data in pairs(fruits) do
                        if type(data) == "table" then
                            fn += 1
                        end
                    end
                end
                cap = fn > 0 and fn or 1
            end
            total += cap
        end
    end
    if plants <= 0 then
        return 0
    end
    return total
end

M.countGardenFruitSlots = M.CountGardenFruitSlots

function M.WorldPosFromPlantData(a, b, c)
    local plantData, plot = a, b
    if type(a) == "table" and type(a.GetGardenTable) == "function" then
        plantData, plot = b, c
    end
    if type(plantData) ~= "table" then return nil end
    local p = plantData.Positions or plantData.Position
    if type(p) ~= "table" then return nil end
    local lx = tonumber(p.PosX or p.X or p[1])
    local ly = tonumber(p.PosY or p.Y or p[2])
    local lz = tonumber(p.PosZ or p.Z or p[3])
    if lx == nil or ly == nil or lz == nil then return nil end
    local localV = Vector3.new(lx, ly, lz)
    if typeof(plot) ~= "Instance" then
        plot = _getPlot()
    end
    if plot then
        local spawn = plot:FindFirstChild("SpawnPoint")
        if spawn and spawn:IsA("BasePart") then
            return spawn.CFrame:PointToWorldSpace(localV)
        end
        if spawn and spawn:IsA("Model") then
            local ok, cf = pcall(function()
                return spawn:GetPivot()
            end)
            if ok and cf then
                return cf:PointToWorldSpace(localV)
            end
        end
    end
    return localV
end

M.worldPosFromPlantData = M.WorldPosFromPlantData

G.EspFruitGarden = M
_G.EspFruitGarden = M

return M
