    { key = "PerfHud",                 name = "Perf Hud",                factory = function() -- PerfHud.lua — mini overlay top-center: FPS | CPU | Ping (style ESP garden)

local Players    = game:GetService("Players")
local RunService = game:GetService("RunService")
local Stats      = game:GetService("Stats")

local LP = Players.LocalPlayer
local G  = (getgenv and getgenv()) or _G
local M  = {}

local TAG = "GAG2_PERF_HUD"
local UPDATE_SEC = 5
local COL_BG     = Color3.fromRGB(18, 22, 16)
local COL_STROKE = Color3.fromRGB(255, 210, 60)
local COL_GLOW   = Color3.fromRGB(255, 196, 45)

local running = false
local gui = nil
local lineLbl = nil
local frame = nil
local conn = nil
local tickGen = 0

local fpsAcc = 0
local fpsFrames = 0
local fpsValue = 0
local cpuValue = 0 -- ms, sama panel Roblox CPU
local pingValue = 0 -- ms, sama NetworkPing
local lastUiAt = 0

do
    local prev = G.PerfHud or rawget(_G, "PerfHud")
    if type(prev) == "table" and prev ~= M and type(prev.Stop) == "function" then
        pcall(prev.Stop, prev)
    end
    local pg = LP and LP:FindFirstChild("PlayerGui")
    if pg then
        local old = pg:FindFirstChild(TAG)
        if old then pcall(old.Destroy, old) end
    end
end

local function _enabled()
    -- Default ON. Hanya mati jika di-set false.
    if G.PERF_HUD_ENABLED == false or rawget(_G, "PERF_HUD_ENABLED") == false then
        return false
    end
    return true
end

local function _writeEnabled(on)
    G.PERF_HUD_ENABLED = on == true
    _G.PERF_HUD_ENABLED = on == true
end

local function _destroyGui()
    if gui then
        pcall(function() gui:Destroy() end)
    end
    gui = nil
    lineLbl = nil
    frame = nil
end

local function _resize()
    if not lineLbl or not frame then return end
    local bounds = lineLbl.TextBounds
    local w = math.max(84, math.ceil(bounds.X) + 14)
    local h = math.max(15, math.ceil(bounds.Y) + 6)
    frame.Size = UDim2.fromOffset(w, h)
end

local function _createGui()
    _destroyGui()
    local pg = LP and (LP:FindFirstChild("PlayerGui") or LP:WaitForChild("PlayerGui", 5))
    if not pg then return false end

    local sg = Instance.new("ScreenGui")
    sg.Name = TAG
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 10040
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.Parent = pg
    gui = sg

    local bg = Instance.new("Frame")
    bg.Name = "Bg"
    bg.AnchorPoint = Vector2.new(0.5, 0)
    bg.Position = UDim2.new(0.5, 0, 0, 3)
    bg.Size = UDim2.fromOffset(112, 15)
    bg.BackgroundColor3 = COL_BG
    bg.BackgroundTransparency = 0
    bg.BorderSizePixel = 0
    bg.Parent = sg
    Instance.new("UICorner", bg).CornerRadius = UDim.new(1, 0)
    frame = bg

    local stroke = Instance.new("UIStroke")
    stroke.Color = COL_STROKE
    stroke.Thickness = 0.7
    stroke.Transparency = 0.22
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = bg

    local glow = Instance.new("UIStroke")
    glow.Name = "Glow"
    glow.Color = COL_GLOW
    glow.Thickness = 1.75
    glow.Transparency = 0.78
    glow.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    glow.Parent = bg

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 7)
    pad.PaddingRight = UDim.new(0, 7)
    pad.PaddingTop = UDim.new(0, 2)
    pad.PaddingBottom = UDim.new(0, 2)
    pad.Parent = bg

    local lbl = Instance.new("TextLabel")
    lbl.Name = "Line"
    lbl.BackgroundTransparency = 1
    lbl.Size = UDim2.fromScale(1, 1)
    lbl.Font = Enum.Font.GothamMedium
    lbl.TextSize = 8
    lbl.TextXAlignment = Enum.TextXAlignment.Center
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.TextWrapped = false
    lbl.RichText = true
    lbl.TextColor3 = Color3.fromRGB(248, 250, 252)
    lbl.TextStrokeTransparency = 0.6
    lbl.TextStrokeColor3 = Color3.fromRGB(15, 23, 42)
    lbl.Text = "0 FPS | 0ms CPU | 0ms"
    lbl.Parent = bg
    lineLbl = lbl

    _resize()
    return true
end

-- Sama panel Roblox "NetworkPing" (bukan Data Ping / one-way)
local function _readPing()
    local okNet, vNet = pcall(function()
        local perf = Stats:FindFirstChild("PerformanceStats")
        local item = perf and perf:FindFirstChild("NetworkPing")
        if item and type(item.GetValue) == "function" then
            return item:GetValue()
        end
        return nil
    end)
    if okNet and typeof(vNet) == "number" then
        return math.max(0, math.floor(vNet + 0.5))
    end

    local okLp, vLp = pcall(function()
        if LP and type(LP.GetNetworkPing) == "function" then
            return LP:GetNetworkPing() * 1000
        end
        return nil
    end)
    if okLp and typeof(vLp) == "number" then
        return math.max(0, math.floor(vLp + 0.5))
    end

    return pingValue
end

-- Sama panel Roblox "CPU" = ms/frame (bukan %)
local function _readCpu()
    local ok, v = pcall(function()
        local perf = Stats:FindFirstChild("PerformanceStats")
        local cpu = perf and perf:FindFirstChild("CPU")
        if cpu and type(cpu.GetValue) == "function" then
            return cpu:GetValue()
        end
        return nil
    end)
    if ok and typeof(v) == "number" then
        if v < 0 then v = 0 end
        return math.floor(v * 10 + 0.5) / 10
    end
    return cpuValue
end

local function _buildText(fps, cpu, ping)
    local sep = '<font color="#475569"> | </font>'
    return table.concat({
        string.format('<font color="#86EFAC"><b>%d FPS</b></font>', fps),
        string.format('<font color="#FDE047"><b>%.1fms CPU</b></font>', cpu),
        string.format('<font color="#7DD3FC"><b>%dms</b></font>', ping),
    }, sep)
end

local function _flushUi()
    if fpsAcc > 0 then
        fpsValue = math.floor((fpsFrames / fpsAcc) + 0.5)
    end
    fpsAcc = 0
    fpsFrames = 0

    pingValue = _readPing()
    cpuValue = _readCpu()

    if not gui or not gui.Parent or not lineLbl then
        if not _createGui() then return end
    end

    lineLbl.Text = _buildText(fpsValue, cpuValue, pingValue)
    _resize()
end

local function _tick(dt)
    if not running then return end

    fpsAcc += dt
    fpsFrames += 1

    local now = os.clock()
    if now - lastUiAt < UPDATE_SEC then return end
    lastUiAt = now
    _flushUi()
end

function M.Start()
    if running then return true end
    tickGen += 1
    running = true
    _writeEnabled(true)
    fpsAcc = 0
    fpsFrames = 0
    fpsValue = 0
    cpuValue = 0
    pingValue = 0
    lastUiAt = 0
    if not _createGui() then
        running = false
        return false
    end
    -- tampilkan segera, lalu refresh tiap 5 detik
    _flushUi()
    lastUiAt = os.clock()
    if conn then conn:Disconnect() end
    conn = RunService.Heartbeat:Connect(_tick)
    return true
end

function M.Stop()
    tickGen += 1
    running = false
    if conn then
        conn:Disconnect()
        conn = nil
    end
    _destroyGui()
end

function M.SetEnabled(a, b)
    local on = a
    if type(a) == "table" then on = b end
    on = (on == true)
    _writeEnabled(on)
    if on then return M.Start() end
    M.Stop()
    return false
end

function M.IsEnabled()
    return running == true
end

function M.IsRunning()
    return running == true
end

function M.EnsureRunning()
    if _enabled() then
        M.Start()
    else
        M.Stop()
    end
end

function M.SyncFromGlobals()
    M.EnsureRunning()
end

M.start = M.Start
M.stop = M.Stop
M.setEnabled = M.SetEnabled
M.ensureRunning = M.EnsureRunning
M.syncFromGlobals = M.SyncFromGlobals

G.PerfHud = M
_G.PerfHud = M
if G.PERF_HUD_ENABLED == nil then
    G.PERF_HUD_ENABLED = true
end
if rawget(_G, "PERF_HUD_ENABLED") == nil then
    _G.PERF_HUD_ENABLED = true
end

task.defer(function()
    if _enabled() then
        M.Start()
    else
        M.Stop()
    end
end)

return M
