            reduceLagEnabled = (on == true)
            G.REDUCE_LAG_ENABLED = reduceLagEnabled
            _G.REDUCE_LAG_ENABLED = reduceLagEnabled
            patchMisc("perf", { reduce_lag = reduceLagEnabled }, function()
                if reduceLagEnabled and removeGardenEnabled then
                    syncReduceFpsModule()
                    task.delay(0.55, syncReduceLagModule)
                else
                    syncReduceLagModule()
                end
            end)
        end)

