            local ESP = getEspFruitBackpack()
            if type(ESP) == "table" then
                if type(ESP.SyncFromGlobals) == "function" then
                    pcall(ESP.SyncFromGlobals, ESP)
                elseif type(ESP.SetEnabled) == "function" then
                    pcall(ESP.SetEnabled, ESP, G.FRUIT_BACKPACK_ESP_ENABLED == true)
                end
            elseif type(G.applyFruitBackpackEspModule) == "function" then
                pcall(G.applyFruitBackpackEspModule)
            end
        end

        local function syncEspFruitGardenModule()
            local ESP = getEspFruitGarden()
            if type(ESP) == "table" then
                if type(ESP.SyncFromGlobals) == "function" then
                    pcall(ESP.SyncFromGlobals, ESP)
                elseif type(ESP.SetEnabled) == "function" then
                    pcall(ESP.SetEnabled, ESP, G.FRUIT_GARDEN_ESP_ENABLED == true)
                end
