        }

        local function normalizeBackpackPriceMode(mode)
            return (tostring(mode or ""):lower() == "stock") and "stock" or "base"
        end

        local function syncBackpackPriceMode()
            local cfg = getMisc("fruit_backpack_esp") or {}
            local mode = normalizeBackpackPriceMode(cfg.price_mode)
            G.FRUIT_BACKPACK_ESP_PRICE_MODE = mode
            _G.FRUIT_BACKPACK_ESP_PRICE_MODE = mode
            G.FRUIT_PRICE_INCLUDE_FRIEND_BOOST = (mode == "stock")
            _G.FRUIT_PRICE_INCLUDE_FRIEND_BOOST = (mode == "stock")

            local FSV = G.FruitSellValue or _G.FruitSellValue
            if type(FSV) == "table" and type(FSV.setEspPriceMode) == "function" then
                pcall(FSV.setEspPriceMode, mode)
            end

            local BP = getEspFruitBackpack()
            if type(BP) == "table" then
                if type(BP.SetPriceMode) == "function" then
                    pcall(BP.SetPriceMode, BP, mode)
                elseif type(BP.ClearPriceCache) == "function" then
                    pcall(BP.ClearPriceCache, BP)
                end
            end
        end

        local backpackPriceMode = normalizeBackpackPriceMode(espCfg.price_mode)
            or normalizeBackpackPriceMode(G.FRUIT_BACKPACK_ESP_PRICE_MODE)

        ui:CreateRowDropdown(bodyEsp, {
