                if type(key) ~= "string" or key == "" or key == "single" or key == "multi" then
                    key = modeOrKey
                end
                backpackPriceMode = normalizeBackpackPriceMode(key)
                patchMisc("fruit_backpack_esp", { price_mode = backpackPriceMode }, function()
                    syncBackpackPriceMode()
                    syncEspFruitBackpackModule()
                end)
            end,
