        local function normalizeGardenEspPriority(v)
            return (tostring(v or ""):lower() == "price") and "price" or "kg"
        end

        local function clampGardenMaxEsp(n)
            n = math.floor(tonumber(n) or 100)
            if n < 1 then n = 1 end
            if n > 5000 then n = 5000 end
            return n
        end

        local gardenEspCfg = getMisc("fruit_garden_esp") or {}
        local gardenEspPriority = normalizeGardenEspPriority(gardenEspCfg.priority)
        local gardenMaxEsp = clampGardenMaxEsp(gardenEspCfg.max_esp)
        local gardenEspEnabled = (gardenEspCfg.enabled == true) or (G.FRUIT_GARDEN_ESP_ENABLED == true)
        local gardenEspFruitsSelected = cleanSelectedMap(
            G.FRUIT_GARDEN_ESP_FRUITS_SELECTED
                or rawget(_G, "FRUIT_GARDEN_ESP_FRUITS_SELECTED")
                or arrayToMap(gardenEspCfg.fruits)
        )

        local function syncGardenEspSettings()
            local cfg = getMisc("fruit_garden_esp") or {}
            gardenEspPriority = normalizeGardenEspPriority(cfg.priority or gardenEspPriority)
            gardenMaxEsp = clampGardenMaxEsp(cfg.max_esp or gardenMaxEsp)
            gardenEspFruitsSelected = cleanSelectedMap(
                G.FRUIT_GARDEN_ESP_FRUITS_SELECTED
                    or rawget(_G, "FRUIT_GARDEN_ESP_FRUITS_SELECTED")
