            G.FRUIT_GARDEN_ESP_PRIORITY = gardenEspPriority
            _G.FRUIT_GARDEN_ESP_PRIORITY = gardenEspPriority
            G.FRUIT_GARDEN_ESP_MAX = gardenMaxEsp
            _G.FRUIT_GARDEN_ESP_MAX = gardenMaxEsp
            G.FRUIT_GARDEN_ESP_FRUITS_SELECTED = gardenEspFruitsSelected
            _G.FRUIT_GARDEN_ESP_FRUITS_SELECTED = gardenEspFruitsSelected
        end

