        ui:CreateRowToggle(bodyEsp, "Garden Fruits", gardenEspEnabled, function(on)
            gardenEspEnabled = (on == true)
            G.FRUIT_GARDEN_ESP_ENABLED = gardenEspEnabled
            _G.FRUIT_GARDEN_ESP_ENABLED = gardenEspEnabled
            patchMisc("fruit_garden_esp", { enabled = gardenEspEnabled }, function()
                local ESP = getEspFruitGarden()
                if type(ESP) == "table" and type(ESP.SetEnabled) == "function" then
