        local bodyHidePrompt = ui:CreateSection("Hide Prompt Teleport", false)

        local function syncHideTeleportPrompt()
            local hp = getMisc("hide_prompt") or {}
            local on = (hp.enabled == true) or (G.HIDE_PROMPT_ENABLED == true)
            G.HIDE_PROMPT_ENABLED = on
            _G.HIDE_PROMPT_ENABLED = on

            local R = _G.PSReconnect or G.PSReconnect
            if type(R) == "table" and type(R.SetHideTeleportPrompt) == "function" then
                pcall(R.SetHideTeleportPrompt, on)
            elseif type(G.applyHidePromptModule) == "function" then
                pcall(G.applyHidePromptModule)
            end

            if not on then
                local R = _G.PSReconnect or G.PSReconnect
                if type(R) == "table" and type(R.RestoreTeleportPrompt) == "function" then
                    pcall(R.RestoreTeleportPrompt, R)
                end
            end
        end

