        local bodyUi = ui:CreateSection("UI Transparent", false)

        local hubCfg = getMisc("hub_ui") or {}
        local function clampPct(n, fallback)
            n = tonumber(n)
            if n == nil then return fallback end
            n = math.floor(n + 0.5)
            if n < 0 then n = 0 end
            if n > 90 then n = 90 end -- jangan sampai UI hilang total
            return n
        end
        local function toAlpha(pct)
            return math.max(0, math.min(1, (tonumber(pct) or 0) / 100))
        end
        local function toPct(alpha, fallback)
            local a = tonumber(alpha)
            if a == nil then return fallback end
            return clampPct(a * 100, fallback)
        end

        local uiPct = toPct(hubCfg.panel_transparency or hubCfg.section_transparency, 15)

        local function applyHubTransparency()
            local alpha = toAlpha(uiPct)
            if type(ui.ApplyTransparency) == "function" then
                pcall(function()
                    ui:ApplyTransparency({
                        panel = alpha,
                        section = alpha,
                        overlay = 1, -- backdrop selalu full clear
                    })
                end)
            elseif type(ui.SetTransparency) == "function" then
                pcall(function()
                    ui:SetTransparency(alpha)
                end)
            end
        end

        ui:CreateRowInput(bodyUi, "UI Transparent %", tostring(uiPct), function(text)
            text = tostring(text or ""):gsub("%s+", "")
            if text == "" then return end
            local v = tonumber(text)
            if not v then return end
            uiPct = clampPct(v, uiPct)
            local alpha = toAlpha(uiPct)
            patchMisc("hub_ui", {
                panel_transparency = alpha,
                section_transparency = alpha,
                overlay_transparency = 1,
            }, applyHubTransparency)
        end)

        -- apply saved values saat buka tab settings
        applyHubTransparency()

        local bodyCharacter = ui:CreateSection("Character", false)

        local function getMoveMod()
            return G.Move or G.MoveModule or rawget(_G, "Move") or rawget(_G, "MoveModule")
        end

        local function normalizeMoveMode(mode)
            local Move = getMoveMod()
            if type(Move) == "table" and type(Move.NormalizeMode) == "function" then
                return Move.NormalizeMode(mode)
            end
            mode = tostring(mode or "walk"):lower()
            if mode == "button" then return "walk" end
            if mode == "step" or mode == "walk" or mode == "hard" or mode == "soft" then
                return mode
            end
            return "walk"
        end

        local function syncMoveModeGlobals(mode)
            mode = normalizeMoveMode(mode)
            local Move = getMoveMod()
            if type(Move) == "table" and type(Move.SetMode) == "function" then
                pcall(Move.SetMode, mode)
            else
                G.MOVE_MODE = mode
                _G.MOVE_MODE = mode
                G.CHARACTER_MOVE_MODE = mode
                _G.CHARACTER_MOVE_MODE = mode
            end
        end

        local characterCfg = getMisc("character") or {}
        local moveMode = normalizeMoveMode(
            characterCfg.move_mode
                or G.MOVE_MODE
                or G.CHARACTER_MOVE_MODE
                or rawget(_G, "MOVE_MODE")
        )

        local softSpeed = math.floor(tonumber(characterCfg.soft_speed or G.MOVE_SOFT_SPEED) or 30)
        local stepSpeed = math.floor(tonumber(characterCfg.step_speed or G.MOVE_STEP_SPEED) or 30)
        local walkSpeed = math.floor(tonumber(characterCfg.walk_speed or G.MOVE_WALK_SPEED) or 30)

        local function applySpeeds()
            G.MOVE_SOFT_SPEED = softSpeed
            _G.MOVE_SOFT_SPEED = softSpeed
            G.MOVE_STEP_SPEED = stepSpeed
            _G.MOVE_STEP_SPEED = stepSpeed
            G.MOVE_WALK_SPEED = walkSpeed
            _G.MOVE_WALK_SPEED = walkSpeed
            local Move = getMoveMod()
            if type(Move) == "table" and type(Move.SetSpeeds) == "function" then
                pcall(Move.SetSpeeds, { soft = softSpeed, step = stepSpeed, walk = walkSpeed })
            end
        end

        syncMoveModeGlobals(moveMode)
        applySpeeds()

        ui:CreateRowDropdown(bodyCharacter, {
            label = "Move Mode",
            placeholder = "Walk",
            mode = "single",
            getItems = function()
                local Move = getMoveMod()
                if type(Move) == "table" and type(Move.MODE_ITEMS) == "table" then
                    return Move.MODE_ITEMS
                end
                return {
                    { key = "soft", name = "Soft" },
                    { key = "step", name = "Step" },
                    { key = "walk", name = "Walk" },
                    { key = "hard", name = "Hard" },
                }
            end,
            initial = moveMode,
            onChanged = function(modeOrKey, selectedKey)
                local key = selectedKey
                if type(key) ~= "string" or key == "" or key == "single" or key == "multi" then
                    key = modeOrKey
                end
                moveMode = normalizeMoveMode(key)
                patchMisc("character", { move_mode = moveMode, clip = false }, function()
                    syncMoveModeGlobals(moveMode)
                end)
            end,
        })

        -- Sama seperti input lain: ketik → klik luar/Enter → apply
        ui:CreateRowInput(bodyCharacter, "Soft Speed", tostring(softSpeed), function(text)
            text = tostring(text or ""):gsub("%s+", "")
            if text == "" then return end
            local v = tonumber(text)
            if not v then return end
            v = math.floor(v)
            if v < 1 then v = 1 end
            if v > 300 then v = 300 end
            softSpeed = v
            applySpeeds()
            patchMisc("character", { soft_speed = softSpeed })
        end)

        ui:CreateRowInput(bodyCharacter, "Step Speed", tostring(stepSpeed), function(text)
            text = tostring(text or ""):gsub("%s+", "")
            if text == "" then return end
            local v = tonumber(text)
            if not v then return end
            v = math.floor(v)
            if v < 1 then v = 1 end
            if v > 400 then v = 400 end
            stepSpeed = v
            applySpeeds()
            patchMisc("character", { step_speed = stepSpeed })
        end)

        ui:CreateRowInput(bodyCharacter, "Walk Speed", tostring(walkSpeed), function(text)
            text = tostring(text or ""):gsub("%s+", "")
            if text == "" then return end
            local v = tonumber(text)
            if not v then return end
            v = math.floor(v)
            if v < 1 then v = 1 end
            if v > 200 then v = 200 end
            walkSpeed = v
            applySpeeds()
            patchMisc("character", { walk_speed = walkSpeed })
