        local bodyConfig = ui:CreateSection("Copy / Paste Config", false)
        local pasteConfigText = ""

        local function doCopyConfig()
            local exportFn = G.__GAG2_EXPORT_CONFIG or rawget(_G, "__GAG2_EXPORT_CONFIG")
            if type(exportFn) ~= "function" then
                warn("[GAG2] Export config handler not available")
                return
            end
            local json, err = exportFn()
            if type(json) == "string" and json ~= "" then
                warn("[GAG2] Config copied to clipboard (" .. tostring(#json) .. " chars)")
            else
                warn("[GAG2] Copy config failed:", tostring(err or "unknown"))
            end
        end

        if type(ui.CreateRowButton) == "function" then
            ui:CreateRowButton(bodyConfig, "Copy Config", doCopyConfig)
        else
            ui:CreateRowToggle(
                bodyConfig,
                "Copy Config",
                false,
                function(on)
                    if on ~= true then return end
                    doCopyConfig()
                end,
                nil, nil, true
            )
        end

        -- noClearOnFocus=false supaya paste JSON besar tidak hilang saat klik box
        local _, pasteSetFn, pasteCommit = ui:CreateRowInput(
            bodyConfig,
            "Paste config",
            "",
            function(text)
                pasteConfigText = tostring(text or "")
            end,
            false
        )

        local function clearPasteBox()
            pasteConfigText = ""
            if type(pasteSetFn) == "function" then
                pcall(pasteSetFn, "")
            end
        end

        local function doPasteApply()
            if type(pasteCommit) == "function" then
                pcall(pasteCommit)
            end
            local text = tostring(pasteConfigText or "")
            if text:gsub("%s+", "") == "" and type(getclipboard) == "function" then
                local okClip, clip = pcall(getclipboard)
                if okClip and type(clip) == "string" then
                    text = clip
                end
            end
            local importFn = G.__GAG2_IMPORT_CONFIG or rawget(_G, "__GAG2_IMPORT_CONFIG")
            if type(importFn) ~= "function" then
                warn("[GAG2] Import config handler not available")
                return
            end
            local ok, err = importFn(text)
            if ok then
                clearPasteBox()
                warn("[GAG2] Config applied + saved for this account")
            else
                warn("[GAG2] Paste Apply failed:", tostring(err or "unknown"))
            end
        end

        if type(ui.CreateRowButton) == "function" then
            ui:CreateRowButton(bodyConfig, "Paste Apply", doPasteApply)
        else
            ui:CreateRowToggle(
                bodyConfig,
                "Paste Apply",
                false,
                function(on)
                    if on ~= true then return end
                    doPasteApply()
                end,
                nil, nil, true
            )
        end

        local body = ui:CreateSection("Reset Script", false)

        local function refreshUiAfterReset()
            task.defer(function()
                if type(G.__GAG2_APPLY_UI_DEFAULTS) == "function" then
                    pcall(G.__GAG2_APPLY_UI_DEFAULTS)
                end
                local mainKey = ui.activeMainKey or "misc"
                local subKey = ui.activeSubKey or "settings"
                if type(ui._setActiveSubTab) == "function" then
                    ui:_setActiveSubTab(mainKey, subKey)
                end
            end)
        end

        G.__GAG2_ON_STATE_RESET = refreshUiAfterReset
        _G.__GAG2_ON_STATE_RESET = refreshUiAfterReset

        ui:CreateRowToggle(
            body,
            "Reset Save / State",
            false,
            function(on)
                if on ~= true then return end
                local resetFn = G.__GAG2_RESET_STATE or rawget(_G, "__GAG2_RESET_STATE")
                if type(resetFn) ~= "function" then
                    warn("[GAG2] Reset handler not available")
                    return
                end
                local ok, err = pcall(resetFn)
                if ok then
                    warn("[GAG2] Save file dihapus. Semua setting dikembalikan ke default.")
                else
                    warn("[GAG2] Reset failed:", tostring(err))
                end
            end,
            nil, nil, true
        )

        -- [NODEHUBWS V48 TRACK SERVER]
        -- Defer: jangan blok render gear + jangan spam EnsureTracked/Connect
        -- saat web offline (headless boot sudah handle reconnect).
        task.defer(function()
            if type(NodeHubWS) ~= "table" or type(NodeHubWS.GAG2) ~= "function" then
                return
            end
            NodeHubWS.GAG2(ui, {
                saveFile = (type(State) == "table" and State.saveFile)
                    or G.__GAG2_SAVE_FILE
                    or rawget(_G, "__GAG2_SAVE_FILE"),
                namespace = "gag2",
                scriptName = "Grow A Garden 2",
                gameName = "Grow A Garden 2",
                --[[==========================================================
                  NodeMonitor WS MODE  >>> PRODUCTION (aktif)
                  Pindah ke LOCAL: comment baris PRODUCTION, uncomment LOCAL
                  (lakukan di 2 tempat: gear + boot) + samakan di 275_Ws_Helper
                ==========================================================]]
                -- wsBaseUrl = "ws://127.0.0.1:3881/socket/device?ws_id={id}&auth_token={token}", -- << LOCAL
                wsBaseUrl = "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}", -- << PRODUCTION (aktif)
                authPassword = "sanken2",

                -- sc_id dari DB admin / tbl_code_list.id_code_list.
                -- Dipakai web untuk deteksi module fitur per script/game.
                sc_id = 156,

                statsInterval = 15,
                assetsInterval = 30,
                useServerStatsInterval = false,

                -- V38:
                -- Default sudah menyimpan track state ringan untuk auto execute.
                -- Isi file hanya ws_id + status on/off, bukan URL/auth/config/stats.
                persistTrackState = true,

                sendDefaultConfigOnTrack = true,
                sendDefaultConfigOnChange = true,
                -- Section UI only: jangan paksa reconnect tiap buka gear.
                skipSectionAutoResume = true,
            })
        end)

        ui._skipDropdownInitialNotify = prevSkipDropdownNotify

    end, 4)

    ----------------------------------------------------------------
    -- Track Server boot — JANGAN menunggu klik MISC → gear.
    -- UI section tetap di gear; koneksi/auto-resume jalan headless di sini.
    ----------------------------------------------------------------
    do
        local localWsOpts = {
            saveFile = (type(State) == "table" and State.saveFile)
                or G.__GAG2_SAVE_FILE
                or rawget(_G, "__GAG2_SAVE_FILE")
                or nil,
            namespace = "gag2",
            scriptName = "Grow A Garden 2",
            gameName = "Grow A Garden 2",
            -- NodeMonitor WS MODE >>> PRODUCTION (aktif) -- mirror gear di atas
            -- wsBaseUrl = "ws://127.0.0.1:3881/socket/device?ws_id={id}&auth_token={token}", -- << LOCAL
            wsBaseUrl = "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}", -- << PRODUCTION (aktif)
            authPassword = "sanken2",
            sc_id = 156,
            statsInterval = 15,
            assetsInterval = 30,
            useServerStatsInterval = false,
            persistTrackState = true,
            sendDefaultConfigOnTrack = true,
            sendDefaultConfigOnChange = true,
            autoStartOnBoot = true,
            autoStartDelay = 0.8,
        }

        -- Defaults ikut wsBaseUrl aktif di atas (local / production).
        G.__NODEHUB_WS_DEFAULTS = G.__NODEHUB_WS_DEFAULTS or {}
        G.__NODEHUB_WS_DEFAULTS.wsBaseUrl = localWsOpts.wsBaseUrl
        G.__NODEHUB_WS_DEFAULTS.authPassword = localWsOpts.authPassword
        G.__NODEHUB_WS_DEFAULTS.sc_id = localWsOpts.sc_id
        G.__NODEHUB_WS_DEFAULTS.namespace = "gag2"
        _G.__NODEHUB_WS_DEFAULTS = G.__NODEHUB_WS_DEFAULTS
        G.__NODEHUB_WS_BASE_URL = localWsOpts.wsBaseUrl
        _G.__NODEHUB_WS_BASE_URL = localWsOpts.wsBaseUrl
        G.__NODEHUB_WS_AUTH_PASSWORD = localWsOpts.authPassword
        _G.__NODEHUB_WS_AUTH_PASSWORD = localWsOpts.authPassword

        -- Local resolve base only when WS juga local. Production → helper default nodemonitor.io.
        if string.find(tostring(localWsOpts.wsBaseUrl or ""), "127.0.0.1", 1, true)
            or string.find(tostring(localWsOpts.wsBaseUrl or ""), "localhost", 1, true) then
            G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE or "http://127.0.0.1:8080"
            _G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE
        end

        -- Boot: NM_MONITOR → resolve + track ON. Jangan AutoStart dulu (itu bikin Status OFF).
        task.spawn(function()
            local started = false
            for attempt = 1, 40 do
                local NH = G.NodeHubWS or rawget(_G, "NodeHubWS")
                if type(NH) == "table" then
                    local nmOn = type(NH.IsNMMonitorEnabled) == "function" and NH.IsNMMonitorEnabled() == true
                    if nmOn == true and type(NH.TryNMMonitorBind) == "function" then
                        local okCall, okBind, bindErr = pcall(function()
                            return NH.TryNMMonitorBind({
                                reason = "misc_boot_nm",
                                wsBaseUrl = localWsOpts.wsBaseUrl,
                                authPassword = localWsOpts.authPassword,
                                sc_id = localWsOpts.sc_id,
                                namespace = localWsOpts.namespace or "gag2",
                                statsInterval = localWsOpts.statsInterval,
                                assetsInterval = localWsOpts.assetsInterval,
                            })
                        end)
                        if okCall == true and okBind == true then
                            started = true
                            break
                        end
                        local why = okCall == true and tostring(bindErr or okBind or "bind_failed") or tostring(okBind)
                        if string.find(why, "username_not_allowed", 1, true)
                            or string.find(why, "username_slot_full", 1, true)
                            or string.find(why, "key_invalid", 1, true)
                            or string.find(why, "sig_invalid", 1, true) then
                            break
                        end
                    elseif nmOn ~= true then
                        if type(NH.GAG2AutoStart) == "function" then
                            local ok = pcall(NH.GAG2AutoStart, localWsOpts)
                            if ok then
                                started = true
                                break
                            end
                        elseif type(NH.GAG2) == "function" then
                            local ok = pcall(NH.GAG2, nil, localWsOpts)
                            if ok then
                                started = true
                                break
                            end
                        end
                    end
                end
                task.wait(0.25)
            end

            if started ~= true then
                return
            end

            for _, delaySec in ipairs({ 2, 6 }) do
                task.delay(delaySec, function()
                    local NH = G.NodeHubWS or rawget(_G, "NodeHubWS")
                    if type(NH) ~= "table" or type(NH.Get) ~= "function" then
                        return
                    end
                    local bridge = NH.Get("gag2")
                    if type(bridge) ~= "table" then
                        return
                    end
                    if not (bridge.trackEnabled == true or bridge.active == true) then
                        return
                    end
                    if bridge.connected == true then
                        return
                    end
                    if type(bridge.EnsureTracked) == "function" then
                        pcall(function()
                            bridge:EnsureTracked("misc_boot_" .. tostring(delaySec))
                        end)
                    elseif type(bridge.SetActive) == "function" then
                        pcall(function()
                            bridge:SetActive(true)
                        end)
                    end
                end)
            end
        end)
    end

    ----------------------------------------------------------------
    -- Boot apply ReduceFPS / ReduceLag — JANGAN tergantung klik gear settings
    ----------------------------------------------------------------
    task.defer(function()
        local MAIN = rawget(_G, "MAIN") or G.MAIN
        local perf = MAIN and MAIN.misc and MAIN.misc.perf
        if type(perf) == "table" and perf.enabled == true then
            -- migrasi / pastikan soft shell + AC filter hidup tanpa buka gear
            patchMisc("perf", { hide_own = true, hide_others = true }, nil)
        end

        local RF = G.ReduceFPS or _G.ReduceFPS or G.ReduceFPSModule or _G.ReduceFPSModule

        if type(G.applyReduceFpsModule) == "function" then
            pcall(G.applyReduceFpsModule)
        elseif type(RF) == "table" and type(RF.SyncFromGlobals) == "function" then
            pcall(RF.SyncFromGlobals, RF)
        end
        -- ReduceLag: oneshot hanya dari MainUI (__GROWAGARDEN2_MODULES_READY), jangan double-Start di sini

        -- apply UI transparent tersimpan (tanpa harus buka gear)
        local hub = MAIN and MAIN.misc and MAIN.misc.hub_ui
        if type(hub) == "table" and type(ui.ApplyTransparency) == "function" then
            local alpha = tonumber(hub.panel_transparency) or tonumber(hub.section_transparency) or 0.15
            pcall(function()
                ui:ApplyTransparency({
                    panel = alpha,
                    section = alpha,
                    overlay = 1,
                })
            end)
        elseif type(ui.ApplyTransparency) == "function" then
            pcall(function()
                ui:ApplyTransparency({ overlay = 1 })
            end)
        end
    end)
end

return M
 end,                      required = true },
    { key = "InfoTabs",                name = "Info Tabs",               factory = function() -- tabs_info.lua — Grow A Garden 2
-- Main tab: INFO (di bawah MISC) → sub tab: Garden | Steal
-- Garden: list per type plant + detail fruit (nama/kg/rarity/mutation/harga) seperti ESP garden.
-- Scan hanya saat Enabled ON + tab INFO/Garden aktif (pause otomatis saat pindah tab).
-- Steal: ringkas untuk publik (tanpa detail teknis / ID).

local M = {}

local DEFAULT_SCAN_SEC = 10
local PAUSE_POLL_SEC = 0.4
local MAX_ROWS = 40
local MAX_PROMPT_SCAN = 120
local PROMPT_TAG = "StealPrompt"

function M.Register(ui, STATE)
    STATE = rawget(_G, "STATE") or STATE or {}
    local G = (getgenv and getgenv()) or _G
    G.STATE = STATE

    local Players = game:GetService("Players")
    local CollectionService = game:GetService("CollectionService")
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local Workspace = game:GetService("Workspace")
    local LP = Players.LocalPlayer

    local State = G.__GAG2_STATE

    local function saveNow()
        if G.__GAG2_RESETTING == true then return end
        if type(State) == "table" and type(State.saveFromUi) == "function" then
            pcall(State.saveFromUi)
            return
        end
        if ui and type(ui.SaveState) == "function" then
            pcall(function() ui:SaveState() end)
        end
    end

    local function getMisc(key)
        if type(State) == "table" and type(State.getMisc) == "function" then
            local ok, result = pcall(State.getMisc, key)
            if ok and type(result) == "table" then return result end
        end
        local m = G.MAIN or rawget(_G, "MAIN")
        if type(m) == "table" and type(m.misc) == "table" then
            return m.misc[key] or {}
        end
        return {}
    end

    local function patchMisc(key, partial, syncFnOrOpts)
        local syncFn = nil
        local opts = nil
        if type(syncFnOrOpts) == "function" then
            syncFn = syncFnOrOpts
        elseif type(syncFnOrOpts) == "table" then
            opts = syncFnOrOpts
        end

        if type(State) == "table" and type(State.patchMisc) == "function" then
            pcall(State.patchMisc, key, partial, opts or {})
        else
            local m = G.MAIN or rawget(_G, "MAIN")
            if type(m) == "table" and type(partial) == "table" then
                m.misc = m.misc or {}
                local cur = type(m.misc[key]) == "table" and m.misc[key] or {}
                for k, v in pairs(partial) do
                    cur[k] = v
                end
                m.misc[key] = cur
                G.MAIN = m
                _G.MAIN = m
            end
        end
        if syncFn then pcall(syncFn) end
        local skipSave = opts and (opts.noSync == true or opts.noSave == true)
        if not skipSave then
            saveNow()
        end
    end

    local function getEspFruitGarden()
        return G.EspFruitGarden or rawget(_G, "EspFruitGarden")
    end

    local function formatPrice(n)
        n = tonumber(n) or 0
        if n <= 0 then return "0" end
        if n >= 1e9 then return string.format("%.2fB", n / 1e9) end
        if n >= 1e6 then return string.format("%.2fM", n / 1e6) end
        if n >= 1e3 then return string.format("%.1fk", n / 1e3) end
        return tostring(math.floor(n))
    end

    local function formatPlayTime(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        local h = math.floor(sec / 3600)
        local m = math.floor((sec % 3600) / 60)
        local s = sec % 60
        if h > 0 then
            return string.format("%dj %dm", h, m)
        end
        if m > 0 then
            return string.format("%dm %ds", m, s)
        end
        return string.format("%ds", s)
    end

    local function readEclStats()
        local st = G.__GAG2_ECL_STATS
        if type(st) ~= "table" then
            st = {}
        end
        local RF = G.ReduceFPS or rawget(_G, "ReduceFPS")
        if type(RF) == "table" and type(RF.GetEclStats) == "function" then
            local ok, snap = pcall(RF.GetEclStats)
            if ok and type(snap) == "table" then
                st = snap
            end
        end
        local live = G.__GAG2_ECL_WAVE
        if type(live) == "table" then
            if (tonumber(st.cycleWaves) or 0) <= 0 and (tonumber(live.n) or 0) > 0 then
                st.cycleWaves = tonumber(live.n) or 0
                st.gardenEcl = tonumber(live.prev) or st.gardenEcl
                st.cycleLive = true
            end
            if tonumber(st.sessionAt) == nil and tonumber(live.t0) then
                st.sessionAt = live.t0
            end
        end
        return st
    end

    local function formatEclSummary()
        local st = readEclStats()
        local sessionAt = tonumber(st.sessionAt) or os.clock()
        local elapsed = os.clock() - sessionAt
        if elapsed < 0 then elapsed = 0 end
        local hours = elapsed / 3600
        local cycleNew = tonumber(st.cycleNew) or 0
        local cycleWaves = tonumber(st.cycleWaves) or 0
        local sessionNew = tonumber(st.sessionNew) or 0
        local sessionWaves = tonumber(st.sessionWaves) or 0
        local sessionCycles = tonumber(st.sessionCycles) or 0
        local lastNew = tonumber(st.lastCycleNew) or 0
        local gardenEcl = tonumber(st.gardenEcl) or 0
        local live = st.cycleLive == true
            or Workspace:GetAttribute("TimeFrozen") == true
        local cycleDenom = sessionCycles
        if live then cycleDenom += 1 end
        if cycleDenom < 1 then cycleDenom = 1 end
        local avgCycle = sessionNew / cycleDenom
        local avgHour = (hours > 0.02) and (sessionNew / hours) or sessionNew
        local avgWave = (sessionWaves > 0) and (sessionNew / sessionWaves) or 0
        local phase = live and "LIVE" or "idle"
        return table.concat({
            "Eclipse:",
            string.format("· This cycle (%s): +%d  ·  %d own beams", phase, cycleNew, cycleWaves),
            string.format("· Last cycle: +%d", lastNew),
            string.format("· Session gained: +%d  ·  in garden now %d", sessionNew, gardenEcl),
            string.format("· Played: %s", formatPlayTime(elapsed)),
            string.format("· Average: %.1f / cycle  ·  %.1f / hour  ·  %.2f / wave", avgCycle, avgHour, avgWave),
        }, "\n")
    end

    local function clampScanSec(n)
        n = math.floor(tonumber(n) or DEFAULT_SCAN_SEC)
        if n < 1 then n = 1 end
        if n > 60 then n = 60 end
        return n
    end

    local function getScanSec()
        local sec = tonumber(G.__GAG2_INFO_GARDEN_SCAN_SEC)
            or tonumber(rawget(_G, "__GAG2_INFO_GARDEN_SCAN_SEC"))
        if sec == nil then
            local cfg = getMisc("info_garden") or {}
            sec = cfg.scan_sec
        end
        return clampScanSec(sec)
    end

    local function setScanSec(sec)
        sec = clampScanSec(sec)
        patchMisc("info_garden", { scan_sec = sec }, function()
            G.__GAG2_INFO_GARDEN_SCAN_SEC = sec
            _G.__GAG2_INFO_GARDEN_SCAN_SEC = sec
        end)
        return sec
    end

    local function isInfoGardenTab()
        return ui.activeMainKey == "info" and ui.activeSubKey == "garden"
    end

    local function isScanEnabled()
        return G.__GAG2_INFO_GARDEN_ENABLED == true
    end

    local function setScanEnabled(on)
        on = (on == true)
        patchMisc("info_garden", { enabled = on }, function()
            G.__GAG2_INFO_GARDEN_ENABLED = on
            _G.__GAG2_INFO_GARDEN_ENABLED = on
        end)
    end

    -- Pool UI plant/fruit: update Text saja, jangan destroy/create tiap scan
    local plantUiPool = {} -- [plantName] = { section, body, titleLbl, infoLbl, fruitLbls = {TextLabel...}, emptyLbl }
    local lastGroupsByName = {}
    local emptyPlantsUi = nil -- { section, body, infoLbl }

    local function scanGarden()
        local ESP = getEspFruitGarden()
        if type(ESP) ~= "table" or type(ESP.ListGardenFruitsByPlant) ~= "function" then
            return {
                groups = {},
                count = 0,
                total = 0,
                ready = true,
                error = "EspFruitGarden tidak tersedia",
            }
        end
        -- GetGarden (u2): ripe saja. Semua buah per jenis (bukan top 40).
        local ok, result = pcall(ESP.ListGardenFruitsByPlant, ESP, {
            force = false,
            summary = true,
            maxFruitRows = -1,
        })
        if not ok or type(result) ~= "table" then
            return {
                groups = {},
                count = 0,
                total = 0,
                ready = true,
                error = tostring(result or "scan gagal"),
            }
        end
        return result
    end

    local function fruitLine(f)
        f = type(f) == "table" and f or {}
        local line = tostring(f.line or "")
        if line ~= "" then return line end
        local mut = tostring(f.mutation or "")
        local low = mut:lower()
        if mut == "" or low == "none" or low == "nomutation" or low == "nil" then
            mut = ""
        end
        local parts = {}
        if f.rarity and tostring(f.rarity) ~= "" then
            parts[#parts + 1] = tostring(f.rarity)
        end
        parts[#parts + 1] = tostring(f.name or "?")
        if mut ~= "" then
            parts[#parts + 1] = mut
        end
        parts[#parts + 1] = string.format("%.2fkg", tonumber(f.kg) or 0)
        parts[#parts + 1] = formatPrice(f.price)
        return table.concat(parts, " · ")
    end

    local function mutationKey(raw)
        local s = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return "None" end
        local low = s:lower()
        if low == "none" or low == "nomutation" or low == "nil" then
            return "None"
        end
        return s
    end

    -- Aggregate count + value per mutation dari semua fruit di groups
    local function buildMutationTotals(groups)
        local byMut = {}
        groups = type(groups) == "table" and groups or {}
        for _, g in ipairs(groups) do
            local fruits = type(g.fruits) == "table" and g.fruits or {}
            for _, f in ipairs(fruits) do
                local key = mutationKey(f and f.mutation)
                local row = byMut[key]
                if not row then
                    row = { name = key, count = 0, total = 0 }
                    byMut[key] = row
                end
                row.count += 1
                row.total += tonumber(f and f.price) or 0
            end
        end
        local list = {}
        for _, row in pairs(byMut) do
            list[#list + 1] = row
        end
        table.sort(list, function(a, b)
            local ta, tb = tonumber(a.total) or 0, tonumber(b.total) or 0
            if ta ~= tb then return ta > tb end
            local ca, cb = tonumber(a.count) or 0, tonumber(b.count) or 0
            if ca ~= cb then return ca > cb end
            if a.name == "None" then return false end
            if b.name == "None" then return true end
            return tostring(a.name) < tostring(b.name)
        end)
        return list
    end

    local function formatMutationSummary(mutList)
        mutList = type(mutList) == "table" and mutList or {}
        if #mutList == 0 then
            return "Mutations: —"
        end
        local lines = { "Total by mutation:" }
        for i = 1, #mutList do
            local m = mutList[i]
            lines[#lines + 1] = string.format(
                "· %s  ·  x%d  ·  %s",
                tostring(m.name or "?"),
                tonumber(m.count) or 0,
                formatPrice(m.total)
            )
        end
        return table.concat(lines, "\n")
    end

    local function paintEclLbl(eclLbl)
        if not (eclLbl and eclLbl.Parent) then return end
        eclLbl.TextWrapped = true
        eclLbl.TextTruncate = Enum.TextTruncate.None
        eclLbl.TextYAlignment = Enum.TextYAlignment.Top
        eclLbl.AutomaticSize = Enum.AutomaticSize.Y
        eclLbl.Size = UDim2.new(1, 0, 0, 0)
        eclLbl.Text = formatEclSummary()
        local erow = eclLbl.Parent
        if erow and erow:IsA("GuiObject") then
            erow.AutomaticSize = Enum.AutomaticSize.Y
            erow.Size = UDim2.new(1, 0, 0, 0)
        end
    end

    local function markDynamic(body)
        if body and body.Parent then
            body.Parent:SetAttribute("_GAG2InfoDynamic", true)
        end
    end

    local function destroyPlantPool()
        for key, entry in pairs(plantUiPool) do
            if entry and entry.section and entry.section.Parent then
                pcall(function() entry.section:Destroy() end)
            end
            plantUiPool[key] = nil
        end
        table.clear(lastGroupsByName)
        if emptyPlantsUi and emptyPlantsUi.section and emptyPlantsUi.section.Parent then
            pcall(function() emptyPlantsUi.section:Destroy() end)
        end
        emptyPlantsUi = nil
    end

    local function ensureEmptyPlantsUi()
        if emptyPlantsUi and emptyPlantsUi.section and emptyPlantsUi.section.Parent then
            return emptyPlantsUi
        end
        local body = ui:CreateSection("Plants", true)
        markDynamic(body)
        local row, lbl = ui:CreateRowLabel(body, "Tidak ada plant / fruit di plot.", nil, nil, "info")
        emptyPlantsUi = {
            section = body and body.Parent,
            body = body,
            infoLbl = lbl,
            infoRow = row,
        }
        return emptyPlantsUi
    end

    local function ensurePlantUi(plantName)
        plantName = tostring(plantName or "?")
        local entry = plantUiPool[plantName]
        if entry and entry.section and entry.section.Parent and entry.body and entry.body.Parent then
            return entry
        end
        local body = ui:CreateSection(plantName, false)
        markDynamic(body)
        local section = body and body.Parent
        local titleLbl = section and section:FindFirstChild("Header")
        titleLbl = titleLbl and titleLbl:FindFirstChild("Title")
        local infoRow, infoLbl = ui:CreateRowLabel(body, "", nil, nil, "info")
        local emptyRow, emptyLbl = ui:CreateRowLabel(body, "Belum ada fruit harvestable.", nil, nil, "info")
        if emptyRow then emptyRow.Visible = false end
        entry = {
            section = section,
            body = body,
            titleLbl = titleLbl,
            infoLbl = infoLbl,
            infoRow = infoRow,
            emptyLbl = emptyLbl,
            emptyRow = emptyRow,
            fruitLbls = {},
            fruitRows = {},
        }
        plantUiPool[plantName] = entry
        local header = section and section:FindFirstChild("Header")
        if header and header:IsA("GuiButton") then
            header.MouseButton1Click:Connect(function()
                paintPlantFruits(entry, lastGroupsByName[plantName])
            end)
        end
        return entry
    end

    local function ensureFruitLabel(entry, index)
        local lbl = entry.fruitLbls[index]
        local row = entry.fruitRows[index]
        if lbl and lbl.Parent and row and row.Parent then
            row.Visible = true
            return lbl
        end
        row, lbl = ui:CreateRowLabel(entry.body, "", nil, nil, "list")
        entry.fruitRows[index] = row
        entry.fruitLbls[index] = lbl
        return lbl
    end

    local function paintPlantFruits(entry, group)
        if not entry then return end
        local fruits = type(group) == "table" and type(group.fruits) == "table" and group.fruits or {}
        local showN = #fruits
        if showN == 0 then
            if entry.emptyRow then entry.emptyRow.Visible = true end
            if entry.emptyLbl then entry.emptyLbl.Text = "No harvestable fruit." end
            for i = 1, #entry.fruitRows do
                if entry.fruitRows[i] then entry.fruitRows[i].Visible = false end
            end
            return
        end
        if entry.emptyRow then entry.emptyRow.Visible = false end
        for fi = 1, showN do
            local lbl = ensureFruitLabel(entry, fi)
            if lbl then
                lbl.Text = fruitLine(fruits[fi])
            end
        end
        for i = showN + 1, #entry.fruitRows do
            if entry.fruitRows[i] then entry.fruitRows[i].Visible = false end
        end
    end

    local function stillLive(gen, summaryLbl)
        if G.__GAG2_INFO_GARDEN_GEN ~= gen then return false end
        if not (summaryLbl and summaryLbl.Parent) then return false end
        return true
    end

    local function renderResults(gen, summaryLbl, mutLbl, eclLbl, data)
        if not stillLive(gen, summaryLbl) then return end
        if not isInfoGardenTab() then return end

        local plants = tonumber(data.plants) or 0
        local count = tonumber(data.count) or 0
        local total = tonumber(data.total) or 0
        local groups = type(data.groups) == "table" and data.groups or {}
        local err = data.error
        local mutList = type(data.mutations) == "table" and #data.mutations > 0
            and data.mutations
            or buildMutationTotals(groups)

        -- Summary + mutasi: update Text saja
        if err and tostring(err) ~= "" and count <= 0 and #groups == 0 then
            summaryLbl.Text = "Error: " .. tostring(err)
            if mutLbl and mutLbl.Parent then
                mutLbl.Text = "Mutations: —"
            end
            paintEclLbl(eclLbl)
        else
            summaryLbl.Text = string.format(
                "Plants: %d  ·  Fruits: %d  ·  Types: %d  ·  Value: %s",
                plants,
                count,
                #groups,
                formatPrice(total)
            )
            if mutLbl and mutLbl.Parent then
                mutLbl.TextWrapped = true
                mutLbl.TextTruncate = Enum.TextTruncate.None
                mutLbl.TextYAlignment = Enum.TextYAlignment.Top
                mutLbl.AutomaticSize = Enum.AutomaticSize.Y
                mutLbl.Size = UDim2.new(1, 0, 0, 0)
                mutLbl.Text = formatMutationSummary(mutList)
                local row = mutLbl.Parent
                if row and row:IsA("GuiObject") then
                    row.AutomaticSize = Enum.AutomaticSize.Y
                    row.Size = UDim2.new(1, 0, 0, 0)
                end
            end
            paintEclLbl(eclLbl)
        end

        if not stillLive(gen, summaryLbl) or not isInfoGardenTab() then return end

        -- Empty garden
        if #groups == 0 then
            for _, entry in pairs(plantUiPool) do
                if entry.section then entry.section.Visible = false end
            end
            local empty = ensureEmptyPlantsUi()
            if empty.section then empty.section.Visible = true end
            if empty.infoLbl then
                empty.infoLbl.Text = "Tidak ada plant / fruit di plot."
            end
            return
        end

        if emptyPlantsUi and emptyPlantsUi.section then
            emptyPlantsUi.section.Visible = false
        end

        local seen = {}
        for gi = 1, #groups do
            if not stillLive(gen, summaryLbl) or not isInfoGardenTab() then return end
            local g = groups[gi]
            local name = tostring(g.name or "?")
            seen[name] = true
            local plantN = tonumber(g.plants) or 0
            local fruitN = tonumber(g.count) or 0
            local title = string.format(
                "%s  ·  plants x%d  ·  fruits x%d  ·  %s",
                name,
                plantN,
                fruitN,
                formatPrice(g.total)
            )
            local info = string.format(
                "Plants: %d  ·  Fruits: %d  ·  Value: %s",
                plantN,
                fruitN,
                formatPrice(g.total)
            )

            local entry = ensurePlantUi(name)
            if entry.section then
                entry.section.Visible = true
                entry.section.LayoutOrder = 100 + gi
            end
            if entry.titleLbl then
                entry.titleLbl.Text = title
            end
            if entry.infoLbl then
                entry.infoLbl.Text = info
            end

            lastGroupsByName[name] = g
            paintPlantFruits(entry, g)
        end

        -- Hide plant types yang sudah tidak ada
        for key, entry in pairs(plantUiPool) do
            if not seen[key] and entry.section then
                entry.section.Visible = false
            end
        end
    end

    local function waitScanGap(gen, summaryLbl, fruitN)
        local gap = getScanSec()
        fruitN = tonumber(fruitN) or 0
        if fruitN >= 800 then
            gap = math.max(gap, 10)
        elseif fruitN >= 350 then
            gap = math.max(gap, 8)
        end
        local untilAt = os.clock() + gap
        while os.clock() < untilAt do
            if not stillLive(gen, summaryLbl) then return false end
            -- Pindah tab / disable → keluar menunggu (pause), jangan paksa delay penuh
            if not isInfoGardenTab() or not isScanEnabled() then
                return true
            end
            task.wait(PAUSE_POLL_SEC)
        end
        return true
    end

    ----------------------------------------------------------------
    -- Steal (publik, ringkas) — helper + scan ringan
    ----------------------------------------------------------------
    local function isNight()
        local n = ReplicatedStorage:FindFirstChild("Night")
        if not n then return false end
        local v = n.Value
        return v == true or v == 1
    end

    local function getCarryCount()
        local char = LP and LP.Character
        if not char then return 0 end
        local n = 0
        for _, ch in ipairs(char:GetChildren()) do
            if ch:IsA("Model") and ch:GetAttribute("FruitId") ~= nil then
                n += 1
            end
        end
        return n
    end

    local function getCarryValue()
        return tonumber(LP and LP:GetAttribute("StolenCarryValue")) or 0
    end

    local function flatDist(a, b)
        if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then
            return math.huge
        end
        return Vector3.new(a.X - b.X, 0, a.Z - b.Z).Magnitude
    end

    local function getFSV()
        return G.FruitSellValue or rawget(_G, "FruitSellValue")
    end

    local function looksLikeIdName(s)
        s = tostring(s or "")
        if s == "" or s == "?" then return true end
        if s:find("_", 1, true) and s:find("-", 1, true) then return true end
        return false
    end

    local function isStealPrompt(p)
        if not p or not p:IsA("ProximityPrompt") then return false end
        if CollectionService:HasTag(p, PROMPT_TAG) then return true end
        local at = string.lower(tostring(p.ActionText or ""))
        local ot = string.lower(tostring(p.ObjectText or ""))
        if at == "steal" or ot == "steal" then return true end
        if string.find(at, "steal", 1, true) or string.find(ot, "steal", 1, true) then return true end
        return false
    end

    local function fruitModelFromPrompt(prompt)
        if not prompt or not prompt.Parent then return nil end
        local best = nil
        local cur = prompt.Parent
        for _ = 1, 12 do
            if not cur or cur == workspace or cur == game then break end
            if cur:IsA("Model") then
                if cur:GetAttribute("FruitId") ~= nil then
                    return cur
                end
                if not best then best = cur end
            end
            cur = cur.Parent
        end
        return best
    end

    local ownerCache = {}
    local ownerPending = {}

    local function ownerNameOf(uid)
        uid = tonumber(uid)
        if not uid then return "?" end
        if ownerCache[uid] then return ownerCache[uid] end
        local plr = Players:GetPlayerByUserId(uid)
        if plr then
            ownerCache[uid] = plr.Name
            return plr.Name
        end
        ownerCache[uid] = tostring(uid)
        if not ownerPending[uid] then
            ownerPending[uid] = true
            task.spawn(function()
                local ok, name = pcall(Players.GetNameFromUserIdAsync, Players, uid)
                if ok and type(name) == "string" and name ~= "" then
                    ownerCache[uid] = name
                end
                ownerPending[uid] = nil
            end)
        end
        return ownerCache[uid]
    end

    local function attrOnModelOrPlant(model, keys)
        if not model then return nil end
        local nodes = { model }
        if model.Parent and model.Parent:IsA("Model") then
            nodes[#nodes + 1] = model.Parent
            if model.Parent.Parent and model.Parent.Parent:IsA("Model") then
                nodes[#nodes + 1] = model.Parent.Parent
            end
        end
        for _, node in ipairs(nodes) do
            for _, k in ipairs(keys) do
                local v = node:GetAttribute(k)
                if v ~= nil and tostring(v) ~= "" then
                    return v
                end
            end
        end
        return nil
    end

    local function resolveSeed(model)
        local v = attrOnModelOrPlant(model, { "SeedName", "CorePartName", "Name", "FruitName", "PlantName" })
        local s = tostring(v or model and model.Name or "?")
        if looksLikeIdName(s) then
            local alt = attrOnModelOrPlant(model, { "DisplayName", "FruitDisplayName" })
            if alt and not looksLikeIdName(alt) then s = tostring(alt) end
        end
        return s
    end

    local function resolveMut(model)
        local v = attrOnModelOrPlant(model, { "Mutation", "MutationName", "Mutations" })
        if v == nil then return "" end
        if type(v) == "table" then
            local parts = {}
            for _, x in ipairs(v) do
                if tostring(x) ~= "" then parts[#parts + 1] = tostring(x) end
            end
            return table.concat(parts, ",")
        end
        local s = tostring(v)
        if s == "" or s:lower() == "none" then return "" end
        return s
    end

    local function resolveKg(model)
        local v = attrOnModelOrPlant(model, { "Weight", "Kg", "Mass", "FruitWeight" })
        v = tonumber(v)
        if v and v > 0 then return v end
        local fsv = getFSV()
        if fsv and type(fsv.fromFruit) == "function" then
            local ok, info = pcall(fsv.fromFruit, model)
            if not ok then ok, info = pcall(fsv.fromFruit, fsv, model) end
            if ok and type(info) == "table" then
                return tonumber(info.kg or info.weight) or 0
            end
        end
        return 0
    end

    local function resolvePrice(model, seed, mut)
        local tagged = tonumber(attrOnModelOrPlant(model, { "SellValue", "Value", "Price" }))
        if tagged and tagged > 0 then return tagged end
        local fsv = getFSV()
        if not fsv then return 0 end
        if type(fsv.fromFruit) == "function" then
            local ok, v = pcall(fsv.fromFruit, model)
            if not ok then ok, v = pcall(fsv.fromFruit, fsv, model) end
            if ok and type(v) == "number" and v > 0 then return v end
            if ok and type(v) == "table" then
                local p = tonumber(v.price or v.value or v.sell)
                if p and p > 0 then return p end
            end
        end
        if type(fsv.calculate) == "function" then
            local name = tostring(seed or "")
            if name == "" or name == "?" then name = resolveSeed(model) end
            local multi = 0
            if type(fsv.resolveMulti) == "function" then
                local ok, m = pcall(fsv.resolveMulti, model)
                if ok then multi = tonumber(m) or 0 end
            end
            if multi <= 0 then
                multi = tonumber(model:GetAttribute("SizeMulti") or model:GetAttribute("SizeMultiplier")) or 1
            end
            local ok, v = pcall(fsv.calculate, name, multi, mut or "")
            if not ok then ok, v = pcall(fsv.calculate, fsv, name, multi, mut or "") end
            if ok and type(v) == "number" and v > 0 then return v end
        end
        return 0
    end

    local function isInfoStealTab()
        return ui.activeMainKey == "info" and ui.activeSubKey == "steal"
    end

    local function isStealScanEnabled()
        return G.__GAG2_INFO_STEAL_ENABLED == true
    end

    local function getStealScanSec()
        local sec = tonumber(G.__GAG2_INFO_STEAL_SCAN_SEC)
            or tonumber(rawget(_G, "__GAG2_INFO_STEAL_SCAN_SEC"))
        if sec == nil then
            local cfg = getMisc("info_steal") or {}
            sec = cfg.scan_sec
        end
        return clampScanSec(sec)
    end

    local function setStealScanSec(sec)
        sec = clampScanSec(sec)
        patchMisc("info_steal", { scan_sec = sec }, function()
            G.__GAG2_INFO_STEAL_SCAN_SEC = sec
            _G.__GAG2_INFO_STEAL_SCAN_SEC = sec
        end)
        return sec
    end

    local function setStealScanEnabled(on)
        on = (on == true)
        patchMisc("info_steal", { enabled = on }, function()
            G.__GAG2_INFO_STEAL_ENABLED = on
            _G.__GAG2_INFO_STEAL_ENABLED = on
        end)
    end

    local function getStealSortMode()
        local m = tostring(G.__GAG2_INFO_STEAL_SORT or "")
        if m == "" then
            local cfg = getMisc("info_steal") or {}
            m = tostring(cfg.sort_mode or "price")
        end
        m = string.lower(m)
        if m == "near" then m = "dist" end
        if m ~= "kg" and m ~= "dist" and m ~= "seed" and m ~= "owner" then
            m = "price"
        end
        return m
    end

    local function setStealSortMode(mode)
        mode = string.lower(tostring(mode or "price"))
        if mode == "near" then mode = "dist" end
        if mode ~= "kg" and mode ~= "dist" and mode ~= "seed" and mode ~= "owner" then
            mode = "price"
        end
        patchMisc("info_steal", { sort_mode = mode }, function()
            G.__GAG2_INFO_STEAL_SORT = mode
            _G.__GAG2_INFO_STEAL_SORT = mode
        end)
        return mode
    end

    local function getAutoSteal()
        return G.AutoSteal or G.AutoStealModule
            or rawget(_G, "AutoSteal") or rawget(_G, "AutoStealModule")
    end

    local function sortStealRows(rows, sortMode)
        sortMode = tostring(sortMode or "price")
        if sortMode == "kg" then
            table.sort(rows, function(a, b)
                local ka, kb = tonumber(a.kg) or 0, tonumber(b.kg) or 0
                if ka ~= kb then return ka > kb end
                return (a.dist or math.huge) < (b.dist or math.huge)
            end)
        elseif sortMode == "dist" then
            table.sort(rows, function(a, b)
                return (a.dist or math.huge) < (b.dist or math.huge)
            end)
        elseif sortMode == "seed" then
            table.sort(rows, function(a, b)
                local sa, sb = tostring(a.seed or ""), tostring(b.seed or "")
                if sa ~= sb then return sa < sb end
                return (tonumber(a.price) or 0) > (tonumber(b.price) or 0)
            end)
        elseif sortMode == "owner" then
            table.sort(rows, function(a, b)
                local oa = tostring(a.ownerName or a.ownerUserId or "")
                local ob = tostring(b.ownerName or b.ownerUserId or "")
                if oa ~= ob then return oa < ob end
                return (tonumber(a.price) or 0) > (tonumber(b.price) or 0)
            end)
        else
            table.sort(rows, function(a, b)
                local pa, pb = tonumber(a.price) or 0, tonumber(b.price) or 0
                if pa ~= pb then return pa > pb end
                return (a.dist or math.huge) < (b.dist or math.huge)
            end)
        end
    end

    local function isLiveStealRow(r)
        if type(r) ~= "table" then return false end
        local model = r.model
        if model and model.Parent then
            local prompt = r.prompt
            if prompt and prompt.Parent then return true end
            -- prompt hilang = sudah tidak stealable
            local found = false
            pcall(function()
                for _, d in ipairs(model:GetDescendants()) do
                    if isStealPrompt(d) then
                        found = true
                        break
                    end
                end
            end)
            return found
        end
        -- row tanpa model ref (normalize stripped) — anggap hidup hanya jika hasPrompt
        -- untuk AS cache kita butuh model; tanpa model drop
        return false
    end

    local function normalizeStealRow(r)
        r = type(r) == "table" and r or {}
        local ownerId = r.ownerUserId
        return {
            seed = tostring(r.seed or "?"),
            mut = tostring(r.mut or r.mutation or ""),
            kg = tonumber(r.kg) or 0,
            price = tonumber(r.price) or 0,
            multi = tonumber(r.multi) or 0,
            dist = tonumber(r.dist) or math.huge,
            ownerUserId = ownerId,
            ownerName = tostring(r.ownerName or ownerNameOf(ownerId) or "?"),
            plantId = r.plantId,
            fruitId = r.fruitId,
            hold = tonumber(r.hold) or 0,
            maxDist = tonumber(r.maxDist) or 0,
            hasPrompt = r.hasPrompt ~= false,
            stealable = r.stealable ~= false,
            model = r.model,
            prompt = r.prompt,
        }
    end

    local function packStealResult(rows, meta)
        meta = type(meta) == "table" and meta or {}
        local live = {}
        for i = 1, #(rows or {}) do
            local r = rows[i]
            if isLiveStealRow(r) then
                live[#live + 1] = r
            elseif type(r) == "table" and r.model == nil and r.hasPrompt ~= false and r.ownerUserId then
                -- fallback scan rows tanpa model ref tetap boleh
                live[#live + 1] = r
            end
        end
        local sortMode = getStealSortMode()
        sortStealRows(live, sortMode)
        local shown = {}
        for i = 1, math.min(#live, MAX_ROWS) do
            shown[i] = live[i]
            -- jangan bawa Instance ke UI text path lebih dari perlu
            shown[i].model = nil
            shown[i].prompt = nil
        end
        local owners = {}
        for i = 1, #live do
            local uid = live[i].ownerUserId
            if uid then owners[uid] = true end
        end
        local ownerN = 0
        for _ in pairs(owners) do ownerN += 1 end
        return {
            rows = shown,
            scanned = #live,
            promptTotal = tonumber(meta.promptTotal) or #live,
            owners = ownerN,
            capped = meta.capped == true,
            sortMode = sortMode,
            source = tostring(meta.source or "scan"),
        }
    end

    -- Prefer list Auto Steal (target farm yang sama). Fallback scan sendiri + readFruit AS.
    local function scanStealLight()
        local AS = getAutoSteal()

        if type(AS) == "table" then
            local raw = nil
            -- force refresh supaya buah stolen (model/prompt hilang) langsung ke-drop
            if type(AS._scan) == "table" and type(AS._scan.ensure) == "function" then
                local ok, r = pcall(AS._scan.ensure, true)
                if ok and type(r) == "table" then
                    raw = r
                end
            end
            if (not raw) and type(AS.GetScanRows) == "function" then
                local r = AS.GetScanRows()
                if type(r) == "table" then
                    raw = r
                end
            end
            if type(raw) == "table" then
                local out = {}
                for i = 1, #raw do
                    if isLiveStealRow(raw[i]) then
                        out[#out + 1] = normalizeStealRow(raw[i])
                    end
                end
                return packStealResult(out, {
                    source = "autosteal",
                    promptTotal = #out,
                })
            end
        end

        local char = LP and LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local mePos = hrp and hrp.Position
        local tagged = CollectionService:GetTagged(PROMPT_TAG)
        local promptTotal = #tagged
        local rows = {}
        local n = math.min(promptTotal, MAX_PROMPT_SCAN)
        local readFruit = (type(AS) == "table" and type(AS._scan) == "table" and type(AS._scan.readFruit) == "function")
            and AS._scan.readFruit
            or nil

        for i = 1, n do
            local prompt = tagged[i]
            if not (prompt and prompt.Parent and isStealPrompt(prompt)) then continue end
            local model = fruitModelFromPrompt(prompt)
            if not model or not model:IsA("Model") then continue end
            if model:GetAttribute("_GAG2FruitShell") == true then continue end

            local info = nil
            if readFruit then
                local ok, r = pcall(readFruit, model, prompt)
                if ok and type(r) == "table" then
                    info = normalizeStealRow(r)
                    info.hasPrompt = true
                end
            end

            if not info then
                local ownerId = tonumber(model:GetAttribute("UserId"))
                local plant = model
                if model.Parent and (model.Parent.Name == "Fruits" or model.Parent.Name == "Fruit") then
                    plant = model.Parent.Parent or model
                end
                if not ownerId and plant then
                    ownerId = tonumber(plant:GetAttribute("UserId"))
                end
                if LP and ownerId == LP.UserId then continue end
                if not ownerId then continue end

                local plantId = model:GetAttribute("PlantId") or (plant and plant:GetAttribute("PlantId"))
                local fruitId = model:GetAttribute("FruitId")
                if fruitId == nil and plant then fruitId = plant:GetAttribute("FruitId") end

                local pos = nil
                pcall(function()
                    pos = model:GetPivot().Position
                end)
                local dist = (mePos and typeof(pos) == "Vector3") and flatDist(mePos, pos) or math.huge
                local seed = resolveSeed(model)
                local mut = resolveMut(model)
                local kg = resolveKg(model)
                if kg <= 0 and plant and plant ~= model then
                    kg = resolveKg(plant)
                end
                info = {
                    seed = seed,
                    mut = mut,
                    kg = kg,
                    price = resolvePrice(model, seed, mut),
                    multi = 0,
                    dist = dist,
                    ownerUserId = ownerId,
                    ownerName = ownerNameOf(ownerId),
                    plantId = plantId,
                    fruitId = fruitId,
                    hold = tonumber(prompt.HoldDuration) or 0,
                    maxDist = tonumber(prompt.MaxActivationDistance) or 0,
                    hasPrompt = true,
                    stealable = true,
                }
            elseif mePos and (not info.dist or info.dist == math.huge) then
                local pos = nil
                pcall(function() pos = model:GetPivot().Position end)
                if typeof(pos) == "Vector3" then
                    info.dist = flatDist(mePos, pos)
                end
            end

            if info and info.ownerUserId and (not LP or info.ownerUserId ~= LP.UserId) then
                rows[#rows + 1] = info
            end
            if i % 40 == 0 then
                task.wait()
            end
        end

        return packStealResult(rows, {
            source = "scan",
            promptTotal = promptTotal,
            capped = promptTotal > MAX_PROMPT_SCAN,
        })
    end

    local function stealStatusLine()
        local carry = getCarryCount()
        local val = formatPrice(getCarryValue())
        local night = isNight() and "Night" or "Day"
        local AS = getAutoSteal()
        local asOn = type(AS) == "table" and type(AS.IsEnabled) == "function" and AS.IsEnabled() == true
        if asOn then
            return string.format("%s  ·  Carry %d  ·  $%s  ·  AutoSteal ON", night, carry, val)
        end
        return string.format("%s  ·  Carry %d  ·  $%s", night, carry, val)
    end

    local function sortLabel(mode)
        mode = tostring(mode or "price")
        if mode == "kg" then return "Kg" end
        if mode == "dist" then return "Near" end
        if mode == "seed" then return "Name" end
        if mode == "owner" then return "Owner" end
        return "Price"
    end

    local function fmtDist(dist)
        dist = tonumber(dist)
        if not dist or dist >= 1e6 then return "—" end
        return string.format("%.0f", dist)
    end

    local stealRowPool = {}
    local stealEmptyUi = nil

    local function stillLiveSteal(gen, anchor)
        if G.__GAG2_INFO_STEAL_GEN ~= gen then return false end
        if not anchor or not anchor.Parent then return false end
        return true
    end

    local function ensureStealEmpty(body)
        if stealEmptyUi and stealEmptyUi.row and stealEmptyUi.row.Parent then
            return stealEmptyUi
        end
        local row, lbl = ui:CreateRowLabel(body, "—", nil, nil, "info")
        stealEmptyUi = { row = row, lbl = lbl }
        return stealEmptyUi
    end

    local function ensureStealRow(body, i)
        local slot = stealRowPool[i]
        if slot and slot.row and slot.row.Parent and slot.lbl and slot.lbl.Parent then
            slot.row.Visible = true
            return slot.lbl
        end
        local row, lbl = ui:CreateRowLabel(body, "", nil, nil, "info")
        if lbl then
            lbl.TextWrapped = false
            lbl.TextTruncate = Enum.TextTruncate.AtEnd
            lbl.Font = Enum.Font.Code
            lbl.TextSize = 12
        end
        stealRowPool[i] = { row = row, lbl = lbl }
        return lbl
    end

    local function hideStealRowsFrom(fromIdx)
        for i = fromIdx, MAX_ROWS + 5 do
            local slot = stealRowPool[i]
            if slot and slot.row then
                slot.row.Visible = false
            end
        end
    end

    -- Format baris = steal test: [P/-] $price seed [mut] kg dist @owner
    local function formatStealRowLine(i, r)
        local canSteal = (r.hasPrompt ~= false)
            and r.ownerUserId ~= nil
            and r.plantId ~= nil
        local promptMark = canSteal and "P" or "-"
        local ownerShort = tostring(r.ownerName or ownerNameOf(r.ownerUserId) or "?")
        if #ownerShort > 14 then
            ownerShort = string.sub(ownerShort, 1, 13) .. "…"
        end
        local mut = tostring(r.mut or "")
        if mut ~= "" then
            return string.format(
                "%d. [%s] $%s  %s [%s]  %.2fkg  %sst  @%s",
                i,
                promptMark,
                formatPrice(r.price),
                tostring(r.seed or "?"),
                mut,
                tonumber(r.kg) or 0,
                fmtDist(r.dist),
                ownerShort
            )
        end
        return string.format(
            "%d. [%s] $%s  %s  %.2fkg  %sst  @%s",
            i,
            promptMark,
            formatPrice(r.price),
            tostring(r.seed or "?"),
            tonumber(r.kg) or 0,
            fmtDist(r.dist),
            ownerShort
        )
    end

    local function renderSteal(gen, summaryLbl, statusLbl, listBody, data)
        if not stillLiveSteal(gen, summaryLbl) then return end
        if not isInfoStealTab() then return end

        if statusLbl and statusLbl.Parent then
            statusLbl.Text = stealStatusLine()
        end

        local rows = type(data.rows) == "table" and data.rows or {}
        local n = #rows
        local owners = tonumber(data.owners) or 0
        local fruits = tonumber(data.scanned) or n
        local sortMode = tostring(data.sortMode or getStealSortMode())
        local src = tostring(data.source or "scan")
        local srcLabel = (src == "autosteal") and "AutoSteal" or "Scan"

        if fruits <= 0 then
            summaryLbl.Text = string.format(
                "%s · fruits 0 · %s",
                srcLabel,
                sortLabel(sortMode)
            )
        else
            summaryLbl.Text = string.format(
                "%s · fruits %d · listed %d · owners %d · %s",
                srcLabel,
                fruits,
                n,
                owners,
                sortLabel(sortMode)
            )
        end

        if n == 0 then
            hideStealRowsFrom(1)
            local empty = ensureStealEmpty(listBody)
            if empty.row then empty.row.Visible = true end
            if empty.lbl then
                empty.lbl.Text = isNight()
                    and "No StealPrompt targets right now."
                    or "Wait for night (or enable Auto Steal)."
            end
            return
        end

        if stealEmptyUi and stealEmptyUi.row then
            stealEmptyUi.row.Visible = false
        end

        for i = 1, n do
            local lbl = ensureStealRow(listBody, i)
            if lbl then
                lbl.Text = formatStealRowLine(i, rows[i])
            end
        end
        hideStealRowsFrom(n + 1)
    end

    -- INFO di bawah MISC (MISC order=2)
    ui:RegisterMainTab("info", "INFO", 3)

    ui:RegisterSubTab("info", "garden", "Garden", function()
        ui:ClearSubContent()
        -- ClearSubContent sudah destroy UI lama — reset pool referensi
        for k in pairs(plantUiPool) do
            plantUiPool[k] = nil
        end
        emptyPlantsUi = nil

        local gen = (tonumber(G.__GAG2_INFO_GARDEN_GEN) or 0) + 1
        G.__GAG2_INFO_GARDEN_GEN = gen

        -- Load saved toggle + scan interval (MAIN.misc.info_garden)
        local scanSec = DEFAULT_SCAN_SEC
        do
            local cfg = getMisc("info_garden") or {}
            local on = (cfg.enabled == true) or (G.__GAG2_INFO_GARDEN_ENABLED == true)
            G.__GAG2_INFO_GARDEN_ENABLED = on
            _G.__GAG2_INFO_GARDEN_ENABLED = on
            scanSec = clampScanSec(cfg.scan_sec or G.__GAG2_INFO_GARDEN_SCAN_SEC or DEFAULT_SCAN_SEC)
            G.__GAG2_INFO_GARDEN_SCAN_SEC = scanSec
            _G.__GAG2_INFO_GARDEN_SCAN_SEC = scanSec
        end

        local enabled = isScanEnabled()
        local bodySummary = ui:CreateSection("Summary", true)
        local _, summaryLbl = ui:CreateRowLabel(
            bodySummary,
            enabled and "Enabled — scanning…" or "Disabled — nyalakan Enabled untuk scan.",
            nil,
            nil,
            "accent"
        )
        local mutRow, mutLbl = ui:CreateRowLabel(
            bodySummary,
            enabled and "Total by mutation: (scanning…)" or "Total by mutation: —",
            nil,
            nil,
            "info"
        )
        if mutLbl then
            mutLbl.TextWrapped = true
            mutLbl.TextTruncate = Enum.TextTruncate.None
            mutLbl.TextYAlignment = Enum.TextYAlignment.Top
            mutLbl.AutomaticSize = Enum.AutomaticSize.Y
            mutLbl.Size = UDim2.new(1, 0, 0, 0)
        end
        if mutRow and mutRow:IsA("GuiObject") then
            mutRow.AutomaticSize = Enum.AutomaticSize.Y
            mutRow.Size = UDim2.new(1, 0, 0, 0)
        end
        local eclRow, eclLbl = ui:CreateRowLabel(
            bodySummary,
            formatEclSummary(),
            nil,
            nil,
            "info"
        )
        if eclLbl then
            eclLbl.TextWrapped = true
            eclLbl.TextTruncate = Enum.TextTruncate.None
            eclLbl.TextYAlignment = Enum.TextYAlignment.Top
            eclLbl.AutomaticSize = Enum.AutomaticSize.Y
            eclLbl.Size = UDim2.new(1, 0, 0, 0)
        end
        if eclRow and eclRow:IsA("GuiObject") then
            eclRow.AutomaticSize = Enum.AutomaticSize.Y
            eclRow.Size = UDim2.new(1, 0, 0, 0)
        end

        ui:CreateRowInput(
            bodySummary,
            "Scanning (sec)",
            tostring(scanSec),
            function(txt)
                local n = clampScanSec(txt)
                setScanSec(n)
            end
        )

        ui:CreateRowToggle(bodySummary, "Enabled", enabled, function(on)
            setScanEnabled(on == true)
            if not stillLive(gen, summaryLbl) then return end
            if on == true then
                summaryLbl.Text = "Enabled — scanning…"
                if mutLbl and mutLbl.Parent then
                    mutLbl.Text = "Total by mutation: (scanning…)"
                end
                paintEclLbl(eclLbl)
            else
                summaryLbl.Text = "Disabled — scan di-pause."
                if mutLbl and mutLbl.Parent then
                    mutLbl.Text = "Total by mutation: —"
                end
                paintEclLbl(eclLbl)
            end
        end)

        -- Placeholder (reuse empty UI pool — nanti di-update Text, bukan dibuat ulang)
        do
            local empty = ensureEmptyPlantsUi()
            if empty.infoLbl then
                empty.infoLbl.Text = enabled
                    and "Memuat list fruit…"
                    or ("Nyalakan Enabled untuk mulai scan (setiap " .. tostring(scanSec) .. " detik).")
            end
        end

        task.spawn(function()
            while stillLive(gen, summaryLbl) do
                -- Pause penuh saat bukan tab INFO/Garden (hemat CPU)
                if not isInfoGardenTab() then
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                if not isScanEnabled() then
                    if summaryLbl and summaryLbl.Parent then
                        if summaryLbl.Text == "" or summaryLbl.Text:find("scanning", 1, true)
                            or summaryLbl.Text:find("Memuat", 1, true) then
                            summaryLbl.Text = "Disabled — scan di-pause."
                        end
                    end
                    paintEclLbl(eclLbl)
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                if not stillLive(gen, summaryLbl) or not isInfoGardenTab() then
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                local data = scanGarden()

                if not stillLive(gen, summaryLbl) then return end
                -- Selesai scan tapi sudah pindah tab / disable → jangan rebuild UI berat
                if not isInfoGardenTab() or not isScanEnabled() then
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                renderResults(gen, summaryLbl, mutLbl, eclLbl, data)

                if not waitScanGap(gen, summaryLbl, data and data.count) then
                    return
                end
            end
        end)
    end, 1)

    ui:RegisterSubTab("info", "steal", "Steal", function()
        ui:ClearSubContent()
        for i in pairs(stealRowPool) do
            stealRowPool[i] = nil
        end
        stealEmptyUi = nil

        local gen = (tonumber(G.__GAG2_INFO_STEAL_GEN) or 0) + 1
        G.__GAG2_INFO_STEAL_GEN = gen

        local scanSec = DEFAULT_SCAN_SEC
        local sortMode = "price"
        do
            local cfg = getMisc("info_steal") or {}
            local on = (cfg.enabled == true) or (G.__GAG2_INFO_STEAL_ENABLED == true)
            G.__GAG2_INFO_STEAL_ENABLED = on
            _G.__GAG2_INFO_STEAL_ENABLED = on
            scanSec = clampScanSec(cfg.scan_sec or G.__GAG2_INFO_STEAL_SCAN_SEC or DEFAULT_SCAN_SEC)
            G.__GAG2_INFO_STEAL_SCAN_SEC = scanSec
            _G.__GAG2_INFO_STEAL_SCAN_SEC = scanSec
            sortMode = setStealSortMode(cfg.sort_mode or G.__GAG2_INFO_STEAL_SORT or "price")
        end

        local enabled = isStealScanEnabled()
        local bodySummary = ui:CreateSection("Steal", true)
        local _, statusLbl = ui:CreateRowLabel(
            bodySummary,
            stealStatusLine(),
            nil,
            nil,
            "accent"
        )
        local _, summaryLbl = ui:CreateRowLabel(
            bodySummary,
            enabled and "Scanning…" or "Off",
            nil,
            nil,
            "info"
        )

        ui:CreateRowDropdown(bodySummary, {
            label = "Sort",
            placeholder = "Price",
            mode = "single",
            getItems = function()
                return {
                    { key = "price", name = "Price" },
                    { key = "kg", name = "Kg" },
                    { key = "dist", name = "Near" },
                    { key = "seed", name = "Name" },
                    { key = "owner", name = "Owner" },
                }
            end,
            initial = sortMode,
            onChanged = function(_, selectedKey)
                setStealSortMode(selectedKey)
            end,
        })

        ui:CreateRowInput(
            bodySummary,
            "Refresh (sec)",
            tostring(scanSec),
            function(txt)
                setStealScanSec(clampScanSec(txt))
            end
        )

        ui:CreateRowToggle(bodySummary, "Enabled", enabled, function(on)
            setStealScanEnabled(on == true)
            if not stillLiveSteal(gen, summaryLbl) then return end
            summaryLbl.Text = (on == true) and "Scanning…" or "Off"
        end)

        local listBody = ui:CreateSection("Targets", true)
        do
            local empty = ensureStealEmpty(listBody)
            if empty.lbl then
                empty.lbl.Text = enabled and "Loading…" or "Turn on Enabled to scan."
            end
        end

        task.spawn(function()
            while stillLiveSteal(gen, summaryLbl) do
                if not isInfoStealTab() then
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                if statusLbl and statusLbl.Parent then
                    statusLbl.Text = stealStatusLine()
                end

                if not isStealScanEnabled() then
                    if summaryLbl and summaryLbl.Parent then
                        summaryLbl.Text = "Off"
                    end
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                local okScan, data = pcall(scanStealLight)
                if not okScan then
                    if summaryLbl and summaryLbl.Parent then
                        summaryLbl.Text = "Scan failed"
                    end
                    task.wait(1)
                    continue
                end
                if not stillLiveSteal(gen, summaryLbl) then return end
                if not isInfoStealTab() or not isStealScanEnabled() then
                    task.wait(PAUSE_POLL_SEC)
                    continue
                end

                pcall(renderSteal, gen, summaryLbl, statusLbl, listBody, data)

                pcall(function()
                    local rows = type(data) == "table" and data.rows or nil
                    G.__GAG2_INFO_STEAL_LAST = {
                        at = os.clock(),
                        rows = rows,
                        scanned = type(data) == "table" and data.scanned or 0,
                        promptTotal = type(data) == "table" and data.promptTotal or 0,
                        source = type(data) == "table" and data.source or "scan",
                    }
                    _G.__GAG2_INFO_STEAL_LAST = G.__GAG2_INFO_STEAL_LAST
                end)

                local untilAt = os.clock() + getStealScanSec()
                while os.clock() < untilAt do
                    if not stillLiveSteal(gen, summaryLbl) then return end
                    if not isInfoStealTab() then break end
                    if statusLbl and statusLbl.Parent then
                        statusLbl.Text = stealStatusLine()
                    end
                    if not isStealScanEnabled() then break end
                    task.wait(PAUSE_POLL_SEC)
                end
            end
        end)
    end, 2)
end

return M
 end,                      required = false },
    { key = "PSReconnect",             name = "PSReconnect",             factory = function() -- PSReconnect.lua (FULL, DEBUG + HARD GATE)
-- ✅ Rejoin (PS-safe) + optional auto reconnect
-- ✅ Auto Exec STRICT dari save file: autohatch/<username>.json -> rejoin.auto_exec
-- ✅ queue_on_teleport hanya dipanggil jika auto_exec true
-- ✅ QTP chunk cek file lagi di server baru (OFF => skip)
-- ✅ QTP chunk nulis marker file + --warn() (biar kebukti jalan / gak jalan)
-- ✅ Kalau auto_exec ON tapi QTP gagal -> CANCEL teleport (biar gak rejoin tanpa autoexec)
-- ✅ Export ke _G/getgenv: _G.PSReconnect selalu ada
-- ✅ Debounce anti spam prompt

