local function normText(s)
    s = tostring(s or "")
    s = s:gsub("%s+", " ")
    s = s:gsub("^%s+", "")
    s = s:gsub("%s+$", "")
    return s
end

local function dprint(...)
    if not DEBUG_PSRECONNECT then return end
    print("[PSReconnect]", ...)
end

-- debounce
local _rejoinInFlight       = false
local _shutdownRejoinBusy   = false
local _lastRejoinT          = 0
local MIN_REJOIN_INTERVAL   = 6
local _teleportAntiPromptStarted = false
local _hideTeleportPromptEnabled = false
local _lastTeleportFailAt   = 0
local _lastTeleportFailMsg  = ""
local _teleportAttemptToken = 0

-- Event world (Ghoul / Fall Harvest / PetHunt) butuh travel token game.
-- TeleportService:Teleport(PlaceId event) = Unauthorized "valid teleport token".
local MAIN_PLACE_ID = 97598239454123
local EVENT_PLACE_IDS = {
    [102868797705537] = true, -- GhoulGarden
    [136420110879676] = true, -- GhoulGardenBotUser
    [120978386897995] = true, -- PetHuntGhoulGarden
    [126987765280963] = true, -- FallHarvest
