local function setRejoinInFlight(on)
    _rejoinInFlight = (on == true)
    G.__GAG2_REJOIN_IN_FLIGHT = _rejoinInFlight
    G.__GAG2_PAUSE_WORLD_TRAVEL = _rejoinInFlight
    _G.__GAG2_REJOIN_IN_FLIGHT = _rejoinInFlight
    _G.__GAG2_PAUSE_WORLD_TRAVEL = _rejoinInFlight
end

local function getMainPlaceId()
    local pid = MAIN_PLACE_ID
    local ok, Worlds = pcall(function()
        return require(ReplicatedStorage.SharedModules.Worlds)
    end)
    if ok and type(Worlds) == "table" and type(Worlds.GetPlaceId) == "function" then
        local ok2, v = pcall(Worlds.GetPlaceId, Worlds, "Main")
        if not ok2 then
            ok2, v = pcall(Worlds.GetPlaceId, "Main")
        end
        v = tonumber(v)
        if ok2 and v then
            pid = v
        end
    end
    return pid
end

local function isEventWorldPlace(placeId)
    placeId = tonumber(placeId) or tonumber(game.PlaceId)
    if EVENT_PLACE_IDS[placeId] == true then
        return true
    end
    local ok, Worlds = pcall(function()
        return require(ReplicatedStorage.SharedModules.Worlds)
    end)
    if ok and type(Worlds) == "table" then
        if Worlds.IsMain == false then
            return true
        end
        local id = Worlds.CurrentId
        if type(id) == "string" and id ~= "" and id ~= "Main" then
            return true
        end
    end
    return false
end

local function fireRequestTravel(worldId)
    worldId = tostring(worldId or "Main")
    local ok, Net = pcall(function()
        return require(ReplicatedStorage.SharedModules.Networking)
    end)
    if not ok or type(Net) ~= "table" then
        return false
    end
    local node = Net.Worlds and Net.Worlds.RequestTravel
    if node == nil then
        return false
    end
    local okF = pcall(function()
        if type(node.Fire) == "function" then
            node:Fire(worldId)
        elseif type(node.FireServer) == "function" then
            node:FireServer(worldId)
        else
            error("nofire")
        end
    end)
    return okF
end

local function _hidePromptGloballyEnabled()
    if _hideTeleportPromptEnabled == true then
        return true
    end
    local ge = (getgenv and getgenv()) or _G
    return ge.HIDE_PROMPT_ENABLED == true or rawget(_G, "HIDE_PROMPT_ENABLED") == true
end

