MAIN.misc.hub_ui = (type(MAIN.misc.hub_ui) == "table") and MAIN.misc.hub_ui or _deepCopy(DEFAULT_MISC.hub_ui)
do
    local hub = MAIN.misc.hub_ui
    local def = DEFAULT_MISC.hub_ui
    local function clamp01(n, fallback)
        n = tonumber(n)
        if n == nil then return fallback end
        if n < 0 then n = 0 end
        if n > 1 then n = 1 end
        return n
    end
    hub.panel_transparency = clamp01(hub.panel_transparency, def.panel_transparency)
    -- backdrop selalu full clear (anti blur / anti dim)
    hub.overlay_transparency = 1
    -- section ikut panel (1 setting)
    hub.section_transparency = hub.panel_transparency
end
