local function _normalizeAutoKillMonsterState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_AUTO.killMonster)
    st.enabled = (st.enabled == true)
    if st.smashPumpkin == nil then st.smashPumpkin = true end
    st.smashPumpkin = (st.smashPumpkin ~= false)
    local types = {}
    local seen = {}
    local raw = st.types
    if type(raw) == "table" then
        if raw[1] ~= nil then
            for _, v in ipairs(raw) do
                local s = tostring(v or "")
                if s ~= "" and not seen[s] then
                    seen[s] = true
                    types[#types + 1] = s
                end
            end
        else
            for k, v in pairs(raw) do
                if v == true then
                    local s = tostring(k)
                    if s ~= "" and not seen[s] then
                        seen[s] = true
                        types[#types + 1] = s
                    end
                end
            end
        end
    end
    st.types = types
    return st
end

