local function _normalizeFruitGardenEspPriority(v)
    v = tostring(v or ""):lower()
    if v == "price" then return "price" end
    return "kg"
end

local function _clampFruitGardenEspMax(n)
    n = math.floor(tonumber(n) or 100)
    if n < 1 then n = 1 end
    if n > 5000 then n = 5000 end
    return n
end

local function _normalizeFruitGardenEspState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_MISC.fruit_garden_esp)
    st.enabled = (st.enabled == true)
    st.priority = _normalizeFruitGardenEspPriority(st.priority)
    st.max_esp = _clampFruitGardenEspMax(st.max_esp)
    st.fruits = _mapToArray(st.fruits)
    return st
end

