    st.scan_sec = sec
    return st
end

local function _normalizeInfoStealState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_MISC.info_steal)
    st.enabled = (st.enabled == true)
    local sec = math.floor(tonumber(st.scan_sec) or 5)
    if sec < 1 then sec = 1 end
    if sec > 60 then sec = 60 end
    st.scan_sec = sec
    local sm = tostring(st.sort_mode or "price"):lower()
    if sm ~= "kg" and sm ~= "near" and sm ~= "seed" and sm ~= "owner" then
        sm = "price"
    end
    st.sort_mode = sm
    return st
end

