local function _normalizeMoveMode(mode)
    mode = tostring(mode or "walk"):lower()
    if mode == "button" then
        return "walk" -- legacy: button dihapus dari UI
    end
    if mode == "step" or mode == "walk" or mode == "hard" or mode == "soft" then
        return mode
    end
    return "walk"
end

local function _clampMoveSoftSpeed(n)
    n = math.floor(tonumber(n) or 30)
    if n < 1 then n = 1 end
    if n > 300 then n = 300 end
    return n
end

local function _clampMoveStepSpeed(n)
    n = math.floor(tonumber(n) or 30)
    if n < 1 then n = 1 end
    if n > 400 then n = 400 end
    return n
end

local function _clampMoveWalkSpeed(n)
    n = math.floor(tonumber(n) or 30)
    if n < 1 then n = 1 end
    if n > 200 then n = 200 end
    return n
end

local function _normalizeCharacterState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_MISC.character)
    local def = DEFAULT_MISC.character
    st.move_mode = _normalizeMoveMode(st.move_mode)
    st.soft_speed = _clampMoveSoftSpeed(st.soft_speed ~= nil and st.soft_speed or def.soft_speed)
    st.step_speed = _clampMoveStepSpeed(st.step_speed ~= nil and st.step_speed or def.step_speed)
    st.walk_speed = _clampMoveWalkSpeed(st.walk_speed ~= nil and st.walk_speed or def.walk_speed)
    -- clip UI dihapus — jangan persist ON dari toggle lama
    st.clip = false
    st.path_mode = nil -- legacy underground dihapus
    st.move_path = nil
    return st
end

