    end
    if swPosMode ~= nil then sw.position_mode = normalizePositionMode(swPosMode) end

    MAIN.auto.sprinklerOtherGarden = _normalizeSprinklerOtherGardenState(sw)
    STATE.auto_sprinkler_other_garden = _deepCopy(MAIN.auto.sprinklerOtherGarden)
