    local order = G.OPEN_EGG_RULES_ORDER or rawget(_G, "OPEN_EGG_RULES_ORDER")
    if type(order) == "table" then MAIN.auto.openEgg.rulesOrder = order end

    MAIN.auto.openEgg = _normalizeOpenEggState(MAIN.auto.openEgg)
    STATE.auto_open_egg = _deepCopy(MAIN.auto.openEgg)
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function syncAutoSellPetGlobalsToMain()
    local mainRef = _getMainRef()
    if mainRef ~= MAIN then
        MAIN = mainRef
    end

    MAIN.auto = MAIN.auto or _deepCopy(DEFAULT_AUTO)
    MAIN.auto.sellPet = MAIN.auto.sellPet or _deepCopy(DEFAULT_AUTO.sellPet)

    local on = G.AUTO_SELL_PET_ENABLED
    if on == nil then on = rawget(_G, "AUTO_SELL_PET_ENABLED") end
    if on ~= nil then MAIN.auto.sellPet.enabled = (on == true) end

    local sel = G.AUTO_SELL_PET_SELECTED or rawget(_G, "AUTO_SELL_PET_SELECTED")
    if type(sel) == "table" and next(sel) then
        MAIN.auto.sellPet.pets = _mapToArray(sel)
    end

    MAIN.auto.sellPet = _normalizeAutoSellPetState(MAIN.auto.sellPet)
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

