-- Saat save: MAIN = source of truth → snapshot (jangan timpa MAIN dari snapshot stale)
local function _syncAutoHopSnapshotFromMain()
    MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
    MAIN.misc.rejoin = MAIN.misc.rejoin or _deepCopy(DEFAULT_MISC.rejoin)
    local ah = _normalizeAutoHopState(MAIN.misc.rejoin.auto_hop)
    MAIN.misc.rejoin.auto_hop = ah

    G.__AUTO_HOP_SAVED = {
        enabled = ah.enabled,
        current = ah.current_player,
        max = ah.max_player,
        delay = ah.teleport_delay,
    }
    _G.__AUTO_HOP_SAVED = G.__AUTO_HOP_SAVED
end

-- Hop cuma update visited — jangan full save (bisa overwrite setting UI ke default)
local function saveAutoHopVisitedOnly(visited)
    if not FS.ok or not _ensureFolder() then return end

    local out = {}
    if type(visited) == "table" then
        for _, v in ipairs(visited) do
            local s = tostring(v or "")
            if s ~= "" then out[#out + 1] = s end
        end
    end

    local data = {}
    if isfile(SAVE_FILE) then
        local ok, text = pcall(readfile, SAVE_FILE)
        if ok and type(text) == "string" and #text > 0 then
            local ok2, parsed = pcall(function()
                return HttpService:JSONDecode(text)
            end)
            if ok2 and type(parsed) == "table" then
                data = parsed
            else
                -- JSON rusak (mati lampu / write putus). Jangan encode {} lalu timpa save utuh.
                warn("[GAG2 state] hop visited skip: save JSON rusak, tidak overwrite")
                return
            end
        end
    end

    data.main = type(data.main) == "table" and data.main or {}
    data.main.misc = type(data.main.misc) == "table" and data.main.misc or {}
    data.main.misc.rejoin = type(data.main.misc.rejoin) == "table" and data.main.misc.rejoin or {}
    local ah = type(data.main.misc.rejoin.auto_hop) == "table" and data.main.misc.rejoin.auto_hop or {}
    data.main.misc.rejoin.auto_hop = ah

    MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
    MAIN.misc.rejoin = MAIN.misc.rejoin or _deepCopy(DEFAULT_MISC.rejoin)
    local mainAh = _normalizeAutoHopState(MAIN.misc.rejoin.auto_hop)
    MAIN.misc.rejoin.auto_hop = mainAh

    -- Merge setting dari MAIN (bukan cuma dari file stale) supaya delay/current/max tidak reset
    ah.enabled = mainAh.enabled
    ah.current_player = mainAh.current_player
    ah.max_player = mainAh.max_player
    ah.teleport_delay = mainAh.teleport_delay
    ah.minutes = mainAh.minutes
    ah.diff_servers = mainAh.diff_servers
    ah.visited = _deepCopy(out)
    ah.delay = nil

    MAIN.misc.rejoin.auto_hop.visited = _deepCopy(out)
    G.MAIN = MAIN
    _G.MAIN = MAIN

    _syncAutoHopSnapshotFromMain()

    local ok, json = pcall(function()
        return HttpService:JSONEncode(data)
    end)
    if ok and type(json) == "string" then
        pcall(writefile, SAVE_FILE, json)
    end
end

G.__GAG2_SAVE_AUTO_HOP_VISITED = saveAutoHopVisitedOnly
_G.__GAG2_SAVE_AUTO_HOP_VISITED = saveAutoHopVisitedOnly

local function _prepareMainForSave()
    local live = G.MAIN or _G.MAIN
    if type(live) == "table" then
        MAIN = live
    end
    if type(MAIN) ~= "table" then
        MAIN = {}
    end
    MAIN.auto = MAIN.auto or _deepCopy(DEFAULT_AUTO)
    MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
    MAIN.misc.rejoin = (type(MAIN.misc.rejoin) == "table") and MAIN.misc.rejoin or _deepCopy(DEFAULT_MISC.rejoin)

    _pullUiStoresIntoMain()
    _syncAutoHopSnapshotFromMain()

    _safeNormalizeMainAutoForSave()
    syncRejoinGlobalsToMain()
    syncWeatherPredictGlobalsToMain()
    syncPetFinderGlobalsToMain()
    syncReduceFpsGlobalsToMain()
    syncFruitBackpackEspGlobalsToMain()
    syncFruitGardenEspGlobalsToMain()
    syncHidePromptGlobalsToMain()
    syncHideHarvestPromptGlobalsToMain()
    syncHideLoadingGlobalsToMain()
    syncInfoStealGlobalsToMain()
    syncInfoGardenGlobalsToMain()
    syncCharacterGlobalsToMain()
    syncHubUiGlobalsToMain()
    syncAutoVulnGlobalsToMain()
    _syncAllRuntimeFromMain()
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function _snapshotTrackServerForExport()
    local out = {
        ws_id = "",
        status = "off",
    }

    local NH = rawget(_G, "NodeHubWS") or G.NodeHubWS
    if type(NH) == "table" then
        local bridge = (type(NH.Get) == "function" and NH.Get("gag2")) or nil
        if type(bridge) == "table" then
            out.ws_id = tostring(bridge.wsId or ""):match("^%s*(.-)%s*$") or ""
            out.status = (bridge.trackEnabled == true or bridge.active == true) and "on" or "off"
            if bridge.scId ~= nil then
                out.sc_id = bridge.scId
            end
            return out
        end
        if type(NH.Debug) == "function" then
            local okDbg, dbg = pcall(NH.Debug, "gag2")
            if okDbg and type(dbg) == "table" then
                out.ws_id = tostring(dbg.ws_id or ""):match("^%s*(.-)%s*$") or ""
                out.status = (dbg.track_enabled == true or dbg.active == true) and "on" or "off"
                if dbg.sc_id ~= nil then
                    out.sc_id = dbg.sc_id
                end
                return out
            end
        end
    end

    -- Fallback: file track-state terpisah (bukan SAVE_FILE script)
    if type(isfile) == "function" and type(readfile) == "function" then
        local uid = (LP and LP.UserId) or "unknown"
        local path = ("nodehub_ws_static/gag2_%s.json"):format(tostring(uid))
        if isfile(path) then
            local ok, text = pcall(readfile, path)
            if ok and type(text) == "string" and text ~= "" then
                local ok2, data = pcall(function()
                    return HttpService:JSONDecode(text)
                end)
                if ok2 and type(data) == "table" then
                    out.ws_id = tostring(data.ws_id or data.wsId or ""):match("^%s*(.-)%s*$") or ""
                    local st = tostring(data.status or data.track_status or ""):lower()
                    if st == "on" or st == "1" or st == "true"
                        or data.active == true
                        or data.track_enabled == true
                        or data.trackEnabled == true then
                        out.status = "on"
                    end
                    if data.sc_id ~= nil or data.scId ~= nil then
                        out.sc_id = data.sc_id or data.scId
                    end
                end
            end
        end
    end

    return out
end

local function _writeTrackServerFile(wsId, wantOn, scId)
    if type(writefile) ~= "function" then
        return false, "no_fs"
    end
    local uid = (LP and LP.UserId) or "unknown"
    local path = ("nodehub_ws_static/gag2_%s.json"):format(tostring(uid))
    if type(makefolder) == "function" then
        pcall(makefolder, "nodehub_ws_static")
    end
    local payload = {
        schema = "nodehub_ws_static_track_state_v38",
        namespace = "gag2",
        ws_id = tostring(wsId or ""),
        status = wantOn and "on" or "off",
        ts = os.time(),
    }
    if scId ~= nil then
        payload.sc_id = scId
    end
    local ok, json = pcall(function()
        return HttpService:JSONEncode(payload)
    end)
    if not ok or type(json) ~= "string" then
        return false, "encode_failed"
    end
    local okW = pcall(writefile, path, json)
    return okW == true, path
end

local function _applyTrackServerFromData(data)
    if type(data) ~= "table" then
        return false, "no_data"
    end
    local ts = data.track_server or data.trackServer or data.nodehub_track
    if type(ts) ~= "table" then
        return false, "no_track_server"
    end

    local wsId = tostring(ts.ws_id or ts.wsId or ""):match("^%s*(.-)%s*$") or ""
    local status = tostring(ts.status or ts.track_status or ts.trackStatus or ""):lower()
    local wantOn = (status == "on" or status == "1" or status == "true"
        or ts.enabled == true
        or ts.active == true
        or ts.track_enabled == true
        or ts.trackEnabled == true)
    if wsId == "" then
        wantOn = false
    end
    local scId = ts.sc_id or ts.scId

    -- Selalu tulis file track-state supaya auto-boot / akun baru ikut
    pcall(_writeTrackServerFile, wsId, wantOn, scId)

    local NH = rawget(_G, "NodeHubWS") or G.NodeHubWS
    if type(NH) ~= "table" then
        return true, "file_only_no_helper"
    end

    local bridge = (type(NH.Get) == "function" and NH.Get("gag2")) or nil
    if type(bridge) ~= "table" then
        local defs = G.__NODEHUB_WS_DEFAULTS or rawget(_G, "__NODEHUB_WS_DEFAULTS") or {}
        local opts = {
            namespace = "gag2",
            wsId = wsId,
            persistTrackState = true,
            autoStartOnBoot = wantOn == true,
            autoStartDelay = 0.35,
            wsBaseUrl = defs.wsBaseUrl or G.__NODEHUB_WS_BASE_URL or rawget(_G, "__NODEHUB_WS_BASE_URL"),
            authPassword = defs.authPassword or G.__NODEHUB_WS_AUTH_PASSWORD or rawget(_G, "__NODEHUB_WS_AUTH_PASSWORD"),
            sc_id = scId or defs.sc_id,
            scriptName = defs.scriptName or "Grow A Garden 2",
            gameName = defs.gameName or "Grow A Garden 2",
            sendDefaultConfigOnTrack = true,
            sendDefaultConfigOnChange = true,
        }
        if type(NH.GAG2AutoStart) == "function" then
            pcall(NH.GAG2AutoStart, opts)
        elseif type(NH.GAG2) == "function" then
            pcall(NH.GAG2, nil, opts)
        elseif type(NH.Setup) == "function" then
            pcall(NH.Setup, opts)
        end
        bridge = (type(NH.Get) == "function" and NH.Get("gag2")) or nil
    end

    if type(bridge) ~= "table" then
        return true, "file_only_no_bridge"
    end

    bridge.wsId = wsId
    if scId ~= nil then
        local n = tonumber(scId)
        if n and n >= 1 then
            bridge.scId = math.floor(n)
        end
    end

    if type(bridge._wsIdSetter) == "function" then
        pcall(bridge._wsIdSetter, wsId)
    end

    if wantOn then
        if type(bridge.SetActive) == "function" then
            pcall(bridge.SetActive, bridge, true)
        elseif type(bridge.Connect) == "function" then
            pcall(bridge.Connect, bridge, wsId)
            if type(bridge.SetTrack) == "function" then
                pcall(bridge.SetTrack, bridge, true)
            end
        end
        if type(bridge.ScheduleAutoResume) == "function" then
            pcall(bridge.ScheduleAutoResume, bridge, "import_config")
        end
        if type(bridge._trackToggleSetter) == "function" then
            pcall(bridge._trackToggleSetter, true, true)
        end
    else
        if type(bridge.SetActive) == "function" then
            pcall(bridge.SetActive, bridge, false)
        else
            if type(bridge.SetTrack) == "function" then
                pcall(bridge.SetTrack, bridge, false)
            end
            if type(bridge.Disconnect) == "function" then
                pcall(bridge.Disconnect, bridge)
            end
            if type(bridge.SavePrefs) == "function" then
                bridge.trackEnabled = false
                bridge.active = false
                pcall(bridge.SavePrefs, bridge)
            end
        end
        if type(bridge._trackToggleSetter) == "function" then
            pcall(bridge._trackToggleSetter, false, true)
        end
    end

    return true, wantOn and "track_on" or "track_off"
end

local function _buildSelectionsPayload(opts)
    opts = type(opts) == "table" and opts or {}
    local forExport = (opts.forExport == true)

    if opts.skipPrepare == true then
        -- Close/restart: jangan isi DEFAULT lalu tulis — itu yang ngereset save.
        local live = G.MAIN or _G.MAIN
        if type(live) ~= "table" or type(live.auto) ~= "table" then
            return nil
        end
        MAIN = live
        MAIN.misc = (type(MAIN.misc) == "table") and MAIN.misc or {}
        MAIN.misc.rejoin = (type(MAIN.misc.rejoin) == "table") and MAIN.misc.rejoin or {}
    else
        _prepareMainForSave()
        if type(MAIN) ~= "table" then
            MAIN = type(G.MAIN) == "table" and G.MAIN or {}
        end
        MAIN.auto = MAIN.auto or _deepCopy(DEFAULT_AUTO)
        MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
        MAIN.misc.rejoin = (type(MAIN.misc.rejoin) == "table") and MAIN.misc.rejoin or _deepCopy(DEFAULT_MISC.rejoin)
    end

    local enabled, minute = readUpdateNewServerGlobals()
    MAIN.misc.rejoin.update_new_server        = enabled
    MAIN.misc.rejoin.update_new_server_minute  = minute

    local rejoin = _deepCopy(MAIN.misc.rejoin)
    if forExport and type(rejoin) == "table" and type(rejoin.auto_hop) == "table" then
        rejoin.auto_hop.visited = {}
    end

    local payload = {
        main = {
            misc = {
                rejoin = rejoin,
                weather_predict = _deepCopy(MAIN.misc.weather_predict),
                pet_finder = _snapshotPetFinderForSave(MAIN.misc.pet_finder),
                perf = _deepCopy(MAIN.misc.perf),
                fruit_backpack_esp = _deepCopy(MAIN.misc.fruit_backpack_esp),
                fruit_garden_esp = _deepCopy(MAIN.misc.fruit_garden_esp),
                hide_prompt = _deepCopy(MAIN.misc.hide_prompt),
                hide_harvest_prompt = _deepCopy(MAIN.misc.hide_harvest_prompt),
                hide_loading = _deepCopy(MAIN.misc.hide_loading),
                info_steal = _deepCopy(MAIN.misc.info_steal),
                info_garden = _deepCopy(MAIN.misc.info_garden),
                character = _deepCopy(MAIN.misc.character),
                hub_ui = _deepCopy(_normalizeHubUiState(MAIN.misc.hub_ui)),
                auto_vuln = _deepCopy(MAIN.misc.auto_vuln),
            },
            auto = {
                collect = _deepCopy(MAIN.auto.collect),
                sell = _deepCopy(MAIN.auto.sell),
                sellStock = _deepCopy(MAIN.auto.sellStock),
                sellDaily = _deepCopy(MAIN.auto.sellDaily),
                mergeEclipse = _deepCopy(MAIN.auto.mergeEclipse),
                shovel = _deepCopy(MAIN.auto.shovel),
                shovelFruit = _deepCopy(MAIN.auto.shovelFruit),
                plant = _deepCopy(MAIN.auto.plant),
                trowel = _deepCopy(MAIN.auto.trowel),
                sprinkler = _deepCopy(MAIN.auto.sprinkler),
                watering = _deepCopy(MAIN.auto.watering),
                plot = _deepCopy(MAIN.auto.plot),
                fav = _deepCopy(MAIN.auto.fav),
                unfav = _deepCopy(MAIN.auto.unfav),
                buy = _deepCopy(MAIN.auto.buy),
                claimSeed = _deepCopy(MAIN.auto.claimSeed),
                gardenCards = _deepCopy(MAIN.auto.gardenCards),
                dragonEgg = _deepCopy(MAIN.auto.dragonEgg),
                steal = _deepCopy(MAIN.auto.steal),
                fallHarvest = _deepCopy(MAIN.auto.fallHarvest),
                killMonster = _deepCopy(MAIN.auto.killMonster),
                cauldron = _deepCopy(MAIN.auto.cauldron),
                openEgg = _deepCopy(MAIN.auto.openEgg),
                sprinklerOtherGarden = _deepCopy(MAIN.auto.sprinklerOtherGarden),
                sellPet = _deepCopy(MAIN.auto.sellPet),
                favPet = _deepCopy(MAIN.auto.favPet),
                unfavPet = _deepCopy(MAIN.auto.unfavPet),
                autoTele = _deepCopy(MAIN.auto.autoTele),
                gift = _deepCopy(MAIN.auto.gift),
                normalGift = _deepCopy(MAIN.auto.normalGift),
                giftMulti = _deepCopy(MAIN.auto.giftMulti),
                dropItem = _deepCopy(MAIN.auto.dropItem),
            },
        },
    }

    if forExport then
        payload.kind = "gag2-config"
        payload.v = 2
        -- Track Server (ws_id + status) — file terpisah; ikut di copy/paste config
        payload.track_server = _snapshotTrackServerForExport()
    else
        payload.running = (STATE.scriptRunning == true)
    end

    return payload
end


-- [NODEHUBWS V48 REMOTE APPLY GUARD]
-- LETAK id_code_list 231:
-- tepat sebelum: local function saveSelectionsToFile()
local function isNodeHubRemoteApplying()
    if type(NodeHubWS) == "table"
        and type(NodeHubWS.IsRemoteApplying) == "function"
        and NodeHubWS.IsRemoteApplying("gag2") == true then
        return true
    end

    return G.__NODEHUB_WS_REMOTE_APPLYING == true
        or rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING") == true
        or G.__NODEHUB_WS_REMOTE_APPLYING_gag2 == true
        or rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING_gag2") == true
        or G.__NODEHUB_WS_REMOTE_APPLYING_GAG2 == true
        or rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING_GAG2") == true
end


local function _countEnabledAutos(data)
    local n = 0
    local auto = type(data) == "table" and data.main and data.main.auto
    if type(auto) ~= "table" then return 0 end
    for _, v in pairs(auto) do
        if type(v) == "table" and v.enabled == true then
            n += 1
        end
    end
    return n
end

local function _writeSaveAtomic(json)
    -- Bak sudah versi lama. Jangan readfile-verify (executor FS lambat di boot/UI).
    local okMain = pcall(writefile, SAVE_FILE, json)
    if not okMain then
        warn("[GAG2 state] write save gagal:", SAVE_FILE)
        return false
    end
    return true
end

local function saveSelectionsToFile(opts)
    if not FS.ok or not _ensureFolder() then return end
    opts = type(opts) == "table" and opts or {}

    local payload = _buildSelectionsPayload(opts)
    if type(payload) ~= "table" then
        return
    end
    local newN = _countEnabledAutos(payload)
    local oldText = G.__GAG2_LAST_SAVE_JSON
    local oldN = tonumber(G.__GAG2_LAST_SAVE_AUTO_N) or 0
    local needRead = (type(oldText) ~= "string" or #oldText == 0)
    if needRead and _fileExists(SAVE_FILE) then
        local okOld, text = pcall(readfile, SAVE_FILE)
        if okOld and type(text) == "string" and #text > 0 then
            oldText = text
            oldN = _countEnabledAutos(select(1, _decodeConfigText(text)))
            G.__GAG2_LAST_SAVE_JSON = oldText
            G.__GAG2_LAST_SAVE_AUTO_N = oldN
        end
    end

    -- Close / mati lampu / boot default: jangan timpa save hidup.
    if newN <= 0 and opts.allowEmpty ~= true and G.__GAG2_RESETTING ~= true then
        if oldN > 0 or opts.skipPrepare == true then
            warn("[GAG2 state] skip save: payload default (0 auto ON), file lama", oldN, "auto ON")
            return
        end
    end

    local ok, json = pcall(function()
        return HttpService:JSONEncode(payload)
    end)
    if ok and type(json) == "string" then
        if json == oldText then
            if type(State) == "table" then
                State._diskDirty = false
            end
            return
        end
        if not _writeSaveAtomic(json) then
            return
        end
        -- Satu cadangan: last-known autos ON. Jangan clone file yang baru di-reset.
        if newN > 0 then
            pcall(writefile, SAVE_FILE .. ".prev", json)
        end
        G.__GAG2_LAST_SAVE_JSON = json
        G.__GAG2_LAST_SAVE_AUTO_N = newN
        if type(State) == "table" then
            State._diskDirty = false
        end

        -- EVENT DEVICE -> WEB
        -- Kirim payload yang sama dengan yang ditulis ke file, jangan buat wrapper baru.
        -- Skip kalau hub/web offline: ConfigChanged tetap encode/kirim path berat.
        if opts and opts.skipPrepare == true then
            return
        end
        local bridge = (type(NodeHubWS) == "table" and type(NodeHubWS.Get) == "function")
            and NodeHubWS.Get("gag2")
            or nil
        local hubOnline = type(bridge) == "table"
            and type(bridge.IsHubOnline) == "function"
            and bridge:IsHubOnline() == true

        if hubOnline then
            if type(NodeHubWS) == "table" and type(NodeHubWS.ConfigChanged) == "function" then
                NodeHubWS.ConfigChanged("gag2", "saveSelectionsToFile", payload)
            elseif type(G.__GAG2_WS_CONFIG_CHANGED) == "function" then
                G.__GAG2_WS_CONFIG_CHANGED(payload, "saveSelectionsToFile")
            end
        end
    end
end

