--------------------------------------------------
-- Auto Steal globals
--------------------------------------------------
local function _normalizeAutoStealState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_AUTO.steal)
    st.enabled = (st.enabled == true)
    st.plants = type(st.plants) == "table" and st.plants or {}
    st.mutations = type(st.mutations) == "table" and st.mutations or {}
    local minKg = tonumber(st.min_kg) or 0
    if minKg < 0 then minKg = 0 end
    st.min_kg = minKg
    local minPrice = tonumber(st.min_price) or 0
    if minPrice < 0 then minPrice = 0 end
    st.min_price = minPrice
    st.max_price = nil
    local delay = tonumber(st.delay)
    -- steal test FARM_DELAY = 0.05; migrate legacy 0.35 default
    if delay == nil or delay < 0.02 or math.abs(delay - 0.35) < 1e-6 then
        delay = 0.05
    end
    if delay < 0.02 then delay = 0.02 end
    st.delay = delay
    st.buff_only = (st.buff_only == true)
    -- default ON (nil / missing → true)
    st.buff_offmoon = (st.buff_offmoon ~= false)
    local mm = tostring(st.move_mode or "orbit"):lower()
    if mm == "nearest_garden" then mm = "nearest" end
    if mm == "highest_price" then mm = "highest" end
    if mm ~= "nearest" and mm ~= "highest" and mm ~= "off" then mm = "orbit" end
    st.move_mode = mm
    local tm = tostring(st.travel_mode or "walk"):lower()
    if tm ~= "soft" and tm ~= "step" and tm ~= "hard" then tm = "walk" end
    st.travel_mode = tm
    local sr = tonumber(st.steal_range)
    if sr == nil then sr = 100 end
    if sr < 1 then sr = 1 end
    if sr > 100 then sr = 100 end
    st.steal_range = sr
    return st
end

local function syncAutoStealGlobalsFromMain()
    local mainRef = _getMainRef()
    if mainRef ~= MAIN then
        MAIN = mainRef
    end

    MAIN.auto = MAIN.auto or _deepCopy(DEFAULT_AUTO)
    MAIN.auto.steal = _normalizeAutoStealState(MAIN.auto.steal)
