            G.AUTO_CAULDRON_LOOP = st.loop ~= false
            _G.AUTO_CAULDRON_LOOP = G.AUTO_CAULDRON_LOOP
        end
        _G.syncAutoCauldronGlobalsFromMain = G.syncAutoCauldronGlobalsFromMain
        eg.syncAutoCauldronGlobalsFromMain = G.syncAutoCauldronGlobalsFromMain
    end
end)()

