local function _normalizeMoveMode(mode)
    mode = tostring(mode or "walk"):lower()
    if mode == "button" then
        return "walk" -- legacy: button dihapus dari UI
    end
    if mode == "step" or mode == "walk" or mode == "hard" or mode == "soft" then
        return mode
    end
    return "walk"
end

local function _clampMoveSoftSpeed(n)
    n = math.floor(tonumber(n) or 30)
    if n < 1 then n = 1 end
    if n > 300 then n = 300 end
    return n
end

local function _clampMoveStepSpeed(n)
    n = math.floor(tonumber(n) or 30)
    if n < 1 then n = 1 end
    if n > 400 then n = 400 end
    return n
end

local function _clampMoveWalkSpeed(n)
    n = math.floor(tonumber(n) or 30)
    if n < 1 then n = 1 end
    if n > 200 then n = 200 end
    return n
end

local function _normalizeCharacterState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_MISC.character)
    local def = DEFAULT_MISC.character
    st.move_mode = _normalizeMoveMode(st.move_mode)
    st.soft_speed = _clampMoveSoftSpeed(st.soft_speed ~= nil and st.soft_speed or def.soft_speed)
    st.step_speed = _clampMoveStepSpeed(st.step_speed ~= nil and st.step_speed or def.step_speed)
    st.walk_speed = _clampMoveWalkSpeed(st.walk_speed ~= nil and st.walk_speed or def.walk_speed)
    -- clip UI dihapus — jangan persist ON dari toggle lama
    st.clip = false
    st.path_mode = nil -- legacy underground dihapus
    st.move_path = nil
    return st
end

local function syncCharacterGlobalsFromMain()
    MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
    MAIN.misc.character = _normalizeCharacterState(MAIN.misc.character)
    local cfg = MAIN.misc.character

    G.MOVE_MODE = cfg.move_mode
    _G.MOVE_MODE = cfg.move_mode
    G.CHARACTER_MOVE_MODE = cfg.move_mode
    _G.CHARACTER_MOVE_MODE = cfg.move_mode
    G.MOVE_SOFT_SPEED = cfg.soft_speed
    _G.MOVE_SOFT_SPEED = cfg.soft_speed
    G.MOVE_STEP_SPEED = cfg.step_speed
    _G.MOVE_STEP_SPEED = cfg.step_speed
    G.MOVE_WALK_SPEED = cfg.walk_speed
    _G.MOVE_WALK_SPEED = cfg.walk_speed
    -- noclip UI off; biarkan runtime SetClipEnabled (sprinkler) mengatur flag sendiri
    if G.CHARACTER_CLIP_ENABLED == nil then
        G.CHARACTER_CLIP_ENABLED = false
        _G.CHARACTER_CLIP_ENABLED = false
    end

    local Move = G.Move or rawget(_G, "Move")
    if type(Move) == "table" and type(Move.SetSpeeds) == "function" then
        pcall(Move.SetSpeeds, {
            soft = cfg.soft_speed,
            step = cfg.step_speed,
            walk = cfg.walk_speed,
        })
    end

    STATE.character = _deepCopy(cfg)
end

