    G.CHARACTER_MOVE_MODE = cfg.move_mode
    _G.CHARACTER_MOVE_MODE = cfg.move_mode
    G.MOVE_SOFT_SPEED = cfg.soft_speed
    _G.MOVE_SOFT_SPEED = cfg.soft_speed
    G.MOVE_STEP_SPEED = cfg.step_speed
    _G.MOVE_STEP_SPEED = cfg.step_speed
    G.MOVE_WALK_SPEED = cfg.walk_speed
    _G.MOVE_WALK_SPEED = cfg.walk_speed
