local function _normalizeHubUiState(st)
    st = type(st) == "table" and st or _deepCopy(DEFAULT_MISC.hub_ui)
    local def = DEFAULT_MISC.hub_ui
    local function clamp01(n, fallback)
        n = tonumber(n)
        if n == nil then return fallback end
        if n < 0 then n = 0 end
        if n > 1 then n = 1 end
        return n
    end
    local panel = clamp01(st.panel_transparency, def.panel_transparency)
    st.panel_transparency = panel
    st.section_transparency = panel
    st.overlay_transparency = 1
    return st
end

