    st.auto_save = nil
    st.auto_rejoin_rollback_seed0 = nil
    st.go_home_on_fruit = nil
    st.auto_rollback = nil
    st.auto_rejoin_loading_stuck = nil
    st.egg = nil
    st.sprinkler_water = nil
    return st
end

