        sw.sprinklers = _mapToArray(sprMap)
    end
    local watMap = G.SW_OTHER_WATERING_SELECTED or rawget(_G, "SW_OTHER_WATERING_SELECTED")
    if type(watMap) == "table" then
        sw.watering_cans = _mapToArray(watMap)
    end
    local swEnabled = G.SW_OTHER_ENABLED
    if swEnabled == nil then swEnabled = rawget(_G, "SW_OTHER_ENABLED") end
    if swEnabled ~= nil then
        sw.enabled = (swEnabled == true)
    end
    sw.rollback_rejoin = false
    local swSprMax = G.SW_OTHER_SPRINKLER_MAX_USE or rawget(_G, "SW_OTHER_SPRINKLER_MAX_USE")
    if swSprMax ~= nil then sw.sprinkler_max_use = swSprMax end
    local swWatMax = G.SW_OTHER_WATERING_MAX_USE or rawget(_G, "SW_OTHER_WATERING_MAX_USE")
    if swWatMax ~= nil then sw.watering_max_use = swWatMax end
