    if swStopCollect ~= nil then sw.stop_collect_max = swStopCollect end
    local swWaterDelay = G.SW_OTHER_WATERING_DELAY_SEC or rawget(_G, "SW_OTHER_WATERING_DELAY_SEC")
    if swWaterDelay ~= nil then sw.watering_delay_sec = swWaterDelay end
    local swPauseNight = G.SW_OTHER_PAUSE_AT_NIGHT
    if swPauseNight == nil then swPauseNight = rawget(_G, "SW_OTHER_PAUSE_AT_NIGHT") end
    if swPauseNight ~= nil then sw.pause_at_night = (swPauseNight == true) end
    local swPosMode = G.SW_OTHER_POSITION_MODE or rawget(_G, "SW_OTHER_POSITION_MODE")
    if swPosMode == nil then
        swPosMode = G.SW_OTHER_WATERING_MODE or rawget(_G, "SW_OTHER_WATERING_MODE")
    end
    if swPosMode ~= nil then sw.position_mode = normalizePositionMode(swPosMode) end

    MAIN.auto.sprinklerOtherGarden = _normalizeSprinklerOtherGardenState(sw)
    STATE.auto_sprinkler_other_garden = _deepCopy(MAIN.auto.sprinklerOtherGarden)
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

local function applySprinklerOtherGardenModule()
    syncSprinklerOtherGardenGlobalsFromMain()
    local VSW = G.AutoSprinklerOtherGarden or G.AutoSprinklerOtherGardenModule or rawget(_G, "AutoSprinklerOtherGarden")
        or G.AutoVulnSprinklerWater or G.AutoVulnSprinklerWaterModule or rawget(_G, "AutoVulnSprinklerWater")
    if type(VSW) == "table" and type(VSW.Apply) == "function" then
        pcall(VSW.Apply, VSW)
    end
end

G.applySprinklerOtherGardenModule = applySprinklerOtherGardenModule
_G.applySprinklerOtherGardenModule = applySprinklerOtherGardenModule
G.applyAutoVulnSprinklerWaterModule = applySprinklerOtherGardenModule -- compat
_G.applyAutoVulnSprinklerWaterModule = applySprinklerOtherGardenModule

