local function syncPetFinderGlobalsToMain()
    MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
    local pf = _snapshotPetFinderForSave(MAIN.misc.pet_finder)

    -- Prefer runtime module (sumber kebenaran setelah user toggle), bukan global stale.
    local PF = G.PetFinder or G.PetFinderModule or rawget(_G, "PetFinder")
    local live = nil
    if type(PF) == "table" and type(PF.GetConfig) == "function" then
        local ok, cfg = pcall(PF.GetConfig, PF)
        if ok and type(cfg) == "table" then
            live = cfg
        end
    end

    if type(live) == "table" then
        if type(live.filter_rarities) == "table" then
            pf.filter_rarities = live.filter_rarities
        end
        pf.auto_refresh_list = (live.auto_refresh_list == true)
        pf.auto_hop = (live.auto_hop == true)
    else
        if _petFinderListHasData(G.PET_FINDER_FILTER_RARITIES) then
            pf.filter_rarities = _deepCopy(G.PET_FINDER_FILTER_RARITIES)
        end
        if G.PET_FINDER_AUTO_REFRESH_LIST ~= nil then
            pf.auto_refresh_list = (G.PET_FINDER_AUTO_REFRESH_LIST == true)
        end
        if G.PET_FINDER_AUTO_HOP ~= nil and type(G.PET_FINDER_AUTO_HOP) ~= "table" then
            pf.auto_hop = (G.PET_FINDER_AUTO_HOP == true)
        end
    end
    if _petFinderListHasData(G.PET_FINDER_TARGET_PETS) then
        pf.target_pets = _deepCopy(G.PET_FINDER_TARGET_PETS)
    end

    MAIN.misc.pet_finder = _snapshotPetFinderForSave(pf)
    STATE.pet_finder = _deepCopy(MAIN.misc.pet_finder)
    G.MAIN = MAIN
    _G.MAIN = MAIN
    G.PET_FINDER_AUTO_REFRESH_LIST = (MAIN.misc.pet_finder.auto_refresh_list == true)
    G.PET_FINDER_AUTO_HOP = (MAIN.misc.pet_finder.auto_hop == true)
    _G.PET_FINDER_AUTO_REFRESH_LIST = G.PET_FINDER_AUTO_REFRESH_LIST
    _G.PET_FINDER_AUTO_HOP = G.PET_FINDER_AUTO_HOP
end

local function _mapToArray(map)
    local arr = {}
    if type(map) ~= "table" then return arr end
    for k, v in pairs(map) do
        if v == true then
            table.insert(arr, tostring(k))
        end
    end
    table.sort(arr)
    return arr
end

