local function restoreAutoFallHarvestFromData(data)
    if type(data) ~= "table" then return end
    -- Sumber utama: misc.rejoin.fall_harvest (sudah di restoreRejoinFromData).
    -- Legacy auto.fallHarvest hanya migrasi kalau key rejoin BELUM ada di save.
    -- Jangan anggap false = "belum set" — itu yang bikin OFF naik lagi pas rejoin.
    MAIN.misc = MAIN.misc or _deepCopy(DEFAULT_MISC)
    MAIN.misc.rejoin = MAIN.misc.rejoin or _deepCopy(DEFAULT_MISC.rejoin)

    local saved = nil
    if type(data.main) == "table" and type(data.main.misc) == "table"
        and type(data.main.misc.rejoin) == "table" then
        saved = data.main.misc.rejoin.fall_harvest
    end
    if saved == nil and type(data.rejoin) == "table" then
        saved = data.rejoin.fall_harvest
    end
    if saved == nil and type(data.misc) == "table" and type(data.misc.rejoin) == "table" then
        saved = data.misc.rejoin.fall_harvest
    end
    if type(saved) == "boolean" then
        MAIN.misc.rejoin.fall_harvest = saved
        syncAutoFallHarvestGlobalsFromMain()
        return
    end

    if MAIN.misc.rejoin.fall_harvest == true then
        syncAutoFallHarvestGlobalsFromMain()
        return
    end

    local legacy = nil
    if type(data.main) == "table" and type(data.main.auto) == "table" then
        legacy = data.main.auto.fallHarvest
    end
    if type(legacy) ~= "table" then legacy = data.auto and data.auto.fallHarvest end
    if type(legacy) ~= "table" then legacy = data.auto_fall_harvest end
    if type(legacy) == "table" and legacy.enabled == true then
        MAIN.misc.rejoin.fall_harvest = true
    end
    syncAutoFallHarvestGlobalsFromMain()
end

