local function _safeRestoreStep(label, fn, data)
    local ok, err = pcall(fn, data)
    if not ok then
        warn(("[GAG2 state] restore %s gagal: %s"):format(tostring(label), tostring(err)))
    end
end

local function _applySelectionsFromData(data, opts)
    if type(data) ~= "table" then return false end
    opts = type(opts) == "table" and opts or {}

    if opts.applyRunning == true and type(data.running) == "boolean" then
        STATE.scriptRunning = data.running
        G.scriptRunning = STATE.scriptRunning
    end

    -- Export/import: drop hop visited noise even if present in pasted JSON
    if opts.clearHopVisited == true then
        local rejoin = type(data.main) == "table" and type(data.main.misc) == "table" and data.main.misc.rejoin
        if type(rejoin) == "table" and type(rejoin.auto_hop) == "table" then
            rejoin.auto_hop.visited = {}
        end
        if type(data.rejoin) == "table" and type(data.rejoin.auto_hop) == "table" then
            data.rejoin.auto_hop.visited = {}
        end
    end

    _safeRestoreStep("rejoin", restoreRejoinFromData, data)
    _safeRestoreStep("collect", restoreAutoCollectFromData, data)
    _safeRestoreStep("plant", restoreAutoPlantFromData, data)
    _safeRestoreStep("trowel", restoreAutoTrowelFromData, data)
    _safeRestoreStep("sprinkler", restoreAutoSprinklerFromData, data)
    _safeRestoreStep("watering", restoreAutoWateringFromData, data)
    _safeRestoreStep("plot", restoreAutoPlotFromData, data)
    _safeRestoreStep("fav", restoreAutoFavFromData, data)
    _safeRestoreStep("unfav", restoreAutoUnfavFromData, data)
    _safeRestoreStep("sell", restoreAutoSellFromData, data)
    _safeRestoreStep("sellStock", restoreAutoSellStockFromData, data)
    _safeRestoreStep("sellDaily", restoreAutoSellDailyFromData, data)
    _safeRestoreStep("mergeEclipse", restoreAutoMergeEclipseFromData, data)
    _safeRestoreStep("shovel", restoreAutoShovelFromData, data)
    _safeRestoreStep("shovelFruit", restoreAutoShovelFruitFromData, data)
    _safeRestoreStep("buy", restoreAutoBuyFromData, data)
    _safeRestoreStep("claimSeed", restoreAutoClaimSeedFromData, data)
    _safeRestoreStep("gardenCards", G.restoreAutoGardenCardsFromData, data)
    _safeRestoreStep("dragonEgg", restoreAutoDragonEggFromData, data)
    _safeRestoreStep("steal", restoreAutoStealFromData, data)
    _safeRestoreStep("fallHarvest", restoreAutoFallHarvestFromData, data)
    _safeRestoreStep("killMonster", restoreAutoKillMonsterFromData, data)
    _safeRestoreStep("cauldron", restoreAutoCauldronFromData, data)
    _safeRestoreStep("openEgg", restoreOpenEggFromData, data)
    _safeRestoreStep("sprinklerOtherGarden", restoreSprinklerOtherGardenFromData, data)
    _safeRestoreStep("sellPet", restoreAutoSellPetFromData, data)
    _safeRestoreStep("favPet", G.restoreAutoFavPetFromData, data)
    _safeRestoreStep("unfavPet", G.restoreAutoUnfavPetFromData, data)
    _safeRestoreStep("autoTele", restoreAutoTeleFromData, data)
    _safeRestoreStep("gift", restoreAutoGiftFromData, data)
    _safeRestoreStep("normalGift", restoreNormalGiftFromData, data)
    _safeRestoreStep("giftMulti", restoreAutoGiftMultiFromData, data)
    _safeRestoreStep("dropItem", restoreAutoDropFromData, data)
    _safeRestoreStep("weather_predict", restoreWeatherPredictFromData, data)
    _safeRestoreStep("pet_finder", restorePetFinderFromData, data)
    _safeRestoreStep("perf", restorePerfFromData, data)
    _safeRestoreStep("fruit_backpack_esp", restoreFruitBackpackEspFromData, data)
    _safeRestoreStep("fruit_garden_esp", restoreFruitGardenEspFromData, data)
    _safeRestoreStep("hide_prompt", restoreHidePromptFromData, data)
    _safeRestoreStep("hide_harvest_prompt", restoreHideHarvestPromptFromData, data)
    _safeRestoreStep("character", restoreCharacterFromData, data)
    _safeRestoreStep("hub_ui", restoreHubUiFromData, data)
    _safeRestoreStep("auto_vuln", restoreAutoVulnFromData, data)
    _safeRestoreStep("hide_loading", restoreHideLoadingFromData, data)
    _safeRestoreStep("info_steal", restoreInfoStealFromData, data)
    _safeRestoreStep("info_garden", restoreInfoGardenFromData, data)

    local okGift, errGift = pcall(syncAutoGiftGlobalsFromMain)
    if not okGift then
        warn("[GAG2 state] sync gift gagal:", tostring(errGift))
    end
    pcall(syncAutoTeleGlobalsFromMain)
    pcall(syncNormalGiftGlobalsFromMain)
    pcall(syncAutoGiftMultiGlobalsFromMain)
    pcall(syncAutoDropGlobalsFromMain)

    return true
end

local function loadSelectionsFromFile()
    if not FS.read then
        warn("[GAG2 state] load skip: readfile/isfile tidak ada")
        return false
    end

    -- Path utama dulu (1 read). Cadangan hanya kalau rusak / semua auto OFF.
    local function tryPath(p)
        if type(p) ~= "string" or p == "" or not _fileExists(p) then
            return nil, nil, nil, "missing"
        end
        local ok, text = pcall(readfile, p)
        if not ok or type(text) ~= "string" or #text == 0 then
            return nil, nil, nil, "empty"
        end
        local data, err = _decodeConfigText(text)
        if type(data) ~= "table" then
            return nil, nil, nil, err
        end
        return data, text, _countEnabledAutos(data), nil
    end

    local mainPath = _resolveExistingSaveFile()
    local bestData, bestText, bestN, lastErr = tryPath(mainPath)
    local bestPath = mainPath
    if type(bestData) ~= "table" or (tonumber(bestN) or 0) <= 0 then
        local paths = { SAVE_FILE, SAVE_FILE .. ".prev", SAVE_FILE .. ".bak" }
        for i = 1, #paths do
            local p = paths[i]
            if p ~= mainPath then
                local data, text, n, err = tryPath(p)
                lastErr = err or lastErr
                if type(data) == "table" then
                    local nn = tonumber(n) or 0
                    local cur = tonumber(bestN) or -1
                    if type(bestData) ~= "table" or nn > cur then
                        bestData, bestText, bestN, bestPath = data, text, nn, p
                    end
                end
            end
        end
    end

    if type(bestData) ~= "table" then
        warn("[GAG2 state] load JSON gagal:", SAVE_FILE, tostring(lastErr))
        return false
    end
    if type(bestData.main) ~= "table" and type(bestData.auto) ~= "table"
        and type(bestData.misc) ~= "table" and bestData.kind ~= "gag2-config" then
        warn("[GAG2 state] load format bukan config GAG2:", bestPath)
        return false
    end
    if bestPath ~= SAVE_FILE and bestN > 0 then
        warn("[GAG2 state] load pakai cadangan:", bestPath, "auto ON=", bestN)
    end

    _applySelectionsFromData(bestData, { applyRunning = true })
    G.__GAG2_SELECTIONS_LOADED = true
    G.__GAG2_LAST_SAVE_JSON = bestText
    G.__GAG2_LAST_SAVE_AUTO_N = bestN
    return true
end

local function _looksLikeConfigPayload(data)
    if type(data) ~= "table" then return false end
    data = _unwrapConfigPayload(data)
    if type(data) ~= "table" then return false end
    if data.kind == "gag2-config" then return true end
    if type(data.main) == "table" then
        if type(data.main.auto) == "table" or type(data.main.misc) == "table" then
            return true
        end
    end
    if type(data.auto) == "table" or type(data.misc) == "table" then
        return true
    end
    return false
end

local function exportConfigToString()
    local payload = _buildSelectionsPayload({ forExport = true })
    local ok, json = pcall(function()
        return HttpService:JSONEncode(payload)
    end)
    if not ok or type(json) ~= "string" or json == "" then
        return nil, "JSONEncode failed"
    end
    if type(setclipboard) == "function" then
        pcall(setclipboard, json)
    end
    return json
end

local function importConfigFromString(text)
    text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then
        return false, "empty config"
    end

    local data, err = _decodeConfigText(text)
    if type(data) ~= "table" or not _looksLikeConfigPayload(data) then
        return false, (type(err) == "string" and err ~= "" and err) or "invalid config JSON"
    end

    local applied = _applySelectionsFromData(data, {
        applyRunning = false,
        clearHopVisited = true,
    })
    if not applied then
        return false, "restore failed"
    end

    -- Force gift UI stores to rehydrate from MAIN
    G.__GAG2_GIFT_STORE_EPOCH = (tonumber(G.__GAG2_GIFT_STORE_EPOCH) or 0) + 1
    _G.__GAG2_GIFT_STORE_EPOCH = G.__GAG2_GIFT_STORE_EPOCH
    if type(G.__GAG2_AUTO_GIFT) == "table" then
        G.__GAG2_AUTO_GIFT._storeEpoch = G.__GAG2_GIFT_STORE_EPOCH
        G.__GAG2_AUTO_GIFT._hydrated = false
        G.__GAG2_AUTO_GIFT_UI_READY = false
        _G.__GAG2_AUTO_GIFT_UI_READY = false
    end
    if type(G.__GAG2_AUTO_GIFT_MULTI) == "table" then
        G.__GAG2_AUTO_GIFT_MULTI._hydrated = false
    end
    if type(G.__GAG2_NORMAL_GIFT) == "table" then
        G.__GAG2_NORMAL_GIFT._hydrated = false
    end

    pcall(saveSelectionsToFile)

    -- Track Server (ws_id + status) dari copy config — terpisah dari SAVE_FILE script
    -- Config lama tanpa track_server → no-op (false, "no_track_server")
    pcall(_applyTrackServerFromData, data)

    pcall(syncRejoinGlobalsFromMain)
    pcall(applyAutoHopModule)
    pcall(applyAutoHopFruitModule)
    pcall(applyWeatherKickModule)
    pcall(syncReduceFpsGlobalsFromMain)
    if type(applyReduceFpsModule) == "function" then pcall(applyReduceFpsModule) end
    if type(applyReduceLagModule) == "function" then pcall(applyReduceLagModule) end
    pcall(syncFruitBackpackEspGlobalsFromMain)
    if type(applyFruitBackpackEspModule) == "function" then pcall(applyFruitBackpackEspModule) end
    pcall(syncFruitGardenEspGlobalsFromMain)
    if type(applyFruitGardenEspModule) == "function" then pcall(applyFruitGardenEspModule) end
    pcall(syncHidePromptGlobalsFromMain)
    if type(applyHidePromptModule) == "function" then pcall(applyHidePromptModule) end
    pcall(syncHideHarvestPromptGlobalsFromMain)
    if type(applyHideHarvestPromptModule) == "function" then pcall(applyHideHarvestPromptModule) end
    pcall(syncHideLoadingGlobalsFromMain)
    if type(applyHideLoadingModule) == "function" then pcall(applyHideLoadingModule) end
    pcall(syncCharacterGlobalsFromMain)
    if type(applyCharacterModule) == "function" then pcall(applyCharacterModule) end
    pcall(syncHubUiGlobalsFromMain)
    pcall(syncPetFinderGlobalsFromMain)
    if type(applyPetFinderModule) == "function" then pcall(applyPetFinderModule) end
    pcall(syncWeatherPredictGlobalsFromMain)
    pcall(syncAutoVulnGlobalsFromMain)
    if type(applyAutoVulnModule) == "function" then pcall(applyAutoVulnModule) end

    if type(G.__GAG2_APPLY_UI_DEFAULTS) == "function" then
        pcall(G.__GAG2_APPLY_UI_DEFAULTS)
    end
    if type(G.__GAG2_ON_STATE_RESET) == "function" then
        pcall(G.__GAG2_ON_STATE_RESET)
    end

    return true
end

