-- Method di State (bukan chunk local) — hindari limit 200 register.
function State._isArrayLike(t)
    if type(t) ~= "table" then return false end
    if t[1] ~= nil then return true end
    return next(t) == nil
end

function State._mergePartialInto(target, partial)
    if type(target) ~= "table" or type(partial) ~= "table" then return target end
    for k, v in pairs(partial) do
        if type(v) == "table" and type(target[k]) == "table"
            and not State._isArrayLike(v) and not State._isArrayLike(target[k]) then
            State._mergePartialInto(target[k], v)
        else
            target[k] = (type(v) == "table") and _deepCopy(v) or v
        end
    end
    return target
end

function State._sanitizeBuyAuctionMaxPrices(buy)
    if type(buy) ~= "table" or type(buy.auction) ~= "table" then return end
    local mode = tostring(buy.auction.mode or "normal"):lower()
    buy.auction.mode = (mode == "last_chance") and "last_chance" or "normal"
    local minStock = math.floor(tonumber(buy.auction.last_chance_min_stock) or 100)
    if minStock < 1 then minStock = 1 end
    buy.auction.last_chance_min_stock = minStock
    local timeLeftSec = math.floor(tonumber(buy.auction.last_chance_time_left_sec) or 20)
    if timeLeftSec < 1 then timeLeftSec = 1 end
    buy.auction.last_chance_time_left_sec = timeLeftSec
    for _, catKey in ipairs({ "seed", "gear", "seedpack", "egg" }) do
        local cat = buy.auction[catKey]
        if type(cat) == "table" and cat.max_price ~= nil then
            cat.max_price = _parseAuctionMaxPrice(cat.max_price)
        end
    end
end

function State._applyAutoPatch(key, partial)
    if type(key) ~= "string" or type(partial) ~= "table" then return end
    MAIN.auto = MAIN.auto or _deepCopy(DEFAULT_AUTO)
    local cur = type(MAIN.auto[key]) == "table" and _deepCopy(MAIN.auto[key]) or _deepCopy(DEFAULT_AUTO[key] or {})
    State._mergePartialInto(cur, partial)
    if key == "buy" then
        State._sanitizeBuyAuctionMaxPrices(cur)
    end
    local norm = State.AUTO_NORMALIZERS[key]
    MAIN.auto[key] = norm and norm(cur) or cur
    G.MAIN = MAIN
    _G.MAIN = MAIN
end

