-- Writefile saja (debounce). Jangan JSONEncode sync di tiap klik — itu freeze.
function State.persistDisk()
    if G.__GAG2_RESETTING == true then return end
    if G.__GAG2_SAVING_FROM_UI == true then return end
    State._diskDirty = true
    local gen = (tonumber(State._persistDiskGen) or 0) + 1
    State._persistDiskGen = gen
    task.delay(0.2, function()
        if State._persistDiskGen ~= gen then return end
        if G.__GAG2_RESETTING == true then return end
        if G.__GAG2_SAVING_FROM_UI == true then return end
        if State._persistDiskBusy == true then
            State._persistDiskAgain = true
            return
        end
        State._persistDiskBusy = true
        pcall(saveSelectionsToFile)
        State._persistDiskBusy = false
        if State._persistDiskAgain == true then
            State._persistDiskAgain = false
            if G.__GAG2_RESETTING ~= true and G.__GAG2_SAVING_FROM_UI ~= true then
                pcall(saveSelectionsToFile)
            end
        end
    end)
end

-- [NODEHUBWS V48 REMOTE APPLY GUARD]
function State.saveFromUi()
    -- Wajib di awal. Jangan flush UI lama ketika apply dari web sedang berjalan.
    if isNodeHubRemoteApplying() then return end
    if G.__GAG2_RESETTING == true then return end

    -- Register UI / toggle fire saveNow berkali-kali. Gabung jadi 1 flush + 1 write.
    local gen = (tonumber(State._persistDiskGen) or 0) + 1
    State._persistDiskGen = gen
    State._diskDirty = true
    task.delay(0.15, function()
        if State._persistDiskGen ~= gen then return end
        if G.__GAG2_RESETTING == true then return end
        if isNodeHubRemoteApplying() then return end
        if G.__GAG2_SAVING_FROM_UI == true then return end
        G.__GAG2_SAVING_FROM_UI = true
        _G.__GAG2_SAVING_FROM_UI = true
        local ok, err = pcall(function()
            State.flushUi()
            State.syncAllMisc()
            _syncAllRuntimeFromMain()
            saveSelectionsToFile()
        end)
        G.__GAG2_SAVING_FROM_UI = nil
        _G.__GAG2_SAVING_FROM_UI = nil
        if not ok then
            warn("[GAG2 state] saveFromUi gagal:", tostring(err))
        end
    end)
end

function State.load()
    local function step(name, fn)
        -- Prefer G[name] (export state_a) lalu local B, lalu _G
        local f = nil
        local gfn = rawget(G, name)
        if type(gfn) == "function" then
            f = gfn
        elseif type(fn) == "function" then
            f = fn
        else
            f = rawget(_G, name)
        end
        if type(f) ~= "function" then
            warn("[GAG2] State.load skip nil:", name)
            return
        end
        local ok, err = pcall(f)
        if not ok then
            warn("[GAG2] State.load fail:", name, tostring(err))
        end
    end

    if G.__GAG2_SELECTIONS_LOADED ~= true then
        step("loadSelectionsFromFile", loadSelectionsFromFile)
    end
    step("syncRejoinGlobalsToMain", syncRejoinGlobalsToMain)
    step("applyAutoHopModule", applyAutoHopModule)
    step("applyAutoHopFruitModule", applyAutoHopFruitModule)
    step("applyWeatherKickModule", applyWeatherKickModule)
    step("syncAutoCollectGlobalsFromMain", syncAutoCollectGlobalsFromMain)
    step("syncAutoPlantGlobalsFromMain", syncAutoPlantGlobalsFromMain)
