    function NodeHubWS.IsRemoteApplying(namespace)
        if G.__NODEHUB_WS_REMOTE_APPLYING ~= true and rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING") ~= true then
            return false
        end
        if namespace == nil then return true end
        namespace = nodeHubUiNamespace(namespace)
        return G["__NODEHUB_WS_REMOTE_APPLYING_" .. namespace] == true
            or rawget(_G, "__NODEHUB_WS_REMOTE_APPLYING_" .. namespace) == true
    end

