----------------------------------------------------------------
-- CREATE UI (ReduceLag + ReduceFPS sudah Start di atas; AntiAFK setelah UI)
----------------------------------------------------------------
local uiOk, uiOrErr = pcall(function()
    return MainUI.new({ title = "| GROW A GARDEN 2 V1.2 | discord.gg/nodehub" })
end)
if not uiOk or type(uiOrErr) ~= "table" then
    failBoot("MainUI.new gagal: " .. tostring(uiOrErr))
end
local ui = uiOrErr
if not hubUiVisible() then
    -- overlay mungkin masih di host loading — tunggu sebentar restore
    for _ = 1, 40 do
        if hubUiVisible() then break end
        task.wait(0.1)
    end
end
-- UI mungkin masih di host loading; watchdog NodeHub restore nanti. Jangan spam console.


-- Start early sisa (ReduceFPS / AntiAFK). ReduceLag SyncFromGlobals idempotent.
startEarlyModules()

do
    pcall(function()
        if G.__GROWAGARDEN2_UI and G.__GROWAGARDEN2_UI ~= ui then
            if type(G.__GROWAGARDEN2_UI.Destroy) == "function" then
                G.__GROWAGARDEN2_UI:Destroy()
            elseif typeof(G.__GROWAGARDEN2_UI) == "Instance" then
                G.__GROWAGARDEN2_UI:Destroy()
            end
        end
    end)
    G.__GROWAGARDEN2_UI = ui
    _G.__GROWAGARDEN2_UI = ui
end

if StateModule and type(StateModule.save) == "function" then
    function ui:SaveState()
        if type(StateModule.saveFromUi) == "function" then
            StateModule.saveFromUi()
        else
            StateModule.save()
        end
    end
elseif StateModule and type(StateModule.Save) == "function" then
    function ui:SaveState()
        if type(StateModule.saveFromUi) == "function" then
            StateModule.saveFromUi()
        else
            return StateModule.Save()
        end
    end
else
    function ui:SaveState() return true end
end

